    std.log.info(
        "antfly_bench_row_pipeline writes={d} prepared_rows={d} logical_bytes={d} encoded_bytes={d} prepare_ms={d} apply_lock_wait_ms={d} apply_lock_held_ms={d}",
        .{
            req.writes.len,
            profile.relational_rows_prepared,
            profile.relational_logical_bytes,
            profile.relational_encoded_bytes,
            nsToMs(profile.relational_prepare_ns),
            nsToMs(profile.apply_lock_wait_ns),
            nsToMs(profile.apply_lock_held_ns),
        },
    );
    std.log.info(
        "antfly_bench_batch sequence={d} writes={d} deletes={d} graph_writes={d} graph_deletes={d} transforms={d} sync={s} total_ms={d} resolve_ms={d} merge_ms={d} predicates_ms={d} range_ms={d} extract_ms={d} delete_artifacts_ms={d} precompute_ms={d} identity_capacity_ms={d} identity_metadata_ms={d} identity_metadata_writes={d} store_ms={d} split_delta_ms={d} build_derived_ms={d} shadow_ms={d} collect_sync_ms={d} backlog_admission_ms={d} append_replay_journal_ms={d} backlog_pressure_ms={d} executor_notify_ms={d} sync_wait_ms={d} wait_sync_ms={d} notify_enrichment_ms={d}",
        .{
            profile.source_sequence,
            req.writes.len,
            req.deletes.len,
            req.graph_writes.len,
            req.graph_deletes.len,
            req.transforms.len,
            @tagName(req.sync_level),
            nsToMs(profile.total_ns),
            nsToMs(profile.resolve_transforms_ns),
            nsToMs(profile.merge_effective_req_ns),
            nsToMs(profile.predicates_ns),
            nsToMs(profile.validate_range_ns),
            nsToMs(profile.extract_writes_ns),
            nsToMs(profile.delete_artifacts_ns),
            nsToMs(profile.precompute_generated_ns),
            nsToMs(profile.identity_capacity_check_ns),
            nsToMs(profile.identity_metadata_ns),
            profile.identity_metadata_writes,
            nsToMs(profile.store_write_ns),
            nsToMs(profile.split_delta_ns),
            nsToMs(profile.build_derived_ns),
            nsToMs(profile.apply_shadow_ns),
            nsToMs(profile.collect_sync_targets_ns),
            nsToMs(profile.backlog_admission_ns),
