test "stale multi-source vector replay writes are source fenced" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();
    try db.addEnrichment(.{
        .name = "dense_source_v1",
        .kind = .embedding,
        .field = "body",
        .expected_dims = 2,
        .producer_json = "{\"version\":1,\"provider\":\"antfly\",\"model\":\"dense-test\",\"dimensions\":2}",
    });
    try db.addEnrichment(.{
        .name = "sparse_source_v1",
        .kind = .embedding,
        .field = "body",
        .producer_json = "{\"version\":1,\"provider\":\"antfly\",\"model\":\"sparse-test\"}",
    });
    try db.addIndex(.{
        .name = "dense_union",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":2,\"sources\":[{\"artifact\":\"dense_source_v1\"}]}",
    });
    try db.addIndex(.{
        .name = "sparse_union",
        .kind = .sparse_vector,
        .config_json = "{\"field\":\"sparse_embedding\",\"sources\":[{\"artifact\":\"sparse_source_v1\"}]}",
    });

    const dense_artifact = try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, "doc:authoritative", "dense_source_v1");
    defer alloc.free(dense_artifact);
    const sparse_artifact = try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, "doc:authoritative", "sparse_source_v1");
    defer alloc.free(sparse_artifact);
    const foreign_artifact = try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, "doc:stale", "retired_source_v1");
    defer alloc.free(foreign_artifact);

    const dense_stale = [_]derived_types.DerivedDenseEmbeddingWrite{
        .{ .index_name = "dense_union", .doc_key = "doc:stale", .vector = &.{ 1, 0 } },
        .{ .index_name = "dense_union", .doc_key = "doc:stale", .artifact_key = foreign_artifact, .vector = &.{ 1, 0 } },
    };
    try std.testing.expectEqual(ManagedIndexBatchApplicability.irrelevant, managedIndexBatchApplicability(
        db.core.index_manager,
        .{ .dense_embeddings = &dense_stale },
        .{ .name = "dense_union", .kind = .dense_vector },
    ));
    const dense_writes = [_]derived_types.DerivedDenseEmbeddingWrite{
        dense_stale[0],
        dense_stale[1],
        .{ .index_name = "dense_union", .doc_key = "doc:untrusted", .artifact_key = dense_artifact, .vector = &.{ 0, 1 } },
    };
    var collected_dense = try collectDenseEmbeddingWritesForBatch(alloc, db.core.index_manager, &dense_writes, &.{}, "dense_union");
    defer collected_dense.deinit();
    try std.testing.expectEqual(@as(usize, 1), collected_dense.writes.len);
    try std.testing.expectEqualStrings("doc:authoritative", collected_dense.writes[0].doc_key);
    try std.testing.expectEqual(@as(usize, 0), collected_dense.writes[0].vector.len);

    const sparse_stale = [_]derived_types.DerivedSparseEmbeddingWrite{
        .{ .index_name = "sparse_union", .doc_key = "doc:stale", .indices = &.{1}, .values = &.{1} },
        .{ .index_name = "sparse_union", .doc_key = "doc:stale", .artifact_key = foreign_artifact, .indices = &.{1}, .values = &.{1} },
    };
    try std.testing.expectEqual(ManagedIndexBatchApplicability.irrelevant, managedIndexBatchApplicability(
        db.core.index_manager,
        .{ .sparse_embeddings = &sparse_stale },
        .{ .name = "sparse_union", .kind = .sparse_vector },
    ));
    const sparse_writes = [_]derived_types.DerivedSparseEmbeddingWrite{
        sparse_stale[0],
        sparse_stale[1],
        .{ .index_name = "sparse_union", .doc_key = "doc:untrusted", .artifact_key = sparse_artifact, .indices = &.{1}, .values = &.{1} },
    };
    var collected_sparse = try collectSparseEmbeddingWritesForBatch(alloc, db.core.index_manager, &sparse_writes, &.{}, "sparse_union");
    defer collected_sparse.deinit();
    try std.testing.expectEqual(@as(usize, 1), collected_sparse.writes.len);
    try std.testing.expectEqualStrings("doc:authoritative", collected_sparse.writes[0].doc_key);
    try std.testing.expectEqual(@as(usize, 0), collected_sparse.writes[0].indices.len);
}

fn denseLsmWriteStatsSnapshot(ctx: *AsyncContext, index_name: []const u8) ?hbc_mod.LsmWriteStats {
    const entry = ctx.index_manager.denseIndex(index_name) orelse return null;
    return entry.index.snapshotLsmWriteStats();
}

fn denseLsmWriteStatsDelta(after: hbc_mod.LsmWriteStats, before: hbc_mod.LsmWriteStats) hbc_mod.LsmWriteStats {
    var delta = after;
    const info = @typeInfo(hbc_mod.LsmWriteStats).@"struct";
    inline for (info.field_names, info.field_types) |reflected_name, Field| {
        if (Field == u64) {
            @field(delta, reflected_name) = @field(after, reflected_name) -| @field(before, reflected_name);
        }
    }
    return delta;
}

const sleepNs = local_mutation.sleepNs;

fn sleepPollInterval() void {
    platform_clock.Clock.real().sleepMs(10);
}

fn yieldToBackground() void {
    var spins: usize = 0;
    while (spins < 16) : (spins += 1) {
        spinOrYield();
    }
    sleepPollInterval();
}

const PrimaryStoreOpenPlan = union(enum) {
    mem: mem_backend_mod.Options,
    lsm_memory: lsm_backend_mod.Options,
    lsm: lsm_backend_mod.Options,
};

const SplitDestinationStorePlan = union(enum) {
    lsm: lsm_backend_mod.Options,
    unsupported,
};

fn primaryStoreOpenPlan(opts: db_config.CoreOpenOptions) PrimaryStoreOpenPlan {
    return switch (opts.primary_backend) {
        .mem => |mem_opts| .{ .mem = mem_opts },
        .lsm_memory => |lsm_opts| .{ .lsm_memory = db_config.mergedLsmOptions(opts.storage, opts.lsm_cache, opts.resource_manager, opts.bind_cache_resource_manager, opts.no_sync, lsm_opts) },
        .lsm => |lsm_opts| .{ .lsm = db_config.mergedLsmOptions(opts.storage, opts.lsm_cache, opts.resource_manager, opts.bind_cache_resource_manager, opts.no_sync, lsm_opts) },
    };
}

const openModeRequiresReadOnlyBackends = local_mutation.openModeRequiresReadOnlyBackends;

fn makeLsmOptionsReadOnly(options: *lsm_backend_mod.Options) void {
    options.backend.read_only = true;
    options.backend.create_if_missing = false;
    options.background_executor = null;
}

fn applyReadOnlyToPrimaryBackend(primary_backend: *PrimaryBackend) void {
    switch (primary_backend.*) {
        .lsm => |*lsm_opts| makeLsmOptionsReadOnly(lsm_opts),
        .lsm_memory => |*lsm_opts| makeLsmOptionsReadOnly(lsm_opts),
        .mem => {},
    }
}

fn applyReadOnlyToIndexBackends(index_backends: *db_config.IndexBackendOptions) void {
    makeLsmOptionsReadOnly(&index_backends.text_main_lsm_options);
    makeLsmOptionsReadOnly(&index_backends.text_wal_lsm_options);
    makeLsmOptionsReadOnly(&index_backends.dense_lsm_options);
    makeLsmOptionsReadOnly(&index_backends.sparse_lsm_options);
    makeLsmOptionsReadOnly(&index_backends.graph_reverse_lsm_options);
}

fn splitDestinationStorePlan(self: *DB) SplitDestinationStorePlan {
    return switch (self.primary_backend) {
        .lsm => |opts| .{ .lsm = db_config.splitLsmOptions(.{ .lsm = opts }, self.primary_lsm_storage, opts.cache).? },
        .mem, .lsm_memory => .unsupported,
    };
}

fn makeLsmBackgroundExecutor(runtime: *background_runtime_mod.BackendRuntime, owner_id: u64) lsm_backend_mod.BackgroundExecutor {
    return lsm_backend_mod.BackgroundExecutor.init(runtime, owner_id);
}

fn installLsmReadRuntime(options: *lsm_backend_mod.Options, runtime: *background_runtime_mod.BackendRuntime) void {
    if (options.storage == null) options.storage = runtime.storage();
    if (options.storage == null and options.native_storage_pool == null) options.native_storage_pool = runtime.nativeStoragePool();
    if (options.read_runtime != null) return;
    if (runtime.io()) |io| options.read_runtime = lsm_backend_mod.storage_io.ReadRuntime.init(io);
}

fn installIndexLsmReadRuntime(index_backends: anytype, runtime: *background_runtime_mod.BackendRuntime) void {
    installLsmReadRuntime(&index_backends.text_main_lsm_options, runtime);
    installLsmReadRuntime(&index_backends.text_wal_lsm_options, runtime);
    installLsmReadRuntime(&index_backends.dense_lsm_options, runtime);
    installLsmReadRuntime(&index_backends.sparse_lsm_options, runtime);
    installLsmReadRuntime(&index_backends.graph_reverse_lsm_options, runtime);
}

fn openPrimaryStore(alloc: Allocator, path: []const u8, opts: db_config.CoreOpenOptions) !db_core.OpenedPrimaryStore {
    if (opts.primary_runtime_store) |runtime_store| {
        return .{
            .store = try docstore_mod.DocStore.openRuntime(alloc, runtime_store),
        };
    }

    return switch (primaryStoreOpenPlan(opts)) {
        .mem => |mem_opts| mem_blk: {
            const backend = try alloc.create(mem_backend_mod.Backend);
            errdefer alloc.destroy(backend);
            backend.* = mem_backend_mod.Backend.init(alloc, mem_opts);
            errdefer backend.close();

            var runtime_store = try backend.runtimeStore(alloc, .{ .name = "docs" });
            errdefer runtime_store.deinit();

            break :mem_blk .{
                .store = try docstore_mod.DocStore.openRuntime(alloc, runtime_store),
                .owner = .{ .mem = backend },
            };
        },
        .lsm_memory => |lsm_opts| lsm_mem_blk: {
            var handle = try lsm_backend_mod.BackendHandle.init(alloc, lsm_opts);
            errdefer handle.close();

            var runtime_store = try handle.backend.runtimeStore(alloc, .{ .name = "docs" });
            errdefer runtime_store.deinit();

            break :lsm_mem_blk .{
                .store = try docstore_mod.DocStore.openRuntime(alloc, runtime_store),
                .owner = .{ .lsm = .{
                    .handle = handle,
                    .split_options = null,
                } },
            };
        },
        .lsm => |lsm_opts| lsm_blk: {
            var handle = try lsm_backend_mod.BackendHandle.open(alloc, path, lsm_opts);
            errdefer handle.close();

            var runtime_store = try handle.backend.runtimeStore(alloc, .{ .name = "docs" });
            errdefer runtime_store.deinit();

            break :lsm_blk .{
                .store = try docstore_mod.DocStore.openRuntime(alloc, runtime_store),
                .owner = .{ .lsm = .{
                    .handle = handle,
                    .split_options = db_config.splitLsmOptions(opts.primary_backend, opts.storage, opts.lsm_cache),
                } },
            };
        },
    };
}

const ShadowState = execution_resources.ShadowState;

/// Restore owns one bounded parsed artifact at a time. Keeping it across
/// durable page commits makes recovery linear in the artifact size during a
/// normal run; after a crash the current artifact is parsed once again and
/// resumes directly at its ordinal cursor.
const GraphRestoreParseCache = execution_resources.GraphRestoreParseCache;

/// Mutable admission and publication state shared by foreground mutations and
/// recovery. This owner has one lifetime and one set of locks; a borrowed
/// execution view cannot snapshot or retire any of these resources.
const LocalExecutionState = execution_resources.LocalExecutionState;

// A narrowly scoped secret reader can serve a provider without access to the
// row-policy signing authority. Denial leaves that authority unavailable;
// policy admission still requires both credentials and fails closed.
fn optionalRowPolicyAuthority(alloc: std.mem.Allocator, store: anytype, key: []const u8) !?[]u8 {
    return store.getOwned(alloc, key) catch |err| switch (err) {
        error.Unauthorized => null,
        else => return err,
    };
}

test "db optional row policy authority preserves scoped secret denial and outages" {
    const Reader = struct {
        failure: anyerror = error.Unauthorized,
        fn getOwned(self: *@This(), _: std.mem.Allocator, _: []const u8) anyerror!?[]u8 {
            return self.failure;
        }
    };
    var reader: Reader = .{};
    try std.testing.expectEqual(@as(?[]u8, null), try optionalRowPolicyAuthority(std.testing.allocator, &reader, "antfly.trusted_principal.secret"));
    reader.failure = error.Unavailable;
    try std.testing.expectError(error.Unavailable, optionalRowPolicyAuthority(std.testing.allocator, &reader, "antfly.trusted_principal.secret"));
}

pub const DB = struct {
    /// Shared local mutation state outlives foreground and recovery execution.
    local_execution: *LocalExecutionState,
    /// Monolithic managed opens retain the process verifier until workers drain.
    owned_row_policy_authority_secret: ?[]u8 = null,
    owned_row_policy_authority_issuer: ?[]u8 = null,
    owned_row_policy_table_name: ?[]u8 = null,
    rewrite_program_cache: @import("../rewrite_program_cache.zig").Cache = .{},
    rewrite_tail_cache: @import("../rewrite_tail_spool.zig").Cache = .{},
    restore_decoder_cache: @import("../restore_decoder_cache.zig").Cache = .{},
    source_vector_storage: ?*lsm_backend_mod.NativeStorage = null,
    closed: bool = false,
    stable_address: bool = false,
    graph_cleanup_owner: @import("graph_cleanup_owner.zig").Owner = .{},
    alloc: Allocator,
    runtime_alloc: Allocator,
    generation_read_lease: ?generation_lifecycle.ReadLease,
    open_mode: OpenOptions.OpenMode,
    primary_backend: PrimaryBackend,
    primary_lsm_storage: ?lsm_backend_mod.Storage,
    physical_root_mode: OpenOptions.PhysicalRootMode,
    index_backends: db_config.IndexBackendOptions,
    core: *db_core.DBCore,
    /// Immutable physical root identity, initialized before workers bind.
    root_incarnation: u128 = 0,
    async_context: *AsyncContext,
    backend_runtime: *background_runtime_mod.BackendRuntime,
    index_repair_clock: ?platform_clock.Clock = null,
    backend_owner_id: u64,
    status_owner_epoch: u64 = 0,
    status_publication_mutex: std.atomic.Mutex = .unlocked,
    status_publication_revision: u64 = 0,
    repair_cleanup_owner_id: u64,
    /// Owner-scoped recovery keeps remote acknowledgement off the open/read
    /// path. The startup barrier orders crash-left obligations before new WAL
    /// records; steady-state mutations then wait on independent LSN watermarks.
    publication_recovery: @import("publication_recovery_owner.zig").Owner,
    algebraic_hll_owner_id: u64 = 0,
    owned_backend_runtime: ?background_runtime_mod.BackendRuntimeHandle,
    owned_resource_manager: ?*resource_manager_mod.ResourceManager,
    capacity_source: ?types.RepairCapacitySource,
    executor: *derived_executor_mod.Executor,
    start_index_workers: bool,
    graph_metric_idle_maintenance: OpenOptions.GraphMetricIdleMaintenanceMode,
    graph_metric_idle_planned_options: index_manager_mod.IndexManager.GraphMetricPlannedMaintenanceOptions,
    graph_metric_idle_auto_options: index_manager_mod.IndexManager.GraphMetricPlannedAutoIdleOptions,
    graph_metric_idle_degree_canary_options: index_manager_mod.IndexManager.GraphMetricDegreeCanaryOptions,
    resolver_workers_enabled: bool,
    secret_store: ?*common_secrets.FileStore,
    remote_content: ?*const scraping.RemoteContentConfig,
    enrichment_owner: EnrichmentOwner = .{},
    /// Borrowed views for existing local consumers. The bundle owns destruction;
    /// replacement publishes these views while holding the lifecycle fence.
    enrichment_append_context: ?*EnrichmentAppendContext,
    enrichment_runtime: ?*enrichment_runtime_mod.EnrichmentRuntime,
    resolution_append_context: ?*EnrichmentAppendContext = null,
    resolution_owner: @import("local_runtime_owner.zig").Bundle(EnrichmentAppendContext, resolution_runtime_mod.ResolutionRuntime) = .{},
    promotion_owner_bundle: @import("local_runtime_owner.zig").RuntimeOwner(promotion_runtime_mod.PromotionRuntime) = .{},
    ttl_owner: @import("local_runtime_owner.zig").Bundle(TtlCleanupContext, ttl_runtime_mod.TtlRuntime) = .{},
    text_merge_owner: @import("local_runtime_owner.zig").RuntimeOwner(text_merge_runtime_mod.TextMergeRuntime) = .{},
    sparse_compaction_owner: @import("local_runtime_owner.zig").RuntimeOwner(sparse_compaction_runtime_mod.SparseCompactionRuntime) = .{},
    graph_metric_owner: @import("local_runtime_owner.zig").RuntimeOwner(graph_metric_runtime_mod.GraphMetricRuntime) = .{},
    // Runtime/context pointer fields below are borrowed views of these owners.
    resolution_runtime: ?*resolution_runtime_mod.ResolutionRuntime = null,
    resolution_candidate_source: ?resolution_runtime_mod.CandidateSource = null,
    resolution_embedder: ?embedder_mod.DenseEmbedder = null,
    promotion_runtime: ?*promotion_runtime_mod.PromotionRuntime = null,
