    pub const batchContext = local_mutation.batchContext;

    pub const enforcePortableRuntimeGate = local_mutation.enforcePortableRuntimeGate;

    pub const enforceReplicationWriteGate = local_mutation.enforceReplicationWriteGate;

    /// Keep unavailable work out of lock queues, then revalidate after acquiring
    /// the synchronization primitive that activation itself uses. Publication
    /// may close the gate between those checks; a successful return therefore
    /// owns one stable runtime-catalog generation without penalizing degraded
    /// requests with lock contention.
    pub const lockApplyForPortableRuntime = local_mutation.lockApplyForPortableRuntime;

    fn lockApplySharedForPortableRuntime(self: *DB) !void {
        try self.enforcePortableRuntimeGate();
        lockApplyShared(self);
        errdefer self.core.unlockApplyShared();
        try self.enforcePortableRuntimeGate();
        // A failed split may have withdrawn only some graph owners. Keep the
        // live handle closed to reads until the durable retirement is repaired.
        const pending = self.core.store.get(self.alloc, graph_split_retire_cursor_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (pending) |cursor| {
            self.alloc.free(cursor);
            return error.GraphMaintenanceInProgress;
        }
        if (self.core.index_manager.graphOwnershipCleanupPending())
            return error.GraphMaintenanceInProgress;
    }

    pub const replicationMutationBarrier = local_mutation.replicationMutationBarrier;

    pub const acquireReplicationMutationShared = local_mutation.acquireReplicationMutationShared;

    fn acquireSnapshotReplayMutation(self: *DB) !snapshot_admission_mod.SnapshotAdmission.MutationLease {
        if (self.backend_runtime.filesystemIo()) |io| {
            return try self.core.snapshot_replay_admission.acquireMutationIo(
                io,
                @as(?types.CancellationToken, null),
            );
        }
        return self.core.snapshot_replay_admission.acquireMutation();
    }

    pub const ConstraintValidationStatus = struct {
        schema_version: u32,
        state: relational_constraint_jobs.State,
        rows_scanned: u64,
        failed_check: ?u16,
    };

    pub fn constraintValidationStatus(self: *DB) !ConstraintValidationStatus {
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        var view = self.core.acquireSchemaView() orelse return error.ConstraintNotFound;
        defer view.release();
        var read = try self.core.store.beginReadTxn();
        defer read.abort();
        const progress = try relational_constraint_jobs.status(&read, view);
        return .{ .schema_version = progress.schema_version, .state = progress.state, .rows_scanned = progress.rows_scanned, .failed_check = if (progress.state == .invalid) progress.failed_check else null };
    }

    pub fn validateConstraintsStep(self: *DB, budget: relational_constraint_jobs.Budget) !bool {
        return self.validateConstraintsStepLocal(budget, false);
    }

    fn validateConstraintsStepLocal(self: *DB, budget: relational_constraint_jobs.Budget, replicated: bool) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        {
            var active = self.core.acquireSchemaView() orelse return false;
            defer active.release();
            const validator = active.validator() orelse return false;
            if (validator.execution.checks == null) return false;
        }
        var replication_mutation = if (replicated) null else self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        if (!replicated) try self.enforceReplicationWriteGate();
        var snapshot_mutation = self.core.snapshot_admission.acquireMutation();
        defer snapshot_mutation.release();
        var replay_mutation = try self.acquireSnapshotReplayMutation();
        defer replay_mutation.release();
        var page = (try relational_constraint_jobs.Page.prepare(self.alloc, self.backend_runtime.io(), self.core, budget)) orelse return false;
        defer page.deinit();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (!replicated) try self.enforceReplicationWriteGate();
        try page.commit(self.core);
        return true;
    }

    /// Retry only an observed failed epoch, never reset a newer declaration.
    pub fn retryConstraintValidation(self: *DB, schema_version: u32) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        var snapshot_mutation = self.core.snapshot_admission.acquireMutation();
        defer snapshot_mutation.release();
        var replay_mutation = try self.acquireSnapshotReplayMutation();
        defer replay_mutation.release();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        try self.enforceReplicationWriteGate();
        var view = self.core.acquireSchemaView() orelse return error.ConstraintNotFound;
        defer view.release();
        if (view.version() != schema_version) return error.PreparedGenerationChanged;
        var txn = try self.core.store.beginWriteTxn();
        errdefer txn.abort();
        if ((try relational_constraint_jobs.status(&txn, view)).state != .invalid) {
            txn.abort();
            return false;
        }
        try txn.delete(relational_constraint_jobs.progress_key);
        try txn.commit();
        self.local_execution.relational_index_maintenance_sweep.request();
        self.local_execution.relational_index_retry_after_ns.store(0, .release);
        return true;
    }

    pub const RelationalIndexBuildBudget = relational_index_jobs.Budget;
    pub const RelationalIndexBuildState = relational_index_jobs.State;
    pub const RelationalIndexBuildFailure = relational_index_jobs.Failure;
