    fn initOptionalRuntimes(self: *DB, opts: *OpenOptions) !void {
        // Created before enrichment so the enrichment append context can notify
        // it when extraction artifacts land.
        try self.initResolutionRuntime();
        // Created after the resolution runtime so it can patch the resolution
        // append context to wake the promoter when resolution artifacts land.
        try self.initPromotionRuntime();
        if (opts.enrichment) |*enrichment_cfg| {
            if (enrichment_cfg.secret_store == null) enrichment_cfg.secret_store = opts.secret_store;
            if (enrichment_cfg.remote_content == null) enrichment_cfg.remote_content = opts.remote_content;
            if (enrichment_cfg.resource_manager == null) enrichment_cfg.resource_manager = opts.resource_manager;
            try self.initOptionalEnrichmentRuntime(enrichment_cfg);
            // Providers adopted by a runtime were cleared by the move boundary;
            // provider-only configurations that do not require a runtime remain
            // here and must be released before clearing the open option.
            deinitOwnedEnrichmentConfig(self.alloc, enrichment_cfg);
            opts.enrichment = null;
        }
        if (opts.ttl_cleanup.enabled) {
            try self.initOptionalTtlRuntime(opts.ttl_cleanup);
            self.setCoordinatedTtl(opts.coordinated_ttl);
        }
        if (opts.transaction_recovery.enabled) {
            try self.initOptionalTransactionRuntime(opts.transaction_recovery);
        }
        try self.initOptionalTextMergeRuntime(opts.text_merge);
        try self.initOptionalSparseCompactionRuntime(opts.sparse_compaction);
        try self.initOptionalGraphMetricRuntime(opts.graph_metric_maintenance);
    }

    fn startOptionalRuntimes(self: *DB) !void {
        try self.startResolverReplayRuntimesIfConfigured();
        if (self.enrichment_runtime) |runtime| {
            try runtime.start();
            self.async_context.enrichment_desired_running.store(true, .release);
        }
        if (self.ttl_runtime) |runtime| try runtime.start();
        if (self.transaction_runtime) |runtime| {
            try self.prepareTransactionRecoveryOwner();
            try runtime.start();
        }
        if (self.text_merge_runtime) |runtime| try runtime.start();
        if (self.sparse_compaction_runtime) |runtime| try runtime.start();
        if (self.graph_metric_runtime) |runtime| try runtime.start();
    }

    /// Publish non-joining shutdown to optional workers before a borrowed
    /// deterministic scheduler drains them. Destruction still happens through
    /// the ordinary close path after the drain completes.
    pub fn beginTeardown(self: *DB) void {
        self.graph_cleanup_owner.stopping.store(true, .release);
        if (self.enrichment_runtime) |runtime| runtime.beginTeardown();
        if (self.transaction_runtime) |runtime| runtime.beginTeardown();
    }

    pub fn ensureTransactionRecoveryRuntime(self: *DB, cfg: transaction_runtime_mod.Config) !void {
        if (!cfg.enabled or self.transaction_runtime != null) return;
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (self.transaction_runtime != null) return;
        try self.initOptionalTransactionRuntime(cfg);
        if (self.local_execution.optional_runtime_workers_enabled) {
            const runtime = self.transaction_runtime.?;
            try self.prepareTransactionRecoveryOwner();
            try runtime.start();
        }
    }

    pub const hasConfiguredResolvers = local_mutation.hasConfiguredResolvers;

    fn resolverReplayNeedsDrain(self: *DB) bool {
        if (self.hasConfiguredResolvers()) return true;
        if (self.resolution_runtime) |runtime| {
            const replay_stats = runtime.stats();
            if (replay_stats.catch_up_required or replay_stats.blocked) return true;
        }
        if (self.promotion_runtime) |runtime| {
            const replay_stats = runtime.stats();
            if (replay_stats.catch_up_required or replay_stats.blocked) return true;
        }
        return false;
    }

    pub const notifyResolverReplayRuntimes = local_mutation.notifyResolverReplayRuntimes;

    pub const notifyResolverReplayRuntimesForced = local_mutation.notifyResolverReplayRuntimesForced;

    fn startResolverReplayRuntimesIfConfigured(self: *DB) !void {
        if (!self.hasConfiguredResolvers()) return;
        try self.startResolverReplayRuntimes();
    }

    /// Activate only after the serving owner installs candidate/sink hooks.
    pub fn activateResolverReplayRuntimes(self: *DB) !void {
        self.resolver_workers_enabled = true;
        if (self.local_execution.optional_runtime_workers_enabled) try self.startResolverReplayRuntimesIfConfigured();
    }

    fn startResolverReplayRuntimes(self: *DB) !void {
        if (!self.resolver_workers_enabled or !self.local_execution.optional_runtime_workers_enabled) return;
        var resolution_started = false;
        errdefer if (resolution_started) if (self.resolution_runtime) |runtime| runtime.stop();
        if (self.resolution_runtime) |runtime| {
            try runtime.start();
            resolution_started = true;
        }
        if (builtin.is_test and test_fail_portable_promotion_runtime_start) {
            test_fail_portable_promotion_runtime_start = false;
            return error.InjectedPortablePromotionRuntimeStartFailure;
        }
        if (self.promotion_runtime) |runtime| try runtime.start();
    }

    fn stopResolverReplayRuntimes(self: *DB) void {
        if (self.resolution_runtime) |runtime| runtime.stop();
        if (self.promotion_runtime) |runtime| runtime.stop();
    }

    fn stopResolverReplayRuntimesIfUnconfigured(self: *DB) void {
        if (self.hasConfiguredResolvers()) return;
        if (self.resolution_runtime) |runtime| runtime.stop();
        if (self.promotion_runtime) |runtime| runtime.stop();
    }

    pub const clearLiveDocSetCache = local_mutation.clearLiveDocSetCache;

    pub const clearNonVisibleDocSetCache = local_mutation.clearNonVisibleDocSetCache;

    fn clearEmbeddingActivityCache(self: *DB) void {
        self.embedding_activity.clear(self.alloc);
    }

    fn deinitWrapperState(self: *DB, executor_ready: bool) void {
        if (self.last_run_until_idle_no_progress) |*diagnostic| diagnostic.deinit(self.alloc);
        self.last_run_until_idle_no_progress = null;
        // Stop background workers before tearing down stores, runtimes, and
        // index state they may inspect.
        self.async_context.background_closing.store(true, .release);
        self.local_execution.schema_reconcile.stop();
        self.stopArtifactRepairMetadataWorker();
        self.artifact_producer_scheduler.deinit(self.alloc);
        self.stopPortableActivationRetryWorker();
        self.stopQuarantineRetryWorker();
        self.stopGraphEndpointCleanupWorker();
        self.transaction_owner.deinitRuntime(self.runtime_alloc);
        self.transaction_runtime = null;
        self.local_execution.source_publication.stop(self.backend_runtime.io() orelse std.Options.debug_io);
        self.local_execution.merge_artifact_layout.clear();
        self.local_execution.online_merge_reader.retire(self.backend_runtime.io() orelse std.Options.debug_io, null);
        self.transaction_owner.deinitContext(self.runtime_alloc);
        self.transaction_recovery_local_context = null;
        self.transaction_recovery_identity_context = null;
        // Close may flush/coalesce derived watermarks while workers are
        // stopping. That must not call back into the write/status cache after
        // optional runtimes or index state have started tearing down.
        self.setQueryVisibilityHook(null);
        self.async_context.background_closing.store(true, .release);
        stopNativeProjectionMaintenance(self.async_context);
        self.async_context.enrichment_desired_running.store(false, .release);
        if (self.algebraic_hll_owner_id != 0) {
            self.backend_runtime.durable_jobs.closeOwner(self.algebraic_hll_owner_id);
            self.algebraic_hll_owner_id = 0;
        }
        self.publication_recovery.deinit();
        self.backend_runtime.durable_jobs.closeOwner(self.repair_cleanup_owner_id);
        self.backend_runtime.durable_jobs.closeOwner(self.backend_owner_id);
        self.clearLiveDocSetCache();
        self.clearNonVisibleDocSetCache();
        self.clearEmbeddingActivityCache();
        self.embedding_activity.deinit(self.alloc);
        if (self.graph_restore_parse_cache) |*cache| cache.deinit(self.alloc);
        self.graph_restore_parse_cache = null;
        self.bulk_identity.deinit(self.alloc);
        self.clearActiveIndexRepairsLocked();
        self.active_index_repairs.deinit(self.alloc);
        self.closeShadowIndexManagerLocked() catch {};
        self.ttl_owner.deinit(self.runtime_alloc);
        self.ttl_runtime = null;
        self.ttl_cleanup_context = null;
        self.enrichment_owner.deinit(self.runtime_alloc);
        publishEnrichmentOwner(self);
        self.resolution_owner.deinitRuntime(self.runtime_alloc);
        self.resolution_runtime = null;
        self.async_context.resolution_runtime = null;
        // After the resolution runtime (its final catch-up may journal
        // resolution artifacts that notify the promoter) but before the
        // resolution append context the promoter is wired into is destroyed.
        self.promotion_owner_bundle.deinit(self.runtime_alloc);
        self.promotion_runtime = null;
        self.async_context.promotion_runtime = null;
        self.resolution_owner.deinitContext(self.runtime_alloc);
        self.resolution_append_context = null;
        // Derived full-text publishers may be asleep in merge backpressure
        // admission. Close that admission before joining their executor: the
        // merge runtime is the owner of the wakeup predicate, so joining the
        // publishers first can otherwise strand shutdown behind a predicate
        // that is not closed until later in this function. Drain the merge
        // worker too because its tasks borrow inline index generations.
        if (executor_ready) self.executor.beginShutdown();
        if (self.text_merge_runtime) |runtime| _ = runtime.stop();
        if (executor_ready) self.executor.deinit(self.runtime_alloc);
        self.runtime_alloc.destroy(self.executor);
        self.async_context.text_merge_runtime = null;
        self.text_merge_owner.deinit(self.runtime_alloc);
        self.text_merge_runtime = null;
        self.async_context.sparse_compaction_runtime = null;
        self.sparse_compaction_owner.deinit(self.runtime_alloc);
        self.sparse_compaction_runtime = null;
        self.graph_metric_owner.deinit(self.runtime_alloc);
        self.graph_metric_runtime = null;
        if (executor_ready and self.open_mode.allowsIndexWorkers()) {
            // The executor has published its final HBC coverage. Mirror the
            // human-facing lifecycle/status view once at graceful shutdown;
            // a failure cannot invalidate the authoritative posting WAL and
            // will be repaired from it on the next open.
            self.saveAllLiveIndexStatusSnapshots(self.alloc) catch |err| {
                std.log.warn("index status snapshot persistence deferred during close err={s}", .{@errorName(err)});
            };
            self.core.syncStore(true) catch |err| {
                std.log.warn("index status snapshot sync deferred during close err={s}", .{@errorName(err)});
            };
        }
        // Async capture leases are capabilities owned by the live index
        // manager. The executor is stopped above, so no worker can install a
        // new lease; cancel and release any interrupted catch-up capture while
        // that manager is still valid. In particular, do not defer this until
        // after `core.deinit()`, which destroys the manager the leases name.
        self.async_context.deinit(self.runtime_alloc);
        self.runtime_alloc.destroy(self.async_context);
        // A bounded source mark owns a read transaction on core's backend.
        // Workers are stopped; release it before core destroys that backend.
        if (self.local_execution.source_vectors.load(.acquire)) |source| source.cancelMarking();
        const core = self.core;
        core.deinit();
        self.alloc.destroy(core);
        if (self.local_execution.source_vectors.load(.acquire)) |source| {
            source.deinit();
            self.alloc.destroy(source);
        }
        if (self.source_vector_storage) |storage| {
            storage.deinit();
            self.alloc.destroy(storage);
        }
        // Publication locks are opened and closed through the DB runtime's
        // `std.Io`. Release the read generation before destroying an owned
        // runtime, while still retaining the lease until all physical DB
        // state has closed.
        if (self.generation_read_lease) |*lease| lease.deinit();
        self.generation_read_lease = null;
        if (self.owned_backend_runtime) |*runtime| runtime.deinit();
        if (self.owned_resource_manager) |manager| {
            manager.deinit(self.alloc);
            self.alloc.destroy(manager);
        }
        if (self.local_execution.row_policy_bundle) |*bundle| bundle.deinit();
        self.local_execution.row_policy_bundle = null;
        if (self.owned_row_policy_authority_secret) |value| {
            @memset(value, 0);
            self.alloc.free(value);
        }
        if (self.owned_row_policy_authority_issuer) |value| self.alloc.free(value);
        if (self.owned_row_policy_table_name) |value| self.alloc.free(value);
        self.runtime_alloc.destroy(self.local_execution);
        self.* = undefined;
        self.closed = true;
    }

    /// Admit an external recovery pass without exposing write-gate policy.
    pub fn admitTransactionRecovery(self: *DB) !?MutationBarrier.SharedLease {
        var lease = self.acquireReplicationMutationShared();
        errdefer if (lease) |*held| held.release();
        try self.enforceReplicationWriteGate();
        return lease;
    }

    pub fn recoverFinalizedTransactionIntents(self: *DB, now_ns: u64) !u64 {
        return try self.resolveFinalizedTransactionIntentsForRecovery(now_ns);
    }

    pub fn recoverLocalTransactionRecords(self: *DB, cutoff_ns: u64, now_ns: u64) !transactions_mod.RecoveryStats {
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        return try self.core.recoverTransactions(cutoff_ns, now_ns);
    }

    pub fn beginBulkIngestSession(self: *DB) !void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        // Fail promptly while a restored catalog is degraded instead of
        // entering the dense-session admission wait. The apply-locked check
        // below remains authoritative and closes a concurrent publication.
        try self.enforcePortableRuntimeGate();
        try beginExternalDenseBulkSessionTrackedWait(self.async_context, self.backend_runtime.io());
        errdefer finishExternalDenseBulkSessionTrackedBestEffort(self.async_context);
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        const resources = self.core.batchExecutionResources();
        try resources.store.beginBulkIngestSession();
        errdefer resources.store.abortBulkIngestSession();
        // A table bulk window is a primary-store optimization, not permission
        // to mutate active dense topology across committed batches. Dense
        // projection is published afterward through structurally reopenable
        // streaming replay.
        try resources.index_manager.beginSparseBulkIngestSessions();
        errdefer resources.index_manager.abortSparseBulkIngestSessions();
        try resources.index_manager.beginAlgebraicBulkIngestSessions();
        self.configureBulkIngestIdentityAllNewLocked() catch |err| {
            resources.index_manager.abortAlgebraicBulkIngestSessions();
            return err;
        };
        errdefer self.clearBulkIngestIdentityAllNewLocked();
        self.bulk_ingest_session.begin();
    }

    pub fn finishBulkIngestSessionWithOptions(self: *DB, options: backend_types.BulkIngestFinishOptions) !void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        var external_session_tracked = true;
        defer if (external_session_tracked) finishExternalDenseBulkSessionTrackedBestEffort(self.async_context);
        {
            try self.lockApplyForPortableRuntime();
            defer self.core.unlockApply();
            const resources = self.core.batchExecutionResources();
            var first_err: ?anyerror = null;
            resources.index_manager.finishAlgebraicBulkIngestSessionsWithOptions(resources.store, options) catch |err| {
                first_err = err;
            };
            resources.store.finishBulkIngestSessionWithOptions(options) catch |err| {
                if (first_err == null) first_err = err;
            };
            resources.index_manager.finishSparseBulkIngestSessionsWithOptions(options) catch |err| {
                if (first_err == null) first_err = err;
            };
            self.bulk_ingest_session.finish();
            self.clearBulkIngestIdentityAllNewLocked();
            if (first_err) |err| return err;
        }
        external_session_tracked = false;
        _ = try finishExternalDenseBulkSessionTrackedAndFinalize(self.async_context);
        // External bulk finish is the user-visible publication boundary for the
        // staged batch. Publish the primary LSM session, release the deferred
        // replay wake, then wait for structurally reopenable dense replay before
        // returning.
        flushDeferredExternalBulkExecutorNotificationOrTarget(
            self.async_context,
            self.executor,
            self.core.nextDerivedSequence(),
        );
        try self.waitForCurrentSyncLevel(.full_index);
        notifyQueryVisibilityHook(self.async_context, .publish);
    }

    pub fn bulkSessionActive(self: *const DB) bool {
        return self.bulk_ingest_session.active;
    }

    pub fn beginDenseAutoBulkIngestSession(self: *DB) !void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.enforcePortableRuntimeGate();
        try beginExternalDenseBulkSessionTrackedWait(self.async_context, self.backend_runtime.io());
        errdefer finishExternalDenseBulkSessionTrackedBestEffort(self.async_context);
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        const resources = self.core.batchExecutionResources();
        try resources.index_manager.beginDenseBulkIngestSessions();
        self.bulk_ingest_session.begin();
    }

    pub fn beginPrimaryStoreAutoBulkIngestSession(self: *DB) !void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        const resources = self.core.batchExecutionResources();
        try resources.store.beginBulkIngestSession();
        errdefer resources.store.abortBulkIngestSession();
        try self.configureBulkIngestIdentityAllNewLocked();
        errdefer self.clearBulkIngestIdentityAllNewLocked();
        self.bulk_ingest_session.begin();
    }

    pub fn finishPrimaryStoreAutoBulkIngestSessionWithOptions(self: *DB, options: backend_types.BulkIngestFinishOptions) !void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        {
            try self.lockApplyForPortableRuntime();
            defer self.core.unlockApply();
            const resources = self.core.batchExecutionResources();
            resources.store.finishBulkIngestSessionWithOptions(options) catch |err| {
                self.bulk_ingest_session.finish();
                self.clearBulkIngestIdentityAllNewLocked();
                return err;
            };
            self.bulk_ingest_session.finish();
            self.clearBulkIngestIdentityAllNewLocked();
        }
        flushDeferredExternalBulkExecutorNotificationOrTarget(
            self.async_context,
            self.executor,
            self.core.nextDerivedSequence(),
        );
        notifyQueryVisibilityHook(self.async_context, .publish);
    }

    pub fn rollPrimaryStoreAutoBulkIngestSessionWithOptions(self: *DB, options: backend_types.BulkIngestFinishOptions) !void {
        try self.finishPrimaryStoreAutoBulkIngestSessionWithOptions(options);
        try self.beginPrimaryStoreAutoBulkIngestSession();
    }

    pub fn finishDenseAutoBulkIngestSessionWithOptions(self: *DB, options: backend_types.BulkIngestFinishOptions) !void {
        try self.finishDenseAutoBulkIngestSessionWithOptionsInternal(options, true);
    }

    pub fn rollDenseAutoBulkIngestSessionWithOptions(self: *DB, options: backend_types.BulkIngestFinishOptions) !void {
        try self.finishDenseAutoBulkIngestSessionWithOptionsInternal(options, true);
        try self.beginDenseAutoBulkIngestSession();
    }

    fn finishDenseAutoBulkIngestSessionWithOptionsInternal(self: *DB, options: backend_types.BulkIngestFinishOptions, notify_executor: bool) !void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        var external_session_tracked = true;
        defer if (external_session_tracked) finishExternalDenseBulkSessionTrackedBestEffort(self.async_context);
        {
            try self.lockApplyForPortableRuntime();
            defer self.core.unlockApply();
            const resources = self.core.batchExecutionResources();
            resources.store.flushBufferedWritesWithOptions(options) catch |err| {
                self.bulk_ingest_session.finish();
                return err;
            };
            resources.index_manager.finishDenseBulkIngestSessionsWithOptions(options) catch |err| {
                self.bulk_ingest_session.finish();
                self.clearBulkIngestIdentityAllNewLocked();
                return err;
            };
            self.bulk_ingest_session.finish();
            self.clearBulkIngestIdentityAllNewLocked();
        }
        external_session_tracked = false;
        _ = try finishExternalDenseBulkSessionTrackedAndFinalize(self.async_context);
        if (notify_executor) {
            flushDeferredExternalBulkExecutorNotificationOrTarget(
                self.async_context,
                self.executor,
                self.core.nextDerivedSequence(),
            );
        }
        notifyQueryVisibilityHook(self.async_context, .publish);
    }

    pub fn abortDenseAutoBulkIngestSession(self: *DB) void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        lockApply(self);
        {
            defer self.core.unlockApply();
            const resources = self.core.batchExecutionResources();
            self.bulk_ingest_session.finish();
            resources.index_manager.abortDenseBulkIngestSessions();
        }
        finishExternalDenseBulkSessionTrackedBestEffort(self.async_context);
        flushDeferredExternalBulkExecutorNotification(self.async_context, self.executor);
    }

    pub fn abortPrimaryStoreAutoBulkIngestSession(self: *DB) void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        lockApply(self);
        defer self.core.unlockApply();
        const resources = self.core.batchExecutionResources();
        self.bulk_ingest_session.finish();
        self.clearBulkIngestIdentityAllNewLocked();
        resources.store.abortBulkIngestSession();
    }

    pub fn abortBulkIngestSession(self: *DB) void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        lockApply(self);
        {
            defer self.core.unlockApply();
            const resources = self.core.batchExecutionResources();
            self.bulk_ingest_session.finish();
            self.clearBulkIngestIdentityAllNewLocked();
            resources.index_manager.abortAlgebraicBulkIngestSessions();
            resources.index_manager.abortSparseBulkIngestSessions();
            resources.store.abortBulkIngestSession();
        }
        finishExternalDenseBulkSessionTrackedBestEffort(self.async_context);
        flushDeferredExternalBulkExecutorNotification(self.async_context, self.executor);
    }

    pub fn lsmMaintenanceScore(self: *DB) u64 {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        return @max(@intFromBool(self.source_pin_cleanup.epoch.load(.acquire) != 0), @max(
            self.core.primary_store_owner.lsmMaintenanceScore(),
            self.core.index_manager.lsmMaintenanceScore(),
        ));
    }

    pub fn lsmMaintenanceDebtHint(self: *DB) u64 {
        return @max(@intFromBool(self.source_pin_cleanup.epoch.load(.acquire) != 0), @max(
            self.core.primary_store_owner.lsmMaintenanceDebtHint(),
            self.core.index_manager.lsmMaintenanceDebtHint(),
        ));
    }

    pub fn primaryLsmMaintenanceDebtHint(self: *DB) u64 {
        return self.core.primary_store_owner.lsmMaintenanceDebtHint();
    }

    pub fn nextLsmMaintenanceWakeDelayNsBestEffort(self: *DB) ?u64 {
        var delay_ns = self.core.primary_store_owner.nextLsmMaintenanceWakeDelayNsBestEffort();
        if (self.core.index_manager.nextLsmMaintenanceWakeDelayNsBestEffort()) |candidate| {
            delay_ns = if (delay_ns) |current| @min(current, candidate) else candidate;
        }
        if (self.source_pin_cleanup.epoch.load(.acquire) != 0) {
            const candidate = self.source_pin_cleanup.next_ns.load(.acquire) -| monotonicTimeNs();
            delay_ns = if (delay_ns) |current| @min(current, candidate) else candidate;
        }
        return delay_ns;
    }

    pub fn nextPrimaryLsmMaintenanceWakeDelayNsBestEffort(self: *DB) ?u64 {
        return self.core.primary_store_owner.nextLsmMaintenanceWakeDelayNsBestEffort();
    }

    pub fn snapshotAsyncIndexingStats(self: *DB) types.AsyncIndexingStats {
        var async_stats = self.async_context.stats.snapshot();
        // Runtime status must carry the writer-owned native-vector lifecycle
        // fact. A cached materialization snapshot can have a stale HBC count
        // and cannot reconstruct this safely after aggregation. Treat queued
        // native publication as part of the finalization fence: public status
        // exposes it through dense_vector_projection_pending and remains
        // closed until a complete generation is installed.
        async_stats.dense_projection_finalizing =
            self.async_context.dense_admission.finalizing.load(.acquire) or
            self.core.index_manager.vectorBlockProjectionPending();
        async_stats.bulk_coalescing = self.bulk_ingest_session.snapshot();
        async_stats.derived_workers = self.executor.snapshotStats();
        return async_stats;
    }

    pub fn snapshotApplyLockStats(self: *DB) apply_rw_lock_mod.ApplyRwLock.Stats {
        return self.core.apply_mutex.snapshot();
    }

    fn recordStartupOpenStats(self: *DB, profile: OpenProfile) void {
        self.async_context.stats.startup.configured_indexes.store(self.core.index_manager.count(), .monotonic);
        self.async_context.stats.startup.configured_dense_indexes.store(@intCast(self.core.index_manager.dense_indexes.items.len), .monotonic);
