    pub fn runLsmMaintenanceStep(self: *DB) !bool {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        return try self.runLsmMaintenanceStepWithReplicationMutationHeld();
    }

    fn runLsmMaintenanceStepWithReplicationMutationHeld(self: *DB) !bool {
        var snapshot_replay = try self.acquireSnapshotReplayMutation();
        defer snapshot_replay.release();
        return self.runLsmMaintenanceStepAdmitted(&snapshot_replay);
    }

    fn runLsmMaintenanceStepAdmitted(self: *DB, snapshot_replay: *const snapshot_admission_mod.SnapshotAdmission.MutationLease) !bool {
        std.debug.assert(snapshot_replay.active and snapshot_replay.admission == self.core.snapshot_replay_admission);
        if (self.source_pin_cleanup.takeTurn() and try self.runSourcePinCleanupStep()) return true;
        if (try self.core.index_manager.runLsmObsoleteReclaimDue()) return true;
        const primary_reclaim_due = if (self.core.primary_store_owner.nextLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| delay_ns == 0 else false;
        if (primary_reclaim_due) {
            if (try self.core.primary_store_owner.runLsmMaintenanceStep()) return true;
        }

        const primary_score = self.core.primary_store_owner.lsmMaintenanceScore();
        const index_score = self.core.index_manager.lsmMaintenanceScore();
        if (primary_score == 0 and index_score == 0) {
            self.core.primary_store_owner.refreshLsmMaintenanceDebtHint();
            self.core.index_manager.refreshLsmMaintenanceDebtHint();
            return try self.runSourcePinCleanupStep();
        }
        if (primary_score >= index_score) {
            return try self.core.primary_store_owner.runLsmMaintenanceStep();
        }
        return try self.core.index_manager.runLsmMaintenanceStep();
    }

    pub fn runLsmMaintenanceStepBestEffort(self: *DB) !bool {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        var snapshot_replay = try self.acquireSnapshotReplayMutation();
        defer snapshot_replay.release();
        if (self.source_pin_cleanup.takeTurn() and try self.runSourcePinCleanupStep()) return true;
        if (try self.core.index_manager.runLsmObsoleteReclaimDueBestEffort()) return true;
        const primary_reclaim_due = if (self.core.primary_store_owner.nextLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| delay_ns == 0 else false;
        if (primary_reclaim_due) {
            if (try self.core.primary_store_owner.runLsmMaintenanceStepBestEffort()) return true;
        }

        const primary_score = self.core.primary_store_owner.lsmMaintenanceDebtHint();
        if (primary_score > 0) {
            if (try self.core.primary_store_owner.runLsmMaintenanceStepBestEffort()) return true;
        }
        if (try self.core.index_manager.runLsmMaintenanceStepBestEffort()) return true;
        if (primary_score > 0) {
            self.core.primary_store_owner.refreshLsmMaintenanceDebtHint();
        }
        return try self.runSourcePinCleanupStep();
    }

    /// Source-pin deletion shares the LSM maintenance lane; it never creates a
    /// dedicated thread or monopolizes compaction while the corpus is large.
    pub fn runSourcePinCleanupStep(self: *DB) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode) or !self.source_pin_cleanup.due(monotonicTimeNs())) return false;
        const units_before = self.source_pin_cleanup.work_units.load(.acquire);
        const work = @import("source_pin.zig").reconcileReleasedWithBudget(self, .{}) catch |err| {
            const progressed = self.source_pin_cleanup.work_units.load(.acquire) != units_before;
            self.recordSourcePinCleanupFailureWithProgress(err, progressed);
            return progressed;
        };
        const progressed = work.completed_units != 0;
        self.source_pin_cleanup.succeeded(progressed, monotonicTimeNs());
        return progressed;
    }

    pub fn recordSourcePinCleanupFailure(self: *DB, err: anyerror) void {
        self.recordSourcePinCleanupFailureWithProgress(err, false);
    }

    fn recordSourcePinCleanupFailureWithProgress(self: *DB, err: anyerror, progressed: bool) void {
        self.source_pin_cleanup.failed(err, progressed, monotonicTimeNs(), self.core.path);
    }

    pub fn sourcePinCleanupStatus(self: *DB) @import("source_pin_cleanup_owner.zig").Status {
        return self.source_pin_cleanup.status();
    }

    pub fn runPrimaryLsmMaintenanceStep(self: *DB) !bool {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        var snapshot_replay = try self.acquireSnapshotReplayMutation();
        defer snapshot_replay.release();
        if (try self.core.primary_store_owner.runDueLsmObsoleteReclaim()) return true;
        const primary_score = self.core.primary_store_owner.lsmMaintenanceScore();
        const primary_reclaim_due = if (self.core.primary_store_owner.nextLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| delay_ns == 0 else false;
        if (primary_score == 0 and !primary_reclaim_due) return false;
        if (try self.core.primary_store_owner.runLsmMaintenanceStep()) return true;
        self.core.primary_store_owner.refreshLsmMaintenanceDebtHint();
        return false;
    }

    pub fn runPrimaryLsmMaintenanceStepBestEffort(self: *DB) !bool {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        var snapshot_replay = try self.acquireSnapshotReplayMutation();
        defer snapshot_replay.release();
        if (try self.core.primary_store_owner.runDueLsmObsoleteReclaim()) return true;
        const primary_score = self.core.primary_store_owner.lsmMaintenanceDebtHint();
        const primary_reclaim_due = if (self.core.primary_store_owner.nextLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| delay_ns == 0 else false;
        if (primary_score == 0 and !primary_reclaim_due) return false;
        if (try self.core.primary_store_owner.runLsmMaintenanceStepBestEffort()) return true;
        self.core.primary_store_owner.refreshLsmMaintenanceDebtHint();
        return false;
    }

    pub fn hasActiveDenseBulkWork(self: *const DB) bool {
        return asyncContextHasActiveDenseBulkWork(self.async_context);
    }

    pub fn runLsmMaintenanceUntilIdle(self: *DB) !usize {
        var steps: usize = 0;
        while (try self.runLsmMaintenanceStep()) {
            steps += 1;
        }
        return steps;
    }

    pub fn runDueLsmObsoleteReclaimUntilIdle(self: *DB, max_steps: usize) !usize {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        var snapshot_replay = try self.acquireSnapshotReplayMutation();
        defer snapshot_replay.release();
        var steps: usize = 0;
        while (steps < max_steps) : (steps += 1) {
            var progressed = false;
            if (try self.core.primary_store_owner.runDueLsmObsoleteReclaim()) progressed = true;
            if (try self.core.index_manager.runLsmObsoleteReclaimDue()) progressed = true;

            if (!progressed) {
                const wake_due = if (self.nextLsmMaintenanceWakeDelayNsBestEffort()) |delay_ns| delay_ns == 0 else false;
                if (!wake_due) break;
                if (!try self.runLsmMaintenanceStepAdmitted(&snapshot_replay)) break;
            }
        }
        return steps;
    }

    test "db lsm maintenance reclaims due index obsolete paths before primary compaction" {
        const alloc = std.testing.allocator;
        var path_tmp = try TestDirectory.init("db");
        defer path_tmp.cleanup();
        const path = path_tmp.path().ptr;
        defer cleanupTempDir(path);

        var db = try DB.open(alloc, std.mem.span(path), .{
            .start_index_workers = false,
            // This test drives primary maintenance explicitly; keep detached
            // primary LSM maintenance from racing the precondition checks.
            .executor = .{ .backend = .manual },
            .primary_backend = .{ .lsm = .{
                .flush_threshold = 1,
                .defer_flush_on_commit = true,
                .l0_soft_limit_runs = 100,
                .obsolete_retention_ns = 0,
            } },
            .index_backends = .{
                .dense_lsm_options = .{
                    .flush_threshold = 1,
                    .defer_flush_on_commit = true,
                    .l0_soft_limit_runs = 100,
                    .obsolete_retention_ns = 0,
                },
            },
        });
        defer db.close();

        try db.addIndex(.{
            .name = "dv_v1",
            .kind = .dense_vector,
            .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\"}",
        });

        var key_buf: [16]u8 = undefined;
        for (0..4) |i| {
            const key = try std.fmt.bufPrint(&key_buf, "doc:{d}", .{i});
            try db.batch(.{
                .writes = &.{.{ .key = key, .value = "{\"embedding\":[1,2]}" }},
                .sync_level = .write,
            });
            switch (db.core.primary_store_owner) {
                .lsm => |*owner| try owner.handle.backend.sync(true),
                else => return error.SkipZigTest,
            }
        }

        switch (db.core.primary_store_owner) {
            .lsm => |*owner| try owner.handle.backend.flushBufferedWritesWithOptions(.{ .compact = false, .flush = true }),
            else => return error.SkipZigTest,
        }

        switch (db.core.primary_store_owner) {
            .lsm => |*owner| owner.handle.backend.options.l0_soft_limit_runs = 1,
            else => return error.SkipZigTest,
        }

        const dense_entry = db.core.index_manager.denseIndex("dv_v1") orelse return error.TestUnexpectedResult;
        const dense_backend = switch (dense_entry.index.env_owner) {
            .lsm => |*handle| handle.backend,
            else => return error.SkipZigTest,
        };
        const dense_root = dense_backend.root_dir orelse return error.TestUnexpectedResult;
        const obsolete_path = try lsm_backend_mod.repository.runPath(alloc, dense_root, 999_999);
        defer alloc.free(obsolete_path);

        try lsm_backend_mod.repository.writeFileAbsoluteWithStorage(dense_backend.storage.?, obsolete_path, "obsolete");
        {
            const locked = lsm_backend_mod.runtime.lockBackend(lsm_backend_mod.Backend, dense_backend);
            defer lsm_backend_mod.runtime.unlockBackend(lsm_backend_mod.Backend, dense_backend, locked);
            try dense_backend.queueObsoleteFilePath(try alloc.dupe(u8, obsolete_path));
            dense_backend.manifest_dirty = false;
        }

        try expectObsoletePathsReclaimable(dense_backend, 1);
        try std.testing.expect(try db.runLsmMaintenanceStepBestEffort());
        try std.testing.expectEqual(@as(u64, 0), dense_backend.snapshotMaintenanceStats().obsolete_paths);
        try std.testing.expectError(error.FileNotFound, dense_backend.storage.?.readFileAlloc(alloc, obsolete_path, 1024));
    }

    /// A queued obsolete path only counts as reclaimable once no reader pins
    /// the backend; transient background readers (index loads, status probes)
    /// mask it as pinned_by_readers for a moment. Poll instead of asserting a
    /// single snapshot so loaded CI machines don't flake.
    fn expectObsoletePathsReclaimable(backend: *lsm_backend_mod.Backend, expected: u64) !void {
        var attempts: usize = 0;
        while (backend.snapshotMaintenanceStats().obsolete_paths_reclaimable != expected) : (attempts += 1) {
            if (attempts >= 2000) {
                return std.testing.expectEqual(expected, backend.snapshotMaintenanceStats().obsolete_paths_reclaimable);
            }
            std.testing.io.sleep(.fromNanoseconds(1), .awake) catch {};
        }
    }

    test "db primary lsm maintenance step does not reclaim index obsolete paths" {
        const alloc = std.testing.allocator;
        var path_tmp = try TestDirectory.init("db");
        defer path_tmp.cleanup();
        const path = path_tmp.path().ptr;
        defer cleanupTempDir(path);

        var db = try DB.open(alloc, std.mem.span(path), .{
            .start_index_workers = false,
            // This test verifies the explicit primary-only maintenance entry
            // point; keep detached LSM maintenance from consuming the queued
            // primary obsolete path before the assertion.
            .executor = .{ .backend = .manual },
            .primary_backend = .{ .lsm = .{
                .flush_threshold = 1,
                .defer_flush_on_commit = true,
                .l0_soft_limit_runs = 100,
                .obsolete_retention_ns = 0,
            } },
            .index_backends = .{
                .dense_lsm_options = .{
                    .flush_threshold = 1,
                    .defer_flush_on_commit = true,
                    .l0_soft_limit_runs = 100,
                    .obsolete_retention_ns = 0,
                },
            },
        });
        defer db.close();

        try db.addIndex(.{
            .name = "dv_v1",
            .kind = .dense_vector,
            .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\"}",
        });

        const primary_backend = switch (db.core.primary_store_owner) {
            .lsm => |*owner| owner.handle.backend,
            else => return error.SkipZigTest,
        };
        const primary_root = primary_backend.root_dir orelse return error.TestUnexpectedResult;
        const primary_obsolete_path = try lsm_backend_mod.repository.runPath(alloc, primary_root, 888_888);
        defer alloc.free(primary_obsolete_path);

        const dense_entry = db.core.index_manager.denseIndex("dv_v1") orelse return error.TestUnexpectedResult;
        const dense_backend = switch (dense_entry.index.env_owner) {
            .lsm => |*handle| handle.backend,
            else => return error.SkipZigTest,
        };
        const dense_root = dense_backend.root_dir orelse return error.TestUnexpectedResult;
        const dense_obsolete_path = try lsm_backend_mod.repository.runPath(alloc, dense_root, 999_999);
        defer alloc.free(dense_obsolete_path);

        try lsm_backend_mod.repository.writeFileAbsoluteWithStorage(primary_backend.storage.?, primary_obsolete_path, "primary obsolete");
        {
            const locked = lsm_backend_mod.runtime.lockBackend(lsm_backend_mod.Backend, primary_backend);
            defer lsm_backend_mod.runtime.unlockBackend(lsm_backend_mod.Backend, primary_backend, locked);
            try primary_backend.queueObsoleteFilePath(try alloc.dupe(u8, primary_obsolete_path));
            primary_backend.manifest_dirty = false;
        }

        try lsm_backend_mod.repository.writeFileAbsoluteWithStorage(dense_backend.storage.?, dense_obsolete_path, "dense obsolete");
        {
            const locked = lsm_backend_mod.runtime.lockBackend(lsm_backend_mod.Backend, dense_backend);
            defer lsm_backend_mod.runtime.unlockBackend(lsm_backend_mod.Backend, dense_backend, locked);
            try dense_backend.queueObsoleteFilePath(try alloc.dupe(u8, dense_obsolete_path));
            dense_backend.manifest_dirty = false;
        }

        try expectObsoletePathsReclaimable(primary_backend, 1);
        try expectObsoletePathsReclaimable(dense_backend, 1);

        _ = try db.runPrimaryLsmMaintenanceStep();

        try std.testing.expectEqual(@as(u64, 0), primary_backend.snapshotMaintenanceStats().obsolete_paths);
        try std.testing.expectError(error.FileNotFound, primary_backend.storage.?.readFileAlloc(alloc, primary_obsolete_path, 1024));
        try std.testing.expectEqual(@as(u64, 1), dense_backend.snapshotMaintenanceStats().obsolete_paths);
        const dense_bytes = try dense_backend.storage.?.readFileAlloc(alloc, dense_obsolete_path, 1024);
        alloc.free(dense_bytes);
    }

    fn drainStandaloneGraphEndpointCleanup(self: *DB) !bool {
        return self.drainStandaloneGraphEndpointCleanupWithOptions(.{}, std.math.maxInt(usize));
    }

    fn drainStandaloneGraphEndpointCleanupWithOptions(self: *DB, opts: BatchExecutionOptions, max_pages: usize) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return false;
        // Most batches create no endpoint jobs. Avoid authority probes and
        // maintenance admission altogether on their completion path.
        if (!try self.core.store.hasGraphEndpointCleanup()) return false;
        if (!try self.canRunLocalGraphEndpointCleanup()) return false;
        var pages: usize = 0;
        while (pages < max_pages and try self.core.store.hasGraphEndpointCleanup()) {
            if (!try self.canRunLocalGraphEndpointCleanup()) break;
            // The primary mutation is already durable. Cancellation can leave
            // queued maintenance for the resident owner, but must never interrupt
            // a page halfway through its atomic commit. Explicit drains use .none.
            if (opts.visibility_cancellation.isCancelled()) return error.EnrichmentWaitCanceled;
            try self.batchInternal(.{ .graph_endpoint_cleanup = true, .sync_level = .write }, null, .{
                .document_child_range_dispatcher = opts.document_child_range_dispatcher,
                .committed_batch_effects_observer = opts.committed_batch_effects_observer,
            });
            pages += 1;
        }
        return pages != 0;
    }

    /// Shared completion for ordinary, profiled, callback and transaction
    /// batches, after the serialized primary apply section has finished.
    /// Replicated apply must only execute its exact command; its owner drives
    /// cleanup independently through subsequent ordered Raft entries.
    pub fn finishBatchGraphEndpointCleanup(self: *DB, req: types.BatchRequest, opts: BatchExecutionOptions) !void {
        if (req.graph_endpoint_cleanup or !opts.wait_for_sync_level or
            opts.ordered_apply_receipt != null or opts.replication_applied_lsn_marker != null or
            opts.native_initial_child_entry != null or opts.restore_staging != null or
            req.restore_staging_scope != null or req.restore_staging != null) return;
        // Weak sync levels pay for at most one bounded maintenance page.
        // Durable jobs continue through the resident scheduler; full_index
        // and explicit maintenance retain complete cleanup guarantees.
        const max_pages: usize = if (req.sync_level == .full_index) std.math.maxInt(usize) else 1;
        const drained = try self.drainStandaloneGraphEndpointCleanupWithOptions(opts, max_pages);
        // A resident worker can finish before the foreground queue probe.
        // Deletes/transforms must still include its newly committed replay cut.
        if (req.sync_level == .full_index and (drained or req.writes.len != 0 or req.deletes.len != 0 or req.transforms.len != 0))
            try self.waitForCurrentSyncLevelWithCancellation(.full_index, opts.visibility_cancellation);
    }

    /// Local maintenance follows the same captured write admission as user writes.
    /// A retained standby/fenced generation may open and replay exact commands,
    /// but cannot choose cleanup effects or mutate its local directory on its own.
    fn graphEndpointCleanupWriteAuthority(self: *DB) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return false;
        return if (self.local_execution.replication_write_gate) |gate| gate.allowsBackgroundWrite() else true;
    }

    fn canRunLocalGraphEndpointCleanup(self: *DB) !bool {
        if (!try self.graphEndpointCleanupWriteAuthority()) return false;
        return !try self.maintenanceRequiresOrderedApply();
    }

    pub const maintenanceRequiresOrderedApply = local_mutation.maintenanceRequiresOrderedApply;

    fn startGraphEndpointCleanupWorker(self: *DB) void {
        if (comptime builtin.os.tag == .freestanding) return;
        if (!self.stable_address or !self.local_execution.optional_runtime_workers_enabled or self.open_mode != .writer) return;
        if (!(self.canRunLocalGraphEndpointCleanup() catch false)) return;
        self.graph_cleanup_owner.start(self.graphCleanupPort());
    }
    fn graphCleanupPort(self: *DB) @import("graph_cleanup_owner.zig").Owner.Port {
        return .{ .ptr = self, .runtime = self.backend_runtime, .run = graphCleanupPage };
    }
    fn graphCleanupPage(ptr: *anyopaque) !bool {
        const self: *DB = @ptrCast(@alignCast(ptr));
        return self.runStandaloneGraphEndpointCleanupStep();
    }
    fn stopGraphEndpointCleanupWorker(self: *DB) void {
        self.graph_cleanup_owner.stop(self.backend_runtime.io());
    }
    fn graphEndpointCleanupWorkerStep(self: *DB) ?u64 {
        return self.graph_cleanup_owner.step(self.graphCleanupPort());
    }

    /// Every enqueue path is serviced independently of subsequent foreground
    /// writes. Each scheduler turn commits at most one bounded page.
    fn runStandaloneGraphEndpointCleanupStep(self: *DB) !bool {
        if (!try self.canRunLocalGraphEndpointCleanup()) return false;
        if (!try self.core.store.hasGraphEndpointCleanup()) {
            // A ready directory needs no work. Idle owners must not contend
            // with user mutations for the apply lock every scheduler turn.
            if (try self.core.store.graphIncomingDirectoryReady()) return false;
            try self.lockApplyForPortableRuntime();
            defer self.core.unlockApply();
            if (!try self.canRunLocalGraphEndpointCleanup()) return false;
            if (self.core.index_manager.hasGraphIndexes() and !try self.core.store.graphIncomingDirectoryReady())
                return !try self.core.store.backfillGraphIncomingDirectoryPage();
            return false;
        }
        try self.batchInternal(.{ .graph_endpoint_cleanup = true, .sync_level = .write }, null, .{});
        return true;
    }

    pub const GraphEndpointCleanupBatch = struct {
        page: docstore_mod.DocStore.GraphEndpointCleanupPage,
        graph_deletes: []types.GraphEdgeDelete,
        replay_writes: []types.BatchWrite = &.{},
        pub fn request(self: *const @This()) types.BatchRequest {
            return .{ .graph_endpoint_cleanup = true, .graph_endpoint_cleanup_planned = true, .graph_endpoint_cleanup_guards = self.page.guards, .graph_deletes = self.graph_deletes, .merge_artifacts = self.replay_writes, .deletes = self.page.deletes, .sync_level = .write };
        }
        pub fn deinit(self: *@This()) void {
            for (self.graph_deletes) |*item| item.deinit(self.page.alloc);
            self.page.alloc.free(self.graph_deletes);
            if (self.replay_writes.len != 0) self.page.alloc.free(self.replay_writes);
            self.page.deinit();
        }
    };

    /// The leader selects exact identities before proposal. Followers apply
    /// these afterimages rather than consulting their local directory progress.
    pub fn prepareGraphEndpointCleanupBatch(self: *DB, alloc: Allocator) !?GraphEndpointCleanupBatch {
        if (!try self.graphEndpointCleanupWriteAuthority()) return null;
        if (!try self.core.store.hasGraphEndpointCleanup() and try self.core.store.graphIncomingDirectoryReady()) return null;
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (!try self.graphEndpointCleanupWriteAuthority()) return null;
        if (!try self.core.store.hasGraphEndpointCleanup()) {
            // Build local directory coverage ahead of future endpoint deletes,
            // without proposing empty Raft maintenance entries.
            if (self.core.index_manager.hasGraphIndexes() and !try self.core.store.graphIncomingDirectoryReady())
                _ = try self.core.store.backfillGraphIncomingDirectoryPage();
            return null;
        }
        var page = (try self.core.store.prepareGraphEndpointCleanupPage(alloc)) orelse return null;
        errdefer page.deinit();
        const replay_writes = try graphCleanupReplayWritesAlloc(alloc, page);
        errdefer alloc.free(replay_writes);
        return .{ .page = page, .graph_deletes = try graphEndpointCleanupDeletesAlloc(alloc, page), .replay_writes = replay_writes };
    }

    fn requireGraphEndpointCleanupReady(self: *DB) !void {
        if (!try self.core.store.graphEndpointCleanupBlocksReads()) return;
        return error.StorageBusy;
    }

