    /// Applies one exact data-Raft log entry and persists its identity in the
    /// same primary-store batch. Replaying the entry after a crash becomes an
    /// allocation-light no-op before transforms or derived work execute.
    /// Execute a committed ordered mutation. The receipt and primary effects
    /// share a store transaction; server replay policy is supplied by the caller.
    pub fn applyOrderedCommittedMutation(self: *DB, request: types.BatchRequest, identity: OrderedApplyReceipt, bypass_write_gate: bool) anyerror!void {
        if (request.graph_endpoint_cleanup and !request.graph_endpoint_cleanup_planned) return error.InvalidBatchRequest;
        try self.batchInternal(request, null, .{
            .validate_range_ownership = false,
            .wait_for_sync_level = false,
            .bypass_replication_write_gate = bypass_write_gate,
            .ordered_apply_receipt = identity,
        });
    }

    pub fn recoverOrderedSourceAdmission(self: *DB, request: types.BatchRequest, identity: OrderedApplyReceipt, bypass_write_gate: bool) !void {
        try self.applyOnlineSourceBatch(request, .{
            .validate_range_ownership = false,
            .wait_for_sync_level = false,
            .bypass_replication_write_gate = bypass_write_gate,
            .ordered_apply_receipt = identity,
        });
    }

    /// A hidden initial child in native standalone has no data-Raft log. The
    /// metadata decision names one immutable plan and owner, while the
    /// hidden Record commits the operation receipt with the schema/phase.
    /// Keep this distinct from the generic Raft path: native source roots
    /// must never acquire a fabricated Raft applied-entry watermark.
    pub fn batchNativeInitialChildApply(self: *DB, req: types.BatchRequest, receipt: OrderedApplyReceipt) !void {
        const command = req.relational_topology orelse return error.InvalidInitialChildPublication;
        if (command.action != .provision_initial_child and command.action != .release_initial_child and command.action != .cancel_initial_child)
            return error.InvalidInitialChildPublication;
        if (receipt.term != 1 or receipt.index != switch (command.action) {
            .provision_initial_child => @as(u64, 1),
            .release_initial_child => @as(u64, 2),
            .cancel_initial_child => @as(u64, 3),
            else => unreachable,
        }) return error.InvalidInitialChildPublication;
        if (req.writes.len != 0 or req.deletes.len != 0 or req.transforms.len != 0 or
            req.graph_writes.len != 0 or req.graph_deletes.len != 0 or req.predicates.len != 0 or
            req.integrity.len != 0 or req.integrity_commands.len != 0 or req.range_guards.len != 0 or
            req.online_source != null or req.restore_staging != null or req.restore_staging_scope != null or
            req.restore_staging_plan_id != null or req.relational_generation_gc != null or
            req.relational_activation != null or req.relational_retirement != null or
            req.relational_index_maintenance != null or req.row_policy_publication != null or
            req.row_policy_install_bundle.len != 0 or req.row_policy_principal_proof.len != 0 or
            req.row_policy_database.len != 0 or req.row_policy_admitted_at_seconds != 0 or
            req.split_checkpoint != null or req.split_replication != null or req.split_transition != null or
            req.merge_source_transition != null or req.merge_checkpoint != null or req.merge_replication != null or
            req.merge_page != null or req.merge_artifacts.len != 0 or req.transaction != null or
            req.relational_repair or req.activate_range_tracking or req.reject_graph_transform_projections or
            req.schema_version != null or req.relational_schema_version != null or
            req.relational_integrity_generation_set != null or req.timestamp_ns != 0)
            return error.InvalidInitialChildPublication;
        const bootstrap = self.local_execution.initial_child_bootstrap orelse return error.InvalidInitialChildPublication;
        if (self.local_execution.replication_async_batch_mirror != null or self.local_execution.replication_async_metadata_mirror != null or
            self.local_execution.replication_async_effect_mirror != null or self.local_execution.replication_write_gate != null or
            openModeRequiresReadOnlyBackends(self.open_mode))
            return error.InvalidInitialChildPublication;
        if (!bootstrap.namespace.eql(command.fence.namespace) or
            !std.mem.eql(u8, &bootstrap.catalog_digest, &command.fence.catalog_digest))
            return error.InitialChildPublicationChanged;
        switch (command.action) {
            .provision_initial_child => {
                const provision = command.initial_child_provision orelse return error.InvalidInitialChildPublication;
                if (!std.mem.eql(u8, &bootstrap.plan_id, &provision.plan_id) or
                    !std.mem.eql(u8, &bootstrap.plan_digest, &provision.plan_digest) or
                    !std.mem.eql(u8, &bootstrap.schema_digest, &provision.schema_digest) or
                    !std.mem.eql(u8, &bootstrap.public_schema_json_digest, &provision.public_schema_json_digest) or
                    !std.mem.eql(u8, &bootstrap.catalog_digest, &provision.catalog_digest))
                    return error.InitialChildPublicationChanged;
            },
            .release_initial_child, .cancel_initial_child => {
                const control = command.initial_child_control orelse return error.InvalidInitialChildPublication;
                if (!std.mem.eql(u8, &bootstrap.plan_id, &control.plan_id) or
                    !std.mem.eql(u8, &bootstrap.plan_digest, &control.plan_digest) or
                    bootstrap.schema_version != control.schema_version or
                    !std.mem.eql(u8, &bootstrap.schema_digest, &control.schema_digest) or
                    !std.mem.eql(u8, &bootstrap.public_schema_json_digest, &control.public_schema_json_digest) or
                    !std.mem.eql(u8, &bootstrap.catalog_digest, &control.catalog_digest))
                    return error.InitialChildPublicationChanged;
            },
            else => unreachable,
        }
        var authority = try self.core.store.beginReadTxn();
        defer authority.abort();
        _ = try @import("../source_authority.zig").require(&authority, .native, @import("online_source_contract.zig").namespaceBytes(self.core.identity_namespace));
        return self.batchInternal(req, null, .{
            .validate_range_ownership = false,
            .wait_for_sync_level = false,
            .bypass_replication_write_gate = true,
            .native_initial_child_entry = receipt,
        });
    }

    /// A native owner has no Raft log. Metadata still authorizes the exact
    /// publication fence, and its operation receipt commits with the effect,
    /// without advancing the unrelated Raft apply watermark.
    pub fn batchNativeFkGenerationApply(self: *DB, req: types.BatchRequest) !void {
        const command = req.relational_topology orelse return error.InvalidBatchRequest;
        if (command.fence.role != .child_generation_source and command.fence.role != .child_generation_parent and
            command.fence.role != .child_generation_dual) return error.InvalidBatchRequest;
        const ordinal: u64 = switch (command.action) {
            .begin => 1,
            .stage_child_generation => 2,
            .activate_child_generation => 3,
            .acknowledge_child_generation => 4,
            .install_child_schema => 5,
            .cancel => 6,
            .cancel_child_generation_source => 7,
            else => return error.InvalidBatchRequest,
        };
        // This boundary accepts a control only, never a mixed user mutation.
        const defaults: types.BatchRequest = .{};
        inline for (@typeInfo(types.BatchRequest).@"struct".field_names, @typeInfo(types.BatchRequest).@"struct".field_types) |reflected_name, field_type| {
            if (comptime !std.mem.eql(u8, reflected_name, "relational_topology") and !std.mem.eql(u8, reflected_name, "sync_level")) {
                const value = @field(req, reflected_name);
                if (comptime @typeInfo(field_type) == .pointer and @typeInfo(field_type).pointer.size == .slice) {
                    if (value.len != 0) return error.InvalidBatchRequest;
                } else if (!std.meta.eql(value, @field(defaults, reflected_name))) return error.InvalidBatchRequest;
            }
        }
        if (command.transfer != null or command.parent_retirement != null or command.parent_activation != null or
            command.initial_child_provision != null or command.initial_child_control != null or command.graph_retirement != null or
            command.generation_handoff != null or command.generation_handoff_seal != null or command.generation_handoff_install != null)
            return error.InvalidBatchRequest;
        if (self.local_execution.replication_async_batch_mirror != null or self.local_execution.replication_async_metadata_mirror != null or
            self.local_execution.replication_async_effect_mirror != null or self.local_execution.replication_write_gate != null or openModeRequiresReadOnlyBackends(self.open_mode))
            return error.UnsupportedOperation;
        _ = try command.fence.encode();
        var authority = try self.core.store.beginReadTxn();
        defer authority.abort();
        _ = try @import("../source_authority.zig").require(&authority, .native, @import("online_source_contract.zig").namespaceBytes(self.core.identity_namespace));
        return self.batchInternal(req, null, .{
            .validate_range_ownership = false,
            .wait_for_sync_level = false,
            .native_fk_generation_entry = .{ .term = command.fence.admission_epoch, .index = ordinal },
        });
    }

    pub fn failNextRestoreProjectionApplyForTest() void {
        std.debug.assert(builtin.is_test);
        test_fail_restore_projection_apply = true;
    }

    /// The durable Raft projection validates the split lifecycle before the
    /// document delegate runs. Mirror its finalized range on every replica,
    /// without sending an empty source command through document/index work.
    /// The range and entry receipt share a batch so restart replay cannot
    /// narrow a range again after a later merge has expanded it.
    fn applyRangeFinalization(
        self: *DB,
        transition: types.SplitTransitionMutation,
        identity: ?OrderedApplyReceipt,
        replication_lsn: ?u64,
        replication_payload: ?[]const u8,
    ) !void {
        var snapshot_mutation = self.core.snapshot_admission.acquireMutation();
        defer snapshot_mutation.release();
        lockApply(self);
        defer self.core.unlockApply();
        var transaction_manager = try self.core.initTxnManager();
        defer transaction_manager.deinit();
        if (try transaction_manager.hasSchemaLeases()) return error.SchemaInUse;
        if (identity) |entry| switch (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), entry)) {
            .already_applied => return,
            .apply => {},
        };
        const current = self.core.byteRange();
        if (transition.transition_id == 0 or transition.attempt_epoch == 0 or
            transition.destination_group_id == 0 or transition.split_key.len == 0 or
            !std.mem.lessThan(u8, current.start, transition.split_key) or
            (current.end.len != 0 and std.mem.lessThan(u8, current.end, transition.split_key)))
            return error.InvalidSplitRange;
        const start = try self.alloc.dupe(u8, current.start);
        errdefer self.alloc.free(start);
        const end = try self.alloc.dupe(u8, transition.split_key);
        errdefer self.alloc.free(end);
        const range: types.ByteRange = .{ .start = start, .end = end };
        const range_value = try range_state_mod.encodeRangeAlloc(self.alloc, range);
        defer self.alloc.free(range_value);
        // Publish graph source ownership before acknowledging the transition.
        // Physical retirement is a durable maintenance task, not Raft apply
        // work. Reverse reads use the same source fence; old metric jobs are
        // invalidated before they can publish against the narrowed range.
        self.core.index_manager.fenceGraphSplitRange(transition.split_key, current.end) catch |err| switch (err) {
            // A previous split's cleanup is bounded background work. Keep
            // this committed entry pending, not a fatal Raft apply failure.
            error.GraphMaintenanceInProgress => return error.RaftApplyWriterUnavailable,
            else => return err,
        };
        if (builtin.is_test and graph_mod.test_abort_ownership_before_range_commit) return error.TestInjectedBackfillFailure;
        var marker_buf: [ordered_apply_receipt_value_len]u8 = undefined;
        var replication_marker_buf: [replication_applied_lsn_value_len]u8 = undefined;
        var outbox_value: ?[]u8 = null;
        defer if (outbox_value) |bytes| self.alloc.free(bytes);
        var outbox_key: ?[]u8 = null;
        defer if (outbox_key) |bytes| self.alloc.free(bytes);
        var integrity_coverage: ?[]u8 = null;
        defer if (integrity_coverage) |bytes| self.alloc.free(bytes);
        var receipt: [136]u8 = undefined;
        var metadata_writes: std.ArrayList(docstore_mod.KVPair) = .empty;
        defer metadata_writes.deinit(self.alloc);
        try metadata_writes.append(self.alloc, .{ .key = range_state_mod.range_key, .value = range_value });
        if (identity) |entry| try metadata_writes.append(self.alloc, orderedApplyReceiptWrite(entry, &marker_buf));
        if (replication_lsn) |lsn| try metadata_writes.append(self.alloc, replicationAppliedSequenceWrite(lsn, &replication_marker_buf));
        if (replication_payload) |payload| {
            const mirror = self.local_execution.replication_async_batch_mirror orelse return error.ReplicationPublisherUnavailable;
            const from_lsn = mirror.publisher.nextLsn();
            outbox_value = try encodeDurableReplicationOutboxAlloc(self.alloc, from_lsn, payload);
            outbox_key = try durableReplicationOutboxKeyAlloc(self.alloc, .restore_batch, from_lsn, self.core.root_generation, payload);
            try metadata_writes.append(self.alloc, .{ .key = outbox_key.?, .value = outbox_value.? });
            self.local_execution.durable_replication_outbox_maybe.store(true, .release);
        }
        {
            var view = self.core.acquireSchemaView();
            defer if (view) |*pinned| pinned.release();
            if (hasCoordinatedConstraints(view)) {
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                const topology = @import("relational_integrity_topology.zig");
                const fence = (try topology.current(&read)) orelse return error.CoordinatedConstraintTopologyUnsupported;
                if (fence.role != .split_source or fence.transition_id != transition.transition_id or fence.attempt != transition.attempt_epoch or fence.peer_group_id != transition.destination_group_id) return error.IntegrityTopologyChanged;
                try topology.requireDrained(&read, &transaction_manager, fence);
                const raw_catalog = try read.get(@import("relational_integrity_catalog.zig").key);
                var compiled = try @import("relational_integrity_catalog.zig").decode(self.alloc, raw_catalog);
                defer compiled.deinit();
                try @import("relational_integrity_activation.zig").requireReady(&read, compiled);
                integrity_coverage = try @import("relational_integrity_handoff.zig").coverageForRange(self.alloc, raw_catalog, self.core.identity_namespace, range);
                receipt = try fence.encode();
                try metadata_writes.appendSlice(self.alloc, &.{ .{ .key = @import("relational_integrity_activation.zig").key, .value = integrity_coverage.? }, .{ .key = topology.receipt_key, .value = &receipt } });
            } else {
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                try @import("relational_integrity_topology.zig").requireUnfenced(&read);
            }
        }
        try rebaseRangeCoverageMetadata(self.alloc, self.core.store, self.core.index_manager, range, metadata_writes.items);
        self.core.adoptRangeInMemoryOwned(start, end);
    }

    /// Pin primary data and its ordered receipt under the local apply lock.
    /// A server adapter supplies any surrounding protocol completion fence.
    pub fn pinTransferablePrimarySnapshot(self: *DB) !TransferablePrimarySnapshot {
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        var namespace: [24]u8 = undefined;
        doc_identity.encodeNamespace(&namespace, self.core.identity_namespace);
        {
            var read = try self.core.store.beginProbeTxn();
            defer read.abort();
            try @import("../source_pin_state.zig").requireNoPrepared(&read, namespace);
            try @import("online_source.zig").requireTransferableSnapshots(&read, namespace);
        }
        const marker = try readOrderedApplyReceipt(self.alloc, self.core.store);
        var primary = try self.core.pinNativeSnapshot();
        errdefer primary.deinit();
        switch (primary) {
            .logical => return error.UnsupportedSnapshotFormat,
            .lsm => |checkpoint| if (!checkpoint.storage.supportsHostPathGenerationPublication()) return error.UnsupportedSnapshotFormat,
        }
        return .{ .alloc = self.alloc, .io = self.backend_runtime.filesystemIo() orelse return error.BackendRuntimeIoUnavailable, .namespace = namespace, .receipt = marker, .primary = primary };
    }

    pub const TransferablePrimarySnapshot = struct {
        alloc: Allocator,
        io: std.Io,
        namespace: [24]u8,
        receipt: ?OrderedApplyReceipt,
        primary: db_core.PinnedStoreSnapshot,
    };

    pub fn verifyTransferablePrimarySnapshot(self: *DB, namespace: [24]u8, receipt: ?OrderedApplyReceipt) !void {
        var actual_namespace: [24]u8 = undefined;
        doc_identity.encodeNamespace(&actual_namespace, self.core.identity_namespace);
        if (!std.mem.eql(u8, &actual_namespace, &namespace)) return error.InvalidSnapshot;
        const marker = try self.orderedApplyReceipt();
        if ((if (marker) |value| value.index else 0) != (if (receipt) |value| value.index else 0) or
            (if (marker) |value| value.term else 0) != (if (receipt) |value| value.term else 0)) return error.InvalidSnapshot;
        var read = try self.core.store.beginProbeTxn();
        defer read.abort();
        try @import("../source_pin_state.zig").requireNoPrepared(&read, namespace);
        try @import("online_source.zig").requireTransferableSnapshots(&read, namespace);
    }

    pub fn orderedApplyReceipt(self: *DB) !?OrderedApplyReceipt {
        lockApply(self);
        defer self.core.unlockApply();
        return try readOrderedApplyReceipt(self.alloc, self.core.store);
    }

    pub fn orderedMutationAlreadyApplied(self: *DB, identity: OrderedApplyReceipt) !bool {
        lockApply(self);
        defer self.core.unlockApply();
        return switch (try orderedApplyDisposition(
            try readOrderedApplyReceipt(self.alloc, self.core.store),
            identity,
        )) {
            .apply => false,
            .already_applied => true,
        };
    }

    pub fn recordOrderedApplyReceipt(self: *DB, identity: OrderedApplyReceipt) !void {
        lockApply(self);
        defer self.core.unlockApply();
        switch (try orderedApplyDisposition(
            try readOrderedApplyReceipt(self.alloc, self.core.store),
            identity,
        )) {
            .already_applied => return,
            .apply => {},
        }
        var value_buf: [ordered_apply_receipt_value_len]u8 = undefined;
        const marker = orderedApplyReceiptWrite(identity, &value_buf);
        try self.core.store.putBatch(&.{marker}, &.{});
    }

    /// Apply an exact metadata-read-index policy publication through the data
    /// Raft log. The ingress must obtain `bundle_bytes` from the provisioned
    /// metadata leader callback, never from a user request. The bundle,
    /// fail-closed preparing catalog, pending receipt intent, and applied
    /// marker commit atomically on every replica. Receipt publication is a
    /// separate owner-local completion after old leases drain; no metadata ACK
    /// is available until that completion is durable.
    fn readRowPolicyReceiptLocked(self: *DB, expected: row_policy_bundle_mod.Receipt) !row_policy_bundle_mod.Receipt {
        var key_buf: [128]u8 = undefined;
        const key = try expected.key(&key_buf);
        const bytes = self.core.store.get(self.alloc, key) catch return error.InvalidRowPolicyReceipt;
        defer self.alloc.free(bytes);
        const stored = try row_policy_bundle_mod.Receipt.decode(bytes);
        if (!std.meta.eql(expected, stored)) return error.InvalidRowPolicyReceipt;
        return stored;
    }

    fn readRowPolicyApplyResultLocked(self: *DB, expected: row_policy_bundle_mod.Receipt) !?row_policy_bundle_mod.Receipt {
        const receipt = self.readRowPolicyReceiptLocked(expected) catch |err| switch (err) {
            error.InvalidRowPolicyReceipt => null,
            else => return err,
        };
        if (receipt) |stored| return stored;
        const pending = (try self.pendingRowPolicyReceipt()) orelse return error.InvalidRowPolicyReceipt;
        if (!std.meta.eql(pending, expected)) return error.RowPolicyCatalogChanged;
        return null;
    }

    pub const pendingRowPolicyReceipt = local_mutation.pendingRowPolicyReceipt;

    /// A data-Raft entry first commits a fail-closed preparing marker without
    /// waiting in the apply queue. Only after local old-generation cursors and
    /// schema leases drain may this replica commit the serving phase/receipt.
    /// This is an owner-local monotone completion of an exact committed Raft
    /// intent, not a new caller-selected policy program.
    pub const finalizePendingRowPolicyReceiptLocked = local_mutation.finalizePendingRowPolicyReceiptLocked;

    /// Replicas need not be queried by the coordinator to become serve-ready.
    /// The first subsequent local admission opportunistically completes a
    /// committed pending phase; the disabled/active fast path is one atomic
    /// load and never touches the store. Busy old leases simply leave the
    /// owner preparing and the operation continues to fail closed.
    pub const maybeFinalizePendingRowPolicyPublication = local_mutation.maybeFinalizePendingRowPolicyPublication;

    /// Private owner status query. A coordinator reads this only after the
    /// data-Raft proposal has committed; it is never a substitute for the
    /// metadata read-index bundle or an owner ACK. It exposes no user rows.
    pub fn loadRowPolicyReceipt(self: *DB, generation: u64, phase: @import("../../system_catalog/policies.zig").Publication.Phase) !row_policy_bundle_mod.Receipt {
        if (generation == 0) return error.InvalidRowPolicyReceipt;
        var key_buf: [128]u8 = undefined;
        const identity: row_policy_bundle_mod.Receipt = .{
            .table_id = self.core.identity_namespace.table_id,
            .generation = generation,
            .catalog_epoch = 0,
            .phase = phase,
            .applied_term = 0,
            .applied_index = 0,
            .bundle_digest = @splat(0),
            .descriptor_digest = @splat(0),
        };
        const key = try identity.key(&key_buf);
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        const bytes = self.core.store.get(self.alloc, key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (bytes) |encoded| {
            defer self.alloc.free(encoded);
            const stored = try row_policy_bundle_mod.Receipt.decode(encoded);
            if (stored.table_id != identity.table_id or stored.generation != generation or stored.phase != phase)
                return error.InvalidRowPolicyReceipt;
            return stored;
        }
        const pending = (try self.pendingRowPolicyReceipt()) orelse return error.NotFound;
        if (pending.table_id != identity.table_id or pending.generation != generation or pending.phase != phase)
            return error.NotFound;
        return self.finalizePendingRowPolicyReceiptLocked(pending);
    }

    pub fn applyReplicatedRowPolicyPublication(self: *DB, bundle_bytes: []const u8, request: @import("../../system_catalog/policies.zig").InstallRequest, identity: OrderedApplyReceipt) !?row_policy_bundle_mod.Receipt {
        return self.applyRowPolicyPublicationInternal(bundle_bytes, request, identity, null);
    }

    fn finishRowPolicyReplicationCommitLocked(self: *DB, payload: ?[]const u8, outbox_key: ?[]const u8, apply_held: *bool, replication_mutation: *?MutationBarrier.ExclusiveLease) !void {
        const encoded = payload orelse return;
        var ctx = self.batchContext();
        var deferred = ReplicationDeferredCommitGates.begin(replicationTransitionMutexFromContext(&ctx));
        defer deferred.releaseTransition();
        deferred.append(appendReplicationEncodedSchemaMetadataCommitLockedContext(&ctx, encoded) catch {
            self.core.unlockApply();
            apply_held.* = false;
            if (replication_mutation.*) |*lease| lease.release();
            replication_mutation.* = null;
            return error.DurabilityOutcomeUnknown;
        });
        self.core.unlockApply();
        apply_held.* = false;
        if (replication_mutation.*) |*lease| lease.release();
        replication_mutation.* = null;
        deferred.waitForDurabilityAndAuthority(ctx.replication_write_gate) catch return error.DurabilityOutcomeUnknown;
        self.clearDurableReplicationOutbox(outbox_key.?) catch |err| std.log.warn(
            "row policy HA durability acknowledged but outbox cleanup is pending path={s} err={s}",
            .{ self.core.path, @errorName(err) },
        );
    }

    fn applyRowPolicyPublicationInternal(self: *DB, bundle_bytes: []const u8, request: @import("../../system_catalog/policies.zig").InstallRequest, identity: OrderedApplyReceipt, replication_lsn: ?u64) !?row_policy_bundle_mod.Receipt {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        if (identity.term == 0 or identity.index == 0 or (replication_lsn != null and replication_lsn.? == 0)) return error.InvalidRowPolicyPublication;
        if (replication_lsn == null and self.local_execution.replication_async_metadata_mirror == null and
            (self.local_execution.replication_async_batch_mirror != null or self.local_execution.replication_write_gate != null)) return error.ReplicationPublisherUnavailable;
        // The policy cut must be serialized with all in-flight primary writes,
        // including writers that passed their fast outbox preflight already.
        // Production hot-standby mirrors share this capture barrier with every mutation.
        if (replication_lsn == null) if (self.local_execution.replication_async_metadata_mirror) |mirror|
            if (mirror.mutation_barrier == null) return error.ReplicationPublisherUnavailable;
        var replication_mutation: ?MutationBarrier.ExclusiveLease = null;
        defer if (replication_mutation) |*lease| lease.release();
        if (replication_lsn == null) {
            try self.enforceReplicationWriteGate();
            try self.ensureDurableReplicationStartupBarrier();
            try self.preflightReplicationMetadataSyncCommit();
            if (self.local_execution.replication_async_metadata_mirror) |mirror|
                replication_mutation = mirror.mutation_barrier.?.acquireExclusive();
        }
        var schedule_replication_recovery_on_exit = false;
        defer if (schedule_replication_recovery_on_exit) self.scheduleDurableReplicationOutboxRecovery();
        const replication_payload = if (replication_lsn == null and self.local_execution.replication_async_metadata_mirror != null)
            try replication_effects_mod.encodeRowPolicyMetadataMutationAlloc(self.alloc, bundle_bytes, request, identity)
        else
            null;
        defer if (replication_payload) |payload| self.alloc.free(payload);
        const replication_outbox = if (replication_payload) |payload| blk: {
            // This is a WAL search lower bound, not an LSN reservation.
            // Recovery matches the exact payload and owner identity under the
            // transition/log locks even if another publisher appended first.
            const from_lsn = self.local_execution.replication_async_metadata_mirror.?.publisher.nextLsn();
            const encoded = try encodeDurableReplicationOutboxAlloc(self.alloc, from_lsn, payload);
            errdefer self.alloc.free(encoded);
            const key = try durableReplicationOutboxKeyAlloc(self.alloc, .row_policy, from_lsn, self.core.root_generation, payload);
            break :blk .{ .key = key, .value = encoded };
        } else null;
        defer if (replication_outbox) |outbox| {
            self.alloc.free(outbox.key);
            self.alloc.free(outbox.value);
        };
        const schema = self.core.schema orelse return error.RowPolicyCatalogChanged;
        var installed = try row_policy_bundle_mod.Installed.init(self.alloc, bundle_bytes, self.core.identity_namespace.table_id, schema);
        defer installed.deinit();
        if (installed.parsed.value.table_id != request.table_id or
            installed.parsed.value.policy_generation != request.expected_generation or
            installed.parsed.value.catalog_epoch != request.expected_catalog_epoch or
            installed.parsed.value.phase != request.expected_phase)
            return error.RowPolicyCatalogChanged;
        var bundle_digest: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(bundle_bytes, &bundle_digest, .{});
        const expected_receipt: row_policy_bundle_mod.Receipt = .{
            .table_id = request.table_id,
            .generation = request.expected_generation,
            .catalog_epoch = request.expected_catalog_epoch,
            .phase = request.expected_phase,
            .applied_term = identity.term,
            .applied_index = identity.index,
            .bundle_digest = bundle_digest,
            .descriptor_digest = request.expected_descriptor_digest,
        };
        if (try self.orderedMutationAlreadyApplied(identity)) {
            lockApply(self);
            const already = self.readRowPolicyApplyResultLocked(expected_receipt) catch |err| {
                self.core.unlockApply();
                return err;
            };
            self.core.unlockApply();
            if (replication_lsn) |lsn| try self.recordReplicationApplied(lsn);
            return already;
        }
        const phase = installed.parsed.value.phase;
        const pending_phase = phase == .pending_install or phase == .pending_disable;
        try self.lockApplyForPortableRuntime();
        var apply_held = true;
        defer if (apply_held) self.core.unlockApply();
        if (switch (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), identity)) {
            .already_applied => true,
            .apply => false,
        }) {
            const already = try self.readRowPolicyApplyResultLocked(expected_receipt);
            self.core.unlockApply();
            apply_held = false;
            if (replication_lsn) |lsn| try self.recordReplicationApplied(lsn);
            return already;
        }
        {
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            try self.requireOnlineArtifactCatalogMutableLocked(&read);
            try @import("relational_integrity_topology.zig").requireUnfenced(&read);
        }
        const stage_with_serving = pending_phase and self.local_execution.row_policy_gate.currentPhase() == .active;
        if (!stage_with_serving and pending_phase) {
            if (self.local_execution.row_policy_gate.currentPhase() != .preparing)
                try self.local_execution.row_policy_gate.beginPreparing(self.local_execution.row_policy_gate.currentPhase());
        } else if (!pending_phase and self.local_execution.row_policy_gate.currentPhase() == .active and
            (phase == .serving_install or phase == .serving_disable))
        {
            try self.local_execution.row_policy_gate.beginPreparing(.active);
        } else if (!stage_with_serving and self.local_execution.row_policy_gate.currentPhase() != .preparing) {
            return error.RowPolicyCatalogChanged;
        }
        if (try self.pendingRowPolicyReceipt()) |prior| {
            // A lagging follower need not have received a coordinator receipt
            // probe for the earlier phase. A later metadata-authorized Raft
            // phase may supersede that fail-closed intent without admitting
            // readers or claiming the earlier local ACK. The latest phase
            // still waits for all old leases before it can serve.
            const next_phase = installed.parsed.value.phase;
            const follows = if (request.expected_generation > prior.generation)
                next_phase == .pending_install or next_phase == .pending_disable
            else if (request.expected_generation == prior.generation)
                switch (prior.phase) {
                    .pending_install => next_phase == .serving_install,
                    .serving_install => next_phase == .active or next_phase == .pending_disable,
                    .pending_disable => next_phase == .serving_disable,
                    .serving_disable => next_phase == .disabled,
                    .active, .disabled => false,
                }
            else
                false;
            if (!follows or prior.table_id != request.table_id or
                !std.mem.eql(u8, &prior.descriptor_digest, &request.expected_descriptor_digest) or
                identity.index <= prior.applied_index) return error.RowPolicyCatalogChanged;
        }
        const previous = self.core.table_catalog;
        const publication = installed.parsed.value;
        const current_range = self.core.byteRange();
        const actual_descriptor_digest = try (@import("../../system_catalog/policies.zig").OwnerDescriptor{
            .table_id = self.core.identity_namespace.table_id,
            .group_id = request.owner_group_id,
            .shard_id = self.core.identity_namespace.shard_id,
            .range_id = self.core.identity_namespace.range_id,
            .schema_version = publication.schema_version,
            .schema_digest = publication.schema_digest,
            .range_start = current_range.start,
            .range_end = current_range.end,
        }).digest();
        if (!std.mem.eql(u8, &actual_descriptor_digest, &request.expected_descriptor_digest))
            return error.RowPolicyCatalogChanged;
        if (previous.storage_mode != .relational or previous.active_schema_version != publication.schema_version or
            publication.policy_generation < previous.row_policy_generation or
            (publication.policy_generation == previous.row_policy_generation and !stage_with_serving and
                previous.row_policy_phase != .preparing)) return error.RowPolicyCatalogChanged;
        var receipt_bytes: [ordered_apply_receipt_value_len]u8 = undefined;
        const receipt = orderedApplyReceiptWrite(identity, &receipt_bytes);
        if (stage_with_serving) {
            if (self.local_execution.row_policy_gate.currentPhase() != .active or previous.row_policy_phase != .active or
                publication.policy_generation <= previous.row_policy_generation or
                (try self.pendingRowPolicyReceipt()) != null) return error.RowPolicyCatalogChanged;
            const existing_candidate = self.core.store.get(self.alloc, row_policy_bundle_mod.candidate_key) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            defer if (existing_candidate) |value| self.alloc.free(value);
            if (existing_candidate != null) return error.RowPolicyCatalogChanged;
            const encoded_receipt = expected_receipt.encode();
            var receipt_key_buf: [128]u8 = undefined;
            const receipt_key = try expected_receipt.key(&receipt_key_buf);
            var stage_txn = try self.core.store.beginWriteTxn();
            errdefer stage_txn.abort();
            try stage_txn.put(row_policy_bundle_mod.candidate_key, bundle_bytes);
            try stage_txn.put(receipt_key, &encoded_receipt);
            try stage_txn.put(receipt.key, receipt.value);
            var replication_lsn_buf: [replication_applied_lsn_value_len]u8 = undefined;
            if (replication_lsn) |lsn| {
                const marker = replicationAppliedSequenceWrite(lsn, &replication_lsn_buf);
                try stage_txn.put(marker.key, marker.value);
            }
            if (replication_outbox) |outbox| try stage_txn.put(outbox.key, outbox.value);
            if (replication_outbox != null) {
                // Conservative on abort: the next admission performs an
                // apply-fenced empty scan and clears both fast-negative flags.
                self.local_execution.durable_replication_outbox_maybe.store(true, .release);
                self.local_execution.row_policy_replication_outbox_pending.store(true, .release);
            }
            try stage_txn.commit();
            if (replication_outbox != null) {
                schedule_replication_recovery_on_exit = true;
            }
            try self.finishRowPolicyReplicationCommitLocked(replication_payload, if (replication_outbox) |outbox| outbox.key else null, &apply_held, &replication_mutation);
            return expected_receipt;
        }
        if (phase == .serving_install or phase == .serving_disable) {
            const candidate = try self.core.store.get(self.alloc, row_policy_bundle_mod.candidate_key);
            defer self.alloc.free(candidate);
            var parsed_candidate = try row_policy_bundle_mod.Installed.init(self.alloc, candidate, self.core.identity_namespace.table_id, schema);
            defer parsed_candidate.deinit();
            if (parsed_candidate.parsed.value.table_id != publication.table_id or
                parsed_candidate.parsed.value.policy_generation != publication.policy_generation or
                parsed_candidate.parsed.value.catalog_epoch != publication.catalog_epoch or
                !std.mem.eql(u8, &parsed_candidate.parsed.value.schema_digest, &publication.schema_digest) or
                parsed_candidate.parsed.value.phase != (if (phase == .serving_install)
                    @as(@import("../../system_catalog/policies.zig").Publication.Phase, .pending_install)
                else
                    .pending_disable))
                return error.RowPolicyCatalogChanged;
            const candidate_definitions = try std.json.Stringify.valueAlloc(self.alloc, .{ .records = parsed_candidate.parsed.value.records, .settings = parsed_candidate.parsed.value.settings }, .{});
            defer self.alloc.free(candidate_definitions);
            const serving_definitions = try std.json.Stringify.valueAlloc(self.alloc, .{ .records = publication.records, .settings = publication.settings }, .{});
            defer self.alloc.free(serving_definitions);
            if (!std.mem.eql(u8, candidate_definitions, serving_definitions)) return error.RowPolicyCatalogChanged;
        }
        var next = previous;
        next.row_policy_generation = publication.policy_generation;
        next.row_policy_catalog_epoch = publication.catalog_epoch;
        next.row_policy_phase = .preparing;
        next.generation +|= 1;
        const catalog_bytes = next.encode();
        const encoded_pending = expected_receipt.encode();
        var txn = try self.core.store.beginWriteTxn();
        errdefer txn.abort();
        try txn.put(row_policy_bundle_mod.key, bundle_bytes);
        if (pending_phase) try txn.put(row_policy_bundle_mod.candidate_key, bundle_bytes);
        if (phase == .serving_install or phase == .serving_disable) try txn.delete(row_policy_bundle_mod.candidate_key);
        try txn.put(row_policy_bundle_mod.pending_key, &encoded_pending);
        try txn.put(table_catalog_mod.key, &catalog_bytes);
        try txn.put(receipt.key, receipt.value);
        var replication_lsn_buf: [replication_applied_lsn_value_len]u8 = undefined;
        if (replication_lsn) |lsn| {
            const marker = replicationAppliedSequenceWrite(lsn, &replication_lsn_buf);
            try txn.put(marker.key, marker.value);
        }
        if (replication_outbox) |outbox| try txn.put(outbox.key, outbox.value);
        if (replication_outbox != null) {
            self.local_execution.durable_replication_outbox_maybe.store(true, .release);
            self.local_execution.row_policy_replication_outbox_pending.store(true, .release);
        }
        try txn.commit();
        if (replication_outbox != null) {
            schedule_replication_recovery_on_exit = true;
        }
        self.core.table_catalog = next;
        // Keep the old immutable bundle alive for previously admitted bound
        // readers. The receipt probe swaps it only after those leases drain.
        try self.finishRowPolicyReplicationCommitLocked(replication_payload, if (replication_outbox) |outbox| outbox.key else null, &apply_held, &replication_mutation);
        return null;
    }

    /// Removes group-local apply history when this document generation is
    /// materialized for a different Raft history (for example restore or the
    /// destination side of a split). The caller must hold structural ownership
    /// of the generation; ordinary Raft apply must never clear this fence.
    pub fn clearOrderedApplyReceipt(self: *DB) !void {
        lockApply(self);
        defer self.core.unlockApply();
        try self.core.store.putBatch(&.{}, &.{internal_keys.ordered_document_applied_entry_key[0..]});
    }

    fn batchReplicatedApplyWithMarker(self: *DB, req: types.BatchRequest, applied_lsn_marker: ?u64) anyerror!void {
        var apply_req = req;
        apply_req.sync_level = .write;
        try self.batchInternal(apply_req, null, .{
            .validate_range_ownership = false,
            .wait_for_sync_level = false,
            .bypass_replication_write_gate = true,
            .replication_applied_lsn_marker = applied_lsn_marker,
        });
    }

    pub const splitMarkerMatches = local_mutation.splitMarkerMatches;

    /// Runs under the DB apply lock. False means the replicated operation was
    /// already durably applied and must not produce another document replay.
    pub const shouldApplySplitReplicationLocked = local_mutation.shouldApplySplitReplicationLocked;

    fn setSchemaReplicatedApplyWithMarker(
        self: *DB,
        table_schema: schema_mod.TableSchema,
        public_schema_json: ?[]const u8,
        applied_lsn_marker: ?u64,
    ) anyerror!void {
        var prepared_recovery = if (self.transaction_recovery_identity_context != null)
            try db_core.PreparedRecoveryRelationalState.init(
                self.runtime_alloc,
                if (table_schema.storage_mode == .relational) table_schema.relational_columns else null,
                table_schema.version,
            )
        else
            null;
        defer if (prepared_recovery) |*prepared| prepared.deinit();
        const versioned_public_key = try public_table_schema.versionedSchemaKeyAlloc(self.alloc, table_schema.version);
        defer self.alloc.free(versioned_public_key);
        {
            try self.lockApplyForPortableRuntime();
            defer self.core.unlockApply();
            const reconciled_row_count = try self.validateStorageModeCompatibilityLocked(table_schema);
            if (public_schema_json) |schema_json| {
                _ = try self.core.commitSchemaMetadata(table_schema, &.{
                    .{ .key = public_schema_json_key, .value = schema_json },
                    .{ .key = versioned_public_key, .value = schema_json },
                }, &.{}, reconciled_row_count);
            } else {
                _ = try self.core.commitSchemaMetadata(table_schema, &.{}, &.{public_schema_json_key}, reconciled_row_count);
            }
            self.publishRelationalRuntimeModePrepared(if (prepared_recovery) |*prepared| prepared else null);
        }
        self.reconcilePublishedSchemaIndexes(table_schema.version);
        if (applied_lsn_marker) |lsn| try self.recordReplicationApplied(lsn);
    }

    /// The hot-standby journal carries the primary's authenticated child-source cut.
    /// Apply the schema, accepted integrity catalog, source-fence release,
    /// owner receipt and hot-standby LSN in one standby transaction. Generic metadata
    /// replay deliberately cannot publish a changed FK generation.
    fn setPublishedChildSchemaReplicatedApplyWithMarker(self: *DB, table_schema: schema_mod.TableSchema, schema_json: []const u8, published: replication_effects_mod.PublishedChildSchema, lsn: u64) !void {
        if (lsn == 0 or (published.fence.role != .child_generation_source and published.fence.role != .child_generation_dual) or
            !published.fence.namespace.eql(self.core.identity_namespace) or
            published.applied_term == 0 or published.applied_index == 0) return error.InvalidGenerationPublication;
        var schema_digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(schema_json, &schema_digest, .{});
        if (!std.mem.eql(u8, &schema_digest, &published.schema_json_digest)) return error.InvalidGenerationPublication;
        var prepared_recovery = if (self.transaction_recovery_identity_context != null)
            try db_core.PreparedRecoveryRelationalState.init(self.runtime_alloc, if (table_schema.storage_mode == .relational) table_schema.relational_columns else null, table_schema.version)
        else
            null;
        defer if (prepared_recovery) |*prepared| prepared.deinit();
        const versioned_key = try public_table_schema.versionedSchemaKeyAlloc(self.alloc, table_schema.version);
        defer self.alloc.free(versioned_key);
        const admission = @import("relational_integrity_generation_admission.zig");
        const receipt_digest = try admission.sourceInstallDigest(published.fence, published.before_schema_json_digest, published.schema_json_digest, published.before_catalog_digest, published.after_catalog_digest);
        const receipt_bytes = (admission.AppliedReceipt{ .digest = receipt_digest, .term = published.applied_term, .index = published.applied_index }).encode();
        var lsn_buf: [replication_applied_lsn_value_len]u8 = undefined;
        const marker = replicationAppliedSequenceWrite(lsn, &lsn_buf);
        const writes = [_]docstore_mod.KVPair{
            .{ .key = public_schema_json_key, .value = schema_json },
            .{ .key = versioned_key, .value = schema_json },
            .{ .key = admission.source_install_receipt_key, .value = &receipt_bytes },
            marker,
        };
        var prepared = try self.core.prepareSchemaMetadataPublishedChild(table_schema, &writes);
        defer prepared.deinit();
        const after_catalog = (prepared.integrity_catalog orelse return error.IntegrityCatalogChanged).value;
        var after_digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(after_catalog, &after_digest, .{});
        if (!std.mem.eql(u8, &after_digest, &published.after_catalog_digest)) return error.IntegrityCatalogChanged;
        try self.lockApplyForPortableRuntime();
        var apply_held = true;
        errdefer if (apply_held) self.core.unlockApply();
        const current_schema = (try self.core.getStoreValue(self.alloc, public_schema_json_key)) orelse return error.IntegrityCatalogChanged;
        defer self.alloc.free(current_schema);
        var before_schema_digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(current_schema, &before_schema_digest, .{});
        if (!std.mem.eql(u8, &before_schema_digest, &published.before_schema_json_digest)) return error.IntegrityCatalogChanged;
        const current_catalog = (try self.core.getStoreValue(self.alloc, @import("relational_integrity_catalog.zig").key)) orelse return error.IntegrityCatalogChanged;
        defer self.alloc.free(current_catalog);
        var before_digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(current_catalog, &before_digest, .{});
        if (!std.mem.eql(u8, &before_digest, &published.before_catalog_digest)) return error.IntegrityCatalogChanged;
        const row_count = try self.validateStorageModeCompatibilityLocked(table_schema);
        _ = try self.core.commitPreparedSchemaMetadataPublishedChild(&prepared, &writes, &.{}, row_count, published.fence);
        self.publishRelationalRuntimeModePrepared(if (prepared_recovery) |*recovery| recovery else null);
        self.core.unlockApply();
        apply_held = false;
        self.reconcilePublishedSchemaIndexes(table_schema.version);
    }

    /// Apply an already decoded committed batch. The mutation and its replay
    /// receipt remain in the same primary-store transaction.
    pub fn applyReplicatedBatch(self: *DB, mutation: replicated_mutation.Batch, sequence: u64) !void {
        var request = mutation.request;
        var options: BatchExecutionOptions = .{
            .validate_range_ownership = false,
            .wait_for_sync_level = false,
            .bypass_replication_write_gate = true,
            .replication_applied_lsn_marker = sequence,
        };
        switch (mutation.receipt) {
            .native => |position| options.native_topology_position = position,
            .ordered => |entry| options.ordered_apply_receipt = entry,
            .online_source => |index| {
                request.sync_level = .write;
                options.online_source_applied_index = index;
            },
            .none => request.sync_level = .write,
        }
        try self.batchInternal(request, null, options);
    }

    /// Reconcile an ordered source inventory before applying its mutation.
    /// The store owns the admission fence; callers supply an exact receipt.
    pub fn reconcileReplicatedArtifactAdmission(self: *DB, request: types.BatchRequest, entry: OrderedApplyReceipt) !void {
        const command = request.artifact_catalog orelse return;
        const context = try self.preflightArtifactAdmission(request, entry);
        if (!try self.reconcileOrderedArtifactCatalogWithContext(command, entry.index, context)) return error.ArtifactCatalogDrift;
    }

    pub fn applyReplicatedSchema(self: *DB, mutation: replication_effects_mod.SchemaMutation, sequence: u64) !void {
        if (mutation.published_child) |published|
            try self.setPublishedChildSchemaReplicatedApplyWithMarker(mutation.schema, mutation.public_schema_json orelse return error.InvalidGenerationPublication, published, sequence)
        else
            try self.setSchemaReplicatedApplyWithMarker(mutation.schema, mutation.public_schema_json, sequence);
    }

    pub fn applyReplicatedRowPolicy(self: *DB, mutation: replication_effects_mod.RowPolicyMutation, sequence: u64) !void {
        _ = try self.applyRowPolicyPublicationInternal(
            mutation.bundle,
            mutation.request,
            mutation.entry,
            sequence,
        );
    }

    /// Only the latest replay receipt may need local source-pin repair.
    /// Older retries remain allocation-free and do not decode their payloads.
    pub fn recoverReplicatedBatchCut(self: *DB, sequence: u64) !bool {
        if (sequence != try self.replicationAppliedSequence()) return false;
        try self.resumePreparedSourcePin();
        if (try self.restoreStagingStatus(self.alloc)) |stored| {
            var progress = stored;
            defer progress.deinit();
            return progress.value.phase == .validated or progress.value.phase == .published;
        }
        return false;
    }

    pub fn recoverReplicatedRestoreFinish(self: *DB, finish: @FieldType(@import("restore_staging_contract.zig").Control, "finish")) !void {
        try self.prepareAppliedRestoreFinishReplay(.{ .restore_staging = .{ .finish = finish } });
    }

    pub fn applyReplicatedDerivedEffect(self: *DB, change: change_journal_mod.Record, primary: ?replication_effects_mod.primary_effect.View, sequence: u64) !u64 {
        var ctx = self.batchContext();
        return try appendReplicatedDerivedEffectContext(&ctx, change, primary, sequence);
    }

    pub fn replicationAppliedSequence(self: *DB) anyerror!u64 {
        return try readReplicationAppliedSequence(self.alloc, self.core.store);
    }

    pub fn replicationMutationAlreadyApplied(self: *DB, sequence: u64) !bool {
        if (sequence == 0) return false;
        return (try self.replicationAppliedSequence()) >= sequence;
    }

    pub fn recordReplicationApplied(self: *DB, lsn: u64) !void {
        if (lsn == 0) return;
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        const current = try self.replicationAppliedSequence();
        if (current >= lsn) return;
        var value_buf: [replication_applied_lsn_value_len]u8 = undefined;
        const marker = replicationAppliedSequenceWrite(lsn, &value_buf);
        try self.core.store.putBatch(&.{marker}, &.{});
    }

    pub fn applyDocumentArtifactChildRangeBatch(self: *DB, child_batch: DocumentArtifactChildRangeApplyBatch) anyerror!u64 {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        if (child_batch.artifact_writes.len == 0 and
            child_batch.artifact_delete_keys.len == 0 and
            child_batch.documents.len == 0 and
            child_batch.dense_embeddings.len == 0 and
            child_batch.sparse_embeddings.len == 0 and
            child_batch.generated_enrichment_refs.len == 0)
        {
            return 0;
        }

        try self.executor.failIfUnhealthy();

        var snapshot_mutation = self.core.snapshot_admission.acquireMutation();
        defer snapshot_mutation.release();
        // Recheck after lock acquisition to close publication racing the fast
        // preflight performed by the caller.
        try self.lockApplyForPortableRuntime();
        var apply_mutex_held = true;
        errdefer if (apply_mutex_held) self.core.unlockApply();

        var store_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer store_writes.deinit(self.alloc);
        var delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer delete_keys.deinit(self.alloc);
        var owned_store_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_store_keys.items) |key| self.alloc.free(key);
            owned_store_keys.deinit(self.alloc);
        }
        var owned_store_values = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_store_values.items) |value| self.alloc.free(value);
            owned_store_values.deinit(self.alloc);
        }
        var owned_delete_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_delete_keys.items) |key| self.alloc.free(key);
            owned_delete_keys.deinit(self.alloc);
        }
        var changed_artifact_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (changed_artifact_keys.items) |key| self.alloc.free(key);
            changed_artifact_keys.deinit(self.alloc);
        }
        var changed_artifact_key_set = std.StringHashMapUnmanaged(void).empty;
        defer changed_artifact_key_set.deinit(self.alloc);
        for (child_batch.artifact_writes) |write| {
            try store_writes.append(self.alloc, .{
                .key = write.key,
                .value = write.value,
            });
            try appendUniqueOwnedKeyIndexed(self.alloc, &changed_artifact_keys, &changed_artifact_key_set, write.key);
        }
        for (child_batch.artifact_delete_keys) |key| {
            try delete_keys.append(self.alloc, key);
            try appendUniqueOwnedKeyIndexed(self.alloc, &changed_artifact_keys, &changed_artifact_key_set, key);
        }

        // Graph artifact expansion belongs to the durable derived replay. Keep
        // foreground apply proportional to the admitted artifact bytes: the
        // replay record below owns graph materialization, retries, and the
        // sync-level visibility fence after this primary-store commit.
        if (child_batch.artifact_writes.len > 0) {
            try self.core.appendArtifactPresenceMarker(&store_writes);
        }
        try appendAssetArtifactSourceIndexMutations(
            self.alloc,
            &store_writes,
            child_batch.artifact_delete_keys,
            &delete_keys,
            &owned_store_keys,
            &owned_store_values,
            &owned_delete_keys,
        );
        const sequence = self.core.reserveDerivedAppendSequence();
        const derived_seed = derived_types.DerivedBatch{
            .sequence = sequence,
            .documents = child_batch.documents,
            .deleted_keys = child_batch.artifact_delete_keys,
            .changed_artifact_keys = changed_artifact_keys.items,
            .dense_embeddings = child_batch.dense_embeddings,
            .sparse_embeddings = child_batch.sparse_embeddings,
            .generated_enrichment_refs = child_batch.generated_enrichment_refs,
        };
        var derived_batch = try derived_types.cloneBatch(self.alloc, derived_seed);
        defer derived_types.deinitDerivedBatch(self.alloc, &derived_batch);
        derived_batch.sequence = sequence;

        var sync_targets = try collectManagedSyncTargets(self.alloc, self.core.index_manager, derived_batch);
        defer sync_targets.deinit(self.alloc);
        const replay_payload = try encodeChangeRecordPayload(&self.batchContext(), derived_batch, sequence);
        defer self.alloc.free(replay_payload);

        try appendArtifactSourceRevisionWritesFromReplay(
            self.alloc,
            replay_payload,
            sequence,
            &store_writes,
            &owned_store_keys,
            &owned_store_values,
        );

        try appendDenseArtifactCounterMutations(
            self.alloc,
            self.core.store,
            self.core.index_manager,
            &store_writes,
            delete_keys.items,
            &owned_store_keys,
            &owned_store_values,
        );
        var backlog_admission = try self.executor.admitBacklogBytes(@intCast(replay_payload.len));
        defer backlog_admission.cancel();
        try self.core.store.putBatchWithReplay(
            self.backend_runtime.io(),
            store_writes.items,
            delete_keys.items,
            .{
                .sequence = sequence,
                .payload = replay_payload,
            },
        );
        self.mirrorReplicationReplayPayloadBestEffort(replay_payload);
        if (shouldAppendSplitDelta(self)) {
            try self.core.appendSplitDelta(currentTimeNs(), store_writes.items, delete_keys.items);
        }

        self.executor.commitBacklogAdmission(sequence, &backlog_admission);
        self.core.unlockApply();
        apply_mutex_held = false;
        snapshot_mutation.release();
        notifyQueryVisibilityTargetAdvancedScoped(
            self.async_context,
            sequence,
            sync_targets.target_identities,
            sync_targets.target_scope_known,
        );

        var pressure_ctx = self.batchContext();
        try self.markPrecomputedEnrichmentAppliedForSync(child_batch.sync_level, sequence);
        try applyDerivedBacklogPressureContext(&pressure_ctx, sequence, child_batch.sync_level, sync_targets);
        if (self.executor.hasWorkers()) {
            notifyExecutorForSyncLevelWithDenseBulkDeferral(self.async_context, self.executor, child_batch.sync_level, sequence, sync_targets);
            try self.waitForSyncLevel(child_batch.sync_level, sequence, sync_targets);
        } else {
            if (syncLevelRequiresDerivedVisibility(child_batch.sync_level)) {
                if (child_batch.sync_level == .full_text) {
                    try applyDerivedBatchTargetsProfiled(self, derived_batch, sync_targets.full_text_indexes, null);
                } else {
                    try applyDerivedBatchProfiled(self, derived_batch, null);
                }
            }
            try self.waitForSyncLevel(child_batch.sync_level, sequence, sync_targets);
        }
        if (self.enrichment_runtime) |runtime| runtime.notifySequence(sequence);
        self.notifyResolverReplayRuntimes(sequence);
        return sequence;
    }

    /// Prepared relational work is optimistic: schema or index publication may
    /// invalidate it before commit. Retry the complete preparation outside the
    /// apply lock instead of falling back to parse/extract/encode while holding
    /// the global serialization fence. The bound prevents catalog churn from
    /// turning one request into unbounded CPU/provider work.
    fn batchInternal(self: *DB, req: types.BatchRequest, profile: ?*BatchProfile, opts: BatchExecutionOptions) anyerror!void {
        try types.validateGraphEndpointCleanupCommand(req);
        var lake_schema_view = self.core.acquireSchemaView();
        defer if (lake_schema_view) |*view| view.release();
        if (lake_schema_view) |view| if (view.tableSchema().external_base_source != null and
            (req.writes.len != 0 or req.deletes.len != 0 or req.transforms.len != 0 or req.graph_writes.len != 0 or req.graph_deletes.len != 0)) return error.ExternalLakeReadOnly;
        if (self.local_execution.initial_child_hidden.load(.acquire) and
            (req.relational_topology == null or
                (req.relational_topology.?.action != .provision_initial_child and
                    req.relational_topology.?.action != .release_initial_child and
                    req.relational_topology.?.action != .cancel_initial_child)))
            return error.InitialChildNotPublished;
        // Publication has a dedicated deterministic Raft apply path; it must
        // never be silently treated as an ordinary empty batch.
        if (req.row_policy_publication != null or req.row_policy_install_bundle.len != 0)
            return error.InvalidBatchRequest;
        // Follower/recovery Raft replay applies an already-authorized log
        // command. Every local direct mutation must retain an admission lease
        // through commit so a policy activation cannot cross it.
        var verified_principal: ?std.json.Parsed(row_policy_authority_mod.Payload) = null;
        defer if (verified_principal) |*principal| principal.deinit();
        var row_policy_lease: ?row_policy_gate_mod.Gate.Lease = null;
        const trusted_replay = opts.ordered_apply_receipt != null or opts.native_initial_child_entry != null or opts.replication_applied_lsn_marker != null;
        // Strict private-command validation above confines this exemption to
        // derived inline-edge/job maintenance. It cannot mutate user rows,
        // and must progress while a policy publication is preparing or active.
        const graph_cleanup_maintenance = req.graph_endpoint_cleanup;
        if (!trusted_replay and !graph_cleanup_maintenance) try self.maybeFinalizePendingRowPolicyPublication();
        if (req.row_policy_principal_proof.len != 0) {
            if (req.row_policy_admitted_at_seconds <= 0 or req.row_policy_database.len == 0 or
                req.row_policy_publication != null or req.relational_generation_gc != null or
                req.online_source != null or req.restore_staging != null)
                return error.RowPolicyAuthenticationRequired;
            const now_seconds: i64 = @intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s));
            verified_principal = try self.verifyRowPolicyPrincipal(self.alloc, req.row_policy_principal_proof, req.row_policy_database, .write, if (trusted_replay) req.row_policy_admitted_at_seconds else now_seconds);
            row_policy_lease = if (trusted_replay)
                try self.local_execution.row_policy_gate.enterReplicatedPrincipal(&verified_principal.?.value)
            else
                try self.local_execution.row_policy_gate.enterVerifiedPrincipal(&verified_principal.?.value, now_seconds);
        } else if (req.row_policy_database.len != 0 or req.row_policy_admitted_at_seconds != 0) {
            return error.RowPolicyAuthenticationRequired;
        } else if (!trusted_replay and !graph_cleanup_maintenance and req.relational_generation_gc == null and opts.transaction_resolution == null) {
            row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        } else if (self.local_execution.row_policy_gate.currentPhase() != .disabled and
            (req.writes.len != 0 or req.deletes.len != 0 or req.transforms.len != 0 or
                req.graph_writes.len != 0 or req.graph_deletes.len != 0) and
            opts.transaction_resolution == null and req.relational_generation_gc == null and !graph_cleanup_maintenance)
        {
            return error.RowPolicyAuthenticationRequired;
        }
        defer if (row_policy_lease) |*lease| lease.release();
        var policy_opts = opts;
        if (verified_principal) |*principal| policy_opts.row_policy_principal = &principal.value;
        if (row_policy_lease) |*lease| policy_opts.row_policy_lease = lease;
        // A topology rewrite cannot inherit an active policy by copying row
        // bytes: the new owner would lack an authenticated, descriptor-bound
        // policy publication. Until coordinated bundle handoff exists, reject
        // every replicated split/merge/restore lifecycle while a publication
        // is preparing or active. This check also covers trusted Raft replay,
        // which deliberately bypasses ordinary user-row admission.
        if (self.local_execution.row_policy_gate.currentPhase() != .disabled and !graph_cleanup_maintenance and
            (req.online_source != null or req.restore_staging != null or
                req.relational_topology != null or req.split_transition != null or
                req.split_checkpoint != null or req.split_replication != null or
                req.merge_source_transition != null or req.merge_checkpoint != null or
                req.merge_replication != null or req.merge_page != null or
                req.merge_artifacts.len != 0)) return error.RowPolicyTopologyUnsupported;
        try @import("../range_protection.zig").validateRequest(req);
        try @import("merge_page_contract.zig").validateRequest(req);
        try @import("merge_proof_adoption.zig").validateRequest(req);
        try @import("online_source_contract.zig").validateRequest(req);
        try @import("artifact_inventory.zig").validateRequest(req);
        try @import("artifact_publication_transport.zig").validateBatchRequest(req);
        if (req.merge_proof_adoption != null) return self.applyMergeProofAdoptionBatch(req, opts);
        if (req.artifact_catalog != null and req.online_source == null and req.merge_checkpoint == null) return self.applyArtifactCatalogBatch(req, opts);
        if (req.artifact_publication != null) return self.applyArtifactPublicationBatch(req, opts);
        if (req.artifact_publication_transport != null) return self.applyArtifactPublicationTransportBatch(req, opts);
        if (req.online_source != null) {
            if (comptime builtin.os.tag == .freestanding) {
                return error.UnsupportedPlatform;
            } else {
                return self.applyOnlineSourceBatch(req, opts);
            }
        }
        if (self.core.store.retained_effects_cache.load(.acquire) != 1) {
            var source_read = try self.core.store.beginReadTxn();
            defer source_read.abort();
            var source_namespace: [24]u8 = undefined;
            doc_identity.encodeNamespace(&source_namespace, self.core.identity_namespace);
            try @import("../source_pin_state.zig").requireNoPrepared(&source_read, source_namespace);
        }
        if (req.relational_index_maintenance != null and (req.restore_staging != null or req.relational_topology != null)) return error.InvalidBatchRequest;
        if (req.restore_staging) |control| {
            if (req.transaction != null or req.relational_topology != null or (req.deletes.len != 0 and control != .rewrite_page) or req.transforms.len != 0 or req.graph_writes.len != 0 or req.graph_deletes.len != 0 or req.integrity.len != 0 or req.integrity_commands.len != 0 or req.relational_activation != null or req.relational_retirement != null or req.predicates.len != 0 or req.relational_repair or req.split_checkpoint != null or req.split_replication != null or req.split_transition != null or req.merge_source_transition != null or req.merge_checkpoint != null or req.merge_replication != null or req.merge_artifacts.len != 0) return error.InvalidRestoreStagingCommand;
            switch (control) {
                .begin => |scope| {
                    if (req.writes.len != 0) return error.InvalidRestoreStagingCommand;
                    _ = scope;
                    if (comptime builtin.os.tag == .freestanding) {
                        return error.UnsupportedPlatform;
                    } else {
                        return self.applyRestoreStagingControl(req, opts);
                    }
                },
                .finish => |finish| {
                    if (req.writes.len != 0) return error.InvalidRestoreStagingCommand;
                    _ = finish;
                    if (comptime builtin.os.tag == .freestanding) {
                        return error.UnsupportedPlatform;
                    } else {
                        return self.applyRestoreStagingControl(req, opts);
                    }
                },
                .install_generation_admissions => |install| {
                    if (req.writes.len != 0 or req.deletes.len != 0) return error.InvalidRestoreStagingCommand;
                    try install.validate();
                    return self.applyRestoreStagingControl(req, opts);
                },
                .import_page, .rewrite_page => |page| {
                    if (req.writes.len +| req.deletes.len > 128 or page.timestamps.len != req.writes.len or page.next.len > 8 * 1024 * 1024) return error.InvalidRestoreStagingCommand;
                    if (page.artifacts.len > (if (page.source_generation_proof_page) @as(usize, 1024) else 128) or
                        @as(u8, @intFromBool(page.artifact_page)) + @as(u8, @intFromBool(page.projection_page)) + @as(u8, @intFromBool(page.source_generation_proof_page)) > 1 or
                        ((page.artifact_page or page.projection_page or page.source_generation_proof_page) and (control != .import_page or req.writes.len != 0 or req.deletes.len != 0)) or
                        (!page.artifact_page and !page.projection_page and !page.source_generation_proof_page and page.artifacts.len != 0)) return error.InvalidRestoreStagingCommand;
                    var timestamps: std.StringHashMapUnmanaged(u64) = .empty;
                    defer timestamps.deinit(self.alloc);
                    var input_bytes: usize = 0;
                    var previous_artifact: ?[]const u8 = null;
                    for (page.artifacts) |artifact| {
                        if (page.source_generation_proof_page) {
                            const portable = @import("../portable_backup.zig");
                            const accepted = @import("relational_integrity_generation_admission.zig");
                            if (!std.mem.startsWith(u8, artifact.key, portable.source_generation_admission_prefix) or
                                artifact.key.len != portable.source_generation_admission_prefix.len + 32) return error.InvalidRestoreStagingCommand;
                            const decoded = accepted.Scope.decode(artifact.value) catch return error.InvalidRestoreStagingCommand;
                            if (decoded.phase != .active) return error.InvalidRestoreStagingCommand;
                            const key = try accepted.scopeKey(decoded.child_table_name, decoded.constraint_name);
                            if (!std.mem.eql(u8, artifact.key[portable.source_generation_admission_prefix.len..], key[accepted.prefix.len..]))
                                return error.InvalidRestoreStagingCommand;
                        } else if (!(if (page.projection_page) isMergeArtifactKey(artifact.key) else isRestoreArtifactKey(artifact.key))) return error.InvalidRestoreStagingCommand;
                        if (previous_artifact) |previous| if (std.mem.order(u8, previous, artifact.key) != .lt) return error.InvalidRestoreStagingCommand;
                        previous_artifact = artifact.key;
                        if (!page.source_generation_proof_page) {
                            const owner = (try internal_keys.decodeDocumentComponentAlloc(self.alloc, artifact.key)) orelse return error.InvalidRestoreStagingCommand;
                            defer self.alloc.free(owner);
                            if (!self.core.byteRange().contains(owner)) return error.KeyOutOfRange;
                        }
                        input_bytes = std.math.add(usize, input_bytes, artifact.key.len +| artifact.value.len) catch return error.TransactionTooLarge;
                        if (input_bytes > 16 * 1024 * 1024) return error.TransactionTooLarge;
                    }
                    for (page.timestamps, req.writes) |timestamp, row| {
                        if (timestamp.timestamp == 0 or !std.mem.eql(u8, timestamp.key, row.key)) return error.InvalidRestoreStagingCommand;
                        input_bytes = std.math.add(usize, input_bytes, row.key.len +| row.value.len) catch return error.TransactionTooLarge;
                        if (input_bytes > 16 * 1024 * 1024) return error.TransactionTooLarge;
                        const entry = try timestamps.getOrPut(self.alloc, timestamp.key);
                        if (entry.found_existing) return error.InvalidRestoreStagingCommand;
                        entry.value_ptr.* = timestamp.timestamp;
                    }
                    for (req.deletes) |key| {
                        input_bytes = std.math.add(usize, input_bytes, key.len) catch return error.TransactionTooLarge;
                        if (input_bytes > 16 * 1024 * 1024) return error.TransactionTooLarge;
                        const entry = try timestamps.getOrPut(self.alloc, key);
                        if (entry.found_existing) return error.InvalidRestoreStagingCommand;
                        entry.value_ptr.* = 0;
                    }
                    var apply_req = req;
                    apply_req.restore_staging = null;
                    apply_req.sync_level = if (page.artifact_page or page.source_generation_proof_page) .write else .full_index;
                    var apply_opts = opts;
                    apply_opts.wait_for_sync_level = !page.artifact_page and !page.source_generation_proof_page;
                    apply_opts.restore_staging = .{ .expected = page.expected, .next = page.next, .scope = page.scope, .rewrite = control == .rewrite_page, .source_effects = page.source_effects, .artifact_page = page.artifact_page, .projection_page = page.projection_page, .source_generation_proof_page = page.source_generation_proof_page };
                    apply_opts.restore_timestamps = &timestamps;
                    apply_opts.restore_replication_request = req;
                    apply_opts.restore_artifacts = page.artifacts;
                    const extra = try self.alloc.alloc(docstore_mod.KVPair, opts.extra_store_writes.len + 1 + @intFromBool(page.artifacts.len != 0 and !page.source_generation_proof_page));
                    defer self.alloc.free(extra);
                    @memcpy(extra[0..opts.extra_store_writes.len], opts.extra_store_writes);
                    extra[opts.extra_store_writes.len] = .{ .key = @import("restore_staging.zig").key, .value = page.next };
                    if (page.artifacts.len != 0 and !page.source_generation_proof_page) {
                        self.core.artifact_cleanup_maybe.store(true, .release);
                        extra[extra.len - 1] = .{ .key = internal_keys.artifact_presence_key[0..], .value = "1" };
                    }
                    apply_opts.extra_store_writes = extra;
                    return self.batchInternal(apply_req, profile, apply_opts);
                },
            }
        }
        if (req.relational_generation_gc != null) return self.applyGenerationGcBatch(req, opts);
        if (req.relational_topology != null or req.split_transition != null) {
            return self.applyRelationalTopologyBatch(req, opts);
        }
        // One budget spans transforms, provider memoization, optimistic retries
        // and commit-side consumption. No request-owned allocation may outlive
        // this context, including generated results moved into derived batches.
        var preparation: RequestPreparationContext = undefined;
        preparation.init(self);
        defer preparation.deinit();
        var proof_witness_arena = std.heap.ArenaAllocator.init(preparation.guard.allocator());
        defer proof_witness_arena.deinit();
        var page_timestamps: std.StringHashMapUnmanaged(u64) = .empty;
        defer page_timestamps.deinit(self.alloc);
        var apply_opts = opts;
        var apply_req = req;
        var chunk_prepared: ?@import("merge_page_chunks.zig").Prepared = null;
        defer if (chunk_prepared) |*prepared| prepared.deinit();
        if (req.merge_page) |page| if (page.chunk != null) {
            chunk_prepared = self.prepareMergePageChunk(preparation.guard.allocator(), req, opts.visibility_cancellation) catch |err| return preparation.mapError(err);
            const prepared = &chunk_prepared.?;
            apply_req = prepared.request;
            apply_opts.merge_chunk_expected_progress = prepared.expected_progress;
            const extra_writes = prepared.arena.allocator().alloc(docstore_mod.KVPair, opts.extra_store_writes.len + prepared.writes.len) catch |err| return preparation.mapError(err);
            @memcpy(extra_writes[0..opts.extra_store_writes.len], opts.extra_store_writes);
            @memcpy(extra_writes[opts.extra_store_writes.len..], prepared.writes);
            apply_opts.extra_store_writes = extra_writes;
            const extra_deletes = prepared.arena.allocator().alloc([]const u8, opts.extra_store_deletes.len + prepared.deletes.len) catch |err| return preparation.mapError(err);
            @memcpy(extra_deletes[0..opts.extra_store_deletes.len], opts.extra_store_deletes);
            @memcpy(extra_deletes[opts.extra_store_deletes.len..], prepared.deletes);
            apply_opts.extra_store_deletes = extra_deletes;
            // Standby receives the same bounded command, never the assembled
            // row re-escaped into an oversized replication JSON envelope.
            apply_opts.restore_replication_request = req;
        };
        if (apply_req.merge_page) |page| if (page.provenance_effects.len != 0) {
            try @import("merge_page_contract.zig").validateRequest(apply_req);
            const proof_batch = @import("source_proof_batch.zig");
            const scratch = preparation.guard.allocator();
            const owned = proof_witness_arena.allocator();
            const witness_writes = try owned.alloc(docstore_mod.KVPair, apply_opts.extra_store_writes.len + page.provenance_effects.len);
            @memcpy(witness_writes[0..apply_opts.extra_store_writes.len], apply_opts.extra_store_writes);
            var namespace: @import("artifact_publication.zig").Namespace = undefined;
            doc_identity.encodeNamespace(&namespace, page.source.namespace);
            for (page.provenance_effects, 0..) |effect, index| {
                const digest = try proof_batch.transferDigest(namespace, page.source.pin_digest, effect.key);
                var decoded = try proof_batch.decodeValue(scratch, namespace, digest, effect.value orelse return error.InvalidMergePage);
                const witness_key = proof_batch.witnessKey(namespace, page.source.pin_digest, digest);
                witness_writes[apply_opts.extra_store_writes.len + index] = .{
                    .key = try owned.dupe(u8, &witness_key),
                    .value = try owned.dupe(u8, &decoded.record_digest),
                };
                decoded.deinit();
            }
            apply_opts.extra_store_writes = witness_writes;
        };
        if (apply_req.merge_page) |page| if (page.phase == .rows or page.phase == .tail) {
            if (page.chunk) |chunk| {
                if (apply_req.writes.len != 0) try page_timestamps.put(self.alloc, chunk.row_key, chunk.timestamp);
            } else for (apply_req.writes, page.timestamps) |row, timestamp| try page_timestamps.put(self.alloc, row.key, timestamp);
            apply_opts.restore_timestamps = &page_timestamps;
            apply_opts.preserve_logical_values = true;
        };
        apply_opts.row_policy_principal = policy_opts.row_policy_principal;
        apply_opts.row_policy_lease = policy_opts.row_policy_lease;
        self.batchInternalWithPreparationAllocator(apply_req, profile, apply_opts, &preparation.guard) catch |err|
            return preparation.mapError(err);
    }

    pub const batchInternalWithPreparationAllocator = local_mutation.batchInternalWithPreparationAllocator;

    pub const batchInternalPrepared = local_mutation.batchInternalPrepared;

    /// Exact source replays may omit derived journal work while each existing
    /// artifact-backed dense generation is nonempty. A partial-generation
    /// mismatch belongs to durable repair; replaying unchanged source into it
    /// amplifies a small maintenance discrepancy into destructive HBC churn.
    /// A reset or a newly admitted empty generation still needs the replay so
    /// cached artifacts can populate it without re-embedding.
    pub const unchangedDerivedReplayTargetsServiceable = local_mutation.unchangedDerivedReplayTargetsServiceable;

    pub const storedDocumentValuesEqual = local_mutation.storedDocumentValuesEqual;

    pub const thinReplayInputsHaveDerivedWork = local_mutation.thinReplayInputsHaveDerivedWork;

    /// Inject (or clear) the cross-shard entity-resolution candidate source on
    /// an already-open DB. The serving layer (managed write cache) calls this
    /// right after a DB is opened, since managed DBs open lazily and cannot
    /// thread the source through `OpenOptions`. No-op when this DB has no
    /// resolution runtime (e.g. read-only / status opens).
    pub fn setResolutionCandidateSource(self: *DB, src: ?resolution_runtime_mod.CandidateSource) void {
        self.resolution_candidate_source = src;
        if (self.resolution_runtime) |runtime| runtime.setCandidateSource(src);
    }

    /// Inject (or clear) the cross-shard entity sink on an already-open DB. The
    /// serving layer (managed write cache) calls this right after a DB is opened,
    /// since managed DBs open lazily and cannot thread the sink through
    /// `OpenOptions`. No-op when this DB has no promotion runtime.
    pub fn setEntitySink(self: *DB, sink: ?promotion_runtime_mod.EntitySink) void {
        self.entity_sink = sink;
        if (self.promotion_runtime) |runtime| runtime.setSink(sink);
    }

    /// Inject (or clear) the source-shard promotion owner on an already-open DB.
    /// Serving-layer managed DBs use this to keep follower raft apply from
    /// turning replay into public entity-table writes.
    pub fn setPromotionOwner(self: *DB, owner: ?promotion_runtime_mod.PromotionOwner) void {
        self.promotion_owner = owner;
        if (self.promotion_runtime) |runtime| runtime.setOwner(owner);
    }

    pub const failIfIdentityOrdinalExhaustedForNewUpserts = local_mutation.failIfIdentityOrdinalExhaustedForNewUpserts;

    fn configureBulkIngestIdentityAllNewLocked(self: *DB) !void {
        self.clearBulkIngestIdentityAllNewLocked();
        if (!try self.primaryUserNamespaceIsEmptyLocked()) return;
        if (try doc_identity.loadAllNewTrustedStateForNamespace(self.core.store, self.core.identity_namespace)) |state| {
            self.bulk_identity.trusted = state;
            self.core.identity_visibility.summary = state.visibility_summary;
            self.clearLiveDocSetCache();
            self.clearNonVisibleDocSetCache();
            self.bulk_identity.enabled = true;
        }
    }

    pub const clearBulkIngestIdentityAllNewLocked = local_mutation.clearBulkIngestIdentityAllNewLocked;

    pub const clearActiveIndexRepairsLocked = local_mutation.clearActiveIndexRepairsLocked;

    fn scheduleInactiveRepairShadowCleanup(self: *DB) void {
        scheduleInactiveRepairShadowCleanupContext(
            self.core.index_manager,
            self.backend_runtime.durable_jobs,
            self.repair_cleanup_owner_id,
        );
    }

    fn scheduleInactiveRepairShadowCleanupContext(
        manager: *index_manager_mod.IndexManager,
        lane: background_runtime_mod.DurableJobLane,
        owner_id: u64,
    ) void {
        @import("cleanup_job_owner.zig").schedule(.{
            .ptr = manager,
            .state = &manager.repair_cleanup_state,
            .lane = lane,
            .owner_id = owner_id,
            .io = manager.checkpointIo(),
            .advance = advanceRepairShadowCleanup,
            .name = "repair-generation",
        });
    }

    fn advanceRepairShadowCleanup(ptr: *anyopaque) !@import("cleanup_job_owner.zig").Advance {
        const manager: *index_manager_mod.IndexManager = @ptrCast(@alignCast(ptr));
        return if (try manager.cleanupInactiveRepairShadowRootsPage()) .progressed else .idle;
    }

    var test_enrichment_restart_failures_remaining: std.atomic.Value(u32) = .init(0);
    var test_enrichment_reconfigure_after_detached_hook: ?*const fn (*DB) anyerror!void = null;

    fn startEnrichmentRuntimeForLifecycle(runtime: *enrichment_runtime_mod.EnrichmentRuntime) !void {
        if (builtin.is_test) {
            var remaining = test_enrichment_restart_failures_remaining.load(.acquire);
            while (remaining != 0) {
                if (test_enrichment_restart_failures_remaining.cmpxchgWeak(
                    remaining,
                    remaining - 1,
                    .acq_rel,
                    .acquire,
                )) |actual| {
                    remaining = actual;
                    continue;
                }
                return error.TestTransientEnrichmentRestart;
            }
        }
        try runtime.start();
    }

    fn scheduleEnrichmentRestartContext(ctx: *AsyncContext, lane: background_runtime_mod.DurableJobLane, owner_id: u64) void {
        ctx.enrichment_restart_owner.schedule(.{ .ptr = ctx, .lane = lane, .owner_id = owner_id, .io = ctx.io, .closing = &ctx.background_closing, .wanted = enrichmentRestartWanted, .attempt = attemptEnrichmentRestart, .name = "enrichment", .unavailable = error.EnrichmentRuntimeUnavailable });
    }
    fn enrichmentRestartWanted(ptr: *anyopaque) bool {
        const ctx: *AsyncContext = @ptrCast(@alignCast(ptr));
        return ctx.enrichment_desired_running.load(.acquire);
    }
    fn attemptEnrichmentRestart(ptr: *anyopaque) !bool {
        const ctx: *AsyncContext = @ptrCast(@alignCast(ptr));
        lockAtomicWithBackoff(&ctx.enrichment_lifecycle_mutex);
        const runtime = ctx.enrichment_runtime;
        const should_start = runtime != null and ctx.enrichment_desired_running.load(.acquire) and !ctx.background_closing.load(.acquire) and !runtime.?.isStarted();
        const start_error: ?anyerror = if (should_start) blk: {
            startEnrichmentRuntimeForLifecycle(runtime.?) catch |err| break :blk err;
            break :blk null;
        } else null;
        const started = runtime == null or runtime.?.isStarted();
        ctx.enrichment_lifecycle_mutex.unlock();
        if (started) {
            notifyQueryVisibilityHook(ctx, .status);
            return true;
        }
        if (start_error) |err| return err;
        return false;
    }
    const MaintenanceRuntimeKind = enum { text_merge, sparse_compaction };
    fn restartWanted(_: *anyopaque) bool {
        return true;
    }
    fn attemptTextMergeRestart(ptr: *anyopaque) !bool {
        const ctx: *AsyncContext = @ptrCast(@alignCast(ptr));
        return if (ctx.text_merge_runtime) |runtime| try runtime.ensureRunning() else true;
    }
    fn attemptSparseCompactionRestart(ptr: *anyopaque) !bool {
        const ctx: *AsyncContext = @ptrCast(@alignCast(ptr));
        return if (ctx.sparse_compaction_runtime) |runtime| try runtime.ensureRunning() else true;
    }
    fn scheduleMaintenanceRestartContext(ctx: *AsyncContext, lane: background_runtime_mod.DurableJobLane, owner_id: u64, kind: MaintenanceRuntimeKind) void {
        const owner = switch (kind) {
            .text_merge => &ctx.text_merge_restart_owner,
            .sparse_compaction => &ctx.sparse_compaction_restart_owner,
        };
        owner.schedule(.{ .ptr = ctx, .lane = lane, .owner_id = owner_id, .io = ctx.io, .closing = &ctx.background_closing, .wanted = restartWanted, .attempt = switch (kind) {
            .text_merge => attemptTextMergeRestart,
            .sparse_compaction => attemptSparseCompactionRestart,
        }, .name = @tagName(kind) });
    }

    fn quiesceEnrichmentForStructuralMutation(self: *DB) bool {
        const desired = self.async_context.enrichment_desired_running.swap(false, .acq_rel);
        lockAtomicWithBackoff(&self.async_context.enrichment_lifecycle_mutex);
        defer self.async_context.enrichment_lifecycle_mutex.unlock();
        const runtime = self.async_context.enrichment_runtime orelse return desired;
        const started = runtime.isStarted();
        if (started) runtime.stop();
        return desired or started;
    }

    fn quiesceTextMergeForStructuralMutation(self: *DB) bool {
        const runtime = self.text_merge_runtime orelse return false;
        return runtime.pause();
    }

    fn quiesceSparseCompactionForStructuralMutation(self: *DB) bool {
        const runtime = self.sparse_compaction_runtime orelse return false;
        return runtime.pause();
    }

    fn restartTextMergeAfterStructuralMutation(self: *DB, operation: []const u8, index_name: []const u8) void {
        const runtime = self.text_merge_runtime orelse return;
        runtime.resumeAfterPause() catch |err| {
            // Index catalog durability is already decided at this point.
            // Queries and foreground indexing remain available; surface the
            // maintenance degradation without misreporting the mutation.
            std.log.warn("failed to restart text merge runtime after {s} index={s} err={s}", .{ operation, index_name, @errorName(err) });
            scheduleMaintenanceRestartContext(
                self.async_context,
                self.backend_runtime.durable_jobs,
                self.repair_cleanup_owner_id,
                .text_merge,
            );
        };
    }

    fn restartSparseCompactionAfterStructuralMutation(self: *DB, operation: []const u8, index_name: []const u8) void {
        const runtime = self.sparse_compaction_runtime orelse return;
        runtime.resumeAfterPause() catch |err| {
            std.log.warn("failed to restart sparse compaction runtime after {s} index={s} err={s}", .{ operation, index_name, @errorName(err) });
            scheduleMaintenanceRestartContext(
                self.async_context,
                self.backend_runtime.durable_jobs,
                self.repair_cleanup_owner_id,
                .sparse_compaction,
            );
        };
    }

    const IndexStructuralMutationGuard = struct {
        db: *DB,
        snapshot_mutation: snapshot_admission_mod.SnapshotAdmission.MutationLease,
        operation: []const u8,
        index_name: []const u8,
        restart_text_merge: bool,
        restart_sparse_compaction: bool,
        catalog_barrier_held: bool = false,
        active: bool = true,

        fn acquireCatalogBarrierUntil(self: *@This(), deadline_ns: u64) bool {
            std.debug.assert(self.active and !self.catalog_barrier_held);
            if (!self.db.beginIndexCatalogBarrierUntil(deadline_ns)) return false;
            self.catalog_barrier_held = true;
            return true;
        }

        fn releaseCatalogBarrier(self: *@This()) void {
            if (!self.catalog_barrier_held) return;
            self.db.endIndexCatalogBarrier();
            self.catalog_barrier_held = false;
        }

        fn release(self: *@This()) void {
            if (!self.active) return;
            // The catalog is stable once the caller releases apply exclusive;
            // let lock-free dense searches resume before runtime startup work.
            self.releaseCatalogBarrier();
            // Restart while serialization is still held: another structural
            // mutation must not stop a runtime between this restart and the
            // corresponding unlock.
            if (self.restart_sparse_compaction) {
                self.db.restartSparseCompactionAfterStructuralMutation(self.operation, self.index_name);
            }
            if (self.restart_text_merge) {
                self.db.restartTextMergeAfterStructuralMutation(self.operation, self.index_name);
            }
            self.db.local_execution.index_structural_mutation_mutex.unlock();
            self.snapshot_mutation.release();
            self.active = false;
        }

        pub fn deinit(self: *@This()) void {
            self.release();
        }
    };

    /// Lightweight serialization for repair-control commits which bind to the
    /// current catalog incarnation but do not publish or retire runtime index
    /// pointers. Full structural mutations take the same mutex and additionally
    /// drain background pointer borrowers; discovery needs only the shared
    /// incarnation boundary and therefore does not stop merge/compaction work.
    const IndexCatalogIncarnationGuard = struct {
        db: *DB,
        active: bool = true,

        fn release(self: *@This()) void {
            if (!self.active) return;
            self.db.local_execution.index_structural_mutation_mutex.unlock();
            self.active = false;
        }

        pub fn deinit(self: *@This()) void {
            self.release();
        }
    };

    fn beginIndexCatalogIncarnationGuard(self: *DB) IndexCatalogIncarnationGuard {
        lockAtomicWithBackoff(&self.local_execution.index_structural_mutation_mutex);
        return .{ .db = self };
    }

    const QuarantineIndexPublicationFence = struct {
        db: *DB,
        structural_guard: ?IndexStructuralMutationGuard = null,
        apply_locked: bool = false,

        fn iface(self: *@This()) index_manager_mod.IndexManager.CatalogPublicationFence {
            return .{
                .ptr = self,
                .lock_fn = lockOpaque,
                .unlock_fn = unlockOpaque,
            };
        }

        fn lockOpaque(ptr: *anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            std.debug.assert(self.structural_guard == null and !self.apply_locked);
            self.structural_guard = self.db.beginIndexStructuralMutation("quarantined index publication", "*");
            if (builtin.is_test) test_quarantine_publication_fence_entered.store(true, .release);
            lockApply(self.db);
            self.apply_locked = true;
        }

        fn unlockOpaque(ptr: *anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            std.debug.assert(self.apply_locked and self.structural_guard != null);
            self.db.core.unlockApply();
            self.apply_locked = false;
            self.structural_guard.?.release();
            self.structural_guard = null;
        }
    };

    /// Serializes every live index-catalog publication and drains background
    /// tasks that borrow inline index generations. Callers must acquire this
    /// before the DB apply lock; active tasks retire under that lock while the
    /// guard waits for their workers to stop.
    fn beginIndexStructuralMutation(
        self: *DB,
        operation: []const u8,
        index_name: []const u8,
    ) IndexStructuralMutationGuard {
        var guard = self.beginDrainedIndexStructuralMutation(operation, index_name);
        if (!guard.acquireCatalogBarrierUntil(std.math.maxInt(u64))) unreachable;
        return guard;
    }

    fn beginDrainedIndexStructuralMutation(
        self: *DB,
        operation: []const u8,
        index_name: []const u8,
    ) IndexStructuralMutationGuard {
        return self.beginDrainedIndexStructuralMutationWithLease(operation, index_name, self.core.snapshot_admission.acquireMutation());
    }

    // Consumes the caller's admission. Native capture lends an explicit scoped
    // lease; ordinary structural operations acquire their own shared lease.
    fn beginDrainedIndexStructuralMutationWithLease(
        self: *DB,
        operation: []const u8,
        index_name: []const u8,
        snapshot_mutation: snapshot_admission_mod.SnapshotAdmission.MutationLease,
    ) IndexStructuralMutationGuard {
        std.debug.assert(snapshot_mutation.active and snapshot_mutation.admission == self.core.snapshot_admission);
        lockAtomicWithBackoff(&self.local_execution.index_structural_mutation_mutex);
        return .{
            .db = self,
            .snapshot_mutation = snapshot_mutation,
            .operation = operation,
            .index_name = index_name,
            .restart_text_merge = self.quiesceTextMergeForStructuralMutation(),
            .restart_sparse_compaction = self.quiesceSparseCompactionForStructuralMutation(),
        };
    }

    fn scheduleGeneratedArtifactCleanup(self: *DB) void {
        scheduleGeneratedArtifactCleanupContext(
            self.async_context,
            self.backend_runtime.durable_jobs,
            self.repair_cleanup_owner_id,
        );
    }

    /// Try to advance one bounded page of retired-index artifact records.
    /// Terminal filesystem finalization owns a separate lease, so callers never
    /// wait behind checkpoint or directory deletion performed by another job.
    pub const GeneratedArtifactCleanupAdvanceResult = @import("cleanup_job_owner.zig").Advance;

    pub fn advanceGeneratedArtifactCleanupPage(self: *DB, index_name: ?[]const u8) !GeneratedArtifactCleanupAdvanceResult {
        return try advanceGeneratedArtifactCleanupContext(self.async_context, index_name);
    }

    fn advanceGeneratedArtifactCleanupContext(
        ctx: *AsyncContext,
        index_name: ?[]const u8,
    ) !GeneratedArtifactCleanupAdvanceResult {
        if (!ctx.index_artifact_cleanup_mutex.tryLock()) return .busy;
        var cleanup_locked = true;
        defer if (cleanup_locked) ctx.index_artifact_cleanup_mutex.unlock();

        if (index_name) |name| {
            var targeted = try ctx.index_manager.drainGeneratedArtifactCleanupForIndexPage(
                ctx.store,
                name,
            );
            defer targeted.deinit();
            if (targeted.found) {
                if (!targeted.completed) return .progressed;
                return try finalizeClaimedRetiredIndexCleanup(ctx, &cleanup_locked, targeted.index_name, targeted.key);
            }
        }

        var result = try ctx.index_manager.drainGeneratedArtifactCleanupOutboxPage(ctx.store);
        defer result.deinit();
        if (!result.found) return .idle;
        if (!result.completed) return .progressed;
        return try finalizeClaimedRetiredIndexCleanup(ctx, &cleanup_locked, result.index_name, result.key);
    }

    fn finalizeClaimedRetiredIndexCleanup(
        ctx: *AsyncContext,
        cleanup_locked: *bool,
        index_name: []const u8,
        cleanup_key: []const u8,
    ) !GeneratedArtifactCleanupAdvanceResult {
        if (!ctx.index_artifact_finalization_mutex.tryLock()) return .busy;
        defer ctx.index_artifact_finalization_mutex.unlock();

        // Repair issues describe one concrete consumer generation. A
        // same-name replacement has different artifact identities and cannot
        // resolve diagnoses left by the retired generation. Keep the durable
        // cleanup tombstone authoritative until every issue and its terminal
        // failure history have drained in bounded, crash-idempotent pages.
        if (try drainRetiredIndexArtifactRepairIssuesPageContext(ctx, index_name)) return .progressed;

        // The durable tombstone remains visible while finalization runs, so
        // namespace admission stays fenced. Release page arbitration before
        // checkpoint and filesystem I/O; other indexes can continue draining.
        ctx.index_artifact_cleanup_mutex.unlock();
        cleanup_locked.* = false;
        if (builtin.is_test and test_block_generated_artifact_finalization.load(.acquire)) {
            test_generated_artifact_finalization_entered.store(true, .release);
            while (!test_release_generated_artifact_finalization.load(.acquire)) {
                std.testing.io.sleep(.fromNanoseconds(1), .awake) catch {};
            }
        }
        try finalizeRetiredIndexCleanupContext(ctx, index_name, cleanup_key);
        return .progressed;
    }

    fn scheduleGeneratedArtifactCleanupContext(
        ctx: *AsyncContext,
        lane: background_runtime_mod.DurableJobLane,
        owner_id: u64,
    ) void {
        @import("cleanup_job_owner.zig").schedule(.{
            .ptr = ctx,
            .state = &ctx.index_manager.artifact_cleanup_state,
            .lane = lane,
            .owner_id = owner_id,
            .io = ctx.io,
            .closing = &ctx.background_closing,
            .advance = advanceArtifactCleanup,
            .name = "generated-artifact",
        });
    }

    fn advanceArtifactCleanup(ptr: *anyopaque) !@import("cleanup_job_owner.zig").Advance {
        const ctx: *AsyncContext = @ptrCast(@alignCast(ptr));
        return try advanceGeneratedArtifactCleanupContext(ctx, null);
    }

    const retired_index_artifact_repair_cleanup_page_size: usize = 64;

    const RetiredArtifactRepairIssueKeyParse = union(enum) {
        valid: internal_keys.ArtifactRepairIssueKeyParts,
        malformed: anyerror,
    };

    fn parseRetiredArtifactRepairIssueKeyAlloc(
        alloc: Allocator,
        key: []const u8,
    ) !RetiredArtifactRepairIssueKeyParse {
        const parts = internal_keys.artifactRepairIssueKeyPartsAlloc(alloc, key) catch |err| switch (err) {
            error.OutOfMemory => return err,
            error.InvalidInternalUserKey => return .{ .malformed = err },
        };
        return .{ .valid = parts };
    }

    const RetiredArtifactRepairIssueValueDecode = union(enum) {
        valid: types.ArtifactRepairIssue,
        malformed: anyerror,
    };

    fn decodeRetiredArtifactRepairIssueAlloc(
        alloc: Allocator,
        raw: []const u8,
    ) !RetiredArtifactRepairIssueValueDecode {
        const issue = decodeArtifactRepairIssueValueAlloc(alloc, raw) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return .{ .malformed = err },
        };
        return .{ .valid = issue };
    }

    fn drainRetiredIndexArtifactRepairIssuesPageContext(
        ctx: *AsyncContext,
        index_name: []const u8,
    ) !bool {
        // Summary rebuilds own the apply lock, while issue publication and
        // terminal-marker transitions own the repair mutex. This ordering is
        // shared by derived apply paths and prevents a cleanup batch from
        // racing either authority.
        ctx.apply_mutex.lockExclusive();
        defer ctx.apply_mutex.unlockExclusive();
        lockAtomicWithBackoff(&ctx.artifact_repair_issue_mutex);
        defer ctx.artifact_repair_issue_mutex.unlock();

        const prefix = try internal_keys.artifactRepairIssueIndexPrefixAlloc(ctx.alloc, index_name);
        defer ctx.alloc.free(prefix);
        const rows = try ctx.store.scanPrefixPage(
            ctx.alloc,
            prefix,
            null,
            retired_index_artifact_repair_cleanup_page_size,
        );
        defer docstore_mod.DocStore.freeResults(ctx.alloc, rows);
        if (rows.len == 0) {
            // Primary records are authoritative. Sweep legacy orphaned
            // kind-index rows in bounded pages before releasing admission.
            for (std.meta.tags(types.ArtifactRepairKind)) |kind| {
                const kind_prefix = try internal_keys.artifactRepairIssueKindIndexPrefixAlloc(
                    ctx.alloc,
                    @tagName(kind),
                    index_name,
                );
                defer ctx.alloc.free(kind_prefix);
                const secondary_rows = try ctx.store.scanPrefixPage(
                    ctx.alloc,
                    kind_prefix,
                    null,
                    retired_index_artifact_repair_cleanup_page_size,
                );
                defer docstore_mod.DocStore.freeResults(ctx.alloc, secondary_rows);
                if (secondary_rows.len == 0) continue;
                const secondary_deletes = try ctx.alloc.alloc([]const u8, secondary_rows.len);
                defer ctx.alloc.free(secondary_deletes);
                for (secondary_rows, 0..) |row, i| secondary_deletes[i] = row.key;
                try ctx.store.putBatch(&.{}, secondary_deletes);
                return true;
            }
            return false;
        }

        var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer {
            for (writes.items) |write| ctx.alloc.free(@constCast(write.value));
            writes.deinit(ctx.alloc);
        }
        var deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer deletes.deinit(ctx.alloc);
        var owned_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (owned_keys.items) |key| ctx.alloc.free(@constCast(key));
            owned_keys.deinit(ctx.alloc);
        }
        const Batch = struct {
            fn appendOwnedDelete(
                alloc: Allocator,
                out_deletes: *std.ArrayListUnmanaged([]const u8),
                out_owned_keys: *std.ArrayListUnmanaged([]const u8),
                key: []u8,
            ) !void {
                errdefer alloc.free(key);
                const owned_len = out_owned_keys.items.len;
                try out_owned_keys.append(alloc, key);
                errdefer out_owned_keys.shrinkRetainingCapacity(owned_len);
                try out_deletes.append(alloc, key);
            }
        };

        var removed_issue_count: usize = 0;
        for (rows) |row| {
            // A coalesced issue can own arbitrarily many historical failure
            // markers. Drain exactly one marker page and leave the primary
            // issue present until a later pass observes the reverse namespace
            // empty; this is the durable cursor across crashes and reopen.
            const marker_count = try appendEnrichmentTerminalFailureMarkerDeletePageForIssue(
                ctx.alloc,
                ctx.store,
                row.key,
                &deletes,
                &owned_keys,
            );
            if (marker_count != 0) {
                if (removed_issue_count != 0) {
                    try appendArtifactRepairSummaryDirtyMarkerForStore(ctx.alloc, &writes, &deletes, &owned_keys);
                }
                try ctx.store.putBatch(writes.items, deletes.items);
                return true;
            }

            try deletes.append(ctx.alloc, row.key);
            removed_issue_count += 1;

            // The marker generation is keyed by the authoritative primary
            // key, so it is safe to retire even when the value is malformed.
            const generation_key = try internal_keys.enrichmentTerminalFailureGenerationKeyAlloc(ctx.alloc, row.key);
            try Batch.appendOwnedDelete(ctx.alloc, &deletes, &owned_keys, generation_key);

            var parts = switch (try parseRetiredArtifactRepairIssueKeyAlloc(ctx.alloc, row.key)) {
                .valid => |value| value,
                .malformed => |err| {
                    std.log.warn("retired index cleanup removed malformed artifact repair key index={s} err={s}", .{
                        index_name,
                        @errorName(err),
                    });
                    continue;
                },
            };
            defer parts.deinit(ctx.alloc);
            if (!std.mem.eql(u8, parts.index_name, index_name)) return error.InvalidInternalUserKey;

            const kind_key = try internal_keys.artifactRepairIssueKindKeyAlloc(
                ctx.alloc,
                parts.repair_artifact_kind,
                parts.index_name,
                parts.issue_id,
            );
            try Batch.appendOwnedDelete(ctx.alloc, &deletes, &owned_keys, kind_key);

            var issue_valid = true;
            var issue = switch (try decodeRetiredArtifactRepairIssueAlloc(ctx.alloc, row.value)) {
                .valid => |value| value,
                .malformed => |err| issue: {
                    issue_valid = false;
                    std.log.warn("retired index cleanup removed malformed artifact repair issue index={s} err={s}", .{
                        index_name,
                        @errorName(err),
                    });
                    break :issue types.ArtifactRepairIssue{};
                },
            };
            defer if (issue_valid) issue.deinit(ctx.alloc);
            if (issue_valid) {
                const expected_issue_key = try artifactRepairIssueKeyForIssueAlloc(ctx.alloc, issue);
                defer ctx.alloc.free(expected_issue_key);
                issue_valid = std.mem.eql(u8, issue.index_name, index_name) and
                    std.mem.eql(u8, expected_issue_key, row.key);
                if (!issue_valid) {
                    issue.deinit(ctx.alloc);
                    std.log.warn("retired index cleanup removed mismatched artifact repair issue index={s}", .{index_name});
                }
            }

            const completion_key = try internal_keys.artifactRepairCompletionKeyAlloc(
                ctx.alloc,
                parts.repair_artifact_kind,
                parts.issue_id,
            );
            var completion_key_local = true;
            defer if (completion_key_local) ctx.alloc.free(completion_key);
            if (!issue_valid) {
                // Completion fences are only a single-flight optimization. A
                // corrupt consumer value cannot safely contribute to their
                // shared count, so discard the fence rather than let stale
                // completed state suppress future repair.
                try Batch.appendOwnedDelete(ctx.alloc, &deletes, &owned_keys, completion_key);
                completion_key_local = false;
                continue;
            }
            if (issue.reason != .enrichment_failed) {
                continue;
            }

            const completion = (try loadArtifactRepairCompletionStateFromStore(
                ctx.alloc,
                ctx.store,
                completion_key,
            )) orelse continue;
            var updated_completion = completion;
            updated_completion.pending_issues -|= 1;
            if (updated_completion.pending_issues == 0) {
                try Batch.appendOwnedDelete(ctx.alloc, &deletes, &owned_keys, completion_key);
                completion_key_local = false;
            } else {
                const owned_len = owned_keys.items.len;
                owned_keys.append(ctx.alloc, completion_key) catch |err| {
                    return err;
                };
                errdefer owned_keys.shrinkRetainingCapacity(owned_len);
                const encoded = try ctx.alloc.create([artifact_repair_completion_state_len]u8);
                errdefer ctx.alloc.destroy(encoded);
                encodeArtifactRepairCompletionState(encoded, updated_completion);
                try writes.append(ctx.alloc, .{ .key = completion_key, .value = encoded });
                completion_key_local = false;
            }
        }

        try appendArtifactRepairSummaryDirtyMarkerForStore(ctx.alloc, &writes, &deletes, &owned_keys);
        try ctx.store.putBatch(writes.items, deletes.items);
        return true;
    }

    fn finalizeRetiredIndexCleanupContext(ctx: *AsyncContext, index_name: []const u8, cleanup_key: []const u8) !void {
        // Filesystem/cache cleanup is intentionally outside the DB apply lock.
        // The durable tombstone blocks overlapping artifact namespaces while
        // this runs.
        try ctx.index_manager.finalizeRetiredIndexStorage(ctx.store, index_name);

        try lockApplyForPortableRuntimeAsync(ctx);
        defer ctx.apply_mutex.unlockExclusive();
        if (ctx.index_manager.get(index_name) != null) return error.IndexGenerationStillActive;

        const storage_alloc = ctx.index_manager.alloc;
        if (try indexRepairIdForIndexContext(ctx, storage_alloc, index_name)) |repair_id| {
            removeIndexRepairIntentAndPinContext(ctx, storage_alloc, repair_id) catch |err| switch (err) {
                error.IndexRepairIntentNotFound, error.FileNotFound => {},
                else => return err,
            };
        }
        try deleteDenseArtifactCounterMetadataContext(storage_alloc, ctx.store, index_name);
        ctx.store.delete(cleanup_key) catch |err| switch (err) {
            error.NotFound => {},
            else => return err,
        };
    }

    fn rejectConflictingRetiredIndexCleanupForAdmission(self: *DB, cfg: types.IndexConfig) !void {
        lockAtomicWithBackoff(&self.async_context.index_artifact_cleanup_mutex);
        defer self.async_context.index_artifact_cleanup_mutex.unlock();
        const retired_name = (try self.core.index_manager.pendingGeneratedArtifactCleanupIndexForConfigAlloc(
            self.core.store,
            cfg,
        )) orelse return;
        defer self.alloc.free(retired_name);
        self.scheduleGeneratedArtifactCleanup();
        return error.IndexArtifactCleanupPending;
    }

    fn beginIndexRepairLease(self: *DB, index_name: []const u8) !bool {
        lockAtomic(&self.index_repair_mutex);
        defer self.index_repair_mutex.unlock();
        if (self.active_index_repairs.contains(index_name)) return false;
        const owned = try self.alloc.dupe(u8, index_name);
        errdefer self.alloc.free(owned);
        try self.active_index_repairs.put(self.alloc, owned, false);
        return true;
    }

    fn activeIndexRepairCancellationRequested(self: *DB, index_name: []const u8) bool {
        lockAtomic(&self.index_repair_mutex);
        defer self.index_repair_mutex.unlock();
        return self.active_index_repairs.get(index_name) orelse false;
    }

    fn requestActiveIndexRepairCancellation(self: *DB, index_name: []const u8) bool {
        lockAtomic(&self.index_repair_mutex);
        defer self.index_repair_mutex.unlock();
        const requested = self.active_index_repairs.getPtr(index_name) orelse return false;
        requested.* = true;
        return true;
    }

    fn endIndexRepairLease(self: *DB, index_name: []const u8) void {
        lockAtomic(&self.index_repair_mutex);
        defer self.index_repair_mutex.unlock();
        if (self.active_index_repairs.fetchRemove(index_name)) |removed| {
            self.alloc.free(@constCast(removed.key));
        }
    }

    fn primaryUserNamespaceIsEmptyLocked(self: *DB) !bool {
        var txn = try self.core.store.beginCurrentScanTxn();
        defer txn.abort();
        var cur = try txn.openCursor();
        defer cur.close();

        const lower = [_]u8{internal_keys.user_namespace};
        const first = (try cur.seekAtOrAfter(lower[0..])) orelse return true;
        return first.key.len == 0 or first.key[0] != internal_keys.user_namespace;
    }

    pub const rememberBulkIngestAllNewIdentityUpserts = local_mutation.rememberBulkIngestAllNewIdentityUpserts;

    pub const identityUpsertStoreWritesAreNew = local_mutation.identityUpsertStoreWritesAreNew;

    pub const CoalescedKeyValueRequest = local_mutation.CoalescedKeyValueRequest;

    /// Immutable bases for transforms that depend on durable rows rather than
    /// a value established earlier in the same request. Values and versions
    /// are captured from one storage read transaction; the exclusive commit
    /// fence later validates every version before consuming prepared output.
    pub const TransformReadSnapshot = local_mutation.TransformReadSnapshot;

    pub const captureTransformReadSnapshot = local_mutation.captureTransformReadSnapshot;

    pub const GeneratedWriteReadSnapshot = local_mutation.GeneratedWriteReadSnapshot;

    /// Fence every document's primary and artifact state across precomputation.
    /// Physical transactions advance these revisions even when TTL timestamps
    /// and primary bytes are unchanged. Unrelated documents do not invalidate
    /// this request, and no catalog or provider work runs under the apply lock.
    pub const captureGeneratedWriteReadSnapshot = local_mutation.captureGeneratedWriteReadSnapshot;

    pub const validateGeneratedWriteReadSnapshot = local_mutation.validateGeneratedWriteReadSnapshot;

    pub const validateTransformReadSnapshot = local_mutation.validateTransformReadSnapshot;

    pub const deinitOwnedGraphEdgeWrite = local_mutation.deinitOwnedGraphEdgeWrite;

    pub const deinitOwnedGraphEdgeDelete = local_mutation.deinitOwnedGraphEdgeDelete;

    pub const graphMutationIdentityEql = local_mutation.graphMutationIdentityEql;

    pub const appendGraphTransformWrite = local_mutation.appendGraphTransformWrite;

    pub const appendGraphTransformDelete = local_mutation.appendGraphTransformDelete;

    pub const resetCoalescedEntryToDelete = local_mutation.resetCoalescedEntryToDelete;

    pub const setCoalescedEntryToBorrowedWrite = local_mutation.setCoalescedEntryToBorrowedWrite;

    pub const setCoalescedEntryToOwnedWrite = local_mutation.setCoalescedEntryToOwnedWrite;

    pub const coalesceKeyValueRequest = local_mutation.coalesceKeyValueRequest;

    pub fn get(self: *DB, alloc: Allocator, key: []const u8) !?[]u8 {
        try self.maybeFinalizePendingRowPolicyPublication();
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRawRead();
        defer row_policy_lease.release();
        var schema_view = self.core.acquireSchemaView();
        defer if (schema_view) |*view| view.release();
        const store_key = try encodeStoreLookupKeyWithPinnedSchemaAlloc(self, alloc, key, schema_view);
        defer alloc.free(store_key);
        const raw = try self.core.getStoreValue(alloc, store_key) orelse {
            try row_policy_lease.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
            return null;
        };
        defer alloc.free(raw);
        if (!internal_keys.isInternalUserKey(key)) {
            const ttl_duration_ns = if (schema_view) |view| view.visibilityTtlDurationNs() else 0;
            if (ttl_duration_ns != 0) {
                const timestamp_ns = if (internal_keys.isRelationalRowKey(store_key))
                    try relational_store.rowWriteTimestampNs(raw)
                else
                    try self.getTimestamp(alloc, key);
                if (timestamp_ns != 0 and ttl_mod.isExpired(timestamp_ns, ttl_duration_ns, currentTimeNs())) {
                    try row_policy_lease.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
                    return null;
                }
            }
        }
        const result = try self.core.index_manager.materializeStoredValueWithPinnedSchemaAlloc(alloc, store_key, raw, schema_view);
        errdefer alloc.free(result);
        try row_policy_lease.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
        return result;
    }

    pub fn getArtifact(self: *DB, alloc: Allocator, artifact_id: []const u8) !?types.ArtifactRecord {
        try self.maybeFinalizePendingRowPolicyPublication();
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRawRead();
        defer row_policy_lease.release();
        var artifact_ref = (try artifact_ids.decodeArtifactPublicIdAlloc(alloc, artifact_id)) orelse return error.InvalidArgument;
        errdefer artifact_ref.deinit(alloc);

        const internal_key = try artifact_ids.internalKeyForArtifactRefAlloc(alloc, artifact_ref);
        defer alloc.free(internal_key);

        const value = blk: {
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            var input = try @import("artifact_extraction_generation.zig").captureInput(alloc, &read, internal_key);
            defer input.deinit();
            const raw = input.value orelse {
                artifact_ref.deinit(alloc);
                return null;
            };
            break :blk try alloc.dupe(u8, raw);
        };
        errdefer alloc.free(value);

        const id = try alloc.dupe(u8, artifact_id);
        errdefer alloc.free(id);
        try row_policy_lease.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
        return .{
            .id = id,
            .value = value,
            .artifact_ref = artifact_ref,
        };
    }

    /// Returns an artifact through a public response boundary. Raw artifact
    /// values are retained internally because compute/apply transports need
    /// storage metadata, while public lookup must never expose hierarchy
    /// revision fingerprints or coordinator envelopes.
    pub fn getPublicArtifact(self: *DB, alloc: Allocator, artifact_id: []const u8) !?types.ArtifactRecord {
        try self.maybeFinalizePendingRowPolicyPublication();
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRawRead();
        defer row_policy_lease.release();
        var artifact = (try self.getArtifact(alloc, artifact_id)) orelse return null;
        errdefer artifact.deinit(alloc);
        const public_value = try hierarchy_navigation.publicArtifactPayloadAlloc(alloc, artifact.value);
        alloc.free(artifact.value);
        artifact.value = public_value;
        try row_policy_lease.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
        return artifact;
    }

    pub fn getDocumentArtifactManifest(
        self: *DB,
        alloc: Allocator,
        doc_key: []const u8,
        artifact_name: []const u8,
    ) !?types.DocumentArtifactManifest {
        try self.maybeFinalizePendingRowPolicyPublication();
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRawRead();
        defer row_policy_lease.release();
        lockApplyShared(self);
        defer self.core.unlockApplyShared();

        const manifest_key = try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "asset", artifact_name);
        defer alloc.free(manifest_key);
        const manifest = try self.core.getStoreValue(alloc, manifest_key) orelse return null;
        var manifest_owned = true;
        errdefer if (manifest_owned) alloc.free(manifest);

        const state_key = try assetStateKeyAlloc(alloc, doc_key, artifact_name);
        defer alloc.free(state_key);
        const state = self.core.getStoreValue(alloc, state_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        var state_owned = true;
        errdefer if (state_owned) if (state) |value| alloc.free(value);

        manifest_owned = false;
        state_owned = false;
        var result = try documentArtifactManifestFromJsonAlloc(alloc, doc_key, artifact_name, manifest, state);
        errdefer result.deinit(alloc);
        try row_policy_lease.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
        return result;
    }

    pub fn listDocumentArtifactManifests(
        self: *DB,
        alloc: Allocator,
        doc_key: []const u8,
    ) !types.DocumentArtifactManifestList {
        try self.maybeFinalizePendingRowPolicyPublication();
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRawRead();
        defer row_policy_lease.release();
        lockApplyShared(self);
        defer self.core.unlockApplyShared();

        const prefix = try internal_keys.artifactTypePrefixAlloc(alloc, doc_key, "asset");
        defer alloc.free(prefix);
        const rows = try self.core.scanStorePrefix(alloc, prefix);
        defer docstore_mod.DocStore.freeResults(alloc, rows);

        var artifacts = std.ArrayListUnmanaged(types.DocumentArtifactManifest).empty;
        errdefer {
            for (artifacts.items) |*artifact| artifact.deinit(alloc);
            artifacts.deinit(alloc);
        }

        for (rows) |row| {
            var artifact_ref = (try decodeArtifactRefIfKnownAlloc(alloc, row.key)) orelse continue;
            defer artifact_ref.deinit(alloc);
            if (artifact_ref.kind != .asset) continue;
            if (artifact_ref.unit_id != null) continue;
            if (!std.mem.eql(u8, artifact_ref.document_id, doc_key)) continue;

            const state_key = try assetStateKeyAlloc(alloc, doc_key, artifact_ref.name);
            defer alloc.free(state_key);
            const state = self.core.getStoreValue(alloc, state_key) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            errdefer if (state) |value| alloc.free(value);

            const manifest_json = try alloc.dupe(u8, row.value);
            errdefer alloc.free(manifest_json);
            try artifacts.append(
                alloc,
                try documentArtifactManifestFromJsonAlloc(alloc, doc_key, artifact_ref.name, manifest_json, state),
            );
        }

        var result: types.DocumentArtifactManifestList = .{
            .document_id = try alloc.dupe(u8, doc_key),
            .artifacts = try artifacts.toOwnedSlice(alloc),
        };
        errdefer result.deinit(alloc);
        try row_policy_lease.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
        return result;
    }

    pub fn updateDocumentArtifactChildRangePlacement(
        self: *DB,
        alloc: Allocator,
        doc_key: []const u8,
        artifact_name: []const u8,
        update: types.DocumentArtifactChildRangePlacementUpdate,
    ) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.executor.failIfUnhealthy();

        var snapshot_mutation = self.core.snapshot_admission.acquireMutation();
        defer snapshot_mutation.release();
        try self.lockApplyForPortableRuntime();
        var apply_mutex_held = true;
        errdefer if (apply_mutex_held) self.core.unlockApply();

        const manifest_key = try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "asset", artifact_name);
        defer alloc.free(manifest_key);
        const manifest = try self.core.getStoreValue(alloc, manifest_key) orelse {
            self.core.unlockApply();
            apply_mutex_held = false;
            return false;
        };
        defer alloc.free(manifest);

        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const arena_alloc = arena.allocator();
        var manifest_value = try std.json.parseFromSliceLeaky(std.json.Value, arena_alloc, manifest, .{ .allocate = .alloc_always });
        if (manifest_value != .object) return error.InvalidArgument;
        const child_ranges = manifest_value.object.getPtr("child_ranges") orelse return error.InvalidArgument;
        if (child_ranges.* != .array) return error.InvalidArgument;

        var changed = false;
        for (child_ranges.array.items) |*item| {
            if (item.* != .object) return error.InvalidArgument;
            const range_id = item.object.get("range_id") orelse return error.InvalidArgument;
            if (range_id != .string) return error.InvalidArgument;
            if (!std.mem.eql(u8, range_id.string, update.range_id)) continue;

            try putLeakyJsonStringField(arena_alloc, &item.object, "placement", update.placement);
            if (update.owner_group_id) |owner_group_id| try putLeakyJsonU64Field(arena_alloc, &item.object, "owner_group_id", owner_group_id);
            if (update.placement_generation) |placement_generation| try putLeakyJsonU64Field(arena_alloc, &item.object, "placement_generation", placement_generation);
            if (update.route_status) |route_status| try putLeakyJsonStringField(arena_alloc, &item.object, "route_status", route_status);
            if (update.split_eligible) |split_eligible| try item.object.put(arena_alloc, "split_eligible", .{ .bool = split_eligible });
            changed = true;
            break;
        }

        if (!changed) {
            self.core.unlockApply();
            apply_mutex_held = false;
            return false;
        }

        const updated_manifest = try std.json.Stringify.valueAlloc(alloc, manifest_value, .{});
        defer alloc.free(updated_manifest);

        const sequence = self.core.reserveDerivedAppendSequence();
        const changed_artifact_keys = [_][]const u8{manifest_key};
        const replay_payload = try encodeChangeRecordPayload(&self.batchContext(), .{
            .sequence = sequence,
            .changed_artifact_keys = changed_artifact_keys[0..],
        }, sequence);
        defer alloc.free(replay_payload);

        const writes = [_]docstore_mod.KVPair{.{
            .key = manifest_key,
            .value = updated_manifest,
        }};
        var backlog_admission = try self.executor.admitBacklogBytes(@intCast(replay_payload.len));
        defer backlog_admission.cancel();
        try self.core.store.putBatchWithReplay(self.backend_runtime.io(), writes[0..], &.{}, .{
            .sequence = sequence,
            .payload = replay_payload,
        });
        self.mirrorReplicationReplayPayloadBestEffort(replay_payload);
        self.executor.commitBacklogAdmission(sequence, &backlog_admission);
        self.core.unlockApply();
        apply_mutex_held = false;
        snapshot_mutation.release();
        notifyQueryVisibilityTargetAdvanced(self.async_context, sequence);

        if (self.executor.hasWorkers()) {
            self.executor.forceSequence(sequence);
        } else {
            self.executor.notifySequence(sequence);
        }
        self.notifyResolverReplayRuntimes(sequence);
        return true;
    }

    pub fn reprocessDocumentArtifact(
        self: *DB,
        alloc: Allocator,
        doc_key: []const u8,
        artifact_name: []const u8,
    ) !bool {
        var cfg = (try self.getEnrichment(alloc, .asset, artifact_name)) orelse return false;
        defer cfg.deinit(alloc);
        // A missing producer definition means this artifact cannot currently be
        // regenerated. A missing source document is a distinct, actionable
        // repair outcome and must reach the repair API as `missing_source_docs`.
        const value = try self.get(alloc, doc_key) orelse return error.NotFound;
        defer alloc.free(value);

        const writes = [_]types.BatchWrite{.{ .key = doc_key, .value = value }};
        const force_artifacts = [_][]const u8{artifact_name};
        try self.batchInternal(.{
            .writes = &writes,
            .sync_level = .full_index,
        }, null, .{
            .force_generated_artifact_names = &force_artifacts,
        });
        return true;
    }

    pub fn reprocessDocumentEmbeddingArtifact(
        self: *DB,
