    fn loadArtifactRepairSummaryCountByKey(self: *DB, alloc: Allocator, key: []const u8) !?u64 {
        const raw = self.core.store.get(alloc, key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        defer alloc.free(raw);
        if (raw.len != @sizeOf(u64)) return error.InvalidArtifactPayload;
        return std.mem.readInt(u64, raw[0..8], .little);
    }

    fn artifactRepairSummaryReady(self: *DB, alloc: Allocator) !bool {
        const ready_key = try internal_keys.artifactRepairSummaryReadyKeyAlloc(alloc);
        defer alloc.free(ready_key);
        const ready = self.core.store.get(alloc, ready_key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        defer alloc.free(ready);
        return std.mem.eql(u8, ready, artifact_repair_summary_ready_marker);
    }

    fn loadArtifactRepairSummaryCountOrScan(
        self: *DB,
        alloc: Allocator,
        key: []const u8,
    ) !u64 {
        if (try self.artifactRepairSummaryReady(alloc)) {
            return (try self.loadArtifactRepairSummaryCountByKey(alloc, key)) orelse 0;
        }
        return (try self.loadArtifactRepairSummaryCountByKey(alloc, key)) orelse 0;
    }

    fn scanArtifactRepairIssueCountBounded(self: *DB, alloc: Allocator, index_name: ?[]const u8) !u64 {
        const prefix = try internal_keys.artifactRepairIssueRootPrefixAlloc(alloc);
        defer alloc.free(prefix);
        const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
        defer if (upper) |buf| alloc.free(buf);

        const ScanState = struct {
            const scan_limit: usize = 1024;

            alloc: Allocator,
            index_name: ?[]const u8,
            count: u64 = 0,
            scanned: usize = 0,

            fn scanEntry(ctx: ?*anyopaque, _: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                var issue = try decodeArtifactRepairIssueValueAlloc(state.alloc, value);
                defer issue.deinit(state.alloc);
                state.scanned += 1;
                if (state.index_name == null or std.mem.eql(u8, issue.index_name, state.index_name.?)) {
                    state.count += 1;
                }
                if (state.scanned >= scan_limit) return .stop;
                return .@"continue";
            }
        };

        var state = ScanState{ .alloc = alloc, .index_name = index_name };
        try self.core.store.scanWithContext(prefix, if (upper) |buf| buf else "", .{}, &state, ScanState.scanEntry);
        return state.count;
    }

    const ArtifactRepairSummarySnapshot = struct {
        ready: bool,
        count: u64,
        repair_scan_count: u64 = 0,
    };

    fn artifactRepairSummaryRootSnapshot(self: *DB, alloc: Allocator) !ArtifactRepairSummarySnapshot {
        const ready = try self.artifactRepairSummaryReady(alloc);
        const key = if (ready)
            try internal_keys.artifactRepairSummaryRootKeyAlloc(alloc)
        else
            try internal_keys.artifactRepairSummaryRebuildRootKeyAlloc(alloc);
        defer alloc.free(key);
        return .{
            .ready = ready,
            .count = (try self.loadArtifactRepairSummaryCountByKey(alloc, key)) orelse if (ready) 0 else try self.scanArtifactRepairIssueCountBounded(alloc, null),
        };
    }

    fn artifactRepairSummaryRootCount(self: *DB, alloc: Allocator) !u64 {
        return (try self.artifactRepairSummaryRootSnapshot(alloc)).count;
    }

    fn artifactRepairSummaryIndexSnapshot(self: *DB, alloc: Allocator, index_name: []const u8, ready: bool) !ArtifactRepairSummarySnapshot {
        const key = if (ready)
            try internal_keys.artifactRepairSummaryIndexKeyAlloc(alloc, index_name)
        else
            try internal_keys.artifactRepairSummaryRebuildIndexKeyAlloc(alloc, index_name);
        defer alloc.free(key);
        if (try self.loadArtifactRepairSummaryCountByKey(alloc, key)) |count| {
            return .{ .ready = ready, .count = count };
        }
        if (ready) return .{ .ready = true, .count = 0 };
        const scanned_count = try self.scanArtifactRepairIssueCountBounded(alloc, index_name);
        return .{ .ready = false, .count = scanned_count, .repair_scan_count = scanned_count };
    }

    fn artifactRepairSummarySourceSnapshot(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        artifact_name: []const u8,
        ready: bool,
    ) !ArtifactRepairSummarySnapshot {
        // During a rebuild there is no safe bounded fallback that can prove
        // absence for an arbitrary source. Return the partial shadow count for
        // diagnostics and keep readiness explicitly false until publication.
        const key = if (ready)
            try internal_keys.artifactRepairSummarySourceKeyAlloc(alloc, index_name, artifact_name)
        else
            try internal_keys.artifactRepairSummaryRebuildSourceKeyAlloc(alloc, index_name, artifact_name);
        defer alloc.free(key);
        return .{
            .ready = ready,
            .count = (try self.loadArtifactRepairSummaryCountByKey(alloc, key)) orelse 0,
        };
    }

    const ArtifactRepairIndexFallbackCounts = struct {
        alloc: Allocator,
        counts: std.StringHashMapUnmanaged(u64) = .empty,
        loaded: bool = false,

        pub fn deinit(self: *@This()) void {
            var it = self.counts.iterator();
            while (it.next()) |entry| self.alloc.free(entry.key_ptr.*);
            self.counts.deinit(self.alloc);
        }
    };

    fn ensureArtifactRepairIndexFallbackCounts(self: *DB, alloc: Allocator, fallback: *ArtifactRepairIndexFallbackCounts) !void {
        if (fallback.loaded) return;
        fallback.loaded = true;

        const prefix = try internal_keys.artifactRepairIssueRootPrefixAlloc(alloc);
        defer alloc.free(prefix);
        const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
        defer if (upper) |buf| alloc.free(buf);

        const ScanState = struct {
            const scan_limit: usize = 1024;

            alloc: Allocator,
            counts: *std.StringHashMapUnmanaged(u64),
            scanned: usize = 0,

            fn scanEntry(ctx: ?*anyopaque, _: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                var issue = try decodeArtifactRepairIssueValueAlloc(state.alloc, value);
                defer issue.deinit(state.alloc);
                state.scanned += 1;
                const result = try state.counts.getOrPut(state.alloc, issue.index_name);
                if (!result.found_existing) {
                    result.key_ptr.* = try state.alloc.dupe(u8, issue.index_name);
                    result.value_ptr.* = 0;
                }
                result.value_ptr.* += 1;
                if (state.scanned >= scan_limit) return .stop;
                return .@"continue";
            }
        };

        var state = ScanState{ .alloc = alloc, .counts = &fallback.counts };
        try self.core.store.scanWithContext(prefix, if (upper) |buf| buf else "", .{}, &state, ScanState.scanEntry);
    }

    fn artifactRepairSummaryIndexSnapshotForStats(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        ready: bool,
        fallback: *ArtifactRepairIndexFallbackCounts,
    ) !ArtifactRepairSummarySnapshot {
        if (ready) return try self.artifactRepairSummaryIndexSnapshot(alloc, index_name, true);

        const key = try internal_keys.artifactRepairSummaryRebuildIndexKeyAlloc(alloc, index_name);
        defer alloc.free(key);
        if (try self.loadArtifactRepairSummaryCountByKey(alloc, key)) |count| {
            return .{ .ready = false, .count = count };
        }

        try self.ensureArtifactRepairIndexFallbackCounts(alloc, fallback);
        const scanned_count = fallback.counts.get(index_name) orelse 0;
        return .{ .ready = false, .count = scanned_count, .repair_scan_count = scanned_count };
    }

    fn appendArtifactRepairSummaryWrite(
        self: *DB,
        alloc: Allocator,
        writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
        deletes: *std.ArrayListUnmanaged([]const u8),
        key: []const u8,
        delta: i64,
    ) !void {
        const existing = (try self.loadArtifactRepairSummaryCountByKey(alloc, key)) orelse 0;
        const updated = if (delta >= 0) existing +| @as(u64, @intCast(delta)) else existing -| @as(u64, @intCast(-delta));
        if (updated == 0) {
            try deletes.append(alloc, key);
            return;
        }
        const value = try alloc.alloc(u8, @sizeOf(u64));
        std.mem.writeInt(u64, value[0..8], updated, .little);
        try writes.append(alloc, .{ .key = key, .value = value });
    }

    fn appendKeysForPrefixDelete(
        self: *DB,
        alloc: Allocator,
        deletes: *std.ArrayListUnmanaged([]const u8),
        owned_keys: *std.ArrayListUnmanaged([]const u8),
        prefix: []const u8,
    ) !void {
        const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
        defer if (upper) |buf| alloc.free(buf);
        const ScanState = struct {
            alloc: Allocator,
            deletes: *std.ArrayListUnmanaged([]const u8),
            owned_keys: *std.ArrayListUnmanaged([]const u8),

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, _: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                const key_copy = try state.alloc.dupe(u8, key);
                errdefer state.alloc.free(key_copy);
                const owned_len = state.owned_keys.items.len;
                try state.owned_keys.append(state.alloc, key_copy);
                errdefer state.owned_keys.shrinkRetainingCapacity(owned_len);
                try state.deletes.append(state.alloc, key_copy);
                return .@"continue";
            }
        };
        var state = ScanState{ .alloc = alloc, .deletes = deletes, .owned_keys = owned_keys };
        try self.core.store.scanWithContext(prefix, if (upper) |buf| buf else "", .{}, &state, ScanState.scanEntry);
    }

    fn appendArtifactRepairSummaryRebuildInvalidation(
        self: *DB,
        alloc: Allocator,
        writes: ?*std.ArrayListUnmanaged(docstore_mod.KVPair),
        deletes: *std.ArrayListUnmanaged([]const u8),
        owned_keys: *std.ArrayListUnmanaged([]const u8),
    ) !void {
        const progress_key = try internal_keys.artifactRepairSummaryProgressKeyAlloc(alloc);
        errdefer alloc.free(progress_key);
        const owned_len = owned_keys.items.len;
        try owned_keys.append(alloc, progress_key);
        errdefer owned_keys.shrinkRetainingCapacity(owned_len);
        if (writes) |out| {
            const dirty_value = try alloc.dupe(u8, artifact_repair_summary_dirty_marker);
            errdefer alloc.free(dirty_value);
            try out.append(alloc, .{ .key = progress_key, .value = dirty_value });
        } else {
            try deletes.append(alloc, progress_key);
        }

        const rebuild_prefix = try internal_keys.artifactRepairSummaryRebuildRootKeyAlloc(alloc);
        defer alloc.free(rebuild_prefix);
        try self.appendKeysForPrefixDelete(alloc, deletes, owned_keys, rebuild_prefix);
    }

    fn appendArtifactRepairSummaryDirty(
        self: *DB,
        alloc: Allocator,
        writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
        deletes: *std.ArrayListUnmanaged([]const u8),
        owned_delete_keys: *std.ArrayListUnmanaged([]const u8),
    ) !void {
        const ready_key = try internal_keys.artifactRepairSummaryReadyKeyAlloc(alloc);
        errdefer alloc.free(ready_key);
        const owned_len = owned_delete_keys.items.len;
        try owned_delete_keys.append(alloc, ready_key);
        errdefer owned_delete_keys.shrinkRetainingCapacity(owned_len);
        try deletes.append(alloc, ready_key);
        try self.appendArtifactRepairSummaryRebuildInvalidation(alloc, writes, deletes, owned_delete_keys);
    }

    fn saveArtifactRepairIssueWithSummary(
        self: *DB,
        alloc: Allocator,
        key: []const u8,
        issue: types.ArtifactRepairIssue,
        new_issue: bool,
        extra_writes: []const docstore_mod.KVPair,
        extra_deletes: []const []const u8,
    ) !void {
        const kind_key = try self.repairIssueKindKeyForIssueAlloc(alloc, issue);
        defer alloc.free(kind_key);
        const encoded = try self.encodeArtifactRepairIssueAlloc(alloc, issue);
        defer alloc.free(encoded);
        if (!new_issue) {
            var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
            defer writes.deinit(alloc);
            try writes.append(alloc, .{ .key = key, .value = encoded });
            try writes.append(alloc, .{ .key = kind_key, .value = encoded });
            try writes.appendSlice(alloc, extra_writes);
            try self.core.store.putBatch(writes.items, extra_deletes);
            return;
        }

        var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        var borrowed_write_count: usize = 0;
        defer {
            for (writes.items[borrowed_write_count..]) |item| alloc.free(@constCast(item.value));
            writes.deinit(alloc);
        }
        var deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer deletes.deinit(alloc);
        var owned_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (owned_delete_keys.items) |owned_key| alloc.free(@constCast(owned_key));
            owned_delete_keys.deinit(alloc);
        }

        try writes.append(alloc, .{ .key = key, .value = encoded });
        try writes.append(alloc, .{ .key = kind_key, .value = encoded });
        borrowed_write_count = writes.items.len;
        try writes.appendSlice(alloc, extra_writes);
        borrowed_write_count = writes.items.len;
        try deletes.appendSlice(alloc, extra_deletes);
        try self.appendArtifactRepairSummaryDirty(alloc, &writes, &deletes, &owned_delete_keys);
        try self.core.store.putBatch(writes.items, deletes.items);
    }

    fn deleteArtifactRepairIssueWithSummary(
        self: *DB,
        alloc: Allocator,
        key: []const u8,
        existing_issue: types.ArtifactRepairIssue,
        extra_writes: []const docstore_mod.KVPair,
        extra_deletes: []const []const u8,
    ) !void {
        const kind_key = try self.repairIssueKindKeyForIssueAlloc(alloc, existing_issue);
        defer alloc.free(kind_key);

        var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer writes.deinit(alloc);
        try writes.appendSlice(alloc, extra_writes);
        const borrowed_write_count = writes.items.len;
        defer for (writes.items[borrowed_write_count..]) |item| alloc.free(@constCast(item.value));
        var deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer deletes.deinit(alloc);
        var owned_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (owned_delete_keys.items) |owned_key| alloc.free(@constCast(owned_key));
            owned_delete_keys.deinit(alloc);
        }

        try deletes.append(alloc, key);
        try deletes.append(alloc, kind_key);
        try deletes.appendSlice(alloc, extra_deletes);
        if (existing_issue.reason == .enrichment_failed) {
            try appendEnrichmentTerminalFailureMarkerDeletesForIssue(
                alloc,
                self.core.store,
                key,
                &deletes,
                &owned_delete_keys,
                true,
            );
        }
        try self.appendArtifactRepairSummaryDirty(alloc, &writes, &deletes, &owned_delete_keys);
        try self.core.store.putBatch(writes.items, deletes.items);
    }

    fn clearArtifactRepairIssueWithSummary(self: *DB, alloc: Allocator, issue: types.ArtifactRepairIssue) !void {
        const key = try self.repairIssueKeyForIssueAlloc(alloc, issue);
        defer alloc.free(key);

        const existing = (try self.loadArtifactRepairIssueByKey(alloc, key)) orelse {
            const stale_kind_key = try self.repairIssueKindKeyForIssueAlloc(alloc, issue);
            defer alloc.free(stale_kind_key);
            try self.core.store.putBatch(&.{}, &.{stale_kind_key});
            return;
        };
        var existing_issue = existing;
        defer existing_issue.deinit(alloc);
        try self.deleteArtifactRepairIssueWithSummary(alloc, key, existing_issue, &.{}, &.{});
    }

    fn clearArtifactRepairIssueIfCurrent(
        self: *DB,
        alloc: Allocator,
        issue: types.ArtifactRepairIssue,
        revision: ArtifactRepairIssueRevision,
    ) !bool {
        lockAtomicWithBackoff(&self.async_context.artifact_repair_issue_mutex);
        defer self.async_context.artifact_repair_issue_mutex.unlock();

        const key = try self.repairIssueKeyForIssueAlloc(alloc, issue);
        defer alloc.free(key);
        // Successful replay can retire this exact diagnosis at its publication
        // boundary before the request that initiated replay reaches completion.
        // Absence is therefore an idempotent success; a present, newer revision
        // remains a conflict and must not be cleared below.
        const existing = (try self.loadArtifactRepairIssueByKey(alloc, key)) orelse return true;
        var current = existing;
        defer current.deinit(alloc);
        if (!revision.matches(current)) return false;

        try self.deleteArtifactRepairIssueWithSummary(alloc, key, current, &.{}, &.{});
        return true;
    }

    fn enrichmentFailureCoverageMarkerKeyAlloc(
        self: *DB,
        alloc: Allocator,
        issue: types.ArtifactRepairIssue,
    ) !?[]u8 {
        if (issue.reason != .enrichment_failed or issue.index_name.len == 0) return null;
        if (self.core.index_manager.denseIndex(issue.index_name) == null and
            self.core.index_manager.sparseIndex(issue.index_name) == null)
        {
            return null;
        }
        const generation = self.core.index_manager.coverageGenerationForIndex(issue.index_name) orelse return null;
        return try internal_keys.derivedCoverageOutcomeKeyAlloc(alloc, issue.index_name, generation, issue.doc_key);
    }

    fn repairCoverageMarkerComplete(self: *DB, alloc: Allocator, marker_key: []const u8) !bool {
        const raw_outcome = self.core.store.get(alloc, marker_key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        defer alloc.free(raw_outcome);
        const outcome = std.meta.stringToEnum(DerivedCoverageOutcome, raw_outcome) orelse
            return error.InvalidDerivedCoverageOutcome;
        return outcome == .produced or outcome == .skipped;
    }

    fn completeArtifactRepairIssueIfCurrent(
        self: *DB,
        alloc: Allocator,
        issue: types.ArtifactRepairIssue,
        revision: ArtifactRepairIssueRevision,
        completion_key: []const u8,
        expected_epoch: u64,
        require_completed_fence: bool,
    ) !ArtifactRepairCompletionDisposition {
        const coverage_marker_key = try self.enrichmentFailureCoverageMarkerKeyAlloc(alloc, issue);
        defer if (coverage_marker_key) |key| alloc.free(key);

        lockAtomicWithBackoff(&self.async_context.artifact_repair_issue_mutex);
        defer self.async_context.artifact_repair_issue_mutex.unlock();

        const key = try self.repairIssueKeyForIssueAlloc(alloc, issue);
        defer alloc.free(key);
        // Publication owns the authoritative resolution boundary and may have
        // already removed this exact issue while the initiating repair request
        // was replaying it. Treat absence as idempotent completion, but retain
        // the revision and completion-epoch fences for every present record.
        const existing = (try self.loadArtifactRepairIssueByKey(alloc, key)) orelse return .completed;
        var current = existing;
        defer current.deinit(alloc);
        if (!revision.matches(current)) return .stale;

        // Validate the shared execution fence before interpreting this
        // consumer's coverage marker. A sibling failure can advance the epoch
        // without changing this issue revision; treating that stale snapshot
        // as coverage debt would pay for provider work that cannot commit.
        var completion = (try self.loadArtifactRepairCompletionState(alloc, completion_key)) orelse ArtifactRepairCompletionState{};
        if (completion.epoch != expected_epoch) return .stale;
        if (require_completed_fence and completion.completed_sequence < revision.sequence) return .stale;

        // Coverage transitions and repair-ledger completion share this mutex.
        // Re-read the repaired generation while holding it so either repair
        // clears debt first (and stale terminal transitions are rejected) or a
        // terminal transition lands first (and debt remains queued). There is
        // no interleaving that can leave terminal coverage without repair debt.
        if (coverage_marker_key) |marker_key| {
            if (!try self.repairCoverageMarkerComplete(alloc, marker_key)) return .coverage_incomplete;
        }

        completion.completed_sequence = @max(completion.completed_sequence, revision.sequence);
        completion.pending_issues -|= 1;

        var encoded: [artifact_repair_completion_state_len]u8 = undefined;
        const completion_writes: []const docstore_mod.KVPair = if (completion.pending_issues == 0)
            &.{}
        else blk: {
            encodeArtifactRepairCompletionState(&encoded, completion);
            break :blk &.{.{ .key = completion_key, .value = &encoded }};
        };
        const completion_deletes: []const []const u8 = if (completion.pending_issues == 0)
            &.{completion_key}
        else
            &.{};
        try self.deleteArtifactRepairIssueWithSummary(
            alloc,
            key,
            current,
            completion_writes,
            completion_deletes,
        );
        return .completed;
    }

    fn saveArtifactRepairAttemptIfCurrent(
        self: *DB,
        alloc: Allocator,
        issue: types.ArtifactRepairIssue,
        revision: ArtifactRepairIssueRevision,
    ) !bool {
        lockAtomicWithBackoff(&self.async_context.artifact_repair_issue_mutex);
        defer self.async_context.artifact_repair_issue_mutex.unlock();
        const key = try self.repairIssueKeyForIssueAlloc(alloc, issue);
        defer alloc.free(key);
        const existing = (try self.loadArtifactRepairIssueByKey(alloc, key)) orelse return false;
        var current = existing;
        defer current.deinit(alloc);
        if (!revision.matches(current)) return false;
        try self.saveArtifactRepairIssueWithSummary(alloc, key, issue, false, &.{}, &.{});
        return true;
    }

    fn rebuildArtifactRepairSummaryIfMissing(self: *DB, alloc: Allocator) !bool {
        // Issue writers publish the ledger mutation and summary invalidation in
        // one store batch under this mutex. Hold the same fence for each bounded
        // rebuild quantum so a writer cannot commit a dirty marker after our
        // scan and then have final publication overwrite it with stale `ready`.
        lockAtomicWithBackoff(&self.async_context.artifact_repair_issue_mutex);
        defer self.async_context.artifact_repair_issue_mutex.unlock();
        if (try self.artifactRepairSummaryReady(alloc)) return false;

        const root_summary_key = try internal_keys.artifactRepairSummaryRootKeyAlloc(alloc);
        defer alloc.free(root_summary_key);
        const rebuild_root_summary_key = try internal_keys.artifactRepairSummaryRebuildRootKeyAlloc(alloc);
        defer alloc.free(rebuild_root_summary_key);
        const progress_key = try internal_keys.artifactRepairSummaryProgressKeyAlloc(alloc);
        defer alloc.free(progress_key);
        const raw_progress = self.core.store.get(alloc, progress_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        defer if (raw_progress) |value| alloc.free(value);

        const invalidation_pending = if (raw_progress) |progress|
            std.mem.eql(u8, progress, artifact_repair_summary_dirty_marker)
        else
            false;
        if (invalidation_pending and try self.drainArtifactRepairSummaryRebuildInvalidationPage(alloc)) {
            return true;
        }

        if (!invalidation_pending and raw_progress == null) {
            var deletes = std.ArrayListUnmanaged([]const u8).empty;
            defer deletes.deinit(alloc);
            var owned_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
            defer {
                for (owned_delete_keys.items) |owned_key| alloc.free(@constCast(owned_key));
                owned_delete_keys.deinit(alloc);
            }
            try self.appendArtifactRepairSummaryRebuildInvalidation(alloc, null, &deletes, &owned_delete_keys);
            if (deletes.items.len != 0) {
                try self.core.store.putBatchWithReplayWithOptions(null, &.{}, deletes.items, null, .{ .defer_commit_flush = true });
            }
        }

        const prefix = try internal_keys.artifactRepairIssueRootPrefixAlloc(alloc);
        defer alloc.free(prefix);
        const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
        defer if (upper) |buf| alloc.free(buf);

        const lower = lower: {
            if (invalidation_pending) break :lower try alloc.dupe(u8, prefix);
            const progress = raw_progress orelse break :lower try alloc.dupe(u8, prefix);
            if (!std.mem.startsWith(u8, progress, prefix)) break :lower try alloc.dupe(u8, prefix);
            var lower = try alloc.alloc(u8, progress.len + 1);
            @memcpy(lower[0..progress.len], progress);
            lower[progress.len] = 0;
            break :lower lower;
        };
        defer alloc.free(lower);

        const ScanState = struct {
            const batch_limit: usize = 1024;

            alloc: Allocator,
            index_manager: *const index_manager_mod.IndexManager,
            root_count: u64 = 0,
            per_index: std.StringHashMapUnmanaged(u64) = .empty,
            // Keys are already encoded shadow-summary keys. This avoids a
            // second composite identity codec and lets publication switch the
            // namespace byte exactly like every other shadow counter.
            per_source: std.StringHashMapUnmanaged(u64) = .empty,
            rows: usize = 0,
            last_key: ?[]u8 = null,

            pub fn deinit(state: *@This()) void {
                var it = state.per_index.iterator();
                while (it.next()) |entry| state.alloc.free(entry.key_ptr.*);
                state.per_index.deinit(state.alloc);
                var source_it = state.per_source.iterator();
                while (source_it.next()) |entry| state.alloc.free(entry.key_ptr.*);
                state.per_source.deinit(state.alloc);
                if (state.last_key) |key| state.alloc.free(key);
            }

            fn addSource(state: *@This(), index_name: []const u8, configured_source: []const u8) !void {
                if (configured_source.len == 0) return;
                const source_key = try internal_keys.artifactRepairSummaryRebuildSourceKeyAlloc(
                    state.alloc,
                    index_name,
                    configured_source,
                );
                const source_result = try state.per_source.getOrPut(state.alloc, source_key);
                if (source_result.found_existing) {
                    state.alloc.free(source_key);
                } else {
                    source_result.key_ptr.* = source_key;
                    source_result.value_ptr.* = 0;
                }
                source_result.value_ptr.* += 1;
            }

            fn addIssueSources(state: *@This(), issue: types.ArtifactRepairIssue) !void {
                if (issue.index_source_artifact_name.len > 0) {
                    return state.addSource(issue.index_name, issue.index_source_artifact_name);
                }

                const configured = try state.index_manager.artifactSourceNamesForIndexAlloc(state.alloc, issue.index_name);
                defer {
                    for (configured) |name| state.alloc.free(name);
                    if (configured.len > 0) state.alloc.free(configured);
                }
                for (configured) |name| {
                    if (std.mem.eql(u8, name, issue.artifact_name)) {
                        return state.addSource(issue.index_name, name);
                    }
                }

                // Old graph repair records did not carry configured-source
                // identity for resolution and materialized-edge failures. Such
                // debt cannot be attributed safely after the fact, so fail
                // closed for every configured graph source rather than publish
                // a false source-local ready state.
                if (issue.artifact_kind == .graph and configured.len > 0) {
                    for (configured) |name| try state.addSource(issue.index_name, name);
                    return;
                }
                try state.addSource(issue.index_name, issue.artifact_name);
            }

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                var issue = try decodeArtifactRepairIssueValueAlloc(state.alloc, value);
                defer issue.deinit(state.alloc);
                state.root_count += 1;
                state.rows += 1;
                const result = try state.per_index.getOrPut(state.alloc, issue.index_name);
                if (!result.found_existing) {
                    result.key_ptr.* = try state.alloc.dupe(u8, issue.index_name);
                    result.value_ptr.* = 0;
                }
                result.value_ptr.* += 1;
                try state.addIssueSources(issue);
                if (state.last_key) |existing| state.alloc.free(existing);
                state.last_key = try state.alloc.dupe(u8, key);
                if (state.rows >= batch_limit) return .stop;
                return .@"continue";
            }
        };

        var state = ScanState{ .alloc = alloc, .index_manager = self.core.index_manager };
        defer state.deinit();
        try self.core.store.scanWithContext(lower, if (upper) |buf| buf else "", .{}, &state, ScanState.scanEntry);

        var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        var owned_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (writes.items) |item| alloc.free(@constCast(item.value));
            for (owned_keys.items) |owned_key| alloc.free(@constCast(owned_key));
            owned_keys.deinit(alloc);
            writes.deinit(alloc);
        }
        var deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer deletes.deinit(alloc);

        if (state.rows < ScanState.batch_limit) {
            var publish_counts = std.StringHashMapUnmanaged(u64).empty;
            defer {
                publish_counts.deinit(alloc);
            }

            const PublishState = struct {
                alloc: Allocator,
                counts: *std.StringHashMapUnmanaged(u64),
                deletes: *std.ArrayListUnmanaged([]const u8),
                owned_keys: *std.ArrayListUnmanaged([]const u8),

                fn addCount(ctx: *@This(), live_key: []u8, value: u64) !void {
                    errdefer ctx.alloc.free(live_key);
                    const result = try ctx.counts.getOrPut(ctx.alloc, live_key);
                    if (result.found_existing) {
                        ctx.alloc.free(live_key);
                        result.value_ptr.* += value;
                    } else {
                        try ctx.owned_keys.append(ctx.alloc, live_key);
                        result.key_ptr.* = live_key;
                        result.value_ptr.* = value;
                    }
                }

                fn scanEntry(ctx_raw: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                    const ctx: *@This() = @ptrCast(@alignCast(ctx_raw orelse return error.InvalidArgument));
                    if (value.len != @sizeOf(u64)) return error.InvalidArtifactPayload;
                    const shadow_key = try ctx.alloc.dupe(u8, key);
                    errdefer ctx.alloc.free(shadow_key);
                    const owned_len = ctx.owned_keys.items.len;
                    try ctx.owned_keys.append(ctx.alloc, shadow_key);
                    errdefer ctx.owned_keys.shrinkRetainingCapacity(owned_len);
                    try ctx.deletes.append(ctx.alloc, shadow_key);
                    const count = std.mem.readInt(u64, value[0..8], .little);
                    var live_key = try ctx.alloc.dupe(u8, key);
                    live_key[2] = internal_keys.artifact_repair_summary_kind;
                    try ctx.addCount(live_key, count);
                    return .@"continue";
                }
            };

            try self.appendKeysForPrefixDelete(alloc, &deletes, &owned_keys, root_summary_key);
            var publish_state = PublishState{
                .alloc = alloc,
                .counts = &publish_counts,
                .deletes = &deletes,
                .owned_keys = &owned_keys,
            };
            const rebuild_upper = try internal_keys.nextPrefixAlloc(alloc, rebuild_root_summary_key);
            defer if (rebuild_upper) |buf| alloc.free(buf);
            try self.core.store.scanWithContext(
                rebuild_root_summary_key,
                if (rebuild_upper) |buf| buf else "",
                .{},
                &publish_state,
                PublishState.scanEntry,
            );

            if (state.root_count != 0) {
                const live_key = try alloc.dupe(u8, root_summary_key);
                try PublishState.addCount(&publish_state, live_key, state.root_count);
            }

            var it = state.per_index.iterator();
            while (it.next()) |entry| {
                const live_key = try internal_keys.artifactRepairSummaryIndexKeyAlloc(alloc, entry.key_ptr.*);
                try PublishState.addCount(&publish_state, live_key, entry.value_ptr.*);
            }

            var source_it = state.per_source.iterator();
            while (source_it.next()) |entry| {
                var live_key = try alloc.dupe(u8, entry.key_ptr.*);
                live_key[2] = internal_keys.artifact_repair_summary_kind;
                try PublishState.addCount(&publish_state, live_key, entry.value_ptr.*);
            }

            var count_it = publish_counts.iterator();
            while (count_it.next()) |entry| {
                if (entry.value_ptr.* == 0) continue;
                const value = try alloc.alloc(u8, @sizeOf(u64));
                std.mem.writeInt(u64, value[0..8], entry.value_ptr.*, .little);
                try writes.append(alloc, .{ .key = entry.key_ptr.*, .value = value });
            }

            const ready_key = try internal_keys.artifactRepairSummaryReadyKeyAlloc(alloc);
            try owned_keys.append(alloc, ready_key);
            const ready_value = try alloc.dupe(u8, artifact_repair_summary_ready_marker);
            try writes.append(alloc, .{ .key = ready_key, .value = ready_value });
            try deletes.append(alloc, progress_key);
        } else if (state.last_key) |last_key| {
            if (state.root_count != 0) {
                try self.appendArtifactRepairSummaryWrite(alloc, &writes, &deletes, rebuild_root_summary_key, @intCast(state.root_count));
            }

            var it = state.per_index.iterator();
            while (it.next()) |entry| {
                const key = try internal_keys.artifactRepairSummaryRebuildIndexKeyAlloc(alloc, entry.key_ptr.*);
                try owned_keys.append(alloc, key);
                try self.appendArtifactRepairSummaryWrite(alloc, &writes, &deletes, key, @intCast(entry.value_ptr.*));
            }

            var source_it = state.per_source.iterator();
            while (source_it.next()) |entry| {
                try self.appendArtifactRepairSummaryWrite(
                    alloc,
                    &writes,
                    &deletes,
                    entry.key_ptr.*,
                    @intCast(entry.value_ptr.*),
                );
            }

            const progress_key_copy = try alloc.dupe(u8, progress_key);
            try owned_keys.append(alloc, progress_key_copy);
            const progress_value = try alloc.dupe(u8, last_key);
            try writes.append(alloc, .{ .key = progress_key_copy, .value = progress_value });
            try self.core.store.putBatchWithReplayWithOptions(null, writes.items, deletes.items, null, .{ .defer_commit_flush = true });
            return true;
        }
        try self.core.store.putBatchWithReplayWithOptions(null, writes.items, deletes.items, null, .{ .defer_commit_flush = true });
        return false;
    }

    fn drainArtifactRepairSummaryRebuildInvalidationPage(self: *DB, alloc: Allocator) !bool {
        const prefix = try internal_keys.artifactRepairSummaryRebuildRootKeyAlloc(alloc);
        defer alloc.free(prefix);
        const rows = try self.core.store.scanPrefixPage(
            alloc,
            prefix,
            null,
            artifact_repair_summary_invalidation_page_size,
        );
        defer docstore_mod.DocStore.freeResults(alloc, rows);
        if (rows.len == 0) return false;

        const deletes = try alloc.alloc([]const u8, rows.len);
        defer alloc.free(deletes);
        for (rows, 0..) |row, i| deletes[i] = row.key;
        try self.core.store.putBatchWithReplayWithOptions(
            null,
            &.{},
            deletes,
            null,
            .{ .defer_commit_flush = true },
        );
        return true;
    }

    fn artifactRepairKindIndexReady(self: *DB, alloc: Allocator) !bool {
        const ready_key = try internal_keys.artifactRepairKindIndexReadyKeyAlloc(alloc);
        defer alloc.free(ready_key);
        const ready = self.core.store.get(alloc, ready_key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        alloc.free(ready);
        return true;
    }

    fn rebuildArtifactRepairKindIndexIfMissing(self: *DB, alloc: Allocator) !bool {
        if (try self.artifactRepairKindIndexReady(alloc)) return false;

        const prefix = try internal_keys.artifactRepairIssueRootPrefixAlloc(alloc);
        defer alloc.free(prefix);
        const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
        defer if (upper) |buf| alloc.free(buf);

        const progress_key = try internal_keys.artifactRepairKindIndexProgressKeyAlloc(alloc);
        defer alloc.free(progress_key);
        const raw_progress = self.core.store.get(alloc, progress_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        defer if (raw_progress) |value| alloc.free(value);

        const lower = lower: {
            const progress = raw_progress orelse break :lower try alloc.dupe(u8, prefix);
            if (!std.mem.startsWith(u8, progress, prefix)) break :lower try alloc.dupe(u8, prefix);
            var lower = try alloc.alloc(u8, progress.len + 1);
            @memcpy(lower[0..progress.len], progress);
            lower[progress.len] = 0;
            break :lower lower;
        };
        defer alloc.free(lower);

        var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer {
            for (writes.items) |item| {
                alloc.free(@constCast(item.key));
                alloc.free(@constCast(item.value));
            }
            writes.deinit(alloc);
        }

        const ScanState = struct {
            const batch_limit: usize = 1024;

            alloc: Allocator,
            writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
            rows: usize = 0,
            last_key: ?[]u8 = null,

            pub fn deinit(state: *@This()) void {
                if (state.last_key) |key| state.alloc.free(key);
            }

            fn scanEntry(ctx: ?*anyopaque, _: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                var issue = try decodeArtifactRepairIssueValueAlloc(state.alloc, value);
                defer issue.deinit(state.alloc);

                const kind_key = try artifactRepairIssueKindKeyForIssueAlloc(state.alloc, issue);
                errdefer state.alloc.free(kind_key);
                const value_copy = try state.alloc.dupe(u8, value);
                errdefer state.alloc.free(value_copy);
                try state.writes.append(state.alloc, .{ .key = kind_key, .value = value_copy });
                state.rows += 1;
                if (state.last_key) |key| state.alloc.free(key);
                state.last_key = try artifactRepairIssueKeyForIssueAlloc(state.alloc, issue);
                if (state.rows >= batch_limit) return .stop;
                return .@"continue";
            }
        };

        var state = ScanState{ .alloc = alloc, .writes = &writes };
        defer state.deinit();
        try self.core.store.scanWithContext(lower, if (upper) |buf| buf else "", .{}, &state, ScanState.scanEntry);

        if (state.rows < ScanState.batch_limit) {
            const ready_key = try internal_keys.artifactRepairKindIndexReadyKeyAlloc(alloc);
            errdefer alloc.free(ready_key);
            const ready_value = try alloc.dupe(u8, "1");
            errdefer alloc.free(ready_value);
            try writes.append(alloc, .{ .key = ready_key, .value = ready_value });
            const deletes = [_][]const u8{progress_key};
            try self.core.store.putBatchWithReplayWithOptions(null, writes.items, deletes[0..], null, .{ .defer_commit_flush = true });
            return false;
        }

        if (state.last_key) |last_key| {
            const progress_key_copy = try alloc.dupe(u8, progress_key);
            errdefer alloc.free(progress_key_copy);
            const progress_value = try alloc.dupe(u8, last_key);
            errdefer alloc.free(progress_value);
            try writes.append(alloc, .{ .key = progress_key_copy, .value = progress_value });
        }

        try self.core.store.putBatchWithReplayWithOptions(null, writes.items, &.{}, null, .{ .defer_commit_flush = true });
        return true;
    }

    pub fn recordArtifactRepairIssue(
        self: *DB,
        alloc: Allocator,
        issue: types.ArtifactRepairIssue,
    ) !void {
        lockAtomicWithBackoff(&self.async_context.artifact_repair_issue_mutex);
        defer self.async_context.artifact_repair_issue_mutex.unlock();
        const key = try self.repairIssueKeyForIssueAlloc(alloc, issue);
        defer alloc.free(key);

        const now_ns = currentTimeNs();
        const existing = try self.loadArtifactRepairIssueByKey(alloc, key);
        const existing_was_pending = if (existing) |loaded| loaded.reason == .enrichment_failed else false;
        const previous_terminal_sequence: ?u64 = if (existing) |loaded|
            if (loaded.reason == .enrichment_failed) loaded.sequence else null
        else
            null;
        var stored = if (existing) |loaded|
            loaded
        else
            try cloneArtifactRepairIssueAlloc(alloc, issue);
        defer stored.deinit(alloc);

        stored.artifact_kind = issue.artifact_kind;
        stored.sequence = issue.sequence;
        stored.reason = issue.reason;
        try applyArtifactRepairability(alloc, &stored);
        if (stored.first_seen_ns == 0) stored.first_seen_ns = now_ns;
        stored.last_seen_ns = nextArtifactRepairIssueTimestamp(stored.last_seen_ns, now_ns);
        if (stored.artifact_key.len == 0 and issue.artifact_key.len > 0) {
            stored.artifact_key = try alloc.dupe(u8, issue.artifact_key);
        }
        if (stored.parent_doc_key.len == 0 and issue.parent_doc_key.len > 0) {
            stored.parent_doc_key = try alloc.dupe(u8, issue.parent_doc_key);
        }
        if (stored.unit_id.len == 0 and issue.unit_id.len > 0) {
            stored.unit_id = try alloc.dupe(u8, issue.unit_id);
        }
        if (stored.source_artifact_name.len == 0 and issue.source_artifact_name.len > 0) {
            stored.source_artifact_name = try alloc.dupe(u8, issue.source_artifact_name);
        }

        const completion_key = try self.artifactRepairCompletionKeyForIssueAlloc(alloc, stored);
        defer alloc.free(completion_key);
        var completion = (try self.loadArtifactRepairCompletionState(alloc, completion_key)) orelse ArtifactRepairCompletionState{
            .pending_issues = @intFromBool(existing_was_pending),
        };
        if (existing_was_pending) completion.pending_issues = @max(completion.pending_issues, 1);
        if (stored.reason == .enrichment_failed) {
            var marker_deletes = std.ArrayListUnmanaged([]const u8).empty;
            defer marker_deletes.deinit(alloc);
            var owned_marker_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
            defer {
                for (owned_marker_delete_keys.items) |marker_key| alloc.free(@constCast(marker_key));
                owned_marker_delete_keys.deinit(alloc);
            }
            var terminal_marker = try EnrichmentTerminalFailureMarkerWrite.init(
                alloc,
                self.core.store,
                key,
                previous_terminal_sequence,
                stored.sequence,
                &marker_deletes,
                &owned_marker_delete_keys,
            );
            defer terminal_marker.deinit(alloc);
            completion.epoch +%= 1;
            if (completion.epoch == 0) completion.epoch = 1;
            completion.completed_sequence = 0;
            if (!existing_was_pending) completion.pending_issues +|= 1;
            var encoded_completion: [artifact_repair_completion_state_len]u8 = undefined;
            encodeArtifactRepairCompletionState(&encoded_completion, completion);
            try self.saveArtifactRepairIssueWithSummary(
                alloc,
                key,
                stored,
                existing == null,
                &.{
                    .{ .key = completion_key, .value = &encoded_completion },
                    .{ .key = &internal_keys.enrichment_terminal_failure_generation_counter_key, .value = &terminal_marker.generation_counter_value },
                    .{ .key = terminal_marker.generation_key, .value = &terminal_marker.generation_value },
                    .{ .key = terminal_marker.marker.sequence_key, .value = terminal_marker.marker_value },
                    .{ .key = terminal_marker.marker.issue_key, .value = terminal_marker.marker.sequence_key },
                },
                marker_deletes.items,
            );
        } else {
            var marker_deletes = std.ArrayListUnmanaged([]const u8).empty;
            defer marker_deletes.deinit(alloc);
            var owned_marker_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
            defer {
                for (owned_marker_delete_keys.items) |marker_key| alloc.free(@constCast(marker_key));
                owned_marker_delete_keys.deinit(alloc);
            }
            try appendEnrichmentTerminalFailureMarkerDeletesForIssue(
                alloc,
                self.core.store,
                key,
                &marker_deletes,
                &owned_marker_delete_keys,
                true,
            );
            try marker_deletes.append(alloc, completion_key);
            try self.saveArtifactRepairIssueWithSummary(alloc, key, stored, existing == null, &.{}, marker_deletes.items);
        }
    }

    fn recordEmbeddingArtifactRepairIssue(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        artifact_key: []const u8,
        sequence: u64,
        reason: types.ArtifactRepairReason,
    ) !void {
        lockAtomicWithBackoff(&self.async_context.artifact_repair_issue_mutex);
        defer self.async_context.artifact_repair_issue_mutex.unlock();
        var identity = (try artifact_ids.decodeEmbeddingArtifactIdentityAlloc(alloc, artifact_key)) orelse return;
        defer identity.deinit(alloc);

        const artifact_key_hex = try bytesToHexAlloc(alloc, artifact_key);
        defer alloc.free(artifact_key_hex);
        const key = try internal_keys.artifactRepairIssueKeyAlloc(alloc, index_name, "embedding", artifact_key_hex);
        defer alloc.free(key);

        const now_ns = currentTimeNs();
        const existing = try self.loadArtifactRepairIssueByKey(alloc, key);
        const existing_was_pending = if (existing) |loaded| loaded.reason == .enrichment_failed else false;
        const previous_terminal_sequence: ?u64 = if (existing) |loaded|
            if (loaded.reason == .enrichment_failed) loaded.sequence else null
        else
            null;
        var issue = if (existing) |loaded|
            loaded
        else
            types.ArtifactRepairIssue{
                .artifact_kind = .embedding,
                .index_name = try alloc.dupe(u8, index_name),
                .doc_key = try alloc.dupe(u8, identity.doc_key),
                .parent_doc_key = try alloc.dupe(u8, identity.parent_doc_key orelse ""),
                .unit_id = try alloc.dupe(u8, identity.unit_id orelse ""),
                .source_artifact_name = try alloc.dupe(u8, identity.source_artifact_name orelse ""),
                .artifact_name = try alloc.dupe(u8, identity.embedding_name),
                .artifact_key = try alloc.dupe(u8, artifact_key_hex),
                .chunk_id = identity.chunk_id,
                .repairable = artifactRepairReasonHasAutomatedReprocessor(.embedding, reason),
                .first_seen_ns = now_ns,
            };
        defer issue.deinit(alloc);

        issue.sequence = sequence;
        issue.reason = reason;
        issue.chunk_id = identity.chunk_id;
        try applyArtifactRepairability(alloc, &issue);
        issue.last_seen_ns = nextArtifactRepairIssueTimestamp(issue.last_seen_ns, now_ns);
        if (issue.artifact_key.len == 0) {
            issue.artifact_key = try alloc.dupe(u8, artifact_key_hex);
        }
        if (issue.parent_doc_key.len == 0) {
            issue.parent_doc_key = try alloc.dupe(u8, identity.parent_doc_key orelse "");
        }
        if (issue.unit_id.len == 0) {
            issue.unit_id = try alloc.dupe(u8, identity.unit_id orelse "");
        }
        if (issue.source_artifact_name.len == 0) {
            issue.source_artifact_name = try alloc.dupe(u8, identity.source_artifact_name orelse "");
        }

        const completion_key = try internal_keys.artifactRepairCompletionKeyAlloc(alloc, "embedding", artifact_key_hex);
        defer alloc.free(completion_key);
        var completion = (try self.loadArtifactRepairCompletionState(alloc, completion_key)) orelse ArtifactRepairCompletionState{
            .pending_issues = @intFromBool(existing_was_pending),
        };
        if (existing_was_pending) completion.pending_issues = @max(completion.pending_issues, 1);
        if (reason == .enrichment_failed) {
            var marker_deletes = std.ArrayListUnmanaged([]const u8).empty;
            defer marker_deletes.deinit(alloc);
            var owned_marker_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
            defer {
                for (owned_marker_delete_keys.items) |marker_key| alloc.free(@constCast(marker_key));
                owned_marker_delete_keys.deinit(alloc);
            }
            var terminal_marker = try EnrichmentTerminalFailureMarkerWrite.init(
                alloc,
                self.core.store,
                key,
                previous_terminal_sequence,
                sequence,
                &marker_deletes,
                &owned_marker_delete_keys,
            );
            defer terminal_marker.deinit(alloc);
            completion.epoch +%= 1;
            if (completion.epoch == 0) completion.epoch = 1;
            completion.completed_sequence = 0;
            if (!existing_was_pending) completion.pending_issues +|= 1;
            var encoded_completion: [artifact_repair_completion_state_len]u8 = undefined;
            encodeArtifactRepairCompletionState(&encoded_completion, completion);
            try self.saveArtifactRepairIssueWithSummary(
                alloc,
                key,
                issue,
                existing == null,
                &.{
                    .{ .key = completion_key, .value = &encoded_completion },
                    .{ .key = &internal_keys.enrichment_terminal_failure_generation_counter_key, .value = &terminal_marker.generation_counter_value },
                    .{ .key = terminal_marker.generation_key, .value = &terminal_marker.generation_value },
                    .{ .key = terminal_marker.marker.sequence_key, .value = terminal_marker.marker_value },
                    .{ .key = terminal_marker.marker.issue_key, .value = terminal_marker.marker.sequence_key },
                },
                marker_deletes.items,
            );
        } else {
            var marker_deletes = std.ArrayListUnmanaged([]const u8).empty;
            defer marker_deletes.deinit(alloc);
            var owned_marker_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
            defer {
                for (owned_marker_delete_keys.items) |marker_key| alloc.free(@constCast(marker_key));
                owned_marker_delete_keys.deinit(alloc);
            }
            try appendEnrichmentTerminalFailureMarkerDeletesForIssue(
                alloc,
                self.core.store,
                key,
                &marker_deletes,
                &owned_marker_delete_keys,
                true,
            );
            try marker_deletes.append(alloc, completion_key);
            try self.saveArtifactRepairIssueWithSummary(alloc, key, issue, existing == null, &.{}, marker_deletes.items);
        }
    }

    fn artifactRepairScanLowerBoundAlloc(
        self: *DB,
        alloc: Allocator,
        prefix: []const u8,
        cursor: ?[]const u8,
    ) ![]u8 {
        _ = self;
        const raw_cursor = cursor orelse return try alloc.dupe(u8, prefix);
        if (raw_cursor.len == 0) return try alloc.dupe(u8, prefix);
        const key = hexToBytesAlloc(alloc, raw_cursor) catch return error.InvalidArgument;
        defer alloc.free(key);
        if (!std.mem.startsWith(u8, key, prefix)) return error.InvalidArgument;
        var lower = try alloc.alloc(u8, key.len + 1);
        @memcpy(lower[0..key.len], key);
        lower[key.len] = 0;
        return lower;
    }

    fn artifactRepairCursorMatchesPrefix(self: *DB, alloc: Allocator, cursor: ?[]const u8, prefix: []const u8) !bool {
        _ = self;
        const raw_cursor = cursor orelse return true;
        if (raw_cursor.len == 0) return true;
        const key = hexToBytesAlloc(alloc, raw_cursor) catch return false;
        defer alloc.free(key);
        return std.mem.startsWith(u8, key, prefix);
    }

    fn artifactRepairPrimaryScanPrefixAlloc(self: *DB, alloc: Allocator, req: types.ArtifactRepairListRequest) ![]u8 {
        _ = self;
        if (req.index_name) |name| return try internal_keys.artifactRepairIssueIndexPrefixAlloc(alloc, name);
        return try internal_keys.artifactRepairIssueRootPrefixAlloc(alloc);
    }

    fn artifactRepairKindScanPrefixAlloc(self: *DB, alloc: Allocator, req: types.ArtifactRepairListRequest, kind: types.ArtifactRepairKind) ![]u8 {
        _ = self;
        if (req.index_name) |name| return try internal_keys.artifactRepairIssueKindIndexPrefixAlloc(alloc, @tagName(kind), name);
        return try internal_keys.artifactRepairIssueKindRootPrefixAlloc(alloc, @tagName(kind));
    }

    fn artifactRepairFallbackScanBudget(limit: u32) u64 {
        const requested: u64 = if (limit == 0) 4096 else @as(u64, limit) * 32;
        return @min(@max(requested, 256), 4096);
    }

    fn artifactRepairKindForIndexKind(kind: types.IndexKind) ?types.ArtifactRepairKind {
        return switch (kind) {
            .dense_vector, .sparse_vector => .embedding,
            .graph => .graph,
            .full_text => .full_text,
            .algebraic => .algebraic,
        };
    }

    fn listIndexRepairIssuesPage(
        self: *DB,
        alloc: Allocator,
        req: types.ArtifactRepairListRequest,
    ) !types.ArtifactRepairListResult {
        const configs = try self.core.listIndexes(alloc);
        defer types.freeIndexConfigs(alloc, configs);
        std.mem.sort(types.IndexConfig, configs, {}, struct {
            fn lessThan(_: void, lhs: types.IndexConfig, rhs: types.IndexConfig) bool {
                return std.mem.order(u8, lhs.name, rhs.name) == .lt;
            }
        }.lessThan);

        var issues = std.ArrayListUnmanaged(types.ArtifactRepairIssue).empty;
        errdefer {
            for (issues.items) |*issue| issue.deinit(alloc);
            issues.deinit(alloc);
        }

        const cursor = req.cursor orelse "";
        var last_returned: ?[]const u8 = null;
        var has_more = false;
        var scanned: u64 = 0;
        for (configs) |cfg| {
            if (cursor.len != 0 and std.mem.order(u8, cfg.name, cursor) != .gt) continue;
            if (req.index_name) |requested| {
                if (!std.mem.eql(u8, requested, cfg.name)) continue;
            }
            const artifact_kind = artifactRepairKindForIndexKind(cfg.kind) orelse continue;
            if (req.artifact_kind) |requested_kind| {
                if (requested_kind != artifact_kind) continue;
            }
            if (!(try self.indexGenerationRepairRequired(alloc, cfg.name))) continue;
            scanned += 1;
            if (req.limit != 0 and issues.items.len >= req.limit) {
                has_more = true;
                break;
            }

            const load_error = self.core.index_manager.loadFailure(cfg.name);
            try issues.append(alloc, .{
                .artifact_kind = artifact_kind,
                .index_name = try alloc.dupe(u8, cfg.name),
                .artifact_name = try alloc.dupe(u8, cfg.name),
                .repairable = true,
                .unsupported_reason = "",
                .reason = if (load_error != null) .unreadable_artifact else .missing_artifact,
                .last_error = if (load_error) |err_name| try alloc.dupe(u8, err_name) else try alloc.dupe(u8, "index_repair_required"),
            });
            last_returned = cfg.name;
        }

        return .{
            .issues = try issues.toOwnedSlice(alloc),
            .limit = req.limit,
            .scanned = scanned,
            .next_cursor = if (has_more and last_returned != null) try alloc.dupe(u8, last_returned.?) else null,
            .has_more = has_more,
        };
    }

    pub fn listArtifactRepairIssuesPage(
        self: *DB,
        alloc: Allocator,
        req: types.ArtifactRepairListRequest,
    ) !types.ArtifactRepairListResult {
        if (req.target == .index) return try self.listIndexRepairIssuesPage(alloc, req);

        var filtering_without_kind_index = false;
        const prefix = if (req.artifact_kind) |kind| prefix_blk: {
            if (try self.artifactRepairKindIndexReady(alloc)) {
                const kind_prefix = try self.artifactRepairKindScanPrefixAlloc(alloc, req, kind);
                if (try self.artifactRepairCursorMatchesPrefix(alloc, req.cursor, kind_prefix)) break :prefix_blk kind_prefix;
                alloc.free(kind_prefix);
            }
            filtering_without_kind_index = true;
            break :prefix_blk try self.artifactRepairPrimaryScanPrefixAlloc(alloc, req);
        } else try self.artifactRepairPrimaryScanPrefixAlloc(alloc, req);
        defer alloc.free(prefix);
        const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
        defer if (upper) |buf| alloc.free(buf);
        const lower = try self.artifactRepairScanLowerBoundAlloc(alloc, prefix, req.cursor);
        defer alloc.free(lower);

        const ScanState = struct {
            alloc: Allocator,
            db: *DB,
            artifact_kind: ?types.ArtifactRepairKind,
            limit: u32,
            scan_budget: u64,
            scanned: u64 = 0,
            has_more: bool = false,
            last_cursor: ?[]u8 = null,
            issues: std.ArrayListUnmanaged(types.ArtifactRepairIssue) = .empty,

            fn deinitPartial(state: *@This()) void {
                for (state.issues.items) |*issue| issue.deinit(state.alloc);
                state.issues.deinit(state.alloc);
                if (state.last_cursor) |cursor| state.alloc.free(cursor);
            }

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                if (state.limit != 0 and state.issues.items.len >= state.limit) {
                    state.has_more = true;
                    return .stop;
                }
                state.scanned += 1;
                if (state.last_cursor) |cursor| state.alloc.free(cursor);
                state.last_cursor = try bytesToHexAlloc(state.alloc, key);
                var issue = try state.db.decodeArtifactRepairIssueAlloc(state.alloc, value);
                errdefer issue.deinit(state.alloc);
                if (state.artifact_kind) |kind| {
                    if (issue.artifact_kind != kind) {
                        issue.deinit(state.alloc);
                        if (state.scan_budget != 0 and state.scanned >= state.scan_budget) {
                            state.has_more = true;
                            return .stop;
                        }
                        return .@"continue";
                    }
                }
                try state.issues.append(state.alloc, issue);
                if (state.scan_budget != 0 and state.scanned >= state.scan_budget) {
                    state.has_more = true;
                    return .stop;
                }
                return .@"continue";
            }
        };

        var state = ScanState{
            .alloc = alloc,
            .db = self,
            .artifact_kind = req.artifact_kind,
            .limit = req.limit,
            .scan_budget = if (filtering_without_kind_index) artifactRepairFallbackScanBudget(req.limit) else 0,
        };
        errdefer state.deinitPartial();
        try self.core.store.scanWithContext(lower, if (upper) |buf| buf else "", .{}, &state, ScanState.scanEntry);
        const issues = try state.issues.toOwnedSlice(alloc);
        state.issues = .empty;
        const next_cursor = if (state.has_more) state.last_cursor else null;
        if (!state.has_more) {
            if (state.last_cursor) |cursor| alloc.free(cursor);
        }
        state.last_cursor = null;
        return .{
            .issues = issues,
            .limit = req.limit,
            .scanned = state.scanned,
            .next_cursor = next_cursor,
            .has_more = state.has_more,
        };
    }

    pub fn listArtifactRepairIssues(
        self: *DB,
        alloc: Allocator,
        artifact_kind: ?types.ArtifactRepairKind,
        index_name: ?[]const u8,
        limit: usize,
    ) ![]types.ArtifactRepairIssue {
        const page = try self.listArtifactRepairIssuesPage(alloc, .{
            .artifact_kind = artifact_kind,
            .index_name = index_name,
            .limit = @intCast(@min(limit, std.math.maxInt(u32))),
        });
        if (page.next_cursor) |cursor| alloc.free(cursor);
        return page.issues;
    }

    pub fn listEmbeddingArtifactRepairIssues(
        self: *DB,
        alloc: Allocator,
        index_name: ?[]const u8,
        limit: usize,
    ) ![]types.EmbeddingArtifactRepairIssue {
        const generic = try self.listArtifactRepairIssues(alloc, .embedding, index_name, limit);
        defer types.freeArtifactRepairIssues(alloc, generic);

        var issues = try alloc.alloc(types.EmbeddingArtifactRepairIssue, generic.len);
        var count: usize = 0;
        errdefer {
            for (issues[0..count]) |*issue| issue.deinit(alloc);
            alloc.free(issues);
        }
        for (generic) |issue| {
            issues[count] = try types.embeddingArtifactRepairIssueFromArtifactAlloc(alloc, issue);
            count += 1;
        }
        return issues;
    }

    fn clearArtifactRepairIssue(self: *DB, alloc: Allocator, issue: types.ArtifactRepairIssue) !void {
        try self.clearArtifactRepairIssueWithSummary(alloc, issue);
    }

    fn artifactNowReadable(self: *DB, alloc: Allocator, issue: types.ArtifactRepairIssue) !bool {
        return switch (issue.artifact_kind) {
            .embedding => try self.embeddingArtifactNowReadable(alloc, issue),
            .asset => try self.assetArtifactNowReadable(alloc, issue),
            .chunk, .graph, .full_text, .algebraic => false,
        };
    }

    fn assetArtifactNowReadable(self: *DB, alloc: Allocator, issue: types.ArtifactRepairIssue) !bool {
        const doc_key = if (issue.parent_doc_key.len > 0) issue.parent_doc_key else issue.doc_key;
        if (doc_key.len == 0 or issue.artifact_name.len == 0) return false;
        var cfg = (try self.getEnrichment(alloc, .asset, issue.artifact_name)) orelse return false;
        defer cfg.deinit(alloc);
        var producer_cfg = try asset_producer_mod.parseProducerConfig(alloc, cfg.producer_json);
        defer producer_cfg.deinit(alloc);

        const expected_key = try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "asset", issue.artifact_name);
        defer alloc.free(expected_key);
        if (issue.artifact_key.len > 0) {
            const actual_key = try hexToBytesAlloc(alloc, issue.artifact_key);
            defer alloc.free(actual_key);
            if (!std.mem.eql(u8, actual_key, expected_key)) return false;
        }
        if (producer_cfg.type != .document_extraction) {
            const raw = self.core.store.get(alloc, expected_key) catch |err| switch (err) {
                error.NotFound => return false,
                else => return err,
            };
            defer alloc.free(raw);
            return true;
        }
        var manifest = (self.getDocumentArtifactManifest(alloc, doc_key, issue.artifact_name) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return false,
        }) orelse return false;
        defer manifest.deinit(alloc);
        return true;
    }

    fn embeddingArtifactNowReadable(self: *DB, alloc: Allocator, issue: types.ArtifactRepairIssue) !bool {
        if (issue.reason == .enrichment_failed and issue.source_artifact_name.len > 0 and issue.chunk_id == null) {
            // Request-scoped chunk generation may legitimately produce zero,
            // one, or many physical artifacts. The generation-scoped coverage
            // outcome is the authoritative completion fence after full_index
            // repair; probing one synthetic document key can never prove this
            // set healthy.
            const generation = self.core.index_manager.coverageGenerationForIndex(issue.index_name) orelse return false;
            const marker_key = try internal_keys.derivedCoverageOutcomeKeyAlloc(alloc, issue.index_name, generation, issue.doc_key);
            defer alloc.free(marker_key);
            const raw_outcome = self.core.store.get(alloc, marker_key) catch |err| switch (err) {
                error.NotFound => return false,
                else => return err,
            };
            defer alloc.free(raw_outcome);
            const outcome = std.meta.stringToEnum(DerivedCoverageOutcome, raw_outcome) orelse
                return error.InvalidDerivedCoverageOutcome;
            return outcome == .produced or outcome == .skipped;
        }

        const artifact_key = if (issue.artifact_key.len > 0)
            try hexToBytesAlloc(alloc, issue.artifact_key)
        else
            try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, issue.doc_key, issue.artifact_name);
        defer alloc.free(artifact_key);

        const raw = self.core.store.get(alloc, artifact_key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        defer alloc.free(raw);

        if (self.core.index_manager.denseIndex(issue.index_name)) |entry| {
            const view = enrichment_artifact_codec.denseEmbeddingVectorView(raw) catch |err| {
                if (isRecoverableEmbeddingArtifactError(err)) return false;
                return err;
            };
            if (view) |vector| return vector.len == entry.dims;
            const decoded = enrichment_artifact_codec.decodeDenseEmbeddingAlloc(alloc, raw) catch |err| {
                if (isRecoverableEmbeddingArtifactError(err)) return false;
                return err;
            };
            defer alloc.free(decoded);
            return decoded.len == entry.dims;
        }

        if (self.core.index_manager.sparseIndex(issue.index_name) != null) {
            if (enrichment_artifact_codec.sparseEmbeddingVectorView(raw)) |maybe_view| {
                if (maybe_view != null) return true;
            } else |err| {
                if (isRecoverableEmbeddingArtifactError(err)) return false;
                return err;
            }
            var decoded = enrichment_artifact_codec.decodeSparseEmbeddingAlloc(alloc, raw) catch |err| {
                if (isRecoverableEmbeddingArtifactError(err)) return false;
                return err;
            };
            decoded.deinit(alloc);
            return true;
        }
        return false;
    }

    fn reprocessArtifactIssue(
        self: *DB,
        alloc: Allocator,
        issue: types.ArtifactRepairIssue,
    ) !bool {
        return switch (issue.artifact_kind) {
            .embedding => try self.reprocessEmbeddingArtifactIssue(alloc, issue),
            .asset => try self.reprocessDocumentArtifact(alloc, if (issue.parent_doc_key.len > 0) issue.parent_doc_key else issue.doc_key, issue.artifact_name),
            .chunk => try self.reprocessChunkArtifactIssue(alloc, issue),
            .graph, .full_text, .algebraic => false,
        };
    }

    fn artifactRepairKindHasReprocessor(kind: types.ArtifactRepairKind) bool {
        return artifactRepairKindHasAutomatedReprocessor(kind);
    }

    pub const StartupIndexRepairDiscovery = struct {
        discovered: usize = 0,
        already_pending: usize = 0,
        terminal: usize = 0,
        existing_terminal: usize = 0,
        automatic_remaining: usize = 0,
        automatic_deferred: usize = 0,
        automatic_sweep_complete: bool = true,

        pub fn automaticDiscoveryPending(self: @This()) bool {
            return self.automatic_remaining != 0 and
                (!self.automatic_sweep_complete or self.automatic_deferred != 0);
        }
    };

    fn indexRepairStateLocation(self: *const DB) !index_repair_state.Location {
        return try indexRepairStateLocationContext(self.async_context);
    }

    fn indexRepairStateLocationContext(ctx: *const AsyncContext) !index_repair_state.Location {
        return ctx.index_repair_checkpoint orelse error.DurableIndexRepairStateUnavailable;
    }

    fn localRepairGroupId(self: *const DB) u64 {
        const namespace = self.core.identity_namespace;
        if (namespace.range_id != 0) return namespace.range_id;
        return namespace.shard_id;
    }

    pub fn hasPendingIndexRepairIntents(self: *const DB, alloc: Allocator) !bool {
        if (builtin.os.tag == .freestanding) return self.hasManagedIndexAdmissionMarker(alloc);
        const location = try self.indexRepairStateLocation();
        var state = index_repair_state.loadAt(alloc, location) catch |err| switch (err) {
            error.FileNotFound => return self.hasManagedIndexAdmissionMarker(alloc),
            else => return err,
        };
        defer state.deinit(alloc);
        if (state.entries.items.len != 0) return true;
        return self.hasManagedIndexAdmissionMarker(alloc);
    }

    fn hasManagedIndexAdmissionMarker(self: *const DB, alloc: Allocator) !bool {
        const admission_prefix = try internal_keys.managedIndexAdmissionRootPrefixAlloc(alloc);
        defer alloc.free(admission_prefix);
        const admissions = try self.core.store.scanPrefixPage(alloc, admission_prefix, null, 1);
        defer docstore_mod.DocStore.freeResults(alloc, admissions);
        return admissions.len != 0;
    }

    /// Authoritative owner wake decision. A tagged state prevents `0` from
    /// ambiguously meaning both "run now" and "nothing runnable" at scheduler
    /// boundaries.
    pub const IndexRepairWake = types.IndexRepairWake;

    pub const IndexRepairIntentSummary = @import("index_repair_scheduler.zig").Summary;

    /// Requires index_repair_scheduler_mutex.
    fn publishIndexRepairProgressWaitHint(ctx: *AsyncContext) void {
        ctx.index_repair_progress_wait_pending.store(
            ctx.index_repair_scheduler.initialized and
                ctx.index_repair_scheduler.progress_waiters != 0,
            .release,
        );
    }

    fn invalidateIndexRepairSchedulerDirectory(ctx: *AsyncContext) void {
        _ = ctx.index_repair_scheduler_revision.fetchAdd(1, .acq_rel);
        lockAtomic(&ctx.index_repair_scheduler_mutex);
        defer ctx.index_repair_scheduler_mutex.unlock();
        ctx.index_repair_scheduler.deinit(ctx.alloc);
        publishIndexRepairProgressWaitHint(ctx);
    }

    fn noteIndexRepairSchedulerUpsert(
        ctx: *AsyncContext,
        intent: index_repair_state.IndexRepairIntent,
        persisted_revision: u64,
        control_revision: u64,
    ) void {
        _ = ctx.index_repair_scheduler_revision.fetchAdd(1, .acq_rel);
        lockAtomic(&ctx.index_repair_scheduler_mutex);
        defer ctx.index_repair_scheduler_mutex.unlock();
        if (!ctx.index_repair_scheduler.initialized) {
            publishIndexRepairProgressWaitHint(ctx);
            return;
        }
        switch (ctx.index_repair_scheduler.classifyControlMutation(intent.identity(), control_revision)) {
            .stale => return,
            .gap => {
                ctx.index_repair_scheduler.deinit(ctx.alloc);
                publishIndexRepairProgressWaitHint(ctx);
                return;
            },
            .next => {},
        }
        ctx.index_repair_scheduler.upsert(ctx.alloc, intent, persisted_revision) catch {
            // The durable checkpoint remains authoritative. Allocation or a
            // consistency mismatch invalidates only the acceleration layer;
            // the next owner rebuilds it from the committed checkpoint.
            ctx.index_repair_scheduler.deinit(ctx.alloc);
            publishIndexRepairProgressWaitHint(ctx);
            return;
        };
        ctx.index_repair_scheduler.control_revision = control_revision;
        publishIndexRepairProgressWaitHint(ctx);
    }

    fn noteIndexRepairSchedulerRemove(
        ctx: *AsyncContext,
        identity: index_repair_state.ReplicaIdentity,
        repair_id: u128,
        control_revision: u64,
    ) void {
        _ = ctx.index_repair_scheduler_revision.fetchAdd(1, .acq_rel);
        lockAtomic(&ctx.index_repair_scheduler_mutex);
        defer ctx.index_repair_scheduler_mutex.unlock();
        if (!ctx.index_repair_scheduler.initialized) {
            publishIndexRepairProgressWaitHint(ctx);
            return;
        }
        switch (ctx.index_repair_scheduler.classifyControlMutation(identity, control_revision)) {
            .stale => return,
            .gap => {
                ctx.index_repair_scheduler.deinit(ctx.alloc);
                publishIndexRepairProgressWaitHint(ctx);
                return;
            },
            .next => {},
        }
        ctx.index_repair_scheduler.remove(ctx.alloc, repair_id);
        ctx.index_repair_scheduler.control_revision = control_revision;
        publishIndexRepairProgressWaitHint(ctx);
    }

    fn indexRepairNowMs(self: *const DB) u64 {
        return (self.index_repair_clock orelse self.backend_runtime.clock()).nowRealtimeMs();
    }

    const progressive_index_repair_audit_interval_ms: u64 = 5 * std.time.ms_per_s;

    fn deferIndexRepairForProgress(
        self: *DB,
        repair_id: u128,
        expected_revision: u64,
        wake_at_sequence: u64,
    ) bool {
        const fallback_at_ms = self.indexRepairNowMs() +|
            progressive_index_repair_audit_interval_ms;
        lockAtomic(&self.async_context.index_repair_scheduler_mutex);
        defer self.async_context.index_repair_scheduler_mutex.unlock();
        if (!self.async_context.index_repair_scheduler.initialized) return false;
        const armed = self.async_context.index_repair_scheduler.deferForProgress(
            repair_id,
            expected_revision,
            wake_at_sequence,
            fallback_at_ms,
        );
        if (armed) self.async_context.index_repair_progress_wait_pending.store(true, .release);
        return armed;
    }

    fn deferIndexRepairForAudit(
        self: *DB,
        repair_id: u128,
        expected_revision: u64,
    ) bool {
        const fallback_at_ms = self.indexRepairNowMs() +|
            progressive_index_repair_audit_interval_ms;
        lockAtomic(&self.async_context.index_repair_scheduler_mutex);
        defer self.async_context.index_repair_scheduler_mutex.unlock();
        if (!self.async_context.index_repair_scheduler.initialized) return false;
        const deferred = self.async_context.index_repair_scheduler.deferForAudit(
            repair_id,
            expected_revision,
            fallback_at_ms,
        );
        if (deferred) publishIndexRepairProgressWaitHint(self.async_context);
        return deferred;
    }

    /// Park an initial-build intent on the one watermark that can change the
    /// current replay proof. Once that target is already visible, later index
    /// publications cannot by themselves prove source-coverage completion;
    /// use the bounded audit deadline instead of waking repair for every newly
    /// generated artifact.
    fn deferIndexRepairUntilTargetOrAudit(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
        expected_revision: u64,
        index_name: []const u8,
        observed_sequence: u64,
        target_sequence: u64,
    ) !bool {
        if (observed_sequence >= target_sequence) {
            return self.deferIndexRepairForAudit(repair_id, expected_revision);
        }
        if (!self.deferIndexRepairForProgress(
            repair_id,
            expected_revision,
            target_sequence,
        )) return false;

        // Arm-then-recheck closes the lost-wakeup window between observing the
        // watermark and installing the revision-scoped resident wait.
        const current_sequence = try self.managedIndexAppliedSequence(alloc, index_name);
        if (current_sequence >= target_sequence) {
            _ = wakeIndexRepairForProgressContext(
                self.async_context,
                index_name,
                current_sequence,
            );
        }
        return true;
    }

    fn wakeIndexRepairForProgressContext(
        ctx: *AsyncContext,
        index_name: []const u8,
        applied_sequence: u64,
    ) ?IndexRepairSchedulerDirectory.ProgressWake {
        if (!ctx.index_repair_progress_wait_pending.load(.acquire)) return null;
        lockAtomic(&ctx.index_repair_scheduler_mutex);
        defer ctx.index_repair_scheduler_mutex.unlock();
        if (!ctx.index_repair_scheduler.initialized) {
            ctx.index_repair_progress_wait_pending.store(false, .release);
            return null;
        }
        const woke = ctx.index_repair_scheduler.wakeForIndexProgress(index_name, applied_sequence);
        if (ctx.index_repair_scheduler.progress_waiters == 0) {
            ctx.index_repair_progress_wait_pending.store(false, .release);
        }
        return woke;
    }

    fn ensureIndexRepairSchedulerDirectory(self: *DB, alloc: Allocator) !void {
        while (true) {
            lockAtomic(&self.async_context.index_repair_scheduler_mutex);
            const initialized = self.async_context.index_repair_scheduler.initialized;
            const current_root = if (self.async_context.index_repair_scheduler.identity) |identity|
                identity.root_generation == self.core.root_generation
            else
                false;
            if (initialized and !current_root) {
                self.async_context.index_repair_scheduler.deinit(self.async_context.alloc);
                publishIndexRepairProgressWaitHint(self.async_context);
                _ = self.async_context.index_repair_scheduler_revision.fetchAdd(1, .acq_rel);
            }
            self.async_context.index_repair_scheduler_mutex.unlock();
            if (initialized and current_root) return;
            if (initialized) continue;

            const observed_revision = self.async_context.index_repair_scheduler_revision.load(.acquire);
            var state = try self.loadOrCreateCurrentIndexRepairState(alloc);
            defer state.deinit(alloc);
            var replacement = try IndexRepairSchedulerDirectory.buildFromState(self.async_context.alloc, state);
            var replacement_owned = true;
            defer if (replacement_owned) replacement.deinit(self.async_context.alloc);

            lockAtomic(&self.async_context.index_repair_scheduler_mutex);
            defer self.async_context.index_repair_scheduler_mutex.unlock();
            if (self.async_context.index_repair_scheduler.initialized) return;
            if (self.async_context.index_repair_scheduler_revision.load(.acquire) != observed_revision) continue;
            self.async_context.index_repair_scheduler = replacement;
            replacement_owned = false;
            publishIndexRepairProgressWaitHint(self.async_context);
            return;
        }
    }

    pub fn indexRepairIntentSummary(self: *DB, alloc: Allocator) !IndexRepairIntentSummary {
        return self.indexRepairIntentSummaryForIndex(alloc, null);
    }

    pub fn indexRepairIntentSummaryForIndex(self: *DB, alloc: Allocator, target_index_name: ?[]const u8) !IndexRepairIntentSummary {
        if (self.managedAdmissionMaterializationPending()) try self.drainManagedIndexAdmissions(alloc);
        try self.ensureIndexRepairSchedulerDirectory(alloc);
        lockAtomic(&self.async_context.index_repair_scheduler_mutex);
        defer self.async_context.index_repair_scheduler_mutex.unlock();
        return self.async_context.index_repair_scheduler.summaryForIndex(target_index_name);
    }

    pub fn loadIndexRepairState(self: *const DB, alloc: Allocator) !index_repair_state.State {
        return try index_repair_state.loadAt(alloc, try self.indexRepairStateLocation());
    }

    fn refreshIndexRepairAvailabilityGate(self: *DB, alloc: Allocator) !void {
        var state = self.loadIndexRepairState(alloc) catch |err| switch (err) {
            error.FileNotFound, error.DurableIndexRepairStateUnavailable => return,
            error.InvalidIndexRepairState => {
                self.async_context.index_repair_state_corrupt.store(true, .release);
                self.async_context.index_repair_replay_pinned.store(true, .release);
                const configs = try self.core.index_manager.listIndexesPublic(alloc);
                defer {
                    for (configs) |*cfg| cfg.deinit(alloc);
                    alloc.free(configs);
                }
                for (configs) |cfg| try self.core.index_manager.markUnscopedRepairUnavailable(cfg.name);
                return;
            },
            else => return err,
        };
        defer state.deinit(alloc);
        // Opening already has to inspect every durable intent to install the
        // fail-closed serving gates. Build the exact scheduler projection from
        // that same snapshot so the first maintenance quantum never pays a
        // second O(N) cold-directory reconstruction.
        var scheduler = try IndexRepairSchedulerDirectory.buildFromState(self.async_context.alloc, state);
        var scheduler_owned = true;
        defer if (scheduler_owned) scheduler.deinit(self.async_context.alloc);
        lockAtomic(&self.async_context.index_repair_scheduler_mutex);
        if (!self.async_context.index_repair_scheduler.initialized) {
            self.async_context.index_repair_scheduler = scheduler;
            scheduler_owned = false;
        }
        self.async_context.index_repair_scheduler_mutex.unlock();
        for (state.entries.items) |entry| {
            var unavailable = indexRepairIntentBlocksService(entry.intent);
            if (!unavailable) {
                if (entry.intent.trigger == .incomplete_bulk_publish) {
                    const checkpoint = try self.core.loadProjectionCheckpoint(alloc, entry.intent.index_name);
                    unavailable = checkpoint.status != .clean or checkpoint.config_hash != entry.intent.config_hash;
                }
            }
            if (unavailable) {
                try self.core.index_manager.markUnscopedRepairUnavailable(entry.intent.index_name);
                self.core.index_manager.publishRepairAdmission(
                    entry.intent.index_name,
                    repairAdmissionVersion(entry.intent, entry.intent.revision, entry.intent.control_revision),
                    true,
                    false,
                );
            } else self.core.index_manager.publishRepairAdmission(
                entry.intent.index_name,
                repairAdmissionVersion(entry.intent, entry.intent.revision, entry.intent.control_revision),
                false,
                false,
            );
        }
    }

    /// A writable generation may clear its gate after activating the repaired
    /// root. A query-only DB is pinned to the root it opened, so it must retain
    /// every startup gate until retirement; durable checkpoint completion can
    /// describe a newer root and is not authority to expose the pinned one.
    /// Writable DBs recheck only rejected indexes, keeping healthy queries free
    /// of checkpoint I/O.
    fn refreshIndexRepairAvailabilityForIndex(self: *DB, alloc: Allocator, index_name: []const u8) !void {
        const pinned_read_generation = openModeRequiresReadOnlyBackends(self.open_mode);
        var state = self.loadIndexRepairState(alloc) catch |err| switch (err) {
            error.FileNotFound => {
                if (pinned_read_generation) return;
                try self.clearRepairGateIfAdmissionCompleted(alloc, index_name);
                return;
            },
            error.DurableIndexRepairStateUnavailable => return,
            error.InvalidIndexRepairState => {
                self.async_context.index_repair_state_corrupt.store(true, .release);
                self.async_context.index_repair_replay_pinned.store(true, .release);
                return;
            },
            else => return err,
        };
        defer state.deinit(alloc);

        try self.refreshIndexRepairAvailabilityForIndexFromState(alloc, index_name, &state, pinned_read_generation);
    }

    fn refreshIndexRepairAvailabilityForIndexFromState(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        state: *const index_repair_state.State,
        pinned_read_generation: bool,
    ) !void {
        // A checkpoint from another root generation is not authority to clear
        // this generation's gate. Startup/root-transition repair owns it.
        if (state.identity.root_generation != self.core.root_generation) return;

        const entry_index = state.findIndex(index_name) orelse {
            if (pinned_read_generation) return;
            try self.clearRepairGateIfAdmissionCompleted(alloc, index_name);
            return;
        };
        const intent = state.entries.items[entry_index].intent;
        var unavailable = indexRepairIntentBlocksService(intent);
        const pinned_generation_proved_serviceable = unavailable and
            try self.managedAdmissionGenerationIsQueryable(alloc, intent);
        if (pinned_generation_proved_serviceable) {
            unavailable = false;
        }
        // Durable phase/checkpoint transitions can describe a newer root than
        // the query-only DB has open. Only the proof above inspected this
        // pinned in-memory generation, so it is the sole read-only exception.
        if (pinned_read_generation) {
            if (pinned_generation_proved_serviceable) {
                self.core.index_manager.publishRepairServiceabilityProof(
                    index_name,
                    repairAdmissionVersion(intent, intent.revision, intent.control_revision),
                );
            }
            return;
        }
        if (!unavailable and intent.trigger == .incomplete_bulk_publish) {
            const checkpoint = try self.core.loadProjectionCheckpoint(alloc, index_name);
            unavailable = checkpoint.status != .clean or checkpoint.config_hash != intent.config_hash;
        }
        if (!unavailable) self.core.index_manager.publishRepairServiceabilityProof(
            index_name,
            repairAdmissionVersion(intent, intent.revision, intent.control_revision),
        );
    }

    /// Bind a completion/query proof to this replica's initial materialization.
    /// Generated-coverage recovery has no catalog-admission marker: its durable
    /// source-replay state supplies that boundary instead. Ordinary repairs
    /// must never inherit this exception.
    fn managedInitialBuildMinimumReplay(
        self: *DB,
        alloc: Allocator,
        intent: index_repair_state.IndexRepairIntent,
    ) !?u64 {
        if ((intent.kind != .dense_vector and intent.kind != .sparse_vector) or
            intent.work_class != .initial_build or
            intent.root_generation != self.core.root_generation or
            intent.group_id != self.localRepairGroupId()) return null;

        if (intent.trigger == .replay_artifact_unavailable) {
            if (intent.source_replay_state == .not_required) return null;
            return intent.target_sequence;
        }
        if (intent.trigger != .catalog_admission) return null;
        const admission_key = try internal_keys.managedIndexAdmissionKeyAlloc(alloc, intent.index_name);
        defer alloc.free(admission_key);
        const admission_raw = self.core.store.get(alloc, admission_key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        defer alloc.free(admission_raw);
        const marker = try decodeManagedIndexAdmissionMarker(admission_raw);
        if (marker.disposition != .managed_rebuild or marker.config_hash != intent.config_hash) return null;
        return @max(marker.replay_target_sequence, intent.target_sequence);
    }

    fn initialBuildCanRetireBeforeActivation(intent: index_repair_state.IndexRepairIntent) bool {
        return switch (intent.phase) {
            .detected, .preflight, .building, .catching_up, .ready, .waiting_for_convergence => true,
            else => false,
        };
    }

    /// Managed admission deliberately installs an empty, gated generation and
    /// delegates corpus reconstruction. The ordinary enrichment/replay workers
    /// can finish that same generation before the shadow-repair owner runs. In
    /// that case, this bounded proof avoids both an unnecessary replacement
    /// build and a user-visible `index_rebuilding` interval after coverage is
    /// already complete.
    ///
    /// Every input is generation-scoped and O(1): the admission marker binds
    /// the catalog hash, the checkpoint binds replay and projection identity,
    /// the maintained outcome tuple proves terminal source coverage, and the
    /// active HBC cardinality proves that every produced artifact is present.
    fn managedAdmissionGenerationIsServiceable(
        self: *DB,
        alloc: Allocator,
        intent: index_repair_state.IndexRepairIntent,
    ) !bool {
        const minimum_replay = (try self.managedInitialBuildMinimumReplay(alloc, intent)) orelse return false;
        if (!initialBuildCanRetireBeforeActivation(intent) or intent.source_replay_state == .pending) return false;
        if (intent.candidate_relative_path) |candidate| {
            if (try self.core.index_manager.isRepairCandidateActive(intent.index_name, candidate)) return false;
        }
        return try self.managedGenerationIsServiceableAtLeast(
            alloc,
            intent.index_name,
            intent.config_hash,
            minimum_replay,
        );
    }

    /// Atomic managed admission normally defers the canonical derived worker
    /// until shadow activation. The canonical generation can nevertheless
    /// become independently serviceable while enrichment drains its durable
    /// requests. Before retiring that admission intent, attach the ordinary
    /// worker at the durable publication cursor so future writes continue to
    /// advance the generation. Intent removal is deliberately ordered after
    /// this fallible operation: a failed attachment remains durable repair
    /// debt and is retried by the same single owner.
    fn ensureManagedAdmissionCanonicalWorker(
        self: *DB,
        alloc: Allocator,
        intent: index_repair_state.IndexRepairIntent,
    ) !void {
        if (!self.start_index_workers or self.executor.appliedSequence(intent.index_name) != null) return;

        const configs = try self.core.listIndexes(alloc);
        defer types.freeIndexConfigs(alloc, configs);
        const cfg = for (configs) |candidate| {
            if (std.mem.eql(u8, candidate.name, intent.index_name)) break candidate;
        } else return error.IndexNotFound;
        if (cfg.kind != intent.kind or types.indexConfigHash(cfg) != intent.config_hash) {
            return error.IndexConfigMismatch;
        }

        const applied = try self.core.loadAppliedSequence(alloc, intent.index_name);
        try self.executor.addWorker(intent.index_name, .{
            .name = intent.index_name,
            .kind = intent.kind,
        }, applied);
        const current_target = self.core.nextDerivedSequence();
        if (current_target > applied) self.executor.notifyIndexes(current_target, &.{intent.index_name});
    }

    /// Progressive managed admission publishes only the canonical active
    /// generation. It may answer queries before corpus-wide coverage is
    /// complete once a durable worker checkpoint proves that every artifact
    /// currently in the generation has been applied. Dense generations also
    /// require exact physical cardinality and a structurally quiet HBC
    /// snapshot; sparse batches are transactional, so their applied cursor is
    /// the publication boundary. The repair intent remains durable until the
    /// stronger complete-generation proof above succeeds.
    fn managedAdmissionGenerationIsQueryable(
        self: *DB,
        alloc: Allocator,
        intent: index_repair_state.IndexRepairIntent,
    ) !bool {
        const minimum_replay = (try self.managedInitialBuildMinimumReplay(alloc, intent)) orelse return false;
        if (intent.phase == .activating or intent.phase == .validating) {
            // A pinned predecessor may keep serving across the durable pointer
            // change. Its resident identity must match the captured predecessor;
            // the replacement cannot inherit this admission before validation.
            if (intent.kind != .dense_vector or !intent.previous_pointer_captured) return false;
            const candidate = intent.candidate_relative_path orelse return false;
            if (!try self.core.index_manager.denseResidentIsRepairPredecessor(
                intent.index_name,
                intent.previous_active_relative_path,
                candidate,
            )) return false;
        } else {
            if (!initialBuildCanRetireBeforeActivation(intent)) return false;
            if (intent.candidate_relative_path) |candidate| {
                if (try self.core.index_manager.isRepairCandidateActive(intent.index_name, candidate)) return false;
            }
        }
        return try self.progressiveManagedGenerationIsQueryableAtLeast(
            alloc,
            intent.index_name,
            intent.config_hash,
            minimum_replay,
        );
    }

    const ProgressiveGenerationQueryability = enum {
        queryable,
        index_missing,
        unsupported_kind,
        config_changed,
        atomic_publication,
        load_failed,
        checkpoint_not_publishable,
        checkpoint_config_changed,
        checkpoint_behind,
        coverage_identity_unavailable,
        external_coverage,
        coverage_incarnation_unavailable,
        coverage_counter_unavailable,
        no_published_sources,
        physical_index_unavailable,
        artifact_counter_unavailable,
        artifact_count_mismatch,
        empty_dense_publication,
        empty_sparse_publication,
    };

    /// Durable O(1) proof for the currently published progressive generation.
    /// This is deliberately independent of repair ownership: ordinary
    /// ingestion retires its empty-table admission intent before later partial
    /// publications exist, while restart still needs to distinguish a safe
    /// checkpoint from projection reconstruction debt. Repair callers layer
    /// their admission marker and minimum replay fence on top of this proof.
    fn observeProgressiveManagedGenerationQueryabilityAtLeast(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        config_hash: u64,
        minimum_replay_sequence: u64,
    ) !ProgressiveGenerationQueryability {
        const cfg = self.core.index_manager.get(index_name) orelse return .index_missing;
        if (cfg.kind != .dense_vector and cfg.kind != .sparse_vector) return .unsupported_kind;
        if (types.indexConfigHash(cfg.*) != config_hash) return .config_changed;
        if (try types.indexPublicationPolicy(alloc, cfg.*) != .progressive) return .atomic_publication;
        if (self.core.index_manager.loadFailure(index_name) != null) return .load_failed;

        const checkpoint = try self.core.loadProjectionCheckpoint(alloc, index_name);
        if (checkpoint.status != .clean and checkpoint.status != .rebuilding) return .checkpoint_not_publishable;
        if (checkpoint.config_hash != config_hash) return .checkpoint_config_changed;
        if (checkpoint.applied_sequence < minimum_replay_sequence) return .checkpoint_behind;

        const ownership = indexDerivedCoverageOwnership(alloc, cfg.*) orelse return .coverage_identity_unavailable;
        if (ownership == .external) return .external_coverage;
        const generation = self.core.index_manager.coverageGenerationForIndex(index_name) orelse
            return .coverage_incarnation_unavailable;
        const produced = (try loadDerivedCoverageCounters(alloc, self.core.store, index_name, generation, null, null)).produced orelse return .coverage_counter_unavailable;
        if (produced == 0) return .no_published_sources;
        return switch (cfg.kind) {
            .dense_vector => blk: {
                const dense = self.core.index_manager.denseIndex(index_name) orelse break :blk .physical_index_unavailable;
                const active_count = dense.index.servingActiveCountForCheckpoint() orelse break :blk .physical_index_unavailable;
                if (active_count == 0) break :blk .empty_dense_publication;
                if (checkpoint.published_count != null) {
                    // Only an open or publication boundary may certify this
                    // checkpoint. A recovered older native WAL prefix remains
                    // serviceable when its sidecar names an unfinished window.
                    if (!dense.hasValidatedServingCertificate(checkpoint) and
                        !dense.hasRecoveredNativeServingCertificate(checkpoint))
                        break :blk .artifact_count_mismatch;
                } else {
                    // v0.2/legacy checkpoints carry no physical certificate.
                    // An opened native WAL can prove its durable prefix;
                    // otherwise preserve the conservative equality proof.
                    if (!dense.hasRecoveredNativeServingCertificate(checkpoint)) {
                        const expected_active_count = if (densePublicationTargetUsesArtifactCounter(dense))
                            (try loadDenseArtifactTargetCounter(alloc, self.core.store, index_name)) orelse break :blk .artifact_counter_unavailable
                        else
                            produced;
                        if (!denseCoverageMatchesTarget(active_count, expected_active_count)) break :blk .artifact_count_mismatch;
                    }
                }
                // Dirty posting centroids/payloads are bounded optimization
                // debt. HBC searches them exactly until the maintenance lane
                // refreshes those caches, so neither query admission nor this
                // O(1) startup proof may scan or quarantine them.
                break :blk .queryable;
            },
            .sparse_vector => blk: {
                const sparse = self.core.index_manager.sparseIndex(index_name) orelse break :blk .physical_index_unavailable;
                // Sparse replay applies a whole derived batch transactionally
                // before advancing the checkpoint. At least one live sparse
                // document plus the cursor proof above is therefore enough to
                // publish this generation without scanning the index.
                break :blk if (sparse.index.stats().doc_count > 0) .queryable else .empty_sparse_publication;
            },
            else => .unsupported_kind,
        };
    }

    fn progressiveManagedGenerationIsQueryableAtLeast(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        config_hash: u64,
        minimum_replay_sequence: u64,
    ) !bool {
        return try self.observeProgressiveManagedGenerationQueryabilityAtLeast(
            alloc,
            index_name,
            config_hash,
            minimum_replay_sequence,
        ) == .queryable;
    }

    fn progressiveManagedGenerationIsQueryable(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
    ) !bool {
        const cfg = self.core.index_manager.get(index_name) orelse return false;
        return try self.progressiveManagedGenerationIsQueryableAtLeast(
            alloc,
            index_name,
            types.indexConfigHash(cfg.*),
            0,
        );
    }

    /// Bounded proof used by structural reconciliation after a managed dense
    /// admission has retired its outbox/repair marker. A complete generation
    /// must not be force-reprocessed from stored documents: deterministic
    /// chunk artifact identities are already represented by the current
    /// snapshot, and replaying their historical replacement stream over that
    /// snapshot can remove the final values.
    pub fn completedManagedDenseGenerationIsServiceable(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
    ) !bool {
        const cfg = self.core.index_manager.get(index_name) orelse return false;
        if (cfg.kind != .dense_vector) return false;
        return try self.managedGenerationIsServiceableAtLeast(
            alloc,
            index_name,
            types.indexConfigHash(cfg.*),
            0,
        );
    }

    fn managedGenerationIsServiceableAtLeast(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        config_hash: u64,
        minimum_replay_sequence: u64,
    ) !bool {
        const cfg = self.core.index_manager.get(index_name) orelse return false;
        if ((cfg.kind != .dense_vector and cfg.kind != .sparse_vector) or
            types.indexConfigHash(cfg.*) != config_hash or
            self.core.index_manager.loadFailure(index_name) != null)
        {
            return false;
        }

        const checkpoint = try self.core.loadProjectionCheckpoint(alloc, index_name);
        if (checkpoint.status != .clean or checkpoint.config_hash != config_hash) return false;
        const applied_sequence = try self.managedIndexAppliedSequence(alloc, index_name);
        const target_sequence = try self.projectionStatsTargetSequence(alloc, cfg.*, applied_sequence);
        if (applied_sequence < minimum_replay_sequence or
            applied_sequence < target_sequence or
            checkpoint.applied_sequence < target_sequence)
        {
            return false;
        }

        const ownership = indexDerivedCoverageOwnership(alloc, cfg.*) orelse return false;
        const policy = switch (ownership) {
            .external => return false,
            .managed => |value| value,
        };
        const generation = self.core.index_manager.coverageGenerationForIndex(index_name) orelse return false;
        const coverage_counts = try loadDerivedCoverageCounters(alloc, self.core.store, index_name, generation, null, null);
        const produced = coverage_counts.produced orelse return false;
        const skipped = coverage_counts.skipped orelse return false;
        const terminal_failed = coverage_counts.terminal_failed orelse return false;
        // Do not fall back to a primary-store scan on query admission. Modern
        // managed writes maintain this counter atomically; a missing legacy
        // counter simply leaves the durable repair owner in charge.
        const source_total = coverage_counts.source_total orelse return false;
        const assessment = types.evaluateDerivedCoverageAssessment(
            policy,
            source_total,
            produced,
            skipped,
            terminal_failed,
            true,
            true,
        );
        if (!assessment.health.counters_valid or !assessment.complete) return false;
        return switch (cfg.kind) {
            .dense_vector => blk: {
                const dense = self.core.index_manager.denseIndex(index_name) orelse break :blk false;
                // Coverage outcomes count source documents. Chunk-backed and
                // multi-source dense indexes can contain several physical
                // vectors for every produced source, so their durable artifact
                // counter—not `produced`—is the active HBC cardinality
                // authority.
                const expected_active_count = if (densePublicationTargetUsesArtifactCounter(dense))
                    (try coverage_counts.artifactCount()) orelse break :blk false
                else
                    produced;
                // Posting cache freshness is intentionally absent here.
                // Dirty postings remain exactly searchable and drain in the
                // bounded maintenance lane; completion describes publication
                // and source coverage, not physical optimization cleanliness.
                break :blk denseCoverageMatchesTarget(dense.index.stats().active_count, expected_active_count);
            },
            .sparse_vector => blk: {
                const sparse = self.core.index_manager.sparseIndex(index_name) orelse break :blk false;
                // The complete coverage tuple and replay checkpoint prove all
                // source outcomes reached this transactional sparse
                // generation. Produced sources must have at least one live
                // sparse document; chunking may legitimately make this count
                // larger than the source-level counter.
                break :blk produced == 0 or sparse.index.stats().doc_count >= produced;
            },
            else => false,
        };
    }

    fn clearRepairGateIfAdmissionCompleted(self: *DB, alloc: Allocator, index_name: []const u8) !void {
        const key = try internal_keys.managedIndexAdmissionKeyAlloc(alloc, index_name);
        defer alloc.free(key);
        const marker = self.core.store.get(alloc, key) catch |err| switch (err) {
            error.NotFound => {
                self.core.index_manager.clearManagedAdmissionSnapshotForIndex(index_name);
                self.core.index_manager.clearUnscopedRepairUnavailable(index_name);
                return;
            },
            else => return err,
        };
        alloc.free(marker);
    }

    fn indexRepairIntentBlocksService(intent: index_repair_state.IndexRepairIntent) bool {
        // Initial materialization has no validated predecessor to retain.
        // Replay can reclassify its trigger while source artifacts arrive,
        // but only the scoped canonical proof or validated cleanup may open
        // admission; the ordinary replay-repair exception is not authority.
        if (intent.work_class == .initial_build) return intent.phase != .cleanup;
        return switch (intent.trigger) {
            .incomplete_bulk_publish => intent.phase != .cleanup,
            // Only an operator-requested rebuild starts from a generation that
            // is still proven healthy. Coverage mismatch or missing proof is
            // fail-closed until replacement validation publishes cleanup.
            .operator_generation_rebuild, .storage_format_migration, .artifact_baseline_adoption => intent.phase == .activating or
                intent.phase == .validating or
                intent.phase == .rolling_back,
            .replay_artifact_unavailable => intent.phase == .activating or
                intent.phase == .validating or
                intent.phase == .rolling_back,
            .artifact_coverage_mismatch,
            .artifact_counter_missing,
            .root_generation_rebuild,
            .projection_generation_invalid,
            .operator_generation_validation,
            .catalog_admission,
            => intent.phase != .cleanup,
        };
    }

    fn indexRepairAdmission(intent: index_repair_state.IndexRepairIntent) IndexRepairAdmission {
        return if (indexRepairIntentBlocksService(intent)) .blocked else .serviceable;
    }

    fn repairAdmissionVersion(
        intent: index_repair_state.IndexRepairIntent,
        persisted_revision: u64,
        control_revision: u64,
    ) index_manager_mod.IndexManager.RepairAdmissionVersion {
        return .{
            .repair_id = intent.repair_id,
            .control_revision = control_revision,
            .revision = persisted_revision,
            .config_hash = intent.config_hash,
            .root_generation = intent.root_generation,
        };
    }

    fn indexRepairActionRequired(intent: index_repair_state.IndexRepairIntent) bool {
        if (intent.automation == .paused) return true;
        return intent.phase == .terminal and
            retryableIndexRepairTerminalPhase(intent.last_error, intent.trigger) == null;
    }

    fn loadOrCreateCurrentIndexRepairState(self: *DB, alloc: Allocator) !index_repair_state.State {
        const location = try self.indexRepairStateLocation();
        var state = try index_repair_state.loadOrCreateAt(alloc, location, self.core.root_generation);
        var state_owned = true;
        defer if (state_owned) state.deinit(alloc);
        if (state.identity.root_generation == self.core.root_generation) {
            state_owned = false;
            return state;
        }

        // A root-generation transition fences every old repair identity. An
        // inactive candidate can be deleted. A pointer-selected candidate must
        // never become silently serviceable merely because its old intent is
        // discarded: persist fresh, new-root reconstruction debt first and
        // keep that index fail-closed until a new generation is validated.
        var replacement_intents = std.ArrayListUnmanaged(index_repair_state.IndexRepairIntent).empty;
        defer {
            for (replacement_intents.items) |*intent| intent.deinit(alloc);
            replacement_intents.deinit(alloc);
        }
        for (state.entries.items) |entry| {
            const candidate = entry.intent.candidate_relative_path orelse continue;
            try index_repair_state.validateCandidateRelativePath(entry.intent.index_name, candidate);
            if (try self.core.index_manager.isRepairCandidateActive(entry.intent.index_name, candidate)) {
                const cfg = self.core.index_manager.get(entry.intent.index_name) orelse
                    return error.InvalidIndexRepairState;
                const now_ms = self.indexRepairNowMs();
                const target_sequence = self.core.nextDerivedSequence();
                var replacement_intent = index_repair_state.IndexRepairIntent{
                    .repair_id = try index_repair_state.newRepairId(alloc),
                    .db_identity = state.identity.db_identity,
                    .group_id = self.localRepairGroupId(),
                    .replica_id = state.identity.replica_id,
                    .root_generation = self.core.root_generation,
                    .index_name = try alloc.dupe(u8, entry.intent.index_name),
                    .kind = cfg.kind,
                    .config_hash = types.indexConfigHash(cfg.*),
                    .trigger = .root_generation_rebuild,
                    .detected_sequence = target_sequence,
                    .target_sequence = target_sequence,
                    .started_at_ms = now_ms,
                    .updated_at_ms = now_ms,
                    .owner_epoch = 0,
                    .last_error = try alloc.dupe(u8, "root_generation_changed_during_activation"),
                };
                var replacement_intent_owned = true;
                errdefer if (replacement_intent_owned) replacement_intent.deinit(alloc);
                try replacement_intents.append(alloc, replacement_intent);
                replacement_intent_owned = false;
                try self.core.index_manager.prepareRepairAdmissionRebind(
                    entry.intent.index_name,
                    repairAdmissionVersion(replacement_intent, 1, 1),
                );
                continue;
            }
            const separator = std.mem.indexOfScalar(u8, candidate, '/') orelse return error.InvalidRepairCandidatePath;
            const shadow_root = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ self.core.path, candidate[0..separator] });
            defer alloc.free(shadow_root);
            if (self.primary_lsm_storage) |storage| {
                try storage.deleteTree(shadow_root);
            } else if (comptime builtin.os.tag == .freestanding) {
                return error.UnsupportedPlatform;
            } else {
                var io_impl = threadedIo();
                defer io_impl.deinit();
                try std.Io.Dir.cwd().deleteTree(io_impl.io(), shadow_root);
            }
        }
        const old_identity = state.identity;
        const replacement = try index_repair_state.resetForRootGenerationWithIntentsAt(
            alloc,
            location,
            old_identity,
            self.core.root_generation,
            replacement_intents.items,
        );
        for (replacement.entries.items) |entry| {
            self.core.index_manager.publishRepairAdmission(
                entry.intent.index_name,
                repairAdmissionVersion(entry.intent, entry.intent.revision, entry.intent.control_revision),
                indexRepairIntentBlocksService(entry.intent),
                false,
            );
        }
        // Only the checkpoint replacement authorizes retirement of old-root
        // admissions. Active candidates were pre-bound to their new identity,
        // so the exact old publication is ignored for them; inactive entries
        // are released without allowing a same-name incarnation to be opened.
        for (state.entries.items) |entry| {
            self.core.index_manager.publishRepairAdmission(
                entry.intent.index_name,
                repairAdmissionVersion(entry.intent, entry.intent.revision +| 1, state.control_revision +| 1),
                false,
                false,
            );
            self.core.index_manager.clearUnscopedRepairUnavailable(entry.intent.index_name);
        }
        state.deinit(alloc);
        state_owned = false;
        invalidateIndexRepairSchedulerDirectory(self.async_context);
        const observed_revision = self.async_context.index_repair_scheduler_revision.load(.acquire);
        var scheduler = try IndexRepairSchedulerDirectory.buildFromState(self.async_context.alloc, replacement);
        var scheduler_owned = true;
        defer if (scheduler_owned) scheduler.deinit(self.async_context.alloc);
        lockAtomic(&self.async_context.index_repair_scheduler_mutex);
        if (!self.async_context.index_repair_scheduler.initialized and
            self.async_context.index_repair_scheduler_revision.load(.acquire) == observed_revision)
        {
            self.async_context.index_repair_scheduler = scheduler;
            scheduler_owned = false;
        }
        publishIndexRepairProgressWaitHint(self.async_context);
        self.async_context.index_repair_scheduler_mutex.unlock();
        return replacement;
    }

    fn loadIndexRepairEntryById(
        self: *const DB,
        alloc: Allocator,
        repair_id: u128,
    ) !index_repair_state.Entry {
        var state = try self.loadIndexRepairState(alloc);
        defer state.deinit(alloc);
        for (state.entries.items) |entry| {
            if (entry.intent.repair_id == repair_id) return try entry.clone(alloc);
        }
        return error.IndexRepairIntentNotFound;
    }

    pub const PinnedIndexRepairSnapshot = struct {
        txn: docstore_mod.DocStore.Txn,
        repair_id: u128,
        build_floor_sequence: u64,

        pub fn deinit(self: *@This()) void {
            self.txn.abort();
            self.* = undefined;
        }
    };

    /// Atomically protects replay before exposing a primary snapshot. The
    /// provisional zero pin and truncation share repair_replay_mutex, closing
    /// the floor-capture race even if the process stops between either durable
    /// checkpoint update.
    pub fn beginPinnedIndexRepairSnapshot(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
    ) !PinnedIndexRepairSnapshot {
        self.core.repair_replay_mutex.lockUncancelable(self.core.index_manager.checkpointIo());
        defer self.core.repair_replay_mutex.unlock(self.core.index_manager.checkpointIo());
        const location = try self.indexRepairStateLocation();
        var state = try index_repair_state.loadAt(alloc, location);
        defer state.deinit(alloc);
        const entry_index = blk: {
            for (state.entries.items, 0..) |entry, i| {
                if (entry.intent.repair_id == repair_id) break :blk i;
            }
            return error.IndexRepairIntentNotFound;
        };
        var entry = try state.entries.items[entry_index].clone(alloc);
        defer entry.deinit(alloc);
        if (entry.intent.phase == .terminal or entry.intent.automation == .paused) return error.IndexRepairNotRunnable;
        var expected = index_repair_state.ExpectedTransition{
            .repair_id = entry.intent.repair_id,
            .revision = entry.intent.revision,
            .phase = entry.intent.phase,
            .config_hash = entry.intent.config_hash,
            .root_generation = entry.intent.root_generation,
            .owner_epoch = entry.intent.owner_epoch,
        };
        if (entry.pin == null) {
            entry.pin = .{
                .repair_id = entry.intent.repair_id,
                .db_identity = entry.intent.db_identity,
                .replica_id = entry.intent.replica_id,
                .root_generation = entry.intent.root_generation,
                .index_name = try alloc.dupe(u8, entry.intent.index_name),
                .retain_after_sequence = 0,
            };
            const control_revision = try index_repair_state.putEntryAt(alloc, location, state.identity, expected, entry);
            self.core.index_manager.publishRepairAdmission(
                entry.intent.index_name,
                repairAdmissionVersion(entry.intent, expected.revision +| 1, control_revision),
                indexRepairIntentBlocksService(entry.intent),
                true,
            );
            noteIndexRepairSchedulerUpsert(self.async_context, entry.intent, expected.revision +| 1, control_revision);
        } else {
            // Re-entering snapshot acquisition must become conservative before
            // replacing a previously finalized build floor.
            entry.pin.?.retain_after_sequence = 0;
            const control_revision = try index_repair_state.putEntryAt(alloc, location, state.identity, expected, entry);
            self.core.index_manager.publishRepairAdmission(
                entry.intent.index_name,
                repairAdmissionVersion(entry.intent, expected.revision +| 1, control_revision),
                indexRepairIntentBlocksService(entry.intent),
                true,
            );
            noteIndexRepairSchedulerUpsert(self.async_context, entry.intent, expected.revision +| 1, control_revision);
        }
        expected.revision +|= 1;
        self.async_context.index_repair_replay_pinned.store(true, .release);

        var txn = try self.core.store.beginReadTxn();
        errdefer txn.abort();
        const build_floor = try self.core.store.lastReplaySequenceFromTxn(&txn, 0);
        entry.intent.build_floor_sequence = build_floor;
        entry.intent.build_source_guard = try @import("artifact_source_gap.zig").Guard.capture(&txn);
        entry.intent.updated_at_ms = self.indexRepairNowMs();
        entry.pin.?.retain_after_sequence = build_floor;
        const control_revision = try index_repair_state.putEntryAt(alloc, location, state.identity, expected, entry);
        self.core.index_manager.publishRepairAdmission(
            entry.intent.index_name,
            repairAdmissionVersion(entry.intent, expected.revision +| 1, control_revision),
            indexRepairIntentBlocksService(entry.intent),
            true,
        );
        noteIndexRepairSchedulerUpsert(self.async_context, entry.intent, expected.revision +| 1, control_revision);
        return .{
            .txn = txn,
            .repair_id = repair_id,
            .build_floor_sequence = build_floor,
        };
    }

    const IndexRepairIntentUpdate = struct {
        const AttemptFailure = struct {
            err_name: []const u8,
            terminal: bool,
        };

        trigger: ?index_repair_state.Trigger = null,
        operator_job_id: ?u64 = null,
        operator_job_created_at_ms: ?u64 = null,
        phase: ?index_repair_state.Phase = null,
        candidate_relative_path: ?[]const u8 = null,
        replace_candidate_path: bool = false,
        previous_pointer_captured: ?bool = null,
        previous_active_relative_path: ?[]const u8 = null,
        replace_previous_active_path: bool = false,
        candidate_applied_sequence: ?u64 = null,
        build_resume_key: ?[]const u8 = null,
        replace_build_resume_key: bool = false,
        build_reprocessed: ?u64 = null,
        source_replay_resume_key: ?[]const u8 = null,
        replace_source_replay_resume_key: bool = false,
        source_replay_reprocessed: ?u64 = null,
        source_replay_state: ?index_repair_state.SourceReplayState = null,
        estimated_candidate_bytes: ?u64 = null,
        planned_disk_bytes: ?u64 = null,
        target_sequence: ?u64 = null,
        attempt_count: ?u32 = null,
        failure_streak: ?u32 = null,
        next_retry_at_ms: ?u64 = null,
        automation: ?index_repair_state.Automation = null,
        owner_epoch: ?u64 = null,
        last_error: ?[]const u8 = null,
        replace_last_error: bool = false,
        /// Relative retry accounting must be derived from the authoritative
        /// entry while repair-control ownership is held. Supplying absolute
        /// counters from an earlier snapshot can lose a concurrent failure.
        attempt_failure: ?AttemptFailure = null,
    };

    fn indexRepairPhaseHasActivationCertification(phase: index_repair_state.Phase) bool {
        return switch (phase) {
            .activating, .validating, .cleanup, .rolling_back => true,
            else => false,
        };
    }

    /// Resolve the phase produced by the complete update transaction. Failure
    /// accounting can move an intent to `terminal` without populating the
    /// explicit phase field, while an explicit phase retains the historical
    /// last-writer precedence of the mutation block below. Safety invariants
    /// must reason about this effective phase, not the update's encoding.
    fn indexRepairIntentEffectivePhase(
        current: index_repair_state.Phase,
        update: IndexRepairIntentUpdate,
    ) index_repair_state.Phase {
        if (update.phase) |phase| return phase;
        if (update.attempt_failure) |failure| {
            if (failure.terminal) return .terminal;
        }
        return current;
    }

    fn indexRepairRetryDelayMs(repair_id: u128, attempt_count: u32) u64 {
        const exponent: u6 = @intCast(@min(attempt_count -| 1, 5));
        const base_ms: u64 = 30 * std.time.ms_per_s;
        const maximum_ms: u64 = 10 * std.time.ms_per_min;
        const nominal = @min(base_ms << exponent, maximum_ms);
        // Stable per-attempt +/-10% jitter prevents a node restart from
        // synchronizing every pending repair while keeping the retry time
        // reconstructible and bounded.
        var seed: [20]u8 = undefined;
        std.mem.writeInt(u128, seed[0..16], repair_id, .little);
        std.mem.writeInt(u32, seed[16..20], attempt_count, .little);
        const spread = @max(@as(u64, 1), nominal / 5);
        const jitter = std.hash.Wyhash.hash(0x4944585250525954, &seed) % spread;
        return nominal - nominal / 10 + jitter;
    }

    fn indexRepairIdForIndex(self: *const DB, alloc: Allocator, index_name: []const u8) !?u128 {
        return try indexRepairIdForIndexContext(self.async_context, alloc, index_name);
    }

    fn indexRepairIdForIndexContext(ctx: *const AsyncContext, alloc: Allocator, index_name: []const u8) !?u128 {
        const location = indexRepairStateLocationContext(ctx) catch {
            // Backends without a replica-local durable checkpoint cannot own
            // repair intents, so read-side discovery is equivalent to empty.
            // Intent creation remains fail-closed through the same capability.
            return null;
        };
        var state = index_repair_state.loadAt(alloc, location) catch |err| switch (err) {
            error.FileNotFound => return null,
            else => return err,
        };
        defer state.deinit(alloc);
        const i = state.findIndex(index_name) orelse return null;
        return state.entries.items[i].intent.repair_id;
    }

    fn validateIndexRepairActivationState(self: *DB, alloc: Allocator, repair_id: u128, expected_owner_epoch: u64) !void {
        var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer entry.deinit(alloc);
        if (entry.intent.root_generation != self.core.root_generation or
            entry.intent.group_id != self.localRepairGroupId())
        {
            return error.RepairOwnershipLost;
        }
        if (entry.intent.phase == .terminal or entry.intent.automation == .paused) return error.IndexRepairNotRunnable;
        if (expected_owner_epoch != 0 and entry.intent.owner_epoch != expected_owner_epoch) {
            return error.RepairOwnershipLost;
        }
        const cfg = self.core.index_manager.get(entry.intent.index_name) orelse return error.IndexRepairConfigurationChanged;
        if (cfg.kind != entry.intent.kind or types.indexConfigHash(cfg.*) != entry.intent.config_hash) {
            return error.IndexRepairConfigurationChanged;
        }
    }

    fn updateIndexRepairIntent(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
        update: IndexRepairIntentUpdate,
    ) !void {
        return try self.updateIndexRepairIntentWithBindingEffect(
            alloc,
            repair_id,
            update,
            .retain,
            null,
        );
    }

    /// Consume a scheduler audit grant by advancing exactly the durable
    /// revision selected by that scheduler turn. This is a real control
    /// transition, not a read-then-act check: the control mutex plus the
    /// checkpoint CAS linearize the grant against pause/resume, owner handoff,
    /// replay, and retry mutations. The returned revision is the owned turn's
    /// new authority for any wait it publishes after the audit.
    fn consumeIndexRepairAuditGrant(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
        expected_revision: u64,
    ) !?u64 {
        self.updateIndexRepairIntentWithBindingEffect(
            alloc,
            repair_id,
            .{},
            .retain,
            expected_revision,
        ) catch |err| switch (err) {
            error.RepairTransitionConflict => return null,
            else => return err,
        };
        return expected_revision +| 1;
    }

    const IndexRepairBindingEffect = enum { retain, release };

    fn updateIndexRepairIntentWithBindingEffect(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
        update: IndexRepairIntentUpdate,
        binding_effect: IndexRepairBindingEffect,
        required_revision: ?u64,
    ) !void {
        lockAtomic(&self.async_context.index_repair_control_mutex);
        var control_locked = true;
        defer if (control_locked) self.async_context.index_repair_control_mutex.unlock();
        const location = try self.indexRepairStateLocation();
        var state = try index_repair_state.loadAt(alloc, location);
        defer state.deinit(alloc);
        const i = blk: {
            for (state.entries.items, 0..) |entry, entry_i| {
                if (entry.intent.repair_id == repair_id) break :blk entry_i;
            }
            return error.IndexRepairIntentNotFound;
        };
        if (required_revision) |revision| {
            if (state.entries.items[i].intent.revision != revision) {
                return error.RepairTransitionConflict;
            }
        }
        var entry = try state.entries.items[i].clone(alloc);
        defer entry.deinit(alloc);
        const effective_phase = indexRepairIntentEffectivePhase(entry.intent.phase, update);
        if (update.candidate_applied_sequence) |candidate_sequence| {
            const remains_activation_certified = indexRepairPhaseHasActivationCertification(entry.intent.phase) and
                indexRepairPhaseHasActivationCertification(effective_phase);
            if (remains_activation_certified and candidate_sequence != entry.intent.candidate_applied_sequence) {
                return error.InvalidIndexRepairState;
            }
        }
        const previous_admission = indexRepairAdmission(entry.intent);
        const previous_action_required = indexRepairActionRequired(entry.intent);
        const previous_trigger = entry.intent.trigger;
        const previous_phase = entry.intent.phase;
        const expected = index_repair_state.ExpectedTransition{
            .repair_id = entry.intent.repair_id,
            .revision = entry.intent.revision,
            .phase = entry.intent.phase,
            .config_hash = entry.intent.config_hash,
            .root_generation = entry.intent.root_generation,
            .owner_epoch = entry.intent.owner_epoch,
        };
        if (update.attempt_failure != null and update.replace_last_error) {
            return error.InvalidArgument;
        }

        // Stage every fallible owned-string replacement before mutating the
        // cloned intent. Once staging succeeds, the swaps below are infallible;
        // on a later checkpoint failure, entry.deinit owns the replacements.
        const replacement_candidate_path = if (update.replace_candidate_path)
            if (update.candidate_relative_path) |value| try alloc.dupe(u8, value) else null
        else
            null;
        var replacement_candidate_path_owned = replacement_candidate_path != null;
        errdefer if (replacement_candidate_path_owned) alloc.free(replacement_candidate_path.?);

        const replacement_previous_active_path = if (update.replace_previous_active_path)
            if (update.previous_active_relative_path) |value| try alloc.dupe(u8, value) else null
        else
            null;
        var replacement_previous_active_path_owned = replacement_previous_active_path != null;
        errdefer if (replacement_previous_active_path_owned) alloc.free(replacement_previous_active_path.?);

        const replacement_build_resume_key = if (update.replace_build_resume_key)
            if (update.build_resume_key) |value| try alloc.dupe(u8, value) else null
        else
            null;
        var replacement_build_resume_key_owned = replacement_build_resume_key != null;
        errdefer if (replacement_build_resume_key_owned) alloc.free(replacement_build_resume_key.?);

        const replacement_source_replay_resume_key = if (update.replace_source_replay_resume_key)
            if (update.source_replay_resume_key) |value| try alloc.dupe(u8, value) else null
        else
            null;
        var replacement_source_replay_resume_key_owned = replacement_source_replay_resume_key != null;
        errdefer if (replacement_source_replay_resume_key_owned) alloc.free(replacement_source_replay_resume_key.?);

        const replaces_last_error = update.attempt_failure != null or update.replace_last_error;
        const replacement_last_error_source = if (update.attempt_failure) |failure|
            @as(?[]const u8, failure.err_name)
        else
            update.last_error;
        const replacement_last_error = if (replaces_last_error)
            if (replacement_last_error_source) |value| try alloc.dupe(u8, value) else null
        else
            null;
        var replacement_last_error_owned = replacement_last_error != null;
        errdefer if (replacement_last_error_owned) alloc.free(replacement_last_error.?);

        const now_ms = self.indexRepairNowMs();
        if (update.attempt_failure) |failure| {
            entry.intent.attempt_count = @max(entry.intent.attempt_count, 1);
            entry.intent.failure_streak +|= 1;
            entry.intent.next_retry_at_ms = if (failure.terminal)
                0
            else
                now_ms +| indexRepairRetryDelayMs(repair_id, entry.intent.failure_streak);
        }
        if (update.trigger) |value| entry.intent.trigger = value;
        if (update.operator_job_id) |value| entry.intent.operator_job_id = value;
        if (update.operator_job_created_at_ms) |value| entry.intent.operator_job_created_at_ms = value;
        if (update.phase != null or update.attempt_failure != null) entry.intent.phase = effective_phase;
        if (update.replace_candidate_path) {
            if (entry.intent.candidate_relative_path) |value| alloc.free(value);
            entry.intent.candidate_relative_path = replacement_candidate_path;
            replacement_candidate_path_owned = false;
        }
        if (update.previous_pointer_captured) |value| entry.intent.previous_pointer_captured = value;
        if (update.replace_previous_active_path) {
            if (entry.intent.previous_active_relative_path) |value| alloc.free(value);
            entry.intent.previous_active_relative_path = replacement_previous_active_path;
            replacement_previous_active_path_owned = false;
        }
        if (update.candidate_applied_sequence) |value| entry.intent.candidate_applied_sequence = value;
        if (update.replace_build_resume_key) {
            if (entry.intent.build_resume_key) |value| alloc.free(value);
            entry.intent.build_resume_key = replacement_build_resume_key;
            replacement_build_resume_key_owned = false;
        }
        if (update.build_reprocessed) |value| entry.intent.build_reprocessed = value;
        if (update.replace_source_replay_resume_key) {
            if (entry.intent.source_replay_resume_key) |value| alloc.free(value);
            entry.intent.source_replay_resume_key = replacement_source_replay_resume_key;
            replacement_source_replay_resume_key_owned = false;
        }
        if (update.source_replay_reprocessed) |value| entry.intent.source_replay_reprocessed = value;
        if (update.source_replay_state) |value| entry.intent.source_replay_state = value;
        if (update.estimated_candidate_bytes) |value| entry.intent.estimated_candidate_bytes = value;
        if (update.planned_disk_bytes) |value| entry.intent.planned_disk_bytes = value;
        if (update.target_sequence) |value| entry.intent.target_sequence = value;
        if (update.attempt_count) |value| entry.intent.attempt_count = value;
        if (update.failure_streak) |value| entry.intent.failure_streak = value;
        if (update.next_retry_at_ms) |value| entry.intent.next_retry_at_ms = value;
        if (update.automation) |value| entry.intent.automation = value;
        if (update.owner_epoch) |value| entry.intent.owner_epoch = value;
        if (replaces_last_error) {
            if (entry.intent.last_error) |value| alloc.free(value);
            entry.intent.last_error = replacement_last_error;
            replacement_last_error_owned = false;
        }
        entry.intent.updated_at_ms = now_ms;
        const blocks_service = indexRepairIntentBlocksService(entry.intent);
        const preserve_serviceability = blocks_service and
            previous_admission == .blocked and
            previous_trigger == entry.intent.trigger and
            previous_phase == entry.intent.phase;
        var admission_fence: ?index_manager_mod.IndexManager.RepairAdmissionFence = if (blocks_service and
            !preserve_serviceability)
            try self.core.index_manager.beginRepairAdmissionFence(entry.intent.index_name)
        else
            null;
        defer if (admission_fence) |*fence| {
            self.core.index_manager.cancelRepairAdmissionFence(fence, entry.intent.index_name);
        };
        const control_revision = try index_repair_state.putEntryAt(alloc, location, state.identity, expected, entry);
        const persisted_revision = entry.intent.revision +| 1;
        if (admission_fence) |*fence| {
            self.core.index_manager.finishRepairAdmissionFence(
                fence,
                entry.intent.index_name,
                repairAdmissionVersion(entry.intent, persisted_revision, control_revision),
                true,
                false,
            );
        } else {
            self.core.index_manager.publishRepairAdmission(
                entry.intent.index_name,
                repairAdmissionVersion(entry.intent, persisted_revision, control_revision),
                blocks_service,
                preserve_serviceability,
            );
        }
        noteIndexRepairSchedulerUpsert(self.async_context, entry.intent, persisted_revision, control_revision);
        if (binding_effect == .release) {
            self.core.index_manager.releaseFailedIndexLoadRepairClaim(
                entry.intent.index_name,
                entry.intent.repair_id,
            );
        }
        // Hooks may enqueue work or inspect the DB. Publish them only after the
        // durable transition, scheduler projection, and binding effect are one
        // completed control transaction.
        self.async_context.index_repair_control_mutex.unlock();
        control_locked = false;
        const admission = indexRepairAdmission(entry.intent);
        const action_required = indexRepairActionRequired(entry.intent);
        if (previous_admission != admission or
            previous_action_required != action_required)
        {
            notifyIndexRepairVisibilityHook(
                self.async_context,
                .index_repair_pending,
                entry.intent,
                persisted_revision,
                previous_admission,
                previous_action_required,
                false,
            );
        }
        const persisted_phase = update.phase orelse
            if (update.attempt_failure != null) entry.intent.phase else null;
        if (persisted_phase) |phase| {
            if (self.shadow_index_repair_hook) |hook| {
                if (hook.after_phase_persisted) |after_phase| {
                    try after_phase(hook.ptr, self, repair_id, phase);
                }
            }
        }
    }

    const operator_repair_completion_prefix = "\x00\x00__metadata__:index_generation_repair_completion:";

    fn operatorRepairCompletionKeyAlloc(
        alloc: Allocator,
        index_name: []const u8,
    ) ![]u8 {
        return try std.fmt.allocPrint(alloc, "{s}{s}", .{ operator_repair_completion_prefix, index_name });
    }

    fn operatorRepairAlreadyCompleted(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        job_id: u64,
        job_created_at_ms: u64,
    ) !bool {
        if (job_id == 0 or job_created_at_ms == 0) return false;
        const key = try operatorRepairCompletionKeyAlloc(alloc, cfg.name);
        defer alloc.free(key);
        const raw = self.core.store.get(alloc, key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        defer alloc.free(raw);
        if (raw.len != 48) return error.InvalidIndexRepairState;
        var state = try self.loadOrCreateCurrentIndexRepairState(alloc);
        defer state.deinit(alloc);
        const completed_job_id = std.mem.readInt(u64, raw[32..40], .little);
        const completed_created_at_ms = std.mem.readInt(u64, raw[40..48], .little);
        const completion_covers_request = completed_created_at_ms > job_created_at_ms or
            (completed_created_at_ms == job_created_at_ms and completed_job_id >= job_id);
        return completion_covers_request and
            std.mem.readInt(u64, raw[0..8], .little) == types.indexConfigHash(cfg) and
            std.mem.readInt(u128, raw[8..24], .little) == state.identity.db_identity and
            std.mem.readInt(u64, raw[24..32], .little) == state.identity.root_generation;
    }

    fn persistOperatorRepairCompletion(self: *DB, alloc: Allocator, intent: index_repair_state.IndexRepairIntent) !void {
        return try persistOperatorRepairCompletionContext(self.async_context, alloc, intent);
    }

    fn persistOperatorRepairCompletionContext(ctx: *AsyncContext, alloc: Allocator, intent: index_repair_state.IndexRepairIntent) !void {
        if (intent.operator_job_id == 0 or intent.operator_job_created_at_ms == 0) return;
        const key = try operatorRepairCompletionKeyAlloc(alloc, intent.index_name);
        defer alloc.free(key);
        var raw: [48]u8 = undefined;
        std.mem.writeInt(u64, raw[0..8], intent.config_hash, .little);
        std.mem.writeInt(u128, raw[8..24], intent.db_identity, .little);
        std.mem.writeInt(u64, raw[24..32], intent.root_generation, .little);
        std.mem.writeInt(u64, raw[32..40], intent.operator_job_id, .little);
        std.mem.writeInt(u64, raw[40..48], intent.operator_job_created_at_ms, .little);
        try ctx.store.put(key, &raw);
    }

    const AutomaticDenseGenerationRepairClassification = struct {
        trigger: index_repair_state.Trigger,
        last_error: []const u8,
    };

    const OperatorDenseGenerationValidation = union(enum) {
        online_safe,
        replay_pending,
        fail_closed: AutomaticDenseGenerationRepairClassification,
    };

    fn classifyCurrentDenseGenerationRepair(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
    ) !?AutomaticDenseGenerationRepairClassification {
        if (cfg.kind != .dense_vector) return null;
        const entry = self.core.index_manager.denseIndex(cfg.name) orelse return null;
        const physical_migration_required =
            try self.core.index_manager.denseNativePhysicalMigrationRequired(cfg.name);
        const checkpoint = try self.core.loadProjectionCheckpoint(alloc, cfg.name);
        if (checkpoint.config_hash != types.indexConfigHash(cfg)) return .{
            .trigger = .projection_generation_invalid,
            .last_error = "dense_projection_config_mismatch",
        };
        if (checkpoint.status == .repair_required) return .{
            .trigger = .projection_generation_invalid,
            .last_error = "dense_projection_checkpoint_repair_required",
        };
        if (!try index_manager_mod.denseConfigRequiresArtifactCoverage(alloc, cfg)) return if (physical_migration_required) .{
            .trigger = .storage_format_migration,
            .last_error = "dense_native_v2_migration",
        } else null;
        const expected = (try loadDenseArtifactTargetCounter(alloc, self.core.store, cfg.name)) orelse return .{
            .trigger = .artifact_counter_missing,
            .last_error = "dense_artifact_counter_missing",
        };
        if (entry.index.stats().active_count > expected) {
            const target_sequence = try self.probeDerivedReplayTargetSequence(
                alloc,
                self.core.replaySource(),
                .{ .name = cfg.name, .kind = .dense_vector },
                checkpoint.applied_sequence,
            );
            if (checkpoint.applied_sequence >= target_sequence) return .{
                .trigger = .artifact_coverage_mismatch,
                .last_error = "dense_artifact_coverage_surplus",
            };
        }
        return if (physical_migration_required) .{
            .trigger = .storage_format_migration,
            .last_error = "dense_native_v2_migration",
        } else null;
    }

    /// Performs the potentially linear structural proof only on the admitted
    /// BackendRuntime repair worker, never on the HTTP/operator request path.
    /// Cheap generation, replay, and cardinality checks run first so routine
    /// lag avoids a tree walk. The validation read transaction is stable while
    /// foreground writes continue through the ordinary derived stream.
    fn validateOperatorDenseGenerationForOnlineRebuild(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        options: types.ArtifactRepairRunOptions,
    ) !OperatorDenseGenerationValidation {
        const checkpoint = try self.core.loadProjectionCheckpoint(alloc, cfg.name);
        if (checkpoint.config_hash != types.indexConfigHash(cfg)) return .{ .fail_closed = .{
            .trigger = .projection_generation_invalid,
            .last_error = "dense_projection_config_mismatch",
        } };
        if (checkpoint.status != .clean) return .{ .fail_closed = .{
            .trigger = .projection_generation_invalid,
            .last_error = "dense_projection_checkpoint_not_clean",
        } };
        const target_sequence = try self.probeDerivedReplayTargetSequence(
            alloc,
            self.core.replaySource(),
            .{ .name = cfg.name, .kind = .dense_vector },
            checkpoint.applied_sequence,
        );
        if (checkpoint.applied_sequence < target_sequence) return .replay_pending;

        // Pin both the catalog entry and its generation while inspecting the
        // HBC metadata/tree. The read transaction stabilizes backend pages;
        // this guard additionally prevents an apply or delete/recreate from
        // changing the in-memory generation around that snapshot.
        var apply_guard = self.core.index_manager.lockManagedIndexApply(.{
            .name = cfg.name,
            .kind = .dense_vector,
        }) catch return .{ .fail_closed = .{
            .trigger = .projection_generation_invalid,
            .last_error = "dense_projection_generation_unavailable",
        } };
        defer apply_guard.unlock();

        const entry = self.core.index_manager.denseIndex(cfg.name) orelse return .{ .fail_closed = .{
            .trigger = .projection_generation_invalid,
            .last_error = "dense_projection_generation_unavailable",
        } };

        if (try index_manager_mod.denseConfigRequiresArtifactCoverage(alloc, cfg)) {
            const expected = (try loadDenseArtifactTargetCounter(alloc, self.core.store, cfg.name)) orelse
                return .{ .fail_closed = .{
                    .trigger = .artifact_counter_missing,
                    .last_error = "dense_artifact_counter_missing",
                } };
            if (!denseCoverageMatchesTarget(entry.index.stats().active_count, expected)) {
                return .{ .fail_closed = .{
                    .trigger = .artifact_coverage_mismatch,
                    .last_error = "dense_artifact_coverage_mismatch",
                } };
            }
        }

        const cancel_ctx = if (options.cancel_check) |check| check.ptr else null;
        const cancel_fn = if (options.cancel_check) |check| check.is_requested else null;
        entry.index.validateStoredStructureWithCancellation(alloc, cancel_ctx, cancel_fn) catch |err| switch (err) {
            error.NotFound, error.FileNotFound, error.Corrupted => {
                entry.index.quarantineExperimentalPostingGeneration();
                return .{ .fail_closed = .{
                    .trigger = .projection_generation_invalid,
                    .last_error = "dense_projection_structure_invalid",
                } };
            },
            else => return err,
        };
        return .online_safe;
    }

    /// Replay has already identified the affected dense incarnation and
    /// proved that ordinary catch-up cannot apply its next journal record.
    /// Persist that stronger classification before returning to the repair
    /// scheduler; otherwise an older operator-validation intent waits for the
    /// same impossible replay forever.
    pub fn markDenseReplayArtifactRepairRequired(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
    ) !bool {
        return try self.markDenseReplayRepairRequired(
            alloc,
            index_name,
            .projection_generation_invalid,
            "dense_replay_artifact_missing",
        );
    }

    fn markDenseReplayArtifactCoverageRepairRequired(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
    ) !void {
        _ = try self.markDenseReplayRepairRequired(
            alloc,
            index_name,
            .artifact_coverage_mismatch,
            "dense_replay_artifact_unreadable",
        );
    }

    fn markDenseReplayRepairRequired(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        blocking_trigger: index_repair_state.Trigger,
        reason: []const u8,
    ) !bool {
        // Browser databases have no durable repair sidecar to publish.
        if (builtin.os.tag == .freestanding) return false;
        const cfg = self.core.index_manager.get(index_name) orelse return error.NotFound;
        if (cfg.kind != .dense_vector) return error.InvalidArgument;
        if (try self.indexRepairIdForIndex(alloc, index_name)) |repair_id| {
            var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
            defer entry.deinit(alloc);
            // Replaying the same unavailable artifact must not revoke the
            // serviceability proof that created this shadow-repair intent.
            // Only an unrelated pre-existing intent is promoted to the
            // conservative blocking classification below.
            if (entry.intent.trigger == .replay_artifact_unavailable) return true;
            // Source replay for a newly admitted managed index can reach its
            // canonical consumer before the producer publishes the referenced
            // artifact. That is an expected dependency edge owned by the same
            // durable admission job, not evidence that a serving generation
            // is corrupt. Preserve the job class so the worker can retry via
            // ReplayDocumentNotVisible without manufacturing repair debt.
            if (entry.intent.work_class == .initial_build and
                entry.intent.phase != .terminal)
            {
                return false;
            }
            // A resumable shadow already owns recovery. Do not replace its
            // phase or candidate merely because the stale active generation
            // still cannot consume replay.
            const classifiable_phase = entry.intent.phase == .detected or entry.intent.phase == .preflight;
            if (!classifiable_phase or entry.intent.candidate_relative_path != null) return true;
            try self.updateIndexRepairIntent(alloc, repair_id, .{
                // Preserve the pre-existing intent's fail-closed contract.
                // Only debt created from this replay observation has proof
                // that the retained physical generation is serviceable.
                .trigger = blocking_trigger,
                .next_retry_at_ms = 0,
                .last_error = reason,
                .replace_last_error = true,
            });
            return true;
        }
        _ = try self.createGenerationRepairIntent(
            alloc,
            cfg.*,
            .replay_artifact_unavailable,
            0,
            0,
            reason,
        );
        return true;
    }

    fn createGenerationRepairIntent(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        trigger: index_repair_state.Trigger,
        operator_job_id: u64,
        operator_job_created_at_ms: u64,
        last_error: ?[]const u8,
    ) !u128 {
        return try self.createGenerationRepairIntentAtTarget(
            alloc,
            cfg,
            trigger,
            operator_job_id,
            operator_job_created_at_ms,
            last_error,
            null,
            .not_required,
            .repair,
        );
    }

    fn createGenerationRepairIntentAtTarget(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        trigger: index_repair_state.Trigger,
        operator_job_id: u64,
        operator_job_created_at_ms: u64,
        last_error: ?[]const u8,
        minimum_target_sequence: ?u64,
        source_replay_state: index_repair_state.SourceReplayState,
        work_class: index_repair_state.WorkClass,
    ) !u128 {
        lockAtomic(&self.async_context.index_repair_control_mutex);
        var control_locked = true;
        defer if (control_locked) self.async_context.index_repair_control_mutex.unlock();
        var state = try self.loadOrCreateCurrentIndexRepairState(alloc);
        defer state.deinit(alloc);
        if (state.findIndex(cfg.name)) |i| return state.entries.items[i].intent.repair_id;
        const location = try self.indexRepairStateLocation();
        const now_ms = self.indexRepairNowMs();
        const target_sequence = @max(
            self.core.nextDerivedSequence(),
            minimum_target_sequence orelse 0,
        );
        const repair_id = try index_repair_state.newRepairId(alloc);
        const index_name = try alloc.dupe(u8, cfg.name);
        var intent_allocations_transferred = false;
        errdefer if (!intent_allocations_transferred) alloc.free(index_name);
        const owned_last_error = if (last_error) |value| try alloc.dupe(u8, value) else null;
        errdefer if (!intent_allocations_transferred) if (owned_last_error) |value| alloc.free(value);
        var intent = index_repair_state.IndexRepairIntent{
            .repair_id = repair_id,
            .db_identity = state.identity.db_identity,
            .group_id = self.localRepairGroupId(),
            .replica_id = state.identity.replica_id,
            .root_generation = state.identity.root_generation,
            .index_name = index_name,
            .kind = cfg.kind,
            .config_hash = types.indexConfigHash(cfg),
            .trigger = trigger,
            .work_class = work_class,
            .operator_job_id = operator_job_id,
            .operator_job_created_at_ms = operator_job_created_at_ms,
            .detected_sequence = target_sequence,
            .target_sequence = target_sequence,
            .started_at_ms = now_ms,
            .updated_at_ms = now_ms,
            .owner_epoch = 0,
            .last_error = owned_last_error,
            .source_replay_state = source_replay_state,
        };
        intent_allocations_transferred = true;
        defer intent.deinit(alloc);
        const blocks_service = indexRepairIntentBlocksService(intent);
        var admission_fence: ?index_manager_mod.IndexManager.RepairAdmissionFence = if (blocks_service)
            try self.core.index_manager.beginRepairAdmissionFence(intent.index_name)
        else
            null;
        defer if (admission_fence) |*fence| {
            self.core.index_manager.cancelRepairAdmissionFence(fence, intent.index_name);
        };
        const control_revision = index_repair_state.putEntryAt(alloc, location, state.identity, null, .{ .intent = intent }) catch |err| switch (err) {
            // Another operator/maintenance caller may win creation between the
            // optimistic state read and the checkpoint CAS. Adopt that durable
            // intent; callers subsequently attach their job identity or
            // promote its safety classification with revision-fenced retries.
            error.RepairTransitionConflict => return (try self.indexRepairIdForIndex(alloc, cfg.name)) orelse return err,
            else => return err,
        };
        const persisted_revision: u64 = 1;
        if (admission_fence) |*fence| {
            self.core.index_manager.finishRepairAdmissionFence(
                fence,
                intent.index_name,
                repairAdmissionVersion(intent, persisted_revision, control_revision),
                true,
                false,
            );
        }
        noteIndexRepairSchedulerUpsert(self.async_context, intent, persisted_revision, control_revision);
        self.async_context.index_repair_control_mutex.unlock();
        control_locked = false;
        notifyIndexRepairVisibilityHook(
            self.async_context,
            .index_repair_pending,
            intent,
            persisted_revision,
            .serviceable,
            false,
            false,
        );
        return repair_id;
    }

    fn createOperatorGenerationRepairIntent(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        operator_job_id: u64,
        operator_job_created_at_ms: u64,
    ) !u128 {
        const repair_id = try self.createGenerationRepairIntent(
            alloc,
            cfg,
            if (cfg.kind == .dense_vector) .operator_generation_validation else .operator_generation_rebuild,
            operator_job_id,
            operator_job_created_at_ms,
            null,
        );
        try self.attachOperatorRepairRequest(
            alloc,
            repair_id,
            operator_job_id,
            operator_job_created_at_ms,
        );
        return repair_id;
    }

    /// Materializes one catalog admission outbox row into a durable generation
    /// repair. Until that repair activates, the marker remains the fail-closed
    /// admission authority for every index kind, including algebraic.
    pub fn materializeManagedIndexAdmission(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
    ) !?u128 {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var structural_guard = self.beginIndexStructuralMutation("managed index admission materialization", index_name);
        defer structural_guard.deinit();
        // Catalog entries are owned by the apply lifecycle. Hold its exclusive
        // lock through marker validation and checkpoint publication so deletion or
        // replacement cannot free the config or commit absence in between.
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        const key = try internal_keys.managedIndexAdmissionKeyAlloc(alloc, index_name);
        defer alloc.free(key);
        const raw = self.core.store.get(alloc, key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        defer alloc.free(raw);
        return try self.materializeManagedIndexAdmissionValueLocked(alloc, index_name, key, raw);
    }

    /// Requires the DB apply lock. The returned catalog pointer remains valid
    /// until the repair intent has durably adopted its identity.
    fn materializeManagedIndexAdmissionValueLocked(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        key: []const u8,
        raw: []const u8,
    ) !?u128 {
        const marker = try decodeManagedIndexAdmissionMarker(raw);
        const cfg = self.core.index_manager.get(index_name) orelse {
            try self.core.store.delete(key);
            return null;
        };
        if (builtin.is_test) {
            if (test_managed_admission_materialization_hook) |hook| {
                if (hook.after_config_lookup) |after_lookup| after_lookup(hook.ptr, self, index_name);
            }
        }
        if (types.indexConfigHash(cfg.*) != marker.config_hash)
            return error.InvalidManagedIndexAdmission;
        if (marker.disposition == .managed_rebuild and marker.source_doc_count == 0)
            return error.InvalidManagedIndexAdmission;
        const summary = try self.managedAdmissionVisibilitySummary();
        const current_identity_generation = @max(
            summary.max_created_generation,
            summary.max_deleted_generation,
        );
        if (current_identity_generation < marker.identity_generation)
            return error.InvalidDocIdentity;

        if (!indexKindSupportsManagedGenerationRepair(cfg.kind))
            return error.InvalidManagedIndexAdmission;
        const source_replay_state: index_repair_state.SourceReplayState = if (try self.core.indexRequiresEnrichmentReplay(index_name))
            .pending
        else
            .not_required;
        return try self.createGenerationRepairIntentAtTarget(
            alloc,
            cfg.*,
            .catalog_admission,
            0,
            0,
            managed_catalog_admission_rebuild_reason,
            marker.replay_target_sequence,
            source_replay_state,
            .initial_build,
        );
    }

    fn requestManagedAdmissionMaterialization(self: *DB) void {
        self.managed_admission.request();
    }

    fn managedAdmissionMaterializationPending(self: *const DB) bool {
        return self.managed_admission.pending();
    }

    /// Drain every generation observed while a pass is in flight. A marker
    /// commit increments requested after its atomic catalog transaction; the
    /// completed generation advances only to the snapshot owned by one
    /// successful pass, so a concurrent commit necessarily forces another.
    fn drainManagedIndexAdmissions(self: *DB, alloc: Allocator) !void {
        var structural_guard = self.beginIndexStructuralMutation("managed index admission drain", "*");
        defer structural_guard.deinit();
        try self.drainManagedIndexAdmissionsUnderStructuralGuard(alloc);
    }

    /// The caller already owns index structural serialization.
    fn drainManagedIndexAdmissionsUnderStructuralGuard(self: *DB, alloc: Allocator) !void {
        try self.managed_admission.drain(alloc, .{ .ptr = self, .pass = managedAdmissionPass });
    }

    fn managedAdmissionPass(ptr: *anyopaque, alloc: Allocator) !void {
        const self: *DB = @ptrCast(@alignCast(ptr));
        try self.materializeManagedIndexAdmissionsOnce(alloc);
    }

    fn materializeManagedIndexAdmissionsOnce(self: *DB, alloc: Allocator) !void {
        // This is intentionally a structural lock, not a general repair lock:
        // the primary marker, catalog membership, and borrowed config must
        // remain one lifecycle observation through checkpoint publication.
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        const prefix = try internal_keys.managedIndexAdmissionRootPrefixAlloc(alloc);
        defer alloc.free(prefix);
        const admissions = try self.core.store.scanPrefix(alloc, prefix);
        defer docstore_mod.DocStore.freeResults(alloc, admissions);
        try self.materializeManagedIndexAdmissionRowsLocked(alloc, admissions);
        if (builtin.is_test) {
            if (test_managed_admission_materialization_hook) |hook| {
                if (hook.after_pass) |after_pass| after_pass(hook.ptr, self);
            }
        }
    }

    /// Requires the DB apply lock.
    fn materializeManagedIndexAdmissionRowsLocked(
        self: *DB,
        alloc: Allocator,
        admissions: []const docstore_mod.OwnedKVPair,
    ) !void {
        if (admissions.len == 0) return;

        const configs = try self.core.listIndexes(alloc);
        defer types.freeIndexConfigs(alloc, configs);
        var configs_by_name = std.StringHashMapUnmanaged(*const types.IndexConfig).empty;
        defer configs_by_name.deinit(alloc);
        try configs_by_name.ensureTotalCapacity(alloc, @intCast(configs.len));
        for (configs) |*cfg| {
            configs_by_name.putAssumeCapacity(cfg.name, cfg);
        }

        for (admissions) |admission| {
            const index_name = try internal_keys.managedIndexAdmissionNameAlloc(alloc, admission.key);
            defer alloc.free(index_name);
            if (configs_by_name.get(index_name) == null) {
                // Catalog deletion wins over an orphaned outbox row. Only
                // catalog absence proves orphanhood; a same-name kind/hash
                // mismatch is corruption and retains its fail-closed marker.
                try self.core.store.delete(admission.key);
                self.core.index_manager.clearManagedAdmissionSnapshotForIndex(index_name);
                self.core.index_manager.clearUnscopedRepairUnavailable(index_name);
                continue;
            }
            _ = try self.materializeManagedIndexAdmissionValueLocked(
                alloc,
                index_name,
                admission.key,
                admission.value,
            );
        }
    }

    fn attachOperatorRepairRequest(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
        operator_job_id: u64,
        operator_job_created_at_ms: u64,
    ) !void {
        if (operator_job_id == 0 or operator_job_created_at_ms == 0) return;
        var attempts: usize = 0;
        while (attempts < 4) : (attempts += 1) {
            var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
            defer entry.deinit(alloc);
            const existing_is_newer = entry.intent.operator_job_created_at_ms > operator_job_created_at_ms or
                (entry.intent.operator_job_created_at_ms == operator_job_created_at_ms and
                    entry.intent.operator_job_id >= operator_job_id);
            if (existing_is_newer) return;
            self.updateIndexRepairIntent(alloc, repair_id, .{
                .operator_job_id = operator_job_id,
                .operator_job_created_at_ms = operator_job_created_at_ms,
            }) catch |err| switch (err) {
                error.RepairTransitionConflict => continue,
                else => return err,
            };
            return;
        }
        return error.RepairTransitionConflict;
    }

    fn automaticDenseGenerationRepairTriggerPriority(trigger: index_repair_state.Trigger) u8 {
        return switch (trigger) {
            .operator_generation_rebuild, .operator_generation_validation, .storage_format_migration, .artifact_baseline_adoption => 0,
            .artifact_coverage_mismatch, .replay_artifact_unavailable => 1,
            .artifact_counter_missing => 2,
            .incomplete_bulk_publish, .root_generation_rebuild, .projection_generation_invalid, .catalog_admission => 3,
        };
    }

    const AutomaticDenseGenerationRepairIntentOutcome = struct {
        repair_id: u128,
        made_progress: bool,
    };

    fn ensureAutomaticDenseGenerationRepairIntent(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        trigger: index_repair_state.Trigger,
        last_error: []const u8,
    ) !u128 {
        return (try self.ensureAutomaticDenseGenerationRepairIntentOutcome(
            alloc,
            cfg,
            trigger,
            last_error,
        )).repair_id;
    }

    fn ensureAutomaticDenseGenerationRepairIntentOutcome(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        trigger: index_repair_state.Trigger,
        last_error: []const u8,
    ) !AutomaticDenseGenerationRepairIntentOutcome {
        std.debug.assert(trigger == .artifact_coverage_mismatch or
            trigger == .artifact_counter_missing or
            trigger == .projection_generation_invalid or
            trigger == .storage_format_migration);

        // Correctness repairs close the query gate before persistence. A
        // physical-format migration is different: v1 remains the proven
        // serving generation while its v2 shadow is built and caught up.
        const close_query_gate = trigger != .storage_format_migration;
        const was_unavailable = self.core.index_manager.repairUnavailable(cfg.name);
        if (close_query_gate) try self.core.index_manager.markUnscopedRepairUnavailable(cfg.name);

        const existing_repair_id = try self.indexRepairIdForIndex(alloc, cfg.name);
        const repair_id = existing_repair_id orelse try self.createGenerationRepairIntent(
            alloc,
            cfg,
            trigger,
            0,
            0,
            last_error,
        );
        if (existing_repair_id == null) {
            std.log.warn("dense generation repair intent created index={s} trigger={s} reason={s}", .{
                cfg.name,
                @tagName(trigger),
                last_error,
            });
        }

        // Creation races with an operator request are harmless: re-read the
        // winning intent and promote its safety classification when needed.
        var attempts: usize = 0;
        while (attempts < 4) : (attempts += 1) {
            var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
            defer entry.deinit(alloc);
            if (automaticDenseGenerationRepairTriggerPriority(trigger) <=
                automaticDenseGenerationRepairTriggerPriority(entry.intent.trigger)) return .{
                .repair_id = repair_id,
                .made_progress = existing_repair_id == null or (close_query_gate and !was_unavailable),
            };
            self.updateIndexRepairIntent(alloc, repair_id, .{
                .trigger = trigger,
                .replace_last_error = true,
                .last_error = last_error,
            }) catch |err| switch (err) {
                error.RepairTransitionConflict => continue,
                else => return err,
            };
            return .{ .repair_id = repair_id, .made_progress = true };
        }
        return error.RepairTransitionConflict;
    }

    const DenseArtifactCounterBootstrapSnapshot = struct {
        txn: docstore_mod.DocStore.Txn,
        attempt_id: u128,

        pub fn deinit(self: *@This()) void {
            self.txn.abort();
            self.* = undefined;
        }
    };

    fn beginDenseArtifactCounterBootstrapSnapshot(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        repair_id: u128,
    ) !DenseArtifactCounterBootstrapSnapshot {
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();

        if (try loadDenseArtifactTargetCounter(alloc, self.core.store, index_name) != null) {
            return error.DenseArtifactCounterAlreadyInitialized;
        }
        const attempt_id = try index_repair_state.newRepairId(alloc);
        const marker_key = try denseArtifactCounterBootstrapKeyAlloc(alloc, index_name);
        defer alloc.free(marker_key);
        var marker_value: [dense_artifact_counter_bootstrap_encoded_len]u8 = undefined;
        encodeDenseArtifactCounterBootstrap(.{
            .repair_id = repair_id,
            .attempt_id = attempt_id,
        }, &marker_value);
        try self.core.store.putBatch(&.{.{ .key = marker_key, .value = &marker_value }}, &.{});

        // The apply lock orders marker publication before this snapshot and
        // before every later artifact mutation. Once it is released, those
        // mutations update the marker's signed delta in their own atomic store
        // batch while this stable snapshot is counted without blocking writes.
        return .{
            .txn = try self.core.store.beginReadTxn(),
            .attempt_id = attempt_id,
        };
    }

    fn finishDenseArtifactCounterBootstrap(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        repair_id: u128,
        attempt_id: u128,
        snapshot_count: u64,
    ) !void {
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();

        if (try loadDenseArtifactTargetCounter(alloc, self.core.store, index_name) != null) return;
        const marker = (try loadDenseArtifactCounterBootstrap(alloc, self.core.store, index_name)) orelse
            return error.DenseArtifactCounterBootstrapMissing;
        if (marker.repair_id != repair_id or marker.attempt_id != attempt_id) {
            return error.StaleDenseArtifactCounterBootstrap;
        }

        const final_count_i128 = @as(i128, @intCast(snapshot_count)) + @as(i128, marker.delta);
        if (final_count_i128 < 0 or final_count_i128 > std.math.maxInt(u64)) {
            return error.InvalidDenseArtifactCounterBootstrapDelta;
        }
        const counter_key = try denseArtifactTargetCounterKeyAlloc(alloc, index_name);
        defer alloc.free(counter_key);
        const marker_key = try denseArtifactCounterBootstrapKeyAlloc(alloc, index_name);
        defer alloc.free(marker_key);
        var counter_value: [8]u8 = undefined;
        std.mem.writeInt(u64, &counter_value, @intCast(final_count_i128), .little);
        try self.core.store.putBatch(
            &.{.{ .key = counter_key, .value = &counter_value }},
            &.{marker_key},
        );
    }

    fn countDenseArtifactsForConfigFromReadTxn(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        read_txn: *docstore_mod.DocStore.Txn,
        cancel_check: ?types.RepairCancelCheck,
    ) !u64 {
        const artifact_names = try index_manager_mod.denseConfigArtifactNamesAlloc(alloc, cfg);
        defer {
            for (artifact_names) |name| alloc.free(name);
            alloc.free(artifact_names);
        }
        const dims = try index_manager_mod.denseConfigDimensions(alloc, cfg);
        const lower = try self.core.documentRangeLowerAlloc("");
        defer self.core.alloc.free(lower);

        const ScanState = struct {
            alloc: Allocator,
            artifact_names: []const []const u8,
            dims: u32,
            cancel_check: ?types.RepairCancelCheck,
            scanned: usize = 0,
            count: u64 = 0,

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                state.scanned +|= 1;
                if ((state.scanned & 1023) == 0) {
                    if (state.cancel_check) |check| if (check.requested()) return error.Canceled;
                }
                if (!internal_keys.isInternalUserKey(key)) return .@"continue";
                var artifact_ref = (try decodeArtifactRefIfKnownAlloc(state.alloc, key)) orelse return .@"continue";
                defer artifact_ref.deinit(state.alloc);
                if (artifact_ref.kind != .embedding) return .@"continue";
                var selected = false;
                for (state.artifact_names) |name| {
                    if (std.mem.eql(u8, artifact_ref.name, name)) {
                        selected = true;
                        break;
                    }
                }
                if (!selected) return .@"continue";
                const artifact_dims = enrichment_artifact_codec.decodeDenseEmbeddingDims(value) catch |err| {
                    if (isRecoverableEmbeddingArtifactError(err)) return .@"continue";
                    return err;
                };
                if (artifact_dims == state.dims) state.count +|= 1;
                return .@"continue";
            }
        };

        var scan_state = ScanState{
            .alloc = alloc,
            .artifact_names = artifact_names,
            .dims = dims,
            .cancel_check = cancel_check,
        };
        try self.core.store.scanReadTxnWithContext(read_txn, lower, "", .{}, &scan_state, ScanState.scanEntry);
        return scan_state.count;
    }

    fn ensureDenseArtifactTargetCounterForRepair(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        repair_id: u128,
        cancel_check: ?types.RepairCancelCheck,
    ) !void {
        if (!try index_manager_mod.denseConfigRequiresArtifactCoverage(alloc, cfg)) return;
        if (try loadDenseArtifactTargetCounter(alloc, self.core.store, cfg.name) != null) return;

        // Counter bootstrap is a background repair phase in its own right. It
        // can hold a stable store snapshot for a full artifact scan, so admit
        // it before publishing the marker rather than doing unaccounted work
        // that a later shadow-build admission would reject.
        var bootstrap_admission: ?resource_manager_mod.Reservation = if (self.core.index_manager.resource_manager) |manager|
            try reserveDenseCounterBootstrapWorkingSet(manager)
        else
            null;
        defer if (bootstrap_admission) |*reservation| reservation.release();

        var bootstrap_snapshot = self.beginDenseArtifactCounterBootstrapSnapshot(alloc, cfg.name, repair_id) catch |err| switch (err) {
            error.DenseArtifactCounterAlreadyInitialized => return,
            else => return err,
        };
        defer bootstrap_snapshot.deinit();

        const snapshot_count = try self.countDenseArtifactsForConfigFromReadTxn(
            alloc,
            cfg,
            &bootstrap_snapshot.txn,
            cancel_check,
        );
        if (cancel_check) |check| if (check.requested()) return error.Canceled;
        try self.finishDenseArtifactCounterBootstrap(
            alloc,
            cfg.name,
            repair_id,
            bootstrap_snapshot.attempt_id,
            snapshot_count,
        );
    }

    fn validateIndexRepairSourcePreflight(self: *DB, alloc: Allocator, cfg: types.IndexConfig) !void {
        if (!try index_manager_mod.denseConfigRequiresArtifactCoverage(alloc, cfg)) return;
        const target_count = try loadDenseArtifactTargetCounter(alloc, self.core.store, cfg.name);
        if (target_count == null) return error.RepairSourceCoverageIncomplete;
    }

    fn currentIndexRepairIdMatches(self: *const DB, alloc: Allocator, index_name: []const u8, expected_repair_id: ?u128) !?u128 {
        const repair_id = (try self.indexRepairIdForIndex(alloc, index_name)) orelse {
            if (expected_repair_id != null) return error.StaleIndexRepairControl;
            return null;
        };
        if (expected_repair_id) |expected| {
            if (repair_id != expected) return error.StaleIndexRepairControl;
        }
        return repair_id;
    }

    pub fn pauseAutomaticIndexRepair(self: *DB, alloc: Allocator, index_name: []const u8, expected_repair_id: ?u128) !bool {
        const repair_id = (try self.currentIndexRepairIdMatches(alloc, index_name, expected_repair_id)) orelse return false;
        try self.updateIndexRepairIntent(alloc, repair_id, .{ .automation = .paused });
        _ = self.requestActiveIndexRepairCancellation(index_name);
        return true;
    }

    pub fn cancelCurrentIndexRepairAttempt(self: *DB, alloc: Allocator, index_name: []const u8, expected_repair_id: ?u128) !bool {
        _ = (try self.currentIndexRepairIdMatches(alloc, index_name, expected_repair_id)) orelse return false;
        return self.requestActiveIndexRepairCancellation(index_name);
    }

    pub fn resumeAutomaticIndexRepair(self: *DB, alloc: Allocator, index_name: []const u8, expected_repair_id: ?u128) !bool {
        const repair_id = (try self.currentIndexRepairIdMatches(alloc, index_name, expected_repair_id)) orelse return false;
        try self.updateIndexRepairIntent(alloc, repair_id, .{
            .automation = .enabled,
            .next_retry_at_ms = 0,
            .replace_last_error = true,
        });
        return true;
    }

    /// Quiesce repair for deletion while retaining its durable gate. The caller
    /// owns the returned lease and removes the checkpoint only after catalog
    /// absence and marker deletion commit atomically.
    fn prepareIndexRepairForDeletion(self: *DB, alloc: Allocator, index_name: []const u8) !?u128 {
        const repair_id = (try self.indexRepairIdForIndex(alloc, index_name)) orelse return null;
        if (!(try self.beginIndexRepairLease(index_name))) return error.IndexRepairInProgress;
        errdefer self.endIndexRepairLease(index_name);
        var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer entry.deinit(alloc);
        if (entry.intent.candidate_relative_path) |candidate| {
            if (!try self.core.index_manager.isRepairCandidateActive(index_name, candidate)) {
                try self.discardInactiveIndexRepairCandidate(alloc, repair_id);
            }
        }
        return repair_id;
    }

    fn removeOrphanedIndexRepairIntents(self: *DB, alloc: Allocator) !void {
        var state = self.loadIndexRepairState(alloc) catch |err| switch (err) {
            error.FileNotFound => return,
            else => return err,
        };
        defer state.deinit(alloc);
        var orphan_ids = std.ArrayListUnmanaged(u128).empty;
        defer orphan_ids.deinit(alloc);
        for (state.entries.items) |entry| {
            if (self.core.index_manager.get(entry.intent.index_name) == null) {
                try orphan_ids.append(alloc, entry.intent.repair_id);
            }
        }
        for (orphan_ids.items) |repair_id| try self.removeIndexRepairIntentAndPin(alloc, repair_id);
    }

    /// Requires the DB apply lock. Fresh admission must not adopt repair state
    /// from a catalog generation whose deletion already committed.
    fn removeOrphanedIndexRepairIntentForFreshAdmission(self: *DB, alloc: Allocator, index_name: []const u8) !void {
        if (self.core.index_manager.get(index_name) != null) return;
        const repair_id = (try self.indexRepairIdForIndex(alloc, index_name)) orelse return;
        try self.removeIndexRepairIntentAndPin(alloc, repair_id);
    }

    fn recordIndexRepairAttemptFailure(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
        err_name: []const u8,
        terminal: bool,
    ) !void {
        try self.updateIndexRepairIntentWithBindingEffect(
            alloc,
            repair_id,
            .{
                .attempt_failure = .{
                    .err_name = err_name,
                    .terminal = terminal,
                },
            },
            if (terminal) .release else .retain,
            null,
        );
    }

    fn indexRepairFailureIsTerminal(err: anyerror) bool {
        return switch (err) {
            error.InvalidArgument,
            error.NotFound,
            error.UnsupportedOperation,
            error.InvalidIndexRepairState,
            error.InvalidRepairCandidatePath,
            error.ReplicaIdentityMismatch,
            error.DurableIndexRepairStateUnavailable,
            error.RepairSourceCoverageIncomplete,
            error.IndexRepairConfigurationChanged,
            => true,
            else => false,
        };
    }

    test "index repair treats source coverage lag as retryable" {
        try std.testing.expect(indexRepairFailureIsTerminal(error.RepairSourceCoverageIncomplete));
        try std.testing.expect(indexRepairFailureIsTerminal(error.IndexRepairConfigurationChanged));
        try std.testing.expectEqual(
            index_repair_state.Phase.detected,
            retryableIndexRepairTerminalPhase("RepairSourceCoverageIncomplete", .operator_generation_rebuild).?,
        );
        try std.testing.expect(
            retryableIndexRepairTerminalPhase("RepairSourceCoverageIncomplete", .projection_generation_invalid) == null,
        );
        try std.testing.expectEqual(
            index_repair_state.Phase.detected,
            retryableIndexRepairTerminalPhase("RepairSourceCoverageIncomplete", .artifact_coverage_mismatch).?,
        );
        try std.testing.expect(
            retryableIndexRepairTerminalPhase("IndexRepairConfigurationChanged", .operator_generation_rebuild) == null,
        );
    }

    test "rollback predecessor retry policy preserves automatic recovery boundaries" {
        try std.testing.expectEqual(
            ActivatedIndexRepairRollback.retry_deferred,
            activatedIndexRepairRollbackFailureDisposition(.retry_open),
        );
        try std.testing.expectEqual(
            ActivatedIndexRepairRollback.rebuild_required,
            activatedIndexRepairRollbackFailureDisposition(.rebuild_from_artifacts),
        );
        try std.testing.expectEqual(
            ActivatedIndexRepairRollback.action_required,
            activatedIndexRepairRollbackFailureDisposition(.manual_intervention),
        );
    }

    test "rollback action required atomically retires activation certification" {
        const alloc = std.testing.allocator;
        var path_tmp = try TestDirectory.init("db");
        defer path_tmp.cleanup();
        const path = path_tmp.path().ptr;
        defer cleanupTempDir(path);

        var db = try DB.open(alloc, std.mem.span(path), .{
            .open_mode = .writer_no_replay,
            .start_index_workers = false,
            .ttl_cleanup = .{ .enabled = false },
        });
        defer db.close();
        try db.addIndex(.{
            .name = "dense_idx",
            .kind = .dense_vector,
            .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\",\"external\":true}",
        });
        const cfg = db.core.index_manager.get("dense_idx") orelse return error.TestUnexpectedResult;
        const repair_id = try db.createGenerationRepairIntent(
            alloc,
            cfg.*,
            .operator_generation_validation,
            0,
            0,
            null,
        );
        try db.updateIndexRepairIntent(alloc, repair_id, .{ .phase = .preflight });
        try db.updateIndexRepairIntent(alloc, repair_id, .{
            .phase = .building,
            .candidate_relative_path = ".repair-shadow-terminal/indexes/dense_idx",
            .replace_candidate_path = true,
        });
        try db.updateIndexRepairIntent(alloc, repair_id, .{
            .phase = .catching_up,
            .candidate_applied_sequence = 17,
        });
        try db.updateIndexRepairIntent(alloc, repair_id, .{
            .phase = .ready,
            .candidate_applied_sequence = 17,
        });
        try db.updateIndexRepairIntent(alloc, repair_id, .{
            .phase = .activating,
            .candidate_applied_sequence = 17,
            .target_sequence = 17,
        });
        try std.testing.expectError(error.InvalidIndexRepairState, db.updateIndexRepairIntent(alloc, repair_id, .{
            .phase = .validating,
            .candidate_applied_sequence = 18,
        }));
        try db.updateIndexRepairIntent(alloc, repair_id, .{ .phase = .rolling_back });

        // The real manual-predecessor-failure disposition deletes the inactive
        // candidate and combines its reset with a terminal failure update. The
        // terminal phase leaves the certified family, so clearing the obsolete
        // manifest sequence is both safe and required for coherent status.
        try db.discardInactiveIndexRepairCandidateWithTerminal(
            alloc,
            repair_id,
            "rollback_predecessor_manual_intervention",
        );

        var terminal = try db.loadIndexRepairEntryById(alloc, repair_id);
        defer terminal.deinit(alloc);
        try std.testing.expectEqual(index_repair_state.Phase.terminal, terminal.intent.phase);
        try std.testing.expect(terminal.intent.candidate_relative_path == null);
        try std.testing.expectEqual(@as(u64, 0), terminal.intent.candidate_applied_sequence);
        try std.testing.expectEqualStrings(
            "rollback_predecessor_manual_intervention",
            terminal.intent.last_error.?,
        );
        try std.testing.expect(indexRepairActionRequired(terminal.intent));
    }

    fn removeIndexRepairIntentAndPin(self: *DB, alloc: Allocator, repair_id: u128) !void {
        return try removeIndexRepairIntentAndPinContext(self.async_context, alloc, repair_id);
    }

    fn removeIndexRepairIntentAndPinContext(ctx: *AsyncContext, alloc: Allocator, repair_id: u128) !void {
        lockAtomic(&ctx.index_repair_control_mutex);
        var control_locked = true;
        defer if (control_locked) ctx.index_repair_control_mutex.unlock();
        // Pin creation, pin removal, the in-memory pressure gate, and replay
        // truncation must observe one serialization order. Per-index repair
        // leases are insufficient because two different indexes may complete
        // concurrently.
        const repair_replay_mutex = ctx.repair_replay_mutex orelse return error.DurableIndexRepairStateUnavailable;
        repair_replay_mutex.lockUncancelable(ctx.index_manager.checkpointIo());
        defer repair_replay_mutex.unlock(ctx.index_manager.checkpointIo());
        const location = try indexRepairStateLocationContext(ctx);
        var state = try index_repair_state.loadAt(alloc, location);
        defer state.deinit(alloc);
        const entry = blk: {
            for (state.entries.items) |candidate| {
                if (candidate.intent.repair_id == repair_id) break :blk candidate;
            }
            return error.IndexRepairIntentNotFound;
        };
        if (entry.intent.phase == .cleanup) try persistOperatorRepairCompletionContext(ctx, alloc, entry.intent);
        var remaining_replay_pin = false;
        for (state.entries.items) |candidate| {
            if (candidate.intent.repair_id != repair_id and candidate.pin != null) {
                remaining_replay_pin = true;
                break;
            }
        }
        // For managed admission, clear the primary-store lifecycle marker only
        // after activation published a clean generation. Do this before
        // removing the checkpoint intent: a crash between the two leaves
        // harmless resumable checkpoint debt, never an admitted generation
        // with no proof.
        const admission_key = try internal_keys.managedIndexAdmissionKeyAlloc(alloc, entry.intent.index_name);
        defer alloc.free(admission_key);
        ctx.store.delete(admission_key) catch |err| switch (err) {
            error.NotFound => {},
            else => return err,
        };
        const control_revision = try index_repair_state.removeEntryAndPinAt(alloc, location, state.identity, .{
            .repair_id = repair_id,
            .revision = entry.intent.revision,
            .phase = entry.intent.phase,
            .config_hash = entry.intent.config_hash,
            .root_generation = entry.intent.root_generation,
            .owner_epoch = entry.intent.owner_epoch,
        });
        noteIndexRepairSchedulerRemove(ctx, state.identity, repair_id, control_revision);
        ctx.index_repair_replay_pinned.store(remaining_replay_pin, .release);
        ctx.index_manager.publishRepairAdmission(
            entry.intent.index_name,
            repairAdmissionVersion(entry.intent, entry.intent.revision +| 1, control_revision),
            false,
            false,
        );
        ctx.index_manager.releaseFailedIndexLoadRepairClaim(
            entry.intent.index_name,
            entry.intent.repair_id,
        );
        ctx.index_repair_control_mutex.unlock();
        control_locked = false;
        notifyIndexRepairVisibilityHook(
            ctx,
            .index_repair_cleared,
            entry.intent,
            entry.intent.revision,
            indexRepairAdmission(entry.intent),
            indexRepairActionRequired(entry.intent),
            remaining_replay_pin,
        );
    }

    pub const denseRepairWriteBackpressured = local_mutation.denseRepairWriteBackpressured;

    fn discardInactiveIndexRepairCandidate(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
    ) !void {
        return try self.discardInactiveIndexRepairCandidateWithTerminal(
            alloc,
            repair_id,
            null,
        );
    }

    /// Deletes only a proven-inactive candidate, then publishes its durable
    /// disposition in one repair-control checkpoint. A manual predecessor
    /// failure must not expose an intermediate runnable preflight intent if the
    /// process stops after filesystem cleanup.
    fn discardInactiveIndexRepairCandidateWithTerminal(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
        terminal_reason: ?[]const u8,
    ) !void {
        var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer entry.deinit(alloc);
        const candidate = entry.intent.candidate_relative_path orelse return;
        try index_repair_state.validateCandidateRelativePath(entry.intent.index_name, candidate);
        if (try self.core.index_manager.isRepairCandidateActive(entry.intent.index_name, candidate)) {
            return error.RepairCandidateAlreadyActive;
        }
        const separator = std.mem.indexOfScalar(u8, candidate, '/') orelse return error.InvalidRepairCandidatePath;
        const shadow_root = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ self.core.path, candidate[0..separator] });
        defer alloc.free(shadow_root);
        if (entry.intent.kind == .algebraic) {
            // Algebraic generations live in the primary store and may be much
            // larger than a scheduler turn. The directory is their durable
            // namespace marker: clear only the writer marker here, detach the
            // intent below, then let paged orphan collection drain the keys.
            try index_manager_mod.IndexManager.clearRepairShadowInProgressMarker(alloc, shadow_root);
        } else {
            var io_impl = threadedIo();
            defer io_impl.deinit();
            // `deleteTree` is idempotent for an absent root. A cancelled
            // pre-checkpoint build may already have removed its non-reopenable
            // shadow in the unwind path.
            try std.Io.Dir.cwd().deleteTree(io_impl.io(), shadow_root);
        }
        const reset = IndexRepairIntentUpdate{
            .phase = .preflight,
            .replace_candidate_path = true,
            .replace_build_resume_key = true,
            .build_reprocessed = 0,
            .candidate_applied_sequence = 0,
            .target_sequence = self.core.nextDerivedSequence(),
            .failure_streak = 0,
            .next_retry_at_ms = 0,
            .replace_last_error = true,
        };
        if (terminal_reason) |reason| {
            var terminal = reset;
            terminal.phase = null;
            terminal.failure_streak = null;
            terminal.next_retry_at_ms = null;
            terminal.replace_last_error = false;
            terminal.attempt_failure = .{
                .err_name = reason,
                .terminal = true,
            };
            try self.updateIndexRepairIntentWithBindingEffect(
                alloc,
                repair_id,
                terminal,
                .release,
                null,
            );
        } else {
            try self.updateIndexRepairIntent(alloc, repair_id, reset);
        }
        if (entry.intent.kind == .algebraic) self.scheduleInactiveRepairShadowCleanup();
    }

    const ActivatedIndexRepairCertificationFailure = enum {
        manifest_missing,
        manifest_invalid,
        manifest_identity_mismatch,
        manifest_sequence_mismatch,

        fn reason(self: @This()) []const u8 {
            return switch (self) {
                .manifest_missing => "activation_manifest_missing",
                .manifest_invalid => "activation_manifest_invalid",
                .manifest_identity_mismatch => "activation_manifest_identity_mismatch",
                .manifest_sequence_mismatch => "activation_manifest_sequence_mismatch",
            };
        }

        fn fromReason(raw: []const u8) ?@This() {
            inline for (std.meta.tags(@This())) |failure| {
                if (std.mem.eql(u8, raw, failure.reason())) return failure;
            }
            return null;
        }
    };

    const ActivatedIndexRepairReconciliation = union(enum) {
        committed,
        not_active,
        certification_failed: ActivatedIndexRepairCertificationFailure,
    };

    /// Completes the idempotent half of activation recovery. Certification
    /// failures are data outcomes rather than raw scheduler errors: the caller
    /// must durably roll the untrusted incarnation back or expose an exact
    /// action-required terminal state.
    fn reconcileActivatedIndexRepair(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
    ) !ActivatedIndexRepairReconciliation {
        // Restart reconciliation is the second half of the same catalog
        // transaction as ordinary activation. Serialize it with every live
        // index publication and foreground apply, then reload the durable
        // intent inside that fence so pointer, runtime, config, manifest,
        // checkpoint, and admission retirement describe one incarnation.
        if (comptime builtin.is_test) {
            if (test_index_repair_reconcile_fence_hook) |hook| {
                if (hook.before_fence) |before_fence| try before_fence(hook.ptr, self, repair_id);
            }
        }
        var structural_guard = self.beginIndexStructuralMutation("index repair activation reconciliation", "*");
        defer structural_guard.deinit();
        lockApply(self);
        defer self.core.unlockApply();

        var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer entry.deinit(alloc);
        switch (entry.intent.phase) {
            .activating, .validating, .cleanup, .rolling_back => {},
            else => return .not_active,
        }
        if (entry.intent.root_generation != self.core.root_generation or
            entry.intent.group_id != self.localRepairGroupId())
        {
            return error.RepairOwnershipLost;
        }
        const candidate = entry.intent.candidate_relative_path orelse return .not_active;
        try index_repair_state.validateCandidateRelativePath(entry.intent.index_name, candidate);
        const active_pointer = try self.core.index_manager.capturePublishedIndexRootPointerForRecovery(
            entry.intent.index_name,
        );
        defer if (active_pointer) |value| alloc.free(value);
        if (active_pointer == null or !std.mem.eql(u8, active_pointer.?, candidate)) return .not_active;
        const cfg = self.core.index_manager.get(entry.intent.index_name) orelse return .not_active;
        if (cfg.kind != entry.intent.kind or types.indexConfigHash(cfg.*) != entry.intent.config_hash) {
            return error.IndexRepairConfigurationChanged;
        }
        if (!self.core.index_manager.has(entry.intent.index_name) or
            self.core.index_manager.loadFailure(entry.intent.index_name) != null)
        {
            return .not_active;
        }

        const candidate_path = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ self.core.path, candidate });
        defer alloc.free(candidate_path);
        const certification = try index_generation_manifest.certifyReady(
            alloc,
            candidate_path,
            repair_id,
            entry.intent.index_name,
            entry.intent.config_hash,
        );
        const manifest_sequence = switch (certification) {
            .ready => |sequence| sequence,
            .missing => return .{ .certification_failed = .manifest_missing },
            .invalid => return .{ .certification_failed = .manifest_invalid },
            .identity_mismatch => return .{ .certification_failed = .manifest_identity_mismatch },
        };
        if (manifest_sequence != entry.intent.candidate_applied_sequence) {
            return .{ .certification_failed = .manifest_sequence_mismatch };
        }
        if (comptime builtin.is_test) {
            if (test_index_repair_reconcile_fence_hook) |hook| {
                if (hook.after_validation) |after_validation| try after_validation(hook.ptr, self, repair_id);
            }
        }
        try self.core.index_manager.syncIndexByName(entry.intent.index_name, true);
        const checkpoint = try self.core.loadProjectionCheckpoint(alloc, entry.intent.index_name);
        const applied_sequence = @max(
            checkpoint.applied_sequence,
            @max(entry.intent.candidate_applied_sequence, manifest_sequence),
        );
        if (entry.intent.phase != .cleanup or checkpoint.status != .clean or checkpoint.config_hash != entry.intent.config_hash) {
            const update = apply_state.AppliedSequenceUpdate{
                .index_name = entry.intent.index_name,
                .sequence = applied_sequence,
                .status = .clean,
                .generation = checkpoint.generation +| 1,
                .config_hash = entry.intent.config_hash,
            };
            try saveIndexStatusSnapshots(alloc, self.core.store, self.core.index_manager, &[_]apply_state.AppliedSequenceUpdate{update});
            try self.core.saveAppliedSequence(entry.intent.index_name, applied_sequence);
            try self.core.saveProjectionCheckpoint(entry.intent.index_name, .{
                .applied_sequence = update.sequence,
                .status = update.status,
                .generation = update.generation,
                .config_hash = update.config_hash,
            });
            try self.updateIndexRepairIntent(alloc, repair_id, .{
                .phase = .cleanup,
                .target_sequence = applied_sequence,
                .next_retry_at_ms = 0,
                .replace_last_error = true,
            });
        }
        if (comptime builtin.is_test) {
            if (test_index_repair_reconcile_fence_hook) |hook| {
                if (hook.before_retirement) |before_retirement| try before_retirement(hook.ptr, self, repair_id);
            }
        }
        try self.removeIndexRepairIntentAndPin(alloc, repair_id);
        self.scheduleInactiveRepairShadowCleanup();
        return .committed;
    }

    const ActivatedIndexRepairRollback = enum {
        not_active,
        prior_generation_restored,
        retry_deferred,
        rebuild_required,
        action_required,
    };

    fn activatedIndexRepairRollbackFailureDisposition(
        action: index_manager_mod.IndexManager.IndexLoadRecoveryAction,
    ) ActivatedIndexRepairRollback {
        return switch (action) {
            .retry_open => .retry_deferred,
            .rebuild_from_artifacts => .rebuild_required,
            .manual_intervention => .action_required,
        };
    }

    /// Rolls a failed-to-load activated candidate back to the exact pointer
    /// captured before activation. `rolling_back` is checkpointed while the
    /// structural/apply fence and exact quarantine claim are both held, before
    /// the pointer changes. Restart can therefore distinguish a crash before
    /// activation from an interrupted rollback and idempotently finish from
    /// either pointer. Slow reopen I/O remains outside the service fence while
    /// the exact repair claim prevents discovery or an ordinary retry from
    /// publishing underneath it.
    fn rollbackUnavailableActivatedIndexRepair(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
        certification_failure: ?ActivatedIndexRepairCertificationFailure,
    ) !ActivatedIndexRepairRollback {
        var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer entry.deinit(alloc);
        if (!entry.intent.previous_pointer_captured) return .not_active;
        const candidate = entry.intent.candidate_relative_path orelse return .not_active;
        const rollback_certification_failure = certification_failure orelse blk: {
            if (entry.intent.phase != .rolling_back) break :blk null;
            break :blk ActivatedIndexRepairCertificationFailure.fromReason(
                entry.intent.last_error orelse break :blk null,
            );
        };
        var claim: ?index_manager_mod.IndexManager.FailedIndexLoadRepairClaim = null;
        var predecessor_loaded = false;
        {
            var structural_guard = self.beginIndexStructuralMutation("index repair rollback", entry.intent.index_name);
            defer structural_guard.deinit();
            try self.lockApplyForPortableRuntime();
            defer self.core.unlockApply();

            const active_pointer = try self.core.index_manager.capturePublishedIndexRootPointerForRecovery(
                entry.intent.index_name,
            );
            defer if (active_pointer) |value| alloc.free(value);
            const candidate_active = active_pointer != null and
                std.mem.eql(u8, active_pointer.?, candidate);
            const predecessor_active = if (entry.intent.previous_active_relative_path) |previous|
                active_pointer != null and std.mem.eql(u8, active_pointer.?, previous)
            else
                active_pointer == null;

            if (entry.intent.phase != .rolling_back and !candidate_active) return .not_active;
            if (entry.intent.phase == .rolling_back and !candidate_active and !predecessor_active) {
                return error.RepairOwnershipLost;
            }

            if (self.core.index_manager.failedIndexLoadSnapshot(entry.intent.index_name)) |failure| {
                claim = switch (self.core.index_manager.claimFailedIndexLoadRepair(
                    entry.intent.index_name,
                    .{ .exact = failure.token },
                    entry.intent.repair_id,
                )) {
                    .claimed, .already_claimed => |value| value,
                    .absent, .mismatch, .claimed_by_other => return error.RepairOwnershipLost,
                };
            } else if (predecessor_active and self.core.index_manager.has(entry.intent.index_name)) {
                // A restart may have already opened the restored predecessor
                // before the durable rollback owner resumes.
                predecessor_loaded = true;
            } else if (!candidate_active or rollback_certification_failure == null) {
                // A loaded active candidate is reconciled by the caller before
                // entering rollback. Absence here has no safe retry identity;
                // an inactive pointer with no loaded predecessor is likewise
                // not evidence that rollback completed.
                return error.RepairOwnershipLost;
            }

            if (entry.intent.phase != .rolling_back) {
                var checkpointed = false;
                defer if (!checkpointed) self.core.index_manager.releaseFailedIndexLoadRepairClaim(
                    entry.intent.index_name,
                    entry.intent.repair_id,
                );
                try self.updateIndexRepairIntent(alloc, repair_id, .{
                    .phase = .rolling_back,
                    .next_retry_at_ms = 0,
                    .last_error = if (rollback_certification_failure) |failure| failure.reason() else null,
                    .replace_last_error = true,
                });
                checkpointed = true;
            }
            if (candidate_active) {
                if (rollback_certification_failure) |failure| {
                    claim = try self.core.index_manager.rollbackUncertifiedActiveIndexRoot(
                        entry.intent.index_name,
                        candidate,
                        entry.intent.previous_active_relative_path,
                        entry.intent.config_hash,
                        failure.reason(),
                        repair_id,
                    );
                } else {
                    try self.core.index_manager.restoreActiveIndexRootPointer(
                        entry.intent.index_name,
                        candidate,
                        entry.intent.previous_active_relative_path,
                    );
                }
            }
        }

        if (predecessor_loaded) {
            try self.discardInactiveIndexRepairCandidate(alloc, repair_id);
            return .prior_generation_restored;
        }
        if (comptime builtin.is_test) {
            if (test_index_repair_rollback_retry_hook) |hook| {
                try hook.before_retry(hook.ptr, self, repair_id);
            }
        }
        const retry = try self.retryQuarantinedIndexLoadTarget(.{
            .name = entry.intent.index_name,
            .token = claim.?.token,
            .authority = .{ .repair_claim = entry.intent.repair_id },
        }, true);
        switch (retry.target_outcome) {
            .recovered => {
                try self.discardInactiveIndexRepairCandidate(alloc, repair_id);
                return .prior_generation_restored;
            },
            .attempted_failed => switch (activatedIndexRepairRollbackFailureDisposition(
                retry.target_action orelse return error.RepairOwnershipLost,
            )) {
                .retry_deferred => {
                    // Retain both the rollback phase and exact claim. The
                    // durable repair backoff owns subsequent retries, avoiding
                    // a hot loop and preventing generic retry from racing it.
                    try self.recordIndexRepairAttemptFailure(
                        alloc,
                        repair_id,
                        if (rollback_certification_failure) |failure|
                            failure.reason()
                        else
                            "rollback_predecessor_retry_open",
                        false,
                    );
                    return .retry_deferred;
                },
                .action_required => {
                    try self.discardInactiveIndexRepairCandidateWithTerminal(
                        alloc,
                        repair_id,
                        if (rollback_certification_failure) |failure|
                            failure.reason()
                        else
                            "rollback_predecessor_manual_intervention",
                    );
                    return .action_required;
                },
                .rebuild_required => {
                    try self.discardInactiveIndexRepairCandidate(alloc, repair_id);
                    return .rebuild_required;
                },
                .not_active, .prior_generation_restored => unreachable,
            },
            // An exact repair-authorized forced retry is always targeted and
            // ignores backoff. Any other outcome means its incarnation or
            // ownership changed while detached I/O was in flight.
            .not_targeted, .absent, .stale, .repair_claimed, .backoff => return error.RepairOwnershipLost,
        }
    }

    /// Cheap startup discovery. This authorizes and durably records repair
    /// debt, but deliberately performs no corpus scan and never touches the
    /// quarantined index root.
    pub fn discoverRecoverableStartupIndexFailures(
        self: *DB,
        alloc: Allocator,
        limit: usize,
    ) !StartupIndexRepairDiscovery {
        var result: StartupIndexRepairDiscovery = .{};
        try self.ensureIndexRepairSchedulerDirectory(alloc);
        lockAtomic(&self.async_context.index_repair_scheduler_mutex);
        const state_identity = self.async_context.index_repair_scheduler.identity orelse {
            self.async_context.index_repair_scheduler_mutex.unlock();
            return error.InvalidIndexRepairState;
        };
        self.async_context.index_repair_scheduler_mutex.unlock();
        const location = try self.indexRepairStateLocation();

        const inspection_limit = @max(
            @as(usize, 1),
            std.math.mul(usize, limit, index_repair_inspections_per_execution_slot) catch std.math.maxInt(usize),
        );
        var quantum = try self.core.index_manager.failedIndexLoadRecoveryCandidates(
            alloc,
            .rebuild_from_artifacts,
            inspection_limit,
        );
        defer quantum.deinit(alloc);
        // Classification performs detached durable work. Preserve successful
        // acknowledgements even if a later candidate errors, while exact
        // epoch/revision checks prevent this unwind from certifying stale debt.
        errdefer _ = self.core.index_manager.finishFailedIndexLoadRecoveryQuantum(
            .rebuild_from_artifacts,
            quantum.queue_epoch,
            quantum.candidates,
        );
        result.automatic_remaining = quantum.action_total;
        result.automatic_sweep_complete = quantum.sweep_complete;
        for (quantum.candidates) |*candidate| {
            const cfg = candidate.config;
            const action = candidate.token.action;
            if (!self.core.index_manager.failedIndexLoadRecoveryCandidateIsCurrent(candidate.*)) {
                result.automatic_deferred += 1;
                result.automatic_sweep_complete = false;
                continue;
            }
            // Directory observation and its resident binding effect share the
            // same control transaction as durable phase transitions. The
            // directory remains a cache, but its revision cannot change from
            // pending to terminal (or back) between classification and claim.
            lockAtomic(&self.async_context.index_repair_control_mutex);
            lockAtomic(&self.async_context.index_repair_scheduler_mutex);
            const existing = self.async_context.index_repair_scheduler.lookupByName(cfg.name);
            self.async_context.index_repair_scheduler_mutex.unlock();
            if (existing) |record| {
                if (comptime builtin.is_test) {
                    if (test_index_repair_discovery_observation_hook) |hook| {
                        try hook.after_observation(hook.ptr, self, record.repair_id);
                    }
                }
                if (record.phase_terminal) {
                    self.core.index_manager.releaseFailedIndexLoadRecoveryCandidate(
                        cfg.name,
                        candidate.token,
                        record.repair_id,
                    );
                    result.terminal += 1;
                    result.existing_terminal += 1;
                } else {
                    switch (self.core.index_manager.claimFailedIndexLoadRecoveryCandidate(
                        candidate.*,
                        record.repair_id,
                    )) {
                        .claimed, .already_claimed => {},
                        .absent, .stale, .claimed_by_other => {
                            self.async_context.index_repair_control_mutex.unlock();
                            result.automatic_deferred += 1;
                            result.automatic_sweep_complete = false;
                            continue;
                        },
                    }
                    result.already_pending += 1;
                }
                self.async_context.index_repair_control_mutex.unlock();
                candidate.classified = true;
                continue;
            }
            self.async_context.index_repair_control_mutex.unlock();
            switch (action) {
                .retry_open => continue,
                .manual_intervention => {
                    result.terminal += 1;
                    candidate.classified = true;
                    continue;
                },
                .rebuild_from_artifacts => {},
            }
            // Both allowlisted publication failures are currently HBC dense
            // index failures. Do not let future reuse of either error name
            // silently broaden automatic reconstruction.
            if (cfg.kind != .dense_vector) {
                result.terminal += 1;
                candidate.classified = true;
                continue;
            }
            if (result.discovered >= limit) {
                result.automatic_deferred += 1;
                continue;
            }

            const checkpoint = try self.core.loadProjectionCheckpoint(alloc, cfg.name);
            const now_ms = self.indexRepairNowMs();
            const target_sequence = self.core.nextDerivedSequence();
            const repair_id = try index_repair_state.newRepairId(alloc);
            const index_name = try alloc.dupe(u8, cfg.name);
            var intent = index_repair_state.IndexRepairIntent{
                .repair_id = repair_id,
                .db_identity = state_identity.db_identity,
                .group_id = self.localRepairGroupId(),
                .replica_id = state_identity.replica_id,
                .root_generation = state_identity.root_generation,
                .index_name = index_name,
                .kind = cfg.kind,
                .config_hash = types.indexConfigHash(cfg),
                .detected_sequence = target_sequence,
                .target_sequence = target_sequence,
                .started_at_ms = now_ms,
                .updated_at_ms = now_ms,
                .owner_epoch = 0,
            };
            defer intent.deinit(alloc);
            var catalog_incarnation = self.beginIndexCatalogIncarnationGuard();
            defer catalog_incarnation.deinit();
            lockAtomic(&self.async_context.index_repair_control_mutex);
            var repair_control_locked = true;
            defer if (repair_control_locked) self.async_context.index_repair_control_mutex.unlock();
            // Detached config cloning and checkpoint inspection run without the
            // catalog lock. Revalidate under the same short lifecycle boundary
            // used by drop/recreate and quarantine publication so the durable
            // intent cannot bind a stale same-name catalog incarnation.
            if (!self.core.index_manager.failedIndexLoadRecoveryCandidateIsCurrent(candidate.*)) {
                result.automatic_deferred += 1;
                result.automatic_sweep_complete = false;
                continue;
            }
            switch (self.core.index_manager.claimFailedIndexLoadRecoveryCandidate(candidate.*, repair_id)) {
                .claimed, .already_claimed => {},
                .absent, .stale, .claimed_by_other => {
                    result.automatic_deferred += 1;
                    result.automatic_sweep_complete = false;
                    continue;
                },
            }
            var release_repair_claim = true;
            defer if (release_repair_claim) self.core.index_manager.releaseFailedIndexLoadRecoveryCandidate(
                candidate.config.name,
                candidate.token,
                repair_id,
            );
            var admission_fence = try self.core.index_manager.beginRepairAdmissionFence(intent.index_name);
            defer self.core.index_manager.cancelRepairAdmissionFence(&admission_fence, intent.index_name);
            const control_revision = index_repair_state.putEntryAt(
                alloc,
                location,
                state_identity,
                null,
                .{ .intent = intent },
            ) catch |err| switch (err) {
                // Another authorized creator won after the initial directory
                // observation. The exact candidate claim unwinds below and a
                // later bounded pass adopts the committed durable intent.
                error.RepairTransitionConflict => {
                    result.automatic_deferred += 1;
                    result.automatic_sweep_complete = false;
                    continue;
                },
                else => return err,
            };
            // The durable intent now owns this exact quarantine incarnation.
            // Keep the claim until terminal classification or successful
            // replacement removes the failed-load entry.
            release_repair_claim = false;
            self.core.index_manager.finishRepairAdmissionFence(
                &admission_fence,
                intent.index_name,
                repairAdmissionVersion(intent, 1, control_revision),
                true,
                false,
            );
            noteIndexRepairSchedulerUpsert(self.async_context, intent, 1, control_revision);

            // Intent durability precedes the serviceability marker. If this
            // checkpoint write fails, restart still rediscovers the intent and
            // completes the transition without deleting the quarantined root.
            try self.core.saveProjectionCheckpoint(cfg.name, .{
                .applied_sequence = checkpoint.applied_sequence,
                .status = .repair_required,
                .generation = checkpoint.generation,
                .config_hash = types.indexConfigHash(cfg),
            });
            self.async_context.index_repair_control_mutex.unlock();
            repair_control_locked = false;
            catalog_incarnation.release();
            notifyIndexRepairVisibilityHook(
                self.async_context,
                .index_repair_pending,
                intent,
                1,
                .serviceable,
                false,
                false,
            );
            result.discovered += 1;
            candidate.classified = true;
        }
        const final_queue = self.core.index_manager.finishFailedIndexLoadRecoveryQuantum(
            .rebuild_from_artifacts,
            quantum.queue_epoch,
            quantum.candidates,
        );
        result.automatic_remaining = final_queue.action_total;
        result.automatic_sweep_complete = final_queue.sweep_complete;
        return result;
    }

    pub const IndexRepairAdvanceResult = struct {
        repair_id: u128,
        attempted: bool = false,
        repaired: bool = false,
        busy: bool = false,
        deferred: bool = false,
        disk_wait: bool = false,
        terminal: bool = false,
        documents_reprocessed: u64 = 0,
        next_retry_at_ms: u64 = 0,
        has_repair_outcome: bool = false,
        artifacts_repaired: u64 = 0,
        missing_source_docs: u64 = 0,
        failed: u64 = 0,
        unsupported: u64 = 0,
        unresolved: u64 = 0,
        in_progress: u64 = 0,
        indexes_rebuilt: u64 = 0,
        indexes_degraded_before: u64 = 0,
        indexes_degraded_after: u64 = 0,
        debt_remaining: bool = false,
    };

    fn applyCommittedRepairOutcomeToAdvance(
        result: *IndexRepairAdvanceResult,
        repair: types.ArtifactRepairResult,
    ) void {
        result.has_repair_outcome = true;
        result.artifacts_repaired = repair.repaired;
        result.missing_source_docs = repair.missing_source_docs;
        result.failed = repair.failed;
        result.unsupported = repair.unsupported;
        result.unresolved = repair.unresolved;
        result.in_progress = repair.in_progress;
        result.indexes_rebuilt = repair.indexes_rebuilt;
        result.indexes_degraded_before = repair.indexes_degraded_before;
        result.indexes_degraded_after = repair.indexes_degraded_after;
        result.debt_remaining = repair.debt_remaining;
    }

    const DurableIndexRepairRunControl = struct {
        db: *DB,
        index_name: []const u8,
        upstream: ?types.RepairCancelCheck,
        ownership: ?types.RepairActivationCheck,

        fn cancelled(ptr: *anyopaque) bool {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (self.upstream) |check| {
                if (check.requested()) return true;
            }
            if (self.ownership) |check| {
                if (!(check.current() catch return true)) return true;
            }
            return self.db.activeIndexRepairCancellationRequested(self.index_name);
        }
    };

    /// Advances one durable repair intent. Operator repair and the automatic
    /// owner-side executor both enter through this state machine so restart,
    /// cancellation, retries, and pointer reconciliation have one correctness
    /// path.
    const RepairCapacityGuard = struct {
        reservation: *resource_manager_mod.CapacityReservation,
        db: *DB,
        alloc: Allocator,
        repair_id: u128,
        options: types.ArtifactRepairRunOptions,
        admitted_total_bytes: u64,
        headroom_bytes: u64,
        candidate_root: ?[]const u8 = null,

        fn bindCandidateRoot(ptr: *anyopaque, candidate_root: []const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.candidate_root = candidate_root;
        }

        fn reconcile(ptr: *anyopaque, candidate_bytes: u64) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const required = candidate_bytes +| self.headroom_bytes;
            const next_plan = @max(required, self.admitted_total_bytes);
            const desired_future_claim = next_plan -| candidate_bytes;
            const observation = try repairCapacityObservation(self.options);
            const now_ns = monotonicTimeNs();
            try self.reservation.resize(desired_future_claim, observation, now_ns);
            // Shrinking a claim is admission-free, but this boundary follows
            // materialized writes. Revalidate the remaining aggregate claim
            // against the same fresh observation before advancing state.
            try self.reservation.revalidate(observation, now_ns);
            if (next_plan != self.admitted_total_bytes) {
                try self.db.updateIndexRepairIntent(self.alloc, self.repair_id, .{ .planned_disk_bytes = next_plan });
                self.admitted_total_bytes = next_plan;
            }
        }

        fn revalidate(ptr: *anyopaque) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const observation = try repairCapacityObservation(self.options);
            // Availability already includes materialized candidate bytes,
            // while the reservation describes future growth. Stay on the O(1)
            // path while the conservative claim fits. A failed probe is not a
            // denial yet: reconcile exact candidate bytes first, then let the
            // final revalidation record a real denial only if it still fails.
            if (try self.reservation.fits(observation, monotonicTimeNs())) return;
            if (self.candidate_root) |candidate_root| {
                return try RepairCapacityGuard.reconcile(self, try directoryUsageBytes(self.alloc, candidate_root));
            }
            try self.reservation.revalidate(observation, monotonicTimeNs());
        }
    };

    fn repairCapacityDomain(options: types.ArtifactRepairRunOptions) resource_manager_mod.CapacityDomainId {
        if (options.capacity_source) |source| return source.domain_id;
        return options.capacity_domain_id;
    }

    fn repairCapacityObservation(options: types.ArtifactRepairRunOptions) !resource_manager_mod.CapacityObservation {
        const observed = if (options.capacity_source) |source|
            source.current() catch |err| switch (err) {
                // Capacity observation is an optional backend capability.
                // Unsupported backends still participate in node-wide byte
                // accounting; transient failures from a supported source
                // remain retryable and fail admission closed.
                error.UnsupportedPlatform => resource_manager_mod.CapacityObservation{},
                else => return err,
            }
        else
            options.capacity_observation;
        return .{
            .available_bytes = observed.available_bytes,
            .capacity_bytes = observed.capacity_bytes,
            .observed_at_ns = observed.observed_at_ns,
            .valid_for_ns = observed.valid_for_ns,
        };
    }

    fn artifactBackedDenseRepairEstimate(self: *DB, alloc: Allocator, cfg: types.IndexConfig) !u64 {
        if (!try index_manager_mod.denseConfigRequiresArtifactCoverage(alloc, cfg)) return 0;
        const target_count = (try loadDenseArtifactTargetCounter(alloc, self.core.store, cfg.name)) orelse return 0;
        const dims = try index_manager_mod.denseConfigDimensions(alloc, cfg);
        // Candidate storage contains the source vector, HBC node/posting
        // state, quantized payloads, keys, and LSM metadata. Two times the raw
        // vector payload plus a per-vector structural allowance is a
        // deliberately conservative preflight; live boundary checks below
        // remain authoritative as bytes materialize.
        const per_vector = std.math.add(u64, @as(u64, dims) *| @sizeOf(f32), 512) catch std.math.maxInt(u64);
        const logical = std.math.mul(u64, target_count, per_vector) catch std.math.maxInt(u64);
        return std.math.mul(u64, logical, 2) catch std.math.maxInt(u64);
    }

    const RepairWorkingSetPlan = struct {
        reservation_bytes: u64,
        dense_rebuild_batch_items: usize = 2048,
    };

    const dense_counter_bootstrap_working_set_bytes: u64 = 8 * 1024 * 1024;

    fn reserveDenseCounterBootstrapWorkingSet(
        manager: *resource_manager_mod.ResourceManager,
    ) !resource_manager_mod.Reservation {
        const slice_stats = manager.sliceStats(.dense_repair_working_set);
        const hard_available = if (slice_stats.hard_limit_bytes == 0)
            std.math.maxInt(u64)
        else
            slice_stats.hard_limit_bytes -| slice_stats.used_bytes;
        // Let ResourceManager perform an authoritative hard rejection so the
        // shared rejection metric remains accurate under pressure and races.
        if (hard_available < dense_counter_bootstrap_working_set_bytes) {
            return manager.reserve(.dense_repair_working_set, dense_counter_bootstrap_working_set_bytes) catch
                return error.RepairResourceUnavailable;
        }
        const soft_available = if (slice_stats.soft_limit_bytes == 0)
            hard_available
        else
            slice_stats.soft_limit_bytes -| slice_stats.used_bytes;
        if (soft_available < dense_counter_bootstrap_working_set_bytes) {
            return error.RepairResourceUnavailable;
        }
        return manager.reserve(.dense_repair_working_set, dense_counter_bootstrap_working_set_bytes) catch
            return error.RepairResourceUnavailable;
    }

    fn repairWorkingSetPlan(
        alloc: Allocator,
        manager: *resource_manager_mod.ResourceManager,
        cfg: types.IndexConfig,
    ) !RepairWorkingSetPlan {
        const base_bytes: u64 = 8 * 1024 * 1024;
        if (cfg.kind != .dense_vector) return .{ .reservation_bytes = base_bytes };

        const dims = try index_manager_mod.denseConfigDimensions(alloc, cfg);
        // The snapshot scanner owns one decoded vector while the mapper/HBC
        // boundary may transiently own a second copy. Include keys, artifact
        // identity, list capacity, and allocator overhead per item. HBC/LSM
        // caches and routing work remain independently accounted by their own
        // ResourceManager slices.
        const raw_vector_bytes = std.math.mul(u64, dims, @sizeOf(f32)) catch std.math.maxInt(u64);
        const per_item_bytes = (std.math.mul(u64, raw_vector_bytes, 2) catch std.math.maxInt(u64)) +| 2048;
        const desired_items: u64 = 2048;
        const slice_stats = manager.sliceStats(.dense_repair_working_set);
        const hard_available = if (slice_stats.hard_limit_bytes == 0)
            std.math.maxInt(u64)
        else
            slice_stats.hard_limit_bytes -| slice_stats.used_bytes;
        const minimum_reservation = base_bytes +| per_item_bytes;
        // Preserve ResourceManager's authoritative hard-limit rejection and
        // metric. For admissible work, however, size background batches to the
        // soft budget: reaching the hard limit is a safety failure, not a
        // throughput target.
        if (hard_available < minimum_reservation) {
            return .{
                .reservation_bytes = minimum_reservation,
                .dense_rebuild_batch_items = 1,
            };
        }
        const available = if (slice_stats.soft_limit_bytes == 0)
            hard_available
        else
            slice_stats.soft_limit_bytes -| slice_stats.used_bytes;
        if (available < minimum_reservation) return error.RepairResourceUnavailable;
        const fitting_items = if (available <= base_bytes)
            0
        else
            (available - base_bytes) / @max(@as(u64, 1), per_item_bytes);
        const batch_items = @min(desired_items, fitting_items);
        return .{
            .reservation_bytes = base_bytes +| (per_item_bytes *| batch_items),
            .dense_rebuild_batch_items = if (comptime builtin.is_test)
                test_dense_repair_rebuild_batch_size orelse @as(usize, @intCast(batch_items))
            else
                @intCast(batch_items),
        };
    }

    pub fn advanceIndexRepairIntent(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
        options: types.ArtifactRepairRunOptions,
    ) anyerror!IndexRepairAdvanceResult {
        return try self.advanceScheduledIndexRepairIntent(alloc, repair_id, options, null, false);
    }

    fn advanceScheduledIndexRepairIntent(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
        options: types.ArtifactRepairRunOptions,
        scheduled_revision: ?u64,
        audit_due: bool,
    ) anyerror!IndexRepairAdvanceResult {
        // Resolve the durable name before taking the process-local lease, then
        // reload after acquisition. A pause or terminal transition which wins
        // between those operations must be observed by this owner; using the
        // locator snapshot would let an acknowledged pause start one more
        // repair quantum. The checkpoint is already read repeatedly by a
        // material state-machine turn, while deferred intents remain on the
        // O(1) scheduler path and never pay this ownership handoff cost.
        var locator = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer locator.deinit(alloc);
        if (!(try self.beginIndexRepairLease(locator.intent.index_name))) {
            return .{
                .repair_id = repair_id,
                .busy = true,
            };
        }
        defer self.endIndexRepairLease(locator.intent.index_name);

        if (comptime builtin.is_test) {
            if (test_index_repair_advance_lease_hook) |hook| {
                if (hook.after_acquire) |after_acquire| try after_acquire(hook.ptr, self, repair_id);
            }
        }
        var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer entry.deinit(alloc);
        if (!std.mem.eql(u8, locator.intent.index_name, entry.intent.index_name)) {
            return error.InvalidIndexRepairState;
        }
        if (comptime builtin.is_test) {
            if (test_index_repair_advance_lease_hook) |hook| {
                if (hook.after_reload) |after_reload| try after_reload(hook.ptr, self, repair_id);
            }
        }
        // An audit grant is a process-local acceleration token for one exact
        // durable revision. Selection releases the scheduler mutex before the
        // repair lease is acquired, so a source-replay, retry, pause/resume, or
        // concurrent owner transition may supersede it in that interval. The
        // reloaded durable entry is authoritative; never let a stale token skip
        // the newly revised generation's bounded convergence wait.
        const audit_revision = if (audit_due and
            scheduled_revision != null and
            entry.intent.revision == scheduled_revision.?)
            scheduled_revision
        else
            null;
        var run_control = DurableIndexRepairRunControl{
            .db = self,
            .index_name = entry.intent.index_name,
            .upstream = options.cancel_check,
            .ownership = options.activation_check,
        };
        var owned_options = options;
        owned_options.cancel_check = .{
            .ptr = &run_control,
            .is_requested = DurableIndexRepairRunControl.cancelled,
        };
        return try self.advanceIndexRepairIntentOwned(
            alloc,
            repair_id,
            owned_options,
            &entry,
            audit_revision,
        );
    }

    /// Executes one repair quantum while `active_index_repairs[index_name]` is
    /// held by the caller. Keeping the lease outside every phase makes pause,
    /// cancel, deletion, rollback, and activation share one ownership domain.
    fn advanceIndexRepairIntentOwned(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
        options: types.ArtifactRepairRunOptions,
        entry: *index_repair_state.Entry,
        audit_revision: ?u64,
    ) anyerror!IndexRepairAdvanceResult {
        var result = IndexRepairAdvanceResult{ .repair_id = repair_id };
        var effective_options = options;
        if (effective_options.capacity_source == null) effective_options.capacity_source = self.capacity_source;

        if (entry.intent.root_generation != self.core.root_generation or
            entry.intent.group_id != self.localRepairGroupId())
        {
            try self.recordIndexRepairAttemptFailure(alloc, repair_id, "repair_identity_mismatch", true);
            result.terminal = true;
            return result;
        }
        if (entry.intent.phase == .terminal) {
            if (retryableIndexRepairTerminalPhase(
                entry.intent.last_error,
                entry.intent.trigger,
            )) |retry_phase| {
                try self.updateIndexRepairIntent(alloc, repair_id, .{
                    .phase = retry_phase,
                    .next_retry_at_ms = 0,
                    .replace_last_error = true,
                });
                entry.intent.phase = retry_phase;
                entry.intent.revision +|= 1;
            } else {
                result.terminal = true;
                return result;
            }
        }
        // Only startup discovery creates incomplete_bulk_publish intents, so
        // this durable provenance is the authority to reclaim quarantine
        // ownership. Operator and generation-health intents may coexist with
        // retry/manual load failures but must not be reclassified as automatic
        // destructive recovery merely because they share an index name.
        if (entry.intent.trigger == .incomplete_bulk_publish and
            entry.intent.phase != .rolling_back)
        {
            // Retryable terminal phases release their quarantine claim so an
            // operator may intervene. Reclaiming classifies action/config and
            // claims the current incarnation in one catalog-locked operation.
            // Policy or identity drift is terminal for this durable intent: a
            // fresh audit must authorize any different action.
            switch (self.core.index_manager.claimFailedIndexLoadRepair(
                entry.intent.index_name,
                .{ .current_policy = .{
                    .action = .rebuild_from_artifacts,
                    .config_hash = entry.intent.config_hash,
                } },
                repair_id,
            )) {
                .claimed, .already_claimed, .absent => {},
                .claimed_by_other => {
                    result.deferred = true;
                    return result;
                },
                .mismatch => |mismatch| {
                    try self.recordIndexRepairAttemptFailure(
                        alloc,
                        repair_id,
                        quarantineClaimMismatchReason(mismatch.differences),
                        true,
                    );
                    result.terminal = true;
                    return result;
                },
            }
        }
        // A candidate which already failed coverage cannot manufacture an
        // artifact missing below its snapshot floor. Discard only that
        // inactive candidate and rebuild from a current pinned snapshot.
        if (entry.intent.candidate_relative_path != null and
            retryableIndexRepairTerminalPhase(
                entry.intent.last_error,
                entry.intent.trigger,
            ) != null)
        {
            try self.discardInactiveIndexRepairCandidate(alloc, repair_id);
            result.attempted = true;
            result.deferred = true;
            return result;
        }
        if (entry.intent.automation == .paused) {
            result.deferred = true;
            return result;
        }
        const now_ms = self.indexRepairNowMs();
        if (entry.intent.next_retry_at_ms > now_ms) {
            result.deferred = true;
            result.next_retry_at_ms = entry.intent.next_retry_at_ms;
            return result;
        }
        checkArtifactRepairActivationOwner(options) catch |err| switch (err) {
            error.RepairOwnershipLost => {
                result.deferred = true;
                return result;
            },
            else => return err,
        };

        // Claim the durable state machine with the same epoch captured by the
        // owner-side activation fence. A later term/root owner may safely
        // reclaim the intent, but every subsequent transition and the final
        // activation in this attempt are CAS-fenced by the new epoch.
        if (options.owner_epoch != 0 and entry.intent.owner_epoch != options.owner_epoch) {
            try self.updateIndexRepairIntent(alloc, repair_id, .{ .owner_epoch = options.owner_epoch });
            entry.intent.owner_epoch = options.owner_epoch;
            entry.intent.revision +|= 1;
        }

        const cfg_ptr = self.core.index_manager.get(entry.intent.index_name) orelse {
            try self.recordIndexRepairAttemptFailure(alloc, repair_id, "index_configuration_missing", true);
            result.terminal = true;
            return result;
        };
        if (cfg_ptr.kind != entry.intent.kind or types.indexConfigHash(cfg_ptr.*) != entry.intent.config_hash) {
            try self.recordIndexRepairAttemptFailure(alloc, repair_id, "index_configuration_changed", true);
            result.terminal = true;
            return result;
        }

        if (entry.intent.phase == .detected and entry.intent.source_replay_state == .pending) {
            // Managed DDL installs the generator for future writes under the
            // synchronous structural fence, but existing-row discovery belongs
            // to this durable bounded owner. Append one primary-store page,
            // then publish its cursor. A crash before the cursor repeats an
            // idempotent page; a crash after it can never skip source rows.
            const artifact_names = try self.core.index_manager.artifactProducerNamesForIndexAlloc(
                alloc,
                entry.intent.index_name,
            );
            defer {
                for (artifact_names) |name| alloc.free(name);
                alloc.free(artifact_names);
            }
            var page = try self.appendGeneratedEnrichmentsFromStoredDocsPage(
                alloc,
                artifact_names,
                true,
                entry.intent.source_replay_resume_key,
                128,
            );
            defer page.deinit(alloc);
            try self.updateIndexRepairIntent(alloc, repair_id, .{
                .source_replay_resume_key = page.next_resume_key,
                .replace_source_replay_resume_key = true,
                .source_replay_reprocessed = entry.intent.source_replay_reprocessed +| @as(u64, @intCast(page.documents_scanned)),
                .source_replay_state = if (page.complete) .complete else .pending,
                .target_sequence = @max(entry.intent.target_sequence, page.target_sequence),
                .failure_streak = 0,
                .next_retry_at_ms = 0,
            });
            result.attempted = true;
            result.documents_reprocessed = @intCast(page.documents_scanned);
            result.deferred = true;
            return result;
        }

        // Activation recovery is structural O(1) work and precedes corpus
        // validation or capacity admission. `rolling_back` is an explicit
        // durable decision: if restart finds the candidate healthy before the
        // pointer moved, reconciliation may still commit it; otherwise the
        // rollback owner must finish retiring it and must never resume it as a
        // convergence candidate.
        if (entry.intent.phase == .activating or
            entry.intent.phase == .validating or
            entry.intent.phase == .cleanup or
            entry.intent.phase == .rolling_back)
        {
            if (entry.intent.candidate_relative_path == null) {
                try self.recordIndexRepairAttemptFailure(alloc, repair_id, "activated_candidate_missing", true);
                result.terminal = true;
                return result;
            }
            const reconciliation = try self.reconcileActivatedIndexRepair(alloc, repair_id);
            var certification_failure: ?ActivatedIndexRepairCertificationFailure = null;
            switch (reconciliation) {
                .committed => {
                    result.attempted = true;
                    var repair = types.ArtifactRepairResult{ .indexes_rebuilt = 1 };
                    try self.finalizeCommittedIndexRepairOutcome(alloc, entry.intent.index_name, 0, &repair);
                    applyCommittedRepairOutcomeToAdvance(&result, repair);
                    result.repaired = repair.indexes_degraded_after == 0 and !repair.debt_remaining;
                    return result;
                },
                .not_active => {},
                .certification_failed => |failure| certification_failure = failure,
            }
            const rolled_back = try self.rollbackUnavailableActivatedIndexRepair(
                alloc,
                repair_id,
                certification_failure,
            );
            switch (rolled_back) {
                .not_active => {
                    // `activating` is durable before pointer publication. If
                    // that publication never happened, retain the ready shadow
                    // and resume its bounded convergence path.
                    try self.updateIndexRepairIntent(alloc, repair_id, .{
                        .phase = .waiting_for_convergence,
                    });
                    entry.intent.phase = .waiting_for_convergence;
                    entry.intent.revision +|= 1;
                },
                .prior_generation_restored => {
                    // Yield after the rollback quantum. The restored generation
                    // is immediately available while the original durable
                    // repair resumes from preflight on the next owner turn.
                    result.attempted = true;
                    result.deferred = true;
                    return result;
                },
                .retry_deferred => {
                    var deferred = try self.loadIndexRepairEntryById(alloc, repair_id);
                    defer deferred.deinit(alloc);
                    result.attempted = true;
                    result.deferred = true;
                    result.next_retry_at_ms = deferred.intent.next_retry_at_ms;
                    return result;
                },
                .action_required => {
                    result.attempted = true;
                    result.terminal = true;
                    return result;
                },
                .rebuild_required => {},
            }
        }

        // Activation/rollback recovery is a committed-generation safety
        // boundary and therefore wins a concurrent cancellation. Everything
        // below may start new scan/build work and must honor the cancellation
        // bit installed by pause/cancel while this lease is visible.
        if (effective_options.cancelled()) {
            result.deferred = true;
            return result;
        }

        // A managed admission can become queryable before its exact physical
        // cardinality is known. Publish that identity proof before either
        // queryability exit below: the snapshot is ordered with foreground
        // artifact mutations by the apply lock, and later mutations contribute
        // to its signed delta. Deferring first used to park a healthy recreated
        // index forever because no subsequent path owned counter bootstrap.
        self.ensureDenseArtifactTargetCounterForRepair(
            alloc,
            cfg_ptr.*,
            repair_id,
            effective_options.cancel_check,
        ) catch |err| switch (err) {
            error.Canceled, error.StaleDenseArtifactCounterBootstrap => {
                result.attempted = true;
                result.deferred = true;
                return result;
            },
            error.RepairResourceUnavailable => {
                const attempt_count = entry.intent.attempt_count +| 1;
                const failure_streak = entry.intent.failure_streak +| 1;
                const next_retry_at_ms = now_ms +| indexRepairRetryDelayMs(repair_id, failure_streak);
                try self.updateIndexRepairIntent(alloc, repair_id, .{
                    .attempt_count = attempt_count,
                    .failure_streak = failure_streak,
                    .next_retry_at_ms = next_retry_at_ms,
                    .last_error = "RepairResourceUnavailable",
                    .replace_last_error = true,
                });
                result.attempted = true;
                result.deferred = true;
                result.next_retry_at_ms = next_retry_at_ms;
                return result;
            },
            else => return err,
        };

        // Check the exact index generation before the shared enrichment
        // producer fence. Other indexes can legitimately advance that global
        // runtime while this managed admission is already complete. Letting
        // unrelated producer work win here keeps a healthy durable intent at
        // the head of a one-slot repair queue forever.
        if (try self.managedAdmissionGenerationIsServiceable(alloc, entry.intent)) {
            try self.ensureManagedAdmissionCanonicalWorker(alloc, entry.intent);
            if (entry.intent.candidate_relative_path != null) {
                try self.discardInactiveIndexRepairCandidate(alloc, repair_id);
            }
            try self.removeIndexRepairIntentAndPin(alloc, repair_id);
            result.attempted = true;
            result.repaired = true;
            return result;
        }

        // Progressive admission has already published a trustworthy canonical
        // generation. Keep serving and advancing that generation instead of
        // allocating a shadow candidate, which would otherwise make query
        // admission regress from queryable_partial back to fail-closed. The
        // durable intent remains pending and the stronger proof above retires
        // it once coverage and replay converge.
        if (try self.managedAdmissionGenerationIsQueryable(alloc, entry.intent)) {
            const observed_sequence = try self.managedIndexAppliedSequence(alloc, entry.intent.index_name);
            // Selection's slow-audit grant is authority for one exact durable
            // revision, not for the whole owned turn. Claim it with a durable
            // CAS immediately before using the queryable shortcut. Besides
            // closing the selection/reload and reload/use races, the revision
            // advance visibly consumes the process-local audit token so a
            // retry must receive a fresh scheduler grant.
            const consumed_audit_revision = if (audit_revision) |expected_revision|
                try self.consumeIndexRepairAuditGrant(alloc, repair_id, expected_revision)
            else
                null;
            if (consumed_audit_revision) |revision| entry.intent.revision = revision;
            // The audit rechecks the publication proof; its deadline is not
            // evidence of damaged artifacts. A certified partial generation
            // must continue through its canonical worker even when provider
            // failures or new writes keep source coverage incomplete.
            try self.ensureManagedAdmissionCanonicalWorker(alloc, entry.intent);
            if (!try self.deferIndexRepairUntilTargetOrAudit(
                alloc,
                repair_id,
                entry.intent.revision,
                entry.intent.index_name,
                observed_sequence,
                entry.intent.target_sequence,
            )) {
                result.busy = true;
                return result;
            }
            result.deferred = true;
            return result;
        }

        if (entry.intent.phase == .detected and entry.intent.source_replay_state == .complete) {
            // The bounded source-replay phase advances the intent target after
            // every durable page, so its final value is the producer-completion
            // fence. Starting a shadow from artifacts
            // below that fence can snapshot a later artifact value and then
            // replay the earlier delete which produced it, permanently
            // removing deterministic chunk identities from the candidate.
            if (self.enrichment_runtime) |runtime| {
                const enrichment = runtime.stats();
                if (enrichment.enabled and enrichment.applied_sequence < entry.intent.target_sequence) {
                    // The source-discovery owner has durably queued all work;
                    // provider execution and derived publication now own the
                    // next progress edge. Park this exact intent instead of
                    // polling it on every repair scheduler turn. A derived
                    // publication wakes it only when the durable target has
                    // not yet been reached; after that, the bounded audit owns
                    // coverage completion, including terminal/skipped output
                    // which produces no index watermark edge.
                    const observed_sequence = try self.managedIndexAppliedSequence(alloc, entry.intent.index_name);
                    if (!try self.deferIndexRepairUntilTargetOrAudit(
                        alloc,
                        repair_id,
                        entry.intent.revision,
                        entry.intent.index_name,
                        observed_sequence,
                        entry.intent.target_sequence,
                    )) {
                        result.busy = true;
                        return result;
                    }
                    result.deferred = true;
                    return result;
                }
            }

            // The producer fence is sufficient for shadow construction: all
            // artifacts and their derived records are now durable, and the
            // candidate captures the current replay floor after that output.
            // Do not wait for the ordinary canonical worker to apply each
            // generated record individually. Large chunked admissions are
            // intentionally completed by the bounded bulk snapshot path.
        }

        // Automatic reconstruction is destructive only at pointer activation,
        // but creating an apparently valid empty candidate from missing source
        // metadata is still unsafe. Full per-artifact validation remains part
        // of the shadow build.
        self.validateIndexRepairSourcePreflight(alloc, cfg_ptr.*) catch |err| {
            const err_name = if (err == error.RepairSourceCoverageIncomplete)
                "dense_artifact_coverage_missing"
            else
                @errorName(err);
            try self.recordIndexRepairAttemptFailure(alloc, repair_id, err_name, true);
            result.attempted = true;
            result.terminal = true;
            return result;
        };

        const active_index_bytes = self.core.index_manager.activeIndexStorageBytes(entry.intent.index_name) catch 0;
        const source_estimate = self.artifactBackedDenseRepairEstimate(alloc, cfg_ptr.*) catch 0;
        var estimated_candidate_bytes = @max(
            entry.intent.estimated_candidate_bytes,
            @max(options.estimated_candidate_bytes, @max(active_index_bytes, source_estimate)),
        );
        if (estimated_candidate_bytes == 0) {
            estimated_candidate_bytes = 64 * 1024 * 1024;
        }
        const cleanup_and_replay_headroom = @max(estimated_candidate_bytes / 4, 256 * 1024 * 1024);
        const required_disk_bytes = estimated_candidate_bytes +| cleanup_and_replay_headroom;
        const planned_disk_bytes = @max(
            entry.intent.planned_disk_bytes,
            @max(options.planned_disk_bytes, required_disk_bytes),
        );
        if (entry.intent.estimated_candidate_bytes != estimated_candidate_bytes or
            entry.intent.planned_disk_bytes != planned_disk_bytes)
        {
            try self.updateIndexRepairIntent(alloc, repair_id, .{
                .estimated_candidate_bytes = estimated_candidate_bytes,
                .planned_disk_bytes = planned_disk_bytes,
            });
            entry.intent.estimated_candidate_bytes = estimated_candidate_bytes;
            entry.intent.planned_disk_bytes = planned_disk_bytes;
        }

        // Capacity is checked and claimed through the shared ResourceManager
        // so every DB on the node participates in one admission domain. Existing
        // candidate bytes are already reflected in filesystem availability;
        // reserve only the remaining growth and cleanup headroom on resume.
        // Reconciliation above is intentionally admission-free because it
        // releases space and must remain possible on an already-full volume.
        var candidate_bytes: u64 = 0;
        if (entry.intent.candidate_relative_path) |candidate| {
            try index_repair_state.validateCandidateRelativePath(entry.intent.index_name, candidate);
            const separator = std.mem.indexOfScalar(u8, candidate, '/') orelse return error.InvalidRepairCandidatePath;
            if (entry.intent.kind == .algebraic) {
                const storage_namespace = try std.fmt.allocPrint(
                    alloc,
                    "{s}/{s}",
                    .{ candidate[0..separator], entry.intent.index_name },
                );
                defer alloc.free(storage_namespace);
                candidate_bytes = self.core.index_manager.algebraicStorageNamespaceBytes(storage_namespace) catch 0;
            } else {
                const candidate_root = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ self.core.path, candidate[0..separator] });
                defer alloc.free(candidate_root);
                candidate_bytes = directoryUsageBytes(alloc, candidate_root) catch 0;
            }
        }
        const remaining_disk_claim = planned_disk_bytes -| @min(planned_disk_bytes, candidate_bytes);
        const manager = self.core.index_manager.resource_manager orelse return error.ResourceManagerUnavailable;
        const first_capacity = repairCapacityObservation(effective_options) catch |err| {
            try self.recordIndexRepairAttemptFailure(alloc, repair_id, @errorName(err), false);
            result.deferred = true;
            result.disk_wait = true;
            return result;
        };
        var disk_reservation = manager.reserveCapacity(
            alloc,
            repairCapacityDomain(effective_options),
            remaining_disk_claim,
            first_capacity,
            monotonicTimeNs(),
        ) catch |err| switch (err) {
            error.CapacityUnavailable, error.CapacityObservationStale => {
                try self.recordIndexRepairAttemptFailure(alloc, repair_id, "disk_admission_unavailable", false);
                result.deferred = true;
                result.disk_wait = true;
                var updated = try self.loadIndexRepairEntryById(alloc, repair_id);
                defer updated.deinit(alloc);
                result.next_retry_at_ms = updated.intent.next_retry_at_ms;
                if (entry.intent.last_error == null or
                    !std.mem.eql(u8, entry.intent.last_error.?, "disk_admission_unavailable"))
                {
                    std.log.info("dense generation repair waiting for disk capacity index={s} available_bytes={?} requested_growth_bytes={} retry_at_ms={} reason={s}", .{
                        entry.intent.index_name,
                        first_capacity.available_bytes,
                        remaining_disk_claim,
                        result.next_retry_at_ms,
                        @errorName(err),
                    });
                }
                return result;
            },
            else => return err,
        };
        defer disk_reservation.release();
        var capacity_guard = RepairCapacityGuard{
            .reservation = &disk_reservation,
            .db = self,
            .alloc = alloc,
            .repair_id = repair_id,
            .options = effective_options,
            .admitted_total_bytes = planned_disk_bytes,
            .headroom_bytes = cleanup_and_replay_headroom,
        };

        const attempt_count = entry.intent.attempt_count +| 1;
        try self.updateIndexRepairIntent(alloc, repair_id, .{
            .attempt_count = attempt_count,
            .next_retry_at_ms = 0,
        });
        entry.intent.attempt_count = attempt_count;
        result.attempted = true;
        var run_options = effective_options;
        run_options.capacity_check = .{
            .ptr = &capacity_guard,
            .reconcile = RepairCapacityGuard.reconcile,
            .revalidate = RepairCapacityGuard.revalidate,
            .bind_candidate_root = RepairCapacityGuard.bindCandidateRoot,
        };
        const artifact_kind = artifactRepairKindForIndexKind(entry.intent.kind) orelse {
            try self.recordIndexRepairAttemptFailure(alloc, repair_id, "unsupported_index_kind", true);
            result.terminal = true;
            return result;
        };
        const repair = self.repairArtifactIssuesWithRequestOptionsInternal(alloc, .{
            .target = .index,
            .artifact_kind = artifact_kind,
            .index_name = entry.intent.index_name,
            .limit = 1,
            .force = true,
        }, run_options, .already_held) catch |err| {
            // Fault-injection hooks model process loss, not an ordinary
            // returned repair failure. Let the test harness observe the
            // injected stop without persisting retry/backoff state that a
            // crashed process could never have written.
            if (comptime builtin.is_test) {
                if (self.shadow_index_repair_hook != null and std.mem.startsWith(u8, @errorName(err), "Test")) {
                    return err;
                }
            }
            if (err == error.Canceled and run_options.cancelled()) {
                result.deferred = true;
                return result;
            }
            var current_trigger = entry.intent.trigger;
            if (err == error.RepairSourceCoverageIncomplete) {
                var current = try self.loadIndexRepairEntryById(alloc, repair_id);
                defer current.deinit(alloc);
                current_trigger = current.intent.trigger;
            }
            if (err == error.RepairSourceCoverageIncomplete and
                entry.intent.kind == .dense_vector and
                self.enrichment_runtime != null and
                (current_trigger == .operator_generation_rebuild or
                    current_trigger == .storage_format_migration or
                    current_trigger == .artifact_coverage_mismatch or
                    current_trigger == .replay_artifact_unavailable))
            {
                // A shadow rebuild consumes stored embedding artifacts and
                // cannot repair one missing below its snapshot floor. Re-arm
                // the managed producer from primary documents first.
                const artifact_names = try index_manager_mod.denseConfigArtifactNamesAlloc(alloc, cfg_ptr.*);
                defer {
                    for (artifact_names) |name| alloc.free(name);
                    alloc.free(artifact_names);
                }
                var queued_refs: usize = 0;
                for (artifact_names) |artifact_name| {
                    queued_refs +|= self.reprocessGeneratedEnrichmentFromStoredDocs(alloc, artifact_name) catch |reprocess_err| blk: {
                        std.log.warn(
                            "dense repair source recovery deferred index={s} artifact={s} err={s}",
                            .{ entry.intent.index_name, artifact_name, @errorName(reprocess_err) },
                        );
                        break :blk 0;
                    };
                }
                if (queued_refs != 0) {
                    const recovery_target = self.core.nextDerivedSequence();
                    const runtime = self.enrichment_runtime.?;
                    if (runtime.isStarted()) {
                        runtime.notifySequence(recovery_target);
                        runtime.waitForApplied(recovery_target) catch |drain_err| {
                            std.log.warn(
                                "dense repair source worker recovery deferred index={s} err={s}",
                                .{ entry.intent.index_name, @errorName(drain_err) },
                            );
                        };
                    } else {
                        // Bounded startup/repair owners must not start a
                        // long-lived worker which can outlive and pin them.
                        runtime.catchUpUntil(recovery_target) catch |drain_err| {
                            std.log.warn(
                                "dense repair source foreground recovery deferred index={s} err={s}",
                                .{ entry.intent.index_name, @errorName(drain_err) },
                            );
                        };
                    }
                }
            }
            const capacity_wait = err == error.CapacityUnavailable or err == error.CapacityObservationStale;
            // Use the same classification for live failures and persisted
            // terminal states from older binaries. Catalog admission retains
            // its existing producer outcomes; it does not re-arm failed work.
            const retryable_replacement_coverage =
                retryableIndexRepairTerminalPhase(@errorName(err), current_trigger) != null;
            const terminal_failure =
                !retryable_replacement_coverage and indexRepairFailureIsTerminal(err);
            try self.recordIndexRepairAttemptFailure(
                alloc,
                repair_id,
                if (capacity_wait) "disk_admission_unavailable" else @errorName(err),
                terminal_failure,
            );
            result.disk_wait = capacity_wait;
            if (terminal_failure) {
                result.terminal = true;
            } else {
                result.deferred = true;
                var updated = try self.loadIndexRepairEntryById(alloc, repair_id);
                defer updated.deinit(alloc);
                result.next_retry_at_ms = updated.intent.next_retry_at_ms;
            }
            return result;
        };
        result.documents_reprocessed = repair.reprocessed;
        applyCommittedRepairOutcomeToAdvance(&result, repair);

        // A committed replacement wins a cancellation observed after the
        // final pointer/checkpoint publication. Artifact debt discovered
        // during the rebuild remains in its own durable queue and must not
        // resurrect the already-completed generation intent.
        if (repair.indexes_rebuilt != 0 or repair.repaired != 0) {
            result.repaired = repair.indexes_degraded_after == 0 and !repair.debt_remaining;
            return result;
        }

        // Cooperative owner shutdown is not a failed repair attempt. Durable
        // snapshot/catch-up boundaries have already left the candidate in a
        // resumable phase, so preserve its retry schedule and let the next
        // owner continue immediately.
        if (run_options.cancelled()) {
            result.deferred = true;
            return result;
        }
        if (repair.in_progress != 0) {
            try self.updateIndexRepairIntent(alloc, repair_id, .{
                .failure_streak = 0,
                .next_retry_at_ms = 0,
                .replace_last_error = true,
            });
            result.busy = true;
            return result;
        }
        try self.recordIndexRepairAttemptFailure(alloc, repair_id, "repair_attempt_incomplete", false);
        result.deferred = true;
        var updated = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer updated.deinit(alloc);
        result.next_retry_at_ms = updated.intent.next_retry_at_ms;
        return result;
    }

    pub const StartupIndexRepairResult = struct {
        discovered: usize = 0,
        attempted: usize = 0,
        repaired: usize = 0,
        degraded: usize = 0,
        remaining: usize = 0,
        terminal: usize = 0,
        deferred: usize = 0,
        busy: usize = 0,
        disk_waits: usize = 0,
        documents_reprocessed: u64 = 0,
        next_retry_at_ms: u64 = 0,
        wake: IndexRepairWake = .empty,
        inspected: usize = 0,
        automatic_discovery_pending: bool = false,
    };

    /// Advances one durable projection-repair intent created while validating
    /// a native restore. `true` means the staged generation has no remaining
    /// repair debt and is eligible for sealing/publication. Existing healthy
    /// projections are never reset or replayed by this path.
    pub fn repairNativeRestoreProjectionIntentsStep(
        self: *DB,
        alloc: Allocator,
        options: types.ArtifactRepairRunOptions,
    ) !bool {
        const before = try self.indexRepairIntentSummary(alloc);
        if (before.terminal != 0) return error.NativeBackupProjectionRepairFailed;
        if (before.paused != 0) return error.NativeBackupProjectionRepairPaused;
        if (before.runnable == 0) return true;

        const result = try self.repairRecoverableStartupIndexFailures(alloc, 1, options);
        const after = try self.indexRepairIntentSummary(alloc);
        if (after.terminal != 0) return error.NativeBackupProjectionRepairFailed;
        if (after.paused != 0) return error.NativeBackupProjectionRepairPaused;
        return result.remaining == 0 and after.runnable == 0;
    }

    const index_repair_inspections_per_execution_slot: usize = 8;

    const IndexRepairInspectionWindow = struct {
        start: usize,
        budget: usize,
    };

    fn indexRepairInspectionWindow(
        candidate_count: usize,
        execution_limit: usize,
        cursor: u64,
    ) IndexRepairInspectionWindow {
        if (candidate_count == 0 or execution_limit == 0) return .{ .start = 0, .budget = 0 };
        return .{
            .start = @intCast(cursor % candidate_count),
            .budget = @min(
                candidate_count,
                std.math.mul(
                    usize,
                    execution_limit,
                    index_repair_inspections_per_execution_slot,
                ) catch std.math.maxInt(usize),
            ),
        };
    }

    const IndexRepairSchedulerSelection = struct {
        const Repair = struct {
            repair_id: u128,
            revision: u64,
            audit_due: bool,
        };

        repairs: std.ArrayListUnmanaged(Repair) = .empty,
        inspected: usize = 0,
        deferred: usize = 0,
        terminal: usize = 0,
        remaining: usize = 0,
        next_retry_at_ms: u64 = 0,

        pub fn deinit(self: *@This(), alloc: Allocator) void {
            self.repairs.deinit(alloc);
            self.* = undefined;
        }
    };

    fn selectIndexRepairSchedulerQuantum(
        self: *DB,
        alloc: Allocator,
        execution_limit: usize,
    ) !IndexRepairSchedulerSelection {
        return self.selectIndexRepairSchedulerQuantumForIndex(alloc, execution_limit, null);
    }

    fn selectIndexRepairSchedulerQuantumForIndex(self: *DB, alloc: Allocator, execution_limit: usize, target_index_name: ?[]const u8) !IndexRepairSchedulerSelection {
        try self.ensureIndexRepairSchedulerDirectory(alloc);
        var selection: IndexRepairSchedulerSelection = .{};
        errdefer selection.deinit(alloc);
        lockAtomic(&self.async_context.index_repair_scheduler_mutex);
        defer self.async_context.index_repair_scheduler_mutex.unlock();
        const directory = &self.async_context.index_repair_scheduler;
        const summary = directory.summaryForIndex(target_index_name);
        selection.terminal = summary.terminal;
        selection.deferred = summary.paused;
        selection.remaining = summary.runnable + summary.paused + summary.terminal;
        selection.next_retry_at_ms = summary.earliest_retry_at_ms;
        const target_index = if (target_index_name) |name| directory.by_name.get(name) else null;
        if (target_index_name != null and target_index == null) return selection;
        const inspection = if (target_index) |index| IndexRepairInspectionWindow{ .start = index, .budget = @min(execution_limit, 1) } else indexRepairInspectionWindow(
            directory.records.items.len,
            execution_limit,
            @intCast(directory.cursor),
        );
        try selection.repairs.ensureTotalCapacity(alloc, inspection.budget);
        const now_ms = self.indexRepairNowMs();
        while (selection.inspected < inspection.budget) : (selection.inspected += 1) {
            const record_index = (inspection.start + selection.inspected) % directory.records.items.len;
            const record = directory.records.items[record_index];
            if (target_index_name == null) directory.cursor = (record_index + 1) % directory.records.items.len;
            if (record.class != .runnable) continue;
            if (record.next_retry_at_ms > now_ms) {
                selection.deferred += 1;
                if (selection.next_retry_at_ms == 0 or record.next_retry_at_ms < selection.next_retry_at_ms) {
                    selection.next_retry_at_ms = record.next_retry_at_ms;
                }
                continue;
            }
            if (record.progress_wait_until_sequence != null) {
                // The slow audit deadline fired without a matching progress
                // callback. Clear the process-local wait before execution so
                // the new observation can arm a fresh token and deadline.
                const mutable = &directory.records.items[record_index];
                mutable.progress_wait_until_sequence = null;
                directory.progress_waiters -= 1;
                mutable.next_retry_at_ms = mutable.durable_next_retry_at_ms;
                directory.rescheduleRunnable(mutable.repair_id);
                if (directory.progress_waiters == 0) {
                    self.async_context.index_repair_progress_wait_pending.store(false, .release);
                }
            }
            selection.repairs.appendAssumeCapacity(.{
                .repair_id = record.repair_id,
                .revision = record.revision,
                .audit_due = record.audit_wait_armed,
            });
        }
        return selection;
    }

    /// Bounded owner-side pass used by managed startup workers and periodic
    /// repair scans. Discovery itself is cheap; callers choose when execution
    /// is admitted by passing a small `limit` (normally one per node).
    pub fn repairRecoverableStartupIndexFailures(
        self: *DB,
        alloc: Allocator,
        limit: usize,
        options: types.ArtifactRepairRunOptions,
    ) !StartupIndexRepairResult {
        var result: StartupIndexRepairResult = .{};
        const discovery = try self.discoverRecoverableStartupIndexFailures(alloc, limit);
        result.discovered = discovery.discovered;
        result.automatic_discovery_pending = discovery.automaticDiscoveryPending();
        // Existing terminal intents are counted from the durable state below.
        // Discovery contributes only terminal load failures for which no intent
        // exists, avoiding double-counting checkpointed failures.
        result.terminal = if (options.target_index_name == null) discovery.terminal - discovery.existing_terminal else 0;

        var selection = try self.selectIndexRepairSchedulerQuantumForIndex(alloc, limit, options.target_index_name);
        defer selection.deinit(alloc);
        result.terminal += selection.terminal;
        result.deferred += selection.deferred;
        result.next_retry_at_ms = selection.next_retry_at_ms;
        result.inspected = selection.inspected;
        result.remaining = selection.remaining;
        var consumed_slots: usize = 0;
        for (selection.repairs.items) |scheduled| {
            if (consumed_slots >= limit) break;
            const advanced = try self.advanceScheduledIndexRepairIntent(
                alloc,
                scheduled.repair_id,
                options,
                scheduled.revision,
                scheduled.audit_due,
            );
            result.attempted += @intFromBool(advanced.attempted);
            result.repaired += @intFromBool(advanced.repaired);
            result.degraded += @intFromBool(advanced.indexes_degraded_after != 0);
            result.deferred += @intFromBool(advanced.deferred);
            result.disk_waits += @intFromBool(advanced.disk_wait);
            result.busy += @intFromBool(advanced.busy);
            result.documents_reprocessed += advanced.documents_reprocessed;
            // Material execution and inspection are independently bounded.
            // Deferred progressive generations do not consume a repair slot,
            // while the rotating cursor prevents them from pinning every
            // future quantum ahead of later damaged indexes.
            if (advanced.attempted or advanced.busy or advanced.terminal) {
                consumed_slots += 1;
            }
        }
        // Mutations update the directory synchronously after their durable
        // checkpoint commit, so this exact count costs O(1) in steady state.
        // If a post-commit projection allocation failed, rebuild from the
        // durable authority before returning rather than misreporting an empty
        // aggregate. That exceptional recovery is allowed to fail explicitly.
        try self.ensureIndexRepairSchedulerDirectory(alloc);
        lockAtomic(&self.async_context.index_repair_scheduler_mutex);
        const directory = &self.async_context.index_repair_scheduler;
        const summary = directory.summaryForIndex(options.target_index_name);
        result.remaining = summary.runnable + summary.paused + summary.terminal;
        result.wake = summary.wake;
        result.next_retry_at_ms = result.wake.retryAtMs();
        self.async_context.index_repair_scheduler_mutex.unlock();
        return result;
    }

    pub fn repairArtifactIssuesWithRequest(
        self: *DB,
        alloc: Allocator,
        req: types.ArtifactRepairRunRequest,
    ) !types.ArtifactRepairResult {
        return try self.repairArtifactIssuesWithRequestOptions(alloc, req, .{});
    }

    pub fn repairArtifactIssuesWithRequestOptions(
        self: *DB,
        alloc: Allocator,
        req: types.ArtifactRepairRunRequest,
        options: types.ArtifactRepairRunOptions,
    ) !types.ArtifactRepairResult {
        return try self.repairArtifactIssuesWithRequestOptionsInternal(
            alloc,
            req,
            options,
            .acquire,
        );
    }

    const IndexRepairLeaseAuthority = enum {
        acquire,
        already_held,
    };

    /// Private recursion boundary. Public callers always enter with
    /// `.acquire`; only the full-quantum durable owner can supply
    /// `.already_held`, so the public options struct cannot forge lease
    /// ownership.
    fn repairArtifactIssuesWithRequestOptionsInternal(
        self: *DB,
        alloc: Allocator,
        req: types.ArtifactRepairRunRequest,
        options: types.ArtifactRepairRunOptions,
        lease_authority: IndexRepairLeaseAuthority,
    ) !types.ArtifactRepairResult {
        try checkArtifactRepairCancelled(options);
        if (req.target == .index) return try self.repairIndexIssuesWithRequest(
            alloc,
            req,
            options,
            lease_authority,
        );

        const page = try self.listArtifactRepairIssuesPage(alloc, .{
            .artifact_kind = req.artifact_kind,
            .index_name = req.index_name,
            .limit = req.limit,
            .cursor = req.cursor,
        });
        defer {
            types.freeArtifactRepairIssues(alloc, page.issues);
            if (page.next_cursor) |cursor| alloc.free(cursor);
        }

        var result: types.ArtifactRepairResult = .{
            .limit = req.limit,
            .has_more = page.has_more,
            .debt_remaining = page.has_more,
        };
        if (page.next_cursor) |cursor| {
            result.next_cursor = try alloc.dupe(u8, cursor);
        }
        for (page.issues) |*issue| {
            if (options.cancelled()) {
                result.unresolved += 1;
                result.debt_remaining = true;
                return result;
            }
            result.scanned += 1;
            const issue_revision = ArtifactRepairIssueRevision.capture(issue.*);
            issue.attempts += 1;
            issue.last_seen_ns = currentTimeNs();

            if (!issue.repairable or !artifactRepairKindHasReprocessor(issue.artifact_kind)) {
                const unsupported_reason = artifactRepairUnsupportedReasonForIssue(issue.*);
                issue.repairable = false;
                if (issue.unsupported_reason.len == 0) {
                    issue.unsupported_reason = try alloc.dupe(u8, unsupported_reason);
                }
                try replaceRepairIssueLastError(alloc, issue, unsupported_reason);
                _ = try self.saveArtifactRepairAttemptIfCurrent(alloc, issue.*, issue_revision);
                result.unsupported += 1;
                result.unresolved += 1;
                result.debt_remaining = true;
                continue;
            }

            // Consumer-specific debt records for one physical artifact share
            // a single local execution lease and a durable completion fence.
            // This prevents concurrent requests, later cursor pages, and
            // restart from paying for the same provider call more than once.
            const completion_key = try self.artifactRepairCompletionKeyForIssueAlloc(alloc, issue.*);
            defer alloc.free(completion_key);
            if (!(try self.beginIndexRepairLease(completion_key))) {
                result.in_progress += 1;
                result.unresolved += 1;
                result.debt_remaining = true;
                continue;
            }
            defer self.endIndexRepairLease(completion_key);

            const completion_snapshot = if (issue.reason == .enrichment_failed)
                try self.artifactRepairCompletionSnapshot(alloc, completion_key)
            else
                ArtifactRepairCompletionState{};
            if (issue.reason == .enrichment_failed and
                completion_snapshot.completed_sequence >= issue.sequence)
            {
                // Chunk regeneration is set-valued: a valid run may replace,
                // remove, or produce no physical chunks. A completion fence
                // written only after successful full_index regeneration is
                // the authoritative proof for sibling consumer debt.
                if (issue.artifact_kind == .chunk or try self.artifactNowReadable(alloc, issue.*)) {
                    switch (try self.completeArtifactRepairIssueIfCurrent(
                        alloc,
                        issue.*,
                        issue_revision,
                        completion_key,
                        completion_snapshot.epoch,
                        true,
                    )) {
                        .completed => {
                            result.repaired += 1;
                            continue;
                        },
                        .stale => {
                            result.unresolved += 1;
                            result.debt_remaining = true;
                            continue;
                        },
                        // A sibling consumer completed the shared provider
                        // work, but this consumer still has terminal coverage.
                        // Reprocess it below so the durable fence cannot turn
                        // into a permanent no-progress fast path.
                        .coverage_incomplete => {},
                    }
                }
            }

            const reprocessed = self.reprocessArtifactIssue(alloc, issue.*) catch |err| switch (err) {
                error.NotFound => {
                    try replaceRepairIssueLastError(alloc, issue, "source_document_missing");
                    _ = try self.saveArtifactRepairAttemptIfCurrent(alloc, issue.*, issue_revision);
                    result.missing_source_docs += 1;
                    result.unresolved += 1;
                    result.debt_remaining = true;
                    continue;
                },
                else => {
                    try replaceRepairIssueLastError(alloc, issue, @errorName(err));
                    _ = try self.saveArtifactRepairAttemptIfCurrent(alloc, issue.*, issue_revision);
                    result.failed += 1;
                    result.unresolved += 1;
                    result.debt_remaining = true;
                    continue;
                },
            };
            if (!reprocessed) {
                const unavailable_error = switch (issue.artifact_kind) {
                    .embedding => "embedding_enrichment_unavailable",
                    else => "artifact_reprocessor_unavailable",
                };
                try replaceRepairIssueLastError(alloc, issue, unavailable_error);
                _ = try self.saveArtifactRepairAttemptIfCurrent(alloc, issue.*, issue_revision);
                result.failed += 1;
                result.unresolved += 1;
                result.debt_remaining = true;
                continue;
            }
            result.reprocessed += 1;
            if (issue.artifact_kind == .chunk or try self.artifactNowReadable(alloc, issue.*)) {
                if (issue.reason == .enrichment_failed) {
                    switch (try self.completeArtifactRepairIssueIfCurrent(
                        alloc,
                        issue.*,
                        issue_revision,
                        completion_key,
                        completion_snapshot.epoch,
                        false,
                    )) {
                        .completed => result.repaired += 1,
                        .stale, .coverage_incomplete => {
                            result.unresolved += 1;
                            result.debt_remaining = true;
                        },
                    }
                } else {
                    if (try self.clearArtifactRepairIssueIfCurrent(alloc, issue.*, issue_revision)) {
                        result.repaired += 1;
                    } else {
                        result.unresolved += 1;
                        result.debt_remaining = true;
                    }
                }
            } else {
                try replaceRepairIssueLastError(alloc, issue, "artifact_still_unreadable");
                _ = try self.saveArtifactRepairAttemptIfCurrent(alloc, issue.*, issue_revision);
                result.failed += 1;
                result.unresolved += 1;
                result.debt_remaining = true;
            }
        }
        if (result.repaired != 0) {
            self.runDerivedUntil(self.core.nextDerivedSequence()) catch |err| switch (err) {
                error.ArtifactRepairRequired => {},
                else => return err,
            };
            try self.runArtifactRepairMetadataMaintenanceUntilIdle();
        }
        return result;
    }

    fn repairIndexIssuesWithRequest(
        self: *DB,
        alloc: Allocator,
        req: types.ArtifactRepairRunRequest,
        options: types.ArtifactRepairRunOptions,
        lease_authority: IndexRepairLeaseAuthority,
    ) !types.ArtifactRepairResult {
        try checkArtifactRepairCancelled(options);
        const requested_index = req.index_name orelse return error.InvalidArgument;
        if (req.cursor != null and req.cursor.?.len != 0) return error.InvalidArgument;
        const limit = if (req.limit == 0) @as(u32, 100) else req.limit;
        var result = types.ArtifactRepairResult{ .limit = limit };
        if (limit == 0) return result;
        if (req.control == null and req.repair_id != null) return error.InvalidArgument;

        const cfg_ptr = self.core.index_manager.get(requested_index) orelse return error.NotFound;
        var cfg = try types.IndexConfig.clone(alloc, cfg_ptr.*);
        defer cfg.deinit(alloc);

        if (req.control) |control| {
            if (req.force or req.cursor != null or req.artifact_kind != null) return error.InvalidArgument;
            const applied = switch (control) {
                .pause_automatic => try self.pauseAutomaticIndexRepair(alloc, requested_index, req.repair_id),
                .resume_automatic => try self.resumeAutomaticIndexRepair(alloc, requested_index, req.repair_id),
                .cancel_current_attempt => try self.cancelCurrentIndexRepairAttempt(alloc, requested_index, req.repair_id),
            };
            result.scanned = 1;
            result.controls_applied = @intFromBool(applied);
            result.debt_remaining = applied;
            result.indexes_degraded_before = @intFromBool(applied);
            result.indexes_degraded_after = @intFromBool(applied);
            return result;
        }

        if (req.artifact_kind) |kind| {
            const matches_kind = switch (cfg.kind) {
                .dense_vector, .sparse_vector => kind == .embedding,
                .graph => kind == .graph,
                .full_text => kind == .full_text,
                .algebraic => kind == .algebraic,
            };
            if (!matches_kind) return error.NotFound;
        }

        const repair_required = try self.indexGenerationRepairRequired(alloc, cfg.name);
        result.indexes_degraded_before = @intFromBool(repair_required);
        if (!repair_required and !req.force) return result;
        if ((req.repair_job_id == null) != (req.repair_job_created_at_ms == null)) return error.InvalidArgument;
        const repair_job_created_at_ms = req.repair_job_created_at_ms orelse 0;
        if (req.force and req.repair_job_id != null and try self.operatorRepairAlreadyCompleted(
            alloc,
            cfg,
            req.repair_job_id.?,
            repair_job_created_at_ms,
        )) {
            result.scanned = 1;
            result.indexes_rebuilt = 1;
            try self.finalizeCommittedIndexRepairOutcome(alloc, cfg.name, 0, &result);
            return result;
        }

        const initial_load_failure = self.core.index_manager.failedIndexLoadSnapshot(cfg.name);
        const had_load_failure = initial_load_failure != null;
        var durable_repair_id = try self.indexRepairIdForIndex(alloc, cfg.name);
        if (initial_load_failure != null and
            initial_load_failure.?.token.action == .rebuild_from_artifacts)
        {
            _ = try self.discoverRecoverableStartupIndexFailures(alloc, 1);
            durable_repair_id = try self.indexRepairIdForIndex(alloc, cfg.name);
        }
        if (try self.classifyCurrentDenseGenerationRepair(alloc, cfg)) |classification| {
            durable_repair_id = try self.ensureAutomaticDenseGenerationRepairIntent(
                alloc,
                cfg,
                classification.trigger,
                classification.last_error,
            );
        } else if (durable_repair_id == null) {
            durable_repair_id = try self.createOperatorGenerationRepairIntent(
                alloc,
                cfg,
                req.repair_job_id orelse 0,
                repair_job_created_at_ms,
            );
        }
        if (durable_repair_id) |repair_id| {
            if (req.force and req.repair_job_id != null) {
                try self.attachOperatorRepairRequest(
                    alloc,
                    repair_id,
                    req.repair_job_id.?,
                    repair_job_created_at_ms,
                );
            }
        }

        // Public/operator entry points never execute a durable generation
        // rebuild through this lower-level function. Managed callers enqueue
        // the exact group; standalone callers synchronously enter the same
        // admitted state machine used by the owner-side scheduler. The private
        // lease authority is also the recursion capability: public options
        // cannot bypass the durable owner by setting a data bit.
        if (durable_repair_id) |repair_id| if (lease_authority == .acquire) {
            result.scanned = 1;
            result.indexes_degraded_before = @intFromBool(repair_required);
            result.indexes_degraded_after = 1;
            if (req.force) {
                var current = try self.loadIndexRepairEntryById(alloc, repair_id);
                defer current.deinit(alloc);
                if (current.intent.phase == .terminal) {
                    try self.updateIndexRepairIntent(alloc, repair_id, .{
                        .phase = .detected,
                        .attempt_count = current.intent.attempt_count +| 1,
                        .failure_streak = 0,
                        .next_retry_at_ms = 0,
                        .replace_last_error = true,
                    });
                }
            }
            if (options.defer_durable_index_repair_execution) {
                result.in_progress = 1;
                result.unresolved = 1;
                result.debt_remaining = true;
                return result;
            }
            const advanced = try self.advanceIndexRepairIntent(alloc, repair_id, options);
            result.reprocessed = advanced.documents_reprocessed;
            if (advanced.has_repair_outcome) {
                result.repaired = advanced.artifacts_repaired;
                result.missing_source_docs = advanced.missing_source_docs;
                result.failed = advanced.failed;
                result.unsupported = advanced.unsupported;
                result.unresolved = advanced.unresolved;
                result.in_progress = advanced.in_progress;
                result.indexes_rebuilt = advanced.indexes_rebuilt;
                result.indexes_degraded_before = advanced.indexes_degraded_before;
                result.indexes_degraded_after = advanced.indexes_degraded_after;
                result.debt_remaining = advanced.debt_remaining;
            } else if (advanced.repaired) {
                result.repaired = 1;
                result.indexes_rebuilt = 1;
            } else if (advanced.terminal) {
                result.failed = 1;
                result.unresolved = 1;
                result.debt_remaining = true;
            } else {
                result.in_progress = 1;
                result.unresolved = 1;
                result.debt_remaining = true;
            }
            return result;
        };

        // Durable state-machine execution owns the lease at its outermost
        // boundary. Standalone non-durable repair retains the same exclusion
        // by acquiring it here. This avoids a nested, non-reentrant lease while
        // keeping all direct rebuild callers serialized with deletion.
        var local_repair_lease = false;
        if (lease_authority == .acquire) {
            if (!(try self.beginIndexRepairLease(cfg.name))) {
                result.scanned += 1;
                result.in_progress += 1;
                result.unresolved += 1;
                // A contended durable repair remains degraded. Do not publish
                // the zero-value gauge as an authoritative healthy observation.
                result.indexes_degraded_after = 1;
                result.debt_remaining = true;
                return result;
            }
            local_repair_lease = true;
        }
        defer if (local_repair_lease) self.endIndexRepairLease(cfg.name);

        result.scanned += 1;
        if (durable_repair_id) |repair_id| {
            var durable_entry = try self.loadIndexRepairEntryById(alloc, repair_id);
            defer durable_entry.deinit(alloc);
            const resumable = durable_entry.intent.candidate_relative_path != null and switch (durable_entry.intent.phase) {
                .building => durable_entry.intent.build_resume_key != null and
                    indexRepairSupportsSnapshotCursor(cfg.kind),
                .catching_up, .ready, .waiting_for_convergence => true,
                else => false,
            };
            if (durable_entry.intent.phase == .terminal) {
                try self.updateIndexRepairIntent(alloc, repair_id, .{
                    .phase = .detected,
                    .attempt_count = durable_entry.intent.attempt_count +| 1,
                    .failure_streak = 0,
                    .next_retry_at_ms = 0,
                    .replace_last_error = true,
                });
                durable_entry.intent.phase = .detected;
            }
            if (!resumable and durable_entry.intent.phase != .preflight) {
                // The scheduler's earlier admission probe precedes capacity
                // checks and source validation. Canonical publication can
                // become queryable in that interval. Serialize the final
                // decision with status: retain a certified partial generation,
                // retire a complete admission, or commit preflight before an
                // observer can publish the old canonical proof as ready.
                lockApply(self);
                defer self.core.unlockApply();
                var current = try self.loadIndexRepairEntryById(alloc, repair_id);
                defer current.deinit(alloc);
                if (try self.managedAdmissionGenerationIsServiceable(alloc, current.intent)) {
                    try self.ensureManagedAdmissionCanonicalWorker(alloc, current.intent);
                    try self.removeIndexRepairIntentAndPin(alloc, repair_id);
                    result.repaired += 1;
                    result.indexes_degraded_after = 0;
                    return result;
                }
                if (try self.managedAdmissionGenerationIsQueryable(alloc, current.intent)) {
                    try self.ensureManagedAdmissionCanonicalWorker(alloc, current.intent);
                    result.in_progress += 1;
                    result.unresolved += 1;
                    result.debt_remaining = true;
                    result.indexes_degraded_after = 0;
                    return result;
                }
                try self.updateIndexRepairIntent(alloc, repair_id, .{
                    .phase = .preflight,
                    .attempt_count = @max(@as(u32, 1), current.intent.attempt_count),
                    .failure_streak = 0,
                    .next_retry_at_ms = 0,
                    .replace_last_error = true,
                });
            }
            self.ensureDenseArtifactTargetCounterForRepair(
                alloc,
                cfg,
                repair_id,
                options.cancel_check,
            ) catch |err| switch (err) {
                error.Canceled, error.StaleDenseArtifactCounterBootstrap => {
                    result.in_progress += 1;
                    result.unresolved += 1;
                    result.debt_remaining = true;
                    return result;
                },
                else => return err,
            };
            self.validateIndexRepairSourcePreflight(alloc, cfg) catch |err| {
                const err_name = if (err == error.RepairSourceCoverageIncomplete)
                    "dense_artifact_coverage_missing"
                else
                    @errorName(err);
                try self.recordIndexRepairAttemptFailure(alloc, repair_id, err_name, true);
                result.failed += 1;
                result.unresolved += 1;
                result.debt_remaining = true;
                return result;
            };
        }
        result.indexes_degraded_before = @intFromBool(repair_required);
        result.indexes_degraded_after = 1;
        if (self.core.index_manager.failedIndexLoadSnapshot(cfg.name)) |failure| {
            const recovery_action = failure.token.action;
            switch (recovery_action) {
                .retry_open, .manual_intervention => {
                    // Explicit named operator repair may first retry that
                    // exact quarantined incarnation. If its identity changes,
                    // defer so the next pass re-audits the new policy instead
                    // of carrying stale authorization into reconstruction.
                    const retry_result = try self.retryQuarantinedIndexLoadTarget(.{
                        .name = cfg.name,
                        .token = failure.token,
                    }, true);
                    switch (retry_result.target_outcome) {
                        .stale, .repair_claimed, .backoff => {
                            result.in_progress += 1;
                            result.unresolved += 1;
                            result.debt_remaining = true;
                            return result;
                        },
                        .not_targeted => unreachable,
                        .absent, .attempted_failed, .recovered => {},
                    }
                    const remaining_failure = self.core.index_manager.failedIndexLoadSnapshot(cfg.name);
                    if (remaining_failure) |current| {
                        // A failed open advances the resident revision by
                        // design. Re-audit its policy, but retain operator
                        // authorization only for the same durable config.
                        if (current.token.config_hash != failure.token.config_hash) {
                            result.in_progress += 1;
                            result.unresolved += 1;
                            result.debt_remaining = true;
                            return result;
                        }
                        if (recovery_action == .retry_open or
                            current.token.action == .retry_open)
                        {
                            result.failed += 1;
                            result.unresolved += 1;
                            result.debt_remaining = true;
                            return result;
                        }
                    }
                },
                .rebuild_from_artifacts => {
                    // Build directly from the retained status-only config. The
                    // quarantined root remains untouched until the replacement
                    // is durable and activated by pointer swap.
                },
            }
        }
        if (had_load_failure and self.core.index_manager.loadFailure(cfg.name) == null and (cfg.kind == .full_text or cfg.kind == .algebraic) and !try self.indexGenerationRepairRequired(alloc, cfg.name)) {
            result.indexes_degraded_after = 0;
            result.repaired += 1;
            return result;
        }

        const rebuilt = self.rebuildIndexWithShadowReplacement(alloc, cfg, options, durable_repair_id) catch |err| switch (err) {
            error.Canceled => {
                result.unresolved += 1;
                result.debt_remaining = true;
                return result;
            },
            error.ShadowIndexCatchUpIncomplete => {
                result.failed += 1;
                result.unresolved += 1;
                result.debt_remaining = true;
                return result;
            },
            else => return err,
        };
        result.reprocessed += rebuilt.reprocessed;
        if (rebuilt.yielded) {
            result.unresolved += rebuilt.unresolved_artifacts;
            result.in_progress += 1;
            result.unresolved += 1;
            result.debt_remaining = true;
            return result;
        }
        result.indexes_rebuilt += 1;
        try self.finalizeCommittedIndexRepairOutcome(alloc, cfg.name, rebuilt.unresolved_artifacts, &result);
        return result;
    }

    const ShadowIndexReplacementResult = struct {
        reprocessed: u64 = 0,
        applied_sequence: u64 = 0,
        unresolved_artifacts: u64 = 0,
        yielded: bool = false,
    };

    fn rebuildIndexWithShadowReplacement(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        options: types.ArtifactRepairRunOptions,
        durable_repair_id: ?u128,
    ) !ShadowIndexReplacementResult {
        var yield_progress = ShadowIndexReplacementResult{};
        return self.rebuildIndexWithShadowReplacementOwned(alloc, cfg, options, durable_repair_id, &yield_progress) catch |err| switch (err) {
            error.RepairSourceChanged => blk: {
                // A source race requires a fresh snapshot, not failure backoff
                // or repeated catch-up of an irrecoverably stale candidate.
                // The owned builder has released all physical handles here.
                const repair_id = durable_repair_id orelse return err;
                try self.discardInactiveIndexRepairCandidate(alloc, repair_id);
                yield_progress.yielded = true;
                break :blk yield_progress;
            },
            // A bounded activation pause yielding to readers/writers is not
            // a storage failure. Keep the durable candidate runnable instead
            // of imposing failure backoff on ordinary scheduler contention.
            // Snapshot work already completed in this turn still belongs in
            // its result: a resumed candidate will not scan or count it again.
            error.RepairActivationBudgetExhausted => blk: {
                yield_progress.yielded = true;
                break :blk yield_progress;
            },
            else => return err,
        };
    }

    fn rebuildIndexWithShadowReplacementOwned(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        options: types.ArtifactRepairRunOptions,
        durable_repair_id: ?u128,
        yield_progress: *ShadowIndexReplacementResult,
    ) !ShadowIndexReplacementResult {
        try checkArtifactRepairCancelled(options);
        const working_set_plan = if (self.core.index_manager.resource_manager) |manager|
            try repairWorkingSetPlan(alloc, manager, cfg)
        else
            RepairWorkingSetPlan{ .reservation_bytes = 0 };
        var repair_admission: ?resource_manager_mod.Reservation = if (self.core.index_manager.resource_manager) |manager|
            manager.reserve(.dense_repair_working_set, working_set_plan.reservation_bytes) catch
                return error.RepairResourceUnavailable
        else
            null;
        defer if (repair_admission) |*reservation| reservation.release();

        // A forced dense rebuild is initially fail-closed. Only the admitted
        // background worker may prove the current generation safe enough to
        // remain online during shadow construction. Automatic anomaly
        // classifications stay fail-closed and reuse the same reconstruction.
        if (durable_repair_id) |repair_id| {
            var durable_entry = try self.loadIndexRepairEntryById(alloc, repair_id);
            defer durable_entry.deinit(alloc);
            if (durable_entry.intent.trigger == .operator_generation_validation) {
                switch (try self.validateOperatorDenseGenerationForOnlineRebuild(alloc, cfg, options)) {
                    .online_safe => try self.updateIndexRepairIntent(alloc, repair_id, .{
                        .trigger = .operator_generation_rebuild,
                        .replace_last_error = true,
                    }),
                    .replay_pending => return error.OperatorGenerationValidationPending,
                    .fail_closed => |classification| try self.updateIndexRepairIntent(alloc, repair_id, .{
                        .trigger = classification.trigger,
                        .last_error = classification.last_error,
                        .replace_last_error = true,
                    }),
                }
            }
        }
        var resume_candidate = false;
        var resume_building = false;
        var resume_requires_ready_manifest = false;
        var persisted_build_floor_sequence: u64 = 0;
        var build_source_guard: ?@import("artifact_source_gap.zig").Guard = null;
        var persisted_build_reprocessed: u64 = 0;
        var build_resume_key: ?[]u8 = null;
        defer if (build_resume_key) |key| alloc.free(key);
        const generation_id = durable_repair_id orelse try index_repair_state.newRepairId(alloc);
        var shadow_base: []u8 = undefined;
        if (durable_repair_id) |repair_id| {
            var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
            defer entry.deinit(alloc);
            const resumable_phase = switch (entry.intent.phase) {
                .building => entry.intent.build_resume_key != null and
                    indexRepairSupportsSnapshotCursor(cfg.kind),
                .catching_up, .ready, .waiting_for_convergence => true,
                else => false,
            };
            if (resumable_phase and entry.intent.candidate_relative_path != null) {
                const valid_source = blk: {
                    const guard = entry.intent.build_source_guard orelse break :blk false;
                    var read = try self.core.store.beginReadTxn();
                    defer read.abort();
                    guard.requireCurrent(&read) catch |err| switch (err) {
                        error.EnrichmentSourceChanged => break :blk false,
                        else => return err,
                    };
                    break :blk true;
                };
                if (!valid_source) {
                    return error.RepairSourceChanged;
                }
                build_source_guard = entry.intent.build_source_guard;
                const candidate = entry.intent.candidate_relative_path.?;
                try index_repair_state.validateCandidateRelativePath(cfg.name, candidate);
                const separator = std.mem.indexOfScalar(u8, candidate, '/') orelse return error.InvalidRepairCandidatePath;
                shadow_base = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ self.core.path, candidate[0..separator] });
                resume_candidate = true;
                resume_building = entry.intent.phase == .building;
                resume_requires_ready_manifest = entry.intent.phase == .ready or entry.intent.phase == .waiting_for_convergence;
                persisted_build_floor_sequence = entry.intent.build_floor_sequence;
                persisted_build_reprocessed = entry.intent.build_reprocessed;
                build_resume_key = if (entry.intent.build_resume_key) |key| try alloc.dupe(u8, key) else null;
            } else {
                try self.discardInactiveIndexRepairCandidate(alloc, repair_id);
                shadow_base = try createUniqueRepairShadowBase(alloc, self.core.path);
            }
        } else {
            shadow_base = try createUniqueRepairShadowBase(alloc, self.core.path);
        }
        if (!resume_candidate) try index_manager_mod.IndexManager.writeRepairShadowInProgressMarker(alloc, shadow_base);
        var shadow_installed = false;
        var candidate_reopenable = resume_candidate;
        defer {
            var io_impl = threadedIo();
            defer io_impl.deinit();
            if (!shadow_installed and !candidate_reopenable) {
                if (cfg.kind == .algebraic) {
                    // Leave the index directory as a durable namespace marker.
                    // Once the in-progress marker is cleared, paged orphan
                    // cleanup can resume after failure or process restart.
                    index_manager_mod.IndexManager.clearRepairShadowInProgressMarker(alloc, shadow_base) catch {};
                    self.scheduleInactiveRepairShadowCleanup();
                } else {
                    index_manager_mod.IndexManager.clearRepairShadowInProgressMarker(alloc, shadow_base) catch {};
                    std.Io.Dir.cwd().deleteTree(io_impl.io(), shadow_base) catch {};
                }
            }
            alloc.free(shadow_base);
        }
        const shadow_indexes_path = try std.fmt.allocPrint(alloc, "{s}/indexes", .{shadow_base});
        defer alloc.free(shadow_indexes_path);
        if (!resume_candidate) try ensureDirPath(shadow_indexes_path);

        const shadow_index_path = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ shadow_indexes_path, cfg.name });
        defer alloc.free(shadow_index_path);
        // Generation manifests belong to the repair owner. Storage backends
        // may keep index data in a separate namespace and need not create
        // this filesystem directory as a side effect of opening an index.
        try ensureDirPath(shadow_index_path);
        const shadow_checkpoint_path = try std.fmt.allocPrint(alloc, "{s}/applied-sequences", .{shadow_base});
        defer alloc.free(shadow_checkpoint_path);
        if (options.capacity_check) |check| try check.bindCandidateRoot(shadow_base);
        if (resume_requires_ready_manifest) {
            _ = index_generation_manifest.validateReady(
                alloc,
                shadow_index_path,
                generation_id,
                cfg.name,
                types.indexConfigHash(cfg),
            ) catch {
                candidate_reopenable = false;
                if (durable_repair_id) |repair_id| self.discardInactiveIndexRepairCandidate(alloc, repair_id) catch {};
                return error.RepairCandidateResumeInvalid;
            };
        }
        if (!resume_candidate) {
            if (durable_repair_id) |repair_id| {
                const candidate_relative_path = try std.fmt.allocPrint(
                    alloc,
                    "{s}/indexes/{s}",
                    .{ std.fs.path.basename(shadow_base), cfg.name },
                );
                defer alloc.free(candidate_relative_path);
                try index_repair_state.validateCandidateRelativePath(cfg.name, candidate_relative_path);
                try self.updateIndexRepairIntent(alloc, repair_id, .{
                    .phase = .building,
                    .candidate_relative_path = candidate_relative_path,
                    .replace_candidate_path = true,
                });
            }
        }

        var shadow_backends = self.index_backends;
        // The parent catalog capability floor authorizes creation of this
        // private candidate. It must become independently authoritative before
        // the checksummed manifest and active pointer can publish it.
        shadow_backends.dense_native_candidate_build_authorized = if (self.index_backends.dense_native_migration_policy_source) |source|
            source.authorityPermitted()
        else
            true;
        // Detached index entries are adopted by the serving manager. Their
        // mutexes, configs and runtime objects must share its allocator, even
        // when this repair was requested through a short-lived HTTP arena.
        var shadow_manager = try index_manager_mod.IndexManager.initWithOptions(
            self.core.index_manager.alloc,
            shadow_base,
            shadow_backends,
        );
        // Repair candidates share the table's immutable source owner too.
        // Otherwise their native base build silently recreates payload copies.
        shadow_manager.source_payload_store = self.core.index_manager.source_payload_store;
        shadow_manager.setIo(self.backend_runtime.io());
        shadow_manager.setAppliedSequenceCheckpointPath(shadow_checkpoint_path);
        shadow_manager.registerReplacementIndex(self.core.store, cfg) catch |err| {
            shadow_manager.transferLsmOwnerCloneStatsTo(self.core.index_manager) catch |transfer_err| {
                std.log.warn("failed to preserve unopened shadow LSM clone attribution index={s} err={s}", .{
                    cfg.name,
                    @errorName(transfer_err),
                });
            };
            shadow_manager.deinit();
            if (resume_candidate) {
                candidate_reopenable = false;
                if (durable_repair_id) |repair_id| self.discardInactiveIndexRepairCandidate(alloc, repair_id) catch {};
                return error.RepairCandidateResumeInvalid;
            }
            return err;
        };
        var shadow_manager_open = true;
        defer if (shadow_manager_open) {
            shadow_manager.transferLsmOwnerCloneStatsTo(self.core.index_manager) catch |err| {
                std.log.warn("failed to preserve shadow LSM clone attribution index={s} err={s}", .{
                    cfg.name,
                    @errorName(err),
                });
            };
            shadow_manager.deinit();
        };

        // A scan cursor is useful only when there is a durable intent to own
        // it. Non-durable/internal one-shot rebuild callers retain the existing
        // complete bulk behavior even if they forward a scheduler policy by
        // mistake; otherwise they could repeatedly discard partial shadows.
        var effective_options = options;
        if (durable_repair_id == null) effective_options.yield_check = null;
        const cooperative_snapshot_build =
            indexRepairSupportsSnapshotCursor(cfg.kind) and
            effective_options.yield_check != null;
        var repair_issue_counter: AtomicU64 = .init(0);
        defer yield_progress.unresolved_artifacts = repair_issue_counter.load(.monotonic);
        var shadow_ctx = AsyncContext{
            .alloc = alloc,
            .io = self.backend_runtime.io(),
            .store = self.core.store,
            .relational_base_rows = relationalColumns(self) != null,
            .applied_sequence_checkpoint_path = shadow_checkpoint_path,
            .index_manager = &shadow_manager,
            .apply_mutex = self.async_context.apply_mutex,
            .dense_bulk_session_scope = .external,
            .resolution_runtime = self.resolution_runtime,
            .promotion_runtime = self.promotion_runtime,
            .repair_options = effective_options,
            .repair_issue_counter = &repair_issue_counter,
        };
        defer shadow_ctx.deinit(alloc);

        var build_floor_sequence: u64 = if (resume_building)
            persisted_build_floor_sequence
        else if (resume_candidate)
            try apply_state.loadAppliedSequenceWithCheckpoint(
                alloc,
                shadow_manager.checkpointIo(),
                self.core.store,
                shadow_checkpoint_path,
                cfg.name,
            )
        else
            0;
        var expected_snapshot_coverage: ?u64 = null;
        const completed_snapshot_build = !resume_candidate or resume_building;
        const rebuilt: u64 = if (resume_candidate and !resume_building) 0 else switch (cfg.kind) {
            .dense_vector, .sparse_vector, .graph, .full_text, .algebraic => rebuilt_blk: {
                try checkArtifactRepairCancelled(options);
                var pinned_snapshot: ?PinnedIndexRepairSnapshot = if (!resume_building) if (durable_repair_id) |repair_id|
                    try self.beginPinnedIndexRepairSnapshot(alloc, repair_id)
                else
                    null else null;
                defer if (pinned_snapshot) |*pinned| pinned.deinit();
                var ordinary_snapshot: ?docstore_mod.DocStore.Txn = if (pinned_snapshot == null)
                    try self.core.store.beginReadTxn()
                else
                    null;
                defer if (ordinary_snapshot) |*ordinary| ordinary.abort();
                const snapshot_txn = if (pinned_snapshot) |*pinned|
                    &pinned.txn
                else
                    &ordinary_snapshot.?;
                if (!resume_building) build_source_guard = try @import("artifact_source_gap.zig").Guard.capture(snapshot_txn);
                build_floor_sequence = if (resume_building)
                    persisted_build_floor_sequence
                else if (pinned_snapshot) |pinned|
                    pinned.build_floor_sequence
                else
                    try self.core.store.lastReplaySequenceFromTxn(snapshot_txn, 0);
                shadow_ctx.repair_sequence = build_floor_sequence;
                shadow_ctx.snapshot_read_txn = snapshot_txn;
                defer shadow_ctx.snapshot_read_txn = null;
                const count: u64 = switch (cfg.kind) {
                    .dense_vector => count_blk: {
                        var slice = try rebuildDenseIndexForTargetCoverageSliceContext(
                            &shadow_ctx,
                            cfg.name,
                            working_set_plan.dense_rebuild_batch_items,
                            build_resume_key,
                        );
                        defer slice.deinit(alloc);
                        const count: u64 = persisted_build_reprocessed +| @as(u64, @intCast(slice.rebuilt));
                        if (!slice.complete()) {
                            if (options.capacity_check) |check| {
                                try check.current(try directoryUsageBytes(alloc, shadow_base));
                            }
                            if (durable_repair_id) |repair_id| {
                                try self.updateIndexRepairIntent(alloc, repair_id, .{
                                    .phase = .building,
                                    .build_resume_key = slice.resume_key.?,
                                    .replace_build_resume_key = true,
                                    .build_reprocessed = count,
                                    .failure_streak = 0,
                                    .next_retry_at_ms = 0,
                                    .replace_last_error = true,
                                });
                            }
                            candidate_reopenable = durable_repair_id != null;
                            return .{ .reprocessed = @intCast(slice.rebuilt), .yielded = true };
                        }
                        const completed_dense = shadow_manager.denseIndex(cfg.name) orelse return error.IndexNotFound;
                        if (completed_dense.managed_direct_field) {
                            // The complete pinned primary scan counts raw and
                            // stripped/artifact-backed values exactly once.
                            // Verify before catch-up, which can change count.
                            expected_snapshot_coverage = count;
                            if (!denseCoverageMatchesTarget(completed_dense.index.stats().active_count, count)) return error.RepairSourceCoverageIncomplete;
                        } else if (cooperative_snapshot_build) {
                            // A count observed between slices is not a stable
                            // coverage assertion. Require the durable,
                            // generation-scoped outcome tuple when available;
                            // validate its exact fenced value after final
                            // replay below.
                            const dense_entry = shadow_manager.denseIndex(cfg.name) orelse return error.IndexNotFound;
                            expected_snapshot_coverage = if (denseIndexIsArtifactBacked(dense_entry))
                                try denseTargetCountForIndexContext(&shadow_ctx, cfg.name)
                            else
                                null;
                        } else {
                            expected_snapshot_coverage = try denseTargetCountForIndexContext(&shadow_ctx, cfg.name);
                        }
                        break :count_blk count;
                    },
                    .sparse_vector => count_blk: {
                        var slice = try rebuildSparseIndexFromStoredEmbeddingArtifactsSliceContext(&shadow_ctx, cfg.name, if (builtin.is_test) test_dense_repair_rebuild_batch_size orelse 256 else 256, build_resume_key);
                        defer slice.deinit(alloc);
                        const count = persisted_build_reprocessed +| @as(u64, @intCast(slice.rebuilt));
                        if (!slice.complete()) {
                            if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
                                .phase = .building,
                                .build_resume_key = slice.resume_key.?,
                                .replace_build_resume_key = true,
                                .build_reprocessed = count,
                                .failure_streak = 0,
                                .next_retry_at_ms = 0,
                                .replace_last_error = true,
                            });
                            candidate_reopenable = durable_repair_id != null;
                            return .{ .reprocessed = @intCast(slice.rebuilt), .yielded = true };
                        }
                        const built = shadow_manager.sparseIndex(cfg.name) orelse return error.IndexNotFound;
                        if (built.managed_direct_field and built.index.stats().doc_count != count) return error.RepairSourceCoverageIncomplete;
                        break :count_blk count;
                    },
                    .graph => @intCast(try applySplitGraphArtifactsForIndexStreamingContext(
                        &shadow_ctx,
                        cfg.name,
                        graph_repair_rebuild_batch_size,
                    )),
                    .full_text => count_blk: {
                        var slice = try shadow_manager.rebuildFullTextIndexFromReadTxnSlice(self.core.store, snapshot_txn, cfg.name, build_resume_key, effective_options);
                        defer slice.deinit(shadow_manager.alloc);
                        if (slice.resume_key) |cursor| {
                            if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
                                .phase = .building,
                                .build_resume_key = cursor,
                                .replace_build_resume_key = true,
                                .build_reprocessed = slice.rebuilt,
                                .failure_streak = 0,
                                .next_retry_at_ms = 0,
                                .replace_last_error = true,
                            });
                            candidate_reopenable = durable_repair_id != null;
                            return .{ .reprocessed = @intCast(slice.rebuilt -| persisted_build_reprocessed), .yielded = true };
                        }
                        break :count_blk slice.rebuilt;
                    },
                    .algebraic => count_blk: {
                        var slice = try rebuildAlgebraicIndexFromSnapshotSliceContext(
                            &shadow_ctx,
                            cfg.name,
                            if (comptime builtin.is_test)
                                test_algebraic_repair_rebuild_batch_size orelse 256
                            else
                                256,
                            build_resume_key,
                        );
                        defer slice.deinit(alloc);
                        const count = persisted_build_reprocessed +| @as(u64, @intCast(slice.rebuilt));
                        if (!slice.complete()) {
                            if (durable_repair_id) |repair_id| {
                                try self.updateIndexRepairIntent(alloc, repair_id, .{
                                    .phase = .building,
                                    .build_resume_key = slice.resume_key.?,
                                    .replace_build_resume_key = true,
                                    .build_reprocessed = count,
                                    .failure_streak = 0,
                                    .next_retry_at_ms = 0,
                                    .replace_last_error = true,
                                });
                            }
                            candidate_reopenable = durable_repair_id != null;
                            return .{ .reprocessed = @intCast(slice.rebuilt), .yielded = true };
                        }
                        break :count_blk count;
                    },
                };
                break :rebuilt_blk count;
            },
        };
        // Durable intent progress is cumulative, while the public/run result
        // reports work performed by this scheduler turn. Keeping those two
        // meanings separate prevents the final resumed slice from recounting
        // every vector processed by earlier turns.
        const reprocessed_this_pass = if (resume_building and
            indexRepairSupportsSnapshotCursor(cfg.kind))
            rebuilt -| persisted_build_reprocessed
        else
            rebuilt;
        yield_progress.reprocessed = reprocessed_this_pass;

        const index_ref = index_manager_mod.ManagedIndexRef{
            .name = cfg.name,
            .kind = cfg.kind,
        };
        if (cfg.kind == .dense_vector) {
            const built_entry = shadow_manager.denseIndex(cfg.name) orelse return error.IndexNotFound;
            if (completed_snapshot_build and denseIndexIsArtifactBacked(built_entry) and expected_snapshot_coverage == null) {
                return error.RepairSourceCoverageIncomplete;
            }
            if (!cooperative_snapshot_build) {
                if (expected_snapshot_coverage) |expected| {
                    if (!denseCoverageMatchesTarget(built_entry.index.stats().active_count, expected)) {
                        return error.RepairSourceCoverageIncomplete;
                    }
                }
            }
        }
        if (completed_snapshot_build) {
            try checkArtifactRepairCancelled(options);
            try self.saveShadowReplacementAppliedSequence(alloc, &shadow_manager, shadow_checkpoint_path, index_ref, build_floor_sequence);
            if (options.capacity_check) |check| {
                try check.current(try repairCandidateStorageBytes(alloc, cfg, &shadow_manager, shadow_base));
            }
            if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
                .phase = .catching_up,
                .replace_build_resume_key = true,
                .build_reprocessed = rebuilt,
                .candidate_applied_sequence = build_floor_sequence,
                .failure_streak = 0,
                .next_retry_at_ms = 0,
                .replace_last_error = true,
            });
            // From this transition onward the candidate and its applied
            // checkpoint are independently reopenable. Cancellation, owner
            // loss, or restart preserves it for bounded catch-up resumption.
            candidate_reopenable = durable_repair_id != null;
            if (self.shadow_index_repair_hook) |hook| {
                try hook.after_snapshot_build(hook.ptr, self, cfg.name, build_floor_sequence);
            }
        }
        var observed_ns_per_sequence: u64 = 0;
        var catch_up_start_sequence = build_floor_sequence;
        var catch_up_start_ns = monotonicTimeNs();
        const initial_catch_up_target = self.core.nextDerivedSequence();
        const initial_catch_up = try self.catchUpShadowReplacementUntil(
            alloc,
            &shadow_manager,
            shadow_checkpoint_path,
            index_ref,
            initial_catch_up_target,
            options,
            null,
            0,
        );
        var converged_sequence = initial_catch_up.applied_sequence;
        if (options.capacity_check) |check| {
            try check.current(try repairCandidateStorageBytes(alloc, cfg, &shadow_manager, shadow_base));
        }
        observed_ns_per_sequence = observeRepairCatchUpCost(
            observed_ns_per_sequence,
            catch_up_start_sequence,
            converged_sequence,
            elapsedSince(catch_up_start_ns),
        );
        if (initial_catch_up.yielded) {
            if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
                .phase = .catching_up,
                .candidate_applied_sequence = converged_sequence,
                .target_sequence = initial_catch_up_target,
                .failure_streak = 0,
                .next_retry_at_ms = 0,
                .replace_last_error = true,
            });
            candidate_reopenable = durable_repair_id != null;
            return .{ .reprocessed = reprocessed_this_pass, .yielded = true };
        }
        // A generation manifest is a promise that the candidate is
        // independently recoverable. Snapshot construction can legitimately
        // bypass source captures, so explicitly bootstrap and validate the
        // native HBC generation before making that promise. The first native
        // checkpoint is already a full segment; later convergence is flattened
        // once, after the candidate is close enough to activate.
        try finalizeShadowNativePostingGeneration(
            &shadow_manager,
            index_ref,
            converged_sequence,
            true,
            false,
        );
        try index_generation_manifest.writeReadyForPhysicalFormat(
            alloc,
            shadow_index_path,
            generation_id,
            cfg.name,
            types.indexConfigHash(cfg),
            converged_sequence,
            try shadowIndexPhysicalFormat(&shadow_manager, index_ref),
        );
        if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
            .phase = .ready,
            .candidate_applied_sequence = converged_sequence,
            .target_sequence = self.core.nextDerivedSequence(),
        });

        if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
            .phase = .waiting_for_convergence,
            .candidate_applied_sequence = converged_sequence,
            .target_sequence = self.core.nextDerivedSequence(),
        });
        const max_activation_gap_sequences = @max(@as(u64, 1), options.max_activation_gap_sequences);
        const max_convergence_rounds: usize = @max(@as(usize, 1), options.max_convergence_rounds);
        const max_activation_pause_ns = std.math.mul(
            u64,
            @max(@as(u64, 1), options.max_activation_pause_ms),
            std.time.ns_per_ms,
        ) catch std.math.maxInt(u64);
        var convergence_round: usize = 0;
        while (!repairActivationAdmissible(
            self.core.nextDerivedSequence() -| converged_sequence,
            observed_ns_per_sequence,
            max_activation_gap_sequences,
            max_activation_pause_ns,
        ) and
            convergence_round < max_convergence_rounds) : (convergence_round += 1)
        {
            const convergence_target = self.core.nextDerivedSequence();
            if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
                .phase = .catching_up,
                .candidate_applied_sequence = converged_sequence,
                .target_sequence = convergence_target,
            });
            catch_up_start_sequence = converged_sequence;
            catch_up_start_ns = monotonicTimeNs();
            const convergence_catch_up = try self.catchUpShadowReplacementUntil(
                alloc,
                &shadow_manager,
                shadow_checkpoint_path,
                index_ref,
                convergence_target,
                options,
                null,
                0,
            );
            converged_sequence = convergence_catch_up.applied_sequence;
            if (options.capacity_check) |check| {
                try check.current(try repairCandidateStorageBytes(alloc, cfg, &shadow_manager, shadow_base));
            }
            observed_ns_per_sequence = observeRepairCatchUpCost(
                observed_ns_per_sequence,
                catch_up_start_sequence,
                converged_sequence,
                elapsedSince(catch_up_start_ns),
            );
            if (convergence_catch_up.yielded) {
                if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
                    .phase = .catching_up,
                    .candidate_applied_sequence = converged_sequence,
                    .target_sequence = convergence_target,
                    .failure_streak = 0,
                    .next_retry_at_ms = 0,
                    .replace_last_error = true,
                });
                candidate_reopenable = durable_repair_id != null;
                return .{ .reprocessed = reprocessed_this_pass, .yielded = true };
            }
            try finalizeShadowNativePostingGeneration(
                &shadow_manager,
                index_ref,
                converged_sequence,
                false,
                false,
            );
            try index_generation_manifest.writeReadyForPhysicalFormat(
                alloc,
                shadow_index_path,
                generation_id,
                cfg.name,
                types.indexConfigHash(cfg),
                converged_sequence,
                try shadowIndexPhysicalFormat(&shadow_manager, index_ref),
            );
            if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
                .phase = .ready,
                .candidate_applied_sequence = converged_sequence,
                .target_sequence = convergence_target,
            });
            if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
                .phase = .waiting_for_convergence,
                .candidate_applied_sequence = converged_sequence,
                .target_sequence = self.core.nextDerivedSequence(),
            });
        }
        if (!repairActivationAdmissible(
            self.core.nextDerivedSequence() -| converged_sequence,
            observed_ns_per_sequence,
            max_activation_gap_sequences,
            max_activation_pause_ns,
        )) {
            return error.RepairActivationBudgetExhausted;
        }
        // Flatten outside the reader/apply pause. Final fenced replay below is
        // deliberately allowed to remain as a small committed WAL tail: a
        // whole-corpus rewrite inside the activation budget would make repair
        // latency scale with index size rather than with the bounded catch-up
        // gap.
        try finalizeShadowNativePostingGeneration(
            &shadow_manager,
            index_ref,
            converged_sequence,
            true,
            true,
        );
        try index_generation_manifest.writeReadyForPhysicalFormat(
            alloc,
            shadow_index_path,
            generation_id,
            cfg.name,
            types.indexConfigHash(cfg),
            converged_sequence,
            try shadowIndexPhysicalFormat(&shadow_manager, index_ref),
        );
        const ready_sequence = try index_generation_manifest.validateReady(
            alloc,
            shadow_index_path,
            generation_id,
            cfg.name,
            types.indexConfigHash(cfg),
        );
        if (ready_sequence != converged_sequence) return error.IndexGenerationManifestMismatch;
        try checkArtifactRepairActivationOwner(options);
        // The ordinary derived worker owns an in-memory replay cursor and
        // applied watermark that are independent of the durable projection
        // checkpoint. Stop it before publication. Otherwise it can resume
        // after the pointer swap from its pre-repair cursor and apply journal
        // history that the shadow's snapshot already includes, corrupting the
        // newly activated generation with stale deletes. The replacement is
        // caught up under the activation fence below; reinstall the worker at
        // that exact baseline after publication.
        var worker_reinstall_needed = false;
        var worker_reinstall_sequence: u64 = 0;
        defer if (worker_reinstall_needed) {
            self.executor.addWorker(cfg.name, index_ref, worker_reinstall_sequence) catch |err| {
                std.log.err(
                    "failed to restore derived worker after index repair activation index={s} sequence={} err={s}",
                    .{ cfg.name, worker_reinstall_sequence, @errorName(err) },
                );
            };
            const restore_target = self.core.nextDerivedSequence();
            if (restore_target > worker_reinstall_sequence) self.executor.notifyIndexes(restore_target, &.{cfg.name});
        };
        if (self.start_index_workers) {
            worker_reinstall_sequence = try self.core.loadAppliedSequence(alloc, cfg.name);
            worker_reinstall_needed = true;
            if (self.executor.appliedSequence(cfg.name)) |worker_applied| {
                self.executor.removeWorker(cfg.name);
                worker_reinstall_sequence = @max(worker_reinstall_sequence, worker_applied);
            }
        }
        // Final publication detaches and later destroys the active inline
        // generation. Drain maintenance before starting the bounded reader
        // pause: this work has no catalog effect and may wait for an active
        // merge or compaction whose duration is not part of query downtime.
        var structural_guard = self.beginDrainedIndexStructuralMutation(
            "index repair activation",
            cfg.name,
        );
        defer structural_guard.deinit();
        const activation_started_ns = monotonicTimeNs();
        const activation_deadline_ns = activation_started_ns +| max_activation_pause_ns;
        if (!structural_guard.acquireCatalogBarrierUntil(activation_deadline_ns)) {
            return error.RepairActivationBudgetExhausted;
        }
        var unpublished_replacement: ?index_manager_mod.IndexManager.DetachedIndex = null;
        defer if (unpublished_replacement) |*replacement| {
            shadow_manager.destroyDetachedReplacementIndex(replacement);
        };
        var retired_generation: ?index_manager_mod.IndexManager.DetachedIndex = null;
        defer if (retired_generation) |*retired| {
            self.core.index_manager.destroyDetachedReplacementIndex(retired);
        };
        var activation_metric_recorded = false;
        defer if (!activation_metric_recorded) {
            if (self.core.index_manager.resource_manager) |manager| {
                manager.recordIndexRepairActivation(monotonicTimeNs() -| activation_started_ns, max_activation_pause_ns);
            }
        };
        try checkArtifactRepairCancelled(options);
        if (!self.lockApplyUntil(activation_deadline_ns)) return error.RepairActivationBudgetExhausted;
        var apply_lock_held = true;
        defer if (apply_lock_held) self.core.unlockApply();

        const final_target = self.core.nextDerivedSequence();
        if (!repairActivationAdmissible(
            final_target -| converged_sequence,
            observed_ns_per_sequence,
            max_activation_gap_sequences,
            max_activation_pause_ns,
        )) {
            return error.RepairActivationBudgetExhausted;
        }
        const activation_replay_deadline_ns = repairActivationReplayDeadline(
            monotonicTimeNs(),
            activation_deadline_ns,
            max_activation_pause_ns,
        ) orelse return error.RepairActivationBudgetExhausted;
        const activation_catch_up = self.catchUpShadowReplacementUntil(
            alloc,
            &shadow_manager,
            shadow_checkpoint_path,
            index_ref,
            final_target,
            options,
            activation_replay_deadline_ns,
            observed_ns_per_sequence,
        ) catch |err| switch (err) {
            error.CatchUpDeadlineExceeded => return error.RepairActivationBudgetExhausted,
            else => return err,
        };
        std.debug.assert(!activation_catch_up.yielded);
        const reached_target = activation_catch_up.applied_sequence;
        if (reached_target < final_target) return error.ShadowIndexCatchUpIncomplete;
        // Catch-up cannot repair a write which never entered the replay log.
        // Recheck the original snapshot's persisted source guard under the
        // activation writer fence, before publishing any candidate pointer.
        {
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            const guard = build_source_guard orelse return error.RepairSourceChanged;
            guard.requireCurrent(&read) catch |err| switch (err) {
                error.EnrichmentSourceChanged => {
                    candidate_reopenable = false;
                    return error.RepairSourceChanged;
                },
                else => return err,
            };
        }
        // The generation-scoped coverage tuple is maintained in the same
        // fenced primary write stream and is O(1) to read.
        if (cfg.kind == .dense_vector) {
            const dense_entry = shadow_manager.denseIndex(cfg.name) orelse return error.IndexNotFound;
            if (denseIndexIsArtifactBacked(dense_entry)) {
                const expected = (try denseTargetCountForIndexContext(self.async_context, cfg.name)) orelse
                    return error.RepairSourceCoverageIncomplete;
                if (!denseCoverageMatchesTarget(dense_entry.index.stats().active_count, expected)) {
                    return error.RepairSourceCoverageIncomplete;
                }
            } else if (dense_entry.managed_direct_field) {
                // An index created over old raw rows may have only a partial
                // outcome tuple. Complete snapshot + fenced journal replay is
                // the proof in that case; a complete tuple strengthens it.
                if (try denseTargetCountForIndexContext(self.async_context, cfg.name)) |expected| {
                    if (!denseCoverageMatchesTarget(dense_entry.index.stats().active_count, expected)) return error.RepairSourceCoverageIncomplete;
                }
            }
        }
        // Catch-up persisted every source window through the native WAL before
        // advancing its shadow watermark. Verify that exact boundary while the
        // source writer is fenced, but never perform full compaction here.
        try finalizeShadowNativePostingGeneration(
            &shadow_manager,
            index_ref,
            reached_target,
            false,
            false,
        );
        try checkArtifactRepairCancelled(options);
        try checkArtifactRepairActivationOwner(options);
        try ensureRepairActivationDeadline(activation_deadline_ns);
        if (durable_repair_id) |repair_id| try self.validateIndexRepairActivationState(alloc, repair_id, options.owner_epoch);
        try ensureRepairActivationDeadline(activation_deadline_ns);
        const previous_active_pointer = try self.core.index_manager.captureActiveIndexRootPointer(cfg.name);
        defer if (previous_active_pointer) |value| self.core.index_manager.alloc.free(value);
        try ensureRepairActivationDeadline(activation_deadline_ns);
        if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
            .phase = .activating,
            .candidate_applied_sequence = reached_target,
            .target_sequence = final_target,
            .previous_pointer_captured = true,
            .previous_active_relative_path = previous_active_pointer,
            .replace_previous_active_path = true,
        });
        try ensureRepairActivationDeadline(activation_deadline_ns);

        // Final replay may advance beyond the preliminary ready marker. Make
        // readiness describe the exact durable generation installed by the
        // pointer swap, not merely the pre-barrier candidate.
        if (cfg.kind == .full_text) if (build_source_guard) |guard| if (guard.boundary) |boundary| {
            const text = shadow_manager.textIndexEntry(cfg.name) orelse return error.IndexNotFound;
            try text.persistent.publishProjectionSeal(.{
                .root = self.root_incarnation,
                .namespace = boundary.authority.namespace,
                .generation = cfg.coverage_generation,
                .config_hash = types.indexConfigHash(cfg),
                .applied_sequence = reached_target,
                .baseline = guard,
            });
            try ensureRepairActivationDeadline(activation_deadline_ns);
        };
        try index_generation_manifest.writeReadyForPhysicalFormat(
            alloc,
            shadow_index_path,
            generation_id,
            cfg.name,
            types.indexConfigHash(cfg),
            reached_target,
            try shadowIndexPhysicalFormat(&shadow_manager, index_ref),
        );
        try ensureRepairActivationDeadline(activation_deadline_ns);
        const manifest_sequence = try index_generation_manifest.validateReady(
            alloc,
            shadow_index_path,
            generation_id,
            cfg.name,
            types.indexConfigHash(cfg),
        );
        if (manifest_sequence != reached_target) return error.IndexGenerationManifestMismatch;
        try ensureRepairActivationDeadline(activation_deadline_ns);

        if (cfg.kind == .algebraic) {
            // Certify this physical projection only after the final replay has
            // converged under the apply fence. The marker lives in the shadow
            // namespace, so a crash before pointer publication cannot release
            // the active generation's lifecycle gate.
            try shadow_manager.persistAlgebraicProjectionConfigReady(self.core.store, cfg.name);
            try ensureRepairActivationDeadline(activation_deadline_ns);
        }

        // Transfer the already-open runtime for every index family. Pointer
        // publication and in-memory handoff are allocation-free, and the
        // predecessor is retired only after service fences are released.
        unpublished_replacement = try shadow_manager.detachReplacementIndex(cfg.name);
        retired_generation = try self.core.index_manager.installAdoptedReplacementIndex(
            self.core.store,
            cfg,
            shadow_index_path,
            previous_active_pointer,
            &unpublished_replacement.?,
        );
        unpublished_replacement = null;
        shadow_installed = true;
        if (self.shadow_index_repair_hook) |hook| {
            if (hook.after_pointer_activation) |after_activation| try after_activation(hook.ptr, self, cfg.name);
        }
        if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
            .phase = .validating,
            .candidate_applied_sequence = final_target,
            .target_sequence = final_target,
        });
        index_manager_mod.IndexManager.clearRepairShadowInProgressMarker(alloc, shadow_base) catch |err| {
            std.log.warn("failed to clear repair shadow in-progress marker index={s} err={s}", .{ cfg.name, @errorName(err) });
        };
        const prior_checkpoint = try self.core.loadProjectionCheckpoint(alloc, cfg.name);
        const final_update = apply_state.AppliedSequenceUpdate{
            .index_name = cfg.name,
            .sequence = final_target,
            .status = .clean,
            .generation = prior_checkpoint.generation +| 1,
            .config_hash = types.indexConfigHash(cfg),
        };
        try saveIndexStatusSnapshots(alloc, self.core.store, self.core.index_manager, &[_]apply_state.AppliedSequenceUpdate{final_update});
        try self.core.saveAppliedSequence(cfg.name, final_target);
        try self.core.saveProjectionCheckpoint(cfg.name, .{
            .applied_sequence = final_update.sequence,
            .status = final_update.status,
            .generation = final_update.generation,
            .config_hash = final_update.config_hash,
        });
        // The pointer and clean checkpoint are now ordered before any later
        // foreground apply. Release the write fence before operator hooks,
        // intent cleanup, and generation garbage collection. Capture the
        // actual service pause before releasing it.
        // Generation teardown and other post-commit work are measured
        // separately and cannot produce false pause-budget alarms.
        const activation_pause_ns = monotonicTimeNs() -| activation_started_ns;
        self.core.unlockApply();
        apply_lock_held = false;
        structural_guard.releaseCatalogBarrier();
        if (retired_generation) |*retired| {
            self.core.index_manager.destroyDetachedReplacementIndex(retired);
            retired_generation = null;
        }
        if (shadow_manager_open) {
            shadow_manager.transferLsmOwnerCloneStatsTo(self.core.index_manager) catch |err| {
                std.log.warn("failed to preserve activated shadow LSM clone attribution index={s} err={s}", .{
                    cfg.name,
                    @errorName(err),
                });
            };
            shadow_manager.deinit();
            shadow_manager_open = false;
        }
        structural_guard.release();
        if (worker_reinstall_needed) {
            worker_reinstall_sequence = final_target;
            try self.executor.addWorker(cfg.name, index_ref, worker_reinstall_sequence);
            worker_reinstall_needed = false;
            const current_target = self.core.nextDerivedSequence();
            if (current_target > worker_reinstall_sequence) self.executor.notifyIndexes(current_target, &.{cfg.name});
        }
        if (self.core.index_manager.resource_manager) |manager| {
            manager.recordIndexRepairActivation(activation_pause_ns, max_activation_pause_ns);
        }
        activation_metric_recorded = true;
        if (activation_pause_ns > max_activation_pause_ns) {
            std.log.warn(
                "index repair activation exceeded pause budget index={s} elapsed_ms={} budget_ms={}",
                .{
                    cfg.name,
                    @divTrunc(activation_pause_ns, std.time.ns_per_ms),
                    @divTrunc(max_activation_pause_ns, std.time.ns_per_ms),
                },
            );
        }
        if (self.shadow_index_repair_hook) |hook| {
            if (hook.after_clean_checkpoint) |after_checkpoint| try after_checkpoint(hook.ptr, self, cfg.name);
        }
        if (durable_repair_id) |repair_id| {
            try self.updateIndexRepairIntent(alloc, repair_id, .{
                .phase = .cleanup,
                .candidate_applied_sequence = final_target,
                .target_sequence = final_target,
            });
            // The clean checkpoint and replacement are durable before this
            // single local transition releases replay retention and removes
            // the intent.
            try self.removeIndexRepairIntentAndPin(alloc, repair_id);
            self.scheduleInactiveRepairShadowCleanup();
        }

        return .{
            .reprocessed = reprocessed_this_pass,
            .applied_sequence = final_target,
            .unresolved_artifacts = repair_issue_counter.load(.monotonic),
        };
    }

    const ShadowCatchUpResult = struct {
        applied_sequence: u64,
        yielded: bool = false,
    };

    fn catchUpShadowReplacementUntil(
        self: *DB,
        alloc: Allocator,
        shadow_manager: *index_manager_mod.IndexManager,
        shadow_checkpoint_path: []const u8,
        index_ref: index_manager_mod.ManagedIndexRef,
        target_sequence: u64,
        options: types.ArtifactRepairRunOptions,
        deadline_ns: ?u64,
        observed_ns_per_sequence: u64,
    ) !ShadowCatchUpResult {
        if (target_sequence == 0) return .{ .applied_sequence = 0 };
        // Cooperative yielding is only valid before activation fencing. Final
        // replay has its own hard deadline and must either reach that target or
        // abort activation while the write/search barriers remain held.
        const cooperative = deadline_ns == null and options.yield_check != null;
        var batch_ctx = self.batchContext();
        batch_ctx.index_manager = shadow_manager;
        batch_ctx.applied_sequence_checkpoint_path = shadow_checkpoint_path;
        batch_ctx.async_context = null;
        batch_ctx.dense_bulk_session_scope = .external;

        var applied = try apply_state.loadAppliedSequenceWithCheckpoint(
            alloc,
            shadow_manager.checkpointIo(),
            self.core.store,
            shadow_checkpoint_path,
            index_ref.name,
        );
        while (applied < target_sequence) {
            try checkArtifactRepairCancelled(options);
            if (index_ref.kind == .algebraic) {
                if (options.capacity_check) |check| {
                    try check.current(try shadow_manager.activeIndexStorageBytes(index_ref.name));
                }
            }
            if (deadline_ns) |deadline| {
                if (monotonicTimeNs() >= deadline) return error.RepairActivationBudgetExhausted;
            }
            var replay_ctx = ReplayApplyContextBatch{
                .batch = &batch_ctx,
                .dense_bulk_session_scope = .external,
            };
            const remaining_sequences = target_sequence -| applied;
            var max_records_per_window = if (comptime builtin.is_test)
                test_index_repair_catch_up_max_records_per_window orelse derived_worker.catch_up_max_records_per_window_default
            else
                derived_worker.catch_up_max_records_per_window_default;
            var max_items_per_window: usize = 0;
            if (deadline_ns) |deadline| {
                const now = monotonicTimeNs();
                if (now >= deadline) return error.CatchUpDeadlineExceeded;
                const per_sequence_ns = @max(@as(u64, 1), observed_ns_per_sequence);
                const affordable_sequences = (deadline - now) / per_sequence_ns;
                if (affordable_sequences == 0) return error.CatchUpDeadlineExceeded;
                const bounded_sequences = @min(remaining_sequences, affordable_sequences);
                max_records_per_window = @max(@as(usize, 1), @min(
                    derived_worker.catch_up_max_records_per_window_default,
                    std.math.cast(usize, bounded_sequences) orelse std.math.maxInt(usize),
                ));
                max_items_per_window = max_records_per_window;
            }
            const catch_up_stats = try derived_worker.catchUpIndexWithOptions(
                alloc,
                self.core.replaySource(),
                index_ref,
                applied,
                &replay_ctx,
                applyDerivedBatchToIndexReplayContext,
                .{
                    .resource_manager = shadow_manager.resource_manager,
                    .window_ctx = &replay_ctx,
                    .begin_window_fn = beginDerivedCatchUpWindowContext,
                    .finish_window_fn = finishDerivedCatchUpWindowContext,
                    .target_sequence = target_sequence,
                    .max_records_per_window = max_records_per_window,
                    .max_items_per_window = max_items_per_window,
                    // One independently durable window lets the owner inspect
                    // its cooperative deadline without adding a clock read to
                    // every replay record or changing the ordinary catch-up
                    // path. The outer loop immediately reopens from the saved
                    // applied sequence while budget remains.
                    .max_windows_per_call = if (cooperative) 1 else 0,
                    .deadline_ns = deadline_ns,
                },
            );
            if (index_ref.kind == .algebraic) {
                if (options.capacity_check) |check| {
                    try check.current(try shadow_manager.activeIndexStorageBytes(index_ref.name));
                }
            }
            const advanced = catch_up_stats.appliedSequenceAdvance(applied) orelse blk: {
                if (catch_up_stats.shouldTryTargetAdvance(applied, target_sequence) and
                    try canAdvanceDerivedReplayTargetContext(&batch_ctx, index_ref, applied, target_sequence))
                {
                    break :blk target_sequence;
                }
                break :blk applied;
            };
            if (advanced <= applied) return .{ .applied_sequence = applied };
            try self.saveShadowReplacementAppliedSequence(alloc, shadow_manager, shadow_checkpoint_path, index_ref, advanced);
            applied = advanced;
            if (cooperative and applied < target_sequence and options.yield_check.?.requested()) {
                return .{ .applied_sequence = applied, .yielded = true };
            }
            if (deadline_ns) |deadline| {
                if (applied < target_sequence and monotonicTimeNs() >= deadline) {
                    return error.RepairActivationBudgetExhausted;
                }
            }
        }
        try checkArtifactRepairCancelled(options);
        return .{ .applied_sequence = applied };
    }

    fn observeRepairCatchUpCost(previous_ns_per_sequence: u64, from_sequence: u64, to_sequence: u64, elapsed_ns: u64) u64 {
        const advanced = to_sequence -| from_sequence;
        if (advanced == 0) return previous_ns_per_sequence;
        const observed = @max(@as(u64, 1), (elapsed_ns +| advanced -| 1) / advanced);
        // Retain the slower observed rate. Activation admission should be
        // conservative when foreground pressure makes recent replay slower.
        return @max(previous_ns_per_sequence, observed);
    }

    fn repairActivationReplayDeadline(now_ns: u64, activation_deadline_ns: u64, pause_budget_ns: u64) ?u64 {
        if (now_ns >= activation_deadline_ns) return null;
        // Reserve a bounded tail for manifest validation, pointer publication,
        // and clean-checkpoint durability.  Five milliseconds is sufficient
        // for small budgets; large budgets reserve at most fifty milliseconds
        // so replay still receives the majority of the fence interval.
        const reserve_ns = @max(
            5 * std.time.ns_per_ms,
            @min(50 * std.time.ns_per_ms, pause_budget_ns / 5),
        );
        if (activation_deadline_ns - now_ns <= reserve_ns) return null;
        return activation_deadline_ns - reserve_ns;
    }

    fn repairActivationAdmissible(
        gap_sequences: u64,
        observed_ns_per_sequence: u64,
        max_gap_sequences: u64,
        max_pause_ns: u64,
    ) bool {
        if (gap_sequences == 0) return true;
        if (gap_sequences > max_gap_sequences or observed_ns_per_sequence == 0) return false;
        const estimated_pause_ns = std.math.mul(u64, gap_sequences, observed_ns_per_sequence) catch std.math.maxInt(u64);
        return estimated_pause_ns <= max_pause_ns;
    }

    fn saveShadowReplacementAppliedSequence(
        self: *DB,
        alloc: Allocator,
        shadow_manager: *index_manager_mod.IndexManager,
        shadow_checkpoint_path: []const u8,
        index_ref: index_manager_mod.ManagedIndexRef,
        sequence: u64,
    ) !void {
        try shadow_manager.checkpointLsmWalForManagedIndex(index_ref);
        const update = apply_state.AppliedSequenceUpdate{
            .index_name = index_ref.name,
            .sequence = sequence,
            .config_hash = if (shadow_manager.get(index_ref.name)) |value| types.indexConfigHash(value.*) else 0,
        };
        const updates = [_]apply_state.AppliedSequenceUpdate{update};
        try savePhysicalProjectionMetadataForAppliedSequenceUpdates(shadow_manager, &updates);
        try checkpointManagedProjectionEffectsForAppliedSequenceUpdates(shadow_manager, &updates);
        try apply_state.saveAppliedSequenceUpdateWithCheckpoint(
            alloc,
            shadow_manager.checkpointIo(),
            self.core.store,
            shadow_checkpoint_path,
            update,
        );
    }

    fn finalizeShadowNativePostingGeneration(
        shadow_manager: *index_manager_mod.IndexManager,
        index_ref: index_manager_mod.ManagedIndexRef,
        sequence: u64,
        validate_payloads: bool,
        flatten: bool,
    ) !void {
        if (index_ref.kind != .dense_vector) return;
        _ = try shadow_manager.finalizeNativePostingGenerationAtStableTip(
            index_ref.name,
            sequence,
            .{
                .validate_payloads = validate_payloads,
                .flatten = flatten,
            },
        );
    }

    fn shadowIndexPhysicalFormat(
        shadow_manager: *index_manager_mod.IndexManager,
        index_ref: index_manager_mod.ManagedIndexRef,
    ) !index_generation_manifest.PhysicalFormat {
        if (index_ref.kind != .dense_vector) return .legacy_lsm;
        const entry = shadow_manager.denseIndex(index_ref.name) orelse return error.IndexNotFound;
        return if (entry.index.experimentalPostingWalAuthoritative())
            .dense_native_v2
        else
            .legacy_lsm;
    }

    fn indexGenerationRepairRequired(self: *DB, alloc: Allocator, index_name: []const u8) !bool {
        if (self.core.index_manager.loadFailure(index_name) != null) return true;
        // A durable generation intent is itself authoritative repair debt.
        // Managed catalog admission can intentionally leave the active
        // checkpoint clean while a shadow replacement is pending, so looking
        // only at checkpoint/artifact state would make the ordinary named
        // repair entry point skip work that has already been admitted and is
        // fail-closing service. Healthy indexes still require `force` because
        // they have neither an intent nor any of the conditions below.
        if (try self.indexRepairIdForIndex(alloc, index_name) != null) return true;
        if (try self.core.index_manager.denseNativePhysicalMigrationRequired(index_name)) return true;
        const checkpoint = try self.core.loadProjectionCheckpoint(alloc, index_name);
        switch (checkpoint.status) {
            .degraded, .repair_required => return true,
            .clean, .rebuilding => {},
        }
        if (try self.denseCoverageRegressionRepairRequired(alloc, index_name)) return true;
        // Source artifacts have their own durable repair queue. Treating that
        // queue as generation debt recursively starts another shadow rebuild
        // after a repaired generation activates but before its source artifact
        // is regenerated. Managed catch-up repairs source debt, advances replay,
        // and rebuilds a generation only when one of the structural predicates
        // above still requires it.
        return false;
    }

    const CommittedCoverageDisposition = enum {
        complete,
        degraded,
        indeterminate,
    };

    const IndexDerivedCoverageOwnership = union(enum) {
        external,
        managed: types.DerivedCoveragePolicy,
    };

    fn indexDerivedCoverageOwnership(alloc: Allocator, cfg: types.IndexConfig) ?IndexDerivedCoverageOwnership {
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, cfg.config_json, .{}) catch return null;
        defer parsed.deinit();
        if (parsed.value != .object) return null;
        if (parsed.value.object.get("external")) |external| {
            if (external != .bool) return null;
            if (external.bool) return .external;
        }
        const configured = parsed.value.object.get("coverage_policy") orelse return .{ .managed = .strict };
        if (configured != .string) return null;
        if (std.mem.eql(u8, configured.string, "strict")) return .{ .managed = .strict };
        if (std.mem.eql(u8, configured.string, "partial")) return .{ .managed = .partial };
        if (std.mem.eql(u8, configured.string, "best_effort")) return .{ .managed = .best_effort };
        return null;
    }

    fn committedIndexCoverageDisposition(self: *DB, alloc: Allocator, index_name: []const u8) !CommittedCoverageDisposition {
        const cfg = self.core.index_manager.get(index_name) orelse return .indeterminate;
        if (cfg.kind != .dense_vector and cfg.kind != .sparse_vector) return .complete;
        const managed_direct_field = switch (cfg.kind) {
            .dense_vector => self.core.index_manager.denseIndexUsesManagedDirectField(index_name),
            .sparse_vector => self.core.index_manager.sparseIndexUsesManagedDirectField(index_name),
            else => unreachable,
        };
        // Direct-field initial builds can predate outcome counters. Their
        // complete primary-driven snapshot (including stripped artifact
        // fallback) and fenced replay prove generation health; partial later
        // outcome tuples alone are not an authoritative whole-index count.
        if (managed_direct_field) return .complete;
        const ownership = indexDerivedCoverageOwnership(alloc, cfg.*) orelse return .indeterminate;
        const policy = switch (ownership) {
            .external => return .complete,
            .managed => |value| value,
        };
        const generation = self.core.index_manager.coverageGenerationForIndex(index_name) orelse return .indeterminate;
        const coverage_counts = try loadDerivedCoverageCounters(alloc, self.core.store, index_name, generation, self.core.index_manager.byte_range, null);
        const produced = coverage_counts.produced;
        const skipped = coverage_counts.skipped;
        const terminal_failed = coverage_counts.terminal_failed;

        const source_total = coverage_counts.source_total.?;
        const applied_sequence = try self.managedIndexAppliedSequence(alloc, index_name);
        const target_sequence = try self.projectionStatsTargetSequence(alloc, cfg.*, applied_sequence);
        const replay_current = applied_sequence >= target_sequence;
        if (produced == null or skipped == null or terminal_failed == null) {
            // An empty source can legitimately predate creation of the compact
            // counter tuple. Any non-empty or still-replaying source remains
            // unknown and must not be reported repaired.
            return if (source_total == 0 and replay_current) .complete else .indeterminate;
        }
        const assessment = types.evaluateDerivedCoverageAssessment(
            policy,
            source_total,
            produced.?,
            skipped.?,
            terminal_failed.?,
            true,
            replay_current,
        );
        if (!assessment.health.counters_valid or !assessment.complete) {
            return if (assessment.degraded) .degraded else .indeterminate;
        }
        return if (assessment.degraded) .degraded else .complete;
    }

    /// Classify a generation after its replacement is durably committed.
    /// Both the initial response and crash-idempotent job replay enter here so
    /// a completion marker can never be mistaken for proof of healthy coverage.
    fn finalizeCommittedIndexRepairOutcome(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        observed_unresolved_artifacts: u64,
        result: *types.ArtifactRepairResult,
    ) !void {
        const repair_summary_ready = try self.artifactRepairSummaryReady(alloc);
        const unresolved_artifacts = if (repair_summary_ready)
            @max(
                observed_unresolved_artifacts,
                (try self.artifactRepairSummaryIndexSnapshot(alloc, index_name, true)).count,
            )
        else
            observed_unresolved_artifacts;
        result.unresolved += unresolved_artifacts;

        // A rebuilding summary cannot prove absence. Preserve debt without a
        // corpus scan on this latency-sensitive completion path; background
        // summary maintenance will publish the exact count.
        result.debt_remaining = result.debt_remaining or !repair_summary_ready or unresolved_artifacts != 0;

        const generation_repair_required = try self.indexGenerationRepairRequired(alloc, index_name);
        const coverage = try self.committedIndexCoverageDisposition(alloc, index_name);
        if (generation_repair_required or coverage != .complete) {
            result.unresolved += 1;
            result.debt_remaining = true;
            result.indexes_degraded_after = 1;
        }

        // "Rebuilt" describes completed work. "Repaired" is the stronger
        // operator promise that no known or indeterminate debt remains.
        result.indexes_degraded_after = @intFromBool(result.debt_remaining);
        if (!result.debt_remaining) {
            result.repaired += 1;
        }
    }

    fn denseCoverageRegressionRepairRequired(self: *DB, alloc: Allocator, index_name: []const u8) !bool {
        const entry = self.core.index_manager.denseIndex(index_name) orelse return false;
        if (!denseIndexIsArtifactBacked(entry)) return false;
        const expected = (try loadDenseArtifactTargetCounter(alloc, self.core.store, index_name)) orelse
            return true;
        if (denseCoverageMatchesTarget(entry.index.stats().active_count, expected)) return false;

        // Source counters advance atomically with primary writes, before the
        // asynchronous projection applies the corresponding replay sequence.
        // A cardinality difference is repair debt only after replay converges;
        // otherwise every healthy asynchronous write would be misclassified.
        const checkpoint = try self.core.loadProjectionCheckpoint(alloc, index_name);
        if (checkpoint.status == .rebuilding) return false;
        const target_sequence = try self.probeDerivedReplayTargetSequence(
            alloc,
            self.core.replaySource(),
            .{ .name = index_name, .kind = .dense_vector },
            checkpoint.applied_sequence,
        );
        return checkpoint.applied_sequence >= target_sequence;
    }

    pub fn repairArtifactIssues(
        self: *DB,
        alloc: Allocator,
        artifact_kind: ?types.ArtifactRepairKind,
        limit: usize,
    ) !types.ArtifactRepairResult {
        return try self.repairArtifactIssuesWithRequest(alloc, .{
            .artifact_kind = artifact_kind,
            .limit = @intCast(@min(limit, std.math.maxInt(u32))),
        });
    }

    pub fn repairEmbeddingArtifactIssues(self: *DB, alloc: Allocator, limit: usize) !types.EmbeddingArtifactRepairResult {
        return try self.repairArtifactIssues(alloc, .embedding, limit);
    }

    pub fn reprocessDocumentArtifactRange(
        self: *DB,
        alloc: Allocator,
        artifact_name: []const u8,
        req: types.DocumentArtifactTableReprocessRequest,
    ) !types.DocumentArtifactTableReprocessResult {
        var cfg = (try self.getEnrichment(alloc, .asset, artifact_name)) orelse return error.NotFound;
        defer cfg.deinit(alloc);

        var effective_req = req;
        if (req.shard_cursors.len > 0) {
            if (req.shard_cursors.len != 1) return error.InvalidArgument;
            const cursor = req.shard_cursors[0];
            if (cursor.group_id != null) return error.InvalidArgument;
            effective_req = .{
                .from_key = cursor.next_key,
                .to_key = req.to_key,
                .limit = if (cursor.limit != 0) cursor.limit else req.limit,
            };
        }

        const limit = if (effective_req.limit == 0) @as(u32, 100) else effective_req.limit;
        const scan_limit = if (limit == std.math.maxInt(u32)) limit else limit + 1;
        var scanned = try self.scan(alloc, effective_req.from_key, effective_req.to_key, .{
            .include_documents = true,
            .limit = scan_limit,
        });
        defer scanned.deinit(alloc);

        var failures = std.ArrayListUnmanaged(types.DocumentArtifactReprocessFailure).empty;
        errdefer {
            for (failures.items) |*failure| failure.deinit(alloc);
            failures.deinit(alloc);
        }

        var result = types.DocumentArtifactTableReprocessResult{
            .limit = limit,
        };
        errdefer result.deinit(alloc);

        const process_len = @min(scanned.documents.len, @as(usize, @intCast(limit)));
        for (scanned.documents[0..process_len]) |doc| {
            result.scanned += 1;
            const handled = self.reprocessDocumentArtifact(alloc, doc.id, artifact_name) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => {
                    result.failed += 1;
                    try failures.append(alloc, .{
                        .key = try alloc.dupe(u8, doc.id),
                        .error_code = try alloc.dupe(u8, @errorName(err)),
                    });
                    continue;
                },
            };
            if (handled) {
                result.reprocessed += 1;
            } else {
                result.skipped += 1;
            }
        }

        if (scanned.documents.len > process_len and process_len > 0) {
            result.next_key = try alloc.dupe(u8, scanned.documents[process_len - 1].id);
        }
        result.failures = try failures.toOwnedSlice(alloc);
        return result;
    }

    pub fn getDocument(self: *DB, alloc: Allocator, key: []const u8, opts: types.LookupOptions) !?types.LookupResult {
        return try self.lookup(alloc, key, opts);
    }

    fn lookupRelationalIntegrityCatalog(self: *DB, alloc: Allocator) !?types.LookupResult {
        const catalog_mod = @import("relational_integrity_catalog.zig");
        self.core.lockApplyShared();
        defer self.core.unlockApplyShared();
        var pinned = self.core.acquireSchemaView() orelse return error.InvalidRelationalRowsRequest;
        defer pinned.release();
        if (pinned.storageMode() != .relational) return error.InvalidRelationalRowsRequest;
        const bytes = (try self.core.getStoreValue(alloc, catalog_mod.key)) orelse return null;
        defer alloc.free(bytes);
        var catalog = try catalog_mod.decode(alloc, bytes);
        defer catalog.deinit();
        if (catalog.schema_version != pinned.version()) return error.IntegrityCatalogChanged;
        const incarnation = try catalog_mod.incarnationFromTableId(self.core.identity_namespace.table_id);
        if (!std.mem.eql(u8, &incarnation, &catalog.incarnation)) return error.IntegrityCatalogIncarnationMismatch;
        const layout = try schema_mod.serializeSchema(alloc, pinned.tableSchema().*);
        defer alloc.free(layout);
        var digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(layout, &digest, .{});
        if (!std.mem.eql(u8, &digest, &catalog.schema_digest)) return error.IntegrityCatalogChanged;
        const encoded = try alloc.alloc(u8, std.base64.standard.Encoder.calcSize(bytes.len));
        defer alloc.free(encoded);
        _ = std.base64.standard.Encoder.encode(encoded, bytes);
        return .{ .json = try std.fmt.allocPrint(alloc, "{{\"catalog\":{f},\"schema_version\":{d},\"table_id\":\"{d}\"}}", .{
            std.json.fmt(encoded, .{}), pinned.version(), self.core.identity_namespace.table_id,
        }) };
    }

    fn lookupRelationalIndexStatus(self: *DB, alloc: Allocator, bytes: []const u8, opts: types.LookupOptions) !?types.LookupResult {
        const contract = @import("relational_index_status_contract.zig");
        if (bytes.len > 4096) return error.InvalidArgument;
        var request = try std.json.parseFromSlice(contract.Request, alloc, bytes, .{});
        defer request.deinit();
        if (request.value.name) |name| if (name.len == 0 or name.len > 1024) return error.InvalidArgument;
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const temporary = arena.allocator();
        var statuses: std.ArrayList(contract.NamedStatus) = .empty;
        // Capture one owner snapshot, then release the apply lock and storage
        // snapshot before JSON encoding/network delivery. All escaped slices
        // below are request-owned, not borrowed from a retired schema plan.
        {
            try self.lockApplySharedForPortableRuntime();
            defer self.core.unlockApplyShared();
            var view = self.core.acquireSchemaView() orelse return error.RelationalTableRequired;
            defer view.release();
            if (view.storageMode() != .relational) return error.RelationalTableRequired;
            if (view.version() != request.value.schema_version) return error.PreparedGenerationChanged;
            var pinned = self.core.relational_indexes.acquire() orelse return error.IndexNotFound;
            defer pinned.deinit();
            if (pinned.plan.schemaView().epoch != view.epoch) return error.PreparedGenerationChanged;
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            const range = self.core.byteRange();
            var admitted_bytes: usize = 0;
            for (pinned.plan.boundIndexes()) |index| {
                if (request.value.name) |name| if (!std.mem.eql(u8, index.name, name)) continue;
                // JSON's worst case is six bytes per input byte. Admit before
                // materializing status arrays or encoding escaped range keys.
                admitted_bytes +|= 2048 +| (6 *| (index.name.len +| range.start.len +| range.end.len));
                if (admitted_bytes > contract.max_response_bytes) return error.ResourceBudgetExceeded;
            }
            const range_start = try temporary.dupe(u8, range.start);
            const range_end = try temporary.dupe(u8, range.end);
            const ownership = try relational_index_jobs.ownership(&read);
            for (pinned.plan.boundIndexes()) |index| {
                try checkLookupOptionsActive(opts);
                if (request.value.name) |name| if (!std.mem.eql(u8, index.name, name)) continue;
                const proof = try relational_index_jobs.statusProofWithOwnership(&read, index, ownership);
                const progress = proof.progress;
                const value = contract.Status{
                    .table_id = self.core.identity_namespace.table_id,
                    .schema_version = view.version(),
                    .generation = index.generation,
                    .slot = index.slot,
                    .catalog = pinned.head.blob_digest,
                    .comparison = progress.comparison,
                    .owner = progress.owner,
                    .range_start = range_start,
                    .range_end = range_end,
                    .state = switch (progress.state) {
                        .building => .building,
                        .ready => .ready,
                        .failed => .failed,
                    },
                    .rows_scanned = progress.rows_scanned,
                    .progress_digest = proof.digest,
                    .maintenance_epoch = proof.maintenance_epoch,
                    .last_maintenance_request = proof.last_maintenance_request,
                    .failure = switch (progress.failure) {
                        .none => .none,
                        .incompatible_schema => .incompatible_schema,
                        .invalid_row => .invalid_row,
                        .key_too_large => .key_too_large,
                    },
                };
                try statuses.append(temporary, .{ .name = try temporary.dupe(u8, index.name), .status = value });
            }
        }
        if (request.value.name != null and statuses.items.len == 0) return error.IndexNotFound;
        try checkLookupOptionsActive(opts);
        const json = if (request.value.name != null)
            try std.json.Stringify.valueAlloc(alloc, statuses.items[0].status, .{})
        else
            try std.json.Stringify.valueAlloc(alloc, contract.Batch{ .statuses = statuses.items }, .{});
        errdefer alloc.free(json);
        if (json.len > contract.max_response_bytes) return error.ResourceBudgetExceeded;
        try checkLookupOptionsActive(opts);
        return .{ .json = json };
    }

    fn lookupRelationalIntegrityAction(self: *DB, alloc: Allocator, routing: []const u8) !?types.LookupResult {
        const integrity = @import("relational_integrity.zig");
        if (routing.len != 32) return error.InvalidIntegrityAddress;
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        var read = try integrity.CurrentView.init(self.core.store);
        defer read.deinit();
        try @import("online_integrity_shadow.zig").requireServing(&read, self.core.byteRange(), routing);
        var prefix: [integrity.namespace.len + 1 + 32]u8 = undefined;
        @memcpy(prefix[0..integrity.namespace.len], integrity.namespace);
        prefix[integrity.namespace.len] = @backingInt(integrity.Kind.job);
        @memcpy(prefix[integrity.namespace.len + 1 ..], routing);
        var cursor = try read.openCursor();
        defer cursor.close();
        const first = (try cursor.seekAtOrAfter(&prefix)) orelse return null;
        if (!std.mem.startsWith(u8, first.key, &prefix)) return null;
        const address = (try integrity.parseKey(first.key)).address;
        const action_id = (try integrity.Job.decode(first.key, first.value)).action_id;
        if (try cursor.next()) |next| if (std.mem.startsWith(u8, next.key, &prefix)) return error.IntegrityAddressMismatch;
        var page = try integrity.actionPageWithBudget(alloc, self.backend_runtime.io(), &read, address, action_id, .{ .rows = 128 });
        defer page.deinit();
        const Response = struct {
            address: integrity.Address,
            page: *const integrity.ActionPage,

            pub fn jsonStringify(response: @This(), stream: anytype) @TypeOf(stream.*).Error!void {
                try @import("relational_integrity_json.zig").write(.{
                    .address = response.address,
                    .claim = response.page.claim,
                    .job = response.page.job,
                    .references = response.page.references,
                    .complete = response.page.complete,
                    .next_cursor = response.page.next_cursor,
                }, stream);
            }
        };
        return .{ .json = try std.json.Stringify.valueAlloc(alloc, Response{ .address = address, .page = &page }, .{}) };
    }

    fn lookupRelationalIntegrityJobs(self: *DB, alloc: Allocator, request_json: []const u8, options: types.LookupOptions) !?types.LookupResult {
        const integrity = @import("relational_integrity.zig");
        if (request_json.len > 4096) return error.InvalidIntegrityBudget;
        var kind = try std.json.parseFromSlice(struct { kind: []const u8 = "discover" }, alloc, request_json, .{ .ignore_unknown_fields = true });
        defer kind.deinit();
        if (std.mem.eql(u8, kind.value.kind, "retirement")) return self.lookupRelationalRetirement(alloc, request_json);
        var request = try std.json.parseFromSlice(struct {
            kind: enum { discover, references, claims, observations } = .discover,
            addresses: []const integrity.Address = &.{},
            keys: []const []const u8 = &.{},
            schema_version: ?u32 = null,
            generation_set: ?integrity.Digest = null,
            address: ?integrity.Address = null,
            after: ?[]const u8 = null,
            limit: u32 = 16,
        }, alloc, request_json, .{ .allocate = .alloc_always });
        defer request.deinit();
        if (request.value.limit == 0 or request.value.limit > 128) return error.InvalidIntegrityBudget;
        if (request.value.kind == .observations) return self.lookupPreparationObservations(alloc, request.value.keys, options, request.value.schema_version, request.value.generation_set);
        if (request.value.kind == .claims) return self.lookupRelationalIntegrityClaims(alloc, request.value.addresses, request.value.schema_version, request.value.generation_set);
        if (request.value.kind == .references) return self.lookupRelationalIntegrityReferences(alloc, request.value.address orelse return error.InvalidIntegrityAddress, request.value.after, request.value.limit, request.value.schema_version, request.value.generation_set);
        if (request.value.address != null) return error.InvalidIntegrityAddress;
        var scratch = std.heap.ArenaAllocator.init(alloc);
        defer scratch.deinit();
        const owned = scratch.allocator();
        const after = if (request.value.after) |encoded| after: {
            const decoded = try owned.alloc(u8, try std.base64.standard.Decoder.calcSizeForSlice(encoded));
            try std.base64.standard.Decoder.decode(decoded, encoded);
            if ((try integrity.parseKey(decoded)).kind != .job) return error.InvalidIntegrityKey;
            break :after decoded;
        } else null;
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        var read = try integrity.CurrentView.init(self.core.store);
        defer read.deinit();
        const range = try @import("online_integrity_shadow.zig").servingRange(&read, self.core.byteRange());
        const prefix = integrity.namespace ++ &[_]u8{@backingInt(integrity.Kind.job)};
        const lower = try std.mem.concat(owned, u8, &.{ prefix, range.start });
        const start = if (after) |key| if (std.mem.order(u8, key, lower) == .gt) key else lower else lower;
        var cursor = try read.openCursor();
        defer cursor.close();
        var entry = try cursor.seekAtOrAfter(start);
        if (entry) |item| if (after) |key| if (std.mem.eql(u8, item.key, key)) {
            entry = try cursor.next();
        };
        const Item = struct { address: integrity.Address, action_id: integrity.Generation };
        var jobs: std.ArrayList(Item) = .empty;
        var last_key: ?[]const u8 = null;
        const started = platform_time.monotonicNs();
        var more = false;
        while (entry) |item| : (entry = try cursor.next()) {
            if (!std.mem.startsWith(u8, item.key, prefix)) break;
            const parsed = try integrity.parseKey(item.key);
            if (!range.contains(&parsed.address.routing)) break;
            if (jobs.items.len >= request.value.limit or (jobs.items.len != 0 and platform_time.monotonicNs() -| started >= 5 * std.time.ns_per_ms)) {
                more = true;
                break;
            }
            if (self.backend_runtime.io()) |io| try io.checkCancel();
            const job = try integrity.Job.decode(item.key, item.value);
            try jobs.append(owned, .{ .address = parsed.address, .action_id = job.action_id });
            last_key = try owned.dupe(u8, item.key);
        }
        const next: ?[]const u8 = if (more) next: {
            const raw = last_key orelse return error.InvalidIntegrityBudget;
            const encoded = try owned.alloc(u8, std.base64.standard.Encoder.calcSize(raw.len));
            break :next std.base64.standard.Encoder.encode(encoded, raw);
        } else null;
        const Response = struct {
            jobs: []const Item,
            next: ?[]const u8,

            pub fn jsonStringify(response: @This(), stream: anytype) @TypeOf(stream.*).Error!void {
                try stream.beginObject();
                try stream.objectField("jobs");
                try @import("relational_integrity_json.zig").write(response.jobs, stream);
                try stream.objectField("next");
                try stream.write(response.next);
                try stream.endObject();
            }
        };
        return .{ .json = try std.json.Stringify.valueAlloc(alloc, Response{ .jobs = jobs.items, .next = next }, .{}) };
    }

    /// A single routed ReadIndex gate covers this bounded owner-local read.
    /// All addresses must belong to this physical range; topology changes fail
    /// closed rather than silently routing part of the batch elsewhere.
    fn validateIntegrityReadGeneration(alloc: Allocator, read: *@import("relational_integrity.zig").CurrentView, expected_schema: ?u32, expected_set: ?@import("relational_integrity.zig").Digest) !void {
        if (expected_schema == null and expected_set == null) return;
        const schema_version = expected_schema orelse return error.InvalidIntegrityAddress;
        const generation_set = expected_set orelse return error.InvalidIntegrityAddress;
        const catalog = @import("relational_integrity_catalog.zig");
        const encoded = read.get(catalog.key) catch |err| switch (err) {
            error.NotFound => return error.PreparedGenerationChanged,
            else => return err,
        };
        var bindings = try catalog.decode(alloc, encoded);
        defer bindings.deinit();
        if (bindings.schema_version != schema_version or !std.mem.eql(u8, &generation_set, &@import("relational_integrity_activation_contract.zig").generationSet(bindings))) return error.PreparedGenerationChanged;
    }

    fn lookupPreparationObservations(self: *DB, alloc: Allocator, keys: []const []const u8, outer: types.LookupOptions, expected_schema: ?u32, expected_set: ?@import("relational_integrity.zig").Digest) !?types.LookupResult {
        if (expected_schema == null or expected_set == null) return error.InvalidIntegrityAddress;
        if (keys.len == 0 or keys.len > 8) return error.InvalidIntegrityBudget;
        const Item = struct { key: []const u8, row: ?types.LookupResult };
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const scratch = arena.allocator();
        const items = try scratch.alloc(Item, keys.len);
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        var probe = try self.core.store.beginReadTxn();
        defer probe.abort();
        var serving = try @import("relational_integrity.zig").CurrentView.init(self.core.store);
        defer serving.deinit();
        try validateIntegrityReadGeneration(scratch, &serving, expected_schema, expected_set);
        var retained: usize = 0;
        for (keys, items) |key, *item| {
            try checkLookupOptionsActive(outer);
            if (key.len == 0 or key.len > 512 or internal_keys.isInternalUserKey(key)) return error.InvalidIntegrityAddress;
            if (!self.core.byteRange().contains(key)) return error.PreparedGenerationChanged;
            try @import("online_integrity_shadow.zig").requireServing(&serving, self.core.byteRange(), key);
            var options = outer;
            options.relational_integrity_jobs_json = "";
            options.include_primary_digest = true;
            const row = try self.lookupPrimarySnapshot(scratch, key, options, &probe);
            if (row) |value| {
                retained = std.math.add(usize, retained, value.json.len) catch return error.TransactionTooLarge;
                if (retained > 16 * 1024 * 1024) return error.TransactionTooLarge;
            }
            item.* = .{ .key = key, .row = row };
        }
        const Response = struct {
            observations: []const Item,
            pub fn jsonStringify(value: @This(), stream: anytype) @TypeOf(stream.*).Error!void {
                try stream.beginObject();
                try stream.objectField("observations");
                try stream.beginArray();
                for (value.observations) |item| {
                    try stream.beginObject();
                    try stream.objectField("key");
                    try @import("relational_integrity_json.zig").write(item.key, stream);
                    try stream.objectField("row");
                    // Primary JSON remains an encoded document string. Binary
                    // digests are fixed arrays and cannot lose byte identity.
                    try stream.write(item.row);
                    try stream.endObject();
                }
                try stream.endArray();
                try stream.endObject();
            }
        };
        const json = try std.json.Stringify.valueAlloc(alloc, Response{ .observations = items }, .{});
        errdefer alloc.free(json);
        if (json.len > 16 * 1024 * 1024) return error.TransactionTooLarge;
        try checkLookupOptionsActive(outer);
        return .{ .json = json };
    }

    fn lookupRelationalIntegrityClaims(self: *DB, alloc: Allocator, addresses: []const @import("relational_integrity.zig").Address, expected_schema: ?u32, expected_set: ?@import("relational_integrity.zig").Digest) !?types.LookupResult {
        const integrity = @import("relational_integrity.zig");
        if (expected_schema == null or expected_set == null) return error.InvalidIntegrityAddress;
        if (addresses.len == 0 or addresses.len > 8) return error.InvalidIntegrityBudget;
        const Item = struct { address: integrity.Address, claim: ?integrity.Claim };
        var scratch = std.heap.ArenaAllocator.init(alloc);
        defer scratch.deinit();
        const owned = scratch.allocator();
        const items = try owned.alloc(Item, addresses.len);
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        var read = try integrity.CurrentView.init(self.core.store);
        defer read.deinit();
        try validateIntegrityReadGeneration(owned, &read, expected_schema, expected_set);
        for (addresses, items) |address, *item| {
            if (self.backend_runtime.io()) |io| try io.checkCancel();
            _ = try integrity.parseKey(&address.claimKey());
            if (!self.core.byteRange().contains(&address.routing)) return error.PreparedGenerationChanged;
            try @import("online_integrity_shadow.zig").requireServing(&read, self.core.byteRange(), &address.routing);
            const raw = read.get(&address.claimKey()) catch |err| switch (err) {
                error.NotFound => {
                    item.* = .{ .address = address, .claim = null };
                    continue;
                },
                else => return err,
            };
            const claim = try integrity.Claim.decode(&address.claimKey(), raw);
            if (claim.state != .live) return error.ForeignKeyActionInProgress;
            item.* = .{ .address = address, .claim = claim };
        }
        const Response = struct {
            claims: []const Item,
            pub fn jsonStringify(value: @This(), stream: anytype) @TypeOf(stream.*).Error!void {
                try stream.beginObject();
                try stream.objectField("claims");
                try @import("relational_integrity_json.zig").write(value.claims, stream);
                try stream.endObject();
            }
        };
        return .{ .json = try std.json.Stringify.valueAlloc(alloc, Response{ .claims = items }, .{}) };
    }

    fn lookupRelationalIntegrityReferences(self: *DB, alloc: Allocator, address: @import("relational_integrity.zig").Address, after: ?[]const u8, limit: u32, expected_schema: ?u32, expected_set: ?@import("relational_integrity.zig").Digest) !?types.LookupResult {
        const integrity = @import("relational_integrity.zig");
        const prefix = address.referencePrefix();
        _ = try integrity.parseKey(&address.claimKey());
        var scratch = std.heap.ArenaAllocator.init(alloc);
        defer scratch.deinit();
        const owned = scratch.allocator();
        const decoded_after = if (after) |encoded| decoded: {
            const raw = try owned.alloc(u8, try std.base64.standard.Decoder.calcSizeForSlice(encoded));
            try std.base64.standard.Decoder.decode(raw, encoded);
            if ((try integrity.parseKey(raw)).kind != .reference or !std.mem.startsWith(u8, raw, &prefix)) return error.InvalidIntegrityKey;
            break :decoded raw;
        } else null;
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        var read = try integrity.CurrentView.init(self.core.store);
        defer read.deinit();
        try validateIntegrityReadGeneration(owned, &read, expected_schema, expected_set);
        try @import("online_integrity_shadow.zig").requireServing(&read, self.core.byteRange(), &address.routing);
        const raw_claim = read.get(&address.claimKey()) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        const claim = try integrity.Claim.decode(&address.claimKey(), raw_claim);
        if (claim.state != .live) return error.ForeignKeyActionInProgress;
        var cursor = try read.openCursor();
        defer cursor.close();
        var entry = try cursor.seekAtOrAfter(decoded_after orelse &prefix);
        if (entry) |item| if (decoded_after) |key| if (std.mem.eql(u8, key, item.key)) {
            entry = try cursor.next();
        };
        var references: std.ArrayList(integrity.Reference) = .empty;
        var last_key: ?[]const u8 = null;
        var more = false;
        var bytes: usize = 0;
        var scanned: usize = 0;
        const started = platform_time.monotonicNs();
        while (entry) |item| : (entry = try cursor.next()) {
            if (!std.mem.startsWith(u8, item.key, &prefix)) break;
            // Retired generations remain on disk until bounded GC, but they
            // are no longer dependencies of the parent. Budget physical rows
            // and advance the cursor even when a page contains only tombstoned
            // references, or an old generation could make this read unbounded.
            if (scanned >= limit or (scanned != 0 and platform_time.monotonicNs() -| started >= 5 * std.time.ns_per_ms) or item.value.len > 1024 * 1024 - bytes) {
                if (scanned == 0) return error.IntegrityRecordTooLarge;
                more = true;
                break;
            }
            if (self.backend_runtime.io()) |io| try io.checkCancel();
            const reference = try integrity.Reference.decode(item.key, item.value);
            if (!try @import("relational_integrity_generation_retirement.zig").isRetired(&read, reference)) {
                const copy = try owned.dupe(u8, item.value);
                try references.append(owned, try integrity.Reference.decode(item.key, copy));
            }
            last_key = try owned.dupe(u8, item.key);
            scanned += 1;
            bytes += item.value.len;
        }
        const next: ?[]const u8 = if (more) next: {
            const raw = last_key orelse return error.InvalidIntegrityBudget;
            const encoded = try owned.alloc(u8, std.base64.standard.Encoder.calcSize(raw.len));
            break :next std.base64.standard.Encoder.encode(encoded, raw);
        } else null;
        const Response = struct {
            address: integrity.Address,
            claim: integrity.Claim,
            references: []const integrity.Reference,
            next: ?[]const u8,

            pub fn jsonStringify(response: @This(), stream: anytype) @TypeOf(stream.*).Error!void {
                try stream.beginObject();
                try stream.objectField("address");
                try @import("relational_integrity_json.zig").write(response.address, stream);
                try stream.objectField("claim");
                try @import("relational_integrity_json.zig").write(response.claim, stream);
                try stream.objectField("references");
                try @import("relational_integrity_json.zig").write(response.references, stream);
                try stream.objectField("next");
                try stream.write(response.next);
                try stream.endObject();
            }
        };
        return .{ .json = try std.json.Stringify.valueAlloc(alloc, Response{ .address = address, .claim = claim, .references = references.items, .next = next }, .{}) };
    }

    fn verifyRowPolicyPrincipal(self: *DB, alloc: Allocator, token: []const u8, database: []const u8, access: row_policy_authority_mod.Access, now_seconds: i64) !std.json.Parsed(row_policy_authority_mod.Payload) {
        if (token.len == 0 or token.len > row_policy_authority_mod.maximum_token_bytes or database.len == 0)
            return error.RowPolicyAuthenticationRequired;
        return row_policy_authority_mod.verify(alloc, self.local_execution.row_policy_authority_secret orelse return error.RowPolicyAuthorityUnavailable, self.local_execution.row_policy_authority_issuer orelse return error.RowPolicyAuthorityUnavailable, .{
            .table_id = self.core.identity_namespace.table_id,
            .table = self.local_execution.row_policy_table_name orelse return error.RowPolicyAuthorityUnavailable,
            .database = database,
            .policy_generation = self.local_execution.row_policy_gate.generation.load(.acquire),
            .catalog_epoch = self.local_execution.row_policy_gate.catalog_epoch.load(.acquire),
            .access = access,
        }, now_seconds, token);
    }

    /// Called under the serialized apply lock, after transform coalescing and
    /// optimistic schema validation but before any primary/index side effect.
    /// A single read snapshot observes the old image for each affected key;
    /// new images reuse the already prepared AROW bytes. Both sides are
    /// evaluated on typed ordinals, not reconstructed JSON projections.
    pub const enforceRowPolicyMutationLocked = local_mutation.enforceRowPolicyMutationLocked;

    fn enforceRowPolicyIntentsLocked(self: *DB, schema_view: schema_registry_mod.SchemaView, intents: []const transactions_mod.WriteIntent, principal: *const row_policy_authority_mod.Payload) !void {
        if (principal.access != .write) return error.RowPolicyAuthenticationRequired;
        const bundle = if (self.local_execution.row_policy_bundle) |*installed| installed else return error.RowPolicyCatalogChanged;
        const schema = schema_view.tableSchema().*;
        var insert_check = try bundle.captureEvaluation(self.alloc, schema, principal, .insert);
        defer insert_check.deinit();
        var update_old = try bundle.captureEvaluation(self.alloc, schema, principal, .update_old);
        defer update_old.deinit();
        var update_new = try bundle.captureEvaluation(self.alloc, schema, principal, .update_new);
        defer update_new.deinit();
        var delete_old = try bundle.captureEvaluation(self.alloc, schema, principal, .delete);
        defer delete_old.deinit();
        var probe = try self.core.store.beginProbeTxn();
        defer probe.abort();
        for (intents) |intent| {
            if (isMetadataKey(intent.key)) return error.RowPolicyMutationUnsupported;
            const store_key = try encodeStoreLookupKeyAlloc(self, self.alloc, intent.key);
            defer self.alloc.free(store_key);
            const old_bytes: ?[]const u8 = probe.getLeased(store_key) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            if (old_bytes) |bytes| {
                if (try relational_store.rowSchemaVersion(bytes) != schema.version) return error.RowPolicyCatalogChanged;
                const old = if (self.core.store.valuesAreAuthenticated())
                    try relational_row_codec.ordinalRowViewTrusted(bytes, schema, schema_view.physicalLayout())
                else
                    try relational_row_codec.ordinalRowViewSelective(bytes, schema, schema_view.physicalLayout());
                if (!try (if (intent.value == null) delete_old else update_old).permits(old)) return error.RowPolicyDenied;
            }
            if (intent.value != null) {
                const encoded = intent.prepared_row orelse return error.RowPolicyMutationUnsupported;
                const new = try relational_row_codec.ordinalRowViewTrusted(encoded, schema, schema_view.physicalLayout());
                if (!try (if (old_bytes == null) insert_check else update_new).permits(new)) return error.RowPolicyDenied;
            }
        }
    }

    pub fn lookup(self: *DB, alloc: Allocator, key: []const u8, opts: types.LookupOptions) !?types.LookupResult {
        try checkLookupOptionsActive(opts);
        if (std.mem.eql(u8, opts.relational_topology_json, "{\"mode\":\"generation_handoff_identity\"}") and
            (key.len != 0 or opts.include_primary_digest or opts.relational_integrity_catalog or opts.relational_integrity_action or
                opts.relational_integrity_jobs_json.len != 0 or opts.relational_index_status_json.len != 0 or
                opts.relational_activation_json.len != 0 or opts.fields.len != 0 or opts.generation_handoff_install_read_index_certified)) return error.RestoreStagingScopeChanged;
        if (opts.row_policy_receipt) |request| {
            // Only the provisioned cluster owner may answer coordinator
            // receipt probes. Lite has no trusted policy authority and public
            // lookup parsers never populate this private option.
            if (self.local_execution.row_policy_authority_secret == null or key.len != 0 or
                opts.row_policy_principal_proof.len != 0 or opts.row_policy_database.len != 0)
                return error.RowPolicyAuthenticationRequired;
            const receipt = try self.loadRowPolicyReceipt(request.generation, request.phase);
            return .{ .json = try std.json.Stringify.valueAlloc(alloc, receipt, .{}) };
        }
        try self.maybeFinalizePendingRowPolicyPublication();
        if (self.local_execution.initial_child_hidden.load(.acquire) and
            opts.relational_topology_json.len == 0 and opts.relational_index_status_json.len == 0 and
            !opts.relational_integrity_catalog)
            return error.InitialChildNotPublished;
        if (self.local_execution.restore_staging_required.load(.acquire) or opts.restore_staging_scope != null) {
            var staging_read = try self.core.store.beginProbeTxn();
            defer staging_read.abort();
            try @import("restore_staging.zig").requireScope(alloc, &staging_read, opts.restore_staging_scope, false);
        }
        if (opts.relational_topology_json.len != 0) return self.lookupRelationalTopology(alloc, opts.relational_topology_json, opts);
        if (opts.relational_index_status_json.len != 0) return self.lookupRelationalIndexStatus(alloc, opts.relational_index_status_json, opts);
        if (opts.relational_activation_json.len != 0) return self.lookupRelationalActivation(alloc, opts.relational_activation_json);
        if (opts.relational_integrity_catalog) return self.lookupRelationalIntegrityCatalog(alloc);
        if (opts.relational_integrity_action) return self.lookupRelationalIntegrityAction(alloc, key);
        if (opts.relational_integrity_jobs_json.len != 0) return self.lookupRelationalIntegrityJobs(alloc, opts.relational_integrity_jobs_json, opts);
        var probe = if (opts.include_primary_digest)
            try self.core.store.beginReadTxn()
        else
            try self.core.store.beginProbeTxn();
        defer probe.abort();
        return self.lookupPrimarySnapshot(alloc, key, opts, &probe);
    }

    fn lookupPrimarySnapshot(self: *DB, alloc: Allocator, key: []const u8, opts: types.LookupOptions, probe: *@import("../docstore.zig").DocStore.Txn) !?types.LookupResult {
        var verified_principal: ?std.json.Parsed(row_policy_authority_mod.Payload) = null;
        defer if (verified_principal) |*principal| principal.deinit();
        var row_policy_lease = if (opts.row_policy_principal_proof.len != 0) bound: {
            verified_principal = try self.verifyRowPolicyPrincipal(alloc, opts.row_policy_principal_proof, opts.row_policy_database, .read, @intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
            break :bound try self.local_execution.row_policy_gate.enterVerifiedPrincipal(&verified_principal.?.value, @intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
        } else try self.local_execution.row_policy_gate.enterRawRead();
        defer row_policy_lease.release();
        // Each row uses its authenticated schema epoch. A batch shares the
        // same immutable storage snapshot through projection and predicates.
        var schema_view = self.core.acquireSchemaView();
        defer if (schema_view) |*view| view.release();
        const store_key = try encodeStoreLookupKeyWithPinnedSchemaAlloc(self, alloc, key, schema_view);
        defer alloc.free(store_key);
        const raw = probe.getLeased(store_key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        const relational = internal_keys.isRelationalRowKey(store_key);
        var historical_schema_view: ?schema_registry_mod.SchemaView = null;
        defer if (historical_schema_view) |*view| view.release();
        const ordinal_row = if (relational) blk: {
            const version = try relational_store.rowSchemaVersion(raw);
            const row_schema = if (schema_view) |view|
                if (view.version() == version)
                    view
                else historical: {
                    historical_schema_view = (try self.core.acquireSchemaVersionView(version)) orelse
                        return error.UnknownSchemaVersion;
                    break :historical historical_schema_view.?;
                }
            else historical: {
                historical_schema_view = (try self.core.acquireSchemaVersionView(version)) orelse
                    return error.UnknownSchemaVersion;
                break :historical historical_schema_view.?;
            };
            break :blk if (self.core.store.valuesAreAuthenticated())
                try relational_row_codec.ordinalRowViewTrusted(
                    raw,
                    row_schema.tableSchema().*,
                    row_schema.physicalLayout(),
                )
            else
                try relational_row_codec.ordinalRowViewSelective(
                    raw,
                    row_schema.tableSchema().*,
                    row_schema.physicalLayout(),
                );
        } else null;
        if (verified_principal) |*principal| {
            const row = ordinal_row orelse return error.RowPolicyCatalogChanged;
            const bundle = if (self.local_execution.row_policy_bundle) |*installed| installed else return error.RowPolicyCatalogChanged;
            var evaluation = try bundle.captureReadEvaluation(alloc, row.table_schema, &principal.value);
            defer evaluation.deinit();
            if (!try evaluation.permits(row)) return null;
            try row_policy_lease.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
        }
        if (!internal_keys.isInternalUserKey(key)) {
            const ttl_duration_ns = if (schema_view) |view| view.visibilityTtlDurationNs() else 0;
            if (ttl_duration_ns != 0) {
                const timestamp_ns = if (ordinal_row) |row|
                    row.writeTimestampNs()
                else
                    try lookupSnapshotTimestamp(alloc, key, probe);
                if (timestamp_ns != 0 and ttl_mod.isExpired(timestamp_ns, ttl_duration_ns, currentTimeNs())) return null;
            }
        }
        try checkLookupOptionsActive(opts);
        const direct_fields = if (relational)
            ordinalProjectionFields(opts.fields, opts.include_all_fields)
        else
            null;
        const stored = if (direct_fields) |fields| blk: {
            const row = ordinal_row.?;
            var projection = try RelationalProjectionPlan.init(
                alloc,
                row.table_schema,
                row.layout,
                fields,
            );
            defer projection.deinit();
            break :blk try projection.project(alloc, row);
        } else blk: {
            const materialized = if (ordinal_row) |row|
                try row.reconstructValueAlloc(alloc)
            else
                try alloc.dupe(u8, raw);
            if (opts.fields.len == 0 and opts.include_all_fields) break :blk materialized;
            defer alloc.free(materialized);
            break :blk try projectLookupStoredBytes(self, alloc, key, materialized, opts);
        };
        errdefer alloc.free(stored);
        try checkLookupOptionsActive(opts);
        var version: ?u64 = if (ordinal_row) |row| row.writeTimestampNs() else null;
        var digest: ?[32]u8 = null;
        if (opts.include_primary_digest) {
            var primary_digest: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(raw, &primary_digest, .{});
            digest = primary_digest;
            if (version == null) {
                version = try lookupSnapshotTimestamp(alloc, key, probe);
            }
        }
        try row_policy_lease.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
        return .{ .json = stored, .version = version, .expected_content_digest = digest };
    }

    fn lookupSnapshotTimestamp(alloc: Allocator, key: []const u8, probe: *docstore_mod.DocStore.Txn) !u64 {
        const timestamp_key = try internal_keys.ttlKeyAlloc(alloc, key);
        defer alloc.free(timestamp_key);
        const timestamp = probe.get(timestamp_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        const bytes = timestamp orelse return 0;
        if (bytes.len != 8) return error.InvalidTimestamp;
        return std.mem.readInt(u64, bytes[0..8], .little);
    }

    fn lookupRelationalRetirement(self: *DB, alloc: Allocator, request_json: []const u8) !?types.LookupResult {
        const retirement = @import("relational_integrity_retirement.zig");
        const activation = @import("relational_integrity_activation.zig");
        var request = try std.json.parseFromSlice(struct { kind: []const u8, mode: enum { status, page } = .status, max_rows: u32 = 128, include_catalog: bool = true }, alloc, request_json, .{});
        defer request.deinit();
        if (request.value.max_rows == 0 or request.value.max_rows > 128) return error.InvalidIntegrityBudget;
        if (request.value.mode == .page) {
            var view = self.core.acquireSchemaView() orelse return error.RelationalTableRequired;
            defer view.release();
            const public_schema = (view.validator() orelse return error.ConstraintNotFound).schema;
            var arena = std.heap.ArenaAllocator.init(alloc);
            defer arena.deinit();
            const owned = arena.allocator();
            const raw_progress = (try self.core.getStoreValue(owned, retirement.key)) orelse return null;
            const progress = try retirement.Progress.decode(raw_progress);
            const raw_bindings = (try self.core.getStoreValue(owned, @import("relational_integrity_catalog.zig").key)) orelse return error.IntegrityCatalogChanged;
            var bindings = try @import("relational_integrity_catalog.zig").decode(owned, raw_bindings);
            defer bindings.deinit();
            if (view.version() != progress.schema_version or !std.mem.eql(u8, &progress.generation_set, &activation.generationSet(bindings))) return error.ConstraintRetirementChanged;
            var fields = std.ArrayList([]const u8).empty;
            var selected = std.StringHashMapUnmanaged(void).empty;
            for (try public_schema.relationalUniqueDefinitions(owned)) |definition| {
                const binding = bindings.find(.unique, definition.name) orelse return error.IntegrityCatalogChanged;
                if (progress.phase != .unique or !progress.includes(binding.generation)) continue;
                for (try @import("../../schema/relational_declarations.zig").uniqueFields(owned, view.tableSchema().*, view.physicalLayout(), definition)) |column| if (!(try selected.getOrPut(owned, column)).found_existing) try fields.append(owned, column);
            }
            if (public_schema.foreign_keys) |definitions| for (definitions.value) |definition| {
                const binding = bindings.find(.foreign_key, definition.name) orelse return error.IntegrityCatalogChanged;
                if (progress.phase != .foreign_keys or !progress.includes(binding.generation)) continue;
                for (definition.child_columns) |column| if (!(try selected.getOrPut(owned, column)).found_existing) try fields.append(owned, column);
            };
            var page = (try retirement.Page.prepare(alloc, self.backend_runtime.io(), self.core, fields.items, raw_progress, .{ .rows = request.value.max_rows, .output_bytes = 16 * 1024 * 1024 })) orelse return null;
            defer page.deinit();
            const Row = struct { key: []const u8, json: []const u8, version: u64, expected_content_digest: ?[32]u8 };
            const page_rows = try owned.alloc(Row, page.rows.rows.len);
            for (page_rows, page.rows.rows) |*row, source| row.* = .{ .key = source.key, .json = source.json, .version = source.version, .expected_content_digest = source.expected_content_digest };
            const Response = struct {
                rows: []const Row,
                command: retirement.Command,
                phase: retirement.Phase,
                pub fn jsonStringify(response: @This(), jw: anytype) @TypeOf(jw.*).Error!void {
                    try jw.beginObject();
                    try jw.objectField("rows");
                    try jw.beginArray();
                    for (response.rows) |row| {
                        try jw.beginObject();
                        try jw.objectField("key");
                        try @import("relational_integrity_json.zig").write(row.key, jw);
                        try jw.objectField("json");
                        try jw.write(row.json);
                        try jw.objectField("version");
                        try jw.write(row.version);
                        try jw.objectField("expected_content_digest");
                        try @import("relational_integrity_json.zig").write(row.expected_content_digest, jw);
                        try jw.endObject();
                    }
                    try jw.endArray();
                    try jw.objectField("command");
                    try jw.write(response.command);
                    try jw.objectField("phase");
                    try jw.write(@tagName(response.phase));
                    try jw.endObject();
                }
            };
            return .{ .json = try std.json.Stringify.valueAlloc(alloc, Response{ .rows = page_rows, .command = page.command, .phase = page.phase }, .{}) };
        }
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        var read = try @import("relational_integrity.zig").CurrentView.init(self.core.store);
        defer read.deinit();
        const raw_catalog: []const u8 = if (request.value.include_catalog) read.get(@import("relational_integrity_catalog.zig").key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        } else "";
        const raw_progress: ?[]const u8 = read.get(retirement.key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        const Response = struct {
            catalog: []const u8,
            progress: ?[]const u8,
            owner: [32]u8,
            range_start: []const u8,
            range_end: []const u8,
            pub fn jsonStringify(response: @This(), jw: anytype) @TypeOf(jw.*).Error!void {
                try @import("relational_integrity_json.zig").write(response, jw);
            }
        };
        const serving_range = try @import("online_integrity_shadow.zig").servingRange(&read, self.core.byteRange());
        return .{ .json = try std.json.Stringify.valueAlloc(alloc, Response{ .catalog = raw_catalog, .progress = raw_progress, .owner = try activation.ownership(&read), .range_start = serving_range.start, .range_end = serving_range.end }, .{}) };
    }

    fn lookupRelationalActivation(self: *DB, alloc: Allocator, request_json: []const u8) !?types.LookupResult {
        const activation = @import("relational_integrity_activation.zig");
        const catalog_mod = @import("relational_integrity_catalog.zig");
        if (request_json.len > 1024) return error.InvalidConstraintActivation;
        var request = try std.json.parseFromSlice(struct { mode: enum { status, page, retry } = .status, max_rows: u32 = 128, schema_version: ?u32 = null }, alloc, request_json, .{});
        defer request.deinit();
        if (request.value.max_rows == 0 or request.value.max_rows > 128) return error.InvalidConstraintActivation;
        if (request.value.mode == .page) {
            var view = self.core.acquireSchemaView() orelse return error.RelationalTableRequired;
            defer view.release();
            const public_schema = (view.validator() orelse return error.ConstraintNotFound).schema;
            // Reserve half the native admission credits for encoded tuple and
            // existing claim bytes. The worker can shrink further when actual
            // values exceed this declaration-only estimate.
            const unique_count = if (public_schema.unique_constraints) |values| values.value.len else 0;
            const foreign_count = if (public_schema.foreign_keys) |values| values.value.len else 0;
            const per_row = @max(@as(usize, 1), @max(unique_count, foreign_count));
            const declaration_limit = @max(@as(usize, 1), @import("relational_integrity.zig").max_commands / (2 * per_row));
            // Activation pages commit through distributed 2PC. A bounded
            // 100 ms source scan amortizes that commit without changing the
            // reusable reader's caller-specified budget or its row/byte caps.
            var page = (try activation.Page.prepare(alloc, self.backend_runtime.io(), self.core, .{
                .rows = @min(request.value.max_rows, declaration_limit),
                .output_bytes = 1024 * 1024,
                .time_ns = 100 * std.time.ns_per_ms,
            })) orelse return null;
            defer page.deinit();
            if (page.progress.schema_version != view.version()) return error.PreparedGenerationChanged;
            const Row = struct { key: []const u8, json: []const u8, version: u64, expected_content_digest: ?[32]u8 };
            const rows = try alloc.alloc(Row, page.rows.rows.len);
            defer alloc.free(rows);
            for (rows, page.rows.rows) |*row, source| row.* = .{ .key = source.key, .json = source.json, .version = source.version, .expected_content_digest = source.expected_content_digest };
            const Response = struct {
                rows: []const Row,
                command: activation.Command,
                phase: activation.Phase,

                pub fn jsonStringify(response: @This(), stream: anytype) @TypeOf(stream.*).Error!void {
                    try @import("relational_integrity_json.zig").write(response, stream);
                }
            };
            return .{ .json = try std.json.Stringify.valueAlloc(alloc, Response{ .rows = rows, .command = page.command, .phase = page.phase }, .{}) };
        }
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        var read = try @import("relational_integrity.zig").CurrentView.init(self.core.store);
        defer read.deinit();
        const raw_catalog = read.get(catalog_mod.key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        var catalog = try catalog_mod.decode(alloc, raw_catalog);
        defer catalog.deinit();
        const progress = try activation.status(&read, catalog);
        const range = try @import("online_integrity_shadow.zig").servingRange(&read, self.core.byteRange());
        if (request.value.mode == .retry) {
            try @import("online_integrity_shadow.zig").requireCatalogMutable(&read);
            if ((request.value.schema_version orelse return error.InvalidConstraintActivation) != catalog.schema_version) return error.PreparedGenerationChanged;
            if (progress.state != .invalid) return null;
            const next = try (try progress.retry(catalog)).encode(alloc);
            defer alloc.free(next);
            const expected = try read.get(activation.key);
            const command: activation.Command = .{ .routing_key = range.start, .expected = expected, .next = next, .retry = true };
            return .{ .json = try std.json.Stringify.valueAlloc(alloc, command, .{}) };
        }
        const Response = struct {
            progress: activation.Progress,
            catalog: *const catalog_mod.Catalog,
            range: types.ByteRange,

            pub fn jsonStringify(response: @This(), stream: anytype) @TypeOf(stream.*).Error!void {
                try @import("relational_integrity_json.zig").write(.{
                    .schema_version = response.progress.schema_version,
                    .schema_digest = response.catalog.schema_digest,
                    .generation_set = response.progress.generation_set,
                    .owner = response.progress.owner,
                    .range_start = response.range.start,
                    .range_end = response.range.end,
                    .unique_covered = response.progress.readyForReferences(),
                    .state = response.progress.state,
                    .phase = response.progress.phase,
                    .rows_scanned = response.progress.rows_scanned,
                    .failure = response.progress.failure,
                }, stream);
            }
        };
        return .{ .json = try std.json.Stringify.valueAlloc(alloc, Response{ .progress = progress, .catalog = &catalog, .range = range }, .{}) };
    }

    pub fn getTimestamp(self: *DB, alloc: Allocator, key: []const u8) !u64 {
        try self.maybeFinalizePendingRowPolicyPublication();
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRawRead();
        defer row_policy_lease.release();
        if (internal_keys.isInternalUserKey(key)) return 0;
        const timestamp = try self.core.readTimestamp(alloc, key);
        try row_policy_lease.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
        return timestamp;
    }

    pub fn updateRange(self: *DB, byte_range: types.ByteRange) !void {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        {
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            try @import("artifact_reconcile_intent.zig").requireAbsent(&read);
        }
        const start = try self.alloc.dupe(u8, byte_range.start);
        errdefer self.alloc.free(start);
        const end = try self.alloc.dupe(u8, byte_range.end);
        errdefer self.alloc.free(end);
        const owned_range: types.ByteRange = .{ .start = start, .end = end };
        const range_value = try range_state_mod.encodeRangeAlloc(self.alloc, owned_range);
        defer self.alloc.free(range_value);
        const range_write: docstore_mod.KVPair = .{ .key = range_state_mod.range_key, .value = range_value };
        try rebaseRangeCoverageMetadata(
            self.alloc,
            self.core.store,
            self.core.index_manager,
            owned_range,
            &.{range_write},
        );
        self.core.adoptRangeInMemoryOwned(start, end);
    }

    pub fn getRange(self: *DB) types.ByteRange {
        return self.core.byteRange();
    }

    pub fn durableRootIncarnation(self: *const DB) !u128 {
        if (self.root_incarnation == 0) return error.DurableRootIncarnationUnavailable;
        return self.root_incarnation;
    }

    pub fn findMedianKey(self: *DB, alloc: Allocator) ![]u8 {
        const byte_range = self.getRange();
        const lower = try self.core.documentRangeLowerAlloc(byte_range.start);
        defer self.core.alloc.free(lower);
        const upper = if (byte_range.end.len > 0) try self.core.documentRangeUpperAlloc(byte_range.end) else null;
        defer if (upper) |buf| self.core.alloc.free(buf);

        const internal_key = self.core.findMedianStoreKey(alloc, lower, if (upper) |buf| buf else "", .{
            .skip_fn = &skipNonPrimaryMedianKey,
        }) catch |err| switch (err) {
            error.NotFound => return try doc_identity.findMedianDocIdAlloc(alloc, self.core.store, byte_range.start, byte_range.end),
            else => return err,
        };
        defer alloc.free(internal_key);

        return (try internal_keys.decodeStoredDocumentRowKeyAlloc(alloc, internal_key)) orelse error.NotFound;
    }

    pub fn getSplitState(self: *DB, alloc: Allocator) !?types.SplitState {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        const state = self.core.splitState() orelse return null;
        return .{
            .phase = state.phase,
            .split_key = try alloc.dupe(u8, state.split_key),
            .new_shard_id = state.new_shard_id,
            .started_at = state.started_at,
            .original_range_end = try alloc.dupe(u8, state.original_range_end),
        };
    }

    pub fn setSplitState(self: *DB, state: ?types.SplitState) !void {
        if (self.local_execution.source_vectors.load(.acquire) != null) return error.VectorStoreLifecycleUnsupported;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (state == null) {
            try recoverInterruptedGraphSplitRetirement(self);
            try self.core.setSplitState(null);
            return;
        }
        try recoverInterruptedGraphSplitRetirement(self);
        try self.requireSupportedRelationalTopology();
        try self.core.setSplitState(.{
            .phase = state.?.phase,
            .split_key = state.?.split_key,
            .new_shard_id = state.?.new_shard_id,
            .started_at = state.?.started_at,
            .original_range_end = state.?.original_range_end,
        });
    }

    pub fn clearSplitState(self: *DB) !void {
        try self.setSplitState(null);
    }

    pub fn getSplitDeltaSeq(self: *DB) u64 {
        return self.core.splitDeltaSequence();
    }

    pub fn getSplitDeltaFinalSeq(self: *DB, alloc: Allocator) !u64 {
        return try self.core.loadSplitDeltaFinalSeq(alloc);
    }

    pub fn setSplitDeltaFinalSeq(self: *DB, seq: u64) !void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        try self.core.saveSplitDeltaFinalSeq(seq);
    }

    pub fn clearSplitDeltaFinalSeq(self: *DB) !void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        try self.core.clearSplitDeltaFinalSeq();
    }

    pub fn getSplitBootstrapMarker(self: *DB, alloc: Allocator) !?range_state_mod.SplitBootstrapMarker {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        return try self.core.loadSplitBootstrapMarker(alloc);
    }

    pub fn setSplitBootstrapMarker(self: *DB, marker: range_state_mod.SplitBootstrapMarker) !void {
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        try self.core.saveSplitBootstrapMarker(marker);
    }

    /// Replaces all primary documents and their range in a
    /// single durable commit. Derived indexes consume the same replacement
    /// batch, so stale documents are removed instead of surviving restore.
    pub fn replacePrimaryDocumentsAndRange(
        self: *DB,
        alloc: Allocator,
        byte_range: types.ByteRange,
        writes: []const types.BatchWrite,
    ) !void {
        lockAtomicWithBackoff(&self.generation_replace_mutex);
        defer self.generation_replace_mutex.unlock();
        if (byte_range.start.len > 0 and byte_range.end.len > 0 and
            std.mem.order(u8, byte_range.start, byte_range.end) != .lt)
        {
            return error.InvalidAppliedDataRange;
        }
        var seen = std.StringHashMapUnmanaged(void).empty;
        defer seen.deinit(alloc);
        try seen.ensureTotalCapacity(alloc, @intCast(writes.len));
        for (writes) |write| {
            if (!byte_range.contains(write.key)) return error.KeyOutOfRange;
            const result = try seen.getOrPut(alloc, write.key);
            if (result.found_existing) return error.DuplicateDocumentKey;
        }

        const lower = try internal_keys.documentRangeLowerAlloc(alloc, "");
        defer alloc.free(lower);
        const upper = (try internal_keys.documentRangeUpperAlloc(alloc, "")) orelse return error.InvalidAppliedDataRange;
        defer alloc.free(upper);
        lockApplyShared(self);
        const existing_documents = self.core.scanStoreRange(alloc, lower, upper) catch |err| {
            self.core.unlockApplyShared();
            return err;
        };
        self.core.unlockApplyShared();
        defer docstore_mod.DocStore.freeResults(alloc, existing_documents);

        var deletes = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (deletes.items) |key| alloc.free(key);
            deletes.deinit(alloc);
        }
        for (existing_documents) |entry| {
            const logical_key = (try internal_keys.decodeStoredDocumentRowKeyAlloc(alloc, entry.key)) orelse continue;
            if (seen.contains(logical_key)) {
                alloc.free(logical_key);
                continue;
            }
            errdefer alloc.free(logical_key);
            try deletes.append(alloc, logical_key);
        }

        const range_value = try range_state_mod.encodeRangeAlloc(alloc, byte_range);
        defer alloc.free(range_value);
        const range_write: docstore_mod.KVPair = .{ .key = range_state_mod.range_key, .value = range_value };
        try self.batchInternal(.{
            .writes = writes,
            .deletes = deletes.items,
            .sync_level = .write,
        }, null, .{
            .validate_range_ownership = false,
            .wait_for_sync_level = false,
            .bypass_replication_write_gate = true,
            .extra_store_writes = &.{range_write},
        });
        try self.refreshSplitBootstrapRangeInMemory(byte_range);
    }

    /// Appends a bounded document chunk into an isolated snapshot generation.
    /// The caller owns generation publication and must never call this against
    /// a live generation because chunks are independently durable.
    pub fn appendStagedSnapshotDocuments(
        self: *DB,
        staged_generation: *const generation_lifecycle.StagedGeneration,
        byte_range: types.ByteRange,
        writes: []const types.BatchWrite,
    ) !void {
        try staged_generation.validatePath(self.core.path);
        if (byte_range.start.len > 0 and byte_range.end.len > 0 and
            std.mem.order(u8, byte_range.start, byte_range.end) != .lt)
        {
            return error.InvalidAppliedDataRange;
        }
        for (writes) |write| if (!byte_range.contains(write.key)) return error.KeyOutOfRange;
        try self.batchInternal(.{
            .writes = writes,
            .sync_level = .write,
        }, null, .{
            .validate_range_ownership = false,
            .wait_for_sync_level = false,
            .bypass_replication_write_gate = true,
        });
    }

    /// Finalizes the range metadata after all chunks have been imported.
    pub fn finishStagedSnapshotRange(
        self: *DB,
        staged_generation: *const generation_lifecycle.StagedGeneration,
        byte_range: types.ByteRange,
    ) !void {
        try staged_generation.validatePath(self.core.path);
        const range_value = try range_state_mod.encodeRangeAlloc(self.alloc, byte_range);
        defer self.alloc.free(range_value);
        const range_write: docstore_mod.KVPair = .{ .key = range_state_mod.range_key, .value = range_value };
        try self.batchInternal(.{ .sync_level = .write }, null, .{
            .validate_range_ownership = false,
            .wait_for_sync_level = false,
            .bypass_replication_write_gate = true,
            .extra_store_writes = &.{range_write},
        });
        try self.refreshSplitBootstrapRangeInMemory(byte_range);
    }

    /// Atomically starts or replaces a split destination bootstrap. An
    /// incomplete marker fences ordinary replication while bounded bootstrap
    /// chunks are streamed. Callers must hold the destination generation's
    /// exclusive lifecycle lease.
    pub fn replaceSplitBootstrap(
        self: *DB,
        alloc: Allocator,
        byte_range: types.ByteRange,
        writes: []const types.BatchWrite,
        base_delta_sequence: u64,
        marker: range_state_mod.SplitBootstrapMarker,
    ) !bool {
        lockAtomicWithBackoff(&self.generation_replace_mutex);
        defer self.generation_replace_mutex.unlock();
        try self.requireSupportedRelationalTopology();

        if (marker.transition_id == 0 or marker.attempt_epoch == 0 or
            marker.source_group_id == 0 or marker.destination_group_id == 0 or
            marker.bootstrap_complete)
        {
            return error.InvalidSplitBootstrapMarker;
        }
        if (byte_range.start.len > 0 and byte_range.end.len > 0 and
            std.mem.order(u8, byte_range.start, byte_range.end) != .lt)
        {
            return error.InvalidAppliedDataRange;
        }
        var seen = std.StringHashMapUnmanaged(void).empty;
        defer seen.deinit(alloc);
        try seen.ensureTotalCapacity(alloc, @intCast(writes.len));
        for (writes) |write| {
            if (!byte_range.contains(write.key)) return error.KeyOutOfRange;
            const result = try seen.getOrPut(alloc, write.key);
            if (result.found_existing) return error.DuplicateDocumentKey;
        }

        if (try self.getSplitBootstrapMarker(alloc)) |existing| {
            const same_attempt = existing.transition_id == marker.transition_id and
                existing.attempt_epoch == marker.attempt_epoch and
                existing.source_group_id == marker.source_group_id and
                existing.destination_group_id == marker.destination_group_id;
            if (same_attempt) {
                const reserved_sequence = try self.getSplitDeltaFinalSeq(alloc);
                if (base_delta_sequence < reserved_sequence) return error.StaleSplitBootstrap;
                if (!byteRangesEqual(self.core.byteRange(), byte_range)) return error.ConflictingSplitTransition;
                if (existing.bootstrap_complete) {
                    if (base_delta_sequence > reserved_sequence) return error.SplitBootstrapComplete;
                    return false;
                }
                // Source leadership can change after an earlier worker has
                // reserved and populated this exact transfer. Replaying begin
                // must not erase those chunks beneath its pending completion.
                if (base_delta_sequence == reserved_sequence) return false;
            }
            if (!same_attempt and
                (existing.source_group_id != marker.source_group_id or
                    existing.destination_group_id != marker.destination_group_id or
                    existing.attempt_epoch >= marker.attempt_epoch))
            {
                return error.ConflictingSplitTransition;
            }
        }

        const lower = try internal_keys.documentRangeLowerAlloc(alloc, "");
        defer alloc.free(lower);
        const upper = (try internal_keys.documentRangeUpperAlloc(alloc, "")) orelse return error.InvalidAppliedDataRange;
        defer alloc.free(upper);
        lockApplyShared(self);
        const existing_documents = self.core.scanStoreRange(alloc, lower, upper) catch |err| {
            self.core.unlockApplyShared();
            return err;
        };
        self.core.unlockApplyShared();
        defer docstore_mod.DocStore.freeResults(alloc, existing_documents);

        var deletes = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (deletes.items) |key| alloc.free(key);
            deletes.deinit(alloc);
        }
        for (existing_documents) |entry| {
            const logical_key = (try internal_keys.decodeStoredDocumentRowKeyAlloc(alloc, entry.key)) orelse continue;
            if (seen.contains(logical_key)) {
                alloc.free(logical_key);
                continue;
            }
            errdefer alloc.free(logical_key);
            try deletes.append(alloc, logical_key);
        }

        const range_value = try range_state_mod.encodeRangeAlloc(alloc, byte_range);
        defer alloc.free(range_value);
        var sequence_buf: [8]u8 = undefined;
        var marker_buf: [4 * @sizeOf(u64) + 1]u8 = undefined;
        const metadata_writes = try range_state_mod.splitBootstrapMetadataWrites(
            range_value,
            base_delta_sequence,
            marker,
            &sequence_buf,
            &marker_buf,
        );
        self.batchInternal(.{
            .writes = writes,
            .deletes = deletes.items,
            .sync_level = .write,
        }, null, .{
            .validate_range_ownership = false,
            .wait_for_sync_level = false,
            .bypass_replication_write_gate = true,
            .extra_store_writes = &metadata_writes,
        }) catch |err| {
            if (try self.getSplitBootstrapMarker(alloc)) |committed| {
                if (splitBootstrapMarkersEqual(committed, marker)) {
                    try self.refreshSplitBootstrapRangeInMemory(byte_range);
                    return true;
                }
            }
            return err;
        };
        try self.refreshSplitBootstrapRangeInMemory(byte_range);
        return true;
    }

    /// Atomically publishes a fully streamed split bootstrap. Completion is
    /// valid only for the exact reservation installed by replaceSplitBootstrap.
    pub fn completeSplitBootstrap(
        self: *DB,
        alloc: Allocator,
        byte_range: types.ByteRange,
        base_delta_sequence: u64,
        marker: range_state_mod.SplitBootstrapMarker,
    ) !bool {
        lockAtomicWithBackoff(&self.generation_replace_mutex);
        defer self.generation_replace_mutex.unlock();

        if (marker.transition_id == 0 or marker.attempt_epoch == 0 or
            marker.source_group_id == 0 or marker.destination_group_id == 0 or
            !marker.bootstrap_complete)
        {
            return error.InvalidSplitBootstrapMarker;
        }
        if (byte_range.start.len > 0 and byte_range.end.len > 0 and
            std.mem.order(u8, byte_range.start, byte_range.end) != .lt)
        {
            return error.InvalidAppliedDataRange;
        }

        const existing = (try self.getSplitBootstrapMarker(alloc)) orelse
            return error.SplitBootstrapRequired;
        if (existing.transition_id != marker.transition_id or
            existing.attempt_epoch != marker.attempt_epoch or
            existing.source_group_id != marker.source_group_id or
            existing.destination_group_id != marker.destination_group_id)
        {
            return error.ConflictingSplitTransition;
        }
        const reserved_sequence = try self.getSplitDeltaFinalSeq(alloc);
        if (base_delta_sequence != reserved_sequence) return error.StaleSplitBootstrap;
        if (!byteRangesEqual(self.core.byteRange(), byte_range)) return error.ConflictingSplitTransition;
        if (existing.bootstrap_complete) {
            try self.refreshSplitBootstrapRangeInMemory(byte_range);
            return false;
        }

        const range_value = try range_state_mod.encodeRangeAlloc(alloc, byte_range);
        defer alloc.free(range_value);
        var sequence_buf: [8]u8 = undefined;
        var marker_buf: [4 * @sizeOf(u64) + 1]u8 = undefined;
        const metadata_writes = try range_state_mod.splitBootstrapMetadataWrites(
            range_value,
            base_delta_sequence,
            marker,
            &sequence_buf,
            &marker_buf,
        );
        try self.batchInternal(.{ .sync_level = .write }, null, .{
            .validate_range_ownership = false,
            .wait_for_sync_level = false,
            .bypass_replication_write_gate = true,
            .extra_store_writes = &metadata_writes,
        });
        try self.refreshSplitBootstrapRangeInMemory(byte_range);
        return true;
    }

    fn refreshSplitBootstrapRangeInMemory(self: *DB, byte_range: types.ByteRange) !void {
        const start = try self.alloc.dupe(u8, byte_range.start);
        errdefer self.alloc.free(start);
        const end = try self.alloc.dupe(u8, byte_range.end);
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        self.core.replaceRangeInMemoryOwned(start, end);
    }

    pub fn clearSplitBootstrapMarker(self: *DB) !void {
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        try self.core.clearSplitBootstrapMarker();
    }

    pub fn listSplitDeltaEntriesAfter(self: *DB, alloc: Allocator, after_seq: u64) ![]types.SplitDeltaEntry {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();

        const deltas = try self.core.listSplitDeltasAfter(alloc, after_seq);
        defer shard_mod.freeDeltas(alloc, deltas);

        var entries = std.ArrayListUnmanaged(types.SplitDeltaEntry).empty;
        errdefer {
            for (entries.items) |*entry| entry.deinit(alloc);
            entries.deinit(alloc);
        }

        for (deltas) |delta| {
            var writes = try alloc.alloc(types.BatchWrite, delta.writes.len);
            errdefer alloc.free(writes);
            for (delta.writes, 0..) |write, i| {
                writes[i] = .{
                    .key = try alloc.dupe(u8, write.key),
                    .value = try alloc.dupe(u8, write.value),
                };
            }

            var deletes = try alloc.alloc([]u8, delta.deletes.len);
            errdefer {
                for (deletes) |key| alloc.free(key);
                alloc.free(deletes);
            }
            for (delta.deletes, 0..) |key, i| {
                deletes[i] = try alloc.dupe(u8, key);
            }

            try entries.append(alloc, .{
                .sequence = delta.sequence,
                .timestamp = delta.timestamp,
                .writes = writes,
                .deletes = deletes,
            });
        }

        return try entries.toOwnedSlice(alloc);
    }

    pub fn clearSplitDeltaEntries(self: *DB) !void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        try self.core.clearSplitDeltas();
    }

    pub fn createShadowIndexManager(self: *DB, split_key: []const u8, original_range_end: []const u8) !void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (self.shadow != null) return error.ShadowIndexManagerExists;

        const base_path = try std.fmt.allocPrint(self.alloc, "{s}/.shadow-{d}", .{ self.core.path, monotonicTimeNs() });
        errdefer self.alloc.free(base_path);
        const indexes_path = try std.fmt.allocPrint(self.alloc, "{s}/indexes", .{base_path});
        errdefer self.alloc.free(indexes_path);

        try ensureDirPath(indexes_path);

        const shadow_manager = try self.alloc.create(index_manager_mod.IndexManager);
        errdefer self.alloc.destroy(shadow_manager);
        shadow_manager.* = try index_manager_mod.IndexManager.initWithOptions(
            self.alloc,
            base_path,
            self.index_backends,
        );
        errdefer shadow_manager.deinit();

        const shadow_start = try self.alloc.dupe(u8, split_key);
        errdefer self.alloc.free(shadow_start);
        const shadow_end = try self.alloc.dupe(u8, original_range_end);
        errdefer self.alloc.free(shadow_end);
        shadow_manager.updateRange(.{ .start = shadow_start, .end = shadow_end });

        try self.core.registerShadowIndexes(self.alloc, shadow_manager);

        const shadow = try self.alloc.create(ShadowState);
        shadow.* = .{
            .manager = shadow_manager,
            .base_path = base_path,
            .indexes_path = indexes_path,
            .range_start = shadow_start,
            .range_end = shadow_end,
        };
        self.shadow = shadow;
        if (self.transaction_recovery_local_context) |ctx| {
            ctx.split_shadow = self.shadow;
        }
    }

    pub fn closeShadowIndexManager(self: *DB) !void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        try self.closeShadowIndexManagerLocked();
    }

    fn closeShadowIndexManagerLocked(self: *DB) !void {
        try waitForSplitShadowDrainLocked(self, false);
        const shadow = self.shadow orelse return;
        if (self.transaction_recovery_local_context) |ctx| {
            ctx.split_shadow = null;
        }
        shadow.manager.deinit();
        self.alloc.destroy(shadow.manager);
        self.alloc.free(shadow.base_path);
        self.alloc.free(shadow.indexes_path);
        self.alloc.free(shadow.range_start);
        self.alloc.free(shadow.range_end);
        self.alloc.destroy(shadow);
        self.shadow = null;
    }

    pub fn getShadowIndexDir(self: *DB) []const u8 {
        const shadow = self.shadow orelse return "";
        return shadow.indexes_path;
    }

    fn requireSupportedRelationalTopology(self: *DB) !void {
        if (self.local_execution.row_policy_gate.currentPhase() != .disabled) return error.RowPolicyTopologyUnsupported;
        var view = self.core.acquireSchemaView();
        defer if (view) |*pinned| pinned.release();
        // Initial physical transfer understands routed integrity records, but
        // the online delta/intent handoff does not yet carry those namespaces.
        if (hasCoordinatedConstraints(view)) return error.CoordinatedConstraintTopologyUnsupported;
    }

    pub fn split(
        self: *DB,
        curr_range: types.ByteRange,
        split_key: []const u8,
        dest_dir1: []const u8,
        dest_dir2: []const u8,
        prepare_only: bool,
    ) !void {
        if (self.local_execution.source_vectors.load(.acquire) != null) return error.VectorStoreLifecycleUnsupported;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        var snapshot_mutation = self.core.snapshot_admission.acquireMutation();
        defer snapshot_mutation.release();
        _ = dest_dir1;
        while (true) {
            const target_sequence = self.core.nextDerivedSequence();
            try self.runMaintenanceUntil(target_sequence, .{});

            try self.lockApplyForPortableRuntime();
            if (self.core.nextDerivedSequence() == target_sequence) break;
            self.core.unlockApply();
        }
        defer self.core.unlockApply();

        try self.requireSupportedRelationalTopology();
        if (!byteRangesEqual(self.core.byteRange(), curr_range)) return error.KeyOutOfRange;
        if (!curr_range.contains(split_key)) return error.KeyOutOfRange;
        // Shared FK guards and private metadata intents cannot move owners
        // midway through a durable decision. Drain them before range transfer.
        var transaction_manager = try self.core.initTxnManager();
        defer transaction_manager.deinit();
        if (try transaction_manager.hasSchemaLeases()) return error.SchemaInUse;

        const range2 = types.ByteRange{
            .start = split_key,
            .end = curr_range.end,
        };

        if (self.core.splitState() == null) {
            try self.core.prepareSplit(split_key);
        }

        try prepareSplitDestination(self, range2, dest_dir2);
        if (prepare_only) return;

        try finalizeSplitLocked(self, .{
            .start = curr_range.start,
            .end = split_key,
        });
    }

    pub fn finalizeSplit(self: *DB, new_range: types.ByteRange) !void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        var snapshot_mutation = self.core.snapshot_admission.acquireMutation();
        defer snapshot_mutation.release();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        try finalizeSplitLocked(self, new_range);
    }

    pub fn snapshot(self: *DB, id: []const u8) !u64 {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        defer row_policy_lease.release();
        return try self.snapshotInternal(id, false, .none, null, null, false);
    }

    /// Drain durable replay/enrichment effects before a caller freezes writes
    /// for snapshot capture. Background completion can itself mutate storage,
    /// so callers must drain before taking an exclusive mutation barrier.
    /// The deadline is in this DB's BackendRuntime.monotonicClock domain.
    pub fn drainSnapshotMaintenance(self: *DB, deadline_ns: u64) !void {
        while (true) {
            self.runMaintenanceUntilWithCancellation(
                self.currentMaintenanceTargetSequence(),
                .{},
                .none,
                deadline_ns,
            ) catch |err| switch (err) {
                // A retryable provider failure has already committed its
                // source mutation. Seed preflight is the safe place to absorb
                // that finite retry: returning it to the operator adds a full
                // reconciliation round trip, while waiting after the global
                // barrier closes would deadlock its eventual publication.
                error.EnrichmentRetryInProgress => {
                    const wait_clock = self.backend_runtime.monotonicClock();
                    const now_ns = wait_clock.nowRealtimeNs();
                    if (now_ns >= deadline_ns) return error.EnrichmentWaitTimeout;
                    const sleep_ns = @min(25 * std.time.ns_per_ms, deadline_ns - now_ns);
                    wait_clock.sleepMs(@max(1, @divTrunc(sleep_ns +| std.time.ns_per_ms - 1, std.time.ns_per_ms)));
                    continue;
                },
                else => return err,
            };
            return;
        }
    }

    /// Capture a portable snapshot with bounded maintenance verification.
    /// Callers drain maintenance before freezing writes; this deadline bounds
    /// any follow-up work that raced with their capture barrier.
    /// The deadline is in this DB's BackendRuntime.monotonicClock domain.
    pub fn snapshotWithMaintenanceDeadline(self: *DB, id: []const u8, maintenance_deadline_ns: u64) !u64 {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        defer row_policy_lease.release();
        return try self.snapshotInternal(id, false, .none, maintenance_deadline_ns, null, false);
    }

    /// Captures the primary store and its validated generated projections as
    /// one self-contained generation for the native table-backup format.
    pub fn snapshotNative(self: *DB, id: []const u8) !u64 {
        return try self.snapshotNativeWithCancellation(id, .none);
    }

    pub fn snapshotNativeWithCancellation(self: *DB, id: []const u8, cancellation: types.CancellationToken) !u64 {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        defer row_policy_lease.release();
        return try self.snapshotInternal(id, true, cancellation, null, null, false);
    }

    /// Cohort capture verifies the exact durable owner fence and drained
    /// participant set under the same apply lock that pins the native root.
    pub fn snapshotRelationalCohort(self: *DB, id: []const u8, expected: @import("relational_integrity_topology.zig").Fence, cancellation: types.CancellationToken) !u64 {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        defer row_policy_lease.release();
        if (expected.role != .backup_snapshot) return error.InvalidIntegrityTopologyFence;
        return try self.snapshotInternal(id, true, cancellation, null, expected, false);
    }

    /// Seal an exact common-cut owner generation durably. No corpus copy or
    /// hashing is performed while the write fence is held.
    pub fn sealBackupCohort(self: *DB, id: []const u8, expected: @import("relational_integrity_topology.zig").Fence, cancellation: types.CancellationToken) !@import("native_backup_seal.zig").Handle {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        defer row_policy_lease.release();
        try validateSnapshotId(id);
        if (expected.role != .backup_snapshot or !expected.namespace.eql(self.core.identity_namespace)) return error.InvalidTopologyFence;
        const seal = @import("native_backup_seal.zig");
        const name = try seal.nameAlloc(self.alloc, expected);
        defer self.alloc.free(name);
        _ = try self.snapshotInternal(name, true, cancellation, null, expected, true);
        const root = try seal.pathAlloc(self.alloc, self.core.path, expected);
        defer self.alloc.free(root);
        const io = self.backend_runtime.filesystemIo() orelse return error.BackendRuntimeIoUnavailable;
        return seal.readHandle(self.alloc, io, root, expected);
    }

    pub fn exportBackupCohort(self: *DB, handle: @import("native_backup_seal.zig").Handle, id: []const u8, cancellation: types.CancellationToken) !u64 {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRawRead();
        defer row_policy_lease.release();
        const checkpoint: RowPolicyOutputCheckpoint = .{ .upstream = cancellation, .lease = &row_policy_lease };
        const output_cancellation = checkpoint.token();
        if (!handle.fence.namespace.eql(self.core.identity_namespace)) return error.IdentityNamespaceMismatch;
        try validateSnapshotId(id);
        try lockAtomicWithCancellation(&self.snapshot_publication_mutex, cancellation);
        defer self.snapshot_publication_mutex.unlock();
        const seal = @import("native_backup_seal.zig");
        const io = self.backend_runtime.filesystemIo() orelse return error.BackendRuntimeIoUnavailable;
        var pin_lock = try seal.StoreLock.acquire(self.alloc, io, self.core.path, cancellation);
        defer pin_lock.deinit();
        const root = try seal.pathAlloc(self.alloc, self.core.path, handle.fence);
        defer self.alloc.free(root);
        const tombstone = try std.fmt.allocPrint(self.alloc, "{s}.released", .{root});
        defer self.alloc.free(tombstone);
        if (try snapshotPathExists(io, tombstone)) return error.BackupSealReleased;
        const parent = try std.fmt.allocPrint(self.alloc, "{s}.snapshots", .{self.core.path});
        defer self.alloc.free(parent);
        try fs_paths.createDirPathPortable(io, parent);
        const target = try std.fmt.allocPrint(self.alloc, "{s}/{s}", .{ parent, id });
        defer self.alloc.free(target);
        if (try snapshotPathExists(io, target)) {
            const bytes = try seal.exportedBytes(self.alloc, io, target, handle);
            try output_cancellation.check();
            return bytes;
        }
        const staging = try createSnapshotStagingRoot(self.alloc, io, parent, id);
        defer self.alloc.free(staging);
        var published = false;
        defer if (!published) snapshot_staging.cleanup(io, staging);
        const total = try seal.exportTo(self.alloc, io, root, handle, staging, output_cancellation);
        try seal.recordExport(self.alloc, io, staging, handle, total);
        try output_cancellation.check();
        try publishSnapshotStaging(io, parent, staging, target);
        published = true;
        return total;
    }

    /// Portable logical rows from the identical immutable cut used by native
    /// cohorts. The live root may already have resumed writes at this point.
    pub fn exportBackupCohortPortable(self: *DB, handle: @import("native_backup_seal.zig").Handle, writer: *std.Io.Writer, options: portable_backup.ExportOptions, cancellation: types.CancellationToken) !void {
        if (options.source_generation_summary_output) |summary| summary.output.* = null;
        errdefer if (options.source_generation_summary_output) |summary| if (summary.output.*) |entries| {
            portable_backup.freeSourceGenerationAdmissionSummary(summary.alloc, entries);
            summary.output.* = null;
        };
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRawRead();
        defer row_policy_lease.release();
        const checkpoint: RowPolicyOutputCheckpoint = .{ .upstream = cancellation, .lease = &row_policy_lease };
        const output_cancellation = checkpoint.token();
        if (options.source_certificate) |certificate| certificate.output.* = null;
        errdefer if (options.source_certificate) |certificate| {
            certificate.output.* = null;
        };
        if (!handle.fence.namespace.eql(self.core.identity_namespace)) return error.IdentityNamespaceMismatch;
        try lockAtomicWithCancellation(&self.snapshot_publication_mutex, cancellation);
        defer self.snapshot_publication_mutex.unlock();
        const seal = @import("native_backup_seal.zig");
        const io = self.backend_runtime.filesystemIo() orelse return error.BackendRuntimeIoUnavailable;
        var pin_lock = try seal.StoreLock.acquire(self.alloc, io, self.core.path, cancellation);
        defer pin_lock.deinit();
        const root = try seal.pathAlloc(self.alloc, self.core.path, handle.fence);
        defer self.alloc.free(root);
        const tombstone = try std.fmt.allocPrint(self.alloc, "{s}.released", .{root});
        defer self.alloc.free(tombstone);
        if (try snapshotPathExists(io, tombstone)) return error.BackupSealReleased;
        var opened = try seal.open(self.alloc, io, root, handle);
        defer opened.deinit();
        for (opened.parsed.value.files) |file| {
            try cancellation.check();
            const path = try std.fmt.allocPrint(self.alloc, "{s}/{s}", .{ root, file.path });
            defer self.alloc.free(path);
            const stat = try native_backup.statRegularFile(io, path);
            if (stat.inode != file.inode or stat.size != file.size or stat.mtime.toNanoseconds() != file.mtime_ns) return error.BackupSealSourceChanged;
        }
        var export_options = options;
        export_options.cancellation = output_cancellation;
        export_options.cohort = .{ .seal = handle, .namespace = handle.fence.namespace };
        if (std.mem.eql(u8, opened.parsed.value.primary.artifact_format, "antfly-lsm-checkpoint")) {
            const primary = try std.fmt.allocPrint(self.alloc, "{s}/{s}", .{ root, db_core.primary_lsm_checkpoint_directory_name });
            defer self.alloc.free(primary);
            var backend = try @import("../lsm_backend.zig").Backend.open(self.alloc, primary, .{ .backend = .{ .read_only = true }, .read_runtime = @import("../lsm_backend/storage_io.zig").ReadRuntime.init(io) });
            defer backend.close();
            var store = try docstore_mod.DocStore.openRuntime(self.alloc, try backend.runtimeStore(self.alloc, .{ .name = "docs" }));
            defer store.close();
            try portable_backup.exportPortableToWriterWithOptions(self.alloc, &store, writer, export_options);
        } else if (std.mem.eql(u8, opened.parsed.value.primary.artifact_format, "antfly-kv-stream")) {
            // Logical-backend pins are already a bounded KV stream. Decode
            // into disposable LSM storage, never an in-memory corpus buffer.
            const parent = std.fs.path.dirname(root) orelse return error.InvalidBackupSeal;
            const temporary = try createSnapshotStagingRoot(self.alloc, io, parent, "portable-decoder");
            defer self.alloc.free(temporary);
            defer snapshot_staging.cleanup(io, temporary);
            var backend = try @import("../lsm_backend.zig").Backend.open(self.alloc, temporary, .{ .read_runtime = @import("../lsm_backend/storage_io.zig").ReadRuntime.init(io) });
            defer backend.close();
            var store = try docstore_mod.DocStore.openRuntime(self.alloc, try backend.runtimeStore(self.alloc, .{ .name = "docs" }));
            defer store.close();
            _ = try db_core.importStoreSnapshotWithIo(self.alloc, io, &store, root, cancellation);
            try portable_backup.exportPortableToWriterWithOptions(self.alloc, &store, writer, export_options);
        } else return error.UnsupportedBackupFormat;
        try output_cancellation.check();
    }

    /// Tombstone before unlink: retries after a crash finish bounded inventory
    /// cleanup, and a delayed seal can never recreate an acknowledged release.
    pub fn releaseBackupCohort(self: *DB, handle: @import("native_backup_seal.zig").Handle) !void {
        if (!handle.fence.namespace.eql(self.core.identity_namespace)) return error.IdentityNamespaceMismatch;
        lockAtomicWithBackoff(&self.snapshot_publication_mutex);
        defer self.snapshot_publication_mutex.unlock();
        const seal = @import("native_backup_seal.zig");
        const io = self.backend_runtime.filesystemIo() orelse return error.BackendRuntimeIoUnavailable;
        try seal.reclaim(self.alloc, io, self.core.path, .{ .release = handle }, .none);
    }

    /// Cancellation consumes a planned seal even when its response was lost
    /// or delivery is delayed. Caller authority is the exact cohort fence.
    pub fn cancelBackupCohort(self: *DB, fence: @import("relational_integrity_topology.zig").Fence) !void {
        if (fence.role != .backup_snapshot or !fence.namespace.eql(self.core.identity_namespace)) return error.IdentityNamespaceMismatch;
        lockAtomicWithBackoff(&self.snapshot_publication_mutex);
        defer self.snapshot_publication_mutex.unlock();
        const seal = @import("native_backup_seal.zig");
        const io = self.backend_runtime.filesystemIo() orelse return error.BackendRuntimeIoUnavailable;
        try seal.reclaim(self.alloc, io, self.core.path, .{ .cancel = fence }, .none);
    }

    const SnapshotFenceTestHook = struct {
        ptr: *anyopaque,
        after_capture_admission: *const fn (*anyopaque) void,
        after_apply_release: ?*const fn (*anyopaque) void = null,
        before_artifact_materialize: ?*const fn (*anyopaque) void = null,
    };
    var test_snapshot_fence_hook: ?SnapshotFenceTestHook = null;

    fn primaryOnlySnapshotSupportedLocked(self: *DB) !bool {
        if (self.local_execution.table_storage.dense_embeddings != .primary_lsm) return false;
        if (self.local_execution.source_vectors.load(.acquire) == null) return true;
        // Cancellation retains the source object for already-admitted readers
        // and background retirement. Its presence is not published authority:
        // a terminal cancelled job has removed all candidate roots and kept
        // every live artifact inline in the primary store.
        var job = (try vector_migration.load(self.alloc, self.core.store)) orelse return false;
        defer job.deinit();
        try self.validateVectorMigrationIdentity(job.value);
        return job.value.phase == .cancelled;
    }

    fn ensurePrimaryOnlySnapshotLocked(self: *DB) !void {
        var read = try self.core.store.beginReadTxn();
        defer read.abort();
        try @import("artifact_reconcile_intent.zig").requireAbsent(&read);
        if (!try self.primaryOnlySnapshotSupportedLocked()) return error.VectorStoreLifecycleUnsupported;
    }

    fn ensurePrimaryOnlySnapshot(self: *DB) !void {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        try self.ensurePrimaryOnlySnapshotLocked();
    }

    fn snapshotInternal(
        self: *DB,
        id: []const u8,
        include_generated: bool,
        cancellation: types.CancellationToken,
        maintenance_deadline_ns: ?u64,
        expected_topology_fence: ?@import("relational_integrity_topology.zig").Fence,
        seal_only: bool,
    ) !u64 {
        try self.ensurePrimaryOnlySnapshot();
        // Serialize only snapshot construction/publication. Normal writes can
        // resume before native manifest hashing, while same-ID captures cannot
        // race the fresh-directory check or atomic rename.
        try lockAtomicWithCancellation(&self.snapshot_publication_mutex, cancellation);
        defer self.snapshot_publication_mutex.unlock();
        try ensureSnapshotActive(cancellation);
        try validateSnapshotId(id);
        if (include_generated) {
            // Host-path exchange is the only native publication adapter
            // currently implemented. External stores need a backend-owned
            // staged namespace and atomic generation pointer; until that
            // capability exists, fail before creating or syncing artifacts.
            if (self.physical_root_mode != .filesystem_managed)
                return error.NativeBackupStorageBackendUnsupported;
            if (self.primary_lsm_storage) |storage| {
                if (!storage.supportsHostPathGenerationPublication()) {
                    std.log.err(
                        "native backup requires atomic host-path generation publication for primary storage",
                        .{},
                    );
                    return error.NativeBackupStorageBackendUnsupported;
                }
            }
        }
        const io = self.backend_runtime.filesystemIo() orelse return error.BackendRuntimeIoUnavailable;
        const snapshot_parent = try std.fmt.allocPrint(self.alloc, "{s}.{s}", .{ self.core.path, if (seal_only) "backup-pins" else "snapshots" });
        defer self.alloc.free(snapshot_parent);
        var pin_lock: ?@import("native_backup_seal.zig").StoreLock = if (seal_only) try @import("native_backup_seal.zig").StoreLock.acquire(self.alloc, io, self.core.path, cancellation) else null;
        defer if (pin_lock) |*held| held.deinit();
        const snapshot_root = try std.fmt.allocPrint(self.alloc, "{s}/{s}", .{ snapshot_parent, id });
        defer self.alloc.free(snapshot_root);
        try fs_paths.createDirPathPortable(io, snapshot_parent);
        if (seal_only) {
            const tombstone = try std.fmt.allocPrint(self.alloc, "{s}.released", .{snapshot_root});
            defer self.alloc.free(tombstone);
            if (try snapshotPathExists(io, tombstone)) return error.BackupSealReleased;
            if (try snapshotPathExists(io, snapshot_root)) {
                _ = try @import("native_backup_seal.zig").readHandle(self.alloc, io, snapshot_root, expected_topology_fence.?);
                return 0;
            }
        } else if (try snapshotPathExists(io, snapshot_root)) return error.SnapshotAlreadyExists;
        const staging_root = if (seal_only) blk: {
            // One deterministic unpublished namespace per exact attempt lets
            // restart/retry reclaim abandoned pins without a directory scan.
            const candidate = try std.fmt.allocPrint(self.alloc, "{s}.staging", .{snapshot_root});
            errdefer self.alloc.free(candidate);
            try std.Io.Dir.cwd().deleteTree(io, candidate);
            try fs_paths.createDirPathPortable(io, candidate);
            try fs_paths.syncDirPortable(io, snapshot_parent);
            break :blk candidate;
        } else try createSnapshotStagingRoot(self.alloc, io, snapshot_parent, id);
        defer self.alloc.free(staging_root);
        var published = false;
        defer if (!published) snapshot_staging.cleanup(io, staging_root);

        if (!include_generated) {
            // Portable snapshots omit generated files, but their replay log and
            // durable watermarks must still describe a converged generation so
            // restore can deterministically rebuild every managed projection.
            if (maintenance_deadline_ns) |deadline_ns| {
                try self.runMaintenanceUntilWithCancellation(
                    self.currentMaintenanceTargetSequence(),
                    .{},
                    cancellation,
                    deadline_ns,
                );
            } else {
                try self.runMaintenanceUntil(self.currentMaintenanceTargetSequence(), .{});
            }
            try self.lockApplyForPortableRuntime();
            var apply_held = true;
            defer if (apply_held) self.core.unlockApply();
            // Migration may have started while portable maintenance drained.
            try self.ensurePrimaryOnlySnapshotLocked();
            try self.core.syncStore(true);
            try self.core.index_manager.syncAll(true);
            var primary_snapshot = try self.core.pinPortableSnapshot();
            defer primary_snapshot.deinit();
            self.core.unlockApply();
            apply_held = false;
            var total = try primary_snapshot.materialize(
                self.alloc,
                io,
                staging_root,
                cancellation,
            );
            total = std.math.add(
                u64,
                total,
                try db_core.writeLogicalSnapshotManifest(self.alloc, io, staging_root),
            ) catch return error.SnapshotTooLarge;
            try publishSnapshotStaging(io, snapshot_parent, staging_root, snapshot_root);
            published = true;
            return total;
        }

        // Close primary/catalog admission before selecting the target. The
        // barrier is writer preferring, so continuous client traffic cannot
        // starve capture. Internal enrichment and resolution callbacks remain
        // admitted while maintenance drains already-committed work.
        var capture = self.core.snapshot_admission.acquireCaptureIo(io, @as(?types.CancellationToken, cancellation)) catch |err| switch (err) {
            error.Cancelled => return error.Canceled,
            else => return err,
        };
        defer capture.release();
        // Migration may have won admission after the optimistic entry check.
        // Its structural mutation uses this same snapshot fence.
        try self.ensurePrimaryOnlySnapshot();
        if (builtin.is_test) {
            if (test_snapshot_fence_hook) |hook| hook.after_capture_admission(hook.ptr);
        }

        var structural: ?IndexStructuralMutationGuard = null;
        defer if (structural) |*guard| guard.release();
        var replay_capture: ?snapshot_admission_mod.SnapshotAdmission.CaptureLease = null;
        defer if (replay_capture) |*lease| lease.release();
        var apply_held = false;
        defer if (apply_held) self.core.unlockApply();
        var capture_target_sequence: u64 = undefined;

        // An internal callback can append a finite follow-up replay record
        // during the drain. Recheck under the final apply fence; unlike the old
        // optimistic loop, primary writes and catalog churn are already barred,
        // so an external write stream cannot keep this loop alive forever.
        while (true) {
            const target_sequence = self.currentMaintenanceTargetSequence();
            self.runMaintenanceUntilWithCancellation(
                target_sequence,
                .{},
                cancellation,
                std.math.maxInt(u64),
            ) catch |err| switch (err) {
                error.Cancelled => return error.Canceled,
                else => return err,
            };
            try ensureSnapshotActive(cancellation);
            try self.flushAppliedSequencesForIdle();

            structural = self.beginDrainedIndexStructuralMutationWithLease("native snapshot", "*", capture.borrowMutation());
            if (!structural.?.acquireCatalogBarrierUntil(std.math.maxInt(u64))) unreachable;
            replay_capture = self.core.snapshot_replay_admission.acquireCaptureIo(
                io,
                @as(?types.CancellationToken, cancellation),
            ) catch |err| switch (err) {
                error.Cancelled => return error.Canceled,
                else => return err,
            };
            try self.lockApplyForPortableRuntime();
            apply_held = true;
            if (self.currentMaintenanceTargetSequence() == target_sequence) {
                capture_target_sequence = self.core.nextDerivedSequence();
                break;
            }
            self.core.unlockApply();
            apply_held = false;
            replay_capture.?.release();
            replay_capture = null;
            structural.?.release();
            structural = null;
        }

        try self.ensurePrimaryOnlySnapshotLocked();
        if (expected_topology_fence) |expected| {
            var read = try self.core.store.beginProbeTxn();
            defer read.abort();
            var manager = try self.core.initTxnManager();
            defer manager.deinit();
            try @import("relational_integrity_topology.zig").requireDrained(&read, &manager, expected);
        }
        try self.core.syncStore(true);
        try self.core.index_manager.syncAll(true);
        if (self.loadIndexRepairState(self.alloc)) |repair_state_value| {
            var repair_state = repair_state_value;
            defer repair_state.deinit(self.alloc);
            if (repair_state.entries.items.len != 0)
                return error.NativeBackupRepairStateNotQuiescent;
        } else |err| switch (err) {
            error.FileNotFound, error.DurableIndexRepairStateUnavailable => {},
            else => return err,
        }

        // Pin the primary MVCC/read-snapshot while the selected revision is
        // fenced. Its corpus-sized serialization happens only after writers
        // resume and therefore does not extend write unavailability.
        var primary_snapshot = try self.core.pinNativeSnapshot();
        defer primary_snapshot.deinit();
        if (comptime builtin.os.tag == .freestanding) {
            self.core.unlockApply();
            apply_held = false;
            replay_capture.?.release();
            replay_capture = null;
            structural.?.release();
            structural = null;
            capture.release();
            const total = try primary_snapshot.materialize(
                self.alloc,
                io,
                staging_root,
                cancellation,
            );
            try publishSnapshotStaging(io, snapshot_parent, staging_root, snapshot_root);
            published = true;
            return total;
        }

        const configs = try self.core.listIndexes(self.alloc);
        defer types.freeIndexConfigs(self.alloc, configs);
        const projections = try self.alloc.alloc(native_backup.Projection, configs.len);
        defer self.alloc.free(projections);
        for (configs, 0..) |cfg, i| {
            const checkpoint = try self.core.loadProjectionCheckpoint(self.alloc, cfg.name);
            if (checkpoint.status != .clean or
                checkpoint.config_hash != types.indexConfigHash(cfg) or
                checkpoint.applied_sequence != capture_target_sequence)
            {
                std.log.warn(
                    "native backup projection is not quiescent index={s} status={s} checkpoint_sequence={} target_sequence={} checkpoint_config_hash={x} expected_config_hash={x}",
                    .{
                        cfg.name,
                        @tagName(checkpoint.status),
                        checkpoint.applied_sequence,
                        capture_target_sequence,
                        checkpoint.config_hash,
                        types.indexConfigHash(cfg),
                    },
                );
                return error.NativeBackupProjectionNotQuiescent;
            }
            const backend_id = self.core.index_manager.nativeBackupBackendId(cfg.name, cfg.kind);
            const has_immutable_checkpoint = self.core.index_manager.nativeBackupSupportsImmutableCheckpoint(cfg.name, cfg.kind);
            if (!has_immutable_checkpoint) {
                std.log.err(
                    "native backup requires an immutable projection checkpoint index={s} kind={s} backend={s}",
                    .{ cfg.name, @tagName(cfg.kind), backend_id },
                );
                return error.NativeBackupProjectionBackendUnsupported;
            }
            projections[i] = .{
                .name = cfg.name,
                .kind = @tagName(cfg.kind),
                .config_hash = types.indexConfigHash(cfg),
                .coverage_generation = cfg.coverage_generation,
                .checkpoint_generation = checkpoint.generation,
                .applied_sequence = checkpoint.applied_sequence,
                .target_sequence = capture_target_sequence,
                .artifact_format = "antfly-managed-index-tree",
                .artifact_version = 1,
                .backend_id = backend_id,
                .codec_version = 1,
                .artifact_state = .complete,
                .repair_reason = "",
            };
        }
        std.mem.sort(native_backup.Projection, projections, {}, struct {
            fn lessThan(_: void, lhs: native_backup.Projection, rhs: native_backup.Projection) bool {
                return std.mem.order(u8, lhs.name, rhs.name) == .lt;
            }
        }.lessThan);

        // Ask each backend to retain its exact manifested generation. Pinning
        // is bounded by backend/run metadata: it hardlinks manifest-named
        // immutable files and opens stable committed-WAL descriptor leases
        // without reading corpus or WAL payloads under the mutation fence.
        const generated_native_pin_root = try std.fmt.allocPrint(self.alloc, "{s}/.generated-native-pin", .{staging_root});
        defer self.alloc.free(generated_native_pin_root);
        var generated_checkpoints = try self.core.index_manager.pinNativeBackupCheckpoints(
            io,
            generated_native_pin_root,
            capture_target_sequence,
            cancellation,
        );
        defer generated_checkpoints.deinit();
        const generated_metadata_pin_root = try std.fmt.allocPrint(self.alloc, "{s}/.generated-metadata-pin", .{staging_root});
        defer self.alloc.free(generated_metadata_pin_root);
        var generated_metadata = try native_backup.pinGeneratedCheckpointMetadata(
            self.alloc,
            io,
            self.core.path,
            generated_metadata_pin_root,
            cancellation,
        );
        defer generated_metadata.deinit();

        if (seal_only) {
            const seal = @import("native_backup_seal.zig");
            const wal_bytes = try generated_checkpoints.walPrefixBytes();
            if (wal_bytes > seal.wal_budget_bytes) return error.BackupSealWalBudgetExceeded;
            const primary_root = try std.fmt.allocPrint(self.alloc, "{s}/primary-lsm", .{staging_root});
            defer self.alloc.free(primary_root);
            var total: u64 = switch (primary_snapshot) {
                .lsm => |*checkpoint| try checkpoint.seal(io, primary_root, cancellation),
                .logical => return error.BackupSealBackendUnsupported,
            };
            total = std.math.add(u64, total, try generated_checkpoints.seal(io, staging_root, cancellation, seal.wal_budget_bytes)) catch return error.FileTooBig;
            total = std.math.add(u64, total, try generated_metadata.seal(staging_root, cancellation, 0)) catch return error.FileTooBig;
            // The durable tree has its own links; discard temporary lease
            // trees before its inventory and atomic publication.
            try std.Io.Dir.cwd().deleteTree(io, generated_native_pin_root);
            try std.Io.Dir.cwd().deleteTree(io, generated_metadata_pin_root);
            _ = try seal.finish(self.alloc, io, staging_root, expected_topology_fence.?, capture_target_sequence, .{
                .artifact_format = primary_snapshot.artifactFormat(),
                .artifact_version = primary_snapshot.artifactVersion(),
                .source_backend = @tagName(self.primary_backend),
            }, projections, cancellation);
            try publishSnapshotStaging(io, snapshot_parent, staging_root, snapshot_root);
            published = true;
            return total;
        }

        // The primary store and hardlink-pinned generated files now form one
        // stable generation. Release the latency-sensitive apply lock first,
        // then all mutation admission before reading corpus bytes.
        self.core.unlockApply();
        apply_held = false;
        if (builtin.is_test) {
            if (test_snapshot_fence_hook) |hook| {
                if (hook.after_apply_release) |run| run(hook.ptr);
            }
        }

        replay_capture.?.release();
        replay_capture = null;
        structural.?.release();
        structural = null;
        capture.release();

        // Both primary and generated artifacts remain pinned. Expensive file
        // copies, primary serialization, hashing, and manifest encoding stay
        // off both the apply lock and mutation-admission paths.
        if (builtin.is_test) {
            if (test_snapshot_fence_hook) |hook| {
                if (hook.before_artifact_materialize) |run| run(hook.ptr);
            }
        }
        var artifact_receipts = native_backup.ArtifactReceiptCollector.init(
            self.alloc,
            staging_root,
            projections,
        );
        defer artifact_receipts.deinit();
        const receipt_sink = artifact_receipts.sink();
        var total = try generated_checkpoints.materializeWithSink(io, staging_root, cancellation, receipt_sink);
        total = std.math.add(
            u64,
            total,
            try generated_metadata.materializeWithSink(staging_root, cancellation, receipt_sink),
        ) catch return error.FileTooBig;
        total = std.math.add(u64, total, try primary_snapshot.materializeWithSink(
            self.alloc,
            io,
            staging_root,
            cancellation,
            receipt_sink,
        )) catch return error.FileTooBig;
        total = std.math.add(u64, total, try native_backup.finalizeCaptureGenerationFromReceiptsWithCancellation(
            self.alloc,
            io,
            &artifact_receipts,
            capture_target_sequence,
            .{
                .artifact_format = primary_snapshot.artifactFormat(),
                .artifact_version = primary_snapshot.artifactVersion(),
                .source_backend = @tagName(self.primary_backend),
            },
            cancellation,
        )) catch return error.FileTooBig;
        try ensureSnapshotActive(cancellation);
        try publishSnapshotStaging(io, snapshot_parent, staging_root, snapshot_root);
        published = true;
        return total;
    }

    pub fn sync(self: *DB, full: bool) !void {
        if (full) if (self.local_execution.source_vectors.load(.acquire)) |source| try source.advanceMarkingSnapshot();
        lockApply(self);
        defer self.core.unlockApply();
        try self.core.syncStore(full);
        if (self.local_execution.source_vectors.load(.acquire)) |source| {
            try source.checkpoint();
            if (full) {
                try self.refreshSourceVectorOwnershipScopes();
                if (try source.collectDeferredMark(&self.core.store.runtime_store)) try self.core.index_manager.refreshSourcePayloadGeneration();
            }
        }
    }

    pub fn syncIndexes(self: *DB, force: bool) !void {
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        try self.core.index_manager.syncAll(force);
    }

    pub const PreparedMergeArtifacts = local_mutation.PreparedMergeArtifacts;

    pub const prepareMergeArtifactEffects = local_mutation.prepareMergeArtifactEffects;

    fn prepareMergePageChunk(self: *DB, alloc: Allocator, req: types.BatchRequest, cancellation: types.CancellationToken) !@import("merge_page_chunks.zig").Prepared {
        const chunks = @import("merge_page_chunks.zig");
        self.core.lockApplyShared();
        var locked = true;
        defer if (locked) self.core.unlockApplyShared();
        var txn = try self.core.store.beginReadTxnWithBlockCacheAdmission(.transient);
        defer txn.abort();
        const raw = txn.get(merge_state_mod.key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        var state = if (raw) |value| try merge_state_mod.decodeAlloc(alloc, value) else null;
        defer if (state) |*value| value.deinit(alloc);
        const allowed = merge_state_mod.copyAllowed(state, req.merge_replication.?);
        self.core.unlockApplyShared();
        locked = false;
        // The regular apply fence retains its existing committed-stale-entry
        // no-op behavior, without trying to read a discarded attempt's spool.
        if (!allowed) return chunks.Prepared.init(alloc, req);
        var reader: chunks.NativeReader = .{ .txn = &txn };
        return chunks.prepare(alloc, &reader, req, cancellation);
    }

    pub fn mergeCopyPageStatus(self: *DB, alloc: Allocator) !?std.json.Parsed(@import("merge_page_contract.zig").Progress) {
        const pages = @import("merge_page_contract.zig");
        const raw = (try self.core.getStoreValue(alloc, pages.key)) orelse return null;
        defer alloc.free(raw);
        return try pages.decode(alloc, raw);
    }

    /// Receiver-owned cleanup must prove it did not skip any document-owned
    /// rows, including artifacts whose owner has no primary row. The cursor
    /// and deletes are checked under their commit fence;
    /// exhaustion is never accepted solely on a sender's assertion.
    pub const validateMergeCleanupPageLocked = local_mutation.validateMergeCleanupPageLocked;

    /// Raw primary outcomes for a transition snapshot. Do not use public scan
    /// projection here: it can hydrate derived fields into the returned JSON.
    pub fn mergeDocumentsPage(self: *DB, alloc: Allocator, byte_range: types.ByteRange, after_key: ?[]const u8) ![]types.BatchWrite {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        const lower = if (after_key) |key| try internal_keys.documentKeyAlloc(alloc, key) else try documentRangeLowerAlloc(alloc, byte_range.start);
        defer alloc.free(lower);
        const upper = if (byte_range.end.len > 0) try documentRangeUpperAlloc(alloc, byte_range.end) else null;
        defer if (upper) |key| alloc.free(key);
        var txn = try self.core.store.beginReadTxn();
        defer txn.abort();
        var cursor = try txn.openCursor();
        defer cursor.close();
        cursor.setUpperBound(upper);
        var rows = std.ArrayListUnmanaged(types.BatchWrite).empty;
        errdefer {
            for (rows.items) |row| {
                alloc.free(row.key);
                alloc.free(row.value);
            }
            rows.deinit(alloc);
        }
        var bytes: usize = 0;
        var next = try cursor.seekAtOrAfter(lower);
        while (next) |row| : (next = try cursor.next()) {
            if (upper) |bound| if (std.mem.order(u8, row.key, bound) != .lt) break;
            if (!internal_keys.isStoredDocumentRowKey(row.key)) continue;
            const key = (try internal_keys.decodeStoredDocumentRowKeyAlloc(alloc, row.key)).?;
            errdefer alloc.free(key);
            if (after_key) |after| if (std.mem.order(u8, key, after) != .gt) {
                alloc.free(key);
                continue;
            };
            const value = if (internal_keys.isRelationalRowKey(row.key)) blk: {
                const version = try relational_store.rowSchemaVersion(row.value);
                var view = (try self.core.acquireSchemaVersionView(version)) orelse return error.UnknownSchemaVersion;
                defer view.release();
                const typed = try relational_row_codec.ordinalRowView(row.value, view.tableSchema().*, view.physicalLayout());
                break :blk try typed.reconstructValueAlloc(alloc);
            } else try alloc.dupe(u8, row.value);
            errdefer alloc.free(value);
            try rows.append(alloc, .{ .key = key, .value = value });
            bytes +|= key.len +| value.len;
            if (rows.items.len >= 128 or bytes >= 1024 * 1024) break;
        }
        return rows.toOwnedSlice(alloc);
    }

    /// Enumerate receiver-owned physical keys for replicated merge rollback.
    /// Values are logical owners (or empty for a non-document key); the key is
    /// the exclusive physical continuation. This pages physical visits rather
    /// than only primary documents, so artifact-only owners cannot be skipped.
    pub fn mergeCleanupKeysPage(
        self: *DB,
        alloc: Allocator,
        byte_range: types.ByteRange,
        after_key: ?[]const u8,
    ) ![]types.BatchWrite {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        const lower = try documentRangeLowerAlloc(alloc, byte_range.start);
        defer alloc.free(lower);
        const upper = if (byte_range.end.len > 0) try documentRangeLowerAlloc(alloc, byte_range.end) else null;
        defer if (upper) |key| alloc.free(key);
        var txn = try self.core.store.beginReadTxn();
        defer txn.abort();
        var cursor = try txn.openPhysicalCursorAdapter();
        defer cursor.close();
        cursor.setUpperBound(upper);
        var rows = std.ArrayListUnmanaged(types.BatchWrite).empty;
        errdefer {
            for (rows.items) |row| {
                alloc.free(row.key);
                alloc.free(row.value);
            }
            rows.deinit(alloc);
        }
        var bytes: usize = 0;
        var next = try cursor.seekAtOrAfter(after_key orelse lower);
        while (next) |row| : (next = try cursor.next()) {
            if (upper) |bound| if (std.mem.order(u8, row.key, bound) != .lt) break;
            if (!std.mem.startsWith(u8, row.key, &.{internal_keys.user_namespace})) break;
            if (after_key) |after| if (std.mem.order(u8, row.key, after) != .gt) continue;
            const owner = (try internal_keys.decodeDocumentComponentAlloc(alloc, row.key)) orelse try alloc.dupe(u8, "");
            errdefer alloc.free(owner);
            const key = try alloc.dupe(u8, row.key);
            errdefer alloc.free(key);
            try rows.append(alloc, .{ .key = key, .value = owner });
            bytes +|= key.len +| owner.len;
            if (rows.items.len >= 128 or bytes >= 1024 * 1024) break;
        }
        return rows.toOwnedSlice(alloc);
    }

    /// Returns a bounded page of authoritative artifacts under a transition
    /// lease. The continuation is an exclusive physical store key. One large
    /// row may exceed the byte budget so pagination always makes progress.
    pub fn mergeArtifactsPage(
        self: *DB,
        alloc: Allocator,
        byte_range: types.ByteRange,
        after_key: ?[]const u8,
    ) ![]types.BatchWrite {
        // Export only an admitted primary snapshot. Revalidate under the apply
        // lease so recovery publication cannot race the page's admission.
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        const lower = try documentRangeLowerAlloc(alloc, byte_range.start);
        defer alloc.free(lower);
        const upper = if (byte_range.end.len > 0) try documentRangeUpperAlloc(alloc, byte_range.end) else null;
        defer if (upper) |key| alloc.free(key);
        var txn = try self.core.store.beginReadTxn();
        defer txn.abort();
        var cursor = try txn.openCursor();
        defer cursor.close();
        cursor.setUpperBound(upper);
        var rows = std.ArrayListUnmanaged(types.BatchWrite).empty;
        errdefer {
            for (rows.items) |row| {
                alloc.free(row.key);
                alloc.free(row.value);
            }
            rows.deinit(alloc);
        }
        var bytes: usize = 0;
        var next = try cursor.seekAtOrAfter(after_key orelse lower);
        while (next) |row| : (next = try cursor.next()) {
            if (upper) |bound| if (std.mem.order(u8, row.key, bound) != .lt) break;
            if (after_key) |key| if (std.mem.order(u8, row.key, key) != .gt) continue;
            if (!isMergeArtifactKey(row.key)) continue;
            if (internal_keys.isGraphRetirementKey(row.key)) _ = try @import("../graph_cleanup_contract.zig").retirementGeneration(row.value);
            const value = if (internal_keys.isGraphEdgeArtifactKey(row.key)) graph: {
                const edge = (try internal_keys.parseGraphEdgeArtifactKeyAlloc(alloc, row.key)) orelse return error.InvalidBatchRequest;
                defer {
                    alloc.free(edge.doc_key);
                    alloc.free(edge.index_name);
                    alloc.free(edge.edge_type);
                    alloc.free(edge.target_doc_key);
                    alloc.free(edge.edge_id);
                    alloc.free(edge.logical_source);
                }
                const index = self.core.index_manager.graphIndex(edge.index_name) orelse continue;
                var decoded = try enrichment_artifact_codec.decodeGraphEdgeAlloc(alloc, row.value);
                defer decoded.deinit(alloc);
                if (enrichment_artifact_codec.isLegacyUnboundGraphEdge(row.value)) continue;
                if (decoded.generation != index.config.coverage_generation and
                    !enrichment_artifact_codec.isPortableUnboundGraphEdge(row.value)) continue;
                // Authenticate against the donor generation, then mark the
                // edge portable. Receiver replay binds its own generation;
                // copying the donor generation would silently discard it.
                break :graph try enrichment_artifact_codec.encodePortableUnboundGraphEdgeWithTtlAlloc(
                    alloc,
                    decoded.weight,
                    decoded.created_at,
                    decoded.updated_at,
                    decoded.ttl_created_ns,
                    decoded.metadata_json,
                );
            } else if (internal_keys.isGraphGlobalEdgeContenderKey(row.key)) contender: {
                const generation = try graph_edge_contender.coverageGeneration(row.value);
                var current = false;
                for (self.core.index_manager.graph_indexes.items) |entry| {
                    if (entry.config.coverage_generation == generation and
                        internal_keys.matchesGraphGlobalEdgeContenderIndexName(row.key, entry.config.name))
                    {
                        const decoded = (try graph_edge_contender.decode(row.value, generation)) orelse return error.InvalidGraphEdgeContender;
                        const expected_key = try internal_keys.graphGlobalEdgeContenderKeyAlloc(alloc, entry.config.name, generation, decoded.edge_key, decoded.source_priority, decoded.state_key);
                        defer alloc.free(expected_key);
                        if (!std.mem.eql(u8, row.key, expected_key)) return error.InvalidGraphEdgeContender;
                        current = true;
                        break;
                    }
                }
                if (!current) continue;
                break :contender try alloc.dupe(u8, row.value);
            } else if (internal_keys.isGraphEdgeTtlLifetimeKey(row.key) or internal_keys.isGraphEdgeTtlTombstoneKey(row.key)) state: {
                const generation = try internal_keys.graphEdgeTtlStateKeyGeneration(row.key);
                var current = false;
                for (self.core.index_manager.graph_indexes.items) |entry| {
                    if (entry.config.coverage_generation == generation and
                        internal_keys.matchesGraphEdgeContenderIndexName(row.key, entry.config.name))
                    {
                        current = true;
                        break;
                    }
                }
                if (!current) continue;
                if (internal_keys.isGraphEdgeTtlLifetimeKey(row.key)) {
                    if (row.value.len != 8) return error.InvalidGraphEdgeTtlLifetime;
                } else _ = try graph_edge_ttl_tombstone.Tombstone.decode(row.value);
                break :state try alloc.dupe(u8, row.value);
            } else try alloc.dupe(u8, row.value);
            errdefer alloc.free(value);
            const key = try alloc.dupe(u8, row.key);
            errdefer alloc.free(key);
            try rows.append(alloc, .{ .key = key, .value = value });
            bytes +|= key.len +| value.len;
            if (rows.items.len >= 128 or bytes >= 1024 * 1024) break;
        }
        return rows.toOwnedSlice(alloc);
    }

    /// Imports donor-owned derived artifacts into a live merge receiver while
    /// both DBs are protected by transition leases. Primary documents are
    /// copied separately from the authoritative Raft apply projection.
    ///
    /// The Raft apply projection used by range coordination deliberately stores
    /// only primary documents. It therefore cannot reconstruct stripped inputs
    /// such as `_edges` or explicit embeddings by itself. Copy the authoritative
    /// document-scoped store rows and live graph projection before cutover so a
    /// successful merge cannot publish primary data with incomplete indexes.
    pub fn importMergeRangeFromTransitionDonor(
        self: *DB,
        donor: *DB,
        byte_range: types.ByteRange,
    ) !void {
        if (self == donor or std.mem.eql(u8, self.core.path, donor.core.path))
            return error.InvalidArgument;

        // Transition activity prevents new public writes. The DB apply locks
        // additionally give this copy one coherent donor view and keep index
        // mutation atomic with respect to receiver maintenance. Order by path
        // so independently initiated transitions cannot invert these locks.
        const donor_first = std.mem.order(u8, donor.core.path, self.core.path) == .lt;
        if (donor_first) {
            donor.core.lockApplyShared();
            self.core.lockApply();
        } else {
            self.core.lockApply();
            donor.core.lockApplyShared();
        }
        defer if (donor_first) {
            self.core.unlockApply();
            donor.core.unlockApplyShared();
        } else {
            donor.core.unlockApplyShared();
            self.core.unlockApply();
        };

        try self.requireSupportedRelationalTopology();
        try donor.requireSupportedRelationalTopology();
        try self.enforcePortableRuntimeGate();
        // A failed donor import can still owe source reconciliation that only
        // its durable recovery worklist describes. Do not borrow its catalog
        // rebuild lease or certify its snapshot until that recovery completes.
        try donor.enforcePortableRuntimeGate();

        // Stabilize both materialized snapshots and their pending source debt
        // before copying rows. Apply locks alone do not stop derived workers.
        const first_manager = if (donor_first) donor.core.index_manager else self.core.index_manager;
        const second_manager = if (donor_first) self.core.index_manager else donor.core.index_manager;
        var first_rebuild = first_manager.beginGraphArtifactRebuild();
        defer first_rebuild.deinit();
        var second_rebuild = second_manager.beginGraphArtifactRebuild();
        defer second_rebuild.deinit();
        const receiver_rebuild = if (donor_first) &second_rebuild else &first_rebuild;
        const donor_rebuild = if (donor_first) &first_rebuild else &second_rebuild;
        defer donor_rebuild.complete();
        var primary_published = false;
        defer if (!primary_published) receiver_rebuild.complete();
        var source_work = std.StringHashMapUnmanaged(void).empty;
        defer {
            var it = source_work.keyIterator();
            while (it.next()) |key| self.alloc.free(key.*);
            source_work.deinit(self.alloc);
        }
        try collectGraphMergeSourceWork(self, byte_range, false, &source_work, self.alloc);
        try collectGraphMergeSourceWork(donor, byte_range, true, &source_work, self.alloc);
        const source_keys = try self.alloc.alloc([]const u8, source_work.count());
        defer self.alloc.free(source_keys);
        var source_it = source_work.keyIterator();
        for (source_keys) |*key| key.* = source_it.next().?.*;
        // Finish donor source debt while its catalog is stable, so copied
        // contenders carry the donor's lifetime on repeated range imports.
        for (source_keys) |key| {
            const owner = (try internal_keys.decodeDocumentComponentAlloc(self.alloc, key)) orelse return error.InvalidGraphArtifact;
            defer self.alloc.free(owner);
            if (!byte_range.contains(owner)) continue;
            try reconcileGraphMergeSourceInput(donor, key, donor.core.store.nextReplaySequence(1) -| 1);
        }
        try donor.core.syncStore(true);
        // Donor outputs are now complete and copied below with their existing
        // lifetimes. Only retained receiver debt needs replay during recovery;
        // re-rendering moved inputs would require donor resolution/doc context.
        var retained_source_count: usize = 0;
        for (source_keys) |key| {
            const owner = (try internal_keys.decodeDocumentComponentAlloc(self.alloc, key)) orelse return error.InvalidGraphArtifact;
            defer self.alloc.free(owner);
            if (byte_range.contains(owner)) continue;
            source_keys[retained_source_count] = key;
            retained_source_count += 1;
        }

        const store_lower = try documentRangeLowerAlloc(self.alloc, byte_range.start);
        defer self.alloc.free(store_lower);
        const store_upper = if (byte_range.end.len > 0)
            try documentRangeUpperAlloc(self.alloc, byte_range.end)
        else
            null;
        defer if (store_upper) |key| self.alloc.free(key);
        const donor_rows = try donor.core.scanStoreRange(
            self.alloc,
            store_lower,
            if (store_upper) |key| key else "",
        );
        defer docstore_mod.DocStore.freeResults(self.alloc, donor_rows);

        var derived_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer derived_writes.deinit(self.alloc);
        var owned_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_keys.items) |key| self.alloc.free(key);
            owned_keys.deinit(self.alloc);
        }
        var owned_graph_values = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_graph_values.items) |value| self.alloc.free(value);
            owned_graph_values.deinit(self.alloc);
        }
        var donor_artifact_keys = std.StringHashMapUnmanaged(void).empty;
        defer donor_artifact_keys.deinit(self.alloc);
        var imported_counts = std.StringHashMapUnmanaged(struct { generation: u64, edges: usize }).empty;
        defer imported_counts.deinit(self.alloc);
        var counted_edges = std.StringHashMapUnmanaged(void).empty;
        defer counted_edges.deinit(self.alloc);
        for (donor_rows) |row| {
            if (!internal_keys.isGraphRetirementKey(row.key) and !internal_keys.isGraphEdgeArtifactKey(row.key) and
                !internal_keys.isAssetArtifactKey(row.key) and
                !internal_keys.isGraphGlobalEdgeContenderKey(row.key) and
                !internal_keys.isGraphAssetStateKey(row.key) and
                !internal_keys.isGraphEdgeTtlLifetimeKey(row.key) and
                !internal_keys.isGraphEdgeTtlTombstoneKey(row.key) and
                !internal_keys.isEmbeddingArtifactKey(row.key) and
                !internal_keys.isDerivedEmbeddingArtifactKey(row.key)) continue;
            var key = row.key;
            var value = row.value;
            if (internal_keys.isGraphEdgeArtifactKey(row.key)) {
                const parsed = (try internal_keys.parseGraphEdgeArtifactKeyAlloc(self.alloc, row.key)) orelse return error.InvalidGraphEdgeArtifact;
                defer {
                    self.alloc.free(parsed.doc_key);
                    self.alloc.free(parsed.index_name);
                    self.alloc.free(parsed.edge_type);
                    self.alloc.free(parsed.target_doc_key);
                    self.alloc.free(parsed.edge_id);
                    self.alloc.free(parsed.logical_source);
                }
                const donor_index = donor.core.index_manager.graphIndex(parsed.index_name) orelse continue;
                const receiver_index = self.core.index_manager.graphIndex(parsed.index_name) orelse return error.IndexNotFound;
                var decoded = try enrichment_artifact_codec.decodeGraphEdgeAlloc(self.alloc, row.value);
                defer decoded.deinit(self.alloc);
                if (decoded.generation != donor_index.config.coverage_generation and
                    !enrichment_artifact_codec.isPortableUnboundGraphEdge(row.value)) continue;
                const portable = try enrichment_artifact_codec.encodePortableUnboundGraphEdgeWithTtlAlloc(
                    self.alloc,
                    decoded.weight,
                    decoded.created_at,
                    decoded.updated_at,
                    decoded.ttl_created_ns,
                    decoded.metadata_json,
                );
                defer self.alloc.free(portable);
                const bound = try enrichment_artifact_codec.bindGraphEdgeGenerationAlloc(self.alloc, portable, receiver_index.config.coverage_generation);
                var bound_unowned = true;
                errdefer if (bound_unowned) self.alloc.free(bound);
                try owned_graph_values.append(self.alloc, bound);
                bound_unowned = false;
                value = bound;
            } else if (internal_keys.isGraphGlobalEdgeContenderKey(row.key)) {
                const donor_generation = try graph_edge_contender.coverageGeneration(row.value);
                const contender = (try graph_edge_contender.decode(row.value, donor_generation)) orelse return error.InvalidGraphEdgeContender;
                var index_name: ?[]const u8 = null;
                for (donor.core.index_manager.graph_indexes.items) |entry| {
                    if (entry.config.coverage_generation == donor_generation and
                        internal_keys.matchesGraphGlobalEdgeContenderIndexName(row.key, entry.config.name))
                    {
                        index_name = entry.config.name;
                        break;
                    }
                }
                const name = index_name orelse continue;
                const receiver_index = self.core.index_manager.graphIndex(name) orelse return error.IndexNotFound;
                const expected_donor_key = try internal_keys.graphGlobalEdgeContenderKeyAlloc(self.alloc, name, donor_generation, contender.edge_key, contender.source_priority, contender.state_key);
                defer self.alloc.free(expected_donor_key);
                if (!std.mem.eql(u8, row.key, expected_donor_key)) return error.InvalidGraphEdgeContender;
                var donor_edge = try enrichment_artifact_codec.decodeGraphEdgeAlloc(self.alloc, contender.payload);
                defer donor_edge.deinit(self.alloc);
                if (donor_edge.generation != donor_generation) return error.InvalidGraphEdgeContender;
                const rebound_payload = try enrichment_artifact_codec.encodeGraphEdgeWithTtlAlloc(
                    self.alloc,
                    null,
                    receiver_index.config.coverage_generation,
                    donor_edge.weight,
                    donor_edge.created_at,
                    donor_edge.updated_at,
                    donor_edge.ttl_created_ns,
                    donor_edge.metadata_json,
                );
                defer self.alloc.free(rebound_payload);
                const rebound_key = try internal_keys.graphGlobalEdgeContenderKeyAlloc(self.alloc, name, receiver_index.config.coverage_generation, contender.edge_key, contender.source_priority, contender.state_key);
                var key_unowned = true;
                errdefer if (key_unowned) self.alloc.free(rebound_key);
                try owned_keys.append(self.alloc, rebound_key);
                key_unowned = false;
                key = rebound_key;
                const rebound_value = try graph_edge_contender.encodeAlloc(self.alloc, receiver_index.config.coverage_generation, contender.source_priority, contender.edge_key, contender.state_key, rebound_payload);
                var value_unowned = true;
                errdefer if (value_unowned) self.alloc.free(rebound_value);
                try owned_graph_values.append(self.alloc, rebound_value);
                value_unowned = false;
                value = rebound_value;
                // Reconstruct primary membership from authenticated global
                // contributors, including direct sources. Local records and
                // counts are generation-bound and cannot be copied verbatim.
                const owner = (try internal_keys.decodeDocumentComponentAlloc(self.alloc, contender.edge_key)) orelse return error.InvalidGraphEdgeArtifact;
                defer self.alloc.free(owner);
                const local_key = try internal_keys.graphEdgeContenderKeyAlloc(self.alloc, owner, name, contender.edge_key, contender.state_key);
                owned_keys.append(self.alloc, local_key) catch |err| {
                    self.alloc.free(local_key);
                    return err;
                };
                const local_value = try graph_edge_contender.encodeAlloc(self.alloc, receiver_index.config.coverage_generation, contender.source_priority, contender.edge_key, contender.state_key, "");
                owned_graph_values.append(self.alloc, local_value) catch |err| {
                    self.alloc.free(local_value);
                    return err;
                };
                try derived_writes.append(self.alloc, .{ .key = local_key, .value = local_value });
                try donor_artifact_keys.put(self.alloc, local_key, {});
                const edge = try counted_edges.getOrPut(self.alloc, contender.edge_key);
                if (!edge.found_existing) {
                    const count_key = try internal_keys.graphEdgeContenderCountKeyAlloc(self.alloc, owner, name);
                    owned_keys.append(self.alloc, count_key) catch |err| {
                        self.alloc.free(count_key);
                        return err;
                    };
                    const counter = try imported_counts.getOrPut(self.alloc, count_key);
                    if (!counter.found_existing) counter.value_ptr.* = .{ .generation = receiver_index.config.coverage_generation, .edges = 0 };
                    counter.value_ptr.edges = try std.math.add(usize, counter.value_ptr.edges, 1);
                }
            } else if (internal_keys.isGraphEdgeTtlLifetimeKey(row.key) or internal_keys.isGraphEdgeTtlTombstoneKey(row.key)) {
                const donor_generation = try internal_keys.graphEdgeTtlStateKeyGeneration(row.key);
                var index_name: ?[]const u8 = null;
                for (donor.core.index_manager.graph_indexes.items) |entry| {
                    if (entry.config.coverage_generation == donor_generation and
                        internal_keys.matchesGraphEdgeContenderIndexName(row.key, entry.config.name))
                    {
                        index_name = entry.config.name;
                        break;
                    }
                }
                const name = index_name orelse continue;
                const receiver_index = self.core.index_manager.graphIndex(name) orelse return error.IndexNotFound;
                const rebound_key = try internal_keys.rebindGraphEdgeTtlStateKeyGenerationAlloc(self.alloc, row.key, receiver_index.config.coverage_generation);
                var key_unowned = true;
                errdefer if (key_unowned) self.alloc.free(rebound_key);
                try owned_keys.append(self.alloc, rebound_key);
                key_unowned = false;
                key = rebound_key;
            } else if (internal_keys.isGraphAssetStateKey(row.key)) {
                var source_index: ?*index_manager_mod.IndexManager.GraphIndex = null;
                for (donor.core.index_manager.graph_indexes.items) |*entry| {
                    if (internal_keys.matchesGraphAssetStateIndexName(row.key, entry.config.name)) {
                        source_index = entry;
                        break;
                    }
                }
                const donor_index = source_index orelse continue;
                const receiver_index = self.core.index_manager.graphIndex(donor_index.config.name) orelse return error.IndexNotFound;
                if (try graph_asset_state.recordGeneration(self.alloc, row.value, !internal_keys.isGraphAssetStateRootKey(row.key)) != donor_index.config.coverage_generation) continue;
                const rebound = try graph_asset_state.rebindGenerationAlloc(self.alloc, row.value, donor_index.config.coverage_generation, receiver_index.config.coverage_generation, !internal_keys.isGraphAssetStateRootKey(row.key));
                owned_graph_values.append(self.alloc, rebound) catch |err| {
                    self.alloc.free(rebound);
                    return err;
                };
                value = rebound;
            }
            try derived_writes.append(self.alloc, .{ .key = key, .value = value });
            try donor_artifact_keys.put(self.alloc, key, {});
        }
        var counts = imported_counts.iterator();
        while (counts.next()) |counter| {
            // A logical edge with multiple contributors counts only once.
            const encoded = try graph_edge_contender.encodeVisibleCount(
                counter.value_ptr.generation,
                counter.value_ptr.edges,
            );
            const value = try self.alloc.dupe(u8, &encoded);
            owned_graph_values.append(self.alloc, value) catch |err| {
                self.alloc.free(value);
                return err;
            };
            const key = counter.key_ptr.*;
            try derived_writes.append(self.alloc, .{ .key = key, .value = value });
            try donor_artifact_keys.put(self.alloc, key, {});
        }
        // A range import is a replacement snapshot. Delete receiver artifacts
        // that the donor no longer owns, including expired direct contenders
        // and retired asset inputs, before rebuilding local projections.
        const receiver_rows = try self.core.scanStoreRange(
            self.alloc,
            store_lower,
            if (store_upper) |key| key else "",
        );
        defer docstore_mod.DocStore.freeResults(self.alloc, receiver_rows);
        var stale_artifact_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer stale_artifact_keys.deinit(self.alloc);
        for (receiver_rows) |row| {
            const local_membership = internal_keys.isGraphEdgeContenderKey(row.key) and
                !internal_keys.isGraphEdgeTtlLifetimeKey(row.key) and !internal_keys.isGraphEdgeTtlTombstoneKey(row.key);
            if ((isMergeArtifactKey(row.key) or local_membership or internal_keys.isGraphAssetStateKey(row.key)) and !donor_artifact_keys.contains(row.key))
                try stale_artifact_keys.append(self.alloc, row.key);
        }
        const recovery_indexes = try self.alloc.alloc(GraphMergeImportIndex, self.core.index_manager.graph_indexes.items.len);
        defer self.alloc.free(recovery_indexes);
        for (self.core.index_manager.graph_indexes.items, recovery_indexes) |entry, *identity| identity.* = .{ .name = entry.config.name, .generation = entry.config.coverage_generation };
        const recovery_record = try std.json.Stringify.valueAlloc(self.alloc, GraphMergeImportRecovery{
            .indexes = recovery_indexes,
            .replay_sequence = self.core.store.nextReplaySequence(1) -| 1,
            .source_artifact_keys = source_keys[0..retained_source_count],
        }, .{});
        defer self.alloc.free(recovery_record);
        try derived_writes.append(self.alloc, .{ .key = graph_merge_import_recovery_key, .value = recovery_record });
        try derived_writes.append(self.alloc, .{ .key = graph_edge_ttl_due_rebuild_marker, .value = "1" });
        {
            const raw_writes = try rawStoreWritesAlloc(self.alloc, derived_writes.items);
            defer self.alloc.free(raw_writes);
            try self.core.store.putBatch(raw_writes, stale_artifact_keys.items);
            primary_published = true;
            self.local_execution.graph_merge_import_recovery_pending.store(true, .release);
            // The recovery record and the complete authoritative snapshot
            // become durable together, before touching disposable indexes.
            try self.core.syncStore(true);
            if (builtin.is_test and test_graph_merge_import_abort_after_primary.swap(false, .monotonic)) return error.TestInjectedGraphMergeImportFailure;
            try applySplitEmbeddingArtifactsFromBatch(
                self.core.store,
                self.core.index_manager,
                derived_writes.items,
                &.{},
                &.{},
            );
        }
        // Range replacement follows producing documents, not edge sources.
        // Rebuild the complete owned projection so withdrawn owners disappear
        // and retained owners of shared entity edges remain selectable. Use
        // exactly the same durable publication path as interrupted recovery.
        try finishGraphMergeImport(self, receiver_rebuild);
    }

    const RestorePurpose = union(enum) {
        historical_table,
        /// Preserve the exact durable namespace and catalog incarnation supplied
        /// by a verified generation owner.
        identity_preserving: doc_identity.Namespace,
    };

    fn restoreSnapshotStoreTo(
        alloc: Allocator,
        snapshot_root: []const u8,
        path: []const u8,
        opts: OpenOptions,
        restore_identity: ?RestoreIdentity,
        restore_io: ?Io,
        cancellation: types.CancellationToken,
        native_manifest: ?*const native_backup.Manifest,
        purpose: RestorePurpose,
    ) !void {
        try cancellation.check();
        const shared_io = restore_io orelse if (opts.backend_runtime) |runtime| runtime.filesystemIo() else null;
        const identity_io = if (restore_identity != null)
            shared_io orelse return error.BackendRuntimeIoUnavailable
        else
            null;
        if (restore_identity) |identity| {
            try beginRestoreImportWithIo(alloc, identity_io.?, path, snapshot_root, identity);
        }
        const physical_primary = if (native_manifest) |manifest|
            std.mem.eql(u8, manifest.primary.artifact_format, "antfly-lsm-checkpoint")
        else
            false;
        if (physical_primary) switch (opts.primary_backend) {
            .lsm => {},
            else => return error.UnsupportedBackupFormat,
        };

        var opened_primary = try openPrimaryStore(alloc, path, .{
            .map_size = opts.map_size,
            .no_sync = opts.no_sync,
            .primary_backend = opts.primary_backend,
            .primary_runtime_store = opts.primary_runtime_store,
            .storage = opts.storage,
            .index_backends = opts.index_backends,
        });
        defer {
            opened_primary.store.close();
            opened_primary.owner.close(alloc);
        }

        const streaming_store = if (physical_primary)
            true
        else blk: {
            try db_core.clearAllKeysFromStore(alloc, &opened_primary.store);
            break :blk if (shared_io) |io|
                try db_core.importStoreSnapshotWithIo(alloc, io, &opened_primary.store, snapshot_root, cancellation)
            else fallback: {
                try db_core.importStoreSnapshot(alloc, &opened_primary.store, snapshot_root);
                break :fallback false;
            };
        };
        try cancellation.check();
        try doc_identity.validateStoreAlloc(alloc, &opened_primary.store);
        try validateRestoredIdentityNamespace(&opened_primary.store, opts);
        // A table-local historical image cannot certify references owned by
        // other tables at a later cut. Keep the candidate unpublished until a
        // cluster-coordinated restore/activation barrier is available.
        if (purpose == .historical_table) {
            const topology_fence = opened_primary.store.get(alloc, @import("relational_integrity_topology.zig").fence_key) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            if (topology_fence) |bytes| {
                alloc.free(bytes);
                return error.CoordinatedConstraintRestoreRequired;
            }
            const retirement = opened_primary.store.get(alloc, @import("relational_integrity_retirement.zig").key) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            if (retirement) |bytes| {
                alloc.free(bytes);
                return error.CoordinatedConstraintRestoreRequired;
            }
        }
        const restored_integrity = opened_primary.store.get(alloc, @import("relational_integrity_catalog.zig").key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (restored_integrity) |bytes| {
            defer alloc.free(bytes);
            var catalog = try @import("relational_integrity_catalog.zig").decode(alloc, bytes);
            defer catalog.deinit();
            if (@import("relational_integrity_activation.zig").hasActive(catalog)) switch (purpose) {
                .historical_table => return error.CoordinatedConstraintRestoreRequired,
                .identity_preserving => |expected_namespace| {
                    const stored_namespace = (try doc_identity.loadNamespaceFromStore(&opened_primary.store)) orelse return error.IdentityNamespaceMismatch;
                    if (!stored_namespace.eql(expected_namespace)) return error.IdentityNamespaceMismatch;
                    const incarnation = try @import("relational_integrity_catalog.zig").incarnationFromTableId(expected_namespace.table_id);
                    if (!std.mem.eql(u8, &incarnation, &catalog.incarnation)) return error.IntegrityCatalogIncarnationMismatch;
                },
            };
        }
        if (!streaming_store)
            try db_core.importChangeJournalSnapshot(alloc, &opened_primary.store, snapshot_root);
        // The candidate root owns its identity. Creating it while the staged
        // capability is still held makes identity part of the durable tree
        // that is sealed and atomically published, rather than an open-time
        // side effect after the generation becomes visible.
        if (opts.physical_root_mode == .filesystem_managed) {
            _ = if (shared_io) |io|
                try root_identity.loadOrCreate(alloc, io, path)
            else
                try loadOrCreateDurableRootIdentity(alloc, opts.backend_runtime, path);
        }
        if (restore_identity) |identity| {
            try markRestorePrimaryRestoredForPathWithIdentityWithIo(alloc, identity_io.?, path, identity);
        }
    }

    fn validateRestoredIdentityNamespace(store: *docstore_mod.DocStore, opts: OpenOptions) !void {
        if (opts.identity_namespace == null or opts.prefer_existing_identity_namespace) return;
        const stored = (try doc_identity.loadNamespaceFromStore(store)) orelse return;
        if (!stored.eql(opts.identity_namespace.?)) return error.IdentityNamespaceMismatch;
    }

    fn restoreSnapshotTo(alloc: Allocator, snapshot_root: []const u8, path: []const u8, opts: OpenOptions) !void {
        try restoreSnapshotStoreTo(alloc, snapshot_root, path, opts, null, null, .none, null, .historical_table);
        try finishSnapshotRuntimeRepair(alloc, path, opts);
    }

    fn finishSnapshotRuntimeRepair(alloc: Allocator, path: []const u8, opts: OpenOptions) !void {
        // Graph reverse indexes are derived from stored outgoing edge keys, so
        // restore them after the logical store and derived log are rehydrated.
        var restored = try DB.open(alloc, path, opts);
        defer restored.close();
        _ = try restored.rebuildDenseIndexesForTargetCoverage(alloc);
        _ = try restored.rebuildSparseIndexesForTargetCoverage(alloc);
        try restored.rebuildGraphIndexesForTargetCoverage(alloc);
        try restored.core.index_manager.syncAll(true);
    }

    /// A verified primary is complete. Reconstruct only
    /// derived projections in its unpublished generation; never run optional
    /// transaction recovery or advance the replicated mutation watermark.
    pub fn repairVerifiedPrimarySnapshot(
        alloc: Allocator,
        staged: *const generation_lifecycle.StagedGeneration,
        namespace: [24]u8,
        receipt: ?OrderedApplyReceipt,
        root_generation: u64,
    ) !void {
        try staged.validatePath(staged.path());
        const options: OpenOptions = .{
            .staged_generation = staged,
            .open_mode = .writer_no_replay,
            .start_optional_runtimes = false,
            .start_index_workers = false,
            .lsm_root_generation = root_generation,
            .identity_namespace = .{
                .table_id = std.mem.readInt(u64, namespace[0..8], .big),
                .shard_id = std.mem.readInt(u64, namespace[8..16], .big),
                .range_id = std.mem.readInt(u64, namespace[16..24], .big),
            },
        };
        try finishSnapshotRuntimeRepair(alloc, staged.path(), options);
        // Prove a fresh owner can use the files, not merely the rebuilding
        // owner's transient in-memory structures.
        var verify = try DB.open(alloc, staged.path(), options);
        defer verify.close();
        try verify.verifyTransferablePrimarySnapshot(namespace, receipt);
        if (verify.core.index_manager.hasLoadFailures() or verify.core.index_manager.hasRepairUnavailableIndexes()) return error.RestoreIndexLoadIncomplete;
        try verify.core.index_manager.syncAll(true);
        try verify.core.syncStore(true);
    }

    pub fn restoreSnapshotToStagedGeneration(
        staged_generation: *const generation_lifecycle.StagedGeneration,
        alloc: Allocator,
        snapshot_root: []const u8,
        path: []const u8,
        opts: OpenOptions,
    ) !void {
        try staged_generation.validatePath(path);
        var staged_opts = opts;
        staged_opts.staged_generation = staged_generation;
        try restoreSnapshotTo(alloc, snapshot_root, path, staged_opts);
    }

    /// Install a verified snapshot while preserving its namespace and catalog
    /// incarnation. The staged capability keeps it unpublished during repair.
    pub fn restoreIdentityPreservingSnapshotToStagedGeneration(
        staged_generation: *const generation_lifecycle.StagedGeneration,
        alloc: Allocator,
        snapshot_root: []const u8,
        path: []const u8,
        opts: OpenOptions,
        expected_namespace: doc_identity.Namespace,
    ) !void {
        try staged_generation.validatePath(path);
        if (expected_namespace.table_id == 0 or opts.prefer_existing_identity_namespace or
            !(opts.identity_namespace orelse return error.IdentityNamespaceMismatch).eql(expected_namespace))
            return error.IdentityNamespaceMismatch;
        var staged_opts = opts;
        staged_opts.staged_generation = staged_generation;
        try restoreSnapshotStoreTo(alloc, snapshot_root, path, staged_opts, null, null, .none, null, .{ .identity_preserving = expected_namespace });
        try finishSnapshotRuntimeRepair(alloc, path, staged_opts);
    }

    /// Materialize an authenticated native backup into a disposable source
    /// generation, retaining SOURCE identities only in this read-only decoder.
    /// No source catalog/index/claim bytes are ever installed into the target.
    /// The artifact digest is verified by the private restore RPC before this
    /// filesystem operation; it is then bound into the target owner's Scope.
    pub fn openVerifiedRestoreSource(staged_generation: *const generation_lifecycle.StagedGeneration, alloc: Allocator, snapshot_root: []const u8, path: []const u8, opts: OpenOptions, expected_namespace: doc_identity.Namespace) !DB {
        return openVerifiedRestoreSourceWithCancellation(staged_generation, alloc, snapshot_root, path, opts, expected_namespace, .none);
    }

    pub fn openVerifiedRestoreSourceWithCancellation(staged_generation: *const generation_lifecycle.StagedGeneration, alloc: Allocator, snapshot_root: []const u8, path: []const u8, opts: OpenOptions, expected_namespace: doc_identity.Namespace, cancellation: types.CancellationToken) !DB {
        try cancellation.check();
        try staged_generation.validatePath(path);
        if (expected_namespace.table_id == 0) return error.IdentityNamespaceMismatch;
        var source_opts = opts;
        source_opts.identity_namespace = expected_namespace;
        source_opts.prefer_existing_identity_namespace = false;
        source_opts.staged_generation = staged_generation;
        source_opts.start_index_workers = false;
        source_opts.start_optional_runtimes = false;
        const io = if (opts.backend_runtime) |runtime| runtime.filesystemIo() orelse return error.BackendRuntimeIoUnavailable else return error.BackendRuntimeIoUnavailable;
        var native_generation = try native_backup.validateAndMaterializeWithCancellation(alloc, io, snapshot_root, path, cancellation);
        defer if (native_generation) |*manifest| manifest.deinit();
        if (native_generation) |*manifest| {
            if (std.mem.eql(u8, manifest.value().primary.artifact_format, "antfly-lsm-checkpoint")) source_opts.primary_backend = .{ .lsm = .{} };
        }
        try restoreSnapshotStoreTo(alloc, snapshot_root, path, source_opts, null, io, cancellation, if (native_generation) |*manifest| manifest.value() else null, .{ .identity_preserving = expected_namespace });
        source_opts.open_mode = .query_readonly;
        source_opts.primary_only_readonly = true;
        return try DB.open(alloc, path, source_opts);
    }

    pub fn restoreSnapshotToDeferredRuntimeRepair(
        staged_generation: *const generation_lifecycle.StagedGeneration,
        alloc: Allocator,
        snapshot_root: []const u8,
        path: []const u8,
        opts: OpenOptions,
        identity: RestoreIdentity,
    ) !void {
        const runtime = opts.backend_runtime orelse return error.BackendRuntimeIoUnavailable;
        const io = runtime.filesystemIo() orelse return error.BackendRuntimeIoUnavailable;
        return try restoreSnapshotToDeferredRuntimeRepairWithIo(
            staged_generation,
            alloc,
            io,
            snapshot_root,
            path,
            opts,
            identity,
        );
    }

    pub fn restoreSnapshotToDeferredRuntimeRepairWithIo(
        staged_generation: *const generation_lifecycle.StagedGeneration,
        alloc: Allocator,
        io: Io,
        snapshot_root: []const u8,
        path: []const u8,
        opts: OpenOptions,
        identity: RestoreIdentity,
    ) !void {
        return try restoreSnapshotToDeferredRuntimeRepairWithIoAndCancellation(
            staged_generation,
            alloc,
            io,
            snapshot_root,
            path,
            opts,
            identity,
            .none,
        );
    }

    pub fn restoreSnapshotToDeferredRuntimeRepairWithIoAndCancellation(
        staged_generation: *const generation_lifecycle.StagedGeneration,
        alloc: Allocator,
        io: Io,
        snapshot_root: []const u8,
        path: []const u8,
        opts: OpenOptions,
        identity: RestoreIdentity,
        cancellation: types.CancellationToken,
    ) !void {
        try staged_generation.validatePath(path);
        var native_generation = try native_backup.validateAndMaterializeWithCancellation(
            alloc,
            io,
            snapshot_root,
            path,
            cancellation,
        );
        defer if (native_generation) |*generation| generation.deinit();
        if (native_generation) |*generation| return try restoreMaterializedNativeGenerationToDeferredRuntimeRepairWithIoAndCancellation(
            staged_generation,
            alloc,
            io,
            snapshot_root,
            path,
            opts,
            identity,
            generation,
            cancellation,
        );
        try restoreSnapshotStoreTo(alloc, snapshot_root, path, opts, identity, io, cancellation, null, .historical_table);
    }

    /// Installs a generation whose declared files were already authenticated
    /// and copied directly into the unpublished destination. This is the
    /// manifest-first remote restore path; it deliberately performs no source
    /// tree enumeration or second corpus-sized validation pass.
    pub fn restoreMaterializedNativeGenerationToDeferredRuntimeRepairWithIoAndCancellation(
        staged_generation: *const generation_lifecycle.StagedGeneration,
        alloc: Allocator,
        io: Io,
        primary_snapshot_root: []const u8,
        path: []const u8,
        opts: OpenOptions,
        identity: RestoreIdentity,
        native_generation: *native_backup.LoadedManifest,
        cancellation: types.CancellationToken,
    ) !void {
        // Tree-materialized callers may already contain every projection.
        // Remove statically incompatible physical codecs before opening the
        // staged catalog; the manifest-first remote planner calls the primary
        // phase directly and has not downloaded these groups yet.
        try classifyIncompatibleNativeProjections(native_generation, opts);
        try native_generation.discardInvalidProjectionArtifacts(io, path);
        try restoreMaterializedNativePrimaryAndPlanProjectionsWithIoAndCancellation(
            staged_generation,
            alloc,
            io,
            primary_snapshot_root,
            path,
            opts,
            identity,
            native_generation,
            cancellation,
        );
        try finishMaterializedNativeGenerationWithIo(
            staged_generation,
            alloc,
            io,
            path,
            opts,
            native_generation,
            true,
        );
    }

    /// Restores only the primary and small generation metadata, then uses the
    /// restored catalog to decide which projection artifact groups are worth
    /// transferring. No physical projection corpus is required by this phase.
    pub fn restoreMaterializedNativePrimaryAndPlanProjectionsWithIoAndCancellation(
        staged_generation: *const generation_lifecycle.StagedGeneration,
        alloc: Allocator,
        io: Io,
        primary_snapshot_root: []const u8,
        path: []const u8,
        opts: OpenOptions,
        identity: RestoreIdentity,
        native_generation: *native_backup.LoadedManifest,
        cancellation: types.CancellationToken,
    ) !void {
        try staged_generation.validatePath(path);
        try classifyIncompatibleNativeProjections(native_generation, opts);
        try restoreSnapshotStoreTo(
            alloc,
            primary_snapshot_root,
            path,
            opts,
            identity,
            io,
            cancellation,
            native_generation.value(),
            .historical_table,
        );
        var validation_opts = opts;
        validation_opts.open_mode = .query_readonly;
        validation_opts.staged_generation = staged_generation;
        validation_opts.start_index_workers = false;
        validation_opts.start_optional_runtimes = false;
        validation_opts.start_optional_runtime_workers = false;
        var validation = try DB.open(alloc, path, validation_opts);
        defer validation.close();
        try validation.classifyNativeProjectionCatalogCompatibility(alloc, native_generation);
    }

    pub fn finishMaterializedNativeGenerationWithIo(
        staged_generation: *const generation_lifecycle.StagedGeneration,
        alloc: Allocator,
        io: Io,
        path: []const u8,
        opts: OpenOptions,
        native_generation: *native_backup.LoadedManifest,
        complete_runtime_repair: bool,
    ) !void {
        try validateInstalledNativeBackupGeneration(
            staged_generation,
            alloc,
            io,
            path,
            opts,
            native_generation,
            complete_runtime_repair,
        );
    }

    /// Local bound databases do not have a non-zero Raft group identity. Return
    /// whether a complete native generation was installed so the caller can
    /// run the legacy logical fallback without manufacturing replica provenance.
    pub fn restoreSnapshotToLocalDeferredRuntimeRepairWithIo(
        staged_generation: *const generation_lifecycle.StagedGeneration,
        alloc: Allocator,
        io: Io,
        snapshot_root: []const u8,
        path: []const u8,
        opts: OpenOptions,
    ) !bool {
        return try restoreSnapshotToLocalDeferredRuntimeRepairWithIoAndCancellation(
            staged_generation,
            alloc,
            io,
            snapshot_root,
            path,
            opts,
            .none,
        );
    }

    pub fn restoreSnapshotToLocalDeferredRuntimeRepairWithIoAndCancellation(
        staged_generation: *const generation_lifecycle.StagedGeneration,
        alloc: Allocator,
        io: Io,
        snapshot_root: []const u8,
        path: []const u8,
        opts: OpenOptions,
        cancellation: types.CancellationToken,
    ) !bool {
        try staged_generation.validatePath(path);
        var native_generation = try native_backup.validateAndMaterializeWithCancellation(
            alloc,
            io,
            snapshot_root,
            path,
            cancellation,
        );
        defer if (native_generation) |*generation| generation.deinit();
        if (native_generation) |*generation| {
            try classifyIncompatibleNativeProjections(generation, opts);
            try generation.discardInvalidProjectionArtifacts(io, path);
        }
        try restoreSnapshotStoreTo(
            alloc,
            snapshot_root,
            path,
            opts,
            null,
            io,
            cancellation,
            if (native_generation) |*generation| generation.value() else null,
            .historical_table,
        );
        if (native_generation) |*generation| {
            try validateInstalledNativeBackupGeneration(staged_generation, alloc, io, path, opts, generation, false);
            return true;
        }
        return false;
    }

    fn validateInstalledNativeBackupGeneration(
        staged_generation: *const generation_lifecycle.StagedGeneration,
        alloc: Allocator,
        io: Io,
        path: []const u8,
        opts: OpenOptions,
        native_generation: *native_backup.LoadedManifest,
        complete_runtime_repair: bool,
    ) !void {
        // Repair identities are replica-local capabilities. The checkpoint is
        // part of the checksummed generation so pending debt cannot disappear,
        // but a quiesced fast-path snapshot is required to carry no entries.
        // Rebind that empty state before any staged open so two restored roots
        // never share repair authority.
        const repair_path = try index_repair_state.checkpointPathAlloc(alloc, path);
        defer alloc.free(repair_path);
        if (index_repair_state.load(alloc, repair_path)) |repair_state_value| {
            var repair_state = repair_state_value;
            defer repair_state.deinit(alloc);
            if (repair_state.entries.items.len != 0)
                return error.NativeBackupRepairStateNotQuiescent;
            var rebound = try index_repair_state.resetForRootGeneration(
                alloc,
                repair_path,
                repair_state.identity,
                opts.lsm_root_generation,
            );
            rebound.deinit(alloc);
        } else |err| switch (err) {
            error.FileNotFound => {},
            else => return err,
        }

        // Native backup artifacts are authenticated into their portable
        // canonical paths. Before the staged root can become visible, rehome
        // every valid native dense projection beneath an explicit physical
        // generation and publish the same incompatible v2 pointer used by an
        // online migration. This is an O(index-count) rename/publication step;
        // restoring native data must never manufacture a corpus-wide rebuild.
        for (native_generation.value().projections) |projection| {
            if (native_generation.projectionInvalid(projection.name) or
                !std.mem.eql(u8, projection.kind, @tagName(types.IndexKind.dense_vector)) or
                !std.mem.eql(
                    u8,
                    projection.backend_id,
                    index_manager_mod.IndexManager.dense_native_backup_backend_id,
                )) continue;
            try index_manager_mod.IndexManager.publishRestoredNativePhysicalGeneration(
                alloc,
                path,
                projection.name,
                projection.config_hash,
                projection.applied_sequence,
                native_generation.value().capture_target_sequence,
            );
        }

        var validation_opts = opts;
        validation_opts.open_mode = if (native_generation.invalid_projections.items.len == 0)
            .query_readonly
        else
            .writer_no_replay;
        validation_opts.staged_generation = staged_generation;
        validation_opts.start_index_workers = false;
        validation_opts.start_optional_runtimes = false;
        validation_opts.start_optional_runtime_workers = false;
        {
            var validation = try DB.open(alloc, path, validation_opts);
            defer validation.close();
            try validation.validateNativeBackupGeneration(alloc, native_generation);
        }
        if (native_generation.invalid_projections.items.len != 0) {
            try native_generation.discardInvalidProjectionArtifacts(io, path);
            validation_opts.open_mode = .writer_no_replay;
            var restored = try DB.open(alloc, path, validation_opts);
            defer restored.close();
            for (native_generation.invalid_projections.items) |invalid| {
                // A projection present only in the native manifest is stale
                // relative to the restored catalog. Its files were discarded,
                // but there is no configured runtime generation to repair.
                const cfg = restored.core.index_manager.get(invalid.name) orelse continue;
                const previous = try restored.core.loadProjectionCheckpoint(alloc, invalid.name);
                try restored.core.saveProjectionCheckpoint(invalid.name, .{
                    .applied_sequence = 0,
                    .status = .repair_required,
                    .generation = previous.generation +| 1,
                    .config_hash = types.indexConfigHash(cfg.*),
                });
                _ = try restored.createGenerationRepairIntentAtTarget(
                    alloc,
                    cfg.*,
                    .projection_generation_invalid,
                    0,
                    0,
                    @tagName(invalid.reason),
                    native_generation.value().capture_target_sequence,
                    .not_required,
                    .repair,
                );
            }
            try restored.core.index_manager.syncAll(true);
            if (complete_runtime_repair) {
                try restored.updateRestoreRuntimeRepairPhaseWithIo(alloc, io, "repair_indexes", false);
            }
        } else if (complete_runtime_repair) {
            try markRestoreRuntimeRepairCompleteWithIo(alloc, io, path);
        }
    }

    fn classifyNativeProjectionCatalogCompatibility(
        self: *DB,
        alloc: Allocator,
        native_generation: *native_backup.LoadedManifest,
    ) !void {
        const manifest = native_generation.value();
        const primary_sequence = self.core.nextDerivedSequence();
        if (primary_sequence != manifest.capture_target_sequence) {
            std.log.err(
                "native backup primary checkpoint mismatch primary_sequence={d} manifest_target={d}",
                .{ primary_sequence, manifest.capture_target_sequence },
            );
            return error.NativeBackupPrimaryCheckpointMismatch;
        }
        const configs = try self.core.listIndexes(alloc);
        defer types.freeIndexConfigs(alloc, configs);
        var configs_by_name = std.StringHashMapUnmanaged(*const types.IndexConfig).empty;
        defer configs_by_name.deinit(alloc);
        try configs_by_name.ensureTotalCapacity(alloc, @intCast(configs.len));
        for (configs) |*cfg| {
            const entry = configs_by_name.getOrPutAssumeCapacity(cfg.name);
            if (entry.found_existing) return error.InvalidIndexCatalog;
            entry.value_ptr.* = cfg;
        }
        var manifest_projection_names = std.StringHashMapUnmanaged(void).empty;
        defer manifest_projection_names.deinit(alloc);
        try manifest_projection_names.ensureTotalCapacity(alloc, @intCast(manifest.projections.len));
        for (manifest.projections) |projection| {
            const entry = manifest_projection_names.getOrPutAssumeCapacity(projection.name);
            if (entry.found_existing) return error.InvalidNativeBackupManifest;
        }

        // A catalog projection omitted from the physical generation is local
        // repair debt, not permission to reject an otherwise valid primary
        // snapshot. It will receive a durable repair intent below.
        for (configs) |cfg| {
            if (!manifest_projection_names.contains(cfg.name))
                try native_generation.invalidateProjection(cfg.name, .missing_artifact);
        }

        for (manifest.projections) |projection| {
            if (native_generation.projectionInvalid(projection.name)) continue;
            const cfg = configs_by_name.get(projection.name) orelse {
                try native_generation.invalidateProjection(projection.name, .config_mismatch);
                continue;
            };
            if (!std.mem.eql(u8, projection.kind, @tagName(cfg.kind)) or
                projection.config_hash != types.indexConfigHash(cfg.*))
            {
                try native_generation.invalidateProjection(projection.name, .config_mismatch);
                continue;
            }
            if (projection.coverage_generation != cfg.coverage_generation) {
                try native_generation.invalidateProjection(projection.name, .coverage_mismatch);
                continue;
            }
            if (projection.target_sequence != manifest.capture_target_sequence or
                projection.applied_sequence != projection.target_sequence)
            {
                try native_generation.invalidateProjection(projection.name, .checkpoint_mismatch);
                continue;
            }
        }
    }

    fn validateNativeBackupGeneration(self: *DB, alloc: Allocator, native_generation: *native_backup.LoadedManifest) !void {
        try self.classifyNativeProjectionCatalogCompatibility(alloc, native_generation);
        const configs = try self.core.listIndexes(alloc);
        defer types.freeIndexConfigs(alloc, configs);
        var configs_by_name = std.StringHashMapUnmanaged(*const types.IndexConfig).empty;
        defer configs_by_name.deinit(alloc);
        try configs_by_name.ensureTotalCapacity(alloc, @intCast(configs.len));
        for (configs) |*cfg| {
            const entry = configs_by_name.getOrPutAssumeCapacity(cfg.name);
            if (entry.found_existing) return error.InvalidIndexCatalog;
            entry.value_ptr.* = cfg;
        }
        for (native_generation.value().projections) |projection| {
            if (native_generation.projectionInvalid(projection.name)) continue;
            const cfg = configs_by_name.get(projection.name) orelse continue;
            if (self.core.index_manager.loadFailure(projection.name)) |err_name| {
                if (nativeBackupProjectionLoadFailureIsRepairable(err_name)) {
                    try native_generation.invalidateProjection(projection.name, .unreadable);
                    continue;
                }
                // Unknown, resource, and transient I/O failures are not proof
                // that a checksummed generation is corrupt. Leave the staged
                // tree intact so the asynchronous restore job can retry.
                std.log.warn("native backup projection validation deferred index={s} err={s}", .{ projection.name, err_name });
                return error.NativeBackupProjectionValidationIndeterminate;
            }
            // The primary-only transfer plan cannot validate a dense checkpoint:
            // its authoritative sequence lives in the still-unrestored posting
            // generation. Validate physical coverage only after installation.
            const checkpoint = try self.core.loadProjectionCheckpoint(alloc, projection.name);
            if (checkpoint.status != .clean or
                checkpoint.config_hash != projection.config_hash or
                checkpoint.generation != projection.checkpoint_generation or
                checkpoint.applied_sequence != projection.applied_sequence or
                checkpoint.applied_sequence != projection.target_sequence)
            {
                std.log.err("native backup projection checkpoint mismatch index={s} status={s} checkpoint_hash={d} manifest_hash={d} checkpoint_generation={d} manifest_generation={d} checkpoint_applied={d} manifest_applied={d} manifest_target={d}", .{
                    projection.name,
                    @tagName(checkpoint.status),
                    checkpoint.config_hash,
                    projection.config_hash,
                    checkpoint.generation,
                    projection.checkpoint_generation,
                    checkpoint.applied_sequence,
                    projection.applied_sequence,
                    projection.target_sequence,
                });
                try native_generation.invalidateProjection(projection.name, .checkpoint_mismatch);
                continue;
            }
            if (cfg.kind == .dense_vector) {
                const dense = self.core.index_manager.denseIndex(projection.name) orelse {
                    try native_generation.invalidateProjection(projection.name, .unreadable);
                    continue;
                };
                if (@hasDecl(@TypeOf(dense.index.*), "validateStoredStructure")) {
                    dense.index.validateStoredStructure(alloc) catch |err| switch (err) {
                        error.NotFound, error.FileNotFound, error.Corrupted => {
                            try native_generation.invalidateProjection(projection.name, .unreadable);
                        },
                        else => {
                            // A transient resource or I/O failure is not
                            // evidence that the checksummed artifact is bad.
                            // Preserve the staged generation and let the
                            // durable restore job retry validation.
                            std.log.warn("native backup dense projection validation deferred index={s} err={s}", .{ projection.name, @errorName(err) });
                            return error.NativeBackupProjectionValidationIndeterminate;
                        },
                    };
                }
            }
        }
    }

    fn nativeBackupProjectionLoadFailureIsRepairable(err_name: []const u8) bool {
        const repairable = [_][]const u8{
            "Corrupted",
            "FileNotFound",
            "NotFound",
            "UnsupportedVersion",
            "IncompleteBulkPublish",
        };
        for (repairable) |candidate| {
            if (std.mem.eql(u8, err_name, candidate)) return true;
        }
        return false;
    }

    fn classifyIncompatibleNativeProjections(
        generation: *native_backup.LoadedManifest,
        opts: OpenOptions,
    ) !void {
        for (generation.value().projections) |projection| {
            const kind = std.meta.stringToEnum(types.IndexKind, projection.kind) orelse
                return error.InvalidNativeBackupManifest;
            const target_backend = switch (kind) {
                .full_text => @tagName(opts.index_backends.text_main_backend),
                .dense_vector => @tagName(opts.index_backends.dense_storage_backend),
                .sparse_vector => @tagName(opts.index_backends.sparse_backend),
                .graph => @tagName(opts.index_backends.graph_reverse_backend),
                .algebraic => "primary",
            };
            const backend_compatible = std.mem.eql(u8, projection.backend_id, target_backend) or
                (kind == .dense_vector and
                    opts.index_backends.dense_storage_backend == .lsm and
                    std.mem.eql(
                        u8,
                        projection.backend_id,
                        index_manager_mod.IndexManager.dense_native_backup_backend_id,
                    ));
            if (!backend_compatible or
                projection.codec_version != 1)
            {
                try generation.invalidateProjection(projection.name, .backend_mismatch);
            }
        }
    }

    fn beginRestoreImport(alloc: Allocator, path: []const u8, snapshot_root: []const u8, identity: RestoreIdentity) !void {
        var io_impl = threadedIo();
        defer io_impl.deinit();
        return try beginRestoreImportWithIo(alloc, io_impl.io(), path, snapshot_root, identity);
    }

    fn beginRestoreImportWithIo(alloc: Allocator, io: Io, path: []const u8, snapshot_root: []const u8, identity: RestoreIdentity) !void {
        if (snapshot_root.len == 0 or !validRestoreIdentity(identity))
            return error.InvalidRestoreImportMarker;
        try fs_paths.createDirPathPortable(io, path);
        const restore_intent_path = try restoreIntentMarkerPathAlloc(alloc, path);
        defer alloc.free(restore_intent_path);
        const restore_state_path = try restoreStateMarkerPathAlloc(alloc, path);
        defer alloc.free(restore_state_path);
        const import_marker_path = try restoreImportMarkerPathAlloc(alloc, path);
        defer alloc.free(import_marker_path);

        try deleteFileIfExists(io, restore_intent_path);
        try deleteFileIfExists(io, restore_state_path);
        const marker = try std.json.Stringify.valueAlloc(alloc, RestoreImportDisk{
            .snapshot_root = snapshot_root,
            .backup_id = identity.backup_id,
            .location = identity.location,
            .artifact_sha256 = identity.artifact_sha256,
            .native_manifest_size_bytes = identity.native_manifest_size_bytes,
            .native_manifest_sha256 = identity.native_manifest_sha256,
            .snapshot_path = identity.snapshot_path,
            .group_id = identity.group_id,
        }, .{});
        defer alloc.free(marker);
        try writeRestoreMarkerAtomicWithIo(alloc, io, path, import_marker_path, marker);
    }

    pub fn recoverIncompleteRestoreImportIfNeeded(alloc: Allocator, path: []const u8, opts: OpenOptions) !bool {
        var io_impl = threadedIo();
        defer io_impl.deinit();
        return try recoverIncompleteRestoreImportIfNeededWithIo(alloc, io_impl.io(), path, opts);
    }

    pub fn recoverIncompleteRestoreImportIfNeededWithIo(
        alloc: Allocator,
        io: Io,
        path: []const u8,
        opts: OpenOptions,
    ) !bool {
        if (try readRestoreStateForPathAllocWithIo(alloc, io, path)) |state_value| {
            var state = state_value;
            state.deinit(alloc);
            return false;
        }

        var import_state = (try readRestoreImportStateAllocWithIo(alloc, io, path)) orelse return false;
        defer import_state.deinit(alloc);
        const identity_state = import_state.identity;
        const identity: RestoreIdentity = .{
            .backup_id = identity_state.backup_id,
            .location = identity_state.location,
            .artifact_sha256 = identity_state.artifact_sha256,
            .native_manifest_size_bytes = identity_state.native_manifest_size_bytes,
            .native_manifest_sha256 = identity_state.native_manifest_sha256,
            .snapshot_path = identity_state.snapshot_path,
            .group_id = identity_state.group_id,
        };
        std.log.warn("recovering incomplete restore import phase=startup", .{});
        try restoreSnapshotStoreTo(alloc, import_state.snapshot_root, path, opts, identity, io, .none, null, .historical_table);
        return true;
    }

    pub fn readRestoreStateForPath(alloc: Allocator, path: []const u8) !?RestoreState {
        return try readRestoreStateForPathAlloc(alloc, path);
    }

    pub fn readRestoreStateForPathWithIo(alloc: Allocator, io: Io, path: []const u8) !?RestoreState {
        return try readRestoreStateForPathAllocWithIo(alloc, io, path);
    }

    pub fn markRestorePrimaryRestoredForPathWithArtifact(
        alloc: Allocator,
        path: []const u8,
        backup_id: []const u8,
        location: []const u8,
        artifact_sha256: []const u8,
        snapshot_path: []const u8,
        group_id: u64,
    ) !void {
        var io_impl = threadedIo();
        defer io_impl.deinit();
        return try markRestorePrimaryRestoredForPathWithArtifactWithIo(
            alloc,
            io_impl.io(),
            path,
            backup_id,
            location,
            artifact_sha256,
            snapshot_path,
            group_id,
        );
    }

    pub fn markRestorePrimaryRestoredForPathWithArtifactWithIo(
        alloc: Allocator,
        io: Io,
        path: []const u8,
        backup_id: []const u8,
        location: []const u8,
        artifact_sha256: []const u8,
        snapshot_path: []const u8,
        group_id: u64,
    ) !void {
        return try markRestorePrimaryRestoredForPathWithIdentityWithIo(alloc, io, path, .{
            .backup_id = backup_id,
            .location = location,
            .artifact_sha256 = artifact_sha256,
            .snapshot_path = snapshot_path,
            .group_id = group_id,
        });
    }

    pub fn markRestorePrimaryRestoredForPathWithIdentityWithIo(
        alloc: Allocator,
        io: Io,
        path: []const u8,
        identity: RestoreIdentity,
    ) !void {
        var state = try restoreStateAlloc(
            alloc,
            identity.backup_id,
            identity.location,
            identity.artifact_sha256,
            identity.native_manifest_size_bytes,
            identity.native_manifest_sha256,
            identity.snapshot_path,
            identity.group_id,
            "runtime_repair",
            true,
            false,
            "",
            "",
        );
        defer state.deinit(alloc);
        try writeRestoreStateForPathWithIo(alloc, io, path, state);
        const import_marker_path = try restoreImportMarkerPathAlloc(alloc, path);
        defer alloc.free(import_marker_path);
        try deleteFileIfExists(io, import_marker_path);
    }

    pub fn restoreRuntimeRepairNeededForPath(alloc: Allocator, path: []const u8) !bool {
        var io_impl = threadedIo();
        defer io_impl.deinit();
        return try restoreRuntimeRepairNeededForPathWithIo(alloc, io_impl.io(), path);
    }

    pub fn restoreRuntimeRepairNeededForPathWithIo(alloc: Allocator, io: Io, path: []const u8) !bool {
        var state = (try readRestoreStateForPathAllocWithIo(alloc, io, path)) orelse return false;
        defer state.deinit(alloc);
        return state.primary_restored and !state.runtime_repair_complete;
    }

    fn markRestoreRuntimeRepairNeeded(alloc: Allocator, path: []const u8) !void {
        var io_impl = threadedIo();
        defer io_impl.deinit();
        return try markRestoreRuntimeRepairNeededWithIo(alloc, io_impl.io(), path);
    }

    fn markRestoreRuntimeRepairNeededWithIo(alloc: Allocator, io: Io, path: []const u8) !void {
        const import_marker_path = try restoreImportMarkerPathAlloc(alloc, path);
        defer alloc.free(import_marker_path);

        var state = (try readRestoreStateForPathAllocWithIo(alloc, io, path)) orelse return error.InvalidRestoreState;
        defer state.deinit(alloc);
        const new_phase = try alloc.dupe(u8, "runtime_repair");
        alloc.free(state.phase);
        state.phase = new_phase;
        state.primary_restored = true;
        state.runtime_repair_complete = false;
        const empty_cursor = try alloc.dupe(u8, "");
        alloc.free(state.graph_ownership_cursor);
        state.graph_ownership_cursor = empty_cursor;
        try writeRestoreStateForPathWithIo(alloc, io, path, state);
        try deleteFileIfExists(io, import_marker_path);
    }

    fn markRestoreRuntimeRepairCompleteWithIo(alloc: Allocator, io: Io, path: []const u8) !void {
        var state = (try readRestoreStateForPathAllocWithIo(alloc, io, path)) orelse return error.InvalidRestoreState;
        defer state.deinit(alloc);
        const new_phase = try alloc.dupe(u8, "complete");
        alloc.free(state.phase);
        state.phase = new_phase;
        state.primary_restored = true;
        state.runtime_repair_complete = true;
        const empty_cursor = try alloc.dupe(u8, "");
        alloc.free(state.graph_ownership_cursor);
        state.graph_ownership_cursor = empty_cursor;
        try writeRestoreStateForPathWithIo(alloc, io, path, state);
    }

    pub fn restoreRuntimeRepairNeeded(self: *DB) !bool {
        if (self.backend_runtime.filesystemIo()) |io| {
            return try restoreRuntimeRepairNeededForPathWithIo(self.alloc, io, self.core.path);
        }
        return try restoreRuntimeRepairNeededForPath(self.alloc, self.core.path);
    }

    /// Restore's first repair owner can prove a generation only while its
    /// index objects remain open. Publication needs the stronger proof that a
    /// fresh owner can load the files it left behind. When that reopen
    /// rediscovers dense generation or watermark debt, reset the durable
    /// restore state so the fresh owner reconstructs the candidate before it
    /// can be sealed.
    pub fn prepareRestoreDurabilityRetryIfNeeded(self: *DB, alloc: Allocator) !bool {
        if (self.core.index_manager.hasLoadFailures()) return error.RestoreIndexLoadIncomplete;
        const retry_needed = try self.hasPendingDenseArtifactRebuild(alloc) or
            try self.denseArtifactWatermarkRepairNeeded(alloc) or
            self.core.index_manager.hasRepairUnavailableIndexes();
        if (!retry_needed) return false;
        if (self.backend_runtime.io()) |io| {
            try markRestoreRuntimeRepairNeededWithIo(alloc, io, self.core.path);
        } else {
            try markRestoreRuntimeRepairNeeded(alloc, self.core.path);
        }
        return true;
    }

    fn updateRestoreRuntimeRepairPhaseWithIo(
        self: *DB,
        alloc: Allocator,
        io: Io,
        phase: []const u8,
        complete: bool,
    ) !void {
        var state = (try readRestoreStateForPathAllocWithIo(alloc, io, self.core.path)) orelse return error.InvalidRestoreState;
        defer state.deinit(alloc);
        const new_phase = try alloc.dupe(u8, phase);
        alloc.free(state.phase);
        state.phase = new_phase;
        state.primary_restored = true;
        state.runtime_repair_complete = complete;
        const empty_cursor = try alloc.dupe(u8, "");
        alloc.free(state.graph_ownership_cursor);
        state.graph_ownership_cursor = empty_cursor;
        const new_last_error = try alloc.dupe(u8, "");
        alloc.free(state.last_error);
        state.last_error = new_last_error;
        try writeRestoreStateForPathWithIo(alloc, io, self.core.path, state);
    }

    fn updateRestoreGraphOwnershipCursorWithIo(
        self: *DB,
        alloc: Allocator,
        io: Io,
        cursor: []const u8,
    ) !void {
        var state = (try readRestoreStateForPathAllocWithIo(alloc, io, self.core.path)) orelse return error.InvalidRestoreState;
        defer state.deinit(alloc);
        if (!std.mem.eql(u8, state.phase, "rebuild_graph") or state.runtime_repair_complete) {
            return error.InvalidRestoreState;
        }
        const encoded_cursor = try bytesToHexAlloc(alloc, cursor);
        alloc.free(state.graph_ownership_cursor);
        state.graph_ownership_cursor = encoded_cursor;
        try writeRestoreStateForPathWithIo(alloc, io, self.core.path, state);
    }

    pub fn repairRestoreRuntimeStateStepIfNeeded(self: *DB, alloc: Allocator) !bool {
        if (self.backend_runtime.filesystemIo()) |io| {
            return try self.repairRestoreRuntimeStateStepIfNeededWithIo(alloc, io);
        }
        var io_impl = threadedIo();
        defer io_impl.deinit();
        return try self.repairRestoreRuntimeStateStepIfNeededWithIo(alloc, io_impl.io());
    }

    pub fn repairRestoreRuntimeStateStepIfNeededWithIo(self: *DB, alloc: Allocator, io: Io) !bool {
        return try self.repairRestoreRuntimeStateStepIfNeededWithIoAndRepairOptions(alloc, io, .{});
    }

    pub fn repairRestoreRuntimeStateStepIfNeededWithIoAndRepairOptions(
        self: *DB,
        alloc: Allocator,
        io: Io,
        repair_options: types.ArtifactRepairRunOptions,
    ) !bool {
        var state = (try readRestoreStateForPathAllocWithIo(alloc, io, self.core.path)) orelse return false;
        defer state.deinit(alloc);
        if (!state.primary_restored or state.runtime_repair_complete) return false;
        const phase = state.phase;

        if (std.mem.eql(u8, phase, "repair_indexes")) {
            std.log.info("restore runtime repair phase=repair_indexes", .{});
            if (!try self.repairNativeRestoreProjectionIntentsStep(alloc, repair_options))
                return error.RestoreRuntimeRepairIncomplete;
            try self.updateRestoreRuntimeRepairPhaseWithIo(alloc, io, "complete", true);
            return true;
        }

        if (std.mem.eql(u8, phase, "runtime_repair") or std.mem.eql(u8, phase, "reset_watermarks")) {
            std.log.info("restore runtime repair phase=reset_index_watermarks", .{});
            try self.resetManagedIndexAppliedSequencesForRestoreRepair(alloc);
            try self.refreshManagedIndexWorkersLocked();
            try self.updateRestoreRuntimeRepairPhaseWithIo(alloc, io, "rebuild_graph", false);
            return true;
        }
        if (std.mem.eql(u8, phase, "rebuild_graph")) {
            std.log.info("restore runtime repair phase=rebuild_graph_ownership", .{});
            const cursor = if (state.graph_ownership_cursor.len > 0)
                try hexToBytesAlloc(alloc, state.graph_ownership_cursor)
            else
                null;
            defer if (cursor) |key| alloc.free(key);
            var ownership_page = try self.rebuildGraphArtifactOwnershipForRestorePage(alloc, cursor);
            defer ownership_page.deinit(alloc);
            if (!ownership_page.complete) {
                try self.updateRestoreGraphOwnershipCursorWithIo(
                    alloc,
                    io,
                    ownership_page.next_cursor.?,
                );
                std.log.info("restore runtime repair rebuilt graph ownership page sources={d}", .{ownership_page.replayed});
                return true;
            }
            const graph_count = try self.rebuildGraphDerivedState();
            std.log.info("restore runtime repair rebuilt final graph ownership page sources={d} mutations={d}", .{ ownership_page.replayed, graph_count });
            try self.updateRestoreRuntimeRepairPhaseWithIo(alloc, io, "rebuild_artifacts", false);
            return true;
        }
        if (std.mem.eql(u8, phase, "rebuild_artifacts")) {
            std.log.info("restore runtime repair rebuild stored embedding artifacts path={s}", .{self.core.path});
            const dense_rebuild = try self.rebuildDenseIndexesFromStoredEmbeddingArtifactsOutcomeWithProgress(alloc, null, null);
            if (dense_rebuild.dense_visibility_changed) self.clearDenseHbcCaches();
            std.log.info("restore runtime repair rebuilt stored embedding artifacts path={s} count={d}", .{ self.core.path, dense_rebuild.reported_work });
            try self.updateRestoreRuntimeRepairPhaseWithIo(alloc, io, "replay_enrichments", false);
            return true;
        }
        if (std.mem.eql(u8, phase, "replay_enrichments")) {
            if (self.core.hasGeneratedEnrichmentTargets()) {
                const runtime = self.enrichment_runtime orelse return error.RestoreRepairRequiresEnrichmentRuntime;
                std.log.info("restore runtime repair replay generated enrichments path={s}", .{self.core.path});
                // A restored enrichment checkpoint can be equal to the first
                // destination replay sequence even when the destination has
                // no generated artifacts. Quiesce the worker before resetting
                // and appending so it cannot advance the checkpoint across an
                // empty replay window between those two operations.
                runtime.stop();
                errdefer if (self.local_execution.optional_runtime_workers_enabled) {
                    runtime.start() catch |start_err| {
                        std.log.warn("restore runtime repair enrichment restart failed path={s} err={}", .{ self.core.path, start_err });
                    };
                };
                try runtime.resumeFrom(0, self.core.nextDerivedSequence());
                const generated_refs = try self.replayGeneratedEnrichmentsFromStoredDocs(alloc);
                // Restore opens with optional workers disabled and drains them
                // synchronously. Starting a background worker here races the
                // foreground catch-up in the next phase over index mutation.
                if (self.local_execution.optional_runtime_workers_enabled) try runtime.start();
                std.log.info("restore runtime repair replayed generated enrichments path={s} refs={d}", .{ self.core.path, generated_refs });
            }
            try self.updateRestoreRuntimeRepairPhaseWithIo(alloc, io, "drain_async", false);
            return true;
        }
        if (std.mem.eql(u8, phase, "drain_async")) {
            std.log.info("restore runtime repair phase=drain_async", .{});
            if (self.core.hasGeneratedEnrichmentTargets()) {
                try self.runRestoreRepairDrainAsync();
                // This is the only asynchronous restore phase that can apply
                // newly generated dense vectors. Retire caches at that exact
                // mutation boundary instead of after every restore quantum.
                self.clearDenseHbcCaches();
            } else {
                std.log.info("restore runtime repair phase=skip_async_drain", .{});
            }
            try self.updateRestoreRuntimeRepairPhaseWithIo(alloc, io, "rebuild_replayed_artifacts", false);
            return true;
        }
        if (std.mem.eql(u8, phase, "rebuild_replayed_artifacts")) {
            std.log.info("restore runtime repair phase=rebuild_replayed_embeddings", .{});
            const dense_rebuild = try self.rebuildDenseIndexesFromStoredEmbeddingArtifactsOutcomeWithProgress(alloc, null, null);
            if (dense_rebuild.dense_visibility_changed) self.clearDenseHbcCaches();
            const coverage_repair = try self.repairRestoreDenseArtifactCoverageFromFinalArtifacts(alloc);
            if (coverage_repair.waiting_for_workers) {
                if (dense_rebuild.made_progress or coverage_repair.made_progress) return true;
                return error.RestoreRuntimeRepairIncomplete;
            }
            _ = try self.rebuildSparseIndexesForTargetCoverage(alloc);
            try self.updateRestoreRuntimeRepairPhaseWithIo(alloc, io, "sync_indexes", false);
            return true;
        }
        if (std.mem.eql(u8, phase, "sync_indexes")) {
            std.log.info("restore runtime repair phase=complete_indexes", .{});
            // Re-evaluate after every replay/rebuild phase. Those phases can
            // advance the durable replay target without rebuilding vectors,
            // leaving a completed artifact projection with an older applied
            // watermark or a rebuilding checkpoint. A restore must not publish
            // its completion marker until both forms of debt converge.
            // Resolve durable restore-owned intents first. In particular, a
            // missing-counter intent is itself reported as rebuild debt, so
            // checking the plan before bootstrapping its counter would keep
            // rediscovering the same intent forever.
            const artifact_completion = try self.completeRestoreDenseArtifactRepairs(alloc);
            if (artifact_completion == .progressed) return true;

            const dense_rebuild = try self.rebuildDenseIndexesFromStoredEmbeddingArtifactsOutcomeWithProgress(alloc, null, null);
            if (dense_rebuild.dense_visibility_changed) self.clearDenseHbcCaches();
            // Portable restores can legitimately rediscover a non-artifact
            // projection intent here. In particular, opening a restored v1
            // dense index under a v2-capable catalog creates a durable storage
            // migration intent only after the artifact repair pass has
            // established complete source coverage. The staged DB is not yet
            // published and therefore has no managed scheduler owner which can
            // advance that intent. Drive one bounded quantum from the restore
            // owner itself, using the same cancellation and capacity fences as
            // native selective restore repair. Otherwise sync_indexes waits
            // forever for an external owner that cannot open the staged root.
            if (!try self.repairNativeRestoreProjectionIntentsStep(alloc, repair_options)) {
                return error.RestoreRuntimeRepairIncomplete;
            }
            if (try self.hasPendingDenseArtifactRebuild(alloc) or
                try self.denseArtifactWatermarkRepairNeeded(alloc))
            {
                // A successful bounded rebuild is real visibility progress.
                // Publish/invalidate it before a later proof-only retry.
                if (dense_rebuild.made_progress) return true;
                return error.RestoreDenseArtifactRebuildIncomplete;
            }
            if (self.core.index_manager.hasRepairUnavailableIndexes()) {
                if (dense_rebuild.made_progress or artifact_completion == .completed_with_progress) return true;
                return error.RestoreIndexAvailabilityIncomplete;
            }
            try self.saveAllLiveIndexStatusSnapshots(alloc);
            try self.core.index_manager.syncAll(true);
            try self.core.syncStore(true);
            try markRestoreRuntimeRepairCompleteWithIo(alloc, io, self.core.path);
            std.log.info("restore runtime repair phase=complete", .{});
            return true;
        }
        return error.InvalidRestoreState;
    }

    fn repairRestoreRuntimeStateIfNeeded(self: *DB, alloc: Allocator) !bool {
        if (self.backend_runtime.filesystemIo()) |io| {
            return try self.repairRestoreRuntimeStateIfNeededWithIo(alloc, io);
        }
        var io_impl = threadedIo();
        defer io_impl.deinit();
        return try self.repairRestoreRuntimeStateIfNeededWithIo(alloc, io_impl.io());
    }

    fn repairRestoreRuntimeStateIfNeededWithIo(self: *DB, alloc: Allocator, io: Io) !bool {
        var repaired = false;
        while (try self.repairRestoreRuntimeStateStepIfNeededWithIo(alloc, io)) {
            repaired = true;
        }
        return repaired;
    }

    fn rebuildGraphDerivedState(self: *DB) !usize {
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        // Portable restore imports graph edge artifacts before the table's
        // configured indexes are opened. Materialize those durable artifacts
        // before repairing reverse edges; rebuilding reverse state alone would
        // silently publish an empty graph for an otherwise valid backup.
        try applySplitGraphArtifactsInRange(
            self.alloc,
            self.getRange().start,
            self.getRange().end,
            self.core.store,
            self.core.index_manager,
        );
        return try self.core.index_manager.rebuildGraphSplitDestination(
            self.getRange().start,
            self.getRange().end,
        );
    }

    /// Reconstruct the private graph materialization state omitted from a
    /// portable backup. Visible graph edges alone cannot preserve source
    /// precedence: after restore, deleting the current winner must reveal the
    /// next surviving source. Replay every durable graph input in bounded
    /// pages before rebuilding the runtime graph projection. One invocation is
    /// deliberately one durable work quantum so large restores do not hold the
    /// apply lock for an unbounded table scan.
    const GraphOwnershipRestorePage = struct {
        replayed: usize = 0,
        next_cursor: ?[]u8 = null,
        complete: bool = false,

        pub fn deinit(self: *@This(), alloc: Allocator) void {
            if (self.next_cursor) |cursor| alloc.free(cursor);
            self.* = undefined;
        }
    };

    const graph_ownership_restore_cursor_magic_v1 = "GRC1";
    const graph_ownership_restore_cursor_magic_v2 = "GRC2";
    const graph_ownership_restore_cursor_magic_v3 = "GRC3";
    const graph_ownership_restore_cursor_magic = "GRC4";

    const GraphOwnershipRestoreCursor = struct {
        artifact_key: []const u8,
        graph_index_offset: u32,
        item_offset: u32 = 0,
        segment_index: u32 = 0,
        key_count: u32 = 0,
        manifest_bytes: u32 = 0,
        rollback: bool = false,
    };

    fn decodeGraphOwnershipRestoreCursor(cursor: ?[]const u8) !?GraphOwnershipRestoreCursor {
        const raw = cursor orelse return null;
        if (std.mem.startsWith(u8, raw, graph_ownership_restore_cursor_magic_v1)) {
            const header_len = graph_ownership_restore_cursor_magic_v1.len + @sizeOf(u32);
            if (raw.len <= header_len) return error.InvalidRestoreState;
            return .{
                .artifact_key = raw[header_len..],
                .graph_index_offset = std.mem.readInt(u32, raw[graph_ownership_restore_cursor_magic_v1.len..header_len], .big),
            };
        }
        const v2_header_len = graph_ownership_restore_cursor_magic_v2.len + 4 * @sizeOf(u32);
        if (std.mem.startsWith(u8, raw, graph_ownership_restore_cursor_magic_v2)) {
            if (raw.len <= v2_header_len) return error.InvalidRestoreState;
            var pos = graph_ownership_restore_cursor_magic_v2.len;
            return .{
                .artifact_key = raw[v2_header_len..],
                .graph_index_offset = readU32Big(raw, &pos) catch return error.InvalidRestoreState,
                .item_offset = readU32Big(raw, &pos) catch return error.InvalidRestoreState,
                .segment_index = readU32Big(raw, &pos) catch return error.InvalidRestoreState,
                .key_count = readU32Big(raw, &pos) catch return error.InvalidRestoreState,
            };
        }
        const v3_header_len = graph_ownership_restore_cursor_magic_v3.len + 5 * @sizeOf(u32);
        if (std.mem.startsWith(u8, raw, graph_ownership_restore_cursor_magic_v3)) {
            if (raw.len <= v3_header_len) return error.InvalidRestoreState;
            var pos = graph_ownership_restore_cursor_magic_v3.len;
            return .{
                .artifact_key = raw[v3_header_len..],
                .graph_index_offset = readU32Big(raw, &pos) catch return error.InvalidRestoreState,
                .item_offset = readU32Big(raw, &pos) catch return error.InvalidRestoreState,
                .segment_index = readU32Big(raw, &pos) catch return error.InvalidRestoreState,
                .key_count = readU32Big(raw, &pos) catch return error.InvalidRestoreState,
                .manifest_bytes = readU32Big(raw, &pos) catch return error.InvalidRestoreState,
            };
        }
        const header_len = graph_ownership_restore_cursor_magic.len + 1 + 5 * @sizeOf(u32);
        if (std.mem.startsWith(u8, raw, graph_ownership_restore_cursor_magic)) {
            if (raw.len <= header_len) return error.InvalidRestoreState;
        } else {
            return null;
        }
        var pos = graph_ownership_restore_cursor_magic.len;
        const mode = raw[pos];
        pos += 1;
        if (mode > 1) return error.InvalidRestoreState;
        return .{
            .artifact_key = raw[header_len..],
            .graph_index_offset = readU32Big(raw, &pos) catch return error.InvalidRestoreState,
            .item_offset = readU32Big(raw, &pos) catch return error.InvalidRestoreState,
            .segment_index = readU32Big(raw, &pos) catch return error.InvalidRestoreState,
            .key_count = readU32Big(raw, &pos) catch return error.InvalidRestoreState,
            .manifest_bytes = readU32Big(raw, &pos) catch return error.InvalidRestoreState,
            .rollback = mode == 1,
        };
    }

    fn encodeGraphOwnershipRestoreCursorAlloc(
        alloc: Allocator,
        artifact_key: []const u8,
        graph_index_offset: usize,
        item_offset: usize,
        segment_index: usize,
        key_count: usize,
        manifest_bytes: usize,
        rollback: bool,
    ) ![]u8 {
        if (graph_index_offset > std.math.maxInt(u32) or item_offset > std.math.maxInt(u32) or
            segment_index > std.math.maxInt(u32) or key_count > std.math.maxInt(u32) or
            manifest_bytes > std.math.maxInt(u32)) return error.InvalidRestoreState;
        const header_len = graph_ownership_restore_cursor_magic.len + 1 + 5 * @sizeOf(u32);
        const out = try alloc.alloc(u8, header_len + artifact_key.len);
        @memcpy(out[0..graph_ownership_restore_cursor_magic.len], graph_ownership_restore_cursor_magic);
        var pos = graph_ownership_restore_cursor_magic.len;
        out[pos] = if (rollback) 1 else 0;
        pos += 1;
        for ([_]usize{ graph_index_offset, item_offset, segment_index, key_count, manifest_bytes }) |value| {
            std.mem.writeInt(u32, out[pos..][0..4], @intCast(value), .big);
            pos += 4;
        }
        @memcpy(out[header_len..], artifact_key);
        return out;
    }

    fn rebuildOneGraphArtifactOwnershipForRestore(
        self: *DB,
        alloc: Allocator,
        artifact_key: []const u8,
        graph_index_offset: usize,
        item_offset: usize,
        segment_index: usize,
        key_count: usize,
        manifest_bytes: usize,
        rollback: bool,
    ) !GraphOwnershipRestorePage {
        const graph_indexes = self.core.index_manager.graphIndexes();
        if (graph_index_offset >= graph_indexes.len) return error.InvalidRestoreState;
        const index_name = graph_indexes[graph_index_offset].config.name;

        if (rollback) {
            var artifact_ref = (try decodeArtifactRefIfKnownAlloc(alloc, artifact_key)) orelse return error.InvalidRestoreState;
            defer artifact_ref.deinit(alloc);
            const more = try rollbackGraphSourceArtifactRestoreStatePage(self, alloc, index_name, artifact_ref);
            return .{
                .replayed = 1,
                .next_cursor = if (more)
                    try encodeGraphOwnershipRestoreCursorAlloc(alloc, artifact_key, graph_index_offset, 0, 0, 0, 0, true)
                else if (graph_index_offset + 1 < graph_indexes.len)
                    try encodeGraphOwnershipRestoreCursorAlloc(alloc, artifact_key, graph_index_offset + 1, 0, 0, 0, 0, false)
                else
                    try alloc.dupe(u8, artifact_key),
            };
        }

        // Runtime restore repair operates on an unpublished staged generation
        // with optional workers disabled. Parsing, contender reconstruction,
        // and mutation filtering can be proportional to one admitted artifact;
        // do not hold the shard apply lock across that work. The durable restore
        // cursor serializes these units and advances only after putBatch returns.
        // Legacy v0.2 artifacts are monolithic. Admit a bounded relation and
        // byte window so a single restored document cannot monopolize memory
        // or produce an unbounded store batch. Invalid/oversized inputs are
        // durable source-local repair debt: they must not brick the remainder
        // of an otherwise healthy restore.
        const materialized: ?GraphArtifactRestoreMaterializationPage = materializeGraphSourceArtifactRestorePage(
            self,
            alloc,
            artifact_key,
            index_name,
            item_offset,
            segment_index,
            key_count,
            manifest_bytes,
        ) catch |err| switch (err) {
            error.ArtifactRepairRequired => null,
            error.ResourceLimitExceeded, error.InvalidGraphArtifact => {
                var artifact_ref = (try decodeArtifactRefIfKnownAlloc(alloc, artifact_key)) orelse return error.InvalidRestoreState;
                defer artifact_ref.deinit(alloc);
                const source = self.core.index_manager.graphArtifactSourceForArtifact(
                    index_name,
                    artifact_ref.name,
                ) orelse return error.InvalidRestoreState;
                try recordArtifactRepairIssueContextForIndexSource(
                    self.async_context,
                    .graph,
                    index_name,
                    artifact_ref.document_id,
                    "",
                    artifact_ref.unit_id orelse "",
                    source.artifact_name,
                    if (artifact_ref.source) |source_ref| source_ref.name else "",
                    artifact_ref.name,
                    artifact_key,
                    artifact_ref.chunk_id,
                    0,
                    if (err == error.ResourceLimitExceeded) .resource_limit_exceeded else .corrupt_artifact,
                );
                const more = try rollbackGraphSourceArtifactRestoreStatePage(self, alloc, index_name, artifact_ref);
                return .{
                    .replayed = 1,
                    .next_cursor = if (more)
                        try encodeGraphOwnershipRestoreCursorAlloc(alloc, artifact_key, graph_index_offset, 0, 0, 0, 0, true)
                    else if (graph_index_offset + 1 < graph_indexes.len)
                        try encodeGraphOwnershipRestoreCursorAlloc(alloc, artifact_key, graph_index_offset + 1, 0, 0, 0, 0, false)
                    else
                        try alloc.dupe(u8, artifact_key),
                };
            },
            else => return err,
        };

        if (materialized) |page| {
            if (page.next_item_offset) |next_item_offset| return .{
                .replayed = 1,
                .next_cursor = try encodeGraphOwnershipRestoreCursorAlloc(
                    alloc,
                    artifact_key,
                    graph_index_offset,
                    next_item_offset,
                    page.next_segment_index,
                    page.key_count,
                    page.manifest_bytes,
                    false,
                ),
            };
        }

        return .{
            .replayed = 1,
            .next_cursor = if (graph_index_offset + 1 < graph_indexes.len)
                try encodeGraphOwnershipRestoreCursorAlloc(alloc, artifact_key, graph_index_offset + 1, 0, 0, 0, 0, false)
            else
                try alloc.dupe(u8, artifact_key),
        };
    }

    fn rebuildGraphArtifactOwnershipForRestorePage(
        self: *DB,
        alloc: Allocator,
        cursor: ?[]const u8,
    ) !GraphOwnershipRestorePage {
        if (!self.core.index_manager.hasGraphIndexes()) return .{ .complete = true };
        if (try decodeGraphOwnershipRestoreCursor(cursor)) |continuation| {
            return try self.rebuildOneGraphArtifactOwnershipForRestore(
                alloc,
                continuation.artifact_key,
                continuation.graph_index_offset,
                continuation.item_offset,
                continuation.segment_index,
                continuation.key_count,
                continuation.manifest_bytes,
                continuation.rollback,
            );
        }

        // Scanning is bounded independently from materialization. Once an
        // artifact is found, process exactly one graph index and persist a
        // continuation for the remaining indexes. This prevents source count,
        // graph index count, and artifact size from multiplying in one quantum.
        const scan_page_size: usize = 128;
        const user_prefix = [_]u8{internal_keys.user_namespace};
        const keys = try self.core.store.scanPrefixKeysPage(alloc, &user_prefix, cursor, scan_page_size);
        defer freeOwnedKeySlice(alloc, keys);
        if (keys.len == 0) {
            if (self.graph_restore_parse_cache) |*cache| cache.deinit(self.alloc);
            self.graph_restore_parse_cache = null;
            return .{ .complete = true };
        }

        var consumed_rows: usize = 0;
        for (keys) |key| {
            const artifact_row = internal_keys.isAssetArtifactKey(key) or
                internal_keys.isChunkArtifactRecordKey(key) or
                internal_keys.isResolutionArtifactKey(key);
            consumed_rows += 1;
            if (artifact_row) {
                return try self.rebuildOneGraphArtifactOwnershipForRestore(alloc, key, 0, 0, 0, 0, 0, false);
            }
        }

        return .{
            .replayed = 0,
            .next_cursor = if (consumed_rows < keys.len or keys.len == scan_page_size)
                try alloc.dupe(u8, keys[consumed_rows - 1])
            else
                null,
            .complete = consumed_rows == keys.len and keys.len < scan_page_size,
        };
    }

    pub fn clearDenseHbcCaches(self: *DB) void {
        self.core.index_manager.clearDenseHbcCaches();
    }

    pub fn setSchema(self: *DB, table_schema: schema_mod.TableSchema) !void {
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        defer row_policy_lease.release();
        var schedule_replication_recovery_on_exit = false;
        defer if (schedule_replication_recovery_on_exit) self.scheduleDurableReplicationOutboxRecovery();
        var prepared_recovery = if (self.transaction_recovery_identity_context != null)
            try db_core.PreparedRecoveryRelationalState.init(
                self.runtime_alloc,
                if (table_schema.storage_mode == .relational) table_schema.relational_columns else null,
                table_schema.version,
            )
        else
            null;
        defer if (prepared_recovery) |*prepared| prepared.deinit();

        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.ensureDurableReplicationStartupBarrier();
        try self.enforceReplicationWriteGate();
        try self.preflightReplicationMetadataSyncCommit();
        const durable_replication_schema_payload = if (self.local_execution.replication_async_metadata_mirror) |mirror|
            if (replicationMirrorRequiresDurableOutbox(mirror)) try replication_effects_mod.encodeSchemaMetadataMutationAlloc(self.alloc, table_schema, null) else null
        else
            null;
        defer if (durable_replication_schema_payload) |payload| self.alloc.free(payload);
        const durable_replication_schema_lsn = if (durable_replication_schema_payload != null)
            self.local_execution.replication_async_metadata_mirror.?.publisher.nextLsn()
        else
            null;
        const durable_replication_schema_outbox = if (durable_replication_schema_payload) |payload|
            try encodeDurableReplicationOutboxAlloc(self.alloc, durable_replication_schema_lsn.?, payload)
        else
            null;
        defer if (durable_replication_schema_outbox) |outbox| self.alloc.free(outbox);
        const durable_replication_schema_outbox_key = if (durable_replication_schema_outbox != null)
            try durableReplicationOutboxKeyAlloc(self.alloc, .schema, durable_replication_schema_lsn.?, self.core.root_generation, durable_replication_schema_payload.?)
        else
            null;
        defer if (durable_replication_schema_outbox_key) |key| self.alloc.free(key);
        const schema_metadata_writes: []const docstore_mod.KVPair = if (durable_replication_schema_outbox) |outbox|
            &.{.{ .key = durable_replication_schema_outbox_key.?, .value = outbox }}
        else
            &.{};
        var prepared_schema = try self.core.prepareSchemaMetadata(table_schema, schema_metadata_writes);
        defer prepared_schema.deinit();
        try self.lockApplyForPortableRuntime();
        var apply_held = true;
        errdefer if (apply_held) self.core.unlockApply();
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        if (self.async_context.primary_replication_append_pending.load(.acquire)) return error.ReplicationPublisherUnavailable;
        try self.enforceVectorMigrationConfigurationGate();
        const reconciled_row_count = try self.validateStorageModeCompatibilityLocked(table_schema);
        if (durable_replication_schema_outbox_key != null) self.local_execution.durable_replication_outbox_maybe.store(true, .release);
        _ = try self.core.commitPreparedSchemaMetadata(
            &prepared_schema,
            schema_metadata_writes,
            &.{public_schema_json_key},
            reconciled_row_count,
        );
        schedule_replication_recovery_on_exit = durable_replication_schema_outbox_key != null;
        self.publishRelationalRuntimeModePrepared(if (prepared_recovery) |*prepared| prepared else null);

        var ctx = self.batchContext();
        var deferred_replication_gates = ReplicationDeferredCommitGates.begin(replicationTransitionMutexFromContext(&ctx));
        defer deferred_replication_gates.releaseTransition();
        var post_commit_error: ?anyerror = null;
        if (durable_replication_schema_payload) |payload|
            deferred_replication_gates.append(appendReplicationEncodedSchemaMetadataCommitLockedContext(&ctx, payload) catch |err| blk: {
                post_commit_error = err;
                break :blk null;
            })
        else
            deferred_replication_gates.append(appendReplicationSchemaMetadataCommitLockedContext(&ctx, table_schema, null) catch |err| blk: {
                post_commit_error = err;
                break :blk null;
            });
        self.core.unlockApply();
        apply_held = false;
        releaseReplicationMutationShared(&replication_mutation);
        if (post_commit_error == null) {
            deferred_replication_gates.waitForDurabilityAndAuthority(ctx.replication_write_gate) catch |err| {
                post_commit_error = err;
            };
        } else {
            deferred_replication_gates.releaseTransition();
        }
        if (post_commit_error == null) if (durable_replication_schema_outbox_key) |key| {
            self.clearDurableReplicationOutbox(key) catch |err| std.log.warn(
                "schema HA durability acknowledged but outbox cleanup is pending path={s} version={d} err={s}",
                .{ self.core.path, table_schema.version, @errorName(err) },
            );
        };
        self.reconcilePublishedSchemaIndexes(table_schema.version);
        if (post_commit_error) |err| {
            std.log.warn(
                "schema committed locally but HA durability outcome is unknown path={s} version={d} err={s}",
                .{ self.core.path, table_schema.version, @errorName(err) },
            );
            return error.DurabilityOutcomeUnknown;
        }
    }

    fn refreshRelationalRuntimeMode(self: *DB) !void {
        const enabled = relationalColumns(self) != null;
        self.async_context.relational_base_rows = enabled;
        self.core.index_manager.setRelationalBaseRows(enabled);
        if (self.ttl_cleanup_context) |ctx| ctx.batch.relational_base_rows = enabled;
        if (self.enrichment_runtime) |runtime| runtime.setRelationalBaseRows(enabled);
        if (self.transaction_recovery_identity_context) |ctx| try ctx.updateRelationalColumns(
            relationalColumns(self),
            if (self.core.schema) |schema| schema.version else 0,
        );
    }

    fn publishRelationalRuntimeModePrepared(self: *DB, prepared: ?*db_core.PreparedRecoveryRelationalState) void {
        const enabled = relationalColumns(self) != null;
        self.async_context.relational_base_rows = enabled;
        self.core.index_manager.setRelationalBaseRows(enabled);
        if (self.ttl_cleanup_context) |ctx| ctx.batch.relational_base_rows = enabled;
        if (self.enrichment_runtime) |runtime| runtime.setRelationalBaseRows(enabled);
        if (self.transaction_recovery_identity_context) |ctx| {
            ctx.installPreparedRelationalState(prepared orelse unreachable);
        }
    }

    fn reconcilePublishedSchemaIndexes(self: *DB, _: u32) void {
        self.local_execution.schema_reconcile.schedule(.{
            .ptr = self,
            .lane = self.backend_runtime.durable_jobs,
            .owner_id = self.backend_owner_id,
            .stable_address = self.stable_address,
            .closing = &self.async_context.background_closing,
            .pass = reconcileSchemaPass,
        });
    }

    fn reconcileSchemaPass(ptr: *anyopaque) void {
        const self: *DB = @ptrCast(@alignCast(ptr));
        self.reconcileCurrentSchemaIndexesOnce();
    }

    fn reconcileCurrentSchemaIndexesOnce(self: *DB) void {
        self.lockApplyForPortableRuntime() catch return;
        if (self.core.schema == null or self.core.table_catalog.index_state == .none) {
            self.core.unlockApply();
            return;
        }
        const schema_version = self.core.schema.?.version;
        self.core.persistCatalogIndexState(.building) catch |err| {
            std.log.err("failed to persist schema index building state path={s} err={s}", .{ self.core.path, @errorName(err) });
        };
        self.core.unlockApply();

        self.core.refreshSchemaIndexes() catch |err| {
            self.lockApplyForPortableRuntime() catch return;
            defer self.core.unlockApply();
            if (self.core.schema != null and self.core.schema.?.version == schema_version) {
                self.core.persistCatalogIndexState(.failed) catch |state_err| {
                    std.log.err("failed to persist schema index failure path={s} err={s}", .{ self.core.path, @errorName(state_err) });
                };
            }
            // The schema is durable and reads remain available. Treat the
            // repairable derived-index degradation as an operational warning;
            // the durable `.failed` state is the authoritative alert signal.
            std.log.warn("schema committed; index reconciliation queued for repair path={s} err={s}", .{ self.core.path, @errorName(err) });
            return;
        };
        self.lockApplyForPortableRuntime() catch return;
        defer self.core.unlockApply();
        if (self.core.schema != null and self.core.schema.?.version == schema_version) {
            self.core.persistCatalogIndexState(.ready) catch |err| {
                std.log.err("schema indexes ready but catalog state persistence failed path={s} err={s}", .{ self.core.path, @errorName(err) });
            };
        }
    }

    fn validateStorageModeCompatibilityLocked(self: *DB, next_schema: schema_mod.TableSchema) !?u64 {
        if (self.core.schema) |current_schema| {
            if (current_schema.storage_mode != next_schema.storage_mode) return error.InvalidSchemaUpdateRequest;
            // Attaching/detaching an external base must never hide or resurrect
            // native rows under the same identity. Create a new table instead.
            if ((current_schema.external_base_source == null) != (next_schema.external_base_source == null)) return error.InvalidSchemaUpdateRequest;
            return null;
        }

        const catalog = self.core.table_catalog;
        if (catalog.reconciled) {
            if (next_schema.external_base_source != null and catalog.row_count != 0) return error.InvalidSchemaUpdateRequest;
            if (catalog.row_count != 0 and catalog.mode_initialized and
                catalog.storage_mode != next_schema.storage_mode)
                return error.InvalidSchemaUpdateRequest;
            return null;
        }

        // Legacy stores without catalog/identity cardinality use a bounded
        // one-time streaming reconciliation. Stop as soon as incompatibility
        // is known and never copy keys or values into an aggregate result.
        const State = struct {
            desired: schema_mod.StorageMode,
            external: bool,
            incompatible: bool = false,
            row_count: u64 = 0,

            fn visit(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                _ = value;
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                const mode: schema_mod.StorageMode = if (internal_keys.isPrimaryDocumentKey(key))
                    .document
                else if (internal_keys.isRelationalRowKey(key))
                    .relational
                else
                    return .@"continue";
                state.row_count +|= 1;
                if (!state.external and mode == state.desired) return .@"continue";
                state.incompatible = true;
                return .stop;
            }
        };
        const lower = [_]u8{internal_keys.user_namespace};
        const upper = [_]u8{internal_keys.user_namespace + 1};
        var state = State{ .desired = next_schema.storage_mode, .external = next_schema.external_base_source != null };
        try self.core.store.scanWithContext(&lower, &upper, .{}, &state, State.visit);
        if (state.incompatible) return error.InvalidSchemaUpdateRequest;
        return state.row_count;
    }

    /// Reinstall an already durable owner descriptor without requiring mutation
    /// authority. All schema/catalog/coverage effects must be exact no-ops; a
    /// changed descriptor returns false and must use setSchemaJson instead.
    pub fn rehydrateSchemaJson(self: *DB, schema_json: []const u8) !bool {
        var parsed_schema = try public_table_schema.parseValidatedTableSchema(self.alloc, schema_json);
        defer parsed_schema.deinit(self.alloc);
        const runtime_schema = try public_table_schema.deriveRuntimeTableSchema(self.alloc, parsed_schema);
        defer schema_mod.freeSchema(self.alloc, runtime_schema);
        const versioned_public_key = try public_table_schema.versionedSchemaKeyAlloc(self.alloc, runtime_schema.version);
        defer self.alloc.free(versioned_public_key);
        const writes = [_]docstore_mod.KVPair{
            .{ .key = public_schema_json_key, .value = schema_json },
            .{ .key = versioned_public_key, .value = schema_json },
        };
        var prepared_schema = try self.core.prepareSchemaMetadata(runtime_schema, &writes);
        defer prepared_schema.deinit();
        var prepared_recovery = if (self.transaction_recovery_identity_context != null)
            try db_core.PreparedRecoveryRelationalState.init(
                self.runtime_alloc,
                if (runtime_schema.storage_mode == .relational) runtime_schema.relational_columns else null,
                runtime_schema.version,
            )
        else
            null;
        defer if (prepared_recovery) |*prepared| prepared.deinit();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (!try self.core.rehydratePreparedSchemaMetadata(&prepared_schema, &writes)) return false;
        self.publishRelationalRuntimeModePrepared(if (prepared_recovery) |*prepared| prepared else null);
        return true;
    }

    pub fn setSchemaJson(self: *DB, alloc: Allocator, schema_json: []const u8) !void {
        return self.setSchemaJsonMode(alloc, schema_json, null);
    }

    pub const PublishedChildSchema = struct {
        fence: @import("relational_integrity_topology_contract.zig").Fence,
        before_schema_json_digest: [32]u8,
        schema_json_digest: [32]u8,
        before_catalog_digest: [32]u8,
        after_catalog_digest: [32]u8,
        ordered_receipt: OrderedApplyReceipt,
        native: bool = false,
    };

    pub const InitialHiddenChild = struct {
        fence: @import("relational_integrity_topology_contract.zig").Fence,
        child_table_name: []const u8,
        plan_id: [16]u8,
        plan_digest: [32]u8,
        schema_digest: [32]u8,
        public_schema_json_digest: [32]u8,
        catalog_digest: [32]u8,
        ordered_receipt: OrderedApplyReceipt,
        native: bool = false,
    };

    /// Fresh, unroutable FK child owners receive their candidate schema only
    /// after a durable metadata decision. The hidden record and schema share
    /// one write; Raft owners also persist the Raft marker, while native
    /// owners use the record itself as their exact durable operation receipt.
    pub fn provisionInitialHiddenChild(self: *DB, schema_json: []const u8, input: InitialHiddenChild, replication_lsn: ?u64, replication_payload: ?[]const u8) !void {
        const hidden = @import("relational_initial_child_publication.zig");
        if (self.local_execution.initial_child_bootstrap) |bootstrap| {
            if (!std.mem.eql(u8, &bootstrap.plan_id, &input.plan_id) or
                !std.mem.eql(u8, &bootstrap.plan_digest, &input.plan_digest) or
                !bootstrap.namespace.eql(input.fence.namespace) or
                !std.mem.eql(u8, &bootstrap.schema_digest, &input.schema_digest) or
                !std.mem.eql(u8, &bootstrap.public_schema_json_digest, &input.public_schema_json_digest) or
                !std.mem.eql(u8, &bootstrap.catalog_digest, &input.catalog_digest)) return error.InitialChildPublicationChanged;
        }
        if (input.fence.role != .child_generation_source or
            !input.fence.namespace.eql(self.core.identity_namespace) or
            input.child_table_name.len == 0 or input.child_table_name.len > 256 or
            !std.unicode.utf8ValidateSlice(input.child_table_name) or
            std.mem.allEqual(u8, &input.plan_id, 0) or std.mem.allEqual(u8, &input.plan_digest, 0) or
            (replication_lsn != null and replication_payload != null))
            return error.InvalidInitialChildPublication;
        const replay = if (input.native)
            try self.core.getStoreValue(self.alloc, hidden.key)
        else if (try self.orderedMutationAlreadyApplied(input.ordered_receipt))
            (try self.core.getStoreValue(self.alloc, hidden.key)) orelse return error.InitialChildPublicationChanged
        else
            null;
        if (replay) |raw| {
            defer self.alloc.free(raw);
            const prior = try hidden.Record.decode(raw);
            if (!std.mem.eql(u8, &prior.plan_id, &input.plan_id) or
                !std.mem.eql(u8, &prior.plan_digest, &input.plan_digest) or
                !prior.namespace.eql(input.fence.namespace) or
                !std.mem.eql(u8, &prior.schema_digest, &input.schema_digest) or
                !std.mem.eql(u8, &prior.public_schema_json_digest, &input.public_schema_json_digest) or
                !std.mem.eql(u8, &prior.catalog_digest, &input.catalog_digest) or
                prior.provision_term != input.ordered_receipt.term or prior.provision_index != input.ordered_receipt.index)
                return error.InitialChildPublicationChanged;
            if (replication_lsn) |lsn| try self.recordReplicationApplied(lsn);
            return;
        }
        var public_digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(schema_json, &public_digest, .{});
        if (!std.mem.eql(u8, &public_digest, &input.public_schema_json_digest)) return error.InvalidInitialChildPublication;
        var parsed = try public_table_schema.parseValidatedTableSchema(self.alloc, schema_json);
        defer parsed.deinit(self.alloc);
        if (parsed.storage_mode != .relational) return error.InvalidInitialChildPublication;
        const runtime_schema = try public_table_schema.deriveRuntimeTableSchema(self.alloc, parsed);
        defer schema_mod.freeSchema(self.alloc, runtime_schema);
        const versioned_key = try public_table_schema.versionedSchemaKeyAlloc(self.alloc, runtime_schema.version);
        defer self.alloc.free(versioned_key);
        const schema_writes = [_]docstore_mod.KVPair{
            .{ .key = public_schema_json_key, .value = schema_json },
            .{ .key = versioned_key, .value = schema_json },
        };
        var candidate = try self.core.prepareSchemaMetadataPublishedChild(runtime_schema, &schema_writes);
        defer candidate.deinit();
        const aic = candidate.integrity_catalog orelse return error.IntegrityCatalogChanged;
        var catalog_digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(aic.value, &catalog_digest, .{});
        if (!std.mem.eql(u8, &catalog_digest, &input.catalog_digest) or
            !std.mem.eql(u8, &aic.catalog.schema_digest, &input.schema_digest)) return error.IntegrityCatalogChanged;
        const record: hidden.Record = .{
            .phase = .hidden,
            .plan_id = input.plan_id,
            .plan_digest = input.plan_digest,
            .namespace = input.fence.namespace,
            .schema_version = runtime_schema.version,
            .row_count = 0,
            .schema_digest = input.schema_digest,
            .public_schema_json_digest = input.public_schema_json_digest,
            .catalog_digest = input.catalog_digest,
            .provision_term = input.ordered_receipt.term,
            .provision_index = input.ordered_receipt.index,
        };
        const encoded_record = try record.encode();
        var marker_buf: [ordered_apply_receipt_value_len]u8 = undefined;
        const marker = orderedApplyReceiptWrite(input.ordered_receipt, &marker_buf);
        // Self-referential parents share these hidden child owners. Install
        // their accepted generation scopes in the same durable transaction as
        // the initial schema and hidden gate, before any release can route a
        // row. External-parent scopes use the separate parent protocol.
        const admission = @import("relational_integrity_generation_admission.zig");
        const fks = try parsed.relationalForeignKeyDefinitions(self.alloc);
        defer if (fks.len > 0) self.alloc.free(fks);
        var self_arena = std.heap.ArenaAllocator.init(self.alloc);
        defer self_arena.deinit();
        const self_alloc = self_arena.allocator();
        var writes = try self.alloc.alloc(docstore_mod.KVPair, 6 + fks.len);
        defer self.alloc.free(writes);
        var write_count: usize = if (input.native) 3 else 4;
        writes[0] = schema_writes[0];
        writes[1] = schema_writes[1];
        writes[2] = .{ .key = hidden.key, .value = &encoded_record };
        if (!input.native) writes[3] = marker;
        for (fks) |fk| {
            if (!std.mem.eql(u8, fk.parent_table, input.child_table_name)) continue;
            const binding = aic.catalog.find(.foreign_key, fk.name) orelse return error.IntegrityCatalogChanged;
            const scope_key = try admission.scopeKey(input.child_table_name, fk.name);
            const key = try self_alloc.dupe(u8, &scope_key);
            const scope: admission.Scope = .{
                .child_table_id = input.fence.namespace.table_id,
                .child_table_name = input.child_table_name,
                .constraint_name = fk.name,
                .revision = 1,
                .phase = .active,
                .active_generation = binding.generation,
                .plan_id = input.plan_id,
                .decision_digest = input.plan_digest,
            };
            writes[write_count] = .{ .key = key, .value = try scope.encode(self_alloc) };
            write_count += 1;
        }
        var replication_lsn_buffer: [replication_applied_lsn_value_len]u8 = undefined;
        if (replication_lsn) |lsn| {
            writes[write_count] = replicationAppliedSequenceWrite(lsn, &replication_lsn_buffer);
            write_count += 1;
        }
        const replication_outbox = if (replication_payload) |payload| blk: {
            const mirror = self.local_execution.replication_async_batch_mirror orelse return error.ReplicationPublisherUnavailable;
            const from_lsn = mirror.publisher.nextLsn();
            const encoded = try encodeDurableReplicationOutboxAlloc(self.alloc, from_lsn, payload);
            const key = try durableReplicationOutboxKeyAlloc(self.alloc, .restore_batch, from_lsn, self.core.root_generation, payload);
            break :blk .{ .key = key, .value = encoded };
        } else null;
        defer if (replication_outbox) |outbox| {
            self.alloc.free(outbox.key);
            self.alloc.free(outbox.value);
        };
        if (replication_outbox) |outbox| {
            writes[write_count] = .{ .key = outbox.key, .value = outbox.value };
            write_count += 1;
        }
        var prepared = try self.core.prepareSchemaMetadataPublishedChild(runtime_schema, writes[0..write_count]);
        defer prepared.deinit();
        var prepared_recovery = if (self.transaction_recovery_identity_context != null)
            try db_core.PreparedRecoveryRelationalState.init(self.runtime_alloc, runtime_schema.relational_columns, runtime_schema.version)
        else
            null;
        defer if (prepared_recovery) |*state| state.deinit();
        var mutation = self.core.snapshot_admission.acquireMutation();
        defer mutation.release();
        try self.lockApplyForPortableRuntime();
        var apply_held = true;
        errdefer if (apply_held) self.core.unlockApply();
        if (!input.native) switch (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), input.ordered_receipt)) {
            .already_applied => {
                self.core.unlockApply();
                apply_held = false;
                return;
            },
            .apply => {},
        };
        // Two supervisors can preflight the same empty child before either
        // proposal commits. The later Raft entry is a deterministic rejected
        // command once the first provision's hidden receipt is durable.
        if (!input.native) if (try self.core.getStoreValue(self.alloc, hidden.key)) |prior_raw| {
            defer self.alloc.free(prior_raw);
            const prior = try hidden.Record.decode(prior_raw);
            if (std.mem.eql(u8, &prior.plan_id, &input.plan_id) and
                std.mem.eql(u8, &prior.plan_digest, &input.plan_digest) and
                prior.namespace.eql(input.fence.namespace) and
                prior.schema_version == runtime_schema.version and
                std.mem.eql(u8, &prior.schema_digest, &input.schema_digest) and
                std.mem.eql(u8, &prior.public_schema_json_digest, &input.public_schema_json_digest) and
                std.mem.eql(u8, &prior.catalog_digest, &input.catalog_digest) and
                prior.provision_term != 0 and prior.provision_index != 0)
                return error.InitialChildProvisionAlreadyCommitted;
        };
        if (try self.core.getStoreValue(self.alloc, public_schema_json_key)) |prior_schema| {
            self.alloc.free(prior_schema);
            return error.InitialChildPublicationChanged;
        }
        if (try self.core.getStoreValue(self.alloc, @import("relational_integrity_catalog.zig").key)) |prior_catalog| {
            self.alloc.free(prior_catalog);
            return error.InitialChildPublicationChanged;
        }
        if (try self.core.getStoreValue(self.alloc, hidden.key)) |prior_hidden| {
            defer self.alloc.free(prior_hidden);
            if (!input.native) return error.InitialChildPublicationChanged;
            // A second local supervisor may have won the commit after our
            // optimistic replay probe. The hidden record is the native
            // operation receipt; acknowledge only its exact immutable plan
            // and provision ordinal while still under the apply lock.
            const prior = try hidden.Record.decode(prior_hidden);
            if (!std.mem.eql(u8, &prior.plan_id, &input.plan_id) or
                !std.mem.eql(u8, &prior.plan_digest, &input.plan_digest) or
                !prior.namespace.eql(input.fence.namespace) or
                !std.mem.eql(u8, &prior.schema_digest, &input.schema_digest) or
                !std.mem.eql(u8, &prior.public_schema_json_digest, &input.public_schema_json_digest) or
                !std.mem.eql(u8, &prior.catalog_digest, &input.catalog_digest) or
                prior.provision_term != input.ordered_receipt.term or prior.provision_index != input.ordered_receipt.index)
                return error.InitialChildPublicationChanged;
            self.core.unlockApply();
            apply_held = false;
            return;
        }
        const row_count = try self.validateStorageModeCompatibilityLocked(runtime_schema);
        if (row_count != null and row_count.? != 0) return error.InitialChildPublicationChanged;
        _ = try self.core.commitPreparedSchemaMetadata(&prepared, writes[0..write_count], &.{}, row_count);
        if (replication_outbox != null) self.local_execution.durable_replication_outbox_maybe.store(true, .release);
        self.local_execution.initial_child_hidden.store(true, .release);
        self.publishRelationalRuntimeModePrepared(if (prepared_recovery) |*state| state else null);
        self.core.unlockApply();
        apply_held = false;
        self.reconcilePublishedSchemaIndexes(runtime_schema.version);
    }

    fn applyInitialChildPhase(self: *DB, fence: @import("relational_integrity_topology_contract.zig").Fence, control: @import("relational_integrity_topology_contract.zig").InitialChildControl, phase: @import("relational_initial_child_publication.zig").Phase, entry: OrderedApplyReceipt, native: bool, replication_lsn: ?u64, replication_payload: ?[]const u8) !void {
        const hidden = @import("relational_initial_child_publication.zig");
        if (fence.role != .child_generation_source or !fence.namespace.eql(self.core.identity_namespace) or
            std.mem.allEqual(u8, &control.plan_id, 0) or std.mem.allEqual(u8, &control.plan_digest, 0) or
            !std.mem.eql(u8, &control.catalog_digest, &fence.catalog_digest) or
            phase == .hidden or (replication_lsn != null and replication_payload != null)) return error.InvalidInitialChildPublication;
        const replay = if (native)
            try self.core.getStoreValue(self.alloc, hidden.key)
        else if (try self.orderedMutationAlreadyApplied(entry))
            (try self.core.getStoreValue(self.alloc, hidden.key)) orelse return error.InitialChildPublicationChanged
        else
            null;
        if (replay) |raw| {
            defer self.alloc.free(raw);
            const prior = try hidden.Record.decode(raw);
            if (!std.mem.eql(u8, &prior.plan_id, &control.plan_id) or
                !std.mem.eql(u8, &prior.plan_digest, &control.plan_digest) or
                !prior.namespace.eql(fence.namespace) or prior.schema_version != control.schema_version or
                !std.mem.eql(u8, &prior.schema_digest, &control.schema_digest) or
                !std.mem.eql(u8, &prior.public_schema_json_digest, &control.public_schema_json_digest) or
                !std.mem.eql(u8, &prior.catalog_digest, &control.catalog_digest))
                return error.InitialChildPublicationChanged;
            if (prior.phase == phase) {
                if (prior.phase_term != entry.term or prior.phase_index != entry.index) return error.InitialChildPublicationChanged;
                if (replication_lsn) |lsn| try self.recordReplicationApplied(lsn);
                return;
            }
            if (!native or prior.phase != .hidden) return error.InitialChildPublicationChanged;
        }
        var mutation = self.core.snapshot_admission.acquireMutation();
        defer mutation.release();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (!native) switch (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), entry)) {
            .already_applied => return,
            .apply => {},
        };
        var txn = try self.core.store.beginWriteTxn();
        errdefer txn.abort();
        const before = try hidden.load(&txn);
        if (before == null and phase == .canceled) {
            const canceled: hidden.Record = .{
                .phase = .canceled,
                .plan_id = control.plan_id,
                .plan_digest = control.plan_digest,
                .namespace = fence.namespace,
                .schema_version = control.schema_version,
                .row_count = 0,
                .schema_digest = control.schema_digest,
                .public_schema_json_digest = control.public_schema_json_digest,
                .catalog_digest = control.catalog_digest,
                .provision_term = 0,
                .provision_index = 0,
                .phase_term = entry.term,
                .phase_index = entry.index,
            };
            _ = try hidden.stageUnprovisionedCancel(&txn, canceled);
            if (!native) {
                var marker_buf: [ordered_apply_receipt_value_len]u8 = undefined;
                const marker = orderedApplyReceiptWrite(entry, &marker_buf);
                try txn.put(marker.key, marker.value);
            }
            if (replication_lsn) |lsn| {
                var lsn_buf: [replication_applied_lsn_value_len]u8 = undefined;
                const lsn_marker = replicationAppliedSequenceWrite(lsn, &lsn_buf);
                try txn.put(lsn_marker.key, lsn_marker.value);
            }
            try self.stageRestoreStagingReplicationOutbox(&txn, replication_payload);
            try txn.commit();
            self.local_execution.initial_child_hidden.store(true, .release);
            return;
        }
        const current = before orelse return error.InitialChildPublicationMissing;
        if (!current.namespace.eql(fence.namespace) or
            !std.mem.eql(u8, &current.catalog_digest, &fence.catalog_digest) or
            !std.mem.eql(u8, &current.plan_id, &control.plan_id) or
            !std.mem.eql(u8, &current.plan_digest, &control.plan_digest) or
            current.schema_version != control.schema_version or
            !std.mem.eql(u8, &current.schema_digest, &control.schema_digest) or
            !std.mem.eql(u8, &current.public_schema_json_digest, &control.public_schema_json_digest)) return error.InitialChildPublicationChanged;
        if (native and current.phase == phase) {
            if (current.phase_term != entry.term or current.phase_index != entry.index) return error.InitialChildPublicationChanged;
            return;
        }
        if (native and current.phase != .hidden) return error.InitialChildPublicationChanged;
        if (current.provision_term == 0) {
            if (phase != .canceled) return error.InitialChildPublicationChanged;
            if (!native) {
                var marker_buf: [ordered_apply_receipt_value_len]u8 = undefined;
                const marker = orderedApplyReceiptWrite(entry, &marker_buf);
                try txn.put(marker.key, marker.value);
            }
            if (replication_lsn) |lsn| {
                var lsn_buf: [replication_applied_lsn_value_len]u8 = undefined;
                const lsn_marker = replicationAppliedSequenceWrite(lsn, &lsn_buf);
                try txn.put(lsn_marker.key, lsn_marker.value);
            }
            try self.stageRestoreStagingReplicationOutbox(&txn, replication_payload);
            try txn.commit();
            return;
        }
        const stored_catalog = txn.get(@import("relational_integrity_catalog.zig").key) catch return error.IntegrityCatalogChanged;
        var catalog_digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(stored_catalog, &catalog_digest, .{});
        if (!std.mem.eql(u8, &catalog_digest, &current.catalog_digest)) return error.IntegrityCatalogChanged;
        const stored_schema = txn.get(public_schema_json_key) catch return error.IntegrityCatalogChanged;
        var schema_digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(stored_schema, &schema_digest, .{});
        if (!std.mem.eql(u8, &schema_digest, &current.public_schema_json_digest)) return error.IntegrityCatalogChanged;
        if (phase == .released) {
            var parsed_schema = try public_table_schema.parseValidatedTableSchema(self.alloc, stored_schema);
            defer parsed_schema.deinit(self.alloc);
            var parsed_catalog = try @import("relational_integrity_catalog.zig").decode(self.alloc, stored_catalog);
            defer parsed_catalog.deinit();
            const fks = try parsed_schema.relationalForeignKeyDefinitions(self.alloc);
            defer if (fks.len > 0) self.alloc.free(fks);
            for (fks) |fk| {
                // Physical table identity is hash-derived by metadata. Match
                // the hidden child without relying on a public route, then
                // require its own accepted parent generation to be durable.
                if (!std.mem.startsWith(u8, fk.parent_table, "table:")) continue;
                const physical_id = std.hash.Wyhash.hash(0x54424c45, fk.parent_table);
                if ((if (physical_id == 0) @as(u64, 1) else physical_id) != current.namespace.table_id) continue;
                const scope = (try @import("relational_integrity_generation_admission.zig").load(&txn, fk.parent_table, fk.name)) orelse return error.InitialChildPublicationChanged;
                const binding = parsed_catalog.find(.foreign_key, fk.name) orelse return error.IntegrityCatalogChanged;
                if (scope.phase != .active or scope.active_generation == null or
                    !std.mem.eql(u8, &scope.active_generation.?, &binding.generation) or
                    !std.mem.eql(u8, &scope.plan_id, &current.plan_id) or
                    !std.mem.eql(u8, &scope.decision_digest, &current.plan_digest))
                    return error.InitialChildPublicationChanged;
            }
        }
        const table_raw = txn.get(@import("table_catalog.zig").key) catch return error.InitialChildPublicationChanged;
        if ((try @import("table_catalog.zig").Catalog.decode(table_raw)).row_count != 0) return error.InitialChildPublicationChanged;
        _ = try hidden.stagePhase(&txn, current, phase, entry.term, entry.index);
        if (!native) {
            var marker_buf: [ordered_apply_receipt_value_len]u8 = undefined;
            const marker = orderedApplyReceiptWrite(entry, &marker_buf);
            try txn.put(marker.key, marker.value);
        }
        if (replication_lsn) |lsn| {
            var lsn_buf: [replication_applied_lsn_value_len]u8 = undefined;
            const lsn_marker = replicationAppliedSequenceWrite(lsn, &lsn_buf);
            try txn.put(lsn_marker.key, lsn_marker.value);
        }
        try self.stageRestoreStagingReplicationOutbox(&txn, replication_payload);
        try txn.commit();
        if (phase == .released) self.local_execution.initial_child_hidden.store(false, .release);
    }

    /// Called only by the private child-owner publication control after its
    /// direct metadata read-index decision. The schema, integrity catalog,
    /// Raft marker and source-fence release commit atomically.
    pub fn installPublishedChildSchema(self: *DB, alloc: Allocator, schema_json: []const u8, publication: PublishedChildSchema) !void {
        if ((publication.fence.role != .child_generation_source and publication.fence.role != .child_generation_dual) or
            !publication.fence.namespace.eql(self.core.identity_namespace)) return error.InvalidIntegrityTopologyFence;
        var digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(schema_json, &digest, .{});
        if (!std.mem.eql(u8, &digest, &publication.schema_json_digest)) return error.InvalidGenerationPublication;
        if (publication.native) {
            // Local retries use the exact publication digest, not a synthetic
            // Raft high-water mark that could suppress a later publication.
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            const admission = @import("relational_integrity_generation_admission.zig");
            const raw = read.get(admission.source_install_receipt_key) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            if (raw) |bytes| {
                const receipt = try admission.AppliedReceipt.decode(bytes);
                const expected = try admission.sourceInstallDigest(publication.fence, publication.before_schema_json_digest, publication.schema_json_digest, publication.before_catalog_digest, publication.after_catalog_digest);
                if (std.mem.eql(u8, &receipt.digest, &expected)) {
                    const completed = (try @import("relational_integrity_topology.zig").completed(&read)) orelse return error.GenerationAdmissionChanged;
                    if (!completed.eql(publication.fence) or receipt.term != publication.ordered_receipt.term or receipt.index != publication.ordered_receipt.index)
                        return error.GenerationAdmissionChanged;
                    const actual = try read.get(public_schema_json_key);
                    if (!std.mem.eql(u8, actual, schema_json)) return error.IntegrityCatalogChanged;
                    var actual_digest: [32]u8 = undefined;
                    std.crypto.hash.Blake3.hash(try read.get(@import("relational_integrity_catalog.zig").key), &actual_digest, .{});
                    if (!std.mem.eql(u8, &actual_digest, &publication.after_catalog_digest)) return error.IntegrityCatalogChanged;
                    return;
                }
            }
        }
        // The exact Raft entry may be replayed after the accepted catalog has
        // already advanced. Check its durable marker before re-preparing the
        // old→new catalog comparison; the apply-locked check below still
        // closes the race with another entry.
        if (!publication.native and try self.orderedMutationAlreadyApplied(publication.ordered_receipt)) return;
        return self.setSchemaJsonMode(alloc, schema_json, publication);
    }

    fn setSchemaJsonMode(self: *DB, alloc: Allocator, schema_json: []const u8, publication: ?PublishedChildSchema) !void {
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        defer row_policy_lease.release();
        var schedule_replication_recovery_on_exit = false;
        defer if (schedule_replication_recovery_on_exit) self.scheduleDurableReplicationOutboxRecovery();
        _ = alloc;
        var parsed_schema = try public_table_schema.parseValidatedTableSchema(self.alloc, schema_json);
        defer parsed_schema.deinit(self.alloc);
        const runtime_schema = try public_table_schema.deriveRuntimeTableSchema(self.alloc, parsed_schema);
        defer schema_mod.freeSchema(self.alloc, runtime_schema);
        var prepared_recovery = if (self.transaction_recovery_identity_context != null)
            try db_core.PreparedRecoveryRelationalState.init(
                self.runtime_alloc,
                if (runtime_schema.storage_mode == .relational) runtime_schema.relational_columns else null,
                runtime_schema.version,
            )
        else
            null;
        defer if (prepared_recovery) |*prepared| prepared.deinit();

        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.ensureDurableReplicationStartupBarrier();
        try self.enforceReplicationWriteGate();
        try self.preflightReplicationMetadataSyncCommit();
        const replication_schema_payload = if (self.local_execution.replication_async_metadata_mirror) |mirror|
            if (publication) |published|
                try replication_effects_mod.encodePublishedChildSchemaMetadataMutationAlloc(self.alloc, runtime_schema, schema_json, .{
                    .fence = published.fence,
                    .before_schema_json_digest = published.before_schema_json_digest,
                    .schema_json_digest = published.schema_json_digest,
                    .before_catalog_digest = published.before_catalog_digest,
                    .after_catalog_digest = published.after_catalog_digest,
                    .applied_term = published.ordered_receipt.term,
                    .applied_index = published.ordered_receipt.index,
                })
            else if (replicationMirrorRequiresDurableOutbox(mirror))
                try replication_effects_mod.encodeSchemaMetadataMutationAlloc(self.alloc, runtime_schema, schema_json)
            else
                null
        else
            null;
        defer if (replication_schema_payload) |payload| self.alloc.free(payload);
        const durable_replication_schema_payload = if (self.local_execution.replication_async_metadata_mirror) |mirror|
            if (replicationMirrorRequiresDurableOutbox(mirror)) replication_schema_payload else null
        else
            null;
        const durable_replication_schema_lsn = if (durable_replication_schema_payload != null)
            self.local_execution.replication_async_metadata_mirror.?.publisher.nextLsn()
        else
            null;
        const durable_replication_schema_outbox = if (durable_replication_schema_payload) |payload|
            try encodeDurableReplicationOutboxAlloc(self.alloc, durable_replication_schema_lsn.?, payload)
        else
            null;
        defer if (durable_replication_schema_outbox) |outbox| self.alloc.free(outbox);
        const durable_replication_schema_outbox_key = if (durable_replication_schema_outbox != null)
            try durableReplicationOutboxKeyAlloc(self.alloc, .schema, durable_replication_schema_lsn.?, self.core.root_generation, durable_replication_schema_payload.?)
        else
            null;
        defer if (durable_replication_schema_outbox_key) |key| self.alloc.free(key);
        const versioned_public_key = try public_table_schema.versionedSchemaKeyAlloc(self.alloc, runtime_schema.version);
        defer self.alloc.free(versioned_public_key);
        var schema_metadata_writes: [5]docstore_mod.KVPair = undefined;
        var schema_metadata_write_count: usize = 2;
        schema_metadata_writes[0] = .{ .key = public_schema_json_key, .value = schema_json };
        schema_metadata_writes[1] = .{ .key = versioned_public_key, .value = schema_json };
        if (durable_replication_schema_outbox) |outbox| {
            schema_metadata_writes[2] = .{ .key = durable_replication_schema_outbox_key.?, .value = outbox };
            schema_metadata_write_count = 3;
        }
        var raft_marker_buffer: [ordered_apply_receipt_value_len]u8 = undefined;
        var source_receipt_buffer: [48]u8 = undefined;
        if (publication) |published| {
            if (!published.native) {
                const marker = orderedApplyReceiptWrite(published.ordered_receipt, &raft_marker_buffer);
                schema_metadata_writes[schema_metadata_write_count] = marker;
                schema_metadata_write_count += 1;
            }
            const admission = @import("relational_integrity_generation_admission.zig");
            const digest = try admission.sourceInstallDigest(published.fence, published.before_schema_json_digest, published.schema_json_digest, published.before_catalog_digest, published.after_catalog_digest);
            source_receipt_buffer = (admission.AppliedReceipt{ .digest = digest, .term = published.ordered_receipt.term, .index = published.ordered_receipt.index }).encode();
            schema_metadata_writes[schema_metadata_write_count] = .{ .key = admission.source_install_receipt_key, .value = &source_receipt_buffer };
            schema_metadata_write_count += 1;
        }
        var prepared_schema = if (publication != null)
            try self.core.prepareSchemaMetadataPublishedChild(runtime_schema, schema_metadata_writes[0..schema_metadata_write_count])
        else
            try self.core.prepareSchemaMetadata(runtime_schema, schema_metadata_writes[0..schema_metadata_write_count]);
        defer prepared_schema.deinit();
        if (publication) |published| {
            const current_catalog = (try self.core.getStoreValue(self.alloc, @import("relational_integrity_catalog.zig").key)) orelse return error.IntegrityCatalogChanged;
            defer self.alloc.free(current_catalog);
            var before_digest: [32]u8 = undefined;
            std.crypto.hash.Blake3.hash(current_catalog, &before_digest, .{});
            var after_digest: [32]u8 = undefined;
            std.crypto.hash.Blake3.hash((prepared_schema.integrity_catalog orelse return error.IntegrityCatalogChanged).value, &after_digest, .{});
            if (!std.mem.eql(u8, &before_digest, &published.before_catalog_digest) or
                !std.mem.eql(u8, &after_digest, &published.after_catalog_digest)) return error.IntegrityCatalogChanged;
        }
        try self.lockApplyForPortableRuntime();
        var apply_held = true;
        errdefer if (apply_held) self.core.unlockApply();
        if (publication) |published| if (!published.native) switch (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), published.ordered_receipt)) {
            .already_applied => {
                self.core.unlockApply();
                apply_held = false;
                return;
            },
            .apply => {},
        };
        if (publication) |published| {
            const existing_schema = (try self.core.getStoreValue(self.alloc, public_schema_json_key)) orelse return error.IntegrityCatalogChanged;
            defer self.alloc.free(existing_schema);
            var before_schema_digest: [32]u8 = undefined;
            std.crypto.hash.Blake3.hash(existing_schema, &before_schema_digest, .{});
            if (!std.mem.eql(u8, &before_schema_digest, &published.before_schema_json_digest)) return error.IntegrityCatalogChanged;
        }
        try self.enforceReplicationWriteGate();
        const reconciled_row_count = try self.validateStorageModeCompatibilityLocked(runtime_schema);
        if (durable_replication_schema_outbox_key != null) self.local_execution.durable_replication_outbox_maybe.store(true, .release);
        _ = if (publication) |published|
            try self.core.commitPreparedSchemaMetadataPublishedChild(
                &prepared_schema,
                schema_metadata_writes[0..schema_metadata_write_count],
                &.{},
                reconciled_row_count,
                published.fence,
            )
        else
            try self.core.commitPreparedSchemaMetadata(
                &prepared_schema,
                schema_metadata_writes[0..schema_metadata_write_count],
                &.{},
                reconciled_row_count,
            );
        schedule_replication_recovery_on_exit = durable_replication_schema_outbox_key != null;
        self.publishRelationalRuntimeModePrepared(if (prepared_recovery) |*prepared| prepared else null);

        var ctx = self.batchContext();
        var deferred_replication_gates = ReplicationDeferredCommitGates.begin(replicationTransitionMutexFromContext(&ctx));
        defer deferred_replication_gates.releaseTransition();
        var post_commit_error: ?anyerror = null;
        if (replication_schema_payload) |payload|
            deferred_replication_gates.append(appendReplicationEncodedSchemaMetadataCommitLockedContext(&ctx, payload) catch |err| blk: {
                post_commit_error = err;
                break :blk null;
            })
        else
            deferred_replication_gates.append(appendReplicationSchemaMetadataCommitLockedContext(&ctx, runtime_schema, schema_json) catch |err| blk: {
                post_commit_error = err;
                break :blk null;
            });
        self.core.unlockApply();
        apply_held = false;
        releaseReplicationMutationShared(&replication_mutation);
        if (post_commit_error == null) {
            deferred_replication_gates.waitForDurabilityAndAuthority(ctx.replication_write_gate) catch |err| {
                post_commit_error = err;
            };
        } else {
            deferred_replication_gates.releaseTransition();
        }
        if (post_commit_error == null) if (durable_replication_schema_outbox_key) |key| {
            self.clearDurableReplicationOutbox(key) catch |err| std.log.warn(
                "schema HA durability acknowledged but outbox cleanup is pending path={s} version={d} err={s}",
                .{ self.core.path, runtime_schema.version, @errorName(err) },
            );
        };
        self.reconcilePublishedSchemaIndexes(runtime_schema.version);
        if (post_commit_error) |err| {
            std.log.warn(
                "schema committed locally but HA durability outcome is unknown path={s} version={d} err={s}",
                .{ self.core.path, runtime_schema.version, @errorName(err) },
            );
            return error.DurabilityOutcomeUnknown;
        }
    }

    pub fn getSchemaJson(self: *DB, alloc: Allocator) !?[]u8 {
        return try self.core.getStoreValue(alloc, public_schema_json_key);
    }

    /// Storage mode is immutable once a DB contains a schema or user rows, but
    /// take the shared apply lock so callers never race initial publication.
    pub fn usesRelationalStorage(self: *DB) bool {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        return relationalColumns(self) != null;
    }

    /// Refresh schema-derived algebraic index configs (notably dynamic-template
    /// rules) in place from the given table schema JSON, so a dynamic-template
    /// change applies to a running DB without a reopen.
    pub fn reloadAlgebraicSchemaConfigs(self: *DB, schema_json: []const u8) !void {
        try self.core.index_manager.reloadAlgebraicSchemaConfigs(schema_json);
    }

    pub fn beginTransaction(self: *DB, timestamp_ns: u64) !transactions_mod.TxnId {
        const txn_id = makeTxnId(self);
        return try self.beginTransactionWithIdAndParticipants(txn_id, timestamp_ns, &.{});
    }

    pub fn beginTransactionWithId(self: *DB, txn_id: transactions_mod.TxnId, timestamp_ns: u64) !transactions_mod.TxnId {
        return try self.beginTransactionWithIdAndParticipants(txn_id, timestamp_ns, &.{});
    }

    pub fn beginTransactionWithParticipants(self: *DB, timestamp_ns: u64, participants: []const []const u8) !transactions_mod.TxnId {
        const txn_id = makeTxnId(self);
        return try self.beginTransactionWithIdAndParticipants(txn_id, timestamp_ns, participants);
    }

    pub fn beginTransactionWithIdAndParticipants(self: *DB, txn_id: transactions_mod.TxnId, timestamp_ns: u64, participants: []const []const u8) !transactions_mod.TxnId {
        return try self.beginTransactionWithIdAndParticipantsCreatedAt(txn_id, timestamp_ns, timestamp_ns, participants);
    }

    pub fn beginTransactionWithIdAndParticipantsCreatedAt(
        self: *DB,
        txn_id: transactions_mod.TxnId,
        timestamp_ns: u64,
        created_at_ns: u64,
        participants: []const []const u8,
    ) !transactions_mod.TxnId {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        defer row_policy_lease.release();
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        if (self.local_execution.restore_staging_required.load(.acquire)) {
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            try @import("restore_staging.zig").requireScope(self.alloc, &read, null, false);
        }
        return try self.core.beginTransactionWithParticipantsCreatedAt(txn_id, timestamp_ns, created_at_ns, participants);
    }

    pub fn beginTransactionWithIdAndParticipantsCreatedAtAndRole(
        self: *DB,
        txn_id: transactions_mod.TxnId,
        timestamp_ns: u64,
        created_at_ns: u64,
        participants: []const []const u8,
        coordinator: bool,
    ) !transactions_mod.TxnId {
        return try self.beginTransactionWithIdAndParticipantsCreatedAtRoleAndRetention(
            txn_id,
            timestamp_ns,
            created_at_ns,
            participants,
            coordinator,
            false,
        );
    }

    pub fn beginTransactionWithIdAndParticipantsCreatedAtRoleAndRetention(
        self: *DB,
        txn_id: transactions_mod.TxnId,
        timestamp_ns: u64,
        created_at_ns: u64,
        participants: []const []const u8,
        coordinator: bool,
        retain_terminal: bool,
    ) !transactions_mod.TxnId {
        return self.beginTransactionScoped(txn_id, timestamp_ns, created_at_ns, participants, coordinator, retain_terminal, null);
    }

    pub fn beginTransactionScoped(self: *DB, txn_id: transactions_mod.TxnId, timestamp_ns: u64, created_at_ns: u64, participants: []const []const u8, coordinator: bool, retain_terminal: bool, scope: ?[32]u8) !transactions_mod.TxnId {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        defer row_policy_lease.release();
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        if (self.local_execution.restore_staging_required.load(.acquire) or scope != null) {
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            try @import("restore_staging.zig").requireMutableScope(self.alloc, &read, scope);
        }
        return try self.core.beginTransactionWithParticipantsCreatedAtRoleAndRetention(
            txn_id,
            timestamp_ns,
            created_at_ns,
            participants,
            coordinator,
            retain_terminal,
        );
    }

    pub fn beginReplicatedTransactionAtOrderedReceipt(
        self: *DB,
        txn_id: transactions_mod.TxnId,
        timestamp_ns: u64,
        created_at_ns: u64,
        participants: []const []const u8,
        coordinator: bool,
        retain_terminal: bool,
        identity: OrderedApplyReceipt,
    ) !transactions_mod.TxnId {
        return self.beginReplicatedTransactionScoped(txn_id, timestamp_ns, created_at_ns, participants, coordinator, retain_terminal, identity, null);
    }

    pub fn beginReplicatedTransactionScoped(self: *DB, txn_id: transactions_mod.TxnId, timestamp_ns: u64, created_at_ns: u64, participants: []const []const u8, coordinator: bool, retain_terminal: bool, identity: OrderedApplyReceipt, scope: ?[32]u8) !transactions_mod.TxnId {
        lockApply(self);
        defer self.core.unlockApply();
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        switch (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), identity)) {
            .already_applied => return txn_id,
            .apply => {},
        }
        if (self.local_execution.restore_staging_required.load(.acquire) or scope != null) {
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            try @import("restore_staging.zig").requireMutableScope(self.alloc, &read, scope);
        }
        var value_buf: [ordered_apply_receipt_value_len]u8 = undefined;
        const marker = orderedApplyReceiptWrite(identity, &value_buf);
        return try self.core.beginTransactionWithParticipantsCreatedAtRoleAndRetentionExtraBatch(
            txn_id,
            timestamp_ns,
            created_at_ns,
            participants,
            coordinator,
            retain_terminal,
            .{ .writes = &.{marker} },
        );
    }

    pub fn writeIntents(
        self: *DB,
        txn_id: transactions_mod.TxnId,
        intents: []const transactions_mod.WriteIntent,
        predicates: []const transactions_mod.VersionPredicate,
    ) !void {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        var preparation: RequestPreparationContext = undefined;
        preparation.init(self);
        defer preparation.deinit();
        var retries: usize = 0;
        while (true) {
            self.writeIntentsPreparedOnce(txn_id, intents, predicates, preparation.guard.allocator()) catch |err| switch (err) {
                error.PreparedGenerationChanged => {
                    if (retries >= 2) return err;
                    retries += 1;
                    continue;
                },
                else => return preparation.mapError(err),
            };
            return;
        }
    }

    fn writeIntentsPreparedOnce(
        self: *DB,
        txn_id: transactions_mod.TxnId,
        intents: []const transactions_mod.WriteIntent,
        predicates: []const transactions_mod.VersionPredicate,
        preparation_alloc: Allocator,
    ) !void {
        const schema_namespace = self.core.schemaNamespaceGeneration();
        const prepared_intents = try preparation_alloc.dupe(transactions_mod.WriteIntent, intents);
        defer preparation_alloc.free(prepared_intents);
        for (prepared_intents) |*intent| intent.prepared_row = null;
        defer freePreparedIntentRows(preparation_alloc, prepared_intents);
        var identity_upsert_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer identity_upsert_keys.deinit(preparation_alloc);
        for (intents) |intent| {
            if (intent.value == null or isMetadataKey(intent.key)) continue;
            try identity_upsert_keys.append(preparation_alloc, intent.key);
        }
        const binding = try self.core.transactionSchemaBinding(preparation_alloc, txn_id);
        var view = try self.acquireTransactionSchemaView(preparation_alloc, binding);
        defer if (view) |*pinned| pinned.release();
        for (intents) |intent| {
            if (isProtectedIntegrityKey(intent.key) or isProtectedRangeWriteKey(intent.key)) return error.InvalidIntegrityOperation;
            if (hasCoordinatedConstraints(view) and !isMetadataKey(intent.key)) return error.ForeignKeyCoordinationRequired;
        }
        for (predicates) |predicate| if (isProtectedIntegrityKey(predicate.key)) return error.InvalidIntegrityOperation;
        try self.prepareTransactionRows(preparation_alloc, prepared_intents, view);

        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        if (schema_namespace != self.core.schemaNamespaceGeneration()) return error.PreparedGenerationChanged;
        if (binding == null) try self.validatePreparedSchemaViewLocked(view);
        {
            var topology_manager = try self.core.initTxnManager();
            defer topology_manager.deinit();
            var topology_read = try self.core.store.beginProbeTxn();
            defer topology_read.abort();
            if (self.local_execution.restore_staging_required.load(.acquire)) try @import("restore_staging.zig").requireScope(preparation_alloc, &topology_read, null, false);
            try @import("relational_integrity_topology.zig").admitPrepare(&topology_read, &topology_manager, preparation_alloc, txn_id);
        }
        try self.failIfIdentityOrdinalExhaustedForNewUpserts(identity_upsert_keys.items);
        const index_spans = try self.collectIndexSpanReservations(preparation_alloc, prepared_intents, view);
        defer if (index_spans.len != 0) preparation_alloc.free(index_spans);
        try self.prepareOnlineVectorIntentBoundsLocked(preparation_alloc, prepared_intents, view);
        var guarded_predicates = std.ArrayListUnmanaged(transactions_mod.VersionPredicate).empty;
        defer guarded_predicates.deinit(preparation_alloc);
        try guarded_predicates.appendSlice(preparation_alloc, predicates);
        var endpoint_dependencies = std.heap.ArenaAllocator.init(preparation_alloc);
        defer endpoint_dependencies.deinit();
        try self.prepareGraphEndpointDependenciesLocked(preparation_alloc, endpoint_dependencies.allocator(), txn_id, prepared_intents, view, &guarded_predicates);
        try self.core.writeIntentsExtraBatch(txn_id, prepared_intents, guarded_predicates.items, .{
            .preparation_allocator = preparation_alloc,
            .schema_binding = .{ .version = if (view) |pinned| pinned.version() else null },
            .index_span_digests = index_spans,
        });
    }

    pub fn writeTransaction(self: *DB, txn_id: types.TxnId, req: types.TransactionIntentRequest) !void {
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.writeTransactionInternal(txn_id, req, null);
    }

    pub fn writeReplicatedTransactionAtOrderedReceipt(
        self: *DB,
        txn_id: types.TxnId,
        req: types.TransactionIntentRequest,
        identity: OrderedApplyReceipt,
    ) !void {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        try self.writeTransactionInternal(txn_id, req, identity);
    }

    fn writeTransactionInternal(
        self: *DB,
        txn_id: types.TxnId,
        req: types.TransactionIntentRequest,
        ordered_receipt: ?OrderedApplyReceipt,
    ) !void {
        if (ordered_receipt == null) try self.maybeFinalizePendingRowPolicyPublication();
        var verified_principal: ?std.json.Parsed(row_policy_authority_mod.Payload) = null;
        defer if (verified_principal) |*principal| principal.deinit();
        var row_policy_lease: ?row_policy_gate_mod.Gate.Lease = null;
        if (req.row_policy_principal_proof.len != 0) {
            if (req.row_policy_database.len == 0 or req.row_policy_admitted_at_seconds <= 0 or
                req.restore_staging_scope != null) return error.RowPolicyAuthenticationRequired;
            const now_seconds: i64 = @intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s));
            verified_principal = try self.verifyRowPolicyPrincipal(self.alloc, req.row_policy_principal_proof, req.row_policy_database, .write, if (ordered_receipt != null) req.row_policy_admitted_at_seconds else now_seconds);
            row_policy_lease = if (ordered_receipt != null)
                try self.local_execution.row_policy_gate.enterReplicatedPrincipal(&verified_principal.?.value)
            else
                try self.local_execution.row_policy_gate.enterVerifiedPrincipal(&verified_principal.?.value, now_seconds);
        } else if (req.row_policy_database.len != 0 or req.row_policy_admitted_at_seconds != 0) {
            return error.RowPolicyAuthenticationRequired;
        } else if (ordered_receipt == null) {
            row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        } else if (self.local_execution.row_policy_gate.currentPhase() != .disabled and
            (req.writes.len != 0 or req.deletes.len != 0 or req.transforms.len != 0))
        {
            return error.RowPolicyAuthenticationRequired;
        }
        defer if (row_policy_lease) |*lease| lease.release();
        var preparation: RequestPreparationContext = undefined;
        preparation.init(self);
        defer preparation.deinit();
        const max_prepared_retries = 2;
        var retries: usize = 0;
        while (true) {
            self.writeTransactionInternalOnce(txn_id, req, ordered_receipt, preparation.guard.allocator(), if (verified_principal) |*principal| &principal.value else null, if (row_policy_lease) |*lease| lease else null) catch |err| switch (err) {
                error.PreparedGenerationChanged, error.PreparedReadSetChanged => {
                    if (retries >= max_prepared_retries) return err;
                    retries += 1;
                    continue;
                },
                else => return preparation.mapError(err),
            };
            return;
        }
    }

    fn writeTransactionInternalOnce(
        self: *DB,
        txn_id: types.TxnId,
        req: types.TransactionIntentRequest,
        ordered_receipt: ?OrderedApplyReceipt,
        preparation_alloc: Allocator,
        row_policy_principal: ?*const row_policy_authority_mod.Payload,
        row_policy_lease: ?*const row_policy_gate_mod.Gate.Lease,
    ) !void {
        if (req.relational_index_maintenance != null and
            (req.writes.len != 0 or req.deletes.len != 0 or req.transforms.len != 0 or
                req.predicates.len != 0 or req.integrity.len != 0 or req.integrity_commands.len != 0 or
                req.relational_activation != null or req.relational_retirement != null or
                req.relational_repair or req.restore_staging_scope != null)) return error.InvalidBatchRequest;
        const schema_namespace = self.core.schemaNamespaceGeneration();
        // Parse and expand transforms from one optimistic read snapshot before
        // entering the serialized commit section. The commit fence below
        // validates both that read set and the immutable schema epoch.
        var transform_snapshot = try self.captureTransformReadSnapshot(
            preparation_alloc,
            types.TransactionWrite,
            req.writes,
            req.deletes,
            req.transforms,
        );
        defer transform_snapshot.deinit(preparation_alloc);

        var effective_ops = try coalesceKeyValueRequest(
            self,
            preparation_alloc,
            types.TransactionWrite,
            req.writes,
            req.deletes,
            req.transforms,
            &transform_snapshot,
        );
        defer effective_ops.deinit(preparation_alloc);
        // Graph projections are maintained as artifact deltas, while the
        // transaction intent format currently carries only primary key/value
        // rows. Refuse this combination rather than acknowledging a transform
        // whose graph half cannot participate in the transaction commit.
        if (effective_ops.graph_writes.items.len != 0 or effective_ops.graph_deletes.items.len != 0)
            return error.UnsupportedTransformOperation;

        var intents = std.ArrayListUnmanaged(transactions_mod.WriteIntent).empty;
        defer intents.deinit(preparation_alloc);
        var predicates = std.ArrayListUnmanaged(transactions_mod.VersionPredicate).empty;
        defer predicates.deinit(preparation_alloc);

        for (effective_ops.writes) |write| {
            if (isProtectedIntegrityKey(write.key) or isProtectedRangeWriteKey(write.key)) return error.InvalidIntegrityOperation;
            try intents.append(preparation_alloc, .{
                .key = write.key,
                .value = write.value,
                .json_null_fields = write.json_null_fields,
            });
        }
        for (effective_ops.deletes) |key| {
            if (isProtectedIntegrityKey(key) or isProtectedRangeWriteKey(key)) return error.InvalidIntegrityOperation;
            try intents.append(preparation_alloc, .{
                .key = key,
                .value = null,
            });
        }
        for (req.predicates) |predicate| {
            if (isProtectedIntegrityKey(predicate.key)) return error.InvalidIntegrityOperation;
            try predicates.append(preparation_alloc, .{
                .key = predicate.key,
                .expected_version = predicate.expected_version,
                .expected_content_digest = predicate.expected_content_digest,
                .unique_absence = predicate.unique_absence,
            });
        }

        // These internal observations address this exact owner's metadata,
        // never document keyspace. The coordinator routes them by owner fence.
        const tracking = @import("../range_protection.zig");
        if (req.range_guards.len > @import("../range_protection.zig").max_proofs) return error.TransactionTooLarge;
        const range_keys = try preparation_alloc.alloc([tracking.counter_prefix.len + 2]u8, req.range_guards.len);
        defer preparation_alloc.free(range_keys);
        const index_range_keys = try preparation_alloc.alloc([tracking.index_counter_prefix.len + tracking.index_span_digest_bytes]u8, req.range_guards.len);
        defer preparation_alloc.free(index_range_keys);
        const range_values = try preparation_alloc.alloc([8]u8, req.range_guards.len);
        defer preparation_alloc.free(range_values);
        var observed_buckets = std.StaticBitSet(tracking.bucket_count).empty;
        for (req.range_guards, 0..) |guard, i| {
            tracking.validateProof(guard) catch return error.InvalidBatchRequest;
            const key: []const u8 = if (guard.index) |span| blk: {
                index_range_keys[i] = tracking.indexCounterKey(span.digest);
                break :blk &index_range_keys[i];
            } else blk: {
                if (observed_buckets.isSet(guard.bucket)) return error.InvalidBatchRequest;
                observed_buckets.set(guard.bucket);
                range_keys[i] = tracking.counterKey(guard.bucket);
                break :blk &range_keys[i];
            };
            if (guard.generation) |generation| std.mem.writeInt(u64, &range_values[i], generation, .little);
            try predicates.append(preparation_alloc, .{
                .key = key,
                .expected_version = 0,
                .comparison = .exact_value,
                .expected_value = if (guard.generation != null) &range_values[i] else null,
            });
        }

        var identity_upsert_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer identity_upsert_keys.deinit(preparation_alloc);
        for (intents.items) |intent| {
            if (intent.value == null or isMetadataKey(intent.key)) continue;
            try identity_upsert_keys.append(preparation_alloc, intent.key);
        }

        const binding = try self.core.transactionSchemaBinding(preparation_alloc, txn_id);
        var prepared_schema_view = try self.acquireTransactionSchemaView(preparation_alloc, binding);
        defer if (prepared_schema_view) |*view| view.release();
        if (req.schema_version) |version| {
            const view = prepared_schema_view orelse return error.PreparedGenerationChanged;
            if (view.version() != version) return error.PreparedGenerationChanged;
        }
        if ((hasCoordinatedConstraints(prepared_schema_view) or req.relational_repair) and
            (req.relational_schema_version == null or req.relational_integrity_generation_set == null) and
            (effective_ops.writes.len != 0 or effective_ops.deletes.len != 0)) return error.ForeignKeyCoordinationRequired;
        if (req.relational_schema_version) |version| {
            const view = prepared_schema_view orelse return error.InvalidRelationalRowsRequest;
            if (view.storageMode() != .relational) return error.InvalidRelationalRowsRequest;
            if (view.version() != version) return error.PreparedGenerationChanged;
        }
        // Exact index-span proofs remain valid only while the observed READY
        // generation is the current catalog generation. Fence all three
        // pieces of that state in the same prepare as the span counter.
        var range_metadata_buffers: std.ArrayList([]u8) = .empty;
        defer {
            for (range_metadata_buffers.items) |bytes| preparation_alloc.free(bytes);
            range_metadata_buffers.deinit(preparation_alloc);
        }
        const CaptureMetadata = struct {
            fn add(alloc: Allocator, buffers: *std.ArrayList([]u8), output: *std.ArrayListUnmanaged(transactions_mod.VersionPredicate), read: anytype, key: []const u8) !void {
                try buffers.ensureUnusedCapacity(alloc, 2);
                const owned_key = try alloc.dupe(u8, key);
                buffers.appendAssumeCapacity(owned_key);
                const raw = read.get(key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
                const value = if (raw) |bytes| try alloc.dupe(u8, bytes) else null;
                if (value) |bytes| buffers.appendAssumeCapacity(bytes);
                try output.append(alloc, .{ .key = owned_key, .comparison = .exact_value, .expected_value = value });
            }
        };
        var guarded_indexes: std.AutoHashMapUnmanaged([tracking.index_id_bytes]u8, void) = .empty;
        defer guarded_indexes.deinit(preparation_alloc);
        var index_plan: ?@import("relational_index_catalog.zig").WriteSnapshot = null;
        defer if (index_plan) |*plan| plan.deinit();
        var index_read: ?docstore_mod.DocStore.Txn = null;
        defer if (index_read) |*read| read.abort();
        for (req.range_guards) |guard| {
            const span = guard.index orelse continue;
            const seen = try guarded_indexes.getOrPut(preparation_alloc, span.id);
            if (seen.found_existing) continue;
            if (index_plan == null) {
                index_plan = self.core.relational_indexes.acquire() orelse return error.PreparedGenerationChanged;
                index_read = try self.core.store.beginProbeTxn();
                const head_raw = try index_read.?.get(@import("relational_index_catalog.zig").head_key);
                if (!(try @import("relational_index_catalog.zig").Head.decode(head_raw)).eql(index_plan.?.head)) return error.PreparedGenerationChanged;
                try CaptureMetadata.add(preparation_alloc, &range_metadata_buffers, &predicates, &index_read.?, @import("relational_index_catalog.zig").head_key);
            }
            const index = for (index_plan.?.plan.boundIndexes()) |candidate| {
                const candidate_id = candidate.id().encode();
                if (std.mem.eql(u8, &candidate_id, &span.id)) break candidate;
            } else return error.PreparedGenerationChanged;
            if ((try relational_index_jobs.status(&index_read.?, index)).state != .ready) return error.RelationalIndexNotReady;
            const progress_key = relational_index_jobs.progressKey(index.id());
            const control_key = @import("relational_index_maintenance_contract.zig").controlKey(index.id());
            try CaptureMetadata.add(preparation_alloc, &range_metadata_buffers, &predicates, &index_read.?, &progress_key);
            try CaptureMetadata.add(preparation_alloc, &range_metadata_buffers, &predicates, &index_read.?, &control_key);
        }
        defer freePreparedIntentRows(preparation_alloc, intents.items);
        try self.prepareTransactionRows(preparation_alloc, intents.items, prepared_schema_view);

        const integrity_catalog_mod = @import("relational_integrity_catalog.zig");
        var integrity_catalog: ?integrity_catalog_mod.Catalog = null;
        var integrity_catalog_digest: ?[32]u8 = null;
        defer if (integrity_catalog) |*catalog| catalog.deinit();
        if (req.integrity.len != 0 or req.integrity_commands.len != 0 or req.relational_activation != null or req.relational_retirement != null or req.relational_repair or hasCoordinatedConstraints(prepared_schema_view)) {
            const raw_catalog = (try self.core.getStoreValue(preparation_alloc, integrity_catalog_mod.key)) orelse return error.IntegrityCatalogChanged;
            defer preparation_alloc.free(raw_catalog);
            integrity_catalog = try integrity_catalog_mod.decode(preparation_alloc, raw_catalog);
            var digest: [32]u8 = undefined;
            std.crypto.hash.Blake3.hash(raw_catalog, &digest, .{});
            integrity_catalog_digest = digest;
            if (req.relational_integrity_generation_set) |expected| {
                const actual = @import("relational_integrity_activation.zig").generationSet(integrity_catalog.?);
                if (!std.mem.eql(u8, &expected, &actual)) return error.IntegrityCatalogChanged;
            }
            const view = prepared_schema_view orelse return error.IntegrityCatalogChanged;
            if (integrity_catalog.?.schema_version != view.version()) return error.PreparedGenerationChanged;
            const incarnation = try integrity_catalog_mod.incarnationFromTableId(self.core.identity_namespace.table_id);
            if (!std.mem.eql(u8, &incarnation, &integrity_catalog.?.incarnation)) return error.IntegrityCatalogIncarnationMismatch;
            for (req.integrity_commands) |command| {
                const generation = integrity_catalog.?.findGeneration(command.address.generation) orelse return error.IntegrityCatalogChanged;
                if (generation.definition.kind != .unique) return error.InvalidIntegrityOperation;
                if (generation.retired and (command.operation == .establish or command.operation == .attach)) return error.IntegrityCatalogChanged;
            }
        }

        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        if (schema_namespace != self.core.schemaNamespaceGeneration()) return error.PreparedGenerationChanged;
        if (binding == null) try self.validatePreparedSchemaViewLocked(prepared_schema_view);
        if (row_policy_principal) |principal| {
            const view = prepared_schema_view orelse return error.RowPolicyCatalogChanged;
            try self.enforceRowPolicyIntentsLocked(view, intents.items, principal);
        }
        const integrity_mod = @import("relational_integrity.zig");
        const activation_mod = @import("relational_integrity_activation.zig");
        var repair_checkpoint: ?[]const u8 = null;
        defer if (repair_checkpoint) |bytes| preparation_alloc.free(bytes);
        var restore_checkpoint: ?[]const u8 = null;
        defer if (restore_checkpoint) |bytes| preparation_alloc.free(bytes);
        var topology_manager = try self.core.initTxnManager();
        defer topology_manager.deinit();
        {
            var topology_read = try self.core.store.beginProbeTxn();
            defer topology_read.abort();
            try @import("restore_staging.zig").requireMutableScope(preparation_alloc, &topology_read, req.restore_staging_scope);
            if (req.restore_staging_scope != null and (effective_ops.writes.len != 0 or effective_ops.deletes.len != 0 or req.relational_repair or req.relational_retirement != null)) return error.InvalidRestoreStagingCommand;
            if (req.restore_staging_scope != null) {
                const checkpoint = (try @import("restore_staging.zig").optional(&topology_read)) orelse return error.RestoreStagingScopeChanged;
                restore_checkpoint = try preparation_alloc.dupe(u8, checkpoint);
                try predicates.append(preparation_alloc, .{ .key = @import("restore_staging.zig").key, .comparison = .exact_value, .expected_value = restore_checkpoint });
            }
            try @import("relational_integrity_topology.zig").admitPrepare(&topology_read, &topology_manager, preparation_alloc, txn_id);
        }
        var maintenance_preparation: ?@import("relational_index_maintenance.zig").Prepared = null;
        defer if (maintenance_preparation) |*value| value.deinit();
        if (req.relational_index_maintenance) |command| {
            const view = prepared_schema_view orelse return error.RelationalTableRequired;
            if (view.version() != command.schema_version) return error.PreparedGenerationChanged;
            var plan = self.core.relational_indexes.acquire() orelse return error.PreparedGenerationChanged;
            defer plan.deinit();
            if (plan.plan.schemaView().epoch != view.epoch) return error.PreparedGenerationChanged;
            var maintenance_read = try self.core.store.beginProbeTxn();
            defer maintenance_read.abort();
            maintenance_preparation = try @import("relational_index_maintenance.zig").prepareCommand(
                preparation_alloc,
                &maintenance_read,
                plan.plan,
                self.core.identity_namespace.table_id,
                command,
            );
            try intents.append(preparation_alloc, maintenance_preparation.?.intent);
            try predicates.append(preparation_alloc, maintenance_preparation.?.predicate);
        }
        var integrity_effects: ?integrity_mod.Effects = null;
        defer if (integrity_effects) |*effects| effects.deinit();
        if (req.integrity.len != 0 or req.integrity_commands.len != 0 or req.relational_activation != null or req.relational_retirement != null or integrity_catalog != null) {
            var integrity_read = try integrity_mod.CurrentView.initForTransaction(self.core.store, preparation_alloc, txn_id);
            defer integrity_read.deinit();
            // Shadow claims must remain unobservable even to a participant
            // whose stale route happens to name this receiver. Check before
            // any claim/reference lookup or semantic preparation occurs.
            for (req.integrity_commands) |command| try @import("online_integrity_shadow.zig").requireServing(&integrity_read, self.core.byteRange(), &command.address.routing);
            for (req.integrity) |operation| try @import("online_integrity_shadow.zig").requireServing(&integrity_read, self.core.byteRange(), operation.routing_key);
            // Layout epochs alone do not fence changes to UNIQUE/FK declarations.
            // Compare the exact catalog observed during preparation under apply.
            const current_catalog = integrity_read.get(integrity_catalog_mod.key) catch |err| switch (err) {
                error.NotFound => return error.IntegrityCatalogChanged,
                else => return err,
            };
            var current_digest: [32]u8 = undefined;
            std.crypto.hash.Blake3.hash(current_catalog, &current_digest, .{});
            if (!std.mem.eql(u8, &current_digest, &integrity_catalog_digest.?)) return error.IntegrityCatalogChanged;
            if (req.relational_retirement) |command| {
                if (effective_ops.writes.len != 0 or effective_ops.deletes.len != 0 or req.relational_activation != null or req.relational_repair) return error.InvalidConstraintRetirementCommand;
                try @import("online_integrity_shadow.zig").requireCatalogMutable(&integrity_read);
                try @import("online_integrity_shadow.zig").requireServing(&integrity_read, self.core.byteRange(), command.routing_key);
                const retirement = try @import("relational_integrity_retirement.zig").prepareCommand(preparation_alloc, &integrity_read, integrity_catalog.?, command);
                const after = try @import("relational_integrity_retirement.zig").Progress.decode(command.next);
                if (command.expected) |expected| {
                    const before = try @import("relational_integrity_retirement.zig").Progress.decode(expected);
                    if (binding == null and before.phase == .fenced and after.phase != .fenced and try topology_manager.hasSchemaLeases()) return error.SchemaInUse;
                }
                try intents.append(preparation_alloc, retirement.intent);
                try predicates.append(preparation_alloc, retirement.predicate);
            }
            if (req.relational_activation) |command| {
                try @import("relational_integrity_retirement.zig").requireMutable(&integrity_read);
                try @import("online_integrity_shadow.zig").requireCatalogMutable(&integrity_read);
                // A backfill page changes claims and its durable cursor, never
                // primary rows. Its observed rows are retained read guards.
                if (effective_ops.writes.len != 0 or effective_ops.deletes.len != 0) return error.InvalidConstraintActivationCommand;
                try @import("online_integrity_shadow.zig").requireServing(&integrity_read, self.core.byteRange(), command.routing_key);
                const activation = try activation_mod.prepareCommand(preparation_alloc, &integrity_read, integrity_catalog.?, command);
                try intents.append(preparation_alloc, activation.intent);
                try predicates.append(preparation_alloc, activation.predicate);
            } else if (effective_ops.writes.len != 0 or effective_ops.deletes.len != 0) {
                try @import("relational_integrity_retirement.zig").requireMutable(&integrity_read);
                if (req.relational_repair) {
                    const repair_guard = try activation_mod.repairPredicate(preparation_alloc, &integrity_read, integrity_catalog.?);
                    repair_checkpoint = repair_guard.expected_value;
                    try predicates.append(preparation_alloc, repair_guard);
                } else try activation_mod.requireReady(&integrity_read, integrity_catalog.?);
            }
            if (req.integrity.len != 0 and req.integrity_commands.len != 0) return error.InvalidIntegrityOperation;
            if (req.integrity.len != 0) try @import("relational_integrity_retirement.zig").requireMutable(&integrity_read);
            try @import("relational_integrity_retirement.zig").admitCommands(&integrity_read, req.integrity_commands);
            const integrity_operations = if (req.integrity_commands.len != 0) operations: {
                integrity_effects = try integrity_mod.prepare(preparation_alloc, &integrity_read, req.integrity_commands);
                break :operations integrity_effects.?.operations;
            } else req.integrity;
            try integrity_mod.validatePreparedEffects(preparation_alloc, &integrity_read, integrity_operations);
            for (integrity_operations) |operation| {
                try @import("online_integrity_shadow.zig").requireServing(&integrity_read, self.core.byteRange(), operation.routing_key);
                const parsed_key = try integrity_mod.parseKey(operation.key);
                const generation = integrity_catalog.?.findGeneration(parsed_key.address.generation) orelse return error.IntegrityCatalogChanged;
                if (generation.definition.kind != .unique) return error.InvalidIntegrityOperation;
                if (req.integrity_commands.len == 0 and generation.retired and operation.kind != .delete) return error.IntegrityCatalogChanged;
                try predicates.append(preparation_alloc, integrity_mod.predicate(operation));
                if (operation.kind != .guard) try intents.append(preparation_alloc, .{ .key = operation.key, .value = operation.value });
            }
        }
        try self.validateTransformReadSnapshot(transform_snapshot);
        try self.failIfIdentityOrdinalExhaustedForNewUpserts(identity_upsert_keys.items);
        const index_spans = try self.collectIndexSpanReservations(preparation_alloc, intents.items, prepared_schema_view);
        defer if (index_spans.len != 0) preparation_alloc.free(index_spans);
        try self.prepareOnlineVectorIntentBoundsLocked(preparation_alloc, intents.items, prepared_schema_view);
        var endpoint_dependencies = std.heap.ArenaAllocator.init(preparation_alloc);
        defer endpoint_dependencies.deinit();
        try self.prepareGraphEndpointDependenciesLocked(preparation_alloc, endpoint_dependencies.allocator(), txn_id, intents.items, prepared_schema_view, &predicates);
        if (row_policy_lease) |lease| try lease.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
        if (ordered_receipt) |identity| {
            switch (try orderedApplyDisposition(try readOrderedApplyReceipt(preparation_alloc, self.core.store), identity)) {
                .already_applied => return,
                .apply => {},
            }
            var value_buf: [ordered_apply_receipt_value_len]u8 = undefined;
            const marker = orderedApplyReceiptWrite(identity, &value_buf);
            try self.core.writeIntentsExtraBatch(
                txn_id,
                intents.items,
                predicates.items,
                .{ .writes = &.{marker}, .schema_binding = .{ .version = if (prepared_schema_view) |view| view.version() else null }, .preparation_allocator = preparation_alloc, .index_span_digests = index_spans },
            );
        } else {
            try self.core.writeIntentsExtraBatch(txn_id, intents.items, predicates.items, .{
                .preparation_allocator = preparation_alloc,
                .schema_binding = .{ .version = if (prepared_schema_view) |view| view.version() else null },
                .index_span_digests = index_spans,
            });
        }
    }

    pub const acquireTransactionSchemaView = local_mutation.acquireTransactionSchemaView;

    pub const isProtectedIntegrityKey = local_mutation.isProtectedIntegrityKey;

    pub const isProtectedRangeWriteKey = local_mutation.isProtectedRangeWriteKey;

    pub const hasCoordinatedConstraints = local_mutation.hasCoordinatedConstraints;

    pub const validatePreparedSchemaViewLocked = local_mutation.validatePreparedSchemaViewLocked;

    fn freePreparedIntentRows(alloc: Allocator, intents: []const transactions_mod.WriteIntent) void {
        for (intents) |intent| if (intent.prepared_row) |row| {
            alloc.free(@constCast(row));
            alloc.free(@constCast(intent.value.?));
        };
    }

    /// Endpoint deletion is a document mutation, including TTL and deletes
    /// prepared by another transaction. Reuse the durable shared read guards
    /// so it cannot enqueue cleanup after an inline relationship votes prepared.
    /// The guards survive restart and are released atomically with resolution.
    /// Fact-owned projections deliberately have an independent lifecycle.
    fn prepareGraphEndpointDependenciesLocked(
        self: *DB,
        alloc: Allocator,
        scratch: Allocator,
        txn_id: types.TxnId,
        intents: []const transactions_mod.WriteIntent,
        schema_view: ?schema_registry_mod.SchemaView,
        predicates: *std.ArrayListUnmanaged(transactions_mod.VersionPredicate),
    ) !void {
        if (!self.core.hasGraphIndexes()) return;
        var manager = try self.core.initTxnManager();
        defer manager.deinit();
        var targets = std.StringHashMapUnmanaged(void).empty;
        defer targets.deinit(scratch);
        var read = try self.core.store.beginProbeTxn();
        defer read.abort();
        const owning_table: ?[]const u8 = self.local_execution.row_policy_table_name orelse (read.get(internal_keys.graph_owning_table_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        });
        var rows = std.heap.ArenaAllocator.init(alloc);
        defer rows.deinit();
        const row_alloc = rows.allocator();
        for (intents) |intent| {
            if (isMetadataKey(intent.key)) continue;
            const value = intent.value orelse continue;
            defer _ = rows.reset(.retain_capacity);
            var prepared: ?mapper.PreparedRelationalWrite = if (intent.prepared_row != null) prepared_row: {
                const view = schema_view orelse return error.PreparedGenerationChanged;
                break :prepared_row try mapper.PreparedRelationalWrite.initFromIntent(row_alloc, intent.key, value, view.validator(), view.tableSchema().*, view.physicalLayout(), intent.prepared_row);
            } else null;
            defer if (prepared) |*row| row.deinit(row_alloc);
            var parsed: ?std.json.Parsed(std.json.Value) = if (prepared == null)
                try std.json.parseFromSlice(std.json.Value, row_alloc, value, .{ .parse_numbers = false })
            else
                null;
            defer if (parsed) |*root| root.deinit();
            if (prepared) |*row| {
                // AROW columns are lazy; materialize only fields consumed by
                // graph mappings before planning durable endpoint guards.
                for (self.core.graphIndexes()) |entry| {
                    for (entry.edge_type_configs) |edge_cfg| {
                        if (edge_cfg.field_name) |name| try row.requireLogicalField(name);
                    }
                }
            }
            const root = if (prepared) |*row| row.parsedValue() else parsed.?.value;
            var extracted = if (prepared) |*row| row.takeExtracted() else try mapper.extractWriteFromParsed(row_alloc, intent.key, value, root);
            defer extracted.deinit(row_alloc);
            try augmentExtractedWriteWithGraphFieldEdgesParsed(self, row_alloc, intent.key, root, &extracted);
            for (extracted.graph_writes) |edge| {
                if (edge.owner_document.len != 0 and !std.mem.eql(u8, edge.owner_document, edge.source)) continue;
                if (edge.owner.len != 0 and !std.mem.eql(u8, edge.owner, edge.source)) continue;
                var table_scratch = graph_metadata_tables.Scratch.init(row_alloc, null);
                defer table_scratch.deinit();
                const source_table = try table_scratch.table(edge.metadata_json, "source_table");
                const target_table = try table_scratch.table(edge.metadata_json, "target_table");
                if (!graph_metadata_tables.inlineEndpointsAreLocal(source_table, target_table, owning_table)) continue;
                if (targets.contains(edge.target)) continue;
                const target = try scratch.dupe(u8, edge.target);
                // Request preparation owns all predicate bytes until prepare.
                const job = try internal_keys.graphEndpointCleanupKeyAlloc(scratch, target);
                _ = read.get(job) catch |err| switch (err) {
                    error.NotFound => {
                        if (!try manager.hasSharedReadDependency(txn_id, target)) {
                            if (predicates.items.len >= transactions_mod.max_read_guards_per_transaction) return error.TransactionTooLarge;
                            const version = (try ttl_mod.readTimestamp(self.core.store, alloc, target)) orelse 0;
                            try predicates.append(alloc, .{ .key = target, .expected_version = version });
                        }
                        try targets.put(scratch, target, {});
                        continue;
                    },
                    else => return err,
                };
                return error.IntegrityTopologyBusy;
            }
        }
    }

    /// Called under apply after row preparation. Prior reverse companions are
    /// the authoritative old tuples, including retired generations; the pinned
    /// plan produces candidate tuples from canonical AROW without reparsing JSON.
    /// Reserve both sides before publishing a primary intent so an empty index
    /// equality read cannot pass between prepare and index-effect commit.
    /// The catalog cannot change while direct-vector retention is active.
    /// Compute server-owned conservative bounds before voting prepared; the
    /// persisted replacement-aware ledger also counts artifact keys so commit
    /// cannot exceed the retained frame's independent key-count limit.
    fn prepareOnlineVectorIntentBoundsLocked(self: *DB, alloc: Allocator, intents: []transactions_mod.WriteIntent, schema_view: ?schema_registry_mod.SchemaView) !void {
        for (intents) |*intent| {
            intent.retained_artifact_bytes = 0;
            intent.retained_artifact_keys = 0;
        }
        var read = try self.core.store.beginReadTxn();
        defer read.abort();
        const retention = (try @import("../retained_effects.zig").load(&read)) orelse return;
        if (!retention.active() or !retention.direct_vectors) return;
        for (intents) |*intent| {
            if (isMetadataKey(intent.key)) continue;
            if (intent.value) |value| {
                var prepared: ?mapper.PreparedRelationalWrite = if (intent.prepared_row != null) prepared_row: {
                    const view = schema_view orelse return error.PreparedGenerationChanged;
                    break :prepared_row try mapper.PreparedRelationalWrite.initFromIntent(alloc, intent.key, value, view.validator(), view.tableSchema().*, view.physicalLayout(), intent.prepared_row);
                } else null;
                defer if (prepared) |*row| row.deinit(alloc);
                var extracted = if (prepared) |*row| row.takeExtracted() else try mapper.extractWrite(alloc, intent.key, value);
                defer extracted.deinit(alloc);
                if (prepared) |*row| {
                    const view = schema_view.?;
                    try self.core.index_manager.appendIndexFieldEmbeddingsFromPreparedToExtractedWrite(alloc, intent.key, row.parsedValue(), try row.typedView(view.tableSchema().*, view.physicalLayout()), &extracted);
                } else try self.core.index_manager.appendIndexFieldEmbeddingsToExtractedWrite(alloc, intent.key, value, &extracted);
                inline for (.{ extracted.dense_embeddings, extracted.sparse_embeddings }) |embeddings| {
                    for (embeddings) |embedding| {
                        const numbers = if (@hasField(@TypeOf(embedding), "vector")) embedding.vector else embedding.values;
                        for (numbers) |number| if (!std.math.isFinite(number)) return error.InvalidBatchRequest;
                        const key = try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, intent.key, embedding.index_name);
                        defer alloc.free(key);
                        const vector_bytes = if (@hasField(@TypeOf(embedding), "vector"))
                            std.math.mul(u64, embedding.vector.len, 4) catch return error.TransactionTooLarge
                        else
                            std.math.mul(u64, embedding.indices.len, 8) catch return error.TransactionTooLarge;
                        const bytes = std.math.add(u64, 16 + key.len + enrichment_artifact_codec.header_len + 4, vector_bytes) catch return error.TransactionTooLarge;
                        intent.retained_artifact_bytes = std.math.add(u64, intent.retained_artifact_bytes, bytes) catch return error.TransactionTooLarge;
                        intent.retained_artifact_keys += 1;
                    }
                }
            } else {
                const prefix = try internal_keys.artifactRootPrefixAlloc(alloc, intent.key);
                defer alloc.free(prefix);
                var cursor = try read.openCursor();
                defer cursor.close();
                var entry = try cursor.seekAtOrAfter(prefix);
                var inspected: usize = 0;
                while (entry) |record| : (entry = try cursor.next()) {
                    if (!std.mem.startsWith(u8, record.key, prefix)) break;
                    inspected += 1;
                    if (inspected > @import("../retained_effects.zig").max_keys) return error.TransactionTooLarge;
                    if (!internal_keys.isEmbeddingArtifactKey(record.key)) continue;
                    intent.retained_artifact_bytes = std.math.add(u64, intent.retained_artifact_bytes, 16 + record.key.len) catch return error.TransactionTooLarge;
                    intent.retained_artifact_keys += 1;
                }
            }
        }
    }

    fn collectIndexSpanReservations(
        self: *DB,
        alloc: Allocator,
        intents: []const transactions_mod.WriteIntent,
        schema_view: ?schema_registry_mod.SchemaView,
    ) ![]const [@import("../range_protection.zig").index_span_digest_bytes]u8 {
        const protection = @import("../range_protection.zig");
        const view = schema_view orelse return &.{};
        if (view.storageMode() != .relational) return &.{};
        var read = try self.core.store.beginReadTxn();
        defer read.abort();
        if (!try protection.isActive(&read)) return &.{};
        var plan_snapshot = self.core.relational_indexes.acquire();
        defer if (plan_snapshot) |*pinned_plan| pinned_plan.deinit();
        if (plan_snapshot) |pinned_plan| if (pinned_plan.plan.schemaView().epoch != view.epoch) return error.PreparedGenerationChanged;
        var index_keys: ?relational_index_plans.Batch = if (plan_snapshot) |pinned_plan| relational_index_plans.Batch.init(alloc, pinned_plan.plan) else null;
        defer if (index_keys) |*keys| keys.deinit();
        var seen = std.AutoHashMapUnmanaged([protection.index_span_digest_bytes]u8, void).empty;
        defer seen.deinit(alloc);
        var spans = std.ArrayListUnmanaged([protection.index_span_digest_bytes]u8).empty;
        errdefer spans.deinit(alloc);
        var cursor = try read.openCursor();
        defer cursor.close();
        var prefix = std.ArrayList(u8).empty;
        defer prefix.deinit(alloc);
        var inspected: usize = 0;
        for (intents) |intent| {
            if (isMetadataKey(intent.key)) continue;
            prefix.clearRetainingCapacity();
            try internal_keys.appendDocumentPrefix(&prefix, alloc, intent.key);
            try prefix.append(alloc, internal_keys.relational_index_reverse_kind);
            var entry = try cursor.seekAtOrAfter(prefix.items);
            while (entry) |record| : (entry = try cursor.next()) {
                if (!std.mem.startsWith(u8, record.key, prefix.items)) break;
                inspected = std.math.add(usize, inspected, 1) catch return error.TransactionTooLarge;
                if (inspected > transactions_mod.max_read_guards_per_transaction) return error.TransactionTooLarge;
                const reverse = try relational_index_records.parseReverseKey(record.key);
                const tuple = try relational_index_records.reverseTuple(record.key, record.value);
                const digest = try protection.indexTupleSpanDigest(reverse.id.encode(), tuple);
                if (!(try seen.getOrPut(alloc, digest)).found_existing) {
                    if (spans.items.len == transactions_mod.max_read_guards_per_transaction) return error.TransactionTooLarge;
                    try spans.append(alloc, digest);
                }
            }
            if (intent.prepared_row) |encoded_row| if (index_keys) |*keys| {
                keys.reset();
                const row = try relational_row_codec.ordinalRowViewTrusted(encoded_row, view.tableSchema().*, view.physicalLayout());
                const position = try keys.append(row);
                for (keys.view.boundIndexes(), 0..) |index, i| {
                    const candidate = try keys.key(position, i);
                    if (!candidate.member) continue;
                    const digest = try protection.indexTupleSpanDigest(index.id().encode(), candidate.bytes);
                    if (!(try seen.getOrPut(alloc, digest)).found_existing) {
                        if (spans.items.len == transactions_mod.max_read_guards_per_transaction) return error.TransactionTooLarge;
                        try spans.append(alloc, digest);
                    }
                }
            };
        }
        return try spans.toOwnedSlice(alloc);
    }

    fn prepareTransactionRows(
        self: *DB,
        alloc: Allocator,
        intents: []transactions_mod.WriteIntent,
        schema_view: ?schema_registry_mod.SchemaView,
    ) !void {
        const view = schema_view orelse {
            for (intents) |intent| if (intent.json_null_fields.len != 0) return error.InvalidBatchRequest;
            return;
        };
        if (view.storageMode() != .relational) {
            for (intents) |intent| if (intent.json_null_fields.len != 0) return error.InvalidBatchRequest;
            return;
        }
        const Context = struct {
            alloc: Allocator,
            intents: []transactions_mod.WriteIntent,
            view: schema_registry_mod.SchemaView,
            io: std.Io,
            next: std.atomic.Value(usize) = .init(0),
            failed: std.atomic.Value(bool) = .init(false),
            mutex: std.Io.Mutex = .init,
            failure: ?anyerror = null,

            fn prepare(ctx: *@This(), scratch: Allocator, intent: *transactions_mod.WriteIntent) !void {
                if (isMetadataKey(intent.key)) return;
                const value = intent.value orelse return;
                var row = try mapper.PreparedRelationalWrite.initTyped(ctx.alloc, scratch, scratch, false, intent.key, value, ctx.view.validator(), ctx.view.tableSchema().*, ctx.view.physicalLayout(), intent.json_null_fields, false);
                defer row.deinit(ctx.alloc);
                try row.finalizeMetadata(0);
                var specials = std.json.ObjectMap.empty;
                defer specials.deinit(scratch);
                const root = row.parsedValue();
                for ([_][]const u8{ "_edges", "_embeddings" }) |field|
                    if (root.object.get(field)) |special| try specials.put(scratch, field, special);
                const sidecar = try std.json.Stringify.valueAlloc(ctx.alloc, std.json.Value{ .object = specials }, .{});
                intent.prepared_row = row.takePackedRow();
                intent.value = sidecar;
                intent.json_null_fields = &.{};
            }

            fn run(ctx: *@This()) void {
                var scratch = std.heap.ArenaAllocator.init(ctx.alloc);
                defer scratch.deinit();
                while (!ctx.failed.load(.acquire)) {
                    const index = ctx.next.fetchAdd(1, .monotonic);
                    if (index >= ctx.intents.len) return;
                    ctx.prepare(scratch.allocator(), &ctx.intents[index]) catch |err| {
                        ctx.mutex.lockUncancelable(ctx.io);
                        defer ctx.mutex.unlock(ctx.io);
                        if (ctx.failure == null) ctx.failure = err;
                        ctx.failed.store(true, .release);
                        return;
                    };
                    _ = scratch.reset(.retain_capacity);
                }
            }
        };
        const io = self.backend_runtime.io();
        var ctx = Context{ .alloc = alloc, .intents = intents, .view = view, .io = io orelse std.Options.debug_io };
        var input_bytes: usize = 0;
        for (intents) |intent| input_bytes +|= if (intent.value) |value| value.len else 0;
        const workers = @min(@as(usize, 8), @min(intents.len, @max(@as(usize, 1), input_bytes / (256 * 1024))));
        if (io != null and workers > 1) {
            var group: std.Io.Group = .init;
            for (1..workers) |_| group.async(io.?, Context.run, .{&ctx});
            ctx.run();
            try group.await(io.?);
        } else ctx.run();
        if (ctx.failure) |err| return err;
    }

    // resolveTransactionTransforms, removePendingTransactionWrite, and freeTransactionWritesOwned
    // request coalescing is consolidated into coalesceKeyValueRequest above

    pub fn commitTransaction(self: *DB, txn_id: transactions_mod.TxnId, timestamp_ns: u64) !void {
        try self.resolveTransactionIntents(txn_id, .committed, timestamp_ns);
    }

    pub fn resolveTransactionIntents(self: *DB, txn_id: transactions_mod.TxnId, status: transactions_mod.TxnStatus, commit_version: u64) !void {
        try self.resolveTransactionIntentsWithSyncLevel(txn_id, status, commit_version, .propose);
    }

    pub fn resolveTransactionIntentsWithSyncLevel(
        self: *DB,
        txn_id: transactions_mod.TxnId,
        status: transactions_mod.TxnStatus,
        commit_version: u64,
        sync_level: types.SyncLevel,
    ) !void {
        try self.resolveTransactionIntentsWithSyncLevelAndCancellation(txn_id, status, commit_version, sync_level, .none);
    }

    /// Cancellation applies only to the derived-visibility barrier after the
    /// transaction decision and primary mutation are durable. It must never
    /// turn an in-flight commit into a client-visible abort.
    pub fn resolveTransactionIntentsWithSyncLevelAndCancellation(
        self: *DB,
        txn_id: transactions_mod.TxnId,
        status: transactions_mod.TxnStatus,
        commit_version: u64,
        sync_level: types.SyncLevel,
        visibility_cancellation: types.CancellationToken,
    ) !void {
        // Resolution applies only a previously prepared durable decision.
        // Policy publication fences on outstanding schema/transaction leases,
        // so a preparing policy must not deadlock the very resolution needed
        // to drain those leases. User-visible writes are checked at prepare.
        try self.resolveTransactionIntentsInternal(
            txn_id,
            status,
            commit_version,
            sync_level,
            visibility_cancellation,
            null,
            null,
        );
    }

    pub fn resolveReplicatedTransactionAtOrderedReceipt(
        self: *DB,
        txn_id: transactions_mod.TxnId,
        status: transactions_mod.TxnStatus,
        commit_version: u64,
        sync_level: types.SyncLevel,
        visibility_cancellation: types.CancellationToken,
        identity: OrderedApplyReceipt,
        resolved_participant: ?[]const u8,
    ) !void {
        try self.resolveTransactionIntentsInternal(
            txn_id,
            status,
            commit_version,
            sync_level,
            visibility_cancellation,
            identity,
            resolved_participant,
        );
    }

    pub const resolveTransactionIntentsInternal = local_mutation.resolveTransactionIntentsInternal;

    pub const resolveTransactionIntentsPrepared = local_mutation.resolveTransactionIntentsPrepared;

    pub fn abortTransaction(self: *DB, txn_id: transactions_mod.TxnId, timestamp_ns: u64) !void {
        try self.resolveTransactionIntents(txn_id, .aborted, timestamp_ns);
    }

    pub fn getTransactionStatus(self: *DB, txn_id: transactions_mod.TxnId) !transactions_mod.TxnStatus {
        return try self.core.getTransactionStatus(txn_id);
    }

    pub fn getCommitVersion(self: *DB, txn_id: transactions_mod.TxnId) !u64 {
        return try self.core.getCommitVersion(txn_id);
    }

    pub fn transactionDefersCoordinatorAcknowledgement(self: *DB, txn_id: transactions_mod.TxnId) !bool {
        return try self.core.transactionDefersCoordinatorAcknowledgement(txn_id);
    }

    pub fn transactionRetainsCoordinatorAcknowledgement(self: *DB, txn_id: transactions_mod.TxnId) !bool {
        return try self.core.transactionRetainsCoordinatorAcknowledgement(txn_id);
    }

    /// Returns whether split or merge handoff would strand a pending decision,
    /// unresolved participant, intent, or hot-standby recovery outbox.
    pub fn hasTopologySensitiveTransactions(self: *DB) !bool {
        return try self.core.hasTopologySensitiveTransactions();
    }

    pub const validateResolvedKeyOwnership = local_mutation.validateResolvedKeyOwnership;

    pub const RelationalTopologyIdentity = @import("relational_integrity_topology_contract.zig").Identity;

    fn lookupRelationalTopology(self: *DB, alloc: Allocator, request_json: []const u8, opts: types.LookupOptions) !?types.LookupResult {
        var request = try std.json.parseFromSlice(struct {
            mode: enum { identity, status, completed, parent_activation, generation_publication, generation_handoff_summary, generation_handoff_seal, generation_handoff_install, generation_handoff_identity, graph_retirement, graph_endpoint_cleanup, initial_child_preflight, initial_child_publication, public_schema, generation_gc, handoff_progress, handoff_manifest, prune_progress, online_source_status, merge_copy_receipt },
            scope: ?@import("online_source_contract.zig").Scope = null,
        }, alloc, request_json, .{});
        defer request.deinit();
        if ((request.value.mode == .online_source_status) != (request.value.scope != null)) return error.InvalidOnlineSourceCommand;
        var output: std.Io.Writer.Allocating = .init(alloc);
        errdefer output.deinit();
        var stream: std.json.Stringify = .{ .writer = &output.writer, .options = .{} };
        switch (request.value.mode) {
            .identity => try @import("relational_integrity_json.zig").write(try self.relationalTopologyIdentity(), &stream),
            .generation_handoff_identity => {
                const scope = opts.restore_staging_scope orelse return error.RestoreStagingScopeChanged;
                const plan_id = opts.restore_staging_plan_id orelse return error.RestoreStagingScopeChanged;
                {
                    var read = try self.core.store.beginProbeTxn();
                    defer read.abort();
                    const contract = @import("restore_staging_contract.zig");
                    const raw = read.get(contract.bootstrap_key) catch return error.RestoreStagingScopeChanged;
                    var bootstrap = try contract.OwnerBootstrap.decode(alloc, raw);
                    defer bootstrap.deinit();
                    try bootstrap.value.validate();
                    if (bootstrap.value.empty_generation_handoff == null or
                        !bootstrap.value.scope.target_namespace.eql(self.core.identity_namespace) or
                        !std.mem.eql(u8, &scope, &bootstrap.value.scope.digest()) or
                        !std.mem.eql(u8, &plan_id, &bootstrap.value.scope.plan_id)) return error.RestoreStagingScopeChanged;
                }
                try @import("relational_integrity_json.zig").write(try self.relationalTopologyIdentity(), &stream);
            },
            .status => try @import("relational_integrity_json.zig").write(try self.relationalTopologyStatus(), &stream),
            .online_source_status => try @import("relational_integrity_json.zig").write(try self.onlineSourceStatus(request.value.scope.?), &stream),
            .merge_copy_receipt => {
                self.core.lockApplyShared();
                defer self.core.unlockApplyShared();
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                const raw = read.get(merge_state_mod.key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
                var state = if (raw) |value| try merge_state_mod.decodeAlloc(alloc, value) else null;
                defer if (state) |*value| value.deinit(alloc);
                const table = @import("table_catalog.zig");
                const table_raw = read.get(table.key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
                const row_derived_document = if (table_raw) |value| blk: {
                    const catalog = try table.Catalog.decode(value);
                    break :blk catalog.mode_initialized and catalog.storage_mode == .document and
                        try @import("online_merge_io.zig").rowDerivedIndexesAssumeApply(self, alloc);
                } else false;
                try @import("relational_integrity_json.zig").write(@import("merge_contract.zig").CopyReceipt{
                    .namespace = self.core.identity_namespace,
                    .range = self.core.byteRange(),
                    .state = state,
                    .row_derived_document = row_derived_document,
                }, &stream);
            },
            .completed => {
                self.core.lockApplyShared();
                defer self.core.unlockApplyShared();
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                try @import("relational_integrity_json.zig").write(try @import("relational_integrity_topology.zig").completed(&read), &stream);
            },
            .parent_activation => {
                self.core.lockApplyShared();
                defer self.core.unlockApplyShared();
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                const retirement = @import("relational_integrity_generation_retirement.zig");
                const value = try retirement.ownerStatus(alloc, &read);
                defer if (value) |status| alloc.free(status.entries);
                try @import("relational_integrity_json.zig").write(value, &stream);
            },
            .generation_publication => {
                self.core.lockApplyShared();
                defer self.core.unlockApplyShared();
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                const value = try @import("relational_integrity_generation_admission.zig").ownerStatus(&read);
                try @import("relational_integrity_json.zig").write(value, &stream);
            },
            .generation_handoff_summary => {
                self.core.lockApplyShared();
                defer self.core.unlockApplyShared();
                // This status scans bounded live scopes and streams the
                // historical retirement digest. Probe transactions cannot
                // open physical cursors; pin one coherent read snapshot.
                var read = try self.core.store.beginReadTxn();
                defer read.abort();
                var scan_options = opts;
                // A caller that omits a deadline must not pin source read
                // admission for an unbounded historical tombstone scan.
                const local_bound = opts.executionNowNs() +| 2 * std.time.ns_per_s;
                scan_options.execution_deadline_ns = @min(opts.execution_deadline_ns orelse local_bound, local_bound);
                const Scan = struct {
                    fn check(ptr: *anyopaque) !void {
                        const options: *types.LookupOptions = @ptrCast(@alignCast(ptr));
                        try checkLookupOptionsActive(options.*);
                    }
                };
                var value = try @import("empty_generation_handoff.zig").summaryAllocControlled(alloc, &read, self.core.identity_namespace, .{ .ptr = &scan_options, .check_fn = Scan.check });
                defer value.deinit(alloc);
                try @import("relational_integrity_json.zig").write(value, &stream);
            },
            .generation_handoff_seal => {
                self.core.lockApplyShared();
                defer self.core.unlockApplyShared();
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                try @import("relational_integrity_json.zig").write(try @import("empty_generation_handoff.zig").sealStatus(&read, self.core.identity_namespace), &stream);
            },
            .generation_handoff_install => {
                self.core.lockApplyShared();
                defer self.core.unlockApplyShared();
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                try @import("relational_integrity_json.zig").write(try @import("empty_generation_handoff.zig").loadInstallReceipt(&read), &stream);
            },
            .graph_endpoint_cleanup => {
                if (try self.prepareGraphEndpointCleanupBatch(alloc)) |owned| {
                    var cleanup = owned;
                    defer cleanup.deinit();
                    try @import("relational_integrity_json.zig").write(types.GraphEndpointCleanupStatus{ .pending = true, .guards = cleanup.page.guards, .graph_deletes = cleanup.graph_deletes, .deletes = cleanup.page.deletes, .merge_artifacts = cleanup.replay_writes }, &stream);
                } else try @import("relational_integrity_json.zig").write(types.GraphEndpointCleanupStatus{}, &stream);
            },
            .graph_retirement => {
                self.core.lockApplyShared();
                defer self.core.unlockApplyShared();
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                try @import("relational_integrity_json.zig").write(try @import("graph_retirement_seal.zig").status(&read), &stream);
            },
            .initial_child_publication => {
                self.core.lockApplyShared();
                defer self.core.unlockApplyShared();
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                const value = try @import("relational_initial_child_publication.zig").load(&read);
                try @import("relational_integrity_json.zig").write(value, &stream);
            },
            .initial_child_preflight => {
                self.core.lockApplyShared();
                defer self.core.unlockApplyShared();
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                const table_raw = read.get(@import("table_catalog.zig").key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
                const row_count: u64 = if (table_raw) |raw| (try @import("table_catalog.zig").Catalog.decode(raw)).row_count else 0;
                const existing_schema = read.get(public_schema_json_key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
                const existing_catalog = read.get(@import("relational_integrity_catalog.zig").key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
                try @import("relational_integrity_json.zig").write(.{
                    .namespace = self.core.identity_namespace,
                    .row_count = row_count,
                    .has_schema = existing_schema != null,
                    .has_catalog = existing_catalog != null,
                    .hidden = try @import("relational_initial_child_publication.zig").load(&read),
                }, &stream);
            },
            .public_schema => {
                self.core.lockApplyShared();
                defer self.core.unlockApplyShared();
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                const value = read.get(public_schema_json_key) catch return error.IntegrityCatalogChanged;
                try stream.write(std.json.Value{ .string = value });
            },
            .generation_gc => {
                self.core.lockApplyShared();
                defer self.core.unlockApplyShared();
                // GC preparation scans a bounded key range. Probe transactions
                // support point reads only and cannot open the required cursor.
                var read = try self.core.store.beginReadTxn();
                defer read.abort();
                if (try @import("relational_integrity_topology.zig").current(&read) != null) {
                    try @import("relational_integrity_json.zig").write(@as(?@import("relational_integrity_generation_retirement.zig").GcCommand, null), &stream);
                } else {
                    var page = try @import("relational_integrity_generation_retirement.zig").prepareGcPage(alloc, &read, 64, 512 * 1024);
                    defer if (page) |*owned_page| owned_page.deinit();
                    const value: ?@import("relational_integrity_generation_retirement.zig").GcCommand = if (page) |*owned_page| owned_page.command(0, self.core.identity_namespace) else null;
                    try @import("relational_integrity_json.zig").write(value, &stream);
                }
            },
            .handoff_progress => {
                self.core.lockApplyShared();
                defer self.core.unlockApplyShared();
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                var progress = try @import("relational_integrity_handoff.zig").loadProgress(alloc, &read);
                defer progress.deinit();
                try @import("relational_integrity_json.zig").write(progress.value, &stream);
            },
            .handoff_manifest => {
                self.core.lockApplyShared();
                defer self.core.unlockApplyShared();
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                const bytes = read.get(@import("relational_integrity_handoff.zig").manifest_key) catch |err| switch (err) {
                    error.NotFound => "null",
                    else => return err,
                };
                var manifest = try std.json.parseFromSlice(?@import("relational_integrity_handoff.zig").Manifest, alloc, bytes, .{});
                defer manifest.deinit();
                try @import("relational_integrity_json.zig").write(manifest.value, &stream);
            },
            .prune_progress => {
                self.core.lockApplyShared();
                defer self.core.unlockApplyShared();
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                const bytes = read.get(@import("relational_integrity_handoff.zig").prune_key) catch |err| switch (err) {
                    error.NotFound => "null",
                    else => return err,
                };
                var progress = try std.json.parseFromSlice(?@import("relational_integrity_handoff.zig").PruneProgress, alloc, bytes, .{});
                defer progress.deinit();
                try @import("relational_integrity_json.zig").write(progress.value, &stream);
            },
        }
        return .{ .json = try output.toOwnedSlice() };
    }

    pub fn relationalTopologyIdentity(self: *DB) !RelationalTopologyIdentity {
        self.core.lockApplyShared();
        defer self.core.unlockApplyShared();
        var read = try self.core.store.beginProbeTxn();
        defer read.abort();
        const raw = read.get(@import("relational_integrity_catalog.zig").key) catch |err| switch (err) {
            error.NotFound => "",
            else => return err,
        };
        var digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(raw, &digest, .{});
        const authority = try @import("../source_authority.zig").load(&read);
        const handoff_authority: @import("relational_integrity_topology_contract.zig").GenerationHandoffReceiptAuthority = if (authority) |value|
            if (std.mem.eql(u8, &value.namespace, &@import("online_source_contract.zig").namespaceBytes(self.core.identity_namespace)))
                if (value.kind == .raft) .raft else .native
            else
                .unsupported
        else
            .unsupported;
        return .{
            .namespace = self.core.identity_namespace,
            .catalog_digest = digest,
            .next_epoch = try @import("relational_integrity_topology.zig").nextEpoch(&read),
            .generation_handoff_receipt_authority = handoff_authority,
            .backup_seal_supported = self.primary_backend == .lsm and self.physical_root_mode == .filesystem_managed and
                nativeRestoreStoragePublicationCompatible(self.primary_lsm_storage) and self.backend_runtime.filesystemIo() != null and
                try self.primaryOnlySnapshotSupportedLocked(),
        };
    }

    pub fn relationalTopologyStatus(self: *DB) !struct { fence: ?@import("relational_integrity_topology.zig").Fence, drained: bool } {
        self.core.lockApplyShared();
        defer self.core.unlockApplyShared();
        var read = try self.core.store.beginProbeTxn();
        defer read.abort();
        const fence = try @import("relational_integrity_topology.zig").current(&read);
        var manager = try self.core.initTxnManager();
        defer manager.deinit();
        return .{ .fence = fence, .drained = !try manager.hasTopologySensitiveTransactions() };
    }

    fn childGenerationSourceFence(core: *db_core.DBCore) !bool {
        var read = try core.store.beginProbeTxn();
        defer read.abort();
        const fence = (try @import("relational_integrity_topology.zig").current(&read)) orelse return false;
        if (fence.role != .child_generation_source and fence.role != .child_generation_dual) return false;
        _ = core.schema orelse return error.IntegrityCatalogChanged;
        if (!fence.namespace.eql(core.identity_namespace)) return error.IdentityNamespaceMismatch;
        const encoded_catalog = read.get(@import("relational_integrity_catalog.zig").key) catch return error.IntegrityCatalogChanged;
        var digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(encoded_catalog, &digest, .{});
        if (!std.mem.eql(u8, &digest, &fence.catalog_digest)) return error.IntegrityCatalogChanged;
        return true;
    }

    fn childGenerationSourcePinsSchema(core: *db_core.DBCore, candidate_version: u32) !bool {
        if (!try childGenerationSourceFence(core)) return false;
        const durable = core.schema orelse return error.IntegrityCatalogChanged;
        if (candidate_version <= durable.version) return false;
        if (candidate_version != (std.math.add(u32, durable.version, 1) catch return error.GenerationAdmissionChanged))
            return error.GenerationAdmissionChanged;
        return true;
    }

    /// The metadata successor is visible before its exact Raft schema install.
    /// Callers configuring a reopened owner must retain its old schema and
    /// indexes while the verified child-source fence remains active.
    pub fn childGenerationSourcePinsSchemaJson(self: *DB, schema_json: []const u8) !bool {
        var parsed = try public_table_schema.parseValidatedTableSchema(self.alloc, schema_json);
        defer parsed.deinit(self.alloc);
        self.core.lockApplyShared();
        defer self.core.unlockApplyShared();
        return childGenerationSourcePinsSchema(self.core, parsed.version);
    }

    /// A cold current-catalog owner may reopen after the exact child schema
    /// install but before parent ACK removes the dual/source fence. During that
    /// interval its durable index catalog is authoritative; metadata-driven
    /// add/remove/repair is a mutation and must wait for fence release.
    pub fn childGenerationSourceDefersOwnerCatalog(self: *DB) !bool {
        self.core.lockApplyShared();
        defer self.core.unlockApplyShared();
        return childGenerationSourceFence(self.core);
    }

    /// The allocator belongs to one bounded transfer request/arena. All slices
    /// in this manifest are owned; none retain a source cursor or schema view.
    pub fn relationalHandoffManifest(
        self: *DB,
        alloc: Allocator,
        source: @import("relational_integrity_topology.zig").Fence,
        destination: @import("relational_integrity_topology.zig").Fence,
        lower: []const u8,
        upper: []const u8,
        primary_sequence: u64,
    ) !@import("relational_integrity_handoff.zig").Manifest {
        self.core.lockApplyShared();
        defer self.core.unlockApplyShared();
        var read = try self.core.store.beginProbeTxn();
        defer read.abort();
        var manager = try self.core.initTxnManager();
        defer manager.deinit();
        try @import("relational_integrity_topology.zig").requireDrained(&read, &manager, source);
        const owned_range = self.core.byteRange();
        if (std.mem.order(u8, lower, owned_range.start) == .lt or
            (owned_range.end.len != 0 and (upper.len == 0 or std.mem.order(u8, upper, owned_range.end) == .gt))) return error.KeyOutOfRange;
        const raw_catalog = try read.get(@import("relational_integrity_catalog.zig").key);
        var compiled = try @import("relational_integrity_catalog.zig").decode(alloc, raw_catalog);
        defer compiled.deinit();
        try @import("relational_integrity_activation.zig").requireReady(&read, compiled);
        return .{
            .source = source,
            .destination = destination,
            .lower = try alloc.dupe(u8, lower),
            .upper = try alloc.dupe(u8, upper),
            .source_range_start = try alloc.dupe(u8, owned_range.start),
            .source_range_end = try alloc.dupe(u8, owned_range.end),
            .catalog_bytes = try alloc.dupe(u8, raw_catalog),
            .activation_bytes = try alloc.dupe(u8, try read.get(@import("relational_integrity_activation.zig").key)),
            .primary_sequence = primary_sequence,
        };
    }

    pub fn relationalHandoffPage(self: *DB, alloc: Allocator, manifest: @import("relational_integrity_handoff.zig").Manifest, progress: @import("relational_integrity_handoff.zig").Progress) !@import("relational_integrity_handoff.zig").Page {
        self.core.lockApplyShared();
        defer self.core.unlockApplyShared();
        var read = try self.core.store.beginProbeTxn();
        defer read.abort();
        var manager = try self.core.initTxnManager();
        defer manager.deinit();
        try @import("relational_integrity_topology.zig").requireDrained(&read, &manager, manifest.source);
        return @import("relational_integrity_handoff.zig").readPage(alloc, self.core.store, manifest, progress);
    }

    /// Private replicated lifecycle control. Begin fences new work without
    /// waiting for old participants: their later decisions must remain able to
    /// apply. Callers separately poll drained before snapshot or cutover.
    pub fn applyRelationalTopologyControl(
        self: *DB,
        command: @import("relational_integrity_topology.zig").Command,
        ordered_receipt: ?OrderedApplyReceipt,
    ) !void {
        return self.applyRelationalTopologyControlWithReplication(command, ordered_receipt, null, null, null, null);
    }

    /// Internal source-retention controls share the lifecycle transaction path:
    /// source progress, retained log, replication marker and durable outbox are
    /// one commit. The public API has no admission route for these commands.
    fn applyOnlineSourceBatch(self: *DB, req: types.BatchRequest, opts: BatchExecutionOptions) !void {
        try @import("online_source_contract.zig").validateRequest(req);
        const command = req.online_source orelse return error.InvalidOnlineSourceCommand;
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        // A committed admission retry must not need a later Raft GC command to
        // free its slot. Try the bounded local cleanup catalog without waiting
        // on exports and before taking the apply fence.
        if (command == .admit) @import("source_pin.zig").reconcileReleased(self) catch |err| switch (err) {
            error.OnlineSourcePinPending => {}, // Repair this exact prepared cut below.
            else => return err,
        };
        var replication_mutation = if (opts.bypass_replication_write_gate) null else self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        if (!opts.bypass_replication_write_gate) {
            try self.enforceReplicationWriteGate();
            try self.ensureDurableReplicationStartupBarrier();
            try self.flushDurableReplicationOutboxes();
            try self.preflightReplicationBatchSyncCommit();
        }
        var applied_index = if (opts.ordered_apply_receipt) |entry| entry.index else opts.online_source_applied_index orelse 0;
        var payload: ?[]u8 = null;
        defer if (payload) |bytes| self.alloc.free(bytes);
        apply_source: {
            var admission = self.core.snapshot_admission.acquireMutation();
            defer admission.release();
            // Index deletion must join its derived worker before taking apply
            // exclusive. Serialize that join and the final catalog mutation
            // with source admission without blocking the Raft apply lane on a
            // worker: a busy try-lock leaves this committed entry unapplied and
            // the progress driver retries it after the index transition.
            const catalog_admission = command == .admit;
            if (catalog_admission and !self.local_execution.index_structural_mutation_mutex.tryLock())
                return error.StorageBusy;
            defer if (catalog_admission) self.local_execution.index_structural_mutation_mutex.unlock();
            try self.lockApplyForPortableRuntime();
            defer self.core.unlockApply();
            if (opts.ordered_apply_receipt) |entry| switch (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), entry)) {
                .already_applied => {
                    if (command == .admit) {
                        const repair = blk: {
                            var read = try self.core.store.beginReadTxn();
                            defer read.abort();
                            const pending = try @import("../source_pin_state.zig").load(&read) orelse break :blk false;
                            break :blk std.mem.eql(u8, &pending.namespace, &command.scope().namespace()) and std.mem.eql(u8, &pending.pin, &command.scope().pin());
                        };
                        if (repair) try @import("source_pin.zig").ensureAssumeApply(self, command.scope());
                    }
                    break :apply_source;
                },
                .apply => {},
            };
            if (!command.scope().fence.namespace.eql(self.core.identity_namespace)) return error.IdentityNamespaceMismatch;
            if (command.scope().authority == .native and opts.ordered_apply_receipt != null) return error.OnlineSourceScopeChanged;
            // Complete any committed native admission before a retry can
            // advance the owner clock. It must never recapture a later cut.
            if (command.scope().authority == .native and command == .admit) {
                const pending_scope = blk: {
                    var read = try self.core.store.beginReadTxn();
                    defer read.abort();
                    const pending = try @import("../source_pin_state.zig").load(&read) orelse break :blk null;
                    break :blk try @import("online_source_contract.zig").Scope.decode(&pending.scope_bytes);
                };
                if (pending_scope) |scope| {
                    if (!std.meta.eql(scope, command.scope())) return error.OnlineSourcePinPending;
                    try @import("source_pin.zig").ensureAssumeApply(self, scope);
                }
            }
            // Reject unsupported backends before publishing a durable write
            // fence which they could never turn into an immutable pin.
            if (command == .admit) {
                if (try self.core.store.hasGraphEndpointCleanup()) return error.IntegrityTopologyBusy;
                const lsm = self.core.primary_store_owner.lsmBackend() orelse return error.BackupSealBackendUnsupported;
                if (lsm.storage) |storage| {
                    if (!storage.supportsHostPathGenerationPublication()) return error.NativeBackupStorageBackendUnsupported;
                }
                // The catalog predicate is local to this DB, not Raft state.
                // Rechecking it while applying a committed entry could reject
                // on a follower after its leader succeeded. Distributed online
                // merge is rejected before proposal until catalog/membership
                // barriers are Raft-ordered; retain the local recheck for
                // native standalone admission only.
                if (command.scope().authority == .native)
                    try @import("online_merge_io.zig").requireAdmissibleSourceAtCommitAssumeApply(self, self.alloc);
            }
            var txn = try self.core.store.beginWriteTxn();
            var txn_open = true;
            defer if (txn_open) txn.abort();
            if (command == .admit) {
                if (req.artifact_catalog) |install| try @import("artifact_inventory.zig").stageOrdered(self.alloc, &txn, install, applied_index);
                if (command.admit.artifact_catalog) |binding| {
                    try @import("artifact_inventory.zig").requireReady(self.alloc, &txn, command.scope().namespace(), binding);
                    if (!try self.artifactMaterializationsReady(&txn, try @import("artifact_inventory.zig").catalogs(&txn))) return error.ArtifactCatalogDrift;
                } else if (command.scope().authority == .raft) {
                    const ordered = try @import("artifact_inventory.zig").load(self.alloc, &txn);
                    defer if (ordered) |value| value.deinit();
                    if (ordered != null) return error.ArtifactCatalogDrift;
                }
            } else if (command != .release) {
                const progress = try @import("online_source.zig").status(&txn, command.scope());
                if (progress.artifact_catalog) |binding|
                    try @import("artifact_inventory.zig").requireReady(self.alloc, &txn, command.scope().namespace(), binding);
            }
            try @import("restore_staging.zig").requireScope(self.alloc, &txn, null, false);
            if (command != .admit and command != .release) try @import("../source_pin_state.zig").requireNoPrepared(&txn, command.scope().namespace());
            if (try doc_identity.loadNamespaceTxn(&txn)) |stored| {
                if (!stored.eql(command.scope().fence.namespace)) return error.IdentityNamespaceMismatch;
            } else {
                const namespace_bytes = command.scope().namespace();
                try txn.put(&internal_keys.identity_namespace_key, &namespace_bytes);
            }
            const source_authority = @import("../source_authority.zig");
            if (command.scope().authority == .native) {
                applied_index = try source_authority.advance(&txn, command.scope().namespace(), opts.online_source_applied_index);
            } else if (try source_authority.load(&txn) != null) {
                _ = try source_authority.require(&txn, .raft, command.scope().namespace());
            }
            if (command == .final_fence) {
                var manager = try self.core.initTxnManager();
                defer manager.deinit();
                try @import("relational_integrity_topology.zig").requireDrained(&txn, &manager, command.scope().fence);
            }
            if (command == .admit) {
                // Candidate discovery is advisory. Recheck the durable local
                // receiver transition in this admission transaction so an
                // intervening ordinary merge cannot acquire both roles.
                const merge_raw = txn.get(merge_state_mod.key) catch |err| switch (err) {
                    // Older receiver checkpoints remain authoritative until
                    // protectForSplit atomically upgrades their key. Do not
                    // admit a source role over an active legacy receiver.
                    error.NotFound => txn.get(merge_state_mod.legacy_key) catch |legacy_err| switch (legacy_err) {
                        error.NotFound => null,
                        else => return legacy_err,
                    },
                    else => return err,
                };
                if (merge_raw) |raw| {
                    var state = try merge_state_mod.decodeAlloc(self.alloc, raw);
                    defer state.deinit(self.alloc);
                    if (state.phase != .finalized and state.phase != .rolled_back and state.phase != .none) return error.IntegrityTopologyBusy;
                }
            }
            try @import("online_source.zig").stage(&txn, command, applied_index);
            if (req.artifact_catalog) |install| try @import("artifact_reconcile_intent.zig").clear(self.alloc, &txn, install, applied_index);
            if (!opts.bypass_replication_write_gate and self.local_execution.replication_async_batch_mirror != null)
                payload = if (req.artifact_catalog != null) try replication_effects_mod.encodeArtifactCatalogMutationRequestAlloc(self.alloc, req, opts.ordered_apply_receipt orelse return error.InvalidArtifactCatalogCommand) else try replication_effects_mod.encodeOnlineSourceMutationRequestAlloc(self.alloc, req, applied_index);
            for (opts.extra_store_writes) |write| try txn.put(write.key, write.value);
            if (opts.ordered_apply_receipt) |entry| {
                var bytes: [ordered_apply_receipt_value_len]u8 = undefined;
                const marker = orderedApplyReceiptWrite(entry, &bytes);
                try txn.put(marker.key, marker.value);
            }
            if (opts.replication_applied_lsn_marker) |lsn| {
                var bytes: [replication_applied_lsn_value_len]u8 = undefined;
                const marker = replicationAppliedSequenceWrite(lsn, &bytes);
                try txn.put(marker.key, marker.value);
            }
            try self.stageRestoreStagingReplicationOutbox(&txn, payload);
            try txn.commit();
            txn_open = false;
            if (command == .admit) {
                try @import("source_pin.zig").afterPrepare();
                try @import("source_pin.zig").ensureAssumeApply(self, command.scope());
            }
        }
        if (command == .release) {
            const io = self.backend_runtime.io() orelse std.Options.debug_io;
            self.local_execution.source_publication.cancelScope(io, command.scope());
            self.local_execution.online_merge_reader.retire(io, command.scope());
        }
        if (command == .release) @import("source_pin.zig").reclaimReleased(self, command.scope()) catch |err| {
            // Release is already durable. Replica-local cleanup failures keep
            // the bounded slot reserved, but cannot suppress its outbox flush
            // or misreport the replicated terminal decision as rejected.
            if (builtin.is_test and err == error.InjectedSourcePinFailure) return err;
        };
        if (payload != null) try self.flushDurableReplicationOutboxes();
    }

    fn preflightArtifactAdmission(self: *DB, req: types.BatchRequest, entry: anytype) !@import("artifact_reconcile_intent.zig").Context {
        try @import("artifact_inventory.zig").validateRequest(req);
        try @import("artifact_reconcile.zig").validateDesired(self.alloc, req.artifact_catalog.?);
        if (!std.mem.eql(u8, &req.artifact_catalog.?.namespace, &@import("online_source_contract.zig").namespaceBytes(self.core.identity_namespace))) return error.IdentityNamespaceMismatch;
        if (self.local_execution.row_policy_gate.currentPhase() != .disabled) return error.RowPolicyTopologyUnsupported;
        try @import("../range_protection.zig").validateRequest(req);
        try @import("merge_page_contract.zig").validateRequest(req);
        try @import("online_source_contract.zig").validateRequest(req);
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (self.local_execution.row_policy_gate.currentPhase() != .disabled) return error.RowPolicyTopologyUnsupported;
        var txn = try self.core.store.beginWriteTxn();
        var preflight_open = true;
        defer if (preflight_open) txn.abort();
        const prepared = try @import("artifact_inventory.zig").prepareOrdered(self.alloc, &txn, req.artifact_catalog.?, entry.index);
        defer if (prepared) |bytes| self.alloc.free(bytes);
        // Speculative admission derives the effect language from the same
        // ordered catalog as final admission. This transaction is aborted
        // before installing the durable reconciliation intent.
        if (prepared) |bytes| try txn.put(@import("artifact_inventory.zig").ordered_key, bytes);
        try @import("restore_staging.zig").requireScope(self.alloc, &txn, null, false);
        const raw = txn.get(merge_state_mod.key) catch |err| switch (err) {
            error.NotFound => txn.get(merge_state_mod.legacy_key) catch |legacy_err| switch (legacy_err) {
                error.NotFound => null,
                else => return legacy_err,
            },
            else => return err,
        };
        var existing = if (raw) |bytes| try merge_state_mod.decodeAlloc(self.alloc, bytes) else null;
        defer if (existing) |*state| state.deinit(self.alloc);
        if (req.online_source) |source| {
            if (source != .admit or source.scope().authority != .raft) return error.InvalidArtifactCatalogCommand;
            const lsm = self.core.primary_store_owner.lsmBackend() orelse return error.BackupSealBackendUnsupported;
            if (lsm.storage) |storage| if (!storage.supportsHostPathGenerationPublication()) return error.NativeBackupStorageBackendUnsupported;
            if (!source.scope().fence.namespace.eql(self.core.identity_namespace)) return error.IdentityNamespaceMismatch;
            if (try doc_identity.loadNamespaceTxn(&txn)) |stored| {
                if (!stored.eql(source.scope().fence.namespace)) return error.IdentityNamespaceMismatch;
            } else try txn.put(&internal_keys.identity_namespace_key, &source.scope().namespace());
            if (existing) |state| if (state.phase != .none and state.phase != .finalized and state.phase != .rolled_back) return error.IntegrityTopologyBusy;
            const authority = @import("../source_authority.zig");
            if (try authority.load(&txn) != null) _ = try authority.require(&txn, .raft, source.scope().namespace());
            try @import("online_source.zig").stage(&txn, source, entry.index);
        } else if (req.merge_checkpoint) |checkpoint| {
            if (try @import("relational_integrity_topology.zig").current(&txn) != null) return error.IntegrityTopologyBusy;
            if (checkpoint.page_source) |source| {
                try source.validate();
                if (source.artifact_catalog) |binding| if (!binding.compatible(req.artifact_catalog.?.binding)) return error.InvalidArtifactCatalogCommand;
            }
            if (try @import("../retained_effects.zig").load(&txn)) |retained| {
                const namespace = @import("online_source_contract.zig").namespaceBytes(self.core.identity_namespace);
                if (retained.active() and std.mem.eql(u8, &retained.namespace, &namespace)) return error.IntegrityTopologyBusy;
            }
            var coordinated = try @import("online_integrity_shadow.zig").admit(self.alloc, &txn, req, self.core.identity_namespace);
            if (!coordinated) coordinated = try @import("relational_integrity_handoff.zig").admitMergeRequest(self.alloc, &txn, req);
            var schema_view = self.core.schema_registry.acquire();
            defer if (schema_view) |*view| view.release();
            if (hasCoordinatedConstraints(schema_view) and !coordinated) return error.CoordinatedConstraintTopologyUnsupported;
            if (checkpoint.receiver_identity_reassignment_namespace) |namespace| {
                if (!checkpoint.allow_doc_identity_reassignment or !namespace.eql(self.core.identity_namespace)) return error.DocIdentityNamespaceMismatch;
            } else if (checkpoint.allow_doc_identity_reassignment) return error.InvalidBatchRequest;
            const plan = try merge_state_mod.planCheckpointApply(self.alloc, if (existing) |*state| state else null, self.core.byteRange(), checkpoint);
            defer plan.deinit(self.alloc);
            const pages = @import("merge_page_contract.zig");
            const page_raw = txn.get(pages.key) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            var progress = if (page_raw) |bytes| try pages.decode(self.alloc, bytes) else null;
            defer if (progress) |*value| value.deinit();
            _ = try pages.checkpointPlan(existing, plan.state, checkpoint, if (progress) |value| value.value else null);
            if (checkpoint.page_receiver_namespace) |namespace| if (!namespace.eql(self.core.identity_namespace)) return error.DocIdentityNamespaceMismatch;
        }
        // Discard the speculative admission writes, then reserve its exact
        // committed authority while still holding the native apply mutex.
        txn.abort();
        preflight_open = false;
        var intent_txn = try self.core.store.beginWriteTxn();
        errdefer intent_txn.abort();
        const context = try @import("artifact_reconcile_intent.zig").stage(self.alloc, &intent_txn, req, entry);
        try intent_txn.commit();
        return context;
    }

    pub fn reconcileOrderedArtifactCatalogStep(self: *DB, command: @import("artifact_inventory.zig").Command, applied_index: u64) !bool {
        return self.reconcileOrderedArtifactCatalogWithContext(command, applied_index, null);
    }

    fn reconcileOrderedArtifactCatalogWithContext(self: *DB, command: @import("artifact_inventory.zig").Command, applied_index: u64, context: ?@import("artifact_reconcile_intent.zig").Context) !bool {
        if (!std.mem.eql(u8, &command.namespace, &@import("online_source_contract.zig").namespaceBytes(self.core.identity_namespace))) return error.IdentityNamespaceMismatch;
        {
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            const validated = try @import("artifact_inventory.zig").prepareOrdered(self.alloc, &read, command, applied_index);
            defer if (validated) |bytes| self.alloc.free(bytes);
            if (std.mem.eql(u8, &(try @import("artifact_inventory.zig").catalogs(&read)).digest(), &command.binding.digest) and try self.artifactMaterializationsReady(&read, command.catalogs)) return true;
        }
        return @import("artifact_reconcile.zig").step(self, command, context orelse return error.ArtifactCatalogDrift);
    }

    pub fn alignOrderedArtifactCatalog(self: *DB, command: @import("artifact_inventory.zig").Command, configs: []const types.IndexConfig, context: @import("artifact_reconcile_intent.zig").Context) !void {
        var guard = self.beginIndexStructuralMutation("ordered artifact reconciliation", "");
        defer guard.deinit();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        var txn = try self.core.store.beginWriteTxn();
        errdefer txn.abort();
        try self.requireOnlineArtifactCatalogMutableWithContextLocked(&txn, context);
        try self.requireArtifactReconcileUnfenced(&txn, context);
        try self.core.index_manager.alignRowDerivedArtifactCatalog(&txn, command.catalogs, configs);
        try txn.commit();
        self.core.index_manager.invalidateWritePlanSnapshot();
    }

    /// Advance one replica-local initial-build quantum under the exact durable
    /// admission fence. This never grants authority to unrelated operator
    /// repairs or to an obsolete catalog. The primary apply cut is stationary
    /// while reconciliation runs; physical projection publication remains
    /// fenced by the repair intent's root/config/control identity.
    pub fn advanceOrderedArtifactInitialBuild(self: *DB, configs: []const types.IndexConfig, context: @import("artifact_reconcile_intent.zig").Context) !void {
        {
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            try @import("artifact_reconcile_intent.zig").requireContext(self.alloc, &read, context);
        }
        for (configs) |config| {
            if (!self.core.index_manager.repairUnavailable(config.name)) continue;
            const repair_id = try self.indexRepairIdForIndex(self.alloc, config.name) orelse continue;
            var entry = try self.loadIndexRepairEntryById(self.alloc, repair_id);
            defer entry.deinit(self.alloc);
            if (entry.intent.work_class != .initial_build or entry.intent.trigger != .catalog_admission or
                entry.intent.config_hash != types.indexConfigHash(config) or entry.intent.kind != config.kind or
                entry.intent.root_generation != self.core.root_generation or entry.intent.group_id != self.localRepairGroupId()) continue;
            const Quantum = struct {
                deadline_ns: u64,
                fn requested(ptr: *anyopaque) bool {
                    const quantum: *@This() = @ptrCast(@alignCast(ptr));
                    return monotonicTimeNs() >= quantum.deadline_ns;
                }
            };
            var quantum: Quantum = .{ .deadline_ns = monotonicTimeNs() +| 20 * std.time.ns_per_ms };
            _ = try self.advanceIndexRepairIntent(self.alloc, repair_id, .{
                .target_index_name = config.name,
                .yield_check = .{ .ptr = &quantum, .is_requested = Quantum.requested },
            });
            return;
        }
    }

    pub fn reconcileArtifactAddIndex(self: *DB, cfg: types.IndexConfig, context: @import("artifact_reconcile_intent.zig").Context) !?u128 {
        return self.addIndexForReconciliation(cfg, .managed, context);
    }
    pub fn reconcileArtifactDeleteIndex(self: *DB, name: []const u8, context: @import("artifact_reconcile_intent.zig").Context) !bool {
        return self.deleteIndexForReconciliation(name, context);
    }
    pub fn reconcileArtifactDeleteResolver(self: *DB, name: []const u8, context: @import("artifact_reconcile_intent.zig").Context) !bool {
        const removed = try self.removeResolverForReconciliation(name, context);
        if (removed) self.stopResolverReplayRuntimesIfUnconfigured();
        return removed;
    }
    pub fn reconcileArtifactDeleteEnrichment(self: *DB, kind: types.EnrichmentKind, name: []const u8, context: @import("artifact_reconcile_intent.zig").Context) !bool {
        return self.deleteEnrichmentForReconciliation(kind, name, context);
    }
    pub fn reconcileArtifactAddEnrichment(self: *DB, cfg: types.EnrichmentConfig, context: @import("artifact_reconcile_intent.zig").Context) !void {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        // Exact committed reconciliation provenance authorizes standby
        // materialization; no public/local configuration bypass is exposed.
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        {
            var probe = try self.core.store.beginProbeTxn();
            defer probe.abort();
            try self.requireOnlineArtifactCatalogMutableWithContextLocked(&probe, context);
        }
        try self.enforceVectorMigrationConfigurationGate();
        _ = try self.core.upsertEnrichment(cfg);
    }

    pub const artifactMaterializationsReady = local_mutation.artifactMaterializationsReady;

    pub fn artifactInventoryStatus(self: *DB) !@import("artifact_inventory.zig").Status {
        var txn = try self.core.store.beginReadTxn();
        defer txn.abort();
        var namespace: [24]u8 = undefined;
        doc_identity.encodeNamespace(&namespace, self.core.identity_namespace);
        var observed = try @import("artifact_inventory.zig").status(self.alloc, &txn, namespace);
        if (observed.ready) observed.ready = try self.artifactMaterializationsReady(&txn, try @import("artifact_inventory.zig").catalogs(&txn));
        return observed;
    }

    /// The caller verifies this desired catalog against its metadata read-index
    /// before proposal. Ownership of catalogs belongs to the caller.
    pub fn artifactInventoryCommand(self: *DB, alloc: Allocator) !@import("artifact_inventory.zig").Command {
        const inventory = @import("artifact_inventory.zig");
        var txn = try self.core.store.beginReadTxn();
        defer txn.abort();
        if (try @import("artifact_reconcile_intent.zig").load(alloc, &txn)) |intent| {
            defer intent.deinit();
            var command = intent.value.command;
            command.catalogs.indexes = try alloc.dupe(u8, command.catalogs.indexes);
            errdefer alloc.free(command.catalogs.indexes);
            command.catalogs.enrichments = try alloc.dupe(u8, command.catalogs.enrichments);
            errdefer alloc.free(command.catalogs.enrichments);
            command.catalogs.resolvers = try alloc.dupe(u8, command.catalogs.resolvers);
            return command;
        }
        var namespace: [24]u8 = undefined;
        doc_identity.encodeNamespace(&namespace, self.core.identity_namespace);
        const observed = try inventory.status(alloc, &txn, namespace);
        const catalogs = try inventory.copyCatalogs(alloc, &txn);
        errdefer {
            var owned = catalogs;
            owned.deinit(alloc);
        }
        return .{ .namespace = namespace, .previous = observed.ordered, .binding = .{ .epoch = try std.math.add(u64, if (observed.ordered) |value| value.epoch else 0, 1), .digest = catalogs.digest(), .semantic_digest = try catalogs.semanticDigest(alloc) }, .catalogs = catalogs };
    }

    fn completeArtifactUpload(txn: anytype, finalization: ?@import("artifact_publication_transport.zig").Finalization, entry: OrderedApplyReceipt) !void {
        if (finalization) |prepared| {
            const upload = prepared.control;
            if (upload.action != .finalize) return error.InvalidBatchRequest;
            try @import("artifact_publication_transport.zig").stageCompletion(txn, upload.namespace, upload.publication_digest, upload.manifest_root, prepared.created_index, entry.index);
        }
    }

    fn applyMergeProofAdoptionBatch(self: *DB, req: types.BatchRequest, opts: BatchExecutionOptions) !void {
        const adoption = @import("merge_proof_adoption.zig");
        const proof_batch = @import("source_proof_batch.zig");
        const provenance = @import("artifact_producer_provenance.zig");
        try adoption.validateRequest(req);
        const command = req.merge_proof_adoption orelse return error.InvalidBatchRequest;
        const entry = opts.ordered_apply_receipt orelse return error.InvalidBatchRequest;
        if (entry.term == 0 or entry.index == 0 or opts.artifact_upload_finalize != null or
            opts.extra_store_writes.len != 0 or opts.extra_store_deletes.len != 0) return error.InvalidBatchRequest;
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;

        var replication_mutation = if (opts.bypass_replication_write_gate) null else self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        if (!opts.bypass_replication_write_gate) {
            try self.enforceReplicationWriteGate();
            try self.ensureDurableReplicationStartupBarrier();
            try self.flushDurableReplicationOutboxes();
            try self.preflightReplicationBatchSyncCommit();
        }
        const replication_payload = if (!opts.bypass_replication_write_gate and self.local_execution.replication_async_batch_mirror != null)
            try replication_effects_mod.encodeMergeProofAdoptionMutationRequestAlloc(self.alloc, req, entry)
        else
            null;
        defer if (replication_payload) |value| self.alloc.free(value);

        var preparation_budget = if (self.core.index_manager.resource_manager) |manager|
            resource_manager_mod.BudgetedAllocator.init(manager, .shard_transition_working_set, self.alloc, 1)
        else
            null;
        defer if (preparation_budget) |*budget| budget.deinit();
        const preparation_alloc = if (preparation_budget) |*budget| budget.allocator() else self.alloc;
        var fence: ?adoption.Fence = null;
        defer if (fence) |*value| value.deinit(preparation_alloc);
        var prepared: ?proof_batch.PreparedAdoption = null;
        defer if (prepared) |*value| value.deinit(preparation_alloc);
        {
            var read = try self.core.store.beginReadTxnWithBlockCacheAdmission(.transient);
            defer read.abort();
            fence = adoption.loadFence(preparation_alloc, &read, self.core.identity_namespace, command) catch |err| {
                if (err == error.OutOfMemory) if (preparation_budget) |*budget| if (budget.denied()) return error.ResourceBudgetExceeded;
                return err;
            };
            if (fence) |*current| {
                var plan = proof_batch.ReceiverProducerPlan.initForMerge(preparation_alloc, &read, current.progress.value) catch |err| switch (err) {
                    error.ArtifactCatalogDrift => null,
                    error.OutOfMemory => {
                        if (preparation_budget) |*budget| if (budget.denied()) return error.ResourceBudgetExceeded;
                        return err;
                    },
                    else => return err,
                };
                defer if (plan) |*value| value.deinit();
                if (plan) |*mapping| {
                    var receiver_namespace: [24]u8 = undefined;
                    var donor_namespace: [24]u8 = undefined;
                    doc_identity.encodeNamespace(&receiver_namespace, current.progress.value.receiver_namespace);
                    doc_identity.encodeNamespace(&donor_namespace, current.progress.value.source.namespace);
                    prepared = proof_batch.prepareAdoption(preparation_alloc, &read, receiver_namespace, try current.donorRange(), command.source_pin, donor_namespace, command.proof_digest, mapping) catch |err| switch (err) {
                        error.ArtifactAdoptionUnsupported, error.ArtifactCatalogDrift => null,
                        error.OutOfMemory => {
                            if (preparation_budget) |*budget| if (budget.denied()) return error.ResourceBudgetExceeded;
                            return err;
                        },
                        else => return err,
                    };
                }
            }
        }

        var mutation = self.core.snapshot_admission.acquireMutation();
        defer mutation.release();
        try self.lockApplyForPortableRuntime();
        var apply_held = true;
        defer if (apply_held) self.core.unlockApply();
        if (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), entry) == .already_applied) return;
        var txn = try self.core.store.beginWriteTxn();
        errdefer txn.abort();
        if (fence) |*current| if (prepared) |*candidate| {
            if (std.mem.eql(u8, &candidate.candidate.donor.record_digest, &command.record_digest) and
                try current.matchesStored(&txn) and
                try proof_batch.revalidateReceiverCandidate(preparation_alloc, &txn, candidate.candidate.receiver.namespace, candidate.candidate))
            {
                // No donor receipt, sequence or physical position is trusted.
                // The ordered Raft index is this metadata-only receipt's
                // monotonic publication sequence; copied values were already
                // installed and journaled by merge pages.
                try provenance.stageAdoptedIndexed(&txn, candidate.adopted.proof, candidate.adopted.encoded, candidate.positions, .{ .raft = .{ .term = entry.term, .index = entry.index } }, &candidate.references, entry.index);
            }
        };
        var marker_buf: [ordered_apply_receipt_value_len]u8 = undefined;
        const marker = orderedApplyReceiptWrite(entry, &marker_buf);
        try txn.put(marker.key, marker.value);
        var standby_buf: [replication_applied_lsn_value_len]u8 = undefined;
        if (opts.replication_applied_lsn_marker) |lsn| {
            const standby = replicationAppliedSequenceWrite(lsn, &standby_buf);
            try txn.put(standby.key, standby.value);
        }
        try self.stageRestoreStagingReplicationOutbox(&txn, replication_payload);
        try txn.commit();
        self.core.unlockApply();
        apply_held = false;
        if (replication_payload != null) try self.flushDurableReplicationOutboxes();
    }

    fn applyArtifactPublicationTransportBatch(self: *DB, req: types.BatchRequest, opts: BatchExecutionOptions) !void {
        const transport = @import("artifact_publication_transport.zig");
        const control = req.artifact_publication_transport orelse return error.InvalidBatchRequest;
        try transport.validateBatchRequest(req);
        const entry = opts.ordered_apply_receipt orelse return error.InvalidBatchRequest;
        if (entry.term == 0 or entry.index == 0 or opts.artifact_upload_finalize != null) return error.InvalidBatchRequest;
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var namespace: [24]u8 = undefined;
        doc_identity.encodeNamespace(&namespace, self.core.identity_namespace);
        if (control.action != .prune and !std.mem.eql(u8, &namespace, &control.namespace)) return error.IdentityNamespaceMismatch;
        // Assemble against one immutable snapshot outside apply. The final
        // publication transaction checks the same immutable manifest root
        // again, so concurrent pruning cannot publish partially retired work.
        if (control.action == .finalize) assembly: {
            var read = try self.core.store.beginReadTxn();
            var read_open = true;
            defer if (read_open) read.abort();
            if (try transport.terminal(&read, namespace, control.publication_digest)) |decided| {
                if (!std.mem.eql(u8, &decided.root, &control.manifest_root)) return error.ArtifactPublicationUploadChanged;
            } else {
                const raw = read.get(&transport.manifestKey(namespace, control.publication_digest)) catch |err| switch (err) {
                    error.NotFound => break :assembly,
                    else => return err,
                };
                const manifest = try transport.decodeManifest(raw);
                // A recovered hint is tied to one durable upload incarnation.
                // Prune/recreate makes the hint an inert ordered entry, not
                // authority to consume a different upload with the same root.
                if (control.created_index != 0 and control.created_index != manifest.created_index) break :assembly;
                var reservation: ?resource_manager_mod.Reservation = null;
                defer if (reservation) |*value| value.release();
                // Charge the encoded command, backend read buffers and
                // decoded slice tables before allocating the assembly.
                if (self.core.index_manager.resource_manager) |manager| reservation = try manager.reserveWithoutReclaim(.shard_transition_working_set, @as(u64, manifest.encoded_len) * 2 + 4 * 1024 * 1024);
                var decoded = transport.assembleAlloc(self.alloc, &read, namespace, control.publication_digest, control.manifest_root) catch |err| switch (err) {
                    error.ArtifactPublicationUploadMissing, error.ArtifactPublicationUploadIncomplete => break :assembly,
                    else => return err,
                };
                defer decoded.deinit();
                if (decoded.command.mode == .activate) return error.InvalidBatchRequest;
                read.abort();
                read_open = false;
                var publication_opts = opts;
                publication_opts.artifact_upload_finalize = .{ .control = control, .created_index = manifest.created_index };
                return self.applyArtifactPublicationBatch(.{ .artifact_publication = decoded.command, .sync_level = req.sync_level }, publication_opts);
            }
        }
        var replication_mutation = if (opts.bypass_replication_write_gate) null else self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        if (!opts.bypass_replication_write_gate) {
            try self.enforceReplicationWriteGate();
            try self.ensureDurableReplicationStartupBarrier();
            try self.flushDurableReplicationOutboxes();
            try self.preflightReplicationBatchSyncCommit();
        }
        const replication_payload = if (!opts.bypass_replication_write_gate and self.local_execution.replication_async_batch_mirror != null)
            try replication_effects_mod.encodeArtifactPublicationTransportMutationRequestAlloc(self.alloc, req, entry)
        else
            null;
        defer if (replication_payload) |value| self.alloc.free(value);
        // Decode at most one chunk before entering the serialized writer.
        const chunk: ?[]u8 = if (control.action == .chunk) blk: {
            const length = std.base64.standard.Decoder.calcSizeForSlice(control.chunk_base64) catch return error.InvalidBatchRequest;
            const bytes = try self.alloc.alloc(u8, length);
            errdefer self.alloc.free(bytes);
            std.base64.standard.Decoder.decode(bytes, control.chunk_base64) catch return error.InvalidBatchRequest;
            break :blk bytes;
        } else null;
        defer if (chunk) |bytes| self.alloc.free(bytes);
        var mutation = self.core.snapshot_admission.acquireMutation();
        defer mutation.release();
        try self.lockApplyForPortableRuntime();
        var apply_held = true;
        defer if (apply_held) self.core.unlockApply();
        if (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), entry) == .already_applied) return;
        var txn = try self.core.store.beginWriteTxn();
        errdefer txn.abort();
        _ = try @import("../source_authority.zig").require(&txn, .raft, namespace);
        switch (control.action) {
            .begin => {
                _ = try transport.pruneOneExpired(&txn, entry.index);
                // Upload backpressure must not wedge an already committed
                // Raft entry. A refused begin creates no receipt or artifact;
                // the durable producer obligation remains pending for retry.
                transport.stageBegin(self.alloc, &txn, control.proposedManifest(), entry.index) catch |err| switch (err) {
                    error.ResourceLimitExceeded => {},
                    else => return err,
                };
            },
            .chunk => transport.stageChunk(&txn, namespace, control.publication_digest, control.manifest_root, control.ordinal, chunk.?) catch |err| switch (err) {
                error.ArtifactPublicationUploadMissing => {},
                else => return err,
            },
            .finalize => {
                if (try transport.terminal(&txn, namespace, control.publication_digest)) |decided| {
                    if (!std.mem.eql(u8, &decided.root, &control.manifest_root)) return error.ArtifactPublicationUploadChanged;
                }
                // Missing/incomplete staging is a pending upload, never a
                // semantic success. Only the common publication writer can
                // create a terminal record and producer receipt.
            },
            .prune => _ = try transport.pruneOneExpired(&txn, entry.index),
            .abandon => _ = try transport.stageAbandon(&txn, control),
        }
        var marker_buf: [ordered_apply_receipt_value_len]u8 = undefined;
        const marker = orderedApplyReceiptWrite(entry, &marker_buf);
        try txn.put(marker.key, marker.value);
        var standby_buf: [replication_applied_lsn_value_len]u8 = undefined;
        if (opts.replication_applied_lsn_marker) |lsn| {
            const standby = replicationAppliedSequenceWrite(lsn, &standby_buf);
            try txn.put(standby.key, standby.value);
        }
        for (opts.extra_store_writes) |write| try txn.put(write.key, write.value);
        for (opts.extra_store_deletes) |key| try txn.delete(key);
        try self.stageRestoreStagingReplicationOutbox(&txn, replication_payload);
        try txn.commit();
        self.core.unlockApply();
        apply_held = false;
        if (replication_payload != null) try self.flushDurableReplicationOutboxes();
    }

    fn rejectArtifactPublicationAssumeApply(self: *DB, command: @import("artifact_publication.zig").Command, opts: BatchExecutionOptions, replication_payload: ?[]const u8, reason: @import("artifact_publication.zig").Rejection, apply_held: *bool) !void {
        // A source/catalog race is an ordered outcome, not an apply failure.
        // Keep accepted provenance intact and commit the rejection with the
        // applied watermark, so retries cannot wedge a committed Raft entry.
        const entry = opts.ordered_apply_receipt orelse return error.InvalidBatchRequest;
        var txn = try self.core.store.beginWriteTxn();
        errdefer txn.abort();
        try @import("artifact_publication.zig").stageRejection(&txn, command, entry.index, reason);
        // Baseline readiness is temporary: keep the immutable upload so the
        // same logical publication can finalize after reconciliation. A
        // terminal upload record here would strand its retry forever.
        if (reason != .baseline_pending) try completeArtifactUpload(&txn, opts.artifact_upload_finalize, entry);
        var marker_buf: [ordered_apply_receipt_value_len]u8 = undefined;
        const marker = orderedApplyReceiptWrite(entry, &marker_buf);
        try txn.put(marker.key, marker.value);
        var standby_buf: [replication_applied_lsn_value_len]u8 = undefined;
        if (opts.replication_applied_lsn_marker) |lsn| {
            const standby = replicationAppliedSequenceWrite(lsn, &standby_buf);
            try txn.put(standby.key, standby.value);
        }
        for (opts.extra_store_writes) |write| try txn.put(write.key, write.value);
        for (opts.extra_store_deletes) |key| try txn.delete(key);
        try self.stageRestoreStagingReplicationOutbox(&txn, replication_payload);
        try txn.commit();
        self.core.unlockApply();
        apply_held.* = false;
        if (replication_payload != null) try self.flushDurableReplicationOutboxes();
    }

    fn applyArtifactPublicationBatch(self: *DB, req: types.BatchRequest, opts: BatchExecutionOptions) !void {
        const publication = @import("artifact_publication.zig");
        const inventory = @import("artifact_inventory.zig");
        try publication.validateRequest(self.alloc, req);
        const command = req.artifact_publication orelse return error.InvalidBatchRequest;
        const entry = opts.ordered_apply_receipt orelse return error.InvalidBatchRequest;
        if (entry.term == 0 or entry.index == 0) return error.InvalidBatchRequest;
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = if (opts.bypass_replication_write_gate) null else self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        if (!opts.bypass_replication_write_gate) {
            try self.enforceReplicationWriteGate();
            try self.ensureDurableReplicationStartupBarrier();
            try self.flushDurableReplicationOutboxes();
            try self.preflightReplicationBatchSyncCommit();
        }
        const replication_payload = if (!opts.bypass_replication_write_gate and self.local_execution.replication_async_batch_mirror != null)
            if (opts.artifact_upload_finalize) |upload|
                try replication_effects_mod.encodeArtifactPublicationTransportMutationRequestAlloc(self.alloc, .{ .artifact_publication_transport = upload.control, .sync_level = req.sync_level }, entry)
            else
                try replication_effects_mod.encodeArtifactPublicationMutationRequestAlloc(self.alloc, req, entry)
        else
            null;
        defer if (replication_payload) |value| self.alloc.free(value);
        // Prepare immutable producer bytes against a copied ordered catalog
        // before taking apply. The exact epoch/digest is checked again below;
        // a concurrent catalog change makes this work a durable rejection.
        var prepared: ?publication.PreparedBaseVectors = null;
        defer if (prepared) |*value| value.deinit();
        var preparation_error: ?anyerror = null;
        var input_preparation_error = false;
        var prepared_replay: ?[]u8 = null;
        defer if (prepared_replay) |value| self.alloc.free(value);
        var prepared_proof: ?[]u8 = null;
        defer if (prepared_proof) |value| self.alloc.free(value);
        var prepared_document_refs: ?@import("artifact_producer_provenance.zig").PreparedDocumentReferences = null;
        defer if (prepared_document_refs) |*value| value.deinit();
        var coverage_layout: ?@import("artifact_coverage_layout.zig").Layout = null;
        defer if (coverage_layout) |*value| value.deinit();
        var reservation: ?resource_manager_mod.Reservation = null;
        defer if (reservation) |*value| value.release();
        var census_budget = if ((command.mode == .census or command.mode == .complete_streams or command.mode == .reconcile_units) and self.core.index_manager.resource_manager != null)
            resource_manager_mod.BudgetedAllocator.init(self.core.index_manager.resource_manager.?, .shard_transition_working_set, self.alloc, 1)
        else
            null;
        defer if (census_budget) |*budget| budget.deinit();
        var prepared_census: ?@import("artifact_stream_progress.zig").Prepared = null;
        defer if (prepared_census) |*value| value.deinit();
        var prepared_inventory: ?@import("artifact_chunk_inventory_progress.zig").Prepared = null;
        defer if (prepared_inventory) |*value| value.deinit();
        var prepared_units: ?@import("artifact_unit_progress.zig").Prepared = null;
        defer if (prepared_units) |*value| value.deinit();
        const completion = @import("artifact_completion_progress.zig");
        var prepared_completion: ?completion.Prepared(completion.StreamVerifier.Witness) = null;
        defer if (prepared_completion) |*value| value.deinit();
        if (command.mode == .census or command.mode == .complete_streams or command.mode == .reconcile_units) {
            var plan = try self.core.index_manager.acquireWritePlanSnapshot();
            defer plan.release();
            const census_alloc = if (census_budget) |*budget| budget.allocator() else self.alloc;
            // Each receiver certifies its own physical projection, before
            // opening the read snapshot used to prepare ordered completion.
            if (command.mode == .complete_streams) {
                const claim = command.completion.?;
                self.refreshArtifactProjections(census_alloc, claim.document_key, plan.plan(), .{ .visits = claim.visits, .bytes = claim.bytes, .time_budget_ns = null }) catch |err| {
                    if (err == error.OutOfMemory) if (census_budget) |*budget| if (budget.denied()) return error.ResourceBudgetExceeded;
                    preparation_error = err;
                };
            }
            var read = try self.core.store.beginReadTxnWithBlockCacheAdmission(.transient);
            defer read.abort();
            if (command.mode == .complete_streams) {
                if (preparation_error == null) prepared_completion = completion.prepareCommand(census_alloc, &read, self.root_incarnation, command, plan.plan()) catch |err| blk: {
                    if (err == error.OutOfMemory) if (census_budget) |*budget| if (budget.denied()) return error.ResourceBudgetExceeded;
                    preparation_error = err;
                    break :blk null;
                };
            } else if (command.mode == .reconcile_units) {
                prepared_units = @import("artifact_unit_progress.zig").prepareCommand(census_alloc, &read, self.root_incarnation, command, plan.plan()) catch |err| blk: {
