    fn applyGenerationGcBatch(self: *DB, req: types.BatchRequest, opts: BatchExecutionOptions) !void {
        try req.relational_generation_gc.?.validate();
        if (req.relational_topology != null or req.row_policy_publication != null or req.online_source != null or req.restore_staging != null or
            req.restore_staging_scope != null or req.restore_staging_plan_id != null or req.merge_page != null or
            req.transaction != null or req.writes.len != 0 or req.deletes.len != 0 or req.transforms.len != 0 or
            req.graph_writes.len != 0 or req.graph_deletes.len != 0 or req.integrity.len != 0 or
            req.integrity_commands.len != 0 or req.predicates.len != 0 or req.relational_activation != null or
            req.relational_retirement != null or req.relational_index_maintenance != null or req.relational_repair or
            req.split_checkpoint != null or req.split_replication != null or req.split_transition != null or
            req.merge_checkpoint != null or req.merge_replication != null or req.merge_source_transition != null or
            req.merge_artifacts.len != 0 or req.range_guards.len != 0 or req.activate_range_tracking or
            req.schema_version != null or req.relational_schema_version != null or req.relational_integrity_generation_set != null) return error.InvalidBatchRequest;
        var mutation = if (opts.bypass_replication_write_gate) null else self.acquireReplicationMutationShared();
        defer if (mutation) |*lease| lease.release();
        if (!opts.bypass_replication_write_gate) {
            try self.enforceReplicationWriteGate();
            try self.ensureDurableReplicationStartupBarrier();
            try self.flushDurableReplicationOutboxes();
            try self.preflightReplicationBatchSyncCommit();
        }
        const payload = if (!opts.bypass_replication_write_gate and self.local_execution.replication_async_batch_mirror != null)
            try replication_effects_mod.encodeBatchMutationRequestAlloc(self.alloc, req)
        else
            null;
        defer if (payload) |bytes| self.alloc.free(bytes);
        var admission = self.core.snapshot_admission.acquireMutation();
        defer admission.release();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (opts.ordered_apply_receipt) |entry| switch (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), entry)) {
            .already_applied => return,
            .apply => {},
        };
        var txn = try self.core.store.beginWriteTxn();
        errdefer txn.abort();
        if (req.relational_generation_gc.?.owner_group_id == 0 or !req.relational_generation_gc.?.namespace.eql(self.core.identity_namespace)) return error.IdentityNamespaceMismatch;
        // A page prepared at read-index can lose a race to a new reference,
        // activation or topology fence before its Raft entry applies. Such an
        // admitted entry must still advance the applied marker on every
        // replica; the next bounded sweep will reprepare from durable state.
        if (try @import("relational_integrity_topology.zig").current(&txn) == null) {
            @import("relational_integrity_generation_retirement.zig").applyGcPage(&txn, req.relational_generation_gc.?) catch |err| switch (err) {
                error.GenerationRetirementChanged => {},
                else => return err,
            };
        }
        if (opts.ordered_apply_receipt) |entry| {
            var marker_buf: [ordered_apply_receipt_value_len]u8 = undefined;
            const marker = orderedApplyReceiptWrite(entry, &marker_buf);
            try txn.put(marker.key, marker.value);
        }
        if (opts.replication_applied_lsn_marker) |lsn| {
            var marker_buf: [replication_applied_lsn_value_len]u8 = undefined;
            const marker = replicationAppliedSequenceWrite(lsn, &marker_buf);
            try txn.put(marker.key, marker.value);
        }
        try self.stageRestoreStagingReplicationOutbox(&txn, payload);
        try txn.commit();
        if (payload != null) try self.flushDurableReplicationOutboxes();
    }

    fn applyRelationalTopologyBatch(self: *DB, req: types.BatchRequest, opts: BatchExecutionOptions) !void {
        if (req.relational_index_maintenance != null) return error.InvalidBatchRequest;
        const hidden_handoff_install = if (req.relational_topology) |control| control.action == .install_generation_handoff else false;
        if (hidden_handoff_install) {
            const control = req.relational_topology.?;
            const install = control.generation_handoff_install orelse return error.InvalidBatchRequest;
            var expected_plan_id: [16]u8 = undefined;
            std.mem.writeInt(u64, expected_plan_id[0..8], control.fence.transition_id, .little);
            std.mem.writeInt(u64, expected_plan_id[8..16], control.fence.attempt, .little);
            if (req.restore_staging_scope == null or req.restore_staging_plan_id == null or
                !std.mem.eql(u8, &req.restore_staging_scope.?, &install.scope) or
                !std.mem.eql(u8, &req.restore_staging_plan_id.?, &expected_plan_id)) return error.InvalidBatchRequest;
        } else if (req.restore_staging_scope != null or req.restore_staging_plan_id != null) return error.InvalidBatchRequest;
        if (req.writes.len != 0 or req.deletes.len != 0 or req.transforms.len != 0 or
            req.graph_writes.len != 0 or req.graph_deletes.len != 0 or req.integrity.len != 0 or
            req.integrity_commands.len != 0 or req.predicates.len != 0 or req.transaction != null or
            req.restore_staging != null or
            req.relational_activation != null or req.relational_retirement != null or
            req.relational_repair or req.split_checkpoint != null or req.split_replication != null or
            req.merge_checkpoint != null or req.merge_replication != null or
            req.merge_source_transition != null or req.merge_artifacts.len != 0) return error.InvalidBatchRequest;
        if (req.relational_topology != null and req.split_transition != null) return error.InvalidBatchRequest;
        if (req.relational_topology) |command| if (command.fence.role == .backup_snapshot and (command.action != .begin and command.action != .release and command.action != .cancel)) return error.InvalidBatchRequest;
        if (req.relational_topology) |command| if ((command.action == .seal_graph_retirement and command.graph_retirement == null) or
            (command.graph_retirement != null and command.action != .begin and command.action != .seal_graph_retirement)) return error.InvalidBatchRequest;
        if (req.split_transition) |transition| if (transition.kind != .finalize) return error.InvalidBatchRequest;
        if (req.relational_topology) |command| if (command.action == .install_child_schema) {
            if ((command.fence.role != .child_generation_source and command.fence.role != .child_generation_dual) or command.child_schema_install == null or
                command.transfer != null or command.parent_retirement != null or command.parent_activation != null or
                command.child_generations != null) return error.InvalidBatchRequest;
            const install = command.child_schema_install.?;
            const entry = opts.ordered_apply_receipt orelse opts.native_fk_generation_entry orelse return error.InvalidBatchRequest;
            return self.installPublishedChildSchema(self.alloc, install.schema_json, .{
                .fence = command.fence,
                .before_schema_json_digest = install.before_schema_json_digest,
                .schema_json_digest = install.schema_json_digest,
                .before_catalog_digest = install.before_catalog_digest,
                .after_catalog_digest = install.after_catalog_digest,
                .ordered_receipt = entry,
                .native = opts.native_fk_generation_entry != null,
            });
        };
        if (req.relational_topology) |command| if (command.action == .provision_initial_child) {
            if (command.initial_child_provision == null or command.initial_child_control != null or
                command.child_schema_install != null or command.transfer != null or command.parent_retirement != null or
                command.parent_activation != null or command.child_generations != null) return error.InvalidBatchRequest;
            const provision = command.initial_child_provision.?;
            const entry = opts.ordered_apply_receipt orelse opts.native_initial_child_entry orelse return error.InvalidBatchRequest;
            var replication_mutation = if (opts.bypass_replication_write_gate) null else self.acquireReplicationMutationShared();
            defer if (replication_mutation) |*lease| lease.release();
            if (!opts.bypass_replication_write_gate) {
                if (self.local_execution.replication_async_metadata_mirror != null and self.local_execution.replication_async_batch_mirror == null) return error.ReplicationPublisherUnavailable;
                try self.enforceReplicationWriteGate();
                try self.ensureDurableReplicationStartupBarrier();
                try self.flushDurableReplicationOutboxes();
                try self.preflightReplicationBatchSyncCommit();
            }
            const payload = if (!opts.bypass_replication_write_gate and self.local_execution.replication_async_batch_mirror != null)
                try replication_effects_mod.encodeInitialChildMutationRequestAlloc(self.alloc, req, entry)
            else
                null;
            defer if (payload) |bytes| self.alloc.free(bytes);
            try self.provisionInitialHiddenChild(provision.schema_json, .{
                .fence = command.fence,
                .child_table_name = provision.child_table_name,
                .plan_id = provision.plan_id,
                .plan_digest = provision.plan_digest,
                .schema_digest = provision.schema_digest,
                .public_schema_json_digest = provision.public_schema_json_digest,
                .catalog_digest = provision.catalog_digest,
                .ordered_receipt = entry,
                .native = opts.native_initial_child_entry != null,
            }, opts.replication_applied_lsn_marker, payload);
            if (payload != null) try self.flushDurableReplicationOutboxes();
            return;
        };
        if (req.relational_topology) |command| if (command.action == .release_initial_child or command.action == .cancel_initial_child) {
            if (command.initial_child_control == null or command.initial_child_provision != null or
                command.child_schema_install != null or command.transfer != null or command.parent_retirement != null or
                command.parent_activation != null or command.child_generations != null) return error.InvalidBatchRequest;
            const entry = opts.ordered_apply_receipt orelse opts.native_initial_child_entry orelse return error.InvalidBatchRequest;
            var replication_mutation = if (opts.bypass_replication_write_gate) null else self.acquireReplicationMutationShared();
            defer if (replication_mutation) |*lease| lease.release();
            if (!opts.bypass_replication_write_gate) {
                if (self.local_execution.replication_async_metadata_mirror != null and self.local_execution.replication_async_batch_mirror == null) return error.ReplicationPublisherUnavailable;
                try self.enforceReplicationWriteGate();
                try self.ensureDurableReplicationStartupBarrier();
                try self.flushDurableReplicationOutboxes();
                try self.preflightReplicationBatchSyncCommit();
            }
            const payload = if (!opts.bypass_replication_write_gate and self.local_execution.replication_async_batch_mirror != null)
                try replication_effects_mod.encodeInitialChildMutationRequestAlloc(self.alloc, req, entry)
            else
                null;
            defer if (payload) |bytes| self.alloc.free(bytes);
            try self.applyInitialChildPhase(command.fence, command.initial_child_control.?, if (command.action == .release_initial_child) .released else .canceled, entry, opts.native_initial_child_entry != null, opts.replication_applied_lsn_marker, payload);
            if (payload != null) try self.flushDurableReplicationOutboxes();
            return;
        };
        var mutation = if (opts.bypass_replication_write_gate) null else self.acquireReplicationMutationShared();
        defer if (mutation) |*lease| lease.release();
        if (!opts.bypass_replication_write_gate) {
            try self.enforceReplicationWriteGate();
            try self.ensureDurableReplicationStartupBarrier();
            try self.flushDurableReplicationOutboxes();
            try self.preflightReplicationBatchSyncCommit();
        }
        const native_control = opts.ordered_apply_receipt == null and opts.native_fk_generation_entry == null and
            (if (req.relational_topology) |command| @import("native_topology_receipt.zig").supports(command) else false);
        if (native_control) try @import("native_topology_receipt.zig").validateRequest(self.alloc, req);
        const mirror_control = !opts.bypass_replication_write_gate and self.local_execution.replication_async_batch_mirror != null;
        const payload = if (mirror_control and !native_control)
            if (req.relational_topology) |command|
                if (command.action == .seal_graph_retirement)
                    try replication_effects_mod.encodeGraphRetirementSealMutationRequestAlloc(self.alloc, req, opts.ordered_apply_receipt orelse return error.InvalidBatchRequest)
                else
                    try replication_effects_mod.encodeBatchMutationRequestAlloc(self.alloc, req)
            else
                try replication_effects_mod.encodeBatchMutationRequestAlloc(self.alloc, req)
        else
            null;
        defer if (payload) |bytes| self.alloc.free(bytes);
        if (req.relational_topology) |command| {
            try self.applyRelationalTopologyControlWithReplication(command, opts.ordered_apply_receipt, opts.replication_applied_lsn_marker, payload, opts.native_fk_generation_entry, if (native_control) .{ .request = req, .replay = opts.native_topology_position, .mirror = mirror_control } else null);
        } else {
            try self.applyRangeFinalization(req.split_transition.?, opts.ordered_apply_receipt, opts.replication_applied_lsn_marker, payload);
        }
        if (mirror_control) try self.flushDurableReplicationOutboxes();
    }

    const NativeTopologyContext = struct {
        request: types.BatchRequest,
        replay: ?@import("receipt_position.zig").Native,
        mirror: bool,
    };

    fn applyRelationalTopologyControlWithReplication(
        self: *DB,
        command: @import("relational_integrity_topology.zig").Command,
        ordered_receipt: ?OrderedApplyReceipt,
        replication_lsn: ?u64,
        replication_payload: ?[]const u8,
        native_receipt: ?OrderedApplyReceipt,
        native_control: ?NativeTopologyContext,
    ) !void {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        const receipt_entry = ordered_receipt orelse native_receipt;
        var mutation = self.core.snapshot_admission.acquireMutation();
        defer mutation.release();
        const structural_held = command.action == .begin;
        if (structural_held) lockAtomicWithBackoff(&self.local_execution.index_structural_mutation_mutex);
        defer if (structural_held) self.local_execution.index_structural_mutation_mutex.unlock();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (ordered_receipt) |entry| switch (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), entry)) {
            .already_applied => return,
            .apply => {},
        };
        const graph_catalog_lock_required = command.graph_retirement != null or
            (command.fence.role == .rewrite_source and (command.action == .cancel or command.action == .abort_transition));
        if (graph_catalog_lock_required and !self.core.index_manager.catalog_mutex.tryLockExclusive()) return error.StorageBusy;
        defer if (graph_catalog_lock_required) self.core.index_manager.catalog_mutex.unlockExclusive();
        var close_graph_after_commit = false;
        var open_graph_after_commit = false;
        if (!command.fence.namespace.eql(self.core.identity_namespace)) return error.IdentityNamespaceMismatch;
        var txn = try self.core.store.beginWriteTxn();
        errdefer txn.abort();
        if (try doc_identity.loadNamespaceTxn(&txn)) |stored| {
            if (!stored.eql(command.fence.namespace)) return error.IdentityNamespaceMismatch;
        } else {
            var namespace_bytes: [24]u8 = undefined;
            doc_identity.encodeNamespace(&namespace_bytes, command.fence.namespace);
            try txn.put(&internal_keys.identity_namespace_key, &namespace_bytes);
        }
        const topology = @import("relational_integrity_topology.zig");
        if (ordered_receipt != null) try @import("../source_authority.zig").requireRaftMarkerAllowed(&txn);
        if ((command.action == .transfer) != (command.transfer != null) or
            (command.action == .seal_graph_retirement and command.graph_retirement == null) or
            (command.graph_retirement != null and command.action != .begin and command.action != .seal_graph_retirement) or
            (command.generation_handoff != null and command.action != .begin) or
            ((command.action == .seal_generation_handoff) != (command.generation_handoff_seal != null)) or
            ((command.action == .install_generation_handoff) != (command.generation_handoff_install != null)) or
            (command.action == .stage_parent_retirement) != (command.parent_retirement != null) or
            ((command.action == .activate_parent_retirement or command.action == .acknowledge_parent_retirement) != (command.parent_activation != null)) or
            ((command.action == .stage_child_generation or command.action == .activate_child_generation or command.action == .acknowledge_child_generation or
                (command.action == .cancel and (command.fence.role == .child_generation_parent or command.fence.role == .child_generation_dual))) != (command.child_generations != null))) return error.InvalidBatchRequest;
        if (command.child_schema_install != null) return error.InvalidBatchRequest;
        const native_prepared: ?@import("native_topology_receipt.zig").Prepared = if (native_control) |control| blk: {
            if (ordered_receipt != null or native_receipt != null) return error.InvalidControlReceiptPosition;
            const owner = try @import("../source_authority.zig").load(&txn);
            if (owner == null or owner.?.kind != .native) {
                if (control.replay != null) return error.InvalidControlReceiptPosition;
                break :blk null;
            }
            break :blk try @import("native_topology_receipt.zig").stage(self.alloc, &txn, command, control.replay);
        } else null;
        const stamp: ?@import("receipt_position.zig").Position = if (native_prepared) |prepared|
            .{ .native = prepared.receipt }
        else if (ordered_receipt) |entry|
            .{ .raft = .{ .term = entry.term, .index = entry.index } }
        else
            null;
        const native_payload = if (native_control) |control|
            if (control.mirror)
                if (native_prepared) |prepared| try replication_effects_mod.encodeNativeTopologyMutationRequestAlloc(self.alloc, control.request, prepared.receipt) else try replication_effects_mod.encodeBatchMutationRequestAlloc(self.alloc, control.request)
            else
                null
        else
            null;
        defer if (native_payload) |bytes| self.alloc.free(bytes);
        if (native_prepared == null or !native_prepared.?.duplicate) switch (command.action) {
            .begin => {
                if (command.graph_retirement) |scope| {
                    if (!scope.fence.eql(command.fence)) return error.InvalidBatchRequest;
                    const loaded = (try self.core.index_manager.graphRetirementConfigDigestAssumeCatalogLock(self.alloc)) orelse return error.InvalidBatchRequest;
                    if (!std.mem.eql(u8, &loaded, &scope.graph_config_digest)) return error.InvalidBatchRequest;
                }
                if (try topology.current(&txn) == null) {
                    if (command.fence.role == .split_destination) {
                        const previous_manifest = txn.get(@import("relational_integrity_handoff.zig").manifest_key) catch |err| switch (err) {
                            error.NotFound => null,
                            else => return err,
                        };
                        if (previous_manifest) |bytes| {
                            var previous = try std.json.parseFromSlice(@import("relational_integrity_handoff.zig").Manifest, self.alloc, bytes, .{});
                            defer previous.deinit();
                            if (!previous.value.destination.eql(command.fence)) return error.IntegrityHandoffDestinationResetRequired;
                        }
                    }
                    const enrichment = self.enrichmentStatsWithSupervisorState(.{ .enabled = true });
                    const has_producers = enrichment.enabled or self.core.hasGeneratedEnrichmentTargets() or self.core.index_manager.enrichments.items.len != 0 or self.hasConfiguredResolvers();
                    if (replication_lsn == null and has_producers) {
                        const target = self.currentMaintenanceTargetSequence();
                        if (enrichment.retrying or enrichment.worker_failed or enrichment.stalled or
                            ((enrichment.enabled or self.core.hasGeneratedEnrichmentTargets() or self.core.index_manager.enrichments.items.len != 0) and enrichment.applied_sequence < @max(target, enrichment.target_sequence))) return error.IntegrityTopologyBusy;
                        if (self.hasConfiguredResolvers()) {
                            const resolution = self.resolutionStageStats();
                            const promotion = self.promotionStageStats();
                            if (!resolution.enabled or !promotion.enabled or resolution.blocked or promotion.blocked or resolution.applied_sequence < target or promotion.applied_sequence < target) return error.IntegrityTopologyBusy;
                        }
                        // An old participant commit could enqueue a new
                        // primary-changing callback after this freeze. Drain
                        // those decisions before admitting a producer-bearing
                        // owner; ordinary producer-free tables may drain under
                        // the already-published fence without this restriction.
                        var manager = try self.core.initTxnManager();
                        defer manager.deinit();
                        if (try manager.hasTopologySensitiveTransactions()) return error.IntegrityTopologyBusy;
                    }
                }
                try topology.stageBeginWithHandoff(&txn, command.fence, command.generation_handoff);
                if (command.graph_retirement) |scope| {
                    try @import("graph_retirement_seal.zig").stageBegin(&txn, scope);
                    close_graph_after_commit = true;
                }
                if (command.fence.role == .child_generation_source or command.fence.role == .child_generation_dual)
                    try @import("relational_integrity_generation_admission.zig").stageSourceFencedReceipt(&txn, command.fence, if (receipt_entry) |entry| entry.term else 0, if (receipt_entry) |entry| entry.index else 0);
            },
            .seal_graph_retirement => {
                const scope = command.graph_retirement.?;
                if (!scope.fence.eql(command.fence)) return error.InvalidBatchRequest;
                if (!self.core.index_manager.graphRetirementPinsDrainedAssumeCatalogLock()) return error.StorageBusy;
                const loaded = (try self.core.index_manager.graphRetirementConfigDigestAssumeCatalogLock(self.alloc)) orelse return error.InvalidBatchRequest;
                if (!std.mem.eql(u8, &loaded, &scope.graph_config_digest)) return error.InvalidBatchRequest;
                _ = try @import("graph_retirement_seal.zig").stageSealPosition(&txn, scope, stamp orelse return error.InvalidBatchRequest);
            },
            .seal_generation_handoff => {
                try @import("empty_generation_handoff.zig").stageSealPosition(&txn, command.fence, command.generation_handoff_seal.?, stamp orelse return error.InvalidBatchRequest);
            },
            .install_generation_handoff => {
                if (command.fence.role != .rewrite_destination) return error.InvalidGenerationHandoff;
                const install_stamp = stamp orelse return error.InvalidBatchRequest;
                try install_stamp.requireNamespace(command.fence.namespace);
                const install = command.generation_handoff_install.?;
                const contract = @import("restore_staging_contract.zig");
                const logical = try @import("empty_generation_handoff.zig").installReceiptDigest(install);
                var expected_plan_id: [16]u8 = undefined;
                std.mem.writeInt(u64, expected_plan_id[0..8], command.fence.transition_id, .little);
                std.mem.writeInt(u64, expected_plan_id[8..16], command.fence.attempt, .little);
                const bootstrap_raw = txn.get(contract.bootstrap_key) catch return error.RestoreStagingScopeChanged;
                var bootstrap = try contract.OwnerBootstrap.decode(self.alloc, bootstrap_raw);
                defer bootstrap.deinit();
                const binding = bootstrap.value.empty_generation_handoff orelse return error.GenerationHandoffIntentMissing;
                const raw_progress = txn.get(contract.key) catch return error.RestoreStagingScopeChanged;
                var progress = try contract.Progress.decode(self.alloc, raw_progress);
                defer progress.deinit();
                if (!bootstrap.value.scope.target_namespace.eql(command.fence.namespace) or
                    !std.mem.eql(u8, &bootstrap.value.scope.plan_id, &expected_plan_id) or
                    !std.mem.eql(u8, &bootstrap.value.scope.digest(), &install.scope) or
                    !std.mem.eql(u8, &progress.value.scope.digest(), &install.scope) or
                    progress.value.phase != .validated or
                    !std.mem.eql(u8, &binding.source_summary_digest, &install.source_summary_digest) or
                    !std.mem.eql(u8, &binding.retired_digest, &install.retired_digest) or
                    binding.retired_count != install.retired_count or
                    !std.mem.eql(u8, &binding.expected_install_receipt_digest, &logical))
                    return error.RestoreStagingScopeChanged;
                _ = try @import("empty_generation_handoff.zig").stageInstallPosition(self.alloc, &txn, install, bootstrap.value.scope.plan_id, install_stamp);
            },
            .release => {
                if (command.fence.role == .child_generation_parent or command.fence.role == .child_generation_source or command.fence.role == .child_generation_dual or command.fence.role == .truncate_parent)
                    return error.GenerationAdmissionActivationRequired;
                if ((command.fence.role == .split_destination or command.fence.role == .merge_destination) and try topology.current(&txn) != null) {
                    var progress = try @import("relational_integrity_handoff.zig").loadProgress(self.alloc, &txn);
                    defer progress.deinit();
                    if (!progress.value.ready) return error.IntegrityHandoffIncomplete;
                    if (command.fence.role == .split_destination) {
                        const marker = (try self.core.loadSplitBootstrapMarker(self.alloc)) orelse return error.SplitBootstrapIncomplete;
                        if (!marker.bootstrap_complete or marker.transition_id != command.fence.transition_id or marker.attempt_epoch != command.fence.attempt) return error.SplitBootstrapIncomplete;
                    } else {
                        var state = try merge_state_mod.decodeAlloc(self.alloc, try txn.get(merge_state_mod.key));
                        defer state.deinit(self.alloc);
                        if (state.phase != .finalized or state.transition_id != command.fence.transition_id or state.donor_group_id != command.fence.peer_group_id) return error.MergeTransitionNotReady;
                    }
                    var compiled = try @import("relational_integrity_catalog.zig").decode(self.alloc, try txn.get(@import("relational_integrity_catalog.zig").key));
                    defer compiled.deinit();
                    try @import("relational_integrity_activation.zig").requireReady(&txn, compiled);
                } else if (command.fence.role != .backup_snapshot and try topology.current(&txn) != null) return error.IntegrityTopologyCutoverRequired;
                try topology.stageRelease(&txn, command.fence);
                if (command.fence.role == .merge_destination) {
                    try txn.delete(@import("relational_integrity_handoff.zig").manifest_key);
                    try txn.delete(@import("relational_integrity_handoff.zig").progress_key);
                    try txn.delete(@import("relational_integrity_handoff.zig").prune_key);
                }
            },
            .cancel => {
                // A merge receiver is already a published owner. Its imported
                // off-range records must be drained by rollback/prune before
                // admission resumes; generic cancellation is not that proof.
                if (command.fence.role == .merge_source or command.fence.role == .merge_destination) return error.InvalidBatchRequest;
                // A child-source fence protects the old FK generation while
                // parent owners transition. Only a metadata-authenticated
                // abort decision may lift it; generic cancellation could
                // admit a delayed old-generation attach after activation.
                if (command.fence.role == .child_generation_source) return error.GenerationAdmissionActivationRequired;
                if (command.fence.role == .child_generation_parent or command.fence.role == .child_generation_dual) {
                    const admission = @import("relational_integrity_generation_admission.zig");
                    const transitions = command.child_generations.?;
                    try admission.validateTransitions(transitions);
                    for (transitions) |transition| try admission.cancelTransition(self.alloc, &txn, transition);
                    try admission.stageCanceledReceipt(&txn, command.fence, transitions, if (receipt_entry) |entry| entry.term else 0, if (receipt_entry) |entry| entry.index else 0);
                }
                if (command.fence.role == .child_generation_dual)
                    try txn.delete(@import("relational_integrity_generation_admission.zig").dual_acknowledged_fence_key);
                try topology.stageCancel(&txn, command.fence);
                if (command.fence.role == .child_generation_dual) {
                    const encoded_fence = try command.fence.encode();
                    try txn.put(@import("relational_integrity_generation_admission.zig").dual_canceled_fence_key, &encoded_fence);
                }
                if (command.fence.role == .rewrite_source)
                    open_graph_after_commit = try @import("graph_retirement_seal.zig").stageCancel(&txn, command.fence);
            },
            .abort_transition => {
                if (command.fence.role == .merge_destination and try topology.current(&txn) != null) {
                    const active = (try topology.current(&txn)).?;
                    if (active.role != command.fence.role or active.transition_id != command.fence.transition_id or
                        active.peer_group_id != command.fence.peer_group_id or active.attempt > command.fence.attempt) return error.IntegrityTopologyChanged;
                    const handoff = @import("relational_integrity_handoff.zig");
                    // An ambiguously delivered begin with no imported proof
                    // can be canceled immediately. Once copying started,
                    // rollback must first restore the range and drain all
                    // off-owner integrity records under the same fence.
                    const manifest = txn.get(handoff.manifest_key) catch |err| switch (err) {
                        error.NotFound => null,
                        else => return err,
                    };
                    if (manifest != null) {
                        const raw_progress = txn.get(handoff.prune_key) catch |err| switch (err) {
                            error.NotFound => return error.IntegrityHandoffIncomplete,
                            else => return err,
                        };
                        var progress = try std.json.parseFromSlice(handoff.PruneProgress, self.alloc, raw_progress, .{});
                        defer progress.deinit();
                        if (!progress.value.complete or !progress.value.fence.eql((try topology.current(&txn)).?)) return error.IntegrityHandoffIncomplete;
                        try txn.delete(handoff.manifest_key);
                        try txn.delete(handoff.progress_key);
                        try txn.delete(handoff.prune_key);
                    }
                }
                try topology.stageAbortTransition(&txn, command.fence);
                if (command.fence.role == .rewrite_source)
                    open_graph_after_commit = try @import("graph_retirement_seal.zig").stageCancel(&txn, command.fence);
            },
            .transfer => {
                var manager = try self.core.initTxnManager();
                defer manager.deinit();
                try topology.requireDrained(&txn, &manager, command.fence);
                try @import("relational_integrity_handoff.zig").apply(self.alloc, &txn, command.fence, command.transfer.?);
            },
            .stage_parent_retirement => {
                var manager = try self.core.initTxnManager();
                defer manager.deinit();
                const stage = command.parent_retirement.?;
                try @import("relational_integrity_generation_retirement.zig").stagePending(self.alloc, &txn, &manager, command.fence, stage.plan_digest, stage.entries);
            },
            .activate_parent_retirement => {
                const retirement = @import("relational_integrity_generation_retirement.zig");
                const activation = command.parent_activation.?;
                if (command.fence.role != .truncate_parent or std.mem.allEqual(u8, &activation.plan_id, 0) or
                    !std.mem.eql(u8, &activation.publication_digest, &retirement.publicationDigest(activation.plan_id, activation.plan_digest)))
                    return error.InvalidGenerationRetirement;
                if (try topology.current(&txn)) |actual| {
                    if (!actual.eql(command.fence)) return error.IntegrityTopologyChanged;
                    if (!try retirement.completedActivation(&txn, command.fence, activation.plan_digest, activation.publication_digest)) {
                        if (try retirement.completedPending(&txn)) |prior| {
                            if (prior.fence.eql(command.fence)) return error.GenerationRetirementChanged;
                        }
                        var manager = try self.core.initTxnManager();
                        defer manager.deinit();
                        try topology.requireDrained(&txn, &manager, command.fence);
                        try retirement.stageVerifiedActivation(self.alloc, &txn, command.fence, activation.plan_id, activation.plan_digest, activation.publication_digest);
                    }
                } else {
                    const completed = (try topology.completed(&txn)) orelse return error.IntegrityTopologyFenceMissing;
                    if (!completed.eql(command.fence) or !try retirement.completedActivation(&txn, command.fence, activation.plan_digest, activation.publication_digest))
                        return error.GenerationRetirementChanged;
                }
            },
            .acknowledge_parent_retirement => {
                const retirement = @import("relational_integrity_generation_retirement.zig");
                const activation = command.parent_activation.?;
                if (command.fence.role != .truncate_parent or std.mem.allEqual(u8, &activation.plan_id, 0) or
                    !std.mem.eql(u8, &activation.publication_digest, &retirement.publicationDigest(activation.plan_id, activation.plan_digest)))
                    return error.InvalidGenerationRetirement;
                try retirement.stageAcknowledgement(&txn, command.fence, activation.plan_digest, activation.publication_digest);
            },
            .stage_child_generation => {
                if (command.fence.role != .child_generation_parent and command.fence.role != .child_generation_dual) return error.InvalidGenerationAdmission;
                var manager = try self.core.initTxnManager();
                defer manager.deinit();
                try topology.requireDrained(&txn, &manager, command.fence);
                const admission = @import("relational_integrity_generation_admission.zig");
                const transitions = command.child_generations.?;
                try admission.validateTransitions(transitions);
                for (transitions) |transition| try admission.stageTransition(self.alloc, &txn, transition);
                try admission.stageStagedReceipt(&txn, command.fence, transitions, if (receipt_entry) |entry| entry.term else 0, if (receipt_entry) |entry| entry.index else 0);
            },
            .activate_child_generation => {
                if (command.fence.role != .child_generation_parent and command.fence.role != .child_generation_dual) return error.InvalidGenerationAdmission;
                const admission = @import("relational_integrity_generation_admission.zig");
                const transitions = command.child_generations.?;
                try admission.validateTransitions(transitions);
                if (try topology.current(&txn)) |actual| {
                    if (!actual.eql(command.fence)) return error.IntegrityTopologyChanged;
                    var manager = try self.core.initTxnManager();
                    defer manager.deinit();
                    try topology.requireDrained(&txn, &manager, command.fence);
                    for (transitions) |transition| try admission.activateTransition(self.alloc, &txn, transition);
                    try @import("relational_integrity_generation_retirement.zig").stageChildGenerationRetirements(self.alloc, &txn, command.fence, transitions);
                    try admission.stageCompletion(&txn, command.fence, transitions, if (receipt_entry) |entry| entry.term else 0, if (receipt_entry) |entry| entry.index else 0);
                    // The same fence still protects the old child schema. A
                    // dual-role owner releases it only with the published
                    // schema/catalog install, never at parent activation.
                    if (command.fence.role != .child_generation_dual) try topology.stageRelease(&txn, command.fence);
                } else {
                    if (command.fence.role == .child_generation_dual) return error.IntegrityTopologyFenceMissing;
                    const completed = (try topology.completed(&txn)) orelse return error.IntegrityTopologyFenceMissing;
                    const expected = try admission.completionReceipt(command.fence, transitions);
                    const stored = txn.get(admission.activation_receipt_key) catch return error.GenerationAdmissionChanged;
                    const applied = try admission.AppliedReceipt.decode(stored);
                    if (!completed.eql(command.fence) or !std.mem.eql(u8, &applied.digest, &expected)) return error.GenerationAdmissionChanged;
                }
            },
            .acknowledge_child_generation => {
                if (command.fence.role != .child_generation_parent and command.fence.role != .child_generation_dual) return error.InvalidGenerationAdmission;
                try @import("relational_integrity_generation_admission.zig").stageAcknowledgement(&txn, command.fence, command.child_generations.?, if (receipt_entry) |entry| entry.term else 0, if (receipt_entry) |entry| entry.index else 0);
            },
            .cancel_child_generation_source => {
                if (command.fence.role != .child_generation_source and command.fence.role != .child_generation_dual) return error.InvalidGenerationAdmission;
                // The private owner route must independently read the durable
                // metadata canceling decision before proposing this command.
                // The source has no accepted-generation state to undo; the
                // exact fence receipt consumes its admission epoch forever.
                if (command.fence.role == .child_generation_dual) {
                    try @import("relational_integrity_generation_admission.zig").requireDualParentCanceled(&txn, command.fence);
                    try txn.delete(@import("relational_integrity_generation_admission.zig").dual_acknowledged_fence_key);
                    try txn.delete(@import("relational_integrity_generation_admission.zig").dual_canceled_fence_key);
                }
                try topology.stageCancel(&txn, command.fence);
                try @import("relational_integrity_generation_admission.zig").stageCanceledReceipt(&txn, command.fence, null, if (receipt_entry) |entry| entry.term else 0, if (receipt_entry) |entry| entry.index else 0);
            },
            .install_child_schema => unreachable, // Handled before generic topology transaction.
            .provision_initial_child, .release_initial_child, .cancel_initial_child => unreachable, // Handled before generic topology transaction.
            .prune => try @import("relational_integrity_handoff.zig").prune(self.alloc, &txn, command.fence, self.core.byteRange()),
        };
        if (ordered_receipt) |entry| {
            var marker_buf: [ordered_apply_receipt_value_len]u8 = undefined;
            const marker = orderedApplyReceiptWrite(entry, &marker_buf);
            try txn.put(marker.key, marker.value);
        }
        if (replication_lsn) |lsn| {
            var marker_buf: [replication_applied_lsn_value_len]u8 = undefined;
            const marker = replicationAppliedSequenceWrite(lsn, &marker_buf);
            try txn.put(marker.key, marker.value);
        }
        try self.stageRestoreStagingReplicationOutbox(&txn, native_payload orelse replication_payload);
        try txn.commit();
        if (close_graph_after_commit) self.core.index_manager.setGraphRetirementAdmissionAssumeCatalogLock(false);
        if (open_graph_after_commit) self.core.index_manager.setGraphRetirementAdmissionAssumeCatalogLock(true);
    }

    pub fn markTransactionParticipantResolved(self: *DB, txn_id: transactions_mod.TxnId, participant: []const u8) !void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        try self.core.markTransactionParticipantResolved(txn_id, participant);
    }

    pub fn markTransactionParticipantsResolved(self: *DB, txn_id: transactions_mod.TxnId, participants: []const []const u8) !void {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        try self.core.markTransactionParticipantsResolvedExtraBatch(txn_id, participants, .{});
    }

    pub fn markReplicatedTransactionParticipantResolvedAtOrderedReceipt(
        self: *DB,
        txn_id: transactions_mod.TxnId,
        participant: []const u8,
        identity: OrderedApplyReceipt,
    ) !void {
        lockApply(self);
        defer self.core.unlockApply();
        switch (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), identity)) {
            .already_applied => return,
            .apply => {},
        }
        var value_buf: [ordered_apply_receipt_value_len]u8 = undefined;
        const marker = orderedApplyReceiptWrite(identity, &value_buf);
        self.core.markTransactionParticipantResolvedExtraBatch(
            txn_id,
            participant,
            .{ .writes = &.{marker} },
        ) catch |err| switch (err) {
            transactions_mod.TxnError.TxnNotFound => try self.core.store.putBatch(&.{marker}, &.{}),
            else => return err,
        };
    }

    pub fn markReplicatedTransactionParticipantsResolvedAtOrderedReceipt(self: *DB, txn_id: transactions_mod.TxnId, participants: []const []const u8, identity: OrderedApplyReceipt) !void {
        lockApply(self);
        defer self.core.unlockApply();
        switch (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), identity)) {
            .already_applied => return,
            .apply => {},
        }
        var value_buf: [ordered_apply_receipt_value_len]u8 = undefined;
        const marker = orderedApplyReceiptWrite(identity, &value_buf);
        self.core.markTransactionParticipantsResolvedExtraBatch(
            txn_id,
            participants,
            .{ .writes = &.{marker} },
        ) catch |err| switch (err) {
            transactions_mod.TxnError.TxnNotFound => try self.core.store.putBatch(&.{marker}, &.{}),
            else => return err,
        };
    }

    pub fn cleanupTransactionMetadataIfEligible(
        self: *DB,
        txn_id: transactions_mod.TxnId,
        cutoff_timestamp: u64,
        retained_cutoff_timestamp: u64,
    ) !bool {
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        return try self.core.cleanupTransactionMetadataIfEligible(txn_id, cutoff_timestamp, retained_cutoff_timestamp);
    }

    pub fn cleanupReplicatedTransactionAtOrderedReceipt(
        self: *DB,
        txn_id: transactions_mod.TxnId,
        cutoff_timestamp: u64,
        retained_cutoff_timestamp: u64,
        identity: OrderedApplyReceipt,
    ) !bool {
        lockApply(self);
        defer self.core.unlockApply();
        switch (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), identity)) {
            .already_applied => return false,
            .apply => {},
        }
        var value_buf: [ordered_apply_receipt_value_len]u8 = undefined;
        const marker = orderedApplyReceiptWrite(identity, &value_buf);
        return try self.core.cleanupTransactionMetadataIfEligibleExtraBatch(
            txn_id,
            cutoff_timestamp,
            retained_cutoff_timestamp,
            .{ .writes = &.{marker} },
        );
    }

    pub fn getTransactionParticipants(self: *DB, alloc: Allocator, txn_id: transactions_mod.TxnId) ![][]u8 {
        return try self.core.getTransactionParticipants(alloc, txn_id);
    }

    pub fn getUnresolvedTransactionParticipants(self: *DB, alloc: Allocator, txn_id: transactions_mod.TxnId) ![][]u8 {
        return try self.core.getUnresolvedTransactionParticipants(alloc, txn_id);
    }

    pub fn recoverTransactions(self: *DB, cutoff_timestamp: u64, resolution_timestamp: u64) !transactions_mod.RecoveryStats {
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        const resolved_finalized = try self.resolveFinalizedTransactionIntentsForRecovery(resolution_timestamp);
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        var recovery_stats = try self.core.recoverTransactions(cutoff_timestamp, resolution_timestamp);
        recovery_stats.resolved_finalized += resolved_finalized;
        return recovery_stats;
    }

    fn resolveFinalizedTransactionIntentsForRecovery(self: *DB, resolution_timestamp: u64) !u64 {
        const txns = try self.core.listTransactions(self.alloc);
        defer self.alloc.free(txns);
        var resolved_finalized: u64 = 0;
        for (txns) |txn| {
            if (txn.status == .pending or
                (!(try self.core.transactionHasIntents(txn.txn_id)) and !(try self.core.transactionHasReplicationOutbox(txn.txn_id)))) continue;
            const resolve_version = if (txn.status == .committed and txn.commit_version != 0)
                txn.commit_version
            else
                resolution_timestamp;
            try self.resolveTransactionIntentsWithSyncLevel(txn.txn_id, txn.status, resolve_version, .propose);
            resolved_finalized += 1;
        }
        return resolved_finalized;
    }

    /// Physical graph reads retain the same admission, identity fence, and
    /// scan budget through selection and the owned result.
    pub fn graphEdgesForInternalReadBoundedAt(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        key: []const u8,
        edge_types: []const []const u8,
        direction: graph_mod.EdgeDirection,
        identity_read_generation: ?u64,
        ttl_now_ns: u64,
        max_edges: usize,
        max_owned_bytes: usize,
        max_scanned_rows: usize,
    ) !graph_mod.GraphIndex.BoundedEdgeResult {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRawRead();
        defer row_policy_lease.release();
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        try self.requireGraphEndpointCleanupReady();
        if (!self.core.index_manager.graphRetirementAdmissionOpen()) return error.IntegrityTopologyBusy;
        _ = try self.currentIdentityReadGenerationForRequest(identity_read_generation);
        const entry = self.core.graphIndex(index_name) orelse return error.IndexNotFound;
        const result = try entry.index.getEdgesByTypesBoundedWithStatsAt(alloc, key, edge_types, direction, max_edges, max_owned_bytes, max_scanned_rows, if (ttl_now_ns == 0) entry.index.clock.nowRealtimeNs() else ttl_now_ns);
        errdefer graph_mod.GraphIndex.freeEdges(alloc, result.edges);
        try row_policy_lease.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
        return result;
    }

    pub fn getEdges(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        key: []const u8,
        edge_type: []const u8,
        direction: graph_mod.EdgeDirection,
    ) ![]graph_mod.Edge {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRawRead();
        defer row_policy_lease.release();
        if (key.len == 0) return try alloc.alloc(graph_mod.Edge, 0);
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        try self.requireGraphEndpointCleanupReady();
        if (!self.core.index_manager.graphRetirementAdmissionOpen()) return error.IntegrityTopologyBusy;
        const edges = try self.core.graphGetEdges(alloc, index_name, key, edge_type, direction);
        errdefer graph_mod.GraphIndex.freeEdges(alloc, edges);
        try row_policy_lease.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
        return edges;
    }

    pub fn traverseEdges(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        start_key: []const u8,
        rules: traversal_mod.TraversalRules,
    ) ![]traversal_mod.TraversalResult {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRawRead();
        defer row_policy_lease.release();
        if (start_key.len == 0) return try alloc.alloc(traversal_mod.TraversalResult, 0);
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        try self.requireGraphEndpointCleanupReady();
        if (!self.core.index_manager.graphRetirementAdmissionOpen()) return error.IntegrityTopologyBusy;
        const results = try self.core.graphTraverseEdges(alloc, index_name, start_key, rules);
        errdefer traversal_mod.freeOwnedResults(alloc, results);
        try row_policy_lease.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
        return results;
    }

    pub fn getNeighbors(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        key: []const u8,
        edge_type: []const u8,
        direction: graph_mod.EdgeDirection,
    ) ![]traversal_mod.TraversalResult {
        var edge_types_storage: [1][]const u8 = undefined;
        const edge_types = if (edge_type.len > 0) blk: {
            edge_types_storage[0] = edge_type;
            break :blk edge_types_storage[0..1];
        } else &.{};
        return try self.traverseEdges(alloc, index_name, key, .{
            .edge_types = edge_types,
            .direction = direction,
            .max_depth = 1,
        });
    }

    pub fn findShortestPath(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        source: []const u8,
        target: []const u8,
        edge_types: []const []const u8,
        direction: graph_mod.EdgeDirection,
        weight_mode: paths_mod.PathWeightMode,
        max_depth: u32,
        min_weight: ?f64,
        max_weight: ?f64,
    ) !?paths_mod.Path {
        return self.findShortestPathWithOptions(alloc, index_name, source, target, .{
            .edge_types = edge_types,
            .direction = direction,
            .weight_mode = weight_mode,
            .max_depth = max_depth,
            .min_weight = min_weight,
            .max_weight = max_weight,
            .expand_cross_table_local = true,
        });
    }

    /// Options are borrowed for this synchronous call. Predicates and admission
    /// are evaluated before ranking; callers may share one work budget.
    pub fn findShortestPathWithOptions(self: *DB, alloc: Allocator, index_name: []const u8, source: []const u8, target: []const u8, options: paths_mod.PathFindOptions) !?paths_mod.Path {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        defer row_policy_lease.release();
        try options.edge_filter.validate(alloc);
        if (source.len == 0 or target.len == 0) return null;
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        try self.requireGraphEndpointCleanupReady();
        if (!self.core.index_manager.graphRetirementAdmissionOpen()) return error.IntegrityTopologyBusy;
        // Use the shortcut only when every semantic option has an equivalent
        // representation in its unqualified, default-clock execution plan.
        if (algebraicShortestPathOptionsSupported(options)) {
            if (try self.findAlgebraicShortestPath(alloc, index_name, source, target, options.edge_types, options.direction, options.weight_mode, options.max_depth, options.min_weight, options.max_weight)) |path| return path;
        }
        const entry = self.core.index_manager.graphIndex(index_name) orelse {
            try self.failIfIndexQuarantined(index_name);
            return error.IndexNotFound;
        };
        return paths_mod.findShortestPath(alloc, &entry.index, source, target, options);
    }

    pub fn findKShortestPaths(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        source: []const u8,
        target: []const u8,
        k: u32,
        edge_types: []const []const u8,
        direction: graph_mod.EdgeDirection,
        weight_mode: paths_mod.PathWeightMode,
        max_depth: u32,
        min_weight: ?f64,
        max_weight: ?f64,
    ) ![]paths_mod.Path {
        return self.findKShortestPathsWithOptions(alloc, index_name, source, target, k, .{
            .edge_types = edge_types,
            .direction = direction,
            .weight_mode = weight_mode,
            .max_depth = max_depth,
            .min_weight = min_weight,
            .max_weight = max_weight,
            .expand_cross_table_local = true,
        });
    }

    pub fn findKShortestPathsWithOptions(self: *DB, alloc: Allocator, index_name: []const u8, source: []const u8, target: []const u8, k: u32, options: paths_mod.PathFindOptions) ![]paths_mod.Path {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        defer row_policy_lease.release();
        try options.edge_filter.validate(alloc);
        if (source.len == 0 or target.len == 0 or k == 0) return alloc.alloc(paths_mod.Path, 0);
        if (k == 1) {
            if (try self.findShortestPathWithOptions(alloc, index_name, source, target, options)) |path| {
                errdefer paths_mod.freePath(alloc, path);
                const paths = try alloc.alloc(paths_mod.Path, 1);
                paths[0] = path;
                return paths;
            }
            return alloc.alloc(paths_mod.Path, 0);
        }
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        try self.requireGraphEndpointCleanupReady();
        if (!self.core.index_manager.graphRetirementAdmissionOpen()) return error.IntegrityTopologyBusy;
        const entry = self.core.index_manager.graphIndex(index_name) orelse {
            try self.failIfIndexQuarantined(index_name);
            return error.IndexNotFound;
        };
        return paths_mod.findKShortestPaths(alloc, &entry.index, source, target, k, options);
    }

    fn findAlgebraicShortestPath(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        source: []const u8,
        target: []const u8,
        edge_types: []const []const u8,
        direction: graph_mod.EdgeDirection,
        weight_mode: paths_mod.PathWeightMode,
        max_depth: u32,
        min_weight: ?f64,
        max_weight: ?f64,
    ) !?paths_mod.Path {
        const entry = self.core.index_manager.graphIndex(index_name) orelse {
            try self.failIfIndexQuarantined(index_name);
            return error.IndexNotFound;
        };
        const params = graph_query_mod.QueryParams{
            .edge_types = edge_types,
            .direction = direction,
            .max_depth = max_depth,
            .max_results = 0,
            .min_weight = min_weight,
            .max_weight = max_weight,
            .deduplicate = true,
            .include_paths = false,
            .weight_mode = weight_mode,
        };
        if (!(graph_query_mod.algebraicTraversalProof(&entry.index, params).safe())) return null;
        try self.proveGraphTraversalProgram(index_name, true);

        var graph_engine = graph_query_mod.GraphQueryEngine{ .alloc = alloc };
        var result = try graph_engine.execute(&entry.index, .{
            .query_type = .shortest_path,
            .index_name = index_name,
            .start_nodes = .{ .keys = &.{source} },
            .target_nodes = .{ .keys = &.{target} },
            .params = params,
        }, &.{source});
        defer result.deinit(alloc);
        if (result.nodes.len == 0) return null;
        return try graphResultNodePathAlloc(alloc, result.nodes[0]);
    }

    fn graphResultNodePathAlloc(alloc: Allocator, node: graph_query_mod.GraphResultNode) !?paths_mod.Path {
        const node_path = node.path orelse return null;
        const edge_path = node.path_edges orelse return null;
        const nodes = try alloc.alloc([]const u8, node_path.len);
        var initialized_nodes: usize = 0;
        errdefer {
            for (nodes[0..initialized_nodes]) |item| alloc.free(item);
            alloc.free(nodes);
        }
        for (node_path, 0..) |item, i| {
            nodes[i] = try alloc.dupe(u8, item);
            initialized_nodes += 1;
        }

        const edges = try alloc.alloc(paths_mod.PathEdge, edge_path.len);
        var initialized_edges: usize = 0;
        errdefer {
            for (edges[0..initialized_edges]) |edge| {
                alloc.free(edge.source);
                alloc.free(edge.target);
                alloc.free(edge.edge_type);
                if (edge.edge_id.len > 0) alloc.free(edge.edge_id);
                if (edge.owner_document.len > 0) alloc.free(edge.owner_document);
                if (edge.metadata.len > 0) alloc.free(edge.metadata);
            }
            alloc.free(edges);
        }
        for (edge_path, 0..) |item, i| {
            edges[i] = try paths_mod.clonePathEdge(alloc, item);
            initialized_edges += 1;
        }
        const total_weight = try paths_mod.sumPathEdgeWeights(edges);

        return .{
            .nodes = nodes,
            .edges = edges,
            .total_weight = total_weight,
            .length = @intCast(edges.len),
        };
    }

    pub fn matchPattern(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        start_keys: []const []const u8,
        pattern: []const graph_pattern_mod.PatternStep,
        max_results: u32,
        return_aliases: []const []const u8,
    ) ![]graph_pattern_mod.PatternMatch {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRawRead();
        defer row_policy_lease.release();
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        try self.requireGraphEndpointCleanupReady();
        if (!self.core.index_manager.graphRetirementAdmissionOpen()) return error.IntegrityTopologyBusy;
        var work_budget = graph_pattern_mod.WorkBudget.init(
            graph_pattern_mod.default_max_explored_nodes,
            graph_pattern_mod.default_max_explored_edges,
        );
        const matches = try self.matchPatternWithNodeAdmission(
            alloc,
            index_name,
            start_keys,
            pattern,
            max_results,
            return_aliases,
            &.{},
            false,
            true,
            null,
            &work_budget,
            .{},
        );
        errdefer graph_pattern_mod.freeMatches(alloc, matches);
        try row_policy_lease.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
        return matches;
    }

    fn matchPatternWithNodeAdmission(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        start_keys: []const []const u8,
        pattern: []const graph_pattern_mod.PatternStep,
        max_results: u32,
        return_aliases: []const []const u8,
        target_nodes: []const graph_node_identity.Ref,
        target_required: bool,
        include_paths: bool,
        node_admission: ?NodeAdmission,
        work_budget: *graph_pattern_mod.WorkBudget,
        scope: graph_query_mod.ExecutionScope,
    ) ![]graph_pattern_mod.PatternMatch {
        if (start_keys.len == 0) return try alloc.alloc(graph_pattern_mod.PatternMatch, 0);
        var filter_ctx = PatternNodeFilterContext.init(self, alloc);
        defer filter_ctx.deinit();
        return try self.core.graphMatchPattern(alloc, index_name, start_keys, pattern, .{
            .max_results = max_results,
            .return_aliases = return_aliases,
            .target_nodes = target_nodes,
            .target_required = target_required,
            .include_paths = include_paths,
            .evaluator = .{
                .ctx = &filter_ctx,
                .func = patternNodeFilterEvaluator,
            },
            .node_admission = node_admission,
            .work_budget = work_budget,
            .owning_table = scope.owning_table,
        });
    }

    fn matchConjunctivePatternWithNodeAdmission(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        start_keys: []const []const u8,
        pattern: graph_pattern_mod.ConjunctivePattern,
        max_results: u32,
        return_aliases: []const []const u8,
        node_admission: ?NodeAdmission,
        work_budget: *graph_pattern_mod.WorkBudget,
        scope: graph_query_mod.ExecutionScope,
    ) ![]graph_pattern_mod.PatternMatch {
        if (start_keys.len == 0) return try alloc.alloc(graph_pattern_mod.PatternMatch, 0);
        var filter_ctx = PatternNodeFilterContext.init(self, alloc);
        defer filter_ctx.deinit();
        return try self.core.graphMatchConjunctivePattern(alloc, index_name, start_keys, pattern, .{
            .max_results = max_results,
            .return_aliases = return_aliases,
            .include_paths = false,
            .evaluator = .{ .ctx = &filter_ctx, .func = patternNodeFilterEvaluator },
            .node_admission = node_admission,
            .work_budget = work_budget,
            .owning_table = scope.owning_table,
        });
    }

    fn aggregateConjunctivePatternWithNodeAdmission(
        self: *DB,
        alloc: Allocator,
        named: *const types.NamedGraphQuery,
        start_keys: []const []const u8,
        node_admission: ?NodeAdmission,
        budgets: db_query_graph.RequestGraphBudgets,
        scope: graph_query_mod.ExecutionScope,
    ) ![]types.GraphAggregateResult {
        if (start_keys.len == 0) {
            const empty = try alloc.alloc(types.GraphAggregateResult, named.query.aggregates.len);
            var initialized: usize = 0;
            errdefer {
                for (empty[0..initialized]) |*aggregate| aggregate.deinit(alloc);
                alloc.free(empty);
            }
            for (named.query.aggregates, 0..) |aggregate, i| {
                empty[i] = .{ .name = try alloc.dupe(u8, aggregate.name), .value = 0 };
                initialized += 1;
            }
            return empty;
        }
        const specs = try alloc.alloc(graph_pattern_mod.CountAggregateSpec, named.query.aggregates.len);
        defer alloc.free(specs);
        for (named.query.aggregates, 0..) |aggregate, i| specs[i] = .{
            .alias = if (std.mem.eql(u8, aggregate.of, "*")) null else aggregate.of,
            .distinct = aggregate.distinct,
        };

        var filter_ctx = PatternNodeFilterContext.init(self, alloc);
        defer filter_ctx.deinit();
        const computed = try self.core.graphAggregateConjunctivePattern(
            alloc,
            named.query.index_name,
            start_keys,
            named.query.match_pattern orelse return error.InvalidArgument,
            specs,
            .{
                .evaluator = .{ .ctx = &filter_ctx, .func = patternNodeFilterEvaluator },
                .node_admission = node_admission,
                .work_budget = budgets.work,
                .distinct_budget = budgets.distinct,
                .owning_table = scope.owning_table,
            },
        );
        defer {
            for (computed) |*aggregate| aggregate.deinit(alloc);
            if (computed.len > 0) alloc.free(computed);
        }
        const results = try alloc.alloc(types.GraphAggregateResult, computed.len);
        var initialized: usize = 0;
        errdefer {
            for (results[0..initialized]) |*result| result.deinit(alloc);
            if (results.len > 0) alloc.free(results);
        }
        for (computed, 0..) |*aggregate, i| {
            const name = try alloc.dupe(u8, named.query.aggregates[i].name);
            results[i] = .{
                .name = name,
                .value = aggregate.value,
                .distinct_values = aggregate.distinct_values,
            };
            aggregate.distinct_values = &.{};
            initialized += 1;
        }
        return results;
    }

    const PatternNodeFilterContext = struct {
        db: *DB,
        cache: db_query_graph.PreparedPatternFilterCache,

        fn init(db: *DB, alloc: Allocator) PatternNodeFilterContext {
            return .{
                .db = db,
                .cache = db_query_graph.PreparedPatternFilterCache.init(alloc),
            };
        }

        pub fn deinit(self: *PatternNodeFilterContext) void {
            self.cache.deinit();
            self.* = undefined;
        }
    };

    fn graphInputSetHitsAlloc(
        self: *DB,
        alloc: Allocator,
        hit_ids: []const []const u8,
        generation: ?u64,
    ) ![]types.SearchHit {
        const ordinals = try self.lookupLiveDocOrdinalsNoLock(alloc, hit_ids, generation);
        defer alloc.free(ordinals);

        const hits = try alloc.alloc(types.SearchHit, hit_ids.len);
        var initialized: usize = 0;
        errdefer {
            for (hits[0..initialized]) |*hit| hit.deinit(alloc);
            if (hits.len > 0) alloc.free(hits);
        }
        for (hit_ids, 0..) |hit_id, j| {
            hits[j] = .{
                .id = try alloc.dupe(u8, hit_id),
                .doc_ordinal = ordinals[j],
                .score = null,
                .stored_data = null,
                .chunk_hits = &.{},
            };
            initialized += 1;
        }
        return hits;
    }

    pub fn executeNamedGraphQueries(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
        graph_queries: []const types.NamedGraphQuery,
        input_sets: []const types.NamedGraphInputSet,
    ) ![]types.GraphSearchResult {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        defer row_policy_lease.release();
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        try self.requireGraphEndpointCleanupReady();
        if (!self.core.index_manager.graphRetirementAdmissionOpen()) return error.IntegrityTopologyBusy;
        if (req.identity_read_generation == null) {
            for (input_sets) |input_set| {
                if (input_set.hit_ids.len > 0) return error.UnsupportedQueryRequest;
            }
        }
        const snapshot_req = try self.searchRequestAtCurrentIdentityGeneration(req);

        var named_sets = try alloc.alloc(NamedResultSet, input_sets.len);
        defer alloc.free(named_sets);
        var temp_hits = try alloc.alloc([]types.SearchHit, input_sets.len);
        defer alloc.free(temp_hits);
        var resolved_sets = try alloc.alloc(?doc_set.ResolvedDocSet, input_sets.len);
        defer {
            for (resolved_sets) |*maybe_set| {
                if (maybe_set.*) |*set| set.deinit(alloc);
            }
            if (resolved_sets.len > 0) alloc.free(resolved_sets);
        }
        @memset(resolved_sets, null);
        var initialized_sets: usize = 0;

        for (input_sets, 0..) |input_set, i| {
            resolved_sets[i] = try self.resolveDocSetForIdsNoLockAtGenerationAlloc(alloc, input_set.hit_ids, snapshot_req.identity_read_generation);
            temp_hits[i] = try self.graphInputSetHitsAlloc(alloc, input_set.hit_ids, snapshot_req.identity_read_generation);
            const resolved_doc_set = if (resolved_sets[i]) |*set| set else null;
            named_sets[i] = .{
                .name = input_set.name,
                .hits = temp_hits[i],
                .total_hits = if (input_set.total_hits > 0) input_set.total_hits else @intCast(input_set.hit_ids.len),
                .resolved_doc_set = resolved_doc_set,
                .resolved_doc_set_complete = input_set.total_hits == 0 or @as(u64, input_set.total_hits) <= input_set.hit_ids.len,
            };
            initialized_sets += 1;
        }
        defer {
            for (temp_hits[0..initialized_sets]) |hits| {
                for (hits) |*hit| hit.deinit(alloc);
                if (hits.len > 0) alloc.free(hits);
            }
        }

        return try self.executeGraphQueriesWithSets(alloc, snapshot_req, graph_queries, named_sets);
    }

    const InstalledIndex = struct {
        applied: u64,
        needs_enrichment_replay: bool,
        managed_admission_pending: bool = false,
        post_commit_error: ?anyerror = null,
    };

    const IndexAdmissionMode = enum {
        ordinary,
        managed,
    };

    pub fn indexKindSupportsManagedGenerationRepair(kind: types.IndexKind) bool {
        return switch (kind) {
            .dense_vector, .sparse_vector, .graph, .full_text, .algebraic => true,
        };
    }

    const managed_index_admission_magic: u64 = 0x324d444154584449; // "IDXTADM2"
    const managed_index_admission_encoded_len = 48;
    const managed_catalog_admission_rebuild_reason = "managed_catalog_admission_rebuild";
    var test_fail_managed_index_delete_after_catalog_commit = false;
    var test_index_delete_after_worker_paused: ?*const fn (*DB) anyerror!void = null;
    var test_fail_managed_index_repair_cleanup_after_catalog_commit = false;
    var test_fail_index_activation_after_catalog_commit = false;
    var test_block_generated_artifact_finalization: std.atomic.Value(bool) = .init(false);
    var test_generated_artifact_finalization_entered: std.atomic.Value(bool) = .init(false);
    var test_release_generated_artifact_finalization: std.atomic.Value(bool) = .init(false);

    const IndexAdmissionDisposition = enum(u64) {
        activation_fence = 1,
        managed_rebuild = 2,
    };

    const ManagedIndexAdmissionMarker = struct {
        config_hash: u64,
        source_doc_count: u64,
        identity_generation: u64,
        replay_target_sequence: u64,
        disposition: IndexAdmissionDisposition = .managed_rebuild,
    };

    const ManagedAdmissionMaterializationTestHook = struct {
        ptr: *anyopaque,
        after_config_lookup: ?*const fn (*anyopaque, *DB, []const u8) void = null,
        after_pass: ?*const fn (*anyopaque, *DB) void = null,
    };

    var test_managed_admission_materialization_hook: ?ManagedAdmissionMaterializationTestHook = null;

    fn encodeManagedIndexAdmissionMarker(
        marker: ManagedIndexAdmissionMarker,
    ) [managed_index_admission_encoded_len]u8 {
        var out: [managed_index_admission_encoded_len]u8 = undefined;
        std.mem.writeInt(u64, out[0..8], managed_index_admission_magic, .little);
        std.mem.writeInt(u64, out[8..16], marker.config_hash, .little);
        std.mem.writeInt(u64, out[16..24], marker.source_doc_count, .little);
        std.mem.writeInt(u64, out[24..32], marker.identity_generation, .little);
        std.mem.writeInt(u64, out[32..40], marker.replay_target_sequence, .little);
        std.mem.writeInt(u64, out[40..48], @backingInt(marker.disposition), .little);
        return out;
    }

    fn decodeManagedIndexAdmissionMarker(raw: []const u8) !ManagedIndexAdmissionMarker {
        if (raw.len != managed_index_admission_encoded_len) return error.InvalidManagedIndexAdmission;
        if (std.mem.readInt(u64, raw[0..8], .little) != managed_index_admission_magic)
            return error.InvalidManagedIndexAdmission;
        const disposition = std.enums.fromInt(
            IndexAdmissionDisposition,
            std.mem.readInt(u64, raw[40..48], .little),
        ) orelse return error.InvalidManagedIndexAdmission;
        return .{
            .config_hash = std.mem.readInt(u64, raw[8..16], .little),
            .source_doc_count = std.mem.readInt(u64, raw[16..24], .little),
            .identity_generation = std.mem.readInt(u64, raw[24..32], .little),
            .replay_target_sequence = std.mem.readInt(u64, raw[32..40], .little),
            .disposition = disposition,
        };
    }

    fn managedAdmissionVisibilitySummary(self: *DB) !doc_identity.VisibilitySummary {
        // Admission is a rare structural mutation and must be based on the
        // primary store that commits the catalog marker. The runtime cache is
        // published only after hot-standby mirrors complete, so a mirror failure can
        // legitimately leave it behind the durable primary state.
        if (try doc_identity.visibilitySummaryFromStore(self.core.store)) |summary| return summary;
        const empty = (try doc_identity.loadAllNewTrustedStateForNamespace(
            self.core.store,
            self.core.identity_namespace,
        )) orelse return error.InvalidDocIdentity;
        return empty.visibility_summary;
    }

    fn externalCoverageHasStoredArtifacts(self: *DB, cfg: types.IndexConfig) !bool {
        if (cfg.kind != .dense_vector and cfg.kind != .sparse_vector) return false;
        const dense_names = if (cfg.kind == .dense_vector)
            try index_manager_mod.denseConfigArtifactNamesAlloc(self.alloc, cfg)
        else
            null;
        defer if (dense_names) |names| {
            for (names) |name| self.alloc.free(name);
            self.alloc.free(names);
        };
        const artifact_names: []const []const u8 = if (dense_names) |names| names else &.{cfg.name};
        const lower = try self.core.documentRangeLowerAlloc("");
        defer self.core.alloc.free(lower);

        const ScanState = struct {
            artifact_names: []const []const u8,
            found: bool = false,

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, _: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                for (state.artifact_names) |artifact_name| {
                    const matches = (internal_keys.isEmbeddingArtifactKey(key) and
                        internal_keys.matchesEmbeddingArtifactName(key, artifact_name)) or
                        (internal_keys.isDerivedEmbeddingArtifactKey(key) and
                            internal_keys.matchesDerivedEmbeddingArtifactName(key, artifact_name));
                    if (matches) {
                        state.found = true;
                        return .stop;
                    }
                }
                return .@"continue";
            }
        };
        var state = ScanState{ .artifact_names = artifact_names };
        try self.core.store.scanWithContext(lower, "", .{}, &state, ScanState.scanEntry);
        return state.found;
    }

    /// Artifact and resolver catalog changes alter the source's materialized
    /// state contract. REF3 retains primary-row and coordinated-integrity
    /// effects, not independently produced graph/vector/enrichment effects.
    /// Check after taking the apply lock, which serializes this observation
    /// with source admission and terminal release.
    fn requireOnlineArtifactCatalogMutableLocked(self: *DB, txn: anytype) !void {
        return self.requireOnlineArtifactCatalogMutableWithContextLocked(txn, null);
    }

    fn requireArtifactReconcileUnfenced(self: *DB, txn: anytype, context: ?@import("artifact_reconcile_intent.zig").Context) !void {
        if (context) |value| {
            try @import("artifact_reconcile_intent.zig").requireContext(self.alloc, txn, value);
            if (try @import("relational_integrity_topology.zig").current(txn) != null) return error.IntegrityTopologyBusy;
        } else try @import("relational_integrity_topology.zig").requireUnfenced(txn);
    }

    fn requireOnlineArtifactCatalogMutableWithContextLocked(self: *DB, txn: anytype, context: ?@import("artifact_reconcile_intent.zig").Context) !void {
        if (context) |value| try @import("artifact_reconcile_intent.zig").requireContext(self.alloc, txn, value) else try @import("artifact_reconcile_intent.zig").requireAbsent(txn);
        var namespace: [24]u8 = undefined;
        doc_identity.encodeNamespace(&namespace, self.core.identity_namespace);
        try @import("../source_pin_state.zig").requireNoPrepared(txn, namespace);
        if (try @import("../retained_effects.zig").load(txn)) |retention| {
            if (retention.active() and std.mem.eql(u8, &retention.namespace, &namespace))
                return error.IntegrityTopologyBusy;
        }
        // A receiver has no retained source record. Its immutable copy/tail
        // contract is instead owned by the durable merge checkpoint. This
        // also closes ordinary merge DDL races, without scanning any rows.
        const merge = @import("merge_state.zig");
        const merge_raw = txn.get(merge.key) catch |err| switch (err) {
            error.NotFound => txn.get(merge.legacy_key) catch |legacy_err| switch (legacy_err) {
                error.NotFound => null,
                else => return legacy_err,
            },
            else => return err,
        };
        if (merge_raw) |raw| {
            var state = try merge.decodeAlloc(self.alloc, raw);
            defer state.deinit(self.alloc);
            if (state.phase != .none and state.phase != .finalized and state.phase != .rolled_back)
                return error.IntegrityTopologyBusy;
        }
    }

    fn installIndexWhileEnrichmentQuiesced(
        self: *DB,
        cfg: types.IndexConfig,
        admission_mode: IndexAdmissionMode,
    ) !InstalledIndex {
        return self.installIndexForReconciliation(cfg, admission_mode, null);
    }

    /// Field-derived edges are part of prepared document effects. Preserve
    /// their catalog until durable prepares resolve, including prepares made
    /// while no graph index existed. Schema leases already survive recovery.
    fn requireGraphCatalogMutableForTransactions(self: *DB) !void {
        var manager = try self.core.initTxnManager();
        defer manager.deinit();
        if (try manager.hasSchemaLeases()) return error.SchemaInUse;
    }

    fn installIndexForReconciliation(self: *DB, cfg: types.IndexConfig, admission_mode: IndexAdmissionMode, context: ?@import("artifact_reconcile_intent.zig").Context) !InstalledIndex {
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        {
            var read = try self.core.store.beginProbeTxn();
            defer read.abort();
            try self.requireArtifactReconcileUnfenced(&read, context);
            try self.requireOnlineArtifactCatalogMutableWithContextLocked(&read, context);
        }
        if (cfg.kind == .graph or self.core.index_manager.graphIndex(cfg.name) != null)
            try self.requireGraphCatalogMutableForTransactions();
        if (admission_mode == .managed and !indexKindSupportsManagedGenerationRepair(cfg.kind))
            return error.UnsupportedOperation;
        try self.removeOrphanedIndexRepairIntentForFreshAdmission(self.alloc, cfg.name);
        const summary = try self.managedAdmissionVisibilitySummary();
        const externally_populated = try index_manager_mod.configUsesExternalCoverage(self.alloc, cfg);
        const external_artifacts_exist = externally_populated and
            try self.externalCoverageHasStoredArtifacts(cfg);
        const disposition: IndexAdmissionDisposition = if (admission_mode == .managed and
            summary.live_ordinals != 0 and
            (!externally_populated or external_artifacts_exist))
            .managed_rebuild
        else
            .activation_fence;
        const admission_key = try internal_keys.managedIndexAdmissionKeyAlloc(self.alloc, cfg.name);
        defer self.alloc.free(admission_key);
        const admission_value = encodeManagedIndexAdmissionMarker(.{
            .config_hash = types.indexConfigHash(cfg),
            .source_doc_count = summary.live_ordinals,
            .identity_generation = @max(summary.max_created_generation, summary.max_deleted_generation),
            .replay_target_sequence = self.core.nextDerivedSequence(),
            .disposition = disposition,
        });
        const admission_write: index_manager_mod.IndexManager.AtomicCatalogMutation = .{ .put = .{
            .key = admission_key,
            .value = &admission_value,
        } };
        var catalog_committed = false;
        // Allocate the service gate before committing admission. Once the
        // catalog and marker become durable, allocation failure must not
        // create an ungated window in the current process.
        try self.core.index_manager.markUnscopedRepairUnavailable(cfg.name);
        errdefer if (!catalog_committed) {
            self.core.index_manager.clearUnscopedRepairUnavailable(cfg.name);
        };

        // Managed empty-source and proven-empty external admissions bypass
        // ordinary synchronous backfill. Source identity proves the former;
        // a streaming artifact-key probe proves the latter. Both start clean
        // at the current replay head.
        var applied = switch (admission_mode) {
            .ordinary => try self.core.addIndex(cfg, admission_write),
            .managed => try self.core.addManagedIndex(cfg, admission_write),
        };
        catalog_committed = true;
        var post_commit_error: ?anyerror = if (builtin.is_test and test_fail_index_activation_after_catalog_commit)
            error.TestPostCommitIndexActivation
        else
            null;
        if (admission_mode == .managed and disposition == .activation_fence) {
            applied = self.core.nextDerivedSequence();
        }
        if (post_commit_error == null) {
            self.core.saveAppliedSequence(cfg.name, applied) catch |err| {
                post_commit_error = err;
            };
        }
        if (post_commit_error == null) {
            self.initializeDenseArtifactTargetCounterForAdmission(cfg, disposition) catch |err| {
                post_commit_error = err;
            };
        }
        if (post_commit_error == null and
            disposition == .managed_rebuild and
            cfg.kind == .dense_vector)
        {
            // The empty canonical generation is a valid progressive build
            // target, but it is not a completed projection of this non-empty
            // source. Arm the native stable-tip lifecycle before enrichment
            // can publish its first replay window. Leaving this checkpoint
            // clean at sequence zero strands exact-vector publication: native
            // postings can advance while no owner is permitted to publish the
            // matching vector generation or its status compatibility mirror.
            if (self.core.loadProjectionCheckpoint(self.alloc, cfg.name)) |current| {
                self.core.saveProjectionCheckpoint(cfg.name, .{
                    .applied_sequence = current.applied_sequence,
                    .status = .rebuilding,
                    .generation = current.generation,
                    .config_hash = types.indexConfigHash(cfg),
                    .published_count = current.published_count,
                }) catch |err| {
                    post_commit_error = err;
                };
            } else |err| post_commit_error = err;
        }
        if (post_commit_error == null) {
            saveIndexStatusSnapshots(self.alloc, self.core.store, self.core.index_manager, &[_]apply_state.AppliedSequenceUpdate{.{
                .index_name = cfg.name,
                .sequence = applied,
            }}) catch |err| {
                post_commit_error = err;
            };
        }
        if (cfg.kind == .algebraic) {
            self.hydrateAlgebraicObservationStatusForIndexBestEffort(cfg.name);
        }
        var needs_enrichment_replay = false;
        if (post_commit_error == null) {
            needs_enrichment_replay = self.core.indexRequiresEnrichmentReplay(cfg.name) catch |err| blk: {
                post_commit_error = err;
                break :blk false;
            };
        }
        return .{
            .applied = applied,
            .needs_enrichment_replay = needs_enrichment_replay,
            .managed_admission_pending = disposition == .managed_rebuild,
            .post_commit_error = post_commit_error,
        };
    }

    fn restartEnrichmentAfterStructuralMutation(self: *DB, operation: []const u8, index_name: []const u8) !void {
        self.async_context.enrichment_desired_running.store(true, .release);
        lockAtomicWithBackoff(&self.async_context.enrichment_lifecycle_mutex);
        const runtime = self.async_context.enrichment_runtime orelse {
            self.async_context.enrichment_lifecycle_mutex.unlock();
            return;
        };
        const start_result = if (!runtime.isStarted()) startEnrichmentRuntimeForLifecycle(runtime) else {};
        self.async_context.enrichment_lifecycle_mutex.unlock();
        start_result catch |err| {
            // The durable restart supervisor owns recovery from this point;
            // preserve the diagnostic without classifying a retryable outage
            // as an unrecoverable process failure.
            std.log.warn("failed to restart enrichment runtime after {s} index={s} err={s}", .{ operation, index_name, @errorName(err) });
            scheduleEnrichmentRestartContext(
                self.async_context,
                self.backend_runtime.durable_jobs,
                self.repair_cleanup_owner_id,
            );
            notifyQueryVisibilityHook(self.async_context, .status);
            return err;
        };
    }

    fn finalizeCompletedIndexAdmission(self: *DB, index_name: []const u8) !void {
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        const key = try internal_keys.managedIndexAdmissionKeyAlloc(self.alloc, index_name);
        defer self.alloc.free(key);
        try self.finalizeCompletedIndexAdmissionLocked(index_name, key);
    }

    /// Requires the DB apply lock.
    fn finalizeCompletedIndexAdmissionLocked(self: *DB, index_name: []const u8, key: []const u8) !void {
        self.core.store.delete(key) catch |err| switch (err) {
            error.NotFound => {},
            else => return err,
        };
        self.core.index_manager.clearManagedAdmissionSnapshotForIndex(index_name);
        self.core.index_manager.clearUnscopedRepairUnavailable(index_name);
        // The managed-admission marker is the durable control record for an
        // initial materialization, not corruption debt. Preserve that class
        // on the clear edge just as the repair-intent path does. Leaving the
        // default `.repair` here makes the serving layer interpret successful
        // activation as a new corruption boundary and re-fence the exact
        // incarnation it has just acknowledged.
        notifyQueryVisibilityEvent(self.async_context, .{
            .change = .index_repair_cleared,
            .repair = .{
                .index_name = index_name,
                .work_class = .initial_build,
                .previous_admission = .blocked,
                .admission = .serviceable,
            },
        });
    }

    fn recoverCommittedIndexAdmission(self: *DB, cfg: types.IndexConfig, activation_err: anyerror) !?u128 {
        // Admission remains fail-closed until the durable repair marker is
        // materialized, so this is degraded-but-recoverable state.
        std.log.warn("index catalog admission committed with pending activation index={s} err={s}", .{ cfg.name, @errorName(activation_err) });
        self.requestManagedAdmissionMaterialization();
        self.drainManagedIndexAdmissionsUnderStructuralGuard(self.alloc) catch |materialize_err| {
            // The primary-store marker remains authoritative and startup will
            // retry projection into the repair scheduler.
            std.log.err("committed index activation marker remains pending index={s} err={s}", .{ cfg.name, @errorName(materialize_err) });
            return null;
        };
        const repair_id = self.indexRepairIdForIndex(self.alloc, cfg.name) catch |lookup_err| {
            std.log.err("committed index activation repair lookup failed index={s} err={s}", .{ cfg.name, @errorName(lookup_err) });
            return null;
        };
        return repair_id;
    }

    fn completeInstalledIndexAdmission(
        self: *DB,
        cfg: types.IndexConfig,
        installed: InstalledIndex,
        restart_enrichment: bool,
    ) !?u128 {
        var worker_applied = installed.applied;
        if (installed.needs_enrichment_replay) {
            if (!installed.managed_admission_pending) {
                // Ordinary admission can seed its serving generation directly
                // from retained artifacts before the worker begins replay.
                const rebuilt = switch (cfg.kind) {
                    .dense_vector => try rebuildDenseIndexForTargetCoverageContext(self.async_context, cfg.name, 2048),
                    .sparse_vector => try rebuildSparseIndexFromStoredEmbeddingArtifactsContext(self.async_context, cfg.name, 2048),
                    else => 0,
                };
                const generation_baseline = self.core.nextDerivedSequence();
                if (rebuilt > 0 or generation_baseline > worker_applied) {
                    worker_applied = generation_baseline;
                    try self.core.saveAppliedSequence(cfg.name, worker_applied);
                    try saveIndexStatusSnapshots(self.alloc, self.core.store, self.core.index_manager, &[_]apply_state.AppliedSequenceUpdate{.{
                        .index_name = cfg.name,
                        .sequence = worker_applied,
                    }});
                }
            }
            if (self.enrichment_runtime != null and !installed.managed_admission_pending) {
                // Ordinary embedded admission retains its synchronous
                // readiness contract. Managed admission persists a repair
                // intent below; that owner pages source-document replay after
                // the write-capability barrier is released, so DDL remains
                // O(groups) rather than O(corpus).
                const refs = try self.replayGeneratedEnrichmentsFromStoredDocs(self.alloc);
                if (refs == 0) {
                    const target_sequence = self.core.nextDerivedSequence();
                    try self.core.saveAppliedSequence(cfg.name, target_sequence);
                    try self.markEnrichmentAppliedIfNoPendingThrough(target_sequence);
                }
            }
        }

        const repair_id = if (installed.managed_admission_pending) repair_blk: {
            // Project the admission marker into a durable repair intent before
            // releasing structural ownership. For generated indexes the same
            // intent owns resumable source replay and advances its producer
            // fence page by page before shadow construction can begin.
            self.requestManagedAdmissionMaterialization();
            // Drain the complete outbox, not only this index. A prior admission
            // may have committed before a transient checkpoint failure.
            try self.drainManagedIndexAdmissionsUnderStructuralGuard(self.alloc);
            break :repair_blk try self.indexRepairIdForIndex(self.alloc, cfg.name);
        } else null;

        // A managed admission with the durable repair scheduler enabled is
        // completed by its shadow generation. Starting the canonical worker
        // here makes it finalize HBC once per producer window while competing
        // with artifact production, even though that generation will be
        // discarded. Install the worker at the shadow activation fence above.
        const defer_worker_to_managed_repair = installed.managed_admission_pending and
            self.local_execution.optional_runtime_workers_enabled and
            try types.indexPublicationPolicy(self.alloc, cfg) == .atomic;
        if (self.start_index_workers and !defer_worker_to_managed_repair) {
            try self.executor.addWorker(cfg.name, .{ .name = cfg.name, .kind = cfg.kind }, worker_applied);
        }
        if (restart_enrichment) try self.restartEnrichmentAfterStructuralMutation("index creation", cfg.name);
        if (self.start_index_workers and !defer_worker_to_managed_repair) {
            const current_target = self.core.nextDerivedSequence();
            if (current_target > worker_applied) self.executor.notifyIndexes(current_target, &.{cfg.name});
        }
        if (!installed.managed_admission_pending) try self.finalizeCompletedIndexAdmission(cfg.name);
        return repair_id;
    }

    fn addIndexWithAdmission(self: *DB, cfg: types.IndexConfig, admission_mode: IndexAdmissionMode) !?u128 {
        return self.addIndexForReconciliation(cfg, admission_mode, null);
    }

    fn addIndexForReconciliation(self: *DB, cfg: types.IndexConfig, admission_mode: IndexAdmissionMode, context: ?@import("artifact_reconcile_intent.zig").Context) !?u128 {
        if (self.local_execution.row_policy_gate.currentPhase() != .disabled) return error.RowPolicyUnsupported;
        var row_policy_lease = self.local_execution.row_policy_gate.enterRaw() catch return error.RowPolicyUnsupported;
        defer row_policy_lease.release();
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        if (context == null) try self.enforceReplicationWriteGate();
        var structural_guard = self.beginIndexStructuralMutation("index creation", cfg.name);
        defer structural_guard.deinit();
        {
            lockApplyShared(self);
            defer self.core.unlockApplyShared();
            var probe = try self.core.store.beginReadTxn();
            defer probe.abort();
            try self.requireArtifactReconcileUnfenced(&probe, context);
        }
        try self.enforceVectorMigrationConfigurationGate();
        // Generated artifact namespaces can be shared across differently named
        // indexes. Cleanup is durable and owner-driven; never turn index
        // admission into an unbounded corpus scan. Metadata reconciliation can
        // retry after the conflicting generation's tombstone is retired.
        try self.rejectConflictingRetiredIndexCleanupForAdmission(cfg);
        const restart_enrichment = self.quiesceEnrichmentForStructuralMutation();
        var enrichment_restarted = false;
        errdefer if (restart_enrichment and !enrichment_restarted) {
            self.restartEnrichmentAfterStructuralMutation("failed index creation", cfg.name) catch |restart_err| {
                std.log.err("failed to restore enrichment runtime after index creation error index={s} err={s}", .{ cfg.name, @errorName(restart_err) });
            };
        };
        const installed = try self.installIndexForReconciliation(cfg, admission_mode, context);
        if (installed.post_commit_error) |activation_err| {
            if (restart_enrichment) self.restartEnrichmentAfterStructuralMutation("pending index activation", cfg.name) catch {};
            enrichment_restarted = true;
            return try self.recoverCommittedIndexAdmission(cfg, activation_err);
        }

        const repair_id = self.completeInstalledIndexAdmission(cfg, installed, restart_enrichment) catch |activation_err| {
            if (restart_enrichment) self.restartEnrichmentAfterStructuralMutation("pending index activation", cfg.name) catch {};
            enrichment_restarted = true;
            return try self.recoverCommittedIndexAdmission(cfg, activation_err);
        };
        enrichment_restarted = true;
        return repair_id;
    }

    pub fn addIndex(self: *DB, cfg: types.IndexConfig) !void {
        _ = try self.addIndexWithAdmission(cfg, .ordinary);
    }

    /// Managed table reconciliation uses a crash-consistent catalog/outbox
    /// admission backed by shadow generation repair for every index kind.
    /// Corpus reconstruction remains asynchronous and bounded by the
    /// owner-side generation repair scheduler, while replay records writes
    /// after the admission fence.
    pub fn admitManagedIndex(self: *DB, cfg: types.IndexConfig) !?u128 {
        return try self.addIndexWithAdmission(cfg, .managed);
    }

    /// Compatibility wrapper for callers that specifically admit full-text
    /// indexes. New managed-table code should use admitManagedIndex.
    pub fn admitManagedFullTextIndex(self: *DB, cfg: types.IndexConfig) !?u128 {
        if (cfg.kind != .full_text) return error.InvalidArgument;
        return try self.admitManagedIndex(cfg);
    }

    /// VOPR-only preparation seam for a committed managed catalog admission
    /// whose durable outbox has not yet been materialized. This exposes the
    /// same crash boundary used by production recovery without pausing while
    /// an apply or structural lock is held.
    pub fn prepareManagedIndexAdmissionForVopr(self: *DB, cfg: types.IndexConfig) !void {
        if (!builtin.is_test) return error.VoprTestSeamUnavailable;
        const installed = try self.installIndexWhileEnrichmentQuiesced(cfg, .managed);
        if (!installed.managed_admission_pending) return error.InvalidManagedIndexAdmission;
    }

    pub fn addEnrichment(self: *DB, cfg: types.EnrichmentConfig) !void {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        {
            var probe = try self.core.store.beginProbeTxn();
            defer probe.abort();
            try self.requireOnlineArtifactCatalogMutableLocked(&probe);
        }
        try self.enforceVectorMigrationConfigurationGate();
        try self.enforceReplicationWriteGate();
        try self.core.addEnrichment(cfg);
    }

    pub fn upsertEnrichment(self: *DB, cfg: types.EnrichmentConfig) !index_manager_mod.IndexManager.EnrichmentUpsertResult {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        {
            var probe = try self.core.store.beginProbeTxn();
            defer probe.abort();
            try self.requireOnlineArtifactCatalogMutableLocked(&probe);
        }
        try self.enforceVectorMigrationConfigurationGate();
        try self.enforceReplicationWriteGate();
        return try self.core.upsertEnrichment(cfg);
    }

    const ResolverCatalogActivity = struct {
        resolution: ?*std.atomic.Mutex,
        promotion: ?*std.atomic.Mutex,

        pub fn deinit(self: *@This()) void {
            if (self.promotion) |mutex| mutex.unlock();
            if (self.resolution) |mutex| mutex.unlock();
        }
    };

    fn acquireResolverCatalogActivity(self: *DB, wait: bool) !ResolverCatalogActivity {
        const resolution = if (self.resolution_runtime) |runtime| &runtime.catch_up_mutex else null;
        const promotion = if (self.promotion_runtime) |runtime| &runtime.catch_up_mutex else null;
        while (true) {
            if (resolution == null or resolution.?.tryLock()) {
                if (promotion == null or promotion.?.tryLock())
                    return .{ .resolution = resolution, .promotion = promotion };
                if (resolution) |mutex| mutex.unlock();
            }
            // Managed refresh/apply callers hold a group activity. They must
            // release it so a worker already inside a Raft callback can finish.
            if (!wait) return error.WriterLocked;
            const io = self.backend_runtime.controlIo() orelse self.backend_runtime.io() orelse
                return error.BackendRuntimeIoUnavailable;
            try io.sleep(.fromMilliseconds(1), .awake);
        }
    }

    pub fn addResolver(self: *DB, cfg: index_manager_mod.ResolverConfig) !void {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        {
            var activity = try self.acquireResolverCatalogActivity(true);
            defer activity.deinit();
            try self.lockApplyForPortableRuntime();
            defer self.core.unlockApply();
            {
                var probe = try self.core.store.beginProbeTxn();
                defer probe.abort();
                try self.requireOnlineArtifactCatalogMutableLocked(&probe);
            }
            try self.core.addResolver(cfg);
            if (self.resolution_runtime) |runtime| runtime.notifyBackfill();
        }
        try self.startResolverReplayRuntimes();
        try self.backfillResolverCorpus();
    }

    pub const ResolverUpsertOptions = struct {
        /// When false, persist the catalog mutation and mark the resolver backlog
        /// dirty, but leave execution to the resolver worker. Admission is
        /// nonblocking: a refresh holding a group activity must not wait for
        /// in-flight resolution or promotion callbacks.
        drain_backfill: bool = true,
    };

    /// Add or replace a resolver. Inserts and material config changes re-resolve
    /// the existing corpus so the new resolver/scorer behavior applies to
    /// documents already ingested (the extraction artifacts did not change, so
    /// the incremental hint would not fire on its own).
    pub fn upsertResolverWithResultOptions(
        self: *DB,
        cfg: index_manager_mod.ResolverConfig,
        options: ResolverUpsertOptions,
    ) !index_manager_mod.IndexManager.ResolverUpsertResult {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        const upsert_result = blk: {
            try cfg.validate();
            // An unchanged catalog observation does not mutate resolver state.
            // Do not wait for distributed callbacks, rewrite the catalog, or
            // retire a serving owner just because replay is currently active.
            if (self.core.index_manager.resolverConfigMatches(cfg)) break :blk .updated_no_backfill;
            var activity = try self.acquireResolverCatalogActivity(options.drain_backfill);
            defer activity.deinit();
            try self.lockApplyForPortableRuntime();
            defer self.core.unlockApply();
            {
                var probe = try self.core.store.beginProbeTxn();
                defer probe.abort();
                try self.requireOnlineArtifactCatalogMutableLocked(&probe);
            }
            const result = try self.core.upsertResolver(cfg);
            if (result != .updated_no_backfill) {
                if (self.resolution_runtime) |runtime| runtime.notifyBackfill();
            }
            break :blk result;
        };
        switch (upsert_result) {
            .inserted, .updated_backfill_required => {
                try self.startResolverReplayRuntimes();
                if (options.drain_backfill) {
                    try self.backfillResolverCorpus();
                }
            },
            .updated_no_backfill => {
                try self.startResolverReplayRuntimesIfConfigured();
                if (options.drain_backfill and self.resolution_runtime != null) {
                    const runtime = self.resolution_runtime.?;
                    if (try runtime.hasReresolveBacklog()) {
                        try self.backfillResolverCorpus();
                    } else {
                        // The worker may have cleared the enqueue cursor while
                        // the resulting replay and downstream work is pending.
                        try self.runUntilIdle();
                    }
                }
            },
        }
        return upsert_result;
    }

    pub fn upsertResolverWithResult(self: *DB, cfg: index_manager_mod.ResolverConfig) !index_manager_mod.IndexManager.ResolverUpsertResult {
        return try self.upsertResolverWithResultOptions(cfg, .{});
    }

    pub fn upsertResolver(self: *DB, cfg: index_manager_mod.ResolverConfig) !void {
        _ = try self.upsertResolverWithResult(cfg);
    }

    pub fn drainResolverBackfill(self: *DB) !void {
        try self.startResolverReplayRuntimesIfConfigured();
        try self.backfillResolverCorpus();
    }

    fn backfillResolverCorpus(self: *DB) !void {
        if (!self.hasConfiguredResolvers()) return;
        if (self.resolution_runtime) |runtime| {
            try runtime.requestReresolveBacklog();
            while (true) {
                var tick = try runtime.runReresolveBacklogWindow();
                const queued = tick.queued;
                const complete = tick.complete;
                tick.deinit(self.runtime_alloc);
                // Drive the enqueued extraction artifacts through resolution,
                // promotion, and graph materialization before queuing more.
                if (queued > 0) try self.runUntilIdle();
                if (complete) break;
            }
            // A background window may have enqueued the final records, so this
            // caller's last window can report complete with zero queued work.
            // Synchronous backfill promises applied output, not just an empty
            // corpus cursor; drain the shared replay target before returning.
            try self.runUntilIdle();
        }
    }

    pub fn removeResolver(self: *DB, name: []const u8) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        try self.enforceReplicationWriteGate();
        while (true) {
            try self.retireResolverReplayBeforeCatalogRemoval();
            return self.removeResolverWithoutDrain(name) catch |err| {
                if (err != error.WriterLocked) return err;
                if (self.backend_runtime.controlIo() orelse self.backend_runtime.io()) |io|
                    try io.sleep(.fromMilliseconds(1), .awake);
                continue;
            };
        }
    }

    pub fn removeResolverWithoutDrain(self: *DB, name: []const u8) !bool {
        return self.removeResolverForReconciliation(name, null);
    }

    fn removeResolverForReconciliation(self: *DB, name: []const u8, context: ?@import("artifact_reconcile_intent.zig").Context) !bool {
        if (context) |authority| return self.removeResolverReconciliationPage(name, authority);
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        if (context == null) try self.enforceReplicationWriteGate();
        {
            var activity = try self.acquireResolverCatalogActivity(false);
            defer activity.deinit();
            // No resolver can be removed while an old decision or promotion is
            // in flight. Wake the existing owner and retry on a later refresh.
            const promotion_ready = if (self.promotion_runtime) |runtime|
                runtime.retirementReadinessLocked() != .pending
            else blk: {
                const persisted = self.promotionStageStats();
                break :blk !persisted.catch_up_required and !persisted.blocked;
            };
            if (self.resolutionStageStats().catch_up_required or !promotion_ready)
                return error.WriterLocked;
            try self.lockApplyForPortableRuntime();
            defer self.core.unlockApply();
            {
                var probe = try self.core.store.beginProbeTxn();
                defer probe.abort();
                try self.requireOnlineArtifactCatalogMutableWithContextLocked(&probe, context);
            }
            const cfg = (try self.resolverConfigByNameAlloc(name)) orelse return false;
            defer {
                var owned = cfg;
                owned.deinit(self.alloc);
            }
            if (try self.retireResolverArtifactsLocked(cfg)) |sequence| {
                notifyQueryVisibilityTargetAdvanced(self.async_context, sequence);
                self.executor.notifySequence(sequence);
                self.notifyResolverReplayRuntimesForced(sequence);
                return error.WriterLocked;
            }
            // Graph replay still needs the resolver contract to interpret
            // retirement records, including records whose artifact is absent.
            // Its persisted/live watermark also makes this safe after reopen.
            for (self.core.index_manager.graph_indexes.items) |entry| {
                const applied = try self.managedIndexAppliedSequence(self.alloc, entry.config.name);
                const target = try self.managedIndexReplayTargetSequence(self.alloc, entry.config.name, .graph, applied);
                if (applied < target)
                    return error.WriterLocked;
            }
            if (!try self.core.removeResolver(name)) return false;
        }
        self.stopResolverReplayRuntimesIfUnconfigured();
        return true;
    }

    fn resolverConfigByNameAlloc(self: *DB, name: []const u8) !?index_manager_mod.ResolverConfig {
        const resolvers = try self.core.listResolvers(self.alloc);
        defer {
            for (resolvers) |*cfg| cfg.deinit(self.alloc);
            if (resolvers.len > 0) self.alloc.free(resolvers);
        }
        for (resolvers) |cfg| {
            if (std.mem.eql(u8, cfg.name, name)) {
                return try index_manager_mod.ResolverConfig.clone(self.alloc, cfg);
            }
        }
        return null;
    }

    fn removeResolverReconciliationPage(self: *DB, name: []const u8, context: @import("artifact_reconcile_intent.zig").Context) !bool {
        const intent = @import("artifact_reconcile_intent.zig");
        var activity = try self.acquireResolverCatalogActivity(false);
        defer activity.deinit();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        {
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            try self.requireOnlineArtifactCatalogMutableWithContextLocked(&read, context);
            try self.requireArtifactReconcileUnfenced(&read, context);
        }
        // Graph indexes were detached by preceding reconciliation steps.
        // catch_up_mutex covers resolver/promotion jobs through publication;
        // holding both activity locks drains any prior callback. Between
        // pages, the durable intent rejects producer and handoff publication
        // under the apply mutex, so nothing can appear behind this cursor.
        // Final config removal uses these same locks before stopping workers.
        if (self.core.graphIndexes().len != 0) return error.ArtifactCatalogDrift;
        const config = (try self.resolverConfigByNameAlloc(name)) orelse return false;
        defer {
            var owned = config;
            owned.deinit(self.alloc);
        }
        const raw = try self.core.getStoreValue(self.alloc, intent.resolver_cursor_key);
        defer if (raw) |bytes| self.alloc.free(bytes);
        var parsed = if (raw) |bytes| std.json.parseFromSlice(intent.ResolverCursor, self.alloc, bytes, .{}) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return error.ArtifactCatalogCorrupt,
        } else null;
        defer if (parsed) |*value| value.deinit();
        const prior: ?intent.ResolverCursor = if (parsed) |value| if (std.mem.eql(u8, value.value.name, name) and std.mem.eql(u8, &value.value.token, &context.token)) value.value else null else null;
        if (prior != null and prior.?.complete) return self.core.removeResolver(name);
        const prefix = [_]u8{internal_keys.user_namespace};
        const keys = try self.core.store.scanPrefixKeysPage(self.alloc, &prefix, if (prior) |value| value.after else null, 128);
        defer {
            for (keys) |key| self.alloc.free(key);
            self.alloc.free(keys);
        }
        var deletes: std.ArrayListUnmanaged([]const u8) = .empty;
        defer {
            for (deletes.items) |key| self.alloc.free(@constCast(key));
            deletes.deinit(self.alloc);
        }
        for (keys) |key| {
            const resolution = (try internal_keys.parseResolutionArtifactKeyAlloc(self.alloc, key)) orelse continue;
            defer {
                self.alloc.free(resolution.doc_key);
                self.alloc.free(resolution.artifact_name);
            }
            if (!std.mem.eql(u8, resolution.artifact_name, config.resolution_artifact)) continue;
            try deletes.append(self.alloc, try self.alloc.dupe(u8, key));
            try appendResolutionHandoffDeleteKey(self.alloc, &deletes, key);
        }
        const cursor = try std.json.Stringify.valueAlloc(self.alloc, intent.ResolverCursor{ .token = context.token, .name = name, .after = if (keys.len == 0) "" else keys[keys.len - 1], .complete = keys.len == 0 }, .{});
        defer self.alloc.free(cursor);
        try self.core.store.putBatch(&.{.{ .key = intent.resolver_cursor_key, .value = cursor }}, deletes.items);
        return false;
    }

    fn retireResolverArtifactsLocked(self: *DB, cfg: index_manager_mod.ResolverConfig) !?u64 {
        var deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (deletes.items) |key| self.alloc.free(@constCast(key));
            deletes.deinit(self.alloc);
        }
        var changed = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (changed.items) |key| self.alloc.free(key);
            changed.deinit(self.alloc);
        }

        const marker_prefix = try internal_keys.assetArtifactSourceIndexPrefixAlloc(self.alloc, cfg.source_artifact);
        defer self.alloc.free(marker_prefix);
        const markers = try self.core.store.scanPrefix(self.alloc, marker_prefix);
        defer docstore_mod.DocStore.freeResults(self.alloc, markers);

        for (markers) |marker| {
            const parsed = (try internal_keys.parseAssetArtifactKeyAlloc(self.alloc, marker.value)) orelse continue;
            defer {
                self.alloc.free(parsed.doc_key);
                self.alloc.free(parsed.artifact_name);
            }
            if (!std.mem.eql(u8, parsed.artifact_name, cfg.source_artifact)) continue;

            const resolution_key = try internal_keys.resolutionArtifactKeyAlloc(self.alloc, parsed.doc_key, cfg.resolution_artifact);
            var resolution_key_owned = true;
            errdefer if (resolution_key_owned) self.alloc.free(resolution_key);
            const exists = if (self.core.store.get(self.alloc, resolution_key)) |raw| exists: {
                self.alloc.free(raw);
                break :exists true;
            } else |err| switch (err) {
                error.NotFound => false,
                else => return err,
            };
            if (exists and !containsDeleteKey(deletes.items, resolution_key)) {
                try deletes.append(self.alloc, resolution_key);
                resolution_key_owned = false;
                try appendUniqueOwnedKey(self.alloc, &changed, resolution_key);
                try appendResolutionHandoffDeleteKey(self.alloc, &deletes, resolution_key);
            } else {
                self.alloc.free(resolution_key);
                resolution_key_owned = false;
            }

            try self.collectResolverMentionArtifactsForDocLocked(cfg, parsed.doc_key, &deletes, &changed);
        }

        const root_lower = [_]u8{internal_keys.user_namespace};
        const root_upper = [_]u8{internal_keys.user_namespace + 1};
        const resolution_rows = try self.core.store.scanRange(self.alloc, root_lower[0..], root_upper[0..]);
        defer docstore_mod.DocStore.freeResults(self.alloc, resolution_rows);
        for (resolution_rows) |row| {
            const parsed = (try internal_keys.parseResolutionArtifactKeyAlloc(self.alloc, row.key)) orelse continue;
            defer {
                self.alloc.free(parsed.doc_key);
                self.alloc.free(parsed.artifact_name);
            }
            if (!std.mem.eql(u8, parsed.artifact_name, cfg.resolution_artifact)) continue;
            if (!containsDeleteKey(deletes.items, row.key)) {
                try deletes.append(self.alloc, try self.alloc.dupe(u8, row.key));
                try appendUniqueOwnedKey(self.alloc, &changed, row.key);
                try appendResolutionHandoffDeleteKey(self.alloc, &deletes, row.key);
            }
            try self.collectResolverMentionArtifactsForDocLocked(cfg, parsed.doc_key, &deletes, &changed);
        }

        if (deletes.items.len == 0 and changed.items.len == 0) return null;

        const sequence = self.core.reserveDerivedAppendSequence();
        const replay_payload = try encodeChangeRecordPayload(&self.batchContext(), .{
            .sequence = sequence,
            .changed_artifact_keys = changed.items,
        }, sequence);
        defer self.alloc.free(replay_payload);

        var backlog_admission = try self.executor.admitBacklogBytes(@intCast(replay_payload.len));
        defer backlog_admission.cancel();
        try self.core.store.putBatchWithReplay(self.backend_runtime.io(), &.{}, deletes.items, .{
            .sequence = sequence,
            .payload = replay_payload,
        });
        self.mirrorReplicationReplayPayloadBestEffort(replay_payload);
        self.executor.commitBacklogAdmission(sequence, &backlog_admission);
        return sequence;
    }

    fn collectResolverMentionArtifactsForDocLocked(
        self: *DB,
        cfg: index_manager_mod.ResolverConfig,
        doc_key: []const u8,
        deletes: *std.ArrayListUnmanaged([]const u8),
        changed: *std.ArrayListUnmanaged([]u8),
    ) !void {
        for (self.core.graphIndexes()) |graph_entry| {
            for (graph_entry.artifact_sources) |source| {
                if (source.mention_edge_type.len == 0) continue;
                if (!std.mem.eql(u8, source.artifact_name, cfg.source_artifact)) continue;

                const state_name = try mentionGraphStateNameAlloc(self.alloc, cfg.source_artifact, cfg.resolution_artifact);
                defer self.alloc.free(state_name);
                try self.collectGraphStateForDeleteLocked(doc_key, graph_entry.config.name, state_name, graph_entry.config.coverage_generation, deletes, changed);

                const mention_state_name = try mentionArtifactStateNameAlloc(self.alloc, cfg.source_artifact, cfg.resolution_artifact);
                defer self.alloc.free(mention_state_name);
                try self.collectGraphStateForDeleteLocked(doc_key, graph_entry.config.name, mention_state_name, graph_entry.config.coverage_generation, deletes, changed);
            }
        }
    }

    fn collectGraphStateForDeleteLocked(
        self: *DB,
        doc_key: []const u8,
        index_name: []const u8,
        state_name: []const u8,
        expected_generation: u64,
        deletes: *std.ArrayListUnmanaged([]const u8),
        changed: *std.ArrayListUnmanaged([]u8),
    ) !void {
        const state_key = try graphAssetStateKeyAlloc(self.alloc, doc_key, index_name, state_name);
        var state_key_owned = true;
        errdefer if (state_key_owned) self.alloc.free(state_key);

        if (try loadGraphAssetStateKeysAlloc(self.alloc, self.core.store, state_key, expected_generation)) |previous_keys| {
            defer freeOwnedConstKeySlice(self.alloc, previous_keys);
            for (previous_keys) |previous_key| {
                if (containsDeleteKey(deletes.items, previous_key)) continue;
                const owned_key = try self.alloc.dupe(u8, previous_key);
                try deletes.append(self.alloc, owned_key);
                try appendUniqueOwnedKey(self.alloc, changed, previous_key);
            }
        }
        try appendGraphAssetStateSegmentDeleteKeys(self.alloc, self.core.store, state_key, deletes);

        const state_exists = if (self.core.store.get(self.alloc, state_key)) |raw| exists: {
            self.alloc.free(raw);
            break :exists true;
        } else |err| switch (err) {
            error.NotFound => false,
            else => return err,
        };
        if (state_exists and !containsDeleteKey(deletes.items, state_key)) {
            try deletes.append(self.alloc, state_key);
            state_key_owned = false;
        } else {
            self.alloc.free(state_key);
            state_key_owned = false;
        }
    }

    fn retireResolverReplayBeforeCatalogRemoval(self: *DB) !void {
        try self.runUntilIdle();
        const resolution_stats = self.resolutionStageStats();
        if (resolution_stats.catch_up_required or resolution_stats.blocked) return error.ResolverReplayPending;
        const promotion_stats = self.promotionStageStats();
        if (promotion_stats.catch_up_required or promotion_stats.blocked) return error.ResolverReplayPending;
    }

    /// The review queue: review-band mentions awaiting human curation. Empty
    /// when no resolution runtime is active. Caller owns the result
    /// (`resolution_runtime_mod.freePendingReviews`).
    pub fn listPendingReviews(self: *DB, alloc: Allocator) ![]resolution_runtime_mod.PendingReview {
        const runtime = self.resolution_runtime orelse return try alloc.alloc(resolution_runtime_mod.PendingReview, 0);
        return try runtime.pendingReviews(alloc);
    }

    /// Persist a human curation decision for one review-band mention and enqueue
    /// the document for ordinary replay-driven resolution/promotion.
    pub fn recordReviewDecision(
        self: *DB,
        doc_key: []const u8,
        source_artifact: []const u8,
        resolution_artifact: []const u8,
        local_id: []const u8,
        decision: resolver_lib.Decision,
        table: []const u8,
        key: []const u8,
    ) !u64 {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        try self.executor.failIfUnhealthy();

        var snapshot_mutation = self.core.snapshot_admission.acquireMutation();
        defer snapshot_mutation.release();
        try self.lockApplyForPortableRuntime();
        var apply_mutex_held = true;
        errdefer if (apply_mutex_held) self.core.unlockApply();

        const resolvers = try self.core.listResolvers(self.alloc);
        defer {
            for (resolvers) |*cfg| cfg.deinit(self.alloc);
            if (resolvers.len > 0) self.alloc.free(resolvers);
        }
        for (resolvers) |cfg| {
            if (std.mem.eql(u8, cfg.source_artifact, source_artifact) and
                std.mem.eql(u8, cfg.resolution_artifact, resolution_artifact))
            {
                break;
            }
        } else return error.ResolverNotFound;

        const override_key = try resolution_runtime_mod.reviewOverrideArtifactKeyAlloc(self.alloc, doc_key, source_artifact, resolution_artifact);
        defer self.alloc.free(override_key);
        const existing = self.core.store.get(self.alloc, override_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        defer if (existing) |raw| self.alloc.free(raw);
        const override_bytes = try resolution_runtime_mod.buildReviewDecisionBytesAlloc(self.alloc, existing, local_id, decision, table, key);
        defer self.alloc.free(override_bytes);

        const source_key = try internal_keys.artifactNamedPrefixAlloc(self.alloc, doc_key, "asset", source_artifact);
        defer self.alloc.free(source_key);
        const sequence = self.core.reserveDerivedAppendSequence();
        const changed_artifact_keys = [_][]const u8{source_key};
        const replay_payload = try encodeChangeRecordPayload(&self.batchContext(), .{
            .sequence = sequence,
            .changed_artifact_keys = changed_artifact_keys[0..],
        }, sequence);
        defer self.alloc.free(replay_payload);

        const writes = [_]docstore_mod.KVPair{.{
            .key = override_key,
            .value = override_bytes,
        }};
        var backlog_admission = try self.executor.admitBacklogBytes(@intCast(replay_payload.len));
        defer backlog_admission.cancel();
        try self.core.store.putBatchWithReplay(self.backend_runtime.io(), writes[0..], &.{}, .{
            .sequence = sequence,
            .payload = replay_payload,
        });
        self.mirrorReplicationReplayPayloadBestEffort(replay_payload);
        self.executor.commitBacklogAdmission(sequence, &backlog_admission);
        self.core.unlockApply();
        apply_mutex_held = false;
        snapshot_mutation.release();
        notifyQueryVisibilityTargetAdvanced(self.async_context, sequence);

        if (self.executor.hasWorkers()) {
            self.executor.forceSequence(sequence);
        } else {
            self.executor.notifySequence(sequence);
        }
        self.notifyResolverReplayRuntimes(sequence);
        return sequence;
    }

    /// Eager edge rewrite for an entity merge: repoint every inbound edge of
    /// `old_key` (the merged-away entity) at `new_key` (the survivor) in the
    /// given graph index, preserving edge type, weight, and metadata. Already
    /// materialized contributions move with their producer manifests, counts,
    /// and deadlines. Resolver curation keeps replay on the survivor. This local
    /// administrative entry point requires native/unscoped owner authority.
    /// Returns the number of edges rewritten.
    pub fn rewriteEntityEdges(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        old_key: []const u8,
        new_key: []const u8,
    ) !usize {
        if (std.mem.eql(u8, old_key, new_key)) return 0;
        if (new_key.len == 0) return error.InvalidGraphEdgeArtifact;
        var policy = try self.local_execution.row_policy_gate.enterRaw();
        defer policy.release();
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        try self.ensureDurableReplicationStartupBarrier();
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        try self.enforceReplicationWriteGate();
        if (self.local_execution.replication_async_batch_mirror != null and self.local_execution.replication_async_effect_mirror == null)
            return error.ReplicationPublisherUnavailable;
        try self.executor.failIfUnhealthy();
        var snapshot_mutation = self.core.snapshot_admission.acquireMutation();
        defer snapshot_mutation.release();
        try self.lockApplyForPortableRuntime();
        var apply_held = true;
        defer if (apply_held) self.core.unlockApply();
        if (builtin.is_test) if (test_entity_rewrite_apply_admitted) |hook| try hook.call(hook.ctx, self);
        var graph_publication = self.core.index_manager.beginGraphPrimaryMutation();
        defer graph_publication.release();
        // Primary publication excludes both new graph mutations and replay.
        // Verify the projection cut under this fence, and release every fence
        // before waiting. Recheck after waiting so a racing mutation cannot
        // make the adjacency older than the primary snapshot we rewrite.
        const clock = self.backend_runtime.monotonicClock();
        const wait = derived_executor_mod.VisibilityWait{
            .clock = clock,
            .deadline_ns = clock.nowRealtimeNs() +| default_visibility_wait_timeout_ms * std.time.ns_per_ms,
        };
        while (true) {
            try wait.check();
            {
                var read = try self.core.store.beginProbeTxn();
                defer read.abort();
                try self.requireOnlineArtifactCatalogMutableLocked(&read);
                try self.requireArtifactReconcileUnfenced(&read, null);
                try @import("relational_integrity_retirement.zig").requireMutable(&read);
                try @import("restore_staging.zig").requireScope(alloc, &read, null, false);
                if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
                // Local administration cannot invent an ordered publication
                // position. External owners must order curation through their owner.
                if (try @import("../source_authority.zig").publicationOwner(&read)) |owner| {
                    if (owner.mode == .ordered) return error.OnlineSourceScopeChanged;
                }
            }
            if (self.core.index_manager.graphIndex(index_name) == null) return error.IndexNotFound;
            if (!self.core.index_manager.graphRetirementAdmissionOpen()) return error.IntegrityTopologyBusy;
            const applied = try self.managedIndexAppliedSequence(alloc, index_name);
            const target = try self.managedIndexReplayTargetSequence(alloc, index_name, .graph, applied);
            if (applied >= target) break;
            graph_publication.release();
            self.core.unlockApply();
            apply_held = false;
            snapshot_mutation.release();
            if (self.executor.hasWorkers()) {
                try self.runDerivedUntilTargetsWithVisibilityWait(target, &.{index_name}, wait);
            } else {
                try replayPendingDerivedBatches(self, null, null, .{
                    .index_names = &.{index_name},
                    .truncate_replay = false,
                    .deadline_ns = wait.deadline_ns,
                });
            }
            snapshot_mutation = self.core.snapshot_admission.acquireMutation();
            try self.lockApplyForPortableRuntime();
            apply_held = true;
            if (builtin.is_test) if (test_entity_rewrite_apply_admitted) |hook| try hook.call(hook.ctx, self);
            graph_publication = self.core.index_manager.beginGraphPrimaryMutation();
            try self.enforceReplicationWriteGate();
            if (!self.executor.hasWorkers() and try self.managedIndexAppliedSequence(alloc, index_name) < target)
                return error.GraphMaintenanceInProgress;
        }
        const entry = self.core.index_manager.graphIndex(index_name) orelse return error.IndexNotFound;
        const inbound = try entry.index.getEdges(alloc, old_key, "", .in);
        defer graph_mod.GraphIndex.freeEdges(alloc, inbound);
        if (inbound.len == 0) return 0;
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const scratch = arena.allocator();
        const mutation = try prepareEntityGraphRewrite(scratch, self, index_name, inbound, new_key);
        if (mutation.rewritten == 0) return 0;
        // The outbox appends using the DB allocator, independently of scratch.
        var writes: std.ArrayListUnmanaged(docstore_mod.KVPair) = .empty;
        defer writes.deinit(self.alloc);
        try writes.appendSlice(self.alloc, mutation.writes.items);
        {
            var read = try self.core.store.beginProbeTxn();
            defer read.abort();
            const authority_mod = @import("../source_authority.zig");
            if (try authority_mod.load(&read)) |observed| {
                var authority = try authority_mod.require(&read, .native, observed.namespace);
                authority.sequence = std.math.add(u64, authority.sequence, 1) catch return error.OnlineSourceCorrupt;
                const bytes = authority.encode();
                try writes.append(self.alloc, .{ .key = authority_mod.key, .value = try scratch.dupe(u8, &bytes) });
            }
        }
        const sequence = self.core.reserveDerivedAppendSequence();
        const replay = try encodeChangeRecordPayload(&self.batchContext(), .{
            .sequence = sequence,
            .changed_artifact_keys = mutation.changed.items,
        }, sequence);
        defer self.alloc.free(replay);
        var revision_keys: std.ArrayListUnmanaged([]u8) = .empty;
        defer {
            for (revision_keys.items) |key| self.alloc.free(key);
            revision_keys.deinit(self.alloc);
        }
        var revision_values: std.ArrayListUnmanaged([]u8) = .empty;
        defer {
            for (revision_values.items) |value| self.alloc.free(value);
            revision_values.deinit(self.alloc);
        }
        try appendArtifactSourceRevisionWritesFromReplay(self.alloc, replay, sequence, &writes, &revision_keys, &revision_values);
        var context = self.batchContext();
        var primary_replication = try PrimaryReplicationEffect.prepare(&context, writes.items, mutation.deletes.items, replay);
        defer primary_replication.deinit(self.alloc);
        try primary_replication.stage(&context, &writes);
        var backlog = try self.executor.admitBacklogBytes(@intCast(replay.len));
        defer backlog.cancel();
        try policy.checkAt(@intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s)));
        try self.core.store.putBatchWithReplay(self.backend_runtime.io(), writes.items, mutation.deletes.items, .{ .sequence = sequence, .payload = replay });
        self.executor.commitBacklogAdmission(sequence, &backlog);
        if (shouldAppendSplitDelta(self)) try self.core.appendSplitDelta(currentTimeNs(), writes.items, mutation.deletes.items);
        graph_publication.release();
        var gates = ReplicationDeferredCommitGates.begin(replicationTransitionMutexFromContext(&context));
        defer gates.releaseTransition();
        gates.append(try primary_replication.appendLocked(&context));
        self.core.unlockApply();
        apply_held = false;
        snapshot_mutation.release();
        notifyQueryVisibilityTargetAdvanced(self.async_context, sequence);
        self.executor.notifySequence(sequence);
        self.notifyResolverReplayRuntimes(sequence);
        gates.releaseTransition();
        releaseReplicationMutationShared(&replication_mutation);
        try gates.waitForDurabilityAndAuthority(context.replication_write_gate);
        try primary_replication.clear(&context);
        return mutation.rewritten;
    }

