        return try self.resolveDocSetForIdsNoLockAtGenerationAlloc(alloc, doc_ids, null);
    }

    fn resolveDocSetForIdsNoLockAtGenerationAlloc(
        self: *DB,
        alloc: Allocator,
        doc_ids: []const []const u8,
        generation: ?u64,
    ) !doc_set.ResolvedDocSet {
        return self.resolveDocSetForIdsNoLockAtGenerationWithPolicyAlloc(alloc, doc_ids, generation, .{});
    }

    fn resolveDocSetForIdsNoLockAtGenerationWithPolicyAlloc(
        self: *DB,
        alloc: Allocator,
        doc_ids: []const []const u8,
        generation: ?u64,
        policy: doc_set.BitmapPolicy,
    ) !doc_set.ResolvedDocSet {
        var txn = try self.core.store.beginProbeTxn();
        defer txn.abort();
        const resolved = try doc_identity.resolvedDocSetForIdsAtGenerationWithPolicyTxn(alloc, &txn, doc_ids, generation, policy);
        self.recordResolvedDocSet(&resolved, doc_ids.len > 0 and switch (resolved) {
            .doc_keys => true,
            else => false,
        });
        return resolved;
    }

    fn resolvedDocFilterForIdsAlloc(
        self: *DB,
        include_positive: bool,
        include_doc_ids: []const []const u8,
        exclude_doc_ids: []const []const u8,
        generation: ?u64,
    ) !doc_set.ResolvedDocFilter {
        var filter = doc_set.ResolvedDocFilter{};
        errdefer filter.deinit(self.alloc);
        if (include_positive) {
            filter.include = try self.resolveDocSetForIdsNoLockAtGenerationAlloc(self.alloc, include_doc_ids, generation);
        }
        if (exclude_doc_ids.len > 0) {
            filter.exclude = try self.resolveDocSetForIdsNoLockAtGenerationAlloc(self.alloc, exclude_doc_ids, generation);
        }
        return filter;
    }

    fn docIdsForResolvedDocSetAlloc(self: *DB, alloc: Allocator, set: *const doc_set.ResolvedDocSet) !?[]const []const u8 {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        return try self.docIdsForResolvedDocSetNoLockAlloc(alloc, set);
    }

    fn docIdsForResolvedDocSetNoLockAlloc(self: *DB, alloc: Allocator, set: *const doc_set.ResolvedDocSet) !?[]const []const u8 {
        return try self.docIdsForResolvedDocSetNoLockAtGenerationAlloc(alloc, set, null);
    }

    fn docIdsForResolvedDocSetNoLockAtGenerationAlloc(
        self: *DB,
        alloc: Allocator,
        set: *const doc_set.ResolvedDocSet,
        generation: ?u64,
    ) !?[]const []const u8 {
        switch (set.*) {
            .all => return null,
            .none => return try alloc.alloc([]const u8, 0),
            .doc_keys => |keys| return try dupeConstDocIdsAlloc(alloc, keys),
            .ordinals => |ordinals| {
                var txn = try self.core.store.beginProbeTxn();
                defer txn.abort();
                return try docIdsForOrdinalsAtGenerationTxnAlloc(alloc, &txn, ordinals, generation);
            },
            .ordinal_bitmap => |*bitmap| {
                var txn = try self.core.store.beginProbeTxn();
                defer txn.abort();
                var ordinals = std.ArrayListUnmanaged(doc_set.DocOrdinal).empty;
                defer ordinals.deinit(alloc);
                var iter = bitmap.iterator();
                while (iter.next()) |ordinal| try ordinals.append(alloc, ordinal);
                return try docIdsForOrdinalsAtGenerationTxnAlloc(alloc, &txn, ordinals.items, generation);
            },
        }
    }

    pub fn extractEnrichments(self: *DB, alloc: Allocator, writes: []const types.BatchWrite) !types.ExtractEnrichmentsResult {
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();

        var collector: result_collectors.Extraction = .{ .alloc = alloc };
        defer collector.deinit();
        for (writes) |write| {
            var extracted = try mapper.extractWrite(alloc, write.key, write.value);
            defer extracted.deinit(alloc);
            try augmentExtractedWriteWithGraphFieldEdges(self, alloc, write.key, write.value, &extracted);
            try collector.append(write.key, extracted);
        }
        return collector.finish();
    }

    pub fn computeEnrichments(self: *DB, alloc: Allocator, writes: []const types.BatchWrite) !types.ComputeEnrichmentsResult {
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();

        var collector: result_collectors.Enrichments = .{ .alloc = alloc };
        defer collector.deinit();

        for (writes) |write| {
            var extracted = try mapper.extractWrite(alloc, write.key, write.value);
            defer extracted.deinit(alloc);
            try augmentExtractedWriteWithGraphFieldEdges(self, alloc, write.key, write.value, &extracted);
            const cleaned = extracted.cleaned_value orelse continue;

            var explicit_dense = std.ArrayListUnmanaged(types.EnrichmentDenseEmbeddingWrite).empty;
            defer {
                for (explicit_dense.items) |*embedding| embedding.deinit(alloc);
                explicit_dense.deinit(alloc);
            }
            for (extracted.dense_embeddings) |embedding| {
                try appendClonedExplicitDenseEmbedding(
                    alloc,
                    &explicit_dense,
                    embedding.index_name,
                    embedding.doc_key,
                    embedding.vector,
                );
            }
            var explicit_sparse = std.ArrayListUnmanaged(types.EnrichmentSparseEmbeddingWrite).empty;
            defer {
                for (explicit_sparse.items) |*embedding| embedding.deinit(alloc);
                explicit_sparse.deinit(alloc);
            }
            for (extracted.sparse_embeddings) |embedding| {
                try appendClonedExplicitSparseEmbedding(
                    alloc,
                    &explicit_sparse,
                    embedding.index_name,
                    embedding.doc_key,
                    embedding.indices,
                    embedding.values,
                );
            }

            const generated = try self.core.planGeneratedEnrichments(
                alloc,
                write.key,
                cleaned,
                explicit_dense.items,
                explicit_sparse.items,
            );
            defer enrichment_types.deinitGeneratedRequests(alloc, generated);

            var chunk_cache = std.ArrayListUnmanaged(ChunkCacheEntry).empty;
            defer {
                for (chunk_cache.items) |entry| {
                    alloc.free(entry.key);
                    chunker_mod.freeChunks(alloc, entry.chunks);
                }
                chunk_cache.deinit(alloc);
            }

            for (generated) |request| {
                switch (request.kind) {
                    .chunk_text => try computeChunkRequest(alloc, self, cleaned, request, &collector.artifacts, &collector.documents, &chunk_cache),
                    .dense_embedding => computeDenseRequest(alloc, self, cleaned, request, &collector.artifacts, &collector.dense, &chunk_cache) catch |err| switch (err) {
                        error.MissingDenseEmbedder => try appendUniqueOwnedKey(alloc, &collector.failed, write.key),
                        else => return err,
                    },
                    else => {},
                }
            }
        }

        return try collector.finish();
    }

    fn deleteIndexWhileEnrichmentQuiesced(self: *DB, name: []const u8) !bool {
        return self.deleteIndexWhileQuiescedForReconciliation(name, null);
    }

    fn deleteIndexWhileQuiescedForReconciliation(self: *DB, name: []const u8, context: ?@import("artifact_reconcile_intent.zig").Context) !bool {
        // Pausing drains a callback that may need the apply lock. Probe
        // before that drain; the caller's structural mutex also prevents a
        // source admission between this probe and the locked recheck below.
        {
            lockApplyShared(self);
            defer self.core.unlockApplyShared();
            var read = try self.core.store.beginProbeTxn();
            defer read.abort();
            try self.requireArtifactReconcileUnfenced(&read, context);
            try self.requireOnlineArtifactCatalogMutableWithContextLocked(&read, context);
            if (self.core.index_manager.graphIndex(name) != null) try self.requireGraphCatalogMutableForTransactions();
        }
        // A stopped registration remains a replay-retention participant until
        // the catalog commit. Rollback resumes it without allocation or I/O.
        // Register before acquiring apply so retirement runs after its unlock.
        const paused_worker = try self.executor.pauseWorker(name);
        var catalog_deleted = false;
        defer if (paused_worker) {
            if (catalog_deleted) self.executor.removeWorker(name) else self.executor.resumeWorker(name);
        };
        if (builtin.is_test) if (test_index_delete_after_worker_paused) |hook| try hook(self);
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        {
            var read = try self.core.store.beginProbeTxn();
            defer read.abort();
            try self.requireArtifactReconcileUnfenced(&read, context);
            try self.requireOnlineArtifactCatalogMutableWithContextLocked(&read, context);
            if (self.core.index_manager.graphIndex(name) != null) try self.requireGraphCatalogMutableForTransactions();
        }
        const repair_id = try self.prepareIndexRepairForDeletion(self.alloc, name);
        defer if (repair_id != null) self.endIndexRepairLease(name);
        const admission_key = try internal_keys.managedIndexAdmissionKeyAlloc(self.alloc, name);
        defer self.alloc.free(admission_key);
        const removed = try self.core.deleteManagedIndex(name, admission_key);
        if (removed) {
            catalog_deleted = true;
            if (builtin.is_test and test_fail_managed_index_delete_after_catalog_commit)
                return error.TestManagedIndexDeleteCrash;
            self.core.index_manager.clearManagedAdmissionSnapshotForIndex(name);
            if (repair_id) |id| {
                const repair_cleanup = if (builtin.is_test and test_fail_managed_index_repair_cleanup_after_catalog_commit)
                    error.TestPostCommitRepairCleanup
                else
                    self.removeIndexRepairIntentAndPin(self.alloc, id);
                repair_cleanup catch |err| {
                    std.log.warn("index removal committed with stale repair intent name={s} err={s}", .{ name, @errorName(err) });
                };
            }
            self.deleteDenseArtifactCounterMetadata(name) catch |err| {
                std.log.warn("index removal committed with stale dense coverage counters name={s} err={s}", .{ name, @errorName(err) });
            };
        }
        return removed;
    }

    pub fn deleteIndex(self: *DB, name: []const u8) !bool {
        return self.deleteIndexForReconciliation(name, null);
    }

    fn deleteIndexForReconciliation(self: *DB, name: []const u8, context: ?@import("artifact_reconcile_intent.zig").Context) !bool {
        if (self.local_execution.row_policy_gate.currentPhase() != .disabled) return error.RowPolicyUnsupported;
        var row_policy_lease = self.local_execution.row_policy_gate.enterRaw() catch return error.RowPolicyUnsupported;
        defer row_policy_lease.release();
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        if (context == null) try self.enforceReplicationWriteGate();
        var structural_guard = self.beginIndexStructuralMutation("index deletion", name);
        defer structural_guard.deinit();
        {
            lockApplyShared(self);
            defer self.core.unlockApplyShared();
            var probe = try self.core.store.beginReadTxn();
            defer probe.abort();
            try self.requireArtifactReconcileUnfenced(&probe, context);
        }
        try self.enforceVectorMigrationConfigurationGate();
        const restart_enrichment = self.quiesceEnrichmentForStructuralMutation();
        const removed = self.deleteIndexWhileQuiescedForReconciliation(name, context) catch |delete_err| {
            if (restart_enrichment) self.restartEnrichmentAfterStructuralMutation("failed index deletion", name) catch |restart_err| {
                std.log.err("failed to restore enrichment runtime after index deletion error index={s} err={s}", .{ name, @errorName(restart_err) });
            };
            return delete_err;
        };
        if (removed) self.scheduleGeneratedArtifactCleanup();
        // Catalog absence is the committed API result. A runtime restart is a
        // supervised availability fault, not a reason to report that the
        // durable deletion failed.
        if (restart_enrichment) self.restartEnrichmentAfterStructuralMutation("index deletion", name) catch |restart_err| {
            std.log.err("failed to restart enrichment runtime after committed index deletion index={s} err={s}", .{ name, @errorName(restart_err) });
        };
        return removed;
    }

    fn refreshManagedIndexWorkersLocked(self: *DB) !void {
        if (!self.start_index_workers) return;

        const managed_indexes = try self.core.managedIndexes(self.alloc);
        defer {
            for (managed_indexes) |index_ref| self.alloc.free(@constCast(index_ref.name));
            self.alloc.free(managed_indexes);
        }

        for (managed_indexes) |index_ref| {
            self.executor.removeWorker(index_ref.name);
        }
        for (managed_indexes) |index_ref| {
            const applied = try self.core.loadAppliedSequence(self.alloc, index_ref.name);
            try self.executor.addWorker(index_ref.name, index_ref, applied);
        }
    }

    fn resetManagedIndexAppliedSequences(self: *DB) !void {
        const managed_indexes = try self.core.managedIndexes(self.alloc);
        defer {
            for (managed_indexes) |index_ref| self.alloc.free(@constCast(index_ref.name));
            self.alloc.free(managed_indexes);
        }

        for (managed_indexes) |index_ref| {
            try self.core.saveAppliedSequence(index_ref.name, 0);
        }
    }

    fn resetManagedIndexAppliedSequencesForRestoreRepair(self: *DB, alloc: Allocator) !void {
        const managed_indexes = try self.core.managedIndexes(alloc);
        defer {
            for (managed_indexes) |index_ref| alloc.free(@constCast(index_ref.name));
            alloc.free(managed_indexes);
        }

        for (managed_indexes) |index_ref| {
            const sequence: u64 = switch (index_ref.kind) {
                .full_text => try self.probeDerivedReplayTargetSequence(
                    alloc,
                    self.core.replaySource(),
                    index_ref,
                    0,
                ),
                else => 0,
            };
            try self.core.saveAppliedSequence(index_ref.name, sequence);
        }
    }

    fn rebaseManagedIndexAppliedSequencesIfNeeded(self: *DB) !void {
        const managed_indexes = try self.core.managedIndexes(self.alloc);
        defer {
            for (managed_indexes) |index_ref| self.alloc.free(@constCast(index_ref.name));
            self.alloc.free(managed_indexes);
        }

        var max_applied: u64 = 0;
        for (managed_indexes) |index_ref| {
            const applied = try self.core.loadAppliedSequence(self.alloc, index_ref.name);
            max_applied = @max(max_applied, applied);
        }
        if (max_applied == 0) return;

        // Applied watermarks are independent of the retained replay log. Once
        // replay entries are truncated, a valid applied watermark can be above
        // the current append floor recovered from replay metadata. Preserve the
        // watermark and advance the floor so future replay sequence allocation
        // cannot reuse already-applied sequence numbers.
        try ensureReplayFloor(self.core.store, max_applied + 1);
    }

    pub fn deleteEnrichment(self: *DB, kind: types.EnrichmentKind, name: []const u8) !bool {
        return self.deleteEnrichmentForReconciliation(kind, name, null);
    }

    fn deleteEnrichmentForReconciliation(self: *DB, kind: types.EnrichmentKind, name: []const u8, context: ?@import("artifact_reconcile_intent.zig").Context) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var replication_mutation = self.acquireReplicationMutationShared();
        defer if (replication_mutation) |*lease| lease.release();
        if (context == null) try self.enforceReplicationWriteGate();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        {
            var probe = try self.core.store.beginProbeTxn();
            defer probe.abort();
            try self.requireOnlineArtifactCatalogMutableWithContextLocked(&probe, context);
        }
        try self.enforceVectorMigrationConfigurationGate();
        return try self.core.deleteEnrichment(kind, name);
    }

    pub fn pendingWorkStats(self: *DB) db_core.PendingWorkStats {
        return .{
            .derived_target_sequence = self.core.nextDerivedSequence(),
            .has_async_indexes = self.executor.hasWorkers(),
            .portable_import_publication_in_progress = self.core.store.portableImportPublicationInProgress(),
            .portable_import_recovery_required = self.core.store.portableImportRecoveryRequired(),
            .portable_runtime_activation_pending = self.async_context.portable_runtime_activation_pending.load(.acquire),
            .portable_runtime_activation_attempts = self.portable_runtime_activation_attempts.load(.monotonic),
            .enrichment = self.enrichmentStatsWithSupervisorState(.{}),
            .resolution = self.resolutionStageStats(),
            .promotion = self.promotionStageStats(),
            .text_merge = if (self.text_merge_runtime) |runtime| runtime.statsAssumeApplyLockHeld() else self.core.index_manager.textMergeStats(),
            .repair_metadata_rebuild_pending = self.artifactRepairMetadataRebuildPending(),
            .graph_metric = self.core.index_manager.graphMetricPlannedWorkStats() catch .{},
        };
    }

    fn artifactRepairMetadataRebuildPending(self: *DB) bool {
        const summary_ready = self.artifactRepairSummaryReady(self.alloc) catch return true;
        if (!summary_ready) return true;
        const kind_index_ready = self.artifactRepairKindIndexReady(self.alloc) catch return true;
        return !kind_index_ready;
    }

    fn persistedReplayStageStats(self: *DB, scope_name: []const u8, force_enabled: bool) !types.ReplayStageStats {
        const resources = self.core.batchExecutionResources();
        const applied = try enrichment_state.loadAppliedSequence(self.alloc, resources.store, scope_name);
        const target = @max(applied, self.core.nextDerivedSequence());
        return .{
            .enabled = force_enabled or target > 0 or applied < target,
            .target_sequence = target,
            .applied_sequence = applied,
            .catch_up_required = applied < target,
        };
    }

    fn resolutionStageStats(self: *DB) types.ReplayStageStats {
        if (!self.hasConfiguredResolvers()) return .{};
        if (self.resolution_runtime) |runtime| return runtime.stats();
        return self.persistedReplayStageStats(resolution_runtime_mod.scope_name, false) catch .{};
    }

    fn promotionStageStats(self: *DB) types.ReplayStageStats {
        if (!self.hasConfiguredResolvers()) return .{};
        if (self.promotion_runtime) |runtime| return runtime.stats();
        return self.persistedReplayStageStats(promotion_runtime_mod.scope_name, false) catch .{};
    }

    fn resolverReplayDiagnosticsLocked(self: *DB, alloc: Allocator) !types.ResolverReplayDiagnostics {
        const catalog = self.core.index_manager.resolvers.items;
        var resolvers = try alloc.alloc(types.ResolverReplayDiagnostic, catalog.len);
        var initialized: usize = 0;
        errdefer {
            for (resolvers[0..initialized]) |resolver| {
                alloc.free(resolver.name);
                alloc.free(resolver.table);
                alloc.free(resolver.source_artifact);
                alloc.free(resolver.resolution_artifact);
            }
            if (resolvers.len > 0) alloc.free(resolvers);
        }

        for (catalog) |cfg| {
            const name = try alloc.dupe(u8, cfg.name);
            errdefer alloc.free(name);
            const table = try alloc.dupe(u8, cfg.table);
            errdefer alloc.free(table);
            const source_artifact = try alloc.dupe(u8, cfg.source_artifact);
            errdefer alloc.free(source_artifact);
            const resolution_artifact = try alloc.dupe(u8, cfg.resolution_artifact);
            errdefer alloc.free(resolution_artifact);
            resolvers[initialized] = .{
                .name = name,
                .table = table,
                .source_artifact = source_artifact,
                .resolution_artifact = resolution_artifact,
            };
            initialized += 1;
        }

        return .{
            .resolver_count = @intCast(catalog.len),
            .resolution_runtime_present = self.resolution_runtime != null,
            .resolution_worker_started = if (self.resolution_runtime) |runtime| runtime.worker_started.load(.acquire) else false,
            .promotion_runtime_present = self.promotion_runtime != null,
            .promotion_worker_started = if (self.promotion_runtime) |runtime| runtime.worker_started.load(.acquire) else false,
            .resolvers = resolvers[0..initialized],
        };
    }

    fn persistedEnrichmentStats(self: *DB) !types.EnrichmentStats {
        if (!self.core.hasGeneratedEnrichmentTargets()) return .{};
        const resources = self.core.batchExecutionResources();
        const checkpoint = try enrichment_state.loadProjectionCheckpoint(self.alloc, resources.store, enrichment_runtime_mod.scope_name);
        const applied = checkpoint.applied_sequence;
        const status = try enrichment_state.loadRuntimeStatus(self.alloc, resources.store, enrichment_runtime_mod.scope_name);
        const target = @max(applied, status.target_sequence);
        return .{
            .enabled = target > 0 or status.error_count > 0 or status.retrying or status.worker_failed,
            .target_sequence = target,
            .applied_sequence = applied,
            .projection_checkpoint_status = enrichment_state.projectionStatusName(checkpoint.status),
            .projection_checkpoint_applied_sequence = checkpoint.applied_sequence,
            .projection_checkpoint_generation = checkpoint.generation,
            .projection_checkpoint_config_hash = checkpoint.config_hash,
            .checkpoint_replay_tail_sequence_count = target -| checkpoint.applied_sequence,
            .error_count = status.error_count,
            .retryable_error_count = status.retryable_error_count,
            .fatal_error_count = status.fatal_error_count,
            .consecutive_retry_count = status.consecutive_retry_count,
            .next_retry_at_ms = status.next_retry_at_ms,
            .retrying = status.retrying,
            .worker_failed = status.worker_failed,
        };
    }

    const ReplayDrainOptions = struct {
        truncate_replay: bool = true,
        /// Empty selects all indexes; foreground curation selects its graph.
        index_names: []const []const u8 = &.{},
        wait_for_enrichment_retries: bool = false,
        cancellation: types.CancellationToken = .none,
        max_windows_per_index: usize = 0,
        deadline_ns: ?u64 = null,
        /// Run the foreground enrichment catch-up pass to full completion
        /// instead of bounding it at the request-visibility default
        /// (`sync_wait_timeout_ms`, 5 minutes). Only `runUntilIdle` sets
        /// this; see `runEnrichmentUntilForDrainUnbounded`.
        unbounded_enrichment_wait: bool = false,
        /// Opt-in stall guard, in nanoseconds; 0/null disables it. Only
        /// `runUntilIdle` sets this (from `run_until_idle_no_progress_timeout_ms`
        /// at open, see `OpenOptions`). Every pass through
        /// `runMaintenanceUntilWithOptions`'s catch-up loop checks
        /// `AsyncContext.target_advance` (populated by
        /// `canAdvanceDerivedToTargetAsync`) and fails with
        /// `error.RunUntilIdleNoProgress` once any exact index has been unable
        /// to advance its replay target for at least this long, instead of
        /// looping on the same deferred artifact-maintenance check forever.
        /// Left disabled for every other caller (request-visibility waits,
        /// plain `runMaintenanceUntil`, background replay): a busy but
        /// legitimately-progressing embedding backlog must not fail those
        /// paths just because one index is temporarily behind.
        no_progress_timeout_ns: u64 = 0,
    };

    fn runDerivedUntilWithOptions(self: *DB, sequence: u64, options: ReplayDrainOptions) !void {
        if (sequence == 0) return;
        if (options.cancellation.ptr != null) {
            return try self.runDerivedUntilWithVisibilityWait(sequence, .{
                .cancellation = options.cancellation,
            });
        }
        if (!self.executor.hasWorkers()) {
            try replayPendingDerivedBatches(self, null, null, options);
            return;
        }
        self.executor.notifySequence(sequence);
        if (options.no_progress_timeout_ns != 0) {
            // The threaded executor's waitForAll has no deadline, and the
            // post-wait stall check (checkTargetAdvanceNoProgress in
            // runMaintenanceUntilWithOptions) only runs after this returns —
            // a derived index that can never satisfy its replay target (for
            // example an artifact-backed dense index whose indexed count
            // diverges from its expected count) parked the wait forever and
            // the guard it was configured with never executed. Feed the same
            // per-index stuck diagnostic through the wait's cancellation
            // checkpoint so the guard interrupts the wait it is meant to
            // bound; a transient interrupt (the stuck record cleared between
            // firing and re-check) resumes waiting.
            var guard = TargetAdvanceStallGuard{ .db = self, .timeout_ns = options.no_progress_timeout_ns };
            while (true) {
                const outcome = self.executor.waitForAllWithVisibilityWait(sequence, .{
                    .cancellation = guard.token(),
                });
                outcome catch |err| switch (err) {
                    error.EnrichmentWaitCanceled => {
                        try self.checkTargetAdvanceNoProgress(options.no_progress_timeout_ns);
                        continue;
                    },
                    else => return err,
                };
                return;
            }
        }
        try self.executor.waitForAll(sequence);
    }

    /// Cancellation checkpoint that interrupts a threaded derived wait when
    /// any index's target advance has been stuck past `timeout_ns` (the same
    /// diagnostic `checkTargetAdvanceNoProgress` reads after the wait).
    /// Throttled: the executor's wait loop polls its checkpoint every
    /// millisecond, and the stuck scan takes the diagnostic mutex and
    /// allocates a name snapshot, so re-checking every poll would be pure
    /// overhead on healthy drains.
    const TargetAdvanceStallGuard = struct {
        db: *DB,
        timeout_ns: u64,
        last_check_ns: @import("antfly_platform").atomic.Value(u64) = .init(0),

        const recheck_interval_ns: u64 = 250 * std.time.ns_per_ms;

        fn token(self: *TargetAdvanceStallGuard) types.CancellationToken {
            return .{ .ptr = self, .check_fn = check };
        }

        fn check(ptr: *const anyopaque) anyerror!void {
            const self: *TargetAdvanceStallGuard = @ptrCast(@alignCast(@constCast(ptr)));
            const now_ns = monotonicTimeNs();
            if (now_ns -| self.last_check_ns.load(.monotonic) < recheck_interval_ns) return;
            self.last_check_ns.store(now_ns, .monotonic);
            var stuck = (try oldestTargetAdvanceStuck(self.db.async_context, self.timeout_ns, now_ns)) orelse return;
            stuck.deinit(self.db.async_context.alloc);
            return error.DerivedTargetAdvanceStuck;
        }
    };

    pub fn runDerivedUntil(self: *DB, sequence: u64) !void {
        try self.runDerivedUntilWithOptions(sequence, .{});
    }

    fn runDerivedUntilWithVisibilityWait(self: *DB, sequence: u64, wait: derived_executor_mod.VisibilityWait) !void {
        if (sequence == 0) return;
        if (!self.executor.hasWorkers()) {
            try wait.check();
            try replayPendingDerivedBatches(self, null, null, .{});
            try wait.check();
            return;
        }
        self.executor.notifySequence(sequence);
        try self.executor.waitForAllWithVisibilityWait(sequence, wait);
    }

    pub fn runDerivedUntilTargets(self: *DB, sequence: u64, index_names: []const []const u8) !void {
        if (sequence == 0 or index_names.len == 0) return;
        if (!self.executor.hasWorkers()) return;
        self.executor.notifyIndexes(sequence, index_names);
        try self.executor.waitForIndexes(sequence, index_names);
    }

    fn runDerivedUntilTargetsWithVisibilityWait(
        self: *DB,
        sequence: u64,
        index_names: []const []const u8,
        wait: derived_executor_mod.VisibilityWait,
    ) !void {
        if (sequence == 0 or index_names.len == 0) return;
        try wait.check();
        if (!self.executor.hasWorkers()) return;
        self.executor.notifyIndexes(sequence, index_names);
        try self.executor.waitForIndexesWithVisibilityWait(sequence, index_names, wait);
    }

    pub fn runEnrichmentUntil(self: *DB, sequence: u64) !void {
        try self.runEnrichmentUntilWithCancellation(sequence, .none);
    }

    fn runEnrichmentUntilWithCancellation(self: *DB, sequence: u64, cancellation: types.CancellationToken) !void {
        try self.runEnrichmentUntilWithVisibilityDeadline(sequence, cancellation, null);
    }

    fn runEnrichmentUntilWithVisibilityDeadline(
        self: *DB,
        sequence: u64,
        cancellation: types.CancellationToken,
        deadline_ns: ?u64,
    ) !void {
        if (sequence == 0) return;
        if (self.enrichment_runtime) |runtime| {
            if (!self.local_execution.optional_runtime_workers_enabled) {
                if (deadline_ns == null and cancellation.ptr == null) {
                    // Explicit maintenance/drain callers historically execute
                    // custom providers inline. They are not request waiters and
                    // retain that source-compatible behavior; API visibility
                    // always supplies the shared finite deadline below.
                    try runtime.catchUpUntil(sequence);
                    return;
                }
                // Foreground ownership is still a post-commit visibility
                // barrier. Honor the borrowed request token and the runtime's
                // hard wait deadline, but never reinterpret cancellation as a
                // rollback of the durable primary mutation.
                try runtime.catchUpUntilWithVisibilityDeadline(sequence, cancellation, deadline_ns);
                return;
            }
            runtime.notifySequence(sequence);
            try runtime.waitForAppliedWithVisibilityDeadline(sequence, cancellation, deadline_ns);
        }
    }

    /// Unlike `runEnrichmentUntilWithVisibilityDeadline`, never substitutes
    /// the request-visibility default (`sync_wait_timeout_ms`, 5 minutes)
    /// when no deadline is supplied, even when `optional_runtime_workers_enabled`
    /// -- worker-mode's `waitForAppliedWithVisibilityDeadline` only passively
    /// waits for a separate background worker to make progress and bounds
    /// that wait unconditionally when `deadline_ns` is null. `runUntilIdle`
    /// (Lite's synchronous ingest drain, in particular) never supplies a
    /// deadline and must run the foreground catch-up pass itself until the
    /// full enrichment backlog clears, however long that legitimately takes,
    /// not silently truncate at 5 minutes and surface a slow-but-progressing
    /// drain as a hard failure. Scoped to `runUntilIdle`'s own drain call
    /// (via `ReplayDrainOptions.unbounded_enrichment_wait`) rather than
    /// `runEnrichmentUntilWithVisibilityDeadline` generally: other callers
    /// (plain `runEnrichmentUntil`, `runMaintenanceUntil`, request-visibility
    /// barriers) still rely on the passive bounded wait deferring to that
    /// background worker, and forcing them through inline foreground
    /// execution instead changed observable enrichment-worker ownership
    /// behavior (see the `TestLiteHostedPauseResumeGeneratedEnrichment`
    /// regression this scoping fixes).
    fn runEnrichmentUntilForDrainUnbounded(self: *DB, sequence: u64) !void {
        if (sequence == 0) return;
        const runtime = self.enrichment_runtime orelse return;
        runtime.notifySequence(sequence);
        try runtime.catchUpUntilForDrain(sequence);
    }

    fn runEnrichmentUntilForDrain(self: *DB, sequence: u64, options: ReplayDrainOptions) !void {
        while (true) {
            const outcome = if (options.unbounded_enrichment_wait and options.cancellation.ptr == null)
                self.runEnrichmentUntilForDrainUnbounded(sequence)
            else
                self.runEnrichmentUntilWithCancellation(sequence, options.cancellation);
            outcome catch |err| switch (err) {
                error.EnrichmentRetryInProgress => {
                    if (!options.wait_for_enrichment_retries) return err;
                    const io = self.backend_runtime.io() orelse return error.MissingBackendRuntimeIo;
                    try io.sleep(.fromMilliseconds(25), .awake);
                    continue;
                },
                else => return err,
            };
            return;
        }
    }

    pub const markPrecomputedEnrichmentAppliedForSync = local_mutation.markPrecomputedEnrichmentAppliedForSync;

    pub const noPendingEnrichmentReplayThrough = local_mutation.noPendingEnrichmentReplayThrough;

    fn markEnrichmentAppliedIfNoPendingThrough(self: *DB, sequence: u64) !void {
        if (sequence == 0) return;
        const runtime = self.enrichment_runtime orelse return;
        const runtime_stats = runtime.stats();
        if (runtime_stats.applied_sequence >= sequence) return;
        if (try self.noPendingEnrichmentReplayThrough(runtime_stats.applied_sequence, sequence)) {
            try runtime.markAppliedThrough(sequence);
        }
    }

    fn runMaintenanceUntilWithOptions(self: *DB, sequence: u64, sync_targets: ManagedSyncTargets, options: ReplayDrainOptions) !void {
        _ = try self.drainStandaloneGraphEndpointCleanup();
        var stable_target = @max(sequence, self.currentMaintenanceTargetSequence());
        while (true) {
            // Enrichment is a producer for the managed derived indexes: it can
            // append embedding/chunk artifacts at the same source revision as
            // the document being drained. Waiting for a derived consumer
            // first creates a cycle when that consumer correctly refuses to
            // checkpoint an incomplete generation outcome. More importantly,
            // bypassing that wait can publish the source revision before its
            // later artifacts exist and make those artifacts unreplayable.
            // Drain the producer boundary first, then every consumer observes
            // the complete revision and can advance from durable evidence.
            try self.runEnrichmentUntilForDrain(stable_target, options);
            try self.runDerivedUntilWithOptions(stable_target, options);
            if (options.no_progress_timeout_ns != 0) try self.checkTargetAdvanceNoProgress(options.no_progress_timeout_ns);

            const next_target = self.core.nextDerivedSequence();
            if (next_target <= stable_target) {
                try waitForManagedIndexesApplied(self, sequence, sync_targets.all_indexes);
                _ = try self.runArtifactRepairMetadataMaintenancePass();
                return;
            }
            stable_target = next_target;
        }
    }

    /// Opt-in stall guard for `runUntilIdle` (see `ReplayDrainOptions.no_progress_timeout_ns`).
    /// A global "did the replay sequence move" check would not catch this
    /// class of bug: an index that can never satisfy its own replay target
    /// can still coexist with an unrelated sequence counter that keeps
    /// climbing (retries, other lanes' progress), which is exactly the
    /// livelock this guards against. Scoped per-index instead, using the
    /// same diagnostic `canAdvanceDerivedToTargetAsync` already computes.
    fn checkTargetAdvanceNoProgress(self: *DB, timeout_ns: u64) !void {
        const now_ns = monotonicTimeNs();
        var stuck = (try oldestTargetAdvanceStuck(self.async_context, timeout_ns, now_ns)) orelse return;
        // `oldestTargetAdvanceStuck` dupes with `AsyncContext.alloc`
        // (`self.runtime_alloc`), a distinct allocator instance from
        // `self.alloc` -- free with the same one it was allocated with.
        defer stuck.deinit(self.async_context.alloc);
        std.log.err(
            "runUntilIdle no-progress timeout index={s} indexed={d} expected_docs={d} stuck_ms={d}",
            .{ stuck.index_name, stuck.record.indexed, stuck.record.expected, (now_ns -| stuck.record.first_stuck_ns) / std.time.ns_per_ms },
        );
        try self.setLastRunUntilIdleNoProgressDiagnostic(
            stuck.index_name,
            stuck.record.indexed,
            stuck.record.expected,
            now_ns -| stuck.record.first_stuck_ns,
        );
        return error.RunUntilIdleNoProgress;
    }

    pub fn runMaintenanceUntil(self: *DB, sequence: u64, sync_targets: ManagedSyncTargets) !void {
        try self.runMaintenanceUntilWithOptions(sequence, sync_targets, .{});
    }

    fn runMaintenanceUntilWithCancellation(
        self: *DB,
        sequence: u64,
        sync_targets: ManagedSyncTargets,
        cancellation: types.CancellationToken,
        deadline_ns: u64,
    ) !void {
        const wait = derived_executor_mod.VisibilityWait{
            .cancellation = cancellation,
            .deadline_ns = deadline_ns,
            .clock = self.backend_runtime.monotonicClock(),
        };
        var stable_target = sequence;
        while (true) {
            try self.runEnrichmentUntilWithVisibilityDeadline(stable_target, cancellation, deadline_ns);
            try self.runDerivedUntilWithVisibilityWait(stable_target, wait);

            const next_target = self.core.nextDerivedSequence();
            if (next_target <= stable_target) {
                try waitForManagedIndexesApplied(self, sequence, sync_targets.all_indexes);
                _ = try self.runArtifactRepairMetadataMaintenancePass();
                return;
            }
            stable_target = next_target;
        }
    }

    pub fn runMaintenanceUntilTargets(self: *DB, sequence: u64, index_names: []const []const u8) !void {
        if (index_names.len == 0) return;
        var stable_target = sequence;
        while (true) {
            try self.runEnrichmentUntil(stable_target);
            try self.runDerivedUntilTargets(stable_target, index_names);

            const next_target = self.core.nextDerivedSequence();
            if (next_target <= stable_target) {
                try waitForManagedIndexesApplied(self, sequence, index_names);
                if (self.syncTargetsIncludeGraph(index_names)) _ = try self.runGraphMetricMaintenanceForIdle();
                return;
            }
            stable_target = next_target;
        }
    }

    fn syncTargetsIncludeGraph(self: *DB, index_names: []const []const u8) bool {
        for (index_names) |index_name| {
            if (self.core.graphIndex(index_name) != null) return true;
        }
        return false;
    }

    pub fn waitForCurrentSyncLevel(self: *DB, sync_level: types.SyncLevel) !void {
        try self.waitForCurrentSyncLevelWithCancellation(sync_level, .none);
    }

    pub fn waitForCurrentSyncLevelWithCancellation(self: *DB, sync_level: types.SyncLevel, cancellation: types.CancellationToken) !void {
        try self.executor.failIfUnhealthy();
        const sequence = self.core.nextDerivedSequence();
        try self.markPrecomputedEnrichmentAppliedForSync(sync_level, sequence);
        var sync_targets = try self.currentManagedSyncTargets(sync_level);
        defer sync_targets.deinit(self.alloc);
        if (self.executor.hasWorkers()) {
            notifyExecutorForSyncLevelWithDenseBulkDeferral(self.async_context, self.executor, sync_level, sequence, sync_targets);
        }
        try self.waitForSyncLevelWithCancellation(sync_level, sequence, sync_targets, cancellation, false);
    }

    pub const waitForResolvedTransactionSync = local_mutation.waitForResolvedTransactionSync;

    pub fn waitForResolvedTransactionSyncWithCancellation(self: *DB, sync_level: types.SyncLevel, sequence: u64, cancellation: types.CancellationToken) !void {
        if (sequence == 0 or sync_level == .propose or sync_level == .write) {
            try self.executor.failIfUnhealthy();
            return;
        }
        try self.executor.failIfUnhealthy();
        try self.markPrecomputedEnrichmentAppliedForSync(sync_level, sequence);
        var sync_targets = try self.currentManagedSyncTargets(sync_level);
        defer sync_targets.deinit(self.alloc);
        if (self.executor.hasWorkers()) {
            notifyExecutorForSyncLevelWithDenseBulkDeferral(self.async_context, self.executor, sync_level, sequence, sync_targets);
        }
        if (self.enrichment_runtime) |runtime| runtime.notifySequence(sequence);
        self.notifyResolverReplayRuntimes(sequence);
        try self.waitForSyncLevelWithCancellation(sync_level, sequence, sync_targets, cancellation, false);
        if (sync_level == .full_index and self.text_merge_runtime == null) {
            try self.drainScheduledTextMerges();
        }
    }

    fn currentManagedSyncTargets(self: *DB, sync_level: types.SyncLevel) !ManagedSyncTargets {
        const managed_indexes = try self.core.managedIndexes(self.alloc);
        defer {
            for (managed_indexes) |index_ref| self.alloc.free(@constCast(index_ref.name));
            self.alloc.free(managed_indexes);
        }

        var full_text_indexes = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (full_text_indexes.items) |name| self.alloc.free(@constCast(name));
            full_text_indexes.deinit(self.alloc);
        }
        var all_indexes = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (all_indexes.items) |name| self.alloc.free(@constCast(name));
            all_indexes.deinit(self.alloc);
        }

        for (managed_indexes) |index_ref| {
            switch (sync_level) {
                .propose, .write => {},
                .enrichments => {},
                .full_text => {
                    if (index_ref.kind == .full_text) {
                        try appendOwnedManagedIndexName(self.alloc, &full_text_indexes, index_ref.name);
                        try appendOwnedManagedIndexName(self.alloc, &all_indexes, index_ref.name);
                    }
                },
                .full_index => {
                    try appendOwnedManagedIndexName(self.alloc, &all_indexes, index_ref.name);
                    if (index_ref.kind == .full_text) {
                        try appendOwnedManagedIndexName(self.alloc, &full_text_indexes, index_ref.name);
                    }
                },
            }
        }

        return .{
            .full_text_indexes = try full_text_indexes.toOwnedSlice(self.alloc),
            .all_indexes = try all_indexes.toOwnedSlice(self.alloc),
        };
    }

    pub fn catchUpPendingDerivedReplay(self: *DB) !void {
        try replayPendingDerivedBatches(self, null, null, .{});
    }

    pub fn catchUpPendingDerivedReplayWithProgress(
        self: *DB,
        progress_ctx: *anyopaque,
        progress_hook: ReplayProgressHook,
    ) !void {
        try replayPendingDerivedBatches(self, progress_ctx, progress_hook, .{});
    }

    /// Appends internal derived work without exposing the DB's batch execution
    /// context. Runtime partitions use this boundary while retaining the normal
    /// write gate, locking, backlog accounting, and hot-standby mirroring semantics.
    pub fn derivedAsyncAppendDerivedBatchRecord(self: *DB, derived_batch: derived_types.DerivedBatch) !u64 {
        return try appendDerivedBatchRecord(self, derived_batch);
    }

    const run_until_idle_max_replay_rounds: usize = 16;

    fn currentMaintenanceTargetSequence(self: *DB) u64 {
        var target_sequence = self.core.nextDerivedSequence();
        if (self.enrichment_runtime) |runtime| {
            target_sequence = @max(target_sequence, runtime.stats().target_sequence);
        }
        return target_sequence;
    }

    fn resolverReplayBlockedAfterRunnableDrain(self: *DB) bool {
        const resolution_stats = self.resolutionStageStats();
        if (resolution_stats.catch_up_required and !resolution_stats.blocked) return false;
        const promotion_stats = self.promotionStageStats();
        return promotion_stats.blocked;
    }

    fn drainReplayStagesUntilStableWithOptions(self: *DB, options: ReplayDrainOptions) !void {
        var rounds: usize = 0;
        while (rounds < run_until_idle_max_replay_rounds) : (rounds += 1) {
            const starting_sequence = self.core.nextDerivedSequence();
            const starting_resolution_applied = if (self.resolution_runtime) |runtime| runtime.stats().applied_sequence else 0;
            const starting_promotion_applied = if (self.promotion_runtime) |runtime| runtime.stats().applied_sequence else 0;
            try self.runMaintenanceUntilWithOptions(self.currentMaintenanceTargetSequence(), .{}, options);
            const drained_sequence = self.core.nextDerivedSequence();

            const drain_resolver_replay = self.resolverReplayNeedsDrain();
            if (drain_resolver_replay) {
                if (self.resolution_runtime) |runtime| {
                    // nextDerivedSequence() is the highest committed sequence,
                    // not the next append sequence. Include that record when
                    // recovering a missed runtime notification.
                    if (drained_sequence > 0) runtime.notifySequence(drained_sequence);
                    try runtime.catchUp();
                }

                if (self.promotion_runtime) |runtime| {
                    const latest = self.core.nextDerivedSequence();
                    if (latest > 0) runtime.notifySequence(latest);
                    try runtime.catchUp();
                }

                // Resolution can append graph/promotion replay before
                // promotion discovers that its external sink is unavailable.
                // Drain those independent derived consumers before reporting
                // the blocked stage; otherwise runUntilIdle can return with a
                // durable resolution artifact that is absent from the graph.
                if (self.core.nextDerivedSequence() > drained_sequence) {
                    try self.runMaintenanceUntilWithOptions(self.currentMaintenanceTargetSequence(), .{}, options);
                }
                if (self.resolverReplayBlockedAfterRunnableDrain()) return;
            }

            const resolution_advanced = if (self.resolution_runtime) |runtime|
                runtime.stats().applied_sequence > starting_resolution_applied
            else
                false;
            const promotion_advanced = if (self.promotion_runtime) |runtime|
                runtime.stats().applied_sequence > starting_promotion_applied
            else
                false;
            if (self.core.nextDerivedSequence() <= starting_sequence and !resolution_advanced and !promotion_advanced) return;
        }
        return error.RunUntilIdleDidNotConverge;
    }

    /// Re-attempts opening quarantined indexes (artifacts that failed to
    /// load at open time). `force` ignores per-index backoff — used by tests
    /// and operator-triggered recovery. Runs the same detached-open path as
    /// the initial load, so a recovered full-text/sparse/graph index resumes
    /// its persisted rebuild state and catches up before registering.
    pub fn retryQuarantinedIndexLoads(self: *DB, force: bool) !index_manager_mod.IndexManager.QuarantineRetryResult {
        var publication_fence = QuarantineIndexPublicationFence{ .db = self };
        const execution_limit = if (force)
            self.core.index_manager.failedIndexLoadSummary().total
        else
            @as(usize, 8);
        return try self.core.index_manager.retryFailedIndexLoads(
            self.core.store,
            monotonicTimeNs(),
            force,
            null,
            execution_limit,
            publication_fence.iface(),
        );
    }

    /// Retry exactly one quarantined index. Ignoring backoff is orthogonal to
    /// scope: targeted rollback and operator repair must never inspect, clone,
    /// open, or publish unrelated failed indexes.
    pub fn retryQuarantinedIndexLoad(
        self: *DB,
        index_name: []const u8,
        force: bool,
    ) !index_manager_mod.IndexManager.QuarantineRetryResult {
        const failure = self.core.index_manager.failedIndexLoadSnapshot(index_name) orelse
            return .{
                .remaining = self.core.index_manager.failedIndexLoadSummary().total,
                .target_outcome = .absent,
            };
        return try self.retryQuarantinedIndexLoadTarget(.{
            .name = index_name,
            .token = failure.token,
        }, force);
    }

    fn retryQuarantinedIndexLoadTarget(
        self: *DB,
        target: index_manager_mod.IndexManager.FailedIndexLoadRetryTarget,
        force: bool,
    ) !index_manager_mod.IndexManager.QuarantineRetryResult {
        var publication_fence = QuarantineIndexPublicationFence{ .db = self };
        return try self.core.index_manager.retryFailedIndexLoads(
            self.core.store,
            monotonicTimeNs(),
            force,
            target,
            1,
            publication_fence.iface(),
        );
    }

    /// Retries a top-level portable catalog activation that failed after the
    /// durable generation commit. The restore loader rolls partial runtime
    /// state back on error. Recovery is single-flight: callers never queue a
    /// second full catalog reload behind one already in progress.
    pub fn retryPortableRuntimeActivationIfNeeded(self: *DB) !bool {
        if (!self.async_context.portable_runtime_activation_pending.load(.acquire)) return false;
        if (!self.portable_runtime_activation_mutex.tryLock()) return error.PortableRuntimeActivationPending;
        defer self.portable_runtime_activation_mutex.unlock();
        if (!self.async_context.portable_runtime_activation_pending.load(.acquire)) return false;

        _ = self.portable_runtime_activation_attempts.fetchAdd(1, .monotonic);
        self.loadPortableRuntimeAfterPublication() catch |err| {
            self.async_context.portable_runtime_activation_pending.store(true, .release);
            return err;
        };
        self.async_context.portable_runtime_activation_pending.store(false, .release);
        // Session cleanup intentionally leaves maintenance deferred while the
        // catalog is degraded. Release that deferral only after the restored
        // runtime is fully usable.
        resumeDeferredBackgroundMaintenanceIfIdle(self.async_context);
        self.startQuarantineRetryWorkerIfNeeded();
        std.log.info("portable runtime activation recovered path={s}", .{self.core.path});
        return true;
    }

    fn runArtifactRepairMetadataMaintenancePass(self: *DB) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return false;
        // The mark owns immutable primary/ANN/source leases. Scan before
        // taking apply; only setup, planning, and publication need that fence.
        if (self.local_execution.source_vectors.load(.acquire)) |source| try source.advanceMarkingSnapshot();
        return self.runArtifactRepairMetadataMaintenanceAfterScan();
    }

    fn runArtifactRepairMetadataMaintenanceAfterScan(self: *DB) !bool {
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();

        var more = try self.core.index_manager.runGraphOwnershipCleanupStep();
        more = (try self.rebuildArtifactRepairSummaryIfMissing(self.alloc)) or more;
        more = (try self.rebuildArtifactRepairKindIndexIfMissing(self.alloc)) or more;
        if (self.local_execution.source_vectors.load(.acquire)) |source| {
            const step_bytes = source.backgroundCollectionStepBytes();
            if (step_bytes != 0) {
                try self.refreshSourceVectorOwnershipScopes();
                const prior_generation = source.currentGeneration();
                if (try source.collectBackgroundStepDeferredMark(&self.core.store.runtime_store, step_bytes)) {
                    if (source.currentGeneration() != prior_generation) try self.core.index_manager.refreshSourcePayloadGeneration();
                }
                if (source.collectionPending()) more = true;
            }
        }
        return more;
    }

    pub fn runArtifactRepairMetadataMaintenanceUntilIdle(self: *DB) !void {
        while (try self.runArtifactRepairMetadataMaintenancePass()) {}
    }

    const portable_activation_retry_base_ns = portable_activation_recovery.Owner.portable_activation_retry_base_ns;
    const portable_activation_retry_max_ns = portable_activation_recovery.Owner.portable_activation_retry_max_ns;
    const artifact_repair_metadata_poll_ns: u64 = 5 * std.time.ns_per_s;
    const artifact_repair_metadata_active_poll_ns: u64 = 100 * std.time.ns_per_ms;

    // Retry deadlines and comparisons belong to the runtime's awake clock.
    // On Darwin its origin differs from POSIX MONOTONIC; borrowed runtimes
    // may also provide virtual time. Never compare these to platform clocks.
    fn independentMaintenanceNowNs(self: *DB) u64 {
        const io = self.backend_runtime.io() orelse return platform_time.monotonicNs();
        return platform_time.awakeNs(io);
    }

    /// Start only after the DB has reached its final address. DB.open returns
    /// by value, so cache owners invoke this after installing that value in a
    /// stable heap entry rather than letting an async task capture the open
    /// function's temporary stack address.
    pub fn startArtifactRepairMetadataWorkerIfNeeded(self: *DB) void {
        if (comptime builtin.single_threaded or builtin.os.tag == .freestanding) return;
        // Ordinary unit tests drive maintenance explicitly. Borrowed runtimes
        // schedule the production owner deterministically, including VOPR's
        // test-artifact runner; disabling it strands durable graph cleanup.
        if (comptime builtin.is_test) {
            if (!self.backend_runtime.usesBorrowedIo()) return;
        }
        if (!self.start_index_workers) return;
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return;
        self.independent_maintenance.start(self.independentMaintenancePort());
    }

    fn stopArtifactRepairMetadataWorker(self: *DB) void {
        self.independent_maintenance.stop(self.backend_runtime);
    }

    fn artifactRepairMetadataWorkerStep(self: *DB) ?u64 {
        return self.independent_maintenance.step(self.independentMaintenancePort());
    }

    fn independentMaintenancePort(self: *DB) independent_maintenance.Owner.Port {
        return .{ .ptr = self, .runtime = self.backend_runtime, .now = producerMaintenanceNow, .ready = independentMaintenanceReady, .run = independentMaintenanceRun, .failed = independentMaintenanceFailed, .activity = independentMaintenanceActivity };
    }
    fn independentMaintenanceReady(ptr: *anyopaque) bool {
        const self: *DB = @ptrCast(@alignCast(ptr));
        self.enforcePortableRuntimeGate() catch return false;
        return true;
    }
    fn independentMaintenanceRun(ptr: *anyopaque, work: independent_maintenance.Owner.Work) !bool {
        const self: *DB = @ptrCast(@alignCast(ptr));
        switch (work) {
            .upload => return self.advanceArtifactUploadRecoveryWithTrigger(.maintenance),
            .baseline => return self.advanceArtifactProducerBaselinePage(),
            .producer => return self.advanceArtifactProducerWorkPage(),
            .footprint => return self.advanceArtifactFootprintPage(),
            .repair => {
                try self.runArtifactRepairMaintenanceTurn();
                return false;
            },
            .column => {
                _ = try self.runRelationalColumnMaintenancePass();
                return false;
            },
            .index => {
                _ = try self.runRelationalIndexMaintenancePass();
                return false;
            },
        }
    }
    fn independentMaintenanceFailed(ptr: *anyopaque, work: independent_maintenance.Owner.Work) void {
        const self: *DB = @ptrCast(@alignCast(ptr));
        switch (work) {
            .baseline => self.artifact_producer_baseline_pending.store(false, .release),
            .footprint => self.artifact_footprint_pending.store(false, .release),
            else => unreachable,
        }
    }
    fn independentMaintenanceActivity(ptr: *anyopaque) independent_maintenance.Owner.Activity {
        const self: *DB = @ptrCast(@alignCast(ptr));
        const source = self.local_execution.source_vectors.load(.acquire);
        return .{
            .artifacts = self.artifact_repair_metadata_pending or self.artifact_footprint_pending.load(.acquire) or self.artifact_producer_baseline_pending.load(.acquire) or (if (source) |value| value.collectionPending() else false),
            .producers = self.artifact_producer_scheduler.active(self.independentMaintenanceNowNs()),
            .indexes = self.local_execution.relational_index_maintenance_sweep.isPending() and platform_time.monotonicNs() >= self.local_execution.relational_index_retry_after_ns.load(.acquire),
            .columns = self.relational_column_maintenance.pending.load(.acquire) and !self.relational_column_maintenance.backing_off.load(.acquire),
            .scan_pause_ns = if (source) |value| value.activeScanPauseNs() else null,
            .background_checkpoint = if (source) |value| value.background_checkpoint else false,
        };
    }

    /// One bounded physical-key page, never under the DB apply lock. Both
    /// discovery and the ordinary maintenance scheduler advance the same
    /// durable cursor, so large old roots do not require repeated client calls.
    pub fn advanceArtifactFootprintPage(self: *DB) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return true;
        var budget = if (self.core.index_manager.resource_manager) |manager|
            resource_manager_mod.BudgetedAllocator.init(manager, .relational_preparation_working_set, self.alloc, 1)
        else
            null;
        defer if (budget) |*value| value.deinit();
        const scratch = if (budget) |*value| value.allocator() else self.alloc;
        const complete = @import("../artifact_footprint.zig").reconcilePage(scratch, self.core.store) catch |err| {
            if (err == error.OutOfMemory) if (budget) |*value| if (value.denied()) return error.ResourceBudgetExceeded;
            return err;
        };
        self.artifact_footprint_pending.store(!complete, .release);
        return complete;
    }

    /// Discover bounded durable upload facts without payload reads. Release
    /// the storage snapshot before invoking the external scheduling owner.
    /// Admission remains a hint, never an acknowledgement or seal.
    pub fn advanceArtifactUploadRecovery(self: *DB) !bool {
        return self.advanceArtifactUploadRecoveryWithTrigger(.explicit);
    }

    fn advanceArtifactUploadRecoveryWithTrigger(self: *DB, trigger: @FieldType(@import("artifact_publication.zig").UploadRecoveryInvocation, "trigger")) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return false;
        const dispatcher = self.local_execution.artifact_publication_dispatcher orelse return false;
        const recovery = dispatcher.upload_recovery orelse return false;
        const now_ns = self.independentMaintenanceNowNs();
        if (!recovery.should_poll(dispatcher.ptr, .{ .now_ns = now_ns, .trigger = trigger })) return false;
        const inventory = blk: {
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            const namespace = (try @import("../source_authority.zig").externalPublicationNamespace(&read)) orelse return false;
            break :blk try @import("artifact_publication_transport.zig").recoveryInventory(&read, namespace);
        };
        return recovery.recover(dispatcher.ptr, .{
            .io = self.core.index_manager.checkpointIo(),
            .now_ns = now_ns,
            .inventory = inventory,
            .trigger = trigger,
        });
    }

    /// Append root-producer requests using the existing durable replay journal.
    /// The cursor is only a fairness hint: acceptance and sealing remain ordered
    /// operations, and restart can safely rediscover every unscheduled row.
    pub fn advanceArtifactProducerWorkPage(self: *DB) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return false;
        return self.artifact_producer_scheduler.advance(.{ .ptr = self, .now = producerMaintenanceNow, .page = advanceArtifactProducerBudgetedPage });
    }

    fn producerMaintenanceNow(ptr: *anyopaque) u64 {
        const self: *DB = @ptrCast(@alignCast(ptr));
        return self.independentMaintenanceNowNs();
    }

    fn advanceArtifactProducerBudgetedPage(ptr: *anyopaque) !bool {
        const self: *DB = @ptrCast(@alignCast(ptr));
        var budget = if (self.core.index_manager.resource_manager) |manager|
            resource_manager_mod.BudgetedAllocator.init(manager, .relational_preparation_working_set, self.alloc, 1)
        else
            null;
        defer if (budget) |*value| value.deinit();
        const scratch = if (budget) |*value| value.allocator() else self.alloc;
        return self.advanceArtifactProducerWorkPageWithAllocator(scratch) catch |err| {
            if (err == error.OutOfMemory) if (budget) |*value| if (value.denied()) return error.ResourceBudgetExceeded;
            return err;
        };
    }

    fn refreshArtifactProjections(self: *DB, scratch: Allocator, document: []const u8, plan: *const index_manager_mod.IndexManager.WritePlanSnapshot, limits: @import("artifact_completion_progress.zig").Limits) !void {
        const completion = @import("artifact_completion_progress.zig");
        var requests: completion.AdoptionRequests = .{};
        try completion.refreshProjectionsWithAdoption(scratch, self.core.store, self.core.index_manager, self.core.applied_sequence_checkpoint_path, self.root_incarnation, document, plan, limits, &requests);
        if (requests.count == 0) return;
        // Use the revision-tracked scheduler directory for O(1) deduplication,
        // not a checkpoint-file scan per document. Creation still performs its
        // durable CAS. Existing paused/terminal jobs retain their semantics.
        try self.ensureIndexRepairSchedulerDirectory(scratch);
        const compiled = if (plan.completion_plan) |*value| value else return error.ArtifactCatalogDrift;
        for (requests.ordinals[0..requests.count]) |ordinal| {
            const node = &compiled.nodes[ordinal];
            lockAtomic(&self.async_context.index_repair_scheduler_mutex);
            const existing = self.async_context.index_repair_scheduler.initialized and
                self.async_context.index_repair_scheduler.containsName(node.name);
            self.async_context.index_repair_scheduler_mutex.unlock();
            if (existing) continue;
            var structural = self.beginIndexStructuralMutation("artifact baseline adoption", node.name);
            defer structural.deinit();
            try self.lockApplyForPortableRuntime();
            defer self.core.unlockApply();
            {
                var read = try self.core.store.beginReadTxn();
                defer read.abort();
                const catalogs = try @import("artifact_inventory.zig").catalogs(&read);
                if (!plan.matchesArtifactInventory(catalogs)) return error.ArtifactCatalogDrift;
                const active = (try @import("artifact_publication.zig").authority(&read)) orelse return error.ArtifactCatalogDrift;
                if (!std.meta.eql(active, requests.authority.?) or !std.mem.eql(u8, &active.catalog_digest, &catalogs.digest())) return error.ArtifactCatalogDrift;
            }
            const cfg = self.core.index_manager.get(node.name) orelse return error.ArtifactCatalogDrift;
            if (cfg.kind != .full_text or cfg.coverage_generation != node.generation) return error.ArtifactCatalogDrift;
            _ = try self.createGenerationRepairIntent(scratch, cfg.*, .artifact_baseline_adoption, 0, 0, null);
            return;
        }
    }

    fn enqueueArtifactCompletion(self: *DB, scratch: Allocator, document: []const u8, plan: *const index_manager_mod.IndexManager.WritePlanSnapshot) !void {
        const dispatcher = self.local_execution.artifact_publication_dispatcher orelse return;
        try self.refreshArtifactProjections(scratch, document, plan, .{});
        var encoded: ?[]u8 = null;
        defer if (encoded) |bytes| scratch.free(bytes);
        var namespace: @import("artifact_publication.zig").Namespace = undefined;
        var action: ?@import("artifact_completion_progress.zig").NextAction = null;
        defer if (action) |*value| value.deinit();
        var jobs: ?@import("artifact_unit_jobs.zig").Admission = null;
        defer if (jobs) |*value| value.deinit();
        {
            var read = try self.core.store.beginReadTxnWithBlockCacheAdmission(.transient);
            defer read.abort();
            const owner = (try @import("../source_authority.zig").publicationOwner(&read)) orelse return error.ArtifactCatalogDrift;
            if (owner.mode != .ordered) return;
            action = (try @import("artifact_completion_progress.zig").discoverNextAction(scratch, &read, self.root_incarnation, document, plan, .{})) orelse return;
            switch (action.?) {
                .control => |*prepared| {
                    const command = try prepared.command();
                    namespace = command.namespace;
                    encoded = try @import("artifact_publication_transport_codec.zig").encodeAlloc(scratch, command);
                },
                .jobs => |*page| jobs = try @import("artifact_unit_jobs.zig").prepare(scratch, &read, self.root_incarnation, page, .{}),
            }
        }
        if (jobs) |*admission| {
            _ = self.admitArtifactUnitJobs(admission) catch |err| switch (err) {
                // Scope-local headroom must not pin the document sweep. No
                // cursor/job/wakeup committed on refusal; the next metadata
                // round retries after workers have had a chance to drain it.
                error.ResourceBudgetExceeded => return,
                else => return err,
            };
            return;
        }
        // Queue admission does not discharge work or spin the scheduler.
        // Receiver acceptance and the metadata poll drive the next prefix.
        try dispatcher.submit(namespace, encoded.?);
    }

    /// One bounded receiver-local pass over a document's scoped outbox. Only
    /// accepted or obsolete receipts retire jobs; pending callbacks retain
    /// their slots. The pinned read is gone before the writer fence; the
    /// immutable plan remains pinned for the maintenance turn.
    pub fn advanceArtifactUnitReceiptPage(self: *DB, scratch: Allocator, document: []const u8, plan: *const index_manager_mod.IndexManager.WritePlanSnapshot) !bool {
        const unit_jobs = @import("artifact_unit_jobs.zig");
        var document_turn: ?unit_jobs.DocumentTurn = null;
        var work: ?unit_jobs.WorkTurn = null;
        defer if (work) |*turn| turn.deinit();
        var retirements: std.ArrayListUnmanaged(unit_jobs.Retirement) = .empty;
        defer {
            for (retirements.items) |*retirement| retirement.deinit();
            retirements.deinit(scratch);
        }
        {
            var read = try self.core.store.beginReadTxnWithBlockCacheAdmission(.transient);
            defer read.abort();
            document_turn = try unit_jobs.prepareDocumentTurn(&read, self.root_incarnation, document);
            const turn = document_turn orelse return false;
            if (turn.selected) |selected| {
                work = try unit_jobs.prepareTurn(scratch, &read, self.root_incarnation, selected, .{ .visits = 8 });
            }
            if (work != null and work.?.page.items.len != 0) {
                const child = work.?.page.items[0].job.child;
                if (unit_jobs.retirementSession(scratch, &read, self.root_incarnation, document, child, plan)) |session_value| {
                    var session = session_value;
                    defer session.deinit();
                    for (work.?.page.items) |item| {
                        if (!std.mem.eql(u8, item.job.document, document) or !std.mem.eql(u8, item.job.child, child)) return error.ArtifactCatalogCorrupt;
                        if (try session.preparePageItem(scratch, item)) |prepared| {
                            var retirement = prepared;
                            errdefer retirement.deinit();
                            try retirements.append(scratch, retirement);
                        }
                    }
                } else |err| switch (err) {
                    error.ArtifactPublicationPending, error.EnrichmentSourceChanged => {},
                    else => return err,
                }
            }
        }
        const pointers = try scratch.alloc(*const unit_jobs.Retirement, retirements.items.len);
        defer scratch.free(pointers);
        for (retirements.items, pointers) |*retirement, *pointer| pointer.* = retirement;
        const work_ptr: ?*const unit_jobs.WorkTurn = if (work) |*turn| turn else null;
        try self.finishArtifactUnitWorkPage(&document_turn.?, work_ptr, pointers);
        return true;
    }

    fn advanceArtifactProducerWorkPageWithAllocator(self: *DB, scratch: Allocator) !bool {
        var plan = try self.core.index_manager.acquireWritePlanSnapshot();
        defer plan.release();
        const obligations = @import("artifact_producer_obligations.zig");
        var page = blk: {
            var read = try self.core.store.beginReadTxnWithBlockCacheAdmission(.transient);
            defer read.abort();
            const authority = (try @import("artifact_publication.zig").authority(&read)) orelse return false;
            // Protocol-14 owners have no required-stream work registry.
            const state = (try obligations.load(&read)) orelse {
                var ordered = (try @import("artifact_inventory.zig").load(scratch, &read)) orelse return error.ArtifactCatalogDrift;
                defer ordered.deinit();
                if (ordered.value.command.binding.effect_protocol >= 15) return error.ArtifactCatalogCorrupt;
                return false;
            };
            try state.requireAuthority(authority);
            if (state.sealed_attempt != null) return false;
            const catalogs = try @import("artifact_inventory.zig").catalogs(&read);
            if (!plan.plan().matchesArtifactInventory(catalogs) or !std.mem.eql(u8, &catalogs.digest(), &authority.catalog_digest)) return error.ArtifactCatalogDrift;
            const cursor = self.artifact_producer_scheduler.cursorForAuthority(self.alloc, authority);
            break :blk try obligations.scanWork(scratch, &read, authority, cursor);
        };
        defer page.deinit();
        const dispatch = @import("artifact_producer_dispatch.zig");
        const retry = @import("artifact_producer_retry.zig");
        const retry_now = self.independentMaintenanceNowNs();
        self.artifact_producer_scheduler.observeAuthority(page.authority);
        const retry_real_now: u64 = @intCast(@max(0, std.Io.Timestamp.now(self.core.index_manager.checkpointIo(), .real).toNanoseconds()));
        // Persisted wall time selects retries only. It prevents cold-owner
        // churn from restarting the grace period forever; runtime deadlines
        // still use the owner's awake clock and cannot discharge any work.
        if (self.artifact_producer_scheduler.needsRetryDelay()) {
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            self.artifact_producer_scheduler.setRetryDelay(retry_now, try obligations.retryDelay(&read, page.authority, retry_real_now, retry.interval_ns));
        }
        if (self.artifact_producer_scheduler.needsRetryRound(retry_now, page.items.len != 0, plan.plan().generated_templates.len != 0)) {
            try self.lockApplyForPortableRuntime();
            defer self.core.unlockApply();
            var txn = try self.core.store.beginWriteTxn();
            errdefer txn.abort();
            const round = try obligations.beginRetryRoundAt(&txn, page.authority, retry_real_now);
            try txn.commit();
            self.artifact_producer_scheduler.startRound(page.authority, round);
        }
        var refs: dispatch.Buffer = undefined;
        const deadline = platform_time.monotonicNs() +| @import("artifact_producer_scheduler.zig").Scheduler.quantum_ns;
        var processed: usize = 0;
        var more_dispatch = false;
        for (page.items) |item| {
            if (processed != 0 and platform_time.monotonicNs() >= deadline) break;
            // Allocate the next fairness cursor before committing, so allocation
            // failure cannot strand an admitted request behind a stale cursor.
            const next = try self.alloc.dupe(u8, item.document);
            errdefer self.alloc.free(next);
            // Native verification is local, resumable evidence, not discharge.
            // It also runs for catalogs with no generated provider templates.
            const native_progress = try @import("artifact_native_stream.zig").advance(scratch, self.core.store, self.root_incarnation, item.document, plan.plan());
            more_dispatch = more_dispatch or native_progress == .progress;
            if (native_progress == .closed) {
                _ = try self.advanceArtifactUnitReceiptPage(scratch, item.document, plan.plan());
                try self.enqueueArtifactCompletion(scratch, item.document, plan.plan());
            }
            if (!item.dispatch_complete and plan.plan().generated_templates.len != 0) {
                const requests = try dispatch.prepare(plan.plan().generated_templates, item.next_template, item.document, &refs);
                var ctx = self.batchContext();
                _ = try appendDerivedBatchRecordContextWithWork(&ctx, .{ .generated_enrichment_refs = requests.items }, false, .{
                    .authority = page.authority,
                    .item = item,
                    .plan_generation = plan.generation(),
                    .page = requests.progress,
                });
                more_dispatch = more_dispatch or !requests.progress.complete;
            }
            if (self.artifact_producer_scheduler.retryPage(item, plan.plan().generated_templates.len != 0)) |round| {
                const requests = blk: {
                    var read = try self.core.store.beginReadTxnWithBlockCacheAdmission(.transient);
                    defer read.abort();
                    break :blk try retry.prepare(scratch, &read, self.root_incarnation, plan.plan(), round.first_template, item.document, &refs);
                };
                const required: RequiredProducerDispatch = .{ .authority = page.authority, .item = item, .plan_generation = plan.generation(), .page = requests.progress, .retry_round = round.number };
                if (requests.items.len != 0) {
                    var ctx = self.batchContext();
                    _ = try appendDerivedBatchRecordContextWithWork(&ctx, .{ .generated_enrichment_refs = requests.items }, false, required);
                } else {
                    // No empty replay record for an already accepted page.
                    // This advances scheduling only, not completion credit.
                    try self.lockApplyForPortableRuntime();
                    defer self.core.unlockApply();
                    if (self.core.index_manager.writePlanGeneration() != required.plan_generation) return error.EnrichmentSourceChanged;
                    var txn = try self.core.store.beginWriteTxn();
                    errdefer txn.abort();
                    if (!try obligations.stageRetry(scratch, &txn, page.authority, item, round.number, null, requests.progress)) return error.EnrichmentSourceChanged;
                    try txn.commit();
                }
                self.artifact_producer_scheduler.noteRetryProgress(requests.progress.complete);
            }
            self.artifact_producer_scheduler.commitCursor(self.alloc, page.authority, next);
            processed += 1;
        }
        self.artifact_producer_scheduler.completePage(self.alloc, processed == page.items.len and page.at_end, more_dispatch, self.independentMaintenanceNowNs());
        return processed != 0;
    }

    /// Persist scoped jobs and their document wakeup atomically. The thin
    /// journal is only a wakeup: exact child/unit/generation identities remain
    /// in the root-local outbox until receipt-checked retirement.
    pub fn admitArtifactUnitJobs(self: *DB, admission: *const @import("artifact_unit_jobs.zig").Admission) !u64 {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        if (admission.root != self.root_incarnation) return error.DurableRootIncarnationUnavailable;
        var plan = try self.core.index_manager.acquireWritePlanSnapshot();
        defer plan.release();
        const completion = if (plan.plan().completion_plan) |*value| value else return error.ArtifactCatalogDrift;
        const child = try completion.unitChild(admission.page.child);
        const ordinal = child.parent_template orelse return error.ArtifactPublicationPending;
        if (ordinal >= plan.plan().generated_templates.len) return error.ArtifactCatalogDrift;
        var ctx = self.batchContext();
        if (admission.jobs.len == 0) {
            // Accepted/metadata-only pages need no provider wakeup or empty
            // replay record. Apply the same authority and snapshot fences.
            var replication_mutation = acquireReplicationMutationSharedContext(&ctx);
            defer if (replication_mutation) |*lease| lease.release();
            try enforceReplicationWriteGateOptional(ctx.replication_write_gate);
            var snapshot_replay = try acquireSnapshotReplayContext(&ctx);
            defer if (snapshot_replay) |*lease| lease.release();
            try lockApplyForPortableRuntimeContext(&ctx);
            defer ctx.apply_mutex.unlockExclusive();
            if (ctx.index_manager.writePlanGeneration() != plan.generation()) return error.EnrichmentSourceChanged;
            var writer = try self.core.store.beginWriteTxn();
            errdefer writer.abort();
            _ = try admission.stage(&writer, self.root_incarnation);
            try writer.commit();
            return 0;
        }
        const parent = plan.plan().generated_templates[ordinal];
        const wake: enrichment_types.GeneratedEnrichmentRef = .{ .kind = parent.kind, .index_name = parent.index_name, .artifact_name = parent.artifact_name, .embedding_name = parent.embedding_name, .doc_key = admission.page.document };
        const sequence = try appendDerivedBatchRecordContextWithAdmissions(&ctx, .{ .generated_enrichment_refs = (&wake)[0..1] }, false, null, .{ .admission = admission, .root = self.root_incarnation, .plan_generation = plan.generation() });
        self.executor.notifySequence(sequence);
        if (self.enrichment_runtime) |runtime| runtime.notifySequence(sequence);
        return sequence;
    }

    /// Retire only receiver-verified work; callback submission is not an ack.
    /// This changes local scheduling metadata, not replay or stream completion.
    pub fn retireArtifactUnitJob(self: *DB, retirement: *const @import("artifact_unit_jobs.zig").Retirement) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var ctx = self.batchContext();
        var replication_mutation = acquireReplicationMutationSharedContext(&ctx);
        defer if (replication_mutation) |*lease| lease.release();
        try enforceReplicationWriteGateOptional(ctx.replication_write_gate);
        var snapshot_replay = try acquireSnapshotReplayContext(&ctx);
        defer if (snapshot_replay) |*lease| lease.release();
        try lockApplyForPortableRuntimeContext(&ctx);
        defer ctx.apply_mutex.unlockExclusive();
        var writer = try self.core.store.beginWriteTxn();
        errdefer writer.abort();
        const retired = try retirement.stage(&writer, self.root_incarnation);
        try writer.commit();
        return retired;
    }

    /// Advance the fair worker continuation without acknowledging any job.
    /// The turn owns its scan results; no provider runs under this write gate.
    pub fn advanceArtifactUnitWorkTurn(self: *DB, turn: *const @import("artifact_unit_jobs.zig").WorkTurn) !void {
        return self.finishArtifactUnitWorkTurn(null, turn);
    }

    /// Commit sibling and within-child fairness together after a bounded
    /// attempt. A refused/canceled child may advance only the document cursor;
    /// neither cursor acknowledges a producer result or releases job headroom.
    pub fn finishArtifactUnitWorkTurn(self: *DB, document: ?*const @import("artifact_unit_jobs.zig").DocumentTurn, work: ?*const @import("artifact_unit_jobs.zig").WorkTurn) !void {
        return self.finishArtifactUnitWorkPage(document, work, &.{});
    }

    /// One durable worker checkpoint: fair continuations and receiver-verified
    /// receipts commit together. A callback outcome alone cannot enter this
    /// list; every retirement carries its own current accepted-result fence.
    pub fn finishArtifactUnitWorkPage(self: *DB, document: ?*const @import("artifact_unit_jobs.zig").DocumentTurn, work: ?*const @import("artifact_unit_jobs.zig").WorkTurn, retirements: []const *const @import("artifact_unit_jobs.zig").Retirement) !void {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        if (document == null and work == null and retirements.len == 0) return error.InvalidBatchRequest;
        if (retirements.len > 128) return error.InvalidBatchRequest;
        if (document) |selected| if (work) |turn| {
            if (selected.selected == null or !std.mem.eql(u8, &selected.selected.?, &turn.selected)) return error.InvalidBatchRequest;
        };
        for (retirements) |retirement| {
            if (retirement.root != self.root_incarnation) return error.DurableRootIncarnationUnavailable;
            if (!std.mem.eql(u8, &retirement.selected, &retirements[0].selected) or
                !std.mem.eql(u8, &retirement.document_scope, &retirements[0].document_scope)) return error.InvalidBatchRequest;
            if (work) |turn| if (!std.mem.eql(u8, &retirement.selected, &turn.selected)) return error.InvalidBatchRequest;
            if (document) |turn| {
                if (turn.selected == null or !std.mem.eql(u8, &retirement.selected, &turn.selected.?) or
                    !std.mem.eql(u8, &retirement.document_scope, &turn.document)) return error.InvalidBatchRequest;
            }
        }
        var ctx = self.batchContext();
        var replication_mutation = acquireReplicationMutationSharedContext(&ctx);
        defer if (replication_mutation) |*lease| lease.release();
        try enforceReplicationWriteGateOptional(ctx.replication_write_gate);
        var snapshot_replay = try acquireSnapshotReplayContext(&ctx);
        defer if (snapshot_replay) |*lease| lease.release();
        try lockApplyForPortableRuntimeContext(&ctx);
        defer ctx.apply_mutex.unlockExclusive();
        var writer = try self.core.store.beginWriteTxn();
        errdefer writer.abort();
        if (work) |turn| _ = try turn.stage(&writer, self.root_incarnation);
        if (document) |turn| try turn.stage(&writer, self.root_incarnation);
        for (retirements) |retirement| _ = try retirement.stage(&writer, self.root_incarnation);
        try writer.commit();
    }

    pub fn advanceArtifactProducerBaselinePage(self: *DB) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return true;
        var budget = if (self.core.index_manager.resource_manager) |manager|
            resource_manager_mod.BudgetedAllocator.init(manager, .relational_preparation_working_set, self.alloc, 1)
        else
            null;
        defer if (budget) |*value| value.deinit();
        const scratch = if (budget) |*value| value.allocator() else self.alloc;
        return self.advanceArtifactProducerBaselinePageWithAllocator(scratch) catch |err| {
            if (err == error.OutOfMemory) if (budget) |*value| if (value.denied()) return error.ResourceBudgetExceeded;
            return err;
        };
    }

    fn advanceArtifactProducerBaselinePageWithAllocator(self: *DB, scratch: Allocator) !bool {
        const publication_mode = blk: {
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            if (try @import("artifact_publication.zig").authority(&read) == null) {
                self.artifact_producer_baseline_pending.store(false, .release);
                return true;
            }
            const owner = (try @import("../source_authority.zig").publicationOwner(&read)) orelse return error.ArtifactCatalogDrift;
            break :blk owner.mode;
        };
        const retired_work = try @import("artifact_producer_obligations.zig").collectObsoleteWorkPage(scratch, self.core.store);
        const retired_proofs = try @import("artifact_producer_provenance.zig").collectObsoletePage(scratch, self.core.store);
        const retired_checkpoints = try @import("artifact_stream_checkpoint.zig").collectObsoletePage(scratch, self.core.store, self.root_incarnation);
        const retired_streams = try @import("artifact_stream_progress.zig").collectObsoletePage(scratch, self.core.store, self.root_incarnation);
        const retired_completions = try @import("artifact_completion_progress.zig").collectObsoletePage(scratch, self.core.store, self.root_incarnation);
        const retired_native = try @import("artifact_native_stream.zig").collectObsoletePage(scratch, self.core.store, self.root_incarnation);
        const retired_inventories = try @import("artifact_chunk_inventory_progress.zig").collectObsoletePage(scratch, self.core.store, self.root_incarnation);
        const retired_units = try @import("artifact_unit_progress.zig").collectObsoletePage(scratch, self.core.store, self.root_incarnation);
        const retired_unit_jobs = try @import("artifact_unit_jobs.zig").collectObsoletePage(scratch, self.core.store, self.root_incarnation);
        const retired_authored = try @import("artifact_authored_acceptance.zig").collectObsoletePage(scratch, self.core.store, self.root_incarnation);
        const swept_authored = try @import("artifact_authored_acceptance.zig").collectCurrentPage(scratch, self.core.store, self.root_incarnation);
        const retired = retired_work and retired_proofs and retired_checkpoints and retired_streams and retired_completions and retired_native and retired_inventories and retired_units and retired_unit_jobs and retired_authored and swept_authored;
        if (publication_mode == .ordered) {
            var prepared = (try @import("artifact_producer_baseline.zig").prepareRaft(scratch, self.core.store)) orelse {
                var validation = (try @import("artifact_producer_validation.zig").prepareRaft(scratch, self.core.store)) orelse {
                    self.artifact_producer_baseline_pending.store(!retired, .release);
                    return retired;
                };
                defer validation.deinit();
                const dispatcher = self.local_execution.artifact_publication_dispatcher orelse {
                    self.artifact_producer_baseline_pending.store(!retired, .release);
                    return false;
                };
                const encoded = try @import("artifact_publication_transport_codec.zig").encodeAlloc(scratch, validation.command);
                defer scratch.free(encoded);
                try dispatcher.enqueue(dispatcher.ptr, validation.command.namespace, encoded);
                self.artifact_producer_baseline_pending.store(true, .release);
                return false;
            };
            defer prepared.deinit();
            const dispatcher = self.local_execution.artifact_publication_dispatcher orelse {
                self.artifact_producer_baseline_pending.store(!retired, .release);
                return false;
            };
            const encoded = try @import("artifact_publication_transport_codec.zig").encodeAlloc(scratch, prepared.command);
            defer scratch.free(encoded);
            try dispatcher.enqueue(dispatcher.ptr, prepared.command.namespace, encoded);
            // Queue admission is not a baseline certificate. The next pass
            // observes only progress installed by the replicated transaction.
            self.artifact_producer_baseline_pending.store(true, .release);
            return false;
        }
        const complete = try @import("artifact_producer_baseline.zig").page(scratch, self.core.store);
        self.artifact_producer_baseline_pending.store(!complete or !retired, .release);
        return complete and retired;
    }

    /// Fair bounded dispatch on the existing std.Io maintenance scheduler.
    /// Never scan every catalog entry or finish an entire index in one turn.
    pub fn runRelationalIndexMaintenancePass(self: *DB) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return false;
        if (self.independent_maintenance.stopping.load(.acquire)) return error.Canceled;
        const started = platform_time.monotonicNs();
        if (started < self.local_execution.relational_index_retry_after_ns.load(.acquire)) return false;
        const sweep = &self.local_execution.relational_index_maintenance_sweep;
        if (!sweep.enter()) return false;
        defer sweep.leave();
        errdefer {
            sweep.failed();
            self.local_execution.relational_index_retry_after_ns.store(platform_time.monotonicNs() +| artifact_repair_metadata_poll_ns, .release);
        }
        const validated = try self.validateConstraintsStep(.{});
        var pinned = self.core.relational_indexes.acquire() orelse {
            sweep.empty(validated);
            return validated;
        };
        defer pinned.deinit();
        const collected = try self.collectRelationalIndexGarbageStep();
        const indexes = pinned.plan.boundIndexes();
        sweep.begin(pinned.head, self.core.schemaNamespaceGeneration(), indexes.len);
        if (indexes.len == 0) {
            sweep.empty(collected or validated);
            return collected or validated;
        }
        for (0..@min(indexes.len, 16)) |_| {
            const next = sweep.next() orelse break;
            const name = indexes[next].name;
            if ((try self.relationalIndexBuildStatus(name)).state == .building) {
                try self.buildRelationalIndexStep(name, .{});
                sweep.finish(true);
                return true;
            }
            if (platform_time.monotonicNs() -| started >= 5 * std.time.ns_per_ms) {
                sweep.finish(collected or validated);
                return false;
            }
        }
        sweep.finish(collected or validated);
        return collected or validated;
    }

    pub fn runRelationalColumnMaintenancePass(self: *DB) !usize {
        const started = self.independentMaintenanceNowNs();
        // Artifact repair can keep the shared worker on its active cadence;
        // enforce columnar backoff independently of that worker's sleep.
        if (started < self.relational_column_maintenance.retry_after_ns.load(.acquire)) return 0;
        var completed: usize = 0;
        while (completed < 8) : (completed += 1) {
            const changed = self.rebuildRelationalColumnsWithPolicy(true) catch |err| {
                // Resource pressure backs off to the idle cadence; it must not
                // create a 100 ms retry storm or masquerade as a clean table.
                self.relational_column_maintenance.notePending(true);
                self.relational_column_maintenance.backing_off.store(true, .release);
                self.relational_column_maintenance.retry_after_ns.store(self.independentMaintenanceNowNs() +| artifact_repair_metadata_poll_ns, .release);
                return err;
            };
            if (!changed) break;
            if (self.independentMaintenanceNowNs() -| started >= 50 * std.time.ns_per_ms) return completed + 1;
        }
        return completed;
    }

    /// Build disposable table-owned column blocks without holding the apply
    /// lock. The store's atomic primary-mutation fence governs publication.
    pub fn rebuildRelationalColumns(self: *DB) !bool {
        return self.rebuildRelationalColumnsWithPolicy(false);
    }

    fn rebuildRelationalColumnsWithPolicy(self: *DB, adaptive: bool) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return false;
        if (self.independent_maintenance.stopping.load(.acquire)) return error.Canceled;
        var view = self.core.acquireSchemaView() orelse return false;
        defer view.release();
        if (view.storageMode() != .relational) return false;
        if (self.relational_columns_building.swap(true, .acq_rel)) return false;
        defer self.relational_columns_building.store(false, .release);
        const started = self.independentMaintenanceNowNs();
        _ = self.relational_column_maintenance.passes.fetchAdd(1, .monotonic);
        defer self.relational_column_maintenance.last_pass_ns.store(self.independentMaintenanceNowNs() -| started, .monotonic);
        errdefer _ = self.relational_column_maintenance.failures.fetchAdd(1, .monotonic);
        var preparation: RequestPreparationContext = undefined;
        preparation.init(self);
        defer preparation.deinit();
        const force = self.relational_columns_rebuild_requested.swap(false, .acq_rel);
        errdefer if (force) self.relational_columns_rebuild_requested.store(true, .release);
        const changed = relational_columns.rebuild(self, preparation.guard.allocator(), force, adaptive) catch |err| {
            switch (err) {
                error.InvalidColumnSegment, error.InvalidData, error.NotFound => self.relational_columns_rebuild_requested.store(true, .release),
                else => {},
            }
            return preparation.mapError(err);
        };
        self.relational_column_maintenance.notePending(changed or self.relational_column_maintenance.waiting_until_ns.load(.acquire) != 0);
        self.relational_column_maintenance.backing_off.store(false, .release);
        self.relational_column_maintenance.retry_after_ns.store(0, .release);
        return changed;
    }

    fn portableActivationRecoveryPort(self: *DB) portable_activation_recovery.Owner.Port {
        return .{
            .ptr = self,
            .path = self.core.path,
            .runtime = self.backend_runtime,
            .owner_id = self.backend_owner_id,
            .pending = &self.async_context.portable_runtime_activation_pending,
            .retry = retryPortableActivationFromOwner,
            .before_start = if (builtin.is_test) portableActivationBeforeStartForTest else null,
            .refuse_launch = if (builtin.is_test) portableActivationRefuseLaunchForTest else null,
        };
    }

    fn retryPortableActivationFromOwner(ptr: *anyopaque) !bool {
        const self: *DB = @ptrCast(@alignCast(ptr));
        return self.retryPortableRuntimeActivationIfNeeded();
    }

    fn portableActivationBeforeStartForTest(ptr: *anyopaque) void {
        const self: *DB = @ptrCast(@alignCast(ptr));
        if (test_pause_portable_activation_retry_probe_before_lifecycle_lock.load(.acquire)) {
            test_portable_activation_retry_probe_paused.store(true, .release);
            const io = self.backend_runtime.io() orelse std.Options.debug_io;
            while (!test_release_portable_activation_retry_probe.load(.acquire))
                io.sleep(.fromMilliseconds(1), .awake) catch {};
        }
    }

    fn portableActivationRefuseLaunchForTest(_: *anyopaque) bool {
        return test_fail_portable_activation_retry_fallback_submit.swap(false, .acq_rel);
    }

    fn startPortableActivationRetryWorkerIfNeeded(self: *DB) void {
        self.startPortableActivationRetryWorkerIfNeededInner(false);
    }

    fn startPortableActivationRetryWorkerIfNeededInner(self: *DB, allow_test_background: bool) void {
        if (comptime builtin.single_threaded or builtin.os.tag == .freestanding) return;
        if (comptime builtin.is_test) {
            if (!allow_test_background) return;
        }
        self.portable_activation_recovery.start(self.portableActivationRecoveryPort());
    }

    fn launchPortableActivationRetryWorkerLocked(self: *DB) !portable_activation_recovery.Owner.PortableActivationRetryLaunch {
        self.portable_activation_recovery.port = self.portableActivationRecoveryPort();
        self.portable_activation_recovery.bound = true;
        return self.portable_activation_recovery.launchPortableActivationRetryWorkerLocked();
    }

    fn stopPortableActivationRetryWorker(self: *DB) void {
        self.portable_activation_recovery.stop(self.portableActivationRecoveryPort());
    }

    const portableActivationRetryDelayNs = portable_activation_recovery.Owner.portableActivationRetryDelayNs;

    fn runArtifactRepairMaintenanceTurn(self: *DB) !void {
        if (self.local_execution.source_vectors.load(.acquire)) |source| try source.checkpointMaintenance();
        const independent = if (self.local_execution.source_vectors.load(.acquire)) |source| source.independent_scan else false;
        const now = self.independentMaintenanceNowNs();
        if (!independent or now >= self.artifact_repair_metadata_due_ns)
            self.artifact_repair_metadata_pending = self.artifactRepairMetadataRebuildPending();
        if (independent) {
            const source = self.local_execution.source_vectors.load(.acquire).?;
            try source.advanceMarkingSnapshot();
            // Immutable scan turns bypass apply/catalog work until metadata
            // is due. State survives scheduler yields, not a pinned thread.
            if (now >= self.artifact_repair_metadata_due_ns or !source.continueScanWithoutApply()) {
                self.artifact_repair_metadata_due_ns = now +| artifact_repair_metadata_active_poll_ns;
                self.artifact_repair_metadata_pending = try self.runArtifactRepairMetadataMaintenanceAfterScan();
            }
        } else {
            self.artifact_repair_metadata_pending = try self.runArtifactRepairMetadataMaintenancePass();
        }
    }

    /// Start only after the DB has reached its final address. The scheduler
    /// registration retains `self` until its stop/join boundary.
    pub fn startQuarantineRetryWorkerIfNeeded(self: *DB) void {
        if (comptime !builtin.is_test and (builtin.single_threaded or builtin.os.tag == .freestanding)) return;
        if (!builtin.is_test and (!self.local_execution.optional_runtime_workers_enabled or self.open_mode != .writer)) return;
        self.quarantine_recovery.start(.{
            .ptr = self,
            .runtime = self.backend_runtime,
            .has_failures = quarantineHasFailures,
            .retry = retryQuarantineFromOwner,
        });
    }

    fn quarantineHasFailures(ptr: *anyopaque) bool {
        const self: *DB = @ptrCast(@alignCast(ptr));
        return self.core.index_manager.hasLoadFailures();
    }

    fn retryQuarantineFromOwner(ptr: *anyopaque) !usize {
        const self: *DB = @ptrCast(@alignCast(ptr));
        return (try self.retryQuarantinedIndexLoads(false)).remaining;
    }

    pub fn quarantineRetryWorkerStartedAtCurrentAddressForTest(self: *const DB) bool {
        return builtin.is_test and self.quarantine_recovery.start_address_for_test == @intFromPtr(self);
    }

    fn stopQuarantineRetryWorker(self: *DB) void {
        self.quarantine_recovery.stop(self.backend_runtime);
    }

    fn runRestoreRepairDrainAsync(self: *DB) !void {
        // Generated enrichment replay is asynchronous with respect to the
        // replay append performed by the preceding repair phase. The restore
        // completion marker is also the query-readiness barrier, so drain all
        // replay stages to a stable sequence before publishing it. Keep
        // posting, text-merge, artifact-metadata, and LSM maintenance outside
        // this barrier; those can continue in the background without hiding
        // logically restored query results.
        if (self.enrichment_runtime) |runtime| {
            const before = runtime.stats();
            std.log.info("restore runtime repair enrichment drain begin path={s} applied={d} target={d} processed={d} skipped={d}", .{
                self.core.path,
                before.applied_sequence,
                before.target_sequence,
                before.processed_requests,
                before.skip_by_hash_count,
            });
        }
        // Do not truncate the replay journal here: subsequent restore repair
        // phases still use its durable target to prove derived-state coverage.
        try self.drainReplayStagesUntilStableWithOptions(.{
            .truncate_replay = false,
            .wait_for_enrichment_retries = true,
        });
        if (self.enrichment_runtime) |runtime| {
            const after = runtime.stats();
            std.log.info("restore runtime repair enrichment drain complete path={s} applied={d} target={d} processed={d} skipped={d} errors={d}", .{
                self.core.path,
                after.applied_sequence,
                after.target_sequence,
                after.processed_requests,
                after.skip_by_hash_count,
                after.error_count,
            });
        }
        try self.flushAppliedSequencesForIdle();
    }

    fn runUntilIdleWithReplayDrainOptions(self: *DB, options: ReplayDrainOptions) !void {
        _ = try self.retryPortableRuntimeActivationIfNeeded();
        try self.drainReplayStagesUntilStableWithOptions(options);
        _ = try self.evaluateAlgebraicAdaptiveCandidates();
        while (try self.runAlgebraicAdaptiveWork() != 0) {}
        try self.flushAppliedSequencesForIdle();
        try self.drainScheduledTextMerges();
        try self.runArtifactRepairMetadataMaintenanceUntilIdle();
        // Preserve the ordinary bounded maintenance pass at the lifecycle
        // boundary: besides posting repair it advances tree-link repair,
        // posting checkpoints, and quiescent vector-block publication.
        _ = try self.runDensePostingMaintenanceForIdle();
        _ = try self.runGraphMetricMaintenanceForIdle();
        _ = try self.drainDensePostingMaintenanceForIdle();
        // This is a caller-proven stable writer boundary. Publish the native
        // exact-vector generation here rather than depending on a later live
        // write-cache maintenance tick; read-only restarts otherwise have no
        // resident writer after startup catch-up retires its short-lived DB.
        _ = try self.publishVectorBlockBasesAtStableTip();
        // Publishing the shared vector generation changes the exact-vector
        // residency policy. Recheck posting debt before advertising idle so
        // no deferred centroid/payload work escapes into the first query.
        _ = try self.drainDensePostingMaintenanceForIdle();
        // Dense WAL coverage is the hot-path applied watermark. Persist the
        // human-facing catalog snapshot once at an explicit idle boundary,
        // then let the normal LSM idle drain include this small control write.
        _ = try finalizeCoveredDenseProjectionCheckpointsIfIdle(self.async_context);
        try self.saveAllLiveIndexStatusSnapshots(self.alloc);
        _ = try self.runLsmMaintenanceUntilIdle();
    }

    pub fn runGraphMetricMaintenanceForIdle(self: *DB) !usize {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        while (true) {
            lockApply(self);
            if (!self.core.index_manager.graphRetirementAdmissionOpen()) {
                self.core.unlockApply();
                return error.IntegrityTopologyBusy;
            }
            const more = self.core.index_manager.runGraphOwnershipCleanupStep() catch |err| {
                self.core.unlockApply();
                return err;
            };
            self.core.unlockApply();
            if (!more) break;
        }
        // Planned maintenance uses the same catalog pins and transaction
        // fences as background workers. Never hold the ingest lock while
        // draining graph computation; graph writes may supersede a build.
        switch (self.graph_metric_idle_maintenance) {
            .auto => return self.runGraphMetricPlannedAutoMaintenanceForIdle(),
            .planned => return self.drainGraphMetricPlannedIdle(),
            else => {},
        }
        lockApply(self);
        defer self.core.unlockApply();
        try self.requireGraphEndpointCleanupReady();
        if (!self.core.index_manager.graphRetirementAdmissionOpen()) return error.IntegrityTopologyBusy;
        return switch (self.graph_metric_idle_maintenance) {
            .legacy => try self.core.index_manager.runGraphMetricMaintenance(),
            .planned, .auto => unreachable,
            .degree_canary => try self.runGraphMetricDegreeCanaryMaintenanceForIdleLocked(),
        };
    }

    fn graphMetricPlannedProgress(result: index_manager_mod.IndexManager.GraphMetricPlannedSchedulerSweepResult) usize {
        return result.planning_steps + result.builds_started + result.pages_completed + result.phases_advanced + result.published;
    }

    fn drainGraphMetricPlannedIdle(self: *DB) !usize {
        const result = try self.core.index_manager.runGraphMetricPlannedMaintenance(self.graph_metric_idle_planned_options);
        if (result.budget_exhausted) return error.RunUntilIdleDidNotConverge;
        return graphMetricPlannedProgress(result);
    }

    fn runGraphMetricPlannedAutoMaintenanceForIdle(self: *DB) !usize {
        const result = try self.core.index_manager.runGraphMetricPlannedAutoMaintenance(
            self.graph_metric_idle_planned_options,
            self.graph_metric_idle_auto_options,
        );
        if (result.budget_exhausted) return error.RunUntilIdleDidNotConverge;
        const progressed = graphMetricPlannedProgress(result);
        const after = try self.core.index_manager.graphMetricPlannedAutoIdleDecision(self.graph_metric_idle_auto_options);
        if (!after.shouldRunPlanned() and after.ineligible_queued != 0) {
            // Admission caps must not silently select unlimited local compute.
            return error.RunUntilIdleDidNotConverge;
        }
        return progressed;
    }

    fn runGraphMetricDegreeCanaryMaintenanceForIdleLocked(self: *DB) !usize {
        const decision = try self.core.index_manager.graphMetricDegreeCanaryDecision(self.graph_metric_idle_degree_canary_options);
        if (decision.shouldRunPlanned()) return try self.drainGraphMetricPlannedIdle();
        if (decision.active_degree_builds != 0 or decision.blocked_active_non_degree != 0) {
            return error.RunUntilIdleDidNotConverge;
        }
        return try self.core.index_manager.runGraphMetricMaintenance();
    }

    pub fn runGraphMetricPlannedMaintenanceForIdle(
        self: *DB,
        options: index_manager_mod.IndexManager.GraphMetricPlannedMaintenanceOptions,
    ) !index_manager_mod.IndexManager.GraphMetricPlannedSchedulerSweepResult {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        lockApply(self);
        defer self.core.unlockApply();
        try self.requireGraphEndpointCleanupReady();
        if (!self.core.index_manager.graphRetirementAdmissionOpen()) return error.IntegrityTopologyBusy;
        return try self.core.index_manager.runGraphMetricPlannedMaintenance(options);
    }

    const GraphMetricServiceMaintenanceAction = enum { tick, status, release };

    const GraphMetricServiceMaintenanceRequest = struct {
        action: GraphMetricServiceMaintenanceAction = .tick,
        role: graph_metric_runtime_mod.Role,
        runtime_id: []const u8,
        owner_id: []const u8,
        lease_owned: bool = false,
        lease_ttl_ms: u64 = 30_000,
        worker_id: ?[]const u8 = null,
        worker_ids: ?[]const []const u8 = null,
        start_background_builds: bool = true,
        max_rounds: usize = 1,
        max_metrics_per_round: usize = 8,
        max_pages_per_round: usize = 1,
        preserve_lease_after_tick: bool = false,
        now_ms: ?u64 = null,
    };

    pub fn runGraphMetricServiceMaintenanceJsonAlloc(self: *DB, alloc: Allocator, body: []const u8) ![]u8 {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        var parsed = std.json.parseFromSlice(GraphMetricServiceMaintenanceRequest, alloc, if (body.len == 0) "{}" else body, .{
            .allocate = .alloc_always,
            .ignore_unknown_fields = true,
        }) catch return error.InvalidGraphMetricRuntimeConfig;
        defer parsed.deinit();

        var manual_clock = platform_clock.ManualClock{};
        if (parsed.value.now_ms) |now_ms| manual_clock.setRealtimeNs(now_ms *| std.time.ns_per_ms);
        const resources = self.core.asyncResources();
        var runtime = try graph_metric_runtime_mod.GraphMetricRuntime.init(
            alloc,
            resources.store,
            resources.index_manager,
            resources.apply_mutex,
            self.backend_runtime,
            .{
                .enabled = true,
                .start_background_loop = false,
                .role = parsed.value.role,
                .runtime_id = parsed.value.runtime_id,
                .lease_owned = parsed.value.lease_owned,
                .owner_id = parsed.value.owner_id,
                .lease_ttl_ms = parsed.value.lease_ttl_ms,
                .coordinator_start_background_builds = parsed.value.start_background_builds,
                .planned_options = .{
                    .worker_id = parsed.value.worker_id orelse "",
                    .worker_ids = parsed.value.worker_ids orelse &.{},
                    .max_rounds = parsed.value.max_rounds,
                    .max_metrics_per_round = parsed.value.max_metrics_per_round,
                    .max_pages_per_round = parsed.value.max_pages_per_round,
                },
                .clock = if (parsed.value.now_ms != null) manual_clock.clock() else platform_clock.Clock.real(),
            },
        );
        var preserve_lease = false;
        defer if (preserve_lease) runtime.deinitPreserveLease() else runtime.deinit();

        if (parsed.value.action == .release) {
            const released = try runtime.ownership.releaseHeldLease();
            var current_lease = try runtime.ownership.loadLease(alloc);
            defer if (current_lease) |*lease| lease_mod.deinitRecord(alloc, lease);
            var runtime_stats = runtime.stats();
            runtime_stats.shutdown = true;
            return try std.json.Stringify.valueAlloc(alloc, .{
                .released = released,
                .lease_owner_id_hash = if (current_lease) |lease| graph_metric_runtime_mod.identityHash(lease.owner_id) else 0,
                .lease_expires_at_ms = if (current_lease) |lease| lease.expires_at_ms else 0,
                .stats = runtime_stats,
            }, .{ .emit_null_optional_fields = false });
        }

        const result: index_manager_mod.IndexManager.GraphMetricPlannedSchedulerSweepResult = if (parsed.value.action == .tick) try runtime.runOnceDetailed() else .{};
        const runtime_stats = runtime.stats();
        preserve_lease = parsed.value.preserve_lease_after_tick and parsed.value.lease_owned and parsed.value.action == .tick and runtime_stats.has_lease;
        return try std.json.Stringify.valueAlloc(alloc, .{
            .result = result,
            .stats = runtime_stats,
        }, .{ .emit_null_optional_fields = false });
    }

    pub fn refreshGraphMetric(self: *DB, alloc: Allocator, index_name: []const u8, metric_name: []const u8) !types.GraphMetricStatus {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        lockApply(self);
        defer self.core.unlockApply();
        try self.requireGraphEndpointCleanupReady();
        if (!self.core.index_manager.graphRetirementAdmissionOpen()) return error.IntegrityTopologyBusy;
        const entry = self.core.graphIndex(index_name) orelse return error.IndexNotFound;
        try entry.index.enableGraphMetric(metric_name);
        var status = try entry.index.runGraphMetric(metric_name);
        defer status.deinit(entry.index.alloc);
        const cloned = try cloneGraphMetricStatusFromGraph(alloc, status);
        if (self.graph_metric_runtime) |runtime| runtime.notify();
        return cloned;
    }

    pub fn rebuildGraphMetric(self: *DB, alloc: Allocator, index_name: []const u8, metric_name: []const u8) !types.GraphMetricStatus {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        lockApply(self);
        defer self.core.unlockApply();
        try self.requireGraphEndpointCleanupReady();
        if (!self.core.index_manager.graphRetirementAdmissionOpen()) return error.IntegrityTopologyBusy;
        const entry = self.core.graphIndex(index_name) orelse return error.IndexNotFound;
        try entry.index.enableGraphMetric(metric_name);
        var status = try entry.index.runGraphMetric(metric_name);
        defer status.deinit(entry.index.alloc);
        const cloned = try cloneGraphMetricStatusFromGraph(alloc, status);
        if (self.graph_metric_runtime) |runtime| runtime.notify();
        return cloned;
    }

    /// Durably enqueue metric work and return immediately. Public control-plane
    /// actions use this path so request latency is independent of graph size;
    /// the bounded maintenance runtime performs and checkpoints the build.
    pub fn scheduleGraphMetricBuild(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        metric_name: []const u8,
        force: bool,
    ) !types.GraphMetricStatus {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        const owned_status = blk: {
            lockApply(self);
            defer self.core.unlockApply();
            try self.requireGraphEndpointCleanupReady();
            if (!self.core.index_manager.graphRetirementAdmissionOpen()) return error.IntegrityTopologyBusy;
            const entry = self.core.graphIndex(index_name) orelse return error.IndexNotFound;
            var current = try entry.index.graphMetricStatus(metric_name);
            defer current.deinit(entry.index.alloc);
            if (current.state == .disabled) {
                try entry.index.enableGraphMetric(metric_name);
                current.deinit(entry.index.alloc);
                current = try entry.index.graphMetricStatus(metric_name);
            }
            if (!force and current.state == .fresh) {
                break :blk try cloneGraphMetricStatusFromGraph(alloc, current);
            }
            const target_generation = @max(current.edge_generation, current.target_edge_generation);
            // Force means "build another immutable score epoch", not
            // "unpublish first". Repeated requests remain idempotent while a
            // build is active, and readers keep the verified prior epoch until
            // the new pointer is atomically published.
            var scheduled = entry.index.queueGraphMetricBuild(metric_name, target_generation) catch |err| switch (err) {
                // A newer edge snapshot may be queued while the prior bounded
                // build is still active. Treat repeated control-plane actions
                // as accepted and expose the active/queued generations in the
                // returned status instead of turning a safe retry into a 500.
                error.GraphMetricBuildAlreadyRunning => break :blk try cloneGraphMetricStatusFromGraph(alloc, current),
                else => return err,
            };
            defer scheduled.deinit(self.core.index_manager.alloc);
            break :blk try cloneGraphMetricStatusFromGraph(alloc, scheduled);
        };
        if (self.graph_metric_runtime) |runtime| runtime.notify();
        return owned_status;
    }

