        try applySplitGraphArtifactsInRange(
            alloc,
            "",
            "",
            self.core.store,
            self.core.index_manager,
        );
    }

    pub fn runDensePostingMaintenanceForIdle(self: *DB) !usize {
        var snapshot_replay = try self.acquireSnapshotReplayMutation();
        defer snapshot_replay.release();
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        return try self.core.index_manager.runDensePostingMaintenance(.{
            .max_postings_per_index = densePostingIdleMaxPostingsPerIndex(),
            .max_layout_changes_per_index = densePostingIdleMaxLayoutChangesPerIndex(),
            .max_boundary_reassignments_per_index = densePostingIdleMaxBoundaryReassignmentsPerIndex(),
        });
    }

    pub const PostingRefreshProgress = hbc_mod.HBCIndex.PostingRefreshProgress;

    pub fn refreshDensePostingPayloadPageBestEffort(self: *DB) !PostingRefreshProgress {
        // Clean scanning needs only the catalog lifetime and per-index
        // mutation owner. It must not close query admission or queue behind
        // a sustained stream of readers simply to discover an empty backlog.
        const scanned_page = blk: {
            var lease = self.tryAcquireIndexCatalogReadLease() orelse return .{ .pending = true };
            defer lease.release();
            break :blk try self.core.index_manager.refreshDensePostingPayloadPage(false);
        };
        if (!scanned_page.needs_write) return scanned_page;
        // Capture owns leaf/ancestor state and pins immutable input generations.
        // Native input loading and computation need no DB/catalog/index lock.
        // Unsupported input formats retain the coherent copied-input path.
        const capture = blk: {
            // Keep primary/source fallback reads at one revision while copying
            // inputs. This shared lease admits queries; no writer fence is
            // requested until the detached computation has completed.
            if (!self.core.tryLockApplyShared()) return .{ .pending = true, .scanned = scanned_page.scanned };
            defer self.core.unlockApplyShared();
            var lease = self.tryAcquireIndexCatalogReadLease() orelse return .{ .pending = true };
            defer lease.release();
            break :blk self.core.index_manager.captureDensePostingRefreshWithOutcome() catch |err| switch (err) {
                error.ResourceBudgetExceeded => return .{ .pending = true, .scanned = scanned_page.scanned },
                else => return err,
            };
        };
        const prepared: ?*hbc_mod.HBCIndex.PreparedPostingRefresh = switch (capture) {
            .prepared => |value| value,
            .deferred => return .{ .pending = true, .scanned = scanned_page.scanned },
            .synchronous_required => null,
        };
        defer if (prepared) |value| value.deinit();
        const preparation_started = monotonicTimeNs();
        defer if (prepared) |value| {
            if (benchMetricsEnabled()) std.log.info("dense posting prepared outcome leaf={} detached={} published={} elapsed_ns={} capture_ns={} input_ns={} metadata_ns={} read_ns={} input_rows={} binding_hits={}", .{ value.leaf_id, value.detached, value.published, elapsedSince(preparation_started), value.capture_ns, value.input_ns, value.metadata_ns, value.read_ns, value.input_rows, value.binding_hits });
        };
        if (prepared) |value| {
            const started = monotonicTimeNs();
            value.build() catch |err| switch (err) {
                error.PreparedInputUnavailable, error.ResourceBudgetExceeded => return .{ .pending = true, .scanned = scanned_page.scanned },
                else => return err,
            };
            value.build_ns = (monotonicTimeNs() -| started) -| value.input_ns;
        }

        // Upgrade only after finding actual debt, releasing the catalog lease
        // first to avoid a cycle with a structural writer draining that lease.
        // Writer-preferring admission makes progress under steady queries;
        // cancellation reopens admission if existing readers take too long.
        const admission_started = monotonicTimeNs();
        if (!self.core.tryLockApplyExclusive()) {
            const io = self.backend_runtime.io() orelse return .{ .pending = true, .scanned = scanned_page.scanned };
            self.core.apply_mutex.lockExclusiveDeadlineIo(io, .fromNow(io, .{
                .raw = .fromMilliseconds(50),
                .clock = .awake,
            })) catch |err| switch (err) {
                error.Timeout => return .{ .pending = true, .scanned = scanned_page.scanned },
                else => return err,
            };
        }
        defer self.core.unlockApply();
        if (prepared) |value| value.admission_ns = monotonicTimeNs() -| admission_started;
        // Recheck the current index state under the exclusive fence: a write
        // or another refresh may have run between scanning and admission.
        var repaired = if (prepared) |value|
            try self.core.index_manager.publishPreparedDensePostingRefresh(value)
        else
            try self.core.index_manager.refreshDensePostingPayloadPage(true);
        repaired.scanned += scanned_page.scanned;
        return repaired;
    }

    pub fn publishCompletedDensePostingCheckpoints(self: *DB) !NativePublicationResult {
        // Native backup closes and drains this same catalog barrier before
        // selecting/pinning generated files. It excludes publication until
        // hardlinks own the captured generation, without serializing ordinary
        // primary commits behind the checkpoint handoff.
        var catalog_lease = self.tryAcquireIndexCatalogReadLease() orelse return .{ .busy = true };
        defer catalog_lease.release();
        const result = try self.core.index_manager.publishCompletedDensePostingCheckpoints();
        return .{ .published = result.published, .deferred = result.deferred };
    }

    /// Cooperatively drain the posting dependency chain at a caller-proven
    /// quiet boundary. Individual repair pages remain bounded by the runtime
    /// policy and the drain stops when foreground dense work reappears.
    pub fn drainDensePostingMaintenanceForIdle(self: *DB) !usize {
        lockApply(self);
        defer self.core.unlockApply();
        return try self.core.index_manager.drainDensePostingMaintenance(.{
            .max_postings_per_index = densePostingIdleMaxPostingsPerIndex(),
            .max_layout_changes_per_index = densePostingIdleMaxLayoutChangesPerIndex(),
            .max_boundary_reassignments_per_index = densePostingIdleMaxBoundaryReassignmentsPerIndex(),
        });
    }

    pub fn runVectorBlockMaintenanceForIdle(self: *DB) !usize {
        return try self.publishVectorBlockBasesOnline(.{});
    }

    /// Live repair and recurring acceleration share one optimistic owner.
    /// Catalog lifetime ownership pins index pointers without acquiring the
    /// apply lock (even shared apply would exclude primary commits). Native
    /// file construction never owns the table write fence. Posting
    /// reconstruction has its own durable repair owner.
    pub fn publishVectorBlockBasesOnline(self: *DB, options: index_manager_mod.IndexManager.OnlineVectorBlockPublicationOptions) !usize {
        return (try self.publishVectorBlockBasesOnlineReported(options)).published;
    }

    pub const NativePublicationResult = types.NativePublicationResult;

    pub fn publishVectorBlockBasesOnlineReported(self: *DB, options: index_manager_mod.IndexManager.OnlineVectorBlockPublicationOptions) !NativePublicationResult {
        var catalog_lease = self.tryAcquireIndexCatalogReadLease() orelse return .{ .busy = true };
        defer catalog_lease.release();
        var session_lock = lockAtomicWithBackoffProfiled(
            &self.async_context.dense_admission.mutex,
            &self.async_context.stats.dense_finish_mutex,
        );
        const claimed = tryClaimDenseProjectionFinalizationLocked(self.async_context);
        session_lock.unlock();
        if (!claimed) return .{ .busy = true };
        defer finishDenseProjectionFinalization(self.async_context);
        const initial = try self.core.index_manager.publishVectorBlockBasesOnlineReported(options);
        var published = initial.published;
        var deferred = initial.deferred;
        // Fail-closed reconstruction cannot depend on its own clean marker
        // to enter acceleration maintenance. Permit only candidates whose
        // durable terminal outcomes already cover the current source corpus.
        // Nothing here activates the repair or certifies a stale generation.
        for (self.core.index_manager.dense_indexes.items) |entry| {
            if (!self.core.index_manager.repairUnavailable(entry.config.name)) continue;
            const checkpoint = self.core.index_manager.denseProjectionCheckpointMetadata(entry.config.name) orelse continue;
            if (checkpoint.status != .rebuilding) continue;
            const expected = (try denseTargetCountForIndexContext(self.async_context, entry.config.name)) orelse continue;
            if (entry.index.stats().active_count != expected) continue;
            var repair_options = options;
            repair_options.covered_rebuilding_index = entry.config.name;
            const repair = try self.core.index_manager.publishVectorBlockBasesOnlineReported(repair_options);
            published += repair.published;
            deferred = deferred or repair.deferred;
        }
        return .{ .published = published, .deferred = deferred };
    }

    /// Retry readiness publication after all dense sessions have retired.
    /// The last source callback can observe coverage counters just before
    /// their final durable update and legitimately decline publication. The
    /// recurring vector-maintenance lane must re-evaluate that lifecycle
    /// proof; otherwise a finite load depends on unrelated future writes.
    pub fn finalizeDenseProjectionLifecycleForIdle(self: *DB) !bool {
        // The recurring owner may construct files, but never while holding
        // the shared apply lease used by the small certification below.
        _ = try self.publishVectorBlockBasesOnline(.{});
        return try finalizeCoveredDenseProjectionCheckpointsIfIdle(self.async_context);
    }

    pub fn publishVectorBlockBasesAtStableTip(self: *DB) !usize {
        // The explicit idle drain and the background owner share one vector
        // store. Acquire the same publication claim before taking apply; a
        // writer lock alone cannot exclude a worker staging outside that lock.
        // Wait without any primary/catalog lock so the owner can finish.
        const ctx = self.async_context;
        const deadline = monotonicTimeNs() +| 30 * std.time.ns_per_s;
        var wait_ms: u64 = 1;
        while (true) {
            var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
            const claimed = tryClaimDenseProjectionFinalizationLocked(ctx);
            const sessions_active = asyncContextHasDenseSessionsOrWaiters(ctx);
            session_lock.unlock();
            if (claimed) break;
            if (sessions_active or monotonicTimeNs() >= deadline) return error.WriterLocked;
            if (self.backend_runtime.io()) |io| {
                try io.sleep(std.Io.Duration.fromMilliseconds(@intCast(wait_ms)), .awake);
            } else if (comptime builtin.os.tag == .freestanding) {
                return error.WriterLocked;
            } else {
                sleepNs(wait_ms * std.time.ns_per_ms);
            }
            wait_ms = @min(wait_ms * 2, 16);
        }
        defer finishDenseProjectionFinalization(ctx);
        lockApply(self);
        defer self.core.unlockApply();
        return try self.core.index_manager.publishVectorBlockBasesAtStableTip();
    }

    pub fn nativeVectorProjectionMaintenanceNeeded(self: *DB) bool {
        return self.core.index_manager.vectorBlockBaseMaintenanceNeeded();
    }

    fn flushAppliedSequencesForIdle(self: *DB) !void {
        var lifecycle_completed = false;
        const published = blk: {
            var seq_lock = lockAtomicWithBackoffProfiled(
                &self.async_context.applied_sequence_mutex,
                &self.async_context.stats.applied_sequence_mutex,
            );
            defer seq_lock.unlock();
            break :blk try flushPendingAppliedSequencesLocked(self.async_context, true, &lifecycle_completed);
        };
        if (lifecycle_completed) {
            notifyQueryVisibilityHook(self.async_context, .publish_blocking);
        } else if (published) {
            notifyQueryVisibilityHook(self.async_context, .publish_consistent);
        }
    }

    fn isRecoverableEmbeddingArtifactError(err: anyerror) bool {
        return switch (err) {
            error.InvalidArtifactHeader,
            error.InvalidArtifactMagic,
            error.UnsupportedArtifactCodecVersion,
            error.InvalidArtifactKind,
            error.InvalidArtifactPayload,
            error.InvalidVectorDimensions,
            error.InvalidSparseEmbedding,
            => true,
            else => false,
        };
    }

    fn freeDenseArtifactRebuildWrites(alloc: Allocator, writes: *std.ArrayListUnmanaged(mapper.DenseEmbeddingWrite)) void {
        for (writes.items) |write| {
            alloc.free(write.index_name);
            alloc.free(write.doc_key);
            if (write.parent_doc_key) |parent_doc_key| alloc.free(@constCast(parent_doc_key));
            if (write.artifact_key) |artifact_key| alloc.free(artifact_key);
            if (write.vector.len > 0) alloc.free(write.vector);
        }
        writes.clearRetainingCapacity();
    }

    fn freeSparseArtifactRebuildWrites(alloc: Allocator, writes: *std.ArrayListUnmanaged(mapper.SparseEmbeddingWrite)) void {
        for (writes.items) |write| {
            alloc.free(write.doc_key);
            if (write.artifact_key) |artifact_key| alloc.free(artifact_key);
            if (write.indices.len > 0) alloc.free(write.indices);
            if (write.values.len > 0) alloc.free(write.values);
        }
        writes.clearRetainingCapacity();
    }

    fn flushDenseArtifactRebuildChunk(
        self: *DB,
        alloc: Allocator,
        writes: *std.ArrayListUnmanaged(mapper.DenseEmbeddingWrite),
        mutated_indexes: *std.StringHashMapUnmanaged(void),
    ) !void {
        defer freeDenseArtifactRebuildWrites(alloc, writes);
        if (writes.items.len == 0) return;

        for (self.core.index_manager.dense_indexes.items) |entry| {
            var has_writes = false;
            for (writes.items) |write| {
                if (std.mem.eql(u8, write.index_name, entry.config.name)) {
                    has_writes = true;
                    break;
                }
            }
            if (!has_writes) continue;

            const posting_capture = try self.core.index_manager.beginDensePostingSidecarCaptureLeaseByNameWithOptions(entry.config.name, .{});
            var posting_capture_owned = if (posting_capture) |lease| lease.ownsLifecycle() else false;
            if (posting_capture == null and
                self.core.index_manager.densePostingSidecarCaptureRequiredByName(entry.config.name))
            {
                return error.PostingWalCaptureOwnershipConflict;
            }
            errdefer if (posting_capture_owned) if (posting_capture) |lease|
                self.core.index_manager.cancelDensePostingSidecarCaptureLeaseByName(entry.config.name, lease) catch {};
            try self.core.index_manager.applyDenseEmbeddingWritesByNameWithOptions(
                self.core.store,
                entry.config.name,
                writes.items,
                .{ .mode = .bulk_ingest },
            );
            if (posting_capture) |lease| if (posting_capture_owned) {
                // Repair chunks are independently recoverable. Keep their WAL
                // bounded at their existing capture boundary. Zero would regress
                // a reopened native generation; retaining the base does not
                // claim additional source coverage for an incomplete scan.
                try self.core.index_manager.finishDensePostingSidecarCaptureLeaseByName(entry.config.name, lease, lease.capture.base_coverage);
                posting_capture_owned = false;
            };
            try mutated_indexes.put(alloc, entry.config.name, {});
        }
    }

    const DenseArtifactRebuildResumeHook = *const fn (ctx: *anyopaque, last_key: []const u8) anyerror!void;

    const DenseArtifactRebuildTarget = struct {
        dense_index_idx: usize,
        resume_from: ?[]u8 = null,
        /// True only when resume_from came from a cursor owned by the current
        /// catalog generation. Fresh and stale-generation targets must publish
        /// a generation-owned restart cursor during execution, never probing.
        resume_state_current: bool = false,
        artifact_target_count: u64 = 0,

        pub fn deinit(self: *@This(), alloc: Allocator) void {
            if (self.resume_from) |buf| alloc.free(buf);
            self.* = .{
                .dense_index_idx = 0,
            };
        }
    };

    const DenseGenerationRepairTarget = struct {
        dense_index_idx: usize,
        trigger: index_repair_state.Trigger,
        last_error: []const u8,
    };

    const DenseArtifactRebuildPlan = struct {
        targets: []DenseArtifactRebuildTarget = &.{},
        generation_repairs: []DenseGenerationRepairTarget = &.{},
        rebuild_state_cleanups: []usize = &.{},
        target_sequence: u64 = 0,

        pub fn deinit(self: *@This(), alloc: Allocator) void {
            for (self.targets) |*target| target.deinit(alloc);
            if (self.targets.len > 0) alloc.free(self.targets);
            if (self.generation_repairs.len > 0) alloc.free(self.generation_repairs);
            if (self.rebuild_state_cleanups.len > 0) alloc.free(self.rebuild_state_cleanups);
            self.* = .{};
        }
    };

    const DenseArtifactRebuildOutcome = struct {
        /// Preserves the public helper's historical count: rebuilt artifact
        /// records, or discovered generation-repair targets when no in-place
        /// target exists.
        reported_work: usize = 0,
        /// True only when this invocation changed durable/in-memory repair
        /// state. Existing debt rediscovered by a probe is not progress.
        made_progress: bool = false,
        /// Dense vectors changed, so HBC query caches must be retired.
        dense_visibility_changed: bool = false,
    };

    const DenseArtifactRebuildPreparation = struct {
        made_progress: bool = false,
        dense_visibility_changed: bool = false,
    };

    const DenseArtifactTargetCounts = struct {
        per_target_index: std.AutoHashMapUnmanaged(usize, u64) = .empty,
        authoritative_targets: std.AutoHashMapUnmanaged(usize, void) = .empty,
        total_target_artifacts: u64 = 0,

        pub fn deinit(self: *@This(), alloc: Allocator) void {
            self.per_target_index.deinit(alloc);
            self.authoritative_targets.deinit(alloc);
            self.* = .{};
        }
    };

