    const freeDBIndexStatsItem = status_projection.freeDBIndexStatsItem;

    const cloneAlgebraicCandidateStatusAlloc = status_projection.cloneAlgebraicCandidateStatusAlloc;

    const cloneAlgebraicCandidateDecisionStatusAlloc = status_projection.cloneAlgebraicCandidateDecisionStatusAlloc;

    const cloneAlgebraicProgressStatusAlloc = status_projection.cloneAlgebraicProgressStatusAlloc;

    const IndexStatusSnapshot = status_projection.IndexStatusSnapshot;
    const index_status_magic_v1 = status_projection.index_status_magic_v1;
    const index_status_encoded_len = status_projection.index_status_encoded_len;

    const indexStatusKeyAlloc = status_projection.indexStatusKeyAlloc;
    const encodeIndexStatusSnapshot = status_projection.encodeIndexStatusSnapshot;
    const decodeIndexStatusSnapshot = status_projection.decodeIndexStatusSnapshot;

    const DenseServingCounts = struct { doc_count: u64, node_count: u64, root_node: u64, revision: u64 };

    fn denseServingCounts(index: *hbc_mod.HBCIndex) DenseServingCounts {
        if (index.nativeServingSnapshot()) |serving_snapshot| return .{
            .doc_count = serving_snapshot.active_count,
            .node_count = serving_snapshot.node_count,
            .root_node = serving_snapshot.root_node,
            .revision = serving_snapshot.publish_generation,
        };
        if (index.experimentalPostingWalAuthoritative()) return .{
            .doc_count = 0,
            .node_count = 0,
            .root_node = 0,
            .revision = 0,
        };
        const published = index.publishedStats();
        return .{
            .doc_count = published.stats.active_count,
            .node_count = published.stats.node_count,
            .root_node = published.stats.root_node,
            .revision = published.generation,
        };
    }

    fn collectLiveIndexStatusSnapshot(index_manager: *index_manager_mod.IndexManager, index_name: []const u8) ?IndexStatusSnapshot {
        // These bytes enter compressed durable tables, so even a diagnostic
        // timestamp can change disk usage and subsequent placement decisions.
        const now = platform_time.awakeNs(index_manager.checkpointIo());
        if (index_manager.textIndex(index_name)) |entry| {
            // Applied-sequence persistence runs outside the DB apply lock; keep this
            // snapshot cheap and avoid walking full-text segment internals here.
            const text_snapshot = entry.acquireSnapshot();
            defer text_snapshot.release();
            return .{
                .kind = .full_text,
                .doc_count = text_snapshot.liveDocCount(),
                .updated_at_ns = now,
            };
        }
        if (index_manager.denseIndex(index_name)) |entry| {
            const dense_stats = denseServingCounts(entry.index);
            return .{
                .kind = .dense_vector,
                .doc_count = dense_stats.doc_count,
                .node_count = dense_stats.node_count,
                .root_node = dense_stats.root_node,
                .updated_at_ns = now,
            };
        }
        if (index_manager.sparseIndex(index_name)) |entry| {
            const sparse_stats = entry.index.stats();
            return .{
                .kind = .sparse_vector,
                .doc_count = sparse_stats.doc_count,
                .term_count = sparse_stats.term_count,
                .updated_at_ns = now,
            };
        }
        if (index_manager.graphIndex(index_name)) |entry| {
            const graph_stats = entry.index.operationalStats();
            return .{
                .kind = .graph,
                .doc_count = graph_stats.node_count,
                .edge_count = graph_stats.edge_count,
                .graph_counts_pending = graph_stats.counts_pending,
                .node_count = graph_stats.node_count,
                .updated_at_ns = now,
            };
        }
        return null;
    }

    fn textIndexTermCount(entry: anytype) u64 {
        const snap = entry.acquireSnapshot();
        defer snap.release();
        return textSnapshotTermCount(snap);
    }

    fn textSnapshotTermCount(snap: anytype) u64 {
        var terms: u64 = 0;
        for (snap.segments) |*seg| {
            terms +|= seg.layoutStats(false).inverted_term_count;
        }
        return terms;
    }

    fn saveIndexStatusSnapshots(
        alloc: Allocator,
        store: *docstore_mod.DocStore,
        index_manager: *index_manager_mod.IndexManager,
        updates: []const apply_state.AppliedSequenceUpdate,
    ) !void {
        if (updates.len == 0) return;

        const PendingStatusWrite = struct {
            key: []u8,
            value: [index_status_encoded_len]u8,
        };
        var pending = std.ArrayListUnmanaged(PendingStatusWrite).empty;
        defer {
            for (pending.items) |item| alloc.free(item.key);
            pending.deinit(alloc);
        }

        for (updates) |update| {
            const status_snapshot = collectLiveIndexStatusSnapshot(index_manager, update.index_name) orelse continue;
            const key = try indexStatusKeyAlloc(alloc, update.index_name);
            var encoded: [index_status_encoded_len]u8 = undefined;
            encodeIndexStatusSnapshot(status_snapshot, &encoded);
            errdefer alloc.free(key);
            try pending.append(alloc, .{
                .key = key,
                .value = encoded,
            });
        }

        if (pending.items.len == 0) return;
        var status_batch = try store.beginWriteBatch();
        errdefer status_batch.abort();
        for (pending.items) |item| try status_batch.put(item.key, &item.value);
        try status_batch.commit();
    }

    fn saveAllLiveIndexStatusSnapshots(self: *DB, alloc: Allocator) !void {
        const configs = try self.core.listIndexes(alloc);
        defer types.freeIndexConfigs(alloc, configs);
        if (configs.len == 0) return;

        var updates = std.ArrayListUnmanaged(apply_state.AppliedSequenceUpdate).empty;
        defer updates.deinit(alloc);
        for (configs) |cfg| {
            try updates.append(alloc, .{
                .index_name = cfg.name,
                .sequence = try self.core.loadAppliedSequence(alloc, cfg.name),
            });
        }
        try saveIndexStatusSnapshots(alloc, self.core.store, self.core.index_manager, updates.items);
    }

    fn loadIndexStatusSnapshot(self: *DB, alloc: Allocator, index_name: []const u8) !?IndexStatusSnapshot {
        const key = try indexStatusKeyAlloc(alloc, index_name);
        defer alloc.free(key);
        const raw = self.core.store.get(alloc, key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        defer alloc.free(raw);
        return decodeIndexStatusSnapshot(raw) catch null;
    }

    const applyIndexStatusSnapshot = status_projection.applyIndexStatusSnapshot;

    const indexLoadFailureKeyAlloc = status_projection.indexLoadFailureKeyAlloc;

    fn loadPersistedIndexLoadFailure(self: *DB, alloc: Allocator, index_name: []const u8) !?[]u8 {
        const key = try indexLoadFailureKeyAlloc(alloc, index_name);
        defer alloc.free(key);
        const raw = self.core.store.get(alloc, key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        return raw;
    }

    fn persistIndexLoadFailuresFromManager(self: *DB, alloc: Allocator) !void {
        const configs = try self.core.listIndexes(alloc);
        defer types.freeIndexConfigs(alloc, configs);
        var failure_batch = try self.core.store.beginWriteBatchWithOptions(.{ .defer_commit_flush = true });
        errdefer failure_batch.abort();
        var wrote = false;
        for (configs) |cfg| {
            const key = try indexLoadFailureKeyAlloc(alloc, cfg.name);
            defer alloc.free(key);
            if (self.core.index_manager.loadFailure(cfg.name)) |err_name| {
                try failure_batch.put(key, err_name);
                wrote = true;
            } else {
                const persisted = self.core.store.get(alloc, key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
                if (persisted) |value| {
                    alloc.free(value);
                    failure_batch.delete(key) catch {};
                    wrote = true;
                }
            }
        }
        if (wrote) try failure_batch.commit() else failure_batch.abort();
    }

    const applyTerminalLoadFailureStatus = status_projection.applyTerminalLoadFailureStatus;

    fn markDenseCoverageRegressionIfNeeded(self: *DB, alloc: Allocator, index_name: []const u8, item: *types.DBIndexStats) !void {
        const status_snapshot = (try self.loadIndexStatusSnapshot(alloc, index_name)) orelse return;
        if (status_snapshot.kind != .dense_vector) return;
        if (status_snapshot.doc_count <= item.doc_count) return;
        item.repair_degraded = true;
        item.repair_issue_count +|= 1;
    }

    const applyGraphAlgebraicRuntimeStats = status_projection.applyGraphAlgebraicRuntimeStats;

    const cloneGraphMetricStatusFromGraph = status_projection.cloneGraphMetricStatusFromGraph;

    fn populateGraphMetricStatusStats(alloc: Allocator, item: *types.DBIndexStats, graph_index: *graph_mod.GraphIndex) !void {
        if (graph_index.metric_configs.len == 0) return;
        const statuses = try alloc.alloc(types.GraphMetricStatus, graph_index.metric_configs.len);
        var initialized: usize = 0;
        errdefer {
            for (statuses[0..initialized]) |*status| status.deinit(alloc);
            alloc.free(statuses);
        }
        for (graph_index.metric_configs, 0..) |cfg, i| {
            var status = try graph_index.graphMetricStatus(cfg.name);
            defer status.deinit(graph_index.alloc);
            statuses[i] = try cloneGraphMetricStatusFromGraph(alloc, status);
            initialized += 1;
        }
        item.graph_metric_status = statuses;
    }

    fn managedIndexAppliedSequence(self: *DB, alloc: Allocator, index_name: []const u8) !u64 {
        var applied_sequence = try self.core.loadAppliedSequence(alloc, index_name);
        if (self.executor.appliedSequence(index_name)) |live_applied| {
            applied_sequence = @max(applied_sequence, live_applied);
        }
        return applied_sequence;
    }

    pub fn managedIndexReplayTargetSequence(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        kind: types.IndexKind,
        applied_sequence: u64,
    ) !u64 {
        return try self.probeDerivedReplayTargetSequence(
            alloc,
            self.core.replaySource(),
            .{
                .name = index_name,
                .kind = kind,
            },
            applied_sequence,
        );
    }

    fn projectionStatsTargetSequence(self: *DB, alloc: Allocator, cfg: types.IndexConfig, applied_sequence: u64) !u64 {
        return try self.managedIndexReplayTargetSequence(alloc, cfg.name, cfg.kind, applied_sequence);
    }

    fn enrichmentStatsWithSupervisorState(self: *DB, fallback: types.EnrichmentStats) types.EnrichmentStats {
        // Status is called while the DB apply lock is held. Structural
        // mutations hold lifecycle while stopping and joining the enrichment
        // worker, and that worker can be waiting for apply. Never close the
        // lifecycle -> worker join -> apply -> lifecycle cycle here.
        const lifecycle_locked = self.async_context.enrichment_lifecycle_mutex.tryLock();
        defer if (lifecycle_locked) self.async_context.enrichment_lifecycle_mutex.unlock();
        var enrichment_status = if (lifecycle_locked)
            if (self.async_context.enrichment_runtime) |runtime|
                runtime.stats()
            else
                self.persistedEnrichmentStats() catch fallback
        else
            fallback;
        const desired = self.async_context.enrichment_desired_running.load(.acquire);
        // `desired` is the lock-free source of truth for whether this DB owns
        // an enrichment producer. A retained query-only snapshot may have
        // `enabled=false`, and lifecycle contention prevents us from replacing
        // it with runtime.stats(). Never let that observation gap turn a live
        // or restarting producer into a disabled one: public readiness treats
        // enabled + retrying as transient debt and remains fail-closed until a
        // later poll can observe the worker directly.
        if (desired) enrichment_status.enabled = true;
        const started = if (lifecycle_locked)
            if (self.async_context.enrichment_runtime) |runtime| runtime.isStarted() else false
        else
            false;
        if (desired and !started) {
            // While lifecycle owns the runtime pointer, expose the persisted
            // snapshot as a supervised transition rather than a fatal worker.
            const supervised = !lifecycle_locked or self.async_context.enrichment_restart_owner.state.load(.acquire) != 0;
            enrichment_status.retrying = supervised;
            enrichment_status.worker_failed = !supervised;
            enrichment_status.projection_checkpoint_status = if (supervised) "retrying" else "failed";
        }
        return enrichment_status;
    }

    /// Refresh readiness-neutral worker diagnostics on a retained status
    /// snapshot. Publication lifecycle is deliberately excluded: a lock-free
    /// observation may add activity, but it cannot prove that the artifact
    /// counters in the retained snapshot crossed a completion boundary.
    pub fn overlayRuntimeStatusRuntimeBestEffort(self: *DB, runtime_stats: *types.DBStats) void {
        runtime_stats.async_indexing = self.snapshotAsyncIndexingStats();
        runtime_stats.enrichment = self.enrichmentStatsWithSupervisorState(runtime_stats.enrichment);
        runtime_stats.resolution = self.resolutionStageStats();
        runtime_stats.promotion = self.promotionStageStats();
        runtime_stats.ttl_cleanup = if (self.ttl_runtime) |runtime| runtime.stats() else runtime_stats.ttl_cleanup;
        runtime_stats.transaction_recovery = if (self.transaction_runtime) |runtime| runtime.stats() else runtime_stats.transaction_recovery;
        runtime_stats.graph_metric_runtime = self.graphMetricRuntimeStats();

        // Runtime-only diagnostics are optional status-plane detail and may run
        // under apply. A contended sample is not evidence that the owner went
        // away: retain the last incarnation-matched receipt until the shared
        // heartbeat TTL expires. A successfully observed absent runtime does
        // clear immediately because it is an authoritative lifecycle edge.
        const now_ms = monotonicTimeNs() / std.time.ns_per_ms;
        for (runtime_stats.indexes) |*item| item.embedding_activity_sample_fresh = false;
        if (self.async_context.enrichment_lifecycle_mutex.tryLock()) {
            defer self.async_context.enrichment_lifecycle_mutex.unlock();
            if (self.async_context.enrichment_runtime) |runtime| {
                for (runtime_stats.indexes) |*item| {
                    item.enrichment_failed = item.enrichment_failed or runtime.indexHasIsolatedFailure(item.name);
                    for (item.source_replay) |*source| {
                        source.failed = source.failed or runtime.indexSourceHasIsolatedFailure(item.name, source.artifact_name);
                    }
                }
                self.embedding_activity.observe(self.alloc, runtime_stats.indexes, runtime, now_ms);
                return;
            }
            clearEmbeddingActivityObservations(runtime_stats.indexes);
            self.clearEmbeddingActivityCache();
            return;
        }
        self.embedding_activity.retain(self.alloc, runtime_stats.indexes, now_ms);
    }

    fn clearEmbeddingActivityObservations(indexes: []types.DBIndexStats) void {
        for (indexes) |*item| {
            if (item.kind != .dense_vector and item.kind != .sparse_vector) continue;
            item.embedding_activity_observed = false;
            item.embedding_activity_sample_fresh = false;
            item.embedding_activity = .{};
        }
    }

    /// Apply lifecycle facts only when the caller also owns a consistent
    /// artifact/coverage refresh boundary.
    fn overlayRuntimeStatusLifecycleFromSnapshot(self: *DB, runtime_stats: *types.DBStats) void {
        for (runtime_stats.indexes) |*item| {
            const dense_catch_up = item.kind == .dense_vector and runtime_stats.async_indexing.dense_catch_up.active;
            // This overlay can run over a cached materialization snapshot.
            // Read the live immutable HBC generation's cardinality for the
            // exact-vector certificate instead of pairing a current replay
            // watermark with that snapshot's potentially stale doc_count.
            // The public aggregation layer may later contribute the current
            // count, but it cannot safely reconstruct this generation-local
            // consistency check after the fact.
            const dense_vector_active_count = if (item.kind == .dense_vector)
                if (self.core.denseIndex(item.name)) |entry|
                    entry.index.stats().active_count
                else
                    item.doc_count
            else
                0;
            if (!dense_catch_up) if (self.executor.appliedSequence(item.name)) |live_applied| {
                item.replay_applied_sequence = @max(item.replay_applied_sequence, live_applied);
                item.replay_target_sequence = @max(item.replay_target_sequence, live_applied);
            };
            item.catch_up_active = dense_catch_up;
            if (item.kind == .dense_vector) {
                const progress = runtime_stats.async_indexing.dense_catch_up;
                if (dense_catch_up) {
                    if (progress.current_sequence != 0) {
                        item.replay_applied_sequence = if (item.replay_applied_sequence == 0)
                            progress.current_sequence
                        else
                            @min(item.replay_applied_sequence, progress.current_sequence);
                        item.catch_up_applied_sequence = progress.current_sequence;
                    } else {
                        item.catch_up_applied_sequence = item.replay_applied_sequence;
                    }
                    item.catch_up_target_sequence = @max(item.replay_target_sequence, progress.current_target_sequence);
                    item.replay_target_sequence = item.catch_up_target_sequence;
                    item.replay_catch_up_required = true;
                    item.backfill_active = true;
                } else {
                    item.replay_catch_up_required = item.replay_applied_sequence < item.replay_target_sequence;
                    item.catch_up_applied_sequence = item.replay_applied_sequence;
                    item.catch_up_target_sequence = item.replay_target_sequence;
                }
                item.catch_up_phase = progress.phase;
            } else {
                item.replay_catch_up_required = item.replay_applied_sequence < item.replay_target_sequence;
                item.catch_up_applied_sequence = item.replay_applied_sequence;
                item.catch_up_target_sequence = item.replay_target_sequence;
                item.catch_up_phase = .idle;
            }
            if (item.catch_up_active or item.replay_catch_up_required) {
                item.backfill_active = true;
                if (item.replay_target_sequence > 0) {
                    item.backfill_progress = @min(
                        1.0,
                        @as(f64, @floatFromInt(item.replay_applied_sequence)) /
                            @as(f64, @floatFromInt(item.replay_target_sequence)),
                    );
                }
            } else {
                item.backfill_active = durableGenerationBuildActive(item);
                if (!item.backfill_active and item.replay_target_sequence > 0) item.backfill_progress = 1.0;
            }
            normalizeReplayStatusFromDurableCheckpoint(item);
            if (item.kind == .dense_vector and
                self.core.index_manager.vectorBlockProjectionRequiredForDenseIndex(item.name) and
                !self.core.index_manager.vectorBlockReadyForDenseIndexAtSequence(
                    item.name,
                    item.replay_applied_sequence,
                    dense_vector_active_count,
                ))
            {
                // When the native exact-vector projection is enabled it is
                // part of query readiness, not best-effort maintenance. Apply
                // this after replay normalization so it cannot be overwritten
                // by an otherwise-clean durable generation.
                item.backfill_active = true;
                item.backfill_progress = @min(item.backfill_progress, 0.999);
                item.dense_vector_projection_pending = true;
            }
            for (item.source_replay) |*source| {
                source.published_sequence = @max(source.published_sequence, item.replay_applied_sequence);
                source.target_sequence = @max(source.target_sequence, source.published_sequence);
            }
            item.checkpoint_replay_tail_sequence_count = item.replay_target_sequence -| item.projection_checkpoint_applied_sequence;
        }
    }

    fn normalizeReplayStatusFromDurableCheckpoint(item: *types.DBIndexStats) void {
        const durable_applied = item.projection_checkpoint_applied_sequence;
        if (durable_applied <= item.replay_applied_sequence) return;

        // Projection checkpoints are persisted only after the index publication
        // boundary. A worker snapshot can briefly lag that durable write while
        // it updates its in-memory sequence, but status must not expose the
        // transient ordering as durable replay debt.
        item.replay_applied_sequence = durable_applied;
        item.replay_target_sequence = @max(item.replay_target_sequence, durable_applied);
        item.catch_up_applied_sequence = @max(item.catch_up_applied_sequence, durable_applied);
        item.catch_up_target_sequence = @max(item.catch_up_target_sequence, item.replay_target_sequence);
        item.replay_catch_up_required = item.replay_applied_sequence < item.replay_target_sequence;
        if (!item.catch_up_active and !item.replay_catch_up_required) {
            item.backfill_active = durableGenerationBuildActive(item);
            if (!item.backfill_active and item.replay_target_sequence > 0) item.backfill_progress = 1.0;
        }
    }

    fn replaceOptionalOwnedStringBestEffort(alloc: Allocator, slot: *?[]const u8, value: ?[]const u8) void {
        if (value) |raw| {
            const owned = alloc.dupe(u8, raw) catch return;
            if (slot.*) |previous| alloc.free(previous);
            slot.* = owned;
        } else {
            if (slot.*) |previous| alloc.free(previous);
            slot.* = null;
        }
    }

    fn overlayRuntimeStatusIndexesLocked(self: *DB, stats_alloc: Allocator, runtime_stats: *types.DBStats) !void {
        // This compatibility overlay is not an owner capture. It must never
        // edit facts while retaining the stamp of a different observation.
        for (runtime_stats.indexes) |*item| {
            item.serving_publication = null;
            item.coverage_publication = null;
            item.runtime_serving_applied_sequence = null;
            item.runtime_coverage_applied_sequence = null;
            item.runtime_coverage_source_sequence = null;
        }
        // Coverage outcomes and identity totals are one status invariant. A
        // cached status may predate the write whose generated artifact is
        // being overlaid, so refresh the maintained O(1) identity summary at
        // the same apply-lock boundary before publishing live counters.
        var identity_stats = try doc_identity.fastStatsFromStore(self.core.store);
        applyCachedIdentityVisibilitySummary(&identity_stats, self.core.identity_visibility.summary);
        runtime_stats.source_doc_count = identity_stats.live_ordinals;
        runtime_stats.doc_identity = dbDocIdentityStats(identity_stats, self.core.identity_namespace);
        runtime_stats.columnar_maintenance = self.relational_column_maintenance.snapshot();
        try self.hydrateDerivedCoverageIdentities(stats_alloc, runtime_stats.indexes);
        var repairs = try self.loadIndexRepairStateForStats(stats_alloc);
        defer if (repairs) |*state| state.deinit(stats_alloc);
        var visible_doc_count = runtime_stats.doc_count;
        for (runtime_stats.indexes) |*item| {
            switch (item.kind) {
                .full_text => {
                    if (self.core.textIndex(item.name)) |entry| {
                        const text_snapshot = entry.acquireSnapshot();
                        defer text_snapshot.release();
                        item.doc_count = text_snapshot.liveDocCount();
                        visible_doc_count = @max(visible_doc_count, item.doc_count);
                    }
                    item.text_merge = self.core.index_manager.textMergeStatsSnapshotForIndex(item.name);
                    if (self.text_merge_runtime) |runtime| runtime.overlayRuntimeStats(&item.text_merge);
                    if (self.derivedCoverageAppliesToIndex(.full_text, item.name))
                        try self.populateConfiguredDerivedCoverageCounts(item.name, item);
                },
                .dense_vector => {
                    if (self.core.denseIndex(item.name)) |entry| {
                        const serving = denseServingCounts(entry.index);
                        item.doc_count = serving.doc_count;
                        item.node_count = serving.node_count;
                        item.root_node = serving.root_node;
                        item.hbc_cache = dbHbcCacheStats(entry.index.hbcCacheStats());
                        item.hbc_posting.refresh_pending = entry.index.postingRefreshPending();
                    }
                    try self.populateConfiguredDerivedCoverageCounts(item.name, item);
                    visible_doc_count = @max(visible_doc_count, item.doc_count);
                },
                .sparse_vector => {
                    if (self.core.sparseIndex(item.name)) |entry| {
                        const sparse_stats = entry.index.stats();
                        item.doc_count = if (entry.chunk_name == null and runtime_stats.doc_count > 0)
                            @min(sparse_stats.doc_count, runtime_stats.doc_count)
                        else
                            sparse_stats.doc_count;
                        item.term_count = sparse_stats.term_count;
                    }
                    try self.populateConfiguredDerivedCoverageCounts(item.name, item);
                    visible_doc_count = @max(visible_doc_count, item.doc_count);
                },
                .graph => {
                    if (self.core.graphIndex(item.name)) |entry| {
                        const graph_stats = entry.index.operationalStats();
                        item.edge_count = graph_stats.edge_count;
                        item.node_count = graph_stats.node_count;
                        item.doc_count = graph_stats.node_count;
                        item.graph_counts_pending = graph_stats.counts_pending;
                        applyGraphAlgebraicRuntimeStats(item, &entry.index);
                    }
                    if (self.derivedCoverageAppliesToIndex(.graph, item.name))
                        try self.populateConfiguredDerivedCoverageCounts(item.name, item);
                    if (!item.graph_counts_pending) visible_doc_count = @max(visible_doc_count, item.doc_count);
                },
                .algebraic => {
                    if (self.core.index_manager.algebraicIndex(item.name)) |entry| {
                        const status_value = entry.index.status();
                        item.algebraic_parse_error_count = status_value.parse_error_count;
                        item.algebraic_minmax_cache_hits = status_value.minmax_cache_hits;
                        item.algebraic_minmax_cache_misses = status_value.minmax_cache_misses;
                        item.algebraic_minmax_support_scans = status_value.minmax_support_scans;
                        item.algebraic_planner_selected = status_value.planner_algebraic_selected;
                        item.algebraic_planner_fallback_count = status_value.planner_fallback_count;
                        replaceOptionalOwnedStringBestEffort(
                            stats_alloc,
                            &item.algebraic_planner_last_decision,
                            status_value.planner_last_decision,
                        );
                        replaceOptionalOwnedStringBestEffort(
                            stats_alloc,
                            &item.algebraic_planner_last_fallback_reason,
                            status_value.planner_last_fallback_reason,
                        );
                        item.algebraic_planner_last_estimated_scan_rows = if (status_value.planner_last_estimated_scan_rows) |value| @intCast(value) else null;
                        item.algebraic_planner_last_estimated_result_buckets = if (status_value.planner_last_estimated_result_buckets) |value| @intCast(value) else null;
                        item.algebraic_planner_lifecycle_ready = status_value.planner_lifecycle_ready;
                        replaceOptionalOwnedStringBestEffort(
                            stats_alloc,
                            &item.algebraic_planner_lifecycle_blocking_reason,
                            status_value.planner_lifecycle_blocking_reason,
                        );
                        item.algebraic_dictionary_registry_claimed_count = status_value.dictionary_registry_claimed_count;
                        item.algebraic_dictionary_registry_already_owned_count = status_value.dictionary_registry_already_owned_count;
                        item.algebraic_dictionary_registry_owned_by_other_count = status_value.dictionary_registry_owned_by_other_count;
                        item.algebraic_dictionary_registry_ready_hit_count = status_value.dictionary_registry_ready_hit_count;
                        item.algebraic_dictionary_registry_ready_miss_count = status_value.dictionary_registry_ready_miss_count;
                        item.algebraic_distributed_partial_validation_proven_count = status_value.distributed_partial_validation_proven_count;
                        item.algebraic_distributed_partial_validation_rejected_count = status_value.distributed_partial_validation_rejected_count;
                        item.algebraic_distributed_partial_rows_exported_count = status_value.distributed_partial_rows_exported_count;
                        item.algebraic_vector_filter_attempt_count = status_value.vector_filter_attempt_count;
                        item.algebraic_vector_filter_resolved_count = status_value.vector_filter_resolved_count;
                        item.algebraic_vector_filter_unsupported_count = status_value.vector_filter_unsupported_count;
                        item.algebraic_vector_filter_fail_closed_count = status_value.vector_filter_fail_closed_count;
                        item.algebraic_vector_filter_include_doc_id_count = status_value.vector_filter_include_doc_id_count;
                        item.algebraic_vector_filter_exclude_doc_id_count = status_value.vector_filter_exclude_doc_id_count;
                        item.algebraic_observed_query_shape_count = status_value.observed_query_shape_count;
                        item.algebraic_recommendation_count = status_value.recommendation_count;
                    }
                },
            }
            if (item.kind == .dense_vector or item.kind == .sparse_vector) {
                // Live cardinality and cached readiness are not one observation.
                // A shadow may now be installed but still gated by validation.
                // Refresh durable lifecycle and the query gate with the counts.
                try self.applyDurableIndexRepairStats(
                    stats_alloc,
                    if (repairs) |*state| state else null,
                    self.async_context.index_repair_state_corrupt.load(.acquire),
                    item,
                );
                item.serving_snapshot_ready = self.vectorServingSnapshotReady(stats_alloc, item, if (repairs) |*state| state else null);
            }
            for (item.source_replay) |*source| {
                source.target_sequence = try self.artifactSourceTargetSequence(
                    stats_alloc,
                    source.artifact_name,
                    source.published_sequence,
                    item.replay_target_sequence,
                );
            }
        }
        runtime_stats.doc_count = visible_doc_count;
        runtime_stats.text_merge = if (self.text_merge_runtime) |runtime| runtime.statsAssumeApplyLockHeld() else self.core.index_manager.textMergeStatsSnapshot();
    }

    /// A contended apply lock skips the live per-index refresh below, but the
    /// durable per-index status snapshot (`saveIndexStatusSnapshots`) is
    /// written on every applied update as part of the ordinary replay/apply
    /// commit path, independent of this lock. Read it as a lock-free floor so
    /// a sustained backfill or schema migration, which keeps the writer-
    /// preferring apply lock busy, does not leave doc_count frozen at
    /// whatever the last successful live sample happened to observe. Only
    /// raise the value: a durable snapshot can itself lag a live sample that
    /// did succeed, and this is strictly a fallback for when the live sample
    /// could not run at all.
    fn refreshIndexDocCountsFromDurableSnapshotBestEffort(self: *DB, alloc: Allocator, runtime_stats: *types.DBStats) void {
        for (runtime_stats.indexes) |*item| {
            const status_snapshot = (self.loadIndexStatusSnapshot(alloc, item.name) catch continue) orelse continue;
            if (status_snapshot.kind != item.kind) continue;
            if (status_snapshot.doc_count > item.doc_count) item.doc_count = status_snapshot.doc_count;
        }
    }

    /// Return whether lifecycle and physical index facts were refreshed under
    /// one apply-lock boundary. On contention, only readiness-neutral runtime
    /// diagnostics are overlaid and existing blockers remain intact.
    pub fn overlayRuntimeStatusBestEffort(self: *DB, stats_alloc: Allocator, runtime_stats: *types.DBStats) bool {
        self.overlayRuntimeStatusRuntimeBestEffort(runtime_stats);
        if (!self.core.tryLockApplyShared()) {
            self.refreshIndexDocCountsFromDurableSnapshotBestEffort(stats_alloc, runtime_stats);
            return false;
        }
        defer self.core.unlockApplyShared();
        self.overlayRuntimeStatusLifecycleFromSnapshot(runtime_stats);
        self.overlayRuntimeStatusIndexesLocked(stats_alloc, runtime_stats) catch {
            markMissingDerivedCoverageIdentities(runtime_stats.indexes);
            return false;
        };
        return true;
    }

    pub fn overlayRuntimeStatusConsistent(self: *DB, stats_alloc: Allocator, runtime_stats: *types.DBStats) !void {
        self.overlayRuntimeStatusRuntimeBestEffort(runtime_stats);
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        self.overlayRuntimeStatusLifecycleFromSnapshot(runtime_stats);
        try self.overlayRuntimeStatusIndexesLocked(stats_alloc, runtime_stats);
    }

    pub fn graphMetricRuntimeStats(self: *DB) types.GraphMetricRuntimeStats {
        const runtime = self.graph_metric_runtime orelse return .{};
        const runtime_snapshot = runtime.stats();
        const total = runtime_snapshot.total_result;
        const last = runtime_snapshot.last_result;
        return .{
            .enabled = runtime_snapshot.enabled,
            .role = switch (runtime_snapshot.role) {
                .combined => .combined,
                .coordinator => .coordinator,
                .worker => .worker,
                .worker_pool => .worker_pool,
            },
            .runtime_id_hash = runtime_snapshot.runtime_id_hash,
            .owner_id_hash = runtime_snapshot.owner_id_hash,
            .lease_key_hash = runtime_snapshot.lease_key_hash,
            .worker_id_hash = runtime_snapshot.worker_id_hash,
            .worker_count = @intCast(runtime_snapshot.worker_count),
            .lease_owned = runtime_snapshot.lease_owned,
            .has_lease = runtime_snapshot.has_lease,
            .acquisition_count = runtime_snapshot.acquisition_count,
            .takeover_count = runtime_snapshot.takeover_count,
            .lease_acquire_failures = runtime_snapshot.lease_acquire_failures,
            .lost_leases = runtime_snapshot.lost_leases,
            .last_acquired_ms = runtime_snapshot.last_acquired_ms,
            .lease_expires_at_ms = runtime_snapshot.lease_expires_at_ms,
            .lease_renew_after_ms = runtime_snapshot.lease_renew_after_ms,
            .renewal_count = runtime_snapshot.renewal_count,
            .started = runtime_snapshot.started,
            .shutdown = runtime_snapshot.shutdown,
            .notified = runtime_snapshot.notified,
            .ticks_started = runtime_snapshot.ticks_started,
            .ticks_completed = runtime_snapshot.ticks_completed,
            .durable_progress_ticks = runtime_snapshot.durable_progress_ticks,
            .idle_ticks = runtime_snapshot.idle_ticks,
            .error_ticks = runtime_snapshot.error_ticks,
            .last_error_name = if (runtime_snapshot.last_error_name) |name| types.RuntimeErrorName.init(name) else null,
            .total_metrics_scanned = @intCast(total.metrics_scanned),
            .total_active_builds = @intCast(total.active_builds),
            .total_builds_started = @intCast(total.builds_started),
            .total_worker_steps = @intCast(total.worker_steps),
            .total_coordinator_steps = @intCast(total.coordinator_steps),
            .total_retired_input_records = @intCast(total.retired_input_records),
            .total_pages_claimed = @intCast(total.pages_claimed),
            .total_pages_completed = @intCast(total.pages_completed),
            .total_phases_advanced = @intCast(total.phases_advanced),
            .total_published = @intCast(total.published),
            .total_failed_builds = @intCast(total.failed_builds),
            .last_metrics_scanned = @intCast(last.metrics_scanned),
            .last_active_builds = @intCast(last.active_builds),
            .last_builds_started = @intCast(last.builds_started),
            .last_worker_steps = @intCast(last.worker_steps),
            .last_coordinator_steps = @intCast(last.coordinator_steps),
            .last_retired_input_records = @intCast(last.retired_input_records),
            .last_pages_claimed = @intCast(last.pages_claimed),
            .last_pages_completed = @intCast(last.pages_completed),
            .last_phases_advanced = @intCast(last.phases_advanced),
            .last_published = @intCast(last.published),
            .last_failed_builds = @intCast(last.failed_builds),
            .last_budget_exhausted = last.budget_exhausted,
        };
    }

    pub fn stats(self: *DB, alloc: Allocator) !types.DBStats {
        if (self.open_mode == .status_only) {
            return try self.statusOnlyStats(alloc);
        }

        // Operational stats must stay bounded and avoid maintenance/scan work.
        // See STATUS.md for the status-plane contract.
        if (!self.core.tryLockApplyShared()) {
            return .{
                .indexes_available = false,
                .async_indexing = self.snapshotAsyncIndexingStats(),
                .doc_set_planning = self.snapshotDocSetPlanningStats(),
                .visibility = self.snapshotVisibilityStats(),
                .enrichment = self.enrichmentStatsWithSupervisorState(.{}),
                .resolution = self.resolutionStageStats(),
                .promotion = self.promotionStageStats(),
                .ttl_cleanup = if (self.ttl_runtime) |runtime| runtime.stats() else .{},
                .transaction_recovery = if (self.transaction_runtime) |runtime| runtime.stats() else .{},
            };
        }
        var result = self.statsLocked(alloc) catch |err| {
            self.core.unlockApplyShared();
            return err;
        };
        self.core.unlockApplyShared();
        self.overlayRuntimeStatusRuntimeBestEffort(&result);
        return result;
    }

    pub fn runtimeStatusStatsConsistent(self: *DB, alloc: Allocator) !types.DBStats {
        if (self.open_mode == .status_only) {
            return try self.statusOnlyStats(alloc);
        }

        lockApplyShared(self);
        var result = self.statsLocked(alloc) catch |err| {
            self.core.unlockApplyShared();
            return err;
        };
        self.core.unlockApplyShared();
        self.overlayRuntimeStatusRuntimeBestEffort(&result);
        return result;
    }

    pub fn runtimeStatusStatsConsistentIfAvailable(self: *DB, alloc: Allocator) !?types.DBStats {
        if (self.open_mode == .status_only) {
            return try self.statusOnlyStats(alloc);
        }

        if (!self.core.tryLockApplyShared()) return null;
        var result = self.statsLocked(alloc) catch |err| {
            self.core.unlockApplyShared();
            return err;
        };
        self.core.unlockApplyShared();
        self.overlayRuntimeStatusRuntimeBestEffort(&result);
        return result;
    }

    fn applyCachedIdentityVisibilitySummary(identity_stats: *doc_identity.Stats, summary: ?doc_identity.VisibilitySummary) void {
        const cached = summary orelse return;
        identity_stats.live_ordinals = cached.live_ordinals;
        identity_stats.tombstone_ordinals = cached.tombstone_ordinals;
        identity_stats.max_created_generation = cached.max_created_generation;
        identity_stats.min_deleted_generation = cached.min_deleted_generation;
        identity_stats.max_deleted_generation = cached.max_deleted_generation;
    }

    pub fn reassignIdentityNamespaceForInternalTransition(self: *DB, namespace: doc_identity.Namespace) !void {
        if (self.open_mode == .status_only) return error.UnsupportedOperation;
        lockApply(self);
        defer self.core.unlockApply();
        var migration = try vector_migration.load(self.alloc, self.core.store);
        defer if (migration) |*job| job.deinit();
        var migration_update: ?[]u8 = null;
        defer if (migration_update) |raw| self.alloc.free(raw);
        if (migration) |job| {
            try self.validateVectorMigrationIdentity(job.value);
            if (job.value.active()) return error.VectorMigrationActive;
            var rebound = job.value;
            const identity = try std.json.Stringify.valueAlloc(self.alloc, namespace, .{});
            defer self.alloc.free(identity);
            rebound.table_identity = identity;
            migration_update = try std.json.Stringify.valueAlloc(self.alloc, rebound, .{});
        }
        try doc_identity.reassignNamespaceWithMetadataAlloc(self.alloc, self.core.store, namespace, if (migration_update) |raw|
            &.{.{ .key = vector_migration.contract.job_key, .value = raw }}
        else
            &.{});
        self.core.identity_namespace = namespace;
        // Coverage is bound to the durable namespace even when bounds stay
        // unchanged. Wake an idle worker after the new identity commits.
        self.local_execution.relational_index_maintenance_sweep.request();
        self.local_execution.relational_index_retry_after_ns.store(0, .release);
        if (self.transaction_recovery_identity_context) |ctx| ctx.updateIdentityNamespace(namespace);
    }

    fn portableImportTargetEmptyLocked(self: *DB, alloc: Allocator) !bool {
        var read = try self.core.store.beginReadTxn();
        defer read.abort();
        try @import("artifact_reconcile_intent.zig").requireAbsent(&read);
        if (self.core.schema != null) return false;
        // Every Lite database is now provisioned with the default full-text
        // index at creation, matching the server's table-create behavior, so
        // a target carrying only that pristine index is still eligible for a
        // full physical import. Anything beyond that single default index
        // means the target has been configured and must not be silently
        // overwritten.
        switch (self.core.indexCount()) {
            0 => {},
            1 => {
                const configs = try self.core.listIndexes(alloc);
                defer types.freeIndexConfigs(alloc, configs);
                if (configs.len != 1 or configs[0].kind != .full_text or
                    !std.mem.eql(u8, configs[0].name, "full_text_index_v0")) return false;
            },
            else => return false,
        }

        // Primary rows can be empty while durable identity tombstones and
        // forward/reverse mappings remain. Publishing over that state would
        // combine two identity generations, so validate the catalog first and
        // then require its pristine cardinalities rather than relying only on
        // the visible document count.
        doc_identity.validateStoreAlloc(alloc, self.core.store) catch |err| switch (err) {
            error.InvalidDocIdentity => return false,
            else => return err,
        };
        const identity_stats = try doc_identity.fullStatsFromStore(self.core.store);
        if (identity_stats.next_ordinal != 1 or
            identity_stats.allocated_ordinals != 0 or
            identity_stats.state_rows != 0 or
            identity_stats.live_ordinals != 0 or
            identity_stats.tombstone_ordinals != 0 or
            identity_stats.visibility_chunks != 0 or
            identity_stats.visibility_deleted_ordinals != 0 or
            identity_stats.visibility_mask_bytes != 0 or
            identity_stats.visibility_repair_count != 0)
        {
            return false;
        }

        const lower = [_]u8{internal_keys.user_namespace};
        const upper = [_]u8{internal_keys.user_namespace + 1};
        const Probe = struct {
            found: bool = false,

            fn visit(ctx: ?*anyopaque, _: []const u8, _: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const probe: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                probe.found = true;
                return .stop;
            }
        };
        var probe = Probe{};
        try self.core.store.scanWithContext(&lower, &upper, .{}, &probe, Probe.visit);
        if (probe.found) return false;

        const transactions = try self.core.listTransactions(alloc);
        defer alloc.free(transactions);
        if (transactions.len != 0) return false;

        const enrichments = try self.core.listEnrichments(alloc);
        defer types.freeEnrichmentConfigs(alloc, enrichments);
        if (enrichments.len != 0) return false;

        const resolvers = try self.core.listResolvers(alloc);
        defer {
            for (resolvers) |*resolver| resolver.deinit(alloc);
            if (resolvers.len > 0) alloc.free(resolvers);
        }
        if (resolvers.len != 0) return false;

        const public_schema_json = try self.core.getStoreValue(alloc, public_schema_json_key);
        defer if (public_schema_json) |value| alloc.free(value);
        if (public_schema_json != null) return false;

        // Report permanent durable disqualification before transient activity
        // so clients never retry a target that can only be rejected. A pristine
        // durable store is still unsafe to replace while a caller owns or is
        // waiting on an in-memory write/projection lease; the authoritative
        // publication check holds apply-exclusive and closes the final race.
        if (self.bulkSessionActive() or asyncContextHasActiveDenseBulkWork(self.async_context)) return error.WriterLocked;
        return true;
    }

    /// Returns whether every durable catalog that participates in a portable
    /// restore is pristine. Keep this predicate in DB so CLI, C ABI, and
    /// embedded callers cannot drift into weaker definitions of "empty".
    pub fn isPortableImportTargetEmpty(self: *DB, alloc: Allocator) !bool {
        if (self.open_mode == .status_only) {
            return try self.portableImportTargetEmptyLocked(alloc);
        }
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        return try self.portableImportTargetEmptyLocked(alloc);
    }

    pub fn portableImportRecoveryRequired(self: *const DB) bool {
        return self.core.store.portableImportRecoveryRequired();
    }

    pub const PreparedPortableRuntimeMetadata = struct {
        alloc: Allocator,
        runtime_alloc: Allocator,
        identity_summary: ?doc_identity.VisibilitySummary,
        schema: ?schema_mod.TableSchema,
        schema_replacement: schema_registry_mod.Registry.PreparedReplacement,
        relational_indexes: ?@import("relational_index_catalog.zig").WriteSnapshot,
        table_catalog: table_catalog_mod.Catalog,
        row_policy_lease: row_policy_gate_mod.Gate.Lease,
        recovery: ?db_core.PreparedRecoveryRelationalState,
        target_identity: doc_identity.Namespace,

        pub fn deinit(self: *@This()) void {
            if (self.relational_indexes) |*indexes| indexes.deinit();
            self.schema_replacement.deinit();
            if (self.schema) |schema| schema_mod.freeSchema(self.alloc, schema);
            if (self.recovery) |*recovery| recovery.deinit();
            self.row_policy_lease.release();
            self.* = undefined;
        }
    };

    pub const PortableGenerationPublication = enum {
        complete,
        durability_unknown,
    };

    /// Allocates every schema-dependent runtime object before a durable
    /// generation swap. Applying this object is deliberately infallible.
    pub fn preparePortableRuntimeMetadata(
        self: *DB,
        source_store: *docstore_mod.DocStore,
        target_identity: doc_identity.Namespace,
    ) !PreparedPortableRuntimeMetadata {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        errdefer row_policy_lease.release();
        const identity_summary = try doc_identity.visibilitySummaryFromStore(source_store);
        const restored_schema = try schema_mod.loadSchema(source_store, self.alloc);
        var restored_schema_owned = true;
        defer if (restored_schema_owned) if (restored_schema) |schema| schema_mod.freeSchema(self.alloc, schema);

        var prepared_epoch: ?*schema_registry_mod.Epoch = null;
        if (restored_schema) |runtime_schema| {
            var schema_json: ?[]u8 = null;
            defer if (schema_json) |value| self.alloc.free(value);
            if (runtime_schema.storage_mode == .relational) {
                schema_json = source_store.get(self.alloc, public_schema_json_key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
            }
            prepared_epoch = try self.core.prepareSchemaEpoch(runtime_schema, schema_json);
        }
        var prepared_epoch_owned = prepared_epoch != null;
        defer if (prepared_epoch_owned) prepared_epoch.?.release();
        var schema_replacement = try self.core.prepareSchemaRegistryReplacement(prepared_epoch);
        prepared_epoch_owned = false;
        errdefer schema_replacement.deinit();
        var restored_indexes = try @import("relational_index_catalog.zig").Controller.loadSnapshot(
            self.alloc,
            source_store,
            if (prepared_epoch) |epoch| .{ .epoch = epoch } else null,
        );
        errdefer if (restored_indexes) |*indexes| indexes.deinit();
        // Historical layouts were validated while importing the unpublished
        // image and remain durable in the restored store. Match normal startup:
        // publish only the active epoch and fault historical versions into the
        // registry when a row first references them. This keeps publication
        // latency and resident memory independent of schema-history length.
        const restored_catalog = try db_core.loadTableCatalogForSchema(self.alloc, source_store, restored_schema);
        // Portable publication replaces the owner catalog without replaying
        // policy commands. Until the staged image carries a verified compiled
        // policy epoch and an authenticated principal binding, importing an
        // active policy (or replacing one) would create an unguarded window.
        if (restored_catalog.row_policy_phase != .disabled or self.local_execution.row_policy_gate.currentPhase() != .disabled)
            return error.RowPolicyAuthenticationRequired;
        var prepared_recovery = if (self.transaction_recovery_identity_context != null)
            try db_core.PreparedRecoveryRelationalState.init(
                self.runtime_alloc,
                if (restored_schema) |schema| if (schema.storage_mode == .relational) schema.relational_columns else null else null,
                if (restored_schema) |schema| if (schema.storage_mode == .relational) schema.version else 0 else 0,
            )
        else
            null;
        defer if (prepared_recovery) |*prepared| prepared.deinit();

        const result = PreparedPortableRuntimeMetadata{
            .alloc = self.alloc,
            .runtime_alloc = self.runtime_alloc,
            .identity_summary = identity_summary,
            .schema = restored_schema,
            .schema_replacement = schema_replacement,
            .relational_indexes = restored_indexes,
            .table_catalog = restored_catalog,
            .row_policy_lease = row_policy_lease,
            .recovery = prepared_recovery,
            .target_identity = target_identity,
        };
        restored_schema_owned = false;
        prepared_recovery = null;
        return result;
    }

    fn applyPreparedPortableRuntimeMetadataLocked(self: *DB, prepared: *PreparedPortableRuntimeMetadata) void {
        std.debug.assert(prepared.alloc.ptr == self.alloc.ptr and prepared.alloc.vtable == self.alloc.vtable);
        std.debug.assert(prepared.runtime_alloc.ptr == self.runtime_alloc.ptr and prepared.runtime_alloc.vtable == self.runtime_alloc.vtable);
        self.clearBulkIngestIdentityAllNewLocked();
        self.core.identity_visibility.summary = prepared.identity_summary;
        self.clearLiveDocSetCache();
        self.clearNonVisibleDocSetCache();
        self.core.replaceSchemaOwnedPrepared(prepared.schema, &prepared.schema_replacement, &prepared.relational_indexes);
        prepared.schema = null;
        self.core.table_catalog = prepared.table_catalog;
        self.core.identity_namespace = prepared.target_identity;
        if (self.transaction_recovery_identity_context) |ctx| ctx.updateIdentityNamespace(prepared.target_identity);
        self.publishRelationalRuntimeModePrepared(if (prepared.recovery) |*recovery| recovery else null);
    }

    fn loadPortableRuntimeAfterPublicationLocked(self: *DB) !void {
        try self.core.loadIndexesForRestore();
        if (builtin.is_test and test_fail_portable_index_activation) {
            test_fail_portable_index_activation = false;
            return error.InjectedPortableIndexActivationFailure;
        }
    }

    /// Rebind the catalog while writes are excluded, but perform blocking
    /// worker joins and starts outside that lock. Resolver append callbacks
    /// take the apply lock, so joining under it can deadlock shutdown.
    fn loadPortableRuntimeAfterPublication(self: *DB) !void {
        // Reuse the live-catalog publication barrier so lock-free published
        // dense readers and every structural mutation retire before reset.
        // Acquire it before apply: its runtime drains may themselves need apply.
        var structural_guard = self.beginIndexStructuralMutation("portable runtime activation", "*");
        defer structural_guard.deinit();
        self.stopResolverReplayRuntimes();
        {
            lockApply(self);
            defer self.core.unlockApply();
            try self.loadPortableRuntimeAfterPublicationLocked();
        }
        try self.startResolverReplayRuntimesIfConfigured();
    }

    fn activatePortableIndexesAfterPublication(self: *DB) void {
        lockAtomic(&self.portable_runtime_activation_mutex);
        defer self.portable_runtime_activation_mutex.unlock();
        _ = self.portable_runtime_activation_attempts.fetchAdd(1, .monotonic);
        const activation_result: anyerror!void = self.loadPortableRuntimeAfterPublication();
        activation_result catch |err| {
            self.async_context.portable_runtime_activation_pending.store(true, .release);
            std.log.err("portable generation published but live index activation is degraded path={s} class={s}", .{ self.core.path, @errorName(err) });
            self.startPortableActivationRetryWorkerIfNeeded();
            return;
        };
        self.async_context.portable_runtime_activation_pending.store(false, .release);
        resumeDeferredBackgroundMaintenanceIfIdle(self.async_context);
        self.startQuarantineRetryWorkerIfNeeded();
    }

    fn refreshPortableImportedGenerationLocked(
        self: *DB,
        target_identity: doc_identity.Namespace,
    ) !void {
        var prepared = try self.preparePortableRuntimeMetadata(self.core.store, target_identity);
        defer prepared.deinit();
        self.applyPreparedPortableRuntimeMetadataLocked(&prepared);
        try self.core.loadIndexesForRestore();
    }

    /// Imports directly into a disposable, unpublished DB generation. Portable
    /// blocks are already bounded to small store transactions, so this avoids
    /// both an archive-sized pending transaction and an equally large scratch
    /// LSM. On any failure the owner must discard the generation.
    pub fn importPortableIntoUnpublishedEmpty(
        self: *DB,
        alloc: Allocator,
        backup: []const u8,
        target_identity: doc_identity.Namespace,
    ) !void {
        if (self.open_mode == .status_only or self.open_mode == .query_readonly) return error.UnsupportedOperation;

        lockApply(self);
        defer self.core.unlockApply();
        if (!(try self.portableImportTargetEmptyLocked(alloc))) return error.LiteImportTargetNotEmpty;
        try portable_backup.importPortableWithOptions(alloc, self.core.store, backup, .{
            .identity_namespace = target_identity,
            .prefer_existing_identity_namespace = true,
            .unpublished_staging = true,
        });
        portable_backup.validateCompleteDatabaseImageAlloc(alloc, self.core.store) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return error.InvalidBackupRequest,
        };
        try doc_identity.reassignNamespaceAlloc(alloc, self.core.store, target_identity);
        try self.refreshPortableImportedGenerationLocked(target_identity);
    }

    pub const restoreStagingStatus = local_mutation.restoreStagingStatus;

    pub fn restoreGenerationAdmissionReceipt(self: *DB) !?@import("restore_staging_contract.zig").GenerationAdmissionReceipt {
        var read = try self.core.store.beginReadTxn();
        defer read.abort();
        return @import("restore_generation_admissions.zig").loadReceipt(&read);
    }

    /// Private provisioners call this before cache adoption, after installing
    /// the durable reservation. Initial empty schema/index admission must not
    /// emit a hot-standby mutation before its owner authorization exists.
    pub fn attachRestoreStagingReplicationMirror(self: *DB, mirror: ?ReplicationAsyncEffectMirror) !void {
        if (!self.local_execution.restore_staging_required.load(.acquire)) return error.RestoreStagingScopeChanged;
        if (mirror != null and self.core.table_catalog.row_policy_phase != .disabled)
            return error.RowPolicyUnsupported;
        self.local_execution.replication_async_batch_mirror = mirror;
        self.local_execution.replication_async_effect_mirror = mirror;
        self.local_execution.replication_async_metadata_mirror = mirror;
    }

    /// Retryable owner-side repair for a crash after an import page committed
    /// its primary checkpoint but before projection replay became durable.
    /// Processes one bounded apply window per index, with no external producers.
    pub fn prepareRestoreStagingIndexesStep(self: *DB, alloc: Allocator, scope: [32]u8) !bool {
        return self.prepareRestoreStagingIndexesStepLocal(alloc, scope, false);
    }

    fn prepareRestoreStagingIndexesStepLocal(self: *DB, alloc: Allocator, scope: [32]u8, replicated: bool) !bool {
        var progress = (try self.restoreStagingStatus(alloc)) orelse return error.RestoreStagingScopeChanged;
        defer progress.deinit();
        if (!std.mem.eql(u8, &progress.value.scope.digest(), &scope)) return error.RestoreStagingScopeChanged;
        if (progress.value.phase != .imported and progress.value.phase != .validated and progress.value.phase != .published) return error.RestoreStagingInProgress;
        _ = try self.validateConstraintsStepLocal(.{}, replicated);
        // A persisted receipt is not replica-local relational index coverage.
        // Advance one bounded page independently on every importing/recovering
        // owner, including after a lost validated/published acknowledgement.
        if (self.core.relational_indexes.acquire()) |index_snapshot| {
            var pinned = index_snapshot;
            defer pinned.deinit();
            const indexes = pinned.plan.boundIndexes();
            if (indexes.len != 0) for (0..@min(indexes.len, 16)) |_| {
                const ordinal = self.local_execution.relational_index_maintenance_cursor.fetchAdd(1, .monotonic) % indexes.len;
                const index = indexes[ordinal];
                switch ((try self.relationalIndexBuildStatus(index.name)).state) {
                    .ready => {},
                    .failed => return error.RestoreProjectionCorrupt,
                    .building => {
                        try self.buildRelationalIndexStepLocal(index.name, .{}, replicated);
                        break;
                    },
                }
            };
        }
        replayPendingDerivedBatches(self, null, null, .{
            .truncate_replay = false,
            .max_windows_per_index = 1,
            .deadline_ns = monotonicTimeNs() +| 250 * std.time.ns_per_ms,
        }) catch |err| switch (err) {
            error.CatchUpDeadlineExceeded => return false,
            else => return err,
        };
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (self.core.acquireSchemaView()) |active| {
            var view = active;
            defer view.release();
            if (view.validator()) |validator| if (validator.execution.checks != null) {
                var txn = try self.core.store.beginReadTxn();
                defer txn.abort();
                switch ((try relational_constraint_jobs.status(&txn, view)).state) {
                    .enforced => {},
                    .validating => return false,
                    .invalid => return if (replicated) error.RestoreProjectionCorrupt else error.RelationalCheckViolation,
                }
            };
        }
        if (!(try self.restoreStagingIndexesReadyAssumeApply(alloc))) return false;
        try self.core.index_manager.syncAll(true);
        try self.core.store.sync(true);
        return true;
    }

    fn restoreStagingIndexesReadyAssumeApply(self: *DB, alloc: Allocator) !bool {
        if (self.core.relational_indexes.acquire()) |index_snapshot| {
            var pinned = index_snapshot;
            defer pinned.deinit();
            var read = try self.core.store.beginReadTxn();
            defer read.abort();
            for (pinned.plan.boundIndexes()) |index| {
                switch ((try relational_index_jobs.status(&read, index)).state) {
                    .ready => {},
                    .building => return false,
                    .failed => return error.RestoreProjectionCorrupt,
                }
            }
        }
        const debt = try self.listDerivedReplayDebtAssumeApplyLockHeld(alloc);
        defer {
            for (debt) |*entry| entry.deinit(alloc);
            alloc.free(debt);
        }
        for (debt) |entry| if (entry.catch_up_required) return false;
        return !self.core.index_manager.hasRepairUnavailableIndexes() and !(try self.hasPendingIndexRepairIntents(alloc));
    }

    /// Called by private provisioning before a hidden owner can be hosted.
    /// The artifact is not available yet: this durable reservation admits no
    /// reads or writes, including scoped ones, until authenticated import binds it.
    pub fn reserveRestoreStaging(self: *DB, alloc: Allocator, plan_id: [16]u8, plan_digest: [32]u8, namespace: doc_identity.Namespace) !void {
        const staging = @import("restore_staging.zig");
        const scope: staging.Scope = .{ .plan_id = plan_id, .plan_digest = plan_digest, .target_namespace = namespace, .source_namespace = .{ .table_id = 0, .shard_id = 0, .range_id = 0 }, .source_artifact_digest = @splat(0), .target_schema_digest = @splat(0) };
        return self.reserveRestoreStagingScoped(alloc, scope);
    }

    pub fn reserveRestoreStagingScoped(self: *DB, alloc: Allocator, scope: @import("restore_staging.zig").Scope) !void {
        const staging = @import("restore_staging.zig");
        const namespace = scope.target_namespace;
        try scope.validateReservation();
        if (scope.source_namespace.table_id != 0) try scope.validate();
        if (!namespace.eql(self.core.identity_namespace)) return error.RestoreStagingScopeChanged;
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        var txn = try self.core.store.beginWriteTxn();
        var reservation_txn_open = true;
        defer if (reservation_txn_open) txn.abort();
        if (try staging.optional(&txn)) |raw| {
            var existing = try staging.Progress.decode(alloc, raw);
            defer existing.deinit();
            if (!std.mem.eql(u8, &existing.value.scope.plan_id, &scope.plan_id) or !std.mem.eql(u8, &existing.value.scope.plan_digest, &scope.plan_digest) or !namespace.eql(existing.value.scope.target_namespace)) return error.RestoreStagingScopeChanged;
            if (scope.source_namespace.table_id != 0 and !std.mem.eql(u8, &scope.digest(), &existing.value.scope.digest())) return error.RestoreStagingScopeChanged;
            if (existing.value.phase == .canceled or existing.value.phase == .published) return error.RestoreStagingScopeChanged;
            return;
        }
        if (self.core.table_catalog.row_count != 0) return error.RestoreStagingTargetNotEmpty;
        const raw = try (staging.Progress{ .scope = scope, .phase = .reserved }).encode(alloc);
        defer alloc.free(raw);
        if (try doc_identity.loadNamespaceTxn(&txn)) |stored| {
            if (!stored.eql(namespace)) return error.RestoreStagingScopeChanged;
        } else {
            // Empty document owners may never have written a schema or row.
            // Their reservation itself must make the fresh identity durable.
            var namespace_bytes: [24]u8 = undefined;
            doc_identity.encodeNamespace(&namespace_bytes, namespace);
            try txn.put(internal_keys.identity_namespace_key[0..], &namespace_bytes);
        }
        try txn.put(staging.key, raw);
        try txn.commit();
        reservation_txn_open = false;
        self.local_execution.restore_staging_required.store(true, .release);
        try self.core.store.sync(true);
    }

    /// Receiver-side authority check. A capability never substitutes for the
    /// durable owner marker and its fresh namespace; callers hold a resident DB lease.
    pub fn validateRestoreStagingScope(self: *DB, alloc: Allocator, scope: [32]u8) !void {
        var txn = try self.core.store.beginReadTxn();
        defer txn.abort();
        try @import("restore_staging.zig").requireScope(alloc, &txn, scope, false);
    }

    pub fn beginRestoreStaging(self: *DB, alloc: Allocator, scope: @import("restore_staging.zig").Scope) !void {
        return self.beginRestoreStagingWithMarker(alloc, scope, null, null, null);
    }

    /// Install the immutable historical read mapping before constructing any
    /// versioned projection. This does not switch the active row schema or
    /// import source-local migration progress. hot-standby begin carries the same mapping
    /// so followers reconstruct it before accepting row effects.
    pub fn installRestoreStagingReadSchema(self: *DB, alloc: Allocator, scope: @import("restore_staging.zig").Scope, read_json: []const u8) !void {
        if (read_json.len == 0) return;
        try scope.validate();
        var previous = try public_table_schema.parseValidatedTableSchema(alloc, read_json);
        defer previous.deinit(alloc);
        const historical = try public_table_schema.deriveRuntimeTableSchema(alloc, previous);
        defer schema_mod.freeSchema(alloc, historical);
        const encoded = try schema_mod.serializeSchema(alloc, historical);
        defer alloc.free(encoded);
        const runtime_key = try schema_mod.schemaVersionKeyAlloc(alloc, historical.version);
        defer alloc.free(runtime_key);
        const public_key = try public_table_schema.versionedSchemaKeyAlloc(alloc, historical.version);
        defer alloc.free(public_key);
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (!scope.target_namespace.eql(self.core.identity_namespace)) return error.RestoreStagingScopeChanged;
        const active = self.core.schema orelse return error.RestoreStagingScopeChanged;
        if (historical.version >= active.version or historical.storage_mode != active.storage_mode) return error.InvalidRestoreMigrationState;
        const active_encoded = try schema_mod.serializeSchema(alloc, active);
        defer alloc.free(active_encoded);
        if (!std.mem.eql(u8, &@import("restore_staging.zig").digest(active_encoded), &scope.target_schema_digest)) return error.RestoreStagingScopeChanged;
        var txn = try self.core.store.beginWriteTxn();
        var history_txn_open = true;
        defer if (history_txn_open) txn.abort();
        var history_mutable = true;
        if (try @import("restore_staging.zig").optional(&txn)) |raw| {
            var status = try @import("restore_staging.zig").Progress.decode(alloc, raw);
            defer status.deinit();
            if (!std.mem.eql(u8, &status.value.scope.digest(), &scope.digest())) return error.RestoreStagingScopeChanged;
            history_mutable = status.value.phase == .reserved;
        } else if (self.core.table_catalog.row_count != 0) return error.RestoreStagingTargetNotEmpty;
        const prior_bootstrap = txn.get(@import("restore_staging.zig").bootstrap_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (prior_bootstrap) |bytes| {
            var prior = try @import("restore_staging.zig").OwnerBootstrap.decode(alloc, bytes);
            defer prior.deinit();
            if (!std.mem.eql(u8, prior.value.read_schema_json, read_json)) return error.RestoreStagingScopeChanged;
        }
        const existing = txn.get(runtime_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (existing) |bytes| if (!std.mem.eql(u8, bytes, encoded)) return error.RestoreStagingScopeChanged;
        const existing_public = txn.get(public_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (existing_public) |bytes| if (!std.mem.eql(u8, bytes, read_json)) return error.RestoreStagingScopeChanged;
        if (existing != null and existing_public != null) return;
        if (!history_mutable) return error.RestoreStagingScopeChanged;
        try txn.put(runtime_key, encoded);
        try txn.put(public_key, read_json);
        try txn.commit();
        history_txn_open = false;
        try self.core.store.sync(true);
    }

    pub fn installRestoreStagingBootstrap(self: *DB, alloc: Allocator, descriptor: @import("restore_staging.zig").OwnerBootstrap) !void {
        const staging = @import("restore_staging.zig");
        try descriptor.validate();
        try @import("../../schema/restore_migration.zig").validate(alloc, descriptor.schema_json, descriptor.read_schema_json);
        try self.installRestoreStagingReadSchema(alloc, descriptor.scope, descriptor.read_schema_json);
        const encoded = try descriptor.encode(alloc);
        defer alloc.free(encoded);
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (!descriptor.scope.target_namespace.eql(self.core.identity_namespace) or !std.mem.eql(u8, descriptor.byte_range.start, self.core.byteRange().start) or !std.mem.eql(u8, descriptor.byte_range.end, self.core.byteRange().end)) return error.RestoreStagingScopeChanged;
        var txn = try self.core.store.beginWriteTxn();
        var txn_open = true;
        defer if (txn_open) txn.abort();
        const marker = (try staging.optional(&txn)) orelse return error.RestoreStagingScopeChanged;
        var progress = try staging.Progress.decode(alloc, marker);
        defer progress.deinit();
        if (!std.mem.eql(u8, &progress.value.scope.digest(), &descriptor.scope.digest())) return error.RestoreStagingScopeChanged;
        const previous = txn.get(staging.bootstrap_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (previous) |bytes| {
            if (!std.mem.eql(u8, bytes, encoded)) return error.RestoreStagingScopeChanged;
            return;
        }
        if (progress.value.phase != .reserved) return error.RestoreStagingScopeChanged;
        const public_json = txn.get(public_schema_json_key) catch |err| switch (err) {
            error.NotFound => "",
            else => return err,
        };
        if (!std.mem.eql(u8, public_json, descriptor.schema_json)) return error.RestoreStagingScopeChanged;
        const native_schema = try schema_mod.serializeSchema(alloc, self.core.schema orelse .{});
        defer alloc.free(native_schema);
        if (!std.mem.eql(u8, &staging.digest(native_schema), &descriptor.scope.target_schema_digest)) return error.RestoreStagingScopeChanged;
        try txn.put(staging.bootstrap_key, encoded);
        try txn.commit();
        txn_open = false;
        try self.core.store.sync(true);
    }

    pub fn readRestoreStagingBootstrap(self: *DB, alloc: Allocator) !?std.json.Parsed(@import("restore_staging.zig").OwnerBootstrap) {
        const staging = @import("restore_staging.zig");
        const stored = try self.core.getStoreValue(alloc, staging.bootstrap_key);
        defer if (stored) |bytes| alloc.free(bytes);
        if (stored) |bytes| return try staging.OwnerBootstrap.decode(alloc, bytes);
        return null;
    }

    /// A cold, read-only physical proof for canceled initial FK retirement.
    /// This does not consult or synthesize a public catalog route.
    pub fn readInitialChildPublicationRecord(self: *DB) !?@import("relational_initial_child_publication.zig").Record {
        var txn = try self.core.store.beginReadTxn();
        defer txn.abort();
        return @import("relational_initial_child_publication.zig").load(&txn);
    }

    /// Local terminal retirement only, after Raft and all physical owners have
    /// drained under an authenticated exact-root cancellation ticket. This is
    /// not a Raft receipt and must never be used to publish/release a child.
    pub fn cancelColdInitialChildForRetirement(self: *DB, expected: @import("relational_initial_child_publication.zig").Record, cancel_revision: u64) !void {
        const hidden = @import("relational_initial_child_publication.zig");
        try expected.validate();
        if (cancel_revision == 0 or expected.phase == .released) return error.InitialChildPublicationChanged;
        var txn = try self.core.store.beginWriteTxn();
        errdefer txn.abort();
        const current = (try hidden.load(&txn)) orelse return error.InitialChildPublicationMissing;
        if (!current.samePlan(expected) or current.phase == .released) return error.InitialChildPublicationChanged;
        const table_raw = txn.get(@import("table_catalog.zig").key) catch return error.InitialChildPublicationChanged;
        if ((try @import("table_catalog.zig").Catalog.decode(table_raw)).row_count != 0) return error.InitialChildPublicationChanged;
        // The terminal metadata revision identifies this local-only phase;
        // no data-Raft applied watermark is advanced or fabricated.
        _ = try hidden.stagePhase(&txn, current, .canceled, @max(current.provision_term, 1), cancel_revision);
        try txn.commit();
    }

    fn encodeRestoreStagingReplicationPayload(self: *DB, req: types.BatchRequest, ordered_receipt: ?OrderedApplyReceipt) ![]u8 {
        const staging = @import("restore_staging.zig");
        if (req.restore_staging.? == .install_generation_admissions)
            return replication_effects_mod.encodeRestoreGenerationAdmissionMutationRequestAlloc(self.alloc, req, ordered_receipt orelse return error.InvalidRestoreStagingCommand);
        if (req.restore_staging.? == .begin) {
            const stored = try self.core.getStoreValue(self.alloc, staging.bootstrap_key);
            defer if (stored) |bytes| self.alloc.free(bytes);
            if (stored) |bytes| {
                var descriptor = try staging.OwnerBootstrap.decode(self.alloc, bytes);
                defer descriptor.deinit();
                return replication_effects_mod.encodeBatchMutationWithRestoreBootstrapAlloc(self.alloc, req, descriptor.value);
            }
        }
        return replication_effects_mod.encodeBatchMutationRequestAlloc(self.alloc, req);
    }

    /// An exact replicated completion receipt may survive a crash before its
    /// local index coverage does. Repair only the still-current scope/phase;
    /// old entries and canceled/replaced attempts retain no-op replay semantics.
    /// This never reapplies logical controls or advances replication markers.
    fn prepareAppliedRestoreFinishReplay(self: *DB, req: types.BatchRequest) !void {
        const command = req.restore_staging orelse return;
        if (command != .finish or (command.finish.phase != .validated and command.finish.phase != .published)) return;
        var progress = (try self.restoreStagingStatus(self.alloc)) orelse return;
        defer progress.deinit();
        if (progress.value.phase != command.finish.phase or !std.mem.eql(u8, &progress.value.scope.digest(), &command.finish.scope)) return;
        const ready = self.prepareRestoreStagingIndexesStepLocal(self.alloc, command.finish.scope, true) catch |err| switch (err) {
            // A concurrently completed cancellation/replacement must not turn
            // an already-applied entry into a stale logical command failure.
            error.RestoreStagingScopeChanged, error.RestoreStagingInProgress => return,
            else => return err,
        };
        if (!ready) return error.RestoreProjectionCatchUpPending;
    }

    fn installRestoreGenerationAdmissionsWithMarker(
        self: *DB,
        alloc: Allocator,
        command: @import("restore_staging_contract.zig").InstallGenerationAdmissions,
        marker: ?OrderedApplyReceipt,
        replication_lsn: ?u64,
        replication_payload: ?[]const u8,
    ) !@import("restore_staging_contract.zig").GenerationAdmissionReceipt {
        const contract = @import("restore_staging_contract.zig");
        const entry = marker orelse return error.InvalidRestoreStagingCommand;
        const expected = try contract.admissionReceiptDigest(command);
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        var txn = try self.core.store.beginWriteTxn();
        var txn_open = true;
        defer if (txn_open) txn.abort();
        const bootstrap_bytes = txn.get(contract.bootstrap_key) catch |err| switch (err) {
            error.NotFound => return error.RestoreStagingScopeChanged,
            else => return err,
        };
        var bootstrap = try contract.OwnerBootstrap.decode(alloc, bootstrap_bytes);
        defer bootstrap.deinit();
        const binding = bootstrap.value.generation_admission orelse return error.RestoreSourceProofMissing;
        const source_proof_digest = bootstrap.value.source_generation_proof_digest orelse return error.RestoreSourceProofMissing;
        if (!std.mem.eql(u8, &bootstrap.value.scope.digest(), &command.scope) or
            !std.mem.eql(u8, &source_proof_digest, &binding.source_summary_digest) or
            !std.mem.eql(u8, &binding.source_summary_digest, &command.source_summary_digest) or
            !std.mem.eql(u8, &binding.expected_receipt_digest, &expected))
            return error.RestoreStagingScopeChanged;
        switch (try orderedApplyDisposition(try readOrderedApplyReceipt(alloc, self.core.store), entry)) {
            .already_applied => {
                const receipt = (try @import("restore_generation_admissions.zig").loadReceipt(&txn)) orelse
                    return error.RestoreSourceProofMissing;
                if (!std.mem.eql(u8, &receipt.logical_digest, &expected) or
                    !std.mem.eql(u8, &receipt.scope, &command.scope)) return error.RestoreStagingScopeChanged;
                return receipt;
            },
            .apply => {},
        }
        const receipt = try @import("restore_generation_admissions.zig").stageInstall(alloc, &txn, command, entry.term, entry.index);
        var marker_bytes: [ordered_apply_receipt_value_len]u8 = undefined;
        const applied = orderedApplyReceiptWrite(entry, &marker_bytes);
        try txn.put(applied.key, applied.value);
        if (replication_lsn) |lsn| {
            var lsn_bytes: [replication_applied_lsn_value_len]u8 = undefined;
            const replicated = replicationAppliedSequenceWrite(lsn, &lsn_bytes);
            try txn.put(replicated.key, replicated.value);
        }
        try self.stageRestoreStagingReplicationOutbox(&txn, replication_payload);
        try txn.commit();
        txn_open = false;
        try self.core.store.sync(true);
        return receipt;
    }

    /// Control payload and owner marker are committed together. Every hot-standby mode
    /// retains a local append obligation; remote acknowledgement still follows
    /// the configured policy. Retrying an applied Raft entry drains this record.
    fn applyRestoreStagingControl(self: *DB, req: types.BatchRequest, opts: BatchExecutionOptions) !void {
        // Local index/CHECK progress is not a deterministic command result.
        // A follower may have committed the previous import's primary/Raft
        // receipt before its projection watermark was durable. Repair one
        // bounded local slice on EVERY committed-control retry; no optional
        // worker or leader RPC is required, and no apply lock is held here.
        if (opts.ordered_apply_receipt != null or opts.replication_applied_lsn_marker != null) {
            if (req.restore_staging.? == .finish and (req.restore_staging.?.finish.phase == .validated or req.restore_staging.?.finish.phase == .published)) {
                if (!try self.prepareRestoreStagingIndexesStepLocal(self.alloc, req.restore_staging.?.finish.scope, true)) return error.RestoreProjectionCatchUpPending;
            }
        }
        var mutation = if (opts.bypass_replication_write_gate) null else self.acquireReplicationMutationShared();
        defer if (mutation) |*lease| lease.release();
        if (!opts.bypass_replication_write_gate) {
            try self.enforceReplicationWriteGate();
            try self.ensureDurableReplicationStartupBarrier();
            try self.flushDurableReplicationOutboxes();
            try self.preflightReplicationBatchSyncCommit();
        }
        const payload = if (!opts.bypass_replication_write_gate and self.local_execution.replication_async_batch_mirror != null)
            try self.encodeRestoreStagingReplicationPayload(req, opts.ordered_apply_receipt)
        else
            null;
        defer if (payload) |bytes| self.alloc.free(bytes);
        switch (req.restore_staging.?) {
            .begin => |scope| try self.beginRestoreStagingWithMarker(self.alloc, scope, opts.ordered_apply_receipt, opts.replication_applied_lsn_marker, payload),
            .finish => |finish| _ = try self.finishRestoreStagingWithMarker(self.alloc, finish.scope, finish.phase, opts.ordered_apply_receipt, opts.replication_applied_lsn_marker, payload),
            .install_generation_admissions => |install| _ = try self.installRestoreGenerationAdmissionsWithMarker(self.alloc, install, opts.ordered_apply_receipt, opts.replication_applied_lsn_marker, payload),
            .import_page, .rewrite_page => unreachable,
        }
        if (payload != null) try self.flushDurableReplicationOutboxes();
    }

    /// Authenticated hot-standby resolution records carry final native effects, not
    /// participant commands. They may touch only this hidden owner's current
    /// claims/coverage; primary rows enter exclusively through import controls.
    pub const validateRestoreStagingReplicationEffects = local_mutation.validateRestoreStagingReplicationEffects;

    /// A committed live transaction is mirrored as final rows + metadata, not
    /// as participant intents. Only the authenticated hot-standby entrypoint supplies
    /// the applied-LSN capability. Recheck protected effects against this
    /// owner's immutable catalog; this is not an ordinary batch escape hatch.
    pub const validateLiveReplicationIntegrityEffects = local_mutation.validateLiveReplicationIntegrityEffects;

    fn stageRestoreStagingReplicationOutbox(self: *DB, txn: anytype, payload: ?[]const u8) !void {
        const bytes = payload orelse return;
        const mirror = self.local_execution.replication_async_batch_mirror orelse return error.ReplicationPublisherUnavailable;
        const from_lsn = mirror.publisher.nextLsn();
        const encoded = try encodeDurableReplicationOutboxAlloc(self.alloc, from_lsn, bytes);
        defer self.alloc.free(encoded);
        const outbox_key = try durableReplicationOutboxKeyAlloc(self.alloc, .restore_batch, from_lsn, self.core.root_generation, bytes);
        defer self.alloc.free(outbox_key);
        try txn.put(outbox_key, encoded);
        // A failed transaction may leave a false positive, which the bounded
        // outbox scan clears. Never expose a committed obligation as absent.
        self.local_execution.durable_replication_outbox_maybe.store(true, .release);
    }

    fn beginRestoreStagingWithMarker(self: *DB, alloc: Allocator, scope: @import("restore_staging.zig").Scope, marker: ?OrderedApplyReceipt, replication_lsn: ?u64, replication_payload: ?[]const u8) !void {
        const staging = @import("restore_staging.zig");
        try scope.validate();
        if (!scope.target_namespace.eql(self.core.identity_namespace)) return error.RestoreStagingScopeChanged;
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        if (marker) |entry| switch (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), entry)) {
            .already_applied => return,
            .apply => {},
        };
        var manager = try self.core.initTxnManager();
        defer manager.deinit();
        if (try manager.hasSchemaLeases()) return error.SchemaInUse;
        var txn = try self.core.store.beginWriteTxn();
        var txn_open = true;
        defer if (txn_open) txn.abort();
        if (try staging.optional(&txn)) |raw| {
            var existing = try staging.Progress.decode(alloc, raw);
            defer existing.deinit();
            if (existing.value.phase == .reserved) {
                if (!std.mem.eql(u8, &scope.plan_id, &existing.value.scope.plan_id) or !std.mem.eql(u8, &scope.plan_digest, &existing.value.scope.plan_digest) or !scope.target_namespace.eql(existing.value.scope.target_namespace)) return error.RestoreStagingScopeChanged;
                if (existing.value.scope.source_namespace.table_id != 0 and !std.mem.eql(u8, &scope.digest(), &existing.value.scope.digest())) return error.RestoreStagingScopeChanged;
            } else {
                if (!std.mem.eql(u8, &scope.digest(), &existing.value.scope.digest())) return error.RestoreStagingScopeChanged;
                if (existing.value.phase == .canceled) return error.RestoreStagingCanceled;
                if (marker != null or replication_lsn != null or replication_payload != null) {
                    if (marker) |entry| {
                        var buffer: [ordered_apply_receipt_value_len]u8 = undefined;
                        const write = orderedApplyReceiptWrite(entry, &buffer);
                        try txn.put(write.key, write.value);
                    }
                    if (replication_lsn) |lsn| {
                        var buffer: [replication_applied_lsn_value_len]u8 = undefined;
                        const write = replicationAppliedSequenceWrite(lsn, &buffer);
                        try txn.put(write.key, write.value);
                    }
                    try self.stageRestoreStagingReplicationOutbox(&txn, replication_payload);
                    try txn.commit();
                    txn_open = false;
                }
                return;
            }
        }
        if (self.core.table_catalog.row_count != 0) return error.RestoreStagingTargetNotEmpty;
        if (scope.empty_generation) {
            if ((scope.graph_retirement_digest != null) != self.core.index_manager.hasGraphIndexes()) return error.RestoreStagingScopeChanged;
            if (scope.graph_retirement_digest != null) for (self.core.index_manager.graph_indexes.items) |*entry| {
                try entry.index.requirePristineEmptyGeneration();
            };
            if (scope.graph_retirement_digest != null) {
                // Source-owned graph edge/state/contender rows live in the
                // primary store, outside the graph index's private stores.
                // An empty row count cannot prove these orphan artifacts
                // absent. The new owner normally has no user-key band, so
                // this is one bounded early-exit cursor walk at admission.
                var graph_cursor = try txn.openPhysicalCursorAdapter();
                defer graph_cursor.close();
                var entry = try graph_cursor.seekAtOrAfter(&.{internal_keys.replay_namespace});
                while (entry) |record| {
                    if (record.key.len == 0 or record.key[0] != internal_keys.replay_namespace or
                        (record.key.len > 1 and record.key[1] == 0xff)) break;
                    if (internal_keys.isGraphEdgeArtifactKey(record.key) or
                        internal_keys.isGraphAssetStateKey(record.key) or
                        internal_keys.isGraphEdgeContenderKey(record.key)) return error.RestoreStagingTargetNotEmpty;
                    entry = try graph_cursor.next();
                }
                const global_prefix = [_]u8{ internal_keys.replay_namespace, 0xff, internal_keys.graph_global_edge_contender_kind };
                if (try graph_cursor.seekAtOrAfter(&global_prefix)) |record| if (std.mem.startsWith(u8, record.key, &global_prefix)) return error.RestoreStagingTargetNotEmpty;
            }
            // These global secondary records lie outside document identity's
            // user-key proof. A fresh generation must not inherit claims or
            // ordered-index entries even if a corrupt counter says zero.
            var cursor = try txn.openPhysicalCursorAdapter();
            defer cursor.close();
            for ([_][]const u8{ @import("relational_integrity_contract.zig").namespace, @import("relational_index_records.zig").forward_namespace, @import("relational_index_records.zig").ownership_namespace }) |prefix| {
                if (try cursor.seekAtOrAfter(prefix)) |entry| if (std.mem.startsWith(u8, entry.key, prefix)) return error.RestoreStagingTargetNotEmpty;
            }
        }
        const schema_bytes = try schema_mod.serializeSchema(alloc, self.core.schema orelse .{});
        defer alloc.free(schema_bytes);
        if (!std.mem.eql(u8, &staging.digest(schema_bytes), &scope.target_schema_digest)) return error.RestoreStagingScopeChanged;
        var initial_identity_summary: ?doc_identity.VisibilitySummary = null;
        if (scope.preserve_artifacts or scope.empty_generation) {
            // Native cache pages precede primary rows. Bind a proven-pristine
            // identity root and exact zero cardinality before those artifacts
            // make an absent visibility summary ambiguous. Keep these facts
            // atomic with scope admission, Raft/standby markers, and outbox.
            initial_identity_summary = (try doc_identity.initializePristineVisibilitySummaryTxn(&txn, scope.target_namespace)) orelse return error.RestoreStagingTargetNotEmpty;
            if (try range_cardinality.loadFromTxn(&txn)) |count| {
                if (count != 0) return error.RestoreStagingTargetNotEmpty;
            } else {
                const zero = @as([8]u8, @splat(0));
                try txn.put(&internal_keys.range_document_count_key, &zero);
            }
        }
        const raw_catalog = txn.get(@import("relational_integrity_catalog.zig").key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (raw_catalog) |bytes| {
            var catalog = try @import("relational_integrity_catalog.zig").decode(alloc, bytes);
            defer catalog.deinit();
            if (try staging.initialCoverage(alloc, &txn, catalog)) |coverage| {
                defer alloc.free(coverage);
                try txn.put(@import("relational_integrity_activation.zig").key, coverage);
            }
        }
        const bootstrap_raw = txn.get(staging.bootstrap_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        var source_proofs_required = false;
        if (bootstrap_raw) |bytes| {
            var bootstrap = try staging.OwnerBootstrap.decode(alloc, bytes);
            defer bootstrap.deinit();
            if (!std.mem.eql(u8, &bootstrap.value.scope.digest(), &scope.digest())) return error.RestoreStagingScopeChanged;
            source_proofs_required = bootstrap.value.source_generation_proof_digest != null;
        }
        const initial = try (staging.Progress{ .scope = scope, .phase = if (scope.empty_generation) .imported else .importing, .source_generation_proofs_complete = !source_proofs_required, .rewrite = if (scope.rewrite) |rewrite| .{ .sequence = rewrite.retained_start } else null }).encode(alloc);
        defer alloc.free(initial);
        try txn.put(staging.key, initial);
        try self.stageRestoreStagingReplicationOutbox(&txn, replication_payload);
        if (replication_lsn) |lsn| {
            var buffer: [replication_applied_lsn_value_len]u8 = undefined;
            const write = replicationAppliedSequenceWrite(lsn, &buffer);
            try txn.put(write.key, write.value);
        }
        if (marker) |entry| {
            var buffer: [ordered_apply_receipt_value_len]u8 = undefined;
            const write = orderedApplyReceiptWrite(entry, &buffer);
            try txn.put(write.key, write.value);
        }
        try txn.commit();
        txn_open = false;
        if (initial_identity_summary) |summary| self.core.identity_visibility.summary = summary;
        self.local_execution.restore_staging_required.store(true, .release);
        try self.core.store.sync(true);
    }

    /// Source is a verified immutable artifact opened read-only by the shared
    /// restore driver. Each page decodes its declared historical layout once
    /// and feeds logical rows through the target's normal preparation pipeline.
    pub fn importRestoreStagingPage(self: *DB, alloc: Allocator, scope: @import("restore_staging.zig").Scope, source: *DB, max_rows: usize, cancellation: types.CancellationToken) !@import("restore_staging.zig").Phase {
        var prepared = try self.prepareRestoreStagingPage(alloc, scope, source, max_rows, cancellation);
        defer prepared.deinit();
        if (prepared.batch) |req| try self.batchReplicatedApply(req);
        try self.core.store.sync(true);
        return prepared.phase;
    }

    pub fn prepareRestoreStagingPage(self: *DB, alloc: Allocator, scope: @import("restore_staging.zig").Scope, source: *DB, max_rows: usize, cancellation: types.CancellationToken) !@import("restore_staging.zig").PreparedPage {
        if (scope.rewrite != null or scope.empty_generation) return error.InvalidRestoreStagingCommand;
        return self.prepareRestoreStagingPageInternal(alloc, scope, source, max_rows, cancellation, null);
    }

    pub fn prepareRewriteStagingPage(self: *DB, alloc: Allocator, scope: @import("restore_staging.zig").Scope, source: *DB, max_rows: usize, cancellation: types.CancellationToken, program: *const @import("relational_rewrite_staging.zig").ProgramSet) !@import("restore_staging.zig").PreparedPage {
        try program.requireScope(scope);
        try @import("relational_rewrite_staging.zig").requireSnapshotSource(alloc, scope, source);
        return self.prepareRestoreStagingPageInternal(alloc, scope, source, max_rows, cancellation, program);
    }

    fn prepareRestoreStagingPageInternal(self: *DB, alloc: Allocator, scope: @import("restore_staging.zig").Scope, source: *DB, max_rows: usize, cancellation: types.CancellationToken, program: ?*const @import("relational_rewrite_staging.zig").ProgramSet) !@import("restore_staging.zig").PreparedPage {
        const staging = @import("restore_staging.zig");
        if (max_rows == 0 or max_rows > 128 or source.open_mode != .query_readonly or !source.core.identity_namespace.eql(scope.source_namespace)) return error.InvalidRestoreStagingCommand;
        if (!std.mem.eql(u8, source.core.byteRange().start, self.core.byteRange().start) or !std.mem.eql(u8, source.core.byteRange().end, self.core.byteRange().end)) return error.RestoreStagingScopeChanged;
        var arena = std.heap.ArenaAllocator.init(alloc);
        errdefer arena.deinit();
        const owned = arena.allocator();
        const raw = (try self.core.getStoreValue(owned, staging.key)) orelse return error.RestoreStagingScopeChanged;
        const parsed = try staging.Progress.decode(owned, raw);
        var next = parsed.value;
        if (!std.mem.eql(u8, &next.scope.digest(), &scope.digest())) return error.RestoreStagingScopeChanged;
        if (next.phase == .canceled) return error.RestoreStagingCanceled;
        if (next.phase == .reserved) return error.RestoreStagingInProgress;
        if (next.phase != .importing) return .{ .arena = arena, .phase = next.phase, .batch = null };
        if (!next.source_generation_proofs_complete) {
            const portable = @import("../portable_backup.zig");
            var bootstrap = (try self.readRestoreStagingBootstrap(alloc)) orelse return error.RestoreSourceProofMissing;
            defer bootstrap.deinit();
            const expected_digest = bootstrap.value.source_generation_proof_digest orelse return error.RestoreSourceProofMissing;
            if (!std.mem.eql(u8, &bootstrap.value.scope.digest(), &scope.digest())) return error.RestoreStagingScopeChanged;
            var source_read = try source.core.store.beginReadTxn();
            defer source_read.abort();
            var proofs = try portable.sourceGenerationAdmissionProofPageAlloc(alloc, &source_read, scope.source_namespace);
            defer proofs.deinit();
            if (!std.mem.eql(u8, &expected_digest, &try portable.sourceGenerationAdmissionSummaryDigest(scope.source_namespace, proofs.entries)))
                return error.RestoreSourceProofMissing;
            const artifacts = try owned.alloc(staging.Artifact, proofs.artifacts.len);
            for (proofs.artifacts, artifacts) |proof, *artifact| artifact.* = .{
                .key = try owned.dupe(u8, proof.key),
                .value = try owned.dupe(u8, proof.value),
            };
            next.source_generation_proofs_complete = true;
            const encoded_progress = try next.encode(owned);
            return .{ .arena = arena, .phase = next.phase, .batch = .{ .sync_level = .write, .restore_staging = .{ .import_page = .{
                .expected = staging.digest(raw),
                .next = encoded_progress,
                .scope = scope.digest(),
                .timestamps = &.{},
                .source_generation_proof_page = true,
                .artifacts = artifacts,
            } } } };
        }
        if (next.rewrite) |rewrite| if (rewrite.snapshot_complete) return .{ .arena = arena, .phase = next.phase, .batch = null };
        if (scope.preserve_artifacts and (!next.artifacts_complete or next.rows_complete)) {
            // Import immutable generated inputs before primary rows. Normal
            // row preparation can then rebuild target-local index identities
            // using cached provider results, without issuing remote requests.
            var read = try source.core.store.beginReadTxn();
            defer read.abort();
            var artifacts_cursor = try read.openCursor();
            defer artifacts_cursor.close();
            const projections = next.rows_complete;
            var write_plan = if (!projections) try self.core.index_manager.acquireWritePlanSnapshot() else null;
            defer if (write_plan) |*view| view.release();
            var generated_embeddings: std.StringHashMapUnmanaged(void) = .empty;
            if (write_plan) |view| for (view.plan().generated_templates) |request| {
                if (request.kind == .dense_embedding or request.kind == .sparse_embedding)
                    try generated_embeddings.put(owned, requestEmbeddingName(request), {});
            };
            const continuation = if (projections) &next.projection_cursor else &next.artifact_cursor;
            // Skipped records retain only one continuation and one record's
            // scratch data, never one allocation per scan step in the page.
            var continuation_buffer: std.ArrayList(u8) = .empty;
            defer continuation_buffer.deinit(alloc);
            var record_arena = std.heap.ArenaAllocator.init(alloc);
            defer record_arena.deinit();
            var artifact_entry = try artifacts_cursor.seekAtOrAfter(if (continuation.*.len == 0) &.{internal_keys.user_namespace} else continuation.*);
            if (artifact_entry) |row| if (std.mem.eql(u8, row.key, continuation.*)) {
                artifact_entry = try artifacts_cursor.next();
            };
            var artifacts: std.ArrayList(staging.Artifact) = .empty;
            var artifact_bytes: usize = 0;
            var examined_artifacts: usize = 0;
            // Artifact and projection passes only scan the immutable source;
            // they often emit no writes. Give a bounded cursor turn enough
            // time to amortize reopening the decoder and committing its
            // continuation, while retaining per-record cancellation and the
            // 1024-record/128-artifact/16 MiB page ceilings below.
            const artifact_deadline = monotonicTimeNs() +| 100 * std.time.ns_per_ms;
            while (artifact_entry) |row| : (artifact_entry = try artifacts_cursor.next()) {
                _ = record_arena.reset(.retain_capacity);
                const scratch = record_arena.allocator();
                if (cancellation.isCancelled()) return error.Canceled;
                if (row.key.len == 0 or row.key[0] != internal_keys.user_namespace) {
                    artifact_entry = null;
                    break;
                }
                if (artifacts.items.len == max_rows or examined_artifacts == 1024 or
                    (examined_artifacts != 0 and monotonicTimeNs() >= artifact_deadline)) break;
                if (if (projections) isMergeArtifactKey(row.key) else isRestoreArtifactKey(row.key)) {
                    if (row.key.len > 16 * 1024 * 1024 or row.value.len > 16 * 1024 * 1024 - row.key.len) return error.TransactionTooLarge;
                    const owner = (try internal_keys.decodeDocumentComponentAlloc(scratch, row.key)) orelse return error.InvalidRestoreStagingCommand;
                    if (!self.core.byteRange().contains(owner)) return error.RestoreStagingScopeChanged;
                    if (!projections and (internal_keys.isEmbeddingArtifactKey(row.key) or internal_keys.isDerivedEmbeddingArtifactKey(row.key)) and
                        !(try enrichment_artifact_codec.decodeHeader(row.value)).flags.has_source_hash)
                    {
                        const embedding = (try artifact_ids.decodeEmbeddingArtifactIdentityAlloc(scratch, row.key)) orelse return error.InvalidRestoreStagingCommand;
                        if (generated_embeddings.contains(embedding.embedding_name)) {
                            // Portable vectors lack producer provenance. A
                            // managed producer must regenerate them, even when
                            // this hidden owner's optional runtime is absent.
                            // External vectors have no producer and remain data.
                            continuation_buffer.clearRetainingCapacity();
                            try continuation_buffer.appendSlice(alloc, row.key);
                            continuation.* = continuation_buffer.items;
                            examined_artifacts += 1;
                            continue;
                        }
                    }
                    const value = if (internal_keys.isGraphEdgeArtifactKey(row.key)) graph: {
                        const edge = (try internal_keys.parseGraphEdgeArtifactKeyAlloc(scratch, row.key)) orelse return error.InvalidRestoreStagingCommand;
                        const index = self.core.index_manager.graphIndex(edge.index_name);
                        if (index == null or enrichment_artifact_codec.isLegacyUnboundGraphEdge(row.value)) {
                            continuation_buffer.clearRetainingCapacity();
                            try continuation_buffer.appendSlice(alloc, row.key);
                            continuation.* = continuation_buffer.items;
                            examined_artifacts += 1;
                            continue;
                        }
                        const decoded = try enrichment_artifact_codec.decodeGraphEdgeAlloc(scratch, row.value);
                        if (decoded.generation != index.?.config.coverage_generation and !enrichment_artifact_codec.isPortableUnboundGraphEdge(row.value)) {
                            continuation_buffer.clearRetainingCapacity();
                            try continuation_buffer.appendSlice(alloc, row.key);
                            continuation.* = continuation_buffer.items;
                            examined_artifacts += 1;
                            continue;
                        }
                        break :graph try enrichment_artifact_codec.encodePortableUnboundGraphEdgeWithTtlAlloc(scratch, decoded.weight, decoded.created_at, decoded.updated_at, decoded.ttl_created_ns, decoded.metadata_json);
                    } else if (projections) current: {
                        // Row preparation may regenerate (or remove) a portable
                        // cache entry. Project the target's current artifact,
                        // never overwrite it with an archived generated value.
                        break :current self.core.store.get(scratch, row.key) catch |err| switch (err) {
                            error.NotFound => {
                                continuation_buffer.clearRetainingCapacity();
                                try continuation_buffer.appendSlice(alloc, row.key);
                                continuation.* = continuation_buffer.items;
                                examined_artifacts += 1;
                                continue;
                            },
                            else => return err,
                        };
                    } else row.value;
                    const size = std.math.add(usize, row.key.len, value.len) catch return error.TransactionTooLarge;
                    if (size > 16 * 1024 * 1024) return error.TransactionTooLarge;
                    if (artifacts.items.len != 0 and artifact_bytes + size > 16 * 1024 * 1024) break;
                    try artifacts.append(owned, .{ .key = try owned.dupe(u8, row.key), .value = try owned.dupe(u8, value) });
                    artifact_bytes += size;
                }
                continuation_buffer.clearRetainingCapacity();
                try continuation_buffer.appendSlice(alloc, row.key);
                continuation.* = continuation_buffer.items;
                examined_artifacts += 1;
            }
            if (artifact_entry == null) {
                // Only the active phase retains a physical continuation. This
                // keeps the existing bounded record size even for maximum-size
                // binary document keys, and commits phase + cursor atomically.
                continuation.* = "";
                if (projections) next.phase = .imported else next.artifacts_complete = true;
            } else continuation.* = try owned.dupe(u8, continuation.*);
            // Finish every arena allocation before copying its ownership into
            // PreparedPage; allocating while evaluating a later field would
            // update only the old ArenaAllocator state and leak its new block.
            const encoded_progress = try next.encode(owned);
            return .{ .arena = arena, .phase = next.phase, .batch = .{ .sync_level = .write, .restore_staging = .{ .import_page = .{
                .expected = staging.digest(raw),
                .next = encoded_progress,
                .scope = scope.digest(),
                .timestamps = &.{},
                .artifact_page = !projections,
                .projection_page = projections,
                .artifacts = artifacts.items,
            } } } };
        }
        var source_read = try source.core.store.beginReadTxn();
        defer source_read.abort();
        var cursor = try source_read.openCursor();
        defer cursor.close();
        var continuation_buffer: std.ArrayList(u8) = .empty;
        defer continuation_buffer.deinit(alloc);
        var entry = try cursor.seekAtOrAfter(if (next.cursor.len == 0) &.{internal_keys.user_namespace} else next.cursor);
        if (entry) |row| if (std.mem.eql(u8, row.key, next.cursor)) {
            entry = try cursor.next();
        };
        var writes: std.ArrayList(types.BatchWrite) = .empty;
        var timestamps: std.ArrayList(staging.Timestamp) = .empty;
        var historical: ?schema_registry_mod.SchemaView = null;
        defer if (historical) |*view| view.release();
        var bytes: usize = 0;
        var examined: usize = 0;
        const row_started = monotonicTimeNs();
        const row_soft_deadline = row_started +| 5 * std.time.ns_per_ms;
        const row_hard_deadline = row_started +| 100 * std.time.ns_per_ms;
        while (entry) |row| : (entry = try cursor.next()) {
            if (cancellation.isCancelled()) return error.Canceled;
            if (row.key.len == 0 or row.key[0] != internal_keys.user_namespace) {
                entry = null;
                break;
            }
            if (writes.items.len == max_rows or examined == 1024) break;
            if (examined != 0) {
                const now = monotonicTimeNs();
                // Restore pages pay a durable apply and index update each
                // time. Amortize those costs over at least 32 ordinary rows
                // when possible, but keep the 100 ms hard slice, row/byte/
                // examined-record ceilings and per-record cancellation.
                if (now >= row_hard_deadline or (writes.items.len >= 32 and now >= row_soft_deadline)) break;
            }
            const document_key = (try internal_keys.decodeStoredDocumentRowKeyAlloc(owned, row.key)) orelse {
                continuation_buffer.clearRetainingCapacity();
                try continuation_buffer.appendSlice(alloc, row.key);
                next.cursor = continuation_buffer.items;
                examined += 1;
                continue;
            };
            if (!self.core.byteRange().contains(document_key)) return error.RestoreStagingScopeChanged;
            var timestamp: u64 = 0;
            var json_null_fields: []const []const u8 = &.{};
            const json = if (internal_keys.isRelationalRowKey(row.key)) logical: {
                if (program) |rewrite| {
                    const transformed = try rewrite.transformJson(owned, row.value);
                    timestamp = transformed.timestamp;
                    json_null_fields = transformed.json_null_fields;
                    break :logical transformed.json;
                }
                const version = try relational_store.rowSchemaVersion(row.value);
                if (historical == null or historical.?.version() != version) {
                    if (historical) |*view| view.release();
                    historical = (try source.core.acquireSchemaVersionView(version)) orelse return error.UnknownSchemaVersion;
                }
                const view = historical.?;
                const typed = try relational_row_codec.ordinalRowViewSelective(row.value, view.tableSchema().*, view.physicalLayout());
                timestamp = typed.writeTimestampNs();
                json_null_fields = try typed.jsonNullFieldsAlloc(owned);
                break :logical try typed.reconstructValueAlloc(owned);
            } else logical: {
                timestamp = try source.getTimestamp(owned, document_key);
                if (program) |rewrite| break :logical try rewrite.preserveDocument(owned, row.value);
                break :logical try owned.dupe(u8, row.value);
            };
            const row_bytes = std.math.add(usize, document_key.len, json.len) catch return error.TransactionTooLarge;
            if (row_bytes > 16 * 1024 * 1024) return error.RelationalRowResultTooLarge;
            if (writes.items.len != 0 and bytes + row_bytes > 16 * 1024 * 1024) break;
            bytes += row_bytes;
            // The import-page admission below selects preserved-value row
            // preparation. These historical logical values must be validated,
            // not treated as new API input that fills today's defaults or
            // recomputes (and thereby repairs) stored generated results.
            try writes.append(owned, .{ .key = document_key, .value = json, .json_null_fields = json_null_fields });
            try timestamps.append(owned, .{ .key = document_key, .timestamp = timestamp });
            var hash = std.crypto.hash.Blake3.init(.{});
            hash.update(&next.logical_digest);
            var length: [8]u8 = undefined;
            std.mem.writeInt(u64, &length, document_key.len, .little);
            hash.update(&length);
            hash.update(document_key);
            hash.update(json);
            @import("relational_rewrite_program.zig").hashJsonNullFields(&hash, json_null_fields);
            hash.final(&next.logical_digest);
            next.rows = std.math.add(u64, next.rows, 1) catch return error.InvalidRestoreStagingCommand;
            continuation_buffer.clearRetainingCapacity();
            try continuation_buffer.appendSlice(alloc, row.key);
            next.cursor = continuation_buffer.items;
            examined += 1;
        }
        if (entry == null) {
            if (next.rewrite) |*rewrite| rewrite.snapshot_complete = true else if (scope.preserve_artifacts) {
                next.rows_complete = true;
                next.cursor = "";
            } else next.phase = .imported;
        }
        next.cursor = try owned.dupe(u8, next.cursor);
        const encoded = try next.encode(owned);
        const page: staging.ImportPage = .{ .expected = staging.digest(raw), .next = encoded, .scope = scope.digest(), .timestamps = timestamps.items };
        return .{
            .arena = arena,
            .phase = next.phase,
            .batch = .{
                .writes = writes.items,
                // The scoped native import synchronizes derived writes internally.
                // Request only durable apply acknowledgement here: the outer
                // serving-table visibility lookup cannot resolve this hidden owner.
                // Validation rechecks all local coverage before sealing its receipt.
                .sync_level = .write,
                .restore_staging = if (program != null) .{ .rewrite_page = page } else .{ .import_page = page },
            },
        };
    }

    /// Scope is retained as a tombstone after publication/cancellation. Late
    /// import RPCs can never initialize or mutate a recycled owner generation.
    pub fn finishRestoreStaging(self: *DB, alloc: Allocator, scope: @import("restore_staging.zig").Digest, phase: @import("restore_staging.zig").Phase) !@import("restore_staging.zig").Digest {
        return self.finishRestoreStagingWithMarker(alloc, scope, phase, null, null, null);
    }

    fn finishRestoreStagingWithMarker(self: *DB, alloc: Allocator, scope: @import("restore_staging.zig").Digest, phase: @import("restore_staging.zig").Phase, marker: ?OrderedApplyReceipt, replication_lsn: ?u64, replication_payload: ?[]const u8) !@import("restore_staging.zig").Digest {
        const staging = @import("restore_staging.zig");
        if (phase != .validated and phase != .published and phase != .canceled) return error.InvalidRestoreStagingCommand;
        try self.lockApplyForPortableRuntime();
        defer self.core.unlockApply();
        var manager = try self.core.initTxnManager();
        defer manager.deinit();
        if (try manager.hasSchemaLeases()) return error.SchemaInUse;
        var txn = try self.core.store.beginWriteTxn();
        var txn_open = true;
        defer if (txn_open) txn.abort();
        const raw = (try staging.optional(&txn)) orelse return error.RestoreStagingScopeChanged;
        var parsed = try staging.Progress.decode(alloc, raw);
        defer parsed.deinit();
        var next = parsed.value;
        if (!std.mem.eql(u8, &next.scope.digest(), &scope)) return error.RestoreStagingScopeChanged;
        if (marker) |entry| switch (try orderedApplyDisposition(try readOrderedApplyReceipt(self.alloc, self.core.store), entry)) {
            .already_applied => return next.receipt(),
            .apply => {},
        };
        if (next.phase != phase) {
            if (next.phase == .canceled or next.phase == .published) return error.RestoreStagingScopeChanged;
            if (phase == .validated and next.phase != .imported) return error.RestoreStagingInProgress;
            if (phase == .published and next.phase != .validated) return error.RestoreStagingInProgress;
        }
        if ((phase == .validated or phase == .published) and
            (next.phase == .imported or next.phase == .validated or next.phase == .published) and
            !try self.restoreStagingIndexesReadyAssumeApply(alloc))
            return if (marker != null or replication_lsn != null) error.RestoreProjectionCatchUpPending else error.IndexRebuilding;
        if (next.phase == phase) {
            if (marker != null or replication_lsn != null or replication_payload != null) {
                if (marker) |entry| {
                    var buffer: [ordered_apply_receipt_value_len]u8 = undefined;
                    const write = orderedApplyReceiptWrite(entry, &buffer);
                    try txn.put(write.key, write.value);
                }
                if (replication_lsn) |lsn| {
                    var buffer: [replication_applied_lsn_value_len]u8 = undefined;
                    const write = replicationAppliedSequenceWrite(lsn, &buffer);
                    try txn.put(write.key, write.value);
                }
                try self.stageRestoreStagingReplicationOutbox(&txn, replication_payload);
                try txn.commit();
                txn_open = false;
            }
            return next.receipt();
        }
        if (phase == .validated) {
            const bootstrap_raw = txn.get(staging.bootstrap_key) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            if (bootstrap_raw) |bytes| {
                var bootstrap = try staging.OwnerBootstrap.decode(alloc, bytes);
                defer bootstrap.deinit();
                if (!std.mem.eql(u8, &bootstrap.value.scope.digest(), &scope)) return error.RestoreStagingScopeChanged;
                if (bootstrap.value.source_generation_proof_digest) |expected_digest| {
                    if (!next.source_generation_proofs_complete) return error.RestoreSourceProofMissing;
                    try @import("restore_generation_admissions.zig").verifyImportedProofSummary(alloc, &txn, next.scope.source_namespace, expected_digest);
                }
            }
            if (self.core.acquireSchemaView()) |active| {
                var view = active;
                defer view.release();
                if (view.validator()) |validator| if (validator.execution.checks != null) switch ((try relational_constraint_jobs.status(&txn, view)).state) {
                    .enforced => {},
                    .validating => return if (marker != null or replication_lsn != null) error.RestoreProjectionCatchUpPending else error.ConstraintActivationInProgress,
                    .invalid => return if (marker != null or replication_lsn != null) error.RestoreProjectionCorrupt else error.RelationalCheckViolation,
                };
            }
            if (!try self.restoreStagingIndexesReadyAssumeApply(alloc)) return if (marker != null or replication_lsn != null) error.RestoreProjectionCatchUpPending else error.IndexRebuilding;
            // Hidden physical indexes were created empty before import and
            // receive the same PreparedRow writes. Seal their durable state
            // before acknowledging this owner's completion receipt.
            try self.core.index_manager.syncAll(true);
            const raw_catalog = txn.get(@import("relational_integrity_catalog.zig").key) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            if (raw_catalog) |bytes| {
                var catalog = try @import("relational_integrity_catalog.zig").decode(alloc, bytes);
                defer catalog.deinit();
                try @import("relational_integrity_activation.zig").requireReady(&txn, catalog);
            }
        }
        next.phase = phase;
        const encoded = try next.encode(alloc);
        defer alloc.free(encoded);
        try txn.put(staging.key, encoded);
        try self.stageRestoreStagingReplicationOutbox(&txn, replication_payload);
        if (replication_lsn) |lsn| {
            var buffer: [replication_applied_lsn_value_len]u8 = undefined;
            const write = replicationAppliedSequenceWrite(lsn, &buffer);
            try txn.put(write.key, write.value);
        }
        if (marker) |entry| {
            var buffer: [ordered_apply_receipt_value_len]u8 = undefined;
            const write = orderedApplyReceiptWrite(entry, &buffer);
            try txn.put(write.key, write.value);
        }
        try txn.commit();
        txn_open = false;
        self.local_execution.restore_staging_required.store(next.phase != .published, .release);
        try self.core.store.sync(true);
        return next.receipt();
    }

    /// File-backed variant for CLI restore paths. Portable decoding uses
    /// bounded positional reads over a locked source generation, so archive
    /// size does not become resident memory.
    pub fn importPortableFileIntoUnpublishedEmpty(
        self: *DB,
        alloc: Allocator,
        io: Io,
        file: std.Io.File,
        file_size: u64,
        target_identity: doc_identity.Namespace,
    ) !void {
        return self.importPortableLogicalSourceFile(alloc, io, file, file_size, target_identity, null, .none);
    }

    pub fn importCohortPortableFileIntoUnpublishedEmpty(self: *DB, alloc: Allocator, io: Io, file: std.Io.File, file_size: u64, proof: portable_backup.CohortProof, cancellation: types.CancellationToken) !void {
        return self.importPortableLogicalSourceFile(alloc, io, file, file_size, proof.namespace, proof, cancellation);
    }

    fn importPortableLogicalSourceFile(self: *DB, alloc: Allocator, io: Io, file: std.Io.File, file_size: u64, target_identity: doc_identity.Namespace, cohort: ?portable_backup.CohortProof, cancellation: types.CancellationToken) !void {
        if (self.open_mode == .status_only or self.open_mode == .query_readonly) return error.UnsupportedOperation;

        lockApply(self);
        defer self.core.unlockApply();
        if (!(try self.portableImportTargetEmptyLocked(alloc))) return error.LiteImportTargetNotEmpty;
        try portable_backup.importPortableFileWithOptions(alloc, self.core.store, io, file, file_size, .{
            .cohort = cohort,
            .cancellation = cancellation,
            .identity_namespace = target_identity,
            .prefer_existing_identity_namespace = true,
            .unpublished_staging = true,
        });
        portable_backup.validateCompleteDatabaseImageWithCohort(alloc, self.core.store, cohort) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return error.InvalidBackupRequest,
        };
        try doc_identity.reassignNamespaceAlloc(alloc, self.core.store, target_identity);
        try self.refreshPortableImportedGenerationLocked(target_identity);
    }

    /// Atomically adopts a prepared portable generation into a pristine live
    /// DB. The caller-provided publication step runs under the same exclusive
    /// apply fence as the final emptiness check, closing the build-time race
    /// with concurrent writers before runtime metadata is refreshed.
    pub fn adoptPreparedPortableGenerationIfEmpty(
        self: *DB,
        alloc: Allocator,
        prepared_runtime: *PreparedPortableRuntimeMetadata,
        context: anytype,
        comptime adopt: anytype,
    ) !void {
        if (self.open_mode == .status_only or self.open_mode == .query_readonly) return error.UnsupportedOperation;
        lockApply(self);
        var apply_locked = true;
        defer if (apply_locked) self.core.unlockApply();
        if (!(try self.portableImportTargetEmptyLocked(alloc))) return error.LiteImportTargetNotEmpty;
        try self.core.store.beginPortableImportPublication(
            self.backend_runtime.io() orelse self.backend_runtime.filesystemIo() orelse std.Options.debug_io,
        );
        var publication_fenced = true;
        defer if (publication_fenced) self.core.store.finishPortableImportPublication();
        const publication = try adopt(context);
        self.applyPreparedPortableRuntimeMetadataLocked(prepared_runtime);
        // The durable generation and its schema now agree. Lock-free point
        // reads may resume; index-bearing operations remain behind the
        // activation gate while catalog workers are rebound.
        self.core.store.finishPortableImportPublication();
        publication_fenced = false;
        // Keep index-bearing operations closed while activation temporarily
        // releases the apply lock to join and restart resolver workers.
        self.async_context.portable_runtime_activation_pending.store(true, .release);
        self.core.unlockApply();
        apply_locked = false;
        // The rename above is the commit point. Index artifacts were fully
        // finalized in the disposable generation; a host-level allocation or
        // descriptor failure while rebinding the live catalog is degraded
        // runtime state, not a retryable import failure.
        self.activatePortableIndexesAfterPublication();
        if (publication == .durability_unknown) return error.DurabilityOutcomeUnknown;
    }

    /// Publish a portable archive into a pristine live DB as one store
    /// generation. Expensive decoding and validation happen in an isolated
    /// stage before the apply lock is acquired; the locked target check closes
    /// the race with concurrent writers.
    pub fn importPortableIntoEmpty(
        self: *DB,
        alloc: Allocator,
        backup: []const u8,
        target_identity: doc_identity.Namespace,
    ) !void {
        if (self.open_mode == .status_only or self.open_mode == .query_readonly) return error.UnsupportedOperation;
        var stage = try PortableImportStage.init(alloc, self.core.path, backup, .{});
        defer stage.deinit();
        portable_backup.validateCompleteDatabaseImageAlloc(alloc, &stage.store) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return error.InvalidBackupRequest,
        };
        try stage.reassignIdentityNamespace(alloc, target_identity);
        var prepared = try self.preparePortableRuntimeMetadata(&stage.store, target_identity);
        defer prepared.deinit();

        lockApply(self);
        var apply_locked = true;
        defer if (apply_locked) self.core.unlockApply();
        if (!(try self.portableImportTargetEmptyLocked(alloc))) return error.LiteImportTargetNotEmpty;
        try self.core.store.beginPortableImportPublication(
            self.backend_runtime.io() orelse self.backend_runtime.filesystemIo() orelse std.Options.debug_io,
        );
        var publication_fenced = true;
        defer if (publication_fenced) self.core.store.finishPortableImportPublication();
        try stage.publish(self.core.store);

        self.applyPreparedPortableRuntimeMetadataLocked(&prepared);
        self.core.store.finishPortableImportPublication();
        publication_fenced = false;
        self.async_context.portable_runtime_activation_pending.store(true, .release);
        self.core.unlockApply();
        apply_locked = false;
        self.activatePortableIndexesAfterPublication();
    }

    /// Refresh every schema-dependent runtime view after a portable restore
    /// has replaced durable metadata beneath this already-open DB.
    pub fn reloadSchemaForInternalRestore(self: *DB) !void {
        if (self.open_mode == .status_only) return error.UnsupportedOperation;
        lockApply(self);
        defer self.core.unlockApply();
        try self.core.reloadSchemaFromStore();
        try self.refreshRelationalRuntimeMode();
    }

    fn dbDocIdentityStats(raw: doc_identity.Stats, namespace: doc_identity.Namespace) types.DocIdentityStats {
        const max_doc_ordinal = std.math.maxInt(doc_identity.DocOrdinal);
        const remaining = if (raw.next_ordinal >= max_doc_ordinal)
            0
        else
            @as(u64, max_doc_ordinal) - raw.next_ordinal;
        return .{
            .namespace_table_id = namespace.table_id,
            .namespace_shard_id = namespace.shard_id,
            .namespace_range_id = namespace.range_id,
            .next_ordinal = raw.next_ordinal,
            .allocated_ordinals = raw.allocated_ordinals,
            .ordinal_capacity_remaining = remaining,
            .ordinal_capacity_exhausted = raw.next_ordinal >= max_doc_ordinal,
            .rebuild_required = raw.next_ordinal >= max_doc_ordinal,
            .state_rows = raw.state_rows,
            .live_ordinals = raw.live_ordinals,
            .tombstone_ordinals = raw.tombstone_ordinals,
            .visibility_chunk_size = doc_identity.visibility_chunk_size,
            .visibility_chunks = raw.visibility_chunks,
            .visibility_deleted_ordinals = raw.visibility_deleted_ordinals,
            .visibility_mask_bytes = raw.visibility_mask_bytes,
            .visibility_repair_count = raw.visibility_repair_count,
            .min_created_generation = raw.min_created_generation,
            .max_created_generation = raw.max_created_generation,
            .min_deleted_generation = raw.min_deleted_generation,
            .max_deleted_generation = raw.max_deleted_generation,
            .complete = raw.complete,
        };
    }

    fn recordResolvedDocSet(self: *DB, set: *const doc_set.ResolvedDocSet, missing_ordinal_coverage: bool) void {
        self.local_execution.doc_set_planning_stats.recordResolvedSet(set, missing_ordinal_coverage);
    }

    fn recordUnsupportedDocSetFilterShape(self: *DB) void {
        self.local_execution.doc_set_planning_stats.recordUnsupportedFilterShape();
    }

    pub fn currentIdentityReadGenerationForRequest(self: *DB, requested: ?u64) !u64 {
        const current_generation = try self.currentIdentityReadGeneration();
        if (requested) |generation| {
            if (generation != current_generation) {
                self.local_execution.doc_set_planning_stats.recordStaleIdentityGenerationRejection();
                return error.IdentityReadGenerationChanged;
            }
            return generation;
        }
        return current_generation;
    }

    fn currentIdentityReadGeneration(self: *DB) !u64 {
        var current_generation = self.core.nextDerivedSequence();
        if (self.core.identity_visibility.summary) |summary| {
            return @max(current_generation, doc_identity.latestGenerationFromSummary(summary));
        }
        if (try doc_identity.latestGenerationFromSummaryFast(self.core.store)) |identity_generation| {
            return @max(current_generation, identity_generation);
        }
        const identity_stats = try doc_identity.fullStatsFromStore(self.core.store);
        current_generation = @max(current_generation, identity_stats.max_created_generation);
        current_generation = @max(current_generation, identity_stats.max_deleted_generation);
        return current_generation;
    }

    fn snapshotDocSetPlanningStats(self: *DB) types.DocSetPlanningStats {
        return self.local_execution.doc_set_planning_stats.snapshot();
    }

    fn snapshotVisibilityStats(self: *DB) types.VisibilityStats {
        return self.local_execution.visibility_runtime_stats.snapshot(self.core.identity_visibility.nonvisible_entries.load(.monotonic));
    }

    const DocIdentityCoverage = struct {
        scanned_primary_docs: u64 = 0,
        primary_docs_missing_ordinals: u64 = 0,
        primary_docs_missing_identity_state: u64 = 0,
        primary_docs_with_tombstone_ordinals: u64 = 0,
    };

    fn finalizeDocIdentityRebuildRequired(identity_stats: *types.DocIdentityStats) void {
        identity_stats.rebuild_required = identity_stats.rebuild_required or
            identity_stats.ordinal_capacity_exhausted or
            identity_stats.primary_docs_missing_ordinals != 0 or
            identity_stats.primary_docs_missing_identity_state != 0 or
            identity_stats.primary_docs_with_tombstone_ordinals != 0;
    }

    fn diagnosticDocIdentityStats(self: *DB, byte_range: types.ByteRange) !types.DocIdentityStats {
        var identity_stats = dbDocIdentityStats(try doc_identity.fullStatsFromStore(self.core.store), self.core.identity_namespace);
        const coverage = try self.scanPrimaryDocIdentityCoverage(byte_range);
        identity_stats.scanned_primary_docs = coverage.scanned_primary_docs;
        identity_stats.primary_docs_missing_ordinals = coverage.primary_docs_missing_ordinals;
        identity_stats.primary_docs_missing_identity_state = coverage.primary_docs_missing_identity_state;
        identity_stats.primary_docs_with_tombstone_ordinals = coverage.primary_docs_with_tombstone_ordinals;
        finalizeDocIdentityRebuildRequired(&identity_stats);
        return identity_stats;
    }

    fn statsLocked(self: *DB, alloc: Allocator) !types.DBStats {
        // Serialize owner captures, not HTTP reads. A stamp orders the whole
        // coherent capture; concurrent captures cannot assign a newer revision
        // to an older payload. Individual index snapshots retain their own
        // publication locks and replay prefixes are sampled before their facts.
        lockAtomic(&self.status_publication_mutex);
        defer self.status_publication_mutex.unlock();
        self.status_publication_revision += 1;
        const configs = try self.core.listIndexes(alloc);
        defer types.freeIndexConfigs(alloc, configs);
        var durable_index_repairs = try self.loadIndexRepairStateForStats(alloc);
        defer if (durable_index_repairs) |*state| state.deinit(alloc);
        const async_indexing = self.snapshotAsyncIndexingStats();
        var raw_identity_stats = try doc_identity.fastStatsFromStore(self.core.store);
        // Coalesced primary writes update this summary immediately after the
        // store accepts the batch, while a probe transaction can still see the
        // previous durable summary until the bulk window is published. Runtime
        // owners must publish the maintained live summary rather than making
        // status wait for a flush or fall back to a primary scan.
        applyCachedIdentityVisibilitySummary(&raw_identity_stats, self.core.identity_visibility.summary);
        const identity_stats = dbDocIdentityStats(raw_identity_stats, self.core.identity_namespace);
        // Operational status is polled frequently. Identity metadata is the
        // normal O(1) source of the live document count; retain the legacy
        // primary-store scan only as a lazy fallback for an old/incomplete
        // identity catalog and only when sparse-index capping needs it.
        var primary_doc_count_fallback: ?u64 = null;
        const repair_summary = try self.artifactRepairSummaryRootSnapshot(alloc);
        const repair_issue_count = repair_summary.count;
        var repair_index_fallback = ArtifactRepairIndexFallbackCounts{ .alloc = alloc };
        defer repair_index_fallback.deinit();

        var index_stats = try alloc.alloc(types.DBIndexStats, configs.len);
        var index_count: usize = 0;
        errdefer {
            for (index_stats[0..index_count]) |item| freeDBIndexStatsItem(alloc, item);
            alloc.free(index_stats);
        }

        var visible_doc_count: u64 = 0;
        var any_index_repair_degraded = false;
        var term_doc_freq_cache_hits: u64 = 0;
        var term_doc_freq_cache_misses: u64 = 0;
        for (configs) |cfg| {
            const projection_checkpoint = try self.core.loadProjectionCheckpoint(alloc, cfg.name);
            const applied_sequence = try self.managedIndexAppliedSequence(alloc, cfg.name);
            const target_sequence = try self.projectionStatsTargetSequence(alloc, cfg, applied_sequence);
            var item = types.DBIndexStats{
                .name = try alloc.dupe(u8, cfg.name),
                .kind = cfg.kind,
                .replay_applied_sequence = applied_sequence,
                .replay_target_sequence = target_sequence,
                .replay_catch_up_required = applied_sequence < target_sequence,
                .catch_up_active = false,
                .catch_up_applied_sequence = applied_sequence,
                .catch_up_target_sequence = target_sequence,
            };
            errdefer freeDBIndexStatsItem(alloc, item);
            try self.populateIndexSourceReplayStats(alloc, cfg.name, applied_sequence, target_sequence, &item);
            initializeDerivedCoverageIdentity(cfg, &item);
            if (cfg.kind == .dense_vector) {
                item.dense_native_storage_phase = self.core.index_manager.denseNativeStoragePhase(cfg.name);
            }
            applyProjectionCheckpointStats(&item, projection_checkpoint, target_sequence);
            try self.applyDurableIndexRepairStats(
                alloc,
                if (durable_index_repairs) |*state| state else null,
                self.async_context.index_repair_state_corrupt.load(.acquire),
                &item,
            );
            if (target_sequence > 0) {
                item.backfill_progress = @min(
                    1.0,
                    @as(f64, @floatFromInt(applied_sequence)) / @as(f64, @floatFromInt(target_sequence)),
                );
                item.backfill_active = item.backfill_active or applied_sequence < target_sequence;
            }
            if (self.core.index_manager.loadFailure(cfg.name)) |load_error| {
                item.load_error = try alloc.dupe(u8, load_error);
                // A quarantined index has no runtime; it is broken, not warming.
                applyTerminalLoadFailureStatus(&item);
            }
            const index_repair_summary = try self.artifactRepairSummaryIndexSnapshotForStats(alloc, cfg.name, repair_summary.ready, &repair_index_fallback);
            item.repair_issue_count = index_repair_summary.count;
            item.repair_summary_ready = index_repair_summary.ready;
            item.repair_issue_count_estimated = !index_repair_summary.ready;
            item.repair_scan_issue_count = index_repair_summary.repair_scan_count;
            item.repair_degraded = item.repair_degraded or !index_repair_summary.ready or item.repair_issue_count != 0;

            var serving_observed = false;
            switch (cfg.kind) {
                .full_text => {
                    if (self.core.textIndex(cfg.name)) |entry| {
                        const text_snapshot = entry.acquireSnapshot();
                        defer text_snapshot.release();
                        item.doc_count = text_snapshot.liveDocCount();
                        item.term_count = textSnapshotTermCount(text_snapshot);
                        serving_observed = true;
                        visible_doc_count = @max(visible_doc_count, item.doc_count);
                        term_doc_freq_cache_hits += text_snapshot.term_doc_freq_cache_hits;
                        term_doc_freq_cache_misses += text_snapshot.term_doc_freq_cache_misses;
                    }
                    item.text_merge = self.core.index_manager.textMergeStatsSnapshotForIndex(cfg.name);
                    if (self.text_merge_runtime) |runtime| runtime.overlayRuntimeStats(&item.text_merge);
                    // Artifact-fed full-text projections carry the same
                    // durable per-document generation outcomes as embeddings
                    // indexes; surface them so terminal failures are settled
                    // coverage, not invisible pending work. Direct-document
                    // projections have no producer outcomes and stay
                    // coverage-silent instead of eternally pending.
                    if (self.derivedCoverageAppliesToIndex(.full_text, cfg.name))
                        try self.populateConfiguredDerivedCoverageCounts(cfg.name, &item);
                },
                .dense_vector => {
                    if (self.core.denseIndex(cfg.name)) |entry| {
                        const serving = denseServingCounts(entry.index);
                        item.doc_count = serving.doc_count;
                        item.node_count = serving.node_count;
                        item.root_node = serving.root_node;
                        item.serving_snapshot_revision = serving.revision;
                        item.serving_snapshot_owner_id = self.backend_owner_id;
                        serving_observed = true;
                        item.hbc_cache = dbHbcCacheStats(entry.index.hbcCacheStats());
                        item.hbc_posting.refresh_pending = entry.index.postingRefreshPending();
                        visible_doc_count = @max(visible_doc_count, item.doc_count);
                        try self.markDenseCoverageRegressionIfNeeded(alloc, cfg.name, &item);
                    }
                    try self.populateConfiguredDerivedCoverageCounts(cfg.name, &item);
                    if (async_indexing.dense_catch_up.active) {
                        item.catch_up_active = true;
                        item.backfill_active = true;
                    }
                    item.catch_up_phase = async_indexing.dense_catch_up.phase;
                    if (self.core.index_manager.vectorBlockProjectionRequiredForDenseIndex(cfg.name) and
                        !self.core.index_manager.vectorBlockReadyForDenseIndexAtSequence(
                            cfg.name,
                            item.replay_applied_sequence,
                            item.doc_count,
                        ))
                    {
                        item.backfill_active = true;
                        item.backfill_progress = @min(item.backfill_progress, 0.999);
                        item.dense_vector_projection_pending = true;
                    }
                },
                .sparse_vector => {
                    if (self.core.sparseIndex(cfg.name)) |entry| {
                        const sparse_snapshot = entry.index.stats();
                        const sparse_doc_cap = if (identity_stats.live_ordinals > 0)
                            identity_stats.live_ordinals
                        else fallback: {
                            if (primary_doc_count_fallback == null) {
                                primary_doc_count_fallback = self.scanPrimaryDocCount(self.core.byteRange()) catch 0;
                            }
                            break :fallback if (primary_doc_count_fallback.? > 0)
                                primary_doc_count_fallback.?
                            else
                                visible_doc_count;
                        };
                        item.doc_count = if (entry.chunk_name == null and sparse_doc_cap > 0)
                            @min(sparse_snapshot.doc_count, sparse_doc_cap)
                        else
                            sparse_snapshot.doc_count;
                        item.term_count = sparse_snapshot.term_count;
                        serving_observed = true;
                        visible_doc_count = @max(visible_doc_count, item.doc_count);
                    }
                    try self.populateConfiguredDerivedCoverageCounts(cfg.name, &item);
                },
                .graph => {
                    if (self.core.graphIndex(cfg.name)) |entry| {
                        {
                            const graph_snapshot = entry.index.operationalStats();
                            item.graph_counts_pending = graph_snapshot.counts_pending;
                            item.edge_count = graph_snapshot.edge_count;
                            item.node_count = graph_snapshot.node_count;
                            item.doc_count = graph_snapshot.node_count;
                            serving_observed = true;
                            if (!graph_snapshot.counts_pending) visible_doc_count = @max(visible_doc_count, item.doc_count);
                        }
                        applyGraphAlgebraicRuntimeStats(&item, &entry.index);
                        try populateGraphMetricStatusStats(alloc, &item, &entry.index);
                    }
                    // Extraction-fed graph indexes (the autoschema pipeline)
                    // record per-document generation outcomes under the
                    // consuming index's coverage generation; without this the
                    // knowledge graph's terminal extraction failures were
                    // reported nowhere on the index itself. Direct-document
                    // graphs have no producer outcomes and stay silent.
                    if (self.derivedCoverageAppliesToIndex(.graph, cfg.name))
                        try self.populateConfiguredDerivedCoverageCounts(cfg.name, &item);
                },
                .algebraic => {
                    try self.populateAlgebraicIndexStats(alloc, cfg.name, &item, false);
                    serving_observed = self.core.index_manager.algebraicIndex(cfg.name) != null;
                },
            }
            if (cfg.kind == .dense_vector or cfg.kind == .sparse_vector) {
                item.serving_snapshot_ready = self.vectorServingSnapshotReady(
                    alloc,
                    &item,
                    if (durable_index_repairs) |*state| state else null,
                );
            }
            // Coverage and rebuild accounting above describes serviceable
            // runtimes. A quarantined index has no worker that can make that
            // progress, so its terminal load state must take precedence.
            if (item.load_error != null) applyTerminalLoadFailureStatus(&item);
            any_index_repair_degraded = any_index_repair_degraded or item.repair_degraded;
            self.stampIndexObservation(cfg, &item, if (durable_index_repairs) |*state| state else null, serving_observed);
            index_stats[index_count] = item;
            index_count += 1;
        }

        return .{
            .runtime_owner_id = self.backend_owner_id,
            .storage_change_token = self.storageChangeTokenLocked(),
            .source_doc_count = identity_stats.live_ordinals,
            .schema_epoch = self.core.table_catalog.active_schema_version,
            .row_format_version = self.core.table_catalog.row_format_version,
            .table_catalog_generation = self.core.table_catalog.generation,
            .schema_index_state = @tagName(self.core.table_catalog.index_state),
            .doc_count = visible_doc_count,
            .index_count = @intCast(self.core.indexCount()),
            .indexes = index_stats[0..index_count],
            .repair_degraded = any_index_repair_degraded or !repair_summary.ready or repair_issue_count != 0,
            .repair_issue_count = repair_issue_count,
            .repair_summary_ready = repair_summary.ready,
            .repair_issue_count_estimated = !repair_summary.ready,
            .doc_identity = identity_stats,
            .columnar_maintenance = self.relational_column_maintenance.snapshot(),
            .doc_set_planning = self.snapshotDocSetPlanningStats(),
            .visibility = self.snapshotVisibilityStats(),
            .enrichment = self.enrichmentStatsWithSupervisorState(.{}),
            .resolution = self.resolutionStageStats(),
            .promotion = self.promotionStageStats(),
            .resolver_replay = try self.resolverReplayDiagnosticsLocked(alloc),
            .ttl_cleanup = if (self.ttl_runtime) |runtime| runtime.stats() else .{},
            .transaction_recovery = if (self.transaction_runtime) |runtime| runtime.stats() else .{},
            .text_merge = if (self.text_merge_runtime) |runtime| runtime.statsAssumeApplyLockHeld() else self.core.index_manager.textMergeStatsSnapshot(),
            .graph_metric_runtime = self.graphMetricRuntimeStats(),
            .term_doc_freq_cache_hits = term_doc_freq_cache_hits,
            .term_doc_freq_cache_misses = term_doc_freq_cache_misses,
            .async_indexing = async_indexing,
        };
    }

    fn stampIndexObservation(self: *DB, cfg: types.IndexConfig, item: *types.DBIndexStats, repairs: ?*const index_repair_state.State, serving_observed: bool) void {
        // Read-only and status-only DBs are observers, not successor writers.
        if (self.open_mode != .writer and self.open_mode != .writer_no_replay) return;
        if (!item.coverage_identity_ready or item.load_error != null) return;
        if (!serving_observed and !item.coverage_summary_ready) return;
        const recovered = self.observeResidentIndexAdmission(self.alloc, item.name, repairs) == .admitted and
            !item.repair_degraded and !item.index_repair_action_required and
            (std.mem.eql(u8, item.projection_checkpoint_status, "clean") or item.index_repair_active_generation_serviceable) and
            item.projection_checkpoint_config_hash == types.indexConfigHash(cfg) and
            item.projection_checkpoint_applied_sequence <= item.replay_applied_sequence;
        const stamp = @import("publication.zig").Stamp{
            .owner_epoch = self.status_owner_epoch,
            .revision = self.status_publication_revision,
            .applied_through = item.replay_applied_sequence,
            .recovered_through = if (recovered) item.projection_checkpoint_applied_sequence else null,
        };
        if (serving_observed) {
            item.serving_publication = stamp;
            item.runtime_serving_applied_sequence = stamp.applied_through;
        }
        if (item.coverage_summary_ready) {
            item.coverage_publication = stamp;
            item.runtime_coverage_applied_sequence = stamp.applied_through;
            item.runtime_coverage_source_sequence = self.core.nextDerivedSequence();
        }
    }

    pub fn diagnosticStats(self: *DB, alloc: Allocator) !types.DBStats {
        if (self.open_mode == .status_only) {
            return try self.statusOnlyStats(alloc);
        }

        lockApplyShared(self);
        defer self.core.unlockApplyShared();

        const byte_range = self.core.byteRange();
        const configs = try self.core.listIndexes(alloc);
        defer types.freeIndexConfigs(alloc, configs);
        var durable_index_repairs = try self.loadIndexRepairStateForStats(alloc);
        defer if (durable_index_repairs) |*state| state.deinit(alloc);
        const replay_debt = try self.listDerivedReplayDebtAssumeApplyLockHeld(alloc);
        defer {
            for (replay_debt) |*status| status.deinit(alloc);
            alloc.free(replay_debt);
        }
        var indexed_doc_count: ?u64 = null;
        for (configs) |cfg| {
            if (cfg.kind != .full_text) continue;
            if (self.core.textIndex(cfg.name)) |entry| {
                indexed_doc_count = @max(indexed_doc_count orelse 0, entry.snapshot().liveDocCount());
            }
        }
        const visible_doc_count = indexed_doc_count orelse try self.scanPrimaryDocCount(byte_range);
        const async_indexing = self.async_context.stats.snapshot();
        const identity_stats = try self.diagnosticDocIdentityStats(byte_range);
        const repair_summary = try self.artifactRepairSummaryRootSnapshot(alloc);
        const repair_issue_count = repair_summary.count;
        var repair_index_fallback = ArtifactRepairIndexFallbackCounts{ .alloc = alloc };
        defer repair_index_fallback.deinit();

        var index_stats = try alloc.alloc(types.DBIndexStats, configs.len);
        var index_count: usize = 0;
        var any_index_repair_degraded = false;
        errdefer {
            for (index_stats[0..index_count]) |item| freeDBIndexStatsItem(alloc, item);
            alloc.free(index_stats);
        }

        for (configs) |cfg| {
            var item = types.DBIndexStats{
                .name = try alloc.dupe(u8, cfg.name),
                .kind = cfg.kind,
            };
            errdefer freeDBIndexStatsItem(alloc, item);
            initializeDerivedCoverageIdentity(cfg, &item);
            if (cfg.kind == .dense_vector) {
                item.dense_native_storage_phase = self.core.index_manager.denseNativeStoragePhase(cfg.name);
            }
            if (self.core.index_manager.loadFailure(cfg.name)) |load_error| {
                item.load_error = try alloc.dupe(u8, load_error);
                applyTerminalLoadFailureStatus(&item);
            } else if (try self.loadPersistedIndexLoadFailure(alloc, cfg.name)) |load_error| {
                item.load_error = load_error;
                applyTerminalLoadFailureStatus(&item);
            }
            for (replay_debt) |status| {
                if (!std.mem.eql(u8, status.index_name, cfg.name)) continue;
                item.replay_applied_sequence = status.applied_sequence;
                item.replay_target_sequence = status.target_sequence;
                item.replay_catch_up_required = status.catch_up_required;
                item.catch_up_applied_sequence = status.applied_sequence;
                item.catch_up_target_sequence = status.target_sequence;
                item.catch_up_active = false;
                break;
            }
            try self.populateIndexSourceReplayStats(alloc, cfg.name, item.replay_applied_sequence, item.replay_target_sequence, &item);
            applyProjectionCheckpointStats(&item, try self.core.loadProjectionCheckpoint(alloc, cfg.name), item.replay_target_sequence);
            try self.applyDurableIndexRepairStats(
                alloc,
                if (durable_index_repairs) |*state| state else null,
                self.async_context.index_repair_state_corrupt.load(.acquire),
                &item,
            );
            if (item.load_error != null) applyTerminalLoadFailureStatus(&item);
            const index_repair_summary = try self.artifactRepairSummaryIndexSnapshotForStats(alloc, cfg.name, repair_summary.ready, &repair_index_fallback);
            item.repair_issue_count = index_repair_summary.count;
            item.repair_summary_ready = index_repair_summary.ready;
            item.repair_issue_count_estimated = !index_repair_summary.ready;
            item.repair_scan_issue_count = index_repair_summary.repair_scan_count;
            item.repair_degraded = item.repair_degraded or !index_repair_summary.ready or item.repair_issue_count != 0;
            switch (cfg.kind) {
                .full_text => {
                    if (self.core.textIndex(cfg.name)) |entry| {
                        item.doc_count = entry.snapshot().liveDocCount();
                        indexed_doc_count = @max(indexed_doc_count orelse 0, item.doc_count);
                    }
                    item.text_merge = self.core.index_manager.textMergeStatsForIndex(cfg.name);
                    if (self.text_merge_runtime) |runtime| runtime.overlayRuntimeStats(&item.text_merge);
                    if (self.core.textIndexEntry(cfg.name)) |entry| {
                        const rebuild_state = self.core.index_manager.rebuildState(.full_text, entry.rebuild_root_path, entry.config);
                        if (try rebuild_state.estimateProgress(byte_range.start, byte_range.end, alloc)) |progress| {
                            item.backfill_active = true;
                            item.backfill_progress = progress;
                        }
                    }
                },
                .dense_vector => {
                    if (self.core.denseIndex(cfg.name)) |entry| {
                        const serving = denseServingCounts(entry.index);
                        item.doc_count = serving.doc_count;
                        item.node_count = serving.node_count;
                        item.root_node = serving.root_node;
                        item.hbc_cache = dbHbcCacheStats(entry.index.hbcCacheStats());
                        item.hbc_posting = dbHbcPostingStats(try entry.index.postingBacklogStats(), entry.index.getWriteProfile());
                        item.hbc_posting.refresh_pending = entry.index.postingRefreshPending();
                        try self.markDenseCoverageRegressionIfNeeded(alloc, cfg.name, &item);
                        if (async_indexing.dense_catch_up.active) {
                            item.catch_up_active = true;
                            item.backfill_active = true;
                        }
                        const rebuild_root_path = try self.denseIndexRebuildStatePathAlloc(alloc, entry.config.name);
                        defer alloc.free(rebuild_root_path);
                        const rebuild_state = self.core.index_manager.rebuildState(.dense_vector, rebuild_root_path, entry.config);
                        if (item.doc_count < visible_doc_count) {
                            if (try rebuild_state.estimateProgress(byte_range.start, byte_range.end, alloc)) |progress| {
                                item.backfill_active = true;
                                item.backfill_progress = progress;
                            }
                        }
                    }
                    try self.populateConfiguredDerivedCoverageCounts(cfg.name, &item);
                    if (!item.backfill_active and item.replay_target_sequence > 0 and item.doc_count < visible_doc_count) {
                        item.backfill_progress = @min(
                            1.0,
                            @as(f64, @floatFromInt(item.replay_applied_sequence)) / @as(f64, @floatFromInt(item.replay_target_sequence)),
                        );
                        item.backfill_active = item.replay_applied_sequence < item.replay_target_sequence;
                    }
                },
                .sparse_vector => {
                    if (self.core.sparseIndex(cfg.name)) |entry| {
                        const sparse_stats = entry.index.stats();
                        const raw_identity_stats = doc_identity.fastStatsFromStore(self.core.store) catch null;
                        const sparse_doc_cap = if (identity_stats.live_ordinals > 0)
                            identity_stats.live_ordinals
                        else if (raw_identity_stats) |raw|
                            raw.live_ordinals
                        else
                            visible_doc_count;
                        item.doc_count = if (entry.chunk_name == null and sparse_doc_cap > 0)
                            @min(sparse_stats.doc_count, sparse_doc_cap)
                        else
                            sparse_stats.doc_count;
                        item.term_count = sparse_stats.term_count;
                        const rebuild_state = self.core.index_manager.rebuildState(.sparse_vector, entry.rebuild_root_path, entry.config);
                        if (try rebuild_state.estimateProgress(byte_range.start, byte_range.end, alloc)) |progress| {
                            item.backfill_active = true;
                            item.backfill_progress = progress;
                        }
                    }
                    try self.populateConfiguredDerivedCoverageCounts(cfg.name, &item);
                    if (!item.backfill_active and item.replay_target_sequence > 0) {
                        item.backfill_progress = @min(
                            1.0,
                            @as(f64, @floatFromInt(item.replay_applied_sequence)) / @as(f64, @floatFromInt(item.replay_target_sequence)),
                        );
                        item.backfill_active = item.replay_applied_sequence < item.replay_target_sequence;
                    }
                },
                .graph => {
                    if (self.core.graphIndex(cfg.name)) |entry| {
                        const graph_stats = try entry.index.stats(alloc);
                        item.edge_count = graph_stats.edge_count;
                        item.node_count = graph_stats.node_count;
                        item.doc_count = graph_stats.node_count;
                        applyGraphAlgebraicRuntimeStats(&item, &entry.index);
                        const rebuild_state = self.core.index_manager.rebuildState(.graph, entry.rebuild_root_path, entry.config);
                        if (try rebuild_state.estimateProgress(byte_range.start, byte_range.end, alloc)) |progress| {
                            item.backfill_active = true;
                            item.backfill_progress = progress;
                        }
                    }
                },
                .algebraic => try self.populateAlgebraicIndexStats(alloc, cfg.name, &item, true),
            }
            if (cfg.kind == .dense_vector or cfg.kind == .sparse_vector) {
                item.serving_snapshot_ready = self.vectorServingSnapshotReady(
                    alloc,
                    &item,
                    if (durable_index_repairs) |*state| state else null,
                );
            }
            if (item.load_error != null) applyTerminalLoadFailureStatus(&item);
            any_index_repair_degraded = any_index_repair_degraded or item.repair_degraded;
            index_stats[index_count] = item;
            index_count += 1;
        }

        return .{
            .source_doc_count = identity_stats.live_ordinals,
            .doc_count = visible_doc_count,
            .index_count = @intCast(self.core.indexCount()),
            .indexes = index_stats[0..index_count],
            .repair_degraded = any_index_repair_degraded or !repair_summary.ready or repair_issue_count != 0,
            .repair_issue_count = repair_issue_count,
            .repair_summary_ready = repair_summary.ready,
            .repair_issue_count_estimated = !repair_summary.ready,
            .doc_identity = identity_stats,
            .columnar_maintenance = self.relational_column_maintenance.snapshot(),
            .doc_set_planning = self.snapshotDocSetPlanningStats(),
            .visibility = self.snapshotVisibilityStats(),
            .enrichment = self.enrichmentStatsWithSupervisorState(.{}),
            .resolution = self.resolutionStageStats(),
            .promotion = self.promotionStageStats(),
            .resolver_replay = try self.resolverReplayDiagnosticsLocked(alloc),
            .ttl_cleanup = if (self.ttl_runtime) |runtime| runtime.stats() else .{},
            .transaction_recovery = if (self.transaction_runtime) |runtime| runtime.stats() else .{},
            .text_merge = if (self.text_merge_runtime) |runtime| runtime.statsAssumeApplyLockHeld() else self.core.index_manager.textMergeStats(),
            .graph_metric_runtime = self.graphMetricRuntimeStats(),
            .term_doc_freq_cache_hits = blk: {
                var total: u64 = 0;
                for (configs) |cfg| {
                    if (cfg.kind != .full_text) continue;
                    if (self.core.textIndex(cfg.name)) |entry| {
                        const text_snapshot = entry.acquireSnapshot();
                        defer text_snapshot.release();
                        total += text_snapshot.term_doc_freq_cache_hits;
                    }
                }
                break :blk total;
            },
            .term_doc_freq_cache_misses = blk: {
                var total: u64 = 0;
                for (configs) |cfg| {
                    if (cfg.kind != .full_text) continue;
                    if (self.core.textIndex(cfg.name)) |entry| {
                        const text_snapshot = entry.acquireSnapshot();
                        defer text_snapshot.release();
                        total += text_snapshot.term_doc_freq_cache_misses;
                    }
                }
                break :blk total;
            },
            .async_indexing = async_indexing,
        };
    }

    fn applyStatusOnlyRebuildStateStats(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        item: *types.DBIndexStats,
    ) !void {
        if (cfg.kind == .algebraic) return;
        const rebuild_root_path = try self.denseIndexRebuildStatePathAlloc(alloc, cfg.name);
        defer alloc.free(rebuild_root_path);
        const rebuild_state = self.core.index_manager.rebuildState(cfg.kind, rebuild_root_path, cfg);
        var loaded = try rebuild_state.loadWithIo(
            alloc,
            self.core.index_manager.checkpointIo(),
        );
        defer loaded.deinit(alloc);
        const key = switch (loaded) {
            .absent => return,
            .valid => |resume_key| resume_key,
            .legacy => {
                item.backfill_active = true;
                item.backfill_progress = 0;
                return;
            },
            .corrupt => {
                item.load_error = try alloc.dupe(u8, @errorName(error.InvalidRebuildState));
                item.repair_degraded = true;
                item.backfill_active = false;
                item.backfill_progress = 0;
                return;
            },
        };
        const byte_range = self.core.byteRange();
        item.backfill_active = true;
        item.backfill_progress = backfill_state_mod.estimateProgressForKey(
            byte_range.start,
            byte_range.end,
            key,
        );
    }

    fn statusOnlyStats(self: *DB, alloc: Allocator) !types.DBStats {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();

        const configs = try self.core.listIndexes(alloc);
        defer types.freeIndexConfigs(alloc, configs);
        var durable_index_repairs = try self.loadIndexRepairStateForStats(alloc);
        defer if (durable_index_repairs) |*state| state.deinit(alloc);
        var visible_doc_count: u64 = 0;
        const identity_stats = dbDocIdentityStats(try doc_identity.fastStatsFromStore(self.core.store), self.core.identity_namespace);
        const repair_summary = try self.artifactRepairSummaryRootSnapshot(alloc);
        const repair_issue_count = repair_summary.count;
        var repair_index_fallback = ArtifactRepairIndexFallbackCounts{ .alloc = alloc };
        defer repair_index_fallback.deinit();

        var index_stats = try alloc.alloc(types.DBIndexStats, configs.len);
        var index_count: usize = 0;
        var any_index_repair_degraded = false;
        errdefer {
            for (index_stats[0..index_count]) |item| freeDBIndexStatsItem(alloc, item);
            alloc.free(index_stats);
        }

        for (configs) |cfg| {
            const projection_checkpoint = try self.core.loadProjectionCheckpoint(alloc, cfg.name);
            const applied_sequence = try self.core.loadAppliedSequence(alloc, cfg.name);
            const target_sequence = try self.projectionStatsTargetSequence(alloc, cfg, applied_sequence);
            var item = types.DBIndexStats{
                .name = try alloc.dupe(u8, cfg.name),
                .kind = cfg.kind,
                .replay_applied_sequence = applied_sequence,
                .replay_target_sequence = target_sequence,
                .replay_catch_up_required = applied_sequence < target_sequence,
                .catch_up_active = false,
                .catch_up_applied_sequence = applied_sequence,
                .catch_up_target_sequence = target_sequence,
            };
            errdefer freeDBIndexStatsItem(alloc, item);
            try self.populateIndexSourceReplayStats(alloc, cfg.name, applied_sequence, target_sequence, &item);
            initializeDerivedCoverageIdentity(cfg, &item);
            if (cfg.kind == .dense_vector) {
                item.dense_native_storage_phase = self.core.index_manager.denseNativeStoragePhase(cfg.name);
            }
            if (comptime builtin.os.tag != .freestanding) {
                try self.applyStatusOnlyRebuildStateStats(alloc, cfg, &item);
            }
            applyProjectionCheckpointStats(&item, projection_checkpoint, target_sequence);
            try self.applyDurableIndexRepairStats(
                alloc,
                if (durable_index_repairs) |*state| state else null,
                self.async_context.index_repair_state_corrupt.load(.acquire),
                &item,
            );
            if (target_sequence > 0) {
                item.backfill_progress = @min(
                    1.0,
                    @as(f64, @floatFromInt(applied_sequence)) / @as(f64, @floatFromInt(target_sequence)),
                );
                item.backfill_active = item.backfill_active or applied_sequence < target_sequence;
            }
            if (self.core.index_manager.loadFailure(cfg.name)) |load_error| {
                if (item.load_error) |previous| alloc.free(previous);
                item.load_error = try alloc.dupe(u8, load_error);
                applyTerminalLoadFailureStatus(&item);
            } else if (try self.loadPersistedIndexLoadFailure(alloc, cfg.name)) |load_error| {
                if (item.load_error) |previous| alloc.free(previous);
                item.load_error = load_error;
                applyTerminalLoadFailureStatus(&item);
            }
            if (try self.loadIndexStatusSnapshot(alloc, cfg.name)) |status_snapshot| {
                applyIndexStatusSnapshot(&item, status_snapshot);
                visible_doc_count = @max(visible_doc_count, item.doc_count);
            }
            if (cfg.kind == .dense_vector or cfg.kind == .sparse_vector) {
                self.populateConfiguredDerivedCoverageCountsBestEffort(cfg.name, &item);
            }
            const index_repair_summary = try self.artifactRepairSummaryIndexSnapshotForStats(alloc, cfg.name, repair_summary.ready, &repair_index_fallback);
            item.repair_issue_count = index_repair_summary.count;
            item.repair_summary_ready = index_repair_summary.ready;
            item.repair_issue_count_estimated = !index_repair_summary.ready;
            item.repair_scan_issue_count = index_repair_summary.repair_scan_count;
            item.repair_degraded = item.repair_degraded or !index_repair_summary.ready or item.repair_issue_count != 0;
            if (cfg.kind == .full_text) {
                item.text_merge = self.core.index_manager.textMergeStatsSnapshotForIndex(cfg.name);
                if (self.text_merge_runtime) |runtime| runtime.overlayRuntimeStats(&item.text_merge);
            }
            if (item.load_error != null) applyTerminalLoadFailureStatus(&item);
            any_index_repair_degraded = any_index_repair_degraded or item.repair_degraded;
            index_stats[index_count] = item;
            index_count += 1;
        }

        return .{
            .source_doc_count = identity_stats.live_ordinals,
            .doc_count = visible_doc_count,
            .index_count = @intCast(self.core.indexCount()),
            .indexes = index_stats[0..index_count],
            .repair_degraded = any_index_repair_degraded or !repair_summary.ready or repair_issue_count != 0,
            .repair_issue_count = repair_issue_count,
            .repair_summary_ready = repair_summary.ready,
            .repair_issue_count_estimated = !repair_summary.ready,
            .doc_identity = identity_stats,
            .doc_set_planning = self.snapshotDocSetPlanningStats(),
            .columnar_maintenance = self.relational_column_maintenance.snapshot(),
            .visibility = self.snapshotVisibilityStats(),
            .resolution = self.resolutionStageStats(),
            .promotion = self.promotionStageStats(),
            .resolver_replay = try self.resolverReplayDiagnosticsLocked(alloc),
            .async_indexing = self.async_context.stats.snapshot(),
        };
    }

    fn populateAlgebraicIndexStats(self: *DB, alloc: Allocator, index_name: []const u8, item: *types.DBIndexStats, include_adaptive_scans: bool) !void {
        const entry = self.core.index_manager.algebraicIndex(index_name) orelse return;
        const status_value = entry.index.status();
        const cfg = entry.index.config();
        item.algebraic_parse_error_count = status_value.parse_error_count;
        item.algebraic_schema_version = cfg.schema_version;
        if (cfg.capability_fingerprint.len > 0) {
            item.algebraic_capability_fingerprint = try alloc.dupe(u8, cfg.capability_fingerprint);
        }
        if (cfg.capability_lifecycle_status.len > 0) {
            item.algebraic_capability_lifecycle_status = try alloc.dupe(u8, cfg.capability_lifecycle_status);
        }
        item.algebraic_capability_change_added_fields = cfg.capability_change_added_fields;
        item.algebraic_capability_change_removed_fields = cfg.capability_change_removed_fields;
        item.algebraic_capability_change_changed_type_fields = cfg.capability_change_changed_type_fields;
        item.algebraic_skipped_dynamic_fields = cfg.skipped_dynamic_fields;
        item.algebraic_skipped_complex_fields = cfg.skipped_complex_fields;
        item.algebraic_skipped_unbounded_fields = cfg.skipped_unbounded_fields;
        item.algebraic_minmax_cache_hits = status_value.minmax_cache_hits;
        item.algebraic_minmax_cache_misses = status_value.minmax_cache_misses;
        item.algebraic_minmax_support_scans = status_value.minmax_support_scans;
        item.algebraic_planner_selected = status_value.planner_algebraic_selected;
        item.algebraic_planner_fallback_count = status_value.planner_fallback_count;
        if (status_value.planner_last_decision) |value| {
            item.algebraic_planner_last_decision = try alloc.dupe(u8, value);
        }
        if (status_value.planner_last_fallback_reason) |value| {
            item.algebraic_planner_last_fallback_reason = try alloc.dupe(u8, value);
        }
        item.algebraic_planner_last_estimated_scan_rows = if (status_value.planner_last_estimated_scan_rows) |value| @intCast(value) else null;
        item.algebraic_planner_last_estimated_result_buckets = if (status_value.planner_last_estimated_result_buckets) |value| @intCast(value) else null;
        item.algebraic_planner_lifecycle_ready = status_value.planner_lifecycle_ready;
        if (status_value.planner_lifecycle_blocking_reason) |value| {
            item.algebraic_planner_lifecycle_blocking_reason = try alloc.dupe(u8, value);
        }
        item.algebraic_dictionary_registry_claimed_count = status_value.dictionary_registry_claimed_count;
        item.algebraic_dictionary_registry_already_owned_count = status_value.dictionary_registry_already_owned_count;
        item.algebraic_dictionary_registry_owned_by_other_count = status_value.dictionary_registry_owned_by_other_count;
        item.algebraic_dictionary_registry_ready_hit_count = status_value.dictionary_registry_ready_hit_count;
        item.algebraic_dictionary_registry_ready_miss_count = status_value.dictionary_registry_ready_miss_count;
        item.algebraic_distributed_partial_validation_proven_count = status_value.distributed_partial_validation_proven_count;
        item.algebraic_distributed_partial_validation_rejected_count = status_value.distributed_partial_validation_rejected_count;
        item.algebraic_distributed_partial_rows_exported_count = status_value.distributed_partial_rows_exported_count;
        item.algebraic_vector_filter_attempt_count = status_value.vector_filter_attempt_count;
        item.algebraic_vector_filter_resolved_count = status_value.vector_filter_resolved_count;
        item.algebraic_vector_filter_unsupported_count = status_value.vector_filter_unsupported_count;
        item.algebraic_vector_filter_fail_closed_count = status_value.vector_filter_fail_closed_count;
        item.algebraic_vector_filter_include_doc_id_count = status_value.vector_filter_include_doc_id_count;
        item.algebraic_vector_filter_exclude_doc_id_count = status_value.vector_filter_exclude_doc_id_count;
        item.algebraic_observed_query_shape_count = status_value.observed_query_shape_count;
        item.algebraic_recommendation_count = status_value.recommendation_count;
        if (include_adaptive_scans) {
            const adaptive_candidates = try entry.index.scanPersistedAdaptiveCandidates(self.core.store);
            defer {
                for (adaptive_candidates) |*candidate| candidate.deinit(entry.index.alloc);
                if (adaptive_candidates.len > 0) entry.index.alloc.free(adaptive_candidates);
            }
            item.algebraic_adaptive_candidate_count = @intCast(adaptive_candidates.len);
            var top_candidate_index: ?usize = null;
            for (adaptive_candidates) |candidate| switch (candidate.lifecycle) {
                .backfilling => item.algebraic_adaptive_backfilling_count += 1,
                .ready => item.algebraic_adaptive_ready_count += 1,
                .stale => item.algebraic_adaptive_stale_count += 1,
                .dematerialize_recommended => item.algebraic_adaptive_dematerialize_recommended_count += 1,
                else => {},
            };
            for (adaptive_candidates, 0..) |candidate, i| {
                const selected_index = top_candidate_index orelse {
                    top_candidate_index = i;
                    continue;
                };
                const selected = adaptive_candidates[selected_index];
                if (candidate.score > selected.score or
                    (candidate.score == selected.score and candidate.observation_count > selected.observation_count))
                {
                    top_candidate_index = i;
                }
            }
            if (adaptive_candidates.len > 0) {
                const status_candidates = try alloc.alloc(types.AlgebraicCandidateStatus, adaptive_candidates.len);
                var initialized_candidates: usize = 0;
                errdefer {
                    for (status_candidates[0..initialized_candidates]) |candidate| {
                        alloc.free(candidate.recommendation);
                        alloc.free(candidate.materialization_id);
                        alloc.free(candidate.lifecycle);
                        alloc.free(candidate.decision);
                    }
                    alloc.free(status_candidates);
                }
                for (adaptive_candidates, 0..) |candidate, i| {
                    status_candidates[i] = try cloneAlgebraicCandidateStatusAlloc(
                        alloc,
                        candidate.recommendation,
                        candidate.materialization_id,
                        @tagName(candidate.lifecycle),
                        candidate.decision,
                        candidate.observation_count,
                        candidate.estimated_scan_rows_saved,
                        candidate.estimated_write_cost,
                        candidate.estimated_tensor_rows,
                        candidate.estimated_storage_bytes,
                        candidate.estimated_write_amplification,
                        candidate.score,
                        candidate.idle_miss_count,
                        candidate.generation,
                    );
                    initialized_candidates += 1;
                }
                item.algebraic_candidates = status_candidates;
            }
            if (top_candidate_index) |i| {
                const candidate = adaptive_candidates[i];
                item.algebraic_top_candidate = try cloneAlgebraicCandidateStatusAlloc(
                    alloc,
                    candidate.recommendation,
                    candidate.materialization_id,
                    @tagName(candidate.lifecycle),
                    candidate.decision,
                    candidate.observation_count,
                    candidate.estimated_scan_rows_saved,
                    candidate.estimated_write_cost,
                    candidate.estimated_tensor_rows,
                    candidate.estimated_storage_bytes,
                    candidate.estimated_write_amplification,
                    candidate.score,
                    candidate.idle_miss_count,
                    candidate.generation,
                );
            }
            const adaptive_decisions = try entry.index.scanPersistedAdaptiveDecisions(self.core.store, 16);
            defer {
                for (adaptive_decisions) |*decision| decision.deinit(entry.index.alloc);
                if (adaptive_decisions.len > 0) entry.index.alloc.free(adaptive_decisions);
            }
            item.algebraic_adaptive_decision_history_count = @intCast(adaptive_decisions.len);
            for (adaptive_decisions) |decision| {
                if (!std.mem.eql(u8, decision.previous_decision, decision.decision) or decision.score_delta != 0) {
                    item.algebraic_adaptive_policy_drift_count += 1;
                }
            }
            if (adaptive_decisions.len > 0) {
                const status_decisions = try alloc.alloc(types.AlgebraicCandidateDecisionStatus, adaptive_decisions.len);
                var initialized_decisions: usize = 0;
                errdefer {
                    for (status_decisions[0..initialized_decisions]) |decision| {
                        alloc.free(decision.recommendation);
                        alloc.free(decision.materialization_id);
                        alloc.free(decision.lifecycle);
                        alloc.free(decision.previous_decision);
                        alloc.free(decision.decision);
                    }
                    alloc.free(status_decisions);
                }
                for (adaptive_decisions, 0..) |decision, i| {
                    status_decisions[i] = try cloneAlgebraicCandidateDecisionStatusAlloc(
                        alloc,
                        decision.recommendation,
                        decision.materialization_id,
                        @tagName(decision.lifecycle),
                        decision.previous_decision,
                        decision.decision,
                        decision.observation_count,
                        decision.estimated_scan_rows_saved,
                        decision.estimated_write_cost,
                        decision.score,
                        decision.score_delta,
                        decision.idle_miss_count,
                        decision.generation,
                    );
                    initialized_decisions += 1;
                }
                item.algebraic_candidate_decision_history = status_decisions;
            }
            const adaptive_progress = try entry.index.scanPersistedAdaptiveProgress(self.core.store);
            defer {
                for (adaptive_progress) |*progress| progress.deinit(entry.index.alloc);
                if (adaptive_progress.len > 0) entry.index.alloc.free(adaptive_progress);
            }
            item.algebraic_adaptive_progress_count = @intCast(adaptive_progress.len);
            var active_progress_index: ?usize = null;
            if (adaptive_candidates.len == 0) {
                for (adaptive_progress) |progress| switch (progress.lifecycle) {
                    .backfilling => item.algebraic_adaptive_backfilling_count += 1,
                    .ready => item.algebraic_adaptive_ready_count += 1,
                    .stale => item.algebraic_adaptive_stale_count += 1,
                    .dematerialize_recommended => item.algebraic_adaptive_dematerialize_recommended_count += 1,
                    else => {},
                };
            }
            for (adaptive_progress, 0..) |progress, i| {
                const selected_index = active_progress_index orelse {
                    active_progress_index = i;
                    continue;
                };
                const selected = adaptive_progress[selected_index];
                if ((progress.lifecycle == .backfilling and selected.lifecycle != .backfilling) or
                    (progress.lifecycle == selected.lifecycle and progress.target_sequence > selected.target_sequence) or
                    (progress.lifecycle == selected.lifecycle and progress.target_sequence == selected.target_sequence and progress.rows_processed > selected.rows_processed))
                {
                    active_progress_index = i;
                }
            }
            if (adaptive_progress.len > 0) {
                const status_progress = try alloc.alloc(types.AlgebraicProgressStatus, adaptive_progress.len);
                var initialized_progress: usize = 0;
                errdefer {
                    for (status_progress[0..initialized_progress]) |progress| {
                        alloc.free(progress.recommendation);
                        alloc.free(progress.materialization_id);
                        alloc.free(progress.lifecycle);
                    }
                    alloc.free(status_progress);
                }
                for (adaptive_progress, 0..) |progress, i| {
                    status_progress[i] = try cloneAlgebraicProgressStatusAlloc(
                        alloc,
                        progress.recommendation,
                        progress.materialization_id,
                        @tagName(progress.lifecycle),
                        progress.target_sequence,
                        progress.applied_sequence,
                        progress.rows_processed,
                        progress.target_rows,
                    );
                    initialized_progress += 1;
                }
                item.algebraic_progress = status_progress;
            }
            if (active_progress_index) |i| {
                const progress = adaptive_progress[i];
                item.algebraic_active_progress = try cloneAlgebraicProgressStatusAlloc(
                    alloc,
                    progress.recommendation,
                    progress.materialization_id,
                    @tagName(progress.lifecycle),
                    progress.target_sequence,
                    progress.applied_sequence,
                    progress.rows_processed,
                    progress.target_rows,
                );
            }
        }
        if (status_value.last_error_doc_key) |value| {
            item.algebraic_last_error_doc_key = try alloc.dupe(u8, value);
        }
        errdefer if (item.algebraic_last_error_doc_key) |value| {
            alloc.free(value);
            item.algebraic_last_error_doc_key = null;
        };
        if (status_value.last_error_reason) |value| {
            item.algebraic_last_error_reason = try alloc.dupe(u8, value);
        }
        errdefer if (item.algebraic_last_error_reason) |value| {
            alloc.free(value);
            item.algebraic_last_error_reason = null;
        };
        if (status_value.last_observed_query_shape) |value| {
            item.algebraic_last_observed_query_shape = try alloc.dupe(u8, value);
        }
        errdefer if (item.algebraic_last_observed_query_shape) |value| {
            alloc.free(value);
            item.algebraic_last_observed_query_shape = null;
        };
        if (status_value.last_recommended_materialization) |value| {
            item.algebraic_last_recommended_materialization = try alloc.dupe(u8, value);
        }
    }

    fn scanPrimaryDocCount(self: *DB, byte_range: types.ByteRange) !u64 {
        const lower = try self.core.documentRangeLowerAlloc(byte_range.start);
        defer self.core.alloc.free(lower);
        const upper = if (byte_range.end.len > 0) try self.core.documentRangeUpperAlloc(byte_range.end) else null;
        defer if (upper) |buf| self.core.alloc.free(buf);

        var doc_count: u64 = 0;
        const CountState = struct {
            doc_count: *u64,

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                _ = value;
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                if (isPrimaryDocumentStoreKey(key)) state.doc_count.* += 1;
                return .@"continue";
            }
        };

        var state = CountState{ .doc_count = &doc_count };
        try self.core.store.scanWithContext(lower, if (upper) |buf| buf else "", .{}, &state, CountState.scanEntry);
        return doc_count;
    }

    fn initializeDerivedCoverageIdentity(cfg: types.IndexConfig, item: *types.DBIndexStats) void {
        item.coverage_generation = internal_keys.derivedCoverageGenerationForConfig(cfg.coverage_generation, cfg.config_json);
        if (cfg.coverage_config_fingerprint) |fingerprint| {
            item.coverage_config_hash = fingerprint;
            item.coverage_identity_ready = true;
        } else {
            // Catalog admission should make this state unreachable. Keep status
            // available and expose the missing identity as degraded coverage.
            item.coverage_summary_ready = false;
            item.repair_degraded = true;
        }
    }

    fn hydrateDerivedCoverageIdentities(self: *DB, alloc: Allocator, items: []types.DBIndexStats) !void {
        var needs_hydration = false;
        for (items) |item| {
            if (!item.coverage_identity_ready) {
                needs_hydration = true;
                break;
            }
        }
        if (!needs_hydration) return;

        var identities = try self.core.index_manager.coverageIdentityMapAlloc(alloc);
        defer identities.deinit(alloc);
        for (items) |*item| {
            const identity = identities.get(item.name) orelse {
                markMissingDerivedCoverageIdentity(item);
                continue;
            };
            item.coverage_generation = identity.generation;
            if (identity.config_fingerprint) |fingerprint| {
                item.coverage_config_hash = fingerprint;
                item.coverage_identity_ready = true;
            } else {
                markMissingDerivedCoverageIdentity(item);
            }
        }
    }

    fn hydrateDerivedCoverageIdentitiesBestEffort(self: *DB, alloc: Allocator, items: []types.DBIndexStats) void {
        self.hydrateDerivedCoverageIdentities(alloc, items) catch markMissingDerivedCoverageIdentities(items);
    }

    fn markMissingDerivedCoverageIdentities(items: []types.DBIndexStats) void {
        for (items) |*item| {
            markMissingDerivedCoverageIdentity(item);
        }
    }

    fn markMissingDerivedCoverageIdentity(item: *types.DBIndexStats) void {
        item.coverage_identity_ready = false;
        item.coverage_summary_ready = false;
        if (item.kind == .dense_vector) item.publication_target_ready = false;
        item.repair_degraded = true;
    }

    fn populateDerivedCoverageCounts(self: *DB, index_name: []const u8, generation: u64, config_hash: u64, item: *types.DBIndexStats) !DerivedCoverageCounters {
        item.coverage_config_hash = config_hash;
        const coverage_counts = try loadDerivedCoverageCounters(self.core.alloc, self.core.store, index_name, generation, null, if (builtin.is_test) self.async_context else null);
        const produced = coverage_counts.produced;
        const skipped = coverage_counts.skipped;
        const terminal_failed = coverage_counts.terminal_failed;

        const present_count: u2 = @as(u2, @intFromBool(produced != null)) +
            @as(u2, @intFromBool(skipped != null)) +
            @as(u2, @intFromBool(terminal_failed != null));
        // Counter creation and marker mutation share one atomic batch. No
        // counters means a new generation; a partial tuple means corruption or
        // an interrupted legacy write and must not be reported as complete.
        item.coverage_summary_ready = present_count == 0 or present_count == 3;
        item.coverage_produced_count = produced orelse 0;
        item.coverage_skipped_count = skipped orelse 0;
        item.coverage_terminal_failed_count = terminal_failed orelse 0;
        if (!item.coverage_summary_ready) item.repair_degraded = true;
        return coverage_counts;
    }

    /// Whether producer-outcome coverage is meaningful for a graph or
    /// full_text index: only artifact-sourced projections have producers
    /// that record per-document outcomes. Embeddings indexes always apply.
    pub const derivedCoverageAppliesToIndex = local_mutation.derivedCoverageAppliesToIndex;

    fn populateConfiguredDerivedCoverageCounts(self: *DB, index_name: []const u8, item: *types.DBIndexStats) !void {
        if (!item.coverage_identity_ready) {
            item.coverage_summary_ready = false;
            if (item.kind == .dense_vector) item.publication_target_ready = false;
            item.repair_degraded = true;
            return;
        }
        const coverage_counts = try self.populateDerivedCoverageCounts(index_name, item.coverage_generation, item.coverage_config_hash, item);
        // Publication cardinality and source outcomes belong to the same
        // committed revision. Re-reading the artifact counter here could
        // combine old source coverage with a newer publication target.
        try self.populateDensePublicationTarget(index_name, coverage_counts, item);
    }

    /// Populate the exact physical cardinality expected from the current dense
    /// incarnation without scanning documents or artifacts. External,
    /// chunk-backed, and multi-source indexes use the write-maintained target
    /// counter because document outcomes cannot express their multiplicity.
    /// One-vector-per-document managed indexes use generation-scoped outcomes.
    fn populateDensePublicationTarget(self: *DB, index_name: []const u8, coverage_counts: DerivedCoverageCounters, item: *types.DBIndexStats) !void {
        if (item.kind != .dense_vector) return;
        item.publication_target_count = 0;
        item.publication_target_ready = false;
        const entry = self.core.denseIndex(index_name) orelse return;
        if (densePublicationTargetUsesArtifactCounter(entry)) {
            item.publication_target_count = (try coverage_counts.artifactCount()) orelse return;
            item.publication_target_ready = true;
            return;
        }
        if (!item.coverage_summary_ready) return;
        item.publication_target_count = item.coverage_produced_count;
        item.publication_target_ready = true;
    }

    fn populateConfiguredDerivedCoverageCountsBestEffort(self: *DB, index_name: []const u8, item: *types.DBIndexStats) void {
        self.populateConfiguredDerivedCoverageCounts(index_name, item) catch {
            item.coverage_summary_ready = false;
            if (item.kind == .dense_vector) item.publication_target_ready = false;
            item.repair_degraded = true;
        };
    }

    fn scanPrimaryDocIdentityCoverage(self: *DB, byte_range: types.ByteRange) !DocIdentityCoverage {
        const lower = try self.core.documentRangeLowerAlloc(byte_range.start);
        defer self.core.alloc.free(lower);
        const upper = if (byte_range.end.len > 0) try self.core.documentRangeUpperAlloc(byte_range.end) else null;
        defer if (upper) |buf| self.core.alloc.free(buf);

        var doc_ids = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (doc_ids.items) |doc_id| self.core.alloc.free(doc_id);
            doc_ids.deinit(self.core.alloc);
        }

        var coverage = DocIdentityCoverage{};
        const ScanState = struct {
            alloc: Allocator,
            doc_ids: *std.ArrayListUnmanaged([]u8),
            coverage: *DocIdentityCoverage,

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                _ = value;
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                if (!isPrimaryDocumentStoreKey(key)) return .@"continue";
                const raw_key = (try internal_keys.decodeStoredDocumentRowKeyAlloc(state.alloc, key)) orelse return .@"continue";
                errdefer state.alloc.free(raw_key);
                try state.doc_ids.append(state.alloc, raw_key);
                state.coverage.scanned_primary_docs += 1;
                return .@"continue";
            }
        };

        var scan_state = ScanState{
            .alloc = self.core.alloc,
            .doc_ids = &doc_ids,
            .coverage = &coverage,
        };
        try self.core.store.scanWithContext(lower, if (upper) |buf| buf else "", .{}, &scan_state, ScanState.scanEntry);

        var txn = try self.core.store.beginProbeTxn();
        defer txn.abort();
        for (doc_ids.items) |doc_id| {
            const ordinal = (try doc_identity.lookupOrdinalTxn(self.core.alloc, &txn, doc_id)) orelse {
                coverage.primary_docs_missing_ordinals += 1;
                continue;
            };
            const state = (try doc_identity.lookupStateTxn(&txn, ordinal)) orelse {
                coverage.primary_docs_missing_identity_state += 1;
                continue;
            };
            if (!state.isLive()) coverage.primary_docs_with_tombstone_ordinals += 1;
        }
        return coverage;
    }

    pub fn primaryDocCount(self: *DB, alloc: Allocator) !u64 {
        _ = alloc;
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        return try self.scanPrimaryDocCount(self.core.byteRange());
    }

    /// Cheap startup audit for the crash window where generated replay has no
    /// remaining watermark debt but the current index incarnation still lacks
    /// terminal outcomes for source documents. This deliberately avoids both
    /// the full stats path and a primary corpus scan. Current writers maintain
    /// the range cardinality transactionally; a missing cardinality (for
    /// example, an older restored corpus) is conservatively handed to the
    /// paged recovery owner instead of delaying availability to reconstruct it.
    fn generatedCoverageRecoveryConfigsAlloc(self: *DB, alloc: Allocator) ![]types.IndexConfig {
        if (!self.core.hasGeneratedEnrichmentTargets()) return try alloc.alloc(types.IndexConfig, 0);
        lockApplyShared(self);
        defer self.core.unlockApplyShared();

        const primary_doc_count = try range_cardinality.loadOrProveEmpty(alloc, self.core.store);
        if (primary_doc_count != null and primary_doc_count.? == 0)
            return try alloc.alloc(types.IndexConfig, 0);
        const managed_indexes = try self.core.managedIndexes(alloc);
        defer {
            for (managed_indexes) |index_ref| alloc.free(@constCast(index_ref.name));
            alloc.free(managed_indexes);
        }
        var configs = std.ArrayListUnmanaged(types.IndexConfig).empty;
        errdefer {
            for (configs.items) |*cfg| cfg.deinit(alloc);
            configs.deinit(alloc);
        }
        for (managed_indexes) |index_ref| {
            // Only vector replay maintains this per-index source-outcome
            // tuple. Artifact-backed text/graph projections can require the
            // same producers without emitting vector coverage counters. Their
            // absence is not unfinished materialization: treating it as debt
            // reprocesses healthy sibling artifacts and gates their queries.
            if (index_ref.kind != .dense_vector and index_ref.kind != .sparse_vector) continue;
            if (!try self.core.indexRequiresEnrichmentReplay(index_ref.name)) continue;
            const cfg = self.core.index_manager.get(index_ref.name) orelse continue;
            var item = types.DBIndexStats{ .name = index_ref.name, .kind = index_ref.kind };
            initializeDerivedCoverageIdentity(cfg.*, &item);
            if (item.coverage_identity_ready) {
                _ = try self.populateDerivedCoverageCounts(
                    index_ref.name,
                    item.coverage_generation,
                    item.coverage_config_hash,
                    &item,
                );
            }
            const settled = item.coverage_produced_count +|
                item.coverage_skipped_count +|
                item.coverage_terminal_failed_count;
            if (primary_doc_count) |source_total| {
                if (item.coverage_identity_ready and item.coverage_summary_ready and settled >= source_total) continue;
            }
            try configs.append(alloc, try types.IndexConfig.clone(alloc, cfg.*));
        }
        return try configs.toOwnedSlice(alloc);
    }

    pub fn generatedCoverageReplayNeeded(self: *DB, alloc: Allocator) !bool {
        const configs = try self.generatedCoverageRecoveryConfigsAlloc(alloc);
        defer {
            for (configs) |*cfg| cfg.deinit(alloc);
            alloc.free(configs);
        }
        return configs.len != 0;
    }

    /// Returns true when every incomplete generated projection is already
    /// represented by an exact, live initial-build intent. This is the durable
    /// ownership proof used by a resident writer: ordinary provider/backfill
    /// latency must not be reclassified as broad startup repair merely because
    /// the enrichment watermark is momentarily idle.
    pub fn generatedCoverageRecoveryOwnedByInitialBuild(self: *DB, alloc: Allocator) !bool {
        const configs = try self.generatedCoverageRecoveryConfigsAlloc(alloc);
        defer {
            for (configs) |*cfg| cfg.deinit(alloc);
            alloc.free(configs);
        }
        if (configs.len == 0) return false;

        var state = self.loadIndexRepairState(alloc) catch |err| switch (err) {
            error.FileNotFound, error.DurableIndexRepairStateUnavailable => return false,
            else => return err,
        };
        defer state.deinit(alloc);
        for (configs) |cfg| {
            if (!self.currentInitialBuildIntentMatches(&state, cfg)) return false;
        }
        return true;
    }

    fn currentInitialBuildIntentMatches(
        self: *const DB,
        state: *const index_repair_state.State,
        cfg: types.IndexConfig,
    ) bool {
        const index = state.findIndex(cfg.name) orelse return false;
        const intent = state.entries.items[index].intent;
        return intent.work_class == .initial_build and
            intent.phase != .terminal and
            intent.automation != .paused and
            intent.root_generation == self.core.root_generation and
            intent.group_id == self.localRepairGroupId() and
            intent.config_hash == types.indexConfigHash(cfg);
    }

    fn currentNonInitialRepairIntentMatches(
        self: *const DB,
        state: *const index_repair_state.State,
        cfg: types.IndexConfig,
    ) bool {
        const index = state.findIndex(cfg.name) orelse return false;
        const intent = state.entries.items[index].intent;
        return intent.work_class != .initial_build and
            intent.phase != .terminal and
            intent.root_generation == self.core.root_generation and
            intent.group_id == self.localRepairGroupId() and
            intent.config_hash == types.indexConfigHash(cfg);
    }

    /// Converts an idle-watermark/source-coverage mismatch into the existing
    /// durable, bounded generation-materialization state machine. Source discovery is
    /// paged at 128 documents per owner quantum and crash-resumes from its
    /// fenced cursor; the currently published partial generation remains
    /// serviceable until the replacement is atomically activated.
    pub fn ensureGeneratedCoverageRecoveryIntents(self: *DB, alloc: Allocator) !usize {
        const configs = try self.generatedCoverageRecoveryConfigsAlloc(alloc);
        defer {
            for (configs) |*cfg| cfg.deinit(alloc);
            alloc.free(configs);
        }
        var ensured: usize = 0;
        for (configs) |cfg| {
            _ = try self.createGenerationRepairIntentAtTarget(
                alloc,
                cfg,
                .replay_artifact_unavailable,
                0,
                0,
                "generated_source_coverage_incomplete_after_replay",
                null,
                .pending,
                // A missing terminal source outcome after replay is unfinished
                // materialization, not evidence that the published generation
                // is corrupt. It shares the bounded generation scheduler with
                // repair, while retaining its non-repair lifecycle class.
                .initial_build,
            );
            ensured += 1;
        }
        return ensured;
    }

    pub fn scan(self: *DB, alloc: Allocator, from_key: []const u8, to_key: []const u8, opts: types.ScanOptions) !types.ScanResult {
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        var collector = result_collectors.Scan{ .alloc = alloc, .include_documents = opts.include_documents };
        defer collector.deinit();
        try self.scanVisit(alloc, from_key, to_key, opts, .{
            .context = &collector,
            .visit = result_collectors.Scan.visit,
        });
        return try collector.finish();
    }

    pub const StatementReadFence = struct {
        primary: snapshot_admission_mod.SnapshotAdmission.CaptureLease,
        replay: snapshot_admission_mod.SnapshotAdmission.CaptureLease,

        pub fn release(fence: *StatementReadFence) void {
            fence.replay.release();
            fence.primary.release();
        }
    };

    /// A short capture fence, not a transaction-long writer lock. The caller
    /// captures every participating owner, pins their read views, then releases
    /// every fence before reading rows. A busy participant requires releasing
    /// ALL earlier fences before retrying: a prepared transaction may need one
    /// of those owners to finish resolution. Never drain it under this fence.
    pub fn tryStatementReadFence(self: *DB) !?StatementReadFence {
        var primary = self.core.snapshot_admission.tryAcquireCapture() orelse return null;
        errdefer primary.release();
        var replay = self.core.snapshot_replay_admission.tryAcquireCapture() orelse {
            primary.release();
            return null;
        };
        errdefer replay.release();
        // SQL pins only the primary row store. External vector payloads are
        // irrelevant to this visibility cut; the full-backup capability gate
        // would incorrectly reject ordinary SQL on such tables.
        var manager = try self.core.initTxnManager();
        defer manager.deinit();
        if (try manager.hasUnresolvedWriteIntents()) {
            replay.release();
            primary.release();
            return null;
        }
        return .{ .primary = primary, .replay = replay };
    }

    /// Owns a retained schema/store snapshot and its authorization predicate.
    /// The DB owner and request cancellation source must outlive this session;
    /// no query, projection, bound or filter bytes are borrowed from the caller.
    pub const RelationalReadSession = @import("relational_read_session.zig").Session;

    pub const DocumentReadSession = @import("document_rows.zig").Session;

    pub fn openDocumentReadSession(self: *DB, alloc: Allocator, from_key: []const u8, to_key: []const u8, opts: types.ScanOptions) !*DocumentReadSession {
        try self.maybeFinalizePendingRowPolicyPublication();
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRawRead();
        errdefer row_policy_lease.release();
        try self.lockApplySharedForPortableRuntime();
        var locked = true;
        defer if (locked) self.core.unlockApplyShared();
        var schema = self.core.acquireSchemaView();
        defer if (schema) |*view| view.release();
        const borrowed = self.core.byteRange();
        const start = try alloc.dupe(u8, borrowed.start);
        defer alloc.free(start);
        const end = try alloc.dupe(u8, borrowed.end);
        defer alloc.free(end);
        const txn = try self.core.store.beginReadTxnWithBlockCacheAdmission(.transient);
        const now = currentTimeNs();
        self.core.unlockApplyShared();
        locked = false;
        const session = try DocumentReadSession.openSnapshot(alloc, self.core.store, txn, schema, .{ .start = start, .end = end }, from_key, to_key, opts, now);
        session.row_policy_lease = row_policy_lease;
        return session;
    }

    pub fn openRelationalReadSession(self: *DB, alloc: Allocator, from_key: []const u8, to_key: []const u8, opts: types.ScanOptions) !*RelationalReadSession {
        return self.openRelationalReadSessionAtSnapshot(alloc, from_key, to_key, opts, null);
    }

    pub fn openRelationalReadSessionAtSnapshot(self: *DB, alloc: Allocator, from_key: []const u8, to_key: []const u8, opts: types.ScanOptions, statement: ?*RelationalStatementSnapshot) !*RelationalReadSession {
        try self.maybeFinalizePendingRowPolicyPublication();
        var verified_principal: ?std.json.Parsed(row_policy_authority_mod.Payload) = null;
        defer if (verified_principal) |*proof| proof.deinit();
        var row_policy_lease = if (opts.row_policy_principal_proof.len != 0) bound: {
            if (opts.row_policy_principal_proof.len > row_policy_authority_mod.maximum_token_bytes or
                opts.row_policy_database.len == 0) return error.RowPolicyAuthenticationRequired;
            if (statement) |cut| if (cut.row_policy_phase != .active) return error.RowPolicyCatalogChanged;
            const secret = self.local_execution.row_policy_authority_secret orelse return error.RowPolicyAuthorityUnavailable;
            const issuer = self.local_execution.row_policy_authority_issuer orelse return error.RowPolicyAuthorityUnavailable;
            const table = self.local_execution.row_policy_table_name orelse return error.RowPolicyAuthorityUnavailable;
            const now_seconds: i64 = @intCast(@divFloor(platform_time.realtimeNs(), std.time.ns_per_s));
            verified_principal = try row_policy_authority_mod.verify(alloc, secret, issuer, .{
                .table_id = self.core.identity_namespace.table_id,
                .table = table,
                .database = opts.row_policy_database,
                .policy_generation = self.local_execution.row_policy_gate.generation.load(.acquire),
                .catalog_epoch = self.local_execution.row_policy_gate.catalog_epoch.load(.acquire),
            }, now_seconds, opts.row_policy_principal_proof);
            if (statement) |cut| if (cut.row_policy_generation != verified_principal.?.value.policy_generation or
                cut.row_policy_catalog_epoch != verified_principal.?.value.catalog_epoch) return error.RowPolicyCatalogChanged;
            break :bound try self.local_execution.row_policy_gate.enterVerifiedPrincipal(&verified_principal.?.value, now_seconds);
        } else if (statement) |pinned_statement| blk: {
            if (pinned_statement.row_policy_phase != .disabled) return error.RowPolicyAuthenticationRequired;
            const lease = if (pinned_statement.row_policy_lease) |*active| active else return error.RowPolicyAuthenticationRequired;
            break :blk lease.clone();
        } else try self.local_execution.row_policy_gate.enterRawRead();
        errdefer row_policy_lease.release();
        if (opts.relational_query_json.len > 1024 * 1024 or opts.limit > 4096) return error.InvalidRelationalRowsRequest;
        const session = try alloc.create(RelationalReadSession);
        errdefer alloc.destroy(session);
        session.* = .{ .alloc = alloc, .cancellation = opts.cancellation, .deadline_ns = opts.execution_deadline_ns };
        try session.checkpoint();
        const Input = types.RelationalRowQuery;
        var parsed_json: ?std.json.Parsed(Input) = if (opts.relational_query == null) std.json.parseFromSlice(Input, alloc, opts.relational_query_json, .{ .allocate = .alloc_always, .parse_numbers = false, .ignore_unknown_fields = true }) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return error.InvalidRelationalRowsRequest,
        } else null;
        defer if (parsed_json) |*owned| owned.deinit();
        const parsed = .{ .value = opts.relational_query orelse parsed_json.?.value };
        if (parsed.value.page_bytes == 0 or parsed.value.page_bytes > 16 * 1024 * 1024) return error.InvalidRelationalRowsRequest;
        session.page_bytes = parsed.value.page_bytes;
        if (parsed.value.conditions.len > 256 or parsed.value.fields.len > 256) return error.InvalidRelationalRowsRequest;
        var view = self.core.acquireSchemaView() orelse return error.RelationalTableRequired;
        defer view.release();
        if (view.storageMode() != .relational) return error.RelationalTableRequired;
        if (opts.include_range_proofs and view.tableSchema().ttl_duration_ns != 0) return error.UnsupportedSqlExecution;
        if (parsed.value.schema_version) |version| if (version != view.version()) return error.PreparedGenerationChanged;
        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const scratch = arena.allocator();
        if (parsed.value.index == null and (parsed.value.after != null or parsed.value.lower != null or parsed.value.upper != null)) return error.InvalidRelationalRowsRequest;
        if (parsed.value.index != null and (parsed.value.schema_version == null or from_key.len != 0 or to_key.len != 0)) return error.InvalidRelationalRowsRequest;
        var lower: ?RelationalRows.Bound = null;
        var upper: ?RelationalRows.Bound = null;
        if (parsed.value.index) |name| {
            var indexes = self.core.relational_indexes.acquire() orelse return error.IndexNotFound;
            defer indexes.deinit();
            if (indexes.plan.schemaView().epoch != view.epoch) return error.PreparedGenerationChanged;
            const index = for (indexes.plan.boundIndexes()) |candidate| {
                if (std.mem.eql(u8, candidate.name, name)) break candidate;
            } else return error.IndexNotFound;
            inline for (.{ "lower", "upper" }) |field| {
                if (@field(parsed.value, field)) |bound| {
                    if (bound.values.len == 0 or bound.values.len > index.tuple.keys.len) return error.InvalidRelationalIndexBound;
                    const values = try scratch.alloc(RelationalRows.Value, bound.values.len);
                    for (bound.values, values, index.tuple.keys[0..bound.values.len]) |value, *target, key| {
                        target.* = try @import("../../schema/relational_checks.zig").valueFromJson(scratch, key.column_type, value, true);
                    }
                    if (comptime std.mem.eql(u8, field, "lower")) lower = .{ .values = values, .inclusive = bound.inclusive } else upper = .{ .values = values, .inclusive = bound.inclusive };
                }
            }
        }
        const conditions = try scratch.alloc(RelationalRows.Condition, parsed.value.conditions.len);
        for (parsed.value.conditions, conditions) |condition, *compiled| {
            const ordinal = view.physicalLayout().ordinalForName(view.tableSchema().relational_columns, condition.column) orelse return error.RelationalIndexColumnNotFound;
            compiled.* = .{
                .column = condition.column,
                .op = condition.op,
                .value = try @import("../../schema/relational_checks.zig").valueFromJson(scratch, view.tableSchema().relational_columns[ordinal].column_type, condition.value orelse .null, true),
                .collation = condition.collation,
            };
        }
        const Filter = struct {
            alloc: Allocator,
            source: ?db_query_graph.PreparedPatternFilter = null,
            policy: ?*row_policy_bundle_mod.ReadEvaluation = null,
            bound: ?db_query_graph.PreparedOrdinalPatternFilter = null,
            version: ?u32 = null,

            pub fn deinit(filter: *@This()) void {
                if (filter.bound) |*bound| bound.deinit();
                if (filter.source) |*source| source.deinit();
                if (filter.policy) |policy| policy.deinit();
            }

            fn destroy(owner: Allocator, raw: *anyopaque) void {
                const filter: *@This() = @ptrCast(@alignCast(raw));
                filter.deinit();
                owner.destroy(filter);
            }

            fn matches(raw: *anyopaque, temporary: Allocator, key: []const u8, row: relational_row_codec.OrdinalRowView) !bool {
                const filter: *@This() = @ptrCast(@alignCast(raw));
                if (filter.policy) |policy| if (!try policy.permits(row)) return false;
                const source = if (filter.source) |*active| active else return true;
                if (filter.version == null or filter.version.? != row.table_schema.version) {
                    if (filter.bound) |*bound| bound.deinit();
                    filter.bound = null;
                    filter.version = null;
                    filter.bound = try db_query_graph.PreparedOrdinalPatternFilter.init(filter.alloc, source, row.table_schema, row.layout);
                    filter.version = row.table_schema.version;
                }
                if (try filter.bound.?.matches(temporary, key, row)) |matched| return matched;
                // Keep authorization semantics for filters which cannot yet
                // execute against ordinal cells. Never evaluate on the user's
                // projection or silently omit the security predicate.
                const json = try row.reconstructValueAlloc(temporary);
                defer temporary.free(json);
                return try source.matchesStored(temporary, key, json);
            }
        };
        const filter: ?*Filter = if (opts.filter_query_json.len != 0 or verified_principal != null) blk: {
            const active = try alloc.create(Filter);
            errdefer alloc.destroy(active);
            active.* = .{ .alloc = alloc };
            errdefer active.deinit();
            if (opts.filter_query_json.len != 0)
                active.source = try db_query_graph.PreparedPatternFilter.init(alloc, opts.filter_query_json);
            if (verified_principal) |*proof| {
                const bundle = if (self.local_execution.row_policy_bundle) |*installed| installed else return error.RowPolicyCatalogChanged;
                active.policy = try bundle.captureReadEvaluation(alloc, view.tableSchema().*, &proof.value);
            }
            break :blk active;
        } else null;
        errdefer if (filter) |active| Filter.destroy(alloc, active);
        session.reader = try self.beginRelationalRowsAtSnapshot(alloc, .{
            .index = parsed.value.index,
            .auto_index = parsed.value.auto_index,
            .include_primary_digest = opts.include_content_hashes,
            .include_cursor = parsed.value.index != null,
            .after = parsed.value.after,
            .lower = lower,
            .upper = upper,
            .fields = parsed.value.fields,
            .conditions = conditions,
            .primary_lower = if (from_key.len != 0) .{ .key = from_key, .inclusive = opts.inclusive_from } else null,
            .primary_upper = if (to_key.len != 0) .{ .key = to_key, .inclusive = !opts.exclusive_to } else null,
            .expected_schema_version = parsed.value.schema_version orelse view.version(),
            .row_filter = if (filter) |active| .{ .context = active, .matches = Filter.matches } else null,
        }, statement);
        session.filter_context = filter;
        session.destroy_filter = Filter.destroy;
        errdefer session.reader.deinit();
        if (opts.include_range_proofs) {
            const tracking = @import("../range_protection.zig");
            if (session.reader.index) |index| {
                const prefix = try @import("relational_index_records.zig").forwardPrefix(index.id());
                const next = if (parsed.value.after == null and lower != null and upper != null and
                    lower.?.inclusive and upper.?.inclusive and
                    lower.?.values.len == index.tuple.keys.len and upper.?.values.len == index.tuple.keys.len and
                    std.mem.startsWith(u8, session.reader.lower, &prefix) and session.reader.lower.len > prefix.len)
                    try internal_keys.nextPrefixAlloc(scratch, session.reader.lower)
                else
                    null;
                if (next) |exclusive_end| {
                    if (std.mem.eql(u8, exclusive_end, session.reader.upper)) {
                        session.range_proofs = try tracking.captureIndex(alloc, &session.reader.read, index.id().encode(), session.reader.lower[prefix.len..]);
                    }
                }
            }
            if (session.range_proofs == null) session.range_proofs = try tracking.capture(alloc, &session.reader.read, from_key, to_key);
        }
        session.row_policy_lease = row_policy_lease;
        return session;
    }

    fn scanRelationalRowsVisit(self: *DB, alloc: Allocator, from_key: []const u8, to_key: []const u8, opts: types.ScanOptions, visitor: types.ScanVisitor) !void {
        const session = try self.openRelationalReadSession(alloc, from_key, to_key, opts);
        defer session.deinit();
        const reader = &session.reader;
        const limit = if (opts.limit == 0) @as(u32, 128) else opts.limit;
        var delivered: usize = 0;
        var remaining_bytes: usize = 16 * 1024 * 1024;
        while (delivered < limit) {
            try session.checkpoint();
            if (opts.cancellation) |cancellation| if (cancellation.isCancelled()) return error.Canceled;
            if (opts.execution_deadline_ns) |deadline| if (platform_time.monotonicNs() >= deadline) return error.DeadlineExceeded;
            if (remaining_bytes == 0) return error.RelationalRowResultTooLarge;
            var page = try reader.nextPage(alloc, self.backend_runtime.io(), .{ .rows = @min(128, limit - delivered), .output_bytes = remaining_bytes });
            defer page.deinit();
            for (page.rows) |row| {
                try session.checkpoint();
                if (opts.cancellation) |cancellation| if (cancellation.isCancelled()) return error.Canceled;
                try visitor.visit(visitor.context, .{
                    .id = row.key,
                    .hash = row.version,
                    .content_hash = if (opts.include_content_hashes) row.semantic_hash else null,
                    .relational_schema_version = reader.active.version(),
                    .relational_cursor = row.cursor,
                    .json_null_fields = row.json_null_fields,
                    .document_json = if (opts.include_documents) row.json else null,
                });
                delivered += 1;
            }
            remaining_bytes -= page.output_bytes;
            if (!page.more) break;
            if (delivered < limit) if (self.backend_runtime.io()) |io| try io.sleep(.fromNanoseconds(1), .awake);
        }
    }

    /// Stream a scan directly from one storage snapshot. This is the bounded
    /// primitive for transports and maintenance jobs: only the current row and
    /// caller-owned output are resident, and callback failure aborts promptly.
    pub fn scanVisit(
        self: *DB,
        alloc: Allocator,
        from_key: []const u8,
        to_key: []const u8,
        opts: types.ScanOptions,
        visitor: types.ScanVisitor,
    ) !void {
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        if (opts.isRelational()) return self.scanRelationalRowsVisit(alloc, from_key, to_key, opts, visitor);
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        defer row_policy_lease.release();
        const projection_plan = db_query_projection.buildLookupFieldSelectionPlan(.{
            .fields = opts.fields,
            .include_all_fields = opts.include_all_fields,
        });
        const needs_catalog_projection = opts.include_documents and projection_plan.special.all_artifacts;
        // Briefly pin immutable request state. The storage transaction below,
        // rather than the DB-wide apply lock, owns row/TTL consistency for the
        // potentially long scan.
        lockApplyShared(self);
        var apply_shared_held = true;
        errdefer if (apply_shared_held) self.core.unlockApplyShared();
        var schema_view = self.core.acquireSchemaView();
        defer if (schema_view) |*view| view.release();
        const ttl_duration_ns = if (schema_view) |view| view.visibilityTtlDurationNs() else 0;
        const scan_now_ns = if (ttl_duration_ns == 0) 0 else currentTimeNs();

        const borrowed_range = self.core.byteRange();
        const range_start = try alloc.dupe(u8, borrowed_range.start);
        errdefer alloc.free(range_start);
        const range_end = try alloc.dupe(u8, borrowed_range.end);
        errdefer alloc.free(range_end);
        var artifact_catalog = if (needs_catalog_projection)
            try self.core.index_manager.assetContentTypeSnapshotAlloc(alloc)
        else
            null;
        defer if (artifact_catalog) |*artifact_snapshot| artifact_snapshot.deinit();
        self.core.unlockApplyShared();
        apply_shared_held = false;
        defer alloc.free(range_start);
        defer alloc.free(range_end);
        const byte_range = types.ByteRange{ .start = range_start, .end = range_end };
        const lower_raw = if (from_key.len == 0 or std.mem.order(u8, from_key, byte_range.start) == .lt) byte_range.start else from_key;
        const upper_raw = blk: {
            if (to_key.len == 0) break :blk byte_range.end;
            if (byte_range.end.len == 0 or std.mem.order(u8, to_key, byte_range.end) == .lt) break :blk to_key;
            break :blk byte_range.end;
        };
        const lower = try self.core.documentRangeLowerAlloc(lower_raw);
        defer self.core.alloc.free(lower);
        const upper = if (upper_raw.len > 0) try self.core.documentRangeUpperAlloc(upper_raw) else null;
        defer if (upper) |buf| self.core.alloc.free(buf);

        var prepared_filter = if (opts.filter_query_json.len > 0)
            try db_query_graph.PreparedPatternFilter.init(alloc, opts.filter_query_json)
        else
            null;
        defer if (prepared_filter) |*filter| filter.deinit();
        const direct_projection_fields = if (opts.include_documents)
            ordinalProjectionFields(opts.fields, opts.include_all_fields)
        else
            null;
        var read_txn = try self.core.store.beginReadTxn();
        defer read_txn.abort();
        var projection_context = TransactionProjectionContext{
            .source = .{ .core = self.core },
            .read_txn = &read_txn,
            .artifact_catalog = if (artifact_catalog) |*artifact_snapshot| artifact_snapshot else null,
        };

        var columnar_progress: relational_columns.Progress = .{};
        defer columnar_progress.last_key.deinit(alloc);
        var column_materializer = ColumnScanMaterializer{ .context = &projection_context, .opts = opts };
        const accelerated = if (schema_view != null and schema_view.?.storageMode() == .relational) relational_columns.scan(self, alloc, &read_txn, from_key, to_key, byte_range, opts, visitor, ttl_duration_ns, scan_now_ns, &columnar_progress, if (prepared_filter) |*filter| filter else null, .{ .context = &column_materializer, .project = ColumnScanMaterializer.project }) catch |err| switch (err) {
            error.InvalidColumnSegment, error.InvalidData, error.NotFound => blk: {
                if (columnar_progress.callback_failed) return err;
                // Disposable derived corruption never makes valid primary rows
                // unreadable. Resume in the same snapshot after the last row
                // actually delivered, preserving limits and avoiding duplicates.
                self.relational_columns_rebuild_requested.store(true, .release);
                break :blk false;
            },
            else => return err,
        } else false;
        if (accelerated) return;
        var fallback_opts = opts;
        if (columnar_progress.delivered != 0) fallback_opts.inclusive_from = false;

        const ScanState = struct {
            const max_resident_schema_plans = 32;
            const SchemaPlan = struct {
                version: u32,
                access: u64,
                view: schema_registry_mod.SchemaView,
                filter: ?db_query_graph.PreparedOrdinalPatternFilter = null,
                projection: ?RelationalProjectionPlan = null,

                pub fn deinit(plan: *@This()) void {
                    if (plan.filter) |*filter| filter.deinit();
                    if (plan.projection) |*projection| projection.deinit();
                    plan.view.release();
                    plan.* = undefined;
                }
            };

            db: *DB,
            alloc: Allocator,
            byte_range: types.ByteRange,
            from_key: []const u8,
            to_key: []const u8,
            opts: types.ScanOptions,
            ttl_duration_ns: u64,
            now_ns: u64,
            filter: ?*db_query_graph.PreparedPatternFilter,
            direct_projection_fields: ?[]const []const u8,
            read_txn: *docstore_mod.DocStore.Txn,
            projection_context: *TransactionProjectionContext,
            values_authenticated: bool,
            ttl_key_scratch: std.ArrayListUnmanaged(u8) = .empty,
            document_key_scratch: std.ArrayListUnmanaged(u8) = .empty,
            schema_plans: std.ArrayListUnmanaged(SchemaPlan) = .empty,
            schema_plan_indexes: std.AutoHashMapUnmanaged(u32, usize) = .empty,
            schema_plan_clock: u64 = 0,
            schema_admission: SchemaCacheAdmission = .{},
            transient_schema_plan: ?SchemaPlan = null,
            visitor: types.ScanVisitor,
            count: u32 = 0,
            resume_after_key: ?[]const u8 = null,

            pub fn deinit(state: *@This()) void {
                if (state.transient_schema_plan) |*plan| plan.deinit();
                state.ttl_key_scratch.deinit(state.alloc);
                state.document_key_scratch.deinit(state.alloc);
                for (state.schema_plans.items) |*plan| plan.deinit();
                state.schema_plans.deinit(state.alloc);
                state.schema_plan_indexes.deinit(state.alloc);
            }

            fn checkActive(state: *const @This()) !void {
                if (state.opts.cancellation) |cancellation|
                    if (cancellation.isCancelled()) return error.Canceled;
                if (state.opts.execution_deadline_ns) |deadline_ns|
                    if (platform_time.monotonicNs() >= deadline_ns) return error.DeadlineExceeded;
            }

            fn schemaPlan(state: *@This(), version: u32) !*SchemaPlan {
                state.schema_admission.record(version);
                state.schema_plan_clock +%= 1;
                if (state.schema_plan_clock == 0) {
                    for (state.schema_plans.items) |*resident| resident.access = 0;
                    state.schema_plan_clock = 1;
                }
                if (state.schema_plan_indexes.get(version)) |index| {
                    state.schema_plans.items[index].access = state.schema_plan_clock;
                    return &state.schema_plans.items[index];
                }
                if (state.transient_schema_plan) |*plan| {
                    if (plan.version == version) return plan;
                }

                try state.schema_plan_indexes.ensureUnusedCapacity(state.alloc, 1);
                var view = (try state.db.core.acquireSchemaVersionView(version)) orelse
                    return error.UnknownSchemaVersion;
                var view_owned = true;
                errdefer if (view_owned) view.release();
                if (view.storageMode() != .relational) return error.RelationalRowSchemaMismatch;
                var filter = if (state.filter) |prepared|
                    try db_query_graph.PreparedOrdinalPatternFilter.init(
                        state.alloc,
                        prepared,
                        view.tableSchema().*,
                        view.physicalLayout(),
                    )
                else
                    null;
                var filter_owned = filter != null;
                errdefer if (filter_owned) filter.?.deinit();
                var projection = if (state.direct_projection_fields) |fields|
                    try RelationalProjectionPlan.init(
                        state.alloc,
                        view.tableSchema().*,
                        view.physicalLayout(),
                        fields,
                    )
                else
                    null;
                var projection_owned = projection != null;
                errdefer if (projection_owned) projection.?.deinit();
                const new_plan = SchemaPlan{
                    .version = version,
                    .access = state.schema_plan_clock,
                    .view = view,
                    .filter = filter,
                    .projection = projection,
                };
                const plan_index = if (state.schema_plans.items.len < max_resident_schema_plans) blk: {
                    try state.schema_plans.append(state.alloc, new_plan);
                    break :blk state.schema_plans.items.len - 1;
                } else blk: {
                    var evicted_index: usize = 0;
                    var oldest_access = state.schema_plans.items[0].access;
                    for (state.schema_plans.items[1..], 1..) |candidate, index| {
                        const frequency = state.schema_admission.frequency(candidate.version);
                        const victim_frequency = state.schema_admission.frequency(state.schema_plans.items[evicted_index].version);
                        if (frequency < victim_frequency or (frequency == victim_frequency and candidate.access < oldest_access)) {
                            oldest_access = candidate.access;
                            evicted_index = index;
                        }
                    }
                    if (!state.schema_admission.admits(version, state.schema_plans.items[evicted_index].version)) {
                        if (state.transient_schema_plan) |*plan| plan.deinit();
                        state.transient_schema_plan = new_plan;
                        view_owned = false;
                        filter_owned = false;
                        projection_owned = false;
                        return &state.transient_schema_plan.?;
                    }
                    var evicted = state.schema_plans.items[evicted_index];
                    _ = state.schema_plan_indexes.remove(evicted.version);
                    state.schema_plans.items[evicted_index] = new_plan;
                    evicted.deinit();
                    break :blk evicted_index;
                };
                state.schema_plan_indexes.putAssumeCapacity(version, plan_index);
                view_owned = false;
                filter_owned = false;
                projection_owned = false;
                return &state.schema_plans.items[plan_index];
            }

            fn scanEntry(raw_ctx: ?*anyopaque, store_key: []const u8, stored_value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(raw_ctx orelse return error.InvalidArgument));
                try state.checkActive();
                if (!isPrimaryDocumentStoreKey(store_key)) return .@"continue";
                const raw_key = (try internal_keys.decodeStoredDocumentRowKeyScratch(
                    &state.document_key_scratch,
                    state.alloc,
                    store_key,
                )) orelse
                    return .@"continue";

                if (state.resume_after_key) |key| if (std.mem.order(u8, raw_key, key) != .gt) return .@"continue";

                if (!state.byte_range.contains(raw_key)) return .@"continue";
                if (state.from_key.len > 0 and !state.opts.inclusive_from and std.mem.eql(u8, raw_key, state.from_key))
                    return .@"continue";
                if (state.to_key.len > 0) {
                    const order = std.mem.order(u8, raw_key, state.to_key);
                    if ((state.opts.exclusive_to and order != .lt) or (!state.opts.exclusive_to and order == .gt))
                        return .stop;
                }
                const relational = internal_keys.isRelationalRowKey(store_key);
                const row_plan = if (relational)
                    try state.schemaPlan(try relational_store.rowSchemaVersion(stored_value))
                else
                    null;
                // Authenticate and structurally parse the row exactly once for
                // this callback. Every downstream consumer receives the same
                // immutable verified view instead of independently rescanning
                // the physical checksum and header.
                const ordinal_row = if (row_plan) |plan|
                    if (state.values_authenticated)
                        try relational_row_codec.ordinalRowViewTrusted(
                            stored_value,
                            plan.view.tableSchema().*,
                            plan.view.physicalLayout(),
                        )
                    else
                        try relational_row_codec.ordinalRowView(
                            stored_value,
                            plan.view.tableSchema().*,
                            plan.view.physicalLayout(),
                        )
                else
                    null;
                if (state.ttl_duration_ns != 0) {
                    const timestamp = if (relational)
                        ordinal_row.?.writeTimestampNs()
                    else blk: {
                        state.ttl_key_scratch.clearRetainingCapacity();
                        try internal_keys.appendDocumentPrefix(&state.ttl_key_scratch, state.alloc, raw_key);
                        try state.ttl_key_scratch.append(state.alloc, internal_keys.ttl_kind);
                        const timestamp_bytes = state.read_txn.get(state.ttl_key_scratch.items) catch |err| switch (err) {
                            error.NotFound => null,
                            else => return err,
                        };
                        break :blk if (timestamp_bytes) |value|
                            if (value.len >= @sizeOf(u64)) std.mem.readInt(u64, value[0..8], .little) else 0
                        else
                            0;
                    };
                    if (timestamp != 0 and ttl_mod.isExpired(timestamp, state.ttl_duration_ns, state.now_ns))
                        return .@"continue";
                }

                const semantic_hash = if (ordinal_row) |row| row.semanticHash() else null;
                var ordinal_filter_match: ?bool = null;
                if (row_plan) |plan| if (plan.filter) |*filter| {
                    ordinal_filter_match = try filter.matches(state.alloc, raw_key, ordinal_row.?);
                    if (ordinal_filter_match == false) return .@"continue";
                };
                const needs_logical_value = !relational or semantic_hash == null or
                    (state.filter != null and ordinal_filter_match == null) or
                    (state.opts.include_documents and state.direct_projection_fields == null);
                const logical_value = if (needs_logical_value)
                    if (ordinal_row) |row|
                        try row.reconstructValueAlloc(state.alloc)
                    else
                        try state.alloc.dupe(u8, stored_value)
                else
                    null;
                defer if (logical_value) |value| state.alloc.free(value);

                if (state.filter) |filter| if (ordinal_filter_match == null)
                    if (!(try filter.matchesStored(state.alloc, raw_key, logical_value.?)))
                        return .@"continue";

                var content_hash: ?document_content_hash.Digest = null;
                if (state.opts.include_content_hashes) {
                    content_hash = if (relational)
                        semantic_hash orelse try document_content_hash.hashJson(state.alloc, logical_value.?)
                    else
                        try document_content_hash.hashJson(state.alloc, logical_value.?);
                }
                const projected = if (state.opts.include_documents)
                    if (state.direct_projection_fields) |_|
                        if (ordinal_row) |row|
                            try row_plan.?.projection.?.project(state.alloc, row)
                        else
                            try projectLookupStoredBytesTxn(state.projection_context, state.alloc, raw_key, logical_value.?, .{
                                .fields = state.opts.fields,
                                .include_all_fields = state.opts.include_all_fields,
                            })
                    else
                        try projectLookupStoredBytesTxn(state.projection_context, state.alloc, raw_key, logical_value.?, .{
                            .fields = state.opts.fields,
                            .include_all_fields = state.opts.include_all_fields,
                        })
                else
                    null;
                defer if (projected) |document| state.alloc.free(document);

                try state.visitor.visit(state.visitor.context, .{
                    .id = raw_key,
                    // Relational hashes are the stable logical digest, not a
                    // hash of a transient JSON rendering. Document-mode rows
                    // retain the established byte-hash contract.
                    .hash = if (semantic_hash) |digest|
                        std.mem.readInt(u64, digest[0..8], .little)
                    else
                        std.hash.Wyhash.hash(0, logical_value.?),
                    .content_hash = content_hash,
                    .document_json = projected,
                });

                state.count += 1;
                return if (state.opts.limit > 0 and state.count >= state.opts.limit) .stop else .@"continue";
            }
        };

        var state = ScanState{
            .db = self,
            .alloc = alloc,
            .byte_range = byte_range,
            .from_key = if (columnar_progress.delivered != 0) columnar_progress.last_key.items else from_key,
            .to_key = to_key,
            .opts = fallback_opts,
            .ttl_duration_ns = ttl_duration_ns,
            .now_ns = scan_now_ns,
            .filter = if (prepared_filter) |*filter| filter else null,
            .direct_projection_fields = direct_projection_fields,
            .read_txn = &read_txn,
            .projection_context = &projection_context,
            .values_authenticated = self.core.store.valuesAreAuthenticated(),
            .visitor = visitor,
            .count = columnar_progress.delivered,
            .resume_after_key = if (columnar_progress.delivered != 0) columnar_progress.last_key.items else null,
        };
        defer state.deinit();
        try state.checkActive();
        const resume_lower = if (columnar_progress.delivered != 0) try self.core.documentRangeLowerAlloc(columnar_progress.last_key.items) else null;
        defer if (resume_lower) |key| self.core.alloc.free(key);
        if (schema_view) |view| if (view.storageMode() == .relational) {
            const Check = struct {
                fn owner(ptr: ?*anyopaque, _: []const u8) !docstore_mod.DocStore.ScanAction {
                    const active: *ScanState = @ptrCast(@alignCast(ptr.?));
                    try active.checkActive();
                    if (active.opts.columnar_stats) |scan_stats| scan_stats.primary_owners_examined += 1;
                    return .@"continue";
                }
            };
            return self.core.store.scanRelationalRowsReadTxnWithContext(&read_txn, resume_lower orelse lower, upper orelse "", &state, Check.owner, ScanState.scanEntry);
        };
        try self.core.store.scanReadTxnWithContext(
            &read_txn,
            resume_lower orelse lower,
            if (upper) |buf| buf else "",
            .{},
            &state,
            ScanState.scanEntry,
        );
    }

    pub fn search(self: *DB, alloc: Allocator, req: types.SearchRequest) !types.SearchResult {
        return try self.searchWithExecutionContext(alloc, req, .{});
    }

    /// Execute a general query while retaining the single dense component's
    /// profile when the request is composed (for example text+dense hybrid).
    /// The public response currently has one dense profile slot; compositions
    /// with multiple dense lanes intentionally leave it unset rather than
    /// publishing an ambiguous aggregate.
    pub fn searchWithDenseProfile(self: *DB, alloc: Allocator, req: types.SearchRequest) !SearchWithDenseProfileResult {
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        var row_policy_lease = try self.local_execution.row_policy_gate.enterUnsupportedSearch();
        defer row_policy_lease.release();
        try self.enforcePortableRuntimeGate();
        if (self.async_context.resource_manager) |manager| manager.beginForegroundQuery();
        defer if (self.async_context.resource_manager) |manager| manager.finishForegroundQuery();
        const snapshot_input = directSingleVectorRequest(req) orelse req;
        const dense = snapshot_input.dense orelse if (snapshot_input.query == .dense_knn) snapshot_input.query.dense_knn else null;
        if (dense) |query| if (try self.trySnapshotDenseSearch(alloc, snapshot_input, query, true)) |captured| {
            var result = captured;
            result.request = req;
            result.request.identity_read_generation = captured.request.identity_read_generation;
            return result;
        };
        const search_access = self.beginDenseSearchAccess(req);
        defer self.endDenseSearchAccess(search_access);
        try self.enforcePortableRuntimeGate();
        const snapshot_req = try self.searchRequestAtCurrentIdentityGeneration(req);
        var dense_profile: db_query_search.DenseSearchProfile = .{};
        const result = try self.searchLockedWithExecutionContextImpl(alloc, snapshot_req, .{}, true, &dense_profile);
        return .{
            .request = snapshot_req,
            .result = result,
            .dense_profile = if (dense_profile.search_route.len > 0) dense_profile else null,
        };
    }

    /// Returns the identity generation captured after entering the DB search
    /// lease together with the result produced under that lease. Public read
    /// adapters must use this operation instead of sampling the generation and
    /// then calling `search`, which leaves a writer race between the two calls.
    pub fn searchWithCapturedRequest(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
    ) !SearchWithCapturedRequestResult {
        return try self.searchWithCapturedRequestAndExecutionContext(alloc, req, .{});
    }

    /// Own one primary read generation across a local query's selection and
    /// aggregation collection. Acquire only after the Raft read barrier; never
    /// wait for another apply barrier while this lease excludes writers.
    pub const QueryReadLease = struct {
        db: *DB,
        row_policy_lease: row_policy_gate_mod.Gate.Lease,

        pub fn search(self: QueryReadLease, alloc: Allocator, req: types.SearchRequest) !SearchWithDenseProfileResult {
            const db = self.db;
            const snapshot_req = try db.searchRequestAtCurrentIdentityGeneration(req);
            if (!types.canonicalHierarchyExecutionWithinBudget(snapshot_req)) return error.InvalidQueryRequest;
            var identity_prefix = try db.searchRequestWithIdentityPrefixFilterAlloc(snapshot_req);
            defer identity_prefix.deinit();
            var profile: db_query_search.DenseSearchProfile = .{};
            const result = try db.searchLockedWithExecutionContextImpl(alloc, identity_prefix.req, .{}, true, if (req.profile) &profile else null);
            return .{
                .request = snapshot_req,
                .result = result,
                .dense_profile = if (profile.search_route.len > 0) profile else null,
            };
        }

        pub fn release(self: *QueryReadLease) void {
            const db = self.db;
            db.core.unlockApplyShared();
            if (db.async_context.resource_manager) |manager| manager.finishForegroundQuery();
            self.row_policy_lease.release();
            self.* = undefined;
        }
    };

    pub fn beginQueryReadLease(self: *DB) !QueryReadLease {
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        var row_policy_lease = try self.local_execution.row_policy_gate.enterUnsupportedSearch();
        errdefer row_policy_lease.release();
        if (self.async_context.resource_manager) |manager| manager.beginForegroundQuery();
        errdefer if (self.async_context.resource_manager) |manager| manager.finishForegroundQuery();
        try self.enforcePortableRuntimeGate();
        lockApplyShared(self);
        errdefer self.core.unlockApplyShared();
        try self.enforcePortableRuntimeGate();
        return .{ .db = self, .row_policy_lease = row_policy_lease };
    }

    pub fn searchWithExecutionContext(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
        exec_ctx: types.ExecutionContext,
    ) !types.SearchResult {
        return (try self.searchWithCapturedRequestAndExecutionContext(alloc, req, exec_ctx)).result;
    }

    fn searchWithCapturedRequestAndExecutionContext(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
        exec_ctx: types.ExecutionContext,
    ) !SearchWithCapturedRequestResult {
        if (self.local_execution.initial_child_hidden.load(.acquire)) return error.InitialChildNotPublished;
        var row_policy_lease = try self.local_execution.row_policy_gate.enterUnsupportedSearch();
        defer row_policy_lease.release();
        if (self.async_context.resource_manager) |manager| manager.beginForegroundQuery();
        defer if (self.async_context.resource_manager) |manager| manager.finishForegroundQuery();
        // Keep degraded requests out of catalog/apply lock queues. Revalidate
        // after admission below to close publication's check-to-use race.
        try self.enforcePortableRuntimeGate();
        if (std.meta.eql(exec_ctx, types.ExecutionContext{})) {
            const snapshot_input = directSingleVectorRequest(req) orelse req;
            const dense = snapshot_input.dense orelse if (snapshot_input.query == .dense_knn) snapshot_input.query.dense_knn else null;
            if (dense) |query| if (try self.trySnapshotDenseSearch(alloc, snapshot_input, query, false)) |captured| {
                var response_req = req;
                response_req.identity_read_generation = captured.request.identity_read_generation;
                return .{ .request = response_req, .result = captured.result };
            };
        }
        const bench_profile = benchQueryProfileEnabled();
        const total_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
        var generation_ns: u64 = 0;
        var lock_wait_ns: u64 = 0;
        var locked_search_ns: u64 = 0;
        const lock_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
        const search_access = self.beginDenseSearchAccess(req);
        if (bench_profile) lock_wait_ns = platform_time.monotonicNs() - lock_start_ns;
        defer self.endDenseSearchAccess(search_access);
        // beginDenseSearchAccess either owns apply-shared or a catalog lease
        // drained by portable activation. Validate only after that ownership is
        // established so publication cannot slip between the check and use.
        try self.enforcePortableRuntimeGate();
        const generation_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
        const snapshot_req = try self.searchRequestAtCurrentIdentityGeneration(req);
        if (bench_profile) generation_ns = platform_time.monotonicNs() - generation_start_ns;
        const search_start_ns = if (bench_profile) platform_time.monotonicNs() else 0;
        const result = try self.searchLockedWithExecutionContext(alloc, snapshot_req, exec_ctx);
        if (bench_profile) {
            locked_search_ns = platform_time.monotonicNs() - search_start_ns;
            std.log.info(
                "antfly_bench_db_search_wrapper total_us={d} generation_us={d} lock_wait_us={d} locked_search_us={d} published_dense={}",
                .{ (platform_time.monotonicNs() - total_start_ns) / 1000, generation_ns / 1000, lock_wait_ns / 1000, locked_search_ns / 1000, search_access == .published },
            );
        }
        return .{ .request = snapshot_req, .result = result };
    }

    fn searchLocked(self: *DB, alloc: Allocator, req: types.SearchRequest) !types.SearchResult {
        return try self.searchLockedWithExecutionContext(alloc, try self.searchRequestAtCurrentIdentityGeneration(req), .{});
    }

    pub fn searchRequestAtCurrentIdentityGeneration(self: *DB, req: types.SearchRequest) !types.SearchRequest {
        var snapshot_req = req;
        snapshot_req.identity_read_generation = try self.currentIdentityReadGenerationForRequest(snapshot_req.identity_read_generation);
        try self.validateResolvedDocFilterWireContext(snapshot_req);
        return snapshot_req;
    }

    fn validateResolvedDocFilterWireContext(self: *DB, req: types.SearchRequest) !void {
        const ctx = req.resolved_doc_filter_wire_context orelse return;
        if (req.resolved_doc_filter == null) return error.InvalidQueryRequest;
        if (!ctx.namespace.eql(self.core.identity_namespace)) return error.DocIdentityNamespaceMismatch;
        if (req.identity_read_generation == null or req.identity_read_generation.? != ctx.identity_read_generation) {
            self.local_execution.doc_set_planning_stats.recordStaleIdentityGenerationRejection();
            return error.UnsupportedQueryRequest;
        }
    }

    fn searchLockedWithExecutionContext(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
        exec_ctx: types.ExecutionContext,
    ) !types.SearchResult {
        if ((req.query == .graph or req.graph_queries.len != 0 or req.graph_metric_queries.len != 0 or req.graph_metric_rerank != null or req.graph_query_transport != null) and
            !self.core.index_manager.graphRetirementAdmissionOpen())
            return error.IntegrityTopologyBusy;
        // Validate canonical collapse-and-expand work before executing the
        // primary selection query. This protects direct storage callers and
        // internal worker envelopes in addition to the public API boundary.
        if (!types.canonicalHierarchyExecutionWithinBudget(req)) return error.InvalidQueryRequest;
        var identity_prefix_filter = try self.searchRequestWithIdentityPrefixFilterAlloc(req);
        defer identity_prefix_filter.deinit();
        return try self.searchLockedWithExecutionContextImpl(alloc, identity_prefix_filter.req, exec_ctx, true, null);
    }

    fn searchLockedWithExecutionContextImpl(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
        exec_ctx: types.ExecutionContext,
        externalize_artifact_ids: bool,
        dense_profile_sink: ?*db_query_search.DenseSearchProfile,
    ) !types.SearchResult {
        const execution_req = directSingleVectorRequest(req) orelse req;
        if (execution_req.hierarchy_children != null) {
            var children = try self.navigateHierarchyChildren(alloc, execution_req);
            errdefer children.deinit();
            if (externalize_artifact_ids) try externalizeSearchResultArtifactIds(alloc, &children);
            return children;
        }
        var selection_req = types.canonicalGroupedMatchSelectionRequest(execution_req);
        if (execution_req.graph_metric_rerank) |rerank| {
            try types.validateGraphMetricRerankWindow(rerank, execution_req.offset, execution_req.limit);
            selection_req.offset = 0;
            selection_req.limit = types.graphMetricRerankCandidateCount(rerank, execution_req.offset, execution_req.limit);
        }
        if (searchRequestRequiresComposedSearch(selection_req)) {
            var composed = try self.searchComposed(alloc, selection_req, exec_ctx, dense_profile_sink);
            errdefer composed.deinit();
            try self.populateCanonicalGroupedMatches(alloc, execution_req, exec_ctx, &composed);
            try self.applyGraphMetricRerank(&composed, execution_req);
            try self.attachSearchHighlights(alloc, execution_req, &composed);
            if (externalize_artifact_ids) try externalizeSearchResultArtifactIds(alloc, &composed);
            return composed;
        }

        const has_primary = selection_req.full_text != null or selection_req.dense != null or selection_req.sparse != null or !db_query_search.isDefaultMatchAll(selection_req.query) or (selection_req.graph_queries.len == 0 and selection_req.graph_metric_queries.len == 0);

        var base = if (!has_primary and (selection_req.graph_queries.len > 0 or selection_req.graph_metric_queries.len > 0))
            try db_query_search.emptySearchResult(alloc)
        else if (selection_req.full_text) |text|
            try self.searchTextQuery(alloc, selection_req, text)
        else if (selection_req.dense) |dense|
            try self.searchDenseWithProfileSink(alloc, selection_req, dense, dense_profile_sink)
        else if (selection_req.sparse) |sparse|
            try self.searchSparse(alloc, selection_req, sparse)
        else switch (selection_req.query) {
            .match_none,
            .match_all,
            .phrase,
            .multi_phrase,
            .term,
            .fuzzy,
            .numeric_range,
            .date_range,
            .doc_id,
            .bool_field,
            .geo_distance,
            .geo_bbox,
            .term_range,
            .ip_range,
            .geo_shape,
            .match,
            .match_phrase,
            .prefix,
            .wildcard,
            .regexp,
            => try self.searchText(alloc, selection_req),
            .dense_knn => |dense| try self.searchDenseWithProfileSink(alloc, selection_req, dense, dense_profile_sink),
            .sparse_knn => |sparse| try self.searchSparse(alloc, selection_req, sparse),
            .graph => |graph| try self.searchGraph(alloc, selection_req, graph, null),
        };
        errdefer base.deinit();
        try self.populateCanonicalGroupedMatches(alloc, execution_req, exec_ctx, &base);
        try self.attachSearchHighlights(alloc, execution_req, &base);

        if (execution_req.graph_metric_queries.len > 0) {
            base.graph_metric_results = try self.executeGraphMetricQueries(alloc, execution_req.graph_metric_queries, execution_req.cancellation);
        }
        try self.applyGraphMetricRerank(&base, execution_req);

        if (execution_req.graph_queries.len == 0) {
            if (externalize_artifact_ids) try externalizeSearchResultArtifactIds(alloc, &base);
            return base;
        }

        base.graph_results = try self.executeGraphQueries(alloc, execution_req, execution_req.graph_queries, base.hits, base.total_hits);
        try self.applyGraphExpandStrategy(alloc, &base, execution_req.expand_strategy);
        if (externalize_artifact_ids) try externalizeSearchResultArtifactIds(alloc, &base);
        return base;
    }

    /// Attach `_highlights` to hits that carry stored source when the request
    /// asked for them. This runs on the node that owns the stored documents;
    /// a distributed coordinator only relays what its shards computed.
    fn attachSearchHighlights(self: *DB, alloc: Allocator, req: types.SearchRequest, result: *types.SearchResult) !void {
        const options = req.highlight orelse return;
        // Deferred unit grouping carries a private revision envelope in
        // `_source`, not the document.
        if (req.defer_hierarchy_child_hydration) return;
        if (result.hits.len == 0) return;

        if (req.full_text == null and req.full_text_queries.len == 0) return;

        // `_source` may already be projected down to the requested fields (or
        // omitted entirely), so highlight from the unprojected documents in
        // that case rather than from whatever survived the projection.
        const needs_full_documents = !req.include_stored or (!req.include_all_fields and !req.defer_stored_projection);
        var sources: ?[]?[]u8 = null;
        defer if (sources) |items| freeOptionalOwnedBytes(alloc, items);
        if (needs_full_documents) {
            const keys = try alloc.alloc([]const u8, result.hits.len);
            defer alloc.free(keys);
            for (result.hits, keys) |hit, *key| key.* = hit.id;
            const loaded = try loadStoredSearchDocumentsMany(self, alloc, keys, null);
            sources = loaded;
            // Graph hydration can surface hits that live in another table;
            // their ids must not be resolved against this table's store.
            for (result.hits, loaded) |hit, *source| {
                if (hit.source_table == null) continue;
                if (source.*) |owned| alloc.free(owned);
                source.* = null;
            }
        }

        var indexed_queries = std.ArrayListUnmanaged(db_query_search.HighlightQuery).empty;
        defer indexed_queries.deinit(alloc);
        var locked_entries = std.ArrayListUnmanaged(*index_manager_mod.IndexManager.TextIndex).empty;
        defer {
            for (locked_entries.items) |entry| entry.unlockAnalysisShared();
            locked_entries.deinit(alloc);
        }
        if (req.full_text_queries.len > 0) {
            // Composed search executes named queries on their own indexes.
            for (req.full_text_queries) |named| {
                const entry = self.core.textIndexEntry(named.index_name) orelse continue;
                var already_locked = false;
                for (locked_entries.items) |locked| {
                    if (locked == entry) already_locked = true;
                }
                if (!already_locked) {
                    try locked_entries.append(alloc, entry);
                    entry.lockAnalysisShared();
                }
                try indexed_queries.append(alloc, .{
                    .query = named.query,
                    .text_analysis = entry.text_analysis,
                    .runtime_schema = entry.runtime_schema,
                });
            }
        } else if (req.full_text) |query| {
            const entry = self.core.textIndexEntry(req.primary_text_index_name orelse req.index_name) orelse
                self.core.textIndexEntry(null) orelse return;
            try locked_entries.append(alloc, entry);
            entry.lockAnalysisShared();
            try indexed_queries.append(alloc, .{
                .query = query,
                .text_analysis = entry.text_analysis,
                .runtime_schema = entry.runtime_schema,
            });
        }
        if (indexed_queries.items.len == 0) return;
        try db_query_search.attachHighlightsWithIndexQueries(
            alloc,
            options,
            indexed_queries.items,
            result.hits,
            sources,
        );
    }

    fn executeGraphMetricQueries(
        self: *DB,
        alloc: Allocator,
        queries: []const types.NamedGraphMetricQuery,
        cancellation: ?types.CancellationToken,
    ) ![]types.GraphMetricResult {
        if (queries.len == 0) return &.{};
        const results = try alloc.alloc(types.GraphMetricResult, queries.len);
        var initialized: usize = 0;
        errdefer {
            for (results[0..initialized]) |*result| result.deinit(alloc);
            alloc.free(results);
        }
        for (queries, 0..) |named, i| {
            results[i] = try self.executeGraphMetricQuery(alloc, named, cancellation);
            initialized += 1;
        }
        return results;
    }

    fn applyGraphMetricRerank(self: *DB, result: *types.SearchResult, req: types.SearchRequest) !void {
        const rerank = req.graph_metric_rerank orelse return;
        if (req.count_only) return error.UnsupportedQueryRequest;
        if (rerank.damping != null and rerank.seed_nodes.len == 0) return error.InvalidQueryRequest;
        const entry = self.core.graphIndex(rerank.index_name) orelse return error.IndexNotFound;
        const node_ids = try result.alloc.alloc([]const u8, result.hits.len);
        defer result.alloc.free(node_ids);
        for (result.hits, 0..) |hit, i| node_ids[i] = hit.id;
        var score_snapshot = if (rerank.seed_nodes.len != 0) blk: {
            // Personalized blends are computed fresh from the current edge
            // snapshot; a published generation would silently return
            // unpersonalized scores, so seeds require fresh and skip the
            // publication requirements below.
            if (rerank.freshness != .fresh) return error.GraphMetricPersonalizationRequiresFresh;
            break :blk try entry.index.personalizedPageRankScoreSnapshotAllocWithControls(
                rerank.metric_name,
                rerank.seed_nodes,
                rerank.damping,
                node_ids,
                .{ .cancellation = req.cancellation orelse .none },
            );
        } else try entry.index.graphMetricScoreSnapshotWithPolicyAlloc(rerank.metric_name, node_ids, .{
            .require_published = true,
            .require_fresh = rerank.freshness == .fresh,
        });
        defer score_snapshot.deinit(entry.index.alloc);
        if (rerank.seed_nodes.len == 0) {
            if (score_snapshot.status.published_generation == 0) return error.MetricNotReady;
            if (rerank.freshness == .fresh and score_snapshot.status.state != .fresh) return error.MetricStale;
        }

        var result_status = try cloneGraphMetricStatusFromGraph(result.alloc, score_snapshot.status);
        errdefer result_status.deinit(result.alloc);
        const selected = try graph_metric_rerank.selectPageAlloc(
            result.alloc,
            result.hits,
            score_snapshot.scores,
            .{
                .base_weight = rerank.base_weight,
                .metric_weight = rerank.weight,
                .missing_score = rerank.missing_score,
            },
            req.offset,
            req.limit,
        );
        defer result.alloc.free(selected);
        for (selected) |selection| {
            const hit = &result.hits[selection.original_index];
            var details = types.GraphMetricRerankScoreDetails{
                .index_name = try result.alloc.dupe(u8, rerank.index_name),
                .metric_name = undefined,
                .base_score = selection.base_score,
                .base_weight = rerank.base_weight,
                .metric_score = selection.metric_score,
                .metric_score_used = selection.metric_score_used,
                .metric_weight = rerank.weight,
                .missing_score_used = selection.metric_score == null,
                .final_score = selection.final_score,
                .published_generation = score_snapshot.status.published_generation,
            };
            errdefer result.alloc.free(details.index_name);
            details.metric_name = try result.alloc.dupe(u8, rerank.metric_name);
            if (hit.score_details) |*old| old.deinit(result.alloc);
            hit.score_details = details;
            hit.score = selection.final_score;
        }
        const old_hits = result.hits;
        const retained = try result.alloc.alloc(bool, old_hits.len);
        defer result.alloc.free(retained);
        const kept = try result.alloc.alloc(types.SearchHit, selected.len);
        @memset(retained, false);
        for (selected, 0..) |selection, i| {
            retained[selection.original_index] = true;
            kept[i] = old_hits[selection.original_index];
            old_hits[selection.original_index] = undefined;
        }
        for (old_hits, retained) |*hit, keep| if (!keep) hit.deinit(result.alloc);
        if (old_hits.len > 0) result.alloc.free(old_hits);
        result.hits = kept;
        if (result.graph_metric_rerank_status) |*old| old.deinit(result.alloc);
        result.graph_metric_rerank_status = result_status;
    }

    fn executeGraphMetricQuery(
        self: *DB,
        alloc: Allocator,
        named: types.NamedGraphMetricQuery,
        cancellation: ?types.CancellationToken,
    ) !types.GraphMetricResult {
        try self.requireGraphEndpointCleanupReady();
        const entry = self.core.graphIndex(named.query.index_name) orelse return error.IndexNotFound;
        if (named.query.damping != null and named.query.seed_nodes.len == 0) return error.InvalidQueryRequest;
        var metric_snapshot = if (named.query.seed_nodes.len != 0) blk: {
            // Personalized rankings are computed fresh from the current edge
            // snapshot; published generations are global-only, so seeded
            // reads against published freshness fail closed and the fresh
            // publication-state check below does not apply. The fresh
            // computation scans the filtered edge snapshot BEFORE kernel
            // admission, so it carries the request's cancellation and the
            // default scan caps (PersonalizedReadControls).
            if (named.query.freshness != .fresh) return error.GraphMetricPersonalizationRequiresFresh;
            break :blk try entry.index.personalizedPageRankTopKSnapshotAllocWithControls(
                named.query.metric_name,
                named.query.seed_nodes,
                named.query.damping,
                named.query.top_k,
                .{ .cancellation = cancellation orelse .none },
            );
        } else try entry.index.graphMetricTopKSnapshotAlloc(
            named.query.metric_name,
            named.query.top_k,
        );
        defer metric_snapshot.deinit(entry.index.alloc);
        if (named.query.seed_nodes.len == 0 and named.query.freshness == .fresh and metric_snapshot.status.state != .fresh) return error.MetricStale;

        const raw_scores = metric_snapshot.scores;
        const scores = try alloc.alloc(types.GraphMetricScore, raw_scores.len);
        var initialized_scores: usize = 0;
        errdefer {
            for (scores[0..initialized_scores]) |*score| score.deinit(alloc);
            alloc.free(scores);
        }
        for (raw_scores, 0..) |score, i| {
            scores[i] = .{ .node = try alloc.dupe(u8, score.node), .score = score.score };
            initialized_scores += 1;
        }
        const name = try alloc.dupe(u8, named.name);
        errdefer alloc.free(name);
        const index_name = try alloc.dupe(u8, named.query.index_name);
        errdefer alloc.free(index_name);
        const metric_name = try alloc.dupe(u8, named.query.metric_name);
        errdefer alloc.free(metric_name);
        var owned_status = try cloneGraphMetricStatusFromGraph(alloc, metric_snapshot.status);
        errdefer owned_status.deinit(alloc);
        return .{
            .name = name,
            .index_name = index_name,
            .metric_name = metric_name,
            .scores = scores,
            .status = owned_status,
        };
    }

    fn hierarchyChildrenInaccessibleParentResult(
        alloc: Allocator,
        req: types.SearchRequest,
    ) !types.SearchResult {
        if (req.search_after.len == 0) {
            return .{ .alloc = alloc, .hits = &.{}, .total_hits = 0, .graph_results = &.{} };
        }
        // Keep absent, expired, and authorization-hidden parents externally
        // indistinguishable. Cursor shape is still validated so callers receive
        // actionable 400 versus 409 behavior without learning whether the parent
        // exists behind their current row policy.
        if (req.search_after.len != 2 or req.search_after[0] != .string or req.search_after[1] != .string) {
            return error.InvalidQueryRequest;
        }
        _ = hierarchy_navigation.parsePosition(req.search_after[0].string) catch |err| switch (err) {
            error.HierarchyNavigationPositionVersionStale => return error.HierarchyCursorStale,
            error.InvalidHierarchyNavigationPosition => return error.InvalidQueryRequest,
        };
        return error.HierarchyCursorStale;
    }

    fn navigateHierarchyChildren(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
    ) !types.SearchResult {
        const navigation = req.hierarchy_children orelse return error.InvalidQueryRequest;
        if (navigation.parent_level != .source or navigation.level != .unit) return error.UnsupportedQueryRequest;

        const source_key = try encodeStoreLookupKeyAlloc(self, alloc, navigation.parent_id);
        defer alloc.free(source_key);
        const maybe_raw_source = try self.core.getStoreValue(alloc, source_key);
        const maybe_stored_source = if (maybe_raw_source) |raw_source| blk: {
            defer alloc.free(raw_source);
            break :blk try self.core.index_manager.materializeStoredValueAlloc(alloc, source_key, raw_source);
        } else null;
        if (maybe_stored_source == null) {
            // Distributed traversal is fanned out across table groups. Parent
            // absence on one shard only means that shard does not own the plan;
            // the outer coordinator decides whether every shard was empty.
            if (req.defer_hierarchy_child_hydration) {
                return .{ .alloc = alloc, .hits = &.{}, .total_hits = 0, .graph_results = &.{} };
            }
            return try hierarchyChildrenInaccessibleParentResult(alloc, req);
        }
        var source_hits = try alloc.alloc(types.SearchHit, 1);
        source_hits[0] = .{
            .id = try alloc.dupe(u8, navigation.parent_id),
            .stored_data = maybe_stored_source.?,
        };
        var visible_source = try db_query_result_shape.filterVisibleSearchResult(alloc, .{
            .alloc = alloc,
            .hits = source_hits,
            .total_hits = 1,
        }, .{
            .ctx = self,
            .func = isVisibleSearchHitCallback,
            .filter_many = filterVisibleSearchHitsManyCallback,
        });
        defer visible_source.deinit();
        visible_source = try db_query_result_shape.applyStoredSearchPatternFilters(alloc, req, visible_source, .{
            .ctx = self,
            .load_stored = loadStoredForHitCallback,
            .load_many_stored = loadStoredSearchDocumentManyCallback,
            .resolve_doc_set_doc_ids = resolveDocSetDocIdsCallback,
            .resolve_doc_ids_to_doc_set = resolveDocIdsToDocSetCallback,
        });
        const parent_visible = visible_source.hits.len == 1;
        if (!parent_visible) {
            return try hierarchyChildrenInaccessibleParentResult(alloc, req);
        }

        var artifacts = std.ArrayListUnmanaged(HierarchyNavigationArtifact).empty;
        defer {
            for (artifacts.items) |*artifact| artifact.deinit(alloc);
            artifacts.deinit(alloc);
        }
        // Unit payloads share the asset key prefix with their top-level
        // manifest. Scanning that prefix would materialize every page body on
        // every traversal request. The enrichment catalog is the authoritative
        // namespace list, so probe only configured document-extraction
        // manifests and read unit payloads later for the selected page.
        for (self.core.index_manager.enrichments.items, 0..) |entry, entry_index| {
            if (entry_index % hierarchy_navigation_cancel_stride == 0) try checkHierarchyNavigationCancelled(req);
            if (entry.kind != .asset) continue;
            var producer_cfg = try asset_producer_mod.parseProducerConfig(alloc, entry.producer_json);
            defer producer_cfg.deinit(alloc);
            if (producer_cfg.type != .document_extraction) continue;

            const manifest_key = try internal_keys.artifactNamedPrefixAlloc(alloc, navigation.parent_id, "asset", entry.name);
            defer alloc.free(manifest_key);
            const manifest = try self.core.getStoreValue(alloc, manifest_key) orelse continue;
            defer alloc.free(manifest);
            const manifest_info = try documentUnitHierarchyManifestInfo(alloc, manifest);
            const generation = manifest_info.published_generation orelse
                return error.StorageReadTemporarilyUnavailable;
            const state_key = try assetStateKeyAlloc(alloc, navigation.parent_id, entry.name);
            defer alloc.free(state_key);
            const summary_key = try internal_keys.documentUnitNavigationSummaryKeyAlloc(alloc, navigation.parent_id, entry.name);
            defer alloc.free(summary_key);
            const summary_raw = try self.core.getStoreValue(alloc, summary_key);
            defer if (summary_raw) |value| alloc.free(value);
            var legacy_units: ?[]DocumentExtractionUnitDescriptor = null;
            var digest: []u8 = undefined;
            var unit_count: u32 = 0;
            var block_count: u32 = 0;
            var block_size: u32 = hierarchy_navigation_block_size;
            if (summary_raw) |value| {
                const summary = try hierarchyNavigationSummaryParseAlloc(alloc, value);
                if (summary.generation != generation) {
                    alloc.free(summary.digest);
                    return error.StorageReadTemporarilyUnavailable;
                }
                // Transfer the digest allocation to the artifact descriptor;
                // Zig values have no implicit destructor, so this is a single
                // explicit ownership handoff rather than a clone.
                digest = summary.digest;
                unit_count = summary.unit_count;
                block_count = summary.block_count;
                block_size = summary.block_size;
            } else {
                const state = try self.core.getStoreValue(alloc, state_key) orelse return error.InvalidDocumentExtractionState;
                defer alloc.free(state);
                // Only state records with no navigation-era markers are
                // provably legacy. A current-format record without its summary
                // is an incomplete/corrupt publication and must fail closed;
                // synthesizing a revision from its descriptors could otherwise
                // issue cursors for a mixed artifact generation.
                if (try documentExtractionStateHasNavigationMetadata(alloc, state)) {
                    return error.StorageReadTemporarilyUnavailable;
                }
                // Rolling-upgrade fallback. A subsequent extraction writes the
                // compact summary and blocks; until then, preserve correctness
                // with the legacy state representation.
                const units = try documentExtractionStateUnitDescriptorsAlloc(alloc, state);
                errdefer freeDocumentExtractionUnitDescriptors(alloc, units);
                for (units) |unit| {
                    try validateHierarchyNavigationUnitDescriptor(alloc, navigation.parent_id, entry.name, unit);
                }
                legacy_units = units;
                digest = try hierarchyNavigationArtifactDigestAlloc(alloc, units);
                unit_count = std.math.cast(u32, units.len) orelse return error.QueryCandidateBudgetExceeded;
                block_count = hierarchyNavigationBlockCount(unit_count);
            }
            errdefer alloc.free(digest);
            try artifacts.append(alloc, .{
                .name = try alloc.dupe(u8, entry.name),
                .generation = generation,
                .digest = digest,
                .unit_count = unit_count,
                .block_count = block_count,
                .block_size = block_size,
                .legacy_units = legacy_units,
            });
        }
        std.mem.sort(HierarchyNavigationArtifact, artifacts.items, {}, hierarchyNavigationArtifactLessThan);
        if (artifacts.items.len > 1) {
            for (artifacts.items[1..], artifacts.items[0 .. artifacts.items.len - 1]) |current, previous| {
                if (std.mem.eql(u8, current.name, previous.name)) return error.InvalidDocumentExtractionState;
            }
        }
        const source_revision = try hierarchyNavigationSourceRevisionAlloc(alloc, artifacts.items);
        defer alloc.free(source_revision);

        // Validate the complete opaque position before classifying it. A
        // malformed cursor is a bad request; a well-formed cursor bound to a
        // different source hierarchy revision is an actionable conflict that
        // requires restarting traversal without search_after.
        const cursor_position: ?hierarchy_navigation.Position = if (req.search_after.len > 0)
            hierarchy_navigation.parsePosition(req.search_after[0].string) catch |err| switch (err) {
                error.HierarchyNavigationPositionVersionStale => return error.HierarchyCursorStale,
                error.InvalidHierarchyNavigationPosition => return error.InvalidQueryRequest,
            }
        else
            null;
        if (cursor_position) |cursor| {
            if (!std.mem.eql(u8, cursor.source_revision, source_revision)) return error.HierarchyCursorStale;
        }

        var units = std.ArrayListUnmanaged(types.SearchHit).empty;
        var units_owns_hits = true;
        errdefer if (units_owns_hits) {
            for (units.items) |*hit| hit.deinit(alloc);
            units.deinit(alloc);
        };
        var total_units_u64: u64 = 0;
        for (artifacts.items) |artifact| total_units_u64 += @as(u64, artifact.unit_count);
        const total = std.math.cast(u32, total_units_u64) orelse return error.QueryCandidateBudgetExceeded;

        var start_artifact_index: usize = 0;
        var start_ordinal: u64 = 0;
        var cursor_needs_validation = cursor_position != null;
        if (cursor_position) |cursor| {
            var found = false;
            for (artifacts.items, 0..) |artifact, artifact_index| {
                if (!hierarchy_navigation.encodedComponentMatches(cursor.artifact_name_hex, artifact.name)) continue;
                if (artifact.generation != cursor.generation or cursor.ordinal >= @as(u64, artifact.unit_count)) {
                    return error.InvalidQueryRequest;
                }
                start_artifact_index = artifact_index;
                start_ordinal = cursor.ordinal;
                found = true;
                break;
            }
            if (!found) return error.InvalidQueryRequest;
        }

        var remaining_offset: u64 = if (cursor_position == null) req.offset else 0;
        artifact_loop: for (artifacts.items[start_artifact_index..], start_artifact_index..) |artifact, artifact_index| {
            var ordinal: u64 = if (artifact_index == start_artifact_index) start_ordinal else 0;
            const artifact_remaining = @as(u64, artifact.unit_count) - ordinal;
            if (!cursor_needs_validation and remaining_offset >= artifact_remaining) {
                remaining_offset -= artifact_remaining;
                continue;
            }
            ordinal += remaining_offset;
            remaining_offset = 0;

            while (ordinal < @as(u64, artifact.unit_count)) {
                try checkHierarchyNavigationCancelled(req);
                const block_index: u32 = @intCast(ordinal / artifact.block_size);
                const block_start = @as(u64, block_index) * @as(u64, artifact.block_size);
                const block_units = try hierarchyNavigationArtifactBlockUnitsAlloc(
                    self,
                    alloc,
                    navigation.parent_id,
                    artifact,
                    block_index,
                );
                defer freeDocumentExtractionUnitDescriptors(alloc, block_units);
                var block_offset: usize = @intCast(ordinal - block_start);
                while (block_offset < block_units.len) : (block_offset += 1) {
                    const unit = block_units[block_offset];
                    const unit_ordinal = block_start + @as(u64, block_offset);
                    var unit_ref = (try artifact_ids.decodeArtifactRefAlloc(alloc, unit.key)) orelse
                        return error.InvalidDocumentExtractionState;
                    defer unit_ref.deinit(alloc);
                    const public_id = try artifact_ids.artifactPublicIdAlloc(alloc, unit_ref);
                    defer alloc.free(public_id);

                    if (cursor_needs_validation) {
                        const cursor = cursor_position.?;
                        if (unit_ordinal != cursor.ordinal or
                            !hierarchy_navigation.positionUnitFingerprintMatches(cursor, artifact.name, unit.fingerprint) or
                            !std.mem.eql(u8, public_id, req.search_after[1].string))
                        {
                            return error.InvalidQueryRequest;
                        }
                        cursor_needs_validation = false;
                        ordinal = unit_ordinal + 1;
                        continue;
                    }
                    if (units.items.len >= @as(usize, req.limit)) break :artifact_loop;

                    const position = try hierarchyNavigationPositionAlloc(
                        alloc,
                        source_revision,
                        artifact.name,
                        artifact.generation,
                        @intCast(unit_ordinal),
                        unit.fingerprint,
                    );
                    defer alloc.free(position);
                    var unit_hit = types.SearchHit{
                        .id = try alloc.dupe(u8, unit.key),
                        .score = 1,
                    };
                    errdefer unit_hit.deinit(alloc);
                    unit_hit.sort_values = try alloc.alloc(std.json.Value, 2);
                    unit_hit.sort_values[0] = .null;
                    unit_hit.sort_values[1] = .null;
                    unit_hit.sort_values[0] = .{ .string = try alloc.dupe(u8, position) };
                    unit_hit.sort_values[1] = .{ .string = try alloc.dupe(u8, public_id) };
                    unit_hit.artifact_ref = try unit_ref.clone(alloc);
                    try units.append(alloc, unit_hit);
                    ordinal = unit_ordinal + 1;
                }
            }
        }
        if (cursor_needs_validation) return error.InvalidQueryRequest;

        const page = try units.toOwnedSlice(alloc);
        units_owns_hits = false;
        var page_initialized: usize = 0;
        errdefer {
            for (page[0..page_initialized]) |*hit| hit.deinit(alloc);
            if (page.len > 0) alloc.free(page);
        }
        if (!req.include_stored) {
            page_initialized = page.len;
            try self.ensureHierarchyNavigationArtifactsStillPublished(
                alloc,
                navigation.parent_id,
                artifacts.items,
                req,
            );
            return .{
                .alloc = alloc,
                .hits = page,
                .total_hits = total,
                .total_hits_relation = .exact,
                .graph_results = &.{},
            };
        }
        for (page) |*hit| {
            page_initialized += 1;
            const artifact_ref = hit.artifact_ref orelse return error.InvalidDocumentExtractionState;
            const unit_id = artifact_ref.unit_id orelse return error.InvalidDocumentExtractionState;
            const unit_key = try internal_keys.documentUnitArtifactKeyAlloc(alloc, artifact_ref.document_id, artifact_ref.name, unit_id);
            defer alloc.free(unit_key);
            const stored = try self.core.getStoreValue(alloc, unit_key) orelse {
                if (req.defer_hierarchy_child_hydration) continue;
                return error.InvalidDocumentExtractionState;
            };
            defer alloc.free(stored);
            const position = hit.sort_values[0].string;
            const parsed_position = try hierarchyNavigationPositionParse(artifact_ref.name, position);
            if (!(try hierarchyNavigationStoredUnitMatchesPosition(alloc, stored, artifact_ref.name, parsed_position))) {
                return error.InvalidDocumentExtractionState;
            }
            const projected = if (req.fields.len > 0 or !req.include_all_fields)
                try projectLookupStoredBytes(self, alloc, unit_key, stored, .{
                    .fields = req.fields,
                    .include_all_fields = req.include_all_fields,
                })
            else
                try alloc.dupe(u8, stored);
            defer alloc.free(projected);
            hit.stored_data = try hierarchy_navigation.stripUnitFingerprintAlloc(alloc, projected);
        }
        // Close the read-publication race after all selected payloads are in
        // owned memory. If extraction started or completed since the initial
        // manifest read, discard the page rather than returning a hybrid.
        try self.ensureHierarchyNavigationArtifactsStillPublished(
            alloc,
            navigation.parent_id,
            artifacts.items,
            req,
        );
        return .{
            .alloc = alloc,
            .hits = page,
            .total_hits = total,
            .total_hits_relation = .exact,
            .graph_results = &.{},
        };
    }

    fn ensureHierarchyNavigationArtifactsStillPublished(
        self: *DB,
        alloc: Allocator,
        parent_id: []const u8,
        artifacts: []const HierarchyNavigationArtifact,
        req: types.SearchRequest,
    ) !void {
        for (artifacts, 0..) |artifact, i| {
            if (i % hierarchy_navigation_cancel_stride == 0) try checkHierarchyNavigationCancelled(req);
            const manifest_key = try internal_keys.artifactNamedPrefixAlloc(alloc, parent_id, "asset", artifact.name);
            defer alloc.free(manifest_key);
            const manifest = try self.core.getStoreValue(alloc, manifest_key) orelse
                return error.StorageReadTemporarilyUnavailable;
            defer alloc.free(manifest);
            const info = try documentUnitHierarchyManifestInfo(alloc, manifest);
            if (info.published_generation == null or info.published_generation.? != artifact.generation) {
                return error.StorageReadTemporarilyUnavailable;
            }
        }
    }

    /// Canonical hierarchy grouping uses a collapse-and-expand execution plan:
    /// the primary query selects the requested source-group page, and a second
    /// bounded query per returned source obtains that group's exact top
    /// matches. This prevents a source with fewer than the requested maximum
    /// from forcing the primary query to exhaust the global candidate set.
    fn populateCanonicalGroupedMatches(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
        exec_ctx: types.ExecutionContext,
        result: *types.SearchResult,
    ) anyerror!void {
        if (!req.hierarchy_grouped_matches or
            (req.return_mode != .parent_with_chunks and req.return_mode != .unit_with_chunks) or
            req.max_chunks_per_parent == 0 or
            result.hits.len == 0)
        {
            return;
        }
        for (result.hits) |*group_hit| {
            const parent_id = if (req.hierarchy_group_level == .unit)
                (group_hit.artifact_ref orelse return error.InvalidChunkArtifact).document_id
            else
                group_hit.id;
            const parent_filter = [_][]const u8{parent_id};
            const match_req = types.canonicalGroupedMatchDescendantRequest(req, &parent_filter);
            var scoped_match_req = match_req;
            const unit_filter_json = if (req.hierarchy_group_level == .unit) blk: {
                _ = group_hit.artifact_ref orelse return error.InvalidChunkArtifact;
                break :blk try hierarchyUnitMatchFilterJsonAlloc(alloc, req.filter_query_json, group_hit.id);
            } else null;
            defer if (unit_filter_json) |value| alloc.free(value);
            if (unit_filter_json) |value| scoped_match_req.filter_query_json = value;

            var matches = try self.searchLockedWithExecutionContextImpl(alloc, scoped_match_req, exec_ctx, false, null);
            defer matches.deinit();

            const nested_matches: []types.ChunkHit = if (matches.hits.len == 0)
                &.{}
            else
                try alloc.alloc(types.ChunkHit, matches.hits.len);
            var initialized: usize = 0;
            errdefer {
                for (nested_matches[0..initialized]) |*match| match.deinit(alloc);
                if (nested_matches.len > 0) alloc.free(nested_matches);
            }
            for (matches.hits, 0..) |match, i| {
                nested_matches[i] = try chunkHitFromSearchHitAlloc(alloc, match);
                initialized += 1;
            }

            for (group_hit.chunk_hits) |*match| match.deinit(alloc);
            if (group_hit.chunk_hits.len > 0) alloc.free(group_hit.chunk_hits);
            group_hit.chunk_hits = nested_matches;
        }
    }

    fn chunkHitFromSearchHitAlloc(alloc: Allocator, hit: types.SearchHit) !types.ChunkHit {
        var out = types.ChunkHit{
            .id = try alloc.dupe(u8, hit.id),
            .score = hit.score,
            .distance = hit.distance,
        };
        errdefer out.deinit(alloc);
        out.stored_data = if (hit.stored_data) |data| try alloc.dupe(u8, data) else null;
        out.ancestor_source_data = if (hit.ancestor_source_data) |data| try alloc.dupe(u8, data) else null;
        out.ancestor_unit_data = if (hit.ancestor_unit_data) |data| try alloc.dupe(u8, data) else null;
        out.artifact_ref = if (hit.artifact_ref) |artifact_ref| try artifact_ref.clone(alloc) else null;
        return out;
    }

    fn searchRequestRequiresComposedSearch(req: types.SearchRequest) bool {
        if (req.full_text_queries.len > 0 or req.dense_queries.len > 0 or req.sparse_queries.len > 0) return true;

        var base_result_sets: u32 = 0;
        if (req.full_text != null) base_result_sets += 1;
        if (req.dense != null) base_result_sets += 1;
        if (req.sparse != null) base_result_sets += 1;
        switch (req.query) {
            .dense_knn => base_result_sets += 1,
            .sparse_knn => base_result_sets += 1,
            else => {},
        }
        return base_result_sets > 1;
    }

    fn directSingleVectorRequest(req: types.SearchRequest) ?types.SearchRequest {
        if (req.merge_config != null or req.reranker != null or req.pruner != null) return null;
        if (req.full_text_queries.len != 0) return null;
        if (req.full_text) |text| switch (text) {
            .match_all => {},
            else => return null,
        };
        if (!db_query_search.isDefaultMatchAll(req.query)) return null;
        if (req.graph_queries.len != 0 or req.graph_metric_queries.len != 0 or req.expand_strategy != null) return null;
        if (req.dense != null or req.sparse != null) return null;
        if (req.dense_queries.len == 1 and req.sparse_queries.len == 0) {
            var next = req;
            next.index_name = req.dense_queries[0].index_name;
            next.full_text = null;
            next.dense = req.dense_queries[0].query;
            next.dense_queries = &.{};
            return next;
        }
        if (req.sparse_queries.len == 1 and req.dense_queries.len == 0) {
            var next = req;
            next.index_name = req.sparse_queries[0].index_name;
            next.full_text = null;
            next.sparse = req.sparse_queries[0].query;
            next.sparse_queries = &.{};
            return next;
        }
        return null;
    }

    fn searchComposed(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
        exec_ctx: types.ExecutionContext,
        dense_profile_sink: ?*db_query_search.DenseSearchProfile,
    ) !types.SearchResult {
        _ = exec_ctx;
        const metric_name = composedQueryMetricIndexName(req);
        const start_ns = platform_time.monotonicNs();
        errdefer if (db_query_search.peekLastSortRejectionDiagnostic()) |diagnostic| {
            db_query_metrics.observeSortRejection(metric_name, .search, platform_time.monotonicNs() -| start_ns, diagnostic.reason, diagnostic.detail);
        };
        const result = try db_query_search.searchComposed(alloc, req, .{
            .ctx = self,
            .resolve_structured_doc_filter = resolveStructuredDocFilterForComposedCallback,
            .resolve_structured_text_doc_filter = resolveStructuredTextDocFilterForComposedCallback,
            .search_text_query = searchTextQueryCallback,
            .search_text = searchTextComposedCallback,
            .search_dense = searchDenseComposedCallback,
            .search_dense_profiled = searchDenseComposedProfiledCallback,
            .dense_profile_sink = dense_profile_sink,
            .search_sparse = searchSparseComposedCallback,
            .clone_named_set = cloneNamedSetCallback,
            .fuse_named_sets = fuseNamedSetsCallback,
            .resolve_hits_to_doc_set = resolveSearchHitsToDocSetCallback,
            .attach_graph_results = attachGraphResultsCallback,
        });
        if (result.sort_profile != null) {
            db_query_metrics.observeSortProfile(metric_name, .search, platform_time.monotonicNs() -| start_ns, result.sort_profile);
        }
        return result;
    }

    fn composedQueryMetricIndexName(req: types.SearchRequest) ?[]const u8 {
        if (req.index_name) |name| return name;
        if (req.full_text_queries.len > 0) return req.full_text_queries[0].index_name;
        if (req.dense_queries.len > 0) return req.dense_queries[0].index_name;
        if (req.sparse_queries.len > 0) return req.sparse_queries[0].index_name;
        return null;
    }

    /// Composed (fused/hybrid) search resolves filter_text/exclusion_text and
    /// filter_query_json/exclusion_query_json exactly once, against a single
    /// shared doc-number/ordinal space, before fanning out to the text/dense/
    /// sparse arms (see `searchComposed`). Each per-arm search (searchTextQuery,
    /// searchDense) already lifts these into applyStoredSearchPatternFilters'
    /// parent-aware matcher for its OWN chunk-backed member/chunk-mode index,
    /// but a single shared resolution can never be correct for more than one
    /// doc-number space at once: whenever any arm in this composed request is
    /// chunk-backed and returns member/chunk-level hits, the clauses must be
    /// left unresolved here so each arm's own per-arm handling covers it
    /// instead (issue #931 - fused/hybrid filter_query, exclusion_query, and
    /// query.bool.filter/must_not).
    fn composedRequestTouchesChunkBackedMemberModeArm(self: *DB, alloc: Allocator, req: types.SearchRequest) !bool {
        if (req.return_mode != .member and req.return_mode != .chunk) return false;

        if (req.full_text_queries.len > 0) {
            for (req.full_text_queries) |named| {
                if (try self.core.textIndexIsChunkBacked(alloc, named.index_name)) return true;
            }
        } else if (req.full_text != null or (!db_query_search.isDefaultMatchAll(req.query) and db_query_search.isTextQuery(req.query))) {
            if (try self.core.textIndexIsChunkBacked(alloc, req.index_name)) return true;
        }

        if (req.dense_queries.len > 0) {
            for (req.dense_queries) |named| {
                if (self.core.denseIndex(named.index_name)) |entry| {
                    if (entry.chunk_name != null) return true;
                }
            }
        } else if (req.dense != null) {
            if (self.core.denseIndex(req.index_name)) |entry| {
                if (entry.chunk_name != null) return true;
            }
        }

        if (req.sparse_queries.len > 0) {
            for (req.sparse_queries) |named| {
                if (self.core.sparseIndex(named.index_name)) |entry| {
                    if (entry.chunk_name != null) return true;
                }
            }
        } else if (req.sparse != null) {
            if (self.core.sparseIndex(req.index_name)) |entry| {
                if (entry.chunk_name != null) return true;
            }
        }

        return false;
    }

    fn resolveStructuredDocFilterForComposedCallback(
        ctx: ?*anyopaque,
        alloc: Allocator,
        req: types.SearchRequest,
    ) anyerror!?doc_set.ResolvedDocFilter {
        const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
        if (try self.composedRequestTouchesChunkBackedMemberModeArm(alloc, req)) return null;
        return try db_query_search.resolveStructuredDocFilterForComposedAlloc(alloc, req, .{
            .ctx = self,
            .text_index_entry = textIndexEntryCallback,
            .resolve_doc_set_doc_ids = resolveDocSetDocIdsCallback,
            .resolve_doc_ids_to_doc_set = resolveDocIdsToDocSetCallback,
            .live_filter_doc_set = liveFilterDocSetCallback,
            .nonvisible_doc_set = nonVisibleDocSetCallback,
            .project_ordinals_to_doc_ids = false,
            .identity_read_generation = req.identity_read_generation,
        });
    }

    fn resolveStructuredTextDocFilterForComposedCallback(
        ctx: ?*anyopaque,
        alloc: Allocator,
        req: types.SearchRequest,
    ) anyerror!?db_query_search.ResolvedTextDocNumFilter {
        const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
        if (try self.composedRequestTouchesChunkBackedMemberModeArm(alloc, req)) return null;
        return try db_query_search.resolveStructuredTextDocNumFilterForComposedAlloc(alloc, req, .{
            .ctx = self,
            .text_index_entry = textIndexEntryCallback,
            .resolve_doc_set_doc_ids = resolveDocSetDocIdsCallback,
            .resolve_doc_ids_to_doc_set = resolveDocIdsToDocSetCallback,
            .live_filter_doc_set = liveFilterDocSetCallback,
            .nonvisible_doc_set = nonVisibleDocSetCallback,
            .all_docs_visible = allDocsVisibleCallback,
            .project_ordinals_to_doc_ids = false,
            .identity_read_generation = req.identity_read_generation,
        });
    }

    fn searchText(self: *DB, alloc: Allocator, req: types.SearchRequest) !types.SearchResult {
        return try db_query_search.searchText(alloc, req, .{
            .ctx = self,
            .func = searchTextQueryCallback,
        });
    }

    /// Owned filter_query_json/exclusion_query_json produced by lifting
    /// query.bool.filter/must_not (filter_text/exclusion_text) clauses out of
    /// the native per-arm query for chunk-backed member/chunk-mode search.
    /// Empty when there was nothing to lift.
    const ChunkBoolFilterLowering = struct {
        filter_query_json: ?[]u8 = null,
        exclusion_query_json: ?[]u8 = null,

        pub fn deinit(self: *ChunkBoolFilterLowering, alloc: Allocator) void {
            if (self.filter_query_json) |owned| alloc.free(owned);
            if (self.exclusion_query_json) |owned| alloc.free(owned);
        }
    };

    const ChunkBoolFilterLoweringBudget = struct {
        remaining_nodes: usize = 256,
    };

    const StoredPatternCombinator = enum { conjuncts, disjuncts };

    /// Member/chunk-mode chunk hits are a separate full-text/vector document
    /// from their parent row, so resolving `filter_text`/`exclusion_text`
    /// (query.bool.filter/must_not) against the chunk-backed index's own
    /// doc-number/ordinal space can never see a parent-only field (issue
    /// #931). Convert the clauses that `applyStoredSearchPatternFilters`'
    /// stored-pattern matcher (graph_exec.compilePatternFilter) can also
    /// express, and fold them into filter_query_json/exclusion_query_json so
    /// they reach that parent-aware matcher instead. Returns
    /// error.UnsupportedQueryRequest for a clause the stored-pattern matcher
    /// cannot represent (e.g. an analyzed `match`/`phrase`), rather than
    /// silently dropping or misapplying it.
    fn liftChunkBoolFilterClausesAlloc(
        alloc: Allocator,
        filter_text: ?types.TextQuery,
        exclusion_text: ?types.TextQuery,
        existing_filter_query_json: []const u8,
        existing_exclusion_query_json: []const u8,
    ) !ChunkBoolFilterLowering {
        var out = ChunkBoolFilterLowering{};
        errdefer out.deinit(alloc);
        if (filter_text == null and exclusion_text == null) return out;

        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const arena_alloc = arena.allocator();

        if (filter_text) |text_query| {
            var budget = ChunkBoolFilterLoweringBudget{};
            const lowered = try lowerTextQueryToStoredPatternValueAlloc(arena_alloc, text_query, 0, &budget);
            out.filter_query_json = try combineStoredPatternJsonAlloc(alloc, arena_alloc, existing_filter_query_json, lowered, .conjuncts);
        }
        if (exclusion_text) |text_query| {
            var budget = ChunkBoolFilterLoweringBudget{};
            const lowered = try lowerTextQueryToStoredPatternValueAlloc(arena_alloc, text_query, 0, &budget);
            out.exclusion_query_json = try combineStoredPatternJsonAlloc(alloc, arena_alloc, existing_exclusion_query_json, lowered, .disjuncts);
        }
        return out;
    }

    /// Combines an (optionally empty) existing stored-pattern-filter JSON
    /// string with a newly lowered node into one filter, returning an owned
    /// string allocated with `alloc`. `existing_json` is parsed with the
    /// caller's transient `arena_alloc`; only the final serialized string is
    /// durably allocated.
    fn combineStoredPatternJsonAlloc(
        alloc: Allocator,
        arena_alloc: Allocator,
        existing_json: []const u8,
        addition: std.json.Value,
        combinator: StoredPatternCombinator,
    ) ![]u8 {
        if (existing_json.len == 0) {
            return try std.json.Stringify.valueAlloc(alloc, addition, .{});
        }
        const existing = try std.json.parseFromSliceLeaky(std.json.Value, arena_alloc, existing_json, .{});
        var items = std.json.Array.init(arena_alloc);
        try items.ensureTotalCapacity(2);
        items.appendAssumeCapacity(existing);
        items.appendAssumeCapacity(addition);
        var body = std.json.ObjectMap.empty;
        try body.put(arena_alloc, switch (combinator) {
            .conjuncts => "conjuncts",
            .disjuncts => "disjuncts",
        }, .{ .array = items });
        return try std.json.Stringify.valueAlloc(alloc, std.json.Value{ .object = body }, .{});
    }

    fn storedPatternWrappedPredicate(alloc: Allocator, name: []const u8, body: std.json.Value) !std.json.Value {
        var root = std.json.ObjectMap.empty;
        try root.put(alloc, name, body);
        return .{ .object = root };
    }

    fn storedPatternEmptyPredicate(alloc: Allocator, name: []const u8) !std.json.Value {
        return storedPatternWrappedPredicate(alloc, name, .{ .object = std.json.ObjectMap.empty });
    }

    fn storedPatternJsonU64(value: u64) std.json.Value {
        if (value <= std.math.maxInt(i64)) return .{ .integer = @intCast(value) };
        // Stored-pattern date_range compares numerically; values this large
        // fall outside any representable nanosecond timestamp we accept
        // elsewhere, so this branch is unreachable in practice but kept for
        // exhaustiveness rather than risking silent truncation.
        return .{ .float = @floatFromInt(value) };
    }

    /// Lowers the subset of `TextQuery` that `graph_exec.compilePatternFilter`
    /// can also express (match_all/match_none/term/bool_field/numeric_range/
    /// date_range/doc_id, and bool_query composed of those) into the
    /// equivalent stored-pattern-filter JSON value. Analyzed/tokenized shapes
    /// (match, phrase, multi_phrase, match_phrase, multi_match_bool_prefix)
    /// and shapes the stored-pattern matcher does not yet lower this way
    /// (fuzzy, prefix, wildcard, regexp, term_range, ip_range, geo_*) return
    /// error.UnsupportedQueryRequest rather than a wrong or partial result.
    fn lowerTextQueryToStoredPatternValueAlloc(
        alloc: Allocator,
        query: types.TextQuery,
        depth: u8,
        budget: *ChunkBoolFilterLoweringBudget,
    ) anyerror!std.json.Value {
        if (depth > 16 or budget.remaining_nodes == 0) return error.UnsupportedQueryRequest;
        budget.remaining_nodes -= 1;
        return switch (query) {
            .match_all => try storedPatternEmptyPredicate(alloc, "match_all"),
            .match_none => try storedPatternEmptyPredicate(alloc, "match_none"),
            .term => |term| blk: {
                var body = std.json.ObjectMap.empty;
                try body.put(alloc, term.field, .{ .string = term.term });
                break :blk try storedPatternWrappedPredicate(alloc, "term", .{ .object = body });
            },
            .bool_field => |bool_field| blk: {
                var body = std.json.ObjectMap.empty;
                try body.put(alloc, "field", .{ .string = bool_field.field });
                try body.put(alloc, "value", .{ .bool = bool_field.value });
                break :blk try storedPatternWrappedPredicate(alloc, "bool_field", .{ .object = body });
            },
            .numeric_range => |range| blk: {
                if (range.min == null and range.max == null) return error.UnsupportedQueryRequest;
                var body = std.json.ObjectMap.empty;
                try body.put(alloc, "field", .{ .string = range.field });
                if (range.min) |bound| try body.put(alloc, "min", .{ .float = bound });
                if (range.max) |bound| try body.put(alloc, "max", .{ .float = bound });
                try body.put(alloc, "inclusive_min", .{ .bool = range.inclusive_min });
                try body.put(alloc, "inclusive_max", .{ .bool = range.inclusive_max });
                break :blk try storedPatternWrappedPredicate(alloc, "numeric_range", .{ .object = body });
            },
            .date_range => |range| blk: {
                if (range.start_ns == null and range.end_ns == null) return error.UnsupportedQueryRequest;
                var body = std.json.ObjectMap.empty;
                try body.put(alloc, "field", .{ .string = range.field });
                if (range.start_ns) |ns| try body.put(alloc, "start_ns", storedPatternJsonU64(ns));
                if (range.end_ns) |ns| try body.put(alloc, "end_ns", storedPatternJsonU64(ns));
                try body.put(alloc, "inclusive_start", .{ .bool = range.inclusive_start });
                try body.put(alloc, "inclusive_end", .{ .bool = range.inclusive_end });
                break :blk try storedPatternWrappedPredicate(alloc, "date_range", .{ .object = body });
            },
            .doc_id => |doc_id| blk: {
                if (doc_id.ids.len == 0) return error.UnsupportedQueryRequest;
                var ids = std.json.Array.init(alloc);
                try ids.ensureTotalCapacity(doc_id.ids.len);
                for (doc_id.ids) |id| ids.appendAssumeCapacity(.{ .string = id });
                break :blk try storedPatternWrappedPredicate(alloc, "doc_id", .{ .array = ids });
            },
            .bool_query => |bool_query| blk: {
                if (bool_query.must.len == 0 and bool_query.should.len == 0 and bool_query.must_not.len == 0) {
                    return error.UnsupportedQueryRequest;
                }
                var body = std.json.ObjectMap.empty;
                // A pure, explicitly-optional should-disjunction has no
                // must/filter clause to anchor it; the stored-pattern bool
                // contract always floors a pure should to a minimum of one
                // match, so make the match-all requirement explicit instead
                // of weakening that shared invariant.
                const needs_optional_anchor = bool_query.pure_should_optional and bool_query.must.len == 0;
                if (bool_query.must.len > 0 or needs_optional_anchor) {
                    var must = std.json.Array.init(alloc);
                    try must.ensureTotalCapacity(bool_query.must.len + @as(usize, if (needs_optional_anchor) 1 else 0));
                    if (needs_optional_anchor) must.appendAssumeCapacity(try storedPatternEmptyPredicate(alloc, "match_all"));
                    for (bool_query.must) |child| {
                        must.appendAssumeCapacity(try lowerTextQueryToStoredPatternValueAlloc(alloc, child, depth + 1, budget));
                    }
                    try body.put(alloc, "must", .{ .array = must });
                }
                if (bool_query.should.len > 0) {
                    var should = std.json.Array.init(alloc);
                    try should.ensureTotalCapacity(bool_query.should.len);
                    for (bool_query.should) |child| {
                        should.appendAssumeCapacity(try lowerTextQueryToStoredPatternValueAlloc(alloc, child, depth + 1, budget));
                    }
                    try body.put(alloc, "should", .{ .array = should });
                    if (bool_query.min_should > 0) {
                        try body.put(alloc, "minimum_should_match", .{ .integer = bool_query.min_should });
                    }
                }
                if (bool_query.must_not.len > 0) {
                    var must_not = std.json.Array.init(alloc);
                    try must_not.ensureTotalCapacity(bool_query.must_not.len);
                    for (bool_query.must_not) |child| {
                        must_not.appendAssumeCapacity(try lowerTextQueryToStoredPatternValueAlloc(alloc, child, depth + 1, budget));
                    }
                    try body.put(alloc, "must_not", .{ .array = must_not });
                }
                break :blk try storedPatternWrappedPredicate(alloc, "bool", .{ .object = body });
            },
            else => error.UnsupportedQueryRequest,
        };
    }

    fn searchTextQuery(self: *DB, alloc: Allocator, req: types.SearchRequest, text_query: types.TextQuery) !types.SearchResult {
        const needs_algebraic_doc_filter = req.doc_filter_bindings.len > 0 or req.require_algebraic_filter_resolution;
        var algebraic_filter = if (needs_algebraic_doc_filter)
            try self.searchRequestWithAlgebraicDocFilterAlloc(req)
        else
            AlgebraicDocFilterRequest{ .req = req };
        defer algebraic_filter.deinit();
        var execution_req = algebraic_filter.req;
        // Chunk members are separate full-text documents from their parent
        // row and have their own doc numbers, so resolving filter_query/
        // exclusion_query into parent-row doc-number sets here can never
        // match a chunk (positive clause: 0 hits) or exclude one (negative
        // clause: no effect). Leave the JSON filters unresolved for
        // chunk-backed member/chunk-mode text queries so they survive into
        // applyStoredSearchPatternFilters, which matches them against the
        // resolved parent row instead (issue #931).
        const chunk_backed_for_filter = try self.core.textIndexIsChunkBacked(alloc, execution_req.index_name);
        const member_mode_for_filter = execution_req.return_mode == .member or execution_req.return_mode == .chunk;
        const suppress_text_doc_num_filter = chunk_backed_for_filter and member_mode_for_filter;
        var lifted_bool_filter = ChunkBoolFilterLowering{};
        defer lifted_bool_filter.deinit(alloc);
        if (suppress_text_doc_num_filter) {
            // Discard the composed-search doc-number/ordinal resolution a
            // shared filter step may already have attached upstream
            // (searchComposed resolves these unconditionally before
            // dispatching to per-arm searches); it would be just as wrong
            // here. resolved_doc_filter -- the generic doc-identity form
            // filter_prefix resolves into (searchRequestWithIdentityPrefixFilterAlloc)
            // -- is left intact: db_query_search.searchTextQuery itself
            // skips using it natively for a chunk-backed member/chunk-mode
            // query and instead carries it through to
            // applyStoredSearchPatternFilters' parent-aware matcher.
            execution_req.resolved_text_doc_filter = null;
            // query.bool.filter/must_not (native TextQuery filter_text/
            // exclusion_text) are resolved the same wrong way: against the
            // chunk-backed index's own doc-number/ordinal space, which never
            // covers a parent-only field. Lift representable clauses into
            // filter_query_json/exclusion_query_json instead, so they reach
            // applyStoredSearchPatternFilters' parent-aware matcher (issue
            // #931). Unrepresentable shapes fail closed with a clear error
            // rather than silently matching nothing or everything.
            lifted_bool_filter = try liftChunkBoolFilterClausesAlloc(
                alloc,
                execution_req.filter_text,
                execution_req.exclusion_text,
                execution_req.filter_query_json,
                execution_req.exclusion_query_json,
            );
            if (lifted_bool_filter.filter_query_json) |json| execution_req.filter_query_json = json;
            if (lifted_bool_filter.exclusion_query_json) |json| execution_req.exclusion_query_json = json;
            if (execution_req.filter_text != null) execution_req.filter_text = null;
            if (execution_req.exclusion_text != null) execution_req.exclusion_text = null;
        }
        const maybe_resolved_text_filter = if (suppress_text_doc_num_filter)
            null
        else
            try db_query_search.resolveStructuredTextDocNumFilterForComposedAlloc(alloc, execution_req, .{
                .ctx = self,
                .text_index_entry = textIndexEntryCallback,
                .resolve_doc_set_doc_ids = resolveDocSetDocIdsCallback,
                .resolve_doc_ids_to_doc_set = resolveDocIdsToDocSetCallback,
                .live_filter_doc_set = liveFilterDocSetCallback,
                .all_docs_visible = allDocsVisibleCallback,
                .project_ordinals_to_doc_ids = false,
                .identity_read_generation = execution_req.identity_read_generation,
            });
        var resolved_text_filter_storage: db_query_search.ResolvedTextDocNumFilter = undefined;
        var has_resolved_text_filter = false;
        defer {
            if (has_resolved_text_filter) resolved_text_filter_storage.deinit(alloc);
        }
        if (maybe_resolved_text_filter) |filter| {
            resolved_text_filter_storage = filter;
            has_resolved_text_filter = true;
            execution_req.resolved_text_doc_filter = &resolved_text_filter_storage;
            execution_req.filter_query_json = "";
            execution_req.exclusion_query_json = "";
        }
        try self.proveTextQueryAccessPaths(execution_req.index_name, text_query);
        const metric_name = self.textQueryMetricIndexName(execution_req);
        const start_ns = platform_time.monotonicNs();
        errdefer observeSearchFailureMetric(metric_name, .search, platform_time.monotonicNs() -| start_ns);
        const result = try db_query_search.searchTextQuery(alloc, execution_req, text_query, .{
            .filter_candidate_presence = true,
            .ctx = self,
            .text_index_entry = textIndexEntryCallback,
            .text_index_is_chunk_backed = textIndexIsChunkBackedCallback,
            .text_index_supports_unit_grouping = textIndexSupportsUnitGroupingCallback,
            .search_match_all = searchMatchAllCallback,
            .project_stored_search = projectStoredBytesForSearchCallback,
            .load_stored = loadStoredSearchDocumentCallback,
            .load_projected_documents = loadProjectedSearchDocumentManyCallback,
            .is_expired_key = isNonvisibleStoredSearchKeyCallback,
            .resolve_doc_set_doc_ids = resolveDocSetDocIdsCallback,
            .resolve_doc_ids_to_doc_set = resolveDocIdsToDocSetCallback,
            .live_filter_doc_set = liveFilterDocSetCallback,
            .all_docs_visible = allDocsVisibleCallback,
            .requires_full_candidate_visibility_filter = requiresFullCandidateVisibilityFilterCallback,
            .nonvisible_doc_set = nonVisibleDocSetCallback,
            .postprocess = postprocessTextSearchResultCallback,
        });
        db_query_metrics.observeSortProfile(metric_name, .search, platform_time.monotonicNs() -| start_ns, result.sort_profile);
        return result;
    }

    fn proveTextQueryAccessPaths(self: *DB, index_name: ?[]const u8, text_query: types.TextQuery) !void {
        switch (text_query) {
            .term => |term| try self.proveTextFieldAccessPath(index_name, term.field, null, .slice),
            .match => |match| try self.proveTextFieldAccessPath(index_name, match.field, match.analyzer, .slice),
            .multi_match_bool_prefix => |multi_match| {
                for (multi_match.fields) |field| try self.proveMultiMatchBoolPrefixAccessPaths(index_name, field.field);
            },
            .prefix => |prefix| try self.proveTextFieldAccessPath(index_name, prefix.field, null, .automaton_select),
            .wildcard => |wildcard| try self.proveTextFieldAccessPath(index_name, wildcard.field, null, .automaton_select),
            .regexp => |regexp| try self.proveTextFieldAccessPath(index_name, regexp.field, null, .automaton_select),
            .fuzzy => |fuzzy| try self.proveTextFieldAccessPath(index_name, fuzzy.field, null, .automaton_select),
            .bool_query => |bool_query| {
                for (bool_query.must) |child| try self.proveTextQueryAccessPaths(index_name, child);
                for (bool_query.should) |child| try self.proveTextQueryAccessPaths(index_name, child);
                for (bool_query.must_not) |child| try self.proveTextQueryAccessPaths(index_name, child);
            },
            else => {},
        }
    }

    fn proveTextFieldAccessPath(self: *DB, index_name: ?[]const u8, field: []const u8, analyzer: ?[]const u8, fragment: algebraic_mod.ir.TensorFragment) !void {
        _ = try self.core.index_manager.planFullTextLexicalAccessPathAlloc(self.alloc, index_name, field, analyzer, fragment) orelse return error.IndexNotFound;
    }

    fn proveOptionalTextFieldAccessPath(self: *DB, index_name: ?[]const u8, field: []const u8, fragment: algebraic_mod.ir.TensorFragment) !bool {
        const plan = try self.core.index_manager.planFullTextLexicalAccessPathAlloc(self.alloc, index_name, field, null, fragment);
        return plan != null;
    }

    fn proveMultiMatchBoolPrefixAccessPaths(self: *DB, index_name: ?[]const u8, field: []const u8) !void {
        if (std.mem.endsWith(u8, field, "._index_prefix")) {
            try self.proveTextFieldAccessPath(index_name, field, null, .slice);
            return;
        }

        try self.proveTextFieldAccessPath(index_name, field, null, .slice);
        try self.proveTextFieldAccessPath(index_name, field, null, .automaton_select);
        if (isSearchAsYouTypeGeneratedFieldName(field)) return;

        const two_gram = try std.fmt.allocPrint(self.alloc, "{s}._2gram", .{field});
        defer self.alloc.free(two_gram);
        const has_two_gram = try self.proveOptionalTextFieldAccessPath(index_name, two_gram, .slice);
        if (has_two_gram) _ = try self.proveOptionalTextFieldAccessPath(index_name, two_gram, .automaton_select);

        const three_gram = try std.fmt.allocPrint(self.alloc, "{s}._3gram", .{field});
        defer self.alloc.free(three_gram);
        const has_three_gram = try self.proveOptionalTextFieldAccessPath(index_name, three_gram, .slice);
        if (has_three_gram) _ = try self.proveOptionalTextFieldAccessPath(index_name, three_gram, .automaton_select);

        const index_prefix = try std.fmt.allocPrint(self.alloc, "{s}._index_prefix", .{field});
        defer self.alloc.free(index_prefix);
        _ = try self.proveOptionalTextFieldAccessPath(index_name, index_prefix, .slice);
    }

    fn isSearchAsYouTypeGeneratedFieldName(field: []const u8) bool {
        return std.mem.endsWith(u8, field, "._2gram") or
            std.mem.endsWith(u8, field, "._3gram") or
            std.mem.endsWith(u8, field, "._index_prefix");
    }

    fn textQueryMetricIndexName(self: *DB, req: types.SearchRequest) ?[]const u8 {
        if (req.index_name) |name| return name;
        const entry = self.core.textIndexEntry(null) orelse return null;
        return entry.config.name;
    }

