    fn proveVectorSearchAccessPath(self: *DB, index_name: ?[]const u8, layout: algebraic_mod.ir.PhysicalLayout, constrained: bool) !void {
        const selected_path = switch (layout) {
            .dense_vector => self.core.index_manager.denseVectorAccessPath(index_name),
            .sparse_vector => self.core.index_manager.sparseVectorAccessPath(index_name),
            else => null,
        };
        const access_path = selected_path orelse {
            try self.failIfIndexQuarantined(index_name);
            return error.IndexNotFound;
        };
        var planned = (try algebraic_mod.planner.planVectorSearchTensorProgramAlloc(self.alloc, access_path.owner, layout, constrained)) orelse return error.InvalidIndexConfig;
        defer planned.deinit(self.alloc);
        if (planned.access_paths.len != 1 or
            planned.access_paths[0].layout != layout or
            !std.mem.eql(u8, planned.access_paths[0].owner, access_path.owner) or
            !std.mem.eql(algebraic_mod.ir.Dimension, planned.access_paths[0].output_dims, access_path.output_dims))
        {
            return error.InvalidIndexConfig;
        }
        if (!algebraic_mod.ir.vectorSearchProgramMatchesTarget(planned.asProgram(), access_path.owner, layout, constrained)) return error.InvalidIndexConfig;
    }

    fn hasNativeDocIdConstraints(req: types.SearchRequest) bool {
        return req.filter_doc_ids_positive or
            req.filter_doc_ids.len > 0 or
            req.exclude_doc_ids.len > 0 or
            req.resolved_doc_filter != null or
            req.doc_filter_bindings.len > 0;
    }

    const IdentityPrefixFilterRequest = struct {
        req: types.SearchRequest,
        resolved_doc_filter: ?*doc_set.ResolvedDocFilter = null,
        alloc: ?Allocator = null,

        pub fn deinit(self: *@This()) void {
            if (self.resolved_doc_filter) |filter| {
                const alloc = self.alloc.?;
                filter.deinit(alloc);
                alloc.destroy(filter);
            }
            self.* = undefined;
        }
    };

    /// Resolve document-key prefixes once, before composed search fans out to
    /// dense, sparse, and full-text lanes. Artifact-backed indexes use encoded
    /// member identities internally, so forwarding the raw prefix to a physical
    /// backend is both incorrect and inconsistent across index kinds.
    fn searchRequestWithIdentityPrefixFilterAlloc(self: *DB, req: types.SearchRequest) !IdentityPrefixFilterRequest {
        if (req.filter_prefix.len == 0) return .{ .req = req };

        var filter = if (req.resolved_doc_filter) |ptr|
            try self.normalizeResolvedDocFilterDocKeysNoLockAtGenerationAlloc(
                self.alloc,
                @ptrCast(@alignCast(ptr)),
                req.identity_read_generation,
            )
        else
            doc_set.ResolvedDocFilter{};
        errdefer filter.deinit(self.alloc);

        switch (filter.include) {
            // A partial-coverage identity set cannot be intersected with
            // ordinals. Filtering its canonical document keys directly
            // preserves prefix semantics while allowing downstream projection
            // to use its normal fallback behavior.
            .doc_keys => |keys| {
                var matching = std.ArrayListUnmanaged([]const u8).empty;
                defer matching.deinit(self.alloc);
                for (keys) |key| {
                    if (std.mem.startsWith(u8, key, req.filter_prefix)) try matching.append(self.alloc, key);
                }
                const include = try doc_set.cloneDocKeysAlloc(self.alloc, matching.items);
                filter.include.deinit(self.alloc);
                filter.include = include;
            },
            else => {
                var prefix_set = try doc_identity.visibleDocSetForPrefixFromStoreAlloc(
                    self.alloc,
                    self.core.store,
                    req.filter_prefix,
                    req.identity_read_generation,
                );
                defer prefix_set.deinit(self.alloc);
                const include = (try doc_set.intersectAlloc(self.alloc, &filter.include, &prefix_set)) orelse
                    return error.InvalidDocIdentity;
                filter.include.deinit(self.alloc);
                filter.include = include;
            },
        }

        const resolved_filter = try self.alloc.create(doc_set.ResolvedDocFilter);
        errdefer self.alloc.destroy(resolved_filter);
        resolved_filter.* = filter;
        filter = .{};

        var next = req;
        next.filter_prefix = "";
        next.resolved_doc_filter = resolved_filter;
        next.resolved_doc_filter_owned = false;
        return .{
            .req = next,
            .resolved_doc_filter = resolved_filter,
            .alloc = self.alloc,
        };
    }

    const AlgebraicDocFilterRequest = struct {
        req: types.SearchRequest,
        index: ?*@import("algebraic/index.zig").Index = null,
        filter_doc_ids: [][]u8 = &.{},
        exclude_doc_ids: [][]u8 = &.{},
        resolved_doc_filter: ?*doc_set.ResolvedDocFilter = null,
        resolved_doc_filter_alloc: ?Allocator = null,

        pub fn deinit(self: *@This()) void {
            if (self.index) |index| {
                index.freeDocIds(self.filter_doc_ids);
                index.freeDocIds(self.exclude_doc_ids);
            }
            if (self.resolved_doc_filter) |filter| {
                const alloc = self.resolved_doc_filter_alloc.?;
                filter.deinit(alloc);
                alloc.destroy(filter);
            }
            self.* = undefined;
        }
    };

    fn searchRequestWithAlgebraicDocFilterAlloc(self: *DB, req: types.SearchRequest) !AlgebraicDocFilterRequest {
        if (req.filter_query_json.len == 0 and req.exclusion_query_json.len == 0) return .{ .req = req };
        // `_id` is the primary identity access path, not a user-provisioned
        // secondary index. Resolve a closed ID union directly even for callers
        // that require exact native resolution (notably canonical MATCH anchor
        // scans). This keeps bounded point-source queries exact on every table
        // while arbitrary predicates still fail closed without index coverage.
        if (req.doc_filter_bindings.len == 0 and
            req.filter_query_json.len > 0 and
            req.exclusion_query_json.len == 0)
        {
            if (try db_query_search.exactStructuredFilterDocIdsAlloc(self.alloc, req.filter_query_json)) |doc_ids| {
                defer freeConstDocIds(self.alloc, doc_ids);
                const resolved_filter = try self.alloc.create(doc_set.ResolvedDocFilter);
                errdefer self.alloc.destroy(resolved_filter);
                resolved_filter.* = try self.resolvedDocFilterForIdsAlloc(true, doc_ids, &.{}, req.identity_read_generation);
                errdefer resolved_filter.deinit(self.alloc);
                var next = req;
                next.filter_query_json = "";
                next.resolved_doc_filter = resolved_filter;
                return .{
                    .req = next,
                    .resolved_doc_filter = resolved_filter,
                    .resolved_doc_filter_alloc = self.alloc,
                };
            }
        }
        if (!req.require_algebraic_filter_resolution and req.doc_filter_bindings.len == 0) {
            if (try self.searchRequestWithDynamicStructuredDocFilterAlloc(req)) |direct| return direct;
        }
        const entry = self.core.index_manager.algebraicIndex(null) orelse {
            self.recordUnsupportedDocSetFilterShape();
            if (req.require_algebraic_filter_resolution) return error.UnsupportedQueryRequest;
            return .{ .req = req };
        };
        entry.index.recordVectorFilterAttempt();
        if (entry.index.hasErrors() or !entry.index.plannerLifecycleReady()) {
            entry.index.recordVectorFilterUnsupported(req.require_algebraic_filter_resolution);
            self.recordUnsupportedDocSetFilterShape();
            if (req.require_algebraic_filter_resolution) return error.UnsupportedQueryRequest;
            return .{ .req = req };
        }
        if (try self.searchRequestWithDirectAlgebraicDocFilterAlloc(req, entry.index)) |direct| return direct;
        var filter_doc_ids: [][]u8 = &.{};
        errdefer entry.index.freeDocIds(filter_doc_ids);
        var exclude_doc_ids: [][]u8 = &.{};
        errdefer entry.index.freeDocIds(exclude_doc_ids);
        var changed = false;
        var filter_json_resolved = false;
        var exclusion_json_resolved = false;
        var filter_supported = req.filter_doc_ids_positive or req.filter_doc_ids.len > 0;
        var filter_bindings = std.ArrayListUnmanaged(@import("algebraic/index.zig").Index.FilterBinding).empty;
        defer {
            for (filter_bindings.items) |*binding| binding.set.deinit(entry.index);
            filter_bindings.deinit(entry.index.alloc);
        }

        if (filter_supported) filter_doc_ids = try dupeAlgebraicDocIds(entry.index.alloc, req.filter_doc_ids);
        if (req.exclude_doc_ids.len > 0) exclude_doc_ids = try dupeAlgebraicDocIds(entry.index.alloc, req.exclude_doc_ids);

        for (req.doc_filter_bindings) |binding| {
            if (binding.name.len == 0 or binding.filter_query_json.len == 0) return error.InvalidArgument;
            for (filter_bindings.items) |existing| {
                if (std.mem.eql(u8, existing.name, binding.name)) return error.InvalidArgument;
            }
            var set = (try entry.index.docIdSetForFilterJsonWithBindingsAlloc(
                self.core.store,
                binding.filter_query_json,
                filter_bindings.items,
            )) orelse {
                entry.index.recordVectorFilterUnsupported(req.require_algebraic_filter_resolution);
                self.recordUnsupportedDocSetFilterShape();
                if (req.require_algebraic_filter_resolution) return error.UnsupportedQueryRequest;
                return .{ .req = req };
            };
            errdefer set.deinit(entry.index);
            try filter_bindings.append(entry.index.alloc, .{
                .name = binding.name,
                .set = set,
            });
            set = .{};
        }

        if (req.filter_query_json.len > 0) {
            if (try entry.index.docIdSetForFilterJsonWithBindingsAlloc(self.core.store, req.filter_query_json, filter_bindings.items)) |set| {
                var owned_set = set;
                defer owned_set.deinit(entry.index);
                if (owned_set.include) |ids| {
                    if (filter_supported) {
                        const intersected = try intersectAlgebraicDocIds(entry.index.alloc, filter_doc_ids, ids);
                        entry.index.freeDocIds(filter_doc_ids);
                        filter_doc_ids = intersected;
                    } else {
                        filter_doc_ids = try dupeAlgebraicDocIds(entry.index.alloc, ids);
                    }
                    filter_supported = true;
                    changed = true;
                }
                if (owned_set.exclude.len > 0) {
                    const merged = try unionAlgebraicDocIds(entry.index.alloc, exclude_doc_ids, owned_set.exclude);
                    entry.index.freeDocIds(exclude_doc_ids);
                    exclude_doc_ids = merged;
                    changed = true;
                }
                filter_json_resolved = true;
            }
        }
        if (req.exclusion_query_json.len > 0) {
            if (try entry.index.docIdSetForFilterJsonWithBindingsAlloc(self.core.store, req.exclusion_query_json, filter_bindings.items)) |set| {
                var owned_set = set;
                defer owned_set.deinit(entry.index);
                if (owned_set.include) |ids| {
                    const merged = try unionAlgebraicDocIds(entry.index.alloc, exclude_doc_ids, ids);
                    entry.index.freeDocIds(exclude_doc_ids);
                    exclude_doc_ids = merged;
                    changed = true;
                }
                if (owned_set.exclude.len > 0) {
                    const merged = try unionAlgebraicDocIds(entry.index.alloc, exclude_doc_ids, owned_set.exclude);
                    entry.index.freeDocIds(exclude_doc_ids);
                    exclude_doc_ids = merged;
                    changed = true;
                }
                exclusion_json_resolved = true;
            }
        }
        if (!changed) {
            entry.index.recordVectorFilterUnsupported(req.require_algebraic_filter_resolution);
            self.recordUnsupportedDocSetFilterShape();
            if (req.require_algebraic_filter_resolution) return error.UnsupportedQueryRequest;
            return .{ .req = req };
        }

        var next = req;
        if (filter_supported) {
            next.filter_doc_ids = filter_doc_ids;
            next.filter_doc_ids_positive = true;
        }
        if (exclude_doc_ids.len > 0) next.exclude_doc_ids = exclude_doc_ids;
        if (filter_json_resolved) next.filter_query_json = "";
        if (exclusion_json_resolved) next.exclusion_query_json = "";
        if (filter_bindings.items.len > 0) next.doc_filter_bindings = &.{};
        if (next.require_algebraic_filter_resolution and (next.filter_query_json.len > 0 or next.exclusion_query_json.len > 0)) {
            entry.index.recordVectorFilterUnsupported(true);
            self.recordUnsupportedDocSetFilterShape();
            return error.UnsupportedQueryRequest;
        }
        const resolved_filter = try self.alloc.create(doc_set.ResolvedDocFilter);
        errdefer self.alloc.destroy(resolved_filter);
        resolved_filter.* = try self.resolvedDocFilterForIdsAlloc(filter_supported, filter_doc_ids, exclude_doc_ids, req.identity_read_generation);
        errdefer resolved_filter.deinit(self.alloc);
        next.resolved_doc_filter = resolved_filter;
        entry.index.recordVectorFilterResolved(filter_doc_ids.len, exclude_doc_ids.len);
        return .{
            .req = next,
            .index = entry.index,
            .filter_doc_ids = filter_doc_ids,
            .exclude_doc_ids = exclude_doc_ids,
            .resolved_doc_filter = resolved_filter,
            .resolved_doc_filter_alloc = self.alloc,
        };
    }

    fn searchRequestWithDynamicStructuredDocFilterAlloc(self: *DB, req: types.SearchRequest) !?AlgebraicDocFilterRequest {
        var resolved = (try db_query_search.resolveStructuredDocFilterForComposedAlloc(self.alloc, req, .{
            .ctx = self,
            .text_index_entry = textIndexEntryCallback,
            .resolve_doc_set_doc_ids = resolveDocSetDocIdsCallback,
            .resolve_doc_ids_to_doc_set = resolveDocIdsToDocSetCallback,
            .live_filter_doc_set = liveFilterDocSetCallback,
            .nonvisible_doc_set = nonVisibleDocSetCallback,
            .project_ordinals_to_doc_ids = false,
            .identity_read_generation = req.identity_read_generation,
        })) orelse return null;
        errdefer resolved.deinit(self.alloc);

        const resolved_filter = try self.alloc.create(doc_set.ResolvedDocFilter);
        errdefer self.alloc.destroy(resolved_filter);
        resolved_filter.* = resolved;
        resolved = .{};

        var next = req;
        next.resolved_doc_filter = resolved_filter;
        next.filter_text = null;
        next.exclusion_text = null;
        next.filter_query_json = "";
        next.exclusion_query_json = "";
        return .{
            .req = next,
            .resolved_doc_filter = resolved_filter,
            .resolved_doc_filter_alloc = self.alloc,
        };
    }

    fn searchRequestWithDirectAlgebraicDocFilterAlloc(self: *DB, req: types.SearchRequest, index: *@import("algebraic/index.zig").Index) !?AlgebraicDocFilterRequest {
        // Search requests are normalized to the current identity generation before
        // reaching this path. Algebraic ordinal postings represent the current
        // live row set, so using them directly avoids a broad identity-state scan
        // before every vector filter query.
        const algebraic_filter_rows_are_visible = true;
        var resolved_bindings = std.ArrayListUnmanaged(@import("algebraic/index.zig").Index.ResolvedFilterBinding).empty;
        defer {
            for (resolved_bindings.items) |*binding| binding.filter.deinit(index.alloc);
            resolved_bindings.deinit(index.alloc);
        }
        for (req.doc_filter_bindings) |binding| {
            if (binding.name.len == 0 or binding.filter_query_json.len == 0) return error.InvalidArgument;
            for (resolved_bindings.items) |existing| {
                if (std.mem.eql(u8, existing.name, binding.name)) return error.InvalidArgument;
            }
            var binding_filter = (if (algebraic_filter_rows_are_visible)
                try index.resolvedDocFilterForFilterJsonUncheckedAlloc(
                    self.core.store,
                    binding.filter_query_json,
                    resolved_bindings.items,
                )
            else
                try index.resolvedDocFilterForFilterJsonWithBindingsAtGenerationAlloc(
                    self.core.store,
                    binding.filter_query_json,
                    req.identity_read_generation,
                    resolved_bindings.items,
                )) orelse return null;
            errdefer binding_filter.deinit(index.alloc);
            try resolved_bindings.append(index.alloc, .{
                .name = binding.name,
                .filter = binding_filter,
            });
            binding_filter = .{};
        }

        var filter = doc_set.ResolvedDocFilter{};
        errdefer filter.deinit(index.alloc);
        var changed = false;
        var request_constraints_resolved = false;
        var filter_json_resolved = false;
        var exclusion_json_resolved = false;

        if (try self.resolvedDocFilterForRequestNativeConstraintsAlloc(index.alloc, req)) |initial| {
            filter = initial;
            changed = true;
            request_constraints_resolved = true;
        }

        if (req.filter_query_json.len > 0) {
            var query_filter = (if (algebraic_filter_rows_are_visible)
                try index.resolvedDocFilterForFilterJsonUncheckedAlloc(
                    self.core.store,
                    req.filter_query_json,
                    resolved_bindings.items,
                )
            else if (resolved_bindings.items.len > 0)
                try index.resolvedDocFilterForFilterJsonWithBindingsAtGenerationAlloc(
                    self.core.store,
                    req.filter_query_json,
                    req.identity_read_generation,
                    resolved_bindings.items,
                )
            else
                try index.resolvedDocFilterForFilterJsonAtGenerationAlloc(self.core.store, req.filter_query_json, req.identity_read_generation)) orelse {
                filter.deinit(index.alloc);
                return null;
            };
            defer query_filter.deinit(index.alloc);
            if (!(try applyResolvedFilterIncludeAlloc(index.alloc, &filter, &query_filter))) {
                filter.deinit(index.alloc);
                return null;
            }
            changed = true;
            filter_json_resolved = true;
        }
        if (req.exclusion_query_json.len > 0) {
            var exclusion = (if (algebraic_filter_rows_are_visible)
                try index.resolvedDocFilterForFilterJsonUncheckedAlloc(
                    self.core.store,
                    req.exclusion_query_json,
                    resolved_bindings.items,
                )
            else if (resolved_bindings.items.len > 0)
                try index.resolvedDocFilterForFilterJsonWithBindingsAtGenerationAlloc(
                    self.core.store,
                    req.exclusion_query_json,
                    req.identity_read_generation,
                    resolved_bindings.items,
                )
            else
                try index.resolvedDocFilterForFilterJsonAtGenerationAlloc(self.core.store, req.exclusion_query_json, req.identity_read_generation)) orelse {
                filter.deinit(index.alloc);
                return null;
            };
            defer exclusion.deinit(index.alloc);

            if (!(try unionResolvedFilterExcludeAlloc(index.alloc, &filter, &exclusion.include))) {
                filter.deinit(index.alloc);
                return null;
            }
            if (!(try unionResolvedFilterExcludeAlloc(index.alloc, &filter, &exclusion.exclude))) {
                filter.deinit(index.alloc);
                return null;
            }
            changed = true;
            exclusion_json_resolved = true;
        }
        if (!changed) return null;

        const resolved_filter = try index.alloc.create(doc_set.ResolvedDocFilter);
        errdefer index.alloc.destroy(resolved_filter);
        resolved_filter.* = filter;
        filter = .{};

        var next = req;
        if (request_constraints_resolved) {
            next.filter_doc_ids = &.{};
            next.filter_doc_ids_positive = false;
            next.exclude_doc_ids = &.{};
        }
        if (filter_json_resolved) next.filter_query_json = "";
        if (exclusion_json_resolved) next.exclusion_query_json = "";
        if (resolved_bindings.items.len > 0) next.doc_filter_bindings = &.{};
        next.resolved_doc_filter = resolved_filter;

        index.recordVectorFilterResolved(
            resolvedDocSetStatCount(&resolved_filter.include),
            resolvedDocSetStatCount(&resolved_filter.exclude),
        );
        return .{
            .req = next,
            .resolved_doc_filter = resolved_filter,
            .resolved_doc_filter_alloc = index.alloc,
        };
    }

    fn resolvedDocFilterForRequestNativeConstraintsAlloc(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
    ) !?doc_set.ResolvedDocFilter {
        var filter = doc_set.ResolvedDocFilter{};
        errdefer filter.deinit(alloc);
        var changed = false;

        if (req.resolved_doc_filter) |ptr| {
            const existing: *const doc_set.ResolvedDocFilter = @ptrCast(@alignCast(ptr));
            filter = try self.normalizeResolvedDocFilterDocKeysNoLockAtGenerationAlloc(alloc, existing, req.identity_read_generation);
            changed = true;
        }

        if (req.filter_doc_ids_positive or req.filter_doc_ids.len != 0) {
            var include = if (req.filter_doc_ids.len == 0)
                doc_set.ResolvedDocSet.none
            else
                try self.resolveDocSetForIdsNoLockAtGenerationAlloc(alloc, req.filter_doc_ids, req.identity_read_generation);
            defer include.deinit(alloc);
            if (!(try intersectResolvedFilterIncludeAlloc(alloc, &filter, &include))) {
                filter.deinit(alloc);
                return null;
            }
            changed = true;
        }

        if (req.exclude_doc_ids.len != 0) {
            var exclude = try self.resolveDocSetForIdsNoLockAtGenerationAlloc(alloc, req.exclude_doc_ids, req.identity_read_generation);
            defer exclude.deinit(alloc);
            if (!(try unionResolvedFilterExcludeAlloc(alloc, &filter, &exclude))) {
                filter.deinit(alloc);
                return null;
            }
            changed = true;
        }

        if (!changed) return null;
        return filter;
    }

    fn normalizeResolvedDocFilterDocKeysNoLockAtGenerationAlloc(
        self: *DB,
        alloc: Allocator,
        filter: *const doc_set.ResolvedDocFilter,
        generation: ?u64,
    ) !doc_set.ResolvedDocFilter {
        var out = doc_set.ResolvedDocFilter{
            .include = try self.normalizeResolvedDocSetDocKeysNoLockAtGenerationAlloc(alloc, &filter.include, generation),
        };
        errdefer out.deinit(alloc);
        out.exclude = try self.normalizeResolvedDocSetDocKeysNoLockAtGenerationAlloc(alloc, &filter.exclude, generation);
        return out;
    }

    fn normalizeResolvedDocSetDocKeysNoLockAtGenerationAlloc(
        self: *DB,
        alloc: Allocator,
        set: *const doc_set.ResolvedDocSet,
        generation: ?u64,
    ) !doc_set.ResolvedDocSet {
        return switch (set.*) {
            .doc_keys => |keys| try self.resolveDocSetForIdsNoLockAtGenerationAlloc(alloc, keys, generation),
            else => try doc_set.cloneAlloc(alloc, set),
        };
    }

    fn applyResolvedFilterIncludeAlloc(
        alloc: Allocator,
        target: *doc_set.ResolvedDocFilter,
        include_filter: *const doc_set.ResolvedDocFilter,
    ) !bool {
        var merged_include = (try doc_set.intersectAlloc(alloc, &target.include, &include_filter.include)) orelse return false;
        errdefer merged_include.deinit(alloc);
        var merged_exclude = (try doc_set.unionAlloc(alloc, &target.exclude, &include_filter.exclude)) orelse return false;
        errdefer merged_exclude.deinit(alloc);

        target.include.deinit(alloc);
        target.exclude.deinit(alloc);
        target.include = merged_include;
        target.exclude = merged_exclude;
        return true;
    }

    fn intersectResolvedFilterIncludeAlloc(
        alloc: Allocator,
        target: *doc_set.ResolvedDocFilter,
        include: *const doc_set.ResolvedDocSet,
    ) !bool {
        var merged = (try doc_set.intersectAlloc(alloc, &target.include, include)) orelse return false;
        errdefer merged.deinit(alloc);
        target.include.deinit(alloc);
        target.include = merged;
        return true;
    }

    fn unionResolvedFilterExcludeAlloc(
        alloc: Allocator,
        target: *doc_set.ResolvedDocFilter,
        exclude: *const doc_set.ResolvedDocSet,
    ) !bool {
        var merged = (try doc_set.unionAlloc(alloc, &target.exclude, exclude)) orelse return false;
        errdefer merged.deinit(alloc);
        target.exclude.deinit(alloc);
        target.exclude = merged;
        return true;
    }

    fn resolvedDocSetStatCount(set: *const doc_set.ResolvedDocSet) usize {
        return set.estimatedCardinality() orelse 0;
    }

    fn unionResolvedDocSetsAlloc(alloc: Allocator, left: *const doc_set.ResolvedDocSet, right: *const doc_set.ResolvedDocSet) !?doc_set.ResolvedDocSet {
        return switch (left.*) {
            .all => .all,
            .none => try doc_set.cloneAlloc(alloc, right),
            .doc_keys => |left_keys| switch (right.*) {
                .all => .all,
                .none => try doc_set.cloneAlloc(alloc, left),
                .doc_keys => |right_keys| .{ .doc_keys = try unionAlgebraicDocIds(alloc, left_keys, right_keys) },
                .ordinals, .ordinal_bitmap => null,
            },
            .ordinals, .ordinal_bitmap => switch (right.*) {
                .all => .all,
                .none => try doc_set.cloneAlloc(alloc, left),
                .doc_keys => null,
                .ordinals, .ordinal_bitmap => try unionOrdinalDocSetsAlloc(alloc, left, right),
            },
        };
    }

    fn unionOrdinalDocSetsAlloc(alloc: Allocator, left: *const doc_set.ResolvedDocSet, right: *const doc_set.ResolvedDocSet) !doc_set.ResolvedDocSet {
        var ordinals = std.ArrayListUnmanaged(doc_set.DocOrdinal).empty;
        defer ordinals.deinit(alloc);
        try appendResolvedDocSetOrdinalsAlloc(alloc, &ordinals, left);
        try appendResolvedDocSetOrdinalsAlloc(alloc, &ordinals, right);
        return try doc_set.fromOrdinalsAlloc(alloc, ordinals.items);
    }

    fn appendResolvedDocSetOrdinalsAlloc(alloc: Allocator, out: *std.ArrayListUnmanaged(doc_set.DocOrdinal), set: *const doc_set.ResolvedDocSet) !void {
        switch (set.*) {
            .ordinals => |ordinals| try out.appendSlice(alloc, ordinals),
            .ordinal_bitmap => |*bitmap| {
                var iter = bitmap.iterator();
                while (iter.next()) |ordinal| try out.append(alloc, ordinal);
            },
            .all, .none, .doc_keys => {},
        }
    }

    fn dupeAlgebraicDocIds(alloc: Allocator, doc_ids: []const []const u8) ![][]u8 {
        var out = try alloc.alloc([]u8, doc_ids.len);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |item| alloc.free(item);
            if (out.len > 0) alloc.free(out);
        }
        for (doc_ids, 0..) |doc_id, i| {
            out[i] = try alloc.dupe(u8, doc_id);
            initialized += 1;
        }
        return out;
    }

    fn containsAlgebraicDocId(doc_ids: []const []const u8, candidate: []const u8) bool {
        for (doc_ids) |doc_id| {
            if (std.mem.eql(u8, doc_id, candidate)) return true;
        }
        return false;
    }

    fn intersectAlgebraicDocIds(alloc: Allocator, left: []const []const u8, right: []const []const u8) ![][]u8 {
        var out = std.ArrayListUnmanaged([]u8).empty;
        errdefer {
            for (out.items) |item| alloc.free(item);
            out.deinit(alloc);
        }
        for (left) |doc_id| {
            if (!containsAlgebraicDocId(right, doc_id)) continue;
            try out.append(alloc, try alloc.dupe(u8, doc_id));
        }
        return try out.toOwnedSlice(alloc);
    }

    fn unionAlgebraicDocIds(alloc: Allocator, left: []const []const u8, right: []const []const u8) ![][]u8 {
        var out = std.ArrayListUnmanaged([]u8).empty;
        errdefer {
            for (out.items) |item| alloc.free(item);
            out.deinit(alloc);
        }
        for (left) |doc_id| try out.append(alloc, try alloc.dupe(u8, doc_id));
        for (right) |doc_id| {
            if (containsAlgebraicDocId(out.items, doc_id)) continue;
            try out.append(alloc, try alloc.dupe(u8, doc_id));
        }
        return try out.toOwnedSlice(alloc);
    }

    fn denseQueryMetricIndexName(self: *DB, req: types.SearchRequest) ?[]const u8 {
        if (req.index_name) |name| return name;
        const entry = self.core.denseIndex(null) orelse return null;
        return entry.config.name;
    }

    fn sparseQueryMetricIndexName(self: *DB, req: types.SearchRequest) ?[]const u8 {
        if (req.index_name) |name| return name;
        const entry = self.core.sparseIndex(null) orelse return null;
        return entry.config.name;
    }

    fn denseIndexCallback(
        ctx: ?*anyopaque,
        index_name: ?[]const u8,
    ) anyerror!?*index_manager_mod.IndexManager.DenseIndex {
        const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
        try self.failIfIndexQuarantined(index_name);
        return self.core.denseIndex(index_name);
    }

    fn snapshotDenseRequestEligible(req: types.SearchRequest) bool {
        if (req.include_stored or (req.query != .dense_knn and !db_query_search.isDefaultMatchAll(req.query))) return false;
        // Default-deny future request fields. This first snapshot path handles
        // plain document-member score pages; filters, hydration, grouping and
        // composed queries keep their existing synchronization.
        var remaining = req;
        const defaults: types.SearchRequest = .{};
        inline for (.{ "query", "dense", "index_name", "primary_text_index_name", "profile", "limit", "offset", "include_stored", "include_all_fields", "defer_stored_projection", "search_effort", "identity_read_generation", "execution_deadline_ns", "cancellation" }) |field| {
            @field(remaining, field) = @field(defaults, field);
        }
        // Empty slices from a decoded wire envelope need not share the
        // static default's address. std.meta.eql compares slice pointers.
        inline for (@typeInfo(types.SearchRequest).@"struct".field_names, @typeInfo(types.SearchRequest).@"struct".field_types) |reflected_name, field_type| {
            switch (@typeInfo(field_type)) {
                .pointer => |pointer| if (pointer.size == .slice) {
                    if (@field(remaining, reflected_name).len == 0 and @field(defaults, reflected_name).len == 0)
                        @field(remaining, reflected_name) = @field(defaults, reflected_name);
                },
                else => {},
            }
        }
        return std.meta.eql(remaining, defaults);
    }

    const DenseSnapshotExecutor = struct {
        snapshot: *index_manager_mod.IndexManager.DenseReadSnapshot,
        identity_generation: u64,

        fn from(ctx: ?*anyopaque) *@This() {
            return @ptrCast(@alignCast(ctx.?));
        }
        fn text(_: ?*anyopaque, _: ?[]const u8) anyerror!?*index_manager_mod.IndexManager.TextIndex {
            return null;
        }
        fn index(ctx: ?*anyopaque, _: ?[]const u8) anyerror!?*index_manager_mod.IndexManager.DenseIndex {
            return from(ctx).snapshot.entry;
        }
        fn key(ctx: ?*anyopaque, _: []const u8, id: u64) anyerror!?[]u8 {
            return from(ctx).snapshot.lookupDocKey(id);
        }
        fn vectorId(_: ?*anyopaque, _: []const u8, _: []const u8) anyerror!?u64 {
            return error.UnsupportedQueryRequest;
        }
        fn allVisible(ctx: ?*anyopaque, generation: ?u64) anyerror!bool {
            return generation == from(ctx).identity_generation;
        }
        fn visible(_: ?*anyopaque, _: Allocator, _: types.SearchHit) anyerror!bool {
            return true;
        }
        fn parent(_: ?*anyopaque, _: Allocator, _: types.SearchHit) anyerror![]u8 {
            return error.UnsupportedQueryRequest;
        }
        fn parentStored(_: ?*anyopaque, _: Allocator, _: types.SearchRequest, _: []const u8) anyerror!?[]u8 {
            return error.UnsupportedQueryRequest;
        }
        fn stored(_: ?*anyopaque, _: Allocator, _: []const u8) anyerror!?[]u8 {
            return error.UnsupportedQueryRequest;
        }
        fn projected(_: ?*anyopaque, _: Allocator, _: types.SearchRequest, _: []const u8) anyerror![]u8 {
            return error.UnsupportedQueryRequest;
        }
        fn search(ctx: ?*anyopaque, entry: *index_manager_mod.IndexManager.DenseIndex, req: vectorindex_mod.SearchRequest) anyerror!vectorindex_mod.SearchResults {
            return from(ctx).snapshot.source.context.manager.searchDenseEntryWithRequest(entry, req);
        }
        fn profiled(ctx: ?*anyopaque, entry: *index_manager_mod.IndexManager.DenseIndex, req: vectorindex_mod.SearchRequest) anyerror!vectorindex_mod.ProfiledSearchResults {
            return from(ctx).snapshot.source.context.manager.searchDenseEntryProfiledWithRequest(entry, req);
        }
        fn postprocess(ctx: ?*anyopaque, alloc: Allocator, req: types.SearchRequest, raw: types.SearchResult, chunk_backed: bool) anyerror!types.SearchResult {
            std.debug.assert(!chunk_backed);
            return db_query_result_shape.postprocessVectorSearchResult(alloc, req, raw, false, .{
                .ctx = ctx,
                .is_visible = visible,
                .resolve_parent_id = parent,
                .load_parent_stored = parentStored,
                .load_stored = stored,
            });
        }
        fn executor(self: *@This()) db_query_search.DenseSearchExecutor {
            return .{ .filter_candidate_presence = true, .ctx = self, .text_index_entry = text, .dense_index = index, .lookup_doc_key = key, .lookup_vector_id = vectorId, .all_docs_visible_fast = allVisible, .load_projected_document = projected, .hbc_search = @This().search, .hbc_search_profiled = profiled, .postprocess = postprocess };
        }
    };

    fn declineDenseSnapshot(reason: []const u8) ?SearchWithDenseProfileResult {
        if (benchQueryProfileEnabled()) std.log.info("antfly_bench_db_snapshot declined={s}", .{reason});
        return null;
    }

    fn trySnapshotDenseSearch(self: *DB, alloc: Allocator, req: types.SearchRequest, dense: types.DenseKnnQuery, include_profile: bool) !?SearchWithDenseProfileResult {
        const manager = self.async_context.resource_manager orelse return null;
        if (!manager.dense_query_snapshot) return null;
        if (!snapshotDenseRequestEligible(req)) {
            if (benchQueryProfileEnabled()) {
                const defaults: types.SearchRequest = .{};
                inline for (comptime std.meta.fieldNames(types.SearchRequest)) |reflected_name| {
                    if (!std.meta.eql(@field(req, reflected_name), @field(defaults, reflected_name)))
                        std.log.info("antfly_bench_db_snapshot nondefault_field={s}", .{reflected_name});
                }
            }
            return declineDenseSnapshot("request");
        }
        lockApplyShared(self);
        var apply_held = true;
        defer if (apply_held) self.core.unlockApplyShared();
        if (!self.beginPublishedDenseSearch()) return declineDenseSnapshot("catalog");
        defer self.endPublishedDenseSearch();
        // Publication can close admission while this query waits for apply.
        // Recheck under the same fence as the ordinary dense search path.
        try self.enforcePortableRuntimeGate();
        if (ttlDurationNs(self) != 0) return declineDenseSnapshot("ttl");
        const entry = (try denseIndexCallback(self, req.index_name)) orelse return error.IndexNotFound;
        if (entry.chunk_name != null or entry.embedding_names.len != 0) return declineDenseSnapshot("result_shape");
        const snapshot_req = try self.searchRequestAtCurrentIdentityGeneration(req);
        const summary = self.core.identity_visibility.summary orelse return declineDenseSnapshot("identity_summary");
        if (!doc_identity.allVisibleFromSummary(summary, snapshot_req.identity_read_generation)) return declineDenseSnapshot("visibility");
        try self.proveVectorSearchAccessPath(req.index_name, .dense_vector, false);
        var captured = (try self.core.index_manager.captureDenseReadSnapshot(entry, self.core.nextDerivedSequence())) orelse return declineDenseSnapshot("generation_bundle");
        defer captured.deinit();
        // Every mutable input is now captured; index lifetime remains protected
        // by the catalog lease until result metadata is fully materialized.
        self.core.unlockApplyShared();
        apply_held = false;
        captured.activate();
        defer captured.deactivate();
        var context: DenseSnapshotExecutor = .{ .snapshot = &captured, .identity_generation = snapshot_req.identity_read_generation.? };
        if (benchQueryProfileEnabled()) std.log.info("antfly_bench_db_snapshot captured=1 source_sequence={d} native_only={}", .{ captured.ann.sourceSequence(), captured.source.snapshot_native_only });
        const metric_name = entry.config.name;
        const started = platform_time.monotonicNs();
        errdefer observeSearchFailureMetric(metric_name, .vector, platform_time.monotonicNs() -| started);
        if (include_profile) {
            var result = db_query_search.searchDenseProfiled(alloc, snapshot_req, dense, context.executor()) catch |err| switch (err) {
                // Release the immutable bundle before retrying through the DB
                // path that owns durable repair and current-generation checks.
                error.IncompletePublishedSnapshot, error.DenseSnapshotNeedsPrimary => return null,
                else => return err,
            };
            result.profile.search_route = if (captured.source.snapshot_native_only) "hbc_snapshot_native" else "hbc_snapshot";
            return .{ .request = snapshot_req, .result = result.result, .dense_profile = result.profile };
        }
        var result = db_query_search.searchDense(alloc, snapshot_req, dense, context.executor()) catch |err| switch (err) {
            error.IncompletePublishedSnapshot, error.DenseSnapshotNeedsPrimary => return null,
            else => return err,
        };
        errdefer result.deinit();
        db_query_metrics.observeSortProfile(metric_name, .vector, platform_time.monotonicNs() -| started, result.sort_profile);
        try externalizeSearchResultArtifactIds(alloc, &result);
        return .{ .request = snapshot_req, .result = result, .dense_profile = null };
    }

    fn publishedDenseRequestEligible(req: types.SearchRequest) bool {
        // Graph execution must hold apply-shared from the retirement-gate
        // check through the entire read. The published-dense lease only pins
        // dense catalog entries and cannot fence a concurrent graph seal.
        if (req.query == .graph or req.graph_queries.len != 0 or
            req.graph_metric_queries.len != 0 or req.graph_metric_rerank != null or
            req.graph_query_transport != null) return false;
        if (req.full_text != null or req.sparse != null) return false;
        if (req.full_text_queries.len != 0 or req.dense_queries.len != 0 or req.sparse_queries.len != 0) return false;
        if (req.merge_config != null) return false;
        if (req.doc_filter_bindings.len != 0) return false;
        if (req.filter_query_json.len != 0 or req.exclusion_query_json.len != 0) return false;
        if (req.resolved_doc_filter != null) return false;
        if (req.filter_doc_ids_positive or req.filter_doc_ids.len != 0 or req.exclude_doc_ids.len != 0) return false;
        return req.dense != null or req.query == .dense_knn;
    }

    const DenseSearchAccess = enum {
        published,
        apply_shared,
    };

    /// Selects and acquires the complete synchronization mode for one search.
    /// When published-dense preflight discovers that the request needs the
    /// apply lock, acquire that lock before releasing the catalog lease. This
    /// closes the handoff gap in which a concurrent structural mutation could
    /// delete the entry between the preflight lookup and the locked fallback.
    fn beginDenseSearchAccess(self: *DB, req: types.SearchRequest) DenseSearchAccess {
        if (!publishedDenseRequestEligible(req) or !self.beginPublishedDenseSearch()) {
            lockApplyShared(self);
            return .apply_shared;
        }

        if (builtin.is_test) {
            if (test_published_dense_catalog_lookup_hook) |hook| {
                hook.entered.set(hook.io);
                hook.release.waitUncancelable(hook.io);
            }
        }

        const entry = self.core.denseIndex(req.index_name) orelse {
            lockApplyShared(self);
            self.endPublishedDenseSearch();
            return .apply_shared;
        };
        if (entry.index.hasExternalVectorLoader()) {
            lockApplyShared(self);
            self.endPublishedDenseSearch();
            return .apply_shared;
        }
        return .published;
    }

    fn endDenseSearchAccess(self: *DB, access: DenseSearchAccess) void {
        switch (access) {
            .published => self.endPublishedDenseSearch(),
            .apply_shared => self.core.unlockApplyShared(),
        }
    }

    const published_dense_catalog_closed: u32 = @as(u32, 1) << 31;
    const published_dense_reader_mask: u32 = published_dense_catalog_closed - 1;

    const IndexCatalogReadLease = struct {
        db: *DB,
        fn release(self: *@This()) void {
            self.db.endPublishedDenseSearch();
            self.* = undefined;
        }
    };

    /// The same lifetime fence used by immutable searches also protects
    /// optimistic background publishers. Structural writers drain these pins
    /// before retiring inline entries; ordinary primary commits do not.
    fn tryAcquireIndexCatalogReadLease(self: *DB) ?IndexCatalogReadLease {
        if (!self.beginPublishedDenseSearch()) return null;
        return .{ .db = self };
    }

    fn beginPublishedDenseSearch(self: *DB) bool {
        return self.core.index_manager.tryAcquireCatalogRead();
    }

    fn endPublishedDenseSearch(self: *DB) void {
        self.core.index_manager.releaseCatalogRead();
    }

    fn beginIndexCatalogBarrierUntil(self: *DB, deadline_ns: u64) bool {
        // Structural catalog writers are serialized by
        // index_structural_mutation_mutex. The bit and reader count share one
        // modification order: a reader is either counted before this RMW, or
        // observes the bit and falls back before touching the inline catalog.
        const previous = self.core.index_manager.published_dense_admission.fetchOr(published_dense_catalog_closed, .acq_rel);
        if (previous & published_dense_catalog_closed != 0) return false;

        var spins: usize = 0;
        while (self.core.index_manager.published_dense_admission.load(.acquire) & published_dense_reader_mask != 0) : (spins += 1) {
            if (monotonicTimeNs() >= deadline_ns) {
                const timed_out = self.core.index_manager.published_dense_admission.fetchAnd(published_dense_reader_mask, .release);
                std.debug.assert(timed_out & published_dense_catalog_closed != 0);
                return false;
            }
            if (spins < 64) {
                std.atomic.spinLoopHint();
            } else {
                @import("antfly_platform").time.yieldNow();
            }
        }
        return true;
    }

    /// Nonblocking production-protocol microsteps used by VOPR. They expose
    /// the lock-free reader/catalog-writer admission state machine without
    /// copying the protocol into a test model or parking a deterministic
    /// executor on native atomic waits.
    pub fn beginPublishedDenseCaptureForVopr(self: *DB, index_name: []const u8) bool {
        if (!builtin.is_test) return false;
        if (!self.beginPublishedDenseSearch()) return false;
        if (self.core.denseIndex(index_name) == null) {
            self.endPublishedDenseSearch();
            return false;
        }
        return true;
    }

    pub fn endPublishedDenseCaptureForVopr(self: *DB) void {
        if (!builtin.is_test) return;
        self.endPublishedDenseSearch();
    }

    pub fn beginIndexCatalogBarrierForVopr(self: *DB) bool {
        if (!builtin.is_test) return false;
        const previous = self.core.index_manager.published_dense_admission.fetchOr(published_dense_catalog_closed, .acq_rel);
        return previous & published_dense_catalog_closed == 0;
    }

    pub fn indexCatalogBarrierDrainedForVopr(self: *const DB) bool {
        if (!builtin.is_test) return false;
        return self.indexCatalogBarrierActive() and self.publishedDenseSearchCount() == 0;
    }

    pub fn endIndexCatalogBarrierForVopr(self: *DB) void {
        if (!builtin.is_test) return;
        self.endIndexCatalogBarrier();
    }

    fn endIndexCatalogBarrier(self: *DB) void {
        const previous = self.core.index_manager.published_dense_admission.fetchAnd(published_dense_reader_mask, .release);
        std.debug.assert(previous & published_dense_catalog_closed != 0);
        std.debug.assert(previous & published_dense_reader_mask == 0);
    }

    fn publishedDenseSearchCount(self: *const DB) u32 {
        return self.core.index_manager.published_dense_admission.load(.acquire) & published_dense_reader_mask;
    }

    fn indexCatalogBarrierActive(self: *const DB) bool {
        return self.core.index_manager.published_dense_admission.load(.acquire) & published_dense_catalog_closed != 0;
    }

    fn lockApplyUntil(self: *DB, deadline_ns: u64) bool {
        var spins: usize = 0;
        while (!self.core.tryLockApplyExclusive()) : (spins += 1) {
            if (monotonicTimeNs() >= deadline_ns) return false;
            if (spins < 64) {
                std.atomic.spinLoopHint();
            } else {
                @import("antfly_platform").time.yieldNow();
            }
        }
        return true;
    }

    fn ensureRepairActivationDeadline(deadline_ns: u64) !void {
        if (monotonicTimeNs() >= deadline_ns) return error.RepairActivationBudgetExhausted;
    }

