    fn loadRequiredProjectedSearchDocumentCallback(
        ctx: ?*anyopaque,
        alloc: Allocator,
        req: types.SearchRequest,
        key: []const u8,
    ) anyerror![]u8 {
        const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
        return try projectOwnedStoredBytesForSearch(
            self,
            alloc,
            req,
            key,
            (try self.loadStoredSearchDocumentProbe(alloc, key)) orelse return error.StoredDocMissing,
        );
    }

    fn postprocessVectorSearchResultCallback(
        ctx: ?*anyopaque,
        alloc: Allocator,
        req: types.SearchRequest,
        raw: types.SearchResult,
        chunk_backed: bool,
    ) anyerror!types.SearchResult {
        const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
        var presence = VectorSearchPresenceContext{ .db = self };
        var preparing = true;
        errdefer if (preparing) {
            var owned = raw;
            owned.deinit();
        };
        // Only explicitly ephemeral chunk streams use the embedding row as
        // their presence authority. Keep the public chunk identity unchanged
        // so full-text/dense fusion still deduplicates the same member.
        inline for (.{ self.core.index_manager.denseIndex(req.index_name), self.core.index_manager.sparseIndex(req.index_name) }) |selected| {
            if (selected) |entry| {
                if (chunk_backed and entry.embedding_names.len == 0) {
                    if (entry.chunk_name) |chunk_name| {
                        if (self.core.index_manager.getEnrichment(.chunk, chunk_name)) |cfg| {
                            if (cfg.source_artifact_name.len == 0 and !cfg.full_text_index and cfg.chunker_json.len > 0 and
                                !(try chunking_types_mod.parseHasFullTextIndexFromSlice(alloc, cfg.chunker_json)) and
                                !(try chunking_types_mod.parseStoreChunksFromSlice(alloc, cfg.chunker_json)))
                            {
                                presence.ephemeral_embedding_name = entry.embedding_name orelse entry.config.name;
                            }
                        }
                    }
                }
            }
        }
        preparing = false;
        return try db_query_result_shape.postprocessVectorSearchResult(alloc, req, raw, chunk_backed, .{
            .ctx = self,
            .is_visible = if (chunk_backed) isVisibleSearchHitCallback else isVisibleNonChunkSearchHitCallback,
            .filter_visible_many = filterVectorSearchCandidatesManyCallback,
            .filter_visible_many_ctx = &presence,
            .resolve_parent_id = resolveChunkParentIdCallback,
            .load_parent_stored = loadParentStoredForSearchCallback,
            .load_stored = loadStoredSearchDocumentCallback,
            .resolve_doc_set_doc_ids = resolveDocSetDocIdsCallback,
            .resolve_doc_ids_to_doc_set = resolveDocIdsToDocSetCallback,
            .load_many_parent_stored = loadParentStoredForSearchManyCallback,
            .load_many_stored = loadStoredSearchDocumentManyCallback,
            .load_projected_stored = loadProjectedSearchDocumentCallback,
            .load_many_projected_stored = loadProjectedSearchDocumentManyCallback,
        });
    }

    fn searchMatchAll(self: *DB, alloc: Allocator, req: types.SearchRequest) !types.SearchResult {
        return try db_query_search.searchMatchAll(alloc, req, .{
            .ctx = self,
            .collect_candidates = collectSearchMatchAllCandidatesCallback,
            .collect_candidates_stream = streamSearchMatchAllCandidatesCallback,
            .text_index_entry = textIndexEntryCallback,
            .resolve_doc_set_doc_ids = resolveDocSetDocIdsCallback,
            .resolve_doc_ids_to_doc_set = resolveDocIdsToDocSetCallback,
            .live_filter_doc_set = liveFilterDocSetCallback,
            .nonvisible_doc_set = nonVisibleDocSetCallback,
            .load_projected_document = loadRequiredProjectedSearchDocumentCallback,
            .load_projected_documents = loadProjectedSearchDocumentManyCallback,
            .load_stored = loadStoredSearchDocumentCallback,
            .load_many_stored = loadStoredSearchDocumentManyCallback,
            .is_expired_key = isNonvisibleStoredSearchKeyCallback,
        });
    }

    fn collectSearchMatchAllCandidatesCallback(
        ctx: ?*anyopaque,
        alloc: Allocator,
        req: types.SearchRequest,
        options: db_query_search.MatchAllCandidateCollectOptions,
    ) anyerror!db_query_search.MatchAllCandidates {
        const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
        return try db_query_search.collectMatchAllCandidatesWithOptions(alloc, req, .{
            .ctx = self,
            .scan_store_range = scanStoreRangeCallback,
            .scan_store_range_with_context = scanStoreRangeWithContextCallback,
            .is_expired_key = isExpiredDocumentKeyCallback,
            // searchMatchAll is entered under the outer DB apply lease. The
            // lock is not reentrant once an exclusive writer closes its reader
            // gate, so callbacks in this call tree must use lock-assuming APIs.
            .lookup_doc_ordinal = lookupLiveDocOrdinalNoLockCallback,
        }, options);
    }

    fn streamSearchMatchAllCandidatesCallback(
        ctx: ?*anyopaque,
        alloc: Allocator,
        req: types.SearchRequest,
        options: db_query_search.MatchAllCandidateCollectOptions,
        consumer_ctx: ?*anyopaque,
        consumer: db_query_search.MatchAllCandidateConsumer,
    ) anyerror!db_query_search.MatchAllCandidateStreamStats {
        const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
        return try db_query_search.streamMatchAllCandidatesWithOptions(alloc, req, .{
            .ctx = self,
            .scan_store_range = scanStoreRangeCallback,
            .scan_store_range_with_context = scanStoreRangeWithContextCallback,
            .is_expired_key = isExpiredDocumentKeyCallback,
            // See collectSearchMatchAllCandidatesCallback: the caller owns the
            // apply lease for the full streaming traversal.
            .lookup_doc_ordinal = lookupLiveDocOrdinalNoLockCallback,
        }, options, consumer_ctx, consumer);
    }

    fn lookupLiveDocOrdinalNoLockCallback(
        ctx: ?*anyopaque,
        alloc: Allocator,
        doc_id: []const u8,
        generation: ?u64,
    ) anyerror!?doc_set.DocOrdinal {
        const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
        if (builtin.is_test and test_block_match_all_ordinal_lookup.load(.acquire)) {
            test_match_all_ordinal_lookup_entered.store(true, .release);
            while (!test_release_match_all_ordinal_lookup.load(.acquire)) std.testing.io.sleep(.fromNanoseconds(1), .awake) catch {};
        }
        return try self.lookupLiveDocOrdinalNoLock(alloc, doc_id, generation);
    }

    fn lookupLiveDocOrdinalsNoLockCallback(
        ctx: ?*anyopaque,
        alloc: Allocator,
        doc_ids: []const []const u8,
        generation: ?u64,
    ) anyerror![]?doc_set.DocOrdinal {
        const self: *DB = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
        return try self.lookupLiveDocOrdinalsNoLock(alloc, doc_ids, generation);
    }

    fn lookupLiveDocOrdinalsNoLock(
        self: *DB,
        alloc: Allocator,
        doc_ids: []const []const u8,
        generation: ?u64,
    ) ![]?doc_set.DocOrdinal {
        var txn = try self.core.store.beginProbeTxn();
        defer txn.abort();

        const ordinals = try doc_identity.lookupOrdinalsTxnAlloc(alloc, &txn, doc_ids);
        errdefer alloc.free(ordinals);

        const all_visible = try self.allDocsVisibleSummaryFast(generation);
        if (all_visible) return ordinals;

        for (ordinals) |*maybe_ordinal| {
            const ordinal = maybe_ordinal.* orelse continue;
            const state = (try doc_identity.lookupStateTxn(&txn, ordinal)) orelse {
                maybe_ordinal.* = null;
                continue;
            };
            const visible = if (generation) |at| state.isVisibleAt(at) else state.isLive();
            if (!visible) maybe_ordinal.* = null;
        }
        return ordinals;
    }

    fn lookupLiveDocOrdinalNoLock(
        self: *DB,
        alloc: Allocator,
        doc_id: []const u8,
        generation: ?u64,
    ) !?doc_set.DocOrdinal {
        var txn = try self.core.store.beginProbeTxn();
        defer txn.abort();
        const ordinal = (try doc_identity.lookupOrdinalTxn(alloc, &txn, doc_id)) orelse return null;
        const state = (try doc_identity.lookupStateTxn(&txn, ordinal)) orelse return null;
        const visible = if (generation) |at| state.isVisibleAt(at) else state.isLive();
        if (!visible) return null;
        return ordinal;
    }

    /// Owner-local graph admission and hydration after the caller has crossed
    /// the Raft read gate. Candidate filtering and document loading are
    /// batched, avoiding one probe transaction per graph node.
    pub fn graphHydrateKeysForInternalRead(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
        keys: []const []const u8,
    ) ![]types.SearchHit {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();
        try self.requireGraphEndpointCleanupReady();
        if (!self.core.index_manager.graphRetirementAdmissionOpen()) return error.IntegrityTopologyBusy;

        const snapshot_req = try self.searchRequestAtCurrentIdentityGeneration(req);
        var admission = try self.filterGraphKeysWithOrdinalsAlloc(
            alloc,
            snapshot_req,
            keys,
        );
        defer admission.deinit(alloc);

        var hits = std.ArrayListUnmanaged(types.SearchHit).empty;
        errdefer {
            for (hits.items) |*hit| hit.deinit(alloc);
            hits.deinit(alloc);
        }
        try hits.ensureTotalCapacity(alloc, keys.len);
        for (keys, admission.allowed, admission.ordinals, 0..) |key, admitted, maybe_ordinal, i| {
            if (!admitted) continue;
            const ordinal = maybe_ordinal orelse return error.InvalidGraphNodeAdmissionResult;
            var stored_data: ?[]u8 = null;
            if (admission.stored_data) |items| {
                stored_data = items[i] orelse return error.InvalidGraphNodeAdmissionResult;
                items[i] = null;
            }
            const id = try alloc.dupe(u8, key);
            errdefer alloc.free(id);
            hits.appendAssumeCapacity(.{
                .id = id,
                .doc_ordinal = ordinal,
                .stored_data = stored_data,
            });
        }
        return try hits.toOwnedSlice(alloc);
    }

    /// Owner-local graph root probe after the caller has crossed the Raft read
    /// gate. The graph index performs the whole batch in one reverse snapshot.
    pub fn graphHasIncomingEdgesForInternalRead(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        keys: []const []const u8,
        expected: index_manager_mod.IndexManager.CoverageIdentity,
        identity_read_generation: ?u64,
    ) ![]bool {
        const result = try self.graphHasIncomingEdgesForInternalReadBoundedAt(alloc, index_name, keys, expected, identity_read_generation, 0, @import("../../graph/work_budget.zig").default_max_explored_edges);
        alloc.free(result.has_physical_incoming);
        return result.has_incoming;
    }

    pub fn graphHasIncomingEdgesForInternalReadBoundedAt(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        keys: []const []const u8,
        expected: index_manager_mod.IndexManager.CoverageIdentity,
        identity_read_generation: ?u64,
        ttl_now_ns: u64,
        max_scanned_rows: usize,
    ) !graph_mod.GraphIndex.IncomingProbeResult {
        var row_policy_lease = try self.local_execution.row_policy_gate.enterRaw();
        defer row_policy_lease.release();
        try self.lockApplySharedForPortableRuntime();
        defer self.core.unlockApplyShared();
        try self.requireGraphEndpointCleanupReady();
        if (!self.core.index_manager.graphRetirementAdmissionOpen()) return error.IntegrityTopologyBusy;
        // Validate under the same apply lease as the reverse snapshot. A
        // out-of-lease check can race index replacement and certify an
        // old index's negative answers under the new incarnation's cache key.
        if (expected.generation == 0 or expected.config_fingerprint == null)
            return error.InvalidArgument;
        const actual = self.core.index_manager.coverageIdentityForIndex(index_name) orelse
            return error.IndexGenerationMismatch;
        if (actual.generation != expected.generation or actual.config_fingerprint != expected.config_fingerprint)
            return error.IndexGenerationMismatch;
        // Reverse-only probes skip document hydration, but their routing
        // cache keys still bind the source shard's document/read generation.
        _ = try self.currentIdentityReadGenerationForRequest(identity_read_generation);
        const graph_entry = self.core.graphIndex(index_name) orelse return error.IndexNotFound;
        return try graph_entry.index.hasIncomingEdgesManyAllocBoundedAt(alloc, keys, if (ttl_now_ns == 0) graph_entry.index.clock.nowRealtimeNs() else ttl_now_ns, max_scanned_rows);
    }

    fn scanStoreRangeCallback(
        ctx: ?*anyopaque,
