    fn executeSinglePatternQueryWithSetsWithContext(
        self: *DB,
        alloc: Allocator,
        req: types.SearchRequest,
        named: *const types.NamedGraphQuery,
        named_sets: []const NamedResultSet,
        execution: *GraphPredicateExecutionContext,
