fn renderDocumentPdfPagePngAlloc(
    alloc: Allocator,
    pdf_bytes: []const u8,
    page_number: usize,
    dpi: u16,
    max_pixels: u64,
    max_dimension: u32,
    max_decoded_stream_bytes: usize,
    max_working_set_bytes: usize,
    render_timeout_ms: u64,
    out_failure: *runtime_failure_abi.FailureIdentity,
) ![]u8 {
    out_failure.* = .{};
    if (comptime !builtin.is_test and build_options.linked_storage) {
        const rendered = try document_extraction_client.renderPdfPagePngAdaptiveControlledAllocWithFailure(
            alloc,
            alloc,
            pdf_bytes,
            page_number,
            dpi,
            max_pixels,
            max_dimension,
            max_decoded_stream_bytes,
            max_working_set_bytes,
            render_timeout_ms,
            out_failure,
        );
        return rendered.png;
    }
    var render_deadline = document_extraction_mod.PdfRenderDeadline.init(render_timeout_ms);
    var session = try document_extraction_mod.PdfRenderSession.initWithDecodeLimitsAndCancellation(
        alloc,
        pdf_bytes,
        .{
            .max_decoded_stream_bytes = max_decoded_stream_bytes,
            .max_working_set_bytes = max_working_set_bytes,
        },
        render_deadline.probe(),
    );
    defer session.deinit();
    // Parsing and rasterization have independent wall-clock budgets.
    render_deadline = document_extraction_mod.PdfRenderDeadline.init(render_timeout_ms);
    session.setCancellationProbe(render_deadline.probe());
    const rendered = try session.renderPagePngAdaptiveAlloc(alloc, page_number, dpi, max_pixels, max_dimension);
    return rendered.png;
}

const boundaryFailureErrorName = local_mutation.boundaryFailureErrorName;

const GeneratedUnitTextKind = enum { ocr, transcript };

fn isUnavailableGeneratedTextModelError(kind: GeneratedUnitTextKind, err: anyerror) bool {
    if (kind != .ocr) return false;
    return switch (err) {
        error.ModelNotFound,
        error.ModelNotSpecified,
        error.UnsupportedReaderProvider,
        error.AppleProviderUnavailable,
        error.AppleIntelligenceProviderUnavailable,
        => true,
        else => false,
    };
}

test "precompute OCR error policy distinguishes unavailable models from transient inference failures" {
    try std.testing.expect(isUnavailableGeneratedTextModelError(.ocr, error.ModelNotFound));
    try std.testing.expect(isUnavailableGeneratedTextModelError(.ocr, error.ModelNotSpecified));
    try std.testing.expect(isUnavailableGeneratedTextModelError(.ocr, error.UnsupportedReaderProvider));
    try std.testing.expect(!isUnavailableGeneratedTextModelError(.ocr, error.ConnectionTimedOut));
    try std.testing.expect(isRetryableAssetProducerError(error.ConnectionTimedOut));
    try std.testing.expect(isRetryableAssetProducerError(error.EmbedRateLimited));
    try std.testing.expect(isRetryableAssetProducerError(error.ReadTransientFailure));
    try std.testing.expect(!isRetryableAssetProducerError(error.ReadRequestFailed));
}

test "db document extraction OCR default is scoped to PDF routes" {
    const alloc = std.testing.allocator;
    var defaults = try document_extraction_mod.parseConfig(alloc, "{}");
    defer defaults.deinit(alloc);
    try std.testing.expect(document_extraction_mod.ocrEnabledForRoute(defaults, "pdf"));
    try std.testing.expect(!document_extraction_mod.ocrEnabledForRoute(defaults, "image"));

    var explicit_image = try document_extraction_mod.parseConfig(alloc, "{\"ocr\":true}");
    defer explicit_image.deinit(alloc);
    try std.testing.expect(document_extraction_mod.ocrEnabledForRoute(explicit_image, "image"));
}

fn applyGeneratedUnitText(
    alloc: Allocator,
    unit: *document_extraction_mod.Unit,
    produced: []u8,
    method: []const u8,
    status: []const u8,
    kind: GeneratedUnitTextKind,
) !void {
    if (produced.len == 0) {
        alloc.free(produced);
        return error.EmptyGeneratedText;
    }
    defer alloc.free(produced);
    var parsed = try parseGeneratedUnitTextOutputAlloc(alloc, produced);
    errdefer parsed.deinit(alloc);
    const owned_method = try alloc.dupe(u8, method);
    errdefer alloc.free(owned_method);
    const owned_status = try alloc.dupe(u8, status);
    errdefer alloc.free(owned_status);

    alloc.free(unit.text);
    alloc.free(unit.method);
    if (unit.extraction_status) |value| alloc.free(value);
    if (unit.extraction_warning) |value| alloc.free(value);
    unit.text = parsed.text;
    parsed.text = &.{};
    unit.method = owned_method;
    unit.extraction_status = owned_status;
    switch (kind) {
        .ocr => {
            unit.ocr_used = true;
            unit.ocr_confidence = parsed.confidence;
            unit.ocr_bbox = parsed.bbox;
        },
        .transcript => {
            unit.transcript_used = true;
            unit.transcript_confidence = parsed.confidence;
            if (unit.transcript_spans.len > 0) alloc.free(unit.transcript_spans);
            unit.transcript_spans = parsed.spans;
            parsed.spans = &.{};
        },
    }
    if (parsed.spans.len > 0) {
        alloc.free(parsed.spans);
        parsed.spans = &.{};
    }
    unit.extraction_warning = parsed.warning;
    parsed.warning = null;
    const start = unit.char_start orelse 0;
    unit.char_start = start;
    unit.char_end = std.math.cast(u32, @as(usize, @intCast(start)) + unit.text.len);
}

fn markGeneratedUnitTextFailure(
    alloc: Allocator,
    unit: *document_extraction_mod.Unit,
    method: []const u8,
    kind: GeneratedUnitTextKind,
    err: anyerror,
) !void {
    return markGeneratedUnitTextFailureNamed(alloc, unit, method, kind, @errorName(err));
}

fn markGeneratedUnitTextFailureNamed(
    alloc: Allocator,
    unit: *document_extraction_mod.Unit,
    method: []const u8,
    kind: GeneratedUnitTextKind,
    error_name: []const u8,
) !void {
    const failed_status = switch (kind) {
        .ocr => "failed_ocr",
        .transcript => "failed_transcription",
    };
    const warning = try std.fmt.allocPrint(alloc, "{s} failed: {s}", .{ method, error_name });
    errdefer alloc.free(warning);
    const owned_text = try alloc.dupe(u8, "");
    errdefer alloc.free(owned_text);
    const owned_method = try alloc.dupe(u8, method);
    errdefer alloc.free(owned_method);
    const owned_status = try alloc.dupe(u8, failed_status);
    errdefer alloc.free(owned_status);

    alloc.free(unit.text);
    alloc.free(unit.method);
    if (unit.extraction_status) |value| alloc.free(value);
    if (unit.extraction_warning) |value| alloc.free(value);
    unit.text = owned_text;
    unit.method = owned_method;
    unit.extraction_status = owned_status;
    unit.extraction_warning = warning;
    switch (kind) {
        .ocr => {
            unit.ocr_used = false;
            unit.ocr_confidence = null;
            unit.ocr_bbox = null;
        },
        .transcript => {
            unit.transcript_used = false;
            unit.transcript_confidence = null;
        },
    }
    const start = unit.char_start orelse 0;
    unit.char_start = start;
    unit.char_end = start;
}

const ParsedGeneratedUnitText = struct {
    text: []u8,
    confidence: ?f64 = null,
    bbox: ?[4]f64 = null,
    /// Phrase timing when the producer returned transcript segments.
    spans: []document_extraction_mod.TranscriptSpan = &.{},
    warning: ?[]u8 = null,

    pub fn deinit(self: *ParsedGeneratedUnitText, alloc: Allocator) void {
        if (self.text.len > 0) alloc.free(self.text);
        if (self.warning) |value| alloc.free(value);
        if (self.spans.len > 0) alloc.free(self.spans);
        self.* = undefined;
    }
};

fn parseGeneratedUnitTextOutputAlloc(alloc: Allocator, produced: []const u8) !ParsedGeneratedUnitText {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, produced, .{}) catch {
        return .{ .text = try alloc.dupe(u8, produced) };
    };
    defer parsed.deinit();
    if (parsed.value != .object) return .{ .text = try alloc.dupe(u8, produced) };
    const text_value = parsed.value.object.get("text") orelse return .{ .text = try alloc.dupe(u8, produced) };
    if (text_value != .string) return .{ .text = try alloc.dupe(u8, produced) };

    var out = ParsedGeneratedUnitText{ .text = try alloc.dupe(u8, text_value.string) };
    errdefer out.deinit(alloc);
    out.confidence = generatedTextJsonFloatField(parsed.value.object, "confidence");
    out.bbox = generatedTextJsonBboxField(parsed.value.object, "ocr_bbox") orelse generatedTextJsonBboxField(parsed.value.object, "bbox") orelse generatedTextJsonBboxField(parsed.value.object, "coordinates");
    if (generatedTextJsonStringField(parsed.value.object, "warning") orelse generatedTextJsonStringField(parsed.value.object, "extraction_warning")) |warning| {
        out.warning = try alloc.dupe(u8, warning);
    }
    out.spans = try generatedTextSpansAlloc(alloc, parsed.value.object, out.text);
    return out;
}

/// Transcript segments from a producer's JSON output resolved to byte spans
/// of `text`.
fn generatedTextSpansAlloc(alloc: Allocator, object: std.json.ObjectMap, text: []const u8) ![]document_extraction_mod.TranscriptSpan {
    const value = object.get("segments") orelse return &.{};
    if (value != .array or value.array.items.len == 0) return &.{};
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const scratch = arena.allocator();
    const inputs = try scratch.alloc(document_extraction_mod.TranscriptSegmentInput, value.array.items.len);
    var count: usize = 0;
    for (value.array.items) |item| {
        if (item != .object) continue;
        const segment_text = generatedTextJsonStringField(item.object, "text") orelse continue;
        const start_ms = generatedTextJsonFloatField(item.object, "start_ms") orelse continue;
        const end_ms = generatedTextJsonFloatField(item.object, "end_ms") orelse continue;
        if (start_ms < 0 or end_ms < 0) continue;
        var words: []document_extraction_mod.TranscriptWordInput = &.{};
        if (item.object.get("words")) |words_value| {
            if (words_value == .array and words_value.array.items.len > 0) {
                words = try scratch.alloc(document_extraction_mod.TranscriptWordInput, words_value.array.items.len);
                var word_count: usize = 0;
                for (words_value.array.items) |word_item| {
                    if (word_item != .object) continue;
                    const word_text = generatedTextJsonStringField(word_item.object, "word") orelse continue;
                    const word_start = generatedTextJsonFloatField(word_item.object, "start_ms") orelse continue;
                    const word_end = generatedTextJsonFloatField(word_item.object, "end_ms") orelse continue;
                    if (word_start < 0 or word_end < 0) continue;
                    words[word_count] = .{ .text = word_text, .start_ms = @intFromFloat(word_start), .end_ms = @intFromFloat(word_end) };
                    word_count += 1;
                }
                words = words[0..word_count];
            }
        }
        inputs[count] = .{ .text = segment_text, .start_ms = @intFromFloat(start_ms), .end_ms = @intFromFloat(end_ms), .words = words };
        count += 1;
    }
    return try document_extraction_mod.transcriptSpansFromSegmentsAlloc(alloc, text, inputs[0..count]);
}

fn generatedTextJsonStringField(object: std.json.ObjectMap, field: []const u8) ?[]const u8 {
    const value = object.get(field) orelse return null;
    return if (value == .string) value.string else null;
}

fn generatedTextJsonFloatField(object: std.json.ObjectMap, field: []const u8) ?f64 {
    const value = object.get(field) orelse return null;
    return switch (value) {
        .float => |v| v,
        .integer => |v| @floatFromInt(v),
        else => null,
    };
}

fn generatedTextJsonBboxField(object: std.json.ObjectMap, field: []const u8) ?[4]f64 {
    const value = object.get(field) orelse return null;
    if (value != .array or value.array.items.len != 4) return null;
    var out: [4]f64 = undefined;
    for (value.array.items, 0..) |item, i| {
        out[i] = switch (item) {
            .float => |v| v,
            .integer => |v| @floatFromInt(v),
            else => return null,
        };
    }
    return out;
}

fn documentGeneratedTextPartsJsonAlloc(
    alloc: Allocator,
    route_type: []const u8,
    source_content_type: []const u8,
    unit: document_extraction_mod.Unit,
) ![]u8 {
    return try std.json.Stringify.valueAlloc(alloc, .{
        .schema = "antfly.document_generated_text_request.v1",
        .route_type = route_type,
        .source_content_type = source_content_type,
        .unit_id = unit.unit_id,
        .unit_type = unit.unit_type,
        .method = unit.method,
        .extraction_status = unit.extraction_status,
        .source_path = unit.source_path,
        .page_number = unit.page_number,
        .page_label = unit.page_label,
        .page_bbox = unit.page_bbox,
        .page_rotation = unit.page_rotation,
        .text_regions = unit.text_regions,
        .byte_length = unit.byte_length,
        .source_sha256 = unit.source_sha256,
        .ocr_confidence = unit.ocr_confidence,
        .ocr_bbox = unit.ocr_bbox,
        .transcript_confidence = unit.transcript_confidence,
        .extraction_warning = unit.extraction_warning,
    }, .{});
}

