const TtlDeleteGuard = struct {
    candidates: []const ttl_runtime_mod.DeleteCandidate,
    schema_registry: ?*schema_registry_mod.Registry,
    view: ?schema_registry_mod.SchemaView,
    duration_ns: u64,
    grace_period_ns: u64,
    now_ns: u64,
};

const GraphTtlCandidate = execution_resources.GraphTtlCandidate;
const DirectGraphTtlCandidate = graph_edge_ttl_expiration.DirectCandidate;

const GraphDirectTtlCommitGuard = struct {
    artifact_key: []const u8,
    artifact_digest: [32]u8,
    due_key: []const u8,
    due_value: []const u8,
    created_ns: u64,
    duration_ns: u64,
    grace_ns: u64,
    clock: platform_clock.Clock,

    pub fn validate(ptr: *anyopaque, _: Allocator, txn: *docstore_mod.DocStore.Batch.BatchTxn) anyerror!void {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        const artifact = txn.get(self.artifact_key) catch |err| switch (err) {
            error.NotFound => return error.GraphTtlCandidateChanged,
            else => return err,
        };
        var digest: [32]u8 = undefined;
        GraphTtlSha256.hash(artifact, &digest, .{});
        if (!std.mem.eql(u8, &digest, &self.artifact_digest)) return error.GraphTtlCandidateChanged;
        const due = txn.get(self.due_key) catch |err| switch (err) {
            error.NotFound => return error.GraphTtlCandidateChanged,
            else => return err,
        };
        if (!std.mem.eql(u8, due, self.due_value)) return error.GraphTtlCandidateChanged;
        if (!ttl_mod.isExpiredWithGrace(self.created_ns, self.duration_ns, self.grace_ns, self.clock.nowRealtimeNs()))
            return error.GraphTtlCandidateNotDue;
    }

    fn validateAtCommit(ptr: *anyopaque, _: Allocator, _: *docstore_mod.DocStore.Batch.BatchTxn) anyerror!void {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        if (!ttl_mod.isExpiredWithGrace(self.created_ns, self.duration_ns, self.grace_ns, self.clock.nowRealtimeNs()))
            return error.GraphTtlCandidateNotDue;
    }
};

const GraphTtlCommitGuard = struct {
    contender_key: []const u8,
    contender_digest: [32]u8,
    global_prefix: []const u8,
    global_fingerprint: GraphContenderPrefixFingerprint,
    local_prefix: []const u8,
    local_fingerprint: GraphContenderPrefixFingerprint,
    count_key: []const u8,
    count_raw: ?[]const u8,
    edge_key: []const u8,
    edge_raw: ?[]const u8,
    lifetime_key: []const u8,
    lifetime_raw: ?[]const u8,
    tombstone_key: []const u8,
    tombstone_raw: ?[]const u8,
    created_ns: u64,
    duration_ns: u64,
    grace_ns: u64,
    clock: platform_clock.Clock,

    fn matchesRaw(txn: *docstore_mod.DocStore.Batch.BatchTxn, key: []const u8, expected: ?[]const u8) !bool {
        const raw = txn.get(key) catch |err| switch (err) {
            error.NotFound => return expected == null,
            else => return err,
        };
        return if (expected) |value| std.mem.eql(u8, raw, value) else false;
    }

    pub fn validate(ptr: *anyopaque, _: Allocator, txn: *docstore_mod.DocStore.Batch.BatchTxn) anyerror!void {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        const raw = txn.get(self.contender_key) catch |err| switch (err) {
            error.NotFound => return error.GraphTtlCandidateChanged,
            else => return err,
        };
        var actual: [32]u8 = undefined;
        GraphTtlSha256.hash(raw, &actual, .{});
        if (!std.mem.eql(u8, &actual, &self.contender_digest)) return error.GraphTtlCandidateChanged;
        if (!self.global_fingerprint.eql(try GraphContenderPrefixFingerprint.fromTxn(txn, self.global_prefix)) or
            !self.local_fingerprint.eql(try GraphContenderPrefixFingerprint.fromTxn(txn, self.local_prefix)) or
            !(try matchesRaw(txn, self.count_key, self.count_raw)) or
            !(try matchesRaw(txn, self.edge_key, self.edge_raw)) or
            !(try matchesRaw(txn, self.lifetime_key, self.lifetime_raw)) or
            !(try matchesRaw(txn, self.tombstone_key, self.tombstone_raw)))
        {
            return error.GraphTtlCandidateChanged;
        }
        if (!ttl_mod.isExpiredWithGrace(self.created_ns, self.duration_ns, self.grace_ns, self.clock.nowRealtimeNs()))
            return error.GraphTtlCandidateNotDue;
    }

    fn validateAtCommit(ptr: *anyopaque, _: Allocator, _: *docstore_mod.DocStore.Batch.BatchTxn) anyerror!void {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        if (!ttl_mod.isExpiredWithGrace(self.created_ns, self.duration_ns, self.grace_ns, self.clock.nowRealtimeNs()))
            return error.GraphTtlCandidateNotDue;
    }
};

/// A missing identity summary cannot certify emptiness. This single transient
/// prefix seek is used only while holding the apply fence on an uncounted root.
const storeHasUserDataBounded = local_mutation.storeHasUserDataBounded;

/// A physical maintenance mutation and its hot-standby delivery obligation are one
/// primary transaction. Projection replay alone cannot certify these effects.
/// Every configured mirror uses a durable outbox, including asynchronous hot-standby.
const PrimaryReplicationEffect = struct {
    payload: ?[]u8 = null,
    key: ?[]u8 = null,
    value: ?[]u8 = null,

    fn prepare(ctx: *const BatchExecutionContext, writes: []const docstore_mod.KVPair, deletes: []const []const u8, replay: []const u8) !@This() {
        const mirror = ctx.replication_async_effect_mirror orelse return .{};
        if (ctx.async_context) |async_ctx| if (async_ctx.primary_replication_append_pending.load(.acquire)) return error.ReplicationPublisherUnavailable;
        try preflightReplicationMirrorSyncCommitContext(ctx, mirror);
        const payload = try replication_effects_mod.primary_effect.encodeAlloc(ctx.alloc, writes, deletes, replay);
        return prepareEncoded(ctx, payload);
    }

    fn prepareGraphRetirement(ctx: *const BatchExecutionContext, retirement: replication_effects_mod.primary_effect.GraphRetirement, replay: []const u8) !@This() {
        const mirror = ctx.replication_async_effect_mirror orelse return .{};
        try enforceReplicationWriteGateContext(ctx);
        try preflightReplicationMirrorSyncCommitContext(ctx, mirror);
        return prepareEncoded(ctx, try replication_effects_mod.primary_effect.encodeGraphRetirementAlloc(ctx.alloc, retirement, replay));
    }

    fn prepareEncoded(ctx: *const BatchExecutionContext, payload: []u8) !@This() {
        errdefer ctx.alloc.free(payload);
        const mirror = ctx.replication_async_effect_mirror orelse return error.ReplicationPublisherUnavailable;
        const from_lsn = mirror.publisher.nextLsn();
        const key = try durableReplicationOutboxKeyAlloc(ctx.alloc, .primary_effect, from_lsn, ctx.root_generation, payload);
        errdefer ctx.alloc.free(key);
        const value = try encodeDurableReplicationOutboxAlloc(ctx.alloc, from_lsn, payload);
        return .{ .payload = payload, .key = key, .value = value };
    }

    pub fn deinit(self: *@This(), alloc: Allocator) void {
        if (self.payload) |bytes| alloc.free(bytes);
        if (self.key) |bytes| alloc.free(bytes);
        if (self.value) |bytes| alloc.free(bytes);
    }

    fn stage(self: *const @This(), ctx: *const BatchExecutionContext, writes: *std.ArrayListUnmanaged(docstore_mod.KVPair)) !void {
        if (self.key) |key| {
            try writes.append(ctx.alloc, .{ .key = key, .value = self.value.? });
            if (ctx.async_context) |async_ctx| async_ctx.primary_replication_outbox_pending.store(true, .release);
        }
    }

    fn appendLocked(self: *const @This(), ctx: *const BatchExecutionContext) !?ReplicationDeferredCommitGate {
        const payload = self.payload orelse return null;
        const mirror = ctx.replication_async_effect_mirror orelse return error.ReplicationPublisherUnavailable;
        lockAtomic(ctx.log_mutex);
        defer ctx.log_mutex.*.unlock();
        // A failed append keeps the outbox, even under asynchronous policy.
        const lsn = mirror.publisher.publish(mirror, .primary_effect, payload, ctx.identity_namespace) catch |err| {
            if (ctx.async_context) |async_ctx| async_ctx.primary_replication_append_pending.store(true, .release);
            noteReplicationMirrorFailure(mirror, "primary effect", err);
            return err;
        };
        mirror.notePublished(lsn);
        return .{ .mirror = mirror, .lsn = lsn };
    }

    fn clear(self: *const @This(), ctx: *const BatchExecutionContext) !void {
        const key = self.key orelse return;
        try lockApplyForPortableRuntimeContext(ctx);
        defer ctx.apply_mutex.unlockExclusive();
        try ctx.store.putBatch(&.{}, &.{key});
    }
};

fn executeDeleteBatchContext(ctx: *const BatchExecutionContext, candidate_keys: []const []const u8, sync_level: types.SyncLevel, ttl_guard: ?TtlDeleteGuard) !u32 {
    if (candidate_keys.len == 0) return 0;
    var replication_mutation = acquireReplicationMutationSharedContext(ctx);
    defer if (replication_mutation) |*lease| lease.release();
    try enforceReplicationWriteGateContext(ctx);
    var snapshot_mutation = acquireSnapshotMutationContext(ctx);
    defer if (snapshot_mutation) |*lease| lease.release();
    try lockApplyForPortableRuntimeContext(ctx);
    var apply_mutex_held = true;
    errdefer if (apply_mutex_held) ctx.apply_mutex.unlockExclusive();

    var graph_publication = if (ctx.index_manager.hasGraphIndexes()) ctx.index_manager.beginGraphPrimaryMutation() else null;
    defer if (graph_publication) |*lease| lease.release();

    // Expiration is a real write, not an exemption from transaction guards.
    // Check under the same apply fence as deletion. A locked parent must not
    // prevent unrelated expired rows in this bounded page from progressing.
    try enforceReplicationWriteGateContext(ctx);
    {
        var lifecycle = try ctx.store.beginReadTxn();
        defer lifecycle.abort();
        try @import("relational_integrity_topology.zig").requireUnfenced(&lifecycle);
        try @import("relational_integrity_retirement.zig").requireMutable(&lifecycle);
        try @import("restore_staging.zig").requireScope(ctx.alloc, &lifecycle, null, false);
        const catalog_mod = @import("relational_integrity_catalog.zig");
        const raw = lifecycle.get(catalog_mod.key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (raw) |bytes| {
            var catalog = try catalog_mod.decode(ctx.alloc, bytes);
            defer catalog.deinit();
            for (catalog.bindings) |binding| if (!binding.retired)
                return error.ForeignKeyCoordinationRequired;
        }
    }
    var eligible = std.ArrayList([]const u8).empty;
    defer eligible.deinit(ctx.alloc);
    const eligible_keys = if (ttl_guard) |guard| blk: {
        if (guard.schema_registry) |registry| {
            if (guard.view) |pinned| {
                if (!registry.isCurrent(pinned)) return error.PreparedGenerationChanged;
            } else if (registry.acquire()) |current| {
                var pinned = current;
                pinned.release();
                return error.PreparedGenerationChanged;
            }
        }
        for (guard.candidates) |candidate| {
            const current = (try ttl_mod.readTimestamp(ctx.store, ctx.alloc, candidate.key)) orelse continue;
            if (current != candidate.timestamp_ns or
                !ttl_mod.isExpiredWithGrace(current, guard.duration_ns, guard.grace_period_ns, guard.now_ns)) continue;
            try eligible.append(ctx.alloc, candidate.key);
        }
        break :blk eligible.items;
    } else candidate_keys;
    var manager = try transactions_mod.TxnManager.init(ctx.alloc, ctx.store);
    defer manager.deinit();
    var unlocked = std.ArrayListUnmanaged([]const u8).empty;
    defer unlocked.deinit(ctx.alloc);
    const keys = blk: {
        manager.checkOrdinaryWriteConflicts(eligible_keys) catch |err| switch (err) {
            error.IntentConflict => {
                for (eligible_keys) |key| {
                    manager.checkOrdinaryWriteConflict(key) catch |conflict| switch (conflict) {
                        error.IntentConflict => continue,
                        else => return conflict,
                    };
                    try unlocked.append(ctx.alloc, key);
                }
                break :blk unlocked.items;
            },
            else => return err,
        };
        break :blk eligible_keys;
    };
    if (keys.len == 0) {
        ctx.apply_mutex.unlockExclusive();
        apply_mutex_held = false;
        return 0;
    }

    // TTL uses a stable runtime context rather than the movable DB handle.
    // Stage every document-owned generation here too, including retired ones,
    // and join the same primary/identity/replay commit below.
    var index_read: ?docstore_mod.DocStore.Txn = if (ctx.relational_base_rows) try ctx.store.beginReadTxn() else null;
    defer if (index_read) |*read| read.abort();
    const has_relational_indexes = if (index_read) |*read| blk: {
        _ = read.get(relational_index_catalog.head_key) catch |err| switch (err) {
            error.NotFound => break :blk false,
            else => return err,
        };
        break :blk true;
    } else false;
    var index_stage: ?relational_index_records.Staged = if (has_relational_indexes) relational_index_records.Staged.init(ctx.alloc, &index_read.?) else null;
    defer if (index_stage) |*stage| stage.deinit();
    var index_writer = relational_index_records.Writer.init(ctx.alloc);
    defer index_writer.deinit();
    if (index_stage) |*stage| for (keys) |key| try stage.deleteDocument(&index_writer, key);

    var store_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer store_writes.deinit(ctx.alloc);
    var owned_store_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_store_keys.items) |key| ctx.alloc.free(key);
        owned_store_keys.deinit(ctx.alloc);
    }
    var owned_store_values = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_store_values.items) |value| ctx.alloc.free(value);
        owned_store_values.deinit(ctx.alloc);
    }
    var identity_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer {
        for (identity_writes.items) |item| {
            ctx.alloc.free(@constCast(item.key));
            ctx.alloc.free(@constCast(item.value));
        }
        identity_writes.deinit(ctx.alloc);
    }
    var identity_visibility_deletes = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (identity_visibility_deletes.items) |key| ctx.alloc.free(key);
        identity_visibility_deletes.deinit(ctx.alloc);
    }
    var delete_keys = std.ArrayListUnmanaged([]const u8).empty;
    defer delete_keys.deinit(ctx.alloc);
    var timestamp_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (timestamp_delete_keys.items) |key| ctx.alloc.free(@constCast(key));
        timestamp_delete_keys.deinit(ctx.alloc);
    }
    var owned_delete_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_delete_keys.items) |key| ctx.alloc.free(key);
        owned_delete_keys.deinit(ctx.alloc);
    }

    for (keys) |key| {
        const store_key = if (ctx.relational_base_rows)
            try relational_store.keyAlloc(ctx.alloc, key)
        else
            try internal_keys.documentKeyAlloc(ctx.alloc, key);
        try owned_delete_keys.append(ctx.alloc, store_key);
        try delete_keys.append(ctx.alloc, store_key);
        if (!shouldWriteTimestamp(key)) continue;
        const timestamp_key = try makeTimestampKey(ctx.alloc, key);
        try timestamp_delete_keys.append(ctx.alloc, timestamp_key);
        try delete_keys.append(ctx.alloc, timestamp_key);
    }

    var deleted_artifact_keys = std.ArrayListUnmanaged([]u8).empty;
    defer deleted_artifact_keys.deinit(ctx.alloc);
    const should_scan_artifacts = if (ctx.artifact_cleanup_maybe) |artifact_cleanup_maybe|
        artifact_cleanup_maybe.load(.acquire) or ctx.index_manager.hasGeneratedEnrichmentTargets()
    else
        true;
    if (should_scan_artifacts) {
        var selected_artifacts = std.StringHashMapUnmanaged(void).empty;
        defer selected_artifacts.deinit(ctx.alloc);
        var seen_docs = std.StringHashMapUnmanaged(void).empty;
        defer seen_docs.deinit(ctx.alloc);
        for (keys) |key| {
            const gop = try seen_docs.getOrPut(ctx.alloc, key);
            if (gop.found_existing) continue;
            try collectEnrichmentArtifactDeleteKeysForDocContext(
                ctx.alloc,
                ctx.store,
                key,
                &delete_keys,
                &owned_delete_keys,
                &deleted_artifact_keys,
                &selected_artifacts,
            );
        }
    }
    const cleanup_generation = try appendGraphLifecycleGeneration(ctx.alloc, ctx.store, 0, &store_writes, &owned_store_values);
    try appendGraphEndpointRetirements(ctx.alloc, ctx.store, cleanup_generation, keys, ctx.index_manager.hasGraphIndexes(), deleted_artifact_keys.items, &store_writes, &owned_store_keys, &owned_store_values);
    const req = types.BatchRequest{
        .deletes = keys,
        .sync_level = sync_level,
    };
    var derived_batch = try buildDerivedBatch(ctx.alloc, req, &.{}, deleted_artifact_keys.items, &.{});
    defer derived_types.deinitDerivedBatch(ctx.alloc, &derived_batch);
    var sync_targets = try collectManagedSyncTargets(ctx.alloc, ctx.index_manager, derived_batch);
    defer sync_targets.deinit(ctx.alloc);
    const sequence = ctx.store.reserveNextReplaySequence(1);
    derived_batch.sequence = sequence;
    const identity_live_before = (try doc_identity.fastStatsFromStore(ctx.store)).live_ordinals;
    try doc_identity.appendBatchIdentityMetadataForNamespaceWithVisibilityDeletesAlloc(
        ctx.alloc,
        ctx.store,
        ctx.identity_namespace,
        sequence,
        &identity_writes,
        &identity_visibility_deletes,
        &.{},
        keys,
    );
    const pending_identity_visibility_summary = try doc_identity.visibilitySummaryFromWrites(identity_writes.items);
    const merge_count_prepared = try @import("merge_cardinality.zig").prepare(ctx.alloc, ctx.store, req, false, &.{}, keys, identity_live_before, if (pending_identity_visibility_summary) |summary| summary.live_ordinals else identity_live_before, &identity_writes);
    if (!merge_count_prepared) if (pending_identity_visibility_summary) |summary| {
        try range_cardinality.appendIdentityTransitionAlloc(
            ctx.alloc,
            ctx.store,
            ctx.index_manager.byte_range,
            identity_live_before,
            summary.live_ordinals,
            &identity_writes,
        );
    };
    try store_writes.appendSlice(ctx.alloc, identity_writes.items);
    try appendAssetArtifactSourceIndexMutations(
        ctx.alloc,
        &store_writes,
        deleted_artifact_keys.items,
        &delete_keys,
        &owned_store_keys,
        &owned_store_values,
        &owned_delete_keys,
    );
    try appendRetiredDirectGraphTtlDueDeletes(ctx.alloc, ctx.store, ctx.index_manager, store_writes.items, delete_keys.items, &delete_keys, &owned_delete_keys);
    try DB.appendDenseArtifactCounterMutations(
        ctx.alloc,
        ctx.store,
        ctx.index_manager,
        &store_writes,
        delete_keys.items,
        &owned_store_keys,
        &owned_store_values,
    );
    try delete_keys.appendSlice(ctx.alloc, identity_visibility_deletes.items);
    var next_table_catalog: ?table_catalog_mod.Catalog = null;
    var table_catalog_value: [table_catalog_mod.encoded_len]u8 = undefined;
    if (pending_identity_visibility_summary != null) {
        if (ctx.table_catalog) |current| {
            const row_count: u64 = @intFromBool(try range_cardinality.afterIdentityTransition(ctx.alloc, ctx.store, identity_writes.items) != 0);
            if (current.reconciled and current.row_count != row_count) {
                var next = current.*;
                next.row_count = row_count;
                next.generation +|= 1;
                table_catalog_value = next.encode();
                next_table_catalog = next;
                try store_writes.append(ctx.alloc, .{ .key = table_catalog_mod.key, .value = &table_catalog_value });
            }
        }
    } else if (ctx.table_catalog) |current| {
        // TTL/context deletion has the same conservative presence semantics as
        // ordinary mutation: unknown cardinality must never publish empty.
        if (current.row_count == 0 and keys.len != 0 and try storeHasUserDataBounded(ctx.store)) {
            var next = current.*;
            next.row_count = 1;
            next.generation +|= 1;
            table_catalog_value = next.encode();
            next_table_catalog = next;
            try store_writes.append(ctx.alloc, .{ .key = table_catalog_mod.key, .value = &table_catalog_value });
        }
    }
    if (index_stage) |*stage| {
        const effects = try stage.seal();
        var forward_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer forward_keys.deinit(ctx.alloc);
        for (effects.writes) |effect| if (relational_index_records.isForwardKey(effect.key))
            try forward_keys.append(ctx.alloc, effect.key);
        for (effects.deletes) |key| if (relational_index_records.isForwardKey(key))
            try forward_keys.append(ctx.alloc, key);
        try manager.checkIndexForwardWriteConflicts(forward_keys.items);
        try store_writes.appendSlice(ctx.alloc, effects.writes);
        try delete_keys.appendSlice(ctx.alloc, effects.deletes);
    }
    const replay_payload = try encodeChangeRecordPayload(ctx, derived_batch, sequence);
    defer ctx.alloc.free(replay_payload);
    var primary_replication = try PrimaryReplicationEffect.prepare(ctx, store_writes.items, delete_keys.items, replay_payload);
    defer primary_replication.deinit(ctx.alloc);
    try primary_replication.stage(ctx, &store_writes);
    var backlog_admission = try ctx.executor.admitBacklogBytes(@intCast(replay_payload.len));
    defer backlog_admission.cancel();
    try ctx.store.putBatchWithReplay(ctx.io, store_writes.items, delete_keys.items, .{
        .sequence = sequence,
        .payload = replay_payload,
    });
    if (graph_publication) |*lease| lease.release();
    ctx.executor.commitBacklogAdmission(sequence, &backlog_admission);
    if (next_table_catalog) |catalog| ctx.table_catalog.?.* = catalog;
    if (pending_identity_visibility_summary) |summary| {
        if (ctx.identity_visibility) |visibility| visibility.publish(summary);
    }
    var deferred_replication_gates = ReplicationDeferredCommitGates.begin(replicationTransitionMutexFromContext(ctx));
    defer deferred_replication_gates.releaseTransition();
    deferred_replication_gates.append(try primary_replication.appendLocked(ctx));
    ctx.apply_mutex.unlockExclusive();
    apply_mutex_held = false;
    if (snapshot_mutation) |*lease| lease.release();
    snapshot_mutation = null;
    DB.notifyQueryVisibilityTargetAdvancedScopedContext(ctx, sequence, sync_targets);
    releaseReplicationMutationShared(&replication_mutation);
    try deferred_replication_gates.waitForDurabilityAndAuthority(ctx.replication_write_gate);
    try primary_replication.clear(ctx);
    try markPrecomputedEnrichmentAppliedForSyncContext(ctx, sync_level, sequence);
    try applyDerivedBacklogPressureContext(ctx, sequence, sync_level, sync_targets);
    if (ctx.executor.hasWorkers()) {
        notifyExecutorForSyncLevelWithDenseBulkDeferral(ctx.async_context, ctx.executor, sync_level, sequence, sync_targets);
        try waitForSyncLevelContext(ctx, sync_level, sequence, sync_targets);
    } else {
        if (syncLevelRequiresDerivedVisibility(sync_level)) {
            try lockApplyForPortableRuntimeContext(ctx);
            defer ctx.apply_mutex.unlockExclusive();
            if (sync_level == .full_text) {
                try applyDerivedBatchTargetsContext(ctx, derived_batch, sync_targets.full_text_indexes);
            } else {
                try applyDerivedBatchContext(ctx, derived_batch);
            }
        }
        try waitForSyncLevelContext(ctx, sync_level, sequence, sync_targets);
    }
    if (ctx.enrichment_runtime) |runtime| runtime.notifySequence(sequence);
    notifyResolverReplayRuntimesForCatalog(ctx.index_manager, ctx.resolution_runtime, ctx.promotion_runtime, sequence);
    return @intCast(keys.len);
}

fn deleteExpiredDocumentsFromCandidates(ctx_ptr: *anyopaque, candidates: []const ttl_runtime_mod.DeleteCandidate) !u32 {
    const ctx: *TtlCleanupContext = @ptrCast(@alignCast(ctx_ptr));
    var view = if (ctx.schema_registry) |registry| registry.acquire() else null;
    defer if (view) |*pinned| pinned.release();
    if (view) |pinned| if (pinned.hasCoordinatedConstraints()) {
        const io = ctx.batch.io orelse std.Options.debug_io;
        ctx.hook_mutex.lockUncancelable(io);
        const port = ctx.coordinated_port;
        ctx.hook_mutex.unlock(io);
        const callback = port orelse return error.ForeignKeyCoordinationRequired;
        if (ctx.batch.identity_namespace.table_id == 0)
            return error.ForeignKeyCoordinationRequired;
        const schema = pinned.tableSchema();
        if (schema.ttl_duration_ns == 0) return 0;
        const now = ctx.clock.nowRealtimeNs();
        var prepared = std.ArrayList(coordinated_ttl.Candidate).empty;
        defer prepared.deinit(ctx.batch.alloc);
        {
            var txn = try ctx.batch.store.runtime_store.beginRead();
            defer txn.abort();
            for (candidates) |candidate| {
                if (prepared.items.len >= 128) break;
                const timestamp_key = try internal_keys.ttlKeyAlloc(ctx.batch.alloc, candidate.key);
                defer ctx.batch.alloc.free(timestamp_key);
                const timestamp_raw = txn.get(timestamp_key) catch |err| switch (err) {
                    error.NotFound => continue,
                    else => return err,
                };
                if (timestamp_raw.len != 8) return error.InvalidTimestamp;
                const timestamp = std.mem.readInt(u64, timestamp_raw[0..8], .little);
                if (timestamp != candidate.timestamp_ns or
                    !ttl_mod.isExpiredWithGrace(timestamp, schema.ttl_duration_ns, ctx.grace_period_ns, now)) continue;
                const row_key = if (pinned.storageMode() == .relational)
                    try relational_store.keyAlloc(ctx.batch.alloc, candidate.key)
                else
                    try internal_keys.documentKeyAlloc(ctx.batch.alloc, candidate.key);
                defer ctx.batch.alloc.free(row_key);
                const raw = txn.get(row_key) catch |err| switch (err) {
                    error.NotFound => continue,
                    else => return err,
                };
                var digest: [32]u8 = undefined;
                std.crypto.hash.sha2.Sha256.hash(raw, &digest, .{});
                try prepared.append(ctx.batch.alloc, .{
                    .key = candidate.key,
                    .row_version = timestamp,
                    .ttl_timestamp_ns = timestamp,
                    .expected_content_digest = digest,
                });
            }
        }
        if (prepared.items.len == 0) return 0;
        // No native transaction, apply lock, or hook lock spans distributed IO.
        return callback.expire(.{
            .table_id = ctx.batch.identity_namespace.table_id,
            .schema_version = pinned.version(),
            .ttl_duration_ns = schema.ttl_duration_ns,
            .ttl_field = schema.ttl_field,
            .observed_at_unix_ns = now,
            .grace_period_ns = ctx.grace_period_ns,
            .candidates = prepared.items,
        });
    };
    const loaded_schema = try schema_mod.loadSchema(ctx.batch.store, ctx.batch.alloc);
    defer if (loaded_schema) |schema| schema_mod.freeSchema(ctx.batch.alloc, schema);

    const duration_ns = if (loaded_schema) |schema|
        schema.ttl_duration_ns
    else
        0;
    if (duration_ns == 0) return 0;

    const now_ns = ctx.clock.nowRealtimeNs();
    var deletes = std.ArrayListUnmanaged([]const u8).empty;
    defer deletes.deinit(ctx.batch.alloc);

    for (candidates) |candidate| try deletes.append(ctx.batch.alloc, candidate.key);
    if (deletes.items.len == 0) return 0;

    var current_batch = ctx.batch;
    if (view) |pinned| current_batch.relational_base_rows = pinned.storageMode() == .relational;
    return try executeDeleteBatchContext(&current_batch, deletes.items, .full_index, .{
        .candidates = candidates,
        .schema_registry = ctx.schema_registry,
        .view = view,
        .duration_ns = duration_ns,
        .grace_period_ns = ctx.grace_period_ns,
        .now_ns = now_ns,
    });
}

fn graphTtlOptionalStoreValue(alloc: Allocator, store: *docstore_mod.DocStore, key: []const u8) !?[]u8 {
    return store.get(alloc, key) catch |err| switch (err) {
        error.NotFound => null,
        else => return err,
    };
}

fn expireGraphTtlCandidates(ptr: *anyopaque, candidates: []const graph_edge_ttl_expiration.Due) !ttl_runtime_mod.GraphExpireCounts {
    const ctx: *TtlCleanupContext = @ptrCast(@alignCast(ptr));
    var expired: ttl_runtime_mod.GraphExpireCounts = .{};
    for (candidates) |candidate| switch (candidate) {
        .source => |source| {
            if (try expireGraphTtlCandidateContext(ctx, source)) {
                expired.sources += 1;
            } else {
                try pruneStaleGraphTtlCandidateContext(ctx, source);
            }
        },
        .direct => |direct| {
            if (try expireDirectGraphTtlCandidateContext(ctx, direct)) {
                expired.direct_artifacts += 1;
            } else {
                try pruneStaleDirectGraphTtlCandidateContext(ctx, direct);
            }
        },
    };
    return expired;
}

/// Remove only a due record whose exact candidate value is still present and
/// whose source no longer belongs to this shard/index incarnation. The write
/// transaction performs both checks under one writer lock, so a replacement
/// contender can never lose its own deadline entry.
fn pruneStaleGraphTtlCandidateContext(ttl_ctx: *TtlCleanupContext, candidate: GraphTtlCandidate) !void {
    const ctx = &ttl_ctx.batch;
    var snapshot_mutation = acquireSnapshotMutationContext(ctx);
    defer if (snapshot_mutation) |*lease| lease.release();
    try lockApplyForPortableRuntimeContext(ctx);
    defer ctx.apply_mutex.unlockExclusive();
    var graph_publication = ctx.index_manager.beginGraphPrimaryMutation();
    defer graph_publication.release();
    const contender_key = try internal_keys.graphGlobalEdgeContenderKeyAlloc(ctx.alloc, candidate.index_name, candidate.generation, candidate.edge_key, candidate.source_priority, candidate.state_key);
    defer ctx.alloc.free(contender_key);
    const due_key = try graph_edge_ttl_expiration.indexKeyAlloc(ctx.alloc, candidate.deadline_ns, contender_key);
    defer ctx.alloc.free(due_key);
    const expected_value = try graph_edge_ttl_expiration.encodeAlloc(ctx.alloc, candidate);
    defer ctx.alloc.free(expected_value);
    var txn = try ctx.store.beginWriteTxn();
    errdefer txn.abort();
    const actual_value = txn.get(due_key) catch |err| switch (err) {
        error.NotFound => {
            txn.abort();
            return;
        },
        else => return err,
    };
    if (!std.mem.eql(u8, actual_value, expected_value)) {
        txn.abort();
        return;
    }
    if (ctx.index_manager.graphIndex(candidate.index_name)) |entry| {
        if (entry.ttl_duration_ns != 0 and entry.config.coverage_generation == candidate.generation) {
            const doc_key = (try internal_keys.decodeDocumentComponentAlloc(ctx.alloc, candidate.edge_key)) orelse return error.InvalidGraphTtlCandidate;
            defer ctx.alloc.free(doc_key);
            if (ctx.index_manager.byte_range.contains(doc_key)) {
                const raw = txn.get(contender_key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
                if (raw) |contender| {
                    var digest: [32]u8 = undefined;
                    GraphTtlSha256.hash(contender, &digest, .{});
                    if (std.mem.eql(u8, &digest, &candidate.contender_digest)) {
                        txn.abort();
                        return;
                    }
                }
            }
        }
    }
    try txn.delete(due_key);
    try txn.commit();
}

fn pruneStaleDirectGraphTtlCandidateContext(ttl_ctx: *TtlCleanupContext, candidate: DirectGraphTtlCandidate) !void {
    const ctx = &ttl_ctx.batch;
    var snapshot_mutation = acquireSnapshotMutationContext(ctx);
    defer if (snapshot_mutation) |*lease| lease.release();
    try lockApplyForPortableRuntimeContext(ctx);
    defer ctx.apply_mutex.unlockExclusive();
    var graph_publication = ctx.index_manager.beginGraphPrimaryMutation();
    defer graph_publication.release();
    const due_key = try graph_edge_ttl_expiration.directIndexKeyAlloc(ctx.alloc, candidate.deadline_ns, candidate.artifact_key);
    defer ctx.alloc.free(due_key);
    const expected_value = try graph_edge_ttl_expiration.encodeDirectAlloc(ctx.alloc, candidate);
    defer ctx.alloc.free(expected_value);
    var txn = try ctx.store.beginWriteTxn();
    errdefer txn.abort();
    const actual_value = txn.get(due_key) catch |err| switch (err) {
        error.NotFound => {
            txn.abort();
            return;
        },
        else => return err,
    };
    if (!std.mem.eql(u8, actual_value, expected_value)) {
        txn.abort();
        return;
    }
    if (ctx.index_manager.graphIndex(candidate.index_name)) |entry| {
        if (entry.ttl_duration_ns != 0 and entry.config.coverage_generation == candidate.generation) {
            const doc_key = (try internal_keys.decodeDocumentComponentAlloc(ctx.alloc, candidate.artifact_key)) orelse return error.InvalidGraphTtlCandidate;
            defer ctx.alloc.free(doc_key);
            if (ctx.index_manager.byte_range.contains(doc_key)) {
                const raw = txn.get(candidate.artifact_key) catch |err| switch (err) {
                    error.NotFound => null,
                    else => return err,
                };
                if (raw) |artifact| {
                    var digest: [32]u8 = undefined;
                    GraphTtlSha256.hash(artifact, &digest, .{});
                    if (std.mem.eql(u8, &digest, &candidate.artifact_digest)) {
                        txn.abort();
                        return;
                    }
                }
            }
        }
    }
    try txn.delete(due_key);
    try txn.commit();
}

fn expireDirectGraphTtlCandidateContext(ttl_ctx: *TtlCleanupContext, candidate: DirectGraphTtlCandidate) !bool {
    const ctx = &ttl_ctx.batch;
    if (!internal_keys.isGraphEdgeArtifactKey(candidate.artifact_key) or
        !internal_keys.matchesGraphEdgeIndexName(candidate.artifact_key, candidate.index_name) or
        candidate.generation == 0 or candidate.deadline_ns == 0)
        return error.InvalidGraphTtlCandidate;
    var replication_mutation = acquireReplicationMutationSharedContext(ctx);
    defer if (replication_mutation) |*lease| lease.release();
    try enforceReplicationWriteGateContext(ctx);
    var snapshot_mutation = acquireSnapshotMutationContext(ctx);
    defer if (snapshot_mutation) |*lease| lease.release();
    try lockApplyForPortableRuntimeContext(ctx);
    var apply_mutex_held = true;
    errdefer if (apply_mutex_held) ctx.apply_mutex.unlockExclusive();
    var graph_publication = ctx.index_manager.beginGraphPrimaryMutation();
    defer graph_publication.release();
    try enforceReplicationWriteGateContext(ctx);
    const graph_entry = ctx.index_manager.graphIndex(candidate.index_name) orelse {
        ctx.apply_mutex.unlockExclusive();
        return false;
    };
    const duration_ns = graph_entry.ttl_duration_ns;
    if (duration_ns == 0 or graph_entry.config.coverage_generation != candidate.generation or
        ctx.index_manager.graphArtifactSources(candidate.index_name).len != 0)
    {
        ctx.apply_mutex.unlockExclusive();
        return false;
    }
    const doc_key = (try internal_keys.decodeDocumentComponentAlloc(ctx.alloc, candidate.artifact_key)) orelse return error.InvalidGraphTtlCandidate;
    defer ctx.alloc.free(doc_key);
    if (!ctx.index_manager.byte_range.contains(doc_key)) {
        ctx.apply_mutex.unlockExclusive();
        return false;
    }
    {
        var lifecycle = try ctx.store.beginReadTxn();
        defer lifecycle.abort();
        try @import("relational_integrity_topology.zig").requireUnfenced(&lifecycle);
        try @import("relational_integrity_retirement.zig").requireMutable(&lifecycle);
        try @import("restore_staging.zig").requireScope(ctx.alloc, &lifecycle, null, false);
    }
    var txn_manager = try transactions_mod.TxnManager.init(ctx.alloc, ctx.store);
    defer txn_manager.deinit();
    txn_manager.checkOrdinaryWriteConflict(doc_key) catch |err| switch (err) {
        error.IntentConflict => {
            ctx.apply_mutex.unlockExclusive();
            return false;
        },
        else => return err,
    };
    const due_key = try graph_edge_ttl_expiration.directIndexKeyAlloc(ctx.alloc, candidate.deadline_ns, candidate.artifact_key);
    defer ctx.alloc.free(due_key);
    const due_value = try graph_edge_ttl_expiration.encodeDirectAlloc(ctx.alloc, candidate);
    defer ctx.alloc.free(due_value);
    const artifact = try graphTtlOptionalStoreValue(ctx.alloc, ctx.store, candidate.artifact_key) orelse {
        ctx.apply_mutex.unlockExclusive();
        return false;
    };
    defer ctx.alloc.free(artifact);
    var digest: [32]u8 = undefined;
    GraphTtlSha256.hash(artifact, &digest, .{});
    if (!std.mem.eql(u8, &digest, &candidate.artifact_digest)) {
        ctx.apply_mutex.unlockExclusive();
        return false;
    }
    var edge = try enrichment_artifact_codec.decodeGraphEdgeAlloc(ctx.alloc, artifact);
    defer edge.deinit(ctx.alloc);
    if (edge.generation != candidate.generation or edge.ttl_created_ns == 0) return error.GraphEdgeTtlMigrationRequired;
    const deadline_ns = std.math.add(u64, edge.ttl_created_ns, duration_ns) catch std.math.maxInt(u64);
    if (deadline_ns != candidate.deadline_ns or
        !ttl_mod.isExpiredWithGrace(edge.ttl_created_ns, duration_ns, ttl_ctx.grace_period_ns, ttl_ctx.clock.nowRealtimeNs()))
    {
        ctx.apply_mutex.unlockExclusive();
        return false;
    }
    var derived_batch = try buildDerivedBatch(ctx.alloc, .{ .sync_level = .full_index }, &.{}, &.{}, &.{@constCast(candidate.artifact_key)});
    defer derived_types.deinitDerivedBatch(ctx.alloc, &derived_batch);
    var sync_targets = try collectManagedSyncTargets(ctx.alloc, ctx.index_manager, derived_batch);
    defer sync_targets.deinit(ctx.alloc);
    const sequence = ctx.store.reserveNextReplaySequence(1);
    derived_batch.sequence = sequence;
    const replay_payload = try encodeChangeRecordPayload(ctx, derived_batch, sequence);
    defer ctx.alloc.free(replay_payload);
    var primary_replication = try PrimaryReplicationEffect.prepare(ctx, &.{}, &.{ candidate.artifact_key, due_key }, replay_payload);
    defer primary_replication.deinit(ctx.alloc);
    var primary_writes: std.ArrayListUnmanaged(docstore_mod.KVPair) = .empty;
    defer primary_writes.deinit(ctx.alloc);
    try primary_replication.stage(ctx, &primary_writes);
    var backlog_admission = try ctx.executor.admitBacklogBytes(@intCast(replay_payload.len));
    defer backlog_admission.cancel();
    var guard = GraphDirectTtlCommitGuard{
        .artifact_key = candidate.artifact_key,
        .artifact_digest = candidate.artifact_digest,
        .due_key = due_key,
        .due_value = due_value,
        .created_ns = edge.ttl_created_ns,
        .duration_ns = duration_ns,
        .grace_ns = ttl_ctx.grace_period_ns,
        .clock = ttl_ctx.clock,
    };
    _ = ctx.store.putBatchWithPromotionsReplayAndBuiltWrite(
        ctx.io,
        primary_writes.items,
        &.{ candidate.artifact_key, due_key },
        &.{},
        .{ .sequence = sequence, .payload = replay_payload },
        null,
        .{ .ptr = &guard, .validate = GraphDirectTtlCommitGuard.validate, .validate_at_commit = GraphDirectTtlCommitGuard.validateAtCommit },
    ) catch |err| switch (err) {
        error.GraphTtlCandidateChanged, error.GraphTtlCandidateNotDue => {
            ctx.apply_mutex.unlockExclusive();
            apply_mutex_held = false;
            return false;
        },
        else => return err,
    };
    graph_publication.release();
    ctx.executor.commitBacklogAdmission(sequence, &backlog_admission);
    var deferred_replication_gates = ReplicationDeferredCommitGates.begin(replicationTransitionMutexFromContext(ctx));
    defer deferred_replication_gates.releaseTransition();
    deferred_replication_gates.append(try primary_replication.appendLocked(ctx));
    ctx.apply_mutex.unlockExclusive();
    apply_mutex_held = false;
    if (snapshot_mutation) |*lease| lease.release();
    snapshot_mutation = null;
    DB.notifyQueryVisibilityTargetAdvancedScopedContext(ctx, sequence, sync_targets);
    releaseReplicationMutationShared(&replication_mutation);
    try deferred_replication_gates.waitForDurabilityAndAuthority(ctx.replication_write_gate);
    try primary_replication.clear(ctx);
    try applyDerivedBacklogPressureContext(ctx, sequence, .full_index, sync_targets);
    if (ctx.executor.hasWorkers()) {
        notifyExecutorForSyncLevelWithDenseBulkDeferral(ctx.async_context, ctx.executor, .full_index, sequence, sync_targets);
        try waitForSyncLevelContext(ctx, .full_index, sequence, sync_targets);
    } else {
        try lockApplyForPortableRuntimeContext(ctx);
        defer ctx.apply_mutex.unlockExclusive();
        try applyDerivedBatchContext(ctx, derived_batch);
    }
    return true;
}

/// Remove exactly one expired source contribution. The contender, winner,
/// tombstone, lifetime and replay record commit together. A changed candidate
/// or winner input is retried by the worker instead of deleting a newer source.
fn expireGraphTtlCandidateContext(ttl_ctx: *TtlCleanupContext, candidate: GraphTtlCandidate) !bool {
    const ctx = &ttl_ctx.batch;
    if (!internal_keys.isGraphEdgeArtifactKey(candidate.edge_key) or
        !internal_keys.matchesGraphEdgeIndexName(candidate.edge_key, candidate.index_name) or
        candidate.generation == 0 or candidate.deadline_ns == 0)
        return error.InvalidGraphTtlCandidate;
    var replication_mutation = acquireReplicationMutationSharedContext(ctx);
    defer if (replication_mutation) |*lease| lease.release();
    try enforceReplicationWriteGateContext(ctx);
    var snapshot_mutation = acquireSnapshotMutationContext(ctx);
    defer if (snapshot_mutation) |*lease| lease.release();
    try lockApplyForPortableRuntimeContext(ctx);
    var apply_mutex_held = true;
    errdefer if (apply_mutex_held) ctx.apply_mutex.unlockExclusive();
    var graph_publication = ctx.index_manager.beginGraphPrimaryMutation();
    defer graph_publication.release();
    try enforceReplicationWriteGateContext(ctx);

    const graph_entry = ctx.index_manager.graphIndex(candidate.index_name) orelse {
        ctx.apply_mutex.unlockExclusive();
        return false;
    };
    const duration_ns = graph_entry.ttl_duration_ns;
    if (duration_ns == 0 or graph_entry.config.coverage_generation != candidate.generation) {
        ctx.apply_mutex.unlockExclusive();
        return false;
    }
    // A revision admitted before retirement must inherit the existing lifetime.
    // Certifying an older materialized revision while that input is queued would
    // let later replay start a fresh lifetime, depending on worker progress.
    // Pin the committed replay tip under apply/publication and defer until this
    // incarnation has reconciled it. Do not wait for workers while holding locks.
    // Sequence allocation can run ahead of committed replay after a failed
    // mutation. Only durable replay metadata creates reconciliation debt.
    const source_tip = blk: {
        var replay_snapshot = try ctx.store.beginReadTxn();
        defer replay_snapshot.abort();
        break :blk try ctx.store.lastReplaySequenceFromTxn(&replay_snapshot, 0);
    };
    const source_applied = loadManagedAppliedSequenceContext(ctx.alloc, ctx.index_manager, ctx.store, ctx.applied_sequence_checkpoint_path, .{ .name = candidate.index_name, .kind = .graph }) catch |err| switch (err) {
        error.InvalidDerivedApplyState => 0,
        else => return err,
    };
    if (source_applied < source_tip) {
        ctx.executor.notifySequence(source_tip);
        ctx.apply_mutex.unlockExclusive();
        return false;
    }
    const doc_key = (try internal_keys.decodeDocumentComponentAlloc(ctx.alloc, candidate.edge_key)) orelse return error.InvalidGraphTtlCandidate;
    defer ctx.alloc.free(doc_key);
    if (!ctx.index_manager.byte_range.contains(doc_key)) {
        ctx.apply_mutex.unlockExclusive();
        return false;
    }
    {
        var lifecycle = try ctx.store.beginReadTxn();
        defer lifecycle.abort();
        try @import("relational_integrity_topology.zig").requireUnfenced(&lifecycle);
        try @import("relational_integrity_retirement.zig").requireMutable(&lifecycle);
        try @import("restore_staging.zig").requireScope(ctx.alloc, &lifecycle, null, false);
    }
    var txn_manager = try transactions_mod.TxnManager.init(ctx.alloc, ctx.store);
    defer txn_manager.deinit();
    txn_manager.checkOrdinaryWriteConflict(doc_key) catch |err| switch (err) {
        error.IntentConflict => {
            ctx.apply_mutex.unlockExclusive();
            return false;
        },
        else => return err,
    };
    const contender_key = try internal_keys.graphGlobalEdgeContenderKeyAlloc(ctx.alloc, candidate.index_name, candidate.generation, candidate.edge_key, candidate.source_priority, candidate.state_key);
    defer ctx.alloc.free(contender_key);
    const expiration_key = try graph_edge_ttl_expiration.indexKeyAlloc(ctx.alloc, candidate.deadline_ns, contender_key);
    defer ctx.alloc.free(expiration_key);
    const contender_raw = try graphTtlOptionalStoreValue(ctx.alloc, ctx.store, contender_key) orelse {
        ctx.apply_mutex.unlockExclusive();
        return false;
    };
    defer ctx.alloc.free(contender_raw);
    var contender_digest: [32]u8 = undefined;
    GraphTtlSha256.hash(contender_raw, &contender_digest, .{});
    if (!std.mem.eql(u8, &contender_digest, &candidate.contender_digest)) {
        ctx.apply_mutex.unlockExclusive();
        return false;
    }
    const contender = (try graph_edge_contender.decode(contender_raw, candidate.generation)) orelse return error.InvalidGraphTtlCandidate;
    if (!std.mem.eql(u8, contender.edge_key, candidate.edge_key) or
        !std.mem.eql(u8, contender.state_key, candidate.state_key) or
        contender.source_priority != candidate.source_priority)
        return error.InvalidGraphTtlCandidate;
    var edge = try enrichment_artifact_codec.decodeGraphEdgeAlloc(ctx.alloc, contender.payload);
    defer edge.deinit(ctx.alloc);
    if (edge.ttl_created_ns == 0) return error.GraphEdgeTtlMigrationRequired;
    const deadline_ns = std.math.add(u64, edge.ttl_created_ns, duration_ns) catch std.math.maxInt(u64);
    if (deadline_ns != candidate.deadline_ns or
        !ttl_mod.isExpiredWithGrace(edge.ttl_created_ns, duration_ns, ttl_ctx.grace_period_ns, ttl_ctx.clock.nowRealtimeNs()))
    {
        ctx.apply_mutex.unlockExclusive();
        return false;
    }

    const global_prefix = try internal_keys.graphGlobalEdgeContenderEdgePrefixAlloc(ctx.alloc, candidate.index_name, candidate.generation, candidate.edge_key);
    defer ctx.alloc.free(global_prefix);
    const local_prefix = try internal_keys.graphEdgeContenderEdgePrefixAlloc(ctx.alloc, doc_key, candidate.index_name, candidate.edge_key);
    defer ctx.alloc.free(local_prefix);
    const count_key = try internal_keys.graphEdgeContenderCountKeyAlloc(ctx.alloc, doc_key, candidate.index_name);
    defer ctx.alloc.free(count_key);
    const lifetime_key = try internal_keys.graphEdgeTtlLifetimeKeyAlloc(ctx.alloc, candidate.edge_key, candidate.index_name, candidate.generation, candidate.state_key);
    defer ctx.alloc.free(lifetime_key);
    const tombstone_key = try internal_keys.graphEdgeTtlTombstoneKeyAlloc(ctx.alloc, candidate.edge_key, candidate.index_name, candidate.generation, candidate.state_key);
    defer ctx.alloc.free(tombstone_key);
    const count_raw = try graphTtlOptionalStoreValue(ctx.alloc, ctx.store, count_key);
    defer if (count_raw) |value| ctx.alloc.free(value);
    const edge_raw = try graphTtlOptionalStoreValue(ctx.alloc, ctx.store, candidate.edge_key);
    defer if (edge_raw) |value| ctx.alloc.free(value);
    const lifetime_raw = try graphTtlOptionalStoreValue(ctx.alloc, ctx.store, lifetime_key);
    defer if (lifetime_raw) |value| ctx.alloc.free(value);
    const tombstone_raw = try graphTtlOptionalStoreValue(ctx.alloc, ctx.store, tombstone_key);
    defer if (tombstone_raw) |value| ctx.alloc.free(value);
    if (lifetime_raw) |raw| {
        if (raw.len != 8 or std.mem.readInt(u64, raw[0..8], .big) != edge.ttl_created_ns)
            return error.InvalidGraphEdgeTtlLifetime;
    }
    if (tombstone_raw != null) return error.InvalidGraphEdgeTtlTombstone;
    const global_snapshot = try GraphContenderPrefixFingerprint.fromStore(ctx.alloc, ctx.store, global_prefix);
    const local_snapshot = try GraphContenderPrefixFingerprint.fromStore(ctx.alloc, ctx.store, local_prefix);
    const source_digest = try graph_edge_ttl_tombstone.sourceDigest(ctx.alloc, contender.payload);
    const tombstone_value = (graph_edge_ttl_tombstone.Tombstone{ .deadline_ns = deadline_ns, .source_digest = source_digest }).encode();
    var reconciled = try reconcileSingleGraphStateContenders(
        ctx.alloc,
        ctx.store,
        doc_key,
        candidate.index_name,
        candidate.state_key,
        &.{candidate.edge_key},
        &.{},
        ctx.index_manager.graphArtifactSources(candidate.index_name),
        candidate.generation,
        duration_ns,
    );
    defer reconciled.deinit(ctx.alloc);
    var mutation = try prepareGraphContenderReconcilePage(
        ctx.alloc,
        &.{candidate.edge_key},
        &reconciled,
        &.{.{ .key = tombstone_key, .value = &tombstone_value }},
        &.{ lifetime_key, expiration_key },
    );
    defer mutation.deinit(ctx.alloc);
    var guard = GraphTtlCommitGuard{
        .contender_key = contender_key,
        .contender_digest = contender_digest,
        .global_prefix = global_prefix,
        .global_fingerprint = global_snapshot,
        .local_prefix = local_prefix,
        .local_fingerprint = local_snapshot,
        .count_key = count_key,
        .count_raw = count_raw,
        .edge_key = candidate.edge_key,
        .edge_raw = edge_raw,
        .lifetime_key = lifetime_key,
        .lifetime_raw = lifetime_raw,
        .tombstone_key = tombstone_key,
        .tombstone_raw = tombstone_raw,
        .created_ns = edge.ttl_created_ns,
        .duration_ns = duration_ns,
        .grace_ns = ttl_ctx.grace_period_ns,
        .clock = ttl_ctx.clock,
    };
    var derived_batch = try buildDerivedBatch(ctx.alloc, .{ .sync_level = .full_index }, &.{}, &.{}, &.{@constCast(candidate.edge_key)});
    defer derived_types.deinitDerivedBatch(ctx.alloc, &derived_batch);
    var sync_targets = try collectManagedSyncTargets(ctx.alloc, ctx.index_manager, derived_batch);
    defer sync_targets.deinit(ctx.alloc);
    const sequence = ctx.store.reserveNextReplaySequence(1);
    derived_batch.sequence = sequence;
    const replay_payload = try encodeChangeRecordPayload(ctx, derived_batch, sequence);
    defer ctx.alloc.free(replay_payload);
    var primary_replication = try PrimaryReplicationEffect.prepareGraphRetirement(ctx, .{ .candidate = candidate, .source_digest = source_digest }, replay_payload);
    defer primary_replication.deinit(ctx.alloc);
    var primary_writes: std.ArrayListUnmanaged(docstore_mod.KVPair) = .empty;
    defer primary_writes.deinit(ctx.alloc);
    try primary_writes.appendSlice(ctx.alloc, mutation.writes.items);
    try primary_replication.stage(ctx, &primary_writes);
    var backlog_admission = try ctx.executor.admitBacklogBytes(@intCast(replay_payload.len));
    defer backlog_admission.cancel();
    _ = ctx.store.putBatchWithPromotionsReplayAndBuiltWrite(
        ctx.io,
        primary_writes.items,
        mutation.deletes.items,
        &.{},
        .{ .sequence = sequence, .payload = replay_payload },
        null,
        .{ .ptr = &guard, .validate = GraphTtlCommitGuard.validate, .validate_at_commit = GraphTtlCommitGuard.validateAtCommit },
    ) catch |err| switch (err) {
        error.GraphTtlCandidateChanged, error.GraphTtlCandidateNotDue => {
            ctx.apply_mutex.unlockExclusive();
            apply_mutex_held = false;
            return false;
        },
        else => return err,
    };
    graph_publication.release();
    ctx.executor.commitBacklogAdmission(sequence, &backlog_admission);
    var deferred_replication_gates = ReplicationDeferredCommitGates.begin(replicationTransitionMutexFromContext(ctx));
    defer deferred_replication_gates.releaseTransition();
    deferred_replication_gates.append(try primary_replication.appendLocked(ctx));
    ctx.apply_mutex.unlockExclusive();
    apply_mutex_held = false;
    if (snapshot_mutation) |*lease| lease.release();
    snapshot_mutation = null;
    DB.notifyQueryVisibilityTargetAdvancedScopedContext(ctx, sequence, sync_targets);
    releaseReplicationMutationShared(&replication_mutation);
    try deferred_replication_gates.waitForDurabilityAndAuthority(ctx.replication_write_gate);
    try primary_replication.clear(ctx);
    try applyDerivedBacklogPressureContext(ctx, sequence, .full_index, sync_targets);
    if (ctx.executor.hasWorkers()) {
        notifyExecutorForSyncLevelWithDenseBulkDeferral(ctx.async_context, ctx.executor, .full_index, sequence, sync_targets);
        try waitForSyncLevelContext(ctx, .full_index, sequence, sync_targets);
    } else {
        try lockApplyForPortableRuntimeContext(ctx);
        defer ctx.apply_mutex.unlockExclusive();
        try applyDerivedBatchContext(ctx, derived_batch);
    }
    return true;
}

fn appendDerivedBatchRecord(self: *DB, batch: derived_types.DerivedBatch) !u64 {
    var ctx = self.batchContext();
    return try appendDerivedBatchRecordContext(&ctx, batch);
}

fn appendDerivedBatchRecordContext(ctx: *const BatchExecutionContext, batch: derived_types.DerivedBatch) !u64 {
    return appendDerivedBatchRecordContextWithProducerFence(ctx, batch, false);
}

fn appendDerivedBatchRecordContextWithProducerFence(ctx: *const BatchExecutionContext, batch: derived_types.DerivedBatch, producer: bool) !u64 {
    return appendDerivedBatchRecordContextWithWork(ctx, batch, producer, null);
}

const RequiredProducerDispatch = struct {
    authority: @import("artifact_publication.zig").Authority,
    item: @import("artifact_producer_obligations.zig").WorkPage.Item,
    plan_generation: u64,
    page: @import("artifact_producer_obligations.zig").Dispatch,
    retry_round: ?u64 = null,
};

fn appendDerivedBatchRecordContextWithWork(ctx: *const BatchExecutionContext, batch: derived_types.DerivedBatch, producer: bool, work: ?RequiredProducerDispatch) !u64 {
    return appendDerivedBatchRecordContextWithAdmissions(ctx, batch, producer, work, null);
}

const RequiredUnitProducerDispatch = struct {
    admission: *const @import("artifact_unit_jobs.zig").Admission,
    root: u128,
    plan_generation: u64,
};

fn requireProducerRequestsOnly(batch: derived_types.DerivedBatch) !void {
    const requests_only: derived_types.DerivedBatch = .{ .generated_enrichment_refs = batch.generated_enrichment_refs };
    if (batch.generated_enrichment_refs.len == 0) return error.InvalidBatchRequest;
    inline for (comptime std.meta.fieldNames(derived_types.DerivedBatch)) |reflected_name| {
        if (comptime !std.mem.eql(u8, reflected_name, "generated_enrichment_refs")) {
            if (!std.meta.eql(@field(batch, reflected_name), @field(requests_only, reflected_name))) return error.InvalidBatchRequest;
        }
    }
}

fn appendDerivedBatchRecordContextWithAdmissions(ctx: *const BatchExecutionContext, batch: derived_types.DerivedBatch, producer: bool, work: ?RequiredProducerDispatch, unit_work: ?RequiredUnitProducerDispatch) !u64 {
    if (work != null and unit_work != null) return error.InvalidBatchRequest;
    var sync_targets = try collectManagedSyncTargets(ctx.alloc, ctx.index_manager, batch);
    defer sync_targets.deinit(ctx.alloc);
    var replication_mutation = acquireReplicationMutationSharedContext(ctx);
    defer if (replication_mutation) |*lease| lease.release();
    try enforceReplicationWriteGateContext(ctx);
    var snapshot_replay = try acquireSnapshotReplayContext(ctx);
    defer if (snapshot_replay) |*lease| lease.release();
    try lockApplyForPortableRuntimeContext(ctx);
    var apply_mutex_held = true;
    errdefer if (apply_mutex_held) ctx.apply_mutex.unlockExclusive();
    if (producer) try requireArtifactProducerMutableContext(ctx);
    if (work) |required| if (ctx.index_manager.writePlanGeneration() != required.plan_generation) return error.EnrichmentSourceChanged;
    if (unit_work) |required| if (ctx.index_manager.writePlanGeneration() != required.plan_generation) return error.EnrichmentSourceChanged;
    if (work != null or unit_work != null) try requireProducerRequestsOnly(batch);
    if (unit_work) |required| {
        if (required.admission.jobs.len == 0 or batch.generated_enrichment_refs.len != 1 or
            !std.mem.eql(u8, batch.generated_enrichment_refs[0].doc_key, required.admission.page.document)) return error.InvalidBatchRequest;
    }
    try enforceReplicationWriteGateContext(ctx);
    const sequence = ctx.store.reserveNextReplaySequence(1);
    const payload = try encodeChangeRecordPayload(ctx, batch, sequence);
    defer ctx.alloc.free(payload);
    var backlog_admission = try ctx.executor.admitBacklogBytes(@intCast(payload.len));
    defer backlog_admission.cancel();
    if (work) |required| {
        const Guard = struct {
            required: RequiredProducerDispatch,
            sequence: u64,
            pub fn validate(ptr: *anyopaque, alloc: Allocator, txn: *docstore_mod.DocStore.Batch.BatchTxn) !void {
                const self: *@This() = @ptrCast(@alignCast(ptr));
                const accepted = if (self.required.retry_round) |round|
                    try @import("artifact_producer_obligations.zig").stageRetry(alloc, txn, self.required.authority, self.required.item, round, self.sequence, self.required.page)
                else
                    try @import("artifact_producer_obligations.zig").stageDispatch(alloc, txn, self.required.authority, self.required.item, self.sequence, self.required.page);
                if (!accepted) return error.EnrichmentSourceChanged;
            }
        };
        // This path only appends producer requests. It must never bypass
        // authored artifact mutation capture or its ordered authority check.
        const first = if (required.retry_round) |round| (if (required.item.retry_round == round) required.item.retry_next_template else 0) else required.item.next_template;
        if (required.page.next_template <= first or batch.generated_enrichment_refs.len > required.page.next_template - first or
            (required.retry_round == null and required.page.next_template - first != batch.generated_enrichment_refs.len)) return error.InvalidBatchRequest;
        var guard: Guard = .{ .required = required, .sequence = sequence };
        _ = try ctx.store.putBatchWithPromotionsReplayAndBuiltWrite(ctx.io, &.{}, &.{}, &.{}, .{ .sequence = sequence, .payload = payload }, null, .{ .ptr = &guard, .validate = Guard.validate });
    } else if (unit_work) |required| {
        const Guard = struct {
            required: RequiredUnitProducerDispatch,
            pub fn validate(ptr: *anyopaque, _: Allocator, txn: *docstore_mod.DocStore.Batch.BatchTxn) !void {
                const self: *@This() = @ptrCast(@alignCast(ptr));
                _ = try self.required.admission.stage(txn, self.required.root);
            }
        };
        var guard: Guard = .{ .required = required };
        _ = try ctx.store.putBatchWithPromotionsReplayAndBuiltWrite(ctx.io, &.{}, &.{}, &.{}, .{ .sequence = sequence, .payload = payload }, null, .{ .ptr = &guard, .validate = Guard.validate });
    } else try appendReplayWithArtifactSourceRevisionsContext(ctx, payload, sequence);
    ctx.executor.commitBacklogAdmission(sequence, &backlog_admission);
    var deferred_replication_gates = ReplicationDeferredCommitGates.begin(replicationTransitionMutexFromContext(ctx));
    defer deferred_replication_gates.releaseTransition();
    deferred_replication_gates.append(try appendReplicationReplayPayloadCommitLockedContext(ctx, payload));
    ctx.apply_mutex.unlockExclusive();
    apply_mutex_held = false;
    if (snapshot_replay) |*lease| lease.release();
    snapshot_replay = null;
    DB.notifyQueryVisibilityTargetAdvancedScopedContext(ctx, sequence, sync_targets);
    releaseReplicationMutationShared(&replication_mutation);
    try deferred_replication_gates.waitForDurabilityAndAuthority(ctx.replication_write_gate);
    return sequence;
}

/// Apply a primary-certified retirement to this replica's materialized view.
/// Only the source revision is authoritative; local progress determines the
/// count delta and fallback winner. No wall-clock TTL decision is repeated.
fn prepareReplicatedGraphRetirement(ctx: *const BatchExecutionContext, retirement: replication_effects_mod.primary_effect.GraphRetirement) !GraphContenderMutation {
    const candidate = retirement.candidate;
    const entry = ctx.index_manager.graphIndex(candidate.index_name) orelse return error.IndexNotFound;
    if (entry.config.coverage_generation != candidate.generation or entry.ttl_duration_ns == 0) return error.InvalidGraphTtlCandidate;
    const owner = (try internal_keys.decodeDocumentComponentAlloc(ctx.alloc, candidate.edge_key)) orelse return error.InvalidGraphTtlCandidate;
    defer ctx.alloc.free(owner);
    const contender_key = try internal_keys.graphGlobalEdgeContenderKeyAlloc(ctx.alloc, candidate.index_name, candidate.generation, candidate.edge_key, candidate.source_priority, candidate.state_key);
    defer ctx.alloc.free(contender_key);
    const current = try graphTtlOptionalStoreValue(ctx.alloc, ctx.store, contender_key);
    defer if (current) |raw| ctx.alloc.free(raw);
    const tombstone_key = try internal_keys.graphEdgeTtlTombstoneKeyAlloc(ctx.alloc, candidate.edge_key, candidate.index_name, candidate.generation, candidate.state_key);
    defer ctx.alloc.free(tombstone_key);
    const tombstone = (graph_edge_ttl_tombstone.Tombstone{ .deadline_ns = candidate.deadline_ns, .source_digest = retirement.source_digest }).encode();
    if (current) |raw| {
        const view = (try graph_edge_contender.decode(raw, candidate.generation)) orelse return error.InvalidGraphEdgeContender;
        if (!std.mem.eql(u8, view.edge_key, candidate.edge_key) or !std.mem.eql(u8, view.state_key, candidate.state_key) or view.source_priority != candidate.source_priority) return error.InvalidGraphEdgeContender;
        const digest = try graph_edge_ttl_tombstone.sourceDigest(ctx.alloc, view.payload);
        if (!std.mem.eql(u8, &digest, &retirement.source_digest)) {
            // Keep a different materialized revision intact, but record the
            // certified retirement even when this replica still has the older
            // source. Delayed replay of the retired revision must be suppressed.
            const unchanged = GraphContenderReconcileResult{};
            return prepareGraphContenderReconcilePage(ctx.alloc, &.{}, &unchanged, &.{.{ .key = tombstone_key, .value = &tombstone }}, &.{});
        }
    }
    const lifetime_key = try internal_keys.graphEdgeTtlLifetimeKeyAlloc(ctx.alloc, candidate.edge_key, candidate.index_name, candidate.generation, candidate.state_key);
    defer ctx.alloc.free(lifetime_key);
    const due_key = try graph_edge_ttl_expiration.indexKeyAlloc(ctx.alloc, candidate.deadline_ns, contender_key);
    defer ctx.alloc.free(due_key);
    var reconciled = try reconcileSingleGraphStateContenders(ctx.alloc, ctx.store, owner, candidate.index_name, candidate.state_key, &.{candidate.edge_key}, &.{}, ctx.index_manager.graphArtifactSources(candidate.index_name), candidate.generation, entry.ttl_duration_ns);
    defer reconciled.deinit(ctx.alloc);
    return prepareGraphContenderReconcilePage(ctx.alloc, &.{candidate.edge_key}, &reconciled, &.{.{ .key = tombstone_key, .value = &tombstone }}, &.{ lifetime_key, due_key });
}

fn appendReplicatedDerivedEffectContext(ctx: *const BatchExecutionContext, change: change_journal_mod.Record, primary: ?replication_effects_mod.primary_effect.View, applied_sequence: u64) !u64 {
    var snapshot_mutation = acquireSnapshotMutationContext(ctx);
    defer if (snapshot_mutation) |*lease| lease.release();
    var snapshot_replay = try acquireSnapshotReplayContext(ctx);
    defer if (snapshot_replay) |*lease| lease.release();
    try lockApplyForPortableRuntimeContext(ctx);
    defer ctx.apply_mutex.unlockExclusive();
    // Receipt and authoritative effects commit together. Retrying a delivered
    // effect must never roll back newer contributor state or append replay twice.
    if (applied_sequence != 0 and try readReplicationAppliedSequence(ctx.alloc, ctx.store) >= applied_sequence) return 0;
    var graph_publication = if (primary != null and ctx.index_manager.hasGraphIndexes()) ctx.index_manager.beginGraphPrimaryMutation() else null;
    defer if (graph_publication) |*lease| lease.release();
    var decoded_record = change;

    const sequence = ctx.store.reserveNextReplaySequence(1);
    decoded_record.sequence = sequence;
    const payload = try change_journal_mod.encodeRecord(ctx.alloc, decoded_record);
    defer ctx.alloc.free(payload);

    var backlog_admission = try ctx.executor.admitBacklogBytes(@intCast(payload.len));
    defer backlog_admission.cancel();
    var writes: std.ArrayListUnmanaged(docstore_mod.KVPair) = .empty;
    defer writes.deinit(ctx.alloc);
    var owned_keys: std.ArrayListUnmanaged([]u8) = .empty;
    defer {
        for (owned_keys.items) |key| ctx.alloc.free(key);
        owned_keys.deinit(ctx.alloc);
    }
    var owned_values: std.ArrayListUnmanaged([]u8) = .empty;
    defer {
        for (owned_values.items) |value| ctx.alloc.free(value);
        owned_values.deinit(ctx.alloc);
    }
    var deletes: std.ArrayListUnmanaged([]const u8) = .empty;
    defer deletes.deinit(ctx.alloc);
    var owned_deletes: std.ArrayListUnmanaged([]u8) = .empty;
    defer {
        for (owned_deletes.items) |key| ctx.alloc.free(key);
        owned_deletes.deinit(ctx.alloc);
    }
    var graph_mutation: ?GraphContenderMutation = null;
    defer if (graph_mutation) |*mutation| mutation.deinit(ctx.alloc);
    if (primary) |effect| {
        for (effect.writes) |write| try writes.append(ctx.alloc, .{ .key = write.key, .value = write.value });
        try deletes.appendSlice(ctx.alloc, effect.deletes);
        if (effect.graph_retirement) |retirement| {
            graph_mutation = try prepareReplicatedGraphRetirement(ctx, retirement);
            try writes.appendSlice(ctx.alloc, graph_mutation.?.writes.items);
            try deletes.appendSlice(ctx.alloc, graph_mutation.?.deletes.items);
        }
        // A standby can have materialized more owner artifacts than the primary.
        // Retire its complete local owner state in the same receipt transaction.
        var artifact_deletes: std.ArrayListUnmanaged([]u8) = .empty;
        defer artifact_deletes.deinit(ctx.alloc);
        var selected_artifacts = std.StringHashMapUnmanaged(void).empty;
        defer selected_artifacts.deinit(ctx.alloc);
        for (decoded_record.deleted_doc_keys) |owner| try collectEnrichmentArtifactDeleteKeysForDocContext(ctx.alloc, ctx.store, owner, &deletes, &owned_deletes, &artifact_deletes, &selected_artifacts);
        try appendAssetArtifactSourceIndexMutations(ctx.alloc, &writes, artifact_deletes.items, &deletes, &owned_keys, &owned_values, &owned_deletes);
        try appendRetiredDirectGraphTtlDueDeletes(ctx.alloc, ctx.store, ctx.index_manager, writes.items, deletes.items, &deletes, &owned_deletes);
    }
    try appendArtifactSourceRevisionWritesFromReplay(ctx.alloc, payload, sequence, &writes, &owned_keys, &owned_values);
    const summary = try doc_identity.visibilitySummaryFromWrites(writes.items);
    var catalog: ?table_catalog_mod.Catalog = null;
    for (writes.items) |write| if (std.mem.eql(u8, write.key, table_catalog_mod.key)) {
        catalog = try table_catalog_mod.Catalog.decode(write.value);
    };
    var marker: [replication_applied_lsn_value_len]u8 = undefined;
    if (applied_sequence != 0) try writes.append(ctx.alloc, replicationAppliedSequenceWrite(applied_sequence, &marker));
    try ctx.store.putBatchWithReplay(ctx.io, writes.items, deletes.items, .{ .sequence = sequence, .payload = payload });
    if (graph_publication) |*lease| lease.release();
    if (summary) |value| if (ctx.identity_visibility) |visibility| visibility.publish(value);
    if (catalog) |value| if (ctx.table_catalog) |current| {
        current.* = value;
    };
    ctx.executor.commitBacklogAdmission(sequence, &backlog_admission);
    DB.notifyQueryVisibilityTargetAdvancedContext(ctx, sequence);
    return sequence;
}

fn appendReplayWithArtifactSourceRevisionsContext(ctx: *const BatchExecutionContext, payload: []const u8, sequence: u64) !void {
    var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer writes.deinit(ctx.alloc);
    var owned_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_keys.items) |key| ctx.alloc.free(key);
        owned_keys.deinit(ctx.alloc);
    }
    var owned_values = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_values.items) |value| ctx.alloc.free(value);
        owned_values.deinit(ctx.alloc);
    }
    try appendArtifactSourceRevisionWritesFromReplay(
        ctx.alloc,
        payload,
        sequence,
        &writes,
        &owned_keys,
        &owned_values,
    );
    try ctx.store.putBatchWithReplay(
        ctx.io,
        writes.items,
        &.{},
        .{ .sequence = sequence, .payload = payload },
    );
}

fn encodeChangeRecordPayload(ctx: *const BatchExecutionContext, batch: derived_types.DerivedBatch, sequence: u64) ![]u8 {
    return try encodeChangeRecordPayloadWithTargetHints(ctx, batch, sequence, null);
}

fn encodeChangeRecordPayloadWithTargetHints(
    ctx: *const BatchExecutionContext,
    batch: derived_types.DerivedBatch,
    sequence: u64,
    target_hints: ?[]const change_journal_mod.TargetHint,
) ![]u8 {
    var record = if (target_hints) |hints|
        try change_journal_mod.recordFromDerivedBatchWithTargetHints(ctx.alloc, batch, sequence, hints)
    else
        try change_journal_mod.recordFromDerivedBatch(ctx.alloc, batch, sequence);
    defer change_journal_mod.deinitRecord(ctx.alloc, &record);
    // Ordered graph publication encodes while the previous primary snapshot is
    // still visible. Persist lost and gained endpoint work with its effects.
    if (batch.graph_writes.len != 0 or batch.graph_deletes.len != 0) {
        var hints = try directGraphNeighborContextHintsAlloc(ctx.alloc, .{ .graph_deletes = batch.graph_deletes }, batch.graph_writes, &.{}, ctx.index_manager, null);
        defer hints.deinit(ctx.alloc);
        try appendNeighborContextHintsToRecord(ctx, &record, hints.keys);
    }

    return try change_journal_mod.encodeRecord(ctx.alloc, record);
}

