fn beginDenseCatchUpSessionTracked(ctx: *AsyncContext, index_name: []const u8) !void {
    _ = index_name;
    var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
    defer session_lock.unlock();
    try ctx.dense_admission.beginReplayLocked();
    ctx.text_merge_deferred.store(true, .release);
    ctx.stats.dense_catch_up.active.store(1, .monotonic);
    ctx.stats.dense_catch_up.phase.store(@backingInt(types.DenseCatchUpStats.Phase.replay), .monotonic);
    if (ctx.resource_manager) |manager| manager.beginLatencySensitiveDerivedReplay();
}

fn finishDenseCatchUpSessionLocked(ctx: *AsyncContext, index_name: []const u8) bool {
    const remaining = ctx.dense_admission.finishReplayLocked() orelse {
        std.log.warn("dense catch-up session finish without active session index={s}", .{index_name});
        return false;
    };
    if (ctx.resource_manager) |manager| manager.finishLatencySensitiveDerivedReplay();
    if (remaining == 0) {
        ctx.stats.dense_catch_up.active.store(0, .monotonic);
        ctx.stats.dense_catch_up.phase.store(@backingInt(types.DenseCatchUpStats.Phase.idle), .monotonic);
        ctx.stats.dense_catch_up.bulk_finish_current_window.store(0, .monotonic);
        ctx.stats.dense_catch_up.bulk_finish_current_window_split_steps.store(0, .monotonic);
        ctx.stats.dense_catch_up.bulk_finish_deferred_leaf_splits.store(0, .monotonic);
        ctx.stats.dense_catch_up.bulk_finish_current_window_ns.store(0, .monotonic);
    }
    return true;
}

fn finishDenseCatchUpSessionTrackingOnly(ctx: *AsyncContext, index_name: []const u8) bool {
    var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
    const finished = finishDenseCatchUpSessionLocked(ctx, index_name);
    session_lock.unlock();
    return finished;
}

fn finishDenseCatchUpSessionTracked(ctx: *AsyncContext, index_name: []const u8) void {
    const finished = finishDenseCatchUpSessionTrackingOnly(ctx, index_name);
    if (finished) resumeDeferredBackgroundMaintenanceIfIdle(ctx);
}

fn beginExternalDenseBulkSessionTracked(ctx: *AsyncContext) !void {
    var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
    defer session_lock.unlock();
    try ctx.dense_admission.beginExternalLocked();
    ctx.text_merge_deferred.store(true, .release);
}

fn beginExternalDenseBulkSessionTrackedWait(ctx: *AsyncContext, io: ?std.Io) !void {
    const wait_start_ns = monotonicTimeNs();
    const wait_timeout_ns = 30 * std.time.ns_per_s;
    {
        var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
        defer session_lock.unlock();
        ctx.dense_admission.beginWaitLocked();
    }
    var admitted = false;
    defer {
        if (!admitted) {
            var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
            ctx.dense_admission.cancelWaitLocked();
            session_lock.unlock();

            const completed = finalizeCoveredDenseProjectionCheckpointsIfIdle(ctx) catch |err| blk: {
                std.log.err("dense external bulk admission cleanup failed error={s}", .{@errorName(err)});
                DB.notifyQueryVisibilityHook(ctx, .index_repair_pending);
                break :blk false;
            };
            if (completed) DB.notifyQueryVisibilityHook(ctx, .publish_blocking);
            resumeDeferredBackgroundMaintenanceIfIdle(ctx);
        }
    }

    var wait_ms: u64 = 1;
    while (true) {
        var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
        if (ctx.dense_admission.admitWaiterLocked()) {
            ctx.text_merge_deferred.store(true, .release);
            admitted = true;
            session_lock.unlock();
            return;
        }
        session_lock.unlock();
        if (elapsedSince(wait_start_ns) >= wait_timeout_ns) return error.WriterLocked;
        if (io) |runtime_io| {
            runtime_io.sleep(std.Io.Duration.fromMilliseconds(@intCast(wait_ms)), .awake) catch return error.WriterLocked;
        } else if (comptime builtin.os.tag == .freestanding) {
            return error.WriterLocked;
        } else {
            sleepNs(wait_ms * std.time.ns_per_ms);
        }
        wait_ms = @min(wait_ms * 2, 16);
    }
}

fn finishExternalDenseBulkSessionLocked(ctx: *AsyncContext) bool {
    if (ctx.dense_admission.finishExternalLocked()) return true;
    std.log.warn("dense external bulk session finish without active session", .{});
    return false;
}

fn finishExternalDenseBulkSessionTrackingOnly(ctx: *AsyncContext) bool {
    var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
    const finished = finishExternalDenseBulkSessionLocked(ctx);
    session_lock.unlock();
    return finished;
}

fn finishExternalDenseBulkSessionTracked(ctx: *AsyncContext) void {
    const finished = finishExternalDenseBulkSessionTrackingOnly(ctx);
    if (finished) resumeDeferredBackgroundMaintenanceIfIdle(ctx);
}

fn finishDenseCatchUpSessionTrackedAndFinalize(ctx: *AsyncContext, index_name: []const u8) !bool {
    var finished = false;
    errdefer if (finished) resumeDeferredBackgroundMaintenanceIfIdle(ctx);
    const completed = blk: {
        lockApplySharedForPortableRuntimeAsync(ctx) catch |err| {
            // Tracking is process-local lifecycle state, not restored-catalog
            // state. Always release it even when catalog finalization must wait
            // for activation recovery.
            _ = finishDenseCatchUpSessionTrackingOnly(ctx, index_name);
            return err;
        };
        defer ctx.apply_mutex.unlockShared();
        var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
        finished = finishDenseCatchUpSessionLocked(ctx, index_name);
        const claimed = finished and tryClaimOrRequestDenseProjectionFinalizationLocked(ctx);
        session_lock.unlock();
        if (!claimed) break :blk false;
        errdefer finishDenseProjectionFinalization(ctx);
        break :blk try drainClaimedDenseProjectionFinalizations(ctx);
    };
    if (finished) resumeDeferredBackgroundMaintenanceIfIdle(ctx);
    return completed;
}

fn finishExternalDenseBulkSessionTrackedAndFinalize(ctx: *AsyncContext) !bool {
    var finished = false;
    errdefer if (finished) resumeDeferredBackgroundMaintenanceIfIdle(ctx);
    const completed = blk: {
        lockApplySharedForPortableRuntimeAsync(ctx) catch |err| {
            _ = finishExternalDenseBulkSessionTrackingOnly(ctx);
            return err;
        };
        defer ctx.apply_mutex.unlockShared();
        var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
        finished = finishExternalDenseBulkSessionLocked(ctx);
        const claimed = finished and tryClaimOrRequestDenseProjectionFinalizationLocked(ctx);
        session_lock.unlock();
        if (!claimed) break :blk false;
        errdefer finishDenseProjectionFinalization(ctx);
        break :blk try drainClaimedDenseProjectionFinalizations(ctx);
    };
    if (finished) resumeDeferredBackgroundMaintenanceIfIdle(ctx);
    return completed;
}

fn finishDenseCatchUpSessionTrackedBestEffort(ctx: *AsyncContext, index_name: []const u8) void {
    const completed = finishDenseCatchUpSessionTrackedAndFinalize(ctx, index_name) catch |err| {
        // The tracking lease was released before this error. Activation owns
        // catalog recovery and status reporting, so do not manufacture an
        // unrelated index-repair incident for an expected degraded window.
        if (err == error.PortableRuntimeActivationPending) return;
        std.log.err("dense catch-up idle finalization failed index={s} error={s}", .{ index_name, @errorName(err) });
        DB.notifyQueryVisibilityHook(ctx, .index_repair_pending);
        return;
    };
    if (completed) DB.notifyQueryVisibilityHook(ctx, .publish_blocking);
}

fn finishExternalDenseBulkSessionTrackedBestEffort(ctx: *AsyncContext) void {
    const completed = finishExternalDenseBulkSessionTrackedAndFinalize(ctx) catch |err| {
        if (err == error.PortableRuntimeActivationPending) return;
        std.log.err("dense external bulk idle finalization failed error={s}", .{@errorName(err)});
        DB.notifyQueryVisibilityHook(ctx, .index_repair_pending);
        return;
    };
    if (completed) DB.notifyQueryVisibilityHook(ctx, .publish_blocking);
}

fn asyncContextHasDenseSessionsOrWaiters(ctx: *const AsyncContext) bool {
    return ctx.dense_admission.hasSessionsOrWaiters();
}

fn asyncContextHasActiveDenseBulkWork(ctx: *const AsyncContext) bool {
    // Optimistic native projection construction is not a bulk session. It
    // deliberately leaves source admission open and owns separate
    // reservation/commit fences; treating it as bulk work suppresses the LSM,
    // posting, status, and projection-maintenance lanes that let a stable-tip
    // finalizer make progress. Only source sessions and their admission
    // waiters defer those background services.
    return asyncContextHasDenseSessionsOrWaiters(ctx);
}

// dense_finish_mutex must be held. The claim elects one finalization worker;
// expensive native generation construction remains optimistic and does not
// close session admission.
fn tryClaimDenseProjectionFinalizationLocked(ctx: *AsyncContext) bool {
    return ctx.dense_admission.claimLocked();
}

// dense_finish_mutex must be held. A session that completes while another
// optimistic finalizer owns the worker cannot claim it, but its newly
// committed projection state still requires a pass. Publish that handoff in
// the same critical section in which the session count reaches zero so the
// owner cannot miss the request while deciding whether it is finished.
fn tryClaimOrRequestDenseProjectionFinalizationLocked(ctx: *AsyncContext) bool {
    return ctx.dense_admission.claimOrRequestLocked();
}

fn finishDenseProjectionFinalization(ctx: *AsyncContext) void {
    var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
    // Source completion can hand off a newer sequence while this owner is
    // staging. Consume the handoff and release ownership atomically: a later
    // callback either requested this wake or can claim finalization itself.
    const requested = ctx.dense_admission.finishFinalizationLocked();
    session_lock.unlock();
    if (requested) scheduleNativeProjectionMaintenance(ctx);
}

fn tryBeginDenseProjectionCommit(ctx: *AsyncContext) bool {
    var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
    defer session_lock.unlock();
    return ctx.dense_admission.beginCommitLocked();
}

fn finishDenseProjectionCommit(ctx: *AsyncContext) void {
    var session_lock = lockAtomicWithBackoffProfiled(&ctx.dense_admission.mutex, &ctx.stats.dense_finish_mutex);
    ctx.dense_admission.finishCommitLocked();
    session_lock.unlock();
}

fn asyncContextHasActiveExternalDenseBulkWork(ctx: *const AsyncContext) bool {
    return ctx.dense_admission.external_sessions.load(.acquire) != 0;
}

fn resumeDeferredBackgroundMaintenanceIfIdle(ctx: *AsyncContext) void {
    if (asyncContextHasActiveDenseBulkWork(ctx)) return;
    const deferred = ctx.text_merge_deferred.swap(false, .acq_rel);
    if (deferred) if (ctx.text_merge_runtime) |runtime| runtime.notify();
}

fn storeMaxAtomicU64(value: *AtomicU64, candidate: u64) void {
    var current = value.load(.acquire);
    while (candidate > current) {
        if (value.cmpxchgWeak(current, candidate, .acq_rel, .acquire) == null) return;
        current = value.load(.acquire);
    }
}

