test "target advance debt logging is rate limited without doing repair work" {
    var apply_mutex: apply_rw_lock_mod.ApplyRwLock = .{};
    var ctx = AsyncContext{
        .alloc = std.testing.allocator,
        .store = undefined,
        .index_manager = undefined,
        .apply_mutex = &apply_mutex,
    };
    defer ctx.deinit(std.testing.allocator);

    const now_ns = std.time.ns_per_s;
    try std.testing.expect(shouldLogTargetAdvanceDebt(&ctx, "idx", now_ns));
    try noteTargetAdvanceDebtLogged(&ctx, "idx", now_ns);
    try std.testing.expect(!shouldLogTargetAdvanceDebt(&ctx, "idx", now_ns + denseCatchUpMaintenanceCooldownNs() - 1));
    try std.testing.expect(shouldLogTargetAdvanceDebt(&ctx, "idx", now_ns + denseCatchUpMaintenanceCooldownNs()));
}

test "target advance maintenance handoff is exact-incarnation scoped" {
    var apply_mutex: apply_rw_lock_mod.ApplyRwLock = .{};
    var ctx = AsyncContext{
        .alloc = std.testing.allocator,
        .store = undefined,
        .index_manager = undefined,
        .apply_mutex = &apply_mutex,
    };
    defer ctx.deinit(std.testing.allocator);

    try recordTargetAdvanceMaintenanceDebt(&ctx, "idx", .{ .config_hash = 11, .generation = 7 });
    try std.testing.expect(targetAdvanceMaintenanceDebtPending(&ctx, "idx", .{ .config_hash = 11, .generation = 7 }));
    try std.testing.expect(!targetAdvanceMaintenanceDebtPending(&ctx, "idx", .{ .config_hash = 12, .generation = 7 }));
    try std.testing.expect(!targetAdvanceMaintenanceDebtPending(&ctx, "idx", .{ .config_hash = 11, .generation = 8 }));

    // A same-name recreation replaces, rather than inherits, the old edge.
    try recordTargetAdvanceMaintenanceDebt(&ctx, "idx", .{ .config_hash = 12, .generation = 1 });
    try std.testing.expect(!targetAdvanceMaintenanceDebtPending(&ctx, "idx", .{ .config_hash = 11, .generation = 7 }));
    try std.testing.expect(targetAdvanceMaintenanceDebtPending(&ctx, "idx", .{ .config_hash = 12, .generation = 1 }));
    clearTargetAdvanceMaintenanceDebt(&ctx, "idx");
    try std.testing.expect(!targetAdvanceMaintenanceDebtPending(&ctx, "idx", .{ .config_hash = 12, .generation = 1 }));
}

test "target advance stuck tracking records first-seen time and clears on success" {
    var apply_mutex: apply_rw_lock_mod.ApplyRwLock = .{};
    var ctx = AsyncContext{
        .alloc = std.testing.allocator,
        .store = undefined,
        .index_manager = undefined,
        .apply_mutex = &apply_mutex,
    };
    defer ctx.deinit(std.testing.allocator);

    const first_ns: u64 = 10 * std.time.ns_per_s;
    try noteTargetAdvanceStuck(&ctx, "idx", first_ns, 3, 9);
    // A later call for the same index updates counters but must not reset
    // the original first-stuck timestamp -- that timestamp is the duration
    // basis for `checkTargetAdvanceNoProgress`.
    try noteTargetAdvanceStuck(&ctx, "idx", first_ns + std.time.ns_per_s, 5, 9);

    var not_yet = try oldestTargetAdvanceStuck(&ctx, 2 * std.time.ns_per_s, first_ns + std.time.ns_per_s);
    try std.testing.expect(not_yet == null);

    var stuck = (try oldestTargetAdvanceStuck(&ctx, 1 * std.time.ns_per_s, first_ns + std.time.ns_per_s)) orelse
        return error.TestUnexpectedResult;
    defer stuck.deinit(std.testing.allocator);
    try std.testing.expectEqualStrings("idx", stuck.index_name);
    try std.testing.expectEqual(first_ns, stuck.record.first_stuck_ns);
    try std.testing.expectEqual(@as(u64, 5), stuck.record.indexed);
    try std.testing.expectEqual(@as(u64, 9), stuck.record.expected);

    clearTargetAdvanceStuck(&ctx, "idx");
    not_yet = try oldestTargetAdvanceStuck(&ctx, 0, first_ns + std.time.ns_per_s);
    try std.testing.expect(not_yet == null);
}

const readEnvUsize = local_mutation.readEnvUsize;

fn readEnvU64(name: [:0]const u8, default_value: u64) u64 {
    if (comptime builtin.os.tag == .freestanding) return default_value;
    const raw = getenv(name) orelse return default_value;
    if (raw.len == 0) return default_value;
    return std.fmt.parseUnsigned(u64, raw, 10) catch default_value;
}

fn profileBenchTestsEnabled() bool {
    if (comptime builtin.os.tag == .freestanding) return false;
    return getenv("ANTFLY_RUN_PROFILE_BENCH_TESTS") != null;
}

fn appendDerivedBatchFromEnrichment(ctx_ptr: *anyopaque, batch: derived_types.DerivedBatch) !u64 {
    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    var batch_ctx = ctx.batchContext();
    const sequence = try appendDerivedBatchRecordContextWithProducerFence(&batch_ctx, batch, true);
    notifyResolverReplayRuntimesForCatalog(ctx.index_manager, ctx.resolution_runtime, ctx.promotion_runtime, sequence);
    if (ctx.executor.hasWorkers()) {
        ctx.executor.forceSequence(sequence);
        return sequence;
    }

    var applied_batch = batch;
    applied_batch.sequence = sequence;
    try lockApplyForPortableRuntimeContext(&batch_ctx);
    defer batch_ctx.apply_mutex.unlockExclusive();
    try applyDerivedBatchContext(&batch_ctx, applied_batch);
    return sequence;
}

fn commitArtifactUnitTurnFromEnrichment(ptr: *anyopaque, document: ?*const @import("artifact_unit_jobs.zig").DocumentTurn, work: ?*const @import("artifact_unit_jobs.zig").WorkTurn) !void {
    const owner: *EnrichmentAppendContext = @ptrCast(@alignCast(ptr));
    if (owner.read_only) return error.ReadOnly;
    if (owner.root_incarnation == 0) return error.DurableRootIncarnationUnavailable;
    if (document == null and work == null) return error.InvalidBatchRequest;
    if (document) |selected| if (work) |turn| {
        if (selected.selected == null or !std.mem.eql(u8, &selected.selected.?, &turn.selected)) return error.InvalidBatchRequest;
    };
    var ctx = owner.batchContext();
    var replication_mutation = acquireReplicationMutationSharedContext(&ctx);
    defer if (replication_mutation) |*lease| lease.release();
    try enforceReplicationWriteGateOptional(ctx.replication_write_gate);
    var snapshot_replay = try acquireSnapshotReplayContext(&ctx);
    defer if (snapshot_replay) |*lease| lease.release();
    try lockApplyForPortableRuntimeContext(&ctx);
    defer ctx.apply_mutex.unlockExclusive();
    var writer = try ctx.store.beginWriteTxn();
    errdefer writer.abort();
    if (work) |turn| _ = try turn.stage(&writer, owner.root_incarnation);
    if (document) |turn| try turn.stage(&writer, owner.root_incarnation);
    try writer.commit();
}

const ResolutionHandoffDocStoreSink = struct {
    store: *docstore_mod.DocStore,

    fn write(self: *@This(), writes: []const docstore_mod.KVPair, deletes: []const []const u8) !void {
        try self.store.putBatch(writes, deletes);
    }
};

fn publishResolutionHandoffContext(
    ctx: *const BatchExecutionContext,
    write: resolution_runtime_mod.RecordWrite,
) !void {
    var sink = ResolutionHandoffDocStoreSink{ .store = ctx.store };
    try publishResolutionHandoffContextWithSink(ctx, write, &sink);
}

fn publishResolutionHandoffContextWithSink(
    ctx: *const BatchExecutionContext,
    write: resolution_runtime_mod.RecordWrite,
    sink: anytype,
) !void {
    if (!write.publish_resolution_handoff) return;
    const marker_count = write.artifact_writes.len + write.artifact_deletes.len;
    if (marker_count == 0) return;

    const marker_keys = try ctx.alloc.alloc([]u8, marker_count);
    var marker_keys_initialized: usize = 0;
    defer {
        for (marker_keys[0..marker_keys_initialized]) |key| ctx.alloc.free(key);
        ctx.alloc.free(marker_keys);
    }
    const marker_values = try ctx.alloc.alloc(resolution_handoff.Value, write.artifact_writes.len);
    defer ctx.alloc.free(marker_values);
    const marker_writes = try ctx.alloc.alloc(docstore_mod.KVPair, write.artifact_writes.len);
    defer ctx.alloc.free(marker_writes);
    const marker_deletes = try ctx.alloc.alloc([]const u8, write.artifact_deletes.len);
    defer ctx.alloc.free(marker_deletes);

    for (write.artifact_writes, 0..) |artifact, i| {
        marker_keys[i] = try resolution_handoff.keyAlloc(ctx.alloc, artifact.key);
        marker_keys_initialized += 1;
        marker_values[i] = resolution_handoff.value(artifact.value);
        marker_writes[i] = .{ .key = marker_keys[i], .value = &marker_values[i] };
    }
    for (write.artifact_deletes, 0..) |artifact_key, i| {
        const marker_index = write.artifact_writes.len + i;
        marker_keys[marker_index] = try resolution_handoff.keyAlloc(ctx.alloc, artifact_key);
        marker_keys_initialized += 1;
        marker_deletes[i] = marker_keys[marker_index];
    }

    // Match the established apply -> transition lock order. The encompassing
    // resolution writer still owns the hot-standby mutation lease; the final gate check
    // makes marker publication linearizable with a primary-role fence, while a
    // single metadata batch preserves backfill throughput.
    try lockApplyForPortableRuntimeContext(ctx);
    defer ctx.apply_mutex.unlockExclusive();
    try requireArtifactProducerMutableContext(ctx);
    const transition_mutex = replicationTransitionMutexFromContext(ctx);
    if (transition_mutex) |mutex| lockAtomic(mutex);
    defer if (transition_mutex) |mutex| mutex.unlock();
    try enforceReplicationWriteGateContext(ctx);
    try sink.write(marker_writes, marker_deletes);
}

test "db resolution handoff completion publishes fanout in one metadata batch" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
    });
    defer db.close();
    var batch_ctx = db.batchContext();

    const CountingSink = struct {
        store: *docstore_mod.DocStore,
        calls: usize = 0,
        writes: usize = 0,
        deletes: usize = 0,

        fn write(self: *@This(), writes: []const docstore_mod.KVPair, deletes: []const []const u8) !void {
            self.calls += 1;
            self.writes += writes.len;
            self.deletes += deletes.len;
            try self.store.putBatch(writes, deletes);
        }
    };
    var counting_sink = CountingSink{ .store = batch_ctx.store };

    const first_resolution_key = try internal_keys.resolutionArtifactKeyAlloc(alloc, "doc:a", "resolution_v1");
    defer alloc.free(first_resolution_key);
    const second_resolution_key = try internal_keys.resolutionArtifactKeyAlloc(alloc, "doc:b", "resolution_v1");
    defer alloc.free(second_resolution_key);
    const writes = [_]resolution_runtime_mod.ArtifactWrite{
        .{ .key = first_resolution_key, .value = "{\"entities\":[\"a\"]}" },
        .{ .key = second_resolution_key, .value = "{\"entities\":[\"b\"]}" },
    };
    try publishResolutionHandoffContextWithSink(&batch_ctx, .{
        .batch = .{},
        .artifact_writes = &writes,
        .publish_resolution_handoff = true,
    }, &counting_sink);
    try std.testing.expectEqual(@as(usize, 1), counting_sink.calls);
    try std.testing.expectEqual(@as(usize, 2), counting_sink.writes);
    try std.testing.expectEqual(@as(usize, 0), counting_sink.deletes);

    const first_marker_key = try resolution_handoff.keyAlloc(alloc, first_resolution_key);
    defer alloc.free(first_marker_key);
    const second_marker_key = try resolution_handoff.keyAlloc(alloc, second_resolution_key);
    defer alloc.free(second_marker_key);
    for (writes, [_][]const u8{ first_marker_key, second_marker_key }) |artifact, marker_key| {
        const raw = try db.core.store.get(alloc, marker_key);
        defer alloc.free(raw);
        const expected = resolution_handoff.value(artifact.value);
        try std.testing.expectEqualSlices(u8, &expected, raw);
    }
}

const ResolutionHandoffPublishHook = struct {
    ptr: *anyopaque,
    run_fn: *const fn (ptr: *anyopaque) void,

    fn run(self: @This()) void {
        self.run_fn(self.ptr);
    }
};

const NoopResolutionHandoffPublishHook = struct {
    fn run(_: @This()) void {}
};

fn processOrderedResolutions(ctx_ptr: *anyopaque, alloc: Allocator, resolvers: []const resolution_runtime_mod.ResolverConfig, store: resolver_lib.ArtifactStore, provider: ?resolver_lib.CandidateProvider, changed_keys: []const []const u8, candidate_source: ?resolution_runtime_mod.CandidateSource, embedder: ?embedder_mod.DenseEmbedder) !bool {
    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    return @import("artifact_publication_resolution.zig").process(alloc, ctx.store, ctx.artifact_publication_dispatcher, resolvers, store, provider, changed_keys, candidate_source, embedder);
}

fn appendResolutionRecord(ctx_ptr: *anyopaque, write: resolution_runtime_mod.RecordWrite) !u64 {
    return try appendResolutionRecordWithHook(ctx_ptr, write, NoopResolutionHandoffPublishHook{});
}

fn appendResolutionRecordWithHook(
    ctx_ptr: *anyopaque,
    write: resolution_runtime_mod.RecordWrite,
    before_handoff_publish: anytype,
) !u64 {
    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    if (write.artifact_writes.len == 0 and write.artifact_deletes.len == 0 and write.target_hints == null) {
        return appendDerivedBatchFromEnrichment(ctx_ptr, write.batch);
    }

    var batch_ctx = ctx.batchContext();
    var replication_mutation = acquireReplicationMutationSharedContext(&batch_ctx);
    defer if (replication_mutation) |*lease| lease.release();
    try enforceReplicationWriteGateContext(&batch_ctx);
    var snapshot_replay = try acquireSnapshotReplayContext(&batch_ctx);
    defer if (snapshot_replay) |*lease| lease.release();

    const store_writes = try batch_ctx.alloc.alloc(docstore_mod.KVPair, write.artifact_writes.len);
    defer batch_ctx.alloc.free(store_writes);
    for (write.artifact_writes, 0..) |artifact, i| {
        store_writes[i] = .{ .key = artifact.key, .value = artifact.value };
    }

    try lockApplyForPortableRuntimeContext(&batch_ctx);
    var apply_mutex_held = true;
    errdefer if (apply_mutex_held) batch_ctx.apply_mutex.unlockExclusive();
    try requireArtifactProducerMutableContext(&batch_ctx);
    try enforceReplicationWriteGateContext(&batch_ctx);
    const sequence = batch_ctx.store.reserveNextReplaySequence(1);
    const payload = try encodeChangeRecordPayloadWithTargetHints(
        &batch_ctx,
        write.batch,
        sequence,
        write.target_hints,
    );
    defer batch_ctx.alloc.free(payload);
    var backlog_admission = try batch_ctx.executor.admitBacklogBytes(@intCast(payload.len));
    defer backlog_admission.cancel();
    try batch_ctx.store.putBatchWithReplay(batch_ctx.io, store_writes, write.artifact_deletes, .{
        .sequence = sequence,
        .payload = payload,
    });
    batch_ctx.executor.commitBacklogAdmission(sequence, &backlog_admission);
    if (shouldAppendSplitDeltaForContext(&batch_ctx)) {
        try batch_ctx.shard_manager.appendSplitDelta(currentTimeNs(), store_writes, write.artifact_deletes);
    }
    var deferred_replication_gates = ReplicationDeferredCommitGates.begin(replicationTransitionMutexFromContext(&batch_ctx));
    defer deferred_replication_gates.releaseTransition();
    deferred_replication_gates.append(try appendReplicationReplayPayloadCommitLockedContext(&batch_ctx, payload));
    batch_ctx.apply_mutex.unlockExclusive();
    apply_mutex_held = false;
    snapshot_replay.?.release();
    snapshot_replay = null;
    DB.notifyQueryVisibilityTargetAdvancedContext(&batch_ctx, sequence);
    releaseReplicationMutationShared(&replication_mutation);

    try deferred_replication_gates.waitForDurabilityAndAuthority(batch_ctx.replication_write_gate);
    before_handoff_publish.run();
    try publishResolutionHandoffContext(&batch_ctx, write);
    notifyResolverReplayRuntimesForCatalog(ctx.index_manager, ctx.resolution_runtime, ctx.promotion_runtime, sequence);
    if (ctx.executor.hasWorkers()) {
        ctx.executor.forceSequence(sequence);
        return sequence;
    }

    var applied_batch = write.batch;
    applied_batch.sequence = sequence;
    try lockApplyForPortableRuntimeContext(&batch_ctx);
    defer batch_ctx.apply_mutex.unlockExclusive();
    try applyDerivedBatchContext(&batch_ctx, applied_batch);
    return sequence;
}

fn enrichmentFailureArtifactKeyAlloc(
    alloc: Allocator,
    kind: enrichment_types.GeneratedEnrichmentKind,
    doc_key: []const u8,
    artifact_name: []const u8,
    source_artifact_name: []const u8,
) ![]u8 {
    return switch (kind) {
        .dense_embedding, .sparse_embedding => if (source_artifact_name.len > 0)
            // A chunked request owns a set of derived embedding keys. Leave the
            // singular artifact key absent so its durable identity is the
            // complete request tuple rather than a fabricated document key.
            try alloc.alloc(u8, 0)
        else
            try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, doc_key, artifact_name),
        .asset => try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "asset", artifact_name),
        .chunk_text => try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "chunk", artifact_name),
    };
}

fn recordEnrichmentRequestFailure(ctx_ptr: *anyopaque, failure: enrichment_runtime_mod.RequestFailure) !void {
    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    const async_ctx = ctx.async_context orelse return;
    const artifact_kind: types.ArtifactRepairKind = switch (failure.kind) {
        .dense_embedding, .sparse_embedding => .embedding,
        .asset => .asset,
        .chunk_text => .chunk,
    };
    const artifact_key = try enrichmentFailureArtifactKeyAlloc(
        ctx.alloc,
        failure.kind,
        failure.doc_key,
        failure.artifact_name,
        failure.source_artifact_name,
    );
    defer ctx.alloc.free(artifact_key);

    try recordArtifactRepairIssueContextDetailed(
        async_ctx,
        artifact_kind,
        failure.index_name,
        failure.doc_key,
        "",
        "",
        failure.artifact_name,
        failure.source_artifact_name,
        failure.artifact_name,
        artifact_key,
        null,
        failure.sequence,
        .enrichment_failed,
        failure.attempts,
        failure.error_name,
    );
}

fn enrichmentRequestFailurePending(
    ctx_ptr: *anyopaque,
    failure: enrichment_runtime_mod.FailureIdentity,
    index_name: []const u8,
) !bool {
    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    const artifact_kind: types.ArtifactRepairKind = switch (failure.kind) {
        .dense_embedding, .sparse_embedding => .embedding,
        .asset => .asset,
        .chunk_text => .chunk,
    };
    const artifact_key = try enrichmentFailureArtifactKeyAlloc(
        ctx.alloc,
        failure.kind,
        failure.doc_key,
        failure.artifact_name,
        failure.source_artifact_name,
    );
    defer ctx.alloc.free(artifact_key);
    const artifact_key_hex = if (artifact_key.len > 0)
        try bytesToHexAlloc(ctx.alloc, artifact_key)
    else
        try ctx.alloc.dupe(u8, "");
    defer ctx.alloc.free(artifact_key_hex);

    const issue_key = try artifactRepairIssueKeyForIssueAlloc(ctx.alloc, .{
        .artifact_kind = artifact_kind,
        .index_name = index_name,
        .doc_key = failure.doc_key,
        .source_artifact_name = failure.source_artifact_name,
        .artifact_name = failure.artifact_name,
        .artifact_key = artifact_key_hex,
    });
    defer ctx.alloc.free(issue_key);
    const loaded = (try loadArtifactRepairIssueFromStoreByKey(ctx.alloc, ctx.store, issue_key)) orelse return false;
    var issue = loaded;
    defer issue.deinit(ctx.alloc);
    return issue.reason == .enrichment_failed and issue.sequence >= failure.sequence;
}

fn enrichmentRequestFailureRangePending(
    ctx_ptr: *anyopaque,
    after_sequence: u64,
    through_sequence: u64,
) !bool {
    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    const async_ctx = ctx.async_context orelse return error.EnrichmentRuntimeUnavailable;
    lockAtomicWithBackoff(&async_ctx.artifact_repair_issue_mutex);
    defer async_ctx.artifact_repair_issue_mutex.unlock();
    // Ordinary waits inspect (applied_at_entry, requested]. A delayed
    // idempotent recovery may enter after its requested sequence has already
    // been passed; in that case the write's exact source sequence remains the
    // visibility boundary that must be checked.
    const first_sequence = if (after_sequence < through_sequence)
        after_sequence + 1
    else
        through_sequence;
    const lower = try internal_keys.enrichmentTerminalFailureSequencePrefixAlloc(ctx.alloc, first_sequence);
    defer ctx.alloc.free(lower);
    const through_prefix = try internal_keys.enrichmentTerminalFailureSequencePrefixAlloc(ctx.alloc, through_sequence);
    defer ctx.alloc.free(through_prefix);
    const upper = try internal_keys.nextPrefixAlloc(ctx.alloc, through_prefix) orelse
        return error.InvalidInternalUserKey;
    defer ctx.alloc.free(upper);

    const ScanState = struct {
        const page_size: usize = enrichment_terminal_failure_lookup_entry_budget;
        const Candidate = struct {
            sequence_key: []u8,
            issue_key: []u8,
            generation: u64,

            pub fn deinit(self: *@This(), alloc: Allocator) void {
                alloc.free(self.sequence_key);
                alloc.free(self.issue_key);
            }
        };

        alloc: Allocator,
        candidates: std.ArrayListUnmanaged(Candidate) = .empty,

        pub fn deinit(self: *@This()) void {
            for (self.candidates.items) |*candidate| candidate.deinit(self.alloc);
            self.candidates.deinit(self.alloc);
        }

        fn scanEntry(raw_ctx: ?*anyopaque, key: []const u8, marker_value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(raw_ctx orelse return error.InvalidArgument));
            _ = try internal_keys.enrichmentTerminalFailureSequence(key);
            const decoded = try decodeEnrichmentTerminalFailureMarkerValue(marker_value);
            const owned_sequence_key = try state.alloc.dupe(u8, key);
            errdefer state.alloc.free(owned_sequence_key);
            const owned_issue_key = try state.alloc.dupe(u8, decoded.issue_key);
            errdefer state.alloc.free(owned_issue_key);
            try state.candidates.append(state.alloc, .{
                .sequence_key = owned_sequence_key,
                .issue_key = owned_issue_key,
                .generation = decoded.generation,
            });
            return if (state.candidates.items.len >= page_size) .stop else .@"continue";
        }
    };

    // Page the secondary index so a wide stable-visibility range never scales
    // request memory with the total repair backlog. Authoritative issue reads
    // happen after each short scan transaction; the repair mutex keeps marker
    // creation/retirement stable across those pages.
    var owned_scan_lower: ?[]u8 = null;
    defer if (owned_scan_lower) |value| ctx.alloc.free(value);
    var entries_examined: usize = 0;
    while (true) {
        var state = ScanState{ .alloc = ctx.alloc };
        defer state.deinit();
        const scan_lower = owned_scan_lower orelse lower;
        try ctx.store.scanWithContext(
            scan_lower,
            upper,
            .{ .lower_exclusive = owned_scan_lower != null },
            &state,
            ScanState.scanEntry,
        );
        if (state.candidates.items.len == 0) return false;
        entries_examined += state.candidates.items.len;

        const next_scan_lower = try ctx.alloc.dupe(u8, state.candidates.items[state.candidates.items.len - 1].sequence_key);
        var next_scan_lower_owned = true;
        defer if (next_scan_lower_owned) ctx.alloc.free(next_scan_lower);
        var found = false;
        var stale_deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer stale_deletes.deinit(ctx.alloc);
        var owned_stale_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (owned_stale_delete_keys.items) |key| ctx.alloc.free(@constCast(key));
            owned_stale_delete_keys.deinit(ctx.alloc);
        }
        for (state.candidates.items) |candidate| {
            const loaded = try loadArtifactRepairIssueFromStoreByKey(ctx.alloc, ctx.store, candidate.issue_key);
            if (loaded) |value| {
                var issue = value;
                defer issue.deinit(ctx.alloc);
                const candidate_sequence = try internal_keys.enrichmentTerminalFailureSequence(candidate.sequence_key);
                const current_generation = try loadEnrichmentTerminalFailureGeneration(
                    ctx.alloc,
                    ctx.store,
                    candidate.issue_key,
                );
                const candidate_pair_exists = try enrichmentTerminalFailureMarkerPairExists(
                    ctx.alloc,
                    ctx.store,
                    candidate.issue_key,
                    candidate.generation,
                    candidate_sequence,
                );
                // The marker at the issue's current sequence is the incarnation
                // witness. A rollback binary can delete and recreate the issue
                // while leaving an older additive marker behind; it cannot create
                // this witness. Older coalesced markers remain valid while the
                // current witness exists.
                const current_incarnation_exists = candidate.generation == current_generation and
                    (candidate_sequence == issue.sequence or
                        try enrichmentTerminalFailureMarkerPairExists(
                            ctx.alloc,
                            ctx.store,
                            candidate.issue_key,
                            current_generation,
                            issue.sequence,
                        ));
                if (issue.reason == .enrichment_failed and candidate_pair_exists and current_incarnation_exists) {
                    found = true;
                    break;
                }
            }

            // A rollback binary can retire an issue without knowing this additive
            // index. Ignore and lazily remove that stale pair; current binaries
            // create and retire both sides atomically under this same mutex.
            try stale_deletes.append(ctx.alloc, candidate.sequence_key);
            const sequence = try internal_keys.enrichmentTerminalFailureSequence(candidate.sequence_key);
            const reverse_key = try internal_keys.enrichmentTerminalFailureIssueKeyAlloc(ctx.alloc, candidate.issue_key, sequence);
            errdefer ctx.alloc.free(reverse_key);
            try owned_stale_delete_keys.append(ctx.alloc, reverse_key);
            try stale_deletes.append(ctx.alloc, reverse_key);
        }
        if (stale_deletes.items.len > 0) {
            ctx.store.putBatch(&.{}, stale_deletes.items) catch |err| {
                // Cleanup is an optimization. Classification above is based on the
                // authoritative issue record and must not become a false repair
                // result merely because stale-index GC failed.
                std.log.warn("failed to clean stale enrichment terminal failure markers: {s}", .{@errorName(err)});
            };
        }
        if (found) {
            return true;
        }
        // Visibility classification is on the foreground write path and runs
        // after the ordinary wait deadline. Bound total storage work, not just
        // per-page memory. The caller converts this error into a conservative
        // repair-required result; the stale deletes above make retries
        // monotonically converge without extending this request indefinitely.
        if (entries_examined >= enrichment_terminal_failure_lookup_entry_budget) {
            return error.EnrichmentRepairLookupBudgetExceeded;
        }
        if (owned_scan_lower) |value| ctx.alloc.free(value);
        owned_scan_lower = next_scan_lower;
        next_scan_lower_owned = false;
    }
}

const TerminalFailureSequenceEnvelope = struct {
    min: u64 = 0,
    max: u64 = 0,
    entries_examined: u8 = 0,
};

fn enrichmentTerminalFailureSequenceEnvelope(store: *docstore_mod.DocStore) !TerminalFailureSequenceEnvelope {
    const alloc = store.alloc;
    const prefix = try internal_keys.enrichmentTerminalFailureSequenceRootPrefixAlloc(alloc);
    defer alloc.free(prefix);
    const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
    defer if (upper) |value| alloc.free(value);

    const EndpointState = struct {
        sequence: u64 = 0,
        entries_examined: u8 = 0,

        fn scanEntry(raw_ctx: ?*anyopaque, key: []const u8, _: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(raw_ctx orelse return error.InvalidArgument));
            state.sequence = try internal_keys.enrichmentTerminalFailureSequence(key);
            state.entries_examined += 1;
            return .stop;
        }
    };

    // Both endpoints come from one read snapshot. Each scan stops after its
    // first entry, so runtime creation/reconfiguration is O(1) regardless of
    // how much durable repair debt accumulated.
    var txn = try store.beginReadTxn();
    defer txn.abort();
    const scan_upper = if (upper) |value| value else "";
    var min_state = EndpointState{};
    try store.scanReadTxnWithContext(&txn, prefix, scan_upper, .{}, &min_state, EndpointState.scanEntry);
    if (min_state.entries_examined == 0) return .{};

    var max_state = EndpointState{};
    try store.scanReadTxnWithContext(&txn, prefix, scan_upper, .{ .reverse = true }, &max_state, EndpointState.scanEntry);
    return .{
        .min = min_state.sequence,
        .max = max_state.sequence,
        .entries_examined = min_state.entries_examined + max_state.entries_examined,
    };
}

const EnrichmentTerminalFailureMarkerPair = execution_resources.EnrichmentTerminalFailureMarkerPair;

const enrichment_terminal_failure_marker_value_version = execution_resources.enrichment_terminal_failure_marker_value_version;
const enrichment_terminal_failure_marker_generation_len = execution_resources.enrichment_terminal_failure_marker_generation_len;
const enrichment_terminal_failure_lookup_entry_budget: usize = 64;
const enrichment_terminal_failure_retirement_page_size = execution_resources.enrichment_terminal_failure_retirement_page_size;

const EnrichmentTerminalFailureMarkerValue = execution_resources.EnrichmentTerminalFailureMarkerValue;

const decodeEnrichmentTerminalFailureMarkerValue = execution_resources.decodeEnrichmentTerminalFailureMarkerValue;

const encodeEnrichmentTerminalFailureMarkerValueAlloc = execution_resources.encodeEnrichmentTerminalFailureMarkerValueAlloc;

const loadEnrichmentTerminalFailureGeneration = execution_resources.loadEnrichmentTerminalFailureGeneration;

const loadEnrichmentTerminalFailureGenerationCounter = execution_resources.loadEnrichmentTerminalFailureGenerationCounter;

const encodeEnrichmentTerminalFailureGeneration = execution_resources.encodeEnrichmentTerminalFailureGeneration;

const nextEnrichmentTerminalFailureGeneration = execution_resources.nextEnrichmentTerminalFailureGeneration;

const enrichmentTerminalFailureMarkerPairExists = execution_resources.enrichmentTerminalFailureMarkerPairExists;

/// Reuse a generation only while the previous authoritative issue retains its
/// exact marker pair. Otherwise advance the durable incarnation generation so
/// leftover markers from rollback or bounded retirement cannot resurrect when
/// the new current witness is published.
const EnrichmentTerminalFailureGenerationSelection = execution_resources.EnrichmentTerminalFailureGenerationSelection;

const enrichmentTerminalFailureGenerationForWrite = execution_resources.enrichmentTerminalFailureGenerationForWrite;

const EnrichmentTerminalFailureMarkerWrite = execution_resources.EnrichmentTerminalFailureMarkerWrite;

/// Append at most one bounded page of marker pairs owned by a coalesced repair
/// issue. The authoritative issue transition and generation fence make any
/// remainder stale immediately; foreground lookup removes it incrementally.
const appendEnrichmentTerminalFailureMarkerDeletesForIssue = execution_resources.appendEnrichmentTerminalFailureMarkerDeletesForIssue;

const appendEnrichmentTerminalFailureMarkerDeletePageForIssue = execution_resources.appendEnrichmentTerminalFailureMarkerDeletePageForIssue;

fn lockEnrichmentFailurePendingFence(ctx_ptr: *anyopaque) void {
    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    const async_ctx = ctx.async_context orelse return;
    lockAtomicWithBackoff(&async_ctx.artifact_repair_issue_mutex);
}

fn unlockEnrichmentFailurePendingFence(ctx_ptr: *anyopaque) void {
    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    const async_ctx = ctx.async_context orelse return;
    async_ctx.artifact_repair_issue_mutex.unlock();
}

fn requireArtifactProducerMutableContext(ctx: *const BatchExecutionContext) !void {
    var read = try ctx.store.beginReadTxn();
    defer read.abort();
    try @import("artifact_reconcile_intent.zig").requireAbsent(&read);
    // Activation is serialized with this same apply fence. Work prepared by
    // an old local lease may retry through ordered publication, never commit
    // an unreplicated result after the owner selected replicated producers.
    if (try @import("artifact_publication.zig").authority(&read) != null) return error.ArtifactCatalogDrift;
}

fn appendGeneratedBatchFromEnrichment(
    ctx_ptr: *anyopaque,
    batch: derived_types.DerivedBatch,
    artifact_promotions: []const enrichment_runtime_mod.GeneratedArtifactPromotion,
    artifact_delete_keys: []const []const u8,
    source_guards: []const enrichment_runtime_mod.GeneratedSourceGuard,
    fence: ?enrichment_runtime_mod.GeneratedWriteFence,
) !enrichment_runtime_mod.GeneratedRecordCommit {
    if (artifact_promotions.len == 0 and artifact_delete_keys.len == 0 and source_guards.len == 0 and fence == null)
        return .{ .sequence = try appendDerivedBatchFromEnrichment(ctx_ptr, batch) };

    const ctx: *EnrichmentAppendContext = @ptrCast(@alignCast(ctx_ptr));
    var batch_ctx = ctx.batchContext();
    var replication_mutation = acquireReplicationMutationSharedContext(&batch_ctx);
    defer if (replication_mutation) |*lease| lease.release();
    try enforceReplicationWriteGateContext(&batch_ctx);
    var snapshot_replay = try acquireSnapshotReplayContext(&batch_ctx);
    defer if (snapshot_replay) |*lease| lease.release();
    const replay_deleted_keys = try concatKeyViews(batch_ctx.alloc, batch.deleted_keys, artifact_delete_keys);
    defer batch_ctx.alloc.free(replay_deleted_keys);
    var replay_batch = batch;
    replay_batch.deleted_keys = replay_deleted_keys;
    var sync_targets = try collectManagedSyncTargets(batch_ctx.alloc, batch_ctx.index_manager, replay_batch);
    defer sync_targets.deinit(batch_ctx.alloc);

    var staged_key_set = std.StringHashMapUnmanaged(void).empty;
    defer staged_key_set.deinit(batch_ctx.alloc);
    var final_key_set = std.StringHashMapUnmanaged(void).empty;
    defer final_key_set.deinit(batch_ctx.alloc);
    var artifact_delete_key_set = std.StringHashMapUnmanaged(void).empty;
    defer artifact_delete_key_set.deinit(batch_ctx.alloc);
    const promotion_capacity = std.math.cast(u32, artifact_promotions.len) orelse
        return error.InvalidGeneratedArtifactPromotion;
    const delete_capacity = std.math.cast(u32, artifact_delete_keys.len) orelse
        return error.InvalidGeneratedArtifactPromotion;
    try staged_key_set.ensureTotalCapacity(batch_ctx.alloc, promotion_capacity);
    try final_key_set.ensureTotalCapacity(batch_ctx.alloc, promotion_capacity);
    try artifact_delete_key_set.ensureTotalCapacity(batch_ctx.alloc, delete_capacity);
    for (artifact_delete_keys) |key| artifact_delete_key_set.putAssumeCapacity(key, {});
    for (artifact_promotions) |promotion| {
        if (promotion.staged_key.len == 0 or promotion.final_key.len == 0 or
            std.mem.eql(u8, promotion.staged_key, promotion.final_key) or
            artifact_delete_key_set.contains(promotion.final_key))
            return error.InvalidGeneratedArtifactPromotion;
        const staged = staged_key_set.getOrPutAssumeCapacity(promotion.staged_key);
        const final = final_key_set.getOrPutAssumeCapacity(promotion.final_key);
        if (staged.found_existing or final.found_existing)
            return error.InvalidGeneratedArtifactPromotion;
    }
    var staged_it = staged_key_set.iterator();
    while (staged_it.next()) |entry| {
        if (final_key_set.contains(entry.key_ptr.*))
            return error.InvalidGeneratedArtifactPromotion;
    }

    var store_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer store_writes.deinit(batch_ctx.alloc);
    const staged_delete_keys = try batch_ctx.alloc.alloc([]const u8, artifact_promotions.len);
    defer if (staged_delete_keys.len > 0) batch_ctx.alloc.free(staged_delete_keys);
    const store_promotions = try batch_ctx.alloc.alloc(docstore_mod.DocStore.KeyPromotion, artifact_promotions.len);
    defer if (store_promotions.len > 0) batch_ctx.alloc.free(store_promotions);
    for (artifact_promotions, 0..) |promotion, i| {
        staged_delete_keys[i] = promotion.staged_key;
        store_promotions[i] = .{
            .source_key = promotion.staged_key,
            .destination_key = promotion.final_key,
        };
    }
    var store_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
    defer store_delete_keys.deinit(batch_ctx.alloc);
    try store_delete_keys.appendSlice(batch_ctx.alloc, artifact_delete_keys);
    try store_delete_keys.appendSlice(batch_ctx.alloc, staged_delete_keys);
    var owned_store_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_store_keys.items) |key| batch_ctx.alloc.free(key);
        owned_store_keys.deinit(batch_ctx.alloc);
    }
    var owned_store_values = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_store_values.items) |value| batch_ctx.alloc.free(value);
        owned_store_values.deinit(batch_ctx.alloc);
    }
    var owned_delete_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_delete_keys.items) |key| batch_ctx.alloc.free(key);
        owned_delete_keys.deinit(batch_ctx.alloc);
    }
    try appendAssetArtifactSourceIndexMutations(
        batch_ctx.alloc,
        &store_writes,
        artifact_delete_keys,
        &store_delete_keys,
        &owned_store_keys,
        &owned_store_values,
        &owned_delete_keys,
    );
    for (artifact_promotions) |promotion| {
        try appendAssetArtifactSourceIndexWrite(
            batch_ctx.alloc,
            promotion.final_key,
            &store_writes,
            &owned_store_keys,
            &owned_store_values,
        );
    }

    try lockApplyForPortableRuntimeContext(&batch_ctx);
    var apply_mutex_held = true;
    errdefer if (apply_mutex_held) batch_ctx.apply_mutex.unlockExclusive();
    const graph_effects = for (artifact_promotions) |promotion| {
        if (@import("online_graph_artifacts.zig").isKey(promotion.final_key)) break true;
    } else for (artifact_delete_keys) |key| {
        if (@import("online_graph_artifacts.zig").isKey(key)) break true;
    } else false;
    var graph_publication = if (graph_effects) batch_ctx.index_manager.beginGraphPrimaryMutation() else null;
    defer if (graph_publication) |*lease| lease.release();
    try requireArtifactProducerMutableContext(&batch_ctx);
    try enforceReplicationWriteGateContext(&batch_ctx);
    const sequence = batch_ctx.store.reserveNextReplaySequence(1);
    const payload = try encodeChangeRecordPayload(&batch_ctx, replay_batch, sequence);
    defer batch_ctx.alloc.free(payload);
    var owned_counter_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_counter_keys.items) |key| batch_ctx.alloc.free(key);
        owned_counter_keys.deinit(batch_ctx.alloc);
    }
    var owned_counter_values = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_counter_values.items) |value| batch_ctx.alloc.free(value);
        owned_counter_values.deinit(batch_ctx.alloc);
    }
    try DB.appendDenseArtifactCounterMutationsWithPromotions(
        batch_ctx.alloc,
        batch_ctx.store,
        batch_ctx.index_manager,
        &store_writes,
        store_delete_keys.items,
        artifact_promotions,
        &owned_counter_keys,
        &owned_counter_values,
    );
    const SplitDeltaBuilder = struct {
        timestamp: u64,
        writes: []const docstore_mod.KVPair,
        deletes: []const []const u8,
        promotions: []const docstore_mod.DocStore.KeyPromotion,
        resource_manager: ?*resource_manager_mod.ResourceManager,
        reservation: *?resource_manager_mod.Reservation,

        fn build(ptr: *anyopaque, alloc: Allocator, txn: *docstore_mod.DocStore.Batch.BatchTxn) anyerror![]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const encoded_size = shard_mod.splitDeltaWithPromotionsEncodedSize(
                self.writes,
                self.deletes,
                self.promotions,
                txn,
            ) catch |err| switch (err) {
                error.NotFound => return error.InvalidKeyPromotion,
                error.SplitDeltaTooLarge => return error.ResourceLimitExceeded,
                else => return err,
            };
            if (self.resource_manager) |manager| {
                const reservation_bytes = std.math.cast(u64, encoded_size) orelse
                    return error.ResourceLimitExceeded;
                if (self.reservation.* == null) {
                    // This callback runs under the storage/apply transaction.
                    // Reclaimers can acquire unrelated subsystem locks, so use
                    // the explicitly non-reclaiming admission primitive here.
                    self.reservation.* = manager.reserveWithoutReclaim(
                        .shard_transition_working_set,
                        reservation_bytes,
                    ) catch return error.ResourceLimitExceeded;
                } else if (self.reservation.*.?.reservedBytes() != reservation_bytes) {
                    return error.ResourceLimitExceeded;
                }
            }
            return shard_mod.encodeSplitDeltaWithPromotionsAlloc(
                alloc,
                self.timestamp,
                self.writes,
                self.deletes,
                self.promotions,
                txn,
            ) catch |err| switch (err) {
                error.NotFound => error.InvalidKeyPromotion,
                error.SplitDeltaTooLarge => error.ResourceLimitExceeded,
                else => err,
            };
        }
    };
    const PublicationGuard = struct {
        fence: ?enrichment_runtime_mod.GeneratedWriteFence,
        source_guards: []const enrichment_runtime_mod.GeneratedSourceGuard,
        clock: platform_clock.Clock,

        fn validateLease(self: *@This(), alloc: Allocator, txn: *docstore_mod.DocStore.Batch.BatchTxn) !void {
            if (self.fence) |active_fence| {
                const raw = txn.get(active_fence.lease_key) catch |err| switch (err) {
                    error.NotFound => return error.EnrichmentLeaseFenceLost,
                    else => return err,
                };
                var parsed = std.json.parseFromSlice(lease_mod.LeaseRecord, alloc, raw, .{ .allocate = .alloc_always }) catch
                    return error.EnrichmentLeaseFenceLost;
                defer parsed.deinit();
                if (!std.mem.eql(u8, parsed.value.owner_id, active_fence.owner_id) or
                    parsed.value.epoch != active_fence.epoch or
                    parsed.value.expires_at_ms <= self.clock.nowRealtimeMs())
                {
                    return error.EnrichmentLeaseFenceLost;
                }
            }
        }

        pub fn validate(ptr: *anyopaque, alloc: Allocator, txn: *docstore_mod.DocStore.Batch.BatchTxn) anyerror!void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try self.validateLease(alloc, txn);
            for (self.source_guards) |guard| {
                if (guard.document_key) |doc_key| {
                    if (guard.source_sequence != 0) {
                        if (try doc_identity.lookupOrdinalTxn(alloc, txn, doc_key)) |ordinal| {
                            const state = (try doc_identity.lookupStateTxn(txn, ordinal)) orelse return error.InvalidDocIdentity;
                            if (!state.isLive() or state.created_generation > guard.source_sequence)
                                return error.EnrichmentSourceChanged;
                        }
                    }
                }
                const raw = txn.get(guard.key) catch |err| switch (err) {
                    error.NotFound => {
                        if (guard.expected_digest == null) continue;
                        return error.EnrichmentSourceChanged;
                    },
                    else => return err,
                };
                const expected = guard.expected_digest orelse return error.EnrichmentSourceChanged;
                var actual: [32]u8 = undefined;
                std.crypto.hash.sha2.Sha256.hash(raw, &actual, .{});
                if (!std.mem.eql(u8, &expected, &actual)) return error.EnrichmentSourceChanged;
            }
        }

        fn validateAtCommit(ptr: *anyopaque, alloc: Allocator, txn: *docstore_mod.DocStore.Batch.BatchTxn) anyerror!void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            // Source records may be deleted by this transaction. The first
            // validation holds under its writer lock; only the lease's clock
            // expiry needs a second check immediately before commit.
            try self.validateLease(alloc, txn);
        }
    };
    var split_delta_key_buf: [19]u8 = undefined;
    const append_split_delta = shouldAppendSplitDeltaForContext(&batch_ctx);
    var split_delta_reservation: ?resource_manager_mod.Reservation = null;
    defer if (split_delta_reservation) |*reservation| reservation.release();
    var split_delta_builder: SplitDeltaBuilder = undefined;
    var publication_guard: PublicationGuard = undefined;
    const transactional_guard: ?docstore_mod.DocStore.TransactionalGuard = if (fence != null or source_guards.len > 0) blk: {
        publication_guard = .{ .fence = fence, .source_guards = source_guards, .clock = ctx.clock };
        break :blk .{ .ptr = &publication_guard, .validate = PublicationGuard.validate, .validate_at_commit = PublicationGuard.validateAtCommit };
    } else null;
    var transactional_split_delta: ?docstore_mod.DocStore.TransactionalWriteBuilder = null;
    if (append_split_delta) {
        const split_delta_key = batch_ctx.shard_manager.reserveSplitDeltaKey(&split_delta_key_buf) catch |err| switch (err) {
            error.SplitDeltaSequenceOverflow => return error.ResourceLimitExceeded,
            else => return err,
        };
        split_delta_builder = .{
            .timestamp = currentTimeNs(),
            .writes = store_writes.items,
            .deletes = store_delete_keys.items,
            .promotions = store_promotions,
            .resource_manager = batch_ctx.index_manager.resource_manager,
            .reservation = &split_delta_reservation,
        };
        transactional_split_delta = .{
            .ptr = &split_delta_builder,
            .key = split_delta_key,
            .build = SplitDeltaBuilder.build,
        };
    }
    var backlog_admission = try batch_ctx.executor.admitBacklogBytes(@intCast(payload.len));
    defer backlog_admission.cancel();
    const promoted_artifact_bytes = batch_ctx.store.putBatchWithPromotionsReplayAndBuiltWrite(
        batch_ctx.io,
        store_writes.items,
        store_delete_keys.items,
        store_promotions,
        .{
            .sequence = sequence,
            .payload = payload,
        },
        transactional_split_delta,
        transactional_guard,
    ) catch |err| switch (err) {
        error.InvalidKeyPromotion => return error.InvalidGeneratedArtifactPromotion,
        error.KeyPromotionBytesOverflow => return error.GeneratedArtifactPromotionBytesOverflow,
        else => return err,
    };
    batch_ctx.executor.commitBacklogAdmission(sequence, &backlog_admission);
    var deferred_replication_gates = ReplicationDeferredCommitGates.begin(replicationTransitionMutexFromContext(&batch_ctx));
    defer deferred_replication_gates.releaseTransition();
    deferred_replication_gates.append(try appendReplicationReplayPayloadCommitLockedContext(&batch_ctx, payload));
    if (graph_publication) |*lease| lease.release();
    graph_publication = null;
    batch_ctx.apply_mutex.unlockExclusive();
    apply_mutex_held = false;
    snapshot_replay.?.release();
    snapshot_replay = null;
    DB.notifyQueryVisibilityTargetAdvancedScopedContext(&batch_ctx, sequence, sync_targets);
    releaseReplicationMutationShared(&replication_mutation);
    try deferred_replication_gates.waitForDurabilityAndAuthority(batch_ctx.replication_write_gate);
    notifyResolverReplayRuntimesForCatalog(ctx.index_manager, ctx.resolution_runtime, ctx.promotion_runtime, sequence);
    if (ctx.executor.hasWorkers()) {
        ctx.executor.forceSequence(sequence);
        return .{ .sequence = sequence, .promoted_artifact_bytes = promoted_artifact_bytes };
    }

    var applied_batch = replay_batch;
    applied_batch.sequence = sequence;
    try lockApplyForPortableRuntimeContext(&batch_ctx);
    defer batch_ctx.apply_mutex.unlockExclusive();
    try applyDerivedBatchContext(&batch_ctx, applied_batch);
    return .{ .sequence = sequence, .promoted_artifact_bytes = promoted_artifact_bytes };
}

fn replayPendingDerivedBatchesContext(ctx: *const BatchExecutionContext) !void {
    const managed_indexes = try ctx.index_manager.managedIndexes(ctx.alloc);
    defer {
        for (managed_indexes) |index_ref| ctx.alloc.free(@constCast(index_ref.name));
        ctx.alloc.free(managed_indexes);
    }
    if (managed_indexes.len == 0) return;

    var saw_entries = false;
    var updates = std.ArrayListUnmanaged(apply_state.AppliedSequenceUpdate).empty;
    defer updates.deinit(ctx.alloc);
    var replay_ctx = ReplayApplyContextBatch{
        .batch = ctx,
        .dense_bulk_session_scope = .external,
    };
    for (managed_indexes) |index_ref| {
        const applied = try loadManagedAppliedSequenceContext(
            ctx.alloc,
            ctx.index_manager,
            ctx.store,
            ctx.applied_sequence_checkpoint_path,
            index_ref,
        );
        const target_sequence = try ctx.replay_source.latestMatchingSequence(
            ctx.alloc,
            applied,
            managedIndexReplayHint(index_ref.kind),
        );
        const use_dense_maintenance = index_ref.kind == .dense_vector;
        const stats = try derived_worker.catchUpIndexWithOptions(
            ctx.alloc,
            ctx.replay_source,
            index_ref,
            applied,
            &replay_ctx,
            applyDerivedBatchToIndexReplayContext,
            .{
                .resource_manager = ctx.index_manager.resource_manager,
                .window_ctx = &replay_ctx,
                .begin_window_fn = @field(@This(), "beginDerivedCatchUpWindowContext"),
                .finish_window_fn = @field(@This(), "finishDerivedCatchUpWindowContext"),
                .target_sequence = target_sequence,
            },
        );
        if (openProfileEnabled()) logReplayCatchUpProfile(index_ref, applied, stats);
        if (use_dense_maintenance) {
            _ = try ctx.index_manager.runDenseLsmMaintenanceByName(index_ref.name, denseCatchUpMaintenanceSteps());
        }
        saw_entries = saw_entries or stats.scanned_entries > 0;
        if (stats.appliedSequenceAdvance(applied)) |sequence| {
            try ctx.index_manager.checkpointLsmWalForManagedIndex(index_ref);
            try finishReplayCaptureContext(&replay_ctx, index_ref, sequence);
            try updates.append(ctx.alloc, .{
                .index_name = index_ref.name,
                .sequence = sequence,
            });
        } else if (stats.shouldTryTargetAdvance(applied, target_sequence) and
            try canAdvanceDerivedReplayTargetContext(ctx, index_ref, applied, target_sequence))
        {
            try ctx.index_manager.checkpointLsmWalForManagedIndex(index_ref);
            try finishReplayCaptureContext(&replay_ctx, index_ref, target_sequence);
            try updates.append(ctx.alloc, .{
                .index_name = index_ref.name,
                .sequence = target_sequence,
            });
        } else try abortReplayCaptureContext(&replay_ctx, index_ref);
    }
    try saveAppliedSequencesBatchContext(ctx, updates.items);
    try truncateReplayJournalIfSafeContext(ctx);
}

const loadManagedAppliedSequenceContext = local_mutation.loadManagedAppliedSequenceContext;

fn canAdvanceDerivedReplayTargetContext(
    ctx: *const BatchExecutionContext,
    index_ref: index_manager_mod.ManagedIndexRef,
    from_sequence: u64,
    target_sequence: u64,
) !bool {
    if (target_sequence <= from_sequence) return true;
    if (ctx.async_context) |async_ctx| {
        return try canAdvanceDerivedToTargetAsync(async_ctx, index_ref, from_sequence, target_sequence);
    }

    var async_ctx = AsyncContext{
        .alloc = ctx.alloc,
        .io = ctx.io,
        .store = ctx.store,
        .relational_base_rows = ctx.relational_base_rows,
        .applied_sequence_checkpoint_path = ctx.applied_sequence_checkpoint_path,
        .index_manager = ctx.index_manager,
        .apply_mutex = ctx.apply_mutex,
        .snapshot_replay_admission = ctx.snapshot_replay_admission,
        .dense_bulk_session_scope = ctx.dense_bulk_session_scope,
        .resolution_runtime = ctx.resolution_runtime,
        .promotion_runtime = ctx.promotion_runtime,
    };
    defer async_ctx.deinit(ctx.alloc);
    return try canAdvanceDerivedToTargetAsync(&async_ctx, index_ref, from_sequence, target_sequence);
}

fn applyDerivedBatchToIndexReplayContext(
    ctx_ptr: *anyopaque,
    batch: derived_types.DerivedBatch,
    index_ref: index_manager_mod.ManagedIndexRef,
) !bool {
    const replay_ctx: *ReplayApplyContextBatch = @ptrCast(@alignCast(ctx_ptr));
    const ctx = replay_ctx.batch;
    if (!try batchAdvancesManagedIndexApplyStateForReplay(ctx.index_manager, batch, index_ref)) return false;
    // Only a batch accepted by this projection may publish its source
    // boundary from the window callback. A mutation-free tail is certified by
    // canAdvanceDerivedToTargetAsync first, then Core.saveAppliedSequence
    // emits the empty native coverage transaction. Publishing here would let
    // the checkpoint itself bypass that cardinality proof.
    if (index_ref.kind == .dense_vector) {
        replay_ctx.dense_window_sequence = @max(replay_ctx.dense_window_sequence, batch.sequence);
    }

    const async_ctx = AsyncContext{
        .alloc = ctx.alloc,
        .io = ctx.io,
        .store = ctx.store,
        .applied_sequence_checkpoint_path = ctx.applied_sequence_checkpoint_path,
        .index_manager = ctx.index_manager,
        .apply_mutex = ctx.apply_mutex,
        .snapshot_replay_admission = ctx.snapshot_replay_admission,
        .dense_bulk_session_scope = replay_ctx.dense_bulk_session_scope,
        .require_graph_resolution_contract = true,
        .text_merge_runtime = if (ctx.async_context) |active| active.text_merge_runtime else null,
    };
    if (benchMetricsEnabled()) {
        var profile = BatchProfile{};
        const total_start_ns = monotonicTimeNs();
        try applyDerivedBatchToIndexContextProfiled(&async_ctx, batch, index_ref, &profile, true, null);
        const index_sync_start_ns = monotonicTimeNs();
        try ctx.index_manager.syncReplayStateByName(ctx.store, index_ref.name);
        recordProfileNs(&profile, &profile.index_sync_ns, index_sync_start_ns);
        profile.total_ns += monotonicTimeNs() - total_start_ns;
        logDerivedWorkerProfile(index_ref, batch, profile);
    } else {
        // beginDerivedCatchUpWindowContext opened the source-owned posting
        // transaction for this replay window. The unprofiled path must carry
        // the same explicit borrowing capability as the profiled path; routing
        // it through the ordinary foreground helper would correctly reject
        // the already-active capture as unrelated ownership.
        try applyDerivedBatchToIndexContextProfiled(&async_ctx, batch, index_ref, null, true, null);
        try ctx.index_manager.syncReplayStateByName(ctx.store, index_ref.name);
    }
    return true;
}

fn notifyDerivedExecutorSequence(ctx_ptr: *anyopaque, sequence: u64) void {
    const executor: *derived_executor_mod.Executor = @ptrCast(@alignCast(ctx_ptr));
    executor.notifySequence(sequence);
}

fn applyDerivedBatch(self: *DB, batch: derived_types.DerivedBatch) !void {
    try applyDerivedBatchProfiled(self, batch, null);
}

