const applyDerivedBatchContextProfiled = local_mutation.applyDerivedBatchContextProfiled;

const applyDerivedBatchTargetsContextProfiled = local_mutation.applyDerivedBatchTargetsContextProfiled;

const indexNameInSlice = local_mutation.indexNameInSlice;

const saveAppliedSequencesBatchContext = local_mutation.saveAppliedSequencesBatchContext;

fn saveAppliedSequencesBatchLockedContext(
    ctx: *const BatchExecutionContext,
    enriched_updates: []const apply_state.AppliedSequenceUpdate,
    async_ctx: ?*AsyncContext,
) !void {
    var generic_updates = std.ArrayListUnmanaged(apply_state.AppliedSequenceUpdate).empty;
    defer generic_updates.deinit(ctx.alloc);
    try generic_updates.ensureTotalCapacity(ctx.alloc, enriched_updates.len);
    for (enriched_updates) |update| {
        if (ctx.index_manager.densePostingWalAuthoritativeByName(update.index_name)) {
            // The per-index apply path normally publishes authoritative HBC
            // state before returning. Do not re-enter publication if that
            // exact boundary is already durable: another worker may have
            // opened its next source capture after the apply guard was
            // released but before this catalog/status phase acquired its
            // broader lock.
            if (!ctx.index_manager.densePostingCoverageIncludesByName(update.index_name, update.sequence)) {
                try ctx.index_manager.ensureDensePostingCoverageByName(update.index_name, update.sequence);
            }
        } else {
            generic_updates.appendAssumeCapacity(update);
        }
    }
    if (generic_updates.items.len == 0) {
        if (async_ctx) |active_async_ctx| {
            var lifecycle_completed = false;
            for (enriched_updates) |update| {
                lifecycle_completed = try finalizeCoveredDenseProjectionCheckpoint(
                    active_async_ctx,
                    update.index_name,
                    update.sequence,
                ) or lifecycle_completed;
            }
            if (lifecycle_completed) try DB.saveIndexStatusSnapshots(
                ctx.alloc,
                ctx.store,
                ctx.index_manager,
                enriched_updates,
            );
        }
        return;
    }
    if (async_ctx) |active_async_ctx| {
        // Never persist a source watermark in HBC metadata before the
        // corresponding index WAL/posting effects are durable. A crash in that
        // gap would make restart trust a checkpoint ahead of its physical
        // snapshot.
        try checkpointManagedProjectionEffectsForAppliedSequenceUpdates(ctx.index_manager, generic_updates.items);
        try savePhysicalProjectionMetadataForAppliedSequenceUpdates(ctx.index_manager, generic_updates.items);
        try apply_state.saveAppliedSequencesWithCheckpoint(
            ctx.alloc,
            ctx.index_manager.checkpointIo(),
            ctx.store,
            ctx.applied_sequence_checkpoint_path,
            generic_updates.items,
        );
        var authoritative_lifecycle_completed = false;
        for (enriched_updates) |update| {
            const completed_now = try finalizeCoveredDenseProjectionCheckpoint(active_async_ctx, update.index_name, update.sequence);
            authoritative_lifecycle_completed = authoritative_lifecycle_completed or
                (completed_now and ctx.index_manager.densePostingWalAuthoritativeByName(update.index_name));
        }
        try DB.saveIndexStatusSnapshots(
            ctx.alloc,
            ctx.store,
            ctx.index_manager,
            if (authoritative_lifecycle_completed) enriched_updates else generic_updates.items,
        );
        return;
    }
    try checkpointManagedProjectionEffectsForAppliedSequenceUpdates(ctx.index_manager, generic_updates.items);
    try savePhysicalProjectionMetadataForAppliedSequenceUpdates(ctx.index_manager, generic_updates.items);
    try apply_state.saveAppliedSequencesWithCheckpoint(
        ctx.alloc,
        ctx.index_manager.checkpointIo(),
        ctx.store,
        ctx.applied_sequence_checkpoint_path,
        generic_updates.items,
    );
    try DB.saveIndexStatusSnapshots(ctx.alloc, ctx.store, ctx.index_manager, generic_updates.items);
}

const appliedSequenceUpdatesWithConfigHashes = local_mutation.appliedSequenceUpdatesWithConfigHashes;

fn savePhysicalProjectionMetadataForAppliedSequenceUpdates(
    index_manager: *index_manager_mod.IndexManager,
    updates: []const apply_state.AppliedSequenceUpdate,
) !void {
    for (updates) |update| {
        if (index_manager.get(update.index_name)) |cfg| if (cfg.kind == .full_text) {
            try index_manager.publishFullTextReplaySeal(update);
            continue;
        };
        const current = index_manager.denseProjectionCheckpointMetadata(update.index_name) orelse continue;
        try index_manager.saveDenseProjectionCheckpointMetadata(update.index_name, .{
            .applied_sequence = update.sequence,
            .status = current.status,
            .generation = if (update.generation != 0) update.generation else current.generation,
            .config_hash = if (update.config_hash != 0) update.config_hash else current.config_hash,
            .published_count = update.published_count,
        });
    }
}

fn checkpointManagedProjectionEffectsForAppliedSequenceUpdates(
    index_manager: *index_manager_mod.IndexManager,
    updates: []const apply_state.AppliedSequenceUpdate,
) !void {
    for (updates) |update| {
        const cfg = index_manager.get(update.index_name) orelse continue;
        try index_manager.checkpointLsmWalForManagedIndex(.{
            .name = update.index_name,
            .kind = cfg.kind,
        });
        if (cfg.kind == .dense_vector) {
            // Publish posting state after HBC's metadata WAL is durable but
            // before the source applied watermark advances. An optional
            // sidecar can invalidate and fall back to HBC's LSM. Once the
            // persisted WAL-authoritative marker exists, publication is a
            // required half of this durability boundary and failure leaves
            // the source watermark unchanged for replay.
            try index_manager.ensureDensePostingCoverageByName(update.index_name, update.sequence);
        }
    }
}

fn replayPendingDerivedBatches(
    self: *DB,
    progress_ctx: ?*anyopaque,
    progress_hook: ?ReplayProgressHook,
    options: DB.ReplayDrainOptions,
) !void {
    if (!self.core.hasManagedIndexes()) return;

    const dense_catch_up_watchdog_interval_ns = 5 * std.time.ns_per_s;

    const PersistReplayProgressContext = struct {
        db: @TypeOf(self),
        progress_ctx: ?*anyopaque,
        progress_hook: ?ReplayProgressHook,
        track_dense: bool = false,
        target_sequence: u64 = 0,
        scanned_entries: u64 = 0,
        applied_entries: u64 = 0,
        replay_scan_batches: u64 = 0,
        replay_hint_filter_skips: u64 = 0,
        active: bool = false,

        fn publish(state: *@This(), index_name: []const u8) !void {
            const progress: ReplayProgress = .{
                .sequence = try state.db.core.loadAppliedSequence(state.db.alloc, index_name),
                .target_sequence = state.target_sequence,
                .scanned_entries = state.scanned_entries,
                .applied_entries = state.applied_entries,
                .replay_scan_batches = state.replay_scan_batches,
                .replay_hint_filter_skips = state.replay_hint_filter_skips,
                .active = state.active,
            };
            if (state.track_dense) setDenseCatchUpProgress(state.db.async_context, progress);
            if (state.progress_hook) |hook| {
                try hook(state.progress_ctx.?, index_name, progress);
            }
        }
    };

    const PersistReplayProgress = struct {
        fn run(ctx: *anyopaque, index_name: []const u8, sequence: u64) !void {
            const progress: *PersistReplayProgressContext = @ptrCast(@alignCast(ctx));
            try progress.db.core.saveAppliedSequence(index_name, sequence);
            try progress.publish(index_name);
        }
    };

    const DenseReplayProgressContext = struct {
        db: *DB,
        persist: *PersistReplayProgressContext,
        index_name: []const u8,
        last_log_ns: u64 = 0,
        last_applied_entries: u64 = 0,

        fn maybeLogStall(replay: *@This(), progress: derived_worker.CatchUpProgress) void {
            if (!replay.persist.active) return;
            const now_ns = monotonicTimeNs();
            if (replay.last_log_ns != 0 and now_ns - replay.last_log_ns < dense_catch_up_watchdog_interval_ns) return;
            replay.last_log_ns = now_ns;

            const dense_entry = replay.db.core.index_manager.denseIndex(replay.index_name) orelse return;
            const profile = dense_entry.index.getWriteProfile();
            const hbc_cache = dense_entry.index.hbcCacheStats();
            const manager = replay.db.core.index_manager.resource_manager;
            const resource_snapshot = if (manager) |value| value.snapshot() else null;
            const hbc_policy: resource_manager_mod.HbcCachePolicy = if (manager) |value| value.hbcCachePolicy() else .{};
            const retry_stats: resource_manager_mod.DerivedRecoverableRetryStats = if (manager) |value| value.derivedRecoverableRetryStats() else .{};
            const hbc_slice: resource_manager_mod.SliceStats = if (resource_snapshot) |stats| stats.slices[@backingInt(resource_manager_mod.Slice.hbc_node_metadata_cache)] else .{ .name = "hbc_node_metadata_cache" };
            const dense_apply_slice: resource_manager_mod.SliceStats = if (resource_snapshot) |stats| stats.slices[@backingInt(resource_manager_mod.Slice.dense_apply_working_set)] else .{ .name = "dense_apply_working_set" };

            const common_progress_args = .{
                replay.index_name,
                progress.sequence,
                replay.persist.target_sequence,
                progress.scanned_entries,
                progress.applied_entries,
                progress.applied_entries -| replay.last_applied_entries,
            };
            const shared_cache_args = .{
                hbc_policy.target_bytes,
                hbc_slice.used_bytes,
                hbc_slice.peak_bytes,
                hbc_slice.soft_limit_bytes,
                hbc_slice.hard_limit_bytes,
                hbc_policy.node_protected_bytes,
                hbc_policy.quantized_protected_bytes,
                hbc_policy.vector_protected_bytes,
                hbc_policy.metadata_protected_bytes,
                if (resource_snapshot) |stats| stats.reclaim_requests else 0,
                if (resource_snapshot) |stats| stats.reclaimed_bytes else 0,
            };
            if (dense_entry.index.usesSharedCache()) {
                std.log.warn(
                    "dense catch-up watchdog progress index={s} sequence={} target={} scanned={} applied={} delta_applied={} cache_mode=shared_clock shared_hbc={{target_bytes={},used_bytes={},peak_bytes={},soft_limit_bytes={},hard_limit_bytes={},node_protected_bytes={},quantized_protected_bytes={},vector_protected_bytes={},metadata_protected_bytes={},reclaim_requests={},reclaimed_bytes={}}}",
                    common_progress_args ++ shared_cache_args,
                );
            } else {
                std.log.warn(
                    "dense catch-up watchdog progress index={s} sequence={} target={} scanned={} applied={} delta_applied={} cache_mode=local local_cache_capacity={{nodes={},vectors={}}} resource_hbc={{target_bytes={},used_bytes={},peak_bytes={},soft_limit_bytes={},hard_limit_bytes={},node_protected_bytes={},quantized_protected_bytes={},vector_protected_bytes={},metadata_protected_bytes={},reclaim_requests={},reclaimed_bytes={}}}",
                    common_progress_args ++ .{
                        dense_entry.index.config.max_cached_nodes,
                        dense_entry.index.config.max_cached_vectors,
                    } ++ shared_cache_args,
                );
            }
            std.log.warn(
                "dense catch-up watchdog resources index={s} namespace_hbc={{total={},accounted={},node_used={},quantized_used={},vector_used={},vector_peak={},vector_evictions={},metadata_used={}}} rm={{lsm_cache={},dense_search={},dense_apply_used={},dense_apply_peak={},replay_window={},full_text_pending={},full_text_build={}}} retries={{total={},not_found={}}} profile={{find_leaf_ns={},mutate_leaf_ns={},store_vector_ns={},quantized_vector_load_ns={}}}",
                .{
                    replay.index_name,
                    hbc_cache.total_bytes,
                    hbc_cache.accounted_bytes,
                    hbc_cache.node.used_bytes,
                    hbc_cache.quantized.used_bytes,
                    hbc_cache.vector.used_bytes,
                    hbc_cache.vector.peak_bytes,
                    hbc_cache.vector.evictions,
                    hbc_cache.metadata.used_bytes,
                    if (resource_snapshot) |stats| stats.slices[@backingInt(resource_manager_mod.Slice.lsm_block_table_cache)].used_bytes else 0,
                    if (resource_snapshot) |stats| stats.slices[@backingInt(resource_manager_mod.Slice.dense_search_working_set)].used_bytes else 0,
                    dense_apply_slice.used_bytes,
                    dense_apply_slice.peak_bytes,
                    if (resource_snapshot) |stats| stats.slices[@backingInt(resource_manager_mod.Slice.derived_replay_window)].used_bytes else 0,
                    if (resource_snapshot) |stats| stats.slices[@backingInt(resource_manager_mod.Slice.full_text_pending_segments)].used_bytes else 0,
                    if (resource_snapshot) |stats| stats.slices[@backingInt(resource_manager_mod.Slice.full_text_build_working_set)].used_bytes else 0,
                    retry_stats.total,
                    retry_stats.not_found,
                    profile.insert_find_leaf_ns,
                    profile.insert_mutate_leaf_ns,
                    profile.insert_store_vector_ns,
                    profile.quantized_vector_load_ns,
                },
            );
            replay.last_applied_entries = progress.applied_entries;
        }

        fn run(ctx: *anyopaque, index_name: []const u8, progress: derived_worker.CatchUpProgress) !void {
            const replay: *@This() = @ptrCast(@alignCast(ctx));
            replay.persist.scanned_entries = progress.scanned_entries;
            replay.persist.applied_entries = progress.applied_entries;
            replay.persist.replay_scan_batches = progress.replay_scan_batches;
            replay.persist.replay_hint_filter_skips = progress.replay_hint_filter_skips;
            const snapshot: ReplayProgress = .{
                .sequence = progress.sequence,
                .target_sequence = replay.persist.target_sequence,
                .scanned_entries = progress.scanned_entries,
                .applied_entries = progress.applied_entries,
                .replay_scan_batches = progress.replay_scan_batches,
                .replay_hint_filter_skips = progress.replay_hint_filter_skips,
                .active = replay.persist.active,
            };
            setDenseCatchUpProgress(replay.db.async_context, snapshot);
            replay.maybeLogStall(progress);
            if (replay.persist.progress_hook) |hook| {
                try hook(replay.persist.progress_ctx.?, index_name, snapshot);
            }
        }
    };

    var persist_progress_ctx = PersistReplayProgressContext{
        .db = self,
        .progress_ctx = progress_ctx,
        .progress_hook = progress_hook,
    };

    const managed_indexes = try self.core.managedIndexes(self.alloc);
    defer {
        for (managed_indexes) |index_ref| self.alloc.free(@constCast(index_ref.name));
        self.alloc.free(managed_indexes);
    }
    if (managed_indexes.len == 0) return;

    var saw_entries = false;
    var replay_ctx = ReplayApplyContext{
        .db = self,
        .dense_bulk_session_scope = .external,
    };
    for (managed_indexes) |index_ref| {
        if (options.index_names.len != 0 and !containsName(options.index_names, index_ref.name)) continue;
        const applied = try self.core.loadAppliedSequence(self.alloc, index_ref.name);
        const use_dense_catch_up = index_ref.kind == .dense_vector;
        const resources = self.core.batchExecutionResources();
        const target_sequence = try self.probeDerivedReplayTargetSequence(
            self.alloc,
            resources.replay_source,
            index_ref,
            applied,
        );
        persist_progress_ctx.target_sequence = target_sequence;
        persist_progress_ctx.scanned_entries = 0;
        persist_progress_ctx.applied_entries = 0;
        persist_progress_ctx.track_dense = use_dense_catch_up;
        persist_progress_ctx.active = use_dense_catch_up and target_sequence > applied;
        if (use_dense_catch_up) {
            setDenseCatchUpProgress(self.async_context, .{
                .sequence = applied,
                .target_sequence = target_sequence,
                .scanned_entries = 0,
                .applied_entries = 0,
                .active = persist_progress_ctx.active,
            });
            if (progress_hook) |hook| {
                try hook(progress_ctx.?, index_ref.name, .{
                    .sequence = applied,
                    .target_sequence = target_sequence,
                    .scanned_entries = 0,
                    .applied_entries = 0,
                    .active = persist_progress_ctx.active,
                });
            }
        }
        var dense_replay_progress_ctx = DenseReplayProgressContext{
            .db = self,
            .persist = &persist_progress_ctx,
            .index_name = index_ref.name,
            .last_log_ns = monotonicTimeNs(),
        };
        const stats = try derived_worker.catchUpIndexWithOptions(
            self.alloc,
            resources.replay_source,
            index_ref,
            applied,
            &replay_ctx,
            applyDerivedBatchToIndexReplay,
            .{
                .resource_manager = resources.index_manager.resource_manager,
                .window_ctx = &replay_ctx,
                .begin_window_fn = @field(@This(), "beginDerivedCatchUpWindow"),
                .finish_window_fn = @field(@This(), "finishDerivedCatchUpWindow"),
                .progress_ctx = if (use_dense_catch_up) &dense_replay_progress_ctx else null,
                .progress_fn = if (use_dense_catch_up) DenseReplayProgressContext.run else null,
                .persist_ctx = &persist_progress_ctx,
                .persist_progress_fn = PersistReplayProgress.run,
                .max_records_per_window = if (progress_hook != null and use_dense_catch_up) denseCatchUpStartupMaxRecords() else derived_worker.catch_up_max_records_per_window_default,
                .max_chunk_bytes = if (progress_hook != null and use_dense_catch_up) denseCatchUpStartupMaxChunkBytes() else derived_worker.catch_up_max_chunk_bytes_default,
                .max_windows_per_call = options.max_windows_per_index,
                .deadline_ns = options.deadline_ns,
            },
        );
        if (openProfileEnabled()) logReplayCatchUpProfile(index_ref, applied, stats);
        if (use_dense_catch_up) {
            _ = try resources.index_manager.runDenseLsmMaintenanceByName(index_ref.name, denseCatchUpMaintenanceSteps());
            persist_progress_ctx.active = false;
            const final_progress: ReplayProgress = .{
                .sequence = @max(stats.last_sequence, applied),
                .target_sequence = target_sequence,
                .scanned_entries = @intCast(stats.scanned_entries),
                .applied_entries = @intCast(stats.applied_entries),
                .active = false,
            };
            setDenseCatchUpProgress(self.async_context, final_progress);
            if (progress_hook) |hook| {
                try hook(progress_ctx.?, index_ref.name, final_progress);
            }
        }
        saw_entries = saw_entries or stats.scanned_entries > 0;
        if (stats.appliedSequenceAdvance(applied)) |sequence| {
            try resources.index_manager.checkpointLsmWalForManagedIndex(index_ref);
            try finishReplayCapture(&replay_ctx, index_ref, sequence);
            try self.core.saveAppliedSequence(index_ref.name, sequence);
        } else if (stats.shouldTryTargetAdvance(applied, target_sequence) and
            try canAdvanceDerivedToTargetAsync(self.async_context, index_ref, applied, target_sequence))
        {
            try resources.index_manager.checkpointLsmWalForManagedIndex(index_ref);
            try finishReplayCapture(&replay_ctx, index_ref, target_sequence);
            try self.core.saveAppliedSequence(index_ref.name, target_sequence);
        } else try abortReplayCapture(&replay_ctx, index_ref);
    }
    if (options.truncate_replay) try truncateReplayJournalIfSafe(self);
}

fn applyDerivedBatchToIndex(self: *DB, batch: derived_types.DerivedBatch, index_ref: index_manager_mod.ManagedIndexRef) !void {
    const resources = self.core.asyncResources();
    const ctx = AsyncContext{
        .alloc = self.alloc,
        .io = self.backend_runtime.io(),
        .store = resources.store,
        .relational_base_rows = relationalColumns(self) != null,
        .applied_sequence_checkpoint_path = resources.applied_sequence_checkpoint_path,
        .index_manager = resources.index_manager,
        .apply_mutex = resources.apply_mutex,
        .snapshot_replay_admission = resources.snapshot_replay_admission,
        .text_merge_runtime = self.text_merge_runtime,
    };
    try applyDerivedBatchToIndexContext(&ctx, batch, index_ref);
}

const applyDerivedBatchToIndexContext = local_mutation.applyDerivedBatchToIndexContext;

const loadDerivedCoverageOutcomeCounterFromStore = local_mutation.loadDerivedCoverageOutcomeCounterFromStore;

fn loadDerivedCoverageOutcomeCounterFromTxn(
    alloc: Allocator,
    txn: *docstore_mod.DocStore.Txn,
    index_name: []const u8,
    generation: u64,
    outcome: []const u8,
    authority: ?@import("artifact_publication.zig").Authority,
) !?u64 {
    const counter_key = try @import("artifact_coverage_epoch.zig").counter(alloc, authority, index_name, generation, outcome);
    defer alloc.free(counter_key);
    const raw = txn.get(counter_key) catch |err| switch (err) {
        error.NotFound => return null,
        else => return err,
    };
    return try internal_keys.decodeDerivedCoverageOutcomeCount(raw);
}

/// Outcome creation and transitions are atomic writes. All members must be
/// read from one revision too; independent point reads can manufacture a
/// partial tuple or an impossible sum while a worker commits between reads.
const DerivedCoverageCounters = struct {
    produced: ?u64,
    skipped: ?u64,
    terminal_failed: ?u64,
    source_total: ?u64,
    artifact_count: ?u64,
    artifact_invalid: bool,

    fn load(alloc: Allocator, txn: *docstore_mod.DocStore.Txn, index_name: []const u8, generation: u64) !@This() {
        const authority = try @import("artifact_publication.zig").authority(txn);
        return .{
            .produced = try loadDerivedCoverageOutcomeCounterFromTxn(alloc, txn, index_name, generation, "produced", authority),
            .skipped = try loadDerivedCoverageOutcomeCounterFromTxn(alloc, txn, index_name, generation, "skipped", authority),
            .terminal_failed = try loadDerivedCoverageOutcomeCounterFromTxn(alloc, txn, index_name, generation, "terminal_failed", authority),
            .source_total = try range_cardinality.loadFromTxn(txn),
            .artifact_count = try DB.loadDenseArtifactTargetCounterFromTxn(alloc, txn, index_name),
            .artifact_invalid = false,
        };
    }

    fn artifactCount(self: @This()) !?u64 {
        if (self.artifact_invalid) return error.InvalidDenseArtifactTargetCounter;
        return self.artifact_count;
    }
};

fn loadDerivedCoverageCounters(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    index_name: []const u8,
    generation: u64,
    legacy_range: ?types.ByteRange,
    test_ctx: ?*AsyncContext,
) !DerivedCoverageCounters {
    const publication = @import("artifact_publication.zig");
    var scope: ?publication.Authority = null;
    for (0..4) |_| {
        var point = try loadCoveragePointSet(alloc, store, index_name, generation, scope);
        const matches = std.meta.eql(scope, point.authority);
        scope = point.authority;
        if (!matches) {
            point.lease.abort();
            continue;
        }
        if (legacy_range != null and point.counts.source_total == null) {
            point.lease.abort();
            break;
        }
        defer point.lease.abort();
        if (builtin.is_test) {
            if (test_ctx) |ctx| if (test_dense_target_after_coverage_capture) |hook| try hook(ctx);
        }
        return point.counts;
    }
    // Catalog churn and legacy cardinality fallback use one immutable view.
    // Never combine a live point probe's authority with later counter reads.
    var snapshot = try store.beginReadTxn();
    defer snapshot.abort();
    var counts = try DerivedCoverageCounters.load(alloc, &snapshot, index_name, generation);
    if (legacy_range) |range| if (counts.source_total == null) {
        counts.source_total = try range_cardinality.loadOrCountFromTxn(alloc, store, &snapshot, range);
    };
    if (builtin.is_test) {
        if (test_ctx) |ctx| if (test_dense_target_after_coverage_capture) |hook| try hook(ctx);
    }
    return counts;
}

const CoveragePointSet = struct {
    lease: docstore_mod.DocStore.Txn,
    counts: DerivedCoverageCounters,
    authority: ?@import("artifact_publication.zig").Authority,
};

/// The authority witness is in the SAME atomic point batch as the counters,
/// source cardinality and artifact target. The common path never clones the
/// mutable LSM snapshot merely to discover a producer epoch.
fn loadCoveragePointSet(alloc: Allocator, store: *docstore_mod.DocStore, index_name: []const u8, generation: u64, scope: ?@import("artifact_publication.zig").Authority) !CoveragePointSet {
    const publication = @import("artifact_publication.zig");
    const tags = [_][]const u8{ "produced", "skipped", "terminal_failed" };
    var owned_keys: [4][]u8 = undefined;
    var initialized: usize = 0;
    defer for (owned_keys[0..initialized]) |key| alloc.free(key);
    for (tags, 0..) |tag, i| {
        owned_keys[i] = try @import("artifact_coverage_epoch.zig").counter(alloc, scope, index_name, generation, tag);
        initialized += 1;
    }
    owned_keys[3] = try DB.denseArtifactTargetCounterKeyAlloc(alloc, index_name);
    initialized += 1;
    const unsorted = [_][]const u8{ owned_keys[0], owned_keys[1], owned_keys[2], &internal_keys.range_document_count_key, owned_keys[3], publication.authority_key };
    var order = [_]usize{ 0, 1, 2, 3, 4, 5 };
    std.mem.sort(usize, &order, unsorted, struct {
        fn less(keys: [6][]const u8, lhs: usize, rhs: usize) bool {
            return std.mem.order(u8, keys[lhs], keys[rhs]) == .lt;
        }
    }.less);
    var keys: [6][]const u8 = undefined;
    for (order, 0..) |index, i| keys[i] = unsorted[index];
    var values: [6]?[]const u8 = undefined;
    var lease = try store.readManyConsistent(&keys, &values);
    errdefer lease.abort();
    var artifact_invalid = false;
    var decoded = @as([5]?u64, @splat(null));
    var observed_authority: ?publication.Authority = null;
    for (order, values) |index, raw| if (index == 5) {
        if (raw) |value| observed_authority = try publication.decodeAuthority(value);
    };
    // Inactive legacy counters may be absent or malformed; neither grants
    // permission to interpret them as the new epoch's accounting state.
    for (order, values) |index, raw| {
        if (index == 5 or !std.meta.eql(scope, observed_authority)) continue;
        if (raw) |value| decoded[index] = switch (index) {
            3 => try range_cardinality.decode(value),
            4 => blk: {
                if (value.len != 8) {
                    artifact_invalid = true;
                    break :blk null;
                }
                break :blk std.mem.readInt(u64, value[0..8], .little);
            },
            else => try internal_keys.decodeDerivedCoverageOutcomeCount(value),
        };
    }
    return .{
        .lease = lease,
        .authority = observed_authority,
        .counts = .{
            .produced = decoded[0],
            .skipped = decoded[1],
            .terminal_failed = decoded[2],
            .source_total = decoded[3],
            .artifact_count = decoded[4],
            .artifact_invalid = artifact_invalid,
        },
    };
}

test "db derived coverage snapshot stays coherent across atomic creation and transitions" {
    // Debug retains leak instrumentation; optimized timing uses the server's
    // allocator rather than measuring testing-allocator bookkeeping.
    const alloc = if (builtin.mode == .fast) std.heap.smp_allocator else std.testing.allocator;
    inline for (.{ mem_backend_mod.Backend, lsm_backend_mod.Backend }) |Backend| {
        var backend = Backend.init(alloc, if (Backend == mem_backend_mod.Backend) .{} else .{ .wal_enabled = false });
        defer backend.close();
        var runtime_store = try backend.runtimeStore(alloc, .{ .name = "coverage" });
        defer runtime_store.deinit();
        var store = try docstore_mod.DocStore.openRuntime(alloc, &runtime_store);
        defer store.close();
        const names = [_][]const u8{ "produced", "skipped", "terminal_failed" };
        var keys: [3][]u8 = undefined;
        var initialized: usize = 0;
        defer for (keys[0..initialized]) |key| alloc.free(key);
        for (names, 0..) |name, i| {
            keys[i] = try internal_keys.derivedCoverageOutcomeCountKeyAlloc(alloc, "dense", 7, name);
            initialized += 1;
        }
        var before = try store.beginReadTxn();
        defer before.abort();
        try std.testing.expectEqual(@as(?u64, null), (try DerivedCoverageCounters.load(alloc, &before, "dense", 7)).produced);
        var values: [4][8]u8 = undefined;
        var writes: [4]docstore_mod.KVPair = undefined;
        for (keys, 0..) |key, i| {
            writes[i] = .{ .key = key, .value = internal_keys.encodeDerivedCoverageOutcomeCount(&values[i], if (i == 0) 1 else 0) };
        }
        writes[3] = .{ .key = &internal_keys.range_document_count_key, .value = internal_keys.encodeDerivedCoverageOutcomeCount(&values[3], 1) };
        try store.putBatch(&writes, &.{});
        const absent = try DerivedCoverageCounters.load(alloc, &before, "dense", 7);
        try std.testing.expectEqual(@as(?u64, null), absent.produced);
        try std.testing.expectEqual(@as(?u64, null), absent.skipped);
        try std.testing.expectEqual(@as(?u64, null), absent.terminal_failed);
        try std.testing.expectEqual(@as(?u64, null), try range_cardinality.loadFromTxn(&before));

        var pinned = try store.beginReadTxn();
        defer pinned.abort();
        // Move a source between outcomes and add a new source in one commit.
        _ = internal_keys.encodeDerivedCoverageOutcomeCount(&values[0], 0);
        _ = internal_keys.encodeDerivedCoverageOutcomeCount(&values[1], 2);
        _ = internal_keys.encodeDerivedCoverageOutcomeCount(&values[3], 2);
        try store.putBatch(&writes, &.{});
        const old = try DerivedCoverageCounters.load(alloc, &pinned, "dense", 7);
        try std.testing.expectEqual(@as(?u64, 1), old.produced);
        try std.testing.expectEqual(@as(?u64, 0), old.skipped);
        try std.testing.expectEqual(@as(?u64, 0), old.terminal_failed);
        try std.testing.expectEqual(@as(?u64, 1), try range_cardinality.loadFromTxn(&pinned));
        var current = try store.beginReadTxn();
        defer current.abort();
        const next = try DerivedCoverageCounters.load(alloc, &current, "dense", 7);
        try std.testing.expectEqual(@as(?u64, 0), next.produced);
        try std.testing.expectEqual(@as(?u64, 2), next.skipped);
        try std.testing.expectEqual(@as(?u64, 2), try range_cardinality.loadFromTxn(&current));

        if (builtin.mode == .fast) {
            const iterations = 10_000;
            var independent_sum: u64 = 0;
            const independent_start = std.Io.Clock.awake.now(std.testing.io);
            for (0..iterations) |_| {
                for (names) |name| independent_sum += (try loadDerivedCoverageOutcomeCounterFromStore(alloc, &store, "dense", 7, name)).?;
                independent_sum += (try range_cardinality.load(alloc, &store)).?;
            }
            const independent_ns = independent_start.durationTo(std.Io.Clock.awake.now(std.testing.io)).toNanoseconds();
            var snapshot_sum: u64 = 0;
            const snapshot_start = std.Io.Clock.awake.now(std.testing.io);
            for (0..iterations) |_| {
                var txn = try store.beginReadTxn();
                defer txn.abort();
                const counters = try DerivedCoverageCounters.load(alloc, &txn, "dense", 7);
                snapshot_sum += counters.produced.? + counters.skipped.? + counters.terminal_failed.? + (try range_cardinality.loadFromTxn(&txn)).?;
            }
            const snapshot_ns = snapshot_start.durationTo(std.Io.Clock.awake.now(std.testing.io)).toNanoseconds();
            try std.testing.expectEqual(@as(u64, iterations * 4), independent_sum);
            try std.testing.expectEqual(independent_sum, snapshot_sum);
            std.debug.print("coverage read benchmark backend={s} iterations={d} independent_ns={d} snapshot_ns={d}\n", .{ @typeName(Backend), iterations, independent_ns, snapshot_ns });
        }
    }
}

