}

fn expectedChunkArtifactPublicIdAlloc(alloc: Allocator, doc_key: []const u8, artifact_name: []const u8, chunk_id: u32) ![]u8 {
    const internal_key = try expectedChunkArtifactKeyAlloc(alloc, doc_key, artifact_name, chunk_id);
