const GateSparseEmbedder = struct {
    deterministic: embedder_mod.DeterministicSparseEmbedder = .{},
    allowed_successes: std.atomic.Value(usize) = .init(0),
    successful_requests: std.atomic.Value(usize) = .init(0),
