test "db non chunked search paths apply broad live doc filter" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.addIndex(.{
        .name = "ft_v1",
        .kind = .full_text,
        .config_json = "{}",
    });
    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\"}",
    });
    try db.addIndex(.{
        .name = "sp_v1",
        .kind = .sparse_vector,
        .config_json = "{\"field\":\"sparse\"}",
    });

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"alpha only\",\"embedding\":[0,0],\"sparse\":{\"indices\":[7],\"values\":[1.0]}}" },
            .{ .key = "doc:b", .value = "{\"body\":\"beta only\",\"embedding\":[10,0],\"sparse\":{\"indices\":[8],\"values\":[1.0]}}" },
            .{ .key = "doc:c", .value = "{\"body\":\"gamma only\",\"embedding\":[20,0],\"sparse\":{\"indices\":[9],\"values\":[1.0]}}" },
        },
        .sync_level = .full_index,
    });

    const doc_a_store_key = try internal_keys.documentKeyAlloc(alloc, "doc:a");
    defer alloc.free(doc_a_store_key);
    {
        var txn = try db.core.store.beginWriteTxn();
        errdefer txn.abort();
        try txn.delete(doc_a_store_key);
        try doc_identity.markDeletedTxn(alloc, &txn, 2, "doc:a");
        try txn.commit();
    }
    db.core.identity_visibility.summary = null;
    db.clearLiveDocSetCache();
    db.clearNonVisibleDocSetCache();

    var dense_live = try db.searchDenseProfiled(alloc, .{
        .index_name = "dv_v1",
        .limit = 1,
        .include_stored = false,
    }, .{ .vector = &.{ 0.0, 0.0 }, .k = 1 });
    defer dense_live.result.deinit();
    try std.testing.expectEqual(@as(u32, 1), dense_live.result.total_hits);
    try std.testing.expectEqual(@as(usize, 1), dense_live.result.hits.len);
    try std.testing.expectEqualStrings("doc:b", dense_live.result.hits[0].id);
    try std.testing.expectEqual(@as(u32, 1), dense_live.profile.raw_hit_count);

    var dense_live_page_two = try db.searchDenseProfiled(alloc, .{
        .index_name = "dv_v1",
        .limit = 1,
        .offset = 1,
        .include_stored = false,
        .profile = true,
    }, .{ .vector = &.{ 0.0, 0.0 }, .k = 1 });
    defer dense_live_page_two.result.deinit();
    try std.testing.expectEqual(@as(u32, 2), dense_live_page_two.result.total_hits);
    try std.testing.expectEqual(types.TotalHitsRelation.exact, dense_live_page_two.result.total_hits_relation);
    try std.testing.expectEqual(@as(usize, 1), dense_live_page_two.result.hits.len);
    try std.testing.expectEqualStrings("doc:c", dense_live_page_two.result.hits[0].id);
    try std.testing.expectEqual(@as(u32, 2), dense_live_page_two.profile.raw_hit_count);
    const dense_live_page_two_profile = dense_live_page_two.result.sort_profile orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("score_top_k", dense_live_page_two_profile.plan);
    try std.testing.expectEqualStrings("exact", dense_live_page_two_profile.exactness);

    var sparse_live = try db.search(alloc, .{
        .index_name = "sp_v1",
        .query = .{ .sparse_knn = .{
            .indices = &.{7},
            .values = &.{1.0},
            .k = 2,
        } },
        .include_stored = false,
    });
    defer sparse_live.deinit();
    try std.testing.expectEqual(@as(u32, 0), sparse_live.total_hits);
    try std.testing.expectEqual(@as(usize, 0), sparse_live.hits.len);

    var text_live = try db.search(alloc, .{
        .index_name = "ft_v1",
        .query = .{ .match = .{ .field = "body", .text = "alpha" } },
        .include_stored = false,
    });
    defer text_live.deinit();
    try std.testing.expectEqual(@as(u32, 0), text_live.total_hits);
    try std.testing.expectEqual(@as(usize, 0), text_live.hits.len);
}

test "db status_only open reads index catalog without loading index state" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    {
        var db = try DB.open(alloc, std.mem.span(path), .{});
        defer db.close();

        try db.batch(.{
            .writes = &.{
                .{ .key = "doc:a", .value = "{\"title\":\"alpha\",\"embedding\":[0.1,0.2,0.3]}" },
            },
            .sync_level = .write,
        });
        try db.addIndex(.{
            .name = "ft_v1",
            .kind = .full_text,
            .config_json = "{}",
        });
        try db.addIndex(.{
            .name = "dv_v1",
            .kind = .dense_vector,
            .config_json = "{\"field\":\"embedding\",\"dims\":3}",
        });
    }

    // Status is an observational control-plane operation. A native artifact
    // which is not referenced by CURRENT may belong to an in-flight publisher;
    // only a startup/publication owner is allowed to reclaim it.
    const vector_root = try std.fmt.allocPrint(alloc, "{s}/vector-blocks", .{std.mem.span(path)});
    defer alloc.free(vector_root);
    try std.Io.Dir.cwd().createDirPath(std.testing.io, vector_root);
    const orphan_vector_block = try std.fmt.allocPrint(alloc, "{s}/block-999999-0.afvb", .{vector_root});
    defer alloc.free(orphan_vector_block);
    var orphan_file = try std.Io.Dir.cwd().createFile(std.testing.io, orphan_vector_block, .{ .truncate = true });
    orphan_file.close(std.testing.io);

    {
        var status_db = try DB.open(alloc, std.mem.span(path), .{
            .open_mode = .status_only,
            .start_index_workers = false,
            .ttl_cleanup = .{ .enabled = false },
            .transaction_recovery = .{ .enabled = false },
            .text_merge = .{ .enabled = false },
        });
        defer status_db.close();

        try std.testing.expect(status_db.core.textIndex("ft_v1") == null);
        try std.testing.expect(status_db.core.denseIndex("dv_v1") == null);

        const indexes = try status_db.listIndexes(alloc);
        defer types.freeIndexConfigs(alloc, indexes);
        try std.testing.expectEqual(@as(usize, 2), indexes.len);
        var full_text_generation: u64 = 0;
        for (indexes) |config| {
            if (std.mem.eql(u8, config.name, "ft_v1")) {
                full_text_generation = config.coverage_generation;
                break;
            }
        }
        try std.testing.expect(full_text_generation != 0);

        const stats = try status_db.stats(alloc);
        defer types.freeDBStats(alloc, stats);
        try std.testing.expectEqual(@as(u64, 1), stats.doc_count);
        try std.testing.expectEqual(@as(u32, 2), stats.index_count);
        try std.testing.expectEqual(@as(usize, 2), stats.indexes.len);
        var saw_dense = false;
        for (stats.indexes) |item| {
            if (!std.mem.eql(u8, item.name, "dv_v1")) continue;
            saw_dense = true;
            try std.testing.expectEqual(@as(u64, 1), item.doc_count);
            try std.testing.expect(item.node_count > 0);
            try std.testing.expect(item.root_node > 0);
        }
        try std.testing.expect(saw_dense);

        const rebuild_root = try std.fmt.allocPrint(alloc, "{s}/indexes/ft_v1", .{std.mem.span(path)});
        defer alloc.free(rebuild_root);
        const stale_generation = if (full_text_generation == 1) 2 else full_text_generation - 1;
        const stale_state = backfill_state_mod.RebuildState.initOwned(rebuild_root, null, stale_generation);
        defer stale_state.clear() catch {};
        try stale_state.update("doc:stale");

        const stale_stats = try status_db.stats(alloc);
        defer types.freeDBStats(alloc, stale_stats);
        const stale_ft = blk: {
            for (stale_stats.indexes) |item| {
                if (std.mem.eql(u8, item.name, "ft_v1")) break :blk item;
            }
            return error.TestUnexpectedResult;
        };
        try std.testing.expect(!stale_ft.backfill_active);

        const current_state = backfill_state_mod.RebuildState.initOwned(rebuild_root, null, full_text_generation);
        defer current_state.clear() catch {};
        try current_state.update("doc:a");
        const rebuilding_stats = try status_db.stats(alloc);
        defer types.freeDBStats(alloc, rebuilding_stats);
        const rebuilding_ft = blk: {
            for (rebuilding_stats.indexes) |item| {
                if (std.mem.eql(u8, item.name, "ft_v1")) break :blk item;
            }
            return error.TestUnexpectedResult;
        };
        try std.testing.expect(rebuilding_ft.backfill_active);

        try current_state.clear();
        const current_state_path = try current_state.pathAlloc(alloc);
        defer alloc.free(current_state_path);
        const legacy_state = backfill_state_mod.RebuildState.init(rebuild_root);
        const legacy_state_path = try legacy_state.pathAlloc(alloc);
        defer alloc.free(legacy_state_path);
        try std.Io.Dir.cwd().writeFile(std.testing.io, .{
            .sub_path = legacy_state_path,
            .data = "doc:legacy",
        });

        const legacy_stats = try status_db.stats(alloc);
        defer types.freeDBStats(alloc, legacy_stats);
        const legacy_ft = blk: {
            for (legacy_stats.indexes) |item| {
                if (std.mem.eql(u8, item.name, "ft_v1")) break :blk item;
            }
            return error.TestUnexpectedResult;
        };
        try std.testing.expect(legacy_ft.backfill_active);
        try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().access(std.testing.io, current_state_path, .{}));
        const preserved_legacy = try std.Io.Dir.cwd().readFileAlloc(
            std.testing.io,
            legacy_state_path,
            alloc,
            .limited(1024),
        );
        defer alloc.free(preserved_legacy);
        try std.testing.expectEqualStrings("doc:legacy", preserved_legacy);
    }
    try std.Io.Dir.cwd().access(std.testing.io, orphan_vector_block, .{});
}

test "db dense and sparse vector searches apply stored symbolic filters before final paging" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\"}",
    });
    try db.addIndex(.{
        .name = "sp_v1",
        .kind = .sparse_vector,
        .config_json = "{\"field\":\"sparse\"}",
    });

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"category\":\"reject\",\"embedding\":[0,0],\"sparse\":{\"indices\":[1],\"values\":[1.0]}}" },
            .{ .key = "doc:b", .value = "{\"category\":\"keep\",\"embedding\":[10,0],\"sparse\":{\"indices\":[1],\"values\":[0.1]}}" },
        },
        .sync_level = .full_index,
    });

    var dense_result = try db.search(alloc, .{
        .index_name = "dv_v1",
        .dense = .{ .vector = &.{ 0.0, 0.0 }, .k = 1 },
        .limit = 1,
        .include_stored = false,
        .filter_query_json = "{\"term\":{\"category\":\"keep\"}}",
    });
    defer dense_result.deinit();
    try std.testing.expectEqual(@as(u32, 1), dense_result.total_hits);
    try std.testing.expectEqual(@as(usize, 1), dense_result.hits.len);
    try std.testing.expectEqualStrings("doc:b", dense_result.hits[0].id);
    {
        var txn = try db.core.store.beginProbeTxn();
        defer txn.abort();
        try std.testing.expectEqual(try doc_identity.lookupOrdinalTxn(alloc, &txn, "doc:b"), dense_result.hits[0].doc_ordinal);
    }

    var sparse_result = try db.search(alloc, .{
        .index_name = "sp_v1",
        .query = .{ .sparse_knn = .{
            .indices = &.{1},
            .values = &.{1.0},
            .k = 1,
        } },
        .limit = 1,
        .include_stored = false,
        .filter_query_json = "{\"term\":{\"category\":\"keep\"}}",
    });
    defer sparse_result.deinit();
    try std.testing.expectEqual(@as(u32, 1), sparse_result.total_hits);
    try std.testing.expectEqual(@as(usize, 1), sparse_result.hits.len);
    try std.testing.expectEqualStrings("doc:b", sparse_result.hits[0].id);
}

test "db dense stored symbolic filter candidate window covers offset pagination" {
    // Keep leak checks and failure injection; allocation backtraces are opt-in.
    var allocator_state: std.heap.SafeAllocator = .init(std.heap.page_allocator, .{ .stack_trace_frames = 0 });
    defer std.debug.assert(allocator_state.deinit() == 0);
    const alloc = if (@import("antfly_platform").env.getenvBool("ANTFLY_TEST_ALLOCATOR_TRACES")) std.testing.allocator else allocator_state.allocator();

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\"}",
    });

    var writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
    defer {
        for (writes.items) |write| {
            alloc.free(write.key);
            alloc.free(write.value);
        }
        writes.deinit(alloc);
    }
    try writes.ensureTotalCapacity(alloc, 2200);
    for (0..2200) |i| {
        try writes.append(alloc, .{
            .key = try std.fmt.allocPrint(alloc, "doc:{d:0>4}", .{i}),
            .value = try std.fmt.allocPrint(alloc, "{{\"body\":\"keep\",\"embedding\":[{d},0]}}", .{i}),
        });
    }

    try db.batch(.{
        .writes = writes.items,
        .sync_level = .full_index,
    });

    const active_dense_count: u32 = @intCast(db.core.denseIndex("dv_v1").?.index.stats().active_count);
    try std.testing.expect(active_dense_count > 1024);

    var dense_result = try db.searchDenseProfiled(alloc, .{
        .index_name = "dv_v1",
        .limit = 1,
        .offset = 1024,
        .include_stored = false,
        .filter_query_json = "{\"term\":{\"field\":\"body\",\"term\":\"keep\"}}",
    }, .{ .vector = &.{ 0.0, 0.0 }, .k = 1 });
    defer dense_result.result.deinit();

    try std.testing.expectEqual(@as(usize, 1), dense_result.result.hits.len);
    try std.testing.expectEqual(@as(u32, 1025), dense_result.result.total_hits);
    try std.testing.expectEqual(types.TotalHitsRelation.gte, dense_result.result.total_hits_relation);
    try std.testing.expectEqual(@as(u32, 1025), dense_result.profile.raw_hit_count);
}

test "db dense algebraic doc facts feed native dense and sparse symbolic filters" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\"}",
    });
    try db.addIndex(.{
        .name = "sp_v1",
        .kind = .sparse_vector,
        .config_json = "{\"field\":\"sparse\"}",
    });
    try db.addIndex(.{
        .name = "ft_v1",
        .kind = .full_text,
        .config_json = "{}",
    });
    try db.addIndex(.{
        .name = "alg",
        .kind = .algebraic,
        .config_json =
        \\{
        \\  "version": 1,
        \\  "table": "docs",
        \\  "group_fields": [
        \\    {"name":"category","path":"category","type":"string"},
        \\    {"name":"published","path":"published","type":"boolean"},
        \\    {"name":"ip","path":"ip","type":"string"},
        \\    {"name":"score","path":"score","type":"number"}
        \\  ],
        \\  "measure_fields": [
        \\    {"name":"code","path":"code","type":"string"}
        \\  ],
        \\  "materializations": [{"name":"count_by_category","op":"count","group_by":["category"]}]
        \\}
        ,
    });

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"shared token\",\"category\":\"reject\",\"published\":false,\"ip\":\"192.168.1.10\",\"score\":1.0,\"code\":\"drop\",\"meta\":{\"tier\":\"bronze\"},\"location\":{\"lat\":40.7128,\"lon\":-74.0060},\"embedding\":[0,0],\"sparse\":{\"indices\":[1],\"values\":[1.0]}}" },
            .{ .key = "doc:b", .value = "{\"body\":\"shared token\",\"category\":\"keep\",\"published\":true,\"ip\":\"10.1.2.3\",\"score\":5.0,\"code\":\"keep-code\",\"meta\":{\"tier\":\"gold\"},\"location\":{\"lat\":37.7749,\"lon\":-122.4194},\"embedding\":[10,0],\"sparse\":{\"indices\":[1],\"values\":[0.1]}}" },
        },
        .sync_level = .full_index,
    });

    const alg_entry = db.core.index_manager.algebraicIndex("alg") orelse return error.TestUnexpectedResult;
    const keep_doc_ids = (try alg_entry.index.docIdsForFilterJsonAlloc(db.core.store, "{\"term\":{\"category\":\"keep\"}}")) orelse return error.TestUnexpectedResult;
    defer alg_entry.index.freeDocIds(keep_doc_ids);
    try std.testing.expectEqual(@as(usize, 1), keep_doc_ids.len);
    try std.testing.expectEqualStrings("doc:b", keep_doc_ids[0]);
    try std.testing.expect((try db.core.index_manager.lookupDenseVectorId(db.core.store, "dv_v1", "doc:b")) != null);

    const location_lat_ids = (try alg_entry.index.docIdsForFilterJsonAlloc(db.core.store, "{\"numeric_range\":{\"path\":\"/location/lat\",\"min\":37.0,\"max\":38.0}}")) orelse return error.TestUnexpectedResult;
    defer alg_entry.index.freeDocIds(location_lat_ids);
    try std.testing.expectEqual(@as(usize, 1), location_lat_ids.len);
    try std.testing.expectEqualStrings("doc:b", location_lat_ids[0]);

    const geo_doc_ids = (try alg_entry.index.docIdsForFilterJsonAlloc(db.core.store, "{\"geo_distance\":{\"path\":\"/location\",\"lat\":37.7749,\"lon\":-122.4194,\"radius_meters\":2000}}")) orelse return error.TestUnexpectedResult;
    defer alg_entry.index.freeDocIds(geo_doc_ids);
    try std.testing.expectEqual(@as(usize, 1), geo_doc_ids.len);
    try std.testing.expectEqualStrings("doc:b", geo_doc_ids[0]);

    const geo_shape_doc_ids = (try alg_entry.index.docIdsForFilterJsonAlloc(db.core.store, "{\"geo_shape\":{\"path\":\"/location\",\"relation\":\"intersects\",\"polygons\":[[{\"lat\":37.0,\"lon\":-123.0},{\"lat\":38.0,\"lon\":-123.0},{\"lat\":38.0,\"lon\":-122.0},{\"lat\":37.0,\"lon\":-122.0}]]}}")) orelse return error.TestUnexpectedResult;
    defer alg_entry.index.freeDocIds(geo_shape_doc_ids);
    try std.testing.expectEqual(@as(usize, 1), geo_shape_doc_ids.len);
    try std.testing.expectEqualStrings("doc:b", geo_shape_doc_ids[0]);

    var dense_keep = try db.searchDenseProfiled(alloc, .{
        .index_name = "dv_v1",
        .limit = 1,
        .include_stored = false,
        .filter_query_json = "{\"term\":{\"category\":\"keep\"}}",
        .exclusion_query_json = "{\"term\":{\"path\":\"/meta/tier\",\"value\":\"bronze\"}}",
        .require_algebraic_filter_resolution = true,
    }, .{ .vector = &.{ 0.0, 0.0 }, .k = 1 });
    defer dense_keep.result.deinit();
    try std.testing.expectEqual(@as(u32, 1), dense_keep.result.total_hits);
    try std.testing.expectEqual(@as(usize, 1), dense_keep.result.hits.len);
    try std.testing.expectEqualStrings("doc:b", dense_keep.result.hits[0].id);
    try std.testing.expectEqual(@as(u32, 1), dense_keep.profile.raw_hit_count);
    {
        const status_value = alg_entry.index.status();
        try std.testing.expectEqual(@as(u64, 1), status_value.vector_filter_attempt_count);
        try std.testing.expectEqual(@as(u64, 1), status_value.vector_filter_resolved_count);
        try std.testing.expectEqual(@as(u64, 1), status_value.vector_filter_include_doc_id_count);
        try std.testing.expectEqual(@as(u64, 1), status_value.vector_filter_exclude_doc_id_count);
    }

    try std.testing.expectError(error.UnsupportedQueryRequest, db.searchDenseProfiled(alloc, .{
