        ,
    });
    try db.batch(.{
        .writes = &.{
            .{ .key = "fact:works", .value = "{\"relations\":[{\"source\":\"alice\",\"target\":\"acme\",\"weight\":0.5}]}" },
            .{ .key = "fact:founded", .value = "{\"relations\":[{\"source\":\"alice\",\"target\":\"acme\",\"weight\":0.9}]}" },
