test "db materializes doc->entity mention edges as provenance and clears them on delete" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    // The graph index materializes the relations_v1 extraction asset and, with
    // mention_edge_type set, emits doc->entity provenance edges from the durable
    // resolution artifact.
    try db.addIndex(.{
        .name = "prov_graph",
        .kind = .graph,
        .config_json =
        \\{
        \\  "source":{"artifact":"relations_v1","mention_edge_type":"mentions",
        \\    "format":"extraction_relation","path":"$.relations[*]"},
        \\  "artifact":{"name":"relations_v1","kind":"asset","source":{"type":"field","value":"relations"},"content_type":"application/json"}
        \\}
        ,
    });
    try db.addResolver(.{
        .name = "kg",
        .table = "entities",
        .source_artifact = "relations_v1",
        .resolution_artifact = "resolution_v1",
        .key_template = "{{ lower _entity.label }}/{{ slug _entity.text }}",
        .config_generation = 1,
    });

    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value =
            \\{"relations":{"entities":[{"id":"e0","label":"person","text":"Ada Lovelace"},{"id":"e1","label":"org","text":"Antfly"}]}}
            ,
        }},
        .sync_level = .enrichments,
    });
    try db.runUntilIdle();

    const resolution_key = try internal_keys.resolutionArtifactKeyAlloc(alloc, "doc:a", "resolution_v1");
    defer alloc.free(resolution_key);
    const resolution_handoff_key = try resolution_handoff.keyAlloc(alloc, resolution_key);
    defer alloc.free(resolution_handoff_key);
    {
        const raw = try db.core.store.get(alloc, resolution_key);
        defer alloc.free(raw);
        try std.testing.expect(std.mem.indexOf(u8, raw, "\"decision\":\"new\"") != null);
        try std.testing.expect(std.mem.indexOf(u8, raw, "person/ada_lovelace") != null);
        try std.testing.expect(std.mem.indexOf(u8, raw, "org/antfly") != null);
    }
    {
        const raw = try db.core.store.get(alloc, resolution_handoff_key);
        defer alloc.free(raw);
        try std.testing.expectEqual(@sizeOf(resolution_handoff.Value), raw.len);
    }

    const ada_edge_key = try internal_keys.graphEdgeArtifactKeyAlloc(alloc, "doc:a", "prov_graph", "mentions", "person/ada_lovelace");
    defer alloc.free(ada_edge_key);
    {
        const raw = try db.core.store.get(alloc, ada_edge_key);
        defer alloc.free(raw);
        try std.testing.expect(std.mem.indexOf(u8, raw, "\"target_table\":\"entities\"") != null);
    }

    const ada_mention_key = try resolutionMentionArtifactKeyAlloc(alloc, "doc:a", "relations_v1", "resolution_v1", "e0");
    defer alloc.free(ada_mention_key);
    {
        const raw = try db.core.store.get(alloc, ada_mention_key);
        defer alloc.free(raw);
        try std.testing.expect(std.mem.indexOf(u8, raw, "\"_schema\":\"antfly.resolution_mention.v1\"") != null);
        try std.testing.expect(std.mem.indexOf(u8, raw, "\"source_artifact\":\"relations_v1\"") != null);
        try std.testing.expect(std.mem.indexOf(u8, raw, "\"source_artifact_key\"") != null);
        try std.testing.expect(std.mem.indexOf(u8, raw, "\"resolution_artifact\":\"resolution_v1\"") != null);
        try std.testing.expect(std.mem.indexOf(u8, raw, "\"resolution_artifact_key\"") != null);
        try std.testing.expect(std.mem.indexOf(u8, raw, "\"local_id\":\"e0\"") != null);
        try std.testing.expect(std.mem.indexOf(u8, raw, "\"key\":\"person/ada_lovelace\"") != null);
        try std.testing.expect(std.mem.indexOf(u8, raw, "\"text\":\"Ada Lovelace\"") != null);
    }

    // Outbound: doc:a mentions both canonical entities.
    {
        const out = try waitForGraphEdges(alloc, &db, "prov_graph", "doc:a", "mentions", .out, 2);
        defer graph_mod.GraphIndex.freeEdges(alloc, out);
        try std.testing.expectEqual(@as(usize, 2), out.len);
        // Each mention edge records the resolved DocRef target table so the
        // endpoint can be hydrated cross-table.
        for (out) |edge| {
            try std.testing.expect(std.mem.indexOf(u8, edge.metadata, "\"target_table\":\"entities\"") != null);
        }
    }
    // Inbound provenance: "which documents mention this entity" == inbound edges.
    {
        const inbound = try waitForGraphEdges(alloc, &db, "prov_graph", "person/ada_lovelace", "mentions", .in, 1);
        defer graph_mod.GraphIndex.freeEdges(alloc, inbound);
        try std.testing.expectEqual(@as(usize, 1), inbound.len);
        try std.testing.expectEqualStrings("doc:a", inbound[0].source);
        try std.testing.expectEqualStrings("person/ada_lovelace", inbound[0].target);
    }

    // Deleting the source document clears its mention edges (delete-on-source-delete).
    try db.batch(.{ .deletes = &.{"doc:a"}, .sync_level = .enrichments });
    try db.runUntilIdle();
    {
        const out = try db.getEdges(alloc, "prov_graph", "doc:a", "mentions", .out);
        defer graph_mod.GraphIndex.freeEdges(alloc, out);
        try std.testing.expectEqual(@as(usize, 0), out.len);
        const inbound = try db.getEdges(alloc, "prov_graph", "person/ada_lovelace", "mentions", .in);
        defer graph_mod.GraphIndex.freeEdges(alloc, inbound);
        try std.testing.expectEqual(@as(usize, 0), inbound.len);
    }
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, ada_mention_key));
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, resolution_handoff_key));
}

test "db materializes entity-sourced relation edges once resolution lands" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    // extraction_graph relations reference extraction entities by local id;
    // once the resolver mints canonical keys, the relation edges re-render
    // with the canonical ENTITY as their topological source while the
    // producing document keeps artifact-key ownership (zig/AUTOSCHEMA.md).
    try db.addIndex(.{
        .name = "kg_graph",
        .kind = .graph,
        .config_json =
        \\{
        \\  "source":{"artifact":"kg_v1","mention_edge_type":"mentions","format":"extraction_graph"},
        \\  "artifact":{"name":"kg_v1","kind":"asset","source":{"type":"field","value":"kg"},"content_type":"application/json"},
        \\  "edge_types":[{"name":"mentions"},{"name":"works_at"}]
        \\}
        ,
    });
    try db.addResolver(.{
        .name = "kg",
        .table = "entities",
        .source_artifact = "kg_v1",
        .resolution_artifact = "resolution_v1",
        .key_template = "{{ lower _entity.label }}/{{ slug _entity.text }}",
        .config_generation = 1,
    });

    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value =
            \\{"kg":{"entities":[{"id":"e0","label":"person","text":"Ada Lovelace"},{"id":"e1","label":"org","text":"Antfly"}],"relations":[{"type":"works_at","source":"e0","target":"e1"}]}}
            ,
        }},
        .sync_level = .enrichments,
    });
    try db.runUntilIdle();

    // The entity-sourced edge: person --works_at--> org, applied from the
    // canonical source node, owned by doc:a in the artifact key.
    {
        const out = try waitForGraphEdges(alloc, &db, "kg_graph", "person/ada_lovelace", "works_at", .out, 1);
        defer graph_mod.GraphIndex.freeEdges(alloc, out);
        try std.testing.expectEqual(@as(usize, 1), out.len);
        try std.testing.expectEqualStrings("org/antfly", out[0].target);
    }
    const owned_key = try internal_keys.graphEdgeArtifactKeyWithSourceAlloc(alloc, "doc:a", "kg_graph", "works_at", "org/antfly", "person/ada_lovelace");
    defer alloc.free(owned_key);
    {
        const raw = try db.core.store.get(alloc, owned_key);
        defer alloc.free(raw);
        // The resolved endpoint's home table rides the edge metadata so
        // traversal and node admission hydrate the cross-table target, the
        // same contract mention edges carry.
        try std.testing.expect(std.mem.indexOf(u8, raw, "\"target_table\":\"entities\"") != null);
    }
    // No document-sourced or local-id-sourced variant of the relation exists.
    {
        const doc_sourced = try db.getEdges(alloc, "kg_graph", "doc:a", "works_at", .out);
        defer graph_mod.GraphIndex.freeEdges(alloc, doc_sourced);
        try std.testing.expectEqual(@as(usize, 0), doc_sourced.len);
        const local_sourced = try db.getEdges(alloc, "kg_graph", "e0", "works_at", .out);
        defer graph_mod.GraphIndex.freeEdges(alloc, local_sourced);
        try std.testing.expectEqual(@as(usize, 0), local_sourced.len);
    }

    // Deleting the producing document retires the entity-sourced edge with
    // its owner.
    try db.batch(.{ .deletes = &.{"doc:a"}, .sync_level = .enrichments });
    try db.runUntilIdle();
    {
        const out = try db.getEdges(alloc, "kg_graph", "person/ada_lovelace", "works_at", .out);
        defer graph_mod.GraphIndex.freeEdges(alloc, out);
        try std.testing.expectEqual(@as(usize, 0), out.len);
    }
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, owned_key));
}

test "db canonicalizes positional extractor endpoints once resolution lands" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    // GLiNER2.5 boundary payloads carry no per-entity ids: relations
    // reference entities positionally through `entity_index` endpoint
    // objects, and confidence is spelled "score". The resolver assigns each
    // id-less mention its decimal array position as the local id, and the
    // materializer derives the same identity for `entity_index` endpoints,
    // so resolution injection canonicalizes them like id-carrying payloads
    // (the examples/dogfood extractor shape).
    try db.addIndex(.{
        .name = "gliner_graph",
        .kind = .graph,
        .config_json =
        \\{
        \\  "source":{"artifact":"relations_v1","path":"$.relations[*]","format":"extraction_relation","mention_edge_type":"mentions"},
        \\  "artifact":{"name":"relations_v1","kind":"asset","source":{"type":"field","value":"extraction"},"content_type":"application/json"},
        \\  "edge_types":[{"name":"mentions"},{"name":"tested_by"}]
        \\}
        ,
    });
    try db.addResolver(.{
        .name = "kg",
        .table = "entities",
        .source_artifact = "relations_v1",
        .resolution_artifact = "resolution_v1",
        .key_template = "{{ lower _entity.label }}/{{ slug _entity.text }}",
        .config_generation = 1,
    });

    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value =
            \\{"extraction":{"entities":[{"label":"component","text":"DataServer","score":0.69,"start":64,"end":74},{"label":"test","text":"VOPR","score":0.98,"start":45,"end":49}],"relations":[{"type":"tested_by","source":{"entity_index":0},"target":{"entity_index":1},"score":0.9}]}}
            ,
        }},
        .sync_level = .enrichments,
    });
    try db.runUntilIdle();

    // The relation edge starts from the canonical source ENTITY resolved
    // through its positional identity, not from the producing document.
    {
        const out = try waitForGraphEdges(alloc, &db, "gliner_graph", "component/dataserver", "tested_by", .out, 1);
        defer graph_mod.GraphIndex.freeEdges(alloc, out);
        try std.testing.expectEqual(@as(usize, 1), out.len);
        try std.testing.expectEqualStrings("test/vopr", out[0].target);
    }
    // Both positional mentions also produced document-owned mention edges.
    {
        const mentions = try db.getEdges(alloc, "gliner_graph", "doc:a", "mentions", .out);
        defer graph_mod.GraphIndex.freeEdges(alloc, mentions);
        try std.testing.expectEqual(@as(usize, 2), mentions.len);
    }
    // The edge is owned by the producing document in the artifact key, and no
    // document-sourced variant of the relation leaked.
    const owned_key = try internal_keys.graphEdgeArtifactKeyWithSourceAlloc(alloc, "doc:a", "gliner_graph", "tested_by", "test/vopr", "component/dataserver");
    defer alloc.free(owned_key);
    {
        const raw = try db.core.store.get(alloc, owned_key);
        defer alloc.free(raw);
        try std.testing.expect(std.mem.indexOf(u8, raw, "\"target_table\":\"entities\"") != null);
    }
    {
        const doc_sourced = try db.getEdges(alloc, "gliner_graph", "doc:a", "tested_by", .out);
        defer graph_mod.GraphIndex.freeEdges(alloc, doc_sourced);
        try std.testing.expectEqual(@as(usize, 0), doc_sourced.len);
    }

    // Document deletion retires the entity-sourced edge with its owner.
    try db.batch(.{ .deletes = &.{"doc:a"}, .sync_level = .enrichments });
    try db.runUntilIdle();
    {
        const out = try db.getEdges(alloc, "gliner_graph", "component/dataserver", "tested_by", .out);
        defer graph_mod.GraphIndex.freeEdges(alloc, out);
        try std.testing.expectEqual(@as(usize, 0), out.len);
    }
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, owned_key));
}

test "db resolver removal retires resolution artifacts and mention graph state" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var sink = FakePromotionSink{ .alloc = alloc };
    defer sink.deinit();

    var db = try DB.open(alloc, std.mem.span(path), .{
        .executor = .{ .backend = .manual },
        .start_index_workers = false,
        .entity_sink = sink.sink(),
    });
    defer db.close();

    try db.addIndex(.{
        .name = "prov_graph",
        .kind = .graph,
        .config_json =
        \\{
        \\  "source":{"artifact":"relations_v1","mention_edge_type":"mentions",
        \\    "format":"extraction_relation","path":"$.relations[*]"},
        \\  "artifact":{"name":"relations_v1","kind":"asset","source":{"type":"field","value":"relations"},"content_type":"application/json"}
        \\}
        ,
    });
    try db.addResolver(.{
        .name = "kg",
        .table = "entities",
        .source_artifact = "relations_v1",
        .resolution_artifact = "resolution_v1",
        .key_template = "{{ lower _entity.label }}/{{ slug _entity.text }}",
        .config_generation = 1,
    });

    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value =
            \\{"relations":{"entities":[{"id":"e0","label":"person","text":"Ada Lovelace"},{"id":"e1","label":"person","text":"Ada Lovelace"}]}}
            ,
        }},
        .sync_level = .enrichments,
    });
    try db.runUntilIdle();

    const asset_key = try internal_keys.artifactNamedPrefixAlloc(alloc, "doc:a", "asset", "relations_v1");
    defer alloc.free(asset_key);
    {
        const raw = try db.core.store.get(alloc, asset_key);
        defer alloc.free(raw);
        try std.testing.expect(std.mem.indexOf(u8, raw, "Ada Lovelace") != null);
    }

    const resolution_key = try internal_keys.resolutionArtifactKeyAlloc(alloc, "doc:a", "resolution_v1");
    defer alloc.free(resolution_key);
    const resolution_handoff_key = try resolution_handoff.keyAlloc(alloc, resolution_key);
    defer alloc.free(resolution_handoff_key);
    {
        const raw = try db.core.store.get(alloc, resolution_key);
        defer alloc.free(raw);
        try std.testing.expect(std.mem.indexOf(u8, raw, "person/ada_lovelace") != null);
    }
    {
        const raw = try db.core.store.get(alloc, resolution_handoff_key);
        defer alloc.free(raw);
        try std.testing.expectEqual(@sizeOf(resolution_handoff.Value), raw.len);
    }

    const graph_edge_key = try internal_keys.graphEdgeArtifactKeyAlloc(alloc, "doc:a", "prov_graph", "mentions", "person/ada_lovelace");
    defer alloc.free(graph_edge_key);
    {
        const raw = try db.core.store.get(alloc, graph_edge_key);
        defer alloc.free(raw);
        try std.testing.expect(raw.len > 0);
    }
    const mention_artifact_key = try resolutionMentionArtifactKeyAlloc(alloc, "doc:a", "relations_v1", "resolution_v1", "e0");
    defer alloc.free(mention_artifact_key);
    const second_mention_artifact_key = try resolutionMentionArtifactKeyAlloc(alloc, "doc:a", "relations_v1", "resolution_v1", "e1");
    defer alloc.free(second_mention_artifact_key);
    {
        const raw = try db.core.store.get(alloc, mention_artifact_key);
        defer alloc.free(raw);
        try std.testing.expect(std.mem.indexOf(u8, raw, "\"_artifact_kind\":\"resolution_mention\"") != null);
    }
    {
        const raw = try db.core.store.get(alloc, second_mention_artifact_key);
        defer alloc.free(raw);
        try std.testing.expect(std.mem.indexOf(u8, raw, "\"_artifact_kind\":\"resolution_mention\"") != null);
    }
    {
        const out = try waitForGraphEdges(alloc, &db, "prov_graph", "doc:a", "mentions", .out, 1);
        defer graph_mod.GraphIndex.freeEdges(alloc, out);
        try std.testing.expectEqual(@as(usize, 1), out.len);
        var parsed_metadata = try std.json.parseFromSlice(std.json.Value, alloc, out[0].metadata, .{});
        defer parsed_metadata.deinit();
        const metadata = parsed_metadata.value.object;
        try std.testing.expectEqual(@as(i64, 2), metadata.get("mention_count").?.integer);
        const mention_artifact_keys = metadata.get("mention_artifact_keys").?.array.items;
        try std.testing.expectEqual(@as(usize, 2), mention_artifact_keys.len);
        try std.testing.expectEqualStrings(mention_artifact_key, mention_artifact_keys[0].string);
        try std.testing.expectEqualStrings(second_mention_artifact_key, mention_artifact_keys[1].string);
    }
    {
        const inbound = try waitForGraphEdges(alloc, &db, "prov_graph", "person/ada_lovelace", "mentions", .in, 1);
        defer graph_mod.GraphIndex.freeEdges(alloc, inbound);
        try std.testing.expectEqual(@as(usize, 1), inbound.len);
    }

    try std.testing.expect(try db.removeResolver("kg"));

    const resolvers = try db.listResolvers(alloc);
    defer {
        for (resolvers) |*cfg| cfg.deinit(alloc);
        alloc.free(resolvers);
    }
    try std.testing.expectEqual(@as(usize, 0), resolvers.len);

    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, resolution_key));
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, resolution_handoff_key));
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, graph_edge_key));
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, mention_artifact_key));
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, second_mention_artifact_key));
    {
        const raw = try db.core.store.get(alloc, asset_key);
        defer alloc.free(raw);
        try std.testing.expect(std.mem.indexOf(u8, raw, "Ada Lovelace") != null);
    }
    {
        const inbound = try db.getEdges(alloc, "prov_graph", "person/ada_lovelace", "mentions", .in);
        defer graph_mod.GraphIndex.freeEdges(alloc, inbound);
        try std.testing.expectEqual(@as(usize, 0), inbound.len);
        const out = try db.getEdges(alloc, "prov_graph", "doc:a", "mentions", .out);
        defer graph_mod.GraphIndex.freeEdges(alloc, out);
        try std.testing.expectEqual(@as(usize, 0), out.len);
    }
}

test "db does not materialize review-band resolution as canonical mention edges" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    // Keep production workers enabled: this is the regression for the original
    // race between background resolver catch-up and the runUntilIdle fence.
    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.addIndex(.{
        .name = "prov_graph",
        .kind = .graph,
        .config_json =
        \\{
        \\  "source":{"artifact":"relations_v1","mention_edge_type":"mentions",
        \\    "format":"extraction_relation","path":"$.relations[*]"},
        \\  "artifact":{"name":"relations_v1","kind":"asset","source":{"type":"field","value":"relations"},"content_type":"application/json"}
        \\}
        ,
    });
    try db.addResolver(.{
        .name = "kg",
        .table = "entities",
        .source_artifact = "relations_v1",
        .resolution_artifact = "resolution_v1",
        .key_template = "{{ lower _entity.label }}/{{ slug _entity.text }}",
        .candidate_search = "prefix",
        .scorer_json =
        \\{ "comparisons": [ { "name": "name", "left": "canonical_text", "right": "canonical_name",
        \\  "levels": [
        \\    { "when": "exact", "weight": 8.0 },
        \\    { "when": "jaro_winkler > 0.92", "weight": 5.0 },
        \\    { "when": "jaro_winkler > 0.85", "weight": 2.0 },
        \\    { "else": true, "weight": -6.0 }
        \\  ] } ],
        \\  "combine": { "bias": -3.0 }, "decision": { "match": 0.9, "review": 0.6 } }
        ,
        .config_generation = 1,
    });

    const existing_key = try internal_keys.documentKeyAlloc(alloc, "person/ada_lovlace");
    defer alloc.free(existing_key);
    try db.core.store.put(existing_key,
        \\{"canonical_name":"Ada Lovlace","label":"person"}
    );

    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value =
            \\{"relations":{"entities":[{"id":"e0","label":"person","text":"Ada Lovelace"},{"id":"e1","label":"person","text":"Charles Babbage"}],"relations":[{"type":"knows","source":"e1","target":"e0"}]}}
            ,
        }},
        .sync_level = .enrichments,
    });
    try db.runUntilIdle();

    const resolution_key = try internal_keys.resolutionArtifactKeyAlloc(alloc, "doc:a", "resolution_v1");
    defer alloc.free(resolution_key);
    const raw = try db.core.store.get(alloc, resolution_key);
    defer alloc.free(raw);
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, raw, .{});
    defer parsed.deinit();
    const ent = parsed.value.object.get("entities").?.array.items[0].object;
    try std.testing.expectEqualStrings("review", ent.get("decision").?.string);
    try std.testing.expectEqualStrings("person/ada_lovelace", ent.get("doc_ref").?.object.get("key").?.string);

    // Only the cleanly resolved mention has a canonical edge; the reviewed
    // one is withheld.
    {
        const out = try waitForGraphEdges(alloc, &db, "prov_graph", "doc:a", "mentions", .out, 1);
        defer graph_mod.GraphIndex.freeEdges(alloc, out);
        try std.testing.expectEqual(@as(usize, 1), out.len);
        try std.testing.expectEqualStrings("person/charles_babbage", out[0].target);
    }
    // The relation references the reviewed entity, and a review entry
    // carries a PROVISIONAL key: the relation must stay absent until a
    // curator approves — from the canonical source, the producing document,
    // and the local id alike.
    {
        const knows = try db.getEdges(alloc, "prov_graph", "person/charles_babbage", "knows", .out);
        defer graph_mod.GraphIndex.freeEdges(alloc, knows);
        try std.testing.expectEqual(@as(usize, 0), knows.len);
        const doc_sourced = try db.getEdges(alloc, "prov_graph", "doc:a", "knows", .out);
        defer graph_mod.GraphIndex.freeEdges(alloc, doc_sourced);
        try std.testing.expectEqual(@as(usize, 0), doc_sourced.len);
        const local_sourced = try db.getEdges(alloc, "prov_graph", "e1", "knows", .out);
        defer graph_mod.GraphIndex.freeEdges(alloc, local_sourced);
        try std.testing.expectEqual(@as(usize, 0), local_sourced.len);
    }

    _ = try db.recordReviewDecision("doc:a", "relations_v1", "resolution_v1", "e0", .match, "entities", "person/ada_lovelace");
    try db.runUntilIdle();

    const curated_raw = try db.core.store.get(alloc, resolution_key);
    defer alloc.free(curated_raw);
    var curated = try std.json.parseFromSlice(std.json.Value, alloc, curated_raw, .{});
    defer curated.deinit();
    const curated_ent = curated.value.object.get("entities").?.array.items[0].object;
    try std.testing.expectEqualStrings("match", curated_ent.get("decision").?.string);
    try std.testing.expectEqualStrings("person/ada_lovelace", curated_ent.get("doc_ref").?.object.get("key").?.string);

    // runUntilIdle is the lifecycle fence: a blocked promotion sink must not
    // prevent the independent graph consumer from publishing this edge.
    const curated_edges = try waitForGraphEdges(alloc, &db, "prov_graph", "doc:a", "mentions", .out, 2);
    defer graph_mod.GraphIndex.freeEdges(alloc, curated_edges);
    try std.testing.expectEqual(@as(usize, 2), curated_edges.len);
    var saw_ada = false;
    for (curated_edges) |edge| {
        if (std.mem.eql(u8, edge.target, "person/ada_lovelace")) saw_ada = true;
    }
    try std.testing.expect(saw_ada);

    // Approval also releases the withheld relation, entity-sourced from the
    // canonical endpoint.
    const curated_knows = try waitForGraphEdges(alloc, &db, "prov_graph", "person/charles_babbage", "knows", .out, 1);
    defer graph_mod.GraphIndex.freeEdges(alloc, curated_knows);
    try std.testing.expectEqual(@as(usize, 1), curated_knows.len);
    try std.testing.expectEqualStrings("person/ada_lovelace", curated_knows[0].target);
}

test "db mention edge weight is fused from extractor trust and mention confidence" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
    });
    defer db.close();
    var promotion_sink = FakePromotionSink{ .alloc = alloc };
    defer promotion_sink.deinit();
    db.setEntitySink(promotion_sink.sink());

    try db.addIndex(.{
        .name = "prov_graph",
        .kind = .graph,
        .config_json =
        \\{
        \\  "source":{"artifact":"relations_v1","mention_edge_type":"mentions",
        \\    "format":"extraction_relation","path":"$.relations[*]"},
        \\  "artifact":{"name":"relations_v1","kind":"asset","source":{"type":"field","value":"relations"},"content_type":"application/json"}
        \\}
        ,
    });
    // A resolver declaring noisy_or fusion: this extractor is trusted 0.9, no
    // graph prior. The mention asserts confidence 0.8, so the edge weight is
    // fuse(noisy_or, [{0.8, 0.9}], prior=0, prior_weight=0) = 1-(1-0.72) = 0.72.
    try db.addResolver(.{
        .name = "kg",
        .table = "entities",
        .source_artifact = "relations_v1",
        .resolution_artifact = "resolution_v1",
        .key_template = "{{ lower _entity.label }}/{{ slug _entity.text }}",
        .fusion_combine = "noisy_or",
        .fusion_trust = 0.9,
        .config_generation = 1,
    });

    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value =
            \\{"relations":{"entities":[{"id":"e0","label":"person","text":"Ada Lovelace","confidence":0.8}]}}
            ,
        }},
        .sync_level = .enrichments,
    });
    try db.runUntilIdle();

    const resolution_key = try internal_keys.resolutionArtifactKeyAlloc(alloc, "doc:a", "resolution_v1");
    defer alloc.free(resolution_key);
    const initial_resolution = try db.core.store.get(alloc, resolution_key);
    defer alloc.free(initial_resolution);

    const out = try db.getEdges(alloc, "prov_graph", "doc:a", "mentions", .out);
    defer graph_mod.GraphIndex.freeEdges(alloc, out);
    try std.testing.expectEqual(@as(usize, 1), out.len);
    try std.testing.expectEqualStrings("person/ada_lovelace", out[0].target);
    // Calibrated weight, not the legacy 1.0.
    try std.testing.expectApproxEqAbs(@as(f64, 0.72), out[0].weight, 1e-9);
    try std.testing.expectEqual(@as(usize, 1), promotion_sink.count());

    // Mention confidence belongs to the source extraction, not the resolution
    // decision. The resolution bytes therefore stay unchanged, but replay must
    // still reconcile the source-dependent graph weight.
    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value =
            \\{"relations":{"entities":[{"id":"e0","label":"person","text":"Ada Lovelace","confidence":0.4}]}}
            ,
        }},
        .sync_level = .enrichments,
    });
    try db.runUntilIdle();

    const updated_resolution = try db.core.store.get(alloc, resolution_key);
    defer alloc.free(updated_resolution);
    try std.testing.expectEqualStrings(initial_resolution, updated_resolution);

    const updated = try db.getEdges(alloc, "prov_graph", "doc:a", "mentions", .out);
    defer graph_mod.GraphIndex.freeEdges(alloc, updated);
    try std.testing.expectEqual(@as(usize, 1), updated.len);
    try std.testing.expectApproxEqAbs(@as(f64, 0.36), updated[0].weight, 1e-9);
    try std.testing.expectEqual(@as(usize, 1), promotion_sink.count());
    try std.testing.expect(!db.pendingWorkStats().promotion.blocked);
}

test "db rewriteEntityEdges repoints provenance edges to a merge survivor" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.addIndex(.{
        .name = "prov_graph",
        .kind = .graph,
        .config_json =
        \\{
        \\  "source":{"artifact":"relations_v1","mention_edge_type":"mentions",
        \\    "format":"extraction_relation","path":"$.relations[*]"},
        \\  "artifact":{"name":"relations_v1","kind":"asset","source":{"type":"field","value":"relations"},"content_type":"application/json"}
        \\}
        ,
    });
    try db.addResolver(.{
        .name = "kg",
        .table = "entities",
        .source_artifact = "relations_v1",
        .resolution_artifact = "resolution_v1",
        .key_template = "{{ lower _entity.label }}/{{ slug _entity.text }}",
        .config_generation = 1,
    });
    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value =
            \\{"relations":{"entities":[{"id":"e0","label":"person","text":"Ada Lovelace"}]}}
            ,
        }},
        .sync_level = .enrichments,
    });
    try db.runUntilIdle();

    // The mention edge points at the resolved DocRef from the resolution artifact.
    {
        const inbound = try waitForGraphEdges(alloc, &db, "prov_graph", "person/ada_lovelace", "mentions", .in, 1);
        defer graph_mod.GraphIndex.freeEdges(alloc, inbound);
        try std.testing.expectEqual(@as(usize, 1), inbound.len);
    }

    // Merge person/ada_lovelace into a canonical survivor: rewrite its edges.
    const rewritten = try db.rewriteEntityEdges(alloc, "prov_graph", "person/ada_lovelace", "person/ada_canonical");
    try std.testing.expectEqual(@as(usize, 1), rewritten);
    try db.runUntilIdle();

    // Inbound edges moved from the merged-away key to the survivor.
    {
        const old_inbound = try db.getEdges(alloc, "prov_graph", "person/ada_lovelace", "mentions", .in);
        defer graph_mod.GraphIndex.freeEdges(alloc, old_inbound);
        try std.testing.expectEqual(@as(usize, 0), old_inbound.len);

        const new_inbound = try db.getEdges(alloc, "prov_graph", "person/ada_canonical", "mentions", .in);
        defer graph_mod.GraphIndex.freeEdges(alloc, new_inbound);
        try std.testing.expectEqual(@as(usize, 1), new_inbound.len);
        try std.testing.expectEqualStrings("doc:a", new_inbound[0].source);
        try std.testing.expectEqualStrings("person/ada_canonical", new_inbound[0].target);
    }
    // Curation and producer ownership survive reopen and re-resolution of the
    // unchanged extraction. No higher-priority direct contender is invented.
    try std.testing.expectEqual(@as(usize, 0), try db.rewriteEntityEdges(alloc, "prov_graph", "person/ada_lovelace", "person/ada_canonical"));
    db.close();
    db = try DB.open(alloc, std.mem.span(path), .{});
    try db.batch(.{ .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"updated\",\"relations\":{\"entities\":[{\"id\":\"e0\",\"label\":\"person\",\"text\":\"Ada Lovelace\"}]}}" }}, .sync_level = .enrichments });
    try db.runUntilIdle();
    {
        const edges = try db.getEdges(alloc, "prov_graph", "person/ada_canonical", "mentions", .in);
        defer graph_mod.GraphIndex.freeEdges(alloc, edges);
        try std.testing.expectEqual(@as(usize, 1), edges.len);
        const old = try db.getEdges(alloc, "prov_graph", "person/ada_lovelace", "mentions", .in);
        defer graph_mod.GraphIndex.freeEdges(alloc, old);
        try std.testing.expectEqual(@as(usize, 0), old.len);
        const key = try internal_keys.graphEdgeArtifactKeyAlloc(alloc, "doc:a", "prov_graph", "mentions", "person/ada_canonical");
        defer alloc.free(key);
        const prefix = try internal_keys.graphGlobalEdgeContenderEdgePrefixAlloc(alloc, "prov_graph", db.core.index_manager.graphIndex("prov_graph").?.config.coverage_generation, key);
        defer alloc.free(prefix);
        const contenders = try db.core.store.scanPrefix(alloc, prefix);
        defer docstore_mod.DocStore.freeResults(alloc, contenders);
        try std.testing.expectEqual(@as(usize, 1), contenders.len);
        const view = (try graph_edge_contender.decode(contenders[0].value, db.core.index_manager.graphIndex("prov_graph").?.config.coverage_generation)).?;
        try std.testing.expect(view.source_priority != graph_mod.direct_source_priority);
    }
    try db.batch(.{ .deletes = &.{"doc:a"}, .sync_level = .enrichments });
    try db.runUntilIdle();
    const retired = try db.getEdges(alloc, "prov_graph", "person/ada_canonical", "mentions", .in);
    defer graph_mod.GraphIndex.freeEdges(alloc, retired);
    try std.testing.expectEqual(@as(usize, 0), retired.len);
}

test "db rewriteEntityEdges preserves owners TTL and destination collisions" {
    const alloc = std.testing.allocator;
    for ([_]bool{ false, true }) |asset| {
        var directory = try TestDirectory.init("entity-rewrite-collision");
        defer directory.cleanup();
        const options: OpenOptions = .{ .online_source_authority = .native, .identity_namespace = .{ .table_id = 1, .shard_id = 2, .range_id = 3 } };
        var db = try DB.open(alloc, directory.path(), options);
        defer db.close();
        try db.addIndex(.{ .name = "g", .kind = .graph, .config_json = if (asset)
            "{\"ttl\":{\"duration\":\"1h\"},\"source\":{\"artifact\":\"relations\"},\"artifact\":{\"name\":\"relations\",\"kind\":\"asset\",\"source\":{\"type\":\"field\",\"value\":\"relations\"},\"content_type\":\"application/json\"}}"
        else
            "{\"ttl\":{\"duration\":\"1h\"}}" });
        if (asset) {
            try db.batch(.{ .writes = &.{.{ .key = "doc:a", .value =
                \\{"relations":[{"type":"links","source":"node:a","target":{"document_id":"old"},"weight":1},{"type":"links","source":"node:a","target":{"document_id":"survivor"},"weight":2}]}
            }}, .sync_level = .enrichments });
        } else {
            try db.batch(.{ .writes = &.{.{ .key = "doc:a", .value = "{}" }}, .graph_writes = &.{
                .{ .index_name = "g", .source = "node:a", .owner = "doc:a", .target = "old", .edge_type = "links", .weight = 1 },
                .{ .index_name = "g", .source = "node:a", .owner = "doc:a", .target = "survivor", .edge_type = "links", .weight = 2 },
            }, .sync_level = .full_index });
        }
        if (asset) try db.batch(.{ .writes = &.{.{ .key = "doc:b", .value = "{\"relations\":[{\"type\":\"links\",\"source\":\"node:a\",\"target\":{\"document_id\":\"old\"},\"weight\":3}]}" }}, .sync_level = .enrichments });
        try db.runUntilIdle();
        const destination = try internal_keys.graphEdgeArtifactKeyWithSourceAlloc(alloc, "doc:a", "g", "links", "survivor", "node:a");
        defer alloc.free(destination);
        const before_raw = try db.core.store.get(alloc, destination);
        defer alloc.free(before_raw);
        var before = try enrichment_artifact_codec.decodeGraphEdgeAlloc(alloc, before_raw);
        defer before.deinit(alloc);
        try std.testing.expect(before.ttl_created_ns != 0);
        const before_sequence = blk: {
            var read = try db.core.store.beginReadTxn();
            defer read.abort();
            break :blk (try @import("../source_authority.zig").load(&read)).?.sequence;
        };
        try std.testing.expectEqual(@as(usize, 1), try db.rewriteEntityEdges(alloc, "g", "old", "survivor"));
        {
            var read = try db.core.store.beginReadTxn();
            defer read.abort();
            try std.testing.expectEqual(before_sequence + 1, (try @import("../source_authority.zig").load(&read)).?.sequence);
        }
        try db.runUntilIdle();
        db.close();
        db = try DB.open(alloc, directory.path(), options);
        try db.runUntilIdle();
        const after_raw = try db.core.store.get(alloc, destination);
        defer alloc.free(after_raw);
        var after = try enrichment_artifact_codec.decodeGraphEdgeAlloc(alloc, after_raw);
        defer after.deinit(alloc);
        try std.testing.expectEqual(before.ttl_created_ns, after.ttl_created_ns);
        try std.testing.expectEqual(@as(f64, 2), after.weight);
        const old = try db.getEdges(alloc, "g", "old", "links", .in);
        defer graph_mod.GraphIndex.freeEdges(alloc, old);
        try std.testing.expectEqual(@as(usize, 0), old.len);
        const survivor = try db.getEdges(alloc, "g", "survivor", "links", .in);
        defer graph_mod.GraphIndex.freeEdges(alloc, survivor);
        try std.testing.expectEqual(@as(usize, 1), survivor.len);
        try std.testing.expectEqualStrings("node:a", survivor[0].source);
        if (asset) {
            const count_key = try internal_keys.graphEdgeContenderCountKeyAlloc(alloc, "doc:a", "g");
            defer alloc.free(count_key);
            const count = try db.core.store.get(alloc, count_key);
            defer alloc.free(count);
            try std.testing.expectEqual(@as(?usize, 1), try graph_edge_contender.decodeVisibleCount(count, db.core.index_manager.graphIndex("g").?.config.coverage_generation));
        }
        try db.batch(.{ .deletes = &.{"doc:a"}, .sync_level = .enrichments });
        try db.runUntilIdle();
        if (asset) {
            const remaining = try db.getEdges(alloc, "g", "survivor", "links", .in);
            defer graph_mod.GraphIndex.freeEdges(alloc, remaining);
            try std.testing.expectEqual(@as(usize, 1), remaining.len);
            try db.batch(.{ .deletes = &.{"doc:b"}, .sync_level = .enrichments });
            try db.runUntilIdle();
        }
        const retired = try db.getEdges(alloc, "g", "survivor", "links", .in);
        defer graph_mod.GraphIndex.freeEdges(alloc, retired);
        try std.testing.expectEqual(@as(usize, 0), retired.len);
    }
}

test "db rewriteEntityEdges fences stale adjacency and leaves unrelated replay pending" {
    const alloc = std.testing.allocator;
    var directory = try TestDirectory.init("entity-rewrite-cut");
    defer directory.cleanup();
    var db = try DB.open(alloc, directory.path(), .{ .start_index_workers = false, .start_optional_runtimes = false });
    defer db.close();
    try db.addIndex(.{ .name = "g", .kind = .graph, .config_json = "{}" });
    try db.addIndex(.{ .name = "unrelated", .kind = .graph, .config_json = "{}" });
    try db.batch(.{ .graph_writes = &.{.{ .index_name = "g", .source = "before", .target = "old", .edge_type = "links" }}, .sync_level = .full_index });
    try db.runUntilIdle();
    // A writer replaces the source while retaining the target. Primary state
    // has never lacked an inbound edge, but adjacency still names `before`.
    try db.batch(.{
        .graph_deletes = &.{.{ .index_name = "g", .source = "before", .target = "old", .edge_type = "links" }},
        .graph_writes = &.{
            .{ .index_name = "g", .source = "after", .target = "old", .edge_type = "links" },
            .{ .index_name = "unrelated", .source = "another", .target = "old", .edge_type = "links" },
        },
        .sync_level = .write,
    });
    const Admission = struct {
        calls: usize = 0,
        fn check(ptr: *anyopaque, owner: *DB) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (owner.core.apply_mutex.tryLockShared()) {
                owner.core.apply_mutex.unlockShared();
                return error.ApplyAdmissionMissing;
            }
            if (!owner.core.index_manager.graph_primary_publication.tryLockExclusive()) return error.PublicationAcquiredBeforeApply;
            owner.core.index_manager.graph_primary_publication.unlockExclusive();
            self.calls += 1;
        }
    };
    var admission: Admission = .{};
    test_entity_rewrite_apply_admitted = .{ .ctx = &admission, .call = Admission.check };
    defer test_entity_rewrite_apply_admitted = null;
    const unrelated_applied = try db.managedIndexAppliedSequence(alloc, "unrelated");
    try std.testing.expectEqual(@as(usize, 1), try db.rewriteEntityEdges(alloc, "g", "old", "survivor"));
    try std.testing.expectEqual(@as(usize, 2), admission.calls);
    test_entity_rewrite_apply_admitted = null;
    try std.testing.expectEqual(unrelated_applied, try db.managedIndexAppliedSequence(alloc, "unrelated"));
    const new_key = try internal_keys.graphEdgeArtifactKeyAlloc(alloc, "after", "g", "links", "survivor");
    defer alloc.free(new_key);
    const payload = try db.core.store.get(alloc, new_key);
    defer alloc.free(payload);
    try db.runUntilIdle();
    const edges = try db.getEdges(alloc, "g", "survivor", "links", .in);
    defer graph_mod.GraphIndex.freeEdges(alloc, edges);
    try std.testing.expectEqual(@as(usize, 1), edges.len);
    try std.testing.expectEqualStrings("after", edges[0].source);
}

test "db rewriteEntityEdges retains scoped source replay and curation" {
    const alloc = std.testing.allocator;
    for ([_]bool{ false, true }) |chunk| {
        var directory = try TestDirectory.init("entity-rewrite-scoped");
        defer directory.cleanup();
        var db = try DB.open(alloc, directory.path(), .{});
        defer db.close();
        try db.addIndex(.{ .name = "g", .kind = .graph, .config_json = "{\"source\":{\"artifact\":\"relations\",\"mention_edge_type\":\"mentions\"},\"artifact\":{\"name\":\"relations\",\"kind\":\"asset\",\"source\":{\"type\":\"field\",\"value\":\"relations\"},\"content_type\":\"application/json\"}}" });
        try db.addResolver(.{ .name = "kg", .table = "entities", .source_artifact = "relations", .source_artifact_kind = if (chunk) .chunk else .asset, .resolution_artifact = "resolution", .key_template = "{{ lower _entity.label }}/{{ slug _entity.text }}", .config_generation = 1 });
        const source_key = if (chunk) try internal_keys.documentUnitChunkArtifactKeyAlloc(alloc, "doc:a", "relations", "page:1", 0) else try internal_keys.documentUnitArtifactKeyAlloc(alloc, "doc:a", "relations", "page:1");
        defer alloc.free(source_key);
        const extraction = "{\"entities\":[{\"id\":\"e0\",\"label\":\"person\",\"text\":\"Ada Lovelace\"},{\"id\":\"e1\",\"label\":\"person\",\"text\":\"Ada Lovelace\"}]}";
        // Seed the authoritative scoped resolution explicitly, through the
        // production resolver seam. The rewrite owns already-materialized
        // contributions; source-production scheduling is a separate contract.
        try db.core.store.putBatch(&.{.{ .key = source_key, .value = extraction }}, &.{});
        var artifacts: resolution_runtime_mod.DbArtifactStore(@TypeOf(db.core.store.runtime_store)) = .{ .store = &db.core.store.runtime_store, .index_manager = db.core.index_manager };
        const outcome = (try resolution_runtime_mod.processChangedExtraction(alloc, db.core.index_manager.resolvers.items, artifacts.artifactStore(), null, source_key, null, null)).?;
        defer alloc.free(outcome.resolution_key);
        const initial_resolution = try db.core.store.get(alloc, outcome.resolution_key);
        defer alloc.free(initial_resolution);
        _ = try db.applyDocumentArtifactChildRangeBatch(.{ .artifact_writes = &.{.{ .key = outcome.resolution_key, .value = initial_resolution }}, .sync_level = .write });
        try db.runUntilIdle();
        const before = try db.getEdges(alloc, "g", "person/ada_lovelace", "mentions", .in);
        defer graph_mod.GraphIndex.freeEdges(alloc, before);
        try std.testing.expectEqual(@as(usize, 1), before.len);
        try std.testing.expectEqual(@as(usize, 1), try db.rewriteEntityEdges(alloc, "g", "person/ada_lovelace", "survivor"));
        try db.runUntilIdle();
        db.close();
        db = try DB.open(alloc, directory.path(), .{});
        try db.runUntilIdle();
        const resolution_key = try internal_keys.resolutionArtifactKeyAlloc(alloc, source_key, "resolution");
        defer alloc.free(resolution_key);
        const raw = try db.core.store.get(alloc, resolution_key);
        defer alloc.free(raw);
        const parsed = try std.json.parseFromSlice(std.json.Value, alloc, raw, .{});
        defer parsed.deinit();
        for (parsed.value.object.get("entities").?.array.items) |entity|
            try std.testing.expectEqualStrings("survivor", entity.object.get("doc_ref").?.object.get("key").?.string);
        const edges = try db.getEdges(alloc, "g", "survivor", "mentions", .in);
        defer graph_mod.GraphIndex.freeEdges(alloc, edges);
        try std.testing.expectEqual(@as(usize, 1), edges.len);
    }
}

test "db rewriteEntityEdges clears acknowledged replication outbox and retains failed acknowledgement" {
    const alloc = std.testing.allocator;
    const contract = @import("replication_contract.zig");
    const FakePublisher = struct {
        fail: bool = false,
        barrier: *MutationBarrier,
        published: usize = 0,
        fn next(_: *anyopaque) u64 {
            return 1;
        }
        fn identity(_: *anyopaque) contract.Publisher.Identity {
            return .{ .table_id = 0, .shard_id = 0, .timeline_id = 1, .epoch = 1 };
        }
        fn publish(mirror: contract.AsyncEffectMirror, kind: @import("durable_outbox.zig").Kind, payload: []const u8, _: doc_identity.Namespace) !u64 {
            const self: *@This() = @ptrCast(@alignCast(mirror.publisher.ptr));
            try std.testing.expectEqual(@import("durable_outbox.zig").Kind.primary_effect, kind);
            try std.testing.expect(replication_effects_mod.primary_effect.isPrimaryEffect(payload));
            self.published += 1;
            return 1;
        }
        fn recover(_: contract.AsyncEffectMirror, _: @import("durable_outbox.zig").Kind, _: @import("durable_outbox.zig").DurableReplicationOutbox, _: doc_identity.Namespace) !u64 {
            return error.UnexpectedRecovery;
        }
        fn preflight(_: contract.AsyncEffectMirror, _: bool) !void {}
        fn complete(mirror: contract.AsyncEffectMirror, _: u64) !void {
            const self: *@This() = @ptrCast(@alignCast(mirror.publisher.ptr));
            // A replacement seed must freeze the local commit/tail pair
            // before remote recovery can acknowledge this mutation.
            var capture = self.barrier.tryAcquireExclusive() orelse return error.CheckpointCaptureBlockedByCompletionWait;
            capture.release();
            if (self.fail) return error.TestAcknowledgementFailed;
        }
        fn publisher(self: *@This()) contract.Publisher {
            return .{ .ptr = self, .vtable = &.{ .next_lsn = next, .identity = identity, .publish = publish, .recover = recover, .preflight = preflight, .complete = complete } };
        }
    };
    for ([_]bool{ false, true }) |fail| {
        var directory = try TestDirectory.init("entity-rewrite-ha");
        defer directory.cleanup();
        var db = try DB.open(alloc, directory.path(), .{ .start_optional_runtimes = false });
        defer db.close();
        try db.addIndex(.{ .name = "g", .kind = .graph, .config_json = "{}" });
        try db.batch(.{ .graph_writes = &.{.{ .index_name = "g", .source = "doc:a", .target = "old", .edge_type = "links" }}, .sync_level = .full_index });
        var barrier: MutationBarrier = .{};
        var publisher: FakePublisher = .{ .fail = fail, .barrier = &barrier };
        // A coarse batch publisher cannot represent the exact artifact and
        // producer-ownership changes. Reject before mutating or publishing.
        db.local_execution.replication_async_batch_mirror = .{ .publisher = publisher.publisher() };
        try std.testing.expectError(error.ReplicationPublisherUnavailable, db.rewriteEntityEdges(alloc, "g", "old", "survivor"));
        try std.testing.expectEqual(@as(usize, 0), publisher.published);
        {
            const unchanged = try db.getEdges(alloc, "g", "old", "links", .in);
            defer graph_mod.GraphIndex.freeEdges(alloc, unchanged);
            try std.testing.expectEqual(@as(usize, 1), unchanged.len);
            var pending = try durable_outbox_store.readPending(alloc, db.core.store);
            defer pending.deinit(alloc);
            try std.testing.expect(pending.isEmpty());
        }
        db.local_execution.replication_async_batch_mirror = null;
        db.local_execution.replication_async_effect_mirror = .{ .publisher = publisher.publisher(), .mutation_barrier = &barrier };
        if (fail) try std.testing.expectError(error.TestAcknowledgementFailed, db.rewriteEntityEdges(alloc, "g", "old", "survivor")) else try std.testing.expectEqual(@as(usize, 1), try db.rewriteEntityEdges(alloc, "g", "old", "survivor"));
        try std.testing.expectEqual(@as(usize, 1), publisher.published);
        var pending = try durable_outbox_store.readPending(alloc, db.core.store);
        defer pending.deinit(alloc);
        try std.testing.expectEqual(!fail, pending.isEmpty());
        // Avoid recovery through a fixture publisher after its lifetime ends.
        db.local_execution.replication_async_effect_mirror = null;
        if (!fail) {
            db.close();
            db = try DB.open(alloc, directory.path(), .{ .start_optional_runtimes = false });
            try db.batch(.{ .writes = &.{.{ .key = "still-writable", .value = "{}" }}, .sync_level = .write });
        }
    }
}

test "db rewriteEntityEdges indexes a multi-owner mutation in linear work" {
    const alloc = std.testing.allocator;
    var directory = try TestDirectory.init("entity-rewrite-many-owners");
    defer directory.cleanup();
    var db = try DB.open(alloc, directory.path(), .{ .start_index_workers = false });
    defer db.close();
    try db.addIndex(.{ .name = "g", .kind = .graph, .config_json = "{\"ttl\":{\"duration\":\"1h\"},\"source\":{\"artifact\":\"relations\"},\"artifact\":{\"name\":\"relations\",\"kind\":\"asset\",\"source\":{\"type\":\"field\",\"value\":\"relations\"},\"content_type\":\"application/json\"}}" });
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const scratch = arena.allocator();
    const owner_count = 64;
    var documents: [owner_count]types.BatchWrite = undefined;
    var owners: [owner_count][]const u8 = undefined;
    for (&documents, &owners, 0..) |*document, *owner, i| {
        owner.* = try std.fmt.allocPrint(scratch, "doc:{d}", .{i});
        document.* = .{ .key = owner.*, .value = "{\"relations\":[{\"type\":\"links\",\"target\":{\"document_id\":\"old\"}}]}" };
    }
    try db.batch(.{ .writes = &documents, .sync_level = .enrichments });
    try db.runUntilIdle();
    var examined: usize = 0;
    execution_resources.test_graph_overlay_examined = &examined;
    defer execution_resources.test_graph_overlay_examined = null;
    try std.testing.expectEqual(@as(usize, owner_count), try db.rewriteEntityEdges(alloc, "g", "old", "survivor"));
    execution_resources.test_graph_overlay_examined = null;
    // Rebuilding the accumulated overlay per owner exceeds this linear bound.
    try std.testing.expect(examined >= owner_count);
    try std.testing.expect(examined <= owner_count * 32);
    try db.runUntilIdle();
    const edges = try db.getEdges(alloc, "g", "survivor", "links", .in);
    defer graph_mod.GraphIndex.freeEdges(alloc, edges);
    try std.testing.expectEqual(@as(usize, owner_count), edges.len);
    try db.batch(.{ .deletes = &owners, .sync_level = .write });
    try db.runUntilIdle();
    const retired = try db.getEdges(alloc, "g", "survivor", "links", .in);
    defer graph_mod.GraphIndex.freeEdges(alloc, retired);
    try std.testing.expectEqual(@as(usize, 0), retired.len);
}

