test "db complete-snapshot scope expands graph traversal through tagged entity nodes" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.addIndex(.{
        .name = "prov_graph",
        .kind = .graph,
        .config_json =
        \\{
        \\  "source":{"artifact":"relations_v1","mention_edge_type":"mentions",
        \\    "format":"extraction_relation","path":"$.relations[*]"},
        \\  "artifact":{"name":"relations_v1","kind":"asset","source":{"type":"field","value":"relations"},"content_type":"application/json"}
        \\}
        ,
    });
    try db.addResolver(.{
        .name = "kg",
        .table = "entities",
        .source_artifact = "relations_v1",
        .resolution_artifact = "resolution_v1",
        .key_template = "{{ lower _entity.label }}/{{ slug _entity.text }}",
        .config_generation = 1,
    });
    try db.batch(.{
        .writes = &.{
            .{
                .key = "doc:a",
                .value =
                \\{"relations":{"entities":[{"id":"e0","label":"person","text":"Ada Lovelace"}]}}
                ,
            },
            .{
                .key = "doc:b",
                .value =
                \\{"relations":{"entities":[{"id":"e0","label":"person","text":"Ada Lovelace"}]}}
                ,
            },
        },
        .sync_level = .enrichments,
    });
    try db.runUntilIdle();

    const walk = graph_query_mod.GraphQuery{
        .query_type = .traverse,
        .index_name = "prov_graph",
        .start_nodes = .{ .keys = &.{"doc:a"} },
        .params = .{
            .edge_types = &.{"mentions"},
            .direction = .both,
            .max_depth = 2,
            .deduplicate = true,
        },
    };

    // Without the scope the tagged entity node stays terminal: doc:b is
    // unreachable through it.
    {
        var result = try db.search(alloc, .{
            .graph_queries = &.{.{ .name = "walk", .query = walk }},
        });
        defer result.deinit();
        for (result.graph_results[0].nodes) |node| {
            try std.testing.expect(!std.mem.eql(u8, node.key, "doc:b"));
        }
    }

    // The API read source marks admitted single-group requests as
    // complete-snapshot; the local executor then walks doc -> entity -> doc
    // THROUGH the tagged node in one traversal.
    {
        var result = try db.search(alloc, .{
            .graph_queries = &.{.{ .name = "walk", .query = walk }},
            .graph_owning_table = "docs",
            .graph_index_complete_snapshot = true,
        });
        defer result.deinit();
        var saw_entity = false;
        var saw_doc_b = false;
        for (result.graph_results[0].nodes) |node| {
            if (std.mem.eql(u8, node.key, "person/ada_lovelace")) {
                try std.testing.expectEqualStrings("entities", node.table.?);
                saw_entity = true;
            }
            if (std.mem.eql(u8, node.key, "doc:b")) {
                try std.testing.expect(node.table == null);
                saw_doc_b = true;
            }
        }
        try std.testing.expect(saw_entity and saw_doc_b);
    }
}

test "db graph hydration rejects table-qualified entity nodes in local snapshots" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.addIndex(.{
        .name = "prov_graph",
        .kind = .graph,
        .config_json =
        \\{
        \\  "source":{"artifact":"relations_v1","mention_edge_type":"mentions",
        \\    "format":"extraction_relation","path":"$.relations[*]"},
        \\  "artifact":{"name":"relations_v1","kind":"asset","source":{"type":"field","value":"relations"},"content_type":"application/json"}
        \\}
        ,
    });
    try db.addResolver(.{
        .name = "kg",
        .table = "entities",
        .source_artifact = "relations_v1",
        .resolution_artifact = "resolution_v1",
        .key_template = "{{ lower _entity.label }}/{{ slug _entity.text }}",
        .config_generation = 1,
    });
    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value =
            \\{"tenant":"visible","relations":{"entities":[{"id":"e0","label":"person","text":"Ada Lovelace"}]}}
            ,
        }},
        .sync_level = .enrichments,
    });
    try db.runUntilIdle();

    const mention_query = graph_query_mod.GraphQuery{
        .query_type = .neighbors,
        .index_name = "prov_graph",
        .start_nodes = .{ .keys = &.{"doc:a"} },
        .params = .{ .edge_types = &.{"mentions"}, .direction = .out, .max_depth = 1 },
        .include_documents = true,
    };

    const Authorizer = struct {
        fn authorize(
            _: ?*const anyopaque,
            _: Allocator,
            _: []const u8,
        ) !types.GraphTableReadAuthorization {
            return .{ .allowed = false };
        }
    };
    try std.testing.expectError(
        error.UnsupportedQueryRequest,
        db.search(alloc, .{
            .graph_queries = &.{.{ .name = "m", .query = mention_query }},
            .graph_table_read_authorizer = .{
                .ctx = null,
                .authorize_table = Authorizer.authorize,
            },
        }),
    );

    // A table-local DB snapshot cannot hydrate the entity binding. Reject the
    // request instead of returning a successful response with a missing
    // document; coordinator-backed execution owns cross-table hydration.
    try std.testing.expectError(
        error.UnsupportedQueryRequest,
        db.search(alloc, .{ .graph_queries = &.{.{ .name = "m", .query = mention_query }} }),
    );

    // Resolver targets are cross-table even when the graph's default node model
    // is document. Reverse traversal admits that external start by edge role,
    // while still enforcing the source-table predicate on the reached document.
    {
        var result = try db.search(alloc, .{
            .graph_queries = &.{.{
                .name = "reverse_mentions",
                .query = .{
                    .query_type = .neighbors,
                    .index_name = "prov_graph",
                    .start_nodes = .{ .keys = &.{"person/ada_lovelace"} },
                    .params = .{
                        .edge_types = &.{"mentions"},
                        .direction = .in,
                        .max_depth = 1,
                    },
                },
            }},
            .filter_query_json = "{\"term\":{\"tenant\":\"visible\"}}",
        });
        defer result.deinit();
        try std.testing.expectEqual(@as(u32, 1), result.graph_results[0].total_hits);
        try std.testing.expectEqualStrings("doc:a", result.graph_results[0].nodes[0].key);
    }
    {
        var result = try db.search(alloc, .{
            .graph_queries = &.{.{
                .name = "bidirectional_mentions",
                .query = .{
                    .query_type = .neighbors,
                    .index_name = "prov_graph",
                    .start_nodes = .{ .keys = &.{"person/ada_lovelace"} },
                    .params = .{
                        .edge_types = &.{"mentions"},
                        .direction = .both,
                        .max_depth = 1,
                    },
                },
            }},
            .filter_query_json = "{\"term\":{\"tenant\":\"visible\"}}",
        });
        defer result.deinit();
        try std.testing.expectEqual(@as(u32, 1), result.graph_results[0].total_hits);
        try std.testing.expectEqualStrings("doc:a", result.graph_results[0].nodes[0].key);
    }

    // Even a coincidentally equal key in the source table must not satisfy an
    // entities-qualified identity. The coordinator must read the named table.
    try db.batch(.{
        .writes = &.{.{ .key = "person/ada_lovelace", .value =
        \\{"entity_type":"person","canonical_name":"Ada Lovelace"}
        }},
        .sync_level = .write,
    });
    try db.runUntilIdle();
    try std.testing.expectError(
        error.UnsupportedQueryRequest,
        db.search(alloc, .{ .graph_queries = &.{.{ .name = "m", .query = mention_query }} }),
    );
}

