// Regression test for the dogfood in-process ingest livelock: a dense_vector
// index that consumes a two-stage chunk-then-embed pipeline through the
// plural `sources` config form (`embedding_names`, not the singular
// `embedding_name` every other chunk-dense test above uses) never advanced
// its durable dense-artifact target counter past 0, because
// `denseArtifactTargetsForArtifact` (enrichment/enrichment_runtime.zig) only
// matched `entry.embedding_name` and `entry.config.name`. `runUntilIdle`
// (db.zig's `canAdvanceDerivedToTargetAsync`) then deferred forever to
// artifact-maintenance debt that nothing drains, because expected_docs was
// permanently stuck at 0 while indexed kept climbing. See ENRICHMENTS.md's
// "Two-Stream Execution Model" and DENSE_INDEXING_LIFECYCLE.md.
test "db dense index consuming a chunk-then-embed source via plural sources config converges its target counter" {
    try test_support.expectPluralSourceDenseConvergence(null);
}

// Shared real-DB scenario. Server tests supply their wire-status observer; the
// local suite checks convergence without importing the server API facade.
const plural_source_dense_test_support = if (builtin.is_test) struct {
    pub fn expectPluralSourceDenseConvergence(comptime observe: ?*const fn (Allocator, std.json.Value, types.DBStats) anyerror!void) !void {
        const alloc = std.testing.allocator;
        const Admission = enum { before_rows, after_chunks, after_embeddings };
        for ([_]Admission{ .before_rows, .after_chunks, .after_embeddings }) |admission| {
            var path_tmp = try TestDirectory.init("db");
            defer path_tmp.cleanup();
            const path = path_tmp.path().ptr;
            defer cleanupTempDir(path);

            const document = "{\"url\":\"data:text/plain;base64,YWxwaGEgYmV0YSBnYW1tYSBkZWx0YSBlcHNpbG9uIHpldGEgZXRhIHRoZXRhIGlvdGEga2FwcGEgbGFtYmRhIG11IG51IHhpIG9taWNyb24gcGkgcmhvIHNpZ21hIHRhdSB1cHNpbG9uIHBoaSBjaGkgcHNpIG9tZWdh\"}";
            var counting = CountingDenseEmbedder{};
            var db = try DB.open(alloc, std.mem.span(path), .{
                .enrichment = .{
                    .owner_id = "worker-a",
                    .dense_embedder = counting.interface(),
                },
            });
            defer db.close();

            try db.addEnrichment(.{
                .name = "document_units_v1",
                .kind = .asset,
                .field = "url",
                .content_type = "application/json",
                .producer_json = "{\"type\":\"document_extraction\",\"config\":{}}",
            });
            try db.addEnrichment(.{
                .name = "document_chunks_v1",
                .kind = .chunk,
                .field = "text",
                .source_artifact_name = "document_units_v1",
                .chunk_size = 8,
            });
            if (admission != .before_rows) {
                try db.batch(.{ .writes = &.{.{ .key = "doc:a", .value = document }}, .sync_level = .full_index });
                try db.runUntilIdle();
            }
            try db.addEnrichment(.{
                .name = "document_chunk_dense_v1",
                .kind = .embedding,
                .field = "text",
                .source_artifact_name = "document_chunks_v1",
                .expected_dims = 3,
            });
            // Also exercise admission after the embeddings themselves are durable:
            // the new consumer must bootstrap existing one-to-many artifacts.
            if (admission == .after_embeddings) try db.runUntilIdle();
            // Resolve the actual public config to storage config so the runtime and
            // API observe precisely the same incarnation and config fingerprint.
            var config = try std.json.parseFromSlice(std.json.Value, alloc,
                \\{"name":"dv_document_chunks","type":"embeddings","dimension":3,"sources":[{"artifact":"document_chunk_dense_v1"}],"_index_incarnation":42}
            , .{});
            defer config.deinit();
            const config_json = try @import("../../api/table_index_config.zig").extractIndexConfigJson(alloc, "dv_document_chunks", config.value);
            defer alloc.free(config_json);
            try db.addIndex(.{
                .name = "dv_document_chunks",
                .kind = .dense_vector,
                .coverage_generation = 42,
                .config_json = config_json,
            });
            if (admission == .before_rows) {
                try db.batch(.{ .writes = &.{.{ .key = "doc:a", .value = document }}, .sync_level = .full_index });
            }
            try db.runUntilIdle();

            try std.testing.expect(counting.calls > 0);

            const active_count = db.core.index_manager.denseIndex("dv_document_chunks").?.index.stats().active_count;
            try std.testing.expect(active_count > 1);
            const stats = try db.stats(alloc);
            defer types.freeDBStats(alloc, stats);
            const item = for (stats.indexes) |item| {
                if (std.mem.eql(u8, item.name, "dv_document_chunks")) break item;
            } else return error.TestUnexpectedResult;
            try std.testing.expect(item.publication_target_ready);
            try std.testing.expectEqual(active_count, item.publication_target_count);
            try std.testing.expect(item.coverage_summary_ready);
            try std.testing.expectEqual(@as(u64, 1), item.coverage_produced_count);
            if (observe) |observer| try observer(alloc, config.value, stats);

            // Before the fix this counter was permanently stuck at 0 (the guarded
            // embedding-artifact write path never found a matching counter target),
            // so `canAdvanceDerivedToTargetAsync` could never observe
            // `denseCoverageMatchesTarget` and would defer to artifact maintenance
            // forever.
            try std.testing.expectEqual(
                @as(?u64, active_count),
                try DB.loadDenseArtifactTargetCounter(alloc, db.core.store, "dv_document_chunks"),
            );

            // The counter equality above proves the durable target watermark
            // converges; also prove the index is actually searchable end to end.
            var search_result = try db.search(alloc, .{
                .index_name = "dv_document_chunks",
                .query = .{ .dense_knn = .{ .vector = &.{ 0, 0, 0 }, .k = 5 } },
                .limit = 5,
                .search_effort = 1.0,
            });
            defer search_result.deinit();
            try std.testing.expect(search_result.total_hits > 0);
        }
    }
} else struct {};

// `checkTargetAdvanceNoProgress` is `runUntilIdle`'s opt-in stall guard (task
// requirement: fail fast with a named, bounded diagnostic instead of
// spinning on `canAdvanceDerivedToTargetAsync`'s deferred artifact-maintenance
// check indefinitely). Exercised directly against a real (otherwise idle) DB
// rather than by reproducing a genuinely broken pipeline, so the pass/fail
// signal is deterministic and does not depend on timing.
test "runUntilIdle no-progress guard fails fast with a named stuck-index diagnostic" {
    @import("antfly_test_error_logs").expectErrorLogs(1);
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();

    try std.testing.expect(db.lastRunUntilIdleNoProgressDiagnostic() == null);

    const now_ns = monotonicTimeNs();
    // Simulate `canAdvanceDerivedToTargetAsync` having observed
    // "chunk_vectors" stuck (indexed=5017, expected_docs=0, matching the
    // dogfood reproduction) for longer than the configured timeout.
    try noteTargetAdvanceStuck(db.async_context, "chunk_vectors", now_ns -| (2 * std.time.ns_per_s), 5017, 0);
    try std.testing.expectError(error.RunUntilIdleNoProgress, db.checkTargetAdvanceNoProgress(1 * std.time.ns_per_s));

    const diagnostic = db.lastRunUntilIdleNoProgressDiagnostic() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("chunk_vectors", diagnostic.index_name);
    try std.testing.expectEqual(@as(u64, 5017), diagnostic.indexed);
    try std.testing.expectEqual(@as(u64, 0), diagnostic.expected);

    // A shorter observed duration than the configured timeout must not fire.
    clearTargetAdvanceStuck(db.async_context, "chunk_vectors");
    try noteTargetAdvanceStuck(db.async_context, "chunk_vectors", now_ns, 12, 0);
    try db.checkTargetAdvanceNoProgress(60 * std.time.ns_per_s);
}

test "runUntilIdle no-progress guard interrupts the threaded derived wait" {
    // Reviewer-reported P2: with background index workers the guard only ran
    // AFTER runDerivedUntilWithOptions returned, and the threaded
    // waitForAll has no deadline — a derived index that can never satisfy
    // its replay target parked the wait forever and the configured timeout
    // never fired. The stall diagnostic now rides the wait's cancellation
    // checkpoint, so the wait itself is interrupted. This test exercises the
    // real threaded wait path: workers enabled, a target the workers cannot
    // reach, and a stuck record older than the timeout. Environments whose io
    // backend starts no derived workers skip (the guard mechanics have their
    // own unit test below); the expected-error-log declaration must come
    // AFTER the skip decision or the boundary check flags the skip itself.
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();
    if (!db.executor.hasWorkers()) return error.SkipZigTest;
    @import("antfly_test_error_logs").expectErrorLogs(1);

    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"a\"}" }},
        .sync_level = .write,
    });

    const now_ns = monotonicTimeNs();
    try noteTargetAdvanceStuck(db.async_context, "chunk_vectors", now_ns -| (2 * std.time.ns_per_s), 5017, 0);
    // A target far past anything committed: without the in-wait guard this
    // call never returns on a stuck index.
    const unreachable_sequence = db.core.nextDerivedSequence() + 1_000_000;
    try std.testing.expectError(error.RunUntilIdleNoProgress, db.runDerivedUntilWithOptions(unreachable_sequence, .{
        .no_progress_timeout_ns = 1 * std.time.ns_per_s,
    }));

    const diagnostic = db.lastRunUntilIdleNoProgressDiagnostic() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("chunk_vectors", diagnostic.index_name);
    clearTargetAdvanceStuck(db.async_context, "chunk_vectors");
}

test "runUntilIdle stall guard checkpoint fires on a stuck index and stays quiet otherwise" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();

    var guard = DB.TargetAdvanceStallGuard{ .db = &db, .timeout_ns = 1 * std.time.ns_per_s };
    const token = guard.token();

    // Healthy: the checkpoint is silent, so the wait keeps waiting.
    try token.check();

    const now_ns = monotonicTimeNs();
    try noteTargetAdvanceStuck(db.async_context, "chunk_vectors", now_ns -| (2 * std.time.ns_per_s), 5017, 0);
    guard.last_check_ns.store(0, .monotonic);
    try std.testing.expectError(error.DerivedTargetAdvanceStuck, token.check());
    // The wait layer sees the interrupt as a cancellation, which is what
    // breaks waitForAllWithVisibilityWait out of its poll loop.
    guard.last_check_ns.store(0, .monotonic);
    try std.testing.expect(token.isCancelled());

    // Under the recheck throttle the checkpoint stays quiet even while stuck.
    guard.last_check_ns.store(monotonicTimeNs(), .monotonic);
    try token.check();

    // Stuck record cleared: the guard goes quiet again (a transient interrupt
    // resumes the wait).
    clearTargetAdvanceStuck(db.async_context, "chunk_vectors");
    guard.last_check_ns.store(0, .monotonic);
    try token.check();
}

