test "db document extraction unit ranges split by text bytes" {
    const alloc = std.testing.allocator;
    const text_a = try alloc.alloc(u8, 600 * 1024);
    defer alloc.free(text_a);
    const text_b = try alloc.alloc(u8, 400 * 1024);
    defer alloc.free(text_b);
    const text_c = try alloc.alloc(u8, 100 * 1024);
    defer alloc.free(text_c);
    @memset(text_a, 'a');
    @memset(text_b, 'b');
    @memset(text_c, 'c');

    const units = [_]document_extraction_mod.Unit{
        .{
            .unit_id = @constCast("unit:a"),
            .unit_type = @constCast("document"),
            .text = text_a,
            .method = @constCast("text"),
        },
        .{
            .unit_id = @constCast("unit:b"),
            .unit_type = @constCast("document"),
            .text = text_b,
            .method = @constCast("text"),
        },
        .{
            .unit_id = @constCast("unit:c"),
            .unit_type = @constCast("document"),
            .text = text_c,
            .method = @constCast("text"),
        },
    };

    try std.testing.expectEqual(@as(usize, 2), documentExtractionUnitRangeCount(&units));
    try std.testing.expectEqual(@as(usize, 0), documentExtractionUnitRangeIndex(&units, 0));
    try std.testing.expectEqual(@as(usize, 0), documentExtractionUnitRangeIndex(&units, 1));
    try std.testing.expectEqual(@as(usize, 1), documentExtractionUnitRangeIndex(&units, 2));
}

test "db document extraction failure preserves last-known-good children and recovers" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.addEnrichment(.{
        .name = "document_units_v1",
        .kind = .asset,
        .field = "url",
        .content_type = "application/json",
        .producer_json = "{\"type\":\"document_extraction\",\"config\":{}}",
    });

    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value = "{\"url\":\"data:text/plain;base64,YWxwaGE=\"}",
        }},
        .sync_level = .full_index,
    });

    var before = (try db.getDocumentArtifactManifest(alloc, "doc:a", "document_units_v1")) orelse return error.TestUnexpectedResult;
    defer before.deinit(alloc);
    try std.testing.expectEqualStrings("text", before.route_type);
    try std.testing.expect(before.last_error_code == null);
    try std.testing.expectEqual(@as(usize, 1), before.child_ranges.len);
    const stale_unit_key = try alloc.dupe(u8, before.child_ranges[0].start_key);
    defer alloc.free(stale_unit_key);
    {
        const stale_unit = try db.core.store.get(alloc, stale_unit_key);
        defer alloc.free(stale_unit);
    }

    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value = "{\"url\":\"data:text/plain;base64\"}",
        }},
        .sync_level = .full_index,
    });

    var after = (try db.getDocumentArtifactManifest(alloc, "doc:a", "document_units_v1")) orelse return error.TestUnexpectedResult;
    defer after.deinit(alloc);
    try std.testing.expectEqual(@as(u64, before.generation + 1), after.generation);
    try std.testing.expectEqualStrings("error", after.route_type);
    try std.testing.expectEqualStrings("failed", after.merge_status);
    try std.testing.expectEqual(@as(usize, 1), after.unit_count);
    try std.testing.expectEqual(@as(usize, 1), after.child_range_count);
    try std.testing.expect(after.state_json != null);
    try std.testing.expect(after.last_error_code != null);
    try std.testing.expectEqualStrings("InvalidDataUri", after.last_error_code.?);
    try std.testing.expect(after.last_error_message != null);
    try std.testing.expectEqualStrings("remote content download failed", after.last_error_message.?);
    try std.testing.expect(std.mem.indexOf(u8, after.manifest_json, "\"last_error\"") != null);
    {
        const retained_unit = try db.core.store.get(alloc, stale_unit_key);
        defer alloc.free(retained_unit);
    }

    var list = try db.listDocumentArtifactManifests(alloc, "doc:a");
    defer list.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), list.artifacts.len);
    try std.testing.expectEqualStrings("InvalidDataUri", list.artifacts[0].last_error_code.?);

    // A failure manifest must remain eligible for repair even when the restored
    // source matches the retained state fingerprint.
    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value = "{\"url\":\"data:text/plain;base64,YWxwaGE=\"}",
        }},
        .sync_level = .full_index,
    });

    var repaired = (try db.getDocumentArtifactManifest(alloc, "doc:a", "document_units_v1")) orelse return error.TestUnexpectedResult;
    defer repaired.deinit(alloc);
    try std.testing.expectEqual(@as(u64, after.generation + 1), repaired.generation);
    try std.testing.expectEqualStrings("text", repaired.route_type);
    try std.testing.expectEqualStrings("converged", repaired.merge_status);
    try std.testing.expectEqual(@as(usize, 1), repaired.unit_count);
    try std.testing.expect(repaired.last_error_code == null);
}

test "db document extraction skips stable unit local rewrites while replaying full text from stored artifacts" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var counting = CountingDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = counting.interface(),
        },
    });
    defer db.close();

    try db.addEnrichment(.{
        .name = "document_units_v1",
        .kind = .asset,
        .field = "url",
        .content_type = "application/json",
        .producer_json = "{\"type\":\"document_extraction\",\"config\":{}}",
    });
    try db.addEnrichment(.{
        .name = "document_chunks_v1",
        .kind = .chunk,
        .field = "text",
        .source_artifact_name = "document_units_v1",
        .chunk_size = 256,
    });
    try db.addEnrichment(.{
        .name = "document_chunk_dense_v1",
        .kind = .embedding,
        .field = "text",
        .source_artifact_name = "document_chunks_v1",
        .expected_dims = 3,
    });
    try db.addIndex(.{
        .name = "ft_document_units",
        .kind = .full_text,
        .config_json = "{\"field\":\"text\",\"sources\":[{\"artifact\":\"document_units_v1\"}]}",
    });
    try db.addIndex(.{
        .name = "ft_document_chunks",
        .kind = .full_text,
        .config_json = "{\"chunk_name\":\"document_chunks_v1\"}",
    });
    try db.addIndex(.{
        .name = "dv_document_chunks",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"embedding_name\":\"document_chunk_dense_v1\"}",
    });
    const chunk_vector_indexes = try db.core.index_manager.vectorIndexesForChunk(alloc, "document_chunks_v1");
    defer {
        for (chunk_vector_indexes) |index_name| alloc.free(index_name);
        alloc.free(chunk_vector_indexes);
    }
    try std.testing.expectEqual(@as(usize, 1), chunk_vector_indexes.len);
    try std.testing.expectEqualStrings("dv_document_chunks", chunk_vector_indexes[0]);
    const asset_vector_indexes = try db.core.index_manager.vectorIndexesDependingOnArtifact(alloc, "document_units_v1");
    defer {
        for (asset_vector_indexes) |index_name| alloc.free(index_name);
        alloc.free(asset_vector_indexes);
    }
    try std.testing.expectEqual(@as(usize, 1), asset_vector_indexes.len);
    try std.testing.expectEqualStrings("dv_document_chunks", asset_vector_indexes[0]);
    const asset_consumers = try db.core.index_manager.indexesDependingOnArtifact(alloc, "document_units_v1");
    defer {
        for (asset_consumers) |index_name| alloc.free(index_name);
        alloc.free(asset_consumers);
    }
    try std.testing.expectEqual(@as(usize, 3), asset_consumers.len);
    var found_units_text = false;
    var found_chunks_text = false;
    var found_chunks_dense = false;
    for (asset_consumers) |index_name| {
        found_units_text = found_units_text or std.mem.eql(u8, index_name, "ft_document_units");
        found_chunks_text = found_chunks_text or std.mem.eql(u8, index_name, "ft_document_chunks");
        found_chunks_dense = found_chunks_dense or std.mem.eql(u8, index_name, "dv_document_chunks");
    }
    try std.testing.expect(found_units_text and found_chunks_text and found_chunks_dense);

    const first_value = "{\"url\":\"data:text/plain;base64,YWxwaGEgYmV0YSBnYW1tYQ==\"}";
    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = first_value }},
        .sync_level = .full_index,
    });
    try db.runUntilIdle();
    const first_calls = counting.calls;
    try std.testing.expectEqual(@as(usize, 1), first_calls);

    const second_value = "{\"url\":\"data:text/plain,alpha%20beta%20gamma\"}";
    var extracted = [_]mapper.ExtractedWrite{try mapper.extractWrite(alloc, "doc:a", second_value)};
    defer extracted[0].deinit(alloc);
    var precomputed = try prepareGeneratedEnrichments(&db, alloc, .{
        .writes = &.{.{ .key = "doc:a", .value = second_value }},
    }, &extracted, .all, &.{}, null, null);
    defer precomputed.deinit(alloc);

    const unit_key = try internal_keys.documentUnitArtifactKeyAlloc(alloc, "doc:a", "document_units_v1", "document:000001");
    defer alloc.free(unit_key);
    const chunk_key = try internal_keys.documentUnitChunkArtifactKeyAlloc(alloc, "doc:a", "document_chunks_v1", "document:000001", 0);
    defer alloc.free(chunk_key);

    try std.testing.expectEqual(first_calls, counting.calls);
    try std.testing.expectEqual(@as(usize, 2), precomputed.documents.len);
    var saw_unit_doc = false;
    var saw_chunk_doc = false;
    for (precomputed.documents) |doc| {
        try std.testing.expectEqual(@as(?[]const u8, null), doc.cleaned_value);
        if (std.mem.eql(u8, doc.key, unit_key)) saw_unit_doc = true;
        if (std.mem.eql(u8, doc.key, chunk_key)) saw_chunk_doc = true;
    }
    try std.testing.expect(saw_unit_doc);
    try std.testing.expect(saw_chunk_doc);

    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = second_value }},
        .sync_level = .full_index,
    });
    try std.testing.expectEqual(first_calls, counting.calls);

    // A full-index merge precomputes this successful empty extraction before
    // generated replay. The replay's stable-state shortcut must still account
    // for the source document so artifact-backed vector coverage can converge.
    try db.batch(.{
        .writes = &.{.{ .key = "doc:empty", .value = "{\"url\":\"data:text/plain,\"}" }},
        .sync_level = .full_index,
    });
    try db.runUntilIdle();
    const coverage_stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, coverage_stats);
    var saw_vector_coverage = false;
    for (coverage_stats.indexes) |index_stats| {
        if (!std.mem.eql(u8, index_stats.name, "dv_document_chunks")) continue;
        saw_vector_coverage = true;
        try std.testing.expect(index_stats.coverage_summary_ready);
        try std.testing.expectEqual(@as(u64, 1), index_stats.coverage_produced_count);
        try std.testing.expectEqual(@as(u64, 1), index_stats.coverage_skipped_count);
        try std.testing.expectEqual(@as(u64, 0), index_stats.coverage_terminal_failed_count);
    }
    try std.testing.expect(saw_vector_coverage);

    var unit_result = try db.search(alloc, .{
        .index_name = "ft_document_units",
        .full_text = .{ .match = .{ .field = "text", .text = "gamma" } },
        .return_mode = .unit,
    });
    defer unit_result.deinit();
    try std.testing.expectEqual(@as(u32, 1), unit_result.total_hits);
    try std.testing.expectEqualStrings("doc:a", unit_result.hits[0].artifact_ref.?.document_id);
    try std.testing.expectEqualStrings("document_units_v1", unit_result.hits[0].artifact_ref.?.name);
    try std.testing.expectEqualStrings("document:000001", unit_result.hits[0].artifact_ref.?.unit_id.?);

    var all_unit_members = try db.search(alloc, .{
        .index_name = "ft_document_units",
        .full_text = .{ .match_all = {} },
        .return_mode = .chunk,
    });
    defer all_unit_members.deinit();
    try std.testing.expectEqual(@as(u32, 2), all_unit_members.total_hits);
    for (all_unit_members.hits) |hit| {
        try std.testing.expectEqual(types.ArtifactKind.asset, hit.artifact_ref.?.kind);
        try std.testing.expect(hit.artifact_ref.?.unit_id != null);
    }

    // The artifact contains operational strings such as unit_type in addition
    // to text. A selective artifact index must not leak those fields into its
    // postings, including through the schema-less _all projection.
    var excluded_metadata = try db.search(alloc, .{
        .index_name = "ft_document_units",
        .full_text = .{ .match = .{ .field = "unit_type", .text = "document" } },
        .return_mode = .chunk,
    });
    defer excluded_metadata.deinit();
    try std.testing.expectEqual(@as(u32, 0), excluded_metadata.total_hits);

    var chunk_result = try db.search(alloc, .{
        .index_name = "ft_document_chunks",
        .full_text = .{ .match = .{ .field = "text", .text = "gamma" } },
        .return_mode = .chunk,
    });
    defer chunk_result.deinit();
    try std.testing.expectEqual(@as(u32, 1), chunk_result.total_hits);

    var chunk_unit_result = try db.search(alloc, .{
        .index_name = "ft_document_chunks",
        .full_text = .{ .match = .{ .field = "text", .text = "gamma" } },
        .return_mode = .unit,
    });
    defer chunk_unit_result.deinit();
    try std.testing.expectEqual(@as(u32, 1), chunk_unit_result.total_hits);
    try std.testing.expectEqualStrings("doc:a", chunk_unit_result.hits[0].artifact_ref.?.document_id);
    try std.testing.expectEqualStrings("document_units_v1", chunk_unit_result.hits[0].artifact_ref.?.name);
    try std.testing.expectEqualStrings("document:000001", chunk_unit_result.hits[0].artifact_ref.?.unit_id.?);
}

test "db query drops full text hits whose stored document row was deleted directly from the store" {
    // Issue #929: deleting a chunk enrichment and reprocessing (or a crash
    // mid-purge) can leave a full-text posting pointing at a stored-document
    // key whose row is gone -- the write-side fix in this checkout stops
    // *new* orphans from the enrichment-delete-then-reprocess path, but the
    // query side must still tolerate any orphaned posting that already
    // exists (e.g. from a crash, or a store mutated out of band) by
    // dropping the affected hit instead of failing the whole query with
    // StoredDocMissing/500, exactly as the issue's own repro observed for
    // plain row-level queries and match_all. Simulate that end state
    // directly on a plain (non-chunk) table: delete a row's stored KV entry
    // out from under its own full-text posting, then assert queries that
    // would have hit it still succeed with reduced, correct results.
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.addIndex(.{
        .name = "ft_rows",
        .kind = .full_text,
        .config_json = "{}",
    });

    try db.addIndex(.{ .name = "dv_rows", .kind = .dense_vector, .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\"}" });
    try db.addIndex(.{ .name = "sp_rows", .kind = .sparse_vector, .config_json = "{\"field\":\"sparse\"}" });

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"alpha beta gamma\",\"embedding\":[0,0],\"sparse\":{\"indices\":[1],\"values\":[5]}}" },
            .{ .key = "doc:b", .value = "{\"body\":\"alpha delta epsilon\",\"embedding\":[1,0],\"sparse\":{\"indices\":[1],\"values\":[4]}}" },
        },
        .sync_level = .full_index,
    });
    try db.runUntilIdle();

    // Sanity check: both rows are searchable before one goes missing.
    var before_term = try db.search(alloc, .{
        .index_name = "ft_rows",
        .full_text = .{ .match = .{ .field = "body", .text = "alpha" } },
        .include_stored = true,
        .limit = 10,
    });
    defer before_term.deinit();
    try std.testing.expectEqual(@as(u32, 2), before_term.total_hits);
    try std.testing.expectEqual(@as(usize, 2), before_term.hits.len);

    const orphaned_doc_key = try internal_keys.documentKeyAlloc(alloc, "doc:a");
    defer alloc.free(orphaned_doc_key);
    // Confirm the row exists before deleting it, so a failure to delete
    // doesn't silently make this test pass for the wrong reason.
    {
        var probe = try db.core.store.beginProbeTxn();
        defer probe.abort();
        _ = try probe.get(orphaned_doc_key);
    }
    // Delete the KV row directly, bypassing db.batch's normal delete path
    // entirely -- the posting for "doc:a" in ft_rows now has no backing
    // stored row, the same end state left by #929's enrichment-delete +
    // reprocess sequence (or a crash mid-purge).
    try db.core.store.delete(orphaned_doc_key);

    // A child range can own a member while source/unit hydration is remote.
    const remote_member_key = try internal_keys.documentUnitChunkArtifactKeyAlloc(alloc, "doc:remote", "remote_chunks", "document:000001", 0);
    defer alloc.free(remote_member_key);
    try db.core.store.put(remote_member_key, "{}");
    defer db.core.store.delete(remote_member_key) catch {};

    // An embedding member can exist locally even when its source chunk,
    // unit and document belong to another range. Canonical artifact identity,
    // rather than its source/public id, must drive the probe under OOM too.
    const remote_source_key = try internal_keys.documentUnitChunkArtifactKeyAlloc(alloc, "doc:off-shard", "remote_chunks", "document:000001", 0);
    defer alloc.free(remote_source_key);
    const remote_embedding_key = try internal_keys.derivedEmbeddingArtifactKeyAlloc(alloc, remote_source_key, "remote_dense");
    defer alloc.free(remote_embedding_key);
    try db.core.store.put(remote_embedding_key, "{}");
    defer db.core.store.delete(remote_embedding_key) catch {};
    var remote_embedding_ref = (try artifact_ids.decodeArtifactRefAlloc(alloc, remote_embedding_key)).?;
    defer remote_embedding_ref.deinit(alloc);

    const PresenceAllocationCheck = struct {
        fn run(test_alloc: Allocator, active_db: *DB, remote_key: []u8, source_key: []u8, embedding_ref: types.ArtifactRef) !void {
            const keep = try filterPresentSearchHitsMany(active_db, test_alloc, &.{
                .{ .id = @constCast("doc:a") },
                .{ .id = @constCast("doc:b") },
                .{ .id = remote_key },
                .{ .id = @constCast("doc:off-shard"), .artifact_ref = embedding_ref },
                .{ .id = @constCast("doc:b"), .artifact_ref = .{ .document_id = @constCast("doc:b"), .name = @constCast("absent_embedding"), .kind = .embedding } },
            }, null);
            defer test_alloc.free(keep);
            try std.testing.expectEqualSlices(bool, &.{ false, true, true, true, false }, keep);
            // A single managed vector source uses chunk metadata even when
            // store_chunks is false. Its embedding is the persisted member.
            const single = try filterPresentSearchHitsMany(active_db, test_alloc, &.{
                .{ .id = remote_key },
                .{ .id = source_key },
            }, "remote_dense");
            defer test_alloc.free(single);
            try std.testing.expectEqualSlices(bool, &.{ false, true }, single);
        }
    };
    try std.testing.checkAllAllocationFailures(alloc, PresenceAllocationCheck.run, .{ &db, remote_member_key, remote_source_key, remote_embedding_ref });

    // Presence is a candidate visibility rule, including IDs-only and count
    // requests. Apply it before offset/limit, and refill an orphaned top hit.
    for ([_]bool{ false, true }) |include_stored| {
        for ([_]types.TextQuery{ .{ .match_all = {} }, .{ .match = .{ .field = "body", .text = "alpha" } } }) |query| {
            var page = try db.search(alloc, .{ .index_name = "ft_rows", .full_text = query, .include_stored = include_stored, .limit = 1 });
            defer page.deinit();
            try std.testing.expectEqual(@as(usize, 1), page.hits.len);
            try std.testing.expectEqualStrings("doc:b", page.hits[0].id);
            try std.testing.expectEqual(@as(u32, 1), page.total_hits);
            var after = try db.search(alloc, .{ .index_name = "ft_rows", .full_text = query, .include_stored = include_stored, .offset = 1, .limit = 1 });
            defer after.deinit();
            try std.testing.expectEqual(@as(usize, 0), after.hits.len);
            try std.testing.expectEqual(@as(u32, 1), after.total_hits);
            var count = try db.search(alloc, .{ .index_name = "ft_rows", .full_text = query, .count_only = true });
            defer count.deinit();
            try std.testing.expectEqual(@as(u32, 1), count.total_hits);
        }
    }

    for ([_]bool{ false, true }) |include_stored| {
        for ([_]bool{ false, true }) |is_sparse| {
            var req: types.SearchRequest = .{ .index_name = if (is_sparse) "sp_rows" else "dv_rows", .include_stored = include_stored, .limit = 1 };
            if (is_sparse) req.query = .{ .sparse_knn = .{ .indices = &.{1}, .values = &.{1}, .k = 1 } } else req.dense = .{ .vector = &.{ 0, 0 }, .k = 1 };
            var page = try db.search(alloc, req);
            defer page.deinit();
            try std.testing.expectEqual(@as(usize, 1), page.hits.len);
            try std.testing.expectEqualStrings("doc:b", page.hits[0].id);
            req.offset = 1;
            var after = try db.search(alloc, req);
            defer after.deinit();
            try std.testing.expectEqual(@as(usize, 0), after.hits.len);
        }
    }

    for ([_]bool{ false, true }) |include_stored| {
        var sorted = try db.search(alloc, .{
            .index_name = "ft_rows",
            .full_text = .{ .match_all = {} },
            .order_by = &.{.{ .field = "_id" }},
            .include_stored = include_stored,
            .limit = 1,
        });
        defer sorted.deinit();
        try std.testing.expectEqual(@as(usize, 1), sorted.hits.len);
        try std.testing.expectEqualStrings("doc:b", sorted.hits[0].id);
        try std.testing.expectEqual(@as(u32, 1), sorted.total_hits);
    }

    // A term unique to the now-orphaned row must come back empty, not fail
    // the query (matches the issue's `query {"query": "harbor"} -> 500`).
    var unique_term = try db.search(alloc, .{
        .index_name = "ft_rows",
        .full_text = .{ .match = .{ .field = "body", .text = "beta" } },
        .include_stored = true,
        .limit = 10,
    });
    defer unique_term.deinit();
    try std.testing.expectEqual(@as(u32, 0), unique_term.total_hits);
    try std.testing.expectEqual(@as(usize, 0), unique_term.hits.len);

    // A term shared by both rows must drop only the orphaned hit and adjust
    // total_hits, not fail the whole query.
    var shared_term = try db.search(alloc, .{
        .index_name = "ft_rows",
        .full_text = .{ .match = .{ .field = "body", .text = "alpha" } },
        .include_stored = true,
        .limit = 10,
    });
    defer shared_term.deinit();
    try std.testing.expectEqual(@as(u32, 1), shared_term.total_hits);
    try std.testing.expectEqual(@as(usize, 1), shared_term.hits.len);
    try std.testing.expectEqualStrings("doc:b", shared_term.hits[0].id);

    // match_all must also drop the orphaned hit rather than 500 (the
    // issue's own repro: `match_all` failed too, not just term queries).
    var all_result = try db.search(alloc, .{
        .index_name = "ft_rows",
        .full_text = .{ .match_all = {} },
        .include_stored = true,
        .limit = 10,
    });
    defer all_result.deinit();
    try std.testing.expectEqual(@as(u32, 1), all_result.total_hits);
    try std.testing.expectEqual(@as(usize, 1), all_result.hits.len);
    try std.testing.expectEqualStrings("doc:b", all_result.hits[0].id);
}

test "db text totals require presence proof beyond the requested page" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);
    var db = try DB.open(alloc, std.mem.span(path), .{ .start_index_workers = false });
    defer db.close();
    try db.addIndex(.{ .name = "ft_rows", .kind = .full_text, .config_json = "{}" });
    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"alpha\"}" },
            .{ .key = "doc:b", .value = "{\"body\":\"alpha\"}" },
        },
        .sync_level = .full_index,
    });

    // The same prefix is returned before and after the unseen row goes
    // missing. Neither query can prove an exact total from that prefix.
    for ([_]bool{ false, true }) |orphaned| {
        if (orphaned) {
            const key = try internal_keys.documentKeyAlloc(alloc, "doc:b");
            defer alloc.free(key);
            try db.core.store.delete(key);
        }
        const expected_total: u32 = if (orphaned) 1 else 2;
        for ([_]bool{ false, true }) |include_stored| {
            for ([_]types.TextQuery{
                .{ .match_all = {} },
                .{ .match = .{ .field = "body", .text = "alpha" } },
            }) |query| {
                var req = types.SearchRequest{ .index_name = "ft_rows", .full_text = query, .include_stored = include_stored, .limit = 1 };
                var page = try db.search(alloc, req);
                defer page.deinit();
                try std.testing.expectEqual(@as(usize, 1), page.hits.len);
                try std.testing.expectEqualStrings("doc:a", page.hits[0].id);
                try std.testing.expectEqual(@as(u32, 1), page.total_hits);
                try std.testing.expectEqual(types.TotalHitsRelation.gte, page.total_hits_relation);

                req.count_only = true;
                var count = try db.search(alloc, req);
                defer count.deinit();
                try std.testing.expectEqual(expected_total, count.total_hits);
                try std.testing.expectEqual(types.TotalHitsRelation.exact, count.total_hits_relation);

                req.count_only = false;
                req.limit = 2;
                var complete = try db.search(alloc, req);
                defer complete.deinit();
                try std.testing.expectEqual(expected_total, complete.total_hits);
                try std.testing.expectEqual(types.TotalHitsRelation.exact, complete.total_hits_relation);
                try std.testing.expectEqual(@as(usize, expected_total), complete.hits.len);

                req.limit = 1;
                req.offset = 1;
                var tail = try db.search(alloc, req);
                defer tail.deinit();
                try std.testing.expectEqual(expected_total, tail.total_hits);
                try std.testing.expectEqual(types.TotalHitsRelation.exact, tail.total_hits_relation);
                try std.testing.expectEqual(@as(usize, if (orphaned) 0 else 1), tail.hits.len);

                // Native field-sort collectors check every counted row, so
                // their limited pages still have an exact presence proof.
                req.offset = 0;
                req.order_by = &.{.{ .field = "_id" }};
                var sorted = try db.search(alloc, req);
                defer sorted.deinit();
                try std.testing.expectEqual(expected_total, sorted.total_hits);
                try std.testing.expectEqual(types.TotalHitsRelation.exact, sorted.total_hits_relation);
                try std.testing.expectEqual(@as(usize, 1), sorted.hits.len);
            }
        }
    }
}

test "db materialized dense enrichment survives artifact write list growth" {
    try testMaterializedEmbeddingWriteGrowth(.dense);
}

test "db materialized derived dense enrichment survives artifact write list growth" {
    try testMaterializedEmbeddingWriteGrowth(.derived_dense);
}

test "db materialized sparse enrichment survives artifact write list growth" {
    try testMaterializedEmbeddingWriteGrowth(.sparse);
}

fn testMaterializedEmbeddingWriteGrowth(comptime mode: enum { dense, derived_dense, sparse }) !void {
    const alloc = std.testing.allocator;
    const is_sparse = mode == .sparse;
    const embedding_name = if (is_sparse) "document_sparse" else "document_dense";

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var deterministic_dense = embedder_mod.DeterministicDenseEmbedder{};
    var deterministic_sparse = embedder_mod.DeterministicSparseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .ttl_cleanup = .{ .enabled = false },
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = deterministic_dense.interface(),
            .sparse_embedder = deterministic_sparse.interface(),
        },
    });
    defer db.close();

    try db.addEnrichment(.{
        .name = "document_units_v1",
        .kind = .asset,
        .field = "url",
        .content_type = "application/json",
        .producer_json = "{\"type\":\"document_extraction\",\"config\":{}}",
    });
    try db.addEnrichment(.{
        .name = "document_chunks_v1",
        .kind = .chunk,
        .field = "text",
        .source_artifact_name = "document_units_v1",
        .chunk_size = 256,
    });
    try db.addEnrichment(.{
        .name = embedding_name,
        .kind = .embedding,
        .field = "text",
        .source_artifact_name = "document_chunks_v1",
        .expected_dims = if (is_sparse) 0 else 3,
    });
    try db.addIndex(.{
        .name = embedding_name,
        .kind = if (is_sparse) .sparse_vector else .dense_vector,
        .config_json = if (is_sparse)
            "{\"field\":\"sparse_embedding\"}"
        else
            "{\"field\":\"embedding\",\"dims\":3,\"embedding_name\":\"document_dense\"}",
    });

    // Leave a chunk after the first flush and no spare capacity for its output.
    // Follow the configured item limit so batch tuning cannot bypass the regression.
    const chunk_count = generatedEmbedBatchItems() + 1;
    var artifact_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
    defer {
        for (artifact_writes.items) |write| {
            alloc.free(@constCast(write.key));
            alloc.free(@constCast(write.value));
        }
        artifact_writes.deinit(alloc);
    }
    try artifact_writes.ensureTotalCapacityPrecise(alloc, chunk_count);
    for (0..chunk_count) |chunk_id| {
        const key = try internal_keys.documentUnitChunkArtifactKeyAlloc(
            alloc,
            "doc:a",
            "document_chunks_v1",
            "document:000001",
            @intCast(chunk_id),
        );
        errdefer alloc.free(key);
        const value = try std.fmt.allocPrint(alloc, "{{\"text\":\"chunk {d}\"}}", .{chunk_id});
        errdefer alloc.free(value);
        artifact_writes.appendAssumeCapacity(.{ .key = key, .value = value });
    }
    const original_write_pointer = artifact_writes.items.ptr;

    const Embedding = switch (mode) {
        .dense => types.EnrichmentDenseEmbeddingWrite,
        .derived_dense => derived_types.DerivedDenseEmbeddingWrite,
        .sparse => derived_types.DerivedSparseEmbeddingWrite,
    };
    var embeddings = std.ArrayListUnmanaged(Embedding).empty;
    defer {
        for (embeddings.items) |*embedding| {
            switch (mode) {
                .dense => embedding.deinit(alloc),
                .derived_dense => derived_types.deinitDerivedDenseEmbedding(alloc, embedding.*),
                .sparse => derived_types.deinitDerivedSparseEmbedding(alloc, embedding.*),
            }
        }
        embeddings.deinit(alloc);
    }
    var chunk_cache = std.ArrayListUnmanaged(ChunkCacheEntry).empty;
    defer {
        for (chunk_cache.items) |entry| {
            alloc.free(entry.key);
            chunker_mod.freeChunks(alloc, entry.chunks);
        }
        chunk_cache.deinit(alloc);
    }

    var consumer_name = embedding_name.*;
    var consumer_indexes = [_][]u8{consumer_name[0..]};
    const request = enrichment_types.GeneratedEnrichmentRequest{
        .kind = if (is_sparse) .sparse_embedding else .dense_embedding,
        .index_name = embedding_name,
        .artifact_name = "document_chunks_v1",
        .embedding_name = embedding_name,
        .input_kind = .materialized_chunks,
        .consumer_indexes = &consumer_indexes,
        .doc_key = "doc:a",
        .source_field = "text",
        .expected_dims = if (is_sparse) 0 else 3,
        .producer_json = "{}",
    };
    const compute = switch (mode) {
        .dense => computeDenseRequest,
        .derived_dense => computeDenseRequestDerived,
        .sparse => computeSparseRequestDerived,
    };
    if (mode == .dense) {
        try compute(alloc, &db, "{}", request, &artifact_writes, &embeddings, &chunk_cache);
    } else {
        const no_deletes = std.StringHashMapUnmanaged(void).empty;
        try compute(alloc, &db, "{}", request, &artifact_writes, &no_deletes, &embeddings, &chunk_cache, null, null);
    }

    // Guard the test's relocation precondition, not just the successful no-growth path.
    try std.testing.expect(original_write_pointer != artifact_writes.items.ptr);
    try std.testing.expectEqual(chunk_count * 2, artifact_writes.items.len);
    try std.testing.expectEqual(chunk_count, embeddings.items.len);
    var outputs = try PendingArtifactWriteIndex.init(alloc, artifact_writes.items);
    defer outputs.deinit(alloc);
    for (0..chunk_count) |chunk_id| {
        const chunk_key = try internal_keys.documentUnitChunkArtifactKeyAlloc(
            alloc,
            "doc:a",
            "document_chunks_v1",
            "document:000001",
            @intCast(chunk_id),
        );
        defer alloc.free(chunk_key);
        const embedding_key = try internal_keys.derivedEmbeddingArtifactKeyAlloc(alloc, chunk_key, embedding_name);
        defer alloc.free(embedding_key);
        const payload = outputs.get(embedding_key) orelse return error.TestUnexpectedResult;
        const text = try std.fmt.allocPrint(alloc, "chunk {d}", .{chunk_id});
        defer alloc.free(text);
        if (is_sparse) {
            var expected = try deterministic_sparse.interface().embedSparse(alloc, embedding_name, text);
            defer expected.deinit(alloc);
            var actual = try enrichment_artifact_codec.decodeSparseEmbeddingAlloc(alloc, payload);
            defer actual.deinit(alloc);
            try std.testing.expectEqualSlices(u32, expected.indices, actual.indices);
            try std.testing.expectEqualSlices(f32, expected.values, actual.values);
        } else {
            const expected = try deterministic_dense.interface().embedDense(alloc, embedding_name, text, 3);
            defer alloc.free(expected);
            const actual = try enrichment_artifact_codec.decodeDenseEmbeddingAlloc(alloc, payload);
            defer alloc.free(actual);
            try std.testing.expectEqualSlices(f32, expected, actual);
        }
    }
}

test "db document extraction chunks units through source artifact enrichment" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var deterministic_dense = embedder_mod.DeterministicDenseEmbedder{};
    var deterministic_sparse = embedder_mod.DeterministicSparseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = deterministic_dense.interface(),
            .sparse_embedder = deterministic_sparse.interface(),
        },
    });
    defer db.close();

    try db.addEnrichment(.{
        .name = "document_units_v1",
        .kind = .asset,
        .field = "url",
        .content_type = "application/json",
        .producer_json = "{\"type\":\"document_extraction\",\"config\":{}}",
    });
    try db.addEnrichment(.{
        .name = "document_chunks_v1",
        .kind = .chunk,
        .field = "text",
        .source_artifact_name = "document_units_v1",
        .chunk_size = 256,
    });
    try db.addEnrichment(.{
        .name = "document_chunk_dense_v1",
        .kind = .embedding,
        .field = "text",
        .source_artifact_name = "document_chunks_v1",
        .expected_dims = 3,
    });
    try db.addEnrichment(.{
        .name = "document_chunk_caption_dense_v1",
        .kind = .embedding,
        .field = "caption",
        .source_artifact_name = "document_chunks_v1",
        .expected_dims = 3,
    });
    try db.addEnrichment(.{
        .name = "document_chunk_sparse_v1",
        .kind = .embedding,
        .field = "text",
        .source_artifact_name = "document_chunks_v1",
    });
    try db.addIndex(.{
        .name = "ft_document_chunks",
        .kind = .full_text,
        .config_json = "{\"chunk_name\":\"document_chunks_v1\"}",
    });
    try db.addIndex(.{
        .name = "document_vectors",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"embedding_name\":\"document_chunk_dense_v1\"}",
    });
    try db.addIndex(.{
        .name = "document_caption_vectors",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"embedding_name\":\"document_chunk_caption_dense_v1\"}",
    });
    try db.addIndex(.{
        .name = "document_chunk_sparse_v1",
        .kind = .sparse_vector,
        .config_json = "{\"field\":\"sparse_embedding\"}",
    });
    const embedding_cfg = db.core.index_manager.getEnrichment(.embedding, "document_chunk_dense_v1") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("document_chunks_v1", embedding_cfg.source_artifact_name);
    try std.testing.expectEqual(@as(u32, 3), embedding_cfg.expected_dims);
    const dense_consumers = try db.core.index_manager.denseIndexesForEmbedding(alloc, "document_chunk_dense_v1", 3);
    defer {
        for (dense_consumers) |name| alloc.free(name);
        alloc.free(dense_consumers);
    }
    try std.testing.expectEqual(@as(usize, 1), dense_consumers.len);
    try std.testing.expectEqualStrings("document_vectors", dense_consumers[0]);
    const sparse_consumers = try db.core.index_manager.sparseIndexesForEmbedding(alloc, "document_chunk_sparse_v1");
    defer {
        for (sparse_consumers) |name| alloc.free(name);
        alloc.free(sparse_consumers);
    }
    try std.testing.expectEqual(@as(usize, 1), sparse_consumers.len);
    try std.testing.expectEqualStrings("document_chunk_sparse_v1", sparse_consumers[0]);

    const planned = try db.core.planGeneratedEnrichments(
        alloc,
        "doc:planned",
        "{\"url\":\"data:text/plain;base64,YWxwaGEgYmV0YSBnYW1tYQ==\",\"text\":\"source document decoy\"}",
        &.{},
        &.{},
    );
    defer enrichment_types.deinitGeneratedRequests(alloc, planned);
    var saw_document_asset = false;
    var saw_document_chunk_dense = false;
    var saw_document_chunk_caption_dense = false;
    var saw_document_chunk_sparse = false;
    for (planned) |request| {
        if (request.kind == .asset and std.mem.eql(u8, request.artifact_name, "document_units_v1")) saw_document_asset = true;
        if (request.kind == .dense_embedding and
            std.mem.eql(u8, request.artifact_name, "document_chunks_v1") and
            std.mem.eql(u8, request.embedding_name, "document_chunk_dense_v1") and
            request.chunk_size == 256)
        {
            saw_document_chunk_dense = true;
        }
        if (request.kind == .dense_embedding and
            std.mem.eql(u8, request.artifact_name, "document_chunks_v1") and
            std.mem.eql(u8, request.embedding_name, "document_chunk_caption_dense_v1") and
            request.chunk_size == 256)
        {
            saw_document_chunk_caption_dense = true;
        }
        if (request.kind == .sparse_embedding and
            std.mem.eql(u8, request.artifact_name, "document_chunks_v1") and
            std.mem.eql(u8, request.embedding_name, "document_chunk_sparse_v1") and
            request.chunk_size == 256)
