test "db managed dense enrichment remains searchable after transient rate limits" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    // Admit the first request, then force the worker through the real
    // retryable-provider path until this test explicitly releases the gate.
    // Keeping this at the gate's default is part of the test contract: an
    // always-open provider would bypass transient recovery entirely.
    var gated = GateDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = gated.interface(),
        },
    });
    defer db.close();

    try db.addIndex(.{
        .name = "semantic_idx",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"cosine\",\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"embedding_name\":\"semantic_idx\"}}",
    });

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"title\":\"alpha\",\"body\":\"alpha concept overview\"}" },
            .{ .key = "doc:b", .value = "{\"title\":\"beta\",\"body\":\"beta architecture notes\"}" },
            .{ .key = "doc:c", .value = "{\"title\":\"gamma\",\"body\":\"gamma implementation details\"}" },
        },
        .sync_level = .write,
    });

    var attempts: usize = 0;
    while (attempts < 200) : (attempts += 1) {
        const snapshot = gated.snapshot();
        if (snapshot.blocked_requests > 0 and snapshot.successful_requests >= 1) break;
        sleepNs(10 * std.time.ns_per_ms);
    }

    const before_release = gated.snapshot();
    try std.testing.expect(before_release.blocked_requests > 0);
    try std.testing.expect(before_release.successful_requests >= 1);

    gated.allowAll();

    var ready = false;
    var attempts_after_release: usize = 0;
    while (attempts_after_release < 500) : (attempts_after_release += 1) {
        const stats = try db.stats(alloc);
        defer types.freeDBStats(alloc, stats);
        for (stats.indexes) |item| {
            if (!std.mem.eql(u8, item.name, "semantic_idx")) continue;
            if (item.doc_count == 3 and
                item.replay_applied_sequence >= 2 and
                item.replay_applied_sequence == item.replay_target_sequence and
                !item.backfill_active)
            {
                ready = true;
            }
            break;
        }
        if (ready) break;
        sleepNs(10 * std.time.ns_per_ms);
    }
    try std.testing.expect(ready);

    var result = try db.search(alloc, .{
        .index_name = "semantic_idx",
        .dense = .{
            .vector = &.{ 1.0, 0.0, 0.0 },
            .k = 3,
        },
        .limit = 3,
    });
    defer result.deinit();
    try std.testing.expectEqual(@as(u32, 3), result.total_hits);
    try std.testing.expectEqualStrings("doc:a", result.hits[0].id);

    try db.runUntilIdle();
}

fn independentDensePublicationVisibleForTest(db: *DB, alloc: Allocator) !bool {
    // Materialization counters and a replay cursor can advance before the
    // asynchronous query publication is visible. The isolation witness is a
    // successful query while the unrelated producer remains gated; waiting
    // for global idle would instead require that producer to recover.
    var result = db.search(alloc, .{
        .index_name = "title_dense",
        .dense = .{
            .vector = &.{ 1.0, 0.0, 0.0 },
            .k = 1,
        },
    }) catch |err| switch (err) {
        error.IndexRebuilding => return false,
        else => return err,
    };
    defer result.deinit();
    if (result.total_hits == 0) return false;
    try std.testing.expectEqual(@as(u32, 1), result.total_hits);
    try std.testing.expectEqual(@as(usize, 1), result.hits.len);
    try std.testing.expectEqualStrings("doc:a", result.hits[0].id);
    return true;
}

test "db retryable chunked producer does not block independent dense publication" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var gated = SelectiveGateDenseEmbedder{
        .blocked_embedding_name = "body_chunk_dense",
    };
    var db = try DB.open(alloc, std.mem.span(path), .{
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = gated.interface(),
            .inline_retry_max_attempts = 1,
        },
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();

    // Register the throttled chunked producer first. Request ordering must not
    // be the mechanism that lets the direct title producer make progress.
    try db.addIndex(.{
        .name = "body_chunks",
        .kind = .dense_vector,
        .config_json =
        \\{"field":"embedding","dims":3,"publication_policy":"progressive","generator":{"kind":"dense_embedding","source_field":"body","chunk_name":"body_chunks_v1","chunk_size":8,"chunk_overlap":2,"embedding_name":"body_chunk_dense"}}
        ,
    });
    try db.addIndex(.{
        .name = "title_dense",
        .kind = .dense_vector,
        .config_json =
        \\{"field":"embedding","dims":3,"publication_policy":"progressive","generator":{"kind":"dense_embedding","source_field":"title","embedding_name":"title_dense"}}
        ,
    });
    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value = "{\"title\":\"independent title\",\"body\":\"abcdefghijklmno\"}",
        }},
        .sync_level = .write,
    });

    var sibling_published = false;
    var attempts: usize = 0;
    while (attempts < default_test_wait_attempts) : (attempts += 1) {
        const stats = try db.stats(alloc);
        defer types.freeDBStats(alloc, stats);
        if (gated.blocked_requests.load(.acquire) != 0) {
            for (stats.indexes) |index_stats| {
                if (!std.mem.eql(u8, index_stats.name, "title_dense")) continue;
                sibling_published = index_stats.doc_count == 1 and
                    index_stats.coverage_produced_count == 1 and
                    index_stats.replay_applied_sequence != 0;
                break;
            }
        }
        if (sibling_published)
            sibling_published = try independentDensePublicationVisibleForTest(&db, alloc);
        if (sibling_published) break;
        sleepPollInterval();
    }
    try std.testing.expect(gated.blocked_requests.load(.acquire) != 0);
    try std.testing.expect(gated.successful_requests.load(.acquire) != 0);
    try std.testing.expect(sibling_published);

    var result = try db.search(alloc, .{
        .index_name = "title_dense",
        .dense = .{
            .vector = &.{ 1.0, 0.0, 0.0 },
            .k = 1,
        },
    });
    defer result.deinit();
    try std.testing.expectEqual(@as(u32, 1), result.total_hits);
    try std.testing.expectEqualStrings("doc:a", result.hits[0].id);

    gated.allowAll();
    try db.runUntilIdle();
}

