test "db chunked dense enrichment skips unchanged chunks and deletes stale chunk artifacts" {
    try testDenseChunkArtifactLifecycle(.{}, false);
}

test "source vector table deletes stale chunk embeddings" {
    try testDenseChunkArtifactLifecycle(.{ .dense_embeddings = .vector_store }, false);
}

test "source vector migration captures enrichment updates and stale chunk deletion" {
    try testDenseChunkArtifactLifecycle(.{ .dense_embeddings = .primary_lsm }, true);
}

fn testDenseChunkArtifactLifecycle(settings: table_storage_mod.Settings, migrate: bool) !void {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var counting = CountingDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .table_storage = settings,
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = counting.interface(),
        },
    });
    defer db.close();

    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"chunk_name\":\"body_chunks_v1\",\"chunk_size\":8,\"chunk_overlap\":2,\"embedding_name\":\"chunk_dense_v1\"}}",
    });

    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"alpha\",\"body\":\"abcdefghijklmno\"}" }},
        .sync_level = .write,
    });
    try db.runUntilIdle();
    const first_calls = counting.calls;
    try std.testing.expect(first_calls > 0);
    if (migrate) {
        try db.startVectorMigration(.{ .job_id = "chunks", .mode = .online });
        try db.advanceVectorMigration("chunks");
    }

    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"changed\",\"body\":\"abcdefghijklmno\"}" }},
        .sync_level = .write,
    });
    try db.runUntilIdle();
    try std.testing.expectEqual(first_calls, counting.calls);

    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"changed\",\"body\":\"abcdefgh\"}" }},
        .sync_level = .write,
    });
    try db.runUntilIdle();
    try std.testing.expectEqual(first_calls, counting.calls);

    {
        const chunk_prefix = try internal_keys.artifactNamedPrefixAlloc(alloc, "doc:a", "chunk", "body_chunks_v1");
        defer alloc.free(chunk_prefix);
        const artifacts = try db.core.store.scanPrefix(alloc, chunk_prefix);
        defer docstore_mod.DocStore.freeResults(alloc, artifacts);

        var chunk_count: usize = 0;
        var embedding_count: usize = 0;
        for (artifacts) |entry| {
            if (internal_keys.isChunkArtifactRecordKey(entry.key)) chunk_count += 1;
            if (internal_keys.isDerivedEmbeddingArtifactKey(entry.key)) embedding_count += 1;
        }
        try std.testing.expectEqual(@as(usize, 1), chunk_count);
        try std.testing.expectEqual(@as(usize, 1), embedding_count);
        try std.testing.expectEqual(@as(u64, 1), db.core.index_manager.denseIndex("dv_v1").?.index.metadata.active_count);
    }

    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"changed\",\"body\":\"xyzuvw\"}" }},
        .sync_level = .write,
    });
    try db.runUntilIdle();
    try std.testing.expect(counting.calls > first_calls);
    if (migrate) {
        for (0..256) |_| {
            var state = (try vector_migration.load(alloc, db.core.store)).?;
            defer state.deinit();
            if (state.value.phase == .complete) break;
            if (state.value.phase == .ready) try db.publishVectorMigration("chunks") else try db.advanceVectorMigration("chunks");
        } else return error.VectorMigrationDidNotFinish;
    }

    const chunk_prefix = try internal_keys.artifactNamedPrefixAlloc(alloc, "doc:a", "chunk", "body_chunks_v1");
    defer alloc.free(chunk_prefix);
    const artifacts = try db.core.store.scanPrefix(alloc, chunk_prefix);
    defer docstore_mod.DocStore.freeResults(alloc, artifacts);

    var chunk_count: usize = 0;
    var embedding_count: usize = 0;
    for (artifacts) |entry| {
        if (internal_keys.isChunkArtifactRecordKey(entry.key)) {
            chunk_count += 1;
            try std.testing.expect(std.mem.indexOf(u8, entry.value, "\"xyzuvw\"") != null);
        } else if (internal_keys.isDerivedEmbeddingArtifactKey(entry.key)) {
            embedding_count += 1;
            try expectDenseEmbeddingArtifactValue(alloc, entry.value, enrichment_artifact_codec.hashSource("xyzuvw"), 3);
        }
    }
    try std.testing.expectEqual(@as(usize, 1), chunk_count);
    try std.testing.expectEqual(@as(usize, 1), embedding_count);
    try std.testing.expectEqual(@as(u64, 1), db.core.index_manager.denseIndex("dv_v1").?.index.metadata.active_count);
}

fn resetDenseIndexForArtifactRebuildForTest(db: *DB, index_name: []const u8) !void {
    // The native publisher holds catalog pins without the apply lock. Retire
    // those borrowers before taking apply exclusive and closing the old HBC.
    var structural = db.beginIndexStructuralMutation("test artifact dense reset", index_name);
    defer structural.deinit();
    lockApply(db);
    defer db.core.unlockApply();
    try db.core.index_manager.resetDenseIndexForArtifactRebuild(index_name);
}

test "db artifact dense reset waits for catalog readers before closing storage" {
    if (builtin.single_threaded) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);
    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();
    try db.addIndex(.{
        .name = "dense_idx",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"external\":true}",
    });

    // Native publication holds this same catalog pin while reading the live
    // posting generation, independently of the DB apply lock.
    var reader = db.tryAcquireIndexCatalogReadLease() orelse return error.TestUnexpectedResult;
    var reader_held = true;
    defer if (reader_held) reader.release();
    const Reset = struct {
        db: *DB,
        done: std.atomic.Value(bool) = .init(false),
        fn run(self: *@This()) !void {
            defer self.done.store(true, .release);
            try resetDenseIndexForArtifactRebuildForTest(self.db, "dense_idx");
        }
    };
    var reset = Reset{ .db = &db };
    var future = try std.testing.io.concurrent(Reset.run, .{&reset});
    var joined = false;
    defer if (!joined) {
        if (reader_held) {
            reader.release();
            reader_held = false;
        }
        future.await(std.testing.io) catch {};
    };
    const deadline = monotonicTimeNs() + 5 * std.time.ns_per_s;
    while (!db.indexCatalogBarrierActive() and !reset.done.load(.acquire)) {
        if (monotonicTimeNs() >= deadline) return error.TestTimeout;
        try std.testing.io.sleep(.fromMilliseconds(1), .awake);
    }
    try std.testing.expect(db.indexCatalogBarrierActive());
    try std.testing.expect(!reset.done.load(.acquire));
    if (db.tryAcquireIndexCatalogReadLease()) |lease| {
        var unexpected = lease;
        unexpected.release();
        return error.TestUnexpectedResult;
    }
    // The old generation remains readable until its final catalog pin leaves.
    try std.testing.expect(db.core.index_manager.denseIndex("dense_idx").?.index.experimentalPostingDurableAppliedSequence() != null);
    reader.release();
    reader_held = false;
    const result = future.await(std.testing.io);
    joined = true;
    try result;
    try std.testing.expect(!db.indexCatalogBarrierActive());
    var reopened_reader = db.tryAcquireIndexCatalogReadLease() orelse return error.TestUnexpectedResult;
    reopened_reader.release();
}

