}

test "db cooperative dense posting drain crosses more than one maintenance page" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();

    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":2,\"metric\":\"l2_squared\",\"leaf_size\":2,\"branching_factor\":4,\"use_quantization\":false,\"lazy_posting_maintenance\":true,\"auto_posting_maintenance_max_postings\":0}",
    });

    const doc_count: usize = 256;
    const writes = try alloc.alloc(types.BatchWrite, doc_count);
    @memset(writes, .{ .key = &.{}, .value = &.{} });
    defer {
        for (writes) |write| {
            if (write.key.len != 0) alloc.free(@constCast(write.key));
            if (write.value.len != 0) alloc.free(@constCast(write.value));
        }
        alloc.free(writes);
    }
    for (writes, 0..) |*write, i| {
        write.key = try std.fmt.allocPrint(alloc, "doc:{d}", .{i});
        write.value = try std.fmt.allocPrint(alloc, "{{\"embedding\":[{d},{d}]}}", .{ i, i % 17 });
    }
    try db.batch(.{ .writes = writes, .sync_level = .full_index });

    const entry = db.core.denseIndex("dv_v1") orelse return error.IndexNotFound;
    const dirtied_leaf_count = try entry.index.markAllLeafPostingsDirtyForTest();
    try std.testing.expect(dirtied_leaf_count > dense_posting_idle_default_max_postings_per_index);

    const before = try entry.index.postingBacklogStats();
    try std.testing.expect(before.dirty_postings > dense_posting_idle_default_max_postings_per_index);

    const first_page_steps = try db.runDensePostingMaintenanceForIdle();
    try std.testing.expect(first_page_steps > 0);
    const after_first_page = try entry.index.postingBacklogStats();
    try std.testing.expect(after_first_page.hasMaintenanceDebt());

    const drained_steps = try db.drainDensePostingMaintenanceForIdle();
    try std.testing.expect(drained_steps > 0);

    const after = try entry.index.postingBacklogStats();
    try std.testing.expectEqual(@as(u64, 0), after.dirty_postings);
}

test "db leased enrichment worker materializes chunk artifacts" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var deterministic = embedder_mod.DeterministicDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = deterministic.interface(),
        },
    });
    defer db.close();

    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"chunk_name\":\"body_chunks_v1\",\"chunk_size\":8,\"chunk_overlap\":2}}",
    });

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"abcdefghijklmno\"}" },
        },
        .sync_level = .write,
    });

    try db.enrichment_runtime.?.waitForApplied(1);
    try waitForDerivedReplayTarget(&db);

    const chunk_prefix = try internal_keys.artifactNamedPrefixAlloc(alloc, "doc:a", "chunk", "body_chunks_v1");
    defer alloc.free(chunk_prefix);
    const chunk_zero = try expectedChunkArtifactKeyAlloc(alloc, "doc:a", "body_chunks_v1", 0);
    defer alloc.free(chunk_zero);
    const artifacts = try db.core.store.scanPrefix(alloc, chunk_prefix);
    defer docstore_mod.DocStore.freeResults(alloc, artifacts);

    var chunk_count: usize = 0;
    var embedding_count: usize = 0;
    for (artifacts) |entry| {
        if (internal_keys.isChunkArtifactRecordKey(entry.key)) {
            if (chunk_count == 0) {
                try std.testing.expectEqualStrings(chunk_zero, entry.key);
                try std.testing.expect(std.mem.indexOf(u8, entry.value, "\"abcdefgh\"") != null);
            }
            chunk_count += 1;
            continue;
        }
        if (internal_keys.isDerivedEmbeddingArtifactKey(entry.key)) {
            embedding_count += 1;
            try expectDenseEmbeddingArtifactWithSourceHash(alloc, entry.value, 3);
        }
    }
    try std.testing.expect(chunk_count > 0);
    try std.testing.expectEqual(@as(usize, 3), embedding_count);
}

test "db leased enrichment worker keeps chunk storage ephemeral when store_chunks is false" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var counting = CountingDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = counting.interface(),
        },
    });
    defer db.close();

    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"chunk_name\":\"body_chunks_v1\",\"chunker\":{\"provider\":\"antfly\",\"store_chunks\":false,\"text\":{\"target_tokens\":8,\"overlap_tokens\":2}}}}",
    });

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"abcdefghijklmno\"}" },
        },
        .sync_level = .write,
    });

    try db.enrichment_runtime.?.waitForApplied(1);
    try waitForDerivedReplayTarget(&db);

    const chunk_prefix = try internal_keys.artifactNamedPrefixAlloc(alloc, "doc:a", "chunk", "body_chunks_v1");
    defer alloc.free(chunk_prefix);
    {
        const artifacts = try db.core.store.scanPrefix(alloc, chunk_prefix);
        defer docstore_mod.DocStore.freeResults(alloc, artifacts);

        var chunk_count: usize = 0;
        var embedding_count: usize = 0;
        for (artifacts) |entry| {
            if (internal_keys.isChunkArtifactRecordKey(entry.key)) chunk_count += 1;
            if (internal_keys.isDerivedEmbeddingArtifactKey(entry.key)) embedding_count += 1;
        }

        try std.testing.expectEqual(@as(usize, 0), chunk_count);
        try std.testing.expectEqual(@as(usize, 3), embedding_count);
        try std.testing.expectEqual(@as(usize, 3), counting.calls);
    }

    // Replaying an unchanged source must retain the virtual chunks' derived
    // embeddings even though their intermediate chunk rows are intentionally
    // ephemeral. Deleting those embeddings before the source-hash check both
    // regresses serving counts and needlessly invokes the provider again.
    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"abcdefghijklmno\",\"revision\":2}" },
        },
        .sync_level = .write,
    });
    try db.enrichment_runtime.?.waitForApplied(2);
    try waitForDerivedReplayTarget(&db);

    const replayed_artifacts = try db.core.store.scanPrefix(alloc, chunk_prefix);
    defer docstore_mod.DocStore.freeResults(alloc, replayed_artifacts);
    var chunk_count: usize = 0;
    var embedding_count: usize = 0;
    for (replayed_artifacts) |entry| {
        if (internal_keys.isChunkArtifactRecordKey(entry.key)) chunk_count += 1;
        if (internal_keys.isDerivedEmbeddingArtifactKey(entry.key)) embedding_count += 1;
    }
    try std.testing.expectEqual(@as(usize, 0), chunk_count);
    try std.testing.expectEqual(@as(usize, 3), embedding_count);
    try std.testing.expectEqual(@as(usize, 3), counting.calls);

    const stats = try db.stats(alloc);
    defer types.freeDBStats(alloc, stats);
}

