            .owner_id = "worker-a",
            .dense_embedder = deterministic.interface(),
        },
        .start_index_workers = false,
    });
    defer db.close();

    const ttl_duration_ns: u64 = 60 * std.time.ns_per_s;
    try db.setSchema(.{
        .version = 1,
        .default_type = "_default",
        .ttl_duration_ns = ttl_duration_ns,
    });

    try db.addIndex(.{
        .name = "ft_chunks",
