        },
        .start_index_workers = false,
    });
    defer db.close();

    try db.addIndex(.{
        .name = "ft_chunks",
        .kind = .full_text,
        .config_json = "{\"chunk_name\":\"body_chunks_v1\"}",
    });
    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
