}

test "db async replay truncation retains durable enrichment debt" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();

    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"embedding_name\":\"body_dense_v1\"}}",
    });
    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"body\":\"alpha\"}" }},
        .sync_level = .write,
    });
    const first_sequence = db.core.nextDerivedSequence();
    try db.batch(.{
        .writes = &.{.{ .key = "doc:b", .value = "{\"body\":\"beta\"}" }},
        .sync_level = .write,
    });
    const target_sequence = db.core.nextDerivedSequence();
    try std.testing.expect(target_sequence > first_sequence);

    // Model a provider failure after the first durable enrichment checkpoint
    // while the managed-index executor has already reached the replay tail.
    try enrichment_state.saveAppliedSequence(
        db.core.store,
        enrichment_runtime_mod.scope_name,
        first_sequence,
    );
    // Repair-pin contention is covered with actual scheduled tasks in
    // "db replay truncation waits for repair pins through borrowed VoprIo".
    // This fixture verifies durable retention using the owner's native Io.
    try truncateReplaySequenceAsync(db.async_context, target_sequence);

    const retained = try replay_stream_mod.iterateFrom(alloc, db.core.store, 1);
    defer {
        for (retained) |*entry| entry.deinit(alloc);
        alloc.free(retained);
    }
    try std.testing.expectEqual(@as(usize, 1), retained.len);
    try std.testing.expectEqual(target_sequence, retained[0].sequence);
}

test "db restart after provider failure resumes enrichment from retained async replay" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var first_applied_sequence: u64 = 0;
    var failed_target_sequence: u64 = 0;
    {
        // Permit one document to establish a durable enrichment watermark,
        // then keep returning a retryable provider error for the next
        // document. The independent managed-index consumer may pass the source
        // revision, but enrichment's durable watermark must retain its replay.
        var gated = GateDenseEmbedder{};
        var db = try DB.open(alloc, std.mem.span(path), .{
            .enrichment = .{
                .owner_id = "worker-a",
                .dense_embedder = gated.interface(),
            },
            .ttl_cleanup = .{ .enabled = false },
        });
        defer db.close();

        try db.addIndex(.{
            .name = "dv_v1",
            .kind = .dense_vector,
            .config_json = "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"embedding_name\":\"body_dense_v1\"}}",
        });
        try db.batch(.{
            .writes = &.{.{ .key = "doc:a", .value = "{\"body\":\"alpha\"}" }},
            .sync_level = .write,
        });
        first_applied_sequence = db.core.nextEnrichmentSequence();
        try db.enrichment_runtime.?.waitForApplied(first_applied_sequence);

        try db.batch(.{
            .writes = &.{.{ .key = "doc:b", .value = "{\"body\":\"beta\"}" }},
            .sync_level = .write,
        });
        failed_target_sequence = db.core.nextEnrichmentSequence();
        try std.testing.expect(failed_target_sequence > first_applied_sequence);

        var attempts: usize = 0;
        while (attempts < default_test_wait_attempts and gated.snapshot().blocked_requests == 0) : (attempts += 1) {
            sleepPollInterval();
        }
        try std.testing.expect(gated.snapshot().blocked_requests > 0);

        // Stop at the observed provider failure boundary, then explicitly let
        // the independent index consumer catch up. Replay retention must hold
        // even in this ordering; racing an assertion against its progress does
        // not test the enrichment checkpoint that owns the retained debt.
        db.enrichment_runtime.?.stop();
        db.executor.notifySequence(failed_target_sequence);
        try db.executor.waitForIndexes(failed_target_sequence, &.{"dv_v1"});
        try truncateReplaySequenceAsync(db.async_context, failed_target_sequence);

        const failed_stats = try db.stats(alloc);
        defer types.freeDBStats(alloc, failed_stats);
        try std.testing.expectEqual(first_applied_sequence, failed_stats.enrichment.applied_sequence);
        try std.testing.expectEqual(failed_target_sequence, failed_stats.enrichment.target_sequence);
        try std.testing.expect((db.executor.appliedSequence("dv_v1") orelse 0) >= failed_target_sequence);

        const retained = try replay_stream_mod.iterateFrom(alloc, db.core.store, first_applied_sequence + 1);
        defer {
            for (retained) |*entry| entry.deinit(alloc);
            alloc.free(retained);
        }
        try std.testing.expect(retained.len > 0);
        var retained_failed_target = false;
        for (retained) |entry| {
            if (entry.sequence == failed_target_sequence) retained_failed_target = true;
        }
        try std.testing.expect(retained_failed_target);
    }

    var deterministic = embedder_mod.DeterministicDenseEmbedder{};
    var reopened = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = deterministic.interface(),
        },
        .ttl_cleanup = .{ .enabled = false },
    });
    defer reopened.close();

    try reopened.runUntilIdle();

    const recovered_stats = try reopened.stats(alloc);
    defer types.freeDBStats(alloc, recovered_stats);
    try std.testing.expect(recovered_stats.enrichment.applied_sequence >= failed_target_sequence);
    try std.testing.expectEqual(recovered_stats.enrichment.applied_sequence, recovered_stats.enrichment.target_sequence);

    const artifact_key = try expectedDocumentEmbeddingArtifactKeyAlloc(alloc, "doc:b", "body_dense_v1");
    defer alloc.free(artifact_key);
    const artifacts = try reopened.core.store.scanPrefix(alloc, artifact_key);
    defer docstore_mod.DocStore.freeResults(alloc, artifacts);
    try std.testing.expectEqual(@as(usize, 1), artifacts.len);

    const query_vec = try deterministic.interface().embedDense(alloc, "", "beta", 3);
    defer alloc.free(query_vec);
    var result = try reopened.search(alloc, .{
        .index_name = "dv_v1",
        .dense = .{
            .vector = query_vec,
            .k = 2,
        },
        .limit = 2,
    });
    defer result.deinit();
    try std.testing.expectEqual(@as(u32, 2), result.total_hits);
}

test "db async replay truncation retains journal behind generated enrichment" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var provider_failed: std.Io.Event = .unset;
    var gated = GateDenseEmbedder{ .blocked_event = &provider_failed };
    gated.allowed_successes.store(0, .release);
    var db = try DB.open(alloc, std.mem.span(path), .{
        .executor = .{ .backend = .io_threaded },
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = gated.interface(),
        },
    });
    defer db.close();

    try db.addIndex(.{
        .name = "ft_v1",
        .kind = .full_text,
        .config_json = "{}",
    });
    try db.addIndex(.{
        .name = "semantic_idx",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"cosine\",\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"embedding_name\":\"semantic_idx\"}}",
    });
    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"title\":\"alpha\",\"body\":\"alpha concept overview\"}" },
            .{ .key = "doc:b", .value = "{\"title\":\"beta\",\"body\":\"beta architecture notes\"}" },
        },
        .sync_level = .write,
    });

    const target_sequence = db.core.nextDerivedSequence();
    try std.testing.expect(target_sequence > 0);
    const deadline = std.Io.Clock.Timestamp.fromNow(std.testing.io, .{
        .raw = .fromSeconds(5),
        .clock = .awake,
    });
    while (!provider_failed.isSet()) {
        provider_failed.waitTimeout(std.testing.io, .{ .deadline = deadline }) catch |err| switch (err) {
            error.Timeout => {
                if (std.Io.Clock.Timestamp.now(std.testing.io, .awake).compare(.gte, deadline))
                    return error.ProviderFailureNotObserved;
            },
            error.Canceled => return err,
        };
    }
    try std.testing.expectEqual(
        @as(u64, 0),
        try enrichment_state.loadAppliedSequence(alloc, db.core.store, enrichment_runtime_mod.scope_name),
    );

    const expected = try db.core.store.iterateReplayFrom(alloc, 1);
    defer {
        for (expected) |*entry| entry.deinit(alloc);
        alloc.free(expected);
    }
    try std.testing.expect(expected.len > 0);
    try std.testing.expectEqual(target_sequence, expected[expected.len - 1].sequence);

    // Exercise the worst-case consumer ordering directly: request truncation
    // through the entire source tail while the real provider is failing.
    // A checkpoint appearing within a short wall-clock window is neither the
    // retention contract nor evidence that truncation has actually run.
    try truncateReplaySequenceAsync(db.async_context, target_sequence);
    const retained = try db.core.store.iterateReplayFrom(alloc, 1);
    defer {
        for (retained) |*entry| entry.deinit(alloc);
        alloc.free(retained);
    }
    try std.testing.expectEqual(expected.len, retained.len);
    for (expected, retained) |before, after| {
        try std.testing.expectEqual(before.sequence, after.sequence);
        try std.testing.expectEqualStrings(before.payload, after.payload);
    }
    gated.allowAll();
    try db.runUntilIdle();
    const recovered = db.enrichment_runtime.?.stats();
    try std.testing.expect(recovered.applied_sequence >= target_sequence);
    try std.testing.expectEqual(recovered.target_sequence, recovered.applied_sequence);
    for ([_][]const u8{ "ft_v1", "semantic_idx" }) |index_name| {
        try std.testing.expect((try db.core.loadAppliedSequence(alloc, index_name)) >= target_sequence);
    }
    var result = try db.search(alloc, .{
        .index_name = "semantic_idx",
        .dense = .{ .vector = &.{ 1, 0, 0 }, .k = 2 },
        .limit = 2,
    });
    defer result.deinit();
    try std.testing.expectEqual(@as(u32, 2), result.total_hits);
}

