test "text replay delete keys include upserted derived document keys" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();
    try db.addIndex(.{
        .name = "selected_text",
        .kind = .full_text,
        .config_json = "{}",
    });

    const selected_target = [_]derived_types.DerivedTargetRef{.{ .kind = .full_text, .index_name = "selected_text" }};
    const other_target = [_]derived_types.DerivedTargetRef{.{ .kind = .full_text, .index_name = "other_text" }};
    const docs = [_]derived_types.DerivedDocument{
        .{ .key = "chunk:1", .action = .upsert, .cleaned_value = "{\"text\":\"new\"}", .targets = &selected_target },
        .{ .key = "deleted:2", .action = .delete, .targets = &selected_target },
        .{ .key = "ignored", .action = .delete, .targets = &other_target },
        .{ .key = "chunk:1", .action = .upsert, .cleaned_value = "{\"text\":\"newer\"}", .targets = &selected_target },
    };
    const deleted = [_][]const u8{"deleted:1"};
    const overwritten = [_][]const u8{ "chunk:1", "overwritten:1" };
    const batch = derived_types.DerivedBatch{
        .documents = &docs,
        .deleted_keys = &deleted,
        .overwritten_doc_keys = &overwritten,
    };

    var publication = try db.core.index_manager.acquireTextPublicationContext(alloc, "selected_text");
    defer publication.deinit();
    var apply_guard = try db.core.index_manager.lockManagedIndexApply(.{
        .name = "selected_text",
        .kind = .full_text,
    });
    defer apply_guard.unlock();
    const keys = try collectTextReplayDeleteKeys(
        alloc,
        db.core.index_manager,
        batch,
        "selected_text",
        publication,
    );
    defer alloc.free(keys);

    try std.testing.expectEqual(@as(usize, 4), keys.len);
    try std.testing.expectEqualStrings("deleted:1", keys[0]);
    try std.testing.expectEqualStrings("chunk:1", keys[1]);
    try std.testing.expectEqualStrings("overwritten:1", keys[2]);
    try std.testing.expectEqualStrings("deleted:2", keys[3]);
}

test "db replay respects per-index applied watermarks" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var appended_sequence: u64 = 0;

    {
        var db = try DB.open(alloc, std.mem.span(path), .{});
        defer db.close();

        try db.addIndex(.{
            .name = "dv_v1",
            .kind = .dense_vector,
            .config_json = "{\"field\":\"embedding\",\"dims\":2}",
        });
        try db.addIndex(.{
            .name = "gr_v1",
            .kind = .graph,
            .config_json = "{\"edge_types\":[{\"name\":\"related\"}]}",
        });

        const req = types.BatchRequest{
            .writes = &.{
                .{ .key = "doc:a", .value = "{\"title\":\"alpha\",\"_embeddings\":{\"dv_v1\":[1,0]}}" },
            },
        };

        var extracted = try mapper.extractWrite(alloc, req.writes[0].key, req.writes[0].value);
        defer extracted.deinit(alloc);

        const stored_key = try internal_keys.documentKeyAlloc(alloc, req.writes[0].key);
        defer alloc.free(stored_key);
        try db.core.store.putBatch(&.{
            .{ .key = stored_key, .value = extracted.cleaned_value.? },
        }, &.{});
        const artifact_key = try expectedDocumentEmbeddingArtifactKeyAlloc(alloc, "doc:a", "dv_v1");
        defer alloc.free(artifact_key);
        try putDenseEmbeddingArtifactForTest(&db, alloc, artifact_key, null, &[_]f32{ 1, 0 });
        extracted.dense_embeddings[0].artifact_key = try alloc.dupe(u8, artifact_key);

        var derived_batch = try buildDerivedBatch(alloc, req, &.{extracted}, &.{}, &.{});
        defer derived_types.deinitDerivedBatch(alloc, &derived_batch);

        appended_sequence = try appendDerivedBatchRecord(&db, derived_batch);

        try db.core.saveAppliedSequence("dv_v1", appended_sequence);
    }

    var reopened = try DB.open(alloc, std.mem.span(path), .{ .start_index_workers = false });
    defer reopened.close();

    var result = try reopened.search(alloc, .{
        .index_name = "dv_v1",
        .dense = .{
            .vector = &[_]f32{ 1, 0 },
            .k = 1,
        },
        .limit = 1,
    });
    defer result.deinit();

    try std.testing.expectEqual(@as(u32, 0), result.total_hits);

    const dense_applied = try reopened.core.loadAppliedSequence(alloc, "dv_v1");
    try std.testing.expectEqual(appended_sequence, dense_applied);

    const graph_applied = try reopened.core.loadAppliedSequence(alloc, "gr_v1");
    try std.testing.expectEqual(@as(u64, 0), graph_applied);
}

