        var result = try reopened.search(alloc, .{
            .index_name = "dv_v1",
            .dense = .{ .vector = &[_]f32{ 1, 0 }, .k = 1 },
            .limit = 1,
        });
        defer result.deinit();
        try std.testing.expectEqual(@as(u32, 0), result.total_hits);
    }
}

