        defer alloc.free(counter_key);
        try db.core.store.delete(counter_key);
    }

    const dense_path = try std.fmt.allocPrint(alloc, "{s}/indexes/{s}", .{ std.mem.span(path), cfg.name });
    defer alloc.free(dense_path);
