test "db last dense catch-up lease finalizes every covered rebuilding generation" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();

    const configs = [_]types.IndexConfig{
        .{
            .name = "dense_a",
            .kind = .dense_vector,
            .config_json = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"l2_squared\",\"external\":true}",
        },
        .{
            .name = "dense_b",
            .kind = .dense_vector,
            .config_json = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"l2_squared\",\"external\":true}",
        },
    };
    for (configs) |config| try db.addIndex(config);
    try db.batch(.{
        .writes = &.{.{
            .key = "doc:a",
            .value = "{\"_embeddings\":{\"dense_a\":[1,0,0],\"dense_b\":[0,1,0]}}",
        }},
        .sync_level = .full_index,
    });

    for (configs) |config| {
        const entry = db.core.index_manager.denseIndex(config.name) orelse
            return error.TestUnexpectedResult;
        try std.testing.expectEqual(@as(u64, 1), entry.index.stats().active_count);
        try std.testing.expectEqual(
            @as(?u64, 1),
            try DB.loadDenseArtifactTargetCounter(alloc, db.core.store, config.name),
        );
    }

    // Stable-tip publication owns one posting generation even though its
    // exact-vector file is shared by the table. Preserve the independently
    // certified sibling instead of projecting the owner's short fence onto
    // every dense index.
    // This fixture disables index workers. Finish acceleration staging at
    // its idle boundary before testing certification: an online pass only
    // schedules checkpoint builders and may return while either is pending.
    _ = try db.publishVectorBlockBasesAtStableTip();
    for (configs) |config| {
        try std.testing.expect(db.core.index_manager.vectorBlockReadyForDenseIndexAtSequence(
            config.name,
            try db.core.loadAppliedSequence(alloc, config.name),
            1,
        ));
    }
    {
        const owner = db.core.index_manager.denseIndex(configs[0].name) orelse
            return error.TestUnexpectedResult;
        db.core.index_manager.vector_block_stable_tip_index.store(@intFromPtr(owner), .release);
        db.core.index_manager.vector_block_stable_tip_sequence.store(
            try db.core.loadAppliedSequence(alloc, configs[0].name),
            .release,
        );
        db.core.index_manager.vector_block_stable_tip_finalizing.store(true, .release);
        defer {
            db.core.index_manager.vector_block_stable_tip_sequence.store(0, .release);
            db.core.index_manager.vector_block_stable_tip_index.store(0, .release);
            db.core.index_manager.vector_block_stable_tip_finalizing.store(false, .release);
        }

        const stats = try db.stats(alloc);
        defer types.freeDBStats(alloc, stats);
        const owner_stats = for (stats.indexes) |item| {
            if (std.mem.eql(u8, item.name, configs[0].name)) break item;
        } else return error.TestUnexpectedResult;
        const sibling_stats = for (stats.indexes) |item| {
            if (std.mem.eql(u8, item.name, configs[1].name)) break item;
        } else return error.TestUnexpectedResult;
        try std.testing.expect(owner_stats.dense_vector_projection_pending);
        try std.testing.expect(!sibling_stats.dense_vector_projection_pending);
    }

    for (configs) |config| {
        const counter_key = try DB.denseArtifactTargetCounterKeyAlloc(alloc, config.name);
        defer alloc.free(counter_key);
        var counter_value: [8]u8 = undefined;
        std.mem.writeInt(u64, &counter_value, 1, .little);
        try db.core.store.put(counter_key, &counter_value);

        const applied = try db.core.loadAppliedSequence(alloc, config.name);
        try db.core.saveProjectionCheckpoint(config.name, .{
            .applied_sequence = applied,
            .status = .rebuilding,
            .generation = 7,
            .config_hash = types.indexConfigHash(config),
        });
        try beginDenseCatchUpSessionTracked(db.async_context, config.name);
    }

    finishDenseCatchUpSessionTracked(db.async_context, configs[0].name);
    try std.testing.expect(!try finalizeCoveredDenseProjectionCheckpointsIfIdle(db.async_context));
    try std.testing.expect(try finishDenseCatchUpSessionTrackedAndFinalize(db.async_context, configs[1].name));

    for (configs) |config| {
        const checkpoint = try db.core.loadProjectionCheckpoint(alloc, config.name);
        try std.testing.expectEqual(apply_state.ProjectionStatus.clean, checkpoint.status);
        try std.testing.expectEqual(@as(u64, 8), checkpoint.generation);
    }
}

test "db dense target reads atomic artifact and source coverage snapshot" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    var db = try DB.open(alloc, path_tmp.path(), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();
    try db.addIndex(.{
        .name = "dense_idx",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"external\":true}",
        .coverage_generation = 42,
    });
    const Commit = struct {
        fn counters(ctx: *AsyncContext, count: u64) !void {
            const tags = [_][]const u8{ "produced", "skipped", "terminal_failed" };
            var keys: [4][]u8 = undefined;
            var initialized: usize = 0;
            defer for (keys[0..initialized]) |key| ctx.alloc.free(key);
            var value: [8]u8 = undefined;
            std.mem.writeInt(u64, &value, count, .little);
            const zero = @as([8]u8, @splat(0));
            var writes: [4]docstore_mod.KVPair = undefined;
            for (tags, 0..) |tag, i| {
                keys[i] = try internal_keys.derivedCoverageOutcomeCountKeyAlloc(ctx.alloc, "dense_idx", 42, tag);
                initialized += 1;
                writes[i] = .{ .key = keys[i], .value = if (i == 0) &value else &zero };
            }
            keys[3] = try DB.denseArtifactTargetCounterKeyAlloc(ctx.alloc, "dense_idx");
            initialized += 1;
            writes[3] = .{ .key = keys[3], .value = &value };
            try ctx.store.putBatch(&writes, &.{});
        }
        fn afterCapture(ctx: *AsyncContext) !void {
            test_dense_target_after_coverage_capture = null;
            try counters(ctx, 2);
        }
    };
    try Commit.counters(db.async_context, 1);
    var item: types.DBIndexStats = .{
        .name = "dense_idx",
        .kind = .dense_vector,
        .coverage_identity_ready = true,
        .coverage_generation = 42,
    };
    // Commit a second source after status captures its coverage tuple. The
    // publication target must still describe the first revision, rather than
    // re-reading the new counter and reporting contradictory readiness facts.
    test_dense_target_after_coverage_capture = Commit.afterCapture;
    defer test_dense_target_after_coverage_capture = null;
    try db.populateConfiguredDerivedCoverageCounts("dense_idx", &item);
    try std.testing.expect(test_dense_target_after_coverage_capture == null);
    try std.testing.expect(item.publication_target_ready);
    try std.testing.expectEqual(@as(u64, 1), item.coverage_produced_count);
    try std.testing.expectEqual(@as(u64, 1), item.publication_target_count);
    try db.populateConfiguredDerivedCoverageCounts("dense_idx", &item);
    try std.testing.expectEqual(@as(u64, 2), item.coverage_produced_count);
    try std.testing.expectEqual(@as(u64, 2), item.publication_target_count);

    // Missing/corrupt bootstrap metadata cannot be replaced with the source
    // count: a document may produce many vectors, or none.
    const counter_key = try DB.denseArtifactTargetCounterKeyAlloc(alloc, "dense_idx");
    defer alloc.free(counter_key);
    try db.core.store.putBatch(&.{}, &.{counter_key});
    try db.populateConfiguredDerivedCoverageCounts("dense_idx", &item);
    try std.testing.expect(!item.publication_target_ready);
    try std.testing.expectEqual(@as(u64, 0), item.publication_target_count);
    try db.core.store.put(counter_key, "invalid");
    db.populateConfiguredDerivedCoverageCountsBestEffort("dense_idx", &item);
    try std.testing.expect(!item.publication_target_ready);
    try std.testing.expect(item.repair_degraded);
}

test "db dense target reads atomic outcome and source coverage snapshot" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);
    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();
    const config: types.IndexConfig = .{
        .name = "dense_idx",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"metric\":\"cosine\"}",
        .coverage_generation = 42,
    };
    try db.addIndex(config);
    try db.core.store.put(&internal_keys.range_document_count_key, &(@as([8]u8, @splat(0))));
    const Commit = struct {
        fn afterProduced(ctx: *AsyncContext) !void {
            test_dense_target_after_coverage_capture = null;
            const tags = [_][]const u8{ "produced", "skipped", "terminal_failed" };
            var keys: [3][]u8 = undefined;
            var initialized: usize = 0;
            defer for (keys[0..initialized]) |key| ctx.alloc.free(key);
            var one: [8]u8 = undefined;
            std.mem.writeInt(u64, &one, 1, .little);
            const zero = @as([8]u8, @splat(0));
            var writes: [4]docstore_mod.KVPair = undefined;
            for (tags, 0..) |tag, i| {
                keys[i] = try internal_keys.derivedCoverageOutcomeCountKeyAlloc(ctx.alloc, "dense_idx", 42, tag);
                initialized += 1;
                writes[i] = .{ .key = keys[i], .value = if (i == 0) &one else &zero };
            }
            writes[3] = .{ .key = &internal_keys.range_document_count_key, .value = &one };
            try ctx.store.putBatch(&writes, &.{});
        }
    };
    // Publish a complete first tuple after the counter batch is captured.
    // This call must observe the pre-commit empty table; the next sees all
    // four committed counters. No scheduling/sleep is needed to force the race.
    test_dense_target_after_coverage_capture = Commit.afterProduced;
    defer test_dense_target_after_coverage_capture = null;
    try std.testing.expectEqual(@as(?u64, 0), try denseTargetCountForIndexContext(db.async_context, config.name));
    try std.testing.expect(test_dense_target_after_coverage_capture == null);
    try std.testing.expectEqual(@as(?u64, 1), try denseTargetCountForIndexContext(db.async_context, config.name));

    // Actual persisted corruption remains an error, rather than a retryable
    // absence that could certify an incomplete generation.
    const skipped_key = try internal_keys.derivedCoverageOutcomeCountKeyAlloc(alloc, config.name, 42, "skipped");
    defer alloc.free(skipped_key);
    try db.core.store.putBatch(&.{}, &.{skipped_key});
    try std.testing.expectError(error.InvalidDerivedCoverageCounter, denseTargetCountForIndexContext(db.async_context, config.name));
}

test "db artifact dense target prefers current incarnation outcomes over stale name counter" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var counting = CountingDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .start_optional_runtime_workers = false,
        .ttl_cleanup = .{ .enabled = false },
        .enrichment = .{
            .owner_id = "worker-a",
            .dense_embedder = counting.interface(),
        },
    });
    defer db.close();

    const config: types.IndexConfig = .{
        .name = "dense_idx",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"body\",\"dims\":3,\"metric\":\"cosine\",\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"embedding_name\":\"dense_idx\"}}",
        .coverage_generation = 42,
    };
    try db.addIndex(config);
    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"alpha concept overview\"}" },
            .{ .key = "doc:b", .value = "{\"body\":\"beta architecture notes\"}" },
        },
        .sync_level = .write,
    });
    try db.runUntilIdle();

    // Same-name recreation can leave this legacy counter stale while the
    // current generation's outcome accounting is complete.
    const counter_key = try DB.denseArtifactTargetCounterKeyAlloc(alloc, config.name);
    defer alloc.free(counter_key);
    var stale_value: [8]u8 = undefined;
    std.mem.writeInt(u64, &stale_value, 1, .little);
    try db.core.store.put(counter_key, &stale_value);

    try std.testing.expectEqual(
        @as(?u64, 2),
        try denseTargetCountForIndexContext(db.async_context, config.name),
    );

    // A later source has no embedding yet. The certified generation must
    // still advance across source-only replay records; final source coverage
    // and shadow cutover must remain pending on that same durable state.
    db.async_context.enrichment_desired_running.store(false, .release);
    db.enrichment_runtime.?.stop();
    const applied = try db.core.loadAppliedSequence(alloc, config.name);
    try db.batch(.{
        .writes = &.{.{ .key = "doc:pending", .value = "{\"body\":\"provider pending\"}" }},
        .sync_level = .write,
    });
    const target = db.core.nextDerivedSequence();
    try std.testing.expect(target > applied);
    try std.testing.expectEqual(@as(?u64, null), try denseTargetCountForIndexContext(db.async_context, config.name));
    try std.testing.expectEqual(@as(?u64, 2), try denseTargetCountForIndexContextWithCoverage(db.async_context, config.name, .materialized));
    try std.testing.expect(try canAdvanceDerivedToTargetAsync(db.async_context, .{
        .name = config.name,
        .kind = .dense_vector,
    }, applied, target));
}

test "db multi-source dense target uses physical artifact cardinality" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
