    const jan2 = (try parsePatternRfc3339ToNs("2026-01-02T00:00:00Z")).?;
    const jan4 = (try parsePatternRfc3339ToNs("2026-01-04T00:00:00Z")).?;

    {
        var db = try DB.open(alloc, std.mem.span(path), .{});
