                .{ .key = "doc:2", .value = "{\"meta\":{\"title\":\"gamma delta\",\"score\":20,\"published_at\":\"2026-01-03T00:00:00Z\",\"location\":{\"lat\":40.7128,\"lon\":-74.0060}}}" },
            },
