        try std.testing.expectEqual(@as(u32, 1), numeric.total_hits);
        try std.testing.expectEqualStrings("doc:2", numeric.hits[0].id);

        var date = try db.search(alloc, .{
            .index_name = "ft_v1",
            .query = .{ .date_range = .{
                .field = "meta.published_at",
                .start_ns = jan2,
