            .{ .key = "doc:5", .value = "{\"title\":\"delta\",\"body\":\"alpha five\",\"price\":60,\"published_at\":\"2026-01-06T00:00:00Z\",\"location\":{\"lat\":41.8781,\"lon\":-87.6298}}" },
