        .config_json =
        \\{"ttl":{"duration":"1h"},"sources":[{"artifact":"primary_relations_v1"},{"artifact":"fallback_relations_v1"}]}
        ,
    });
    try parent.batch(.{
        .writes = &.{.{
            .key = "doc:z",
