test "db split bootstrap retries preserve reserved data and exact sequence" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{});
    defer db.close();
    const byte_range: types.ByteRange = .{ .start = "doc:m", .end = "doc:z" };
    const incomplete: range_state_mod.SplitBootstrapMarker = .{
        .transition_id = 11,
        .attempt_epoch = 1,
        .source_group_id = 101,
        .destination_group_id = 102,
        .bootstrap_complete = false,
    };
    try std.testing.expect(try db.replaceSplitBootstrap(
        alloc,
        byte_range,
        &.{.{ .key = "doc:m", .value = "{\"version\":1}" }},
        17,
        incomplete,
    ));
    try std.testing.expect(!try db.replaceSplitBootstrap(alloc, byte_range, &.{}, 17, incomplete));
    const reserved = (try db.get(alloc, "doc:m")).?;
    defer alloc.free(reserved);
    try std.testing.expectEqualStrings("{\"version\":1}", reserved);

    var complete = incomplete;
    complete.bootstrap_complete = true;
    try std.testing.expectError(
        error.StaleSplitBootstrap,
        db.completeSplitBootstrap(alloc, byte_range, 18, complete),
    );
    try std.testing.expect(try db.completeSplitBootstrap(alloc, byte_range, 17, complete));

    try std.testing.expect(!try db.replaceSplitBootstrap(alloc, byte_range, &.{}, 17, incomplete));
    const retained = (try db.get(alloc, "doc:m")).?;
    defer alloc.free(retained);
    try std.testing.expectEqualStrings("{\"version\":1}", retained);
    try std.testing.expect((try db.getSplitBootstrapMarker(alloc)).?.bootstrap_complete);

    try std.testing.expectError(
        error.SplitBootstrapComplete,
        db.replaceSplitBootstrap(alloc, byte_range, &.{}, 18, incomplete),
    );
}

test "db replicated split bootstrap requires and preserves begin barrier" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    const identity_namespace: DocIdentityNamespace = .{
        .table_id = 71,
        .shard_id = 72,
        .range_id = 73,
    };
    var db = try DB.open(alloc, std.mem.span(path), .{
        .identity_namespace = identity_namespace,
        .start_index_workers = false,
    });
    defer db.close();

    const base_replication: types.SplitReplicationContext = .{
        .transition_id = 7001,
        .attempt_epoch = 3,
        .source_group_id = 71,
        .destination_group_id = 72,
        .identity_namespace = identity_namespace,
        .bootstrap_sequence = 9,
    };
    var completion_replication = base_replication;
    completion_replication.operation = .checkpoint;
    completion_replication.sequence = 9;
    const completion: types.SplitReplicationCheckpoint = .{
        .kind = .destination_complete,
        .transition_id = 7001,
        .attempt_epoch = 3,
        .source_group_id = 71,
        .destination_group_id = 72,
        .range_start = "doc:m",
        .range_end = "",
        .delta_sequence = 9,
    };

    try std.testing.expectError(error.SplitBootstrapIncomplete, db.batchReplicatedApply(.{
        .writes = &.{.{ .key = "doc:z", .value = "{\"v\":0}" }},
        .split_replication = base_replication,
    }));
    try std.testing.expectError(error.SplitBootstrapIncomplete, db.batchReplicatedApply(.{
        .split_replication = completion_replication,
        .split_checkpoint = completion,
    }));

    var begin_replication = base_replication;
    begin_replication.operation = .checkpoint;
    begin_replication.sequence = 9;
    try db.batchReplicatedApply(.{
        .split_replication = begin_replication,
        .split_checkpoint = .{
            .kind = .destination_begin,
            .transition_id = 7001,
            .attempt_epoch = 3,
            .source_group_id = 71,
            .destination_group_id = 72,
            .range_start = "doc:m",
            .range_end = "",
            .delta_sequence = 9,
        },
    });
    // Raft replay and source retries may repeat the begin checkpoint.
    try db.batchReplicatedApply(.{
        .split_replication = begin_replication,
        .split_checkpoint = .{
            .kind = .destination_begin,
            .transition_id = 7001,
            .attempt_epoch = 3,
            .source_group_id = 71,
            .destination_group_id = 72,
            .range_start = "doc:m",
            .range_end = "",
            .delta_sequence = 9,
        },
    });
    var stale_replication = base_replication;
    stale_replication.bootstrap_sequence = 8;
    try std.testing.expectError(error.StaleSplitBootstrap, db.batchReplicatedApply(.{
        .writes = &.{.{ .key = "doc:z", .value = "{\"v\":0}" }},
        .split_replication = stale_replication,
    }));
    try db.batchReplicatedApply(.{
        .writes = &.{.{ .key = "doc:z", .value = "{\"v\":1}" }},
        .split_replication = base_replication,
    });
    try db.batchReplicatedApply(.{
        .split_replication = completion_replication,
        .split_checkpoint = completion,
    });

    const marker = (try db.getSplitBootstrapMarker(alloc)) orelse return error.TestExpectedEqual;
    try std.testing.expect(marker.bootstrap_complete);
    try std.testing.expectEqual(@as(u64, 9), try db.getSplitDeltaFinalSeq(alloc));
    var found = (try db.lookup(alloc, "doc:z", .{})) orelse return error.TestExpectedEqual;
    defer found.deinit(alloc);
    try std.testing.expectEqualStrings("{\"v\":1}", found.json);
}

test "db replicated merge checkpoints persist phase range and watermark across reopen" {
    const alloc = std.testing.allocator;
    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;

    const namespace: DocIdentityNamespace = .{ .table_id = 7, .shard_id = 42, .range_id = 420 };
    const base_range: types.ByteRange = .{ .start = "doc:m", .end = "" };
    const merged_range: types.ByteRange = .{ .start = "doc:a", .end = "" };
    const checkpoint_base: types.MergeReplicationCheckpoint = .{
        .kind = .accept,
        .transition_id = 40,
        .donor_group_id = 41,
        .receiver_group_id = 42,
        .receiver_base_start = base_range.start,
        .receiver_base_end = base_range.end,
        .merged_start = merged_range.start,
        .merged_end = merged_range.end,
        .allow_doc_identity_reassignment = true,
        .receiver_identity_reassignment_namespace = namespace,
    };

    {
        var db = try DB.open(alloc, std.mem.span(path), .{
            .identity_namespace = namespace,
            .start_index_workers = false,
        });
        defer db.close();
        try db.updateRange(base_range);
        try db.batchReplicatedApply(.{ .merge_checkpoint = checkpoint_base });
        try std.testing.expectEqualStrings("doc:a", db.getRange().start);

        var premature_finalize = checkpoint_base;
        premature_finalize.kind = .finalize;
        premature_finalize.bootstrap_applied_index = 19;
        try std.testing.expectError(
            error.MergeTransitionNotReady,
            db.batchReplicatedApply(.{ .merge_checkpoint = premature_finalize }),
        );

        var conflicting_range = checkpoint_base;
        conflicting_range.kind = .bootstrap_complete;
        conflicting_range.merged_start = "doc:b";
        conflicting_range.bootstrap_applied_index = 19;
        try std.testing.expectError(
            error.ConflictingMergeTransition,
            db.batchReplicatedApply(.{ .merge_checkpoint = conflicting_range }),
        );

        try db.batchReplicatedApply(.{
            .writes = &.{.{ .key = "doc:b", .value = "{\"title\":\"from donor\"}" }},
        });
        var complete = checkpoint_base;
        complete.kind = .bootstrap_complete;
        complete.bootstrap_applied_index = 19;
        try db.batchReplicatedApply(.{ .merge_checkpoint = complete });
        try std.testing.expectEqualStrings("doc:a", db.getRange().start);
        // A delayed accept is a no-op: it cannot regress either the expanded
        // range or the durable bootstrap watermark.
        try db.batchReplicatedApply(.{ .merge_checkpoint = checkpoint_base });
        try std.testing.expectEqualStrings("doc:a", db.getRange().start);

        const raw = (try db.core.getStoreValue(alloc, merge_state_mod.key)) orelse return error.TestExpectedEqual;
        defer alloc.free(raw);
        var state = try merge_state_mod.decodeAlloc(alloc, raw);
        defer state.deinit(alloc);
        try std.testing.expectEqual(merge_state_mod.Phase.accepting, state.phase);
        try std.testing.expect(state.bootstrap_complete);
        try std.testing.expectEqual(@as(u64, 19), state.bootstrap_applied_index);
        try std.testing.expectEqual(@as(u64, 40), state.transition_id);
        const corrupt = try alloc.dupe(u8, raw);
        defer alloc.free(corrupt);
        corrupt[0] = 0xff;
        try std.testing.expectError(error.InvalidMergeState, merge_state_mod.decodeAlloc(alloc, corrupt));
    }

    {
        var db = try DB.open(alloc, std.mem.span(path), .{
            .identity_namespace = namespace,
            .start_index_workers = false,
        });
        defer db.close();
        try std.testing.expectEqualStrings("doc:a", db.getRange().start);
        const donor = (try db.get(alloc, "doc:b")) orelse return error.TestExpectedEqual;
        defer alloc.free(donor);
        try std.testing.expectEqualStrings("{\"title\":\"from donor\"}", donor);

        var finalized = checkpoint_base;
        finalized.kind = .finalize;
        finalized.bootstrap_applied_index = 19;
        try db.batchReplicatedApply(.{ .merge_checkpoint = finalized });
        try db.batchReplicatedApply(.{ .merge_checkpoint = checkpoint_base });
        try std.testing.expectEqualStrings("doc:a", db.getRange().start);
        var newer_after_finalize = finalized;
        newer_after_finalize.bootstrap_applied_index = 20;
        try db.batchReplicatedApply(.{ .merge_checkpoint = newer_after_finalize });
        var different_transition = checkpoint_base;
        different_transition.transition_id = 41;
        try std.testing.expectError(
            error.ConflictingMergeTransition,
            db.batchReplicatedApply(.{ .merge_checkpoint = different_transition }),
        );
        var rollback = checkpoint_base;
        rollback.kind = .rollback;
        try db.batchReplicatedApply(.{ .merge_checkpoint = rollback });
        const raw = (try db.core.getStoreValue(alloc, merge_state_mod.key)) orelse return error.TestExpectedEqual;
        defer alloc.free(raw);
        var state = try merge_state_mod.decodeAlloc(alloc, raw);
        defer state.deinit(alloc);
        try std.testing.expectEqual(merge_state_mod.Phase.finalized, state.phase);
        try std.testing.expect(state.bootstrap_complete);
        try std.testing.expectEqual(@as(u64, 19), state.bootstrap_applied_index);
    }
}

test "db split cutover fences enrichment to the owning range with durable lsm primary backend" {
    const alloc = std.testing.allocator;

    var path_tmp = try TestDirectory.init("db");
    defer path_tmp.cleanup();
    const path = path_tmp.path().ptr;
    defer cleanupTempDir(path);

    var dest_tmp = try TestDirectory.init("db");
    defer dest_tmp.cleanup();
    const dest = dest_tmp.path().ptr;
    defer cleanupTempDir(dest);

    const primary_backend: PrimaryBackend = .{ .lsm = db_config.primary_lsm_options_default };

    var deterministic_parent = embedder_mod.DeterministicDenseEmbedder{};
    var db = try DB.open(alloc, std.mem.span(path), .{
        .primary_backend = primary_backend,
        .enrichment = .{
            .owner_id = "split-parent",
            .dense_embedder = deterministic_parent.interface(),
        },
    });
    defer db.close();

    try db.addIndex(.{
        .name = "dv_v1",
        .kind = .dense_vector,
        .config_json = "{\"field\":\"embedding\",\"dims\":3,\"generator\":{\"kind\":\"dense_embedding\",\"source_field\":\"body\",\"embedding_name\":\"body_dense_v1\"}}",
    });

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"left side\"}" },
            .{ .key = "doc:z", .value = "{\"body\":\"right side\"}" },
        },
        .sync_level = .write,
    });
    try db.enrichment_runtime.?.waitForApplied(1);
    try db.executor.waitForAll(2);

    try db.split(db.getRange(), "doc:m", "", std.mem.span(dest), true);
    try db.finalizeSplit(.{ .start = "", .end = "doc:m" });

    try std.testing.expectError(error.KeyOutOfRange, db.batch(.{
        .writes = &.{.{ .key = "doc:y", .value = "{\"body\":\"parent should reject\"}" }},
        .sync_level = .write,
    }));

    var deterministic_child = embedder_mod.DeterministicDenseEmbedder{};
    var child = try DB.open(alloc, std.mem.span(dest), .{
        .primary_backend = primary_backend,
        .enrichment = .{
            .owner_id = "split-child",
            .dense_embedder = deterministic_child.interface(),
        },
    });
    defer child.close();

    const child_before = try child.stats(alloc);
    defer types.freeDBStats(alloc, child_before);
    const child_dense_before = try child.core.loadAppliedSequence(alloc, "dv_v1");

    try child.batch(.{
        .writes = &.{.{ .key = "doc:y", .value = "{\"body\":\"child owns this\"}" }},
        .sync_level = .write,
    });
    try child.runUntilIdle();
    const child_dense_after = try child.core.loadAppliedSequence(alloc, "dv_v1");
    try std.testing.expect(child_dense_after >= child_dense_before + 2);

    const query_vec = try deterministic_child.interface().embedDense(alloc, "", "child owns this", 3);
    defer alloc.free(query_vec);

    var child_result = try child.search(alloc, .{
        .index_name = "dv_v1",
        .dense = .{
            .vector = query_vec,
            .k = 1,
        },
    });
    defer child_result.deinit();
    try std.testing.expect(child_result.total_hits >= 1);
    try std.testing.expectEqualStrings("doc:y", child_result.hits[0].id);

    var parent_result = try db.search(alloc, .{
        .index_name = "dv_v1",
        .dense = .{
            .vector = query_vec,
            .k = 2,
        },
    });
    defer parent_result.deinit();
    for (parent_result.hits) |hit| {
        try std.testing.expect(!std.mem.eql(u8, hit.id, "doc:y"));
    }
}

test "db merge-style cutover fences enrichment to the merged receiver range" {
    const alloc = std.testing.allocator;

