test "db ordered artifact inventory full text reset revokes before destructive work" {
    const alloc = std.testing.allocator;
    const publication = @import("artifact_publication.zig");
    const epoch = @import("artifact_projection_epoch.zig");
    const rebuild = @import("backfill_state.zig");
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/projection-reset-order", .{tmp.sub_path});
    defer alloc.free(path);
    var db = try DB.open(alloc, path, .{ .identity_namespace = .{ .table_id = 1, .shard_id = 2, .range_id = 2 }, .primary_backend = .{ .lsm = .{} }, .start_index_workers = false, .start_optional_runtimes = false });
    defer db.close();
    try db.setSchemaJson(alloc, "{}");
    try db.batch(.{ .writes = &.{.{ .key = "doc", .value = "{\"body\":\"keep me\"}" }} });
    const cfg: types.IndexConfig = .{ .name = "text", .kind = .full_text, .config_json = "{}" };
    try db.addIndex(cfg);
    const manager = db.core.index_manager;
    const entry = manager.textIndexEntry(cfg.name).?;
    const count = entry.persistent.snapshot().liveDocCount();
    try std.testing.expect(count > 0);
    const before = try db.core.loadProjectionCheckpoint(alloc, cfg.name);
    var catalog = try db.artifactInventoryCommand(alloc);
    defer catalog.catalogs.deinit(alloc);
    {
        var txn = try db.core.store.beginWriteTxn();
        errdefer txn.abort();
        try publication.stageAuthority(&txn, .{ .mode = .activate, .namespace = catalog.namespace, .authority_epoch = 1, .catalog_digest = @splat(2), .producer_name = "", .producer_generation = 0, .sources = &.{}, .mutations = &.{}, .publication_digest = @splat(0) });
        try txn.commit();
    }
    rebuild.test_publish_fault = .after_temp_sync;
    defer rebuild.test_publish_fault = null;
    try std.testing.expectError(error.TestRebuildStateCrash, manager.resetFullTextIndexForArtifactRebuild(db.core.store, cfg.name));
    rebuild.test_publish_fault = null;
    // The checkpoint is already revoked, but storage was not cleared when
    // durable restart-marker publication failed.
    try std.testing.expectEqual(count, entry.persistent.snapshot().liveDocCount());
    const failed = try db.core.loadProjectionCheckpoint(alloc, cfg.name);
    try std.testing.expectEqual(.rebuilding, failed.status);
    try std.testing.expectEqual(before.generation + 1, failed.generation);
    {
        var read = try db.core.store.beginReadTxn();
        defer read.abort();
        try std.testing.expect(try epoch.load(&read) > 0);
    }
    try std.testing.expectEqual(count, try manager.resetFullTextIndexForArtifactRebuild(db.core.store, cfg.name));
    const complete = try db.core.loadProjectionCheckpoint(alloc, cfg.name);
    try std.testing.expectEqual(.clean, complete.status);
    try std.testing.expectEqual(failed.generation + 1, complete.generation);
    try std.testing.expectEqual(types.indexConfigHash(cfg), complete.config_hash);
}

test "db transaction integrity contention precedes stale claim semantics" {
    const alloc = std.testing.allocator;
    for ([_]transactions_mod.TxnStatus{ .committed, .aborted }) |decision| {
        var directory = try TestDirectory.init("claim-contention");
        defer directory.cleanup();
        var db = try DB.open(alloc, directory.path(), .{
            .start_optional_runtimes = false,
            .start_index_workers = false,
            .identity_namespace = .{ .table_id = 100, .shard_id = 101 },
        });
        defer db.close();
        try db.setSchemaJson(alloc,
            \\{"version":1,"storage_mode":"relational","default_type":"row","unique_constraints":[{"name":"pk","columns":["id"]}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"integer"}},"additionalProperties":false}}}}
        );
        const integrity = @import("relational_integrity.zig");
        const catalog_mod = @import("relational_integrity_catalog.zig");
        const raw = (try db.core.getStoreValue(alloc, catalog_mod.key)).?;
        defer alloc.free(raw);
        var catalog = try catalog_mod.decode(alloc, raw);
        defer catalog.deinit();
        const generation_set = @import("relational_integrity_activation.zig").generationSet(catalog);
        var view = db.core.acquireSchemaView().?;
        defer view.release();
        var plan = try @import("relational_index_keys.zig").TuplePlan.init(alloc, view.tableSchema().*, view.physicalLayout(), &.{.{ .column = "id" }});
        defer plan.deinit();
        var tuple: std.ArrayList(u8) = .empty;
        defer tuple.deinit(alloc);
        _ = try plan.appendValues(alloc, &tuple, &.{.{ .integer = 17 }});
        const address = try integrity.Address.init(catalog.find(.unique, "pk").?.generation, tuple.items);
        const seed = try db.beginTransactionWithId(@splat(71), 10);
        try db.writeTransaction(seed, .{
            .relational_schema_version = 1,
            .relational_integrity_generation_set = generation_set,
            .writes = &.{.{ .key = "parent", .value = "{\"id\":17}" }},
            .integrity_commands = &.{.{ .address = address, .operation = .{ .establish = .{ .tuple = tuple.items, .parent_table = "parents", .parent_key = "parent", .schema_version = 1 } } }},
        });
        try db.commitTransaction(seed, 11);
        const release = try db.beginTransactionWithId(@splat(72), 12);
        const release_request: types.TransactionIntentRequest = .{
            .relational_schema_version = 1,
            .relational_integrity_generation_set = generation_set,
            .deletes = &.{"parent"},
            .integrity_commands = &.{.{ .address = address, .operation = .{ .release = .{ .parent_table = "parents", .parent_key = "parent" } } }},
        };
        try db.writeTransaction(release, release_request);
        // Own intents remain idempotently preparable. Another transaction must
        // see recoverable contention before decoding the old physical claim.
        try db.writeTransaction(release, release_request);
        const candidate = try db.beginTransactionWithId(@splat(73), 13);
        const replacement: types.TransactionIntentRequest = .{
            .relational_schema_version = 1,
            .relational_integrity_generation_set = generation_set,
            .writes = &.{.{ .key = "replacement", .value = "{\"id\":17}" }},
            .integrity_commands = &.{.{ .address = address, .operation = .{ .establish = .{ .tuple = tuple.items, .parent_table = "parents", .parent_key = "replacement", .schema_version = 1 } } }},
        };
        try std.testing.expectError(error.IntentConflict, db.writeTransaction(candidate, replacement));
        try db.resolveTransactionIntents(release, decision, 20);
        if (decision == .committed) {
            try db.writeTransaction(candidate, replacement);
            try db.commitTransaction(candidate, 21);
        } else {
            try std.testing.expectError(error.UniqueConstraintViolation, db.writeTransaction(candidate, replacement));
        }
    }
}

/// Project the borrowed replication controls without giving the hot-standby owner
