        defer db.close();
        try db.addIndex(.{ .name = "g", .kind = .graph, .config_json = "{}" });
        try db.addIndex(.{ .name = "other", .kind = .graph, .config_json = "{}" });
        const Race = struct {
            var txn_id: types.TxnId = undefined;
            var failing: std.testing.FailingAllocator = undefined;
