        "{\"vec\":{\"indices\":[1,3],\"values\":[0.5,0.25]}}",
        "{\"v\\u0065c\":{\"indices\":[1,3],\"values\":[0.5,0.25]}}",
        "{\"vec\":{\"metadata\":{},\"indices\":[1,3],\"values\":[0.5,0.25]}}",
    };
